/** Tek bir küratörlü deneme sorusu (registry kaydı). */
export type KartSoru = {
  /** Kaynak soru kimliği (örn. "5237-S-001"). */
  id: string;
  /** Soru metni. */
  soru: string;
  /** Şıklar (önekleri ayıklanmış; 2 (doğru/yanlış) veya 5 olabilir). */
  siklar: string[];
  /** Doğru şıkkın 0-tabanlı index'i. */
  dogru: number;
  /** Doğru cevabın açıklaması (cevaptan sonra gösterilir). */
  aciklama: string;
  /** Kaynak madde (örn. "5237 m.1/1"). */
  kaynak: string;
  /** Zorluk etiketi (kolay/orta/zor). */
  zorluk: string;
};

export const KART_SORULARI: Record<number, KartSoru[]> = {
  1: [
    {"id":"5237-S-001","soru":"5237 sayılı Türk Ceza Kanunu'na göre, aşağıdakilerden hangisi Ceza Kanununun amaçları arasında yer almaz?","siklar":["Kişi hak ve özgürlüklerini korumak","Kamu düzen ve güvenliğini korumak","Milli ekonomiyi güçlendirmek ve kalkınmayı sağlamak","Kamu sağlığını ve çevreyi korumak","Suç işlenmesini önlemek"],"dogru":2,"aciklama":"m.1/1'e göre Ceza Kanununun amacı; kişi hak ve özgürlüklerini, kamu düzen ve güvenliğini, hukuk devletini, kamu sağlığını ve çevreyi, toplum barışını korumak ve suç işlenmesini önlemektir. 'Milli ekonomiyi güçlendirmek' maddede sayılan amaçlar arasında yoktur.","kaynak":"5237 m.1/1","zorluk":"kolay"},
    {"id":"5237-S-002","soru":"5237 sayılı Türk Ceza Kanunu'nun 2. maddesine göre, 'Kanunun açıkça suç saymadığı bir fiil için kimseye ceza verilemez ve ............ uygulanamaz.' cümlesinde boş bırakılan yere aşağıdakilerden hangisi gelmelidir?","siklar":["güvenlik tedbiri","idari yaptırım","disiplin cezası","zorlama hapsi","tazminat"],"dogru":0,"aciklama":"m.2/1: 'Kanunun açıkça suç saymadığı bir fiil için kimseye ceza verilemez ve güvenlik tedbiri uygulanamaz.' Kanunîlik ilkesi yalnız cezayı değil, güvenlik tedbirini de kapsar.","kaynak":"5237 m.2","zorluk":"orta"},
    {"id":"5237-S-003","soru":"5237 sayılı Türk Ceza Kanunu'na göre, 'Ceza kanunlarını ............ mazeret sayılmaz.' cümlesinde boş bırakılan yere aşağıdakilerden hangisi gelmelidir?","siklar":["bilmemek","yanlış yorumlamak","farklı uygulamak","öğrenememek","duymamış olmak"],"dogru":0,"aciklama":"m.4/1 birebir: 'Ceza kanunlarını bilmemek mazeret sayılmaz.'","kaynak":"5237 m.4/1","zorluk":"kolay"},
    {"id":"5237-S-004","soru":"5237 sayılı Türk Ceza Kanunu'nun 'Özel kanunlarla ilişki' başlıklı 5. maddesine göre, bu Kanunun genel hükümleri için aşağıdakilerden hangisi doğrudur?","siklar":["Yalnızca bu Kanunda düzenlenen suçlar hakkında uygulanır.","Özel ceza kanunları ve ceza içeren kanunlardaki suçlar hakkında da uygulanır.","Özel ceza kanunlarında aksine hüküm olsa bile her hâlde uygulanır.","Yalnızca özel ceza kanunlarında boşluk bulunması hâlinde uygulanır.","Kabahatler hakkında da doğrudan uygulanır."],"dogru":1,"aciklama":"m.5: 'Bu Kanunun genel hükümleri, özel ceza kanunları ve ceza içeren kanunlardaki suçlar hakkında da uygulanır.'","kaynak":"5237 m.5","zorluk":"orta"},
    {"id":"5237-S-005","soru":"5237 sayılı Türk Ceza Kanunu'na göre ceza sorumluluğunun şahsiliği ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Ceza sorumluluğu şahsidir.","Kimse başkasının fiilinden dolayı sorumlu tutulamaz.","Tüzel kişiler hakkında ceza yaptırımı uygulanamaz.","Tüzel kişiler hakkında suç dolayısıyla kanunda öngörülen güvenlik tedbiri niteliğindeki yaptırımlar saklıdır.","Tüzel kişiler hakkında hapis cezası dışındaki adli para cezalarına hükmedilebilir."],"dogru":4,"aciklama":"m.20'ye göre tüzel kişiler hakkında ceza yaptırımı uygulanamaz; yalnızca güvenlik tedbiri niteliğindeki yaptırımlar saklıdır. (E) tüzel kişiye adli para cezası verilebileceğini söyleyerek maddeye aykırıdır.","kaynak":"5237 m.20","zorluk":"orta"},
    {"id":"5237-S-006","soru":"5237 sayılı Türk Ceza Kanunu'na göre kast aşağıdakilerden hangisidir?","siklar":["Suçun kanuni tanımındaki unsurların gerçekleşebileceğinin öngörülmesine rağmen fiilin işlenmesidir.","Dikkat ve özen yükümlülüğüne aykırılık dolayısıyla neticenin öngörülmeyerek gerçekleştirilmesidir.","Öngörülen neticenin istenmemesine karşın meydana gelmesidir.","Kastedilenden daha ağır bir neticenin oluşmasıdır.","Suçun kanuni tanımındaki unsurların bilerek ve istenerek gerçekleştirilmesidir."],"dogru":4,"aciklama":"m.21/1: 'Kast, suçun kanuni tanımındaki unsurların bilerek ve istenerek gerçekleştirilmesidir.'","kaynak":"5237 m.21/1","zorluk":"orta"},
    {"id":"5237-S-007","soru":"5237 sayılı Türk Ceza Kanunu'na göre, kişinin suçun kanuni tanımındaki unsurların gerçekleşebileceğini öngörmesine rağmen fiili işlemesi hâlinde (olası kast) ağırlaştırılmış müebbet hapis cezasını gerektiren suçlarda hangi cezaya hükmolunur?","siklar":["Yirmi yıldan yirmibeş yıla kadar hapis cezası","Müebbet hapis cezası","Onaltı yıldan yirmi yıla kadar hapis cezası","Ağırlaştırılmış müebbet hapis cezası temel hâliyle uygulanır","On yıldan onbeş yıla kadar hapis cezası"],"dogru":1,"aciklama":"m.21/2'ye göre olası kast hâlinde ağırlaştırılmış müebbet hapis cezasını gerektiren suçlarda müebbet hapis cezasına, müebbet hapis cezasını gerektiren suçlarda yirmi yıldan yirmibeş yıla kadar hapis cezasına hükmolunur; diğer hâllerde temel ceza üçte birden yarısına kadar indirilir.","kaynak":"5237 m.21/2","zorluk":"zor"},
    {"id":"5237-S-008","soru":"5237 sayılı Türk Ceza Kanunu'na göre, kişinin öngördüğü neticeyi istememesine karşın neticenin meydana gelmesi hâlinde bilinçli taksir vardır; bu hâlde taksirli suça ilişkin ceza ............ artırılır. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["üçte birden yarısına kadar","dörtte birden dörtte üçüne kadar","yarısına kadar","bir katı oranında","üçte ikisi oranında"],"dogru":0,"aciklama":"m.22/3: bilinçli taksirde taksirli suça ilişkin ceza üçte birden yarısına kadar artırılır.","kaynak":"5237 m.22/3","zorluk":"orta"},
    {"id":"5237-S-009","soru":"5237 sayılı Türk Ceza Kanunu'na göre, 'kişinin öngördüğü neticeyi istememesine karşın neticenin meydana gelmesi' aşağıdaki kusurluluk şekillerinden hangisini ifade eder?","siklar":["Kast","Olası kast","Bilinçli taksir","Basit (bilinçsiz) taksir","Netice sebebiyle ağırlaşma"],"dogru":2,"aciklama":"m.22/3: 'Kişinin öngördüğü neticeyi istememesine karşın, neticenin meydana gelmesi hâlinde bilinçli taksir vardır.' Failin neticeyi öngörmesi onu basit taksirden, istememesi ise kasıttan ayırır.","kaynak":"5237 m.21-22","zorluk":"zor"},
    {"id":"5237-S-010","soru":"5237 sayılı Türk Ceza Kanunu'na göre, bir fiilin kastedilenden daha ağır veya başka bir neticenin oluşumuna sebebiyet vermesi hâlinde (netice sebebiyle ağırlaşmış suç), failin bu ağır neticeden sorumlu tutulabilmesi bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Fail, ağır neticeyi de doğrudan kastetmiş olmalıdır.","Failin ağır netice bakımından olası kastla hareket etmesi şarttır.","Ağır neticeden sorumluluk için kusur aranmaz; objektif (kusursuz) sorumluluk geçerlidir.","Fail, ağır netice bakımından en azından taksirle hareket etmiş olmalıdır.","Ağır netice öngörülemez nitelikte olsa dahi fail her hâlde sorumlu tutulur."],"dogru":3,"aciklama":"m.23/1'e göre ağır neticeden sorumluluk için kişinin o netice bakımından en azından taksirle hareket etmiş olması gerekir. Kanun objektif sorumluluğu reddedip en az taksir eşiği arar.","kaynak":"5237 m.23/1","zorluk":"orta"},
    {"id":"5237-S-011","soru":"5237 sayılı Türk Ceza Kanunu'na göre suça teşebbüsün oluşabilmesi için aşağıdakilerden hangisi gerekli değildir?","siklar":["Kişinin işlemeyi kastettiği bir suç bulunması","Elverişli hareketlerle doğrudan doğruya icraya başlanması","Suçun elinde olmayan nedenlerle tamamlanamaması","Failin icra hareketlerinden kendi isteğiyle vazgeçmiş olması","İcra hareketlerine başlanmış olması"],"dogru":3,"aciklama":"m.35/1'e göre teşebbüs; kastedilen suça elverişli hareketlerle icraya başlanıp elinde olmayan nedenlerle tamamlanamamasıdır. (D)'deki 'kendi isteğiyle vazgeçme' teşebbüs değil, gönüllü vazgeçmedir (m.36).","kaynak":"5237 m.35/1","zorluk":"orta"},
    {"id":"5237-S-012","soru":"5237 sayılı Türk Ceza Kanunu'na göre, suça teşebbüs hâlinde (ağırlaştırılmış müebbet ve müebbet dışındaki) diğer hâllerde verilecek ceza ne oranda indirilir?","siklar":["Üçte birden yarısına kadar","Yarısından üçte ikisine kadar","Beşte birinden beşte dördüne kadar","Üçte ikisine kadar","Dörtte birinden dörtte üçüne kadar"],"dogru":4,"aciklama":"m.35/2'ye göre teşebbüste, meydana gelen zarar veya tehlikenin ağırlığına göre, diğer hâllerde verilecek cezanın dörtte birinden dörtte üçüne kadarı indirilir.","kaynak":"5237 m.35/2","zorluk":"zor"},
    {"id":"5237-S-013","soru":"5237 sayılı Türk Ceza Kanunu'na göre, suçun icra hareketlerinden gönüllü vazgeçen fail teşebbüsten dolayı cezalandırılmaz; ancak tamam olan kısım esasen bir suç oluşturuyorsa sadece o suça ait ceza ile cezalandırılır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.36 birebir bu düzenlemeyi içerir: gönüllü vazgeçende teşebbüs cezası yoktur; tamamlanan kısım bağımsız bir suçsa yalnız ondan ceza verilir.","kaynak":"5237 m.36","zorluk":"orta"},
    {"id":"5237-S-014","soru":"5237 sayılı Türk Ceza Kanunu'na göre, suçun işlenmesinde bir başkasını araç olarak kullanan kişi ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Yardım eden olarak sorumlu tutulur.","Azmettiren olarak sorumlu tutulur.","Fail olarak sorumlu tutulur; kusur yeteneği olmayanları araç olarak kullanırsa cezası üçte birden yarısına kadar artırılır.","Suça iştirakten dolayı cezası yarı oranında indirilir.","Yalnızca aracı kullanılan kişi cezalandırılır."],"dogru":2,"aciklama":"m.37/2'ye göre bir başkasını araç olarak kullanan kişi fail olarak sorumlu tutulur; kusur yeteneği olmayanları araç olarak kullananın cezası üçte birden yarısına kadar artırılır.","kaynak":"5237 m.37/2","zorluk":"orta"},
    {"id":"5237-S-015","soru":"5237 sayılı Türk Ceza Kanunu'na göre, başkasını suç işlemeye azmettiren kişi, işlenen suçun cezasının yarısı ile cezalandırılır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.38/1'e göre azmettiren, işlenen suçun cezası ile (yarısı değil, tam olarak) cezalandırılır. Bu nedenle ifade yanlıştır.","kaynak":"5237 m.38/1","zorluk":"orta"},
    {"id":"5237-S-016","soru":"5237 sayılı Türk Ceza Kanunu'na göre suça yardım etme ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Yardım eden, işlenen suçun cezasıyla aynen cezalandırılır.","Yardım edenin cezası üçte birden yarısına kadar artırılır.","Suç işleme kararını kuvvetlendirmek yardım etme değil azmettirme sayılır.","Yardım edenin cezası diğer hâllerde yarısı indirilir; ancak verilecek ceza sekiz yılı geçemez.","Yardım edenin cezası her hâlde on yılı geçemez."],"dogru":3,"aciklama":"m.39/1: diğer hâllerde cezanın yarısı indirilir; ancak bu durumda verilecek ceza sekiz yılı geçemez. m.39/2-a'ya göre suç işleme kararını kuvvetlendirmek yardım etmedir.","kaynak":"5237 m.39/1","zorluk":"zor"},
    {"id":"5237-S-017","soru":"5237 sayılı Türk Ceza Kanunu'na göre, bir suçun işlenmesinde kullanılacak silahı, suçun icrasından önce faile temin eden ancak suçun icra hareketlerine bizzat katılmayan kişinin iştirakteki konumu aşağıdakilerden hangisidir?","siklar":["Asli (müşterek) fail olarak sorumlu tutulur.","Azmettiren olarak sorumlu tutulur.","Suça iştiraki bulunmadığından cezai sorumluluğu doğmaz.","Suça yardım eden olarak sorumlu tutulur.","Yalnızca teşebbüsten sorumlu tutulur."],"dogru":3,"aciklama":"m.39/2-b'ye göre 'fiilin işlenmesinde kullanılan araçları sağlamak' yardım etme hâllerindendir. İcra hareketine katılmayıp araç sağlayan kişi, fail değil yardım eden olarak sorumlu tutulur (m.39/1 uyarınca cezası indirilir).","kaynak":"5237 m.39/2","zorluk":"zor"},
    {"id":"5237-S-018","soru":"5237 sayılı Türk Ceza Kanunu'na göre özgü suçlar bakımından bağlılık kuralı ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Özgü suçlarda özel faillik niteliğini taşımayanlar da asli fail olabilir.","Özgü suçlarda ancak özel faillik niteliğini taşıyan kişi fail olabilir; diğerleri azmettiren veya yardım eden olarak sorumlu tutulur.","Suça iştirakten sorumluluk için suçun tamamlanmış olması zorunludur.","Suça iştirak için failin kusurlu olması her hâlde gerekir.","Özgü suçlara iştirak edenler de fail sıfatıyla cezalandırılır."],"dogru":1,"aciklama":"m.40/2'ye göre özgü suçlarda yalnız özel faillik niteliğini taşıyan kişi fail olabilir; diğerleri azmettiren veya yardım eden olur. m.40/3'e göre iştirak için suçun en az teşebbüs aşamasına varması yeterlidir (tamamlanması şart değil).","kaynak":"5237 m.40/2","zorluk":"zor"},
    {"id":"5237-S-019","soru":"5237 sayılı Türk Ceza Kanunu'na göre suçların içtimaı ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Biri diğerinin unsurunu veya ağırlaştırıcı nedenini oluşturması dolayısıyla tek fiil sayılan suça bileşik suç denir.","Bir suç işleme kararının icrası kapsamında, değişik zamanlarda bir kişiye karşı aynı suçun birden fazla işlenmesi durumunda zincirleme suç hükümleri uygulanır.","İşlediği bir fiil ile birden fazla farklı suçun oluşmasına sebebiyet veren kişi, bunlardan en ağır cezayı gerektiren suçtan dolayı cezalandırılır.","Zincirleme suç hükümlerinin uygulanması hâlinde tek bir cezaya hükmedilir; ancak bu ceza dörtte birinden dörtte üçüne kadar artırılır.","Kasten öldürme, kasten yaralama, işkence ve yağma suçlarında da zincirleme suç hükümleri uygulanır."],"dogru":4,"aciklama":"m.43/3'e göre kasten öldürme, kasten yaralama, işkence ve yağma suçlarında zincirleme suç hükümleri UYGULANMAZ. (E) bunun tersini söyleyerek yanlıştır. A=m.42, B=m.43/1, C=m.44, D=m.43/1 doğrudur.","kaynak":"5237 m.42-43-44","zorluk":"zor"},
    {"id":"5237-S-020","soru":"5237 sayılı Türk Ceza Kanunu'na göre suç karşılığında uygulanan yaptırım olarak cezalar aşağıdakilerden hangisinde birlikte ve doğru verilmiştir?","siklar":["Hapis ve güvenlik tedbirleri","Hapis, adlî para cezası ve müsadere","Adlî para cezası ve idari para cezası","Hapis ve adlî para cezaları","Hapis, sürgün ve adlî para cezası"],"dogru":3,"aciklama":"m.45: 'Suç karşılığında uygulanan yaptırım olarak cezalar, hapis ve adlî para cezalarıdır.'","kaynak":"5237 m.45","zorluk":"kolay"},
    {"id":"5237-S-021","soru":"5237 sayılı Türk Ceza Kanunu'na göre, görevi nedeniyle zilyedliği kendisine devredilmiş olan veya koruma ve gözetimiyle yükümlü olduğu malı kendisinin veya başkasının zimmetine geçiren kamu görevlisine verilecek ceza aşağıdakilerden hangisidir?","siklar":["Üç yıldan sekiz yıla kadar hapis","Dört yıldan oniki yıla kadar hapis","Beş yıldan oniki yıla kadar hapis","Altı yıldan onbeş yıla kadar hapis","İki yıldan beş yıla kadar hapis"],"dogru":2,"aciklama":"m.247/1'e göre zimmet suçunun cezası beş yıldan oniki yıla kadar hapistir.","kaynak":"5237 m.247/1","zorluk":"orta"},
    {"id":"5237-S-022","soru":"5237 sayılı Türk Ceza Kanunu'na göre zimmet suçu ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Suçun konusu yalnızca paradır; başka mallar zimmet suçuna konu olamaz.","Suçun, zimmetin açığa çıkmamasını sağlamaya yönelik hileli davranışlarla işlenmesi hâlinde verilecek ceza yarı oranında artırılır.","Zimmet suçunun, malın geçici bir süre kullanıldıktan sonra iade edilmek üzere işlenmesi hâlinde verilecek ceza yarı oranına kadar indirilebilir.","Suçun faili kamu görevlisidir.","Mal, görevi nedeniyle zilyedliği faile devredilmiş ya da koruma ve gözetimiyle yükümlü olduğu mal olmalıdır."],"dogru":0,"aciklama":"m.247'ye göre suçun konusu 'mal'dır, yalnızca para değildir. (A) suçun konusunu paraya indirgeyerek yanlıştır. B (m.247/2), C (m.247/3), D ve E maddeye uygundur.","kaynak":"5237 m.247","zorluk":"orta"},
    {"id":"5237-S-023","soru":"5237 sayılı Türk Ceza Kanunu'na göre, zimmet suçunda soruşturma başlamadan önce zimmete geçirilen malın aynen iade edilmesi veya uğranılan zararın tamamen tazmin edilmesi hâlinde verilecek cezada ne oranda indirim yapılır?","siklar":["Yarısı indirilir","Üçte biri indirilir","Üçte ikisi indirilir","Dörtte üçü indirilir","Tamamı kaldırılır, cezaya hükmolunmaz"],"dogru":2,"aciklama":"m.248/1'e göre soruşturma başlamadan önce aynen iade veya tam tazmin hâlinde verilecek cezanın üçte ikisi indirilir. Kovuşturmadan önce yarısı, hükümden önce üçte biri indirilir.","kaynak":"5237 m.248/1","zorluk":"zor"},
    {"id":"5237-S-024","soru":"5237 sayılı Türk Ceza Kanunu'na göre, görevinin sağladığı nüfuzu kötüye kullanmak suretiyle kendisine veya başkasına yarar sağlanmasına bir kimseyi icbar eden kamu görevlisine verilecek ceza aşağıdakilerden hangisidir?","siklar":["Üç yıldan beş yıla kadar hapis","Bir yıldan üç yıla kadar hapis","Dört yıldan oniki yıla kadar hapis","Altı aydan iki yıla kadar hapis","Beş yıldan on yıla kadar hapis"],"dogru":4,"aciklama":"m.250/1 (icbar suretiyle irtikâp): beş yıldan on yıla kadar hapis. İkna suretiyle (m.250/2) üç yıldan beş yıla, kişinin hatasından yararlanma (m.250/3) bir yıldan üç yıla kadar hapistir.","kaynak":"5237 m.250/1","zorluk":"orta"},
    {"id":"5237-S-025","soru":"5237 sayılı Türk Ceza Kanunu'na göre, görevinin ifasıyla ilgili bir işi yapması veya yapmaması için doğrudan veya aracılar vasıtasıyla bir kamu görevlisine menfaat sağlayan kişiye verilecek ceza aşağıdakilerden hangisidir?","siklar":["Beş yıldan oniki yıla kadar hapis","Dört yıldan oniki yıla kadar hapis","İki yıldan beş yıla kadar hapis","Üç yıldan yedi yıla kadar hapis","Altı aydan iki yıla kadar hapis"],"dogru":1,"aciklama":"m.252/1'e göre rüşvet veren kişiye dört yıldan oniki yıla kadar hapis cezası verilir; m.252/2 uyarınca menfaat sağlayan kamu görevlisi de aynı ceza ile cezalandırılır (alan da veren de eşit ceza).","kaynak":"5237 m.252/1","zorluk":"orta"},
    {"id":"5237-S-026","soru":"5237 sayılı Türk Ceza Kanunu'na göre, rüşvet suçunun işlenmesi suretiyle yararına haksız menfaat sağlanan tüzel kişiler hakkında bunlara özgü güvenlik tedbirlerine hükmolunur. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.253: rüşvetle yararına haksız menfaat sağlanan tüzel kişiler hakkında bunlara özgü güvenlik tedbirlerine hükmolunur. Bu, m.20'deki tüzel kişiye ceza verilemeyeceği ilkesinin somut hâlidir.","kaynak":"5237 m.253","zorluk":"orta"},
    {"id":"5237-S-027","soru":"5237 sayılı Türk Ceza Kanunu'na göre, kamu görevlisi üzerinde nüfuz sahibi olduğundan bahisle, haksız bir işin gördürülmesi amacıyla girişimde bulunması için kendisine veya bir başkasına menfaat temin eden kişiye verilecek ceza aşağıdakilerden hangisidir?","siklar":["Beş yıldan oniki yıla kadar hapis","Dört yıldan oniki yıla kadar hapis","Bir yıldan üç yıla kadar hapis","İki yıldan beş yıla kadar hapis ve beşbin güne kadar adlî para cezası","Altı aydan iki yıla kadar hapis ve adlî para cezası"],"dogru":3,"aciklama":"m.255/1'e göre nüfuz ticareti suçunun cezası iki yıldan beş yıla kadar hapis ve beşbin güne kadar adlî para cezasıdır.","kaynak":"5237 m.255/1","zorluk":"orta"},
    {"id":"5237-S-028","soru":"5237 sayılı Türk Ceza Kanunu'na göre, zor kullanma yetkisine sahip kamu görevlisinin görevini yaptığı sırada kişilere karşı görevinin gerektirdiği ölçünün dışında kuvvet kullanması hâlinde hangi suça ilişkin hükümler uygulanır?","siklar":["Görevi kötüye kullanma suçuna ilişkin hükümler","Kasten yaralama suçuna ilişkin hükümler","İrtikâp suçuna ilişkin hükümler","Eziyet suçuna ilişkin hükümler","Görevi yaptırmamak için direnme suçuna ilişkin hükümler"],"dogru":1,"aciklama":"m.256'ya göre zor kullanma yetkisinin ölçüsü aşıldığında kasten yaralama suçuna ilişkin hükümler uygulanır.","kaynak":"5237 m.256","zorluk":"orta"},
    {"id":"5237-S-029","soru":"5237 sayılı Türk Ceza Kanunu'na göre görevi kötüye kullanma suçu ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Suç, kanunda ayrıca suç olarak tanımlanan hâller dışında uygulanır.","Görevinin gereklerine aykırı hareketle kişilerin mağduriyetine veya kamunun zararına neden olan ya da kişilere haksız menfaat sağlayan kamu görevlisi altı aydan iki yıla kadar hapisle cezalandırılır.","Görevinin gereklerini yapmakta ihmal veya gecikme gösteren kamu görevlisi üç aydan bir yıla kadar hapisle cezalandırılır.","Suçun oluşması için kişilerin mağduriyeti, kamunun zararı veya haksız menfaat sağlanması koşullarından birinin gerçekleşmesi gerekir.","Görevinin gereklerine aykırı hareket eden kamu görevlisine her hâlde beş yıldan on yıla kadar hapis verilir."],"dogru":4,"aciklama":"m.257/1'e göre icrai görevi kötüye kullanma cezası altı aydan iki yıla kadar hapistir; (E)'deki '5-10 yıl' tamamen yanlıştır. A, B (m.257/1), C (m.257/2), D maddeye uygundur.","kaynak":"5237 m.257","zorluk":"zor"},
    {"id":"5237-S-030","soru":"5237 sayılı Türk Ceza Kanunu'na göre, hukuka aykırı olarak ve toplu biçimde görevlerini terk eden kamu görevlileri ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Her biri hakkında üç aydan bir yıla kadar hapis verilir; kamu görevlisi sayısı üçten fazla değilse cezaya hükmolunmaz.","Her biri hakkında bir yıldan üç yıla kadar hapis verilir; sayı beşten fazla değilse ceza verilmez.","Suç yalnızca tek bir kamu görevlisinin görevi terkiyle de oluşur.","Toplu görev terkinde fiil her hâlde cezasız kalır.","Her biri hakkında altı aydan iki yıla kadar hapis verilir."],"dogru":0,"aciklama":"m.260/1: toplu ve hukuka aykırı görev terkinde her biri için üç aydan bir yıla kadar hapis; kamu görevlisi sayısı üçten fazla olmazsa cezaya hükmolunmaz.","kaynak":"5237 m.260/1","zorluk":"orta"},
    {"id":"5237-S-031","soru":"5237 sayılı Türk Ceza Kanunu'na göre, kamu görevlisine karşı görevini yapmasını engellemek amacıyla cebir veya tehdit kullanan kişiye verilecek ceza aşağıdakilerden hangisidir?","siklar":["Altı aydan üç yıla kadar hapis","Bir yıldan üç yıla kadar hapis","İki yıldan dört yıla kadar hapis","Üç aydan iki yıla kadar hapis","Beş yıldan on yıla kadar hapis"],"dogru":0,"aciklama":"m.265/1: görevi yaptırmamak için direnmede cebir veya tehdit kullanan kişiye altı aydan üç yıla kadar hapis verilir. Suç yargı görevi yapanlara karşı işlenirse (m.265/2) iki yıldan dört yıla kadar hapse hükmolunur.","kaynak":"5237 m.265/1-2","zorluk":"orta"},
    {"id":"5237-S-032","soru":"5237 sayılı Türk Ceza Kanunu'na göre askerî komutanlıkların gaspı suçu ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Suçun cezası müebbet hapistir.","Bir savaş gemisinin veya savaş hava filosunun komutasını yetkisiz alan kişi de bu suçtan sorumlu tutulur.","Suçun oluşması için fiilin savaş zamanında işlenmiş olması şarttır.","Yetkili makamlarca komutanlığı terk etmeleri için verilen emirlere uymayanlara da aynı ceza verilir.","Bir askerî üssün veya tesisin komutasını yetkisiz almak da bu suçu oluşturur."],"dogru":2,"aciklama":"m.317'ye göre suçun cezası müebbet hapistir ve oluşması için savaş zamanı şartı ARANMAZ. (C) savaş zamanı şartı koşarak maddeyi çarpıtır; yanlıştır. A, B, D (m.317/2), E maddeye uygundur.","kaynak":"5237 m.317","zorluk":"orta"},
    {"id":"5237-S-033","soru":"5237 sayılı Türk Ceza Kanunu'na göre, askerlik hizmetini yapanları firara sevk edecek veya askerlik hizmetine katılacak olanları bu hizmeti yapmaktan vazgeçirecek şekilde teşvik veya telkinde bulunma (halkı askerlikten soğutma) suçu ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Faile altı aydan iki yıla kadar hapis cezası verilir.","Fiil, basın ve yayın yolu ile işlenirse ceza yarısı oranında artırılır.","Fiilin basın ve yayın yolu ile işlenmesi cezayı bir kat artırır.","Suç, askerlik hizmetine katılacakları bu hizmetten vazgeçirecek telkinle de işlenebilir.","Suç, askerlik hizmetini yapanları firara sevk edecek teşvikle işlenebilir."],"dogru":2,"aciklama":"m.318/2'ye göre fiil basın ve yayın yolu ile işlenirse ceza YARISI oranında artırılır, bir kat değil. (C) bu nedenle yanlıştır; (B) doğrudur.","kaynak":"5237 m.318","zorluk":"orta"},
    {"id":"5237-S-034","soru":"5237 sayılı Türk Ceza Kanunu'na göre, savaş zamanında Devletin yetkili makam ve mercilerinin emir veya kararlarına bilerek aykırı harekette bulunan kimseye aşağıdaki cezalardan hangisi verilir?","siklar":["Bir yıldan altı yıla kadar hapis","Üç yıldan on yıla kadar hapis","Beş yıldan onbeş yıla kadar hapis","Müebbet hapis","Altı aydan üç yıla kadar hapis"],"dogru":0,"aciklama":"m.321: savaş zamanında yetkili makam ve mercilerin emir veya kararlarına bilerek aykırı harekette bulunana bir yıldan altı yıla kadar hapis verilir.","kaynak":"5237 m.321","zorluk":"orta"},
    {"id":"5237-S-035","soru":"5237 sayılı Türk Ceza Kanunu'nun 324. maddesine göre, '............ zamanında seferberlikle ilgili görevlerini ihmal eden veya geciktiren kamu görevlisine altı aydan üç yıla kadar hapis cezası verilir.' cümlesinde boş bırakılan yere aşağıdakilerden hangisi gelmelidir?","siklar":["Savaş","Sulh (barış)","Seferberlik","Olağanüstü hâl","Sıkıyönetim"],"dogru":1,"aciklama":"m.324/1: 'Sulh zamanında seferberlikle ilgili görevlerini ihmal eden veya geciktiren kamu görevlisine altı aydan üç yıla kadar hapis cezası verilir.' Bu suç barış (sulh) zamanında işlenir.","kaynak":"5237 m.324/1","zorluk":"zor"},
    {"id":"5237-S-036","soru":"5237 sayılı Türk Ceza Kanunu'na göre aşağıdaki Milli Savunmaya Karşı Suçlardan hangisinin oluşması için fiilin 'savaş zamanında' işlenmiş olması şart değildir?","siklar":["Savaş zamanında emirlere uymama (m.321)","Halkı askerlikten soğutma (m.318)","Savaş zamanında yükümlülükleri yerine getirmeme (m.322)","Savaşta yalan haber yayma (m.323)","Türkiye ile savaş hâlindeki devletten unvan kabulü (m.325)"],"dogru":1,"aciklama":"m.318 (halkı askerlikten soğutma) barış zamanında da işlenebilen bir suçtur; oluşması için savaş zamanı şart değildir. Buna karşılık m.321, m.322, m.323 ve m.325 ancak savaş hâli/zamanı koşuluyla işlenir.","kaynak":"5237 m.317-325","zorluk":"zor"},
    {"id":"5237-OO-001","soru":"Bir kamu kurumunda görev yapan memur A, ruhsat başvurusu için kendisine gelen B'ye, 'dosyanı işleme koymam, hakkında olumsuz rapor da yazarım' diyerek korkutmuş ve görevinin sağladığı nüfuzu kötüye kullanarak B'yi kendisine 5.000 TL vermeye mecbur etmiştir. B, mağdur olmamak için parayı vermiştir. A'nın bu fiili hangi suçu oluşturur?","siklar":["Rüşvet","İrtikâp (icbar suretiyle)","Zimmet","Nüfuz ticareti","Görevi kötüye kullanma"],"dogru":1,"aciklama":"m.250/1'e göre görevinin sağladığı nüfuzu kötüye kullanarak bir kimseyi kendisine yarar sağlamaya icbar (mecbur) eden kamu görevlisi irtikâp suçunu işler. Olayda memurun baskı/korkutma ile yararı zorla sağlaması icbar suretiyle irtikâbı oluşturur.","kaynak":"5237 m.250/1","zorluk":"orta"},
    {"id":"5237-OO-002","soru":"Belediyede veznedar olarak görev yapan A, görevi nedeniyle kendisine teslim edilen tahsilat kasasındaki parayı, kişisel kredi borcunu ödemek için çekip kullanmıştır. A'nın bu fiili hangi suçu oluşturur?","siklar":["Rüşvet","İrtikâp","Zimmet","Güveni kötüye kullanma","Dolandırıcılık"],"dogru":2,"aciklama":"m.247/1'e göre görevi nedeniyle zilyedliği kendisine devredilmiş olan malı kendisinin zimmetine geçiren kamu görevlisi zimmet suçunu işler. Paranın görevi nedeniyle veznedarın elinde bulunması ve onu kendi cebine geçirmesi zimmeti oluşturur.","kaynak":"5237 m.247/1","zorluk":"orta"},
    {"id":"5237-OO-003","soru":"Müteahhit A, açılan bir ihaleyi kazanmak için ihale komisyonu üyesi kamu görevlisi B ile, B'ye belirli bir menfaat sağlanması konusunda anlaşmıştır. Ancak menfaat henüz el değiştirmeden olay ortaya çıkmış ve para verilmemiştir. Bu durumda rüşvet suçu bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Menfaat fiilen verilmediği için rüşvet suçu oluşmaz.","Yalnızca rüşvete teşebbüsten ceza verilir.","Rüşvet konusunda anlaşmaya varılması hâlinde suç tamamlanmış gibi cezaya hükmolunur.","Sadece kamu görevlisi B cezalandırılır.","Fiil görevi kötüye kullanma olarak nitelendirilir."],"dogru":2,"aciklama":"m.252/3'e göre rüşvet konusunda anlaşmaya varılması hâlinde suç tamamlanmış gibi cezaya hükmolunur. Bu nedenle menfaat henüz verilmemiş olsa bile anlaşma rüşveti tamamlanmış sayar.","kaynak":"5237 m.252/3","zorluk":"zor"},
    {"id":"5237-OO-004","soru":"A, aslında hiçbir resmî bağlantısı bulunmadığı hâlde B'ye, 'vergi dairesinde sözüm geçer, kesilen cezanı sildiririm' diyerek, haksız işin gördürülmesi amacıyla B'den 10.000 TL menfaat temin etmiştir. Gerçekte A herhangi bir kamu görevlisiyle irtibata dahi geçmemiştir. A'nın fiili hangi suçu oluşturur?","siklar":["Rüşvet","Nüfuz ticareti","İrtikâp","Zimmet","Görevi kötüye kullanma"],"dogru":1,"aciklama":"m.255/1'e göre kamu görevlisi üzerinde nüfuz sahibi olduğundan bahisle, haksız bir işin gördürülmesi amacıyla girişimde bulunması için kendisine menfaat temin eden kişi nüfuz ticareti suçunu işler. A'nın 'sözüm geçer' diyerek menfaat alması bu suçu oluşturur.","kaynak":"5237 m.255/1","zorluk":"zor"},
    {"id":"5237-OO-005","soru":"Zor kullanma yetkisine sahip kamu görevlisi A, görevini yaptığı sırada kendisine direnmeyen ve teslim olmuş B'ye, görevinin gerektirdiği ölçünün çok dışında güç kullanarak vurmuş ve B'yi yaralamıştır. A hakkında hangi suça ilişkin hükümler uygulanır?","siklar":["Eziyet suçuna ilişkin hükümler","İşkence suçuna ilişkin hükümler","Kasten yaralama suçuna ilişkin hükümler","Görevi kötüye kullanma suçuna ilişkin hükümler","Görevi yaptırmamak için direnme suçuna ilişkin hükümler"],"dogru":2,"aciklama":"m.256'ya göre zor kullanma yetkisine sahip kamu görevlisinin görevini yaptığı sırada görevinin gerektirdiği ölçünün dışında kuvvet kullanması hâlinde kasten yaralama suçuna ilişkin hükümler uygulanır.","kaynak":"5237 m.256","zorluk":"orta"},
    {"id":"5237-OO-006","soru":"İcra memuru A, mahkeme kararına dayanarak haciz işlemi yapmak üzere eve geldiğinde, ev sahibi B 'buradan defol, yoksa sana zarar veririm' diyerek A'yı tehdit etmiş ve görevini yapmasını engellemiştir. B'nin bu fiili hangi suçu oluşturur?","siklar":["Tehdit","Görevi yaptırmamak için direnme","Hakaret","Kişiyi hürriyetinden yoksun kılma","Görevi kötüye kullanma"],"dogru":1,"aciklama":"m.265/1'e göre kamu görevlisine karşı görevini yapmasını engellemek amacıyla cebir veya tehdit kullanan kişi görevi yaptırmamak için direnme suçunu işler. B'nin tehditle icra memurunun görevini engellemesi bu suçu oluşturur.","kaynak":"5237 m.265/1","zorluk":"orta"},
    {"id":"5237-OO-007","soru":"Kamu görevlisi A, görevinin gereklerine aykırı hareket ederek B'nin mağduriyetine neden olmuştur. Ancak A'nın bu fiili kanunda zimmet, rüşvet, irtikâp gibi ayrıca bir suç olarak tanımlanmamış olup, A herhangi bir menfaat de sağlamamıştır. A'nın fiili hangi suçu oluşturur?","siklar":["Zimmet","İrtikâp","Rüşvet","Görevi kötüye kullanma","Hiçbir suç oluşmaz"],"dogru":3,"aciklama":"m.257/1'e göre kanunda ayrıca suç olarak tanımlanan hâller dışında, görevinin gereklerine aykırı hareketle kişilerin mağduriyetine neden olan kamu görevlisi görevi kötüye kullanma suçunu işler. Bu suç tali (genel) niteliktedir; başka özel bir suç oluşmadığında devreye girer.","kaynak":"5237 m.257/1","zorluk":"zor"},
    {"id":"5237-OO-008","soru":"A, husumetli olduğu B'yi öldürmek amacıyla silahını B'ye doğrultmuş, ancak ateş etmeden önce vicdanen pişman olarak kendi isteğiyle vazgeçmiş ve silahı indirmiştir. B hiçbir zarar görmemiştir. A'nın cezai durumu için aşağıdakilerden hangisi doğrudur?","siklar":["Kasten öldürmeye teşebbüsten tam ceza ile cezalandırılır.","Teşebbüs hükümleri uyarınca cezası dörtte birinden dörtte üçüne indirilerek cezalandırılır.","Gönüllü vazgeçtiği için teşebbüsten dolayı cezalandırılmaz; ancak o ana kadar tamam olan kısım esasen bir suç oluşturuyorsa yalnız ondan cezalandırılır.","Olası kasttan cezalandırılır.","Hiçbir şekilde cezalandırılamaz."],"dogru":2,"aciklama":"m.36'ya göre suçun icra hareketlerinden gönüllü vazgeçen fail teşebbüsten dolayı cezalandırılmaz; fakat tamam olan kısım esasen bir suç oluşturuyorsa sadece o suça ait ceza ile cezalandırılır. A kendi iradesiyle vazgeçtiği için öldürmeye teşebbüsten ceza almaz.","kaynak":"5237 m.36","zorluk":"orta"},
    {"id":"5237-OO-009","soru":"A, kalabalık bir caddede, insanların bulunduğu yöne doğru 'isabet ederse etsin, umurumda değil' düşüncesiyle ateş etmiş, çıkan kurşun yoldan geçen B'yi yaralamıştır. A'nın B'nin yaralanması bakımından kusurluluk durumu aşağıdakilerden hangisidir?","siklar":["Doğrudan (asıl) kast","Olası kast","Bilinçli taksir","Basit (bilinçsiz) taksir","Kusursuzluk"],"dogru":1,"aciklama":"m.21/2'ye göre kişinin suçun kanuni tanımındaki unsurların gerçekleşebileceğini öngörmesine rağmen fiili işlemesi hâlinde olası kast vardır. A neticenin gerçekleşebileceğini öngörmüş ve 'olursa olsun' tutumuyla hareket etmiştir.","kaynak":"5237 m.21/2","zorluk":"zor"},
    {"id":"5237-OO-010","soru":"A, yalnızca canını yakmak amacıyla B'ye bir tokat atmış; ancak B dengesini kaybedip yere düşmüş, başını sert bir zemine çarparak ölmüştür. A'nın B'nin ölümünden de sorumlu tutulabilmesi için aşağıdakilerden hangisi gereklidir?","siklar":["A'nın ölüm neticesini de doğrudan kastetmiş olması","A'nın ölüm neticesi bakımından en azından taksirle hareket etmiş olması","Ölüm neticesi için herhangi bir kusur aranmaz, A doğrudan sorumludur","A'nın ölüm bakımından mutlaka olası kastla hareket etmiş olması","Netice öngörülemez olsa dahi A'nın sorumlu tutulması"],"dogru":1,"aciklama":"m.23'e göre bir fiil kastedilenden daha ağır veya başka bir neticenin oluşumuna sebebiyet vermişse, kişinin bundan sorumlu tutulabilmesi için bu netice bakımından en azından taksirle hareket etmesi gerekir. A yaralama kastıyla hareket etmiş, ölüm bakımından en az taksiri varsa ölümden sorumlu olur.","kaynak":"5237 m.23","zorluk":"zor"},
    {"id":"5237-OO-011","soru":"A, ceza sorumluluğu (kusur yeteneği) bulunmayan 11 yaşındaki çocuğu kandırarak bir mağazadan hırsızlık yaptırmıştır. A'nın hukuki durumu aşağıdakilerden hangisidir?","siklar":["A yalnızca azmettiren olarak sorumlu tutulur.","A yardım eden olarak sorumlu tutulur.","Çocuk araç olarak kullanıldığından A fail olarak sorumlu tutulur ve cezası üçte birden yarısına kadar artırılır.","Suçu fiilen çocuk işlediğinden yalnızca çocuk sorumlu tutulur.","A'nın herhangi bir cezai sorumluluğu doğmaz."],"dogru":2,"aciklama":"m.37/2'ye göre suçun işlenmesinde bir başkasını araç olarak kullanan kişi fail olarak sorumlu tutulur; kusur yeteneği olmayanları araç olarak kullananın cezası üçte birden yarısına kadar artırılır. A, kusur yeteneği olmayan çocuğu araç kullandığından dolaylı faildir ve cezası artırılır.","kaynak":"5237 m.37/2","zorluk":"zor"},
    {"id":"5237-OO-012","soru":"Kamu görevlisi olmayan sivil A, arkadaşı olan memur B'nin, görevi nedeniyle elinde bulunan parayı zimmetine geçirmesine bilerek ve isteyerek katkı sağlamıştır. Zimmet özgü (mahsus) bir suç olduğuna göre, A'nın iştirakteki durumu aşağıdakilerden hangisidir?","siklar":["A da zimmet suçunun müşterek faili olur.","Özgü suç olduğundan A fail olamaz; ancak azmettiren veya yardım eden olarak sorumlu tutulur.","Kamu görevlisi olmadığından A'nın hiçbir cezai sorumluluğu doğmaz.","A doğrudan fail sıfatıyla cezalandırılır.","Yalnızca memur B sorumlu olur, A'nın iştiraki cezalandırılmaz."],"dogru":1,"aciklama":"m.40/2'ye göre özgü suçlarda ancak özel faillik niteliğini taşıyan kişi fail olabilir; bu suçların işlenişine iştirak eden diğer kişiler azmettiren veya yardım eden olarak sorumlu tutulur. Kamu görevlisi olmayan A zimmette fail olamaz, ancak yardım eden olarak sorumludur.","kaynak":"5237 m.40/2","zorluk":"zor"},
    {"id":"5237-OO-013","soru":"Ortada herhangi bir savaş hâli bulunmayan barış (sulh) döneminde, seferberlikle ilgili hazırlık görevleri kendisine verilmiş kamu görevlisi A, bu görevlerini ihmal etmiş ve yerine getirmeyi geciktirmiştir. A'nın fiili hangi suçu oluşturur?","siklar":["Savaş zamanında emirlere uymama (m.321)","Sulh zamanında seferberlikle ilgili görevin ihmali (m.324)","Görevi kötüye kullanma (m.257)","Savaş zamanında yükümlülükleri yerine getirmeme (m.322)","Halkı askerlikten soğutma (m.318)"],"dogru":1,"aciklama":"m.324/1'e göre sulh zamanında seferberlikle ilgili görevlerini ihmal eden veya geciktiren kamu görevlisine altı aydan üç yıla kadar hapis cezası verilir. Olay barış zamanında geçtiğinden bu özel hüküm uygulanır.","kaynak":"5237 m.324/1","zorluk":"orta"},
  ],
  2: [
    {"id":"2803-S-001","soru":"2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu'na göre Türkiye Cumhuriyeti Jandarması, emniyet ve asayiş ile kamu düzeninin korunmasını sağlayan ve diğer kanunların ve Cumhurbaşkanlığı kararnamelerinin verdiği görevleri yerine getiren nasıl bir kuvvettir?","siklar":["Silahlı özel kolluk kuvvetidir","Askeri kolluk kuvvetidir","Silahlı genel kolluk kuvvetidir","Sivil genel kolluk kuvvetidir","Yardımcı kolluk kuvvetidir"],"dogru":2,"aciklama":"Madde 3: Türkiye Cumhuriyeti Jandarması ... 'silahlı genel kolluk kuvvetidir'.","kaynak":"2803 m.3","zorluk":"kolay"},
    {"id":"2803-S-002","soru":"2803 sayılı Kanun; Türkiye Cumhuriyeti Jandarma Teşkilatının görev, yetki ve sorumluluklarına, hizmetin gerektirdiği bağlılık ve ilişkilere, teşkilat ve konuşa ait esas ve usulleri düzenler. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Madde 1: Kanunun amacı bu şekilde tanımlanmıştır; ifade birebir doğrudur.","kaynak":"2803 m.1","zorluk":"kolay"},
    {"id":"2803-S-003","soru":"2803 sayılı Kanun'a göre Jandarma Genel Komutanlığı hangi makama bağlıdır?","siklar":["Genelkurmay Başkanlığına","İçişleri Bakanlığına","Milli Savunma Bakanlığına","Cumhurbaşkanlığına","Adalet Bakanlığına"],"dogru":1,"aciklama":"Madde 4: 'Jandarma Genel Komutanlığı İçişleri Bakanlığına bağlıdır.'","kaynak":"2803 m.4","zorluk":"kolay"},
    {"id":"2803-S-004","soru":"2803 sayılı Kanun'a göre, geçici olarak birden çok ili içine alan bölge teşkilatı kurulması halinde bölge komutanı, bölge teşkilatının konuşlu bulunduğu yerle ilgili olarak kime karşı sorumlu olarak görev yapar?","siklar":["Garnizon komutanına","İçişleri Bakanına","Jandarma Genel Komutanına","Genelkurmay Başkanına","Bölge teşkilatının konuşlu bulunduğu ilin valisine"],"dogru":4,"aciklama":"Madde 5: 'Bölge komutanı, bölge teşkilatının konuşlu bulunduğu ilin valisine karşı sorumlu olarak görev yapar.'","kaynak":"2803 m.5","zorluk":"orta"},
    {"id":"2803-S-005","soru":"2803 sayılı Kanun'a göre Jandarma birliklerinin kuruluş ve konuşlarının düzenlenmesinde kural olarak ne esas alınır?","siklar":["Coğrafi konum","Nüfus yoğunluğu","Askeri taksimat","Suç oranları","Mülki taksimat"],"dogru":4,"aciklama":"Madde 5: 'Jandarma birliklerinin kuruluş ve konuşlarının düzenlenmesinde mülki taksimat esas alınır.' Geçici olarak birden çok ili içine alan bölge teşkilatı da kurulabilir.","kaynak":"2803 m.5","zorluk":"orta"},
    {"id":"2803-S-006","soru":"2803 sayılı Kanun'un 7. maddesine göre jandarmanın genel görevleri arasında aşağıdakilerden hangisi yer almaz?","siklar":["Emniyet ve asayiş ile kamu düzenini sağlamak, korumak ve kollamak","Kaçakçılığı men, takip ve tahkik etmek","Ceza infaz kurumları ve tutukevlerinin iç güvenliğini sağlamak","İşlenmiş suçlarla ilgili olarak kanunlarda belirtilen adli işlemleri yapmak","Kanunlarla ve Cumhurbaşkanlığı kararnameleriyle verilen askeri hizmetleri yerine getirmek"],"dogru":2,"aciklama":"Madde 7/a jandarmaya ceza infaz kurumları ve tutukevlerinin yalnızca 'DIŞ korunmalarını' yapma görevi verir; iç güvenlik jandarmanın görevi değildir.","kaynak":"2803 m.7","zorluk":"orta"},
    {"id":"2803-S-007","soru":"2803 sayılı Kanun'a göre Jandarma birlikleri; seferberlik ve savaş hallerinde, hangi makamın kararıyla belirlenecek bölümleriyle Kuvvet Komutanlıkları emrine girer?","siklar":["İçişleri Bakanı onayıyla","Cumhurbaşkanı kararıyla","Bakanlar Kurulu kararıyla","Genelkurmay Başkanlığı kararıyla","Milli Savunma Bakanı onayıyla"],"dogru":1,"aciklama":"Madde 8: Jandarma birlikleri seferberlik ve savaş hallerinde 'Cumhurbaşkanı kararıyla' belirlenecek bölümleriyle Kuvvet Komutanlıkları emrine girer, kalan bölümüyle normal görevine devam eder.","kaynak":"2803 m.8","zorluk":"orta"},
    {"id":"2803-S-008","soru":"2803 sayılı Kanun'a göre jandarmanın silah kullanma yetkisi ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Jandarma her durumda ve sınırsız olarak silah kullanma yetkisine sahiptir.","Jandarma, kendisine verilen görevlerin ifası sırasında hizmet özelliğine uygun ve görevin gereği olarak kanunlarda öngörülen silah kullanma yetkisine sahiptir.","Jandarma silah kullanma yetkisini ancak ilgili valinin yazılı izniyle kullanabilir.","Jandarmanın silah kullanma yetkisi yalnızca seferberlik ve savaş hâlinde doğar.","Jandarmanın silah kullanma yetkisi Genelkurmay Başkanlığının emrine bağlıdır."],"dogru":1,"aciklama":"Madde 11: 'Jandarma, kendisine verilen görevlerin ifası sırasında hizmet özelliğine uygun ve görevin gereği olarak kanunlarda öngörülen silah kullanma yetkisine sahiptir.' Yetki sınırsız değil, kanunla ve görevle sınırlıdır.","kaynak":"2803 m.11","zorluk":"orta"},
    {"id":"2803-S-009","soru":"2803 sayılı Kanun'a göre büyükşehir, il veya ilçe belediyesi kurulması, kaldırılması ya da kentleşme veya diğer sebeplerle sınırlarda değişiklik olması halinde, değişikliğin yürürlüğe girdiği tarihten itibaren en geç ______ içerisinde sorumluluk alanları yeniden düzenlenir.","siklar":["bir ay","iki ay","üç ay","altı ay","bir yıl"],"dogru":2,"aciklama":"Madde 10: Sınır değişikliğinde sorumluluk alanları en geç 'üç ay' içerisinde yeniden düzenlenir.","kaynak":"2803 m.10","zorluk":"orta"},
    {"id":"2803-S-010","soru":"2803 sayılı Kanun'a göre kanun ve nizamlar ile bunlara dayalı olarak verilen emir ve kararların öngörmediği hiçbir görev jandarmadan istenemez. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Madde 9: İfade birebir doğrudur; jandarmaya yalnızca mevzuata dayalı görev verilebilir.","kaynak":"2803 m.9","zorluk":"kolay"},
    {"id":"2803-S-011","soru":"2803 sayılı Kanun'a göre rütbelerindeki bekleme süresinin dolması ya da kadrosuzluk nedenleriyle emekliliğe sevk edilme durumunda olan, ancak hizmetlerine ihtiyaç duyulan albaylar ve generaller İçişleri Bakanının onayıyla en fazla kaç yaşına kadar görevde bırakılabilir?","siklar":["Albaylar 55, generaller 60 yaşına kadar","Albaylar 60, generaller 60 yaşına kadar","Albaylar 65, generaller 60 yaşına kadar","Albaylar 65, generaller 67 yaşına kadar","Albaylar 60, generaller 65 yaşına kadar"],"dogru":4,"aciklama":"Madde 13: Hizmetine ihtiyaç duyulan albaylar 60 yaşına, generaller ise 65 yaşına kadar İçişleri Bakanının onayıyla görevde bırakılabilir.","kaynak":"2803 m.13","zorluk":"zor"},
    {"id":"2803-S-012","soru":"2803 sayılı Kanun'a göre lüzum görüldüğü hallerde Emniyet Genel Müdürlüğü, Sahil Güvenlik Komutanlığı ve Jandarma Genel Komutanlığı arasında her kademedeki personeli geçici olarak görevlendirme yetkisi kime aittir?","siklar":["İçişleri Bakanına","Cumhurbaşkanına","Jandarma Genel Komutanına","Genelkurmay Başkanına","İlgili il valisine"],"dogru":0,"aciklama":"Madde 12: Bu görevlendirmeyi İçişleri Bakanı yapar ve bu yetkisini il valilerine devredebilir.","kaynak":"2803 m.12","zorluk":"orta"},
    {"id":"2803-S-013","soru":"2803 sayılı Kanun'un 13/A maddesine göre en az dört yıl süreli fakülte bitirenlerden muvazzaf subay olmak için başvuranlar, düzeltilmemiş nüfus kaydına göre müracaat yapılan yılın ocak ayının ilk günü itibarıyla ______ yaşını bitirmemiş olmalıdır.","siklar":["yirmi beş","yirmi altı","yirmi yedi","otuz","otuz iki"],"dogru":2,"aciklama":"Madde 13/A: Fakülte bitirip muvazzaf subay/astsubay başvuranlar için üst sınır 27, lisansüstü öğrenimi tamamlamış olanlar için 32 yaştır.","kaynak":"2803 m.13/A","zorluk":"orta"},
    {"id":"2803-S-014","soru":"2803 sayılı Kanun'a göre subay veya astsubay nasbedilmek üzere lisans/önlisans eğitimi yapanlardan disiplinsizlik nedeniyle ilişiği kesilenler, kendilerine yapılan öğretim masraflarının kaç katını kanuni faizi ile birlikte tazminat olarak öderler?","siklar":["Bir katını","İki katını","Üç katını","Dört katını","Beş katını"],"dogru":3,"aciklama":"Madde 13/A: Sağlık sebebi hariç öğrenciliği sona erdirilenler masrafların iki katını, disiplinsizlik nedeniyle ilişiği kesilenler ise dört katını öder.","kaynak":"2803 m.13/A","zorluk":"zor"},
    {"id":"2803-S-015","soru":"2803 sayılı Kanun'a göre jandarma personelinin adli görevlerinden doğan suçlarında, 5271 sayılı Ceza Muhakemesi Kanununun kaçıncı maddesinin beşinci fıkrası hükmü uygulanır?","siklar":["158","160","161","250","135"],"dogru":2,"aciklama":"Madde 15/c: Adli görevlerden doğan suçlarda 5271 sayılı Ceza Muhakemesi Kanununun '161 inci maddesinin beşinci fıkrası' hükmü uygulanır.","kaynak":"2803 m.15","zorluk":"zor"},
    {"id":"2803-S-016","soru":"2803 sayılı Kanun'a göre gecikmesinde sakınca bulunan hallerde birlik komutanının veya kurum amirinin yazılı emriyle yapılan erbaş ve er araması için verilen yazılı emir, en geç kaç saat içinde görevli hâkimin onayına sunulur?","siklar":["On iki saat","On sekiz saat","Yirmi dört saat","Kırk sekiz saat","Yetmiş iki saat"],"dogru":2,"aciklama":"Madde 15/A: Gecikmesinde sakınca bulunan hallerde yazılı emir 'yirmi dört saat içinde' görevli hâkimin onayına sunulur.","kaynak":"2803 m.15/A","zorluk":"orta"},
    {"id":"2803-S-017","soru":"2803 sayılı Kanun'a göre erbaş ve er araması kapsamında konutta, yerleşim yerinde ve eklentilerinde önleme araması yapılabilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Madde 15/A: 'Konutta ve yerleşim yerinde ve eklentilerinde önleme araması YAPILAMAZ.' Kanun konut ve eklentilerinde önleme aramasını açıkça yasakladığından ifade yanlıştır.","kaynak":"2803 m.15/A","zorluk":"orta"},
    {"id":"2803-S-018","soru":"2803 sayılı Kanun'a göre nokta ataması yapılmayan subay, astsubay ve uzman jandarmalar kimin emrine atanır?","siklar":["İçişleri Bakanlığı emrine","Jandarma Genel Komutanlığı emrine","Bölge jandarma komutanlığı emrine","Garnizon komutanlığı emrine","Valilik emrine"],"dogru":4,"aciklama":"Madde 14: Nokta ataması yapılmayan subay, astsubay ve uzman jandarmalar 'valilik emrine' atanır; il içi yer değiştirmeleri vali tarafından yapılır.","kaynak":"2803 m.14","zorluk":"orta"},
    {"id":"2803-S-019","soru":"2803 sayılı Kanun'a göre Jandarma Genel Komutanlığının bütçesi, İçişleri Bakanlığının bünyesinde ve bu Bakanlığın bütçesiyle birlikte (aynı bütçe içinde) düzenlenir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Madde 18: Bütçe İçişleri Bakanlığının 'bünyesinde' düzenlenir; ancak bu Bakanlığın bütçesinden 'AYRI' olarak düzenlenir, birlikte/aynı bütçe içinde değil. Bu nedenle ifade yanlıştır.","kaynak":"2803 m.18","zorluk":"kolay"},
    {"id":"2803-S-020","soru":"2803 sayılı Kanun'a göre jandarmanın teşkilat, görev, yetki ve sorumlulukları, komuta ve kontrol ilişkileri ile personelin terfi, değerlendirme, kılık ve kıyafet işleri ve Kanunun uygulanmasına ilişkin diğer hususlar kim tarafından yürürlüğe konulan yönetmelikle düzenlenir?","siklar":["İçişleri Bakanlığınca","Cumhurbaşkanınca","Bakanlar Kurulunca","Genelkurmay Başkanlığınca","Jandarma Genel Komutanlığınca"],"dogru":1,"aciklama":"Madde 24: Bu hususlar 'Cumhurbaşkanınca yürürlüğe konulan yönetmelikle' düzenlenir.","kaynak":"2803 m.24","zorluk":"orta"},
    {"id":"2803-S-021","soru":"2803 sayılı Kanun'a göre komando ve sınır birliklerinde görevli personele, en yüksek Devlet memuru aylığının (ek gösterge dahil) en çok yüzde kaçı tutarında asayiş tazminatı ödenir?","siklar":["% 40","% 45","% 50","% 52","% 60"],"dogru":3,"aciklama":"Madde 21/a: Komando ve sınır birliklerinde % 52; diğer karargah, birlik ve kurumlarda % 40 oranını geçmemek üzere ödenir.","kaynak":"2803 m.21","zorluk":"orta"},
    {"id":"2803-S-022","soru":"2803 sayılı Kanun'a göre asayiş tazminatı ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","siklar":["Komando ve sınır birliklerinde % 52 oranını geçmemek üzere ödenir.","Diğer karargah, birlik ve kurumlarda % 40 oranını geçmemek üzere ödenir.","Tazminatın hesabında en yüksek Devlet memuru aylığı (ek gösterge dahil) esas alınır.","Usul ve esaslar İçişleri Bakanlığınca belirlenir.","Bu tazminattan damga vergisi dahil her türlü vergi ve kesinti yapılır."],"dogru":4,"aciklama":"Madde 21: 'Bu tazminattan damga vergisi hariç herhangi bir vergi ve kesinti yapılmaz.' Sahte şıkta tam tersi söylenmiştir.","kaynak":"2803 m.21","zorluk":"orta"},
    {"id":"2803-S-023","soru":"2803 sayılı Kanun'a göre il jandarma komutanı ile merkez ilçe jandarma komutanı hakkında her yıl sonunda görevleriyle ilgili değerlendirme raporunu kim düzenler?","siklar":["Kaymakam","İçişleri Bakanı","İl valisi","Bölge jandarma komutanı","Jandarma Genel Komutanı"],"dogru":2,"aciklama":"Ek Madde 2: İl jandarma komutanı ile merkez ilçe jandarma komutanı hakkında 'il valisince', ilçe jandarma komutanı hakkında ise kaymakamın değerlendirmesi alınarak yine il valisi tarafından rapor düzenlenir.","kaynak":"2803 Ek m.2","zorluk":"orta"},
    {"id":"2803-S-024","soru":"2803 sayılı Kanun'a göre İçişleri Bakanı, bu Kanundaki yetkilerinden bir kısmını gerektiğinde sınırlarını yazılı olarak açıkça belirlemek şartıyla ilgisine göre kime devredebilir?","siklar":["Kaymakamlara","Bölge jandarma komutanlarına","Garnizon komutanlarına","Jandarma Genel Komutan yardımcılarına","Jandarma Genel Komutanına veya valilere"],"dogru":4,"aciklama":"Ek Madde 6: Yetki devri 'ilgisine göre Jandarma Genel Komutanına veya valilere' yapılabilir ve sınırları yazılı olarak açıkça belirlenir.","kaynak":"2803 Ek m.6","zorluk":"orta"},
    {"id":"2803-S-025","soru":"2803 sayılı Kanun'un Ek 5. maddesine göre önleyici amaçla yapılan iletişimin tespitinde, gecikmesinde sakınca bulunan hallerde verilen yazılı emir yirmi dört saat içinde hâkim onayına sunulur. Hâkim kararını en geç kaç saat içinde verir?","siklar":["Yirmi dört saat","Kırk sekiz saat","Otuz altı saat","Yetmiş iki saat","On iki saat"],"dogru":1,"aciklama":"Ek Madde 5: Yazılı emir 24 saat içinde hâkim onayına sunulur, hâkim kararını en geç 'kırk sekiz saat içinde' verir.","kaynak":"2803 Ek m.5","zorluk":"zor"},
    {"id":"2803-S-026","soru":"2803 sayılı Kanun'un Ek 5. maddesine göre önleyici dinleme kararları en fazla üç ay için verilebilir. Bu süre, terör örgütü faaliyeti dışındaki hallerde aynı usulle üçer ayı geçmeyecek şekilde en fazla kaç defa uzatılabilir?","siklar":["Bir defa","İki defa","Üç defa","Dört defa","Beş defa"],"dogru":2,"aciklama":"Ek Madde 5: Kararlar en fazla üç ay için verilir; üçer ayı geçmeyecek şekilde en fazla 'üç defa' uzatılabilir. Terör örgütü faaliyetinde ise hâkim üç aydan fazla olmamak üzere müteaddit defalar uzatabilir.","kaynak":"2803 Ek m.5","zorluk":"zor"},
    {"id":"2803-S-027","soru":"2803 sayılı Kanun'un Ek 5. maddesine göre önleyici dinlemede yetkili ve görevli hâkim, İstanbul ağır ceza mahkemesi üyesidir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek Madde 5 (Değişik ikinci fıkra): 'Yetkili ve görevli hâkim, ANKARA ağır ceza mahkemesi üyesidir.' Yetki İstanbul'a değil Ankara ağır ceza mahkemesi üyesine verildiğinden ifade yanlıştır.","kaynak":"2803 Ek m.5","zorluk":"orta"},
    {"id":"2803-S-028","soru":"2803 sayılı Kanun'un Ek 3. maddesine göre personelin her yıl kaç gün yıllık izin hakkı vardır (bu müddete yol dahil değildir)?","siklar":["Yirmi gün","Otuz gün","On beş gün","Kırk beş gün","Altmış gün"],"dogru":1,"aciklama":"Ek Madde 3/1-a: Personelin her yıl 30 gün yıllık izin hakkı vardır; ayrıca kısa süreli mazeretler için 15 güne kadar yıllık mazeret izni verilebilir.","kaynak":"2803 Ek m.3","zorluk":"kolay"},
    {"id":"2803-S-029","soru":"2803 sayılı Kanun'un Ek 3. maddesine göre mazeret izinleri ile ilgili olarak aşağıda verilen bilgilerden hangisi yanlıştır?","siklar":["Eşinin ölümü, çocuğunun ölümü, kendisinin veya eşinin ana, baba veya kardeşinin ölümü hallerinin her birinde isteği üzerine on güne kadar mazeret izni verilebilir.","Eşinin doğum yapması halinde isteği üzerine on güne kadar mazeret izni verilebilir.","Kendisinin veya çocuğunun evlenmesi halinde isteği üzerine on güne kadar mazeret izni verilebilir.","Yangın, deprem, su baskını gibi olağanüstü bir mazeret dolayısıyla bir yıl içinde otuz güne kadar mazeret izni verilebilir.","Hizmetleri sırasında radyoaktif ışınlarla çalışan personele her yıl, yıllık izinlerinden ayrı olarak bir aylık izin verilir."],"dogru":2,"aciklama":"Ek Madde 3/2-a: Kendisinin veya çocuğunun evlenmesi halinde isteği üzerine 'yedi güne kadar' mazeret izni verilir; on gün değildir.","kaynak":"2803 Ek m.3","zorluk":"zor"},
    {"id":"2803-S-030","soru":"2803 sayılı Kanun'un Ek 3. maddesine göre kadın personele doğum yapmasından önce sekiz hafta ve doğum yaptığı tarihten itibaren on altı hafta olmak üzere toplam ______ hafta süre ile aylıklı izin verilir.","siklar":["on altı","on sekiz","yirmi","yirmi dört","yirmi altı"],"dogru":3,"aciklama":"Ek Madde 3/3-ç: Doğum öncesi 8 hafta + doğum sonrası 16 hafta = toplam 24 hafta aylıklı izin verilir; çoğul gebelikte doğum öncesine 2 hafta eklenir.","kaynak":"2803 Ek m.3","zorluk":"orta"},
    {"id":"2803-S-031","soru":"2803 sayılı Kanun'un Ek 9. maddesine göre olağanüstü durumlarda yaşamını ortaya koyarak büyük yararlıklar gösteren Jandarma Genel Komutanlığı personeline, fiilen almakta oldukları aylık tutarlarının kaç katından kaç katına kadar para verilerek ödüllendirilir?","siklar":["İki katından beş katına kadar","Altı katından yirmi dört katına kadar","Beş katından on katına kadar","Üç katından on iki katına kadar","On katından yirmi katına kadar"],"dogru":1,"aciklama":"Ek Madde 9/b: Olağanüstü durumlarda yaşamını ortaya koyarak büyük yararlık gösterenlere aylık tutarının altı katından yirmi dört katına kadar para verilir. (a) bendindeki yüksek hizmet için ise iki katından beş katına kadardır.","kaynak":"2803 Ek m.9","zorluk":"zor"},
    {"id":"2803-S-032","soru":"2803 sayılı Kanun'un Ek 9. maddesine göre görevlerini cesaret, feragat, kahramanlık veya üstün başarı ile yerine getirenlere İçişleri Bakanı tarafından verilebilecek madalyalar arasında aşağıdakilerden hangisi yer almaz?","siklar":["Jandarma Üstün Cesaret ve Feragat Madalyası","Jandarma Şeref Madalyası","Jandarma Üstün Hizmet Madalyası","Jandarma Üstün Başarı Madalyası","(Yukarıdakilerin tamamı kanunda sayılmıştır)"],"dogru":3,"aciklama":"Ek Madde 9: Sayılan üç madalya; Üstün Cesaret ve Feragat, Şeref ve Üstün Hizmet madalyalarıdır. 'Jandarma Üstün Başarı Madalyası' kanunda yer almaz.","kaynak":"2803 Ek m.9","zorluk":"orta"},
    {"id":"2803-S-033","soru":"2803 sayılı Kanun'un Ek 8. maddesine göre özel, yerel ve kış eğitim merkezleri ile birlik dışındaki kantinlerin aylık gayrisafi hasılatının yüzde kaçı her ay genel bütçeye gelir kaydedilmek üzere ilgili muhasebe birimine yatırılır?","siklar":["% 1","% 2","% 5","% 10","% 15"],"dogru":0,"aciklama":"Ek Madde 8: Özel, yerel ve kış eğitim merkezleri ile birlik dışındaki kantinlerin aylık gayrisafi hasılatının '% 1'i her ay genel bütçeye gelir kaydedilir.","kaynak":"2803 Ek m.8","zorluk":"zor"},
    {"id":"2803-S-034","soru":"2803 sayılı Kanun'un Ek 13. maddesine göre muvazzaf askerlik yükümlülüğüne başlamadan uzman erbaşlığa kabul edilenlerle beş yıllık sözleşme yapılır. Bu kişiler Jandarma Genel Komutanlığında kaç yıllık hizmet süresini tamamladıklarında askerlik hizmetini yerine getirmiş sayılır?","siklar":["İki yıl","Beş yıl","Üç yıl","Dört yıl","Bir yıl"],"dogru":2,"aciklama":"Ek Madde 13: Beş yıllık sözleşme yapılır; üç yıllık hizmet süresini tamamlayanlar askerlik hizmetini yerine getirmiş sayılır. Bu üç yıllık süre fiilen göreve başlanılan tarihte başlar.","kaynak":"2803 Ek m.13","zorluk":"orta"},
    {"id":"2803-S-035","soru":"2803 sayılı Kanun'un Ek 14. maddesine göre Jandarma Genel Komutanlığında muvazzaf subay veya astsubay olanların mecburi hizmetleri, nasbedildikleri tarihten itibaren fiilen kaç yıldır?","siklar":["On yıl","On iki yıl","Yirmi yıl","On beş yıl","On sekiz yıl"],"dogru":3,"aciklama":"Ek Madde 14/a: Muvazzaf subay veya astsubayların mecburi hizmetleri, nasbedildikleri tarihten itibaren fiilen 15 yıldır. (Pilotaj eğitimi bitirenlerde 6 yıl uzar, vb.)","kaynak":"2803 Ek m.14","zorluk":"orta"},
    {"id":"2803-S-036","soru":"2803 sayılı Kanun'un Geçici 5. maddesine göre Jandarma Genel Komutanlığının er ve erbaş ile askerlik yükümlüsü ihtiyacı, 1111 sayılı Askerlik Kanunu hükümleri çerçevesinde Milli Savunma Bakanlığı tarafından kaç yıl süreyle karşılanır (Cumhurbaşkanı kararıyla uzatılabilir)?","siklar":["Üç yıl","İki yıl","Beş yıl","Dört yıl","Süresiz"],"dogru":0,"aciklama":"Geçici Madde 5: İhtiyaç, Milli Savunma Bakanlığı tarafından 'üç yıl süreyle' karşılanır; ancak Cumhurbaşkanı kararıyla bu süre uzatılabilir.","kaynak":"2803 Geçici m.5","zorluk":"orta"},
    {"id":"2803-S-037","soru":"2803 sayılı Kanun'un Geçici 4. maddesine göre, disiplin işlerine ilişkin özel kanun çıkarılana kadar jandarma personelinin disiplin suç ve cezaları hangi mevzuata göre belirlenir?","siklar":["657 sayılı Devlet Memurları Kanunu","926 sayılı Türk Silahlı Kuvvetleri Personel Kanunu","4483 sayılı Kanun","Emniyet Teşkilatı disiplin mevzuatı","Türk Silahlı Kuvvetleri İç Hizmet Kanunu"],"dogru":3,"aciklama":"Geçici Madde 4/a: Disiplin işlerine ilişkin özel kanun çıkarılana kadar jandarma personelinin disiplin suç ve cezaları 'Emniyet Teşkilatı disiplin mevzuatına' göre belirlenir; diğer hususlarda 657 sayılı Devlet Memurları Kanunu hükümleri uygulanır.","kaynak":"2803 Geçici m.4","zorluk":"orta"},
    {"id":"2803-S-038","soru":"2803 sayılı Kanun'un Ek 16. maddesine göre uzman jandarmalıktan astsubaylığa geçenlerden astsubay kıdemli başçavuşların rütbe yaş haddi kaçtır?","siklar":["43","52","54","55","60"],"dogru":3,"aciklama":"Ek Madde 16: Uzman jandarmalıktan astsubaylığa geçenlerin yaş hadleri; çavuş/kıdemli çavuş 43, üstçavuş/kıdemli üstçavuş 52, başçavuş 54, kıdemli başçavuş 55'tir. Kıdemli başçavuş için yaş haddi 55'tir.","kaynak":"2803 Ek m.16","zorluk":"zor"},
    {"id":"2803-OO-001","soru":"Jandarma astsubayı A, hafta sonu izinli olduğu bir gün, görevle hiçbir ilgisi bulunmayan bir komşuluk anlaşmazlığı nedeniyle komşusu B'yi kasten yaralar. A'nın bu fiilinden dolayı hakkında nasıl işlem yapılır?","siklar":["4483 sayılı Kanun (memurlar ve diğer kamu görevlilerinin yargılanması) hükümlerine göre","5271 sayılı CMK'nın 161'inci maddesinin beşinci fıkrası hükmüne göre","Genel hükümlere göre","Emrine verildiği askeri birliği muhakemeye yetkili mahkemede","Yalnızca disiplin mevzuatına göre"],"dogru":2,"aciklama":"Madde 15/e: 'Jandarma personelinin kişisel suçlarında genel hükümlere göre işlem yapılır.' Olaydaki yaralama görevden doğmayan kişisel bir suç olduğundan izin/onay (4483) veya savcı yetkisi (CMK 161/5) usulleri değil, genel hükümler uygulanır.","kaynak":"2803 m.15","zorluk":"orta"},
    {"id":"2803-OO-002","soru":"Jandarma personeli A, sorumluluk alanındaki bir kasabada asayiş (mülki) görevini yürütürken, bu görevinden doğan bir suç işlediği iddia edilir. Özel kanun hükümleri saklı kalmak şartıyla, A hakkında hangi mevzuata göre işlem yapılır?","siklar":["2/12/1999 tarihli ve 4483 sayılı Memurların ve Diğer Kamu Görevlilerinin Yargılanması Hakkında Kanun","5271 sayılı CMK'nın 161'inci maddesinin beşinci fıkrası","Genel hükümler","7068 sayılı Genel Kolluk Disiplin Hükümleri Kanunu","926 sayılı Türk Silahlı Kuvvetleri Personel Kanunu"],"dogru":0,"aciklama":"Madde 15/b: 'Jandarma personelinin mülki görevlerinden doğan suçlarında; özel kanunların hükümleri saklı kalmak şartıyla 4483 sayılı Kanun hükümlerine göre işlem yapılır.'","kaynak":"2803 m.15","zorluk":"orta"},
    {"id":"2803-OO-003","soru":"Jandarma personeli A'ya usulüne uygun olarak askeri bir görev verilir ve A bir askeri birliğin emrine verilir. A, bu askeri görevinden doğan bir suç işler. A'nın bu suçunun muhakemesi nerede görülür?","siklar":["A'nın asıl bağlı olduğu il jandarma komutanlığının bulunduğu yer mahkemesinde","Genel hükümlere göre suçun işlendiği yer asliye ceza mahkemesinde","A'nın emrine verildiği askeri birlik personelini muhakeme etmekle görevli ve yetkili olan mahkemede","Ankara ağır ceza mahkemesinde","İçişleri Bakanlığının onayı alınarak idari yargıda"],"dogru":2,"aciklama":"Madde 15/d: 'Jandarma personeline askeri görev verildiği takdirde bu görevlerden doğan suçların muhakemesi, Jandarma personelinin emrine verildiği askeri birlik personelini muhakeme etmekle görevli ve yetkili olan mahkemede görülür.'","kaynak":"2803 m.15","zorluk":"zor"},
    {"id":"2803-OO-004","soru":"Bir jandarma hizmet binasında, askerlik yükümlülüğünü yerine getiren er B'nin üstünde ve eşyasında suç delili bulunduğuna dair makul sebepler oluşur. Ancak durum gecikmesinde sakınca bulunan bir hâl arz etmekte ve önceden alınmış bir sulh ceza hâkimi kararı bulunmamaktadır. Bu durumda erin üstü ve eşyasının aranması için yazılı emri kim verebilir?","siklar":["Bölgenin valisi","Cumhuriyet savcısı","Birlik komutanı veya kurum amiri","Jandarma Genel Komutanı","İl jandarma komutanlığının bağlı olduğu kaymakam"],"dogru":2,"aciklama":"Madde 15/A: Gecikmesinde sakınca bulunan hâllerde, yirmi dört saat içinde görevli hâkimin onayına sunulması şartıyla 'birlik komutanının veya kurum amirinin yazılı emri üzerine' erbaş ve erlerin üstü, özel kâğıtları ve eşyası aranır.","kaynak":"2803 m.15/A","zorluk":"orta"},
    {"id":"2803-OO-005","soru":"Sorumluluk alanında bir hırsızlık olayı meydana geldikten sonra jandarma; olay yerini koruma altına alır, suç delillerini toplar, faili yakalar ve kanunlarda belirtilen işlemleri yaparak dosyayı Cumhuriyet savcısına intikal ettirir. Jandarmanın bu faaliyeti 2803 sayılı Kanun'a göre hangi görev grubuna girer?","siklar":["Mülki görev","Adli görev","Askeri görev","Önleyici (idari) görev","Koruyucu istihbarat görevi"],"dogru":1,"aciklama":"Madde 7/b: Adli görevler, 'işlenmiş suçlarla ilgili olarak kanunlarda belirtilen işlemleri yapmak ve bunlara ilişkin adli hizmetleri yerine getirmektir.' Olayda suç işlendikten sonra delil toplama ve faili adli mercie sevk söz konusu olduğundan bu bir ADLİ görevdir.","kaynak":"2803 m.7","zorluk":"orta"},
    {"id":"2803-OO-006","soru":"Barış döneminde bir ilde, garnizon komutanı, o ildeki jandarma birliğinin belirli bir askeri görevi de yerine getirmesini talep eder. Bu talep üzerine jandarma birliğine söz konusu askeri görevin verilebilmesi için kimin onayı gerekir?","siklar":["İçişleri Bakanının","Genelkurmay Başkanının","Jandarma Genel Komutanının","İlin valisinin","Cumhurbaşkanının"],"dogru":3,"aciklama":"Madde 8/2: Jandarma birlikleri, Genelkurmay Başkanlığının talebi üzerine İçişleri Bakanının, 'illerde ise garnizon komutanının talep etmesi halinde valinin onayıyla' kendilerine verilen askeri görevleri de yaparlar.","kaynak":"2803 m.8","zorluk":"orta"},
    {"id":"2803-OO-007","soru":"Bir ilçede Emniyet Teşkilatı, kendi sorumluluk sahasında geçici olarak yetersiz kalacağının değerlendirilmesi üzerine, jandarmanın geçici olarak emniyet sorumluluk sahasında görevlendirilmesine ihtiyaç duyulur. Bu geçici görevlendirme kim tarafından yapılabilir?","siklar":["Jandarma Genel Komutanı tarafından","Emniyet Genel Müdürü tarafından","Mahalli mülki amirler tarafından","İçişleri Bakanı tarafından","Cumhurbaşkanı tarafından"],"dogru":2,"aciklama":"Madde 10: 'Jandarma veya Emniyet Teşkilatı, kendi sorumluluk sahasında yetersiz kaldıkları veya kalacaklarının değerlendirilmesi halinde, mahalli mülki amirler tarafından birbirlerinin sorumluluk sahalarında geçici olarak görevlendirilebilirler.'","kaynak":"2803 m.10","zorluk":"orta"},
    {"id":"2803-OO-008","soru":"Jandarma, sorumluluk alanında Ek 5. madde kapsamındaki bir suçun işlenmesini önlemek amacıyla iletişimin tespiti ve dinlenmesi tedbirine başvurmak ister. Ancak hâkim kararı almaya zaman bulunmayan, gecikmesinde sakınca bulunan bir hâl vardır. Bu durumda tedbirin uygulanması için yazılı emri kim verebilir?","siklar":["Ankara ağır ceza mahkemesi üyesi","Görev yapılan ilin valisi","Cumhuriyet başsavcısı","Jandarma Genel Komutanı veya istihbarat başkanı","İçişleri Bakanı"],"dogru":3,"aciklama":"Ek Madde 5: Gecikmesinde sakınca bulunan hâllerde 'Jandarma Genel Komutanı veya istihbarat başkanının yazılı emriyle' iletişim tespit edilebilir, dinlenebilir; bu emir 24 saat içinde hâkim onayına sunulur.","kaynak":"2803 Ek m.5","zorluk":"zor"},
    {"id":"2803-OO-009","soru":"Jandarma astsubayı A, kendisi evleneceği için mazeret izni talep eder. 2803 sayılı Kanun'un Ek 3. maddesine göre A'ya isteği üzerine en çok kaç güne kadar mazeret izni verilebilir?","siklar":["Beş güne kadar","Yedi güne kadar","On güne kadar","On beş güne kadar","Üç güne kadar"],"dogru":1,"aciklama":"Ek Madde 3/2-a: Kendisinin veya çocuğunun evlenmesi halinde isteği üzerine 'yedi güne kadar' mazeret izni verilebilir. (Ölüm ve eşin doğumu hallerinde ise on güne kadar verilir.)","kaynak":"2803 Ek m.3","zorluk":"orta"},
    {"id":"2803-OO-010","soru":"Jandarma Genel Komutanlığında muvazzaf astsubay olan A, on beş yıllık mecburi hizmet süresi dolmadan, 7068 sayılı Genel Kolluk Disiplin Hükümleri Hakkında Kanun kapsamında meslekten çıkarılır. A, kendisine yapılan öğrenim, eğitim ve yetiştirme masraflarının kaç katını (eksik kalan yükümlülük süresiyle orantılı ve kanuni faizi ile) tazminat olarak öder?","siklar":["Bir katını","İki katını","Üç katını","Dört katını","Beş katını"],"dogru":3,"aciklama":"Ek Madde 14: Mecburi hizmet süresi içinde istifa eden veya sağlık dışı sebeple ilişiği kesilenler masrafların iki katını; 15'inci madde kapsamında ilişiği kesilenler ile 7068 sayılı Kanun kapsamında meslekten veya Devlet memurluğundan çıkarılanlar ise 'dört katını' yükümlülük süresinin eksik kalan kısmı ile orantılı olarak öderler.","kaynak":"2803 Ek m.14","zorluk":"zor"},
    {"id":"2803-OO-011","soru":"Muvazzaf askerlik yükümlülüğüne başlamadan Jandarma Genel Komutanlığında uzman erbaşlığa kabul edilen ve beş yıllık sözleşme yapan A, fiilen göreve başladıktan iki yıl sonra ilişiği kesilir. A'nın askerlik durumu ne olur?","siklar":["Beş yıllık sözleşmeyi imzaladığı için askerlik hizmetini yerine getirmiş sayılır.","Üç yıllık hizmet süresini tamamlamadığından askerlik hizmetini yerine getirir.","İki yıl görev yaptığı için askerliği yapmış sayılır.","Askerliğinin yarısını yapmış sayılır, kalanı tecil edilir.","Cumhurbaşkanı kararıyla askerlikten muaf tutulur."],"dogru":1,"aciklama":"Ek Madde 13: Bu kapsamdakilerden üç yıllık hizmet süresini tamamlayanlar askerlik hizmetini yerine getirmiş sayılır; ancak 'üç yıllık süreyi tamamlamadan hangi nedenle olursa olsun ilişiği kesilen personel askerlik hizmetini yerine getirir.' A iki yılda ayrıldığından askerliğini yapar.","kaynak":"2803 Ek m.13","zorluk":"orta"},
    {"id":"2803-OO-012","soru":"Jandarma ve Sahil Güvenlik Akademisinde subay nasbedilmek üzere lisans eğitimi gören öğrenci A'nın, sağlık kurulu raporuna dayalı olarak Akademide öğrenime devam imkânı kalmadığı belirlenir ve öğrenciliği sona erdirilir. A, kendisine yapılan öğretim masraflarına ilişkin nasıl bir tazminat öder?","siklar":["Masrafların iki katını kanuni faizi ile öder.","Masrafların dört katını kanuni faizi ile öder.","Sağlık sebebiyle ilişiği kesildiğinden bu öğretim masrafı tazminatını ödemez.","Masrafların bir katını faizsiz öder.","Masrafların üç katını öder."],"dogru":2,"aciklama":"Madde 13/A: Tazminat yükümlülüğü 'sağlık sebebi hariç' öğrenciliği sona erdirilenler (iki kat) ile disiplinsizlik nedeniyle ilişiği kesilenler (dört kat) için öngörülmüştür. Sağlık sebebiyle öğrenciliği sona erdirilen A, bu öğretim masrafı tazminatını ödemez.","kaynak":"2803 m.13/A","zorluk":"zor"},
  ],
  3: [
    {"id":"6698-S-001","soru":"6698 sayılı Kanun'a göre açık rıza; belirli bir konuya ilişkin, ______ dayanan ve özgür iradeyle açıklanan rızadır. Boşluğa gelmesi gereken ifade aşağıdakilerden hangisidir?","siklar":["yazılı beyana","bilgilendirilmeye","noter onayına","Kurul iznine","süresiz taahhüde"],"dogru":1,"aciklama":"m.3/1-a: Açık rıza, belirli bir konuya ilişkin, BİLGİLENDİRİLMEYE dayanan ve özgür iradeyle açıklanan rızadır. Üç unsur: belirli + bilgilendirilmeye dayanan + özgür irade. 'Yazılı olma' bir unsur değildir (sık tuzak).","kaynak":"6698 m.3/1-a","zorluk":"orta"},
    {"id":"6698-S-002","soru":"6698 sayılı Kanun'a göre 'kişisel veri' aşağıdakilerden hangisidir?","siklar":["Kimliği yalnızca belirli olan gerçek kişiye ilişkin bilgi","Kimliği belirli veya belirlenebilir gerçek kişiye ilişkin her türlü bilgi","Kimliği belirli veya belirlenebilir gerçek ve tüzel kişiye ilişkin her türlü bilgi","Yalnızca özel hayata ilişkin gizli bilgiler","Bir veri kayıt sisteminde tutulan her türlü kayıt"],"dogru":1,"aciklama":"m.3/1-d: Kişisel veri, kimliği belirli VEYA belirlenebilir GERÇEK kişiye ilişkin her türlü bilgidir.","kaynak":"6698 m.3/1-d","zorluk":"orta"},
    {"id":"6698-S-003","soru":"6698 sayılı Kanun'a göre anonim hâle getirme; kişisel verilerin, başka verilerle eşleştirilerek dahi hiçbir surette kimliği belirli veya belirlenebilir bir ______ ile ilişkilendirilemeyecek hâle getirilmesidir. Boşluğa ne gelmelidir?","siklar":["tüzel kişi","kuruluş","gerçek kişi","veri sorumlusu","kamu kurumu"],"dogru":2,"aciklama":"m.3/1-b: Anonim hâle getirmede ölçü, verinin hiçbir surette GERÇEK KİŞİ ile ilişkilendirilememesidir.","kaynak":"6698 m.3/1-b","zorluk":"orta"},
    {"id":"6698-S-004","soru":"6698 sayılı Kanun'a göre, kişisel verilerin işleme amaçlarını ve vasıtalarını belirleyen, veri kayıt sisteminin kurulmasından ve yönetilmesinden sorumlu olan kişi aşağıdakilerden hangisidir?","siklar":["Veri işleyen","İlgili kişi","İrtibat kişisi","Kişisel Verileri Koruma Kurulu","Veri sorumlusu"],"dogru":4,"aciklama":"m.3/1-ı: Amaç ve vasıtaları belirleyen, kayıt sistemini kuran/yöneten = VERİ SORUMLUSU. Veri işleyen (ğ) ise onun verdiği yetkiyle, onun adına işler.","kaynak":"6698 m.3/1-ı, ğ","zorluk":"kolay"},
    {"id":"6698-S-005","soru":"6698 sayılı Kanun'un 4. maddesine göre aşağıdakilerden hangisi kişisel verilerin işlenmesinde uyulması zorunlu genel ilkelerden biridir?","siklar":["Kişisel verilerin her durumda süresiz olarak saklanması","Veri işleme öncesinde her hâlde Kuruldan izin alınması","Tüm kişisel verilerin yalnızca yurt içinde yedeklenmesi","Her kaydın noter onayıyla tutulması","İşlendikleri amaçla bağlantılı, sınırlı ve ölçülü olma"],"dogru":4,"aciklama":"m.4/2'deki ilkeler: a) hukuka uygun+dürüst, b) doğru-güncel, c) belirli-açık-meşru amaç, ç) bağlantılı-sınırlı-ölçülü, d) süreli muhafaza. 'Bağlantılı, sınırlı ve ölçülü olma' (ç) bir genel ilkedir; süresiz saklama ise süreli muhafaza ilkesine aykırıdır.","kaynak":"6698 m.4/2","zorluk":"orta"},
    {"id":"6698-S-006","soru":"Doğru/Yanlış: 6698 sayılı Kanun'a göre kişisel veriler, ilgili mevzuatta öngörülen veya işlendikleri amaç için gerekli olan süreden bağımsız olarak süresiz saklanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.4/2-d: Veriler, ilgili mevzuatta öngörülen veya amaç için gerekli olan SÜRE KADAR muhafaza edilir. Süresiz saklama ilkeye aykırıdır.","kaynak":"6698 m.4/2-d","zorluk":"kolay"},
    {"id":"6698-S-007","soru":"Doğru/Yanlış: 6698 sayılı Kanun'a göre kural olarak kişisel veriler, ilgili kişinin açık rızası olmaksızın işlenemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5/1: Kişisel veriler ilgili kişinin açık rızası olmaksızın işlenemez (kural). m.5/2'deki sayılı hâllerde rıza aranmaz (istisna).","kaynak":"6698 m.5/1","zorluk":"kolay"},
    {"id":"6698-S-008","soru":"Aşağıdakilerden hangisi 6698 sayılı Kanun'a göre ilgili kişinin açık rızası ARANMAKSIZIN kişisel verilerinin işlenebileceği hâllerden biri DEĞİLDİR?","siklar":["Kanunlarda açıkça öngörülmesi","Veri sorumlusunun ticari kazancını artırması amacıyla gerekli olması","Bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması","Veri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması","İlgili kişinin kendisi tarafından alenileştirilmiş olması"],"dogru":1,"aciklama":"m.5/2 hâlleri: a) kanunda öngörülme, b) hayati tehlike/fiili imkânsızlık, c) sözleşme, ç) hukuki yükümlülük, d) alenileştirme, e) hak tesisi, f) meşru menfaat. 'Ticari kazancı artırma' bir hâl değildir; meşru menfaat ile karıştırılmamalıdır.","kaynak":"6698 m.5/2","zorluk":"zor"},
    {"id":"6698-S-009","soru":"6698 sayılı Kanun'un 5. maddesine göre, ilgili kişinin açık rızası aranmaksızın kişisel verilerin işlenebileceği hâllerin sayısı kaçtır?","siklar":["5","6","7","8","9"],"dogru":2,"aciklama":"m.5/2'de yedi (a, b, c, ç, d, e, f) hâl sayılır. DİKKAT: m.6/3'te özel nitelikli veriler için SEKİZ hâl vardır; ikisi karıştırılmamalıdır.","kaynak":"6698 m.5/2 ↔ m.6/3","zorluk":"zor"},
    {"id":"6698-S-010","soru":"6698 sayılı Kanun'un 6. maddesine göre aşağıdakilerden hangisi özel nitelikli kişisel veridir?","siklar":["Ev adresi","Araç plaka numarası","Doğum tarihi","Genetik veri","E-posta adresi"],"dogru":3,"aciklama":"m.6/1'e göre biyometrik ve genetik veriler özel nitelikli kişisel veridir. Ev adresi, araç plakası, doğum tarihi ve e-posta adresi sıradan kişisel veridir; özel nitelikli kategoride sayılmaz.","kaynak":"6698 m.6/1","zorluk":"orta"},
    {"id":"6698-S-011","soru":"6698 sayılı Kanun'a göre özel nitelikli kişisel verilerin işlenmesiyle ilgili aşağıdakilerden hangisi YANLIŞTIR?","siklar":["Yeterli önlem alınmışsa Kurul kararı olmaksızın her hâlde serbestçe işlenebilir.","Özel nitelikli kişisel verilerin işlenmesi kural olarak yasaktır.","Kanunda sayılan şartlardan birinin varlığı hâlinde işlenmesi mümkündür.","İşlenmesinde ayrıca Kurul tarafından belirlenen yeterli önlemlerin alınması şarttır.","İlgili kişinin açık rızasının bulunması işlenebileceği hâllerden biridir."],"dogru":0,"aciklama":"m.6/3: işlenmesi yasaktır, ancak sayılı sekiz hâlde mümkündür; m.6/4: ayrıca Kurulun belirlediği yeterli önlemler şarttır. Açık rıza (a) bu hâllerden biridir. 'Her hâlde serbestçe işlenebilir' ifadesi yanlıştır.","kaynak":"6698 m.6/3, m.6/4","zorluk":"zor"},
    {"id":"6698-S-012","soru":"6698 sayılı Kanun'un 6. maddesine göre özel nitelikli kişisel verilerin işlenebileceği sayılı hâllerin sayısı kaçtır?","siklar":["5","6","7","8","10"],"dogru":3,"aciklama":"2/3/2024-7499 ile değişik m.6/3'te sekiz hâl (a-g) sayılır. m.5/2'deki yedi hâl ile karıştırılmamalıdır.","kaynak":"6698 m.6/3","zorluk":"zor"},
    {"id":"6698-S-013","soru":"6698 sayılı Kanun'a göre işlenmesini gerektiren sebeplerin ortadan kalkması hâlinde kişisel veriler hangi işlemlere tabi tutulur?","siklar":["Silinir, yok edilir veya anonim hâle getirilir","Şifrelenir veya yedeklenir","Arşive kaldırılır ve süresiz saklanır","Yalnızca Kurula devredilir","Otomatik olarak üçüncü kişilere aktarılır"],"dogru":0,"aciklama":"m.7/1: Sebepler ortadan kalkınca veriler resen veya ilgili kişinin talebi üzerine veri sorumlusu tarafından SİLİNİR, YOK EDİLİR veya ANONİM HÂLE GETİRİLİR.","kaynak":"6698 m.7/1","zorluk":"orta"},
    {"id":"6698-S-014","soru":"Doğru/Yanlış: 6698 sayılı Kanun'a göre işlenmesini gerektiren sebepler ortadan kalktığında kişisel veriler yalnızca ilgili kişinin talebi üzerine silinebilir; veri sorumlusu kendiliğinden (resen) silemez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.7/1: Veriler RESEN veya ilgili kişinin TALEBİ üzerine silinir/yok edilir/anonimleştirilir. 'Yalnızca talep üzerine' ifadesi yanlıştır.","kaynak":"6698 m.7/1","zorluk":"orta"},
    {"id":"6698-S-015","soru":"6698 sayılı Kanun'a göre, kanunla görev ve yetki verilmiş kamu kurum ve kuruluşlarınca millî güvenliği sağlamaya yönelik yürütülen önleyici, koruyucu ve istihbari faaliyetler kapsamında işlenen kişisel veriler bakımından Kanun ne şekilde uygulanır?","siklar":["Kanun hükümlerinin tamamı eksiksiz uygulanır","Yalnızca veri güvenliğine ilişkin yükümlülükler uygulanmaz","Kanun hükümleri tamamen uygulanmaz (tam istisna)","Yalnızca aydınlatma, ilgili kişinin hakları ve sicile kayıt yükümlülükleri uygulanmaz (kısmî istisna)","Faaliyet ancak Kişisel Verileri Koruma Kurulu izniyle Kanun kapsamına girer"],"dogru":2,"aciklama":"m.28/1-(ç): millî savunmayı, millî güvenliği, kamu güvenliğini sağlamaya yönelik kanunla yetkili kamu kurumlarının önleyici, koruyucu ve istihbari faaliyetleri TAM istisnadır; bu hâlde Kanun hükümleri tamamen uygulanmaz. D şıkkı m.28/2 kısmî istisnasıdır (yalnız m.10-11-16 düşer) ve karıştırılmamalıdır.","kaynak":"6698 m.28/1-ç","zorluk":"zor"},
    {"id":"6698-S-016","soru":"6698 sayılı Kanun'un 28. maddesinin ikinci fıkrasındaki kısmî istisna hâllerinde, aşağıdaki yükümlülüklerden hangisi UYGULANMAYA DEVAM EDER?","siklar":["Aydınlatma yükümlülüğü (m.10)","İlgili kişinin haklarının tamamı (m.11)","Veri Sorumluları Siciline kayıt yükümlülüğü (m.16)","Hiçbiri; kısmî istisnada tüm yükümlülükler kalkar","Veri güvenliğine ilişkin yükümlülükler (m.12)"],"dogru":4,"aciklama":"m.28/2 yalnızca m.10 (aydınlatma), m.11 (haklar — zararın giderilmesini talep hariç) ve m.16 (sicil) yükümlülüklerini kaldırır. m.12 veri güvenliği bu fıkrada sayılmaz; AYAKTA kalır.","kaynak":"6698 m.28/2","zorluk":"zor"},
    {"id":"6698-S-017","soru":"Doğru/Yanlış: 6698 sayılı Kanun'un 28/2 maddesindeki kısmî istisna hâllerinde, ilgili kişinin zararın giderilmesini talep etme hakkı da uygulanmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.28/2, m.11'i 'zararın giderilmesini talep etme hakkı hariç' tutarak istisna eder. Yani zararın giderilmesini talep hakkı SAKLIDIR, uygulanmaya devam eder.","kaynak":"6698 m.28/2","zorluk":"zor"},
    {"id":"6698-OO-001","soru":"B, bir internet sitesinden ayakkabı sipariş eder ve ödemeyi yapar. Satıcı firma, ürünü kargoyla gönderebilmek için B'nin ad-soyad, adres ve telefon bilgisini işler. B bu işleme için ayrıca açık rıza vermemiştir. Bu durumda firmanın söz konusu kişisel verileri işlemesi KVKK'ya göre nasıl değerlendirilir?","siklar":["Açık rıza alınmadığı için hukuka aykırıdır","Bir sözleşmenin kurulması veya ifasıyla doğrudan ilgili olduğundan açık rıza aranmaksızın işlenebilir","Yalnızca Kuruldan izin alınması hâlinde işlenebilir","Ancak özel nitelikli veri sayıldığı için yasaktır","Sadece verinin alenileştirilmiş olması hâlinde işlenebilir"],"dogru":1,"aciklama":"m.5/2-c: Bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla, sözleşmenin taraflarına ait kişisel verilerin işlenmesi gerekli ise açık rıza aranmaz. Siparişin teslimi için ad-adres-telefon işlenmesi sözleşmenin ifasıyla doğrudan ilgilidir.","kaynak":"6698 m.5/2-c","zorluk":"orta"},
    {"id":"6698-OO-002","soru":"Trafik kazası geçiren A, baygın hâlde acil servise getirilir; rızasını açıklayabilecek durumda değildir. Görevliler, acil tedaviyi başlatıp hasta kaydını açabilmek için A'nın üzerinden çıkan kimlik bilgilerini işler. Bu işlem KVKK bakımından hangi hâle dayanır?","siklar":["İlgili kişinin önceden alenileştirmiş olması","Veri sorumlusunun meşru menfaati","Fiili imkânsızlık nedeniyle rızasını açıklayamayacak kişinin hayatının korunması için zorunlu olması","Bir hakkın tesisi, kullanılması veya korunması için zorunlu olması","Sözleşmenin ifası için gerekli olması"],"dogru":2,"aciklama":"m.5/2-b: Fiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan kişinin kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması hâlinde açık rıza aranmaz. Baygın hastanın hayatının ve beden bütünlüğünün korunması amacıyla kimlik bilgilerinin işlenmesi tam bu bende girer (sıradan kişisel veri; özel nitelikli sağlık verisi söz konusu olsaydı emsal hâl m.6/3-c olurdu).","kaynak":"6698 m.5/2-b","zorluk":"orta"},
    {"id":"6698-OO-003","soru":"Bir işveren, çalışanı B'nin maaş ve kimlik bilgilerini, kanunen zorunlu olan sigorta primi ve vergi bildirimlerini yapabilmek için ilgili kamu kurumlarına bildirir. B bu paylaşıma ayrıca açık rıza vermemiştir. Bu işleme KVKK'ya göre hangi sebebe dayanır?","siklar":["İlgili kişinin açık rızası","Veri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması","Verinin ilgili kişi tarafından alenileştirilmiş olması","Resmî istatistik amacıyla işlenmesi","Sözleşmenin kurulması için gerekli olması"],"dogru":1,"aciklama":"m.5/2-ç: Veri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması hâlinde açık rıza aranmaz. Sigorta ve vergi bildirimleri kanundan doğan yükümlülüktür.","kaynak":"6698 m.5/2-ç","zorluk":"orta"},
    {"id":"6698-OO-004","soru":"X şirketi, çalışanlarının bordrolarını hesaplatmak için bu işi Y muhasebe firmasına devreder. İşleme amacını ve hangi verilerin nasıl işleneceğini X belirler; Y ise yalnızca X'in verdiği yetki ve talimatlarla, X adına bordro verilerini işler. KVKK'ya göre Y'nin sıfatı nedir?","siklar":["Veri sorumlusu","İlgili kişi","Veri işleyen","İrtibat kişisi","Kişisel Verileri Koruma Kurumu"],"dogru":2,"aciklama":"m.3/1-ğ: Veri işleyen, veri sorumlusunun verdiği yetkiye dayanarak onun adına kişisel verileri işleyen kişidir. Amaç ve vasıtaları X belirlediğinden X veri sorumlusu (m.3/1-ı), X adına talimatla işleyen Y ise veri işleyendir.","kaynak":"6698 m.3/1-ğ, ı","zorluk":"orta"},
    {"id":"6698-OO-005","soru":"Bir kurum, bina girişlerinde personelin parmak izini okutarak geçiş sağlayan bir sistem kurmak ister. KVKK'ya göre parmak izi verisi ve bunun işlenebilmesi bakımından aşağıdakilerden hangisi DOĞRUDUR?","siklar":["Parmak izi sıradan kişisel veridir; herhangi bir koşul aranmadan serbestçe işlenir","Parmak izi özel nitelikli kişisel veridir; işlenmesi kural olarak yasaktır, ancak sayılı hâllerden biri varsa ve Kurulca belirlenen yeterli önlemler alınırsa işlenebilir","Parmak izi özel nitelikli veridir ve hiçbir hâlde işlenemez","Parmak izi anonim veri olduğundan KVKK kapsamı dışındadır","Parmak izi yalnızca yargı kararıyla işlenebilir"],"dogru":1,"aciklama":"m.6/1: biyometrik veri özel nitelikli kişisel veridir. m.6/3: işlenmesi yasaktır, ancak sayılan hâllerden biri (örn. açık rıza veya kanunda öngörülme) varsa mümkündür. m.6/4: ayrıca Kurul tarafından belirlenen yeterli önlemlerin alınması şarttır.","kaynak":"6698 m.6/1, m.6/3, m.6/4","zorluk":"zor"},
    {"id":"6698-OO-006","soru":"Bir firma, yalnızca e-bültene üyelik için form dolduran kişilerden e-posta adresi yeterli olduğu hâlde; ayrıca kan grubu, anne kızlık soyadı ve araç plakası bilgisini de zorunlu olarak ister. Bu uygulama, KVKK'nın genel ilkelerinden hangisine açıkça aykırıdır?","siklar":["Doğru ve gerektiğinde güncel olma","Hukuka ve dürüstlük kurallarına uygun olma dışındaki tüm ilkelere","İşlendikleri amaçla bağlantılı, sınırlı ve ölçülü olma","Süreli muhafaza (gerekli süre kadar saklama)","Kuruldan önceden izin alma ilkesi"],"dogru":2,"aciklama":"m.4/2-ç: Kişisel veriler işlendikleri amaçla bağlantılı, sınırlı ve ölçülü olmalıdır. E-bülten amacı için e-posta yeterliyken kan grubu/plaka gibi gereksiz verilerin toplanması ölçülülük ilkesine aykırıdır.","kaynak":"6698 m.4/2-ç","zorluk":"orta"},
    {"id":"6698-OO-007","soru":"Bir şirket, geçici bir kampanya için topladığı katılımcı verilerini, kampanya bittikten ve saklamayı gerektiren başka hiçbir hukuki sebep kalmadıktan sonra da sistemde tutmaya devam etmektedir. İlgili kişilerden de henüz bir talep gelmemiştir. KVKK'ya göre şirketin yükümlülüğü nedir?","siklar":["Veriler ancak ilgili kişi talep ederse silinebilir; talep gelmediği için saklanması hukuka uygundur","İşlenmesini gerektiren sebep ortadan kalktığından, veriler resen (kendiliğinden) de silinmeli, yok edilmeli veya anonim hâle getirilmelidir","Veriler süresiz saklanabilir, yeter ki şifrelensin","Veriler yalnızca Kurula devredilerek arşivlenir","Veriler otomatik olarak üçüncü kişilere aktarılır"],"dogru":1,"aciklama":"m.7/1: İşlenmesini gerektiren sebeplerin ortadan kalkması hâlinde kişisel veriler RESEN veya ilgili kişinin talebi üzerine veri sorumlusu tarafından silinir, yok edilir veya anonim hâle getirilir. Talep beklemeden resen imha yükümlülüğü vardır.","kaynak":"6698 m.7/1","zorluk":"orta"},
    {"id":"6698-OO-008","soru":"Kanunla görev ve yetki verilmiş bir kamu kurumu, millî güvenliği sağlamaya yönelik önleyici, koruyucu ve istihbari bir faaliyet kapsamında kişisel veri işlemektedir. Bu işleme bakımından KVKK hükümleri nasıl uygulanır?","siklar":["Kanunun bütün hükümleri eksiksiz uygulanır","Yalnızca aydınlatma, ilgili kişinin hakları ve sicile kayıt yükümlülükleri uygulanmaz; diğer hükümler uygulanır","Kanun hükümleri hiç uygulanmaz (tam istisna)","Sadece veri güvenliği yükümlülükleri askıya alınır","Faaliyet ancak Kurul izniyle Kanun kapsamına alınır"],"dogru":2,"aciklama":"m.28/1-ç: Millî savunmayı, millî güvenliği, kamu güvenliğini, kamu düzenini veya ekonomik güvenliği sağlamaya yönelik olarak kanunla yetkili kamu kurumlarınca yürütülen önleyici, koruyucu ve istihbari faaliyetler tam istisnadır; Kanun hükümleri hiç uygulanmaz.","kaynak":"6698 m.28/1-ç","zorluk":"zor"},
    {"id":"6698-OO-009","soru":"A, kendi cep telefonuna eşi ve çocuklarının telefon numaralarını rehber olarak kaydeder; bu bilgileri üçüncü kişilere vermez ve veri güvenliğine de dikkat eder. A'nın bu faaliyeti KVKK bakımından nasıl değerlendirilir?","siklar":["A bir veri sorumlusu olarak tüm KVKK yükümlülüklerine tabidir","Gerçek kişinin tamamen kendisiyle veya aynı konutta yaşayan aile fertleriyle ilgili faaliyeti kapsamında olduğundan Kanun hükümleri uygulanmaz","A, Veri Sorumluları Siciline kayıt olmak zorundadır","A, her bir numara için açık rıza belgesi düzenlemek zorundadır","A'nın bu işlemi yalnızca Kurul izniyle hukuka uygun olur"],"dogru":1,"aciklama":"m.28/1-a: Kişisel verilerin, üçüncü kişilere verilmemek ve veri güvenliğine ilişkin yükümlülüklere uyulmak kaydıyla gerçek kişiler tarafından tamamen kendisiyle veya aynı konutta yaşayan aile fertleriyle ilgili faaliyetler kapsamında işlenmesi tam istisnadır.","kaynak":"6698 m.28/1-a","zorluk":"orta"},
    {"id":"6698-OO-010","soru":"Serbest çalışan A, iş bulabilmek için kendi telefon numarasını ve e-posta adresini kendi açık internet sayfasında herkese açık biçimde yayımlamıştır. B, bu bilgileri sayfadan görerek A'ya iş teklifi için ulaşır. A'nın açık rızası ayrıca alınmamıştır. B'nin bu kişisel verileri işlemesi KVKK'ya göre hangi hâle dayanır?","siklar":["Hiçbir hâle dayanmaz; açık rıza alınmadığı için hukuka aykırıdır","Verinin ilgili kişi tarafından alenileştirilmiş olması","Veri sorumlusunun hukuki yükümlülüğü","Sözleşmenin ifası için zorunlu olması","Fiili imkânsızlık nedeniyle hayatın korunması"],"dogru":1,"aciklama":"m.5/2-d: İlgili kişinin kendisi tarafından alenileştirilmiş olması hâlinde açık rıza aranmaz. A numarasını/e-postasını iş bulma amacıyla kendisi herkese açık yayımladığından, bu amaca uygun kullanım alenileştirme hâline girer.","kaynak":"6698 m.5/2-d","zorluk":"zor"},
  ],
  4: [
    {"id":"7201-S-001","soru":"7201 sayılı Tebligat Kanunu'na göre, diğer kanunlarda özel hüküm bulunması hâlinde, tehirinde zarar umulan işlerde veya aynı yerde bulunan daire ve müesseseler arasında yapılacak tebligat aşağıdakilerden hangisi vasıtasıyla yaptırılır?","siklar":["Yalnızca Posta ve Telgraf Teşkilatı memurları","Kurumun kendi memurları veya mahalli mülkiye amirinin emriyle zabıta","Doğrudan zabıta amirinin kendi takdiriyle görevlendirdiği memurlar","Cumhuriyet savcısının emriyle kolluk görevlileri","Mahkeme kararı alınmak suretiyle ihtiyar heyeti azaları"],"dogru":1,"aciklama":"m.2: Bu hâllerde tebligat 'kendi memurları veya mahalli mülkiye amirinin emriyle zabıta vasıtasıyla' yaptırılır.","kaynak":"7201 m.2","zorluk":"orta"},
    {"id":"7201-S-002","soru":"7201 sayılı Tebligat Kanunu'na göre, tehirinde zarar umulan işlerde tebligat, mahalli mülkiye amirinin emriyle zabıta vasıtasıyla da yaptırılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.2 metni 'tehirinde zarar umulan işlerde ... mahalli mülkiye amirinin emriyle zabıta vasıtasıyla yaptırılır' der; ifade doğrudur.","kaynak":"7201 m.2","zorluk":"kolay"},
    {"id":"7201-S-003","soru":"7201 sayılı Tebligat Kanunu'na göre, Posta ve Telgraf Teşkilatı Genel Müdürlüğünün bu Kanuna göre yapacağı işlerden dolayı alacağı ücretler, bu işletme tarafından ______ ile tespit ve tayin edilir.","siklar":["ayrı bir tarife","Cumhurbaşkanlığı kararnamesi","Bakanlar Kurulu kararı","bu Kanuna ekli cetvel","yönetmelik"],"dogru":0,"aciklama":"m.3: ücretler 'bu işletme tarafından ayrı bir tarife ile tespit ve tayin edilir'.","kaynak":"7201 m.3","zorluk":"kolay"},
    {"id":"7201-S-004","soru":"7201 sayılı Tebligat Kanunu'na göre, kendisine tebligat yapılacak kimse veya tebligat yapılabilecek kimselerden hiçbiri adreste bulunmaz ya da tebellüğden imtina ederse, tebliğ memuru evrakı imza karşılığında aşağıdakilerden hangisine teslim eder?","siklar":["En yakın komşulardan birine","Varsa apartman yöneticisi veya kapıcıya","O yerin muhtar veya ihtiyar heyeti azasından birine ya da zabıta amir veya memurlarına","Görev bölgesinin Cumhuriyet savcısına","Adres kayıt sistemindeki en yakın akrabaya"],"dogru":2,"aciklama":"m.21: evrak 'o yerin muhtar veya ihtiyar heyeti azasından birine veyahut zabıta amir veya memurlarına imza mukabilinde teslim' edilir.","kaynak":"7201 m.21","zorluk":"orta"},
    {"id":"7201-S-005","soru":"7201 sayılı Tebligat Kanunu'na göre, muhatap adreste bulunmaz veya tebellüğden imtina ederse yapılacak işlemlerden biri aşağıdakilerden hangisi değildir?","siklar":["Evrakın muhtar, ihtiyar heyeti azası veya zabıtaya imza karşılığı teslim edilmesi","Tesellüm edenin adresini taşıyan ihbarnamenin binanın kapısına yapıştırılması","Keyfiyetin en yakın komşulardan birine, varsa yönetici veya kapıcıya bildirilmesi","Tebliğ evrakının yedi gün bekletildikten sonra çıkaran mercie iade edilmesi","İhbarnamenin kapıya yapıştırıldığı tarihin tebliğ tarihi sayılması"],"dogru":3,"aciklama":"A, B, C ve E m.21'de açıkça yer alır. D maddede yoktur; evrak iade edilmez, muhtar/zabıtaya teslim edilip ihbarname kapıya yapıştırılır.","kaynak":"7201 m.21","zorluk":"zor"},
    {"id":"7201-S-006","soru":"7201 sayılı Tebligat Kanunu'na göre, muhatabın adreste bulunmaması hâlinde tebliğ tarihi olarak aşağıdakilerden hangisi esas alınır?","siklar":["Evrakın muhtara teslim edildiği tarih","Komşuya haber verildiği tarih","Evrakın PTT'ye verildiği tarih","Kapıya yapıştırma tarihini izleyen yedinci gün","İhbarnamenin binanın kapısına yapıştırıldığı tarih"],"dogru":4,"aciklama":"m.21 son cümle: 'İhbarnamenin kapıya yapıştırıldığı tarih, tebliğ tarihi sayılır.'","kaynak":"7201 m.21","zorluk":"orta"},
    {"id":"7201-S-007","soru":"7201 sayılı Tebligat Kanunu'na göre, ihbarnamenin kapıya yapıştırıldığı tarihten yedi gün sonra tebligat yapılmış sayılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.21'e göre tebliğ tarihi, ihbarnamenin kapıya yapıştırıldığı tarihtir; sonradan eklenen herhangi bir bekleme süresi yoktur. İfade yanlıştır.","kaynak":"7201 m.21","zorluk":"orta"},
    {"id":"7201-S-008","soru":"7201 sayılı Tebligat Kanunu'na göre, muhatap yerine kendisine tebliğ yapılacak kimsede aranan şartlarla ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Nüfus kaydına göre onsekiz yaşını doldurmuş ve okuryazar olmalıdır","Yirmi bir yaşını doldurmuş ve muhatapla aynı konutta oturuyor olmalıdır","Reşit olmalı ve muhatabın birinci derece yakını olmalıdır","Görünüşüne nazaran onsekiz yaşından aşağı olmamalı ve bariz bir surette ehliyetsiz bulunmamalıdır","On beş yaşını bitirmiş ve ayırt etme gücüne sahip olmalıdır"],"dogru":3,"aciklama":"m.22: 'Muhatap yerine kendisine tebliğ yapılacak kimsenin görünüşüne nazaran onsekiz yaşından aşağı olmaması ve bariz bir surette ehliyetsiz bulunmaması lazımdır.' Ölçüt nüfus kaydı, akrabalık veya okuryazarlık değil; görünüşe dayalı yaş ve ehliyettir.","kaynak":"7201 m.22","zorluk":"orta"},
    {"id":"7201-S-009","soru":"7201 sayılı Tebligat Kanunu'na göre, muhatap yerine kendisine tebliğ yapılacak kimse hakkında aşağıdaki ifadelerden hangisi söylenemez?","siklar":["Görünüşüne nazaran onsekiz yaşından aşağı olmamalıdır","Bariz bir surette ehliyetsiz bulunmamalıdır","Yaş değerlendirmesi kişinin görünüşüne nazaran yapılır","Yaş ve ehliyet şartını birlikte taşımalıdır","Kimliğini ispatlamak için nüfus cüzdanı ibraz etmek zorundadır"],"dogru":4,"aciklama":"A, B, C ve D m.22'nin içeriğidir. E'deki 'nüfus cüzdanı ibrazı zorunluluğu' maddede yoktur; değerlendirme kimlik ibrazına değil 'görünüşe' dayanır.","kaynak":"7201 m.22","zorluk":"orta"},
    {"id":"7201-S-010","soru":"7201 sayılı Tebligat Kanunu'na göre, muhatap yerine kendisine tebliğ yapılacak kimsenin ______ onsekiz yaşından aşağı olmaması ve bariz bir surette ehliyetsiz bulunmaması lazımdır.","siklar":["nüfus kaydına göre","görünüşüne nazaran","beyanına göre","muhtarın onayıyla","resmî belgesine göre"],"dogru":1,"aciklama":"m.22: '... görünüşüne nazaran onsekiz yaşından aşağı olmaması ...' Ölçüt görünüştür.","kaynak":"7201 m.22","zorluk":"orta"},
    {"id":"7201-S-011","soru":"7201 sayılı Tebligat Kanunu'na göre, imza edemeyecek durumdaki muhataba parmağı bastırılmak suretiyle tebliğ yapıldığında, bu işlem bakımından aşağıdakilerden hangisi yapılır?","siklar":["Durum yalnızca sözlü olarak muhtara bildirilir, mazbataya yazılmaz","Tebliğ memuru kendi imzasını iki kez atarak işlemi tamamlar","Keyfiyet tebliğ mazbatasında tasrih edilir ve hazır bulunan şahsa da imza ettirilir","Parmak izi alındığı için ayrıca herhangi bir tutanak düzenlenmez","İşlem cumhuriyet savcısına bildirilerek onaya sunulur"],"dogru":2,"aciklama":"m.24: 'Yukardaki fıkralarda yazılı hallerde keyfiyet, tebliğ mazbatasında tasrih edilir ve hazır bulunan şahsa da imza ettirilir.' Parmak bastırma işlemi mazbataya geçirilir ve hazır bulunan kişiye imza ettirilir.","kaynak":"7201 m.24","zorluk":"orta"},
    {"id":"7201-S-012","soru":"7201 sayılı Tebligat Kanunu'na göre, imza edemeyecek durumdaki muhataba tebliğde izlenecek esaslardan hangisi yanlıştır?","siklar":["Önce sol elinin baş parmağı bastırılır","Sol elinin baş parmağı yoksa aynı elinin diğer bir parmağı bastırılır","Muhatabın iki eli de yoksa tebliğ evrakı muhtara teslim edilir","Sol eli yoksa sağ elinin baş parmağı, bu da yoksa diğer parmaklarından biri bastırılır","İşlem keyfiyeti tebliğ mazbatasında tasrih edilir ve hazır bulunan şahsa imza ettirilir"],"dogru":2,"aciklama":"m.24: 'Tebliğ yapılacak kimsenin iki eli de yoksa tebliğ evrakı kendisine verilir.' Muhtara teslim edilmez; C yanlıştır. A, B, D, E maddeye uygundur.","kaynak":"7201 m.24","zorluk":"zor"},
    {"id":"7201-S-013","soru":"7201 sayılı Tebligat Kanunu'na göre, okur yazar bir komşu bulunmaz veya bulunan komşu imzadan imtina ederse, tebliğ memuru muhtar veya ihtiyar heyeti azasından birini ya da bir zabıta memurunu tebliğ sırasında hazır bulunmak üzere davet eder.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.24 son fıkrası bu hâlde muhtar/ihtiyar heyeti azası veya zabıta memurunun davet edilip tebligatın onların huzurunda yapılacağını öngörür. İfade doğrudur.","kaynak":"7201 m.24","zorluk":"orta"},
    {"id":"7201-OO-001","soru":"Bir kamu kurumunun, gecikmesinde zarar doğacak (tehirinde zarar umulan) bir işe ilişkin tebligatı acilen yapması gerekmektedir; olağan PTT yoluyla bekletmek işin amacını boşa çıkaracaktır. Bu durumda kurum, söz konusu tebligatı aşağıdakilerden hangisi vasıtasıyla yaptırabilir?","siklar":["Yalnızca PTT memuru aracılığıyla; istisna yoktur","Kurumun kendi memurları veya mahalli mülkiye amirinin emriyle zabıta vasıtasıyla","Doğrudan görevli zabıta amirinin kendi takdiriyle","Cumhuriyet savcısının yazılı emriyle kolluk vasıtasıyla","İlgili mahkemeden alınacak ara kararla bilirkişi vasıtasıyla"],"dogru":1,"aciklama":"m.2: Tehirinde zarar umulan işlerde tebligat 'kendi memurları veya mahalli mülkiye amirinin emriyle zabıta vasıtasıyla yaptırılır.' Acil hâlde devreye giren yol budur.","kaynak":"7201 m.2","zorluk":"orta"},
    {"id":"7201-OO-002","soru":"Bir karakol amiri, kendi takdirinde aciliyet gördüğü bir tebligatı, herhangi bir üst makamın emri olmaksızın doğrudan zabıta memurlarına yaptırmak istemektedir. 7201 sayılı Kanun bakımından bu yaklaşım doğru mudur?","siklar":["Doğrudur; zabıta amiri tebligatı kendi takdiriyle her zaman yaptırabilir","Doğrudur; aciliyet bulunması yeterlidir, ayrıca emir gerekmez","Yanlıştır; zabıta ancak mahalli mülkiye amirinin emriyle bu tebligatı yapabilir","Yanlıştır; tebligat yalnızca mahkeme kararıyla zabıtaya yaptırılabilir","Doğrudur; ancak işlemi sonradan mülki amire onaylatması gerekir"],"dogru":2,"aciklama":"m.2'de zabıta vasıtasıyla tebligat 'mahalli mülkiye amirinin emriyle' yapılır. Zabıtanın kendi takdiri yeterli değildir; önceden mülki amir emri şarttır (sonradan onay değil).","kaynak":"7201 m.2","zorluk":"zor"},
    {"id":"7201-OO-003","soru":"Tebliğ memuru, muhatap A'nın gösterilen adresine gider; ne A ne de yerine tebligat yapılabilecek kimselerden hiçbiri evdedir. Memurun 7201 sayılı Kanuna göre yapması gereken işlem aşağıdakilerden hangisidir?","siklar":["Evrakı doğrudan en yakın komşuya imza karşılığı teslim eder","Evrakı çıkaran mercie iade eder ve adres yanlış şerhi düşer","Evrakı o yerin muhtar/ihtiyar heyeti azası veya zabıtaya imza karşılığı teslim eder, adresi taşıyan ihbarnameyi kapıya yapıştırır ve mümkünse komşuya haber verir","Evrakı kapının altından içeri atar ve fotoğrafla belgeler","Adreste yedi gün bekleyip muhatabı tekrar arar"],"dogru":2,"aciklama":"m.21: Hiç kimse adreste bulunmazsa evrak muhtar/ihtiyar heyeti azası veya zabıtaya imza karşılığı teslim edilir; tesellüm edenin adresini içeren ihbarname kapıya yapıştırılır; mümkün oldukça komşu/kapıcıya haber verilir.","kaynak":"7201 m.21","zorluk":"orta"},
    {"id":"7201-OO-004","soru":"Muhatap evde bulunamayınca tebliğ memuru, 10 Mart günü evrakı muhtara imza karşılığı teslim eder ve ihbarnameyi aynı gün kapıya yapıştırır; komşuya haber vermeyi ise ancak 12 Mart'ta başarır. Muhatabın gerçekte evrakı muhtardan teslim aldığı gün ise 15 Mart'tır. Bu olayda tebliğ tarihi hangi gündür?","siklar":["10 Mart (ihbarnamenin kapıya yapıştırıldığı gün)","12 Mart (komşuya haber verildiği gün)","15 Mart (muhatabın evrakı fiilen aldığı gün)","17 Mart (yapıştırmadan yedi gün sonra)","Evrakın muhtara teslim edildiği günden bir önceki gün"],"dogru":0,"aciklama":"m.21 son cümle: 'İhbarnamenin kapıya yapıştırıldığı tarih, tebliğ tarihi sayılır.' Komşuya haber, muhtara teslim veya fiilî alım tarihleri esas değildir.","kaynak":"7201 m.21","zorluk":"zor"},
    {"id":"7201-OO-005","soru":"Tebliğ memuru muhatap B'yi evinde bulur; ancak B evrakı almayı açıkça reddeder (tebellüğden imtina). Memurun bu durumda izleyeceği yol aşağıdakilerden hangisidir?","siklar":["Evrakı zorla B'nin eline tutuşturup tutanak tutar","Evrakı muhtar/ihtiyar heyeti azası veya zabıtaya imza karşılığı teslim eder ve ihbarnameyi kapıya yapıştırır","Tebligatı iptal edip dosyayı mahkemeye gönderir","B hakkında derhal idari para cezası uygular ve evrakı geri götürür","Muhatabın yerine ilk gördüğü kişiye, yaşına bakmaksızın evrakı teslim eder"],"dogru":1,"aciklama":"m.21, 'tebellüğden imtina' hâlini de adreste bulunmama hâliyle aynı sonuca bağlar: evrak muhtar/ihtiyar heyeti/zabıtaya imza karşılığı teslim edilir, ihbarname kapıya yapıştırılır; yapıştırma tarihi tebliğ tarihi sayılır.","kaynak":"7201 m.21","zorluk":"orta"},
    {"id":"7201-OO-006","soru":"Muhatap A evde yoktur; kapıyı, görünüşüne göre yaklaşık on üç-on dört yaşlarında olduğu anlaşılan bir çocuk açar. Tebliğ memuru evrakı 7201 sayılı Kanuna göre bu çocuğa teslim edebilir mi?","siklar":["Teslim edemez; muhatap yerine tebliğ yapılacak kişi görünüşüne nazaran onsekiz yaşından aşağı olmamalıdır","Teslim edebilir; aynı konutta oturması yeterlidir, yaş önemli değildir","Teslim edebilir; çocuk on beş yaşını doldurmuş görünüyorsa yeterlidir","Teslim edebilir; ancak çocuğa nüfus cüzdanını ibraz ettirmek şartıyla","Teslim edebilir; muhatabın çocuğu olması her hâlde yeterli sayılır"],"dogru":0,"aciklama":"m.22: Muhatap yerine tebliğ yapılacak kimsenin 'görünüşüne nazaran onsekiz yaşından aşağı olmaması' lazımdır. Görünüşte 18'den küçük çocuğa teslim yapılamaz.","kaynak":"7201 m.22","zorluk":"orta"},
    {"id":"7201-OO-007","soru":"Muhatap evde yokken kapıyı, görünüşe göre yetişkin (otuz yaşlarında) olduğu anlaşılan, ancak içinde bulunduğu durumdan bariz biçimde ehliyetsiz olduğu (algısının açıkça yerinde olmadığı) gözlenen bir kişi açar. Tebliğ memuru ne yapmalıdır?","siklar":["Evrakı teslim eder; çünkü kişi görünüşte onsekiz yaşından büyüktür","Evrakı teslim etmez; kişi yaşça uygun olsa da bariz surette ehliyetsiz görünmektedir","Evrakı teslim eder; ehliyetsizlik ancak mahkeme kararıyla dikkate alınır","Evrakı teslim eder; ancak kişiye iki kez imza attırarak güvence alır","Evrakı teslim eder; ehliyet şartı yalnızca asıl muhatap için aranır"],"dogru":1,"aciklama":"m.22 iki şartı birlikte arar: görünüşte 18'den aşağı olmamak VE bariz surette ehliyetsiz bulunmamak. Yaş uygun olsa bile bariz ehliyetsizlik teslimi engeller.","kaynak":"7201 m.22","zorluk":"zor"},
    {"id":"7201-OO-008","soru":"Tebliğ memuru muhatap A'yı evinde bulur; ancak A imza edecek kadar yazı bilmemekte ve imza atamamaktadır. Yanında okur yazar bir komşu da hazırdır. 7201 sayılı Kanuna göre tebliğ nasıl yapılır?","siklar":["Komşunun A adına evrakı imzalaması suretiyle","Evrakın muhtarlık kapısına asılması suretiyle","Komşulardan bir kişi huzurunda A'nın sol elinin baş parmağı bastırılmak suretiyle","Evrakın A'nın bir yakınına teslim edilmesi suretiyle","Tebligatın ertelenip A okuma yazma öğrenince yapılması suretiyle"],"dogru":2,"aciklama":"m.24: İmza edemeyecek durumdaki muhataba 'komşularından bir kişi huzurunda sol elinin baş parmağı bastırılmak suretiyle' tebliğ yapılır.","kaynak":"7201 m.24","zorluk":"kolay"},
    {"id":"7201-OO-009","soru":"İmza edemeyecek durumda olan muhatap A'nın iki eli de bulunmamaktadır; bu nedenle parmak bastırma yöntemi uygulanamamaktadır. Tebliğ memuru 7201 sayılı Kanuna göre nasıl davranır?","siklar":["Tebliğ evrakını A'nın kendisine verir","Evrakı A'nın bir yakınına teslim eder","Evrakı muhtara teslim edip ihbarnameyi kapıya yapıştırır","A'nın ayak baş parmağını bastırarak tebliğ yapar","Tebligatı iptal eder ve dosyayı geri gönderir"],"dogru":0,"aciklama":"m.24: 'Tebliğ yapılacak kimsenin iki eli de yoksa tebliğ evrakı kendisine verilir.' Bu hâlde evrak doğrudan muhataba teslim edilir.","kaynak":"7201 m.24","zorluk":"zor"},
    {"id":"7201-OO-010","soru":"İmza edemeyen muhataba tebliğ yapılacaktır; ancak çevrede okur yazar bir komşu bulunamamaktadır. Tebliğ memuru bu hâlde ne yapmalıdır?","siklar":["Tebligattan vazgeçip evrakı iade eder","Evrakı kapıya yapıştırarak tebligatı tamamlar","O mahalle veya köyün muhtar/ihtiyar heyeti azasından birini ya da bir zabıta memurunu davet eder ve tebligatı onun huzurunda yapar","Tebligatı tek başına yapar; tanık zorunluluğu kalkar","Muhatabın yerine, görünüşte onsekiz yaşından büyük herhangi birine evrakı teslim eder"],"dogru":2,"aciklama":"m.24 son fıkrası: Okur yazar komşu bulunmaz veya bulunan komşu imzadan imtina ederse, memur muhtar/ihtiyar heyeti azasından birini veya bir zabıta memurunu davet eder ve tebligat bunların huzurunda yapılır.","kaynak":"7201 m.24","zorluk":"orta"},
  ],
  5: [
    {"id":"5442-S-001","soru":"5442 sayılı İl İdaresi Kanunu'na göre, il genel idaresinin başı ve mercii aşağıdakilerden hangisidir?","siklar":["Vali","Vali muavini","Defterdar","İl idare kurulu","İçişleri Bakanı"],"dogru":0,"aciklama":"m.4: 'İl genel idaresinin başı ve mercii validir.' İl idare şube başkanlığı teşkilatı valinin emri altındadır.","kaynak":"5442 m.4","zorluk":"kolay"},
    {"id":"5442-S-002","soru":"5442 sayılı İl İdaresi Kanunu'nun 4. maddesine göre, aşağıdakilerden hangisi bu madde hükmünden (valinin emrinde olmaktan) müstesna tutulanlardan biri DEĞİLDİR?","siklar":["Cumhuriyet savcısı","İl milli eğitim müdürü","Askeri fabrika ve müesseseler","Askerlik daire ve şubeleri","Hâkimler Kanununda yazılı yargıç"],"dogru":1,"aciklama":"m.4 son fıkra: yargıç, Cumhuriyet savcısı ve yargıç sınıfındakiler, adalet memurları, askeri birlikler, askeri fabrika ve müesseseler, askerlik daire ve şubeleri müstesnadır. İl milli eğitim müdürü ise il idare şube başkanı olarak valinin emrindedir.","kaynak":"5442 m.4","zorluk":"orta"},
    {"id":"5442-S-003","soru":"5442 sayılı İl İdaresi Kanunu'na göre, vali ilde aşağıdakilerden hangisinin temsilcisi ve idari yürütme vasıtasıdır?","siklar":["Başbakanın","İçişleri Bakanının","Cumhurbaşkanının","Bakanlar Kurulunun","Türkiye Büyük Millet Meclisinin"],"dogru":2,"aciklama":"m.9: 'Vali, ilde Cumhurbaşkanının temsilcisi ve idari yürütme vasıtasıdır.' Vali, ilin genel idaresinden Cumhurbaşkanına karşı sorumludur.","kaynak":"5442 m.9","zorluk":"kolay"},
    {"id":"5442-S-004","soru":"5442 sayılı İl İdaresi Kanunu'na göre, vali il sınırları içinde bulunan genel ve özel bütün kolluk kuvvet ve teşkilatının amiridir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.11/A: 'Vali, il sınırları içinde bulunan genel ve özel bütün kolluk kuvvet ve teşkilatının amiridir.' Kolluk, valinin emirlerini derhal yerine getirmekle yükümlüdür.","kaynak":"5442 m.11/A","zorluk":"kolay"},
    {"id":"5442-S-005","soru":"5442 sayılı İl İdaresi Kanunu'na göre, vali kamu düzeni veya güvenliğinin olağan hayatı durduracak şekilde bozulduğu hâllerde, belirli yerlere giriş-çıkışı sınırlama ve araçların seyrini kısıtlama gibi tedbirleri en çok kaç günü geçmemek üzere alabilir?","siklar":["7 gün","10 gün","15 gün","20 gün","30 gün"],"dogru":2,"aciklama":"m.11: vali bu tedbirleri 'on beş günü geçmemek üzere' alabilir.","kaynak":"5442 m.11","zorluk":"orta"},
    {"id":"5442-S-006","soru":"5442 sayılı İl İdaresi Kanunu'na göre, vali olağanüstü hâllerde on beş günü geçmemek üzere aşağıdaki tedbirlerden hangisini ALAMAZ?","siklar":["Belirli yerlere giriş ve çıkışı sınırlama","Kişilerin belli yer ve saatlerde dolaşma ve toplanmalarını düzenleme veya kısıtlama","Araçların seyirlerini düzenleme veya kısıtlama","İldeki tüm okulları süresiz olarak kapatma","Ruhsatlı da olsa her çeşit silah ve merminin taşınması ve naklini yasaklama"],"dogru":3,"aciklama":"m.11'de sayılan tedbirler giriş-çıkış sınırlaması, dolaşma/toplanma ve araç seyrinin düzenlenmesi/kısıtlanması ve ruhsatlı dahil silah-mermi nakil yasağıdır. 'Tüm okulları süresiz kapatma' madde metninde yer almaz; ayrıca tedbirler 15 günle sınırlıdır, 'süresiz' olamaz.","kaynak":"5442 m.11","zorluk":"orta"},
    {"id":"5442-S-007","soru":"5442 sayılı İl İdaresi Kanunu'na göre, vali ilde çıkan olayları emrindeki kuvvetlerle önleyemediği takdirde yardım almak için aşağıdakilerden hangisine müracaat eder?","siklar":["Yalnız Genelkurmay Başkanlığına","Yalnız Cumhurbaşkanlığına","Yalnız komşu il valiliklerine","Doğrudan ve yalnızca Milli Savunma Bakanlığına","İçişleri Bakanlığına ve gerekirse en yakın kara, deniz ve hava birlik komutanlığına"],"dogru":4,"aciklama":"m.11/D: vali İçişleri Bakanlığından ve gerekirse en yakın kara, deniz ve hava birlik komutanlığından (sınır birlikleri dâhil) yardım ister; istek geciktirilmeksizin yerine getirilir, acil hâlde sözlü yapılıp sonradan yazıya dönüştürülür.","kaynak":"5442 m.11/D","zorluk":"orta"},
    {"id":"5442-S-008","soru":"5442 sayılı İl İdaresi Kanunu'na göre, genel kolluk kuvvetlerinin imkân ve kabiliyetlerini aşan durumlarda terörle mücadele için Türk Silahlı Kuvvetleri'nin Cumhurbaşkanı kararıyla görevlendirilebilmesi, aşağıdaki makamlardan hangisinin teklifi üzerine gerçekleşir?","siklar":["İçişleri Bakanlığı","Milli Savunma Bakanlığı","Adalet Bakanlığı","Genelkurmay Başkanlığı","İlgili il valisi"],"dogru":0,"aciklama":"m.11/J: Türk Silahlı Kuvvetleri, İçişleri Bakanlığının teklifi üzerine Cumhurbaşkanı kararıyla görevlendirilebilir. Teklif İçişleri Bakanlığına, görevlendirme kararı ise Cumhurbaşkanına aittir; iki aşama birbirine karıştırılmamalıdır.","kaynak":"5442 m.11/J","zorluk":"orta"},
    {"id":"5442-S-009","soru":"5442 sayılı İl İdaresi Kanunu'na göre, askeri birliklerin belirli görevleri genel kolluk kuvvetleriyle birlikte yapması hâlinde komuta, sevk ve idare en kıdemli kolluk amiri tarafından üstlenilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.11/J: birlikte görev hâlinde 'komuta, sevk ve idare askeri birliklerin en kıdemli komutanı tarafından üstlenilir.' Komuta kolluk amirinde değil, en kıdemli askeri komutandadır.","kaynak":"5442 m.11/J","zorluk":"zor"},
    {"id":"5442-S-010","soru":"5442 sayılı İl İdaresi Kanunu'na göre, aşağıdakilerden hangisi hakkında vali birinci derecede sicil amiridir?","siklar":["Köy muhtarı","Kaymakam","Belediye başkanı","İlin ikinci derecedeki memurları","Mahalle muhtarı"],"dogru":1,"aciklama":"m.18: valiler; vali muavini, kaymakamlar, il idare şube başkanları, il ve bölge muhakemat müdürleri ile genel ve özel kolluk amirlerinin birinci derecede; diğer memurların ikinci derecede sicil amiridir.","kaynak":"5442 m.18","zorluk":"orta"},
    {"id":"5442-S-011","soru":"5442 sayılı İl İdaresi Kanunu'na göre, il ve ilçe kurulması, kaldırılması ve merkezlerinin belirtilmesi aşağıdakilerden hangisi ile yapılır?","siklar":["Cumhurbaşkanı onayı ile","İçişleri Bakanlığının tasvibi ile","Kanun ile","Valilik kararı ile","İl genel meclisi kararı ile"],"dogru":2,"aciklama":"m.2/A: il ve ilçe kurulması, kaldırılması, merkezlerinin belirtilmesi, adlarının değiştirilmesi ve bir ilçenin başka bir ile bağlanması kanun ile yapılır.","kaynak":"5442 m.2","zorluk":"orta"},
    {"id":"5442-S-012","soru":"5442 sayılı İl İdaresi Kanunu'na göre, aşağıdaki idari değişiklik-yetkili makam eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["İl kurulması — kanun ile","Bucak kurulması — Cumhurbaşkanı onayı ile","İl ve ilçe sınırlarının değiştirilmesi — Cumhurbaşkanı onayı ile","Köy adlarının değiştirilmesi — İçişleri Bakanlığının tasvibi ile","Bir ilçenin başka bir ile bağlanması — Cumhurbaşkanı onayı ile"],"dogru":4,"aciklama":"m.2/A: bir ilçenin başka bir ile bağlanması KANUN ile yapılır. Diğer eşleştirmeler doğrudur: bucak ve sınır değişiklikleri CB onayı (m.2/B), köy adı değişikliği İçişleri tasvibi (m.2/Ç).","kaynak":"5442 m.2","zorluk":"zor"},
    {"id":"5442-S-013","soru":"5442 sayılı İl İdaresi Kanunu'na göre, bucak kurulması, kaldırılması ile il, ilçe ve bucak sınırlarının değiştirilmesi ........... ile yapılır.","siklar":["kanun","Cumhurbaşkanı onayı","İçişleri Bakanlığının tasvibi","valilik kararı","il idare kurulu kararı"],"dogru":1,"aciklama":"m.2/B: bucak kurulması/kaldırılması, merkezinin belirtilmesi, il-ilçe-bucak sınırlarının ve bucak adlarının değiştirilmesi Cumhurbaşkanı onayı ile yapılır.","kaynak":"5442 m.2","zorluk":"orta"},
    {"id":"5442-S-014","soru":"5442 sayılı İl İdaresi Kanunu'na göre, ilçe genel idaresinin başı ve mercii olup ilçede Cumhurbaşkanının idari yürütme vasıtası olan görevli aşağıdakilerden hangisidir?","siklar":["Vali","Bucak müdürü","Malmüdürü","Kaymakam","Tahrirat katibi"],"dogru":3,"aciklama":"m.27: 'İlçe genel idaresinin başı ve mercii kaymakamdır. Kaymakam, ilçede Cumhurbaşkanının idari yürütme vasıtasıdır.'","kaynak":"5442 m.27","zorluk":"kolay"},
    {"id":"5442-S-015","soru":"5442 sayılı İl İdaresi Kanunu'na göre, kaymakam ilçe idare şube başkanları ile ikinci derecedeki memurlara ve kolluk amir ve memurlarına, savunmasını aldıktan sonra hangi disiplin cezalarını verebilir?","siklar":["Yalnız uyarma","Uyarma ve kınama","Uyarma, kınama ve aylıktan kesme","Kınama ve aylıktan kesme","Yalnız kınama"],"dogru":1,"aciklama":"m.31/I: kaymakam, savunmayı aldıktan sonra uyarma ve kınama cezaları verir ve uygular; daha ağır cezalar için teklifte bulunabilir. Re'sen verdiği cezalar kesindir ve sicile geçer.","kaynak":"5442 m.31","zorluk":"orta"},
    {"id":"5442-S-016","soru":"5442 sayılı İl İdaresi Kanunu'na göre, kaymakam ilçe idare şube başkanlarına acele hâllerde ........... kadar izin verebilir.","siklar":["8 güne","3 güne","15 güne","bir aya","5 güne"],"dogru":0,"aciklama":"m.31/J: kaymakam ilçe idare şube başkanlarına acele hâllerde sekiz güne kadar izin verebilir; tayini kendisine ait memurlara ise yıllık izne mahsuben bir aya kadar izin verebilir.","kaynak":"5442 m.31/J","zorluk":"orta"},
    {"id":"5442-S-017","soru":"5442 sayılı İl İdaresi Kanunu'na göre, kaymakam ilçe genel ve özel kolluk kuvvetleri mensuplarının yerlerini, valinin tasvibini almaksızın doğrudan değiştirebilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.32/D: kaymakam, kolluk mensuplarının yerlerini ancak 'valinin tasvibiyle' geçici veya sürekli değiştirebilir. Valiyse kolluğun yerini kendisi değiştirir (m.11/Ç).","kaynak":"5442 m.32/D","zorluk":"orta"},
    {"id":"5442-S-018","soru":"5442 sayılı İl İdaresi Kanunu'na göre, bucakta en büyük Hükümet memuru ve temsilcisi aşağıdakilerden hangisidir?","siklar":["Kaymakam","Vali","Bucak müdürü","Belediye başkanı","Nahiye meclisi başkanı"],"dogru":2,"aciklama":"m.42: 'Bucak müdürü, bucakta en büyük Hükümet memuru ve temsilcisidir.' Bucağın genel idaresinden sorumludur; kolluk emri altındadır (m.43).","kaynak":"5442 m.42","zorluk":"kolay"},
    {"id":"5442-S-019","soru":"5442 sayılı İl İdaresi Kanunu'ndaki disiplin cezası yetkileri açısından aşağıdaki ifadelerden hangisi YANLIŞTIR?","siklar":["Bucak müdürü, savunmasını aldıktan sonra yalnız uyarma cezası verir.","Kaymakam, savunmasını aldıktan sonra uyarma ve kınama cezası verir.","Vali, uyarma, kınama ve beş günlüğe kadar aylıktan kesme cezası verir.","Bucak müdürü, uyarma ve kınama cezalarını birlikte verebilir.","Bucak müdürünün verdiği uyarma cezası kesindir ve tebliğ tarihinden itibaren sicile geçer."],"dogru":3,"aciklama":"m.42/E: bucak müdürü yalnız uyarma cezası verir; daha ağır ceza için vali ve kaymakama teklifte bulunur. Bucak müdürünün kınama yetkisi yoktur. A, B, C, E ifadeleri (m.42, m.31, m.13) doğrudur.","kaynak":"5442 m.42 / m.31 / m.13","zorluk":"zor"},
    {"id":"5442-S-020","soru":"5442 sayılı İl İdaresi Kanunu'na göre, aşağıdakilerden hangisi il idare kurulunun üyelerinden biri DEĞİLDİR?","siklar":["Defterdar","Hukuk işleri müdürü","Malmüdürü","Veteriner müdürü","Milli eğitim müdürü"],"dogru":2,"aciklama":"m.57: il idare kurulu vali başkanlığında hukuk işleri müdürü, defterdar, milli eğitim, bayındırlık, sağlık ve sosyal yardım, tarım ve veteriner müdürlerinden teşekkül eder. Malmüdürü ise il değil ilçe idare kurulu üyesidir (m.58).","kaynak":"5442 m.57","zorluk":"orta"},
    {"id":"5442-S-021","soru":"5442 sayılı İl İdaresi Kanunu'na göre, aşağıdakilerden hangisi ilçe idare kurulunun üyelerinden biri DEĞİLDİR?","siklar":["Tahrirat katibi","Malmüdürü","Hükümet hekimi","Veteriner","Defterdar"],"dogru":4,"aciklama":"m.58: ilçe idare kurulu kaymakam başkanlığında tahrirat katibi, malmüdürü, Hükümet hekimi, milli eğitim memuru, tarım memuru ve veterinerden teşekkül eder. Defterdar il idare kurulu üyesidir (m.57).","kaynak":"5442 m.58","zorluk":"orta"},
    {"id":"5442-S-022","soru":"5442 sayılı İl İdaresi Kanunu'na göre, kamu düzenini tehlikeye düşürecek toplumsal olayların baş göstermesi hâlinde vali tarafından kamu düzenini sağlamak amacıyla alınan ve usulüne göre ilan olunan karar ve tedbirlere aykırı davrananlar ne ile cezalandırılır?","siklar":["Yalnız idari para cezası","Üç aydan bir yıla kadar hapis cezası","Bir yıldan üç yıla kadar hapis cezası","Altı aydan iki yıla kadar hapis cezası","Yalnız uyarma cezası"],"dogru":1,"aciklama":"m.66 (ek cümle, 6638/16): toplumsal olaylarda valinin usulüne göre ilan ettiği karar ve tedbirlere aykırı davrananlar üç aydan bir yıla kadar hapis cezasıyla cezalandırılır. Olağan karar/tedbire uymama ise Kabahatler Kanunu m.32 (idari para) kapsamındadır.","kaynak":"5442 m.66","zorluk":"zor"},
    {"id":"5442-S-023","soru":"5442 sayılı İl İdaresi Kanunu'na göre, sivil hava meydanları, limanlar ve sınır kapılarında güvenliğin sağlanması, giriş-çıkış hizmetlerinin düzenli yürütülmesi ve koordinasyonun gerçekleştirilmesi için gerekli önlemleri almaya ve kuruluşların çalışmalarını denetlemeye kim yetkilidir?","siklar":["Vali","Kaymakam","İçişleri Bakanı","Bucak müdürü","Gümrük müdürü"],"dogru":0,"aciklama":"Ek Madde 1: bu yerlerde gerekli önlemleri almaya ve uygulamaya, kuruluşları denetlemeye vali yetkilidir. İçişleri Bakanlığının uygun göreceği yerlerde vali tarafından mülki idare amiri görevlendirilir; vali yetkilerini bu amire devredebilir.","kaynak":"5442 Ek Madde 1","zorluk":"orta"},
    {"id":"5442-OO-001","soru":"B ilinde görülmekte olan bir davanın hızlandırılmasını isteyen Vali A, ildeki adliyede görevli Hâkim C'ye 'duruşmaları sıklaştırın' yönünde doğrudan talimat vermek istemiştir. 5442 sayılı İl İdaresi Kanunu'na göre bu durumda hukuken aşağıdakilerden hangisi doğrudur?","siklar":["Vali il genel idaresinin başı olduğundan ildeki bütün görevlilere olduğu gibi hâkime de talimat verebilir","Hâkim, yargı mensubu olarak valinin emrinden müstesna tutulduğundan vali ona bu yönde talimat veremez","Vali, talimatı ancak Cumhuriyet savcısı aracılığıyla hâkime iletebilir","Vali, il idare kurulu kararı almak şartıyla hâkime talimat verebilir","Vali, İçişleri Bakanlığının onayını alarak hâkime talimat verebilir"],"dogru":1,"aciklama":"m.4 son fıkra: Hâkimler Kanunu ve İcra-İflas Kanununda yazılı yargıç, Cumhuriyet savcısı ve yargıç sınıfındakiler ile adalet memurları, askeri birlikler bu madde hükmünden (valinin emri altında olmaktan) müstesnadır. Vali il teşkilatının başı olsa da yargı bağımsızlığı gereği hâkime idari talimat veremez.","kaynak":"5442 m.4","zorluk":"orta"},
    {"id":"5442-OO-002","soru":"Tarım ve Orman Bakanı, kendi görev alanına giren bir iş için D ili Valisine doğrudan (re'sen) bir emir göndermiştir. Vali, 'Bana yalnızca İçişleri Bakanı emir verebilir, başka bir bakanın emrini yerine getirmem' diyerek emri uygulamamıştır. 5442 sayılı İl İdaresi Kanunu'na göre aşağıdakilerden hangisi doğrudur?","siklar":["Vali haklıdır; valiye yalnız İçişleri Bakanı emir verebilir","Vali haklıdır; diğer bakanlar valiye ancak İçişleri Bakanlığı kanalıyla emir verebilir","Bakan haklıdır; bakanlar görevlerine ait işler için valilere re'sen emir ve talimat verir, vali bunu yerine getirmekle yükümlüdür","Bakan haklıdır; ancak emrin geçerli olması için Cumhurbaşkanı onayı gerekir","Emir geçersizdir; bakanlar valilere yalnız genel emir niteliğinde talimat verebilir"],"dogru":2,"aciklama":"m.9/A: Cumhurbaşkanı yardımcıları ve bakanlar, görevlerine ait işleri için valilere re'sen emir ve talimat verirler. Vali, ilin genel idaresinden Cumhurbaşkanına karşı sorumlu olmakla birlikte ilgili bakanın kendi görev alanındaki re'sen emrini yerine getirmek zorundadır.","kaynak":"5442 m.9","zorluk":"orta"},
    {"id":"5442-OO-003","soru":"Vali, ilde aniden büyüyen bir asayiş olayına müdahale için ildeki bir özel kolluk birimine acil emir vermiştir. Birim amiri ise 'Önce bağlı olduğum kurumun amirinden teyit almam gerekir' diyerek emri uygulamayı geciktirmiştir. 5442 sayılı İl İdaresi Kanunu'na göre aşağıdakilerden hangisi doğrudur?","siklar":["Birim amiri haklıdır; özel kolluk valinin değil kendi kurum amirinin emrindedir","Vali yalnız genel kolluğun amiri olduğundan özel kolluk emri uygulamak zorunda değildir","Vali, il sınırları içindeki genel ve özel bütün kolluğun amiridir; kolluk valinin emrini derhal yerine getirmekle yükümlüdür","Emrin uygulanması için il idare kurulunun onayı gerekir","Özel kolluk yalnız kaymakamın emrini derhal yerine getirmekle yükümlüdür"],"dogru":2,"aciklama":"m.11/A: Vali, il sınırları içinde bulunan genel ve özel bütün kolluk kuvvet ve teşkilatının amiridir; bu teşkilatın amir ve memurları vali tarafından verilen emirleri derhal yerine getirmekle yükümlüdür. Üst kurumdan teyit bekleyerek geciktirme bu yükümlülüğe aykırıdır.","kaynak":"5442 m.11/A","zorluk":"kolay"},
    {"id":"5442-OO-004","soru":"Bir ilde kamu güvenliği olağan hayatı durduracak şekilde bozulunca Vali, belirli bir bölgeye giriş ve çıkışı 25 gün süreyle kesintisiz sınırlayan bir tedbir kararı ilan etmiştir. 5442 sayılı İl İdaresi Kanunu açısından bu karar bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Karar tümüyle hukuka uygundur; vali bu tedbirleri süre sınırı olmaksızın uygulayabilir","Tedbir bu madde kapsamında en çok on beş günü geçmemek üzere alınabileceğinden 25 günlük süre bu sınırı aşmaktadır","Süre en çok 30 gün olabileceğinden karar tümüyle geçerlidir","Giriş-çıkış sınırlaması yalnız kaymakam tarafından alınabilir","Bu tedbir için süre sınırı yoktur, ancak il idare kurulu kararı şarttır"],"dogru":1,"aciklama":"m.11: Vali, kamu düzeni veya güvenliğinin olağan hayatı durduracak şekilde bozulduğu hâllerde belirli yerlere giriş-çıkışı sınırlama gibi tedbirleri 'on beş günü geçmemek üzere' alabilir. 25 günlük süre bu azami sınırı aşar.","kaynak":"5442 m.11","zorluk":"orta"},
    {"id":"5442-OO-005","soru":"Vali, ilde çıkan ve emrindeki kuvvetlerle önlenemeyen bir olay nedeniyle en yakın askeri birlikten yardım istemek zorunda kalmıştır. Olay o kadar acildir ki yazılı yazışma için vakit yoktur. 5442 sayılı İl İdaresi Kanunu'na göre vali bu yardım istemini nasıl yapabilir?","siklar":["Yardım istemi her hâlde önceden yazılı yapılmalıdır; aksi hâlde geçersizdir","Acil durumlarda istem, sonradan yazılı şekle dönüştürülmek kaydıyla sözlü olarak yapılabilir ve geciktirilmeksizin yerine getirilir","Vali askeri birlikten yardım isteyemez; yalnız komşu il valiliklerinden yardım isteyebilir","Yardım istemi yalnızca Cumhurbaşkanlığı aracılığıyla yapılabilir","Sözlü istem mümkündür ancak yardım birlik tarafından ancak 24 saat sonra yerine getirilir"],"dogru":1,"aciklama":"m.11/D: Valinin yardım istemi geciktirilmeksizin yerine getirilir; acil durumlarda bu istek sonradan yazılı şekle dönüştürülmek kaydıyla sözlü olarak yapılabilir. Vali, İçişleri Bakanlığından ve gerekirse en yakın kara, deniz ve hava birlik komutanlığından yardım isteyebilir.","kaynak":"5442 m.11/D","zorluk":"orta"},
    {"id":"5442-OO-006","soru":"Terörle mücadele için Cumhurbaşkanı kararıyla görevlendirilen bir askeri birlik, bir ilçede belirli bir operasyonu genel kolluk kuvvetleriyle birlikte yürütmektedir. 5442 sayılı İl İdaresi Kanunu'na göre bu birlikte görevde komuta, sevk ve idare kime aittir?","siklar":["En kıdemli kolluk amirine","İlçe kaymakamına","İl valisine","Askeri birliklerin en kıdemli komutanına","İçişleri Bakanlığınca görevlendirilen mülki amire"],"dogru":3,"aciklama":"m.11/J: Askeri birliklerin belirli görevleri genel kolluk kuvvetleriyle birlikte yapması hâlinde komuta, sevk ve idare askeri birliklerin en kıdemli komutanı tarafından üstlenilir.","kaynak":"5442 m.11/J","zorluk":"zor"},
    {"id":"5442-OO-007","soru":"Bir ilde görev yapan kaymakam hakkında dönem sonu sicil/değerlendirme işlemi yapılacaktır. 5442 sayılı İl İdaresi Kanunu'na göre kaymakamın sicil amirliği bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Vali, kaymakamın birinci derecede sicil amiridir","Vali, kaymakamın yalnızca ikinci derecede sicil amiridir","İçişleri Bakanı, kaymakamın birinci derecede sicil amiridir","Kaymakamın sicil amiri il idare kuruludur","Kaymakamın sicil amiri vali muavinidir"],"dogru":0,"aciklama":"m.18: Valiler; vali muavini ile kaymakamların, il idare şube başkanlarının, il ve bölge muhakemat müdürlerinin, genel ve özel kolluk amirlerinin birinci derecede; diğer memurların ikinci derecede sicil amiridir. Kaymakam birinci derece kapsamındadır.","kaynak":"5442 m.18","zorluk":"kolay"},
    {"id":"5442-OO-008","soru":"Coğrafi yakınlık gerekçesiyle X ilçesinin bağlı olduğu ilden alınıp komşu Y iline bağlanması gündeme gelmiştir. 5442 sayılı İl İdaresi Kanunu'na göre bu değişiklik aşağıdakilerden hangisiyle yapılır?","siklar":["Cumhurbaşkanı onayı ile","İçişleri Bakanlığının tasvibi ile","Kanun ile","İki ilin valiliklerinin ortak kararı ile","İl genel meclisi kararı ile"],"dogru":2,"aciklama":"m.2/A: İl ve ilçe kurulması, kaldırılması, merkezlerinin belirtilmesi, adlarının değiştirilmesi ve bir ilçenin başka bir ile bağlanması KANUN ile yapılır. Bucak kurulması ve sınır değişiklikleri ise Cumhurbaşkanı onayına tabidir (m.2/B).","kaynak":"5442 m.2","zorluk":"zor"},
    {"id":"5442-OO-009","soru":"Kaymakam, görevini sürekli aksatan ilçedeki bir memur hakkında savunmasını da aldıktan sonra doğrudan 'aylıktan kesme' cezası vermek istemektedir. 5442 sayılı İl İdaresi Kanunu'na göre aşağıdakilerden hangisi doğrudur?","siklar":["Kaymakam re'sen aylıktan kesme cezası verebilir; bu ceza kesindir","Kaymakam yalnız uyarma ve kınama cezası verebilir; aylıktan kesme gibi daha ağır cezalar için teklif ve talepte bulunabilir","Kaymakam hiçbir disiplin cezası veremez; tüm cezaları yalnız vali verir","Kaymakam yalnız uyarma cezası verebilir, kınama yetkisi yoktur","Kaymakam aylıktan kesme cezasını ancak il idare kurulu kararıyla verebilir"],"dogru":1,"aciklama":"m.31/I: Kaymakam, ilçe idare şube başkanları ile ikinci derecedeki memurlara ve kolluk amir/memurlarına savunmasını aldıktan sonra uyarma ve kınama cezaları verir ve uygular; daha ağır cezalar için özel kanun hükümlerine göre teklif ve talepte bulunabilir. Aylıktan kesme (m.13) valinin yetkisindedir.","kaynak":"5442 m.31","zorluk":"orta"},
    {"id":"5442-OO-010","soru":"Kaymakam, ilçedeki bir kolluk amirinin görev yerini başka bir bölgeye sürekli olarak değiştirmek istemektedir. 5442 sayılı İl İdaresi Kanunu'na göre kaymakam bu işlemi nasıl yapabilir?","siklar":["Kaymakam ilçe kolluğunun amiri olduğundan kolluk mensubunun yerini doğrudan, valiye danışmaksızın değiştirebilir","Kaymakam, ancak valinin tasvibini alarak kolluk mensubunun yerini geçici veya sürekli değiştirebilir","Kaymakam kolluk mensubunun yerini hiçbir şekilde değiştiremez; bu yetki yalnız validedir","Kaymakam yer değişikliğini ilçe idare kurulu kararıyla yapabilir","Kaymakam yalnızca İçişleri Bakanlığının onayıyla yer değiştirebilir"],"dogru":1,"aciklama":"m.32/D: Kaymakam, valinin tasvibiyle ilçe genel ve özel kolluk kuvvetleri mensuplarının geçici veya sürekli olarak yerlerini değiştirebilir. Vali ise ildeki kolluğun yerini kendisi değiştirir (m.11/Ç).","kaynak":"5442 m.32/D","zorluk":"orta"},
    {"id":"5442-OO-011","soru":"Bir bucak müdürü, gözetimi altındaki bucak teşkilatına dahil bir memura, savunmasını da aldıktan sonra 'kınama' cezası vermek istemektedir. 5442 sayılı İl İdaresi Kanunu'na göre aşağıdakilerden hangisi doğrudur?","siklar":["Bucak müdürü uyarma ve kınama cezalarını birlikte verebilir","Bucak müdürü savunma aldıktan sonra yalnız uyarma cezası verebilir; kınama dâhil daha ağır cezalar için vali ve kaymakama teklifte bulunur","Bucak müdürü kınama cezası verebilir, ancak uyarma cezası veremez","Bucak müdürü aylıktan kesmeye kadar tüm cezaları verebilir","Bucak müdürü hiçbir disiplin cezası veremez"],"dogru":1,"aciklama":"m.42/E: Bucak müdürü, gözetim ve teftişi altındaki bucak teşkilatına dahil amir ve memurlara savunmalarını aldıktan sonra yalnız uyarma cezası verir ve uygular; daha ağır disiplin cezaları ile takdirname için vali ve kaymakama tekliflerde bulunur.","kaynak":"5442 m.42","zorluk":"orta"},
    {"id":"5442-OO-012","soru":"Kişilerin can ve mal emniyetini tehlikeye düşüren toplumsal olayların baş göstermesi üzerine Vali, kamu düzenini sağlamak amacıyla usulüne göre bir karar ilan etmiştir. A, bu karara bilerek aykırı davranmıştır. 5442 sayılı İl İdaresi Kanunu'na göre A hakkında uygulanacak yaptırım nedir?","siklar":["Yalnız idari para cezası uygulanır","Üç aydan bir yıla kadar hapis cezasıyla cezalandırılır","Yalnız uyarma cezası verilir","Bir yıldan üç yıla kadar hapis cezasıyla cezalandırılır","Herhangi bir yaptırım uygulanamaz"],"dogru":1,"aciklama":"m.66 (ek cümle, 6638/16): Kamu düzenini ve güvenliğini veya kişilerin can ve mal emniyetini tehlikeye düşürecek toplumsal olayların baş göstermesi hâlinde vali tarafından usulüne göre ilan olunan karar ve tedbirlere aykırı davrananlar üç aydan bir yıla kadar hapis cezasıyla cezalandırılır. Olağan karar/tedbire uymama ise Kabahatler Kanunu m.32 (idari para) kapsamındadır.","kaynak":"5442 m.66","zorluk":"zor"},
    {"id":"5442-OO-013","soru":"Bir ildeki sivil hava meydanında, giriş-çıkış hizmetlerini yürüten kuruluşlar arasında koordinasyon eksikliği ve güvenlik açığı ortaya çıkmıştır. 5442 sayılı İl İdaresi Kanunu'na göre bu yerde güvenliğin sağlanması, hizmetlerin düzenli yürütülmesi ve kuruluşlar arası koordinasyon için gerekli önlemleri almaya ve kuruluşları denetlemeye asıl yetkili olan kimdir?","siklar":["Vali (gerektiğinde İçişleri Bakanlığının uygun gördüğü yerde görevlendireceği mülki idare amiri)","Hava meydanını işleten kuruluşun genel müdürü","Gümrük müdürü","Bucak müdürü","En yakın askeri birlik komutanı"],"dogru":0,"aciklama":"Ek Madde 1: Vali; sivil hava meydanları, limanlar ve sınır kapılarında güvenliğin sağlanması, giriş-çıkış hizmetlerinin düzenli yürütülmesi ve kuruluşlar arası koordinasyon için gerekli önlemleri almaya, uygulamaya ve kuruluşları denetlemeye yetkilidir. İçişleri Bakanlığının uygun göreceği yerlerde vali tarafından mülki idare amiri görevlendirilir ve vali yetkilerini ona devredebilir.","kaynak":"5442 Ek Madde 1","zorluk":"orta"},
    {"id":"5442-OO-014","soru":"Vali başkanlığında toplanacak il idare kurulu toplantısına, ilçedeki bir malmüdürü 'üye sıfatıyla' katılmak istemiştir. 5442 sayılı İl İdaresi Kanunu'na göre bu talep bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Talep yerindedir; malmüdürü il idare kurulunun üyesidir","Malmüdürü ilçe idare kurulu üyesidir; il idare kurulunda mali üye olarak defterdar bulunur","Malmüdürü hem il hem ilçe idare kurulunun üyesidir","İl idare kurulunda mali işler için hukuk işleri müdürü yer aldığından malmüdürüne gerek yoktur","İl idare kurulunda mali üye bulunmaz"],"dogru":1,"aciklama":"m.57: İl idare kurulu vali başkanlığında hukuk işleri müdürü, defterdar, milli eğitim, bayındırlık, sağlık ve sosyal yardım, tarım ve veteriner müdürlerinden teşekkül eder. m.58: İlçe idare kurulu kaymakam başkanlığında tahrirat katibi, malmüdürü, Hükümet hekimi, milli eğitim memuru, tarım memuru ve veterinerden teşekkül eder. Malmüdürü ilçe kurulu üyesidir; il kurulunun mali üyesi defterdardır.","kaynak":"5442 m.57 / m.58","zorluk":"orta"},
  ],
  6: [
    {"id":"5326-S-001","soru":"5326 sayılı Kabahatler Kanunu'na göre, bu Kanunla korunması amaçlanan değerlerden biri aşağıdakilerden hangisi değildir?","siklar":["Toplum düzeni","Millî güvenlik","Genel sağlık","Çevre","Ekonomik düzen"],"dogru":1,"aciklama":"m.1/1: Kanun toplum düzenini, genel ahlâkı, genel sağlığı, çevreyi ve ekonomik düzeni korumak amacıyla düzenlenmiştir. 'Millî güvenlik' bu beş değer arasında yer almaz.","kaynak":"5326 m.1/1","zorluk":"kolay"},
    {"id":"5326-S-002","soru":"5326 sayılı Kabahatler Kanunu'na göre kabahat deyiminden; kanunun, karşılığında ______ uygulanmasını öngördüğü haksızlık anlaşılır. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["idarî yaptırım","hapis cezası","adlî para cezası","güvenlik tedbiri","disiplin cezası"],"dogru":0,"aciklama":"m.2/1: Kabahat, kanunun karşılığında idarî yaptırım uygulanmasını öngördüğü haksızlıktır. Kabahatin ayırt edici unsuru karşılığının idarî yaptırım olmasıdır.","kaynak":"5326 m.2/1","zorluk":"kolay"},
    {"id":"5326-S-003","soru":"5326 sayılı Kabahatler Kanunu'na göre, kabahat karşılığı olan yaptırımların türü, süresi ve miktarı ancak ne ile belirlenebilir?","siklar":["Yönetmelik","Tüzük","Kanun","İdarenin genel ve düzenleyici işlemi","Cumhurbaşkanlığı kararnamesi"],"dogru":2,"aciklama":"m.4/2: Kabahat karşılığı olan yaptırımların türü, süresi ve miktarı ancak kanunla belirlenebilir.","kaynak":"5326 m.4/2","zorluk":"orta"},
    {"id":"5326-S-004","soru":"5326 sayılı Kabahatler Kanunu'na göre kabahat, neticenin oluştuğu zaman işlenmiş sayılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5/2: Kabahat, failin icraî veya ihmali davranışı gerçekleştirdiği zaman işlenmiş sayılır; neticenin oluştuğu zaman bu bakımdan dikkate alınmaz. İfade ters verildiği için yanlıştır.","kaynak":"5326 m.5/2","zorluk":"orta"},
    {"id":"5326-S-005","soru":"5326 sayılı Kabahatler Kanunu'na göre, organ veya temsilcilik ya da hizmet ilişkisinin dayanağını oluşturan işlemin hukuken geçerli olmaması halinde de tüzel kişi veya iş sahibi hakkında idarî yaptırım uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.8/4: Birinci ve ikinci fıkra hükümleri, organ/temsilcilik ya da hizmet ilişkisinin dayanağını oluşturan işlemin hukuken geçerli olmaması halinde de uygulanır.","kaynak":"5326 m.8/4","zorluk":"zor"},
    {"id":"5326-S-006","soru":"5326 sayılı Kabahatler Kanunu'na göre kabahatler, kanunda açıkça hüküm bulunmayan hallerde, hem kasten hem de taksirle işlenebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.9/1: Kabahatler, kanunda açıkça hüküm bulunmayan hallerde hem kasten hem de taksirle işlenebilir.","kaynak":"5326 m.9/1","zorluk":"kolay"},
    {"id":"5326-S-007","soru":"5326 sayılı Kabahatler Kanunu'na göre, fiili işlediği sırada kaç yaşını doldurmamış çocuk hakkında idarî para cezası uygulanamaz?","siklar":["On beş","On iki","On üç","On altı","On sekiz"],"dogru":0,"aciklama":"m.11/1: Fiili işlediği sırada onbeş yaşını doldurmamış çocuk hakkında idarî para cezası uygulanamaz.","kaynak":"5326 m.11/1","zorluk":"kolay"},
    {"id":"5326-S-008","soru":"5326 sayılı Kabahatler Kanunu'na göre kabahate teşebbüs, kural olarak cezalandırılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.13/1: Kabahate teşebbüs cezalandırılmaz. Ancak teşebbüsün de cezalandırılabileceğine dair ilgili kanunda hüküm bulunan haller saklıdır. Kural cezalandırmamadır.","kaynak":"5326 m.13/1","zorluk":"orta"},
    {"id":"5326-S-009","soru":"5326 sayılı Kabahatler Kanunu'na göre, bir kabahatin işlenişine birden fazla kişinin iştirak etmesi halinde bu kişilerin her biri hakkında hangi sıfatla idarî para cezası verilir?","siklar":["Azmettiren olarak","Yardım eden olarak","Fail olarak","Şerik olarak","Dolaylı fail olarak"],"dogru":2,"aciklama":"m.14/1: Kabahatin işlenişine birden fazla kişinin iştirak etmesi halinde bu kişilerin her biri hakkında, fail olarak idarî para cezası verilir. Kabahatlerde azmettiren/yardım eden ayrımı yapılmaz; iştirak edenlerin tamamı 'fail' sayılır.","kaynak":"5326 m.14/1","zorluk":"orta"},
    {"id":"5326-S-010","soru":"5326 sayılı Kabahatler Kanunu'na göre, aynı kabahatin aynı kişi tarafından birden fazla kez işlenmesi halinde idarî para cezası ne şekilde uygulanır?","siklar":["Sadece en ağır olan idarî para cezası verilir.","Her bir kabahatle ilgili olarak ayrı ayrı idarî para cezası verilir.","Tek bir idarî para cezası verilir, sayısı dikkate alınmaz.","İlk kabahatin cezası yarı oranında artırılarak verilir.","Cezaların toplamının yarısı oranında tek ceza verilir."],"dogru":1,"aciklama":"m.15/2: Aynı kabahatin birden fazla işlenmesi halinde her bir kabahatle ilgili olarak ayrı ayrı idarî para cezası verilir. (Kesintisiz fiille işlenebilen kabahatlerde, idarî yaptırım kararı verilinceye kadar fiil tek sayılır.)","kaynak":"5326 m.15/2","zorluk":"orta"},
    {"id":"5326-S-011","soru":"5326 sayılı Kabahatler Kanunu'na göre, bir fiil hem kabahat hem de suç olarak tanımlanmış ise, sadece ______ dolayı yaptırım uygulanabilir. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["kabahatten","suçtan","hem suç hem kabahatten","en ağır olandan","idarî yaptırımı gerektirenden"],"dogru":1,"aciklama":"m.15/3: Bir fiil hem kabahat hem suç olarak tanımlanmışsa sadece suçtan dolayı yaptırım uygulanır; suçtan yaptırım uygulanamayan hallerde kabahat dolayısıyla yaptırım uygulanır.","kaynak":"5326 m.15/3","zorluk":"orta"},
    {"id":"5326-S-012","soru":"5326 sayılı Kabahatler Kanunu'na göre, kabahatler karşılığında uygulanacak idarî yaptırımlardan biri aşağıdakilerden hangisi değildir?","siklar":["İdarî para cezası","İdarî tedbirler","Mülkiyetin kamuya geçirilmesi","İlgili kanunlarda yer alan diğer tedbirler","Hapis cezası"],"dogru":4,"aciklama":"m.16: İdarî yaptırımlar idarî para cezası ve idarî tedbirlerden ibarettir; idarî tedbirler ise mülkiyetin kamuya geçirilmesi ve ilgili kanunlardaki diğer tedbirlerdir. Hapis cezası kabahat yaptırımı değildir.","kaynak":"5326 m.16","zorluk":"orta"},
    {"id":"5326-S-013","soru":"5326 sayılı Kabahatler Kanunu'na göre idarî para cezası, ______ veya ______ olabilir. Boşluklara sırasıyla aşağıdakilerden hangisi gelmelidir?","siklar":["maktu / nispî","sabit / değişken","aslî / fer'î","adlî / idarî","peşin / taksitli"],"dogru":0,"aciklama":"m.17/1: İdarî para cezası, maktu (sabit) veya nispî (oransal) olabilir.","kaynak":"5326 m.17/1","zorluk":"kolay"},
    {"id":"5326-S-014","soru":"5326 sayılı Kabahatler Kanunu'na göre, ekonomik durumu müsait olmayan kişinin idarî para cezası, ilk taksitinin peşin ödenmesi koşuluyla nasıl ödenebilir?","siklar":["Altı ay içinde iki eşit taksit halinde","İki yıl içinde sekiz eşit taksit halinde","Bir yıl içinde üç eşit taksit halinde","Bir yıl içinde on iki eşit taksit halinde","Bir yıl içinde dört eşit taksit halinde"],"dogru":4,"aciklama":"m.17/3: Kişinin ekonomik durumu müsait değilse, ilk taksit peşin ödenmek koşuluyla bir yıl içinde ve dört eşit taksit halinde ödenmesine karar verilebilir. Taksitler zamanında ödenmezse kalan tamamı tahsil edilir.","kaynak":"5326 m.17/3","zorluk":"orta"},
    {"id":"5326-S-015","soru":"5326 sayılı Kabahatler Kanunu'na göre, idarî para cezasının ödeme süresi içinde ödenmesi halinde cezadan ne oranında indirim yapılır?","siklar":["%10","%15","%20","%25","%33"],"dogru":3,"aciklama":"m.17/6: İdarî para cezasının ödeme süresi içinde ödenmesi halinde cezadan %25 oranında indirim yapılır. Ödeme, kişinin kanun yoluna başvurma hakkını etkilemez.","kaynak":"5326 m.17/6","zorluk":"orta"},
    {"id":"5326-S-016","soru":"5326 sayılı Kabahatler Kanunu'na göre, idarî para cezasını ödeme süresi içinde indirimli olarak ödeyen kişi, bu karara karşı kanun yoluna başvurma hakkını kaybeder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.17/6: Ödeme yapılması, kişinin bu karara karşı kanun yoluna başvurma hakkını etkilemez. Hak kaybı yoktur; ifade yanlıştır.","kaynak":"5326 m.17/6","zorluk":"orta"},
    {"id":"5326-S-017","soru":"5326 sayılı Kabahatler Kanunu'na göre, nispî nitelikteki idarî para cezaları da her takvim yılı başından geçerli olmak üzere yeniden değerleme oranında artırılarak uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.17/7: İdarî para cezaları her yıl yeniden değerleme oranında artırılır; ancak bu hüküm nispî nitelikteki idarî para cezaları açısından uygulanmaz. İfade yanlıştır.","kaynak":"5326 m.17/7","zorluk":"zor"},
    {"id":"5326-S-018","soru":"5326 sayılı Kabahatler Kanunu'na göre, mülkiyeti kamuya geçirilen eşya, kanunda açık hüküm bulunmayan hallerde kime geçer?","siklar":["Devlete","İlgili belediyeye","Doğrudan Hazineye satılmak üzere","İlgili kamu kurum ve kuruluşuna","El koyan kolluk birimine"],"dogru":0,"aciklama":"m.18/4: Eşyanın mülkiyeti, kanunda açık hüküm bulunan hallerde ilgili kamu kurum ve kuruluşuna, aksi takdirde Devlete geçer.","kaynak":"5326 m.18/4","zorluk":"orta"},
    {"id":"5326-S-019","soru":"5326 sayılı Kabahatler Kanunu'na göre, eşyanın mülkiyetinin kamuya geçirilmesine karar verilebilmesi için fail hakkında idarî para cezası veya başka bir idarî yaptırım kararı verilmiş olması şart değildir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.18/5: Mülkiyetin kamuya geçirilmesine karar verilebilmesi için fail hakkında idarî para cezası veya başka bir idarî yaptırım kararı verilmiş olması şart değildir.","kaynak":"5326 m.18/5","zorluk":"orta"},
    {"id":"5326-S-020","soru":"5326 sayılı Kabahatler Kanunu'na göre, yüzbin Türk Lirası veya daha fazla idarî para cezasını gerektiren kabahatlerde soruşturma zamanaşımı süresi kaç yıldır?","siklar":["İki","Üç","Dört","Yedi","Beş"],"dogru":4,"aciklama":"m.20/2-a: Yüzbin TL veya daha fazla idarî para cezasını gerektiren kabahatlerde soruşturma zamanaşımı beş yıldır (50.000 TL ve fazlası: 4 yıl; 50.000 TL'den az: 3 yıl).","kaynak":"5326 m.20/2-a","zorluk":"orta"},
    {"id":"5326-S-021","soru":"5326 sayılı Kabahatler Kanunu'na göre, kabahati oluşturan fiilin aynı zamanda suç oluşturması halinde soruşturma zamanaşımı bakımından suça ilişkin dava zamanaşımı hükümleri uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.20/5: Kabahati oluşturan fiilin aynı zamanda suç oluşturması halinde suça ilişkin dava zamanaşımı hükümleri uygulanır. İfade doğrudur.","kaynak":"5326 m.20/5","zorluk":"orta"},
    {"id":"5326-S-022","soru":"5326 sayılı Kabahatler Kanunu'na göre, soruşturma zamanaşımı süreleri ile ilgili aşağıdaki eşleştirmelerden hangisi yanlıştır?","siklar":["Yüzbin TL veya daha fazla idarî para cezası → 5 yıl","Ellibin TL veya daha fazla idarî para cezası → 4 yıl","Yirmibin TL veya daha fazla idarî para cezası → 6 yıl","Nispî idarî para cezası → 8 yıl","Ellibin TL'den az idarî para cezası → 3 yıl"],"dogru":2,"aciklama":"m.20/2-3: Soruşturma zamanaşımı eşikleri 100.000→5, 50.000→4, 50.000'den az→3, nispî→8 yıldır. 'Yirmibin TL → 6 yıl' diye bir basamak yoktur; yanlıştır.","kaynak":"5326 m.20/2-3","zorluk":"zor"},
    {"id":"5326-S-023","soru":"5326 sayılı Kabahatler Kanunu'na göre, ellibin Türk Lirası veya daha fazla idarî para cezasına karar verilmesi halinde yerine getirme zamanaşımı süresi kaç yıldır?","siklar":["Yedi","Beş","Dört","Üç","On"],"dogru":0,"aciklama":"m.21/2-a: Ellibin TL veya daha fazla cezada yerine getirme zamanaşımı yedi yıldır (20.000→5, 10.000→4, 10.000'den az→3).","kaynak":"5326 m.21/2-a","zorluk":"orta"},
    {"id":"5326-S-024","soru":"5326 sayılı Kabahatler Kanunu'na göre, mülkiyetin kamuya geçirilmesine ilişkin yerine getirme zamanaşımı süresi kaç yıldır?","siklar":["Yedi","Sekiz","On","Beş","On beş"],"dogru":2,"aciklama":"m.21/3: Mülkiyetin kamuya geçirilmesine ilişkin yerine getirme zamanaşımı süresi on yıldır.","kaynak":"5326 m.21/3","zorluk":"orta"},
    {"id":"5326-S-025","soru":"5326 sayılı Kabahatler Kanunu'na göre, soruşturma ve yerine getirme zamanaşımı ile ilgili aşağıdaki bilgilerden hangisi yanlıştır?","siklar":["Soruşturma zamanaşımında nispî idarî para cezalarında süre 8 yıldır.","Yerine getirme zamanaşımında mülkiyetin kamuya geçirilmesi süresi 10 yıldır.","Yerine getirme zamanaşımı, kararın kesinleşmesinin rastladığı takvim yılını takip eden takvim yılı başından itibaren işlemeye başlar.","Soruşturma zamanaşımı, idarî yaptırım kararının tebliğ edildiği tarihten itibaren işlemeye başlar.","Ellibin TL veya daha fazla cezada yerine getirme zamanaşımı 7 yıldır."],"dogru":3,"aciklama":"m.20/4: Soruşturma zamanaşımı, fiilin işlenmesiyle veya neticenin gerçekleşmesiyle işlemeye başlar; tebliğ tarihiyle değil. Diğer şıklar m.20/3, m.21/2-a, m.21/3, m.21/4 metnine uygundur.","kaynak":"5326 m.20-21","zorluk":"zor"},
    {"id":"5326-S-026","soru":"5326 sayılı Kabahatler Kanunu'na göre, kabahat dolayısıyla idarî yaptırım kararı vermeye kanunda açık hüküm bulunmayan hallerde ______ yetkilidir. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["il valisi","Cumhuriyet savcısı","sulh ceza hâkimi","mülkî amir","ilgili kamu kurum ve kuruluşunun en üst amiri"],"dogru":4,"aciklama":"m.22/2: Kanunda açık hüküm bulunmayan hallerde ilgili kamu kurum ve kuruluşunun en üst amiri idarî yaptırım kararı vermeye yetkilidir.","kaynak":"5326 m.22/2","zorluk":"orta"},
    {"id":"5326-S-027","soru":"5326 sayılı Kabahatler Kanunu'na göre, kovuşturma konusu fiilin kabahat oluşturduğunun anlaşılması halinde idarî yaptırım kararını kim verir?","siklar":["Cumhuriyet savcısı","Mahkeme","Mülkî amir","Kolluk görevlileri","İlgili kurumun en üst amiri"],"dogru":1,"aciklama":"m.24/1: Kovuşturma konusu fiilin kabahat oluşturduğunun anlaşılması halinde mahkeme tarafından idarî yaptırım kararı verilir.","kaynak":"5326 m.24/1","zorluk":"kolay"},
    {"id":"5326-S-028","soru":"5326 sayılı Kabahatler Kanunu'na göre, idarî yaptırım kararına ilişkin tutanakta açıkça yazılması gereken hususlardan biri aşağıdakilerden hangisi değildir?","siklar":["Hakkında karar verilen kişinin kimlik ve adresi","Hakkında karar verilen kişinin adlî sicil (sabıka) kaydı","İdarî yaptırım kararı verilmesini gerektiren kabahat fiili","Fiilin işlendiğini ispata yarayacak bütün deliller","Karar tarihi ve kararı veren kamu görevlilerinin kimliği"],"dogru":1,"aciklama":"m.25/1: Tutanakta kimlik-adres, kabahat fiili, deliller, karar tarihi ve kararı veren görevlilerin kimliği yazılır; ayrıca fiilin yeri ve zamanı gösterilir. Adlî sicil (sabıka) kaydı tutanak unsuru değildir.","kaynak":"5326 m.25/1","zorluk":"orta"},
    {"id":"5326-S-029","soru":"5326 sayılı Kabahatler Kanunu'na göre, elektronik ortamda yapılan tebligat, muhatabın elektronik adresine ulaştığı tarihi izleyen kaçıncı günün sonunda yapılmış sayılır?","siklar":["Üçüncü","Beşinci","Yedinci","Onuncu","On beşinci"],"dogru":1,"aciklama":"m.26/4: Elektronik ortamda yapılan tebligat, muhatabın elektronik adresine ulaştığı tarihi izleyen beşinci günün sonunda yapılmış sayılır.","kaynak":"5326 m.26/4","zorluk":"orta"},
    {"id":"5326-S-030","soru":"5326 sayılı Kabahatler Kanunu'na göre, idarî para cezası ve mülkiyetin kamuya geçirilmesine ilişkin idarî yaptırım kararına karşı, kararın tebliği veya tefhimi tarihinden itibaren en geç ne kadar süre içinde sulh ceza mahkemesine başvurulabilir?","siklar":["Yedi gün","On gün","On beş gün","Otuz gün","İki ay"],"dogru":2,"aciklama":"m.27/1: Karara karşı tebliğ/tefhim tarihinden itibaren en geç onbeş gün içinde sulh ceza mahkemesine başvurulabilir; bu süre içinde başvurulmazsa karar kesinleşir.","kaynak":"5326 m.27/1","zorluk":"orta"},
    {"id":"5326-S-031","soru":"5326 sayılı Kabahatler Kanunu'na göre, mücbir sebep dolayısıyla başvuru süresinin geçirilmesi halinde, bu sebebin ortadan kalktığı tarihten itibaren en geç ne kadar süre içinde karara karşı başvuruda bulunulabilir?","siklar":["Yedi gün","Üç gün","On gün","On beş gün","Bir ay"],"dogru":0,"aciklama":"m.27/2: Mücbir sebebin varlığı dolayısıyla sürenin geçirilmesi halinde, sebebin ortadan kalktığı tarihten itibaren en geç yedi gün içinde başvuruda bulunulabilir.","kaynak":"5326 m.27/2","zorluk":"orta"},
    {"id":"5326-S-032","soru":"5326 sayılı Kabahatler Kanunu'na göre, kaç Türk Lirası dahil idarî para cezalarına karşı başvuru üzerine verilen kararlar kesindir?","siklar":["Üç bin","On bin","On beş bin","Yirmi bin","Elli bin"],"dogru":2,"aciklama":"m.28/10: Onbeşbin Türk Lirası dahil idarî para cezalarına karşı başvuru üzerine verilen kararlar kesindir; bu kararlara itiraz yolu kapalıdır.","kaynak":"5326 m.28/10","zorluk":"orta"},
    {"id":"5326-S-033","soru":"5326 sayılı Kabahatler Kanunu'na göre, mahkemenin verdiği son karara karşı, Ceza Muhakemesi Kanunu'na göre, kararın tebliği tarihinden itibaren en geç ne kadar süre içinde itiraz edilebilir?","siklar":["Yedi gün","On gün","On beş gün","İki hafta","Bir ay"],"dogru":3,"aciklama":"m.29/1: Mahkemenin son kararına karşı CMK'ya göre, kararın tebliğinden itibaren en geç iki hafta içinde itiraz edilir; itirazla ilgili karar dosya üzerinden verilir.","kaynak":"5326 m.29/1","zorluk":"orta"},
    {"id":"5326-S-034","soru":"5326 sayılı Kabahatler Kanunu'na göre, başvuru ve itiraz yolları ile ilgili aşağıdaki bilgilerden hangisi yanlıştır?","siklar":["Başvuru, kararın tebliği veya tefhiminden itibaren on beş gün içinde sulh ceza mahkemesine yapılır.","Mahkemenin son kararına itiraz, kararın tebliğinden itibaren on beş gün içinde yapılır.","Başvuru dilekçesi iki nüsha olarak verilir.","İtirazla ilgili karar, dosya üzerinden inceleme yapılarak verilir.","İtiraz, Ceza Muhakemesi Kanunu'na göre yapılır."],"dogru":1,"aciklama":"m.29/1: İtiraz iki hafta içinde yapılır, on beş gün değil. On beş günlük süre m.27/1'deki başvuru süresidir. Diğer şıklar m.27/1, m.27/3 ve m.29 metnine uygundur.","kaynak":"5326 m.27-29","zorluk":"zor"},
    {"id":"5326-S-035","soru":"5326 sayılı Kabahatler Kanunu'na göre, kamu güvenliği, kamu düzeni veya genel sağlığın korunması amacıyla hukuka uygun olarak verilen emre aykırı hareket eden kişiye verilecek idarî para cezasına kim karar verir?","siklar":["Cumhuriyet savcısı","Sulh ceza mahkemesi","Emri veren makam","İl valisi","Belediye encümeni"],"dogru":2,"aciklama":"m.32/1: Emre aykırı hareket eden kişiye idarî para cezası verilir ve bu cezaya emri veren makam tarafından karar verilir (uygulamada genelde mülkî amir).","kaynak":"5326 m.32/1","zorluk":"orta"},
    {"id":"5326-S-036","soru":"5326 sayılı Kabahatler Kanunu'na göre, dilencilik ve kumar kabahatlerinde yetkili makamlarla ilgili aşağıdaki bilgilerden hangisi yanlıştır?","siklar":["Dilencilik nedeniyle idarî para cezasına ve elkoymaya kolluk veya belediye zabıta görevlileri karar verir.","Dilencilikte mülkiyetin kamuya geçirilmesine mülkî amir veya belediye encümeni karar verir.","Kumar oynayan kişiye idarî para cezasına ve elkoymaya kolluk görevlileri karar verir.","Kumardan elde edilen gelirin mülkiyetinin kamuya geçirilmesine belediye encümeni karar verir.","Hem dilencilikten hem kumardan elde edilen gelire elkonularak mülkiyetin kamuya geçirilmesine karar verilir."],"dogru":3,"aciklama":"m.34/2: Kumarda mülkiyetin kamuya geçirilmesine mülkî amir karar verir; belediye encümeni yetkili değildir. Belediye encümeni yalnızca dilencilikte (m.33/2) mülkî amirin yanında alternatif yetkilidir.","kaynak":"5326 m.33-34","zorluk":"zor"},
    {"id":"5326-S-037","soru":"5326 sayılı Kabahatler Kanunu'na göre, 112 Acil Çağrı Merkezini meşgul etmek veya merkeze asılsız ihbarda bulunmak fiillerinde idarî para cezasına kim karar verir?","siklar":["Cumhuriyet savcısı","Kolluk görevlileri","Sulh ceza mahkemesi","Belediye encümeni","İl valileri"],"dogru":4,"aciklama":"m.42/A: 112 Acil Çağrı Merkezini meşgul etme ve asılsız ihbar fiillerinde idarî para cezasına il valileri karar verir; bu fiillerin bir yıl içinde tekrarı halinde ceza iki katı uygulanır.","kaynak":"5326 m.42/A","zorluk":"orta"},
    {"id":"5326-S-038","soru":"5326 sayılı Kabahatler Kanunu'na göre, bir tüzel kişinin yararına dolandırıcılık, rüşvet, ihaleye fesat karıştırma gibi suçların organ veya temsilci tarafından işlenmesi halinde, tüzel kişiye verilecek idarî para cezasına kim karar verir?","siklar":["Cumhuriyet savcısı","İl valisi","İlgili kurumun en üst amiri","Mülkî amir","Yargılama yapmakla görevli mahkeme"],"dogru":4,"aciklama":"m.43/A: Sayılan suçların tüzel kişi yararına işlenmesi halinde tüzel kişiye idarî para cezasına yargılama yapmakla görevli mahkeme karar verir; ceza menfaatin iki katından az olamaz.","kaynak":"5326 m.43/A","zorluk":"orta"},
    {"id":"5326-OO-001","soru":"A, bir kahvehanede para karşılığı kâğıt oyunu (kumar) oynarken kolluk tarafından suçüstü yakalanır ve masada bulunan paraya el konulur. Kumardan elde edilen bu paranın mülkiyetinin kamuya geçirilmesine kim karar verir?","siklar":["Belediye encümeni","Mülkî amir","Kolluk görevlileri","Sulh ceza hâkimi","Belediye zabıta görevlileri"],"dogru":1,"aciklama":"m.34/2: Kumar kabahatinde idarî para cezasına ve elkoymaya kolluk görevlileri, mülkiyetin kamuya geçirilmesine ise mülkî amir karar verir. Kumarda belediye encümeni yetkili değildir.","kaynak":"5326 m.34/2","zorluk":"orta"},
    {"id":"5326-OO-002","soru":"B, kalabalık bir meydanda para toplayarak dilencilik yapmaktadır. Bu fiil nedeniyle B'ye idarî para cezası verilmesine ve topladığı paraya el konulmasına kim karar verir?","siklar":["Yalnızca mülkî amir","Cumhuriyet savcısı","Kolluk veya belediye zabıta görevlileri","Belediye encümeni","Sulh ceza mahkemesi"],"dogru":2,"aciklama":"m.33/2: Dilencilik kabahatinde idarî para cezasına ve elkoymaya kolluk veya belediye zabıta görevlileri karar verir; yalnızca mülkiyetin kamuya geçirilmesine mülkî amir veya belediye encümeni karar verir.","kaynak":"5326 m.33/2","zorluk":"orta"},
    {"id":"5326-OO-003","soru":"Görevle bağlantılı olarak kimliğini soran kamu görevlisine C, gerçeğe aykırı beyanda bulunur ve kimliği bir türlü belirlenemez. Bu durumda kanun gereği ne yapılır?","siklar":["Doğrudan tutuklanarak hâkim önüne çıkarılır","Sadece idarî para cezası verilip serbest bırakılır","Durumdan derhâl Cumhuriyet savcısı haberdar edilir; kişi kimliği açıkça anlaşılıncaya kadar gözaltına alınır","Sulh ceza mahkemesine sevk edilir","Mülkî amirin kararıyla bir aya kadar idarî gözetime alınır"],"dogru":2,"aciklama":"m.40/2: Kimliği belirlenemeyen kişi tutularak durumdan derhâl Cumhuriyet savcısı haberdar edilir; kişi kimliği açık şekilde anlaşılıncaya kadar gözaltına alınır ve gerekirse tutuklanır. Tutuklama ancak gerektiğinde ve usulüne göre devreye girer.","kaynak":"5326 m.40/2","zorluk":"orta"},
    {"id":"5326-OO-004","soru":"D, sarhoş hâlde sokakta bağırıp çağırarak çevredekilerin huzur ve sükûnunu bozar. Kolluk görevlileri kendisine idarî para cezası verir. D'ye ayrıca uygulanacak tedbir aşağıdakilerden hangisidir?","siklar":["Adlî kontrol","Sarhoşluğun etkisi geçinceye kadar kontrol altında tutulma","Yurt dışı çıkış yasağı","Bir aya kadar gözaltı","Mülkiyetin kamuya geçirilmesi"],"dogru":1,"aciklama":"m.35/1: Sarhoş olarak başkalarının huzur ve sükûnunu bozacak şekilde davranan kişiye kolluk idarî para cezası verir; kişi ayrıca sarhoşluğun etkisi geçinceye kadar kontrol altında tutulur.","kaynak":"5326 m.35/1","zorluk":"kolay"},
    {"id":"5326-OO-005","soru":"E'nin tek bir fiili, bir kanunda kabahat, Türk Ceza Kanunu'nda ise suç olarak tanımlanmıştır ve bu fiilden dolayı suçtan yaptırım uygulanması mümkündür. Bu durumda E hakkında ne yapılır?","siklar":["Hem suçtan hem kabahatten ayrı ayrı yaptırım uygulanır","Sadece kabahatten dolayı idarî yaptırım uygulanır","Sadece suçtan dolayı yaptırım uygulanır","En ağır olan yaptırım uygulanır","Yaptırımların yarısı oranında tek yaptırım uygulanır"],"dogru":2,"aciklama":"m.15/3: Bir fiil hem kabahat hem suç olarak tanımlanmışsa sadece suçtan dolayı yaptırım uygulanır. Yalnızca suçtan yaptırım uygulanamayan hallerde kabahat dolayısıyla yaptırım gündeme gelir.","kaynak":"5326 m.15/3","zorluk":"orta"},
    {"id":"5326-OO-006","soru":"A ve B önceden anlaşarak aynı kabahati birlikte işlerler. Bu kişiler hakkında idarî para cezası hangi şekilde verilir?","siklar":["Biri fail, diğeri azmettiren sayılarak farklı oranlarda","Her biri hakkında fail olarak ayrı ayrı","Sadece fiili fiilen gerçekleştiren kişiye","İkisine toplam tek bir ceza paylaştırılarak","Yardım eden konumundaki kişiye indirimli olarak"],"dogru":1,"aciklama":"m.14/1: Bir kabahatin işlenişine birden fazla kişinin iştirak etmesi halinde her biri hakkında fail olarak idarî para cezası verilir. Kabahatlerde azmettiren/yardım eden ayrımı ve buna bağlı indirim yoktur.","kaynak":"5326 m.14/1","zorluk":"orta"},
    {"id":"5326-OO-007","soru":"Bir gerçek kişiye ait işyerinde çalışan A, bu faaliyet çerçevesinde bir kabahat işler. Bu durumda kimler hakkında idarî yaptırım uygulanabilir?","siklar":["Sadece çalışan A","Sadece iş sahibi","Hem çalışan A hem de iş sahibi kişi","Sadece işyerinin bağlı olduğu meslek odası","Hiç kimse, çünkü kabahat iş gereği işlenmiştir"],"dogru":2,"aciklama":"m.8/2: Gerçek kişiye ait bir işte çalışanın bu faaliyet çerçevesinde işlediği kabahatten dolayı iş sahibi hakkında da idarî yaptırım uygulanabilir. Fiili işleyen çalışanın sorumluluğu zaten devam eder; sorumluluk iş sahibine 'de' uzanır.","kaynak":"5326 m.8/2","zorluk":"orta"},
    {"id":"5326-OO-008","soru":"Fiili işlediği sırada 14 yaşında olan A, idarî para cezası öngörülen bir kabahat işler. A hakkında ne uygulanır?","siklar":["İdarî para cezası uygulanamaz","İdarî para cezası yarı oranında uygulanır","Tam idarî para cezası uygulanır","Ceza, A'nın veli veya vasisine uygulanır","Mülkiyetin kamuya geçirilmesine karar verilir"],"dogru":0,"aciklama":"m.11/1: Fiili işlediği sırada onbeş yaşını doldurmamış çocuk hakkında idarî para cezası uygulanamaz. A 14 yaşında olduğundan bu yaş eşiğinin altındadır.","kaynak":"5326 m.11/1","zorluk":"kolay"},
    {"id":"5326-OO-009","soru":"A, belediye sınırları dışındaki bir karayolu kenarına evsel atıklarını döker. Bu kabahat dolayısıyla idarî para cezasına kim karar verir?","siklar":["Belediye zabıta görevlileri","Kolluk görevlileri","Mülkî amir","Belediye encümeni","Karayolları bölge müdürlüğü"],"dogru":1,"aciklama":"m.41/7: Çevreyi kirletme kabahatlerinde idarî para cezasına belediye sınırları içinde belediye zabıta görevlileri, belediye sınırları dışında kolluk görevlileri karar verir. Olay belediye sınırları dışında geçtiği için yetkili kolluktur.","kaynak":"5326 m.41/7","zorluk":"orta"},
    {"id":"5326-OO-010","soru":"A, bir yıl içinde ikinci kez 112 Acil Çağrı Merkezine asılsız ihbarda bulunur ve ihbarın asılsız olduğu olay yerine giden ekiplerce tutanakla tespit edilir. Bu fiil için aşağıdakilerden hangisi uygulanır?","siklar":["İdarî para cezası il valileri tarafından iki katı olarak uygulanır","Cumhuriyet savcısı tarafından adlî para cezası verilir","Kolluk tarafından tek kat idarî para cezası verilir","Sadece yazılı uyarı yapılır","Sulh ceza mahkemesi tarafından hapis cezası verilir"],"dogru":0,"aciklama":"m.42/A: Asılsız ihbarın ekiplerce tutanakla tespiti halinde idarî para cezasına il valileri karar verir (fıkra 2); maddedeki fiillerin bir yıl içinde tekrarı halinde idarî para cezası iki katı olarak uygulanır (fıkra 3).","kaynak":"5326 m.42/A","zorluk":"zor"},
    {"id":"5326-OO-011","soru":"Bir şirketin temsilcisi, şirketin yararına ihaleye fesat karıştırma suçunu işler. Şirkete verilecek idarî para cezası bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Cezaya Cumhuriyet savcısı karar verir","Cezaya yargılama yapmakla görevli mahkeme karar verir ve ceza, işleme konu menfaatin iki katından az olamaz","Şirkete idarî yaptırım uygulanamaz; sadece gerçek kişi cezalandırılır","Cezaya mülkî amir karar verir","Ceza, elde edilen menfaatin yarısı oranında belirlenir"],"dogru":1,"aciklama":"m.43/A: Sayılan suçların (dolandırıcılık, rüşvet, ihaleye fesat karıştırma vb.) tüzel kişi yararına işlenmesi halinde tüzel kişiye idarî para cezasına yargılama yapmakla görevli mahkeme karar verir; ceza, işleme veya eyleme konu menfaatin iki katından az olamaz.","kaynak":"5326 m.43/A","zorluk":"zor"},
    {"id":"5326-OO-012","soru":"Cumhuriyet savcısı, bir suç dolayısıyla başlattığı soruşturma kapsamında ayrıca bir kabahatin de işlendiğini öğrenir. Savcının bu konudaki yetkisiyle ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Yalnızca ilgili kamu kurum ve kuruluşuna bildirebilir, kendisi karar veremez","Durumu ilgili kuruma bildirebileceği gibi kendisi de idarî yaptırım kararı verebilir","Sadece sulh ceza mahkemesine sevk edebilir","Kabahat hakkında hiçbir işlem yapamaz","Yalnızca mülkî amire bildirmekle yükümlüdür"],"dogru":1,"aciklama":"m.23/2: Bir suç dolayısıyla başlatılan soruşturma kapsamında bir kabahatin işlendiğini öğrenen Cumhuriyet savcısı, durumu ilgili kamu kurum ve kuruluşuna bildirebileceği gibi kendisi de idarî yaptırım kararı verebilir.","kaynak":"5326 m.23/2","zorluk":"orta"},
  ],
  7: [
    {"id":"3713-S-001","soru":"3713 sayılı Terörle Mücadele Kanunu'nun 1. maddesindeki terör tanımına göre, aşağıdakilerden hangisi terörün gerçekleşmesinde sayılan yöntemlerden biri DEĞİLDİR?","siklar":["Baskı","Korkutma","Kandırma","Yıldırma","Sindirme"],"dogru":2,"aciklama":"m.1: terör 'baskı, korkutma, yıldırma, sindirme veya tehdit yöntemlerinden biriyle' işlenir. Sayılan yöntemler baskı, korkutma, yıldırma, sindirme ve tehdittir; 'kandırma' bu listede yer almaz.","kaynak":"3713 m.1","zorluk":"orta"},
    {"id":"3713-S-002","soru":"3713 m.1'e göre terör; cebir ve şiddet kullanarak; baskı, korkutma, yıldırma, sindirme veya tehdit yöntemlerinden ____ girişilecek her türlü suç teşkil eden eylemlerdir. Boşluğa gelmesi gereken ifade aşağıdakilerden hangisidir?","siklar":["biriyle","en az ikisiyle birlikte","tamamıyla","en az üçüyle","dördüyle birden"],"dogru":0,"aciklama":"m.1 metni 'yöntemlerinden biriyle' der; sayılan beş yöntemden yalnızca birinin kullanılması terörün yöntem unsuru için yeterlidir.","kaynak":"3713 m.1","zorluk":"orta"},
    {"id":"3713-S-003","soru":"3713 sayılı Kanun'a göre terörün tanımı için baskı, korkutma, yıldırma, sindirme ve tehdit yöntemlerinin tamamının birlikte kullanılması şarttır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.1 'yöntemlerinden biriyle' ifadesini kullanır; yöntemlerden yalnızca birinin kullanılması yeterlidir, tamamının birlikte kullanılması gerekmez.","kaynak":"3713 m.1","zorluk":"kolay"},
    {"id":"3713-S-004","soru":"3713 sayılı Terörle Mücadele Kanunu'nun 2. maddesine göre aşağıdakilerden hangisi terör suçlusu sayılır?","siklar":["Yalnızca terör örgütünü kuran kişi","Yalnızca üzerinde silah bulunan kişi","Sadece amaçlanan suçu fiilen işlemiş olan örgüt mensubu","Terör örgütüne mensup olmasa dahi örgüt adına suç işleyen kişi","Terörle ilgili haber yapan gazeteci"],"dogru":3,"aciklama":"m.2 son cümle: 'Terör örgütüne mensup olmasa dahi örgüt adına suç işleyenler de terör suçlusu sayılır.' Ayrıca örgüt mensubu olup amaçlanan suçu işlemese dahi mensup olan da terör suçlusudur.","kaynak":"3713 m.2","zorluk":"orta"},
    {"id":"3713-S-005","soru":"3713 m.2'ye göre, terör örgütünün mensubu olan kişi amaçlanan suçu işlemese dahi terör suçlusu sayılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.2: '...amaçlanan suçu işlemese dahi örgütlerin mensubu olan kişi terör suçlusudur.'","kaynak":"3713 m.2","zorluk":"orta"},
    {"id":"3713-S-006","soru":"3713 m.3'e göre aşağıdaki Türk Ceza Kanunu suçlarından hangisi, bir terör örgütünün faaliyeti çerçevesinde işlenmesi şartı aranmaksızın DOĞRUDAN terör suçudur?","siklar":["Kasten yaralama (TCK m. 86)","Yabancı hizmetine asker yazma, yazılma (TCK m. 320)","Tehdit (TCK m. 106)","Mala zarar verme (TCK m. 151)","Hakaret (TCK m. 125)"],"dogru":1,"aciklama":"m.3, TCK 302, 307, 309, 311, 312, 313, 314, 315 ve 320 nci maddeleri ile 310/1'i doğrudan terör suçu sayar. TCK 320 (yabancı hizmetine asker yazma) bu listededir; kasten yaralama (86), tehdit (106) ve mala zarar verme (151) ancak m.4'e göre örgüt faaliyeti çerçevesinde işlenirse terör suçudur; hakaret (125) ise hiçbir listede yer almaz.","kaynak":"3713 m.3","zorluk":"orta"},
    {"id":"3713-S-007","soru":"3713 m.3'te sayılan doğrudan terör suçları dikkate alındığında, aşağıdaki Türk Ceza Kanunu maddelerinden hangisi bu DOĞRUDAN terör suçları arasında YER ALMAZ?","siklar":["Devletin birliğini ve ülke bütünlüğünü bozmak (TCK m. 302)","Anayasayı ihlal (TCK m. 309)","Kasten yaralama (TCK m. 86)","Silahlı terör örgütü kurma, yönetme veya üye olma (TCK m. 314)","Yasama organına karşı suç (TCK m. 311)"],"dogru":2,"aciklama":"302, 309, 314 ve 311 m.3'te sayılı doğrudan terör suçlarıdır. Kasten yaralama (TCK 86) ise m.3'te değil, m.4/a kapsamındadır; ancak terör örgütünün faaliyeti çerçevesinde işlenirse terör suçu sayılır. Bu nedenle 'doğrudan' listede yer almaz.","kaynak":"3713 m.3","zorluk":"zor"},
    {"id":"3713-S-008","soru":"3713 sayılı Kanun'un 4. maddesine göre aşağıdaki suçlardan hangisi, ancak bir terör örgütünün faaliyeti çerçevesinde işlendiği takdirde terör suçu sayılır?","siklar":["Anayasayı ihlal (TCK m. 309)","6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanun'da tanımlanan suçlar","Silahlı terör örgütü kurma (TCK m. 314)","Devletin birliğini ve ülke bütünlüğünü bozmak (TCK m. 302)","Silahlı isyan (TCK m. 313)"],"dogru":1,"aciklama":"m.4/b: 6136 sayılı Kanun'da tanımlanan suçlar, terör örgütünün faaliyeti çerçevesinde işlendiği takdirde terör suçu sayılır. 309, 314, 302 ve 313 ise m.3'te sayılı doğrudan terör suçlarıdır.","kaynak":"3713 m.4","zorluk":"zor"},
    {"id":"3713-S-009","soru":"3713 m.4'e göre maddede sayılan suçlar, 1. maddede belirtilen amaçlar doğrultusunda suç işlemek üzere kurulmuş bir terör örgütünün ____ işlendiği takdirde terör suçu sayılır. Boşluğa gelecek ifade aşağıdakilerden hangisidir?","siklar":["yöneticisinin talimatıyla","bilgisi dâhilinde","faaliyeti çerçevesinde","menfaatine olacak şekilde","çağrısı üzerine"],"dogru":2,"aciklama":"m.4: '...bir terör örgütünün faaliyeti çerçevesinde işlendiği takdirde, terör suçu sayılır.' Ayırt edici kilit ifade 'faaliyeti çerçevesinde'dir.","kaynak":"3713 m.4","zorluk":"orta"},
    {"id":"3713-S-010","soru":"3713 m.4'e göre, terör örgütünün faaliyeti çerçevesinde işlendiğinde terör suçu sayılan suçlardan biri DEĞİLDİR?","siklar":["6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanun'da tanımlanan suçlar","6831 sayılı Orman Kanunu'nun ilgili fıkralarında tanımlanan kasten orman yakma suçları","2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanunu'nun 68. maddesinde tanımlanan suç","5816 sayılı Atatürk Aleyhine İşlenen Suçlar Hakkında Kanun'da tanımlanan suçlar","Anayasa'nın 120. maddesi gereğince olağanüstü hâl ilan edilen bölgelerde, olağanüstü hâlin ilanına neden olan olaylara ilişkin suçlar"],"dogru":3,"aciklama":"m.4'ün bentlerinde 6136 (b), 6831 Orman 110/4-5 kasten orman yakma (c), 4926 Kaçakçılık (ç), Anayasa 120 OHAL (d) ve 2863/68 (e) sayılır. 5816 sayılı Atatürk Aleyhine İşlenen Suçlar Hakkında Kanun m.4 kapsamında yer almaz.","kaynak":"3713 m.4","zorluk":"zor"},
    {"id":"3713-S-011","soru":"3713 m.15'e göre, terörle mücadelede görev alan personele görevinden doğan soruşturma ve kovuşturmalarda avukatlık ücreti ödenmesine ilişkin esas ve usuller aşağıdakilerden hangisiyle düzenlenir?","siklar":["Yalnızca İçişleri Bakanlığınca çıkarılan yönetmelikle","Yalnızca Adalet Bakanlığınca çıkarılan yönetmelikle","Milli Savunma ile İçişleri bakanlıklarınca müştereken çıkarılan yönetmelikle","Cumhurbaşkanınca çıkarılan yönetmelikle","Türkiye Büyük Millet Meclisince çıkarılan kanunla"],"dogru":2,"aciklama":"m.15: avukatlık ücreti ödenmesine ilişkin esas ve usuller Milli Savunma ile İçişleri bakanlıklarınca müştereken çıkarılan yönetmelikle düzenlenir. (En fazla 3 avukat; davacıya 1 avukat ücreti ilgili Bakan onayına tabidir.)","kaynak":"3713 m.15","zorluk":"orta"},
    {"id":"3713-S-012","soru":"3713 m.19'a göre, bu Kanun kapsamına giren suçun ortaya çıkarılmasına, delillerin ele geçirilmesine ya da faillerin yakalanmasına yardımcı olanlara para ödülü verilebilmesi için aşağıdakilerden hangisi aranır?","siklar":["Yardımcı olanın suçun işlenişine iştirak etmemiş olması","Yardımcı olanın kamu görevlisi olması","Yardımın en az iki failin yakalanmasını sağlaması","Ödüle hak kazananın terör mağduru olması","Yardımın yazılı dilekçe ile yapılmış olması"],"dogru":0,"aciklama":"m.19: para ödülü, 'suçun işlenişine iştirak etmemiş olmak koşuluyla' yardımcı olanlara veya yer/kimlik bildirenlere verilebilir. Ödül takdiridir ('verilir' değil 'verilebilir') ve usulü İçişleri Bakanlığı yönetmeliğiyle belirlenir.","kaynak":"3713 m.19","zorluk":"orta"},
    {"id":"3713-S-013","soru":"3713 m.20'ye göre kamu görevlileri, görevlerinden ayrılmış olsalar dahi, aşağıdakilerden hangisine yönelik bir taarruzu savmak için silah kullanmaya yetkilidir?","siklar":["Yalnızca kendi canına","Kendisinin veya eş ve çocuklarının canına","Yalnızca görevdeki meslektaşlarının canına","Sadece koruma altındaki kamu binalarına","Yalnızca eşinin canına"],"dogru":1,"aciklama":"m.20: kamu görevlileri, görevlerinden ayrılmış olsalar dahi, kendilerine veya eş ve çocuklarının canına yönelik bir taarruzu savmak için silah kullanmaya yetkilidir.","kaynak":"3713 m.20","zorluk":"orta"},
    {"id":"3713-S-014","soru":"3713 m.21'e göre, görevini ifa ederken veya bu görevinden dolayı yaralanan, engelli hâle gelen, ölen veya öldürülen kamu görevlileri hakkında aşağıdaki kanunlardan hangisi uygulanır?","siklar":["5434 sayılı Emekli Sandığı Kanunu","657 sayılı Devlet Memurları Kanunu","5510 sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu","2330 sayılı Nakdi Tazminat ve Aylık Bağlanması Hakkında Kanun","211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanunu"],"dogru":3,"aciklama":"m.21: bu kapsamdaki kamu görevlileri hakkında 2330 sayılı Nakdi Tazminat ve Aylık Bağlanması Hakkında Kanun uygulanır. Ayrıca malul, şehit dul ve yetimlerine 30 yıl hizmet yapmış gibi emekli ikramiyesi ödenir; kamu konutundan 10 yıl kira alınmaksızın yararlandırılır.","kaynak":"3713 m.21","zorluk":"orta"},
    {"id":"3713-S-015","soru":"3713 m.22'ye göre, terör eylemleri nedeniyle can ve mal kaybına uğrayan vatandaşlara öncelikle aşağıdaki kaynakların hangisinden yardım yapılır?","siklar":["Genel bütçeden doğrudan ödeme yoluyla","Sosyal Yardımlaşma ve Dayanışmayı Teşvik Fonundan","Afet ve Acil Durum Yönetimi Başkanlığı bütçesinden","İl özel idaresi bütçesinden","Türk Kızılay bağışlarından"],"dogru":1,"aciklama":"m.22: can ve mal kaybına uğrayan vatandaşlara Sosyal Yardımlaşma ve Dayanışmayı Teşvik Fonundan öncelikle yardım yapılır. Yardımın ölçüsü Fon Kurulunca tespit edilir.","kaynak":"3713 m.22","zorluk":"orta"},
    {"id":"3713-S-016","soru":"3713 Ek Madde 2'ye göre, terör örgütlerine karşı icra edilen operasyonlarda 'teslim ol' emrine itaat edilmemesi veya silah kullanmaya teşebbüs edilmesi hâlinde kolluk görevlilerinin silah kullanma yetkisi nasıl nitelendirilmiştir?","siklar":["Sınırsız ve koşulsuz silah kullanma yetkisi","Yalnızca havaya uyarı atışı yapma yetkisi","Tehlikeyi etkisiz kılabilecek ölçü ve orantıda, doğrudan ve duraksamadan hedefe karşı silah kullanma yetkisi","Yalnızca amirin yazılı izni alındıktan sonra silah kullanma yetkisi","Yalnızca gece operasyonlarında silah kullanma yetkisi"],"dogru":2,"aciklama":"Ek Madde 2: kolluk görevlileri tehlikeyi etkisiz kılabilecek ölçü ve orantıda, doğrudan ve duraksamadan hedefe karşı silah kullanmaya yetkilidir. İki koşuldan ('teslim ol'a itaatsizlik veya silaha teşebbüs) herhangi biri tek başına yeterlidir; yetki ölçü ve orantıyla sınırlıdır.","kaynak":"3713 Ek Madde 2","zorluk":"zor"},
    {"id":"3713-S-017","soru":"3713 m.7'ye göre, terör örgütü kuranlar, yönetenler ile bu örgüte üye olanlar hangi Türk Ceza Kanunu maddesi hükümlerine göre cezalandırılır?","siklar":["TCK m. 314","TCK m. 302","TCK m. 220","TCK m. 309","TCK m. 310"],"dogru":0,"aciklama":"m.7: terör örgütü kuran, yöneten ve üye olanlar 'Türk Ceza Kanununun 314 üncü maddesi hükümlerine göre cezalandırılır.' Örgütün faaliyetini düzenleyenler de yönetici olarak cezalandırılır.","kaynak":"3713 m.7","zorluk":"orta"},
    {"id":"3713-S-018","soru":"3713 m.7'ye göre, terör örgütünün cebir, şiddet veya tehdit içeren yöntemlerini meşru gösterecek ya da övecek şekilde propagandasını yapan kişi ne kadar hapis cezası ile cezalandırılır?","siklar":["Altı aydan iki yıla kadar","Bir yıldan üç yıla kadar","Bir yıldan beş yıla kadar","İki yıldan beş yıla kadar","Üç yıldan yedi yıla kadar"],"dogru":2,"aciklama":"m.7: propaganda yapan kişi 'bir yıldan beş yıla kadar hapis cezası ile cezalandırılır.'","kaynak":"3713 m.7","zorluk":"orta"},
    {"id":"3713-S-019","soru":"3713 m.7'ye göre, terör örgütünün propagandası suçunun basın ve yayın yolu ile işlenmesi hâlinde verilecek ceza yarı oranında artırılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.7: 'Bu suçun basın ve yayın yolu ile işlenmesi hâlinde, verilecek ceza yarı oranında artırılır.'","kaynak":"3713 m.7","zorluk":"orta"},
    {"id":"3713-S-020","soru":"3713 m.7'ye göre, terör örgütünün propagandasına dönüştürülen toplantı ve gösteri yürüyüşlerinde, kimliklerini gizlemek amacıyla yüzünü tamamen veya kısmen kapatanlar ne kadar hapis cezasıyla cezalandırılır?","siklar":["Bir yıldan üç yıla kadar","Bir yıldan beş yıla kadar","İki yıldan dört yıla kadar","Üç yıldan beş yıla kadar","Dört yıldan sekiz yıla kadar"],"dogru":3,"aciklama":"m.7: yüzünü tamamen veya kısmen kapatanlar 'üç yıldan beş yıla kadar hapis cezasıyla cezalandırılır.' Bu kişilerin cebir-şiddete başvurması ya da silah/molotof bulundurması/kullanması hâlinde cezanın alt sınırı dört yıldan az olamaz.","kaynak":"3713 m.7","zorluk":"zor"},
    {"id":"3713-S-021","soru":"3713 sayılı Kanun'un 3. maddesindeki suçlar ile 4. maddesindeki suçlar arasındaki temel fark aşağıdakilerden hangisidir?","siklar":["m.3 suçları yalnızca çocuklara, m.4 suçları yalnızca yetişkinlere uygulanır","m.3 suçları şart aranmaksızın doğrudan terör suçudur; m.4 suçları ancak terör örgütünün faaliyeti çerçevesinde işlenirse terör suçu sayılır","m.3 suçları örgüt faaliyeti çerçevesinde işlenirse, m.4 suçları ise doğrudan terör suçudur","İki madde arasında hiçbir fark yoktur; her ikisi de aynı suçları sayar","m.3 yalnızca propaganda, m.4 yalnızca terörün finansmanı suçlarını düzenler"],"dogru":1,"aciklama":"m.3'teki TCK suçları herhangi bir şart aranmadan doğrudan terör suçudur; m.4'teki suçlar ise yalnızca bir terör örgütünün faaliyeti çerçevesinde işlendiğinde terör suçu sayılır. Ayırt edici kilit 'örgüt faaliyeti çerçevesinde' şartıdır.","kaynak":"3713 m.3 - m.4","zorluk":"zor"},
    {"id":"3713-S-022","soru":"3713 sayılı Kanun açısından Türk Ceza Kanunu'nun 310. maddesi ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Maddenin hem birinci hem ikinci fıkrası m.4 kapsamında şartlı terör suçudur","Maddenin hem birinci hem ikinci fıkrası m.3 kapsamında doğrudan terör suçudur","Birinci fıkra m.4'te, ikinci fıkra m.3'tedir","TCK 310. maddesi 3713'ün kapsamı dışındadır","Birinci fıkra m.3 kapsamında doğrudan terör suçu; ikinci fıkra m.4 kapsamında örgüt faaliyeti çerçevesinde işlenirse terör suçudur"],"dogru":4,"aciklama":"m.3, TCK 310. maddesinin 'birinci fıkrasında yazılı suçlar'ı doğrudan terör suçu sayar. m.4/a ise '310 uncu maddesinin ikinci fıkrasında yer alan suçlar'ı örgüt faaliyeti çerçevesinde işlenmesi şartına bağlar.","kaynak":"3713 m.3 - m.4","zorluk":"zor"},
    {"id":"3713-OO-001","soru":"A, herhangi bir terör örgütüne üye değildir; ancak bir terör örgütünün talimatıyla, o örgüt adına bir kamu binasına saldırı düzenler. A'nın bu fiildeki hukuki durumu 3713 sayılı Kanun'a göre aşağıdakilerden hangisidir?","siklar":["Örgüte üye olmadığı için terör suçlusu sayılmaz, yalnızca adi suç faili olur","Örgüte mensup olmasa dahi örgüt adına suç işlediği için terör suçlusu sayılır","Yalnızca örgütün yöneticisi konumuna gelirse terör suçlusu sayılır","Ancak örgüte resmen kaydolduğu ispatlanırsa terör suçlusu sayılır","Yalnızca eylemde silah kullanmışsa terör suçlusu sayılır"],"dogru":1,"aciklama":"m.2: 'Terör örgütüne mensup olmasa dahi örgüt adına suç işleyenler de terör suçlusu sayılır.' A üye olmasa da örgüt adına suç işlediği için terör suçlusudur.","kaynak":"3713 m.2","zorluk":"orta"},
    {"id":"3713-OO-002","soru":"B, bir terör örgütünün mensubudur. Örgütün planladığı eylemde kendisine verilen görevi henüz hiç yerine getirmemiş, amaçlanan suçu fiilen işlememiştir. B'nin 3713 sayılı Kanun'a göre durumu nedir?","siklar":["Hiçbir suç işlemediği için terör suçlusu sayılmaz","Yalnızca örgütten ayrıldığını bildirirse suçlu sayılmaz","Amaçlanan suçu işlemese dahi örgütün mensubu olduğu için terör suçlusudur","Yalnızca tanık sıfatıyla değerlendirilir","Ancak eylem başka biri tarafından fiilen gerçekleştirilirse terör suçlusu olur"],"dogru":2,"aciklama":"m.2: '...amaçlanan suçu işlemese dahi örgütlerin mensubu olan kişi terör suçlusudur.' Mensup olmak tek başına yeterlidir; suçun fiilen işlenmesi şart değildir.","kaynak":"3713 m.2","zorluk":"orta"},
    {"id":"3713-OO-003","soru":"A, bir terör örgütünün amaçları doğrultusunda ve örgütün faaliyeti çerçevesinde bir kişiyi kasten yaralar (TCK m. 86). Bu fiil 3713 sayılı Kanun bakımından nasıl nitelendirilir?","siklar":["Kasten yaralama m.3'te sayıldığından, şart aranmaksızın doğrudan terör suçudur","Bir terör örgütünün faaliyeti çerçevesinde işlendiği için terör suçu sayılır","Hiçbir koşulda terör suçu sayılmaz, daima adi suç olarak kalır","Yalnızca mağdur kamu görevlisiyse terör suçu olur","Yalnızca yaralama ölümle sonuçlanırsa terör suçu olur"],"dogru":1,"aciklama":"Kasten yaralama (TCK 86) m.3'te değil, m.4/a'da sayılan suçlardandır ve ancak bir terör örgütünün faaliyeti çerçevesinde işlendiğinde terör suçu sayılır. Olayda bu şart gerçekleştiği için fiil terör suçudur.","kaynak":"3713 m.4","zorluk":"zor"},
    {"id":"3713-OO-004","soru":"A, silahlı bir terör örgütüne üye olmaktan (TCK m. 314) yargılanmaktadır. Bu fiilin terör suçu sayılması için, ayrıca bir terör örgütünün faaliyeti çerçevesinde işlendiğinin ispatlanması gerekir mi?","siklar":["Evet, m.4 gereği örgüt faaliyeti çerçevesinde işlenmesi şarttır","Hayır, TCK 314 m.3'te sayıldığından şart aranmaksızın doğrudan terör suçudur","Evet, ayrıca o bölgede olağanüstü hâl ilan edilmiş olması gerekir","Hayır, ancak yalnızca aynı zamanda propaganda da yapılmışsa terör suçudur","Evet, mağdurun kamu görevlisi olması gerekir"],"dogru":1,"aciklama":"m.3, TCK 314'ü doğrudan terör suçları arasında sayar; bu suçlar için 'örgüt faaliyeti çerçevesinde işlenme' şartı aranmaz. Bu şart m.4 kapsamındaki suçlara özgüdür.","kaynak":"3713 m.3","zorluk":"orta"},
    {"id":"3713-OO-005","soru":"A, bir terör örgütünün cebir ve şiddet içeren yöntemlerini övecek şekilde propagandasını, ulusal bir televizyon kanalında yayımlanan bir programda yapar. Propaganda suçunun temel cezası bir yıldan beş yıla kadar hapis olduğuna göre, fiilin basın ve yayın yoluyla işlenmesi cezayı nasıl etkiler?","siklar":["Cezayı etkilemez, temel ceza aynen uygulanır","Verilecek ceza yarı oranında artırılır","Verilecek ceza iki katına çıkarılır","Verilecek ceza üçte bir oranında azaltılır","Hapis cezası yerine yalnızca adli para cezası uygulanır"],"dogru":1,"aciklama":"m.7: propaganda suçunun 'basın ve yayın yolu ile işlenmesi hâlinde, verilecek ceza yarı oranında artırılır.'","kaynak":"3713 m.7","zorluk":"orta"},
    {"id":"3713-OO-006","soru":"Terör örgütünün propagandasına dönüştürülen bir gösteri yürüyüşünde A, kimliğini gizlemek amacıyla yüzünü kısmen kapatmıştır ve üzerinde molotofkokteyli bulunmaktadır. A hakkında uygulanacak cezaya ilişkin aşağıdakilerden hangisi doğrudur?","siklar":["Yüzünü kapatma fiili suç oluşturmaz, yalnızca molotof bulundurmasından sorumlu olur","Yalnızca bir yıldan beş yıla kadar hapisle cezalandırılır","Yüzünü kapatması nedeniyle üç yıldan beş yıla kadar hapisle cezalandırılır; molotof bulundurması nedeniyle cezanın alt sınırı dört yıldan az olamaz","Yalnızca adli para cezası uygulanır","Cezası yarı oranında indirilir"],"dogru":2,"aciklama":"m.7: propagandaya dönüştürülen toplantı ve gösteri yürüyüşlerinde kimliğini gizlemek için yüzünü tamamen veya kısmen kapatanlar üç yıldan beş yıla kadar hapisle cezalandırılır; bu kişilerin molotof gibi yakıcı/patlayıcı maddeler bulundurması hâlinde verilecek cezanın alt sınırı dört yıldan az olamaz.","kaynak":"3713 m.7","zorluk":"zor"},
    {"id":"3713-OO-007","soru":"Terörle mücadelede görev yapmış, ancak hâlen görevinden ayrılmış (emekli) olan kamu görevlisi A'nın çocuğuna yönelik silahlı bir taarruz gerçekleştirilir. A, bu taarruzu savmak için silah kullanmaya yetkili midir?","siklar":["Hayır, görevinden ayrıldığı için hiçbir silah kullanma yetkisi kalmamıştır","Evet; kamu görevlileri görevlerinden ayrılmış olsalar dahi kendilerinin veya eş ve çocuklarının canına yönelik taarruzu savmak için silah kullanmaya yetkilidir","Yalnızca kendi canına yönelik taarruzda silah kullanabilir, çocuğu için kullanamaz","Ancak en yakın kolluk biriminden önceden izin alırsa silah kullanabilir","Bu yetkiye yalnızca fiilen görevdeyken sahiptir"],"dogru":1,"aciklama":"m.20: kamu görevlileri, görevlerinden ayrılmış olsalar dahi, kendilerine veya eş ve çocuklarının canına yönelik bir taarruzu savmak için silah kullanmaya yetkilidir.","kaynak":"3713 m.20","zorluk":"orta"},
    {"id":"3713-OO-008","soru":"Bir terör örgütüne karşı icra edilen operasyonda, kolluk görevlilerinin 'teslim ol' emrine rağmen şüpheli teslim olmamakta direnir. Kolluk görevlilerinin silah kullanma yetkisi bakımından 3713 Ek Madde 2'ye göre aşağıdakilerden hangisi doğrudur?","siklar":["Önce mutlaka havaya uyarı atışı yapmak, ardından amirin yazılı iznini almak zorundadırlar","Tehlikeyi etkisiz kılabilecek ölçü ve orantıda, doğrudan ve duraksamadan hedefe karşı silah kullanmaya yetkilidirler","Hiçbir şekilde silah kullanamaz, yalnızca bölgeden geri çekilirler","Sınırsız ve koşulsuz biçimde silah kullanabilirler","Yalnızca şüpheli önce ateş ederse silah kullanabilirler"],"dogru":1,"aciklama":"Ek Madde 2: operasyonlarda 'teslim ol' emrine itaat edilmemesi veya silah kullanmaya teşebbüs edilmesi hâlinde kolluk, tehlikeyi etkisiz kılabilecek ölçü ve orantıda, doğrudan ve duraksamadan hedefe karşı silah kullanmaya yetkilidir. 'Teslim ol'a itaatsizlik tek başına yeterli koşuldur.","kaynak":"3713 Ek Madde 2","zorluk":"zor"},
    {"id":"3713-OO-009","soru":"Görevi sırasında bir terör eylemine muhatap olan kamu görevlisi A ağır yaralanır ve engelli hâle gelir. A hakkında öncelikle hangi kanun hükümleri uygulanır?","siklar":["2330 sayılı Nakdi Tazminat ve Aylık Bağlanması Hakkında Kanun","Sosyal Yardımlaşma ve Dayanışmayı Teşvik Fonu mevzuatı","5816 sayılı Atatürk Aleyhine İşlenen Suçlar Hakkında Kanun","Yalnızca 657 sayılı Devlet Memurları Kanunu'nun genel hükümleri","Türk Kızılay yönetmeliği"],"dogru":0,"aciklama":"m.21: terör eylemine muhatap olarak yaralanan, engelli hâle gelen, ölen veya öldürülen kamu görevlileri hakkında 2330 sayılı Kanun uygulanır.","kaynak":"3713 m.21","zorluk":"orta"},
    {"id":"3713-OO-010","soru":"Bir terör eylemi sonucu esnaf A'nın iş yeri tamamen tahrip olur ve A maddi yönden mağdur duruma düşer. Kamu görevlisi olmayan A'ya öncelikle hangi kaynaktan yardım yapılır?","siklar":["2330 sayılı Kanun kapsamında nakdi tazminatla","Sosyal Yardımlaşma ve Dayanışmayı Teşvik Fonundan","İl özel idaresi bütçesinden","Doğrudan genel bütçeden ödeme yoluyla","Hiçbir yardım yapılamaz"],"dogru":1,"aciklama":"m.22: terör eylemleri nedeniyle can ve mal kaybına uğrayan vatandaşlara Sosyal Yardımlaşma ve Dayanışmayı Teşvik Fonundan öncelikle yardım yapılır; yardımın ölçüsü Fon Kurulunca tespit edilir.","kaynak":"3713 m.22","zorluk":"orta"},
    {"id":"3713-OO-011","soru":"Bir terör suçunun işlenişine hiçbir şekilde katılmamış (iştirak etmemiş) olan vatandaş A, faillerin yakalanmasını sağlayacak bilgiyi kolluğa verir ve failler yakalanır. A'ya para ödülü verilmesi bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Suçun işlenişine iştirak etmemiş olması koşuluyla A'ya para ödülü verilebilir","Yalnızca A bir kamu görevlisiyse ödül verilebilir","A aynı zamanda terör mağduru olmadıkça ödül verilemez","Ödül her hâlükârda zorunlu olarak verilir, makamın takdiri söz konusu değildir","Yardımın en az üç failin yakalanmasını sağlamış olması şarttır"],"dogru":0,"aciklama":"m.19: bu Kanun kapsamına giren suçun ortaya çıkarılmasına, delillerin ele geçirilmesine veya faillerin yakalanmasına yardımcı olanlara, 'suçun işlenişine iştirak etmemiş olmak koşuluyla' para ödülü verilebilir. İfade 'verilir' değil 'verilebilir' olduğundan ödül takdiridir.","kaynak":"3713 m.19","zorluk":"orta"},
    {"id":"3713-OO-012","soru":"Terörle mücadelede görev alan personel A hakkında, görevinden doğan bir fiil nedeniyle soruşturma başlatılır ve A müdafi yardımından yararlanmak ister. 3713 m.15'e göre A için en fazla kaç avukatın ücreti karşılanır ve bu husus hangi düzenlemeyle belirlenir?","siklar":["En fazla 1 avukat; Adalet Bakanlığı yönetmeliğiyle","En fazla 3 avukat; Milli Savunma ile İçişleri bakanlıklarınca müştereken çıkarılan yönetmelikle","Sınırsız sayıda avukat; Cumhurbaşkanı yönetmeliğiyle","En fazla 5 avukat; yalnızca İçişleri Bakanlığı yönetmeliğiyle","En fazla 2 avukat; Hazine ve Maliye Bakanlığı genelgesiyle"],"dogru":1,"aciklama":"m.15: terörle mücadelede görev alan personelin görevinden doğan soruşturma ve kovuşturmalarında en fazla üç avukatın ücreti karşılanır; esas ve usuller Milli Savunma ile İçişleri bakanlıklarınca müştereken çıkarılan yönetmelikle düzenlenir.","kaynak":"3713 m.15","zorluk":"orta"},
  ],
  8: [
    {"id":"2935-S-001","soru":"2935 sayılı Olağanüstü Hal Kanunu'na göre aşağıdakilerden hangisi olağanüstü hal ilanını gerektiren durumlardan biri DEĞİLDİR?","siklar":["Tabii afet veya tehlikeli salgın hastalıklar","Ağır ekonomik bunalım","Seferberlik veya savaş halinin ilan edilmesi","Anayasa ile kurulan hür demokrasi düzenini ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması","Şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması"],"dogru":2,"aciklama":"m.1; OHAL sebepleri (a) tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım ile (b) yaygın şiddet hareketlerine ait ciddi belirtiler ya da kamu düzeninin ciddi şekilde bozulmasıdır. Seferberlik/savaş hali OHAL değil, ayrı bir yönetim usulüdür (2941).","kaynak":"2935 m.1","zorluk":"orta"},
    {"id":"2935-S-002","soru":"2935 sayılı Kanun'un 1. maddesinin (b) bendine göre, aşağıdaki hangi durum olağanüstü hal ilanını gerektirir?","siklar":["Tabii afet sonucu meydana gelen hasarın telafisi ihtiyacı","Anayasa ile kurulan hür demokrasi düzenini veya temel hak ve hürriyetleri ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması","Tehlikeli salgın hastalıkların yayılması","Ağır ekonomik bunalımın baş göstermesi","Kamu kaynaklarının yetersiz kalması"],"dogru":1,"aciklama":"m.1/b; (b) bendi yaygın şiddet hareketleri ile kamu düzeninin ciddi bozulmasını kapsar. A, C, D ise (a) bendine ait afet/salgın/ekonomik bunalım sebepleridir.","kaynak":"2935 m.1/b","zorluk":"orta"},
    {"id":"2935-S-003","soru":"2935 sayılı Kanun'a göre olağanüstü hali ilan etmeye yetkili olan makam aşağıdakilerden hangisidir?","siklar":["Türkiye Büyük Millet Meclisi","Milli Güvenlik Kurulu","Cumhurbaşkanı","Bakanlar Kurulu","İçişleri Bakanlığı"],"dogru":2,"aciklama":"m.3; olağanüstü hali, yurdun bir veya birden fazla bölgesinde ya da bütününde altı ayı geçmemek üzere Cumhurbaşkanı ilan eder.","kaynak":"2935 m.3","zorluk":"kolay"},
    {"id":"2935-S-004","soru":"2935 sayılı Kanun'a göre olağanüstü hal, ilk ilanında en çok ne kadar süre için ilan edilebilir?","siklar":["En çok üç ay","En çok dört ay","En çok bir yıl","En çok iki yıl","En çok altı ay"],"dogru":4,"aciklama":"m.3; Cumhurbaşkanı, altı ayı geçmemek üzere olağanüstü hal ilan edebilir.","kaynak":"2935 m.3","zorluk":"orta"},
    {"id":"2935-S-005","soru":"2935 sayılı Kanun'a göre TBMM, Cumhurbaşkanının istemi üzerine olağanüstü hal süresini her defasında en çok ne kadar uzatabilir?","siklar":["Her defasında en çok iki ay","Her defasında en çok üç ay","Her defasında en çok dört ay","Her defasında en çok altı ay","Her defasında en çok bir yıl"],"dogru":2,"aciklama":"m.3; TBMM, Cumhurbaşkanının istemi üzerine her defasında dört ayı geçmemek üzere süreyi uzatabilir veya olağanüstü hali kaldırabilir.","kaynak":"2935 m.3","zorluk":"orta"},
    {"id":"2935-S-006","soru":"2935 sayılı Kanun'a göre, olağanüstü hal ilan edildiğinde Türkiye Büyük Millet Meclisi tatilde ise aşağıdakilerden hangisi yapılır?","siklar":["Meclis derhal toplantıya çağrılır","Onay, Meclisin tatil bitimine kadar ertelenir","Karar, Meclis adına Cumhurbaşkanınca onaylanır","Karar onay için Anayasa Mahkemesine gönderilir","Olağanüstü hal, bir sonraki yasama yılında görüşülür"],"dogru":0,"aciklama":"m.3; olağanüstü hal kararı Resmi Gazete'de yayımlanır ve hemen TBMM'nin onayına sunulur. Türkiye Büyük Millet Meclisi tatilde ise derhal toplantıya çağrılır.","kaynak":"2935 m.3","zorluk":"orta"},
    {"id":"2935-S-007","soru":"2935 sayılı Kanun'a göre, olağanüstü halin ilanı ve süresine ilişkin yetkilerle ilgili olarak aşağıdakilerden hangisi YANLIŞTIR?","siklar":["Olağanüstü hali Cumhurbaşkanı ilan eder.","Olağanüstü hal, yurdun bir veya birden fazla bölgesinde ya da bütününde en çok altı ay için ilan edilebilir.","Türkiye Büyük Millet Meclisi, olağanüstü hal süresini değiştirebilir.","Süreyi uzatma, Cumhurbaşkanının istemi üzerine Türkiye Büyük Millet Meclisince yapılır.","Cumhurbaşkanı, olağanüstü hali Türkiye Büyük Millet Meclisinin onayı olmaksızın süresiz olarak yürürlükte tutabilir."],"dogru":4,"aciklama":"m.3; CB ilan eder (en çok 6 ay), karar hemen TBMM onayına sunulur; Meclis süreyi değiştirebilir ve CB istemiyle her defasında en çok 4 ay uzatabilir. OHAL süresiz ve Meclis onayından bağımsız tutulamaz; bu yüzden E yanlıştır.","kaynak":"2935 m.3","zorluk":"zor"},
    {"id":"2935-S-008","soru":"2935 sayılı Kanun'a göre Türkiye Büyük Millet Meclisi, ilan edilen olağanüstü hal süresini değiştirebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.3; 'Meclis, olağanüstü hal süresini değiştirebilir.' ifadesi birebir kanun metnindendir.","kaynak":"2935 m.3","zorluk":"kolay"},
    {"id":"2935-S-009","soru":"2935 sayılı Kanun'un 2. maddesine göre, vatandaşlar için getirilecek para, mal ve çalışma yükümlülükleri olağanüstü halin hangi hâllerinde söz konusu olur?","siklar":["Yalnızca tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım sebebiyle ilan edilen olağanüstü hâllerde","Olağanüstü halin her türünde ayrım yapılmaksızın","Yalnızca yaygın şiddet hareketleri sebebiyle ilan edilen olağanüstü hâlde","Yalnızca savaş ve seferberlik hâlinde","Olağanüstü hal yalnızca yurdun bütününde ilan edildiğinde"],"dogru":0,"aciklama":"m.2; para, mal ve çalışma yükümlülükleri yalnız tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım hallerinde ilan edilen OHAL'lerde getirilir. Temel hak ve hürriyetlerin sınırlanması/durdurulması ise olağanüstü halin her türü için ayrı ayrı geçerlidir.","kaynak":"2935 m.2","zorluk":"orta"},
    {"id":"2935-S-010","soru":"2935 sayılı Kanun'un 2. maddesinde düzenlenen kapsam konuları arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Vatandaşlar için getirilecek para, mal ve çalışma yükümlülükleri","Temel hak ve hürriyetlerin nasıl sınırlanacağı veya nasıl durdurulacağı","Kamu hizmeti görevlilerine ne gibi yetkiler verileceği","Olağanüstü hal süresince milletvekili genel seçimlerinin ne zaman yapılacağı","Olağanüstü yönetim usulleri"],"dogru":3,"aciklama":"m.2; Kanun yükümlülükleri, temel hak ve hürriyetlerin sınırlanması/durdurulmasını, halin gerektirdiği tedbirleri, kamu görevlilerine verilecek yetkileri ve görevlilerin durumundaki değişiklikleri, olağanüstü yönetim usullerini kapsar. Milletvekili seçim zamanı m.2 kapsamında düzenlenmez.","kaynak":"2935 m.2","zorluk":"orta"},
    {"id":"2935-S-011","soru":"2935 sayılı Kanun'un 22. maddesine göre, 3. maddenin (b) bendi (şiddet/kamu düzeni) gereğince ilan edilen olağanüstü halde il valisi, ihtiyaç duyduğu kuvveti hangi sırayla ister?","siklar":["Önce emrindeki kolluk kuvvetlerinden; bunlar yeterli gelmezse bağlı olduğu bölge valisinden","Önce Genelkurmay Başkanlığından, sonra İçişleri Bakanlığından","Önce bölge valisinden, sonra Cumhurbaşkanından","Doğrudan ve yalnızca en yakın askerî komutanlıktan","Önce belediye başkanından, sonra mülki amirden"],"dogru":0,"aciklama":"m.22; il valisi (b) bendi hallerinde önce emrindeki kolluk kuvvetlerini kullanır, bunlar yeterli gelmezse bağlı olduğu bölge valisinden yardım ve kuvvet ister.","kaynak":"2935 m.22","zorluk":"orta"},
    {"id":"2935-S-012","soru":"2935 sayılı Kanun'un 22. maddesine göre, il valisi ani ve olağanüstü bir olay karşısında kolluk kuvvetlerinin gecikmesi durumunda nereden yardım ister ve durumu kime bildirir?","siklar":["Komşu il valisinden yardım ister; durumu Genelkurmay Başkanlığına bildirir","Doğrudan Cumhurbaşkanından yardım ister; durumu TBMM'ye bildirir","Milli Güvenlik Kurulundan yardım ister; durumu yalnızca Cumhurbaşkanına bildirir","En yakın askerî komutanlıktan yardım ister; durumu bölge valisi ile İçişleri Bakanlığına bildirir","Belediye başkanından yardım ister; durumu yalnızca valiliğe bildirir"],"dogru":3,"aciklama":"m.22; ani ve olağanüstü bir olay ve kuvvetin gecikmesi halinde il valisi en yakın askerî komutanlıktan yardım ister; durumu bölge valisi ile İçişleri Bakanlığına bildirir. Askerî yardımın yerine getirilmesinde 21 inci madde hükümleri uygulanır.","kaynak":"2935 m.22","zorluk":"zor"},
    {"id":"2935-S-013","soru":"2935 sayılı Kanun'un 23. maddesine göre, 3. maddenin (b) bendi gereğince ilan edilen olağanüstü halde; teslim ol emrine itaat edilmemesi veya silahla mukabeleye yeltenilmesi gibi hallerde güvenlik kuvvetleri ............ ateş ederler. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["doğruca ve duraksamadan hedefe","yalnızca havaya ihtar amacıyla","ancak amirinden yazılı emir aldıktan sonra","sadece bacak hizasına nişan alarak","üç kez sözlü uyarı yapıp on dakika bekledikten sonra"],"dogru":0,"aciklama":"m.23; (b) bendi olağanüstü halinde, teslim ol emrine itaatsizlik, silahla mukabele veya meşru müdafaa hallerinde görevliler doğruca ve duraksamadan hedefe ateş ederler.","kaynak":"2935 m.23","zorluk":"zor"},
    {"id":"2935-S-014","soru":"2935 sayılı Kanun'a göre, silah kullanma yetkisini kullanan görevliler hakkında yapılacak soruşturma tutuksuz olarak yürütülür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.23; bu Kanunda öngörülen silah kullanma yetkisi kapsamında görev yapan kişiler hakkındaki soruşturma tutuksuz olarak yapılır.","kaynak":"2935 m.23","zorluk":"orta"},
    {"id":"2935-S-015","soru":"2935 sayılı Kanun'un 9. maddesine göre, tabii afet ve tehlikeli salgın hastalıklar sebebiyle ilan edilen olağanüstü halde öğretim ve eğitim bakımından aşağıdaki tedbirlerden hangisi alınabilir?","siklar":["Bölgedeki tüm öğretmenleri başka illere sürekli olarak nakletmek","Özel öğretim kurumlarını kamulaştırmak","Öğrencilere bölgede kimlik belirleyici belge taşıma zorunluluğu getirmek","Resmi ve özel her derecedeki öğretim ve eğitim kurumlarında öğrenime ara vermek ve öğrenci yurtlarını süreli veya süresiz kapatmak","Okul binalarını tehlike gerekçesiyle istisnasız yıkmak"],"dogru":3,"aciklama":"m.9/b; afet/salgın OHAL'inde resmi ve özel her derecedeki öğretim ve eğitim kurumlarında öğrenime ara verilebilir ve öğrenci yurtları süreli veya süresiz kapatılabilir.","kaynak":"2935 m.9","zorluk":"orta"},
    {"id":"2935-S-016","soru":"2935 sayılı Kanun'un 9. maddesine göre tabii afet ve tehlikeli salgın hastalıklar sebebiyle olağanüstü hal ilanında aşağıdaki tedbirlerden hangisi alınabilir?","siklar":["Sokağa çıkmayı sınırlamak veya yasaklamak","Kişilerin üstünü, araçlarını ve eşyalarını aratmak","Kapalı ve açık yerlerde yapılacak toplantı ve gösteri yürüyüşlerini yasaklamak","Tehlike arz eden binaları yıkmak; sağlığa zararlı gıda maddelerini imha etmek","Dernek faaliyetlerini üç ayı geçmemek kaydıyla durdurmak"],"dogru":3,"aciklama":"m.9/f; tehlike arz eden binaları yıkmak ve sağlığa zararlı gıda maddeleri ile mahsulleri imha etmek afet/salgın tedbiridir. A, B, C, E ise m.11 (şiddet/kamu düzeni) tedbirleridir.","kaynak":"2935 m.9","zorluk":"orta"},
    {"id":"2935-S-017","soru":"2935 sayılı Kanun'un 23. maddesine göre, silah kullanma yetkisinin kullanılmasında aşağıdaki düzenlemelerden hangilerinin hükümleri uygulanır?","siklar":["Yalnızca 5237 sayılı Türk Ceza Kanunu","211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanunu'nun 87. maddesi ile 1481 sayılı Kanun'un 3. maddesi","2559 sayılı Polis Vazife ve Salahiyet Kanunu'nun tamamı","1402 sayılı Sıkıyönetim Kanunu","Yalnızca 2935 sayılı Kanun'un kendi hükümleri"],"dogru":1,"aciklama":"m.23; silah kullanma yetkisinin kullanılmasında 211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanununun 87 nci maddesinin (V) ve (VI) numaralı fıkraları ile 1481 sayılı Kanunun 3 üncü maddesi hükümleri uygulanır.","kaynak":"2935 m.23","zorluk":"zor"},
    {"id":"2935-S-018","soru":"2935 sayılı Kanun'a göre, tabii afet ve tehlikeli salgın hastalıklar (a bendi) sebebiyle ilan edilen olağanüstü halde il valisi, ihtiyaç duyduğu her türlü yardımı doğrudan ve yalnızca en yakın askerî komutanlıktan istemek zorundadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.22; (a) bendi hallerinde il valisi mevcut mevzuatla kendisine verilen yetkileri kullanır. En yakın askerî komutanlıktan yardım isteme, ani ve olağanüstü bir olay ile kuvvetin gecikmesi haline özgüdür ve durum bölge valisi ile İçişleri Bakanlığına bildirilir; dolayısıyla ifade yanlıştır.","kaynak":"2935 m.22","zorluk":"orta"},
    {"id":"2935-S-019","soru":"2935 sayılı Kanun'un 11. maddesine göre, 3. maddenin (b) bendi gereğince (şiddet/kamu düzeni) ilan edilen olağanüstü halde, 9. maddedeki tedbirlere EK olarak aşağıdakilerden hangisi alınabilir?","siklar":["Belli gıda maddeleri ile hayvan ve hayvan yeminin bölge dışına çıkarılmasını kontrol etmek","Sokağa çıkmayı sınırlamak veya yasaklamak","Öğrenci yurtlarını süreli veya süresiz kapatmak","Tehlike arz eden binaları yıkmak","Halkın beslenmesi için gerekli zaruri ihtiyaç maddelerinin dağıtımını düzenlemek"],"dogru":1,"aciklama":"m.11/a; (b) bendi OHAL'inde m.9 tedbirlerine ek olarak sokağa çıkmayı sınırlamak veya yasaklamak alınabilir. A, C, D, E ise m.9 (afet/salgın) tedbirleridir.","kaynak":"2935 m.11","zorluk":"orta"},
    {"id":"2935-S-020","soru":"2935 sayılı Kanun'un 11. maddesine göre, şiddet ve kamu düzeninin bozulması sebebiyle ilan edilen olağanüstü halde alınabilecek ek tedbirlerle ilgili olarak aşağıdakilerden hangisi YANLIŞTIR?","siklar":["Kişilerin üstünü, araçlarını ve eşyalarını aratmak ve suç eşyası ile delil niteliğindekilere el koymak","Ruhsatlı da olsa her nevi silah ve mermilerin taşınmasını veya naklini yasaklamak","Dernek faaliyetlerini, her dernek hakkında ayrı karar almak ve üç ayı geçmemek kaydıyla durdurmak","Kapalı ve açık yerlerde yapılacak toplantı ve gösteri yürüyüşlerini yasaklamak veya ertelemek","Bölgede bulunan 18-60 yaş arası bütün vatandaşları kendilerine verilecek işleri yapmakla yükümlü kılmak"],"dogru":4,"aciklama":"m.11; A, B, C, D maddenin gerçek ek tedbirleridir. 18-60 yaş arası vatandaşların çalışma yükümlülüğü ise m.8 kapsamındaki afet/salgın OHAL'ine aittir; şiddet/kamu düzeni OHAL'inin ek tedbiri değildir.","kaynak":"2935 m.11","zorluk":"zor"},
    {"id":"2935-S-021","soru":"2935 sayılı Kanun'un 9. maddesine göre, tabii afet ve tehlikeli salgın hastalıklar sebebiyle ilan edilen olağanüstü halde kara, deniz ve hava trafiği bakımından aşağıdaki tedbirlerden hangisi alınabilir?","siklar":["Bölgedeki tüm özel araçlara el koyup satışını yapmak","Ulaştırma araçlarının bölgeye giriş ve çıkışlarını kayıtlamak veya yasaklamak","Sürücü belgelerini süresiz olarak iptal etmek","Sokağa çıkmayı sınırlamak veya yasaklamak","Toplu taşımayı bölge genelinde ücretsiz hâle getirmek"],"dogru":1,"aciklama":"m.9/j; afet/salgın OHAL'inde kara, deniz ve hava trafik düzenine ilişkin tedbirler alınabilir; ulaştırma araçlarının bölgeye giriş ve çıkışları kayıtlanabilir veya yasaklanabilir.","kaynak":"2935 m.9","zorluk":"orta"},
    {"id":"2935-S-022","soru":"2935 sayılı Kanun'un 11. maddesine göre, şiddet/kamu düzeninin bozulması (b bendi) sebebiyle ilan edilen olağanüstü halde; işçi çıkartmalarının izne bağlanması veya ertelenmesi ile dernek faaliyetlerinin durdurulması en çok hangi süreyle sınırlıdır?","siklar":["Bir ay","İki ay","Üç ay","Dört ay","Altı ay"],"dogru":2,"aciklama":"m.11; işçi çıkartmaları üç aylık bir süreyi aşmamak kaydıyla izne bağlanabilir veya ertelenebilir (n bendi); dernek faaliyetleri her dernek hakkında ayrı karar almak ve üç ayı geçmemek kaydıyla durdurulabilir (o bendi).","kaynak":"2935 m.11","zorluk":"orta"},
    {"id":"2935-OO-001","soru":"Ülkenin bir bölgesinde meydana gelen şiddetli deprem ve hemen ardından yayılan tehlikeli bir salgın hastalık nedeniyle kamu hizmetleri büyük ölçüde aksamış, halkın temel ihtiyaçları karşılanamaz hâle gelmiştir. Cumhurbaşkanı bu bölgede olağanüstü hal ilan etmeyi değerlendirmektedir. Bu olay, 2935 sayılı Kanun'a göre olağanüstü hal ilanını gerektiren hangi sebep kapsamına girer?","siklar":["(a) bendi: tabii afet ve tehlikeli salgın hastalıklar","(b) bendi: hür demokrasi düzenini ortadan kaldırmaya yönelik yaygın şiddet hareketleri","(b) bendi: şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması","Ağır ekonomik bunalım hâli","Seferberlik ve savaş hâli"],"dogru":0,"aciklama":"m.1/a ve m.3/a; tabii afet (deprem) ve tehlikeli salgın hastalıklar (a) bendi sebepleridir. Bu hallerde Cumhurbaşkanı doğrudan (MGK görüşü aranmaksızın) OHAL ilan edebilir.","kaynak":"2935 m.1 / m.3","zorluk":"orta"},
    {"id":"2935-OO-002","soru":"Cumhurbaşkanı, ülke genelinde baş gösteren ve anayasal düzeni ortadan kaldırmaya yönelik yaygın şiddet hareketleri (3/b) sebebiyle olağanüstü hal ilan etmeye karar vermiştir. Bu durumda Cumhurbaşkanı, ilan kararını almadan önce aşağıdaki kurullardan hangisinin görüşünü almak zorundadır?","siklar":["Türkiye Büyük Millet Meclisi Genel Kurulu","Milli Güvenlik Kurulu","Anayasa Mahkemesi","Olağanüstü Hal Koordinasyon Kurulu","Bölge Olağanüstü Hal Kurulu"],"dogru":1,"aciklama":"m.3/b; (b) bendi hallerinde Cumhurbaşkanı, Milli Güvenlik Kurulunun görüşünü de aldıktan sonra olağanüstü hal ilan edebilir. (a) bendinde böyle bir görüş aranmaz.","kaynak":"2935 m.3/b","zorluk":"orta"},
    {"id":"2935-OO-003","soru":"Cumhurbaşkanı, tabii afet sebebiyle bir bölgede beş ay süreyle olağanüstü hal ilan etmiş ve karar Resmi Gazete'de yayımlanmıştır. İlan tarihinde Türkiye Büyük Millet Meclisi tatildedir. Bu aşamadan sonra kanun gereği yapılması gereken nedir?","siklar":["Karar derhâl Türkiye Büyük Millet Meclisinin onayına sunulur; Meclis tatilde olduğundan derhâl toplantıya çağrılır","Karar, Meclisin tatili bitene kadar yürürlüğe girmez","Karar, onay gerekmeksizin beş ay boyunca tek başına geçerli kalır","Karar, onay için Anayasa Mahkemesine gönderilir","Karar, Milli Güvenlik Kurulunun onayıyla kesinleşir"],"dogru":0,"aciklama":"m.3; olağanüstü hal kararı Resmi Gazete'de yayımlanır ve hemen TBMM'nin onayına sunulur. Meclis tatilde ise derhâl toplantıya çağrılır.","kaynak":"2935 m.3","zorluk":"orta"},
    {"id":"2935-OO-004","soru":"Bir bölgede altı ay için ilan edilen olağanüstü halin süresi dolmak üzeredir; ancak ilanı gerektiren tehlike henüz ortadan kalkmamıştır. Cumhurbaşkanı süreyi uzatmak istemektedir. Bu durumda süre nasıl uzatılır?","siklar":["Cumhurbaşkanı, tek başına aldığı kararla süreyi altı ay daha uzatır","Cumhurbaşkanının istemi üzerine Türkiye Büyük Millet Meclisi, her defasında dört ayı geçmemek üzere süreyi uzatabilir","Milli Güvenlik Kurulu, süreyi her defasında altı ay uzatabilir","Bölge valisi, süreyi üç ay uzatma yetkisine sahiptir","Süre hiçbir şekilde uzatılamaz; yeni bir olağanüstü hal ilan edilmesi gerekir"],"dogru":1,"aciklama":"m.3; Cumhurbaşkanının istemi üzerine TBMM, her defasında dört ayı geçmemek üzere süreyi uzatabilir veya olağanüstü hali kaldırabilir.","kaynak":"2935 m.3","zorluk":"orta"},
    {"id":"2935-OO-005","soru":"Yaygın şiddet olayları (3/b) sebebiyle olağanüstü hal ilan edilen bir bölgede yetkili makam, asayişi sağlamak için bölgedeki vatandaşlara para, mal ve çalışma yükümlülüğü getirmeyi planlamaktadır. 2935 sayılı Kanun'a göre bu plan hukuken mümkün müdür?","siklar":["Mümkün değildir; para, mal ve çalışma yükümlülükleri yalnızca tabii afet, tehlikeli salgın hastalık veya ağır ekonomik bunalım sebebiyle ilan edilen olağanüstü hallerde getirilebilir","Mümkündür; bu yükümlülükler olağanüstü halin her türünde getirilebilir","Mümkündür; ancak yalnızca Cumhurbaşkanının ayrıca izin vermesi şartıyla","Mümkündür; çünkü şiddet olaylarında çalışma yükümlülüğü zorunludur","Mümkün değildir; çünkü yükümlülükler yalnızca savaş hâlinde getirilebilir"],"dogru":0,"aciklama":"m.2; para, mal ve çalışma yükümlülükleri yalnız tabii afet, tehlikeli salgın hastalık veya ağır ekonomik bunalım (a hâlleri) sebebiyle ilan edilen OHAL'de getirilebilir. Temel hak ve hürriyetlerin sınırlanması/durdurulması ise OHAL'in her türü için geçerlidir.","kaynak":"2935 m.2","zorluk":"zor"},
    {"id":"2935-OO-006","soru":"Yalnızca tehlikeli salgın hastalık (3/a) sebebiyle olağanüstü hal ilan edilen bir bölgede vali, alabileceği tedbirleri değerlendirmektedir. Aşağıdaki tedbirlerden hangisi bu olağanüstü hal türünde (m.9 kapsamında) doğrudan ALINAMAZ?","siklar":["Öğretim ve eğitim kurumlarında öğrenime ara vermek, öğrenci yurtlarını kapatmak","Tehlike arz eden binaları yıkmak ve sağlığa zararlı gıda maddelerini imha etmek","Sokağa çıkmayı sınırlamak veya yasaklamak","Eğlence ve konaklama yerlerini denetlemek, gerektiğinde kapatmak","Ulaştırma araçlarının bölgeye giriş ve çıkışlarını kayıtlamak veya yasaklamak"],"dogru":2,"aciklama":"Sokağa çıkmayı sınırlamak/yasaklamak m.11'de (3/b şiddet OHAL'i) m.9'a EK tedbir olarak sayılmıştır; afet/salgın (3/a) OHAL'inin m.9 listesinde yer almaz. A, B, D, E ise m.9 (afet/salgın) tedbirleridir.","kaynak":"2935 m.9 / m.11","zorluk":"zor"},
    {"id":"2935-OO-007","soru":"Yaygın şiddet olayları (3/b) sebebiyle olağanüstü hal ilan edilen bir bölgede vali; bölgeye girişlerde kişilerin üstünü, araçlarını ve eşyalarını aratmakta, suç eşyası ve delil niteliğindekilere el koymakta ve bölge sakinleri ile dışarıdan girenlere kimlik belirleyici belge taşıma zorunluluğu getirmektedir. Bu uygulamalar için aşağıdakilerden hangisi doğrudur?","siklar":["Bu tedbirler, 9. maddedeki tedbirlere ek olarak yalnızca (3/b) gereğince ilan edilen olağanüstü halde alınabilir","Bu tedbirler yalnızca tabii afet ve salgın OHAL'inde (3/a) alınabilir","Bu tedbirler için her seferinde Cumhurbaşkanından ayrı izin alınması zorunludur","Bu tedbirler ancak Milli Güvenlik Kurulu kararıyla uygulanabilir","Bu tedbirler olağanüstü hal ilan edilmeden de her zaman uygulanabilir"],"dogru":0,"aciklama":"m.11; arama-elkoyma (c bendi) ve kimlik belirleyici belge taşıma (d bendi) gibi tedbirler, 9. maddedeki tedbirlere EK olarak (3/b) şiddet/kamu düzeni OHAL'inde alınabilir.","kaynak":"2935 m.11","zorluk":"orta"},
    {"id":"2935-OO-008","soru":"Şiddet olaylarının yaygınlaştığı (3/b) bir olağanüstü hal bölgesinde vali, kamu düzenini bozduğunu değerlendirdiği bir derneğin faaliyetlerini durdurmak ve bazı işyerlerindeki işçi çıkartmalarını ertelemek istemektedir. 2935 sayılı Kanun'a göre bu tedbirler bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Dernek faaliyetleri her dernek hakkında ayrı karar alınmak ve üç ayı geçmemek kaydıyla durdurulabilir; işçi çıkartmaları da üç aylık süreyi aşmamak kaydıyla izne bağlanabilir veya ertelenebilir","Dernek faaliyetleri tek bir genel kararla altı ay süreyle durdurulabilir","İşçi çıkartmaları en çok dört ay süreyle ertelenebilir","Bu tedbirler süresiz olarak uygulanabilir","Dernek faaliyetleri yalnızca mahkeme kararıyla bir yıl durdurulabilir"],"dogru":0,"aciklama":"m.11; dernek faaliyetleri her dernek hakkında ayrı karar almak ve üç ayı geçmemek kaydıyla durdurulabilir (o bendi); işçi çıkartmaları üç aylık süreyi aşmamak kaydıyla izne bağlanabilir veya ertelenebilir (n bendi).","kaynak":"2935 m.11","zorluk":"zor"},
    {"id":"2935-OO-009","soru":"(3/b) gereğince olağanüstü hal ilan edilen bir ilde, artan olaylar karşısında il valisi emrindeki kolluk kuvvetlerinin yetersiz kaldığını tespit etmiştir. 2935 sayılı Kanun'a göre il valisi, ihtiyaç duyduğu ek yardım ve kuvveti öncelikle kimden istemelidir?","siklar":["Bağlı olduğu bölge valisinden","Doğrudan Genelkurmay Başkanlığından","Doğrudan Cumhurbaşkanından","En yakın belediye başkanından","Milli Güvenlik Kurulundan"],"dogru":0,"aciklama":"m.22; (3/b) hallerinde il valisi önce emrindeki kolluk kuvvetlerini kullanır, bunlar yeterli gelmediğinde bağlı olduğu bölge valisinden yardım ve kuvvet ister.","kaynak":"2935 m.22","zorluk":"orta"},
    {"id":"2935-OO-010","soru":"(3/b) gereğince ilan edilen olağanüstü halde görev yapan güvenlik kuvvetleri, kendilerine yöneltilen 'teslim ol' emrine uymayıp silahla karşılık vermeye yeltenen bir grupla karşı karşıya kalmıştır. 2935 sayılı Kanun'a göre güvenlik kuvvetleri bu durumda nasıl silah kullanır?","siklar":["Doğruca ve duraksamadan hedefe ateş ederler","Yalnızca havaya ihtar ateşi açabilirler","Yalnızca bacak hizasına nişan alarak ateş edebilirler","Ancak amirlerinden yazılı emir aldıktan sonra ateş edebilirler","Hiçbir şekilde silah kullanamazlar"],"dogru":0,"aciklama":"m.23; (3/b) OHAL'inde teslim ol emrine itaatsizlik, silahla mukabeleye yeltenme veya meşru müdafaa hallerinde güvenlik kuvvetleri doğruca ve duraksamadan hedefe ateş ederler. Bu yetkiyi kullananlar hakkındaki soruşturma da tutuksuz yürütülür.","kaynak":"2935 m.23","zorluk":"zor"},
  ],
  9: [
    {"id":"5816-S-001","soru":"5816 sayılı Atatürk Aleyhine İşlenen Suçlar Hakkında Kanun gereğince, Atatürk'ün hatırasına alenen hakaret eden veya söven kimse hakkında uygulanacak ceza aşağıdakilerden hangisidir?","siklar":["Bir yıldan beş yıla kadar ağır hapis","Bir yıldan üç yıla kadar ağır hapis","İki yıldan beş yıla kadar ağır hapis","Bir yıldan üç yıla kadar hapis","Bir yıldan beş yıla kadar hapis"],"dogru":3,"aciklama":"m.1/1: 'Atatürk'ün hatırasına alenen hakaret eden veya söven kimse bir yıldan üç yıla kadar hapis cezası ile cezalandırılır.' Ceza türü 'hapis'tir (ağır hapis değil), süre 1-3 yıldır.","kaynak":"5816 m.1/1","zorluk":"kolay"},
    {"id":"5816-S-002","soru":"5816 sayılı Kanun'a göre Atatürk'ü temsil eden heykel, büst ve abideleri veyahut Atatürk'ün kabrini tahrip eden, kıran, bozan veya kirleten kimseye verilecek ceza aşağıdakilerden hangisidir?","siklar":["Bir yıldan üç yıla kadar hapis","Bir yıldan beş yıla kadar hapis","İki yıldan beş yıla kadar ağır hapis","Bir yıldan üç yıla kadar ağır hapis","Bir yıldan beş yıla kadar ağır hapis"],"dogru":4,"aciklama":"m.1/2: bu suçu işleyen kimseye 'bir yıldan beş yıla kadar ağır hapis cezası verilir.' Hem süre (1-5 yıl) hem ceza türü (ağır hapis) önemlidir.","kaynak":"5816 m.1/2","zorluk":"orta"},
    {"id":"5816-S-003","soru":"5816 sayılı Kanun'un 1. maddesinin 2. fıkrasına göre, Atatürk'ü temsil eden heykel, büst ve abideler ile Atatürk'ün kabri bakımından aşağıdaki hareketlerden hangisinin yapılması bu fıkrada düzenlenen suçu oluşturmaz?","siklar":["Bozmak","Kırmak","Yerinden sökerek çalmak","Tahrip etmek","Kirletmek"],"dogru":2,"aciklama":"m.1/2 seçimlik hareketleri sınırlı sayar: 'tahrip eden, kıran, bozan veya kirleten'. Yerinden söküp çalma (alıp götürme) bu fıkrada sayılmaz; bu fiil ayrı bir suç (hırsızlık) oluşturur, m.1/2'deki tahrip suçunu değil.","kaynak":"5816 m.1/2","zorluk":"orta"},
    {"id":"5816-S-004","soru":"5816 sayılı Kanun'a göre, kanunun 1. maddesinde yazılı suçları işlemeye başkalarını teşvik eden kimse nasıl cezalandırılır?","siklar":["Asıl failin cezasının yarısı oranında","Asıl fail gibi","Asıl failin cezasının üçte biri oranında","Teşvik suçu ayrıca cezalandırılmaz","Bir aydan altı aya kadar hapis"],"dogru":1,"aciklama":"m.1/3: 'Yukarki fıkralarda yazılı suçları işlemeye başkalarını teşvik eden kimse asıl fail gibi cezalandırılır.'","kaynak":"5816 m.1/3","zorluk":"orta"},
    {"id":"5816-S-005","soru":"Atatürk'ün hatırasına alenen hakaret eden veya söven kimse, 5816 sayılı Kanun'a göre bir yıldan üç yıla kadar AĞIR hapis cezası ile cezalandırılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Süre (1-3 yıl) doğru olsa da ceza türü yanlıştır: m.1/1'de hatıraya hakaret/sövme için ceza 'hapis'tir. 'Ağır hapis' yalnızca m.1/2'deki anıt/kabir tahribi suçuna aittir.","kaynak":"5816 m.1/1","zorluk":"kolay"},
    {"id":"5816-S-006","soru":"5816 sayılı Kanun'a göre, 1. maddede yazılı suçlar iki veya daha fazla kimse tarafından toplu olarak veya umumi ya da umuma açık mahallerde yahut basın vasıtasıyla işlenirse hükmolunacak ceza ne oranda artırılır?","siklar":["Yarı nispetinde","Bir misli","Üçte bir oranında","İki misli","Dörtte bir oranında"],"dogru":0,"aciklama":"m.2/1: bu ağırlaştırıcı hallerde 'hükmolunacak ceza yarı nispetinde artırılır.'","kaynak":"5816 m.2/1","zorluk":"orta"},
    {"id":"5816-S-007","soru":"Aşağıdakilerden hangisi, 5816 sayılı Kanun'un 2. maddesinin 1. fıkrasına göre cezanın yarı nispetinde artırılmasını gerektiren hâllerden biri DEĞİLDİR?","siklar":["Suçun iki veya daha fazla kişi tarafından toplu olarak işlenmesi","Suçun umuma açık mahalde işlenmesi","Suçun gece vakti işlenmesi","Suçun basın vasıtasıyla işlenmesi","Suçun umumi mahalde işlenmesi"],"dogru":2,"aciklama":"m.2/1 ağırlaştırıcı halleri sınırlı sayar: toplu (iki veya daha fazla kişi), umumi/umuma açık mahal, basın. 'Gece vakti' bu fıkrada yer almaz.","kaynak":"5816 m.2/1","zorluk":"zor"},
    {"id":"5816-S-008","soru":"5816 sayılı Kanun'a göre, 1. maddenin 2. fıkrasında yazılı suçlar (heykel, büst, abide veya kabir tahribi) zor kullanılarak işlenir veya bu suretle işlenmesine teşebbüs olunursa verilecek ceza ne oranda artırılır?","siklar":["Yarı nispetinde artırılır","Üçte bir oranında artırılır","İki misli artırılır","Ceza değişmez","Bir misli artırılır"],"dogru":4,"aciklama":"m.2/2: m.1/2'deki suçlar zor kullanılarak işlenir veya bu suretle işlenmesine teşebbüs olunursa 'verilecek ceza bir misli artırılır.' Teşebbüs hali de tamamlanmış suç gibi bu artırıma tabidir.","kaynak":"5816 m.2/2","zorluk":"zor"},
    {"id":"5816-S-009","soru":"5816 sayılı Kanun'a göre, heykel/büst/abide veya kabir tahribi suçunun zor kullanılarak işlenmesine teşebbüs edilmesi hâlinde de verilecek ceza bir misli artırılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.2/2 'zor kullanılarak işlenir VEYA bu suretle işlenmesine teşebbüs olunursa' diyerek teşebbüs hâlini de bir misli artırım kapsamına alır.","kaynak":"5816 m.2/2","zorluk":"orta"},
    {"id":"5816-S-010","soru":"5816 sayılı Kanun'da yazılı suçlardan dolayı takibat ne şekilde yapılır?","siklar":["Mağdurun veya yakınlarının şikâyeti üzerine","Cumhuriyet savcılıklarınca re'sen","İçişleri Bakanlığının izniyle","Cumhurbaşkanlığının onayıyla","Yalnızca basında yayımlanması hâlinde"],"dogru":1,"aciklama":"m.3: 'Bu kanunda yazılı suçlardan dolayı Cumhuriyet savcılıklarınca re'sen takibat yapılır.' Suçlar şikâyete bağlı değildir.","kaynak":"5816 m.3","zorluk":"kolay"},
    {"id":"5816-S-011","soru":"5816 sayılı Kanun'da yazılı suçların takibi, mağdurun şikâyetine bağlıdır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.3'e göre bu suçlar şikâyete bağlı olmayıp Cumhuriyet savcılıklarınca re'sen takip edilir.","kaynak":"5816 m.3","zorluk":"kolay"},
    {"id":"5816-S-012","soru":"5816 sayılı Kanun'a göre: 'Birinci maddede yazılı suçlar; iki veya daha fazla kimseler tarafından toplu olarak veya umumi veya umuma açık mahallerde yahut basın vasıtasiyle işlenirse hükmolunacak ceza ______ artırılır.' Boşluğa gelecek ifade aşağıdakilerden hangisidir?","siklar":["yarı nispetinde","bir misli","iki misli","üçte bir oranında","dörtte bir oranında"],"dogru":0,"aciklama":"m.2/1 metni: '...hükmolunacak ceza yarı nispetinde artırılır.'","kaynak":"5816 m.2/1","zorluk":"orta"},
    {"id":"5816-S-013","soru":"5816 sayılı Atatürk Aleyhine İşlenen Suçlar Hakkında Kanun ile ilgili aşağıdaki ifadelerden hangisi DOĞRUDUR?","siklar":["Atatürk'ün hatırasına alenen söven kimseye bir yıldan beş yıla kadar ağır hapis cezası verilir.","Anıt ve kabir tahribi suçu basın yoluyla işlenirse hükmolunacak ceza bir misli artırılır.","Atatürk büstünü tahrip eden kimseye altı aydan iki yıla kadar hapis cezası verilir.","Birinci maddedeki suçları işlemeye başkalarını teşvik eden kimse asıl fail gibi cezalandırılır.","Bu kanunda yazılı suçların takibi mağdurun şikâyetine bağlıdır."],"dogru":3,"aciklama":"D doğrudur (m.1/3: teşvik eden asıl fail gibi cezalandırılır). A yanlış: hatıraya hakaret/sövme 1-3 yıl HAPİS'tir, 1-5 yıl ağır hapis anıt/kabir suçudur. B yanlış: basın halinde ceza YARI artar; 'bir misli' yalnız anıt suçunun zor kullanılarak işlenmesinde (m.2/2) söz konusudur. C yanlış: büst tahribi 1-5 yıl ağır hapistir. E yanlış: suçlar re'sen takip edilir (m.3).","kaynak":"5816 m.1-m.3","zorluk":"zor"},
    {"id":"5816-OO-001","soru":"A, bir sohbet sırasında yanındaki birkaç kişinin duyacağı şekilde yüksek sesle Atatürk'ün hatırasına alenen söven sözler sarf etmiştir. Olayda Atatürk'ü temsil eden herhangi bir heykel, büst veya kabre fiziki bir zarar verilmemiş; fiil birden fazla kişi tarafından toplu olarak, umumi ya da umuma açık bir mahalde veya basın vasıtasıyla da işlenmemiştir. 5816 sayılı Kanun'a göre A'nın fiili hangi suçu oluşturur ve hangi ceza uygulanır?","siklar":["Atatürk'ün hatırasına hakaret/sövme suçu; bir yıldan üç yıla kadar hapis","Atatürk'ü temsil eden abideyi tahrip suçu; bir yıldan beş yıla kadar ağır hapis","Atatürk'ün hatırasına hakaret/sövme suçu; bir yıldan beş yıla kadar ağır hapis","Atatürk'ün hatırasına hakaret/sövme suçu; altı aydan iki yıla kadar hapis","Fiil suç oluşturmaz; yalnızca idari para cezası uygulanır"],"dogru":0,"aciklama":"Olayda fiziki bir tahrip yoktur; alenen sövme söz konusudur. m.1/1: 'Atatürk'ün hatırasına alenen hakaret eden veya söven kimse bir yıldan üç yıla kadar hapis cezası ile cezalandırılır.' Ceza türü hapis, süre 1-3 yıldır.","kaynak":"5816 m.1/1","zorluk":"orta"},
    {"id":"5816-OO-002","soru":"A, gece vakti bir meydandaki Atatürk büstünü sprey boya ile kirletmiş ve üzerindeki plakayı kırmıştır. 5816 sayılı Kanun'a göre A'nın bu fiili hangi suçu oluşturur ve uygulanacak ceza nedir?","siklar":["Hatıraya hakaret suçu; bir yıldan üç yıla kadar hapis","Atatürk'ü temsil eden büstü tahrip etme/kirletme suçu; bir yıldan beş yıla kadar ağır hapis","Atatürk'ü temsil eden büstü tahrip etme suçu; bir yıldan üç yıla kadar hapis","Mala zarar verme suçu; yalnızca tazminat sorumluluğu","Atatürk'ü temsil eden büstü tahrip etme suçu; iki yıldan beş yıla kadar ağır hapis"],"dogru":1,"aciklama":"m.1/2: Atatürk'ü temsil eden heykel, büst ve abideleri veyahut kabrini 'tahrip eden, kıran, bozan veya kirleten kimseye bir yıldan beş yıla kadar ağır hapis cezası verilir.' Kirletme ve kırma bu fıkrada sayılan seçimlik hareketlerdendir; ceza 1-5 yıl ağır hapistir.","kaynak":"5816 m.1/2","zorluk":"orta"},
    {"id":"5816-OO-003","soru":"A, arkadaşı B'yi sürekli kışkırtarak bir parktaki Atatürk abidesini tahrip etmeye teşvik etmiş; bunun üzerine B abideyi tahrip etmiştir. A olay sırasında abideye fiilen hiç dokunmamıştır. 5816 sayılı Kanun'a göre teşvik eden A'nın cezai durumu nedir?","siklar":["A asıl fail (B) gibi cezalandırılır","A'ya asıl failin cezasının yarısı verilir","A fiilen tahrip etmediği için cezalandırılamaz","A'ya yalnızca hatıraya hakaret cezası verilir","A'nın cezası, ancak B şikâyetçi olursa uygulanır"],"dogru":0,"aciklama":"m.1/3: 'Yukarki fıkralarda yazılı suçları işlemeye başkalarını teşvik eden kimse asıl fail gibi cezalandırılır.' Teşvik eden, fiili bizzat işlememiş olsa dahi asıl fail gibi sorumludur.","kaynak":"5816 m.1/3","zorluk":"orta"},
    {"id":"5816-OO-004","soru":"A, B ve C birlikte hareket ederek bir meydandaki Atatürk heykelini birlikte tahrip etmişlerdir. Tahrip fiili zor kullanılmaksızın gerçekleşmiştir. 5816 sayılı Kanun'a göre, fiilin iki veya daha fazla kişi tarafından toplu olarak işlenmiş olması nedeniyle hükmolunacak ceza ne oranda artırılır?","siklar":["Yarı nispetinde artırılır","Bir misli artırılır","İki misli artırılır","Üçte bir oranında artırılır","Artırım uygulanmaz; temel ceza verilir"],"dogru":0,"aciklama":"m.2/1: 1. maddedeki suçlar 'iki veya daha fazla kimseler tarafından toplu olarak' işlenirse hükmolunacak ceza yarı nispetinde artırılır. Olayda zor kullanma olmadığından m.2/2'nin bir misli artırımı uygulanmaz.","kaynak":"5816 m.2/1","zorluk":"zor"},
    {"id":"5816-OO-005","soru":"Gazeteci A, yazdığı köşe yazısında Atatürk'ün hatırasına alenen hakaret eden ifadeler kullanmış ve bu yazı yüksek tirajlı bir gazetede yayımlanmıştır. 5816 sayılı Kanun'a göre A hakkında hükmolunacak ceza, fiilin hangi nitelik nedeniyle ve ne oranda artırılır?","siklar":["Basın vasıtasıyla işlenmesi nedeniyle yarı nispetinde","Basın vasıtasıyla işlenmesi nedeniyle bir misli","Toplu olarak işlenmesi nedeniyle bir misli","Zor kullanılarak işlenmesi nedeniyle bir misli","Hiçbir artırım uygulanmaz; basın yoluyla işlenmesi artırıcı sebep değildir"],"dogru":0,"aciklama":"m.2/1: 1. maddedeki suçlar 'basın vasıtasiyle' işlenirse hükmolunacak ceza yarı nispetinde artırılır. Basın yoluyla işleme bu fıkrada açıkça sayılan ağırlaştırıcı hâldir ve artırım oranı yarıdır.","kaynak":"5816 m.2/1","zorluk":"orta"},
    {"id":"5816-OO-006","soru":"A, bir abideyi tahrip etmek amacıyla, abideyi koruyan güvenlik bariyerlerini zorla aşıp önüne geçmeye çalışan görevliye karşı zor kullanarak abideyi kırmıştır. 5816 sayılı Kanun'a göre bu olayda verilecek ceza ne şekilde belirlenir?","siklar":["Abide tahribi cezası bir misli artırılır","Abide tahribi cezası yarı nispetinde artırılır","Abide tahribi cezası üçte bir oranında artırılır","Yalnızca temel ceza verilir; zor kullanma artırım sebebi değildir","Abide tahribi cezası iki misli artırılır"],"dogru":0,"aciklama":"m.2/2: 1. maddenin 2. fıkrasındaki suçlar (heykel/büst/abide/kabir tahribi) 'zor kullanılarak işlenir veya bu suretle işlenmesine teşebbüs olunursa verilecek ceza bir misli artırılır.' Olayda anıt suçu zor kullanılarak işlendiği için artırım bir mislidir.","kaynak":"5816 m.2/2","zorluk":"zor"},
    {"id":"5816-OO-007","soru":"A, bir abideyi zor kullanarak tahrip etmek üzere harekete geçmiş; ancak elindeki balyozu abideye indirmeden, çevredekiler tarafından engellenerek yakalanmış ve abideye fiili bir zarar verememiştir. 5816 sayılı Kanun'a göre A'nın cezası bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Suç tamamlanmadığından A'ya hiçbir ceza verilmez","Zor kullanarak işlenmesine teşebbüs olunduğundan verilecek ceza bir misli artırılır","Teşebbüs hâlinde ceza yalnızca yarı nispetinde artırılır","Teşebbüs ağırlaştırıcı kapsamda olmadığından sadece temel ceza verilir","Teşebbüs nedeniyle ceza üçte bir oranında artırılır"],"dogru":1,"aciklama":"m.2/2: anıt suçunun 'zor kullanılarak işlenir VEYA bu suretle işlenmesine teşebbüs olunursa verilecek ceza bir misli artırılır.' Madde, zor kullanarak işlenmeye teşebbüsü de açıkça bir misli artırım kapsamına almıştır.","kaynak":"5816 m.2/2","zorluk":"zor"},
    {"id":"5816-OO-008","soru":"Bir meydandaki Atatürk büstünün tahrip edildiğini gören vatandaşlar olayı duyurmuş; ancak hiç kimse resmî bir şikâyette bulunmamıştır. 5816 sayılı Kanun'a göre bu suçun soruşturulması bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Cumhuriyet savcılığı şikâyet beklemeksizin re'sen takibat yapar","Şikâyet bulunmadığından soruşturma açılamaz","Soruşturma için İçişleri Bakanlığının izni gerekir","Soruşturma ancak Cumhurbaşkanlığının onayıyla yapılabilir","Suç yalnızca basında yer alırsa takip edilir"],"dogru":0,"aciklama":"m.3: 'Bu kanunda yazılı suçlardan dolayı Cumhuriyet savcılıklarınca re'sen takibat yapılır.' Suç şikâyete bağlı değildir; savcılık kendiliğinden harekete geçer.","kaynak":"5816 m.3","zorluk":"orta"},
  ],
  10: [
    {"id":"6284-S-001","soru":"6284 sayılı Kanunun amacına göre, aşağıdakilerden hangisi Kanun kapsamında korunması öngörülen kişilerden biri DEĞİLDİR?","siklar":["Kadınlar","Çocuklar","Komşuluk ilişkisinde mağdur olan kişiler","Aile bireyleri","Tek taraflı ısrarlı takip mağduru olan kişiler"],"dogru":2,"aciklama":"m.1/1'de korunanlar; şiddete uğrayan veya uğrama tehlikesi bulunan kadınlar, çocuklar, aile bireyleri ve tek taraflı ısrarlı takip mağduru olan kişiler olarak sayılmıştır. 'Komşuluk ilişkisinde mağdur olanlar' sayılmamıştır.","kaynak":"6284 m.1/1","zorluk":"kolay"},
    {"id":"6284-S-002","soru":"6284 sayılı Kanundaki tanıma göre 'Hâkim' ibaresi, aile mahkemesi hâkimini ifade eder.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.2/1-c: 'Hâkim: Aile mahkemesi hâkimini' ifade eder. Bu nedenle Kanundaki tedbir kararlarında 'hâkim' denildiğinde aile mahkemesi hâkimi kastedilir.","kaynak":"6284 m.2/1-c","zorluk":"kolay"},
    {"id":"6284-S-003","soru":"6284 sayılı Kanundaki 'şiddet' tanımına göre, aşağıdakilerden hangisi metinde sayılan şiddet türlerinden biri DEĞİLDİR?","siklar":["Fiziksel","Cinsel","Ekonomik","Dini","Psikolojik"],"dogru":3,"aciklama":"m.2/1-d şiddeti fiziksel, cinsel, psikolojik, sözlü veya ekonomik her türlü tutum ve davranış olarak tanımlar. 'Dini şiddet' tanımda sayılmamıştır.","kaynak":"6284 m.2/1-d","zorluk":"orta"},
    {"id":"6284-S-004","soru":"6284 sayılı Kanunun 3. maddesine göre, gecikmesinde sakınca bulunan hâllerde barınma veya geçici koruma tedbirini alan kolluk amiri, düzenlediği evrakı en geç ne zaman mülkî amirin onayına sunar?","siklar":["Kararın alındığı tarihi takip eden ilk işgünü içinde","Yirmidört saat içinde","Kırksekiz saat içinde","Üç gün içinde","Bir hafta içinde"],"dogru":0,"aciklama":"m.3/2: 'Kolluk amiri evrakı en geç kararın alındığı tarihi takip eden ilk işgünü içinde mülkî amirin onayına sunar.' Mülkî amir tarafından kırksekiz saat içinde onaylanmayan tedbirler ise kendiliğinden kalkar.","kaynak":"6284 m.3/2","zorluk":"orta"},
    {"id":"6284-S-005","soru":"6284 sayılı Kanuna göre, gecikmesinde sakınca bulunan hâllerde kolluk amirince alınan barınma ve geçici koruma tedbirleri, mülkî amir tarafından kaç saat içinde onaylanmazsa kendiliğinden kalkar?","siklar":["24 saat","36 saat","48 saat","72 saat","96 saat"],"dogru":2,"aciklama":"m.3/2: Mülkî amir tarafından kırksekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar.","kaynak":"6284 m.3/2","zorluk":"orta"},
    {"id":"6284-S-006","soru":"6284 sayılı Kanunun 3. maddesine göre, mülkî amir tarafından kreş imkânı; korunan kişinin çocukları varsa çalışma yaşamına katılımını desteklemek üzere ____ ay, kişinin çalışması hâlinde ise ____ aylık süre ile sınırlı olmak kaydıyla sağlanabilir. Boşluklara sırasıyla aşağıdakilerden hangileri gelmelidir?","siklar":["Altı - üç","Üç - bir","İki - dört","Dört - iki","Beş - üç"],"dogru":3,"aciklama":"m.3/1-d: çalışma yaşamına katılımı desteklemek üzere dört ay, kişinin çalışması hâlinde ise iki aylık süre ile sınırlıdır.","kaynak":"6284 m.3/1-d","zorluk":"zor"},
    {"id":"6284-S-007","soru":"6284 sayılı Kanunun 4. maddesi gereğince, aşağıdakilerden hangisi HÂKİM tarafından korunan kişilerle ilgili olarak alınabilecek koruyucu tedbirlerden biridir?","siklar":["Geçici maddi yardım yapılması","Müşterek konuttan derhâl uzaklaştırılması","Uygun barınma yeri sağlanması","Silahların kolluğa teslim edilmesi","Tapu kütüğüne aile konutu şerhi konulması"],"dogru":4,"aciklama":"m.4/1-c: Türk Medenî Kanunundaki şartların varlığı ve korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması, hâkim tarafından verilen koruyucu tedbirdir.","kaynak":"6284 m.4/1","zorluk":"orta"},
    {"id":"6284-S-008","soru":"6284 sayılı Kanuna göre, korunan kişinin kimlik ve ilgili diğer bilgi ve belgelerinin değiştirilmesi, mülkî amir tarafından verilebilecek koruyucu tedbirlerdendir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kimlik ve belgelerin değiştirilmesi m.4/1-ç uyarınca HÂKİM tarafından verilen koruyucu tedbirdir; mülkî amir tedbirleri arasında yer almaz.","kaynak":"6284 m.4/1-ç","zorluk":"orta"},
    {"id":"6284-S-009","soru":"6284 sayılı Kanuna göre, şiddet uygulayanlar hakkında önleyici tedbir kararı, mülkî amir tarafından da verilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5/1: Önleyici tedbirlere yalnızca HÂKİM karar verir. Gecikmesinde sakınca bulunan hâllerde bazı önleyici tedbirleri kolluk amiri geçici alabilir (m.5/2) ama mülkî amir önleyici tedbir veremez.","kaynak":"6284 m.5/1","zorluk":"orta"},
    {"id":"6284-S-010","soru":"6284 sayılı Kanunun 5. maddesine göre, gecikmesinde sakınca bulunan hâllerde önleyici tedbirlerin bir kısmı ilgili kolluk amirince de alınabilir. Aşağıdaki önleyici tedbirlerden hangisi kolluk amiri tarafından alınamaz; yalnızca hâkim tarafından verilebilir?","siklar":["Şiddet mağduruna yönelik tehdit, hakaret veya aşağılama içeren söz ve davranışlarda bulunmaması","Müşterek konuttan derhâl uzaklaştırılması ve konutun korunan kişiye tahsis edilmesi","Korunan kişinin bulunduğu konuta, okula ve işyerine yaklaşmaması","Bulundurulmasına veya taşınmasına izin verilen silahları kolluğa teslim etmesi","Şiddete uğramamış olsa bile korunan kişinin yakınlarına ve tanıklarına yaklaşmaması"],"dogru":3,"aciklama":"m.5/2: Gecikmesinde sakınca bulunan hâllerde kolluk amiri yalnız birinci fıkranın (a), (b), (c) ve (d) bentlerindeki önleyici tedbirleri alabilir. Silahların kolluğa teslimi (g bendi) bu kapsamda olmadığından kolluk amirince alınamaz; yalnız hâkim verebilir.","kaynak":"6284 m.5/2","zorluk":"orta"},
    {"id":"6284-S-011","soru":"6284 sayılı Kanuna göre, gecikmesinde sakınca bulunan hâllerde kolluk amirince alınan önleyici tedbirler, hâkim tarafından kaç saat içinde onaylanmazsa kendiliğinden kalkar?","siklar":["12 saat","24 saat","36 saat","48 saat","72 saat"],"dogru":1,"aciklama":"m.5/2: Hâkim tarafından yirmidört saat içinde onaylanmayan tedbirler kendiliğinden kalkar.","kaynak":"6284 m.5/2","zorluk":"orta"},
    {"id":"6284-S-012","soru":"6284 sayılı Kanunun 8. maddesine göre, tedbir kararı ilk defasında en çok ne kadar süre için verilebilir?","siklar":["Üç ay","Dört ay","Altı ay","Bir yıl","İki yıl"],"dogru":2,"aciklama":"m.8/2: Tedbir kararı ilk defasında en çok altı ay için verilebilir.","kaynak":"6284 m.8/2","zorluk":"kolay"},
    {"id":"6284-S-013","soru":"6284 sayılı Kanuna göre, koruyucu tedbir kararı verilebilmesi için şiddetin uygulandığı hususunda delil veya belge aranmaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.8/3: Koruyucu tedbir kararı verilebilmesi için şiddetin uygulandığı hususunda delil veya belge aranmaz; önleyici tedbir kararı da geciktirilmeksizin verilir.","kaynak":"6284 m.8/3","zorluk":"orta"},
    {"id":"6284-S-014","soru":"6284 sayılı Kanunun 8. maddesine göre, tedbir kararının tefhim ve tebliğ işlemleri sırasında, tedbir kararına aykırılık hâlinde şiddet uygulayan hakkında aşağıdakilerden hangisinin uygulanacağı ihtar edilir?","siklar":["Adli para cezası","İdari para cezası","Güvenlik tedbiri","Disiplin cezası","Zorlama hapsi"],"dogru":4,"aciklama":"m.8/5: 'Tedbir kararının tefhim ve tebliğ işlemlerinde, tedbir kararına aykırılık hâlinde şiddet uygulayan hakkında zorlama hapsinin uygulanacağı ihtarı yapılır.'","kaynak":"6284 m.8/5","zorluk":"orta"},
    {"id":"6284-S-015","soru":"6284 sayılı Kanuna göre, Kanun hükümlerine göre verilen kararlara karşı tefhim veya tebliğ tarihinden itibaren hangi süre içinde ve nereye itiraz edilebilir?","siklar":["Bir hafta içinde asliye hukuk mahkemesine","Bir ay içinde aile mahkemesine","İki hafta içinde sulh ceza hâkimliğine","İki hafta içinde aile mahkemesine","On gün içinde Cumhuriyet başsavcılığına"],"dogru":3,"aciklama":"m.9/1: Kararlara karşı tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir.","kaynak":"6284 m.9/1","zorluk":"orta"},
    {"id":"6284-S-016","soru":"6284 sayılı Kanunun 9. maddesine göre, 'İtiraz mercii kararını ____ içinde verir. İtiraz üzerine verilen kararlar ____.' Boşluklara sırasıyla aşağıdakilerden hangileri gelmelidir?","siklar":["İki hafta - temyiz edilebilir","Bir hafta - kesindir","On gün - istinaf edilebilir","Bir ay - kesindir","Bir hafta - temyiz edilebilir"],"dogru":1,"aciklama":"m.9/3: İtiraz mercii kararını bir hafta içinde verir. İtiraz üzerine verilen kararlar kesindir.","kaynak":"6284 m.9/3","zorluk":"orta"},
    {"id":"6284-S-017","soru":"6284 sayılı Kanunun 13. maddesine göre, hakkında tedbir kararı verilen şiddet uygulayan kararın gereklerine aykırı hareket ederse, ilk aykırılıkta hâkim kararıyla ne kadar zorlama hapsine tabi tutulur?","siklar":["Üç günden on güne kadar","On beş günden otuz güne kadar","Bir günden yedi güne kadar","Beş günden on beş güne kadar","On günden yirmi güne kadar"],"dogru":0,"aciklama":"m.13/1: Aykırı hareket hâlinde, fiil ayrıca suç oluştursa bile, hâkim kararıyla üç günden on güne kadar zorlama hapsine tabi tutulur.","kaynak":"6284 m.13/1","zorluk":"orta"},
    {"id":"6284-S-018","soru":"6284 sayılı Kanunun 13. maddesine göre, tedbir kararının gereklerine aykırılığın her tekrarında zorlama hapsinin süresi ne kadardır?","siklar":["Üç günden on güne kadar","Beş günden on beş güne kadar","On günden yirmi güne kadar","Yirmi günden kırk güne kadar","On beş günden otuz güne kadar"],"dogru":4,"aciklama":"m.13/2: Aykırılığın her tekrarında zorlama hapsinin süresi onbeş günden otuz güne kadardır.","kaynak":"6284 m.13/2","zorluk":"orta"},
    {"id":"6284-S-019","soru":"6284 sayılı Kanunun 13. maddesine göre, tedbir kararının gereklerine aykırılığın tekrarı hâlinde uygulanan zorlama hapsinin TOPLAM süresi en çok ne kadar olabilir?","siklar":["Üç ay","Dört ay","Altı ay","Sekiz ay","Bir yıl"],"dogru":2,"aciklama":"m.13/2: 'Ancak zorlama hapsinin toplam süresi altı ayı geçemez.' Her tekrarda 15-30 gün verilebilse de toplam tavan altı aydır.","kaynak":"6284 m.13/2","zorluk":"orta"},
    {"id":"6284-S-020","soru":"6284 sayılı Kanunun 13. maddesine göre, 'Zorlama hapsine ilişkin kararlar, ____ tarafından yerine getirilir. Bu kararlar ____ bildirilir.' Boşluklara sırasıyla aşağıdakilerden hangileri gelmelidir?","siklar":["Aile mahkemesi - kolluğa","Cumhuriyet başsavcılığı - Bakanlığın ilgili il ve ilçe müdürlüklerine","Mülkî amir - Cumhuriyet başsavcılığına","Kolluk - ŞÖNİM'e","Cumhuriyet başsavcılığı - aile mahkemesine"],"dogru":1,"aciklama":"m.13/3: 'Zorlama hapsine ilişkin kararlar, Cumhuriyet başsavcılığınca yerine getirilir. Bu kararlar Bakanlığın ilgili il ve ilçe müdürlüklerine bildirilir.'","kaynak":"6284 m.13/3","zorluk":"orta"},
    {"id":"6284-S-021","soru":"6284 sayılı Kanuna göre, tedbir kararının gereklerine aykırı hareket eden şiddet uygulayan, bu fiili ayrıca bir suç oluştursa bile zorlama hapsine tabi tutulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.13/1: Aykırı hareket eden, 'fiili bir suç oluştursa bile' ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim kararıyla zorlama hapsine tabi tutulur.","kaynak":"6284 m.13/1","zorluk":"orta"},
    {"id":"6284-S-022","soru":"6284 sayılı Kanuna göre koruyucu ve önleyici tedbirlerle ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Koruyucu tedbir şiddet uygulayana, önleyici tedbir korunan kişiye yöneliktir.","Koruyucu tedbir yalnız hâkim, önleyici tedbir yalnız mülkî amir tarafından verilir.","Koruyucu tedbir korunan kişiye, önleyici tedbir şiddet uygulayana yöneliktir.","Önleyici tedbir hem hâkim hem mülkî amir tarafından verilebilir.","Koruyucu tedbir yalnızca kolluk amiri tarafından verilebilir."],"dogru":2,"aciklama":"Koruyucu tedbirler korunan kişiye (mağdura) yöneliktir ve mülkî amir (m.3) ile hâkim (m.4) tarafından verilir; önleyici tedbirler şiddet uygulayana (faile) yöneliktir ve yalnız hâkim (m.5) tarafından verilir.","kaynak":"6284 m.3, m.4, m.5","zorluk":"orta"},
    {"id":"6284-OO-001","soru":"Gece yarısı yapılan ihbar üzerine olay yerine giden kolluk amiri, eve dönen şiddet uygulayan B'nin korunan kişi A için ağır tehlike oluşturduğunu görür; hâkime o an ulaşmak mümkün değildir. Kolluk amiri B'yi müşterek konuttan derhâl uzaklaştırır ve konutu A'ya tahsis eder. 6284 sayılı Kanuna göre bu işlemin hukuki durumu aşağıdakilerden hangisidir?","siklar":["İşlem geçersizdir; uzaklaştırma önleyici tedbirdir ve hiçbir hâlde kolluk amirince alınamaz, yalnız hâkim verebilir.","İşlem geçerlidir; gecikmesinde sakınca bulunduğundan kolluk amiri bu tedbiri alabilir, ancak hâkim tarafından yirmidört saat içinde onaylanmazsa kendiliğinden kalkar.","İşlem geçerlidir; tedbir mülkî amir tarafından kırksekiz saat içinde onaylanmazsa kendiliğinden kalkar.","İşlem geçersizdir; kolluk amiri ancak korunan kişiye barınma ve geçici koruma sağlayabilir, faile yönelik tedbir alamaz.","İşlem geçerlidir ve kalıcıdır; kolluk amirinin aldığı tedbir için ayrıca hâkim onayı gerekmez."],"dogru":1,"aciklama":"m.5/2: Gecikmesinde sakınca bulunan hâllerde birinci fıkranın (a), (b), (c) ve (d) bentlerindeki önleyici tedbirler kolluk amirince de alınabilir; müşterek konuttan uzaklaştırma ve konutun korunan kişiye tahsisi (b) bu kapsamdadır. Kolluk amiri evrakı en geç ilk işgünü hâkim onayına sunar; hâkim tarafından yirmidört saat içinde onaylanmayan tedbirler kendiliğinden kalkar.","kaynak":"6284 m.5/2","zorluk":"orta"},
    {"id":"6284-OO-002","soru":"Korunan kişi A'nın küçük bir çocuğu vardır ve A hâlihazırda bir işte çalışmaktadır. Mülkî amir, A lehine kreş imkânı sağlanmasına karar verir. 6284 sayılı Kanuna göre, A çalıştığına göre bu kreş imkânı en çok ne kadar süreyle sağlanabilir?","siklar":["Dört ay","Üç ay","İki ay","Altı ay","Bir yıl"],"dogru":2,"aciklama":"m.3/1-d: Kreş imkânı, korunan kişinin çocukları varsa çalışma yaşamına katılımını desteklemek üzere dört ay, kişinin çalışması hâlinde ise iki aylık süre ile sınırlıdır. Olayda A zaten çalıştığından süre iki aydır.","kaynak":"6284 m.3/1-d","zorluk":"orta"},
    {"id":"6284-OO-003","soru":"Aile mahkemesi hâkimi, korunan kişi A'nın güvenliğini sağlamak amacıyla A'nın işyerinin değiştirilmesine karar verir. 6284 sayılı Kanuna göre bu karar, türü ve muhatabı bakımından nasıl nitelendirilir?","siklar":["Şiddet uygulayana yönelik önleyici tedbirdir.","Korunan kişiye yönelik, hâkim tarafından verilen koruyucu tedbirdir.","Korunan kişiye yönelik, mülkî amir tarafından verilen koruyucu tedbirdir.","Şiddet uygulayana yönelik, kolluk amirince alınan önleyici tedbirdir.","Korunan kişiye yönelik önleyici tedbirdir."],"dogru":1,"aciklama":"m.4/1-a: İşyerinin değiştirilmesi, korunan kişiyle ilgili olarak HÂKİM tarafından verilen koruyucu tedbirler arasındadır. Koruyucu tedbir korunan kişiye (mağdura) yöneliktir.","kaynak":"6284 m.4/1-a","zorluk":"orta"},
    {"id":"6284-OO-004","soru":"Şiddet uygulayan B, görevi gereği silah taşıması zorunlu olan bir kamu görevlisidir ve elindeki silah görevi nedeniyle zimmetindedir. Hâkim, B hakkında önleyici tedbir kararı verecektir. 6284 sayılı Kanuna göre bu silah bakımından verilecek doğru önleyici tedbir aşağıdakilerden hangisidir?","siklar":["Zimmetindeki silahı kolluğa teslim etmesi","Zimmetindeki silahı kurumuna teslim etmesi","Silahını korunan kişiye teslim etmesi","Silahını mülkî amire teslim etmesi","Silahıyla ilgili herhangi bir tedbir verilemez, çünkü silah taşıması zorunludur"],"dogru":1,"aciklama":"m.5/1-ğ: Silah taşıması zorunlu olan bir kamu görevi ifa etse bile, şiddet uygulayanın bu görevi nedeniyle zimmetinde bulunan silahı KURUMUNA teslim etmesine karar verilebilir. Kanunen izin verilen kişisel silahlar ise (g bendi) kolluğa teslim edilir.","kaynak":"6284 m.5/1-ğ","zorluk":"zor"},
    {"id":"6284-OO-005","soru":"Hakkında, korunan kişi A'nın evine yaklaşmama tedbiri verilen şiddet uygulayan B, ilk kez bu karara aykırı davranarak A'nın evinin önüne gelir. Fiili ayrıca bir suç da oluşturmaktadır. 6284 sayılı Kanuna göre bu ilk aykırılık nedeniyle B hakkında ne yapılır?","siklar":["Hâkim kararıyla üç günden on güne kadar zorlama hapsine tabi tutulur.","Hâkim kararıyla onbeş günden otuz güne kadar zorlama hapsine tabi tutulur.","Fiil ayrıca suç oluşturduğundan zorlama hapsi uygulanamaz, yalnız ceza soruşturması yürütülür.","Mülkî amir tarafından idari para cezası verilir.","Kolluk amiri tarafından doğrudan gözaltına alınarak zorlama hapsi uygulanır."],"dogru":0,"aciklama":"m.13/1: Tedbir kararının gereklerine aykırı hareket eden şiddet uygulayan, fiili bir suç oluştursa bile, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim kararıyla üç günden on güne kadar zorlama hapsine tabi tutulur.","kaynak":"6284 m.13/1","zorluk":"orta"},
    {"id":"6284-OO-006","soru":"Şiddet uygulayan B, hakkındaki yaklaşmama tedbirini daha önce bir kez ihlal etmiş ve zorlama hapsine tabi tutulmuştu. B bu kez aynı tedbiri yeniden ihlal eder. 6284 sayılı Kanuna göre, aykırılığın bu tekrarında B hakkında uygulanacak zorlama hapsinin süresi ne kadardır?","siklar":["Üç günden on güne kadar","Beş günden on beş güne kadar","Onbeş günden otuz güne kadar","Bir aydan üç aya kadar","Yirmi günden kırk güne kadar"],"dogru":2,"aciklama":"m.13/2: Tedbir kararının gereklerine aykırılığın her tekrarında, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre zorlama hapsinin süresi onbeş günden otuz güne kadardır (toplam altı ayı geçemez).","kaynak":"6284 m.13/2","zorluk":"orta"},
    {"id":"6284-OO-007","soru":"Korunan kişi A, eşinin şiddetinden korktuğunu belirterek hâkimden koruyucu tedbir talep eder; ancak elinde darp raporu, tanık veya başka bir delil yoktur. 6284 sayılı Kanuna göre hâkim ne yapmalıdır?","siklar":["Koruyucu tedbir kararı verebilmesi için şiddetin uygulandığına dair delil veya belge aranmadığından, talebi delil yokluğu gerekçesiyle reddedemez.","Delil sunulmadığı için talebi reddetmelidir.","A'ya delil toplaması için en az bir hafta süre vermek zorundadır.","Talebi, delil değerlendirmesi yapması için Cumhuriyet savcısına göndermelidir.","Yalnızca tanık dinledikten sonra karar verebilir."],"dogru":0,"aciklama":"m.8/3: Koruyucu tedbir kararı verilebilmesi için şiddetin uygulandığı hususunda delil veya belge aranmaz; önleyici tedbir kararı da geciktirilmeksizin verilir. Bu nedenle hâkim, delil bulunmadığı gerekçesiyle koruyucu tedbir talebini reddedemez.","kaynak":"6284 m.8/3","zorluk":"orta"},
    {"id":"6284-OO-008","soru":"Hakkında önleyici tedbir kararı verilen B, kararı haksız bulmaktadır. Karar B'ye tebliğ edileli on gün olmuştur. 6284 sayılı Kanuna göre B'nin bu karara itirazı bakımından aşağıdakilerden hangisi doğrudur?","siklar":["İtiraz süresi tebliğden itibaren bir haftadır; B'nin süresi geçmiştir.","İtiraz süresi tebliğden itibaren iki haftadır; B süresi içinde aile mahkemesine itiraz edebilir.","İtiraz süresi tebliğden itibaren iki haftadır; B sulh ceza hâkimliğine itiraz etmelidir.","İtiraz süresi bir aydır; B asliye hukuk mahkemesine başvurmalıdır.","Tedbir kararlarına karşı itiraz yolu kapalıdır; B ancak iptal davası açabilir."],"dogru":1,"aciklama":"m.9/1: Kanun hükümlerine göre verilen kararlara karşı tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir. On gün geçtiğinden B'nin süresi henüz dolmamıştır.","kaynak":"6284 m.9/1","zorluk":"orta"},
    {"id":"6284-OO-009","soru":"Gecikmesinde sakınca bulunan bir durumda kolluk amiri, korunan kişi A'ya derhâl uygun barınma yeri sağlar ve evrakı en geç kararı izleyen ilk işgünü mülkî amirin onayına sunar. 6284 sayılı Kanuna göre bu koruyucu tedbir bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Tedbir, hâkim tarafından yirmidört saat içinde onaylanmazsa kendiliğinden kalkar.","Tedbir, mülkî amir tarafından kırksekiz saat içinde onaylanmazsa kendiliğinden kalkar.","Tedbir, mülkî amir tarafından yirmidört saat içinde onaylanmazsa kendiliğinden kalkar.","Tedbir, hâkim tarafından kırksekiz saat içinde onaylanmazsa kendiliğinden kalkar.","Kolluk amirinin aldığı barınma tedbiri için herhangi bir onaya gerek yoktur."],"dogru":1,"aciklama":"m.3/2: Gecikmesinde sakınca bulunan hâllerde barınma (a) ve geçici koruma (ç) tedbirleri kolluk amirince de alınabilir; kolluk amiri evrakı en geç ilk işgünü mülkî amirin onayına sunar ve mülkî amir tarafından kırksekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar. Bu koruyucu bir tedbir olduğundan onay makamı mülkî amir, süre 48 saattir.","kaynak":"6284 m.3/2","zorluk":"zor"},
    {"id":"6284-OO-010","soru":"Bir ilçede mülkî amir, şiddet uygulayan B hakkında doğrudan 'müşterek konuttan uzaklaştırma ve korunan kişiye yaklaşmama' kararı vererek bunu önleyici tedbir olarak uygular. 6284 sayılı Kanuna göre bu işlemin hukuki durumu nedir?","siklar":["İşlem geçerlidir; mülkî amir hem koruyucu hem önleyici tedbir verebilir.","İşlem hatalıdır; önleyici tedbirlere kural olarak yalnız hâkim karar verebilir, mülkî amir önleyici tedbir veremez.","İşlem geçerlidir; mülkî amirin kararı hâkim onayıyla kesinleşir.","İşlem geçerlidir; gecikmesinde sakınca bulunması hâlinde mülkî amir tüm önleyici tedbirleri alabilir.","İşlem hatalıdır; önleyici tedbiri yalnız kolluk amiri verebilir."],"dogru":1,"aciklama":"m.5/1: Şiddet uygulayanlarla ilgili önleyici tedbirlere HÂKİM karar verir. Gecikmesinde sakınca bulunan hâllerde bazı önleyici tedbirleri (a-b-c-d bentleri) kolluk amiri geçici olarak alabilir; ancak mülkî amir önleyici tedbir vermeye yetkili değildir. Mülkî amir yalnız m.3'teki koruyucu tedbirleri verir.","kaynak":"6284 m.5/1","zorluk":"orta"},
    {"id":"6284-OO-011","soru":"Evli olan korunan kişi A, Türk Medenî Kanunundaki şartların varlığı hâlinde, ortak konutun satılıp kendisinin mağdur edilmesini önlemek için tapu kütüğüne aile konutu şerhi konulmasını talep eder. 6284 sayılı Kanuna göre bu tedbir hangi makam tarafından ve hangi tür tedbir olarak verilir?","siklar":["Mülkî amir tarafından, koruyucu tedbir olarak","Hâkim tarafından, korunan kişiye yönelik koruyucu tedbir olarak","Hâkim tarafından, şiddet uygulayana yönelik önleyici tedbir olarak","Kolluk amiri tarafından, geçici koruyucu tedbir olarak","Tapu müdürlüğü tarafından, idari işlem olarak"],"dogru":1,"aciklama":"m.4/1-c: Türk Medenî Kanunundaki şartların varlığı hâlinde ve korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması, HÂKİM tarafından verilen koruyucu tedbirler arasındadır ve korunan kişiye yöneliktir.","kaynak":"6284 m.4/1-c","zorluk":"orta"},
  ],
  11: [
    {"id":"2893-S-001","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağı, Kanuna ekli cetvelde gösterilen şekil ve oranlarda olmak kaydıyla nasıl tanımlanır?","siklar":["Kırmızı zemin üzerine sarı ay-yıldızlı sancak","Beyaz ay-yıldızlı albayrak","Beyaz zemin üzerine kırmızı ay-yıldızlı bayrak","Kırmızı ay-yıldızlı beyaz fors","Al zemin üzerine altın ay-yıldızlı flama"],"dogru":1,"aciklama":"m.2: 'Türk Bayrağı, bu Kanuna ekli cetvelde gösterilen şekil ve oranlarda olmak kaydıyla beyaz ay-yıldızlı albayraktır.' Doğru ifade 'beyaz ay-yıldızlı albayrak'tır.","kaynak":"2893 m.2","zorluk":"kolay"},
    {"id":"2893-S-002","soru":"2893 sayılı Türk Bayrağı Kanunu'nun amacı, Türk Bayrağının hangi hususlarına ilişkin esas ve usulleri belirlemektir?","siklar":["Şekli, yapımı ve korunması","Şekli, satışı ve ithali","Yapımı, tescili ve dağıtımı","Kullanımı, vergisi ve denetimi","Şekli, rengi ve ihracı"],"dogru":0,"aciklama":"m.1: 'Bu Kanunun amacı Türk Bayrağının şekli, yapımı ve korunması ile ilgili esas ve usulleri belirlemektir.'","kaynak":"2893 m.1","zorluk":"orta"},
    {"id":"2893-S-003","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre standartları yönetmelikte gösterilen 'özel bayraklar' arasında aşağıdakilerden hangisi yer almaz?","siklar":["Sembolik bayrak","Flama","Sancak","Flandra","Fors"],"dogru":2,"aciklama":"m.2: Özel bayraklar 'sembolik bayrak, özel işaret, flama, flandra ve fors' olarak sayılmıştır. 'Sancak' bu sayımda yer almaz; sahte şıktır.","kaynak":"2893 m.2","zorluk":"orta"},
    {"id":"2893-S-004","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağı, kamu kurum ve kuruluşlarında nasıl bulundurulur?","siklar":["Yalnızca resmi tatil ve bayram günlerinde çekili kalır","Yalnızca mesai saatleri içinde çekili kalır","Sürekli çekili kalır","Güneş doğduktan batıncaya kadar çekili kalır","Haftada bir gün tören ile çekilip indirilir"],"dogru":2,"aciklama":"m.3 (Değişik: 14/7/1999-4409/1 md.): 'Kamu kurum ve kuruluşlarında Türk Bayrağı sürekli çekili kalır.'","kaynak":"2893 m.3","zorluk":"orta"},
    {"id":"2893-S-005","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre aşağıdakilerden hangisi Bayrağın çekileceği yerler arasında sayılmamıştır?","siklar":["Kamu kurum ve kuruluşları","Yurt dışı temsilcilikleri","Kamu kuruluşlarının deniz vasıtaları","Gerçek ve tüzel kişilerin deniz vasıtaları","Vatandaşların özel konutlarının çatıları"],"dogru":4,"aciklama":"m.3: 'Bayrak, kamu kurum ve kuruluşlarıyla yurt dışı temsilciliklerine ve kamu kuruluşlarıyla gerçek ve tüzelkişilerin deniz vasıtalarına çekilir.' Özel konutların çatıları bu sayımda yer almaz; çekilecek yerler kamu kurumları, yurt dışı temsilcilikleri ve (kamu kuruluşları ile gerçek/tüzel kişilerin) deniz vasıtalarıdır.","kaynak":"2893 m.3","zorluk":"zor"},
    {"id":"2893-S-006","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Bayrak törenlerinin gereken biçimde yapılmasından ......................... sorumludur. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["o mahaldeki yetkili amirler","Cumhurbaşkanlığı","mahalli mülki amir","İçişleri Bakanlığı","genelkurmay başkanlığı"],"dogru":0,"aciklama":"m.3: 'Bayrak törenlerinin gereken biçimde yapılmasından o mahaldeki yetkili amirler sorumludur.'","kaynak":"2893 m.3","zorluk":"kolay"},
    {"id":"2893-S-007","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağı, yas alameti olarak her yıl hangi gün yarıya çekilir?","siklar":["29 Ekim","23 Nisan","19 Mayıs","10 Kasım","30 Ağustos"],"dogru":3,"aciklama":"m.4: 'Türk Bayrağı, yas alameti olarak 10 Kasım'da yarıya çekilir.'","kaynak":"2893 m.4","zorluk":"kolay"},
    {"id":"2893-S-008","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağının 10 Kasım'da yarıya çekilmesi neyin alametidir?","siklar":["Yas","Zafer","Bağımsızlık","Ulusal egemenlik","Resmî tatil"],"dogru":0,"aciklama":"m.4: 'Türk Bayrağı, yas alameti olarak 10 KASIM'da yarıya çekilir.' Yarıya çekme bir yas (matem) alametidir.","kaynak":"2893 m.4","zorluk":"orta"},
    {"id":"2893-S-009","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre 10 Kasım dışındaki yas hallerinde Bayrağın yarıya çekileceği zamanı mahalli mülki amir ilan eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4'e göre diğer yas hallerini ve zamanını Cumhurbaşkanlığı ilan eder; mahalli mülki amir m.8'deki idari para cezası makamıdır.","kaynak":"2893 m.4","zorluk":"orta"},
    {"id":"2893-S-010","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre çekilmesi ve indirilmesi esnasında veya tören geçişlerinde Bayrak nasıl selamlanır?","siklar":["Baş öne eğilerek","Cephe alınarak","Sağ el kalbe götürülerek","Diz çökülerek","Sessizce el sallanarak"],"dogru":1,"aciklama":"m.5: 'Çekilmesi ve indirilmesi esnasında veya tören geçişlerinde Bayrak, cephe alınarak selamlanır.'","kaynak":"2893 m.5","zorluk":"kolay"},
    {"id":"2893-S-011","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Bayrak; çekilmesi ve indirilmesi esnasında veya tören geçişlerinde cephe alınarak selamlanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5 hükmü birebir bu şekildedir: çekilme/indirilme esnasında veya tören geçişlerinde cephe alınarak selamlanır.","kaynak":"2893 m.5","zorluk":"kolay"},
    {"id":"2893-S-012","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağının örtülebileceği yer ve haller arasında aşağıdakilerden hangisi yer almaz?","siklar":["Cumhurbaşkanlığı yapmış kişilerin cenaze töreninde tabutlarına","Şehitlerin cenaze töreninde tabutlarına","Spor müsabakalarında galip gelen sporcuların omuzlarına","Açılış törenlerinde Atatürk heykellerine","Resmi yemin törenlerinde masalara"],"dogru":2,"aciklama":"m.6: Bayrak; Cumhurbaşkanlığı yapmış kişilerin, şehitlerin ve yönetmelikte belirlenecek asker-sivil kişilerin cenazelerinde tabutlarına, açılışlarda Atatürk heykellerine, resmi yeminlerde masalara örtülebilir. 'Sporcuların omuzlarına' örtmek kanunda yer almaz; sahte şıktır.","kaynak":"2893 m.6","zorluk":"zor"},
    {"id":"2893-S-013","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre cenaze törenlerinde Türk Bayrağı, aşağıdaki kişilerden hangisinin tabutuna örtülmez?","siklar":["Cumhurbaşkanlığı yapmış kişilerin","Şehitlerin","Yönetmelikte belirlenecek asker kişilerin","Yönetmelikte belirlenecek sivil kişilerin","Vergi rekortmeni olan iş insanlarının"],"dogru":4,"aciklama":"m.6: Tabuta Bayrak örtülebilecekler 'Cumhurbaşkanlığı yapmış kişiler, şehitler ve yönetmelikte belirlenecek asker ve sivil kişiler'dir. 'Vergi rekortmeni iş insanları' bu kapsamda yer almaz.","kaynak":"2893 m.6","zorluk":"orta"},
    {"id":"2893-S-014","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağı, açılış törenlerinde ......................... örtülebilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["protokol masalarına","kürsülere","giriş kapılarına","Atatürk heykellerine","makam koltuklarına"],"dogru":3,"aciklama":"m.6: 'açılış törenlerinde ATATÜRK heykellerine ... örtülebilir.' Doğru yer Atatürk heykelleridir.","kaynak":"2893 m.6","zorluk":"orta"},
    {"id":"2893-S-015","soru":"2893 sayılı Türk Bayrağı Kanunu'nun getirdiği yasaklara göre aşağıdakilerden hangisi söylenemez?","siklar":["Bayrak yırtık, kirli, soluk veya buruşuk şekilde kullanılamaz","Bayrak elbise veya üniforma şeklinde giyilemez","Bayrak, oturulan veya ayakla basılan yerlere konulamaz","Bayrağa sözle, yazı veya hareketle hakaret edilemez","Bayrak, hiçbir törende masaya örtü olarak serilemez"],"dogru":4,"aciklama":"m.7: Bayrak 'resmi yemin törenleri dışında' masalara örtü olarak serilemez. Yani resmi yemin törenlerinde masaya serilebilir; 'hiçbir törende serilemez' ifadesi bu istisnayı yok saydığı için yanlıştır.","kaynak":"2893 m.7","zorluk":"orta"},
    {"id":"2893-S-016","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre aşağıdakilerden hangisi Bayrak hakkında açıkça yasaklanan fiillerden biri değildir?","siklar":["Yırtılması","Yakılması","Yere atılması","Onarılması","Gerekli özen gösterilmeden kullanılması"],"dogru":3,"aciklama":"m.7: 'Bayrak yırtılamaz, yakılamaz, yere atılamaz, gerekli özen gösterilmeden kullanılamaz.' 'Onarılması' kanunda yasaklanan bir fiil değildir; sahte şıktır.","kaynak":"2893 m.7","zorluk":"orta"},
    {"id":"2893-S-017","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Türk Bayrağı elbise veya üniforma şeklinde giyilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'Elbise veya üniforma şeklinde giyilemez.' Hüküm bunu açıkça yasaklar.","kaynak":"2893 m.7","zorluk":"kolay"},
    {"id":"2893-S-018","soru":"2893 sayılı Türk Bayrağı Kanunu'na aykırı davranan ve fiili suç oluşturmayan kişiye mahalli mülki amirce verilecek idarî para cezası, hangi kanunun hükümleri uyarınca uygulanır?","siklar":["Türk Ceza Kanunu'nun 125. maddesi","Kabahatler Kanunu'nun 32. maddesi","Kabahatler Kanunu'nun 41. maddesi","Türk Ceza Kanunu'nun 300. maddesi","Pasaport Kanunu'nun 32. maddesi"],"dogru":1,"aciklama":"m.8: '...mahalli mülki amir tarafından Kabahatler Kanununun 32 nci maddesi uyarınca idarî para ceza verilir.' İdarî para cezasının dayanağı Kabahatler Kanunu'nun 32. maddesidir.","kaynak":"2893 m.8","zorluk":"zor"},
    {"id":"2893-S-019","soru":"2893 sayılı Türk Bayrağı Kanunu'na göre Kanuna ve çıkarılacak yönetmeliğe aykırı olarak yapılan Bayraklar ......................... toplatılır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Cumhuriyet savcısınca","o mahallin yetkili amirlerince","Diyanet İşleri Başkanlığınca","Genelkurmay Başkanlığınca","il özel idaresince"],"dogru":1,"aciklama":"m.8: 'Bu yasağa aykırı olarak yapılan Bayraklar o mahallin yetkili amirlerince toplatılır.'","kaynak":"2893 m.8","zorluk":"orta"},
    {"id":"2893-OO-001","soru":"Bir kamu kurumunda görevli memur A, her akşam mesai bitiminde kurum binasının direğindeki Türk Bayrağını indirip ertesi sabah yeniden çekmektedir. Amiri B, bu uygulamanın kanuna aykırı olduğunu söyler. 2893 sayılı Türk Bayrağı Kanunu'na göre bu olayda doğru uygulama aşağıdakilerden hangisidir?","siklar":["Bayrak yalnızca mesai saatleri içinde çekili tutulmalı, akşam indirilmelidir","Kamu kurum ve kuruluşlarında Türk Bayrağı sürekli çekili kalmalıdır","Bayrak yalnızca resmi tatil ve bayram günlerinde çekili tutulmalıdır","Bayrak güneş battıktan sonra indirilip gün doğunca çekilmelidir","Bayrak haftada bir gün tören ile çekilip indirilmelidir"],"dogru":1,"aciklama":"m.3 (Değişik: 14/7/1999-4409/1 md.): 'Kamu kurum ve kuruluşlarında Türk Bayrağı sürekli çekili kalır.' Bu nedenle memur A'nın her akşam bayrağı indirme uygulaması kanuna aykırıdır; amir B haklıdır.","kaynak":"2893 m.3","zorluk":"orta"},
    {"id":"2893-OO-002","soru":"Büyük bir doğal afet sonrası ülke genelinde yas ilan edilmesi gündeme gelmiştir. Bu kapsamda Türk Bayrağının yas alameti olarak yarıya çekileceği günlerin ve zamanın belirlenip ilan edilmesi gerekmektedir. 2893 sayılı Türk Bayrağı Kanunu'na göre 10 Kasım dışındaki bu tür yas hallerinde Bayrağın yarıya çekileceği halleri ve zamanı hangi makam ilan eder?","siklar":["Cumhurbaşkanlığı","Mahalli mülki amir","O mahaldeki yetkili amirler","İçişleri Bakanlığı","Genelkurmay Başkanlığı"],"dogru":0,"aciklama":"m.4: 'Yas alameti olmak üzere Bayrağın yarıya çekileceği diğer haller ve zamanı Cumhurbaşkanlığınca ilan edilir.' 10 Kasım kanunla sabit olup, diğer yas hallerini ilan yetkisi Cumhurbaşkanlığına aittir.","kaynak":"2893 m.4","zorluk":"orta"},
    {"id":"2893-OO-003","soru":"Bir işletme sahibi B, Kanuna ve yönetmeliğe aykırı oranlarda ürettiği bayrakları piyasaya sürmüştür. Yapılan inceleme sonucu bu fiilin ayrıca bir suç oluşturmadığı tespit edilmiştir. 2893 sayılı Türk Bayrağı Kanunu'na göre bu olayda uygulanacak işlem aşağıdakilerden hangisidir?","siklar":["Aykırı bayraklar Cumhuriyet savcısınca toplatılır ve fail hakkında adli para cezası uygulanır","Aykırı bayraklar o mahallin yetkili amirlerince toplatılır ve mahalli mülki amir tarafından Kabahatler Kanunu m.32 uyarınca idari para cezası verilir","Aykırı bayraklar mahalli mülki amirce toplatılır ve fail Türk Ceza Kanunu m.300 uyarınca cezalandırılır","İşletme valilik kararıyla kapatılır ve fail hakkında hapis cezası uygulanır","Fiil suç oluşturmadığından hiçbir tedbir veya yaptırım uygulanamaz"],"dogru":1,"aciklama":"m.8: 'Bu yasağa aykırı olarak yapılan Bayraklar o mahallin yetkili amirlerince toplatılır. Bu Kanun hükümlerine aykırı davranışta bulunanlara, fiilleri suç oluşturmadığı takdirde mahalli mülki amir tarafından Kabahatler Kanununun 32 nci maddesi uyarınca idarî para ceza verilir.' Olayda toplatma + idari para cezası birlikte uygulanır.","kaynak":"2893 m.8","zorluk":"zor"},
    {"id":"2893-OO-004","soru":"Bir belediye, yeni hizmet binasının açılış töreninde Türk Bayrağını kürsünün ve protokol masasının üzerine örtü olarak sermeyi planlamaktadır. Bir görevli bu planın 2893 sayılı Kanuna uygun olmadığını belirtir. Kanuna göre açılış töreninde Türk Bayrağı, aşağıdakilerden hangisine örtülebilir?","siklar":["Açılış kürsüsüne","Protokol masasına","Atatürk heykeline","Bina giriş kapısına","Makam koltuğuna"],"dogru":2,"aciklama":"m.6: 'açılış törenlerinde ATATÜRK heykellerine ... örtülebilir.' Masaya örtme yalnızca resmi yemin törenlerine özgüdür (m.6 ve m.7). Açılış töreninde bayrak Atatürk heykeline örtülebilir; kürsü/masaya serilmesi kanuna aykırıdır, dolayısıyla görevli haklıdır.","kaynak":"2893 m.6","zorluk":"zor"},
    {"id":"2893-OO-005","soru":"Bir resmi törende Türk Bayrağı direğe çekilirken ve tören geçişi sırasında, tören alanındaki personelden Bayrağın usulüne uygun selamlanması istenmiştir. 2893 sayılı Türk Bayrağı Kanunu'na göre personelin Bayrağı selamlarken yapması gereken doğru davranış aşağıdakilerden hangisidir?","siklar":["Bayrağa cephe alarak (dönerek) selamlamak","Sağ eli kalbe götürmek","Başı öne eğmek","Diz çökmek","Sessizce el sallamak"],"dogru":0,"aciklama":"m.5: 'Çekilmesi ve indirilmesi esnasında veya tören geçişlerinde Bayrak, cephe alınarak selamlanır.' Doğru davranış Bayrağa cephe almaktır.","kaynak":"2893 m.5","zorluk":"kolay"},
    {"id":"2893-OO-006","soru":"Bir kamu kuruluşunda Bayrak çekme töreni gereken biçimde yapılmamış, tören sırasında usulsüzlükler yaşanmıştır. Sorumluluğun kime ait olduğu tartışılmaktadır. 2893 sayılı Türk Bayrağı Kanunu'na göre Bayrak törenlerinin gereken biçimde yapılmasından kim sorumludur?","siklar":["O mahaldeki yetkili amirler","Cumhurbaşkanlığı","Mahalli mülki amir","Cumhuriyet savcısı","Genelkurmay Başkanlığı"],"dogru":0,"aciklama":"m.3: 'Bayrak törenlerinin gereken biçimde yapılmasından o mahaldeki yetkili amirler sorumludur.' Tören usulsüzlüğünün sorumluluğu o mahaldeki yetkili amirlere aittir.","kaynak":"2893 m.3","zorluk":"orta"},
  ],
  12: [
    {"id":"7068-S-001","soru":"7068 sayılı Kanuna göre, sahil güvenlik personelinin, bu Kanunda bir disiplin cezasıyla yaptırıma bağlanmış bir fiili yurt dışı liman ziyaretlerinde veya Türk karasuları dışında işlemesi hâlinde, ceza bakımından nasıl bir sonuç doğar?","siklar":["Ceza bir derece hafifletilerek uygulanır.","Fiilin karşılığı olan cezadan bir üst derece ceza verilebilir.","Disiplin cezası uygulanmaz; yalnızca adli işlem yapılır.","Fiilin karşılığı olan ceza yarı oranında artırılarak uygulanır.","Fiilin türüne bakılmaksızın her hâlde meslekten çıkarma cezası verilir."],"dogru":1,"aciklama":"m.10/13: Bu Kanunda bir disiplin cezasıyla yaptırıma bağlanmış fiillerin sahil güvenlik personelince yurt dışı liman ziyaretlerinde veya Türk karasuları dışında işlenmesi hâlinde; uyarma-kınama gerektiren fiillerde aylıktan kesme/kısa/uzun süreli durdurma, aylıktan kesme-durdurma gerektiren fiillerde ise meslekten çıkarma cezası verilebilir; yani ceza bir üst dereceye çıkar.","kaynak":"7068 m.10/13","zorluk":"orta"},
    {"id":"7068-S-002","soru":"7068 sayılı Kanuna göre, disiplin soruşturması sonucunda yetkili makamca verilebilecek kararlardan biri DEĞİLDİR?","siklar":["Disiplin cezası verilmesine yer olmadığı kararı","Karar verilmesine yer olmadığı kararı","Disiplin cezası kararı","Yetkisizlik kararı","Görevden uzaklaştırma kararı"],"dogru":4,"aciklama":"m.27/1: Soruşturma sonucunda; disiplin cezası verilmesine yer olmadığına, karar verilmesine yer olmadığına, disiplin cezası verilmesine veya yetkisizlik kararı verilebilir; kararlar gerekçeli yazılır, imzalanır ve ilgiliye tebliğ edilir. 'Görevden uzaklaştırma' ise bir soruşturma sonucu kararı değil, m.28 kapsamında geçici bir tedbirdir.","kaynak":"7068 m.27/1","zorluk":"orta"},
    {"id":"7068-S-003","soru":"7068 sayılı Kanuna göre, görevden uzaklaştırma tedbiriyle ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Görevden uzaklaştırma, sürekli sonuç doğuran bir disiplin cezasıdır.","Görevden uzaklaştırmada 657 sayılı Devlet Memurları Kanununun ilgili hükümleri uygulanır; hakkında meslekten çıkarma veya Devlet memurluğundan çıkarma cezası istenip görevi başında kalmasında sakınca görülenler görevden uzaklaştırılabilir.","Görevden uzaklaştırma tedbiri yalnızca uyarma ve kınama cezası istenen personel hakkında uygulanabilir.","İstenen ceza daha hafif bir cezaya dönüştürülse dahi görevden uzaklaştırma tedbiri kendiliğinden sona ermez, görev süresince devam eder.","Görevden uzaklaştırma tedbirine ancak idare mahkemesi karar verebilir."],"dogru":1,"aciklama":"m.28: Görevden uzaklaştırmada 657 sayılı Kanun hükümleri uygulanır; hakkında meslekten çıkarma veya Devlet memurluğundan çıkarma cezası istenen ve görevi başında kalmasında sakınca görülen personel görevden uzaklaştırılabilir. İstenen ceza daha hafif bir cezaya dönüştürülürse tedbir derhâl kaldırılır.","kaynak":"7068 m.28/1-2","zorluk":"orta"},
    {"id":"7068-S-004","soru":"7068 sayılı Kanuna göre, aynı fiil nedeniyle bu Kanunda yazılı disiplin cezalarından birden fazlası verilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.4/2: 'Aynı fiil nedeniyle bu Kanunda yazılı disiplin cezalarından birden fazlası verilemez.' İfade birebir doğrudur.","kaynak":"7068 m.4/2","zorluk":"kolay"},
    {"id":"7068-S-005","soru":"7068 sayılı Kanuna göre, disiplinsizliklerin değerlendirilmesiyle ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde hafif olan disiplin cezası verilir.","Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde ağır olan disiplin cezası verilir.","Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde her disiplinsizlik için ayrı ceza verilir.","Bir fiilin diğer kanunlar kapsamında idari yaptırıma bağlanması, disiplin cezası verilmesine engeldir.","Disiplinsizlik yalnızca kasten işlenebilir, taksirle disiplinsizlik oluşmaz."],"dogru":1,"aciklama":"m.4/3: 'Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde ağır olan disiplin cezası verilir.' (A, C yanlış); m.4/4: idari yaptırım disiplin cezasına engel değildir (D yanlış); m.4/1: disiplinsizlik kasten VEYA taksirle oluşur (E yanlış).","kaynak":"7068 m.4/3-4","zorluk":"orta"},
    {"id":"7068-S-006","soru":"7068 sayılı Kanuna göre, bir fiilden dolayı yapılan adli soruşturma veya kovuşturma, aynı fiilden dolayı ayrıca disiplin soruşturması yapılmasını ve disiplin cezası verilmesini engeller.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5/1: Adli soruşturma veya kovuşturma, aynı fiilden dolayı ayrıca disiplin soruşturması/tahkikat yapılmasını, disiplin cezası verilmesini ve bu cezanın yerine getirilmesini ENGELLEMEZ. İfade tersine kurulduğu için yanlıştır.","kaynak":"7068 m.5/1","zorluk":"orta"},
    {"id":"7068-S-007","soru":"7068 sayılı Kanuna göre, disiplin amirleri veya kurulları takdir haklarını ölçülü, adaletli ve ______ bir şekilde kullanırlar ve bu takdir hakkı mutlaka ______ olarak kullanılır.","siklar":["hakkaniyetli / gerekçeli","hızlı / yazılı","caydırıcı / sözlü","eşit / gizli","bağımsız / onaylı"],"dogru":0,"aciklama":"m.6/1: takdir hakkı 'ölçülü, adaletli ve hakkaniyetli' kullanılır; m.6/2: 'Takdir hakkı mutlaka gerekçeli olarak kullanılır.'","kaynak":"7068 m.6/1-2","zorluk":"orta"},
    {"id":"7068-S-008","soru":"7068 sayılı Kanuna göre, disiplin amiri veya kurulu takdir hakkını kullanırken aşağıdakilerden hangisini göz önünde bulundurmaz?","siklar":["Disiplinsizliğin işleniş biçimi","Disiplinsizliğin hizmete olumsuz etkisinin ağırlığı","Disiplinsizlik yapan personelin daha önceki disiplin durumu","Disiplinsizlik yapan personelin medeni hali ve bakmakla yükümlü olduğu kişi sayısı","Disiplinsizlik yapan personelin samimi ikrarı ve gösterdiği pişmanlık"],"dogru":3,"aciklama":"m.6/3'te sayılan yedi unsur: işleniş biçimi, zaman/yer, hizmete olumsuz etkinin ağırlığı, zarar/tehlikenin ağırlığı, kusurun ağırlığı, önceki disiplin durumu, samimi ikrar ve pişmanlık. 'Medeni hal ve bakmakla yükümlü kişi sayısı' madde metninde yer almaz.","kaynak":"7068 m.6/3","zorluk":"zor"},
    {"id":"7068-S-009","soru":"7068 sayılı Kanuna göre, aşağıdakilerden hangisi personele verilebilecek disiplin cezası türlerinden biri değildir?","siklar":["Aylıktan kesme cezası","Kısa süreli durdurma cezası","Kademe ilerlemesinin geri alınması cezası","Meslekten çıkarma cezası","Devlet memurluğundan çıkarma cezası"],"dogru":2,"aciklama":"m.7/1 cezaları sayar: uyarma, kınama, aylıktan kesme, kısa süreli durdurma, uzun süreli durdurma, meslekten çıkarma, Devlet memurluğundan çıkarma. 'Kademe ilerlemesinin geri alınması' 7068'de yer almayan bir ceza türüdür (657 terminolojisini çağrıştırır).","kaynak":"7068 m.7/1","zorluk":"orta"},
    {"id":"7068-S-010","soru":"7068 sayılı Kanuna göre, aylıktan kesme cezasında personelin zam ve tazminatlar hariç brüt aylığından en fazla ne kadar süreliğine kesinti yapılabilir?","siklar":["Beş günlüğe kadar","On günlüğe kadar","Onbeş günlüğe kadar","Yirmi günlüğe kadar","Bir aylığa kadar"],"dogru":2,"aciklama":"m.7/1-c: Aylıktan kesme cezası, brüt aylıktan 'onbeş günlüğe kadar' kesinti yapılmasıdır. m.8/3'te bu üç kademeye ayrılır (3 güne kadar / 4-10 gün / 11-15 gün).","kaynak":"7068 m.7/1-c","zorluk":"orta"},
    {"id":"7068-S-011","soru":"7068 sayılı Kanuna göre, kısa süreli durdurma ve uzun süreli durdurma cezalarının süreleri aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["Kısa süreli durdurma: 4-6-10 ay / Uzun süreli durdurma: 12-16-20-24 ay","Kısa süreli durdurma: 3-6-9 ay / Uzun süreli durdurma: 12-18-24-30 ay","Kısa süreli durdurma: 4-8-12 ay / Uzun süreli durdurma: 16-20-24-28 ay","Kısa süreli durdurma: 6-10-12 ay / Uzun süreli durdurma: 18-20-22-24 ay","Kısa süreli durdurma: 2-4-6 ay / Uzun süreli durdurma: 10-15-20-25 ay"],"dogru":0,"aciklama":"m.7/1-ç: Kısa süreli durdurma 'dört, altı veya on ay'; m.7/1-d: Uzun süreli durdurma 'oniki, onaltı, yirmi veya yirmidört ay'.","kaynak":"7068 m.7/1-ç-d","zorluk":"zor"},
    {"id":"7068-S-012","soru":"7068 sayılı Kanuna göre, disiplin cezalarının özlük dosyasından silinmesinde; uyarma ve kınama cezaları ile diğer cezalar için aranan süreler aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["Uyarma ve kınama: 3 yıl / Diğer cezalar: 5 yıl","Uyarma ve kınama: 2 yıl / Diğer cezalar: 5 yıl","Uyarma ve kınama: 5 yıl / Diğer cezalar: 7 yıl","Uyarma ve kınama: 10 yıl / Diğer cezalar: 15 yıl","Uyarma ve kınama: 5 yıl / Diğer cezalar: 10 yıl"],"dogru":4,"aciklama":"m.7/5: Uyarma ve kınama cezalarının uygulanmasından başlayarak beş yıl, diğer cezaların uygulanmasından başlayarak on yıl geçtikten sonra, atamaya yetkili amire başvurularak silme istenebilir. (Çıkarma cezaları silinmez.)","kaynak":"7068 m.7/5","zorluk":"orta"},
    {"id":"7068-S-013","soru":"7068 sayılı Kanuna göre, geçmiş hizmetleri olumlu bulunan ve iyi veya çok iyi derecede değerlendirme puanı alan personel için verilecek cezalarda bir derece hafif olanı uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.7/2: 'Kurumda geçmiş hizmetleri sırasında çalışmaları olumlu bulunan ve iyi veya çok iyi derecede değerlendirme puanı alan personel için verilecek cezalarda bir derece hafif olanı uygulanabilir.' İfade birebir doğrudur.","kaynak":"7068 m.7/2","zorluk":"orta"},
    {"id":"7068-S-014","soru":"7068 sayılı Kanuna göre, meslekten çıkarma ile Devlet memurluğundan çıkarma cezaları arasındaki fark aşağıdakilerden hangisinde doğru açıklanmıştır?","siklar":["Meslekten çıkarma personelin bir daha hiçbir Devlet memuriyetine atanamamasıdır; Devlet memurluğundan çıkarma yalnızca teşkilattan çıkarılmadır.","Meslekten çıkarma geçici bir tedbirdir; Devlet memurluğundan çıkarma kalıcıdır.","Her iki ceza da yalnızca bir daha aynı rütbeye dönülememesi sonucunu doğurur.","Meslekten çıkarma personelin emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamasıdır; Devlet memurluğundan çıkarma bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarılmadır.","İki ceza arasında hukuki sonuç bakımından hiçbir fark yoktur."],"dogru":3,"aciklama":"m.7/1-e: Meslekten çıkarma = emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamak; m.7/1-f: Devlet memurluğundan çıkarma = bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarma.","kaynak":"7068 m.7/1-e-f","zorluk":"orta"},
    {"id":"7068-S-015","soru":"7068 sayılı Kanuna göre, terfileri 926, 3466, 3269 ve 6191 sayılı Kanunlara tabi olan Jandarma/Sahil Güvenlik personeli için, kısa ve uzun süreli durdurma cezası yerine uygulanacak brüt aylık kesinti oranları aşağıdakilerden hangisidir?","siklar":["Kısa süreli durdurma: 1/3 ila 1/2 / Uzun süreli durdurma: 1/5 ila 1/4","Kısa süreli durdurma: 1/2 / Uzun süreli durdurma: tamamı","Kısa süreli durdurma: 1/4 ila 1/3 / Uzun süreli durdurma: 1/2 ila tamamı","Kısa süreli durdurma: 1/10 ila 1/5 / Uzun süreli durdurma: 1/5 ila 1/3","Kısa süreli durdurma: 1/5 ila 1/4 / Uzun süreli durdurma: 1/3 ila 1/2"],"dogru":4,"aciklama":"m.8/7: Kısa süreli durdurmayı gerektiren hallerde brüt aylığın 1/5 ila 1/4'ü; uzun süreli durdurmayı gerektiren hallerde 1/3 ila 1/2'si kesilir. Bu cezalar yetkili disiplin kurullarınca verilir (m.8/8).","kaynak":"7068 m.8/7","zorluk":"zor"},
    {"id":"7068-S-016","soru":"7068 sayılı Kanuna göre, aşağıdakilerden hangisi uyarma cezasını gerektiren fiillerden biri değildir?","siklar":["Silahını, araç ve gerecini, giyim ve kuşamını temiz tutmamak","Nezaket kurallarına aykırı tavır ve davranışlarda bulunmak","Nöbeti teslimden sonra görev yerine özürsüz olarak geç dönmek","Özürsüz veya izinsiz olarak mesaiye geç gelmek veya erken ayrılmak","Usulüne uygun verilmiş bir emir üzerine amirini alenen eleştirmek veya amire karşı itirazda bulunmak"],"dogru":2,"aciklama":"A, B, D, E m.8/1'de sayılan uyarma fiilleridir. 'Nöbeti teslimden sonra görev yerine özürsüz olarak geç dönmek' ise m.8/2-c gereği KINAMA cezasını gerektirir.","kaynak":"7068 m.8/1","zorluk":"orta"},
    {"id":"7068-S-017","soru":"7068 sayılı Kanuna göre, aşağıdaki fiillerden hangisi kınama cezasını gerektirir?","siklar":["Özürsüz veya izinsiz olarak mesaiye geç gelmek","Görev sırasında veya dışında kendisi ile aynı rütbede çalışanlara veya mesai arkadaşlarına karşı saygısız davranmak","İzinsiz veya kabul edilebilir özrü olmaksızın yirmidört saate kadar göreve gelmemek","Amir ve memurlara görevle ilgili olarak yalan söylemek","Amir veya üste hakaret etmek"],"dogru":1,"aciklama":"m.8/2-e: 'Görev sırasında veya dışında kendisi ile aynı rütbede çalışanlara veya mesai arkadaşlarına karşı saygısız davranmak' kınama cezasını gerektirir.","kaynak":"7068 m.8/2","zorluk":"zor"},
    {"id":"7068-S-018","soru":"7068 sayılı Kanuna göre, aşağıdaki fiillerden hangisi dört ay kısa süreli durdurma cezasını gerektirir?","siklar":["Nezaket kurallarına aykırı tavır ve davranışlarda bulunmak","İzinsiz veya kabul edilebilir özrü olmaksızın yirmidört saate kadar göreve gelmemek","Toplu olarak sözlü veya yazılı şikâyette bulunmak","Görev sırasında uyumak veya uyuklamak","Amir veya üste hakaret etmek"],"dogru":2,"aciklama":"m.8/4-a: 'Toplu olarak sözlü veya yazılı şikâyette bulunmak' dört ay kısa süreli durdurma cezasını gerektirir. Diğer fiiller farklı kademelerdedir: A uyarma (m.8/1), B aylıktan kesme (m.8/3), D onaltı ay uzun süreli durdurma (m.8/5-b), E yirmidört ay uzun süreli durdurma (m.8/5-ç).","kaynak":"7068 m.8/4-a","zorluk":"zor"},
    {"id":"7068-S-019","soru":"7068 sayılı Kanuna göre, aşağıdakilerden hangisi yirmidört ay uzun süreli durdurma cezasını gerektiren fiillerden biri değildir?","siklar":["Amir veya üste hakaret etmek","Amir veya üste fiilî tecavüze (dövmeye) teşebbüs etmek","Görevle ilgili bir belgeyi, defteri veya kaydı kasıtlı olarak yok etmek","Görev sırasında kişilere veya herhangi bir nedenle kurum binalarına gelen ya da getirilenlere hakaret etmek","Resmî kıyafetle veya hizmette tahsis edilen araçla trafik kazasına sebebiyet vererek bir kişinin ölümüne neden olmak"],"dogru":3,"aciklama":"A, B, C, E m.8/5-ç'de sayılan yirmidört ay uzun süreli durdurma fiilleridir. 'Görev sırasında kişilere veya kurum binalarına gelenlere hakaret etmek' ise m.8/5-a gereği ONİKİ ay uzun süreli durdurma cezasını gerektirir.","kaynak":"7068 m.8/5-ç","zorluk":"zor"},
    {"id":"7068-S-020","soru":"7068 sayılı Kanuna göre, aşağıdakilerden hangisi meslekten çıkarma cezasını gerektiren fiillerden biri değildir?","siklar":["Uyuşturucu maddeleri yapmak veya kullanmak","Göreve sarhoş veya alkollü içki içtiği belli olacak biçimde gelmek","Kumar oynamak veya oynatmak, kumar oynatanlarla ilişki kurmak","Kaçakçılık yapmak veya kaçakçılarla ilişki kurmak","Görev sırasında herhangi bir şekilde uyumak veya uyuklamak"],"dogru":4,"aciklama":"A, B, C, D m.8/6'da sayılan meslekten çıkarma fiilleridir (uyuşturucu yapmak/kullanmak, göreve sarhoş veya alkollü gelmek, kumar oynamak/oynatmak, kaçakçılık). 'Görev sırasında uyumak veya uyuklamak' ise m.8/5-b gereği ONALTI ay uzun süreli durdurma cezasını gerektirir.","kaynak":"7068 m.8/6","zorluk":"zor"},
    {"id":"7068-S-021","soru":"7068 sayılı Kanuna göre, 657 sayılı Kanun hükümlerine ek olarak aşağıdaki fiillerden hangisi/hangileri Devlet memurluğundan çıkarma cezasını gerektirir?\nI. Ülkenin milli güvenliğini tehlikeye düşürmeye yönelik faaliyette bulunmak\nII. İşkence yapmak\nIII. Görev sırasında uyumak veya uyuklamak","siklar":["Yalnız I","Yalnız III","I ve II","II ve III","I, II ve III"],"dogru":2,"aciklama":"m.9: 657 hükümlerine ek olarak (a) milli güvenliği tehlikeye düşürmeye yönelik faaliyet/bu yapılarla ilişki ve (b) işkence yapmak Devlet memurluğundan çıkarma cezasını gerektirir. III (uyumak/uyuklamak) m.8/5-b uzun süreli durdurma fiilidir.","kaynak":"7068 m.9","zorluk":"orta"},
    {"id":"7068-S-022","soru":"7068 sayılı Kanuna göre, geçici olarak kontrol altına almada uygulanacak azami süre ve bilgilendirme yükümlülüğü ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Tedbir en fazla 12 saat uygulanır; 6 saati aşarsa bilgi verilir.","Tedbir en fazla 24 saat uygulanır; 12 saati geçmesi halinde personelin yakınlarına ve tedbiri uygulayan komutanın üstüne bilgi verilir.","Tedbir en fazla 48 saat uygulanır; 24 saati aşarsa savcıya bilgi verilir.","Tedbir en fazla 24 saat uygulanır; bilgilendirme zorunluluğu yoktur.","Tedbir en fazla 36 saat uygulanır; 12 saati aşarsa valiye bilgi verilir."],"dogru":1,"aciklama":"m.11/2: Kontrol altında bulundurma yirmidört saati geçmeyecek şekilde uygulanır; süre oniki saati geçerse personelin yakınlarına ve tedbiri uygulayan komutanın üstüne en kısa sürede bilgi verilir.","kaynak":"7068 m.11/2","zorluk":"orta"},
    {"id":"7068-S-023","soru":"7068 sayılı Kanuna göre, geçici olarak kontrol altında bulundurma ______ saati geçmeyecek şekilde uygulanır.","siklar":["on iki","yetmiş iki","otuz altı","kırk sekiz","yirmi dört"],"dogru":4,"aciklama":"m.11/2: Kontrol altında bulundurma yirmidört saati geçmeyecek şekilde uygulanır.","kaynak":"7068 m.11/2","zorluk":"kolay"},
    {"id":"7068-S-024","soru":"7068 sayılı Kanuna göre, disiplinsizliği alışkanlık haline getirme nedeniyle meslekten çıkarma cezası verilebilmesi için aranan eşiklerden biri aşağıdakilerden hangisidir?","siklar":["Son bir yıl içinde on disiplin cezası puanı veya bir disiplin amirinden beş defa ceza almak","Son bir yıl içinde kırk disiplin cezası puanı veya yirmibeş defa ceza almak","Son beş yıl içinde yirmi disiplin cezası puanı veya tek amirden on defa ceza almak","Son bir yıl içinde yirmi disiplin cezası puanı veya en az iki farklı disiplin amirinden toplam oniki defa ya da daha fazla ceza almak","Son üç yıl içinde otuz disiplin cezası puanı veya onbeş defa ceza almak"],"dogru":3,"aciklama":"m.12/1-a: Son bir yıl içinde yirmi disiplin cezası puanı VEYA en az iki farklı disiplin amirinden toplam oniki defa ya da daha fazla ceza almak. (m.12/1-b ise beş yıl/40 puan/25 defadır.)","kaynak":"7068 m.12/1","zorluk":"zor"},
    {"id":"7068-S-025","soru":"7068 sayılı Kanuna göre, disiplin amirinde aranan nitelikle ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Ceza verilecek personelden yalnızca yaşça büyük olması yeterlidir.","Ceza verilecek personelden makam, rütbe veya kıdemce büyük olması ve amir konumunda bulunması gerekir.","Ceza verilecek personelle aynı rütbede olması yeterlidir.","Yalnızca atamaya yetkili amir disiplin amiri olabilir.","Ceza verilecek personelden kıdemce küçük olsa da amir konumundaysa yeterlidir."],"dogru":1,"aciklama":"m.13/1: Disiplin amirinin, ceza verilecek personelden makam, rütbe veya kıdemce büyük olması VE amir konumunda bulunması gerekir.","kaynak":"7068 m.13/1","zorluk":"orta"},
    {"id":"7068-S-026","soru":"7068 sayılı Kanuna göre, disiplin soruşturmasıyla ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Disiplin amiri, olayın araştırılmasına kanaat getirirse bizzat ya da yazılı görevlendireceği soruşturmacılar vasıtasıyla soruşturma yapar.","Soruşturmacı kural olarak hakkında soruşturma yapılacak kişinin üstü konumundaki bir veya birden fazla kişi olabilir.","Soruşturmacı; bilgi-belge toplama, ifade alma, tanık dinleme, bilirkişi görevlendirme ve keşif yapma yetkilerine sahiptir.","Boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında soruşturmacı olarak görevlendirilebilirler.","Disiplin amiri maiyetindeki bir fiili herhangi bir şekilde öğrenmesi üzerine soruşturma yapabilir."],"dogru":3,"aciklama":"m.14/4: Soruşturmacılar, boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında görevlendirilEMEZler. D ifadesi bu yasağı tersine çevirdiği için yanlıştır. A, B, C, E m.14/1-2-3'e uygundur.","kaynak":"7068 m.14","zorluk":"orta"},
    {"id":"7068-S-027","soru":"7068 sayılı Kanuna göre, disiplin amirliği yetkisi başka bir amire devredilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.15/4: 'Disiplin amirliği yetkisi devredilemez.' Ancak m.15/2 uyarınca vekâleten/ikinci görevle bu görevi yürütenler yetkiyi kullanabilir — bu devir değil, görevin vekâleten yürütülmesidir. İfade yanlıştır.","kaynak":"7068 m.15/4","zorluk":"orta"},
    {"id":"7068-S-028","soru":"7068 sayılı Kanuna göre, il jandarma disiplin kurulu aşağıdakilerden hangisinin başkanlığında toplanır?","siklar":["Valinin","Vali yardımcısının","İl jandarma komutanının","İl hukuk işleri müdürünün","Kaymakamın"],"dogru":1,"aciklama":"m.19/1-a: İl jandarma disiplin kurulu, vali yardımcısının başkanlığında; il hukuk işleri müdürü, il jandarma komutanı (veya yardımcısı), personel şube müdürü ve asayiş şube müdüründen oluşur.","kaynak":"7068 m.19/1-a","zorluk":"orta"},
    {"id":"7068-S-029","soru":"7068 sayılı Kanuna göre, il jandarma disiplin kurulunun meslekten çıkarma dışındaki kararları aşağıdakilerden hangisinin onayıyla kesinleşir?","siklar":["Jandarma Genel Komutanının onayıyla","İçişleri Bakanının onayıyla","Valinin onayıyla","Bakanlık Yüksek Disiplin Kurulunun onayıyla","Kaymakamın onayıyla"],"dogru":2,"aciklama":"m.21/1-a: İl jandarma disiplin kurulunun meslekten çıkarma dışındaki kararları valinin onayıyla kesinleşir. (Meslekten çıkarma kararları ise valinin önerisi, JGnK Yüksek Disiplin Kurulunun uygun görüşü ve Bakanın onayıyla kesinleşir.)","kaynak":"7068 m.21/1-a","zorluk":"zor"},
    {"id":"7068-S-030","soru":"7068 sayılı Kanuna göre, zamanaşımı süreleriyle ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Uyarma, kınama, aylıktan kesme, kısa ve uzun süreli durdurma cezalarında, fiilin öğrenildiği tarihten itibaren bir ay içinde soruşturmaya başlanmazsa ceza verme yetkisi zamanaşımına uğrar.","Meslekten çıkarma ve Devlet memurluğundan çıkarma cezasında, fiilin öğrenildiği tarihten itibaren altı ay içinde soruşturmaya başlanmazsa ceza verme yetkisi zamanaşımına uğrar.","Disiplin cezasını gerektiren fiilin işlendiği tarihten itibaren iki yıl içinde ceza verilmezse ceza verme yetkisi zamanaşımına uğrar.","Süreler, fiilin disiplin amiri tarafından öğrenildiği tarihten itibaren işlemeye başlar.","Meslekten çıkarma cezasında soruşturmaya başlama süresi, fiilin öğrenildiği tarihten itibaren bir aydır."],"dogru":4,"aciklama":"m.29/1-b: Meslekten çıkarma ve Devlet memurluğundan çıkarma cezasında soruşturmaya başlama süresi ALTI aydır; bir ay değildir. E ifadesi yanlıştır. A, B, C, D metne uygundur.","kaynak":"7068 m.29/1-2","zorluk":"zor"},
    {"id":"7068-S-031","soru":"7068 sayılı Kanuna göre, disiplin cezasını gerektiren fiilin işlendiği tarihten itibaren ______ içinde disiplin cezası verilmediği takdirde ceza verme yetkisi zamanaşımına uğrar.","siklar":["altı ay","bir yıl","iki yıl","üç yıl","beş yıl"],"dogru":2,"aciklama":"m.29/2: Fiilin işlendiği tarihten itibaren iki yıl içinde disiplin cezası verilmezse ceza verme yetkisi zamanaşımına uğrar.","kaynak":"7068 m.29/2","zorluk":"orta"},
    {"id":"7068-S-032","soru":"7068 sayılı Kanuna göre, disiplin amirleri tarafından verilen disiplin cezalarına karşı itiraz süresi ve mercii aşağıdakilerden hangisidir?","siklar":["Tebliğden itibaren on gün içinde, bir üst disiplin amirine","Tebliğden itibaren yedi gün içinde, doğrudan idari yargıya","Tebliğden itibaren otuz gün içinde, disiplin kuruluna","Tebliğden itibaren on beş gün içinde, valiye","Tebliğden itibaren altmış gün içinde, Bakanlığa"],"dogru":0,"aciklama":"m.30/1: Disiplin amirlerince verilen cezalara, tebliğden itibaren on gün içinde bir üst disiplin amirine yazılı olarak itiraz edilir.","kaynak":"7068 m.30/1","zorluk":"orta"},
    {"id":"7068-S-033","soru":"7068 sayılı Kanuna göre, itiraz üzerine yetkili merci önceki cezadan daha ağır bir ceza verebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.30/4: 'İtiraz üzerine önceki cezadan daha ağır ceza verilemez.' Hatta m.30/3'e göre itiraz haklı görülürse ceza hafifletilebilir veya tamamen kaldırılabilir. İfade yanlıştır.","kaynak":"7068 m.30/4","zorluk":"orta"},
    {"id":"7068-S-034","soru":"7068 sayılı Kanuna göre, savunma hakkıyla ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Disiplin amiri gerekli görürse savunma almadan da ceza verebilir.","Savunma için verilecek süre üç günden az olamaz.","Savunma için verilecek süre yedi günden az olamaz; süresinde savunma yapmayan personel savunma hakkından vazgeçmiş sayılır.","Savunma yalnızca meslekten çıkarma cezalarında alınır.","Savunma süresi her halde otuz gündür."],"dogru":2,"aciklama":"m.31/1: Savunma alınmadan disiplin cezası verilemez; m.31/2: Savunma için verilen süre yedi günden az olamaz, süresinde savunma yapmayan personel savunma hakkından vazgeçmiş sayılır.","kaynak":"7068 m.31/1-2","zorluk":"orta"},
    {"id":"7068-S-035","soru":"7068 sayılı Kanuna göre, tanık dinletme ve vekil vasıtasıyla savunma yapma hakkı, hakkında meslekten çıkarma veya Devlet memurluğundan çıkarma cezası istenen personele tanınmıştır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.31/4: Hakkında meslekten çıkarma veya Devlet memurluğundan çıkarma cezası istenen personel; soruşturma evrakını incelemeye, tanık dinletmeye ve disiplin kurulunda kendisi veya vekili vasıtasıyla savunma yapma hakkına sahiptir. İfade doğrudur.","kaynak":"7068 m.31/4","zorluk":"zor"},
    {"id":"7068-S-036","soru":"7068 sayılı Kanuna göre, disiplin cezalarının infazı ve denetimiyle ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Kesinleşen disiplin cezalarına karşı iptal davası açılabilir.","Aylıktan kesme cezası, kesinleşme tarihini takip eden aybaşında uygulanır.","Meslekten çıkarma ve Devlet memurluğundan çıkarma cezaları ayrıca Devlet Personel Başkanlığına bildirilir.","Disiplin cezaları, kesinleşmesinden önce derhal yerine getirilir.","Verilen disiplin cezaları üst disiplin amirine bildirilir."],"dogru":3,"aciklama":"m.33/1: Disiplin cezaları kesinleşmesini MÜTEAKİP (kesinleştikten sonra) yerine getirilir; kesinleşmeden önce değil. D yanlıştır. A m.32/1, B m.33/2, C ve E m.33/3'e uygundur.","kaynak":"7068 m.32 / m.33","zorluk":"orta"},
    {"id":"7068-S-037","soru":"7068 sayılı Kanuna göre, 657 sayılı Devlet Memurları Kanununda yer alan 'kademe ilerlemesinin durdurulması' cezası, bu Kanunun uygulanması bakımından hangi disiplin cezası sayılır?","siklar":["Aylıktan kesme cezası","Kınama cezası","Kısa süreli durdurma cezası","Uzun süreli durdurma cezası","Meslekten çıkarma cezası"],"dogru":3,"aciklama":"m.34/2: Diğer kanunlarda veya 657 sayılı Kanunda öngörülen 'kademe ilerlemesinin durdurulması' cezası, bu Kanunun uygulanmasında 'uzun süreli durdurma' cezası sayılır. (m.34/1: bu Kanunda hüküm bulunmayan hâllerde 657 sayılı Kanunun disiplin hükümleri uygulanır.)","kaynak":"7068 m.34/2","zorluk":"orta"},
    {"id":"7068-OO-001","soru":"Jandarma personeli astsubay A, bir gece önce aşırı alkol aldıktan sonra ertesi sabah, alkollü içki içtiği yüzünden ve davranışlarından açıkça belli olacak biçimde göreve gelir. Disiplin amiri durumu tespit eder. 7068 sayılı Kanuna göre A'nın bu fiili hangi disiplin cezasını gerektirir?","siklar":["Kınama cezası","Onbeş güne kadar aylıktan kesme cezası","Yirmidört ay uzun süreli durdurma cezası","Meslekten çıkarma cezası","Devlet memurluğundan çıkarma cezası"],"dogru":3,"aciklama":"m.8/6-k: 'Göreve sarhoş veya alkollü içki içtiği belli olacak biçimde gelmek' meslekten çıkarma cezasını gerektiren fiiller arasında sayılır. Aynı fıkrada görev mahallinde alkol içmek (j) ve resmî kıyafetle umuma açık yerde içmek (l) de meslekten çıkarma sebebidir.","kaynak":"7068 m.8/6-k","zorluk":"orta"},
    {"id":"7068-OO-002","soru":"Personel A, kendisine görev veren amiri B'ye, koğuştaki diğer personelin önünde 'sen aciz birisin, bu makama layık değilsin' diyerek hakaret eder. 7068 sayılı Kanuna göre A'nın bu fiili hangi disiplin cezasını gerektirir?","siklar":["Kınama cezası","Dört ay kısa süreli durdurma cezası","Yirmidört ay uzun süreli durdurma cezası","Onbeş güne kadar aylıktan kesme cezası","Meslekten çıkarma cezası"],"dogru":2,"aciklama":"m.8/5-ç/7: 'Amir veya üste hakaret etmek' yirmidört ay uzun süreli durdurma cezasını gerektirir. Aynı kademede amir/üstü küçümsemek (8), dövmeye teşebbüs (9) ve tehdit (10) de sayılır.","kaynak":"7068 m.8/5-ç/7","zorluk":"zor"},
    {"id":"7068-OO-003","soru":"Personel A, kendisiyle aynı rütbedeki mesai arkadaşı B ile tartışır ve öfkeyle B'yi dövmek üzere üzerine yürür; ancak çevredekiler araya girip engeller. 7068 sayılı Kanuna göre A'nın bu fiili hangi disiplin cezasını gerektirir?","siklar":["Dört ay kısa süreli durdurma cezası","Yirmidört ay uzun süreli durdurma cezası","Kınama cezası","Dört ila on günlüğe kadar aylıktan kesme cezası","Meslekten çıkarma cezası"],"dogru":0,"aciklama":"m.8/4-a/5: 'Astlarını, aynı rütbedeki arkadaşlarını ve diğer mesai arkadaşlarını dövme girişiminde bulunmak' dört ay kısa süreli durdurma cezasını gerektirir. Mağdur amir/üst olsaydı (m.8/5-ç/9 'amir veya üste dövmeye teşebbüs') ceza yirmidört ay uzun süreli durdurma olurdu.","kaynak":"7068 m.8/4-a/5","zorluk":"zor"},
    {"id":"7068-OO-004","soru":"Jandarma Genel Komutanlığının terörle mücadele harekâtı kapsamındaki bir operasyonu sırasında personel A, sarhoşluğu nedeniyle disiplini ciddi şekilde bozar ve operasyon komutanınca geçici olarak kontrol altına alınır. Kontrol altında tutulma süresi onüçüncü saate ulaşır. 7068 sayılı Kanuna göre bu aşamada ne yapılması gerekir?","siklar":["Süre yirmidört saati aşmadığı için herhangi bir bildirim yapılmasına gerek yoktur.","Personelin yakınlarına ve tedbiri uygulayan komutanın üstüne en kısa sürede bilgi verilir.","Durum derhâl Cumhuriyet savcısına bildirilerek gözaltı işlemine geçilir.","Kontrol altına alma kararı için valinin onayı alınır.","Personel serbest bırakılır; çünkü kontrol altında tutma en fazla oniki saat sürebilir."],"dogru":1,"aciklama":"m.11/2: Kontrol altında bulundurma yirmidört saati geçmeyecek şekilde uygulanır; tedbir süresinin oniki saati geçmesi hâlinde personelin yakınlarına ve tedbiri uygulayan komutanın üstüne en kısa sürede bilgi verilir.","kaynak":"7068 m.11/2","zorluk":"orta"},
    {"id":"7068-OO-005","soru":"Personel A, en son aldığı disiplin cezasının kesinleştiği tarihten geriye doğru son bir yıl içinde, iki farklı disiplin amirinden toplam onüç defa disiplin cezası almıştır. 7068 sayılı Kanuna göre A hakkında hangi işlem yapılır?","siklar":["Her ceza ayrı değerlendirildiğinden ek bir işlem yapılamaz.","Disiplinsizliği alışkanlık haline getirme kabul edilir ve yetkili disiplin kurulunca meslekten çıkarma cezası verilir.","Doğrudan Devlet memurluğundan çıkarma cezası verilir.","Yalnızca uzun süreli durdurma cezası verilir.","Cezalar tek bir aylıktan kesme cezasına dönüştürülür."],"dogru":1,"aciklama":"m.12/1-a: Son bir yıl içinde yirmi disiplin cezası puanı VEYA en az iki farklı disiplin amirinden toplam oniki defa ya da daha fazla ceza almak disiplinsizliği alışkanlık haline getirme sayılır ve yetkili disiplin kurullarınca meslekten çıkarma cezası verilir. Olayda iki farklı amirden 13 defa ceza alınmıştır; eşik aşılmıştır.","kaynak":"7068 m.12/1-a","zorluk":"orta"},
    {"id":"7068-OO-006","soru":"Personel A, amirinin usulüne uygun olarak verdiği emri yerine getirmez. Bu nedenle yürütülmesi gereken hizmet durur ve Devlet önemli bir zarara uğrar. 7068 sayılı Kanuna göre, doğan zararın derecesi ve durumun ağırlığı dikkate alındığında A hakkında hangi ceza uygulanabilir?","siklar":["Yalnızca yirmidört ay uzun süreli durdurma cezası uygulanabilir; ağırlaştırma mümkün değildir.","Uyarma cezası uygulanır.","Meslekten çıkarma cezası uygulanabilir.","Onbeş güne kadar aylıktan kesme cezası uygulanır.","Hiçbir ceza verilemez; zarar adli yargıda tazmin edilir."],"dogru":2,"aciklama":"m.10/1: Amirin emrinin yapılmaması fiilinin neticesinde Devlet ya da kişiler zarara uğratılmış veya hizmetin gecikmesine/durmasına neden olunmuşsa, doğan zararın derecesine ya da durumun ağırlığına göre meslekten çıkarma cezası uygulanabilir. (Emrin yapılmaması zarar doğmadan m.8/5-ç/4 gereği yirmidört ay uzun süreli durdurma kademesindedir.)","kaynak":"7068 m.10/1","zorluk":"zor"},
    {"id":"7068-OO-007","soru":"Personel A'ya, kaymakam tarafından doğrudan bir disiplin cezası verilir ve ceza A'ya tebliğ edilir. A bu cezaya itiraz etmek istemektedir. 7068 sayılı Kanuna göre A, itirazını hangi süre içinde ve hangi makama yapmalıdır?","siklar":["Tebliğden itibaren on gün içinde valiye","Tebliğden itibaren on gün içinde bir üst disiplin amirine","Tebliğden itibaren altmış gün içinde doğrudan idari yargıya","Tebliğden itibaren yedi gün içinde Bakanlık Yüksek Disiplin Kuruluna","Tebliğden itibaren otuz gün içinde Jandarma Genel Komutanına"],"dogru":0,"aciklama":"m.30/1: Disiplin cezalarına tebliğden itibaren on gün içinde itiraz edilir; kaymakamın doğrudan verdiği disiplin cezalarına karşı ise valiye itiraz edilir. Süre içinde itiraz edilmeyen cezalar kesinleşir.","kaynak":"7068 m.30/1","zorluk":"orta"},
    {"id":"7068-OO-008","soru":"Hakkında meslekten çıkarma cezası istenen personel A, disiplin kurulunda kendisini bir avukat (vekil) aracılığıyla savunmak ve lehine tanık dinletmek istemektedir. 7068 sayılı Kanuna göre bu talep bakımından aşağıdakilerden hangisi doğrudur?","siklar":["A, soruşturma evrakını incelemeye, tanık dinletmeye ve vekili vasıtasıyla savunma yapmaya hak sahibidir.","Disiplin sürecinde hiçbir personel vekil aracılığıyla savunma yapamaz; vekil yalnızca idari yargıda mümkündür.","A yalnızca yazılı savunma verebilir; tanık dinletme ve vekil hakkı tanınmamıştır.","Vekil ve tanık hakkı yalnızca aylıktan kesme ve daha hafif cezalarda tanınır.","Tanık dinletme hakkı vardır ancak vekille savunma yalnızca Devlet memurluğundan çıkarma cezasına özgüdür."],"dogru":0,"aciklama":"m.31/4: Hakkında meslekten çıkarma veya Devlet memurluğundan çıkarma cezası istenen personel; soruşturma evrakını incelemeye, tanık dinletmeye ve disiplin kurulunda kendisi veya vekili vasıtasıyla savunma yapmaya hak sahibidir. Olayda meslekten çıkarma istendiğinden bu ek güvence paketi açıktır.","kaynak":"7068 m.31/4","zorluk":"orta"},
    {"id":"7068-OO-009","soru":"Disiplin amiri, hakkında disiplin soruşturması yapılacak personel B'nin dosyası için soruşturmacı görevlendirecektir. Görevlendirmeyi düşündüğü personel C, B'nin öz kardeşidir. 7068 sayılı Kanuna göre bu görevlendirme hakkında aşağıdakilerden hangisi doğrudur?","siklar":["C, B'nin üstü konumundaysa soruşturmacı olarak görevlendirilebilir.","C, B'nin ikinci dereceye kadar kan hısmı olduğundan bu soruşturmada soruşturmacı olarak görevlendirilemez.","Hısımlık engeli yalnızca eşler için geçerlidir; kardeşler için engel yoktur.","C ancak valinin yazılı izniyle görevlendirilebilir.","Engel yalnızca evlilik devam ettiği sürece vardır; boşanma hâlinde tüm engeller kalkar."],"dogru":1,"aciklama":"m.14/4: Soruşturmacı olarak görevlendirilebilecek olanlar, boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında yürütülen soruşturmalarda görevlendirilemez. Kardeş ikinci derece kan hısmıdır; C görevlendirilemez.","kaynak":"7068 m.14/4","zorluk":"orta"},
    {"id":"7068-OO-010","soru":"Disiplin amiri B'nin cezalandırması gereken personel, B'nin ikinci derece kan hısmı olan öz kardeşidir. 7068 sayılı Kanuna göre bu durumda disiplin amirliği yetkisi nasıl kullanılır?","siklar":["B, yetkisini bir astına devrederek cezayı verdirir.","Disiplin amirliği yetkisi, üst konumdaki disiplin amiri tarafından kullanılır.","Hısımlık yetkiyi etkilemez; B yetkisini olağan biçimde kullanır.","Yetki tamamen düşer ve bu personele hiçbir disiplin cezası verilemez.","Yetkiyi yalnızca il disiplin kurulu kullanabilir."],"dogru":1,"aciklama":"m.15/3: Disiplin amirleri, boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında bu sıfatlarından doğan yetkilerini kullanamazlar; bu hâllerde disiplin amirliği yetkisi üst konumdaki disiplin amiri tarafından kullanılır.","kaynak":"7068 m.15/3","zorluk":"zor"},
    {"id":"7068-OO-011","soru":"Yüzbaşı rütbesindeki bir jandarma personelinin disiplin dosyası, il jandarma disiplin kurulunun önüne gelir. 7068 sayılı Kanuna göre il jandarma disiplin kurulu bu personel hakkında aşağıdaki cezalardan hangisini VEREMEZ?","siklar":["Aylıktan kesme cezası","Kınama cezası","Uzun süreli durdurma cezası","Meslekten çıkarma cezası","Kısa süreli durdurma cezası"],"dogru":3,"aciklama":"m.20/1-a: İl jandarma disiplin kurulu, yüzbaşı ve altı rütbelerdeki personele meslekten çıkarma ve Devlet memurluğundan çıkarma cezası DIŞINDA kalan diğer disiplin cezalarını verebilir. Dolayısıyla meslekten çıkarma cezası il jandarma disiplin kurulunun yetkisi dışındadır.","kaynak":"7068 m.20/1-a","zorluk":"zor"},
    {"id":"7068-OO-012","soru":"Personel A'nın bir fiili hakkında Cumhuriyet savcılığı ceza soruşturması başlatır. Disiplin amiri de aynı fiil nedeniyle disiplin soruşturması yapmak istemektedir. 7068 sayılı Kanuna göre disiplin amiri ne yapabilir?","siklar":["Ceza davası kesin hükümle sonuçlanana kadar disiplin soruşturmasını başlatamaz.","Aynı fiilden adli süreç yürüdüğü için artık disiplin cezası verilemez.","Adli soruşturma, aynı fiilden ayrıca disiplin soruşturması yapılmasına ve disiplin cezası verilmesine engel olmadığından disiplin soruşturmasını yürütebilir.","Yalnızca A mahkûm olursa disiplin soruşturması yapılabilir; beraat ederse hiçbir disiplin işlemi yapılamaz.","Disiplin soruşturmasını ancak savcının yazılı izniyle yürütebilir."],"dogru":2,"aciklama":"m.5/1: Bir fiilden dolayı yapılan adli soruşturma veya kovuşturma, aynı fiilden dolayı ayrıca disiplin soruşturması ve tahkikat yapılmasını, disiplin cezası verilmesini ve bu cezanın yerine getirilmesini engellemez. İki süreç paralel ve birbirinden bağımsız yürür.","kaynak":"7068 m.5/1","zorluk":"orta"},
  ],
  13: [
    {"id":"4678-S-001","soru":"4678 sayılı Kanun'a göre, askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp onayı tarihine kadar geçecek süreyi kapsayan ve aday ile yapılan belge aşağıdakilerden hangisidir?","siklar":["Sözleşme","Ön sözleşme","Taahhütname","Atama onayı","Hizmet yükümlülüğü senedi"],"dogru":1,"aciklama":"m.3/a: Ön sözleşme, askerî eğitime alınma konusunda yapılan ve askerî eğitim dönemi başlangıcı ile nasıp onayı tarihine kadar geçecek süreyi kapsayan sözleşmedir.","kaynak":"4678 m.3/a-b","zorluk":"orta"},
    {"id":"4678-S-002","soru":"4678 sayılı Kanun'a göre sözleşme; askerî eğitimi başarıyla tamamlayanlar arasında yapılan ve ........... az, ........... fazla olmamak üzere hizmet yükümlülüğü getiren yazılı bir belgedir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki yıldan / sekiz yıldan","üç yıldan / on yıldan","üç yıldan / dokuz yıldan","dört yıldan / dokuz yıldan","üç yıldan / on iki yıldan"],"dogru":2,"aciklama":"m.3/b: Sözleşme, üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getiren belgedir.","kaynak":"4678 m.3/b","zorluk":"orta"},
    {"id":"4678-S-003","soru":"4678 sayılı Kanun'daki 'sözleşmeli subay' tanımına göre, bir sözleşmeli subayın haiz olabileceği EN ÜST rütbe aşağıdakilerden hangisidir?","siklar":["Teğmen","Üsteğmen","Yüzbaşı","Binbaşı","Yarbay"],"dogru":2,"aciklama":"m.3/e: Sözleşmeli subay; teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subayları ifade eder. Tanımdaki en üst rütbe yüzbaşıdır; binbaşı ve üzeri sözleşmeli subay tanımının dışındadır.","kaynak":"4678 m.3/e","zorluk":"orta"},
    {"id":"4678-S-004","soru":"4678 sayılı Kanun'daki 'sözleşmeli astsubay' tanımında sayılan rütbelerden biri aşağıdakilerden hangisi DEĞİLDİR?","siklar":["Astsubay çavuş","Astsubay başçavuş","Astsubay kıdemli çavuş","Astsubay üstçavuş","Astsubay kıdemli üstçavuş"],"dogru":1,"aciklama":"m.3/f: Sözleşmeli astsubay; astsubay çavuş, astsubay kıdemli çavuş, astsubay üstçavuş ve astsubay kıdemli üstçavuş rütbelerini ifade eder. Başçavuş bu tanımda yoktur.","kaynak":"4678 m.3/f","zorluk":"orta"},
    {"id":"4678-S-005","soru":"4678 sayılı Kanun'a göre, sözleşmeli astsubaylar için 'emsal' aşağıdakilerden hangisini ifade eder?","siklar":["Astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubayları","Astsubaylığa nasbedildikleri yıl harp okullarından mezun olan muvazzaf subayları","Kendileriyle aynı yıl sözleşme imzalayan diğer sözleşmeli astsubayları","Aynı kıta ve birlikte görev yapan tüm astsubayları","Astsubaylığa nasbedildikleri yıl terhis olan erbaş ve erleri"],"dogru":0,"aciklama":"m.3/h: Sözleşmeli astsubaylar için emsal, astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubaylardır.","kaynak":"4678 m.3/h","zorluk":"zor"},
    {"id":"4678-S-006","soru":"4678 sayılı Kanun'a göre 'sözleşme yılı', sözleşmenin yürürlüğe girdiği ay ve günü başlangıç olarak kabul eden ve bu tarihten itibaren geçen her bir yıllık süreyi ifade eder. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.3/ı: Sözleşme yılı, sözleşmenin yürürlüğe girdiği ay ve günü başlangıç kabul eden ve bu tarihten itibaren geçen her bir yıllık süredir.","kaynak":"4678 m.3/ı","zorluk":"orta"},
    {"id":"4678-S-007","soru":"4678 sayılı Kanun'a göre, sözleşmeli subay kaynağını en az dört yıllık fakülte veya yüksekokulları bitirenlerden, düzeltilmemiş nüfus kaydına göre müracaat yapılan yılın ocak ayının ilk günü itibarıyla kaç yaşını bitirmemiş olanlar teşkil eder?","siklar":["Yirmi dört","Yirmi beş","Yirmi altı","Yirmi yedi","Otuz iki"],"dogru":3,"aciklama":"m.4/1: En az dört yıllık fakülte/yüksekokul bitirenlerden yirmiyedi yaşını bitirmemiş olanlar kaynağı teşkil eder.","kaynak":"4678 m.4/1","zorluk":"orta"},
    {"id":"4678-S-008","soru":"4678 sayılı Kanun'a göre, sözleşmeli subay kaynağı bakımından lisansüstü eğitimini tamamlamış olanlardan ........... yaşını bitirmemiş olanlar kaynak teşkil eder. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["Yirmi yedi","Yirmi dokuz","Otuz","Otuz iki","Otuz beş"],"dogru":3,"aciklama":"m.4/1: Lisansüstü eğitimini tamamlamış olanlardan otuziki yaşını bitirmemiş olanlar kaynağı teşkil eder.","kaynak":"4678 m.4/1","zorluk":"orta"},
    {"id":"4678-S-009","soru":"4678 sayılı Kanun'a göre, sözleşmeli subaylık için genel olarak aranan niteliklerden biri aşağıdakilerden hangisidir?","siklar":["Daha önce muvazzaf askerlik hizmetini er olarak tamamlamış olmak","En az iki yabancı dili bildiğini belgelemek","Güvenlik soruşturması olumlu sonuçlanmış olmak","Evli ve en az bir çocuk sahibi olmak","İkametgâhının bulunduğu ilde en az beş yıldır oturuyor olmak"],"dogru":2,"aciklama":"m.4/3: Aranan genel nitelikler arasında 'güvenlik soruşturması olumlu sonuçlanmış olmak' (f bendi) yer alır. Diğer şıklar kanunda aranmayan, makul görünümlü uydurma koşullardır.","kaynak":"4678 m.4/3","zorluk":"zor"},
    {"id":"4678-S-010","soru":"4678 sayılı Kanun'a göre, askerî okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişiği kesilen personel sözleşmeli subay olarak alınmaz; ancak askerlik yükümlülüğünü yerine getirmekte olanlar veya terhis edilenler sözleşmeli subay olabilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.4/2: İlişiği kesilen personel alınmaz; ancak askerlik yükümlülüğünü yapan veya terhis edilenler sözleşmeli subay olabilir.","kaynak":"4678 m.4/2","zorluk":"zor"},
    {"id":"4678-S-011","soru":"4678 sayılı Kanun'a göre, aşağıdaki sınıflardan hangisine sözleşmeli subay statüsünde personel alınmaz?","siklar":["Muhabere sınıfı","İkmal sınıfı","Tank sınıfı","Topçu sınıfı","Askerî hâkim sınıfı"],"dogru":4,"aciklama":"m.4 son fıkra: Askeri hâkim sınıfına, sözleşmeli subay statüsünde personel alınmaz.","kaynak":"4678 m.4/son","zorluk":"orta"},
    {"id":"4678-S-012","soru":"4678 sayılı Kanun'a göre, askerî eğitimi başarı ile tamamlayan ve yönetmelikteki şartları taşıyan sözleşmeli subay adayları ile sözleşme yapılarak hangi rütbeye nasbedilirler?","siklar":["Astsubay çavuş","Teğmen","Üsteğmen","Asteğmen","Yüzbaşı"],"dogru":1,"aciklama":"m.6/1: Eğitimi başaranlarla sözleşme yapılır ve bu kişiler teğmen rütbesine nasbedilir.","kaynak":"4678 m.6/1","zorluk":"kolay"},
    {"id":"4678-S-013","soru":"4678 sayılı Kanun'a göre sözleşmeli subayların sözleşme süreleri; en az ve en çok kaç yıl olmak şartıyla, hizmet gerekleri ve yetiştirme maliyetlerine bağlı olarak yönetmelikte belirlenir?","siklar":["En az 2 - en çok 8 yıl","En az 3 - en çok 9 yıl","En az 4 - en çok 10 yıl","En az 3 - en çok 12 yıl","En az 5 - en çok 9 yıl"],"dogru":1,"aciklama":"m.6/1: Sözleşme süreleri üç yıldan az ve dokuz yıldan fazla olmamak şartıyla yönetmelikte belirlenir.","kaynak":"4678 m.6/1","zorluk":"orta"},
    {"id":"4678-S-014","soru":"4678 sayılı Kanun'a göre, seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde sözleşme süreleri, ilgilinin talebine bakılmaksızın, durumun devamı müddetince ilgisine göre Milli Savunma Bakanlığı veya İçişleri Bakanlığının onayı ile uzatılabilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.6/2: Sayılan olağanüstü hâllerde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının lüzumu üzerine, talebe bakılmaksızın MSB veya İçişleri Bakanlığı onayı ile uzatılabilir.","kaynak":"4678 m.6/2","zorluk":"zor"},
    {"id":"4678-S-015","soru":"4678 sayılı Kanun'a göre, sözleşmeli subayların muvazzaf subaylığa geçişi için başvuru, Türk Silâhlı Kuvvetlerindeki hangi fiilî hizmet yılları arasında yapılabilir?","siklar":["Dördüncü fiilî hizmet yılı başından on ikinci fiilî hizmet yılının bitimine kadar","Beşinci fiilî hizmet yılı başından onuncu fiilî hizmet yılının bitimine kadar","Yedinci fiilî hizmet yılı başından on ikinci fiilî hizmet yılının bitimine kadar","Üçüncü fiilî hizmet yılı başından dokuzuncu fiilî hizmet yılının bitimine kadar","Yedinci fiilî hizmet yılı başından on beşinci fiilî hizmet yılının bitimine kadar"],"dogru":2,"aciklama":"m.7/1: Muvazzaf subaylığa geçiş için yedinci fiilî hizmet yılı başından onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir.","kaynak":"4678 m.7/1","zorluk":"zor"},
    {"id":"4678-S-016","soru":"4678 sayılı Kanun'a göre, muvazzaf subaylığa geçirilenler; subay nasbedildikleri tarihten başlamak üzere ........... hizmet etmedikçe istifa edemezler. Boşluğa gelmesi gereken süre hangisidir?","siklar":["on yıl","on iki yıl","on üç yıl","on beş yıl","yirmi yıl"],"dogru":3,"aciklama":"m.7/1: Muvazzaf subaylığa geçirilenler, subay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler.","kaynak":"4678 m.7/1","zorluk":"orta"},
    {"id":"4678-S-017","soru":"4678 sayılı Kanun'a göre, Türk Silahlı Kuvvetleri bünyesinde ön lisans, lisans ve lisansüstü düzeyde eğitim ve öğretim yapan kurum ve kuruluşların öğretim üyesi kadrolarında atamalı olarak görev yapanlarda da muvazzaf subaylığa geçiş için 7-12. fiilî hizmet yılı şartı aranır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.7 son fıkra: Öğretim üyesi kadrolarında atamalı olarak görev yapanlarda fiilî hizmet yılı şartı ARANMAZ. Dolayısıyla ifade yanlıştır.","kaynak":"4678 m.7/son","zorluk":"zor"},
    {"id":"4678-S-018","soru":"4678 sayılı Kanun'a göre, askerî eğitimi başarı ile tamamlayan sözleşmeli astsubay adayları ile sözleşme yapılarak hangi rütbeye nasbedilirler?","siklar":["Astsubay kıdemli çavuş","Astsubay üstçavuş","Astsubay çavuş","Teğmen","Astsubay kıdemli üstçavuş"],"dogru":2,"aciklama":"m.10/1: Eğitimi başaranlarla sözleşme yapılır ve bu kişiler astsubay çavuş rütbesine nasbedilir.","kaynak":"4678 m.10/1","zorluk":"kolay"},
    {"id":"4678-S-019","soru":"4678 sayılı Kanun'a göre, sözleşmeli astsubayların muvazzaf astsubaylığa geçişi için başvuru, Türk Silâhlı Kuvvetlerindeki hangi fiilî hizmet yılları arasında yapılabilir?","siklar":["Dördüncü fiilî hizmet yılı başından on ikinci fiilî hizmet yılının bitimine kadar","Yedinci fiilî hizmet yılı başından on ikinci fiilî hizmet yılının bitimine kadar","Üçüncü fiilî hizmet yılı başından dokuzuncu fiilî hizmet yılının bitimine kadar","Beşinci fiilî hizmet yılı başından on beşinci fiilî hizmet yılının bitimine kadar","Dördüncü fiilî hizmet yılı başından onuncu fiilî hizmet yılının bitimine kadar"],"dogru":0,"aciklama":"m.11/1: Muvazzaf astsubaylığa geçiş için dördüncü fiilî hizmet yılı başından onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir.","kaynak":"4678 m.11/1","zorluk":"zor"},
    {"id":"4678-S-020","soru":"4678 sayılı Kanun'a göre sözleşmeli astsubay kaynağında, dört yıl ve daha fazla süreli yükseköğrenimi bitirenler ile bundan daha az süreli yükseköğrenimi bitirenler için aranan üst yaş sınırları sırasıyla aşağıdakilerin hangisinde doğru verilmiştir?","siklar":["24 - 27","27 - 24","27 - 32","25 - 22","32 - 27"],"dogru":1,"aciklama":"m.8: Dört yıl ve üzeri yükseköğrenimi bitirenler için yirmiyedi (27), daha az süreli yükseköğrenimi bitirenler için yirmidört (24) yaş eşiği uygulanır.","kaynak":"4678 m.8","zorluk":"zor"},
    {"id":"4678-S-021","soru":"4678 sayılı Kanun'a göre, her sözleşme süresinin sona erme tarihinden en az kaç ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmadıkları takdirde sözleşme kendiliğinden sona erer?","siklar":["1 ay","2 ay","3 ay","6 ay","12 ay"],"dogru":2,"aciklama":"m.12: Sözleşme süresinin sona erme tarihinden en az üç ay önce yazılı yenileme bildirimi yapılmazsa sözleşme kendiliğinden sona erer.","kaynak":"4678 m.12","zorluk":"orta"},
    {"id":"4678-S-022","soru":"4678 sayılı Kanun'a göre, sözleşmeli subay veya astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedebilirler. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.12: Sözleşmeli subay veya astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedemezler. Bu nedenle ifade yanlıştır.","kaynak":"4678 m.12","zorluk":"orta"},
    {"id":"4678-S-023","soru":"4678 sayılı Kanun'a göre, sözleşmeli subaylar ile sözleşmeli astsubaylara ilişkin aşağıdaki bilgilerden hangisi YANLIŞTIR?","siklar":["Sözleşmeli subaylar ilk olarak teğmen, sözleşmeli astsubaylar ise astsubay çavuş rütbesine nasbedilir.","Her ikisinin de sözleşme süreleri üç yıldan az, dokuz yıldan fazla olamaz.","Muvazzaf subaylığa geçiş yedinci, muvazzaf astsubaylığa geçiş dördüncü fiilî hizmet yılı başında başlar.","Muvazzaf statüye geçirilenler nasıp tarihinden itibaren on beş yıl hizmet etmeden istifa edemez.","Muvazzaf subaylığa geçiş başvurusu onuncu, muvazzaf astsubaylığa geçiş başvurusu sekizinci fiilî hizmet yılının bitiminde sona erer."],"dogru":4,"aciklama":"Her iki geçiş penceresinin üst sınırı da onikinci (12.) fiilî hizmet yılının bitimidir (m.7 ve m.11). E şıkkındaki 10/8 üst sınırları sahtedir; doğru üst sınır her ikisi için 12'dir.","kaynak":"4678 m.3-m.7-m.11","zorluk":"zor"},
    {"id":"4678-OO-001","soru":"A, dört yıllık bir mühendislik fakültesini bitirmiştir. Sözleşmeli subaylık için müracaat ettiği yılın ocak ayının ilk günü itibarıyla, düzeltilmemiş nüfus kaydına göre yirmi yedi yaşını bitirmiş durumdadır. A'nın başvurusu yaş şartı yönünden nasıl sonuçlanır?","siklar":["Yaş şartını taşır; başvurusu yaş yönünden geçerlidir","Yirmi yedi yaşını bitirdiği için yaş şartını taşımaz; bu kaynaktan alınamaz","Dört yıllık fakülte mezunu olduğundan otuz iki yaş sınırına tabidir, geçerlidir","Yaş, düzeltilmiş (kesinleşmiş) nüfus kaydına göre hesaplanacağından geçerlidir","Yaş, müracaat günü itibarıyla hesaplanacağından durum değişir"],"dogru":1,"aciklama":"m.4/1: En az dört yıllık fakülte/yüksekokul bitirenlerden, müracaat yapılan yılın ocak ayının ilk günü itibarıyla yirmiyedi yaşını BİTİRMEMİŞ olanlar kaynak teşkil eder. A yirmi yedi yaşını bitirmiş olduğundan yaş şartını taşımaz.","kaynak":"4678 m.4/1","zorluk":"orta"},
    {"id":"4678-OO-002","soru":"B, yüksek lisans (lisansüstü) eğitimini tamamlamıştır. Sözleşmeli subaylığa müracaat ettiği yılın ocak ayının ilk günü itibarıyla, düzeltilmemiş nüfus kaydına göre otuz bir yaşındadır (otuz iki yaşını bitirmemiştir). B'nin durumu yaş şartı yönünden nasıl değerlendirilir?","siklar":["Yirmi yedi yaşını geçtiği için kesinlikle alınamaz","Otuz iki yaşını bitirmediğinden yaş şartını taşır; bu yönden başvurusu geçerlidir","Lisansüstü eğitimliler için üst yaş sınırı yoktur, sınırsız başvurabilir","Otuz yaşını geçtiği için ancak sözleşmeli astsubay olarak alınabilir","Lisansüstü eğitim yaş sınırını yirmi dörde düşürür, alınamaz"],"dogru":1,"aciklama":"m.4/1: Lisansüstü eğitimini tamamlamış olanlardan otuziki yaşını bitirmemiş olanlar kaynak teşkil eder. B otuz iki yaşını bitirmemiş olduğundan yaş yönünden uygundur.","kaynak":"4678 m.4/1","zorluk":"orta"},
    {"id":"4678-OO-003","soru":"C, yıllar önce girdiği bir askerî okuldan disiplinsizlik nedeniyle ilişiği kesilmiştir. Aradan geçen sürede dört yıllık bir fakülteyi bitiren C, şimdi sözleşmeli subaylık için müracaat etmektedir. Diğer tüm şartları taşıyan C'nin durumu nasıl değerlendirilir?","siklar":["Askerî okuldan ilişiği kesilenler de askerlik istisnası kapsamında alınabilir","Aradan beş yıldan fazla geçtiği için engel ortadan kalkar, alınabilir","Askerî okuldan veya TSK'dan her ne sebeple olursa olsun ilişiği kesilen personel sözleşmeli subay olarak alınmaz","İlişik kesilme disiplin nedeniyle olduğundan sadece güvenlik soruşturmasıyla aşılabilir","Yalnızca TSK'dan ilişiği kesilenler alınmaz; askerî okuldan ilişiği kesilen alınabilir"],"dogru":2,"aciklama":"m.4/2: Askeri okullardan ve TSK'dan her ne sebeple olursa olsun ilişikleri kesilen personel sözleşmeli subay olarak ALINMAZ. (Askerlik yükümlülüğünü yapan/terhis olan istisnası bu yasaktan farklı bir durumdur.)","kaynak":"4678 m.4/2","zorluk":"zor"},
    {"id":"4678-OO-004","soru":"Hukuk fakültesi mezunu D, askerî hâkim sınıfında görev yapmak amacıyla sözleşmeli subaylığa başvurmak istemektedir. Yaş ve diğer genel şartları taşıyan D'nin bu talebi nasıl değerlendirilir?","siklar":["Hukuk fakültesi mezunu olduğundan doğrudan askerî hâkim sınıfına sözleşmeli subay alınır","Askerî hâkim sınıfına sözleşmeli subay statüsünde personel alınmaz; bu talep kabul edilemez","Güvenlik soruşturması olumlu olursa askerî hâkim sınıfına alınabilir","Yüksek lisans yapması hâlinde askerî hâkim sınıfına alınabilir","İkmal veya muhabere sınıfı kapalı olsa da hâkim sınıfı sözleşmeliye açıktır"],"dogru":1,"aciklama":"m.4 son fıkra: Askeri hâkim sınıfına, sözleşmeli subay statüsünde personel alınmaz. D'nin talebi sınıf yönünden kabul edilemez.","kaynak":"4678 m.4/son","zorluk":"orta"},
    {"id":"4678-OO-005","soru":"Savaş hâlinin ilan edildiği bir dönemde, bir kara birliğinde görevli sözleşmeli subay E'nin sözleşme süresi sona ermek üzeredir. E, süresinin uzatılması için herhangi bir talepte bulunmamıştır. Bu durumda sözleşme süresi bakımından hangi işlem uygulanabilir?","siklar":["Talep bulunmadığından sözleşme süresi dolunca kendiliğinden sona erer","Kuvvet Komutanının lüzumu üzerine, durumun devamı müddetince ilgilinin talebine bakılmaksızın Milli Savunma Bakanlığının onayı ile uzatılabilir","Süre yalnızca E'nin yazılı talebi ve onayı ile uzatılabilir","Süre, hiçbir makamın onayına gerek olmaksızın doğrudan Cumhurbaşkanı kararıyla uzatılır","Savaş hâlinde uzatma yapılamaz; süre dolan personel terhis edilir"],"dogru":1,"aciklama":"m.6/2: Seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının göstereceği lüzum üzerine, durumun devamı müddetince ilgisine göre MSB veya İçişleri Bakanlığının onayı ile TALEBE BAKILMAKSIZIN uzatılabilir.","kaynak":"4678 m.6/2","zorluk":"zor"},
    {"id":"4678-OO-006","soru":"Sözleşmeli subay F, Türk Silâhlı Kuvvetlerindeki altıncı fiilî hizmet yılını sürdürmektedir. Muvazzaf subaylığa geçmek isteyen F, şimdiden başvuru yapmak için makamına dilekçe vermiştir. F'nin başvurusu zaman koşulu yönünden nasıl değerlendirilir?","siklar":["Dördüncü fiilî hizmet yılını geçtiği için başvurusu süresindedir","Beşinci fiilî hizmet yılını doldurduğu için başvurabilir","Başvuru ancak yedinci fiilî hizmet yılı başından itibaren yapılabileceğinden, F'nin başvurusu henüz erkendir","İstediği an başvurabilir; muvazzaf geçişte zaman penceresi yoktur","On ikinci fiilî hizmet yılı dolmadan başvuru yapılamaz"],"dogru":2,"aciklama":"m.7/1: Muvazzaf subaylığa geçiş için yedinci fiilî hizmet yılı başından itibaren onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir. Altıncı yıldaki F için pencere henüz açılmamıştır.","kaynak":"4678 m.7/1","zorluk":"zor"},
    {"id":"4678-OO-007","soru":"Sözleşmeli subaylıktan muvazzaf subaylığa geçirilen G, subay nasbedildiği tarihten on bir yıl sonra kişisel nedenlerle istifa etmek için dilekçe vermek istemektedir. G'nin istifa talebi nasıl değerlendirilir?","siklar":["On yılı doldurduğundan istifa edebilir","Subay nasbedildiği tarihten başlamak üzere on beş yıl hizmet etmedikçe istifa edemez","On iki fiilî hizmet yılını doldurduğunda istifa edebilir","Muvazzaf subaylar istedikleri an istifa edebileceğinden talebi kabul edilir","Yirmi yıl hizmet şartı dolmadan istifa edemez"],"dogru":1,"aciklama":"m.7/1: Muvazzaf subaylığa geçirilenler, subay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler. On birinci yılındaki G henüz bu süreyi doldurmamıştır.","kaynak":"4678 m.7/1","zorluk":"zor"},
    {"id":"4678-OO-008","soru":"H, Türk Silahlı Kuvvetleri bünyesinde lisansüstü düzeyde öğretim yapan bir kurumun öğretim üyesi kadrosunda atamalı olarak görev yapan bir sözleşmeli subaydır. H, beşinci fiilî hizmet yılında muvazzaf subaylığa geçiş başvurusu yapmıştır. Bu başvuru zaman koşulu yönünden nasıl değerlendirilir?","siklar":["Yedinci fiilî hizmet yılını beklemesi gerektiğinden başvurusu reddedilir","Öğretim üyesi kadrolarında atamalı görev yapanlarda fiilî hizmet yılı şartı aranmadığından, başvurusu zaman yönünden geçerlidir","Öğretim üyeleri muvazzaf subaylığa hiçbir şekilde geçemez","Ancak dördüncü fiilî hizmet yılında başvurabilirdi, geç kalmıştır","Öğretim üyeleri için pencere on iki yıldan sonra açılır"],"dogru":1,"aciklama":"m.7 son fıkra: TSK bünyesinde ön lisans, lisans ve lisansüstü düzeyde eğitim-öğretim yapan kurum ve kuruluşların öğretim üyesi kadrolarında atamalı olarak görev yapanlarda fiilî hizmet yılı şartı ARANMAZ. H'nin beşinci yılda başvurması zaman yönünden engel oluşturmaz.","kaynak":"4678 m.7/son","zorluk":"zor"},
    {"id":"4678-OO-009","soru":"Aynı birlikte görev yapan iki personelden sözleşmeli astsubay J ile sözleşmeli subay K, her ikisi de dördüncü fiilî hizmet yıllarının başındadır ve muvazzaf statüye geçmek için başvurmak istemektedir. Başvuru zamanı yönünden hangisi doğrudur?","siklar":["İkisi de başvurabilir; her iki geçiş de dördüncü fiilî hizmet yılında başlar","İkisi de başvuramaz; her iki geçiş de yedinci fiilî hizmet yılında başlar","J (astsubay) başvurabilir; K (subay) ise yedinci fiilî hizmet yılı başına kadar başvuramaz","K (subay) başvurabilir; J (astsubay) ise yedinci fiilî hizmet yılını beklemelidir","İkisi de ancak on ikinci fiilî hizmet yılında başvurabilir"],"dogru":2,"aciklama":"m.11/1: Muvazzaf astsubaylığa geçiş başvurusu dördüncü fiilî hizmet yılı başından itibaren; m.7/1: muvazzaf subaylığa geçiş başvurusu yedinci fiilî hizmet yılı başından itibaren yapılabilir. Dördüncü yıldaki J için pencere açıkken, K'nin penceresi henüz açılmamıştır.","kaynak":"4678 m.7/1-m.11/1","zorluk":"zor"},
    {"id":"4678-OO-010","soru":"Sözleşmeli astsubay M'nin sözleşme süresi 1 Eylül tarihinde dolacaktır. Taraflar, bu tarihten yalnızca bir ay önce dahi sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmamıştır. Bu durumda sözleşme bakımından sonuç nedir?","siklar":["Bildirim yapılmadığı için sözleşme aynı şartlarla kendiliğinden yenilenir","Sona erme tarihinden en az üç ay önce yazılı yenileme bildirimi yapılmadığından sözleşme kendiliğinden sona erer","Bir ay önce bildirim yeterli olduğundan sözleşme yenilenmiş sayılır","İdarenin tek taraflı bildirimi ile sözleşme süresiz hâle gelir","Sözleşme altı ay daha kendiliğinden uzar"],"dogru":1,"aciklama":"m.12: Her sözleşme süresinin sona erme tarihinden EN AZ ÜÇ AY ÖNCE taraflar yazılı yenileme bildiriminde bulunmazsa sözleşme kendiliğinden sona erer. Bir ay kala yapılan/yapılmayan bildirim bu süreyi karşılamaz.","kaynak":"4678 m.12","zorluk":"orta"},
    {"id":"4678-OO-011","soru":"Sözleşmeli astsubay N, üç yıllık sözleşme süresinin henüz birinci yılındayken, kişisel nedenlerle sözleşmesini tek taraflı feshederek görevinden ayrılmak için dilekçe vermiştir. N'nin bu talebi kanun bakımından nasıl değerlendirilir?","siklar":["İş sözleşmelerinde olduğu gibi istediği an tek taraflı feshedebilir","Sözleşme süresi sona ermeden sözleşmesini tek taraflı olarak feshedemez","Üç ay önceden bildirimde bulunursa tek taraflı feshedebilir","Birinci yılı doldurduğu için tek taraflı feshedebilir","Yalnızca idare feshedebilir, ancak personel hiçbir hâlde ayrılamaz"],"dogru":1,"aciklama":"m.12: Sözleşmeli subay veya astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedemezler. N süre dolmadan tek taraflı ayrılamaz.","kaynak":"4678 m.12","zorluk":"orta"},
    {"id":"4678-OO-012","soru":"O, sözleşmeli subay adayı olarak askerî eğitime alınmıştır; henüz subaylık nasıp onayı verilmemiş, eğitimi de tamamlanmamıştır. Bu aşamada O ile Türk Silâhlı Kuvvetleri arasındaki ilişkiyi belgeleyen ve eğitim dönemi başlangıcından nasıp onayına kadar geçecek süreyi kapsayan belge hangisidir?","siklar":["Sözleşme","Ön sözleşme","Hizmet yükümlülüğü senedi","Atama onayı","Muvazzaflık taahhütnamesi"],"dogru":1,"aciklama":"m.3/a: Ön sözleşme, adaylarla askerî eğitime alınmaları konusunda yapılan ve askerî eğitim dönemi başlangıcı ile nasıp onayı tarihine kadar geçecek süreyi kapsayan sözleşmedir. Eğitimi başaranla yapılan asıl belge ise 'sözleşme'dir (m.3/b).","kaynak":"4678 m.3/a-b","zorluk":"orta"},
    {"id":"4678-OO-013","soru":"P, iki yıllık bir önlisans programını (dört yıldan daha az süreli yükseköğrenim) bitirmiştir. Sözleşmeli astsubaylığa müracaat ettiği yılın esas alınan gününde, düzeltilmemiş nüfus kaydına göre yirmi dört yaşını bitirmiş durumdadır. P'nin durumu yaş şartı yönünden nasıl değerlendirilir?","siklar":["Dört yıldan az süreli yükseköğrenimde üst yaş yirmi yedi olduğundan yaş şartını taşır","Dört yıldan az süreli yükseköğrenim bitirenlerde üst yaş yirmi dört olduğundan, bu yaşı bitiren P yaş şartını taşımaz","Lisansüstü eşiği olan otuz iki yaş uygulanacağından geçerlidir","Önlisans mezunları yalnızca sözleşmeli subay olabileceğinden değerlendirme dışıdır","Yaş sınırı yalnızca subaylar için olduğundan P her hâlde uygundur"],"dogru":1,"aciklama":"m.8: Sözleşmeli astsubay kaynağında dört yıl ve daha fazla süreli yükseköğrenimi bitirenler için yirmiyedi (27); bundan daha az süreli yükseköğrenimi bitirenler için yirmidört (24) yaşını bitirmemiş olmak aranır. Önlisans (daha az süreli) bitiren P, yirmi dört yaşını bitirdiğinden yaş şartını taşımaz.","kaynak":"4678 m.8","zorluk":"zor"},
  ],
  14: [
    {"id":"5070-S-001","soru":"5070 sayılı Elektronik İmza Kanunu'ndaki tanıma göre, başka bir elektronik veriye eklenen veya elektronik veriyle mantıksal bağlantısı bulunan elektronik imza esas olarak hangi amaçla kullanılır?","siklar":["Veriyi sıkıştırmak","Veriyi yedeklemek","Verinin oluşturulma zamanını damgalamak","Kimlik doğrulamak","Veriyi şifreleyerek üçüncü kişilerden gizlemek"],"dogru":3,"aciklama":"m.3/b: 'Elektronik imza: Başka bir elektronik veriye eklenen veya elektronik veriyle mantıksal bağlantısı bulunan ve kimlik doğrulama amacıyla kullanılan elektronik veriyi' ifade eder. Tanımdaki kullanım amacı kimlik doğrulamadır.","kaynak":"5070 m.3/b","zorluk":"kolay"},
    {"id":"5070-S-002","soru":"5070 sayılı Elektronik İmza Kanunu'na göre, 'elektronik, optik veya benzeri yollarla üretilen, taşınan veya saklanan kayıtlar' aşağıdaki kavramlardan hangisini ifade eder?","siklar":["Elektronik sertifika","Elektronik veri","Elektronik imza","İmza doğrulama verisi","Zaman damgası"],"dogru":1,"aciklama":"m.3/a: 'Elektronik veri: Elektronik, optik veya benzeri yollarla üretilen, taşınan veya saklanan kayıtları' ifade eder.","kaynak":"5070 m.3/a","zorluk":"orta"},
    {"id":"5070-S-003","soru":"5070 sayılı Elektronik İmza Kanunu'na göre 'imza sahibi' ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["İmza sahibi yalnızca tüzel kişi olabilir.","İmza sahibi gerçek veya tüzel kişi olabilir.","İmza sahibi, elektronik imza oluşturmak amacıyla bir imza oluşturma aracını kullanan gerçek kişidir.","İmza sahibi, elektronik sertifika hizmet sağlayıcısıdır.","İmza sahibi, imza doğrulama verisini elinde bulunduran kamu kurumudur."],"dogru":2,"aciklama":"m.3/c: 'İmza sahibi: Elektronik imza oluşturmak amacıyla bir imza oluşturma aracını kullanan gerçek kişiyi' ifade eder. İmza sahibi yalnızca gerçek kişidir.","kaynak":"5070 m.3/c","zorluk":"orta"},
    {"id":"5070-S-004","soru":"5070 sayılı Elektronik İmza Kanunu'na göre, 'imza sahibine ait olan, imza sahibi tarafından elektronik imza oluşturmak amacıyla kullanılan ve bir eşi daha olmayan şifreler, kriptografik gizli anahtarlar gibi veriler' aşağıdakilerden hangisini ifade eder?","siklar":["İmza doğrulama verisi","İmza oluşturma verisi","Elektronik sertifika","Zaman damgası","Elektronik veri"],"dogru":1,"aciklama":"m.3/d: 'İmza oluşturma verisi: İmza sahibine ait olan, imza sahibi tarafından elektronik imza oluşturmak amacıyla kullanılan ve bir eşi daha olmayan şifreler, kriptografik gizli anahtarlar gibi verileri' ifade eder.","kaynak":"5070 m.3/d","zorluk":"orta"},
    {"id":"5070-S-005","soru":"5070 sayılı Elektronik İmza Kanunu'na göre, elektronik imzayı doğrulamak için kullanılan şifreler, kriptografik açık anahtarlar gibi veriler aşağıdakilerden hangisidir?","siklar":["İmza oluşturma verisi","Elektronik veri","İmza doğrulama verisi","İmza oluşturma aracı","Zaman damgası"],"dogru":2,"aciklama":"m.3/f: 'İmza doğrulama verisi: Elektronik imzayı doğrulamak için kullanılan şifreler, kriptografik açık anahtarlar gibi verileri' ifade eder.","kaynak":"5070 m.3/f","zorluk":"orta"},
    {"id":"5070-S-006","soru":"5070 sayılı Elektronik İmza Kanunu'na göre elektronik sertifika, imza sahibinin hangi iki unsurunu birbirine bağlayan elektronik kayıttır?","siklar":["İmza oluşturma verisi ile imza doğrulama verisini","İmza oluşturma verisi ile kimlik bilgilerini","Elektronik veri ile zaman damgasını","Kimlik bilgileri ile yerleşim yeri bilgilerini","İmza doğrulama verisi ile kimlik bilgilerini"],"dogru":4,"aciklama":"m.3/ı: 'Elektronik sertifika: İmza sahibinin imza doğrulama verisini ve kimlik bilgilerini birbirine bağlayan elektronik kaydı' ifade eder. Sertifika, imza doğrulama verisi ile kimlik bilgilerini bağlar.","kaynak":"5070 m.3/ı","zorluk":"orta"},
    {"id":"5070-S-007","soru":"5070 sayılı Elektronik İmza Kanunu'na göre 'zaman damgası' ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Bir elektronik verinin üretildiği, değiştirildiği, gönderildiği, alındığı ve/veya kaydedildiği zamanın tespit edilmesi amacıyla, elektronik sertifika hizmet sağlayıcısı tarafından elektronik imzayla doğrulanan kayıttır.","İmza sahibinin kimlik bilgilerini doğrulama verisine bağlayan elektronik kayıttır.","İmza sahibine ait, bir eşi daha olmayan gizli anahtardır.","Elektronik imza oluşturmak amacıyla kullanılan yazılım veya donanım aracıdır.","Elektronik, optik veya benzeri yollarla üretilen kayıtlardır."],"dogru":0,"aciklama":"m.3/h: 'Zaman damgası: Bir elektronik verinin, üretildiği, değiştirildiği, gönderildiği, alındığı ve/veya kaydedildiği zamanın tespit edilmesi amacıyla, elektronik sertifika hizmet sağlayıcısı tarafından elektronik imzayla doğrulanan kaydı' ifade eder.","kaynak":"5070 m.3/h","zorluk":"zor"},
    {"id":"5070-S-008","soru":"5070 sayılı Elektronik İmza Kanunu'nda 'Kurum' ibaresi Kanun lafzında Telekomünikasyon Kurumunu ifade etmekle birlikte, 5809 sayılı Elektronik Haberleşme Kanunu gereği bugün yürürlükteki makam ............ olarak anlaşılır.","siklar":["Bilgi Teknolojileri ve İletişim Kurumu (BTK)","Bilgi Teknolojileri Kurumu","Radyo ve Televizyon Üst Kurulu","Türkiye Bilimsel ve Teknolojik Araştırma Kurumu","Kişisel Verileri Koruma Kurumu"],"dogru":0,"aciklama":"m.3/j Kanun lafzı 'Kurum: Telekomünikasyon Kurumunu' der; ancak 5809 sayılı Kanun m.65/3 gereği bu ibare bugün Bilgi Teknolojileri ve İletişim Kurumu (BTK) olarak anlaşılır; güncel/yürürlükteki makam BTK'dır.","kaynak":"5070 m.3/j","zorluk":"zor"},
    {"id":"5070-S-009","soru":"5070 sayılı Elektronik İmza Kanunu'na göre güvenli elektronik imzanın unsurlarından biri olarak aşağıdakilerden hangisi sayılmıştır?","siklar":["İki ayrı imza sahibinin ortak tasarrufunda bulunan araçla oluşturulması","Münhasıran imza sahibine bağlı olması","Noter tarafından onaylanmış olması","Elektronik sertifika hizmet sağlayıcısının mührünü taşıması","Telekomünikasyon Kurumunca ayrıca tescil edilmiş olması"],"dogru":1,"aciklama":"m.4/a: Güvenli elektronik imza 'münhasıran imza sahibine bağlı olan' bir elektronik imzadır. Diğer üç unsur: sadece imza sahibinin tasarrufundaki güvenli araçla oluşturulan, nitelikli sertifikaya dayanarak kimlik tespiti sağlayan, sonradan değişiklik tespitini sağlayan.","kaynak":"5070 m.4","zorluk":"orta"},
    {"id":"5070-S-010","soru":"5070 sayılı Elektronik İmza Kanunu'na göre aşağıdakilerden hangisi güvenli elektronik imzanın unsurlarından biri değildir?","siklar":["Münhasıran imza sahibine bağlı olan","Sadece imza sahibinin tasarrufunda bulunan güvenli elektronik imza oluşturma aracı ile oluşturulan","İmza sahibinin yerleşim yerinin valilikçe onaylanmasını sağlayan","Nitelikli elektronik sertifikaya dayanarak imza sahibinin kimliğinin tespitini sağlayan","İmzalanmış elektronik veride sonradan herhangi bir değişiklik yapılıp yapılmadığının tespitini sağlayan"],"dogru":2,"aciklama":"m.4'te sayılan dört unsur A, B, D ve E'dir. C ('yerleşim yerinin valilikçe onaylanması') Kanun'da yer almayan sahte unsurdur.","kaynak":"5070 m.4","zorluk":"zor"},
    {"id":"5070-S-011","soru":"5070 sayılı Elektronik İmza Kanunu'na göre güvenli elektronik imza, aşağıdakilerden hangisiyle aynı hukukî sonucu doğurur?","siklar":["Noter tasdikiyle","Elle atılan imza ile","Parmak iziyle","Mühürle","Resmî senetle"],"dogru":1,"aciklama":"m.5/1: 'Güvenli elektronik imza, elle atılan imza ile aynı hukukî sonucu doğurur.'","kaynak":"5070 m.5","zorluk":"kolay"},
    {"id":"5070-S-012","soru":"5070 sayılı Elektronik İmza Kanunu'na göre, kanunların resmî şekle veya özel bir merasime tabi tuttuğu hukukî işlemler güvenli elektronik imza ile gerçekleştirilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5/2: Kanunların resmî şekle veya özel bir merasime tabi tuttuğu hukukî işlemler güvenli elektronik imza ile GERÇEKLEŞTİRİLEMEZ. İfade yanlıştır.","kaynak":"5070 m.5","zorluk":"orta"},
    {"id":"5070-S-013","soru":"5070 sayılı Elektronik İmza Kanunu'na göre aşağıdaki işlemlerden hangisi güvenli elektronik imza ile gerçekleştirilebilir?","siklar":["Kanunların özel bir merasime tabi tuttuğu hukukî işlemler","Banka teminat mektupları","Kanunların resmî şekle tabi tuttuğu hukukî işlemler","Banka teminat mektupları ve sigorta şirketi kefalet senetleri dışındaki teminat sözleşmeleri","Resmî merasime tabi tutulan teminat işlemleri"],"dogru":1,"aciklama":"m.5/2'ye göre 'banka teminat mektupları ve Türkiye'de yerleşik sigorta şirketleri tarafından düzenlenen kefalet senetleri DIŞINDAKİ teminat sözleşmeleri' yapılamaz. Banka teminat mektupları bu yasağın dışında olduğundan güvenli e-imza ile YAPILABİLİR.","kaynak":"5070 m.5","zorluk":"zor"},
    {"id":"5070-S-014","soru":"5070 sayılı Elektronik İmza Kanunu'na göre elektronik imza ile güvenli elektronik imza ilişkisi hakkında aşağıdakilerden hangisi yanlıştır?","siklar":["Her elektronik imza güvenli elektronik imza değildir.","Elle atılan imza ile aynı hukukî sonucu yalnızca güvenli elektronik imza doğurur.","Güvenli elektronik imza nitelikli elektronik sertifikaya dayanarak kimlik tespitini sağlar.","Elektronik imza, kimlik doğrulama amacıyla kullanılan elektronik veridir.","Her elektronik imza, elle atılan imza ile aynı hukukî sonucu doğurur."],"dogru":4,"aciklama":"Islak imzayla eşdeğerlik (m.5) yalnızca GÜVENLİ elektronik imzaya tanınmıştır; sıradan elektronik imza bu sonucu doğurmaz. E yanlıştır. A, B, C, D Kanun'a uygundur.","kaynak":"5070 m.3/b, m.4, m.5","zorluk":"zor"},
    {"id":"5070-OO-001","soru":"A, sahibi olduğu taşınmazı (gayrimenkulü) B'ye satmak istemektedir. Tarafların noter veya tapu önüne gitmesini gereksiz bulan A, satış işlemini tamamen elektronik ortamda güvenli elektronik imzalarıyla yapmayı teklif eder. 5070 sayılı Kanun karşısında bu işlem bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Güvenli e-imza ıslak imzayla eşdeğer olduğundan, taşınmaz satışı da güvenli e-imza ile geçerli biçimde yapılabilir.","Taşınmaz satışı kanunen resmî şekle tabi bir işlem olduğundan güvenli elektronik imza ile gerçekleştirilemez.","İşlem ancak iki tarafın da nitelikli sertifika sahibi olması hâlinde güvenli e-imza ile yapılabilir.","İşlem güvenli e-imza ile yapılabilir; yalnızca sonradan notere onaylatılması gerekir.","İşlem güvenli e-imza ile yapılabilir; yeter ki Bilgi Teknolojileri ve İletişim Kurumu önceden izin versin."],"dogru":1,"aciklama":"m.5/2: 'Kanunların resmî şekle veya özel bir merasime tabi tuttuğu hukukî işlemler ... güvenli elektronik imza ile gerçekleştirilemez.' Taşınmaz satışı resmî şekle tabi olduğundan güvenli e-imza ile yapılamaz; m.5/1'deki ıslak imza eşdeğerliği bu işlemler için bir istisna oluşturmaz.","kaynak":"5070 m.5","zorluk":"orta"},
    {"id":"5070-OO-002","soru":"X Bankası, bir kamu ihalesine katılan Y firması lehine bir banka teminat mektubunu tamamen elektronik ortamda, yetkililerinin güvenli elektronik imzasıyla düzenler. Aynı dönemde Z şirketi de bir başka borca güvence olmak üzere (banka teminat mektubu veya Türkiye'de yerleşik sigorta şirketi kefalet senedi niteliğinde olmayan) bir teminat sözleşmesini güvenli e-imza ile yapmaya çalışır. 5070 sayılı Kanun'a göre bu iki işlemin durumu nedir?","siklar":["Her iki işlem de güvenli e-imza ile geçerli biçimde yapılabilir.","Her iki işlem de güvenli e-imza ile yapılamaz; teminata ilişkin tüm işlemler yasak kapsamındadır.","Banka teminat mektubu güvenli e-imza ile yapılabilir; Z'nin teminat sözleşmesi ise güvenli e-imza ile yapılamaz.","Banka teminat mektubu güvenli e-imza ile yapılamaz; Z'nin teminat sözleşmesi ise yapılabilir.","İki işlem de ancak Bilgi Teknolojileri ve İletişim Kurumu'nun onayıyla yapılabilir."],"dogru":2,"aciklama":"m.5/2: '...banka teminat mektupları ve Türkiye'de yerleşik sigorta şirketleri tarafından düzenlenen kefalet senetleri DIŞINDAKİ teminat sözleşmeleri, güvenli elektronik imza ile gerçekleştirilemez.' Banka teminat mektubu yasağın DIŞINDA olduğundan güvenli e-imza ile yapılabilir; bu istisnaya girmeyen Z'nin teminat sözleşmesi ise yapılamaz.","kaynak":"5070 m.5","zorluk":"zor"},
    {"id":"5070-OO-003","soru":"A ile B, resmî şekle veya özel bir merasime tabi olmayan bir hizmet sözleşmesini tamamen elektronik ortamda, geçerli güvenli elektronik imzalarıyla imzalar. Sonradan yükümlülüklerinden kaçınmak isteyen B, 'sözleşmede elle (ıslak) atılmış bir imza bulunmadığı için sözleşme hukuken geçersizdir' iddiasında bulunur. 5070 sayılı Kanun'a göre bu iddia hakkında ne söylenebilir?","siklar":["İddia haklıdır; elektronik imza hiçbir zaman ıslak imza yerine geçmez.","İddia haksızdır; güvenli elektronik imza elle atılan imza ile aynı hukukî sonucu doğurur, sözleşme geçerlidir.","İddia haklıdır; sözleşmenin geçerliliği için ayrıca noter onayı şarttır.","İddia haklıdır; elektronik sözleşmeler ancak çıktısı alınıp ıslak imzayla imzalanırsa geçerli olur.","İddia haksızdır; çünkü sıradan elektronik imza da elle atılan imza ile her zaman aynı sonucu doğurur."],"dogru":1,"aciklama":"m.5/1: 'Güvenli elektronik imza, elle atılan imza ile aynı hukukî sonucu doğurur.' İşlem resmî şekle/özel merasime de tabi olmadığından m.5/2 istisnasına girmez; güvenli e-imza ile imzalanan sözleşme geçerlidir.","kaynak":"5070 m.5","zorluk":"orta"},
    {"id":"5070-OO-004","soru":"X İnşaat A.Ş., kurumsal işlemlerini hızlandırmak için elektronik imzayı doğrudan tüzel kişi olan şirketin kendi adına 'imza sahibi' sıfatıyla kullanmak ister; yani sertifikanın bir gerçek kişiye değil, doğrudan şirkete ait olmasını talep eder. 5070 sayılı Kanun'daki tanım karşısında bu talep bakımından doğru olan nedir?","siklar":["Talep yerindedir; imza sahibi gerçek veya tüzel kişi olabilir.","Talep yerindedir; imza sahibi yalnızca tüzel kişi olabilir.","İmza sahibi, imza oluşturma aracını kullanan gerçek kişidir; tüzel kişi doğrudan imza sahibi olamaz.","Talep yerindedir; ancak şirketin önce elektronik sertifika hizmet sağlayıcısı olarak yetkilendirilmesi gerekir.","İmza sahibi, imza doğrulama verisini elinde bulunduran kamu kurumu olduğundan talep reddedilir."],"dogru":2,"aciklama":"m.3/c: 'İmza sahibi: Elektronik imza oluşturmak amacıyla bir imza oluşturma aracını kullanan gerçek kişiyi' ifade eder. İmza sahibi yalnızca gerçek kişi olabilir; tüzel kişi (şirket) doğrudan imza sahibi olamaz, ancak yetkili gerçek kişisi imza sahibi olur.","kaynak":"5070 m.3/c","zorluk":"orta"},
    {"id":"5070-OO-005","soru":"A, bir belgeyi elektronik imzasıyla imzalar. Bu imza kimlik doğrulama amacıyla belgeye eklenmiştir; ancak kullanılan sistem, imzalanmış belgede sonradan değişiklik yapılıp yapılmadığının tespitini sağlamamakta ve nitelikli elektronik sertifikaya da dayanmamaktadır. 5070 sayılı Kanun'a göre A'nın bu imzası bakımından aşağıdakilerden hangisi doğrudur?","siklar":["İmza, kimlik doğrulama amacı taşıdığından otomatik olarak güvenli elektronik imza sayılır.","İmza bir elektronik imzadır; ancak m.4'teki unsurların tamamını taşımadığından güvenli elektronik imza sayılmaz ve elle atılan imzayla eşdeğer olmaz.","İmza geçersizdir; bu nitelikteki bir veri elektronik imza olarak dahi kabul edilmez.","İmza güvenli elektronik imzadır; eksik unsurlar sonradan tamamlanabildiği için sonuç değişmez.","İmza, banka teminat mektupları dışındaki tüm işlemlerde elle atılan imzayla eşdeğer sonuç doğurur."],"dogru":1,"aciklama":"m.4'e göre güvenli elektronik imza dört unsuru (münhasıran sahibine bağlı, yalnız sahibinin tasarrufundaki araçla oluşturma, nitelikli sertifikayla kimlik tespiti, sonradan değişiklik tespiti) birlikte taşır. Bu unsurlardan ikisi eksik olduğundan imza 'güvenli' sayılmaz; m.5/1 eşdeğerliği yalnız güvenli e-imzaya tanındığından elle atılan imzayla aynı sonucu doğurmaz. Ancak m.3/b anlamında bir elektronik imza olarak kalır.","kaynak":"5070 m.4","zorluk":"zor"},
    {"id":"5070-OO-006","soru":"A, işlerini hızlandırmak için elektronik imza oluştururken kullandığı imza oluşturma verisini (gizli/kriptografik gizli anahtarını) iş arkadaşı B ile paylaşır; böylece B de A adına imza atabilir hâle gelir. 5070 sayılı Kanun'daki tanım ve niteliklere göre bu durumun değerlendirilmesi için en doğru ifade hangisidir?","siklar":["Sorun yoktur; imza oluşturma verisi herkese açık bir anahtar olduğundan paylaşılması doğaldır.","İmza oluşturma verisi imza sahibine ait, bir eşi daha olmayan gizli bir veridir ve güvenli e-imza münhasıran imza sahibine bağlı olmalıdır; bu nedenle verinin paylaşılması bu nitelikleri zedeler.","Sorun yoktur; imza oluşturma verisi ile imza doğrulama verisi aynı şey olduğundan paylaşımın bir önemi yoktur.","Paylaşım gereklidir; çünkü güvenli e-imza ancak iki kişinin ortak tasarrufundaki araçla oluşturulabilir.","Sorun yoktur; çünkü imza oluşturma verisini elektronik sertifika hizmet sağlayıcısı zaten herkesle paylaşır."],"dogru":1,"aciklama":"m.3/d: imza oluşturma verisi 'imza sahibine ait olan ... bir eşi daha olmayan şifreler, kriptografik gizli anahtarlar gibi' GİZLİ veridir. m.4/a: güvenli e-imza 'münhasıran imza sahibine bağlı' olmalıdır. Gizli verinin başkasıyla paylaşılması hem verinin gizli/eşsiz niteliğini hem de imzanın münhasıran sahibine bağlılığını zedeler.","kaynak":"5070 m.3/d, m.4/a","zorluk":"zor"},
  ],
  15: [
    {"id":"RY-S-001","soru":"Resmî Yazışmalarda Uygulanacak Usul ve Esaslar Hakkında Yönetmelik'e göre resmî yazışma ortamları ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Resmî yazışmalar, elektronik ortamda e-Yazışma Teknik Rehberi'ne uygun hazırlanan ve güvenli elektronik imza ile imzalanan belgelerle yapılır.","Güvenli elektronik imza ile imzalanan belgeler elektronik ortamda muhatapları ile paylaşılır ve elektronik ortamda saklanır.","Zorunlu hâllerde veya olağanüstü durumlarda resmî yazışmalar el yazısıyla imzalanan belgelerle yapılır.","Güvenli elektronik imza ile imzalanan belgeler, çıktısı alınarak el yazısıyla atılan imza ile imzalanabilir ve fiziksel ortamda saklanabilir.","Fiziksel ortamda hazırlanan belgelerin gönderilmesi ve saklanması fiziksel ortam şartlarına göre gerçekleştirilir."],"dogru":3,"aciklama":"m.4/1'e göre güvenli elektronik imza ile imzalanan belgeler çıktısı alınarak el yazısıyla atılan imza ile imzalanMAZ ve fiziksel ortamda saklanMAZ. D bu kuralın tersini söylediği için yanlıştır.","kaynak":"m.4/1-2","zorluk":"orta"},
    {"id":"RY-S-002","soru":"Yönetmeliğe göre belgenin yazı alanı, sayfanın üst, sol ve sağ kenarından ___ boşluk bırakılarak düzenlenir.","siklar":["1 cm","1,5 cm","2 cm","2,5 cm","0,5 cm"],"dogru":1,"aciklama":"m.8/1'e göre yazı alanı üst, sol ve sağ kenardan 1,5 cm boşluk bırakılarak düzenlenir.","kaynak":"m.8/1","zorluk":"orta"},
    {"id":"RY-S-003","soru":"Yönetmeliğe göre belgenin 'Sayı:' bölümünde olağanüstü durumlar için kullanılan ön ek aşağıdakilerden hangisidir?","siklar":["E","Z","O","D","F"],"dogru":2,"aciklama":"m.11/1'e göre sayı; elektronik ortam için 'E', zorunlu hâller için 'Z', olağanüstü durumlar için 'O' ön ekiyle başlar. Örnek: O-67915368-952.02.05-10.","kaynak":"m.11/1","zorluk":"kolay"},
    {"id":"RY-S-004","soru":"Yönetmeliğe göre belgenin 'Sayı:' bölümü aşağıdaki unsurlardan hangisini içermez?","siklar":["Elektronik/zorunlu/olağanüstü ortamı gösteren ön ek (E, Z veya O)","DETSİS'te belirtilen Türkiye Cumhuriyeti Devlet Teşkilatı Numarası","Muhatabın T.C. kimlik numarası","Standart dosya planı kodu","Kayıt numarası"],"dogru":2,"aciklama":"m.11/1'e göre sayı; ortam öneki, DETSİS Devlet Teşkilatı Numarası, standart dosya planı kodu ve kayıt numarasından oluşur (aralarına kısa çizgi konur). Muhatabın T.C. kimlik numarası sayı bölümünün bir unsuru değildir.","kaynak":"m.11/1","zorluk":"orta"},
    {"id":"RY-S-005","soru":"Yönetmeliğe göre 'belgenin hazırlanmasından tasfiyesine kadar olan sürecini' ifade eden kavram aşağıdakilerden hangisidir?","siklar":["Aidiyet zinciri","Üstveri","Arşiv imza","Üst yazı","Elektronik onay"],"dogru":0,"aciklama":"m.3'e göre aidiyet zinciri, belgenin hazırlanmasından tasfiyesine kadar olan sürecini ifade eder.","kaynak":"m.3","zorluk":"orta"},
    {"id":"RY-S-006","soru":"Yönetmeliğe göre 'İlgili mevzuattaki özel hükümlere göre belgenin fiziksel ortamda hazırlanması gereken hâlleri' ifade eden kavram aşağıdakilerden hangisidir?","siklar":["Olağanüstü durum","Zorunlu hâl","Aidiyet zinciri","Arşiv imza","Elektronik onay"],"dogru":1,"aciklama":"m.3/t'ye göre zorunlu hâl, ilgili mevzuattaki özel hükümlere göre belgenin fiziksel ortamda hazırlanması gereken hâlleri ifade eder.","kaynak":"m.3/t","zorluk":"orta"},
    {"id":"RY-S-007","soru":"Yönetmeliğe göre zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgeler en az kaç nüsha olarak düzenlenir?","siklar":["Bir nüsha","İki nüsha","Üç nüsha","Dört nüsha","Beş nüsha"],"dogru":1,"aciklama":"m.5/2'ye göre zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgeler, paraflı nüshası hazırlayan idarede kalacak şekilde en az iki nüsha olarak düzenlenir.","kaynak":"m.5/2","zorluk":"orta"},
    {"id":"RY-S-008","soru":"Yönetmeliğe göre elektronik ortamda güvenli elektronik imza ile imzalanan belgeler ___ olarak hazırlanır.","siklar":["en az iki nüsha","muhatap sayısı kadar","tek nüsha","üç nüsha","paraflı iki nüsha"],"dogru":2,"aciklama":"m.5/1'e göre elektronik ortamda güvenli elektronik imza ile imzalanan belgeler tek nüsha olarak hazırlanır.","kaynak":"m.5/1","zorluk":"kolay"},
    {"id":"RY-S-009","soru":"Yönetmeliğe göre belgelerde kullanılan yazı tipi ve harf büyüklüğü ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["'Times New Roman' veya 'Arial' yazı tipi normal yazı stilinde kullanılır.","Harf büyüklüğünün Times New Roman için 12 punto olması esastır.","Harf büyüklüğünün Arial için 11 punto olması esastır.","Gerekli hâllerde yazı alanında harf büyüklüğü 9 puntoya kadar düşürülebilir.","Gerekli hâllerde iletişim bilgileri kısmında harf büyüklüğü 6 puntoya kadar düşürülebilir."],"dogru":4,"aciklama":"m.7/1'e göre iletişim bilgileri kısmında harf büyüklüğü 8 puntoya kadar düşürülebilir, 6 puntoya değil. Yazı alanında ise 9 puntoya kadar düşürülebilir.","kaynak":"m.7/1","zorluk":"orta"},
    {"id":"RY-S-010","soru":"Yönetmeliğe göre bir belge üzerinde en fazla kaç logo kullanılabilir?","siklar":["Bir","İki","Üç","Dört","Sınırsız"],"dogru":1,"aciklama":"m.9'a göre belge üzerinde en fazla iki logo kullanılabilir. İki logo varsa hiyerarşide üst olan idarenin logosu solda, alt olan idarenin logosu sağda yer alır.","kaynak":"m.9","zorluk":"kolay"},
    {"id":"RY-S-011","soru":"Yönetmeliğe göre başlık (antet) ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Başlık, belgenin yazı alanının üst kısmına ortalanarak yazılır.","İlk satıra 'T.C.' kısaltması yazılır.","İkinci satıra idarenin adı büyük harflerle yazılır.","Başlığın yazımında DETSİS'te yer alan başlık kayıtları esas alınır.","Başlık, belgenin gönderildiği idarenin adının belirtildiği bölümdür."],"dogru":4,"aciklama":"m.10/1'e göre başlık (antet), belgeyi GÖNDEREN idarenin adının belirtildiği bölümdür; belgenin gönderildiği (muhatap) idarenin değil. E bu nedenle yanlıştır. A (yazı alanı üstüne ortalı), B (1. satır T.C.), C (2. satır idare adı büyük harf) ve D (DETSİS başlık kayıtları esas) maddeyle birebir doğrudur.","kaynak":"m.10/1","zorluk":"orta"},
    {"id":"RY-S-012","soru":"Yönetmeliğe göre metnin son bölümündeki bitiş ibareleri ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Hiyerarşi yönünden alt makamlara '… rica ederim.' ibaresiyle bitirilir.","Üst ve aynı düzeydeki makamlara '… arz ederim.' ibaresiyle bitirilir.","Üst, aynı düzey ve alt makamlara birlikte dağıtımlı yazışmalar '… arz ve rica ederim.' ibaresiyle bitirilebilir.","Muhatabı gerçek kişi olan yazışmalar 'Saygılarımla.' veya 'Bilgilerinize sunulur.' ibareleriyle bitirilebilir.","1 sayılı Cumhurbaşkanlığı Kararnamesinin 6 ncı maddesi gereğince bakanlıklarla yapılan yazışmalar, Cumhurbaşkanlığı İdari İşler Başkanı tarafından veya adına imzalandığında 'Arz ederim.' ibaresiyle bitirilir."],"dogru":4,"aciklama":"m.16/12-ç'ye göre 1 sayılı Cumhurbaşkanlığı Kararnamesinin 6 ncı maddesi gereğince bakanlıklarla yapılan ve Cumhurbaşkanlığı İdari İşler Başkanı tarafından veya adına imzalanan yazışmalar 'Rica ederim.' ibaresiyle bitirilir, 'Arz ederim.' değil. A, B, C, D maddeyle birebir doğrudur.","kaynak":"m.16/12","zorluk":"orta"},
    {"id":"RY-S-013","soru":"Yönetmeliğe göre hiyerarşi yönünden alt makamlara yapılan yazışmalar hangi ibareyle bitirilir?","siklar":["Rica ederim.","Arz ederim.","Arz ve rica ederim.","Sunarım.","Saygılarımla."],"dogru":0,"aciklama":"m.16/12-a'ya göre alt makamlara '… rica ederim.', üst ve aynı düzeydeki makamlara '… arz ederim.' ibaresiyle bitirilir.","kaynak":"m.16/12-a","zorluk":"orta"},
    {"id":"RY-S-014","soru":"Yönetmeliğe göre belge metninin yazımı ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Paragrafa 1,25 cm içeriden başlanır.","Metin iki yana hizalanır.","Dört ve dörtten çok haneli sayılar sondan sayılmak üzere üçlü gruplara ayrılır ve araya nokta konulur.","Paragraflar arasında bir satır boşluk bırakılır.","Sayılarda kesirler virgül (,) ile ayrılır."],"dogru":3,"aciklama":"m.16/4'e göre paragraflar arasında satır boşluğu bırakılMAZ. D bunun tersini söylediği için yanlıştır.","kaynak":"m.16/4-7","zorluk":"orta"},
    {"id":"RY-S-015","soru":"Yönetmeliğe göre imza ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["İmza yetkisi devredilen makam belgeyi imzaladığında unvanın yanına '…a.' ibaresi konulur.","Belge vekâleten imzalandığında '…V.' biçiminde yazılır.","Zorunlu hâllerde veya olağanüstü durumlarda imza, kaybolmayacak ve kâğıda işlemesini sağlayacak siyah renkli kalemle atılır.","İmza, yazı alanının en sağında ortalanarak ad, soyad ve unvana yer verilerek atılır.","Elektronik ortamda yetkili makam belgeyi güvenli elektronik imzası ile imzalar."],"dogru":2,"aciklama":"m.17/6'ya göre zorunlu hâllerde veya olağanüstü durumlarda el yazısıyla atılan imza MAVİ renkli kalemle atılır, siyah değil. Aynı kural paraf için de geçerlidir (m.21/3).","kaynak":"m.17","zorluk":"orta"},
    {"id":"RY-S-016","soru":"Yönetmeliğe göre belgenin gereğini yerine getirme durumunda olanlar dağıtım bölümünün 'Bilgi:' kısmına yazılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.19/2'ye göre belgenin gereğini yerine getirme durumunda olanlar 'Gereği:' kısmına; belgenin içeriği hakkında bilgi sahibi olması istenenler ise 'Bilgi:' kısmına yazılır. İfade ters olduğu için yanlıştır.","kaynak":"m.19/2","zorluk":"kolay"},
    {"id":"RY-S-017","soru":"Yönetmeliğe göre elektronik ortamda güvenli elektronik imza ile imzalanan belgelerin doğrulama işlemi, doğrulama kodu ve karekod ile aşağıdakilerden hangisi üzerinden sağlanır?","siklar":["Dijital Türkiye (e-Devlet)","DETSİS","Kayıtlı Elektronik Posta (KEP)","e-Yazışma Teknik Rehberi","Yalnızca belgeyi gönderen idarenin internet sitesi"],"dogru":0,"aciklama":"m.23/2'ye göre belge doğrulama işlemi, doğrulama kodu ve karekod ile Dijital Türkiye (e-Devlet) üzerinden sağlanır.","kaynak":"m.23/2","zorluk":"orta"},
    {"id":"RY-S-018","soru":"Yönetmeliğe göre gizlilik dereceli belgeler ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["'Hizmete Özel' gizlilik dereceli belgelerin tüm işlemleri fiziksel ortamda gerçekleştirilir.","'Özel' ve üstü gizlilik dereceli belgelerin tüm işlemleri elektronik ortamda gerçekleştirilir.","'Hizmete Özel' gizlilik dereceli belgelerin hazırlanması, saklanması ve gönderilmesi dâhil tüm işlemleri elektronik ortamda gerçekleştirilir.","Belgeye ait gizlilik derecesinin belirlenmesinden belgeyi hazırlayan memur sorumludur.","Tüm gizlilik dereceli belgeler yalnızca fiziksel ortamda saklanır."],"dogru":2,"aciklama":"m.25/1'e göre 'Hizmete Özel' belgelerin tüm işlemleri elektronik ortamda; m.25/2'ye göre 'Özel' ve üstü belgelerin işlemleri fiziksel ortamda gerçekleştirilir. m.25/3'e göre gizlilik derecesini belgenin imzacısı olan yetkili makam belirler.","kaynak":"m.25","zorluk":"orta"},
    {"id":"RY-S-019","soru":"Yönetmeliğe göre 'ACELE' ibaresi taşıyan bir belgeye nasıl cevap verilir?","siklar":["Belirtilen süre içinde","Beş iş günü içinde","On beş iş günü içinde","İki iş günü içinde","Derhâl ve süratle"],"dogru":4,"aciklama":"m.26/2'ye göre 'ACELE' ibaresi taşıyan belgeye derhâl ve süratle; 'GÜNLÜDÜR' ibaresi taşıyan belgeye ise belirtilen süre içinde cevap verilir.","kaynak":"m.26/2","zorluk":"orta"},
    {"id":"RY-S-020","soru":"Yönetmeliğe göre (fiziksel ortamda hazırlanan) süreli belgelerde 'ACELE' veya 'GÜNLÜDÜR' ibaresi yazı alanının neresinde ve hangi renkte belirtilir?","siklar":["Sol üst köşede mavi renkli","Sağ üst köşede kırmızı renkli","Sağ alt köşede kırmızı renkli","Üst orta kısımda siyah renkli","Sol alt köşede kırmızı renkli"],"dogru":1,"aciklama":"m.26/3'e göre süreli belgelerde 'ACELE' veya 'GÜNLÜDÜR' ibaresi yazı alanının sağ üst köşesinde kırmızı renkli olarak belirtilir.","kaynak":"m.26/3","zorluk":"orta"},
    {"id":"RY-S-021","soru":"Yönetmeliğe göre 'ASLI GİBİDİR' ibaresiyle belge çoğaltılması ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Zorunlu hâllerde veya olağanüstü durumlarda fiziksel ortamda hazırlanan bir belgeden örnek çıkartılması hâlinde kullanılır.","Elektronik ortamda saklanan her güvenli elektronik imzalı belgenin çıktısına otomatik olarak 'ASLI GİBİDİR' ibaresi konulur.","Yönetmeliğin yürürlüğe girdiği tarihten önce fiziksel ortamda hazırlanan bir belgeden örnek çıkartılması hâlinde kullanılır.","Çoğaltılan belge, yetkilendirilmiş görevli tarafından ad, soyad, unvan ve tarih belirtilmek suretiyle imzalanır.","Bu şekilde çoğaltılan belge, asıl belge gibi kabul edilir."],"dogru":1,"aciklama":"m.29/2'ye göre 'ASLI GİBİDİR' ibaresi yalnızca zorunlu hâl/olağanüstü durum ya da Yönetmeliğin yürürlüğünden önce fiziksel hazırlanan belgelerden örnek çıkartılmasında kullanılır. Güvenli e-imzalı belgenin çoğaltılması ise çıktı alınıp m.23/2'deki karekod ile doğrulanarak yapılır (otomatik 'ASLI GİBİDİR' konulmaz).","kaynak":"m.29/2","zorluk":"zor"},
    {"id":"RY-S-022","soru":"Yönetmeliğe göre e-Yazışma Teknik Rehberi'ne uygun hazırlanmamış bir belgeyi reddeden idare, bu durumu sebepleriyle birlikte gönderen idareye en geç ne zaman bildirir?","siklar":["Belgenin kendisine ulaştığı gün","Belgenin ulaştığı tarihi takip eden ikinci iş gününün sonuna kadar","Beş iş günü içinde","On beş iş günü içinde","Üç iş günü içinde"],"dogru":1,"aciklama":"m.30/4'e göre belgeyi reddeden idare, durumu sebepleriyle birlikte gönderen idareye belgenin kendisine ulaştığı tarihi takip eden ikinci iş gününün sonuna kadar bildirir.","kaynak":"m.30/4","zorluk":"orta"},
    {"id":"RY-S-023","soru":"Yönetmeliğe göre kişiler tarafından idareye yazılan dilekçelerin '… arz ederim.' şeklinde bitirilmemesi veya başka ibarelerle bitirilmesi, dilekçenin işleme alınmasına engel değildir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.31/7'ye göre kişilerin dilekçelerinin '… arz ederim.' ile bitirilmemesi, '… rica ederim.' ya da başka ibarelerle bitirilmesi dilekçenin işleme alınmasına engel değildir. İfade doğrudur.","kaynak":"m.31/7","zorluk":"orta"},
    {"id":"RY-S-024","soru":"Yönetmeliğe göre idareler, ilgili mevzuattaki özel hükümler saklı kalmak kaydıyla, süre belirtilmeyen belge taleplerini talebin kendilerine ulaşmasından itibaren en geç kaç iş günü içinde yerine getirir?","siklar":["Beş iş günü","İki iş günü","On iş günü","On beş iş günü","Otuz iş günü"],"dogru":0,"aciklama":"m.33'e göre süre belirtilmeyen belge talepleri en geç beş iş günü içinde yerine getirilir. (2014 yönetmeliğindeki ek süre 2020'de kaldırılmıştır.)","kaynak":"m.33","zorluk":"orta"},
    {"id":"RY-S-025","soru":"Yönetmeliğe göre idarelerin taleplere ilişkin süreleriyle ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Süre belirtilmeyen belge talepleri en geç beş iş günü içinde yerine getirilir.","Süre belirtilmeyen bilgi ve görüş talepleri en geç on beş iş günü içinde yerine getirilir.","Bu süreler, ilgili mevzuattaki özel hükümler saklı kalmak kaydıyla uygulanır.","Süreler, talebin idareye ulaşmasından itibaren işlemeye başlar.","Süre belirtilmeyen bilgi ve görüş talepleri için ayrıca en çok on beş iş günlük ek süre kullanılabilir."],"dogru":4,"aciklama":"m.33'e göre 2020 Yönetmeliğinde belge talebi en geç beş, bilgi ve görüş talebi en geç on beş iş günüdür; bu süreler talebin ulaşmasından itibaren ve özel hükümler saklı kalmak kaydıyla işler. 2014 Yönetmeliğindeki ek süre imkânı 2020'de KALDIRILMIŞTIR; bu nedenle ek süreyi diriltmeye çalışan E yanlıştır. A, B, C, D doğrudur.","kaynak":"m.33","zorluk":"orta"},
    {"id":"RY-S-026","soru":"Yönetmeliğe göre belgenin 'İlgi' bölümü ile ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["İlgi, belgenin bağlantılı olduğu diğer belge veya belgelerin belirtildiği bölümdür.","İlginin birden fazla olması durumunda belgeler önceki tarihli olandan başlanarak tarih sırasına göre sıralanır.","İlgide '… tarihli ve … sayılı …' ibaresi kullanılır ve ilginin sonuna nokta (.) işareti konulur.","İlginin birden fazla olması durumunda belgeler en yeni tarihli olandan başlanarak eskiye doğru sıralanır.","İlgide belirtilen belge gerçek kişiden geliyorsa ilgi bölümü '…'ın … tarihli başvurusu/dilekçesi.' biçiminde yazılır."],"dogru":3,"aciklama":"m.15/5'e göre ilginin birden fazla olması durumunda belgeler ÖNCEKİ (eski) tarihli olandan başlanarak tarih sırasına göre sıralanır; en yeniden eskiye doğru değil. D bu nedenle yanlıştır. A (tanım), B (sıralama yönü), C ('… tarihli ve … sayılı …' + nokta) ve E (gerçek kişi başvurusu biçimi) maddeyle birebir doğrudur.","kaynak":"m.15","zorluk":"orta"},
    {"id":"RY-OO-001","soru":"(X) İlçe Kaymakamlığı, hiyerarşik olarak bağlı bulunduğu (Y) Valiliğine bir konuyu bildirmek üzere resmî yazı hazırlamaktadır. Yönetmeliğe göre bu yazının metni hangi ibareyle bitirilmelidir?","siklar":["… rica ederim.","… arz ederim.","… arz ve rica ederim.","… saygılarımla.","… bilgilerinize sunulur."],"dogru":1,"aciklama":"m.16/12-a'ya göre hiyerarşi yönünden üst ve aynı düzeydeki makamlara '… arz ederim.' ibaresiyle bitirilir. Kaymakamlık valiliğe (üst makama) yazdığından doğru ibare 'arz ederim'dir.","kaynak":"m.16/12-a","zorluk":"orta"},
    {"id":"RY-OO-002","soru":"Bir idare, aynı belgeyi tek seferde; üst makamına, kendisiyle aynı düzeydeki bir kuruma ve kendisine bağlı alt bir birime dağıtımlı olarak göndermektedir. Yönetmeliğe göre bu dağıtımlı yazının metni hangi ibareyle bitirilmelidir?","siklar":["Yalnızca … arz ederim.","Yalnızca … rica ederim.","… arz ve rica ederim.","… saygılarımla.","Her muhatap için ayrı ayrı belge düzenlenir; tek ibare kullanılamaz."],"dogru":2,"aciklama":"m.16/12-b'ye göre üst, aynı düzey ve alt makamlara birlikte dağıtımlı olarak yapılan yazışmalar '… arz ve rica ederim.' veya '… arz/rica ederim.' ibaresiyle bitirilir.","kaynak":"m.16/12-b","zorluk":"orta"},
    {"id":"RY-OO-003","soru":"Bir kurum, hazırladığı yazıyı iki muhataba göndermektedir: (A) Kurumu yazıdaki işlemi fiilen yerine getirecek, (B) Kurumunun ise yalnızca konudan haberdar olması istenmektedir. Yönetmeliğe göre dağıtım bölümünde (A) Kurumu hangi kısma yazılır?","siklar":["'Bilgi:' kısmına","'Gereği:' kısmına","'Koordinasyon:' kısmına","'İlgi:' kısmına","'Olur:' kısmına"],"dogru":1,"aciklama":"m.19/2'ye göre belgenin gereğini yerine getirme durumunda olanlar 'Gereği:' kısmına, içeriği hakkında bilgi sahibi olması istenenler ise 'Bilgi:' kısmına yazılır. İşlemi yapacak (A) Kurumu 'Gereği:' kısmına yazılır.","kaynak":"m.19/2","zorluk":"orta"},
    {"id":"RY-OO-004","soru":"Bir memur, 'Hizmete Özel' gizlilik dereceli bir belge hazırlayacaktır. Yönetmeliğe göre bu belgenin hazırlanması, saklanması ve gönderilmesi dâhil işlemleri hangi ortamda gerçekleştirilir?","siklar":["Tüm işlemleri fiziksel ortamda gerçekleştirilir.","Tüm işlemleri elektronik ortamda gerçekleştirilir.","Hazırlanması elektronik, saklanması fiziksel ortamda gerçekleştirilir.","Yalnızca elden teslim edilerek fiziksel ortamda saklanır.","İdarenin tercihine göre fiziksel veya elektronik ortamda gerçekleştirilebilir."],"dogru":1,"aciklama":"m.25/1'e göre 'Hizmete Özel' gizlilik dereceli belgelerin hazırlanması, kaydedilmesi, saklanması, gönderilmesi, alınması ve diğer işlemleri elektronik ortamda gerçekleştirilir. (m.25/2 uyarınca fiziksel ortam yalnızca 'Özel' ve üstü derecelere ait kuraldır.)","kaynak":"m.25/1-2","zorluk":"orta"},
    {"id":"RY-OO-005","soru":"Bir idareye, üzerinde 'ACELE' ibaresi bulunan bir belge ulaşmıştır. Yönetmeliğe göre bu belgeye nasıl cevap verilmesi gerekir?","siklar":["Belgede belirtilen süre içinde","Derhâl ve süratle","En geç beş iş günü içinde","En geç on beş iş günü içinde","İkinci iş gününün sonuna kadar"],"dogru":1,"aciklama":"m.26/2'ye göre 'ACELE' ibaresi taşıyan belgeye derhâl ve süratle cevap verilir. 'Belirtilen süre içinde' cevap ise 'GÜNLÜDÜR' ibaresi taşıyan belgeye aittir.","kaynak":"m.26/2","zorluk":"orta"},
    {"id":"RY-OO-006","soru":"Bir genel müdür, belirli yazıları imzalama yetkisini genel müdür yardımcısına devretmiştir. Yardımcı, bu yetkiye dayanarak bir belgeyi imzalamıştır. Yönetmeliğe göre imza bölümünde unvanın yazımı nasıl olmalıdır?","siklar":["Genel Müdür V.","Genel Müdür a.","Genel Müdür Yardımcısı V.","Genel Müdür (vekil)","Genel Müdür Yrd. a."],"dogru":1,"aciklama":"m.17/9'a göre belge, imza yetkisi devredilen makam tarafından imzalandığında yetkiyi devreden makamın unvanının altına/yanına '…a.' (adına) ibaresi konur; yani 'Genel Müdür a.' yazılır. 'V.' ibaresi ise vekâleten imzalama hâline aittir (m.17/10).","kaynak":"m.17/9-10","zorluk":"orta"},
    {"id":"RY-OO-007","soru":"Bir görevli, elektronik ortamda güvenli elektronik imza ile imzalanmış bir belgenin yetkili olarak çıktısını almış ve bu çıktının üzerine 'ASLI GİBİDİR' ibaresi koyarak çoğaltmıştır. Yönetmeliğe göre bu uygulama hakkında hangisi doğrudur?","siklar":["İşlem doğrudur; güvenli e-imzalı belgenin her çıktısına 'ASLI GİBİDİR' konulması zorunludur.","İşlem hatalıdır; güvenli e-imzalı belgenin çoğaltılan çıktısının doğrulaması, doğrulama kodu ve karekod ile yapılır, 'ASLI GİBİDİR' konulmaz.","İşlem doğrudur; ancak ibarenin yanına ayrıca mavi kalemle imza atılması gerekir.","İşlem hatalıdır; güvenli e-imzalı belgenin hiçbir şekilde çıktısı alınamaz.","İşlem doğrudur; 'ASLI GİBİDİR' yerine 'SURETİDİR' yazılması koşuluyla geçerlidir."],"dogru":1,"aciklama":"m.29/1'e göre güvenli e-imzalı belgenin çoğaltılması yetkili görevlilerce çıktı alınarak yapılır ve doğrulaması m.23/2'deki gibi doğrulama kodu ve karekodla sağlanır. 'ASLI GİBİDİR' ibaresi (m.29/2) yalnızca zorunlu hâl/olağanüstü durum ya da Yönetmeliğin yürürlüğünden önce fiziksel hazırlanan belgelerin örneğine konur; güvenli e-imzalı belgenin çıktısına konulmaz.","kaynak":"m.29","zorluk":"zor"},
    {"id":"RY-OO-008","soru":"Bir vatandaş, idareye verdiği dilekçesini '… rica ederim.' ibaresiyle bitirmiştir. Evrak görevlisi, dilekçenin resmî yazışma kurallarına göre '… arz ederim.' ile bitmediği gerekçesiyle dilekçeyi işleme almak istememektedir. Yönetmeliğe göre doğru olan nedir?","siklar":["Görevli haklıdır; dilekçe 'arz ederim' ile bitmediği için işleme alınamaz.","Bitiş ibaresinin '… arz ederim.' olmaması veya başka bir ibareyle bitirilmesi dilekçenin işleme alınmasına engel değildir.","Dilekçe ancak vatandaş tarafından düzeltilip yeniden verilirse işleme alınır.","Dilekçe yalnızca 'Saygılarımla.' ile biterse işleme alınabilir.","Görevli dilekçedeki ibareyi 'arz ederim' olarak düzelterek işleme alır."],"dogru":1,"aciklama":"m.31/7'ye göre kişilerce idareye yazılan dilekçelerin '… arz ederim.' şeklinde bitirilmemesi veya '… rica ederim.' ya da başka ibarelerle bitirilmesi, dilekçenin işleme alınmasına engel değildir. Dolayısıyla dilekçe işleme alınır.","kaynak":"m.31/7","zorluk":"orta"},
  ],
  16: [
    {"id":"SOZLESMELI-S-001","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre 'ön sözleşme' ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getirir.","Sözleşmeli subay veya astsubay olmak için müracaat etmiş ancak henüz kendisiyle sözleşme yapılmamış kişiyle yapılır.","Askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp kararnamesinin onay tarihine kadar geçecek süreyi kapsar.","Askerî eğitimi başarı ile tamamlayanlar arasında yapılan yazılı belgedir.","Yalnızca müteakip sözleşmeler için Tayin/Atama Daire Başkanı tarafından yapılır."],"dogru":2,"aciklama":"m.3/a: Ön sözleşme, askerî eğitim dönemi başlangıcı ile subaylık/astsubaylık nasıp kararnamesinin onay tarihine kadar geçen süreyi kapsayan sözleşmedir.","kaynak":"m.3/a","zorluk":"orta"},
    {"id":"SOZLESMELI-S-002","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşme, üç yıldan az, ______ fazla olmamak üzere hizmet yükümlülüğü getiren yazılı belgedir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["beş yıldan","dokuz yıldan","on yıldan","on iki yıldan","yedi yıldan"],"dogru":1,"aciklama":"m.3/b: Sözleşme, üç yıldan az dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getirir (m.12 ile de tutarlı: asgari 3 – azami 9 yıl).","kaynak":"m.3/b","zorluk":"kolay"},
    {"id":"SOZLESMELI-S-003","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre 'sözleşmeli subay'; hangi rütbeleri haiz subayları ifade eder?","siklar":["Teğmen, üsteğmen ve yüzbaşı","Teğmen, üsteğmen, yüzbaşı ve binbaşı","Astsubay çavuş, kıdemli çavuş ve üstçavuş","Yalnızca teğmen ve üsteğmen","Üsteğmen, yüzbaşı ve binbaşı"],"dogru":0,"aciklama":"m.3/e: Sözleşmeli subay, kendileriyle sözleşme yapılarak nasbedilen teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subaylardır; tavan yüzbaşıdır.","kaynak":"m.3/e","zorluk":"kolay"},
    {"id":"SOZLESMELI-S-004","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre aşağıdakilerden hangisi sözleşmeli astsubayın haiz olabileceği rütbelerden biri DEĞİLDİR?","siklar":["Astsubay çavuş","Astsubay kıdemli çavuş","Astsubay üstçavuş","Astsubay başçavuş","Astsubay kıdemli üstçavuş"],"dogru":3,"aciklama":"m.3/f: Sözleşmeli astsubay; astsubay çavuş, kıdemli çavuş, üstçavuş ve kıdemli üstçavuş rütbelerini haiz olur. Tavan kıdemli üstçavuştur; 'astsubay başçavuş' bu kapsamda sayılmamıştır.","kaynak":"m.3/f","zorluk":"orta"},
    {"id":"SOZLESMELI-S-005","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşmeli subay kaynağına ilişkin yaş sınırları aşağıdakilerin hangisinde tam ve doğru verilmiştir? (Müracaat yapılan yılın Ocak ayının ilk günü itibarıyla)","siklar":["En az dört yıllık mezunlar için 24, lisansüstü için 27 yaşını bitirmemiş olmak","En az dört yıllık mezunlar için 25, lisansüstü için 30 yaşını bitirmemiş olmak","En az dört yıllık mezunlar için 30, lisansüstü için 32 yaşını bitirmemiş olmak","En az dört yıllık mezunlar için 27, lisansüstü için 35 yaşını bitirmemiş olmak","En az dört yıllık mezunlar için 27, lisansüstü için 32 yaşını bitirmemiş olmak"],"dogru":4,"aciklama":"m.5: Sözleşmeli subay kaynağı, en az dört yıllık fakülte/yüksekokul bitirenlerden 27, lisansüstü eğitimini tamamlamış olanlardan 32 yaşını bitirmemiş olanlardan teşkil edilir.","kaynak":"m.5","zorluk":"orta"},
    {"id":"SOZLESMELI-S-006","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre dört yıldan daha az süreli yüksek öğrenimi bitirenler için sözleşmeli astsubay kaynağında aranan yaş sınırı, yirmi dört yaşını bitirmemiş olmaktır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5/b: Dört yıldan daha az süreli yüksek öğrenimi bitirenler için yirmi dört, dört yıl veya daha fazla süreli yüksek öğrenimi bitirenler için yirmi yedi yaşını bitirmemiş olmak gerekir.","kaynak":"m.5/b","zorluk":"kolay"},
    {"id":"SOZLESMELI-S-007","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre aşağıdakilerden hangisi doğrudur?","siklar":["Askerî okuldan ilişiği kesilen personel, aradan beş yıl geçmesi hâlinde sözleşmeli subay olarak alınabilir.","Askerî hâkim sınıfına sözleşmeli subay statüsünde personel alınmaz.","Türk Silahlı Kuvvetlerinden ilişiği kesilenler yalnızca sözleşmeli astsubay olarak alınabilir.","Askerî hâkim sınıfına yalnızca sözleşmeli astsubay alınır.","Lisansüstü eğitimini tamamlayan herkes yaş şartı aranmaksızın sözleşmeli subay olabilir."],"dogru":1,"aciklama":"m.5: Askerî okullardan ve TSK'dan her ne sebeple olursa olsun ilişiği kesilen personel sözleşmeli alınmaz; ayrıca askerî hâkim sınıfına sözleşmeli subay statüsünde personel alınmaz.","kaynak":"m.5","zorluk":"orta"},
    {"id":"SOZLESMELI-S-008","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşmeli SUBAY adaylarında aranan öğrenim (eğitim) şartı aşağıdakilerden hangisidir?","siklar":["En az dört yıl süreli fakülte veya yüksekokul mezunu olmak","Genelkurmay Başkanlığınca tespit edilecek branşlarda meslek yüksekokulu mezunu olmak","Dört yıldan daha az süreli yüksek öğrenimi bitirmiş olmak","Herhangi bir ortaöğretim (lise) kurumundan mezun olmak","Lisansüstü öğrenimini tamamlamış olmak (zorunlu şart olarak)"],"dogru":0,"aciklama":"m.6: Sözleşmeli subay adaylarında 'en az dört yıl süreli fakülte veya yüksekokul mezunu olmak' öğrenim şartı aranır. Lisansüstü öğrenim zorunlu değildir; yalnızca yaş üst sınırını 27'den 32'ye çıkarır.","kaynak":"m.6/a","zorluk":"orta"},
    {"id":"SOZLESMELI-S-009","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre bir sözleşmeli subay, muvazzaf subaylığa geçiş başvurusunu en erken ______ fiili hizmet yılına başlamış olmak şartıyla yapabilir. Boşluğa hangisi gelmelidir?","siklar":["dördüncü","beşinci","altıncı","yedinci","sekizinci"],"dogru":3,"aciklama":"m.8/a-1: Muvazzaf subaylığa geçişte aday, yedinci fiili hizmet yılına başlamış (ve on ikinci fiili hizmet yılını henüz bitirmemiş) olmalıdır. Geçiş penceresinin açıldığı en erken yıl yedincidir.","kaynak":"m.8/a-1","zorluk":"orta"},
    {"id":"SOZLESMELI-S-010","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre muvazzaf astsubaylığa geçiş için aranan fiili hizmet süresi aralığı aşağıdakilerin hangisinde tam ve doğru olarak verilmiştir?","siklar":["Dördüncü fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak","Yedinci fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak","Üçüncü fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmiş olmak","Dördüncü fiili hizmet yılına başlamış veya onuncu fiili hizmet yılını bitirmemiş olmak","Beşinci fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak"],"dogru":0,"aciklama":"m.11/a-1: Muvazzaf astsubaylığa geçiş için dördüncü fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak gerekir.","kaynak":"m.11/a-1","zorluk":"orta"},
    {"id":"SOZLESMELI-S-011","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre muvazzaf subaylığa/astsubaylığa geçişte, başvurulan yıla kadar alınan sicil notları ortalamasının sicil tam notunun ______ veya daha fazlası olması şarttır. Boşluğa gelmesi gereken oran hangisidir?","siklar":["%55'i","%70'i","%90'ı","%85'i","%60'ı"],"dogru":2,"aciklama":"m.8/a-3 ve m.11/a-3 (Değişik: RG-1/10/2025-33034): Geçişte sicil ortalamasının sicil tam notunun %90 veya daha fazlası olması aranır.","kaynak":"m.8/a-3, m.11/a-3","zorluk":"orta"},
    {"id":"SOZLESMELI-S-012","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, muvazzaf subaylığa geçirilmeye engel hâllerle ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Hakkında adli ve/veya idari soruşturma veya kovuşturma yapılıyor olanlar muvazzaf subaylığa geçirilemez.","Görevden uzaklaştırma tedbiri uygulananlar, tedbir devam etse dahi geçişe hak kazanır.","Disiplin cezaları muvazzaf subaylığa geçişe hiçbir şekilde engel oluşturmaz.","Hâlen tutuklu bulunanlar, tutukluluk süresince geçiş başvurusunda bulunabilir.","Geçişe engel için en son bir yıl içinde en az on beş disiplin cezası puanı alınmış olması gerekir."],"dogru":0,"aciklama":"m.8/c-3: Hakkında adli ve/veya idari soruşturma ya da kovuşturma yapılıyor olanlar muvazzaf subaylığa geçirilemez. Ayrıca görevden uzaklaştırılan veya tutuklu olanlar (c-4) ile disiplin eşiklerini aşanlar (c-1: son 1 yılda 10 ceza puanı veya 4 ceza) da geçirilemez.","kaynak":"m.8/c","zorluk":"zor"},
    {"id":"SOZLESMELI-S-013","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşme sürelerinin azami sınırı kaç yıldır?","siklar":["3 yıl","5 yıl","6 yıl","12 yıl","9 yıl"],"dogru":4,"aciklama":"m.12: Sözleşme süreleri en az üç yıl olarak düzenlenir; azami sınır dokuz yıldır. Komutanlıklar bu aralığı aşamadan branşa göre süre belirleyebilir.","kaynak":"m.12","zorluk":"kolay"},
    {"id":"SOZLESMELI-S-014","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşmeli subay ve astsubayların rütbe bekleme süreleri hakkında, muvazzaflar için belirlenen süreleri içeren hangi kanun hükümleri uygulanır?","siklar":["211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanunu","926 sayılı Türk Silahlı Kuvvetleri Personel Kanunu","4678 sayılı Sözleşmeli Subay ve Astsubay İstihdamı Kanunu","3269 sayılı Uzman Erbaş Kanunu","5434 sayılı Türkiye Cumhuriyeti Emekli Sandığı Kanunu"],"dogru":1,"aciklama":"m.13: Rütbe bekleme sürelerinde, 926 sayılı TSK Personel Kanununda muvazzaf subay ve astsubaylar için belirlenen süreler uygulanır.","kaynak":"m.13","zorluk":"orta"},
    {"id":"SOZLESMELI-S-015","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşmesini yenilemek isteyenler, sözleşme süresinin sona erme tarihinden ne kadar önceden başlamak suretiyle dilekçe ile ilk amirine müracaat eder?","siklar":["1 yıl önceden","9 ay önceden","2 ay önceden","3 ay önceden","6 ay önceden"],"dogru":4,"aciklama":"m.14/a: Sözleşmesini yenilemek isteyenler, sona erme tarihinden 6 ay önceden başlamak suretiyle dilekçe ile ilk amirine müracaat eder.","kaynak":"m.14/a","zorluk":"orta"},
    {"id":"SOZLESMELI-S-016","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, her sözleşme süresinin sona erme tarihinden en az üç ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmazsa ne olur?","siklar":["Sözleşme kendiliğinden sona erer.","Sözleşme idarece resen bir yıl uzatılır.","Sözleşme bir sözleşme dönemi daha yenilenmiş sayılır.","Personele tazminat ödenerek sözleşme feshedilir.","Yenileme için yetkili makamdan onay beklenir."],"dogru":0,"aciklama":"m.14/d: Sona erme tarihinden en az 3 ay önce taraflar yenilemeye dair yazılı bildirimde bulunmazlarsa sözleşme kendiliğinden sona erer.","kaynak":"m.14/d","zorluk":"orta"},
    {"id":"SOZLESMELI-S-017","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, sözleşmeli subay/astsubay nasbedildikten sonra yabancı memleketlere 6 ay veya daha uzun süreli öğrenim, staj veya kurs için gidenlerin sözleşme süreleri, gidiş ve dönüş tarihleri arasında geçen sürenin iki katı kadar uzatılır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.14/c: Yurt dışına 6 ay veya daha uzun süreli öğrenim/staj/kurs için gidenlerin sözleşmeleri, gidiş-dönüş arasındaki sürenin iki katı kadar uzatılır.","kaynak":"m.14/c","zorluk":"orta"},
    {"id":"SOZLESMELI-S-018","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre sözleşmeli subay ve astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedebilirler. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.15: Sözleşmeli subay ve astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshEDEMEZLER. İfade bunun tersi olduğu için yanlıştır.","kaynak":"m.15","zorluk":"kolay"},
    {"id":"SOZLESMELI-S-019","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, sözleşmeli subay/astsubay adaylarının ön sözleşmeleri, askerî eğitimin ne kadarına çeşitli nedenlerle katılmamaları hâlinde feshedilebilir?","siklar":["Yarısına","Beşte birine","Dörtte birine","Üçte birine","Tamamına"],"dogru":3,"aciklama":"m.15: Ön sözleşmenin fesih sebeplerinden biri, askerî eğitimin üçte birine çeşitli nedenlerle katılmamaktır.","kaynak":"m.15/ç (ön sözleşme)","zorluk":"orta"},
    {"id":"SOZLESMELI-S-020","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, kendi kusurları olmaksızın idare tarafından sözleşmeleri yenilenmeyenlere; hizmet edilen süre kadar ve EN ÇOK kaç yıl ücretsiz muayene ve tedavi hizmeti verilmeye devam edilir?","siklar":["En çok 5 yıl","En çok 10 yıl","En çok 7 yıl","En çok 12 yıl","En çok 15 yıl"],"dogru":1,"aciklama":"m.22/a: İdare tarafından kusursuz olarak sözleşmesi yenilenmeyenlere, hizmet edilen süre kadar ve en çok 10 yıl ücretsiz muayene/tedavi sağlanır.","kaynak":"m.22/a","zorluk":"orta"},
    {"id":"SOZLESMELI-S-021","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, sözleşme süresi sonunda kendi istekleriyle sözleşmeleri yenilenmeyenlere; hizmet edilen sürenin yarısı kadar ve EN ÇOK kaç yıl ücretsiz muayene ve tedavi hizmeti verilir?","siklar":["En çok 10 yıl","En çok 3 yıl","En çok 2 yıl","En çok 1 yıl","En çok 5 yıl"],"dogru":4,"aciklama":"m.22/b: Sözleşme sonunda kendi istekleriyle yenilemeyenlere, hizmet edilen sürenin yarısı kadar ve en çok 5 yıl ücretsiz muayene/tedavi sağlanır.","kaynak":"m.22/b","zorluk":"orta"},
    {"id":"SOZLESMELI-S-022","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, Jandarma Genel Komutanlığına mensup sözleşmeli subay ve astsubayların mülki hizmete ilişkin suçlarında hangi kanunun ilgili hükümleri uygulanır?","siklar":["926 sayılı Türk Silahlı Kuvvetleri Personel Kanunu","211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanunu","2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu","5442 sayılı İl İdaresi Kanunu","4678 sayılı Sözleşmeli Subay ve Astsubay İstihdamı Kanunu"],"dogru":2,"aciklama":"m.26: J.Gen.K.'ya mensup sözleşmeli subay ve astsubayların mülki hizmete ilişkin suçlarında 2803 sayılı Kanunun ilgili hükümleri uygulanır.","kaynak":"m.26","zorluk":"orta"},
    {"id":"SOZLESMELI-S-023","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre ön sözleşme ve ön sözleşmeden sonraki ilk sözleşmeyi yapmaya yetkili makam aşağıdakilerden hangisidir?","siklar":["Kuvvet Komutanlıkları / J.Gen.K. / S.G.K. Tayin/Atama Daire Başkanı veya eşidi birim amiri","Genelkurmay Başkanı veya yetkilendireceği general/amiral","Kuvvet Komutanlıkları / J.Gen.K. / S.G.K. Personel Temin Merkezi Komutanı veya eşidi birim amiri","Milli Savunma Bakanı veya yetkili kıldığı makam","İlgili birlik komutanı veya garnizon komutanı"],"dogru":2,"aciklama":"m.31: Ön sözleşme ve ilk sözleşmeyi yapmaya yetkili makam, Kuvvet Komutanlıkları, J.Gen.K. ve S.G.K. Personel Temin Merkezi Komutanı veya eşidi birim amiridir.","kaynak":"m.31","zorluk":"orta"},
    {"id":"SOZLESMELI-S-024","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre müteakip (ilk sözleşmeden sonraki) sözleşmeleri yapmaya yetkili makam aşağıdakilerden hangisidir?","siklar":["Personel Temin Merkezi Komutanı veya eşidi birim amiri","Kuvvet Komutanı veya yetkilendireceği makam","Garnizon Komutanı veya eşidi birim amiri","Tayin/Atama Daire Başkanı veya eşidi birim amiri","Genelkurmay Personel Başkanı"],"dogru":3,"aciklama":"m.31: Müteakip sözleşmeleri yapmaya yetkili makam, Kuvvet Komutanlıkları, J.Gen.K. ve S.G.K. Tayin/Atama Daire Başkanı veya eşidi birim amiridir.","kaynak":"m.31","zorluk":"orta"},
    {"id":"SOZLESMELI-S-025","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, sözleşmeli subay/astsubayların nasıpları hangi tarihte olursa olsun, kademe ilerlemesi veya üst rütbeye yükselmelerine esas olacak nasıplarında kararname takvim yılının hangi tarihi itibar olunur?","siklar":["1 Ocak","30 Ağustos","1 Eylül","30 Ekim","Nasıp onayının fiilen çıktığı tarih"],"dogru":1,"aciklama":"m.32: Nasıp hangi tarihte olursa olsun, kademe ilerlemesi/üst rütbeye yükselmeye esas nasıpta kararname takvim yılının 30 Ağustos'u itibar olunur (sözleşme yenileme tarihinde ise ilk imza tarihi esastır).","kaynak":"m.32","zorluk":"orta"},
    {"id":"SOZLESMELI-S-026","soru":"Sözleşmeli Subay ve Astsubay Yönetmeliği'ne göre, müracaatları kabul edilen aday adaylarına ön sözleşme yapılmadan önce aşağıdakilerden hangisi UYGULANMAZ?","siklar":["Fiziki yetenek ve değerlendirme testi","Genel kültür ve meslek bilgisi sınavı","Yabancı dil sınavında en az 70 puan alma şartı","Mülakat","Tam teşekküllü askerî hastaneden 'Sözleşmeli Subay/Astsubay Olur' kararlı sağlık raporu alma"],"dogru":2,"aciklama":"m.30: Müracaatı kabul edilenler fiziki yetenek, değerlendirme testi, genel kültür ve meslek bilgisi ile mülakata tabi tutulur; başarılı olanlardan ilgili sağlık raporunu alanlarla ön sözleşme yapılır. Yabancı dil sınavında 70 puan şartı bu süreçte sayılmamıştır.","kaynak":"m.30","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-001","soru":"Sözleşmeli astsubay A, beş yıllık sözleşmesinin ikinci yılında, sivil bir şirkette daha iyi bir iş bulduğu için görevden ayrılmak istemekte ve ilk amirine 'sözleşmemi tek taraflı feshediyorum' dilekçesi vermektedir. Yönetmeliğe göre A'nın bu talebinin hukuki sonucu nedir?","siklar":["Sözleşme süresi sona ermeden sözleşmesini tek taraflı olarak feshedemeyeceğinden talebi sonuç doğurmaz.","Bitişe altı ay kala dilekçe verdiği için sözleşmesi feshedilir.","Bitişe üç ay kala bildirimde bulunduğu için sözleşmesi kendiliğinden sona erer.","Net maaşının iki katı tutarında tazminatını ödemesi şartıyla sözleşmesini tek taraflı feshedebilir.","İlk amirinin uygun görmesi hâlinde tek taraflı fesih gerçekleşir."],"dogru":0,"aciklama":"m.15: 'Sözleşmeli subay ve sözleşmeli astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedemezler.' Fesih yetkisi sayılı hâllerde yalnızca idarededir; personelin tek taraflı feshi mümkün değildir.","kaynak":"m.15","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-002","soru":"Sözleşmeli subay adayı B, ön sözleşme imzalayıp askerî eğitime başlamış; ancak çeşitli nedenlerle askerî eğitimin üçte birinden fazlasına katılmamıştır. Yönetmeliğe göre yetkili makam B hakkında ne yapabilir?","siklar":["B'nin ön sözleşmesi, askerî eğitimin üçte birine katılmaması nedeniyle süresinin bitiminden önce feshedilebilir.","B eğitimi tamamlamış sayılır ve doğrudan nasbedilir.","Ön sözleşme ancak eğitimin yarısına katılmama hâlinde feshedilebileceğinden işlem yapılamaz.","B doğrudan muvazzaf astsubaylığa geçirilir.","B ile yeni bir sözleşme yapılarak hizmet yükümlülüğü dokuz yıla çıkarılır."],"dogru":0,"aciklama":"m.15: Ön sözleşmenin fesih sebeplerinden biri 'askerî eğitimin üçte birine çeşitli nedenlerle katılmamak'tır. Aday henüz nasbedilmediğinden ön sözleşmesi bu nedenle feshedilebilir.","kaynak":"m.15/ç","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-003","soru":"Sözleşmeli subay (üsteğmen) A, beşinci fiili hizmet yılındadır ve muvazzaf subaylığa geçmek için başvurmak istemektedir. Sicil notu ortalaması sicil tam notunun %95'i olup hakkında hiçbir disiplin/soruşturma engeli bulunmamaktadır. Yönetmeliğe göre A'nın başvurusunun süre yönünden durumu nedir?","siklar":["Henüz yedinci fiili hizmet yılına başlamadığından süre şartını taşımaz, başvuramaz.","Sicili %90'ın üzerinde olduğundan süreye bakılmaksızın hemen geçirilir.","Dördüncü fiili hizmet yılını doldurduğundan muvazzaf subaylığa geçiş için uygundur.","On ikinci fiili hizmet yılını bitirdiği için süre geçmiştir.","Üsteğmen rütbesinde bulunması nedeniyle geçişe başvuramaz."],"dogru":0,"aciklama":"m.8/a-1: Muvazzaf subaylığa geçişte 'yedinci fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak' gerekir. A henüz 5. yılda olduğundan pencere açılmamıştır.","kaynak":"m.8/a-1","zorluk":"zor"},
    {"id":"SOZLESMELI-OO-004","soru":"Sözleşmeli astsubay C, dördüncü fiili hizmet yılına yeni başlamıştır; sicil notu ortalaması sicil tam notunun %91'i, nitelik belgesi olumlu, hakkında disiplin/soruşturma engeli yok ve mesleki sınavda başarılıdır. Yönetmeliğe göre C'nin muvazzaf astsubaylığa geçiş başvurusu süre yönünden uygun mudur?","siklar":["Hayır; astsubaylar da en erken yedinci fiili hizmet yılında başvurabilir.","Hayır; en az beşinci fiili hizmet yılı doldurulmalıdır.","Evet; dördüncü fiili hizmet yılına başlamış ve on ikinci yılı bitirmemiş olduğundan süre şartını taşır.","Hayır; sicil ortalaması %90'ın altında olduğundan geçemez.","Evet; ancak yalnızca on ikinci fiili hizmet yılını bitirmiş olması şartıyla."],"dogru":2,"aciklama":"m.11/a-1: 'Dördüncü fiili hizmet yılına başlamış veya on ikinci fiili hizmet yılını bitirmemiş olmak'; m.11/a-3: sicil ortalaması sicil tam notunun %90 veya daha fazlası. C bu iki şartı da taşır.","kaynak":"m.11/a-1, m.11/a-3","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-005","soru":"Sözleşmeli subay D, dokuzuncu fiili hizmet yılındadır; sicil ortalaması %93 ve mesleki sınavda başarılıdır. Ancak başvuru tarihinde hakkında bir idari soruşturma devam etmekte ve ayrıca görevden uzaklaştırma tedbiri uygulanmaktadır. Yönetmeliğe göre D'nin muvazzaf subaylığa geçişi bakımından doğru değerlendirme hangisidir?","siklar":["Hakkında soruşturma yapılıyor olması ve görevden uzaklaştırma tedbiri uygulanması nedeniyle muvazzaf subaylığa geçirilemez.","Sicili ve sınavı yeterli olduğundan engel hâlleri dikkate alınmaz, geçirilir.","Yalnızca tutukluluk geçişe engeldir; görevden uzaklaştırma engel sayılmaz.","Soruşturma sonuçlanana kadar geçirilir, beraat etmezse işlem geri alınır.","Görevden uzaklaştırma tedbiri yalnızca sicil notunu düşürür; geçişe engel değildir."],"dogru":0,"aciklama":"m.8/c-3: hakkında adli ve/veya idari soruşturma ya da kovuşturma yapılıyor olanlar; m.8/c-4: görevden uzaklaştırma tedbiri uygulanan veya tutuklu bulunanlar muvazzaf subaylığa geçirilemez. D her iki engeli de taşır.","kaynak":"m.8/c-3, m.8/c-4","zorluk":"zor"},
    {"id":"SOZLESMELI-OO-006","soru":"Sözleşmeli astsubay E, mevcut sözleşmesini yenilemek istemektedir. Sözleşmesinin sona erme tarihi gelecek yılın 30 Haziran'ıdır. Yönetmeliğe göre E, yenileme için ne zamandan başlamak suretiyle ve nereye müracaat etmelidir?","siklar":["Sona ermeden üç ay önce başlayarak yetkili komutana sözlü olarak.","Sona ermeden altı ay önceden başlamak suretiyle dilekçe ile ilk amirine.","Sona ermeden bir yıl önceden başlayarak Tayin/Atama Daire Başkanlığına.","Sona erme tarihinde dilekçe ile Personel Temin Merkezi Komutanlığına.","Sona ermeden iki ay önce başlayarak ilk amirine."],"dogru":1,"aciklama":"m.14/a: Sözleşmesini yenilemek isteyenler, sona erme tarihinden 6 ay önceden başlamak suretiyle dilekçe ile ilk amirine müracaat eder.","kaynak":"m.14/a","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-007","soru":"Sözleşmeli subay F, nasbedildikten sonra yabancı bir ülkeye mesleki kurs için gönderilmiş; gidiş ve dönüş tarihleri arasında toplam 8 ay geçmiştir. Yönetmeliğe göre F'nin sözleşme süresine bu nedenle ne kadar ekleme yapılır?","siklar":["4 ay (geçen sürenin yarısı kadar)","8 ay (geçen sürenin kendisi kadar)","16 ay (geçen sürenin iki katı kadar)","Hiçbir ekleme yapılmaz; uzatma yalnızca altı aydan kısa süreler için geçerlidir.","24 ay (geçen sürenin üç katı kadar)"],"dogru":2,"aciklama":"m.14/c: Yabancı memleketlere 6 ay veya daha uzun süreli öğrenim/staj/kurs için gidenlerin sözleşmeleri, gidiş ve dönüş tarihleri arasında geçen sürenin iki katı kadar uzatılır. 8 ay × 2 = 16 ay.","kaynak":"m.14/c","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-008","soru":"Sözleşmeli astsubay G, kendi kusuru olmaksızın idare tarafından sözleşmesi yenilenmediği için 8 yıl hizmet ettikten sonra ayrılmıştır. Yönetmeliğe göre G'ye ayrıldıktan sonra ne kadar süreyle ücretsiz muayene ve tedavi hizmeti verilmeye devam edilir?","siklar":["Hizmet ettiği sürenin yarısı kadar ve en çok 5 yıl (4 yıl).","Hizmet ettiği süre kadar ve en çok 10 yılı geçmemek üzere (8 yıl).","Süreden bağımsız olarak sabit 10 yıl.","Yalnızca 12 ay, net maaşının üçte ikisi ödenerek.","Ücretsiz sağlık hakkı doğmaz; kendi imkânlarıyla tedavi olur."],"dogru":1,"aciklama":"m.22/a: Kendi kusurları olmaksızın idare tarafından sözleşmeleri yenilenmeyenlere, hizmet edilen süre kadar ve en çok 10 yılı geçmemek üzere ücretsiz muayene/tedavi sağlanır. 8 yıl hizmet → 8 yıl.","kaynak":"m.22/a","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-009","soru":"Jandarma Genel Komutanlığına mensup sözleşmeli astsubay H, mülki (kolluk) hizmetine ilişkin bir suç işlediği iddiasıyla işleme tabi tutulmaktadır. Yönetmeliğe göre H'nin bu mülki hizmete ilişkin suçunda hangi kanunun ilgili hükümleri uygulanır?","siklar":["926 sayılı Türk Silahlı Kuvvetleri Personel Kanunu","211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanunu","2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu","4678 sayılı Sözleşmeli Subay ve Astsubay İstihdamı Kanunu","657 sayılı Devlet Memurları Kanunu"],"dogru":2,"aciklama":"m.26: J.Gen.K.'ya mensup sözleşmeli subay ve astsubayların mülki hizmete ilişkin suçlarında 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun ilgili hükümleri uygulanır.","kaynak":"m.26","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-010","soru":"Aday adayı sürecini tamamlayan, testleri geçen ve 'Sözleşmeli Astsubay Olur' sağlık raporunu alan kişiyle önce ÖN SÖZLEŞME, ardından onu izleyen İLK SÖZLEŞME yapılacaktır. Yönetmeliğe göre bu ön sözleşme ve ilk sözleşmeyi yapmaya yetkili makam aşağıdakilerden hangisidir?","siklar":["Tayin/Atama Daire Başkanı veya eşidi birim amiri","Personel Temin Merkezi Komutanı veya eşidi birim amiri","İlgili kıta (birlik) komutanı","Genelkurmay Personel Başkanı","Milli Savunma Bakanı"],"dogru":1,"aciklama":"m.31: Ön sözleşme ve ön sözleşmeden sonraki ilk sözleşmeyi yapmaya yetkili makam, kuvvet komutanlıkları, J.Gen.K. ve S.G.K. Personel Temin Merkezi Komutanı veya eşidi birim amiridir.","kaynak":"m.31","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-011","soru":"Sözleşmeli subay I'nın subaylığa nasıp onayı 14 Kasım tarihinde çıkmıştır. Yönetmeliğe göre I'nın kademe ilerlemesi veya üst rütbeye yükselmesine esas olacak nasbında, kararname takvim yılının hangi tarihi itibar olunur?","siklar":["Nasıp onayının fiilen çıktığı 14 Kasım","Takip eden takvim yılının 1 Ocak'ı","Kararname takvim yılının 30 Ağustos'u","1 Eylül","İlk sözleşmeyi imzaladığı tarih"],"dogru":2,"aciklama":"m.32: Nasıplar hangi tarihte olursa olsun, kademe ilerlemesi veya üst rütbeye yükselmeye esas nasıplarında kararname takvim yılının 30 Ağustos'u itibar olunur.","kaynak":"m.32","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-012","soru":"J, daha önce bir askerî okuldan ilişiği kesilmiş bir kişidir. Aradan birkaç yıl geçtikten sonra sözleşmeli subay olmak için müracaat eder; yaş ve öğrenim şartlarını tam olarak taşımaktadır. Yönetmeliğe göre J'nin durumu nedir?","siklar":["Yaş ve öğrenim şartlarını taşıdığından sözleşmeli subay olarak alınabilir.","Aradan beş yıl geçtiği için engeli kalkmıştır, alınabilir.","Askerî okullardan ilişiği kesilenler sözleşmeli subay/astsubay olarak alınmadığından müracaatı kabul edilmez.","Yalnızca sözleşmeli astsubay olarak alınabilir.","Lisansüstü eğitimini tamamlaması hâlinde alınabilir."],"dogru":2,"aciklama":"m.5: Askerî okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişikleri kesilen personel, sözleşmeli subay veya sözleşmeli astsubay olarak alınmaz. Bu mutlak bir engeldir.","kaynak":"m.5","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-013","soru":"Bir Kuvvet Komutanlığı, ihtiyaç duyduğu bir branş için çıkaracağı yönergede sözleşmeli astsubaylarla 11 yıllık sözleşme yapılmasını öngörmek istemektedir. Yönetmeliğe göre bu mümkün müdür?","siklar":["Evet; komutanlıklar branşa göre süreyi serbestçe belirleyebilir.","Hayır; sözleşme sürelerinin azami sınırı dokuz yıl olduğundan bu aralık aşılamaz.","Evet; üst sınır yalnızca subaylar için dokuz yıldır.","Hayır; azami sınır on iki yıl olduğundan 11 yıl yapılabilir ama 12 yıl yapılamaz.","Evet; muvazzaflığa geçiş penceresi 12 yıl olduğundan 11 yıllık sözleşme geçerlidir."],"dogru":1,"aciklama":"m.12: Sözleşme süreleri en az üç yıl olarak düzenlenir; azami sınır dokuz yıldır. Komutanlıklar süreleri azami ve asgari sınırları aşmamak kaydıyla belirleyebilir; 11 yıl bu aralığı aşar.","kaynak":"m.12","zorluk":"orta"},
    {"id":"SOZLESMELI-OO-014","soru":"Sözleşmeli subay K, üst rütbeye terfi şartlarının tümünü taşımaktadır; ancak üst rütbede kadro açığı bulunmadığı için terfi ettirilememektedir. Yönetmeliğe göre K hakkında nasıl bir işlem yapılır?","siklar":["Sözleşmesi kendiliğinden sona erer.","Terfi şartlarını taşıdığından kadro açığına bakılmaksızın üst rütbeye yükseltilir.","Terfi şartlarını haiz olmak kaydıyla, sözleşme süresinin sonuna kadar derece ilerlemesi yapar.","Bir üst dereceye yükseltilmek üzere muvazzaf subaylığa geçirilir.","Rütbe bekleme süresi iki katına çıkarılır."],"dogru":2,"aciklama":"m.13: Üst rütbede kadro açığı bulunmadığı için terfi edemeyenler, terfi şartlarını haiz olmak kaydıyla sözleşme süresinin sonuna kadar derece ilerlemesi yaparlar.","kaynak":"m.13","zorluk":"orta"},
  ],
  17: [
    {"id":"JANDYON-S-001","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği, aşağıdaki hangi kanunun ilgili maddesine dayanılarak hazırlanmıştır?","siklar":["2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 24 üncü maddesine","2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu'nun 24 üncü maddesine","5271 sayılı Ceza Muhakemesi Kanunu'nun 24 üncü maddesine","5442 sayılı İl İdaresi Kanunu'nun 11 inci maddesine","2941 sayılı Seferberlik ve Savaş Hali Kanunu'nun 24 üncü maddesine"],"dogru":1,"aciklama":"m.2/1: Yönetmelik 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24 üncü maddesine dayanılarak hazırlanmıştır.","kaynak":"Yön. m.2","zorluk":"kolay"},
    {"id":"JANDYON-S-002","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ndeki tanımlara göre, 'Devlete, topluma, kişilere, mal ve eşyalara yönelik tehlike, kaza ve sabotajları önlemek için alınan hukuka uygun önlemlerin tümünü ve bu önlemlerin alınmış bulunduğu hali' ifade eden kavram aşağıdakilerden hangisidir?","siklar":["Asayiş","Kamu düzeni","Emniyet","Genel sağlık","Huzur ve sükun"],"dogru":2,"aciklama":"m.3/d: Emniyet, tehlike-kaza-sabotajları önlemek için alınan önlemlerin tümü ve alınmış bulunduğu hâldir (alınan önlem hâli). Asayiş ise bu önlemler sonucu oluşan, kamuda yerleşik dirlik-düzen inancıdır (sağlanan sonuç hâli).","kaynak":"Yön. m.3/d, m.3/a","zorluk":"orta"},
    {"id":"JANDYON-S-003","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, aşağıdakilerden hangisi 'genel kolluk' kapsamında yer almaz?","siklar":["Polis","Jandarma","Orman muhafaza memuru","Sahil güvenlik","Bakanlığa bağlı olma ve silah kullanma yetkisini haiz olma niteliği"],"dogru":2,"aciklama":"m.3/e: Genel kolluk; kamu düzeninin korunmasını sağlayan, silah kullanma yetkisini haiz Bakanlığa bağlı jandarma, sahil güvenlik ve polistir. Orman muhafaza memuru özel kanunla kurulan ve kendi görev alanında güvenlik sağlayan bir özel kolluk türüdür (m.3/m).","kaynak":"Yön. m.3/e","zorluk":"orta"},
    {"id":"JANDYON-S-004","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ndeki tanıma göre mülki amir; illerde ............, ilçelerde ............ ifade eder.","siklar":["vali — kaymakam","vali yardımcısı — kaymakam","il jandarma komutanı — ilçe jandarma komutanı","garnizon komutanı — kaymakam","vali — vali yardımcısı"],"dogru":0,"aciklama":"m.3/l: Mülki amir, illerde vali, ilçelerde kaymakamdır.","kaynak":"Yön. m.3/l","zorluk":"kolay"},
    {"id":"JANDYON-S-005","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, Jandarma Genel Komutanlığı Bakanlığa bağlıdır ve Jandarma Genel Komutanı Bakana karşı sorumludur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.4/1: Jandarma Genel Komutanlığı Bakanlığa bağlıdır; Jandarma Genel Komutanı, Bakana karşı sorumludur.","kaynak":"Yön. m.4/1","zorluk":"kolay"},
    {"id":"JANDYON-S-006","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, karakolların sorumluluk bölgeleri ile konuş yerlerinin belirlenmesi konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Sorumluluk bölgeleri de konuş yerleri de Bakan onayı ile belirlenir.","Sorumluluk bölgeleri il jandarma komutanının önerisi üzerine valinin onayı, konuş yerleri ise Bakan onayı ile belirlenir.","Sorumluluk bölgeleri Bakan onayı, konuş yerleri il jandarma komutanının önerisi üzerine valinin onayı ile belirlenir.","Sorumluluk bölgeleri de konuş yerleri de valinin onayı ile belirlenir.","Sorumluluk bölgeleri kaymakamın, konuş yerleri valinin onayı ile belirlenir."],"dogru":1,"aciklama":"m.6/7: Karakolların sorumluluk bölgeleri il jandarma komutanının önerisi üzerine valinin onayı, karakolların konuş yerleri ise Bakan onayı ile belirlenir.","kaynak":"Yön. m.6/7","zorluk":"zor"},
    {"id":"JANDYON-S-007","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre jandarmanın görev ve sorumluluk alanı ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Jandarmanın görev ve sorumluluk alanı, genel olarak il ve ilçe belediye sınırları dışında kalan ya da polis ve sahil güvenlik teşkilatı bulunmayan yerlerdir.","Belediye sınırları içinde olmakla birlikte hizmet gerekleri bakımından uygun görülen yerler, jandarmanın görev ve sorumluluk alanı olarak belirlenebilir.","Bakanın kararıyla bir il veya ilçenin tamamı polis ya da jandarma görev ve sorumluluk alanı olarak belirlenebilir.","Jandarmanın görev ve sorumluluk alanı, polis ve sahil güvenlik teşkilatının görev alanının dışıdır.","Bir il veya ilçenin tamamının tek bir kolluğun alanı olarak belirlenmesine yalnızca sulh ceza hâkimi karar verebilir."],"dogru":4,"aciklama":"m.7/1: Bir il veya ilçenin tamamının polis ya da jandarma alanı olarak belirlenmesi Bakanın kararıyla olur; sulh ceza hâkimi bu konuda yetkili değildir. Diğer ifadeler madde metnine uygundur.","kaynak":"Yön. m.7/1","zorluk":"orta"},
    {"id":"JANDYON-S-008","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'nin 8 inci maddesine göre, aşağıdakilerden hangisi jandarmanın 'mülki görevleri' arasında yer almaz?","siklar":["Emniyet ve asayiş ile kamu düzenini sağlamak, korumak ve kollamak","İşlenmiş suçlarla ilgili olarak kanunlarda belirtilen işlemleri yapmak ve adli hizmetleri yerine getirmek","Kaçakçılığı men, takip ve tahkik etmek","Ceza infaz kurumlarının dış korumalarını sağlamak","Trafik hizmetlerini yürütmek ve arama kurtarma görevlerini yapmak"],"dogru":1,"aciklama":"m.8/1: B seçeneği aslında 'adli görevler' (m.8/1-b) tanımıdır. A, C, D, E ise mülki görevler (m.8/1-a) arasında sayılmıştır.","kaynak":"Yön. m.8/1-a","zorluk":"orta"},
    {"id":"JANDYON-S-009","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, illerde jandarmaya askeri görev verilmesinde aşağıdaki usullerden hangisi uygulanır?","siklar":["Garnizon komutanının talebi ve valinin onayıyla verilir.","Doğrudan garnizon komutanının emriyle verilir.","Vali talebi ve Bakan onayıyla verilir.","Kaymakamın talebi ve valinin onayıyla verilir.","Yalnızca Bakanlar Kurulu kararıyla verilir."],"dogru":0,"aciklama":"m.8/1-c: Genelkurmay Başkanının talebi üzerine Bakanın, illerde ise garnizon komutanının talebi ve valinin onayıyla askeri görev verilir.","kaynak":"Yön. m.8/1-c","zorluk":"zor"},
    {"id":"JANDYON-S-010","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre; polis teşkilatı kurulmamış olması nedeniyle jandarmanın sorumluluk alanı dışındaki bir yerde olaya el koyması durumunda, jandarmanın görev yaptığı o yer jandarmanın görev alanı sayılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.9/1: Polis teşkilatı kurulmamış olması veya özel kolluk alanındaki/yokluğundaki ilgili ihlal ya da suç nedeniyle jandarmanın görevlendirilmesi ya da kendiliğinden el koyması mümkündür; bu hâllerde görev yaptığı yer onun görev alanı sayılır.","kaynak":"Yön. m.9/1","zorluk":"orta"},
    {"id":"JANDYON-S-011","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, il ve ilçelerdeki jandarma ile polis sorumluluk alanlarının sınırları ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Sınırlar; ilçelerde kaymakam, illerde vali veya görevlendireceği vali yardımcısı başkanlığında jandarma ve emniyet temsilcilerinin katılacağı bir komisyon tarafından belirlenir.","Belediye kurulması, kaldırılması ya da sınırlarda değişiklik olması hâlinde, değişikliğin yürürlüğe girdiği tarihten itibaren en geç üç ay içinde sorumluluk alanları yeniden düzenlenir.","Komisyon tarafından alınan kararlar İçişleri Bakanının onayıyla yürürlüğe girer.","Sorumluluk alanlarının sınırlarının belirlenmesinde kolluk birimleri arasındaki anlaşmazlıklar, mülki amir tarafından kesin olarak çözümlenir.","Komisyon tarafından alınan kararlar, hiçbir onaya tabi olmaksızın alındığı anda kesinleşir ve yürürlüğe girer."],"dogru":4,"aciklama":"m.10/3: Komisyon kararları İçişleri Bakanının onayıyla yürürlüğe girer; onaysız kesinleşmez. C seçeneği doğru, E ise onu çürüten sahte ifadedir.","kaynak":"Yön. m.10/2-3","zorluk":"zor"},
    {"id":"JANDYON-S-012","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'nin 11 inci maddesine göre jandarma; halkın ............ korur.","siklar":["yalnızca malını","can, ırz ve malını","yalnızca canını ve malını","can ve özgürlüğünü","mal ve mülkiyet hakkını"],"dogru":1,"aciklama":"m.11/1-a: Jandarma halkın can, ırz ve malını korur.","kaynak":"Yön. m.11/1-a","zorluk":"kolay"},
    {"id":"JANDYON-S-013","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, ceza infaz kurumlarının dış korunması jandarmaya ait olmakla birlikte, jandarma gerektiğinde kurum içindeki infaz koruma memurluğu görevlerinde de kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.24/3: Jandarma hiçbir şekilde ceza infaz kurumlarının iç işlerinde ve infaz koruma memurluğu görevlerinde kullanılamaz. Dış koruma jandarmaya aittir (m.24/1), iç işler yasaktır.","kaynak":"Yön. m.24/1-3","zorluk":"orta"},
    {"id":"JANDYON-S-014","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, tutuklu ve hükümlülerin sevk ve nakli ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Sevk ve nakillerin, bu iş için ayrılmış olan ceza infaz kurumu araçlarıyla yapılması esastır.","Jandarmaya ait hizmet araçları sevklerde kullanılmaz.","İştirak hâlinde suç işlemiş olanlar ile önemli sayılacak derecede yakınlığı olanlar dışında, erkek ve kadın tutuklu ya da hükümlüler birlikte sevk edilemez.","Sevk ve nakillerde, gidilecek yere gece varılacak biçimde hareket edilmesi esastır.","Sevk edilen tutuklu ve hükümlünün kadın olması durumunda, kadın ceza infaz koruma görevlisi verilir."],"dogru":3,"aciklama":"m.33/1: Sevk ve nakillerde gidilecek yere GÜNDÜZ varılacak biçimde hareket edilir. A (m.27), B (m.27/3), C (m.29/1), E (m.29/2) metne uygundur.","kaynak":"Yön. m.27, m.29, m.33","zorluk":"zor"},
    {"id":"JANDYON-S-015","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, gözaltına alınan şahısların adli makamlar önüne çıkarılıncaya kadarki yeme, içme ve nakil masrafları nasıl karşılanır?","siklar":["Cumhuriyet Başsavcılığının takdir edeceği ödenekten karşılanır.","Şahsın kendisi tarafından peşin olarak karşılanır.","Jandarma Genel Komutanlığı bütçesinden ödenir.","İçişleri Bakanlığı örtülü ödeneğinden karşılanır.","İlgili valilik bütçesinden karşılanır."],"dogru":2,"aciklama":"m.40/1: Gözaltına alınanların adli makamlar önüne çıkarılıncaya kadarki yeme-içme-nakil masrafları ile JGK taşıtlarıyla sevkte yakıt vb. masraflar Jandarma Genel Komutanlığı bütçesinden ödenir.","kaynak":"Yön. m.40/1","zorluk":"orta"},
    {"id":"JANDYON-S-016","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre jandarmanın askeri görevleri ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Seferberlik ve savaş hâllerinde Bakanlar Kurulu kararıyla belirlenecek bölümleriyle kuvvet komutanlıkları emrine girer.","Kuvvet komutanlıkları emrine giren bölüm dışında kalan bölümüyle normal görevlerine devam eder.","Seferberlik ve savaş hâlinde 2941 sayılı Seferberlik ve Savaş Hali Kanunu ile verilen görevleri yapar.","Genelkurmay Başkanlığının talebi üzerine Bakanın verdiği askeri görevleri yapar.","İllerde garnizon komutanının talebi üzerine, herhangi bir onaya gerek olmaksızın doğrudan askeri görev icra eder."],"dogru":4,"aciklama":"m.41/2: İllerde garnizon komutanının talep etmesi hâlinde askeri görev VALİNİN ONAYIYLA verilir; onaysız değildir. A, B, C, D madde metnine uygundur.","kaynak":"Yön. m.41/1-2","zorluk":"orta"},
    {"id":"JANDYON-S-017","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, jandarmanın yetkileri ile emir-itaat ilişkisi hakkında aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Jandarma, mülki ve adli görevlerini yerine getirirken polisin sahip olduğu yetki ve sorumluluklara sahiptir.","Jandarma, amirinden aldığı emri Anayasa, kanun, tüzük ve yönetmelik hükümlerine aykırı görürse yerine getirmez ve bu aykırılığı emri verene bildirir.","Amir, kanuna aykırı görülen emrinde ısrar eder ve emrini yazılı olarak tekrar ederse emir yerine getirilir; bu hâlde emri yerine getiren sorumlu olmaz.","Konusu suç teşkil eden emir, amir tarafından yazılı olarak tekrar edilmesi hâlinde yerine getirilir.","Konusu suç teşkil eden emri yerine getirenler sorumluluktan kurtulamaz."],"dogru":3,"aciklama":"m.42/2: Konusu suç teşkil eden emir HİÇBİR SURETLE yerine getirilmez; yazılı tekrar bunu meşrulaştırmaz. Yazılı tekrarla yerine getirilen yalnızca 'kanuna aykırı (ama suç oluşturmayan)' emirdir.","kaynak":"Yön. m.42/1-2","zorluk":"zor"},
    {"id":"JANDYON-S-018","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre; jandarma, amirinden aldığı emri mevzuata aykırı görüp bildirdiği hâlde amir ısrar eder ve emrini ............ tekrar ederse emir yerine getirilir ve bu hâlde emri yerine getiren ............ .","siklar":["sözlü olarak — sorumlu olur","yazılı olarak — sorumlu olmaz","yazılı olarak — yine de sorumlu olur","sözlü olarak — sorumlu olmaz","bir üst amire onaylatarak — sorumlu olmaz"],"dogru":1,"aciklama":"m.42/2: Amir emrinde ısrar eder ve yazılı olarak tekrar ederse emir yerine getirilir; bu hâlde emri yerine getiren sorumlu olmaz (sorumluluk emri verene geçer).","kaynak":"Yön. m.42/2","zorluk":"orta"},
    {"id":"JANDYON-S-019","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'nde sayılan acil hâllerde (örneğin can, ırz veya mal emniyetini korumak için) yetkili amir tarafından verilen sözlü emirler derhal yerine getirilir, bu emirlerin yazılı olarak verilmesi istenemez ve emrin yerine getirilmesinden doğabilecek sorumluluk emri verene aittir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.42/2: Sayılan hâllerde sözlü emir derhal yerine getirilir, yazılı verilmesi istenemez ve sorumluluk emri verene aittir.","kaynak":"Yön. m.42/2","zorluk":"orta"},
    {"id":"JANDYON-S-020","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre jandarma, kişileri ve araçları belirli amaçlarla durdurabilir. Buna göre, aşağıdakilerden hangisi jandarmanın durdurma yetkisini kullanabileceği amaçlar arasında yer almaz?","siklar":["Bir suç veya kabahatin işlenmesini önlemek","Suç işlendikten sonra kaçan faillerin yakalanmasını sağlamak ve işlenen suç veya kabahatlerin faillerinin kimliklerini tespit etmek","Hakkında yakalama emri ya da zorla getirme kararı verilmiş olan kişileri tespit etmek","Kişilerin hayatı, vücut bütünlüğü veya malvarlığı bakımından ya da topluma yönelik mevcut veya muhtemel bir tehlikeyi önlemek","Kesinleşmiş idari para cezalarını durdurulan kişiden yerinde tahsil etmek"],"dogru":4,"aciklama":"m.46/1: Durdurma yetkisi; (a) suç/kabahat işlenmesini önlemek, (b) kaçan failleri yakalamak ve faillerin kimliklerini tespit etmek, (c) yakalama emri ya da zorla getirme kararı verilmiş kişileri tespit etmek, (ç) kişilerin hayatı/vücut bütünlüğü/malvarlığı ya da topluma yönelik mevcut veya muhtemel tehlikeyi önlemek amaçlarıyla kullanılır. İdari para cezasını yerinde tahsil etmek bir durdurma amacı değildir.","kaynak":"Yön. m.46/1","zorluk":"orta"},
    {"id":"JANDYON-S-021","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, durdurma kapsamında el ile dıştan kontrolü aşan üst, eşya ve araç araması için kolluk amirinin verdiği karar, en geç ne kadar süre içinde görevli hâkimin onayına sunulur?","siklar":["Kırksekiz saat","Oniki saat","Yirmidört saat","Otuzaltı saat","Altı saat"],"dogru":2,"aciklama":"m.46/6: Kolluk amirinin kararı yirmidört saat içinde görevli hâkimin onayına sunulur.","kaynak":"Yön. m.46/6","zorluk":"orta"},
    {"id":"JANDYON-S-022","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre önleme araması ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Önleme araması, usulüne göre verilmiş sulh ceza hâkiminin kararıyla yapılabilir.","Gecikmesinde sakınca bulunan hâllerde önleme araması mülki amirin vereceği yazılı emirle yapılabilir.","Konutta, yerleşim yerinde ve kamuya açık olmayan işyerlerinde ve eklentilerinde de gerekli görülmesi hâlinde önleme araması yapılabilir.","Halkın topluca bulunduğu veya toplanabileceği yerlerde, umumi veya umuma açık yerlerde önleme araması yapılabilir.","Her türlü toplu taşıma araçları ile seyir hâlindeki taşıtlarda önleme araması yapılabilir."],"dogru":2,"aciklama":"m.47/5: Konutta, yerleşim yerinde ve kamuya açık olmayan işyerlerinde ve eklentilerinde önleme araması YAPILAMAZ. A, B (m.47/1), D ve E (m.47/4) doğrudur.","kaynak":"Yön. m.47/1, m.47/5","zorluk":"zor"},
    {"id":"JANDYON-S-023","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre; spor karşılaşması, miting, konser, festival, toplantı ve gösteri yürüyüşünün düzenlendiği veya aniden toplulukların oluştuğu hâllerde önleme araması bakımından ............ var sayılır.","siklar":["gecikmesinde sakınca bulunan hâl","olağanüstü hâl","genel afet hâli","sokağa çıkma yasağı","idari gözetim hâli"],"dogru":0,"aciklama":"m.47/6: Spor karşılaşması, miting, konser, festival, toplantı ve gösteri yürüyüşünün düzenlendiği veya aniden toplulukların oluştuğu hâllerde gecikmesinde sakınca bulunan hâl var sayılır. Bu durumda önleme araması, sulh ceza hâkimi kararı beklenmeksizin mülki amirin yazılı emriyle yapılabilir.","kaynak":"Yön. m.47/6","zorluk":"orta"},
    {"id":"JANDYON-S-024","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre jandarma; imdat istenmesi veya yangın, su baskını ve boğulma gibi büyük tehlikelerden kişileri kurtarmak amacıyla ya da bir suçun işlenmesine veya işlenmekte olan bir suçun devamına engel olmak için konutlara, işyerlerine ve eklentilerine girebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.48/1: Sayılan iki acil hâlde (can kurtarma; işlenen suça engel olma) jandarma konut, işyeri ve eklentilerine girebilir.","kaynak":"Yön. m.48/1","zorluk":"kolay"},
    {"id":"JANDYON-S-025","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, jandarma amirlerinin sorumlu oldukları makamlarla ilgili aşağıdaki eşleştirmelerden hangisi yanlıştır?","siklar":["Jandarma Genel Komutanı — Bakana karşı sorumludur.","Jandarma bölge komutanı — konuşlu olduğu ilin valisine karşı sorumludur.","İlçe jandarma komutanı — doğrudan Jandarma Genel Komutanına karşı sorumludur.","İl jandarma komutanı, il jandarma teşkilatının komutanıdır.","Jandarma karakol komutanı, karakolun komutanıdır."],"dogru":2,"aciklama":"m.56 ve m.58/2: İl ve ilçe jandarma komutanları mülki amirlere (ilçede kaymakama) bağlı ve sorumlu olarak görev yapar; ilçe komutanı doğrudan Genel Komutana karşı sorumlu değildir. A (m.52/3), B (m.54/2), D (m.55/1), E (m.57/1) doğrudur.","kaynak":"Yön. m.52-57","zorluk":"zor"},
    {"id":"JANDYON-S-026","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, jandarma komutanlarına ve diğer jandarma personeline mevzuata uygun olarak doğrudan emir verme yetkisine kimler sahiptir?","siklar":["Mülki amirler ile adli makamlar","Yalnızca Jandarma Genel Komutanı","Belediye başkanları ile il genel meclisi","Bütün kamu kurum ve kuruluşlarının amirleri","Yalnızca garnizon komutanları"],"dogru":0,"aciklama":"m.58/3: Mülki amirler ile adli makamlar mevzuata uygun olarak jandarmaya doğrudan emir verme yetkisine sahiptir. Diğer makamlar görev verilmesini istedikleri konunun kanuni dayanağını belirterek o yerin mülki amirine başvurur.","kaynak":"Yön. m.58/3","zorluk":"orta"},
    {"id":"JANDYON-S-027","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, jandarma sorumluluk alanında bir suçla karşılaşan polis veya sahil güvenlik, olaya müdahale edip jandarmaya haber verir; jandarma gelinceye kadar olay yerinde soruşturma yapamaz, durumu olduğu gibi koruyarak delillerin kaybolmaması için gereken önlemleri alır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.65/1: Jandarma alanında suçla karşılaşan sahil güvenlik veya polis müdahale eder, haber verir; jandarma gelene kadar soruşturma yapamaz, olay yerini koruyup delilleri muhafaza eder.","kaynak":"Yön. m.65/1","zorluk":"orta"},
    {"id":"JANDYON-S-028","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, yakalanarak muhafaza altına alınan yoklama kaçağı ve bakaya yükümlüler, vakit geçirmeksizin ve en geç ne kadar süre içinde nereye getirilir?","siklar":["En geç kırksekiz saat içinde en yakın askerlik şubesine","En geç yirmidört saat içinde en yakın askerlik şubesine","En geç yirmidört saat içinde en yakın Cumhuriyet savcılığına","En geç oniki saat içinde mülki amire","En geç yirmidört saat içinde garnizon komutanlığına"],"dogru":1,"aciklama":"m.74/1: Yakalanan yükümlüler vakit geçirmeksizin ve en geç yirmidört saat içerisinde en yakın askerlik şubesine getirilir. Şube teslim almazsa tutanağa istinaden derhâl serbest bırakılır.","kaynak":"Yön. m.74/1","zorluk":"orta"},
    {"id":"JANDYON-S-029","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'ne göre, Jandarma Genel Komutanlığı stratejik hedef planı ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Üç yıllık bir dönemi kapsar ve vali onayı ile yürürlüğe konulur.","Beş yıllık bir dönemi kapsar, Bakan onayı ile yürürlüğe konulur ve en az iki yılda bir gözden geçirilir.","Beş yıllık bir dönemi kapsar ve her yıl gözden geçirilir.","İki yıllık bir dönemi kapsar ve Bakan onayı ile yürürlüğe konulur.","Beş yıllık bir dönemi kapsar ve Cumhuriyet Başsavcılığının onayı ile yürürlüğe konulur."],"dogru":1,"aciklama":"m.76/1: Stratejik hedef planı beş yıllık dönemi kapsar, Bakan onayı ile yürürlüğe konulur ve en az iki yılda bir gözden geçirilir.","kaynak":"Yön. m.76/1","zorluk":"orta"},
    {"id":"JANDYON-S-030","soru":"Jandarma Teşkilat, Görev ve Yetkileri Yönetmeliği'nin 80 inci maddesi ile, 3/11/1983 tarihli ve 83/7362 sayılı Bakanlar Kurulu Kararı ile yürürlüğe konulan Jandarma Teşkilatı Görev ve Yetkileri Yönetmeliği yürürlükten kaldırılmıştır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.80/1: 3/11/1983 tarihli ve 83/7362 sayılı eski Jandarma Yönetmeliği yürürlükten kaldırılmıştır; yerine 2016/9741 sayılı bu Yönetmelik geçmiştir.","kaynak":"Yön. m.80/1","zorluk":"kolay"},
    {"id":"JANDYON-OO-001","soru":"Jandarma astsubayı A, sorumluluk alanındaki bir köyde henüz herhangi bir suç işlenmemişken, gerginleşen iki grup arasında olası bir kavgayı önlemek amacıyla devriyeyi artırıp tedbir alır. Aynı gün astsubay B ise işlenmiş bir hırsızlık olayında olay yerini koruyup delilleri toplar ve Cumhuriyet savcısının talimatıyla işlem yapar. A ve B'nin yürüttüğü görevler sırasıyla hangi görev türüne girer?","siklar":["A: mülki görev — B: adli görev","A: adli görev — B: mülki görev","A: askeri görev — B: adli görev","A: mülki görev — B: askeri görev","A: adli görev — B: askeri görev"],"dogru":0,"aciklama":"m.8/1-a: Mülki görevler, suç işlenmeden önce emniyet-asayişi sağlamak ve suç işlenmesini önlemek için tedbir almayı kapsar (A'nın yaptığı). m.8/1-b: Adli görevler, işlenmiş suçlarla ilgili kanuni işlemleri ve adli hizmetleri (delil toplama, savcı talimatı) kapsar (B'nin yaptığı).","kaynak":"Yön. m.8/1-a, m.8/1-b","zorluk":"orta"},
    {"id":"JANDYON-OO-002","soru":"Bir ceza infaz kurumunun müdürü, infaz koruma memuru sayısının yetersiz kaldığını gerekçe göstererek, dış korumayı yapan jandarmadan koğuşların bulunduğu iç bölümde nöbet tutmasını ve infaz koruma memurluğu görevini üstlenmesini ister. Bu talep karşısında hukuken doğru olan nedir?","siklar":["Jandarma yalnızca acil ve geçici hâllerde kurum içinde infaz koruma görevi yapabilir.","Kurum müdürünün yazılı emri bulunması hâlinde jandarma iç koğuş nöbetini üstlenir.","Jandarma hiçbir şekilde ceza infaz kurumlarının iç işlerinde ve infaz koruma memurluğu görevlerinde kullanılamaz; görevi yalnızca dış korumadır.","Vali onayı alınması koşuluyla jandarma kurum içinde görevlendirilebilir.","Cumhuriyet savcısının kararıyla jandarma kurum içinde görevlendirilebilir."],"dogru":2,"aciklama":"m.24/1 ve m.24/3: Ceza infaz kurumlarının dış korunması jandarmaya aittir; ancak jandarma hiçbir şekilde kurumun iç işlerinde ve infaz koruma memurluğu görevlerinde kullanılamaz. İç/dış ayrımı mutlaktır, hiçbir onay veya yazılı emir bu yasağı kaldırmaz.","kaynak":"Yön. m.24/1, m.24/3","zorluk":"orta"},
    {"id":"JANDYON-OO-003","soru":"Jandarma personeli A'ya amiri, gözaltındaki bir şüpheliden bilgi almak amacıyla şüpheliye işkence yapmasını emreder. A emrin suç oluşturduğunu belirtip yerine getirmek istemeyince amir ısrar eder ve emri yazılı olarak da tekrarlar. A hukuken ne yapmalıdır?","siklar":["Emir yazılı olarak tekrarlandığından emri yerine getirir, sorumluluk amire geçer.","Konusu suç teşkil eden emri hiçbir suretle yerine getirmez; yazılı tekrar bu emri meşrulaştırmaz ve yerine getirenler sorumluluktan kurtulamaz.","Emri bir üst amire onaylatarak yerine getirir.","Emri yalnızca tanık huzurunda yerine getirirse sorumlu olmaz.","Emri yerine getirir, ancak sonradan durumu Cumhuriyet savcısına bildirirse cezadan kurtulur."],"dogru":1,"aciklama":"m.42/2: Konusu suç teşkil eden emir hiçbir suretle yerine getirilmez; yerine getirenler sorumluluktan kurtulamaz. İşkence açıkça suç olduğundan, emrin yazılı tekrarı onu yerine getirilebilir kılmaz.","kaynak":"Yön. m.42/2","zorluk":"zor"},
    {"id":"JANDYON-OO-004","soru":"Jandarma personeli A, amirinden aldığı emri yönetmeliğe aykırı bulur (emrin konusu suç teşkil etmemektedir) ve bu aykırılığı emri verene bildirir. Buna rağmen amir emrinde ısrar eder ve emri yazılı olarak tekrarlar. Bu durumda hukuki sonuç nedir?","siklar":["Emir yerine getirilmez; çünkü aykırı emir hiçbir şekilde uygulanamaz.","Emir yerine getirilir ve doğacak sorumluluk emri yerine getirene aittir.","Emir yerine getirilir ve bu hâlde emri yerine getiren sorumlu olmaz; sorumluluk emri verene geçer.","Emrin yerine getirilebilmesi için ayrıca valinin onayı gerekir.","Emir yalnızca sözlü olarak tekrarlanırsa yerine getirilir."],"dogru":2,"aciklama":"m.42/2: Mevzuata aykırı görülen emir bildirildiği hâlde amir ısrar eder ve emri yazılı olarak tekrarlarsa emir yerine getirilir; bu hâlde emri yerine getiren sorumlu olmaz (sorumluluk emri verene aittir).","kaynak":"Yön. m.42/2","zorluk":"orta"},
    {"id":"JANDYON-OO-005","soru":"Jandarma ekibi, makul bir sebebe dayanarak bir aracı durdurur. Ekip, el ile dıştan kontrolün ötesine geçerek sürücünün üzerindeki elbiseyi çıkarttırmak ve aracın dışarıdan içerisi görünmeyen bölümlerini açıp aramak istemektedir. Bu kontrol/arama bakımından hukuken doğru olan nedir?","siklar":["Makul sebep bulunduğundan ekip, elbiseyi çıkartıp her türlü aramayı kendiliğinden yapabilir.","Durdurmada yalnızca el ile dıştan kontrol yapılabilir; bunun ötesindeki üst ve araç araması mülki amirin görevlendireceği kolluk amirinin emriyle yapılır ve bu karar yirmidört saat içinde görevli hâkimin onayına sunulur.","İleri arama yalnızca Cumhuriyet savcısının yazılı emriyle yapılabilir.","Elbisenin çıkarılması serbesttir; ancak aracın kapalı bölümleri yalnızca hâkim kararıyla aranabilir.","Durdurmada arama yapılamaz; arama için kişinin mutlaka karakola götürülmesi zorunludur."],"dogru":1,"aciklama":"m.46/6: Durdurmada kişinin elbisesinin çıkarılması veya aracın içerisi görünmeyen bölümlerinin açılması istenemez. El ile dıştan kontrol hariç üst/eşya/araç araması, mülki amirin görevlendireceği kolluk amirinin yazılı (acelede sözlü, sonra yazıyla teyit) emriyle yapılır ve karar yirmidört saat içinde görevli hâkimin onayına sunulur.","kaynak":"Yön. m.46/2, m.46/6","zorluk":"zor"},
    {"id":"JANDYON-OO-006","soru":"Bir ilçede gecikmesinde sakınca bulunduğu değerlendirilen bir durum ortaya çıkmıştır. Kaymakam, bir suçun önlenmesi amacıyla bir kişinin konutunda önleme araması yapılması için jandarmaya yazılı emir vermek istemektedir. Bu talep bakımından hukuken doğru olan nedir?","siklar":["Gecikmesinde sakınca bulunduğundan kaymakamın yazılı emriyle konutta önleme araması yapılabilir.","Konutta önleme araması yapılamaz; önleme araması konut, yerleşim yeri ve kamuya açık olmayan işyerleri ile eklentilerinde uygulanamaz.","Konutta önleme araması ancak sulh ceza hâkiminin kararıyla yapılabilir.","Konutta önleme araması yalnızca vali onayıyla yapılabilir.","Konutta önleme araması yapılabilir, ancak arama sonrası yirmidört saat içinde hâkim onayı alınması gerekir."],"dogru":1,"aciklama":"m.47/5: Konutta, yerleşim yerinde ve kamuya açık olmayan işyerlerinde ve eklentilerinde önleme araması yapılamaz. Bu yasak mutlaktır; sulh ceza hâkimi kararı veya mülki amir yazılı emri de konutta önleme aramasına imkân vermez.","kaynak":"Yön. m.47/1, m.47/5","zorluk":"zor"},
    {"id":"JANDYON-OO-007","soru":"Bir jandarma devriyesi, bir evden yükselen imdat çığlıklarını duyar ve evden duman çıktığını görür. İçeride yangında mahsur kalmış kişiler olabileceğini değerlendiren devriye, kişileri kurtarmak amacıyla önceden karar/emir almaksızın konuta girer. Bu davranış hukuken nasıl değerlendirilir?","siklar":["Hukuka aykırıdır; jandarma hiçbir koşulda konuta giremez.","Hukuka uygundur; imdat istenmesi veya yangın, su baskını, boğulma gibi büyük tehlikelerden kişileri kurtarmak amacıyla jandarma konut, işyeri ve eklentilerine girebilir.","Hukuka aykırıdır; girmek için önce sulh ceza hâkimi kararı alınmalıydı.","Hukuka aykırıdır; girmek için mülki amirin yazılı emri gerekirdi.","Hukuka uygundur, ancak yalnızca işlenmekte olan bir suç söz konusu olsaydı girebilirdi."],"dogru":1,"aciklama":"m.48/1-a: İmdat istenmesi veya yangın, su baskını ve boğulma gibi büyük tehlikelerden kişileri kurtarmak amacıyla jandarma konutlara, işyerlerine ve eklentilerine girebilir. Bu, önleme araması yasağının (m.47/5) bir istisnasıdır ve önceden karar/emir gerektirmez.","kaynak":"Yön. m.48/1-a","zorluk":"orta"},
    {"id":"JANDYON-OO-008","soru":"Bir belediye başkanı, ilçedeki bir etkinlikte güvenlik sağlanması için jandarma karakol komutanına doğrudan emir vererek personel görevlendirmesini ister. Karakol komutanı bu doğrudan emir karşısında nasıl hareket etmelidir?","siklar":["Belediye başkanı seçilmiş bir makam olduğundan emri doğrudan yerine getirir.","Doğrudan emri yalnızca mülki amirler ile adli makamlar verebilir; belediye başkanı gibi diğer makamlar, istedikleri görevin kanuni dayanağını belirterek o yerin mülki amirine başvurmalıdır.","Emri Jandarma Genel Komutanlığına ileterek oradan onay almalıdır.","Emri garnizon komutanının onayına sunmalıdır.","Belediye başkanının emrini ancak vali yardımcısı onaylarsa yerine getirir."],"dogru":1,"aciklama":"m.58/3: Mülki amirler ile adli makamlar jandarmaya doğrudan emir verme yetkisine sahiptir. Diğer makamlar (belediye başkanı dâhil), görev olarak istedikleri konunun kanuni dayanağını belirterek o yerin mülki amirine başvurur; doğrudan emir veremez.","kaynak":"Yön. m.58/3","zorluk":"orta"},
    {"id":"JANDYON-OO-009","soru":"Bir polis ekibi, jandarmanın sorumluluk alanında işlenmekte olan bir suçla karşılaşır. Bu durumda polis ekibi nasıl hareket etmelidir?","siklar":["Suç kendi alanında olmadığından hiç müdahale etmeden olay yerinden ayrılır.","Olaya müdahale eder ve soruşturmayı kendisi tamamlayarak dosyayı doğrudan savcılığa gönderir.","Olaya müdahale eder ve jandarmaya haber verir; jandarma gelinceye kadar olay yerinde soruşturma yapamaz, durumu olduğu gibi koruyarak delillerin kaybolmaması için gereken önlemleri alır.","Yalnızca jandarmaya haber verir, olay yerine hiç müdahale etmez.","Olayı doğrudan garnizon komutanlığına bildirir."],"dogru":2,"aciklama":"m.65/1: Jandarma sorumluluk alanında suçla karşılaşan polis (veya sahil güvenlik), olaya müdahale eder ve jandarmaya haber verir; jandarma gelinceye kadar olay yerinde soruşturma yapamaz, durumu olduğu gibi koruyup delillerin kaybolmaması için önlem alır.","kaynak":"Yön. m.65/1","zorluk":"orta"},
    {"id":"JANDYON-OO-010","soru":"Henüz polis teşkilatı kurulmamış olan ve jandarmanın sorumluluk alanı dışında kalan bir yerleşim yerinde bir suç işlenir. En yakın jandarma birimi olaya kendiliğinden el koyar. Bu durumda söz konusu yer bakımından hukuki sonuç nedir?","siklar":["Jandarma sorumluluk alanı dışında olduğundan hiçbir işlem yapamaz, polisin gelmesini bekler.","Jandarmanın görev yaptığı o yer, jandarmanın görev alanı sayılır.","O yer, kalıcı olarak jandarmanın sorumluluk alanına katılır ve bir daha değiştirilemez.","Jandarma yalnızca mülki amirin önceden vereceği yazılı izinle el koyabilirdi.","El koyma yetkisi yalnızca sulh ceza hâkimi kararıyla doğar."],"dogru":1,"aciklama":"m.9/1-a: Polis teşkilatı kurulmamış olması nedeniyle jandarmanın görevlendirilmesi ya da kendiliğinden olaya el koyması mümkündür; bu gibi durumlarda jandarmanın görev yaptığı o yer, onun görev alanı sayılır.","kaynak":"Yön. m.9/1-a","zorluk":"orta"},
    {"id":"JANDYON-OO-011","soru":"Jandarma, bir yoklama kaçağını yakalayıp muhafaza altına alır. En yakın askerlik şubesine getirilen yükümlüyü, şube o an teslim alamayacağını bildirir. Süre ve sonraki işlem bakımından hukuken doğru olan nedir?","siklar":["Yükümlü en geç kırksekiz saat içinde şubeye getirilir; şube almazsa Cumhuriyet savcılığına teslim edilir.","Yükümlü vakit geçirmeksizin ve en geç yirmidört saat içinde en yakın askerlik şubesine getirilir; şube teslim alamazsa jandarmanın hazırladığı tutanağa istinaden derhal serbest bırakılır.","Yükümlü yirmidört saat içinde şubeye getirilir; şube almazsa mülki amir kararıyla gözaltına alınır.","Yükümlü oniki saat içinde garnizon komutanlığına teslim edilir.","Yükümlü şube alamazsa, alınana kadar karakolda muhafaza edilmeye devam edilir."],"dogru":1,"aciklama":"m.74/1: Yakalanan yükümlüler vakit geçirmeksizin ve en geç yirmidört saat içinde en yakın askerlik şubesine getirilir; askerlik şubesince teslim alınamayan yükümlüler, jandarma tarafından hazırlanan tutanağa istinaden derhal serbest bırakılır.","kaynak":"Yön. m.74/1","zorluk":"orta"},
    {"id":"JANDYON-OO-012","soru":"Barış döneminde bir ilde garnizon komutanı, jandarma birliklerinden belirli bir askeri görevin yerine getirilmesini talep eder. Bu askeri görev jandarmaya hangi usulle verilir?","siklar":["Garnizon komutanının talebi tek başına yeterlidir; görev doğrudan emirle verilir.","Garnizon komutanının talebi üzerine valinin onayıyla verilir.","Yalnızca Genelkurmay Başkanının talebi ve Bakanın onayıyla verilir.","Kaymakamın talebi ve valinin onayıyla verilir.","Yalnızca Bakanlar Kurulu kararıyla verilir."],"dogru":1,"aciklama":"m.41/2: Jandarma birlikleri, Genelkurmay Başkanlığının talebi üzerine Bakanın, illerde ise garnizon komutanının talep etmesi hâlinde valinin onayıyla kendilerine verilen askeri görevleri yapar. İllerde onay mercii validir.","kaynak":"Yön. m.41/2","zorluk":"zor"},
  ],
  18: [
    {"id":"30224-S-001","soru":"Kişisel Verilerin Silinmesi, Yok Edilmesi veya Anonim Hale Getirilmesi Hakkında Yönetmeliğe göre, kişisel verilerin silinmesi aşağıdakilerden hangisini ifade eder?","siklar":["Kişisel verilerin hiç kimse tarafından hiçbir şekilde erişilemez ve geri getirilemez hale getirilmesi","Kişisel verilerin başka verilerle eşleştirilse dahi kimliği belirli bir kişiyle ilişkilendirilemeyecek hale getirilmesi","Kişisel verilerin ilgili kullanıcılar için hiçbir şekilde erişilemez ve tekrar kullanılamaz hale getirilmesi","Kişisel verilerin veri kayıt sisteminden geçici olarak çıkarılarak arşive aktarılması","Kişisel verilerin saklama süresi dolduğunda otomatik olarak yedeklenmesi"],"dogru":2,"aciklama":"m.8/1: Silme, kişisel verilerin ilgili kullanıcılar için hiçbir şekilde erişilemez ve tekrar kullanılamaz hale getirilmesi işlemidir. Kapsam dar; başkası erişebilir.","kaynak":"30224 m.8/1","zorluk":"kolay"},
    {"id":"30224-S-002","soru":"Yönetmeliğe göre, kişisel verilerin 'hiç kimse tarafından hiçbir şekilde erişilemez, geri getirilemez ve tekrar kullanılamaz hale getirilmesi' aşağıdakilerden hangisini ifade eder?","siklar":["Yok edilmesi","Silinmesi","Anonim hale getirilmesi","Periyodik imha edilmesi","Maskelenmesi"],"dogru":0,"aciklama":"m.9/1: Yok etme, kişisel verilerin hiç kimse tarafından hiçbir şekilde erişilemez, geri getirilemez ve tekrar kullanılamaz hale getirilmesidir. Ayırt edici unsur 'hiç kimse' ve 'geri getirilemez'dir.","kaynak":"30224 m.9/1","zorluk":"orta"},
    {"id":"30224-S-003","soru":"Yönetmeliğe göre kişisel verilerin anonim hale getirilmesiyle ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Veriler hiç kimse tarafından hiçbir şekilde erişilemez ve geri getirilemez hale getirilir.","Verilere yalnızca ilgili kullanıcıların erişimi engellenir; veriler tümüyle ortadan kalkmaz.","Veriler şifrelenerek geçici bir süre için arşive aktarılır.","Veriler, başka verilerle eşleştirilse dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hale getirilir.","Verilerin saklama süresi dolduğunda otomatik olarak yedeği alınır."],"dogru":3,"aciklama":"m.10/1: Anonim hale getirme, kişisel verilerin başka verilerle eşleştirilse dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hale getirilmesidir. Veri ortadan kalkmaz; yalnızca kimlik bağı koparılır.","kaynak":"30224 m.10/1","zorluk":"orta"},
    {"id":"30224-S-004","soru":"Aşağıdakilerden hangisi, Kişisel Verilerin Silinmesi, Yok Edilmesi veya Anonim Hale Getirilmesi Hakkında Yönetmelikte yer alan bir kavram ya da işlem değildir?","siklar":["Kişisel verilerin silinmesi","Kişisel verilerin şifrelenmesi","Kişisel verilerin yok edilmesi","Kişisel verilerin anonim hale getirilmesi","Periyodik imha"],"dogru":1,"aciklama":"Silme (m.8), yok etme (m.9), anonim hale getirme (m.10) ve periyodik imha (m.4/ğ ve m.11) Yönetmelikte yer alan kavram ve işlemlerdir. Şifreleme ise bir veri güvenliği tedbiridir; bu Yönetmelikte düzenlenen bir imha kavramı/işlemi değildir; bu nedenle B sahte cevaptır.","kaynak":"30224 m.8-10","zorluk":"orta"},
    {"id":"30224-S-005","soru":"Yönetmeliğe göre kişisel verilerin silinmesi, kişisel verilerin ilgili kullanıcılar için hiçbir şekilde erişilemez ve tekrar kullanılamaz hale getirilmesi işlemidir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.8/1 metni birebir budur. Silmede erişim engeli 'ilgili kullanıcılar' ile sınırlıdır.","kaynak":"30224 m.8/1","zorluk":"kolay"},
    {"id":"30224-S-006","soru":"Yönetmeliğe göre kişisel verilerin yok edilmesi, kişisel verilerin yalnızca ilgili kullanıcılar için erişilemez hale getirilmesi işlemidir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.9/1'e göre yok etmede veriler 'hiç kimse tarafından' hiçbir şekilde erişilemez, geri getirilemez ve tekrar kullanılamaz hale gelir. 'Yalnızca ilgili kullanıcılar için' ifadesi silmenin (m.8) ölçütüdür; bu nedenle ifade yanlıştır.","kaynak":"30224 m.9/1","zorluk":"orta"},
    {"id":"30224-S-007","soru":"Yönetmeliğe göre, telafisi güç veya imkânsız zararların doğması ve açıkça hukuka aykırılık olması hâlinde, periyodik imha ile resen imhaya ilişkin Yönetmelikte belirlenen süreleri kısaltma yetkisi aşağıdakilerden hangisine aittir?","siklar":["Veri sorumlusuna","İlgili kişiye","Veri işleyene","Kişisel Verileri Koruma Kuruluna","Cumhurbaşkanlığına"],"dogru":3,"aciklama":"m.11/4: Kurul, telafisi güç veya imkânsız zararların doğması ve açıkça hukuka aykırılık olması hâlinde, bu maddede belirlenen süreleri kısaltabilir. Bu yetki münhasıran Kişisel Verileri Koruma Kuruluna aittir.","kaynak":"30224 m.11/4","zorluk":"orta"},
    {"id":"30224-S-008","soru":"Yönetmeliğe göre, kişisel veri saklama ve imha politikası hazırlama yükümlülüğü olmayan veri sorumlusu, imha yükümlülüğünün ortaya çıktığı tarihi takip eden kaç ay içinde kişisel verileri siler, yok eder veya anonim hale getirir?","siklar":["İlk periyodik imha işleminde","3 ay içinde","6 ay içinde","30 gün içinde","1 yıl içinde"],"dogru":1,"aciklama":"m.11/3: Politikası hazırlama yükümlülüğü olmayan veri sorumlusu, yükümlülüğün ortaya çıktığı tarihi takip eden üç ay içinde imha eder.","kaynak":"30224 m.11/3","zorluk":"orta"},
    {"id":"30224-S-009","soru":"Yönetmeliğe göre kişisel verilerin silinmesi, kişisel verilerin ............... için hiçbir şekilde erişilemez ve tekrar kullanılamaz hale getirilmesi işlemidir. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["hiç kimse","veri sorumlusu","Kurul","üçüncü kişiler","ilgili kullanıcılar"],"dogru":4,"aciklama":"m.8/1: Silmede erişim engeli 'ilgili kullanıcılar' için geçerlidir.","kaynak":"30224 m.8/1","zorluk":"orta"},
    {"id":"30224-S-010","soru":"Yönetmeliğin 11. maddesine göre, periyodik imhanın gerçekleştirileceği zaman aralığı her halde ............... ayı geçemez. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["iki","üç","altı","sekiz","on"],"dogru":2,"aciklama":"m.11/2: Bu süre her halde altı ayı geçemez.","kaynak":"30224 m.11/2","zorluk":"kolay"},
    {"id":"30224-S-011","soru":"Yönetmeliğe göre kişisel verilerin yok edilmesi tanımı dikkate alındığında, aşağıdakilerden hangisi bu tanımın bir unsuru değildir?","siklar":["Yalnızca ilgili kullanıcılar için erişilemez hale getirilmesi","Hiç kimse tarafından erişilemez hale getirilmesi","Hiçbir şekilde erişilemez hale getirilmesi","Geri getirilemez hale getirilmesi","Tekrar kullanılamaz hale getirilmesi"],"dogru":0,"aciklama":"m.9/1: Yok etme; verinin hiç kimse tarafından, hiçbir şekilde erişilemez, geri getirilemez ve tekrar kullanılamaz hale getirilmesidir. 'Yalnızca ilgili kullanıcılar için' ölçütü silmeye (m.8) aittir; yok etme tanımının unsuru değildir.","kaynak":"30224 m.9/1","zorluk":"zor"},
    {"id":"30224-S-012","soru":"Yönetmeliğe göre, kişisel veri saklama ve imha politikası hazırlamış olan veri sorumlusu, imha yükümlülüğünün ortaya çıktığı tarihi takip eden hangi aşamada kişisel verileri siler, yok eder veya anonim hale getirir?","siklar":["30 gün içinde","Aynı gün içinde","3 ay içinde","1 yıl içinde","İlk periyodik imha işleminde"],"dogru":4,"aciklama":"m.11/1: Politikası hazırlamış olan veri sorumlusu, yükümlülüğün ortaya çıktığı tarihi takip eden ilk periyodik imha işleminde kişisel verileri imha eder.","kaynak":"30224 m.11/1","zorluk":"orta"},
    {"id":"30224-OO-001","soru":"Bir kamu kurumunda veri sorumlusu adına çalışan A, artık işlenme şartı kalmayan personel kayıtlarını, kurumdaki ilgili kullanıcıların hiçbir şekilde erişemeyeceği ve tekrar kullanamayacağı hâle getirir. Ancak veriler, yalnızca sistem yöneticisinin denetimindeki yedek ortamlarda teknik olarak hâlâ bulunmaktadır. A'nın gerçekleştirdiği bu işlem, Yönetmeliğe göre aşağıdakilerden hangisidir?","siklar":["Kişisel verilerin yok edilmesi","Kişisel verilerin silinmesi","Kişisel verilerin anonim hale getirilmesi","Kişisel verilerin maskelenmesi","Kişisel verilerin arşivlenmesi"],"dogru":1,"aciklama":"m.8/1: Silme, kişisel verilerin ilgili kullanıcılar için hiçbir şekilde erişilemez ve tekrar kullanılamaz hale getirilmesidir. Olayda erişim yalnızca ilgili kullanıcılara kapatılmış, veriler teknik olarak (yedekte) hâlâ var; bu tam olarak silmenin tanımıdır.","kaynak":"30224 m.8/1","zorluk":"orta"},
    {"id":"30224-OO-002","soru":"Bir hastane, hizmet dışı bıraktığı ve kişisel veri içeren sabit diskleri, manyetik alandan geçirip ardından fiziksel olarak parçalayarak verilerin hiç kimse tarafından hiçbir şekilde erişilemez ve geri getirilemez hâle gelmesini sağlar. Hastanenin gerçekleştirdiği bu işlem Yönetmeliğe göre aşağıdakilerden hangisidir?","siklar":["Kişisel verilerin silinmesi","Kişisel verilerin anonim hale getirilmesi","Kişisel verilerin yok edilmesi","Kişisel verilerin yedeklenmesi","Kişisel verilerin şifrelenmesi"],"dogru":2,"aciklama":"m.9/1: Yok etme, kişisel verilerin hiç kimse tarafından hiçbir şekilde erişilemez, geri getirilemez ve tekrar kullanılamaz hale getirilmesidir. Diskin fiziksel olarak imha edilip verinin geri getirilemez hâle gelmesi yok etmenin tipik örneğidir.","kaynak":"30224 m.9/1","zorluk":"orta"},
    {"id":"30224-OO-003","soru":"Bir araştırma birimi, istatistiksel çalışmalarda kullanmaya devam edeceği veri setindeki ad, soyad ve T.C. kimlik numarası gibi tanımlayıcıları, veri seti başka verilerle eşleştirilse dahi hiçbir surette belirli bir gerçek kişiyle ilişkilendirilemeyecek şekilde işler. Veriler araştırma amacıyla kullanılmaya devam etmektedir. Bu işlem Yönetmeliğe göre aşağıdakilerden hangisidir?","siklar":["Kişisel verilerin silinmesi","Kişisel verilerin yok edilmesi","Kişisel verilerin anonim hale getirilmesi","Kişisel verilerin periyodik imhası","Kişisel verilerin maskelenerek arşivlenmesi"],"dogru":2,"aciklama":"m.10/1: Anonim hale getirme, kişisel verilerin başka verilerle eşleştirilse dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hale getirilmesidir. Olayda veri seti varlığını sürdürür, yalnızca kimlik bağı koparılır — anonim hale getirmenin tipik örneğidir.","kaynak":"30224 m.10/1","zorluk":"orta"},
    {"id":"30224-OO-004","soru":"Kişisel veri saklama ve imha politikası hazırlamış olan bir veri sorumlusu, bir personeline ait kişisel verilerin işlenme şartlarının tamamının ortadan kalktığını tespit eder. Bu veri sorumlusu, ilgili kişiden herhangi bir talep gelmemiş olmasına rağmen söz konusu verileri Yönetmeliğe göre ne zaman silmeli, yok etmeli veya anonim hale getirmelidir?","siklar":["Tespit tarihinden itibaren 30 gün içinde","Yükümlülüğün ortaya çıktığı tarihi takip eden ilk periyodik imha işleminde","Yükümlülüğün ortaya çıktığı tarihi takip eden 3 ay içinde","Yalnızca ilgili kişinin talebi üzerine","Tespit tarihinden itibaren 6 ay içinde"],"dogru":1,"aciklama":"m.11/1: Politikası hazırlamış olan veri sorumlusu, imha yükümlülüğünün ortaya çıktığı tarihi takip eden ilk periyodik imha işleminde kişisel verileri siler, yok eder veya anonim hale getirir. Şartların ortadan kalkması hâlinde imha resen yapılır; talep şart değildir.","kaynak":"30224 m.11/1","zorluk":"zor"},
    {"id":"30224-OO-005","soru":"Kişisel veri saklama ve imha politikası hazırlama yükümlülüğü bulunmayan küçük ölçekli bir veri sorumlusu, 1 Mart günü bir kişisel veri grubu yönünden imha yükümlülüğünün ortaya çıktığını tespit eder. Bu veri sorumlusu, söz konusu kişisel verileri Yönetmeliğe göre en geç ne zaman silmeli, yok etmeli veya anonim hale getirmelidir?","siklar":["1 Mart'ı takip eden ilk periyodik imha işleminde","1 Mart'ı takip eden 30 gün içinde","1 Mart'ı takip eden üç ay içinde","1 Mart'ı takip eden altı ay içinde","1 Mart'ı takip eden bir yıl içinde"],"dogru":2,"aciklama":"m.11/3: Politika hazırlama yükümlülüğü olmayan veri sorumlusu, yükümlülüğün ortaya çıktığı tarihi takip eden üç ay içinde kişisel verileri siler, yok eder veya anonim hale getirir.","kaynak":"30224 m.11/3","zorluk":"orta"},
    {"id":"30224-OO-006","soru":"Bir veri sorumlusu, hazırladığı kişisel veri saklama ve imha politikasında periyodik imhanın gerçekleştirileceği zaman aralığını sekiz ay olarak belirlemek istemektedir. Yönetmeliğe göre bu belirleme bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Veri sorumlusu bu aralığı serbestçe belirleyebileceğinden sekiz ay geçerlidir.","Periyodik imha aralığı her halde altı ayı geçemeyeceğinden sekiz aylık belirleme bu sınıra aykırıdır.","Periyodik imha aralığı en fazla üç ay olabileceğinden sekiz ay geçersizdir.","Aralık ancak Kişisel Verileri Koruma Kurulunun onayıyla sekiz ay olarak belirlenebilir.","Periyodik imha aralığı en fazla bir yıl olabileceğinden sekiz ay geçerlidir."],"dogru":1,"aciklama":"m.11/2: Periyodik imhanın gerçekleştirileceği zaman aralığı veri sorumlusu tarafından politikada belirlenir; ancak bu süre her halde altı ayı geçemez. Bu nedenle sekiz aylık belirleme tavanı aşar ve geçersizdir.","kaynak":"30224 m.11/2","zorluk":"zor"},
  ],
  19: [
    {"id":"BILGIEDINME-S-001","soru":"Bilgi Edinme Hakkı Kanununun Uygulanmasına İlişkin Esas ve Usuller Hakkında Yönetmeliğin 2. maddesine göre, aşağıdakilerden hangisi mahalli idareler bakımından Yönetmeliğin kapsamı DIŞINDA bırakılmıştır?","siklar":["Köyler","Üniversiteler","T.C. Merkez Bankası","Kamu kurumu niteliğindeki meslek kuruluşları","Mahalli idarelerin birlik veya şirketleri"],"dogru":0,"aciklama":"m.2: '...köyler hariç olmak üzere mahalli idareler ve bunların bağlı ve ilgili kuruluşları ile birlik veya şirketlerinin...' Metinde açıkça hariç tutulan tek unsur köylerdir.","kaynak":"Yönetmelik m.2","zorluk":"kolay"},
    {"id":"BILGIEDINME-S-002","soru":"Yönetmeliğin 2. maddesine göre, aşağıdakilerden hangisi Yönetmeliğin uygulanacağı kapsama dâhil edilen kuruluşlardan biri DEĞİLDİR?","siklar":["Merkezi idare kapsamındaki kamu idarelerinin bağlı, ilgili veya ilişkili kuruluşları","Kamu kurumu niteliğindeki meslek kuruluşları","Türkiye'de faaliyet gösteren özel bankalar","T.C. Merkez Bankası ve üniversiteler","Köyler hariç olmak üzere mahalli idareler ile bunların birlik veya şirketleri"],"dogru":2,"aciklama":"m.2 yalnızca kamu idarelerini, kamu tüzel kişiliğini haiz kurum/kuruluşları, mahalli idareleri (köy hariç), TCMB ve üniversiteleri ve kamu kurumu niteliğindeki meslek kuruluşlarını kapsar. Özel bankalar madde kapsamında sayılmaz.","kaynak":"Yönetmelik m.2","zorluk":"orta"},
    {"id":"BILGIEDINME-S-003","soru":"Yönetmeliğin 2. maddesine göre bu Yönetmelik, köyler de dâhil olmak üzere tüm mahalli idarelerin faaliyetlerinde uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.2'de mahalli idareler 'köyler hariç olmak üzere' kapsama alınmıştır. Dolayısıyla köyler kapsam dışıdır; ifade yanlıştır.","kaynak":"Yönetmelik m.2","zorluk":"kolay"},
    {"id":"BILGIEDINME-S-004","soru":"Yönetmeliğin 2. maddesine göre: '......................... ve üniversiteler de dahil olmak üzere kamu tüzel kişiliğini haiz olarak enstitü, teşebbüs, teşekkül, fon ve sair adlarla kurulmuş olan bütün kamu kurum ve kuruluşlarının ... faaliyetlerinde uygulanır.' Boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?","siklar":["T.C. Merkez Bankası","İstanbul Menkul Kıymetler Borsası (İMKB)","Bankacılık Düzenleme ve Denetleme Kurumu","Sermaye Piyasası Kurulu","Hazine ve Maliye Bakanlığı"],"dogru":0,"aciklama":"m.2'nin güncel metni 'T.C. Merkez Bankası ve üniversiteler de dahil olmak üzere...' şeklindedir.","kaynak":"Yönetmelik m.2","zorluk":"orta"},
    {"id":"BILGIEDINME-S-005","soru":"Yönetmeliğin 3. maddesine göre bu Yönetmelik, hangi kanunun hangi maddesi uyarınca hazırlanmıştır?","siklar":["5018 sayılı Kamu Mali Yönetimi ve Kontrol Kanununun 31 inci maddesi","4982 sayılı Bilgi Edinme Hakkı Kanununun 1 inci maddesi","4982 sayılı Bilgi Edinme Hakkı Kanununun 13 üncü maddesi","4982 sayılı Bilgi Edinme Hakkı Kanununun 30 uncu maddesi","4982 sayılı Bilgi Edinme Hakkı Kanununun 31 inci maddesi"],"dogru":4,"aciklama":"m.3: 'Bu Yönetmelik, 9/10/2003 tarihli ve 4982 sayılı Bilgi Edinme Hakkı Kanununun 31 inci maddesi uyarınca hazırlanmıştır.'","kaynak":"Yönetmelik m.3","zorluk":"kolay"},
    {"id":"BILGIEDINME-S-006","soru":"Yönetmeliğin 4. maddesinde (Tanımlar) kaç adet kavram tanımlanmıştır?","siklar":["5","6","7","8","9"],"dogru":2,"aciklama":"m.4'te a) Kurum ve kuruluş, b) Başvuru sahibi, c) Bilgi, d) Belge, e) Bilgi veya belgeye erişim, f) Kurul, g) Kanun olmak üzere 7 tanım yapılmıştır.","kaynak":"Yönetmelik m.4","zorluk":"orta"},
    {"id":"BILGIEDINME-S-007","soru":"Yönetmeliğin 4. maddesine göre, aşağıdakilerden hangisi bu Yönetmelikte tanımı yapılan kavramlardan biri DEĞİLDİR?","siklar":["Bilgi","Belge","Başvuru sahibi","Veri sorumlusu","Bilgi veya belgeye erişim"],"dogru":3,"aciklama":"m.4'te tanımlanan kavramlar: Kurum ve kuruluş, Başvuru sahibi, Bilgi, Belge, Bilgi veya belgeye erişim, Kurul, Kanun. 'Veri sorumlusu' bu Yönetmelikte tanımlanmaz (kişisel verilerin korunması mevzuatına ait bir kavramdır).","kaynak":"Yönetmelik m.4","zorluk":"orta"},
    {"id":"BILGIEDINME-S-008","soru":"Yönetmeliğin 4. maddesindeki 'bilgi veya belgeye erişim' tanımına göre, istenen bilgi veya belgeye erişim sağlanırken kurum ve kuruluşlarca öncelikle hangi yol izlenir?","siklar":["Başvuru sahibine söz konusu bilgi veya belgenin bir kopyasının verilmesi","Belgenin aslının başvuru sahibine kalıcı olarak teslim edilmesi","Bilginin başvuru sahibine yalnızca sözlü olarak özetlenmesi","Bilgi veya belgenin mutlaka elektronik imza ile gönderilmesi","Başvuru sahibinin belgeyi bizzat kurum arşivinden alıp götürmesi"],"dogru":0,"aciklama":"m.4/e: erişim, niteliğine göre öncelikle başvuru sahibine bilgi veya belgenin bir kopyasının verilmesini; kopya verilmesinin mümkün olmadığı hâllerde aslını inceleyerek not alma, içeriğini görme veya işitmeye izin verilmesini ifade eder. Önceliklenen yol kopya verilmesidir.","kaynak":"Yönetmelik m.4/e","zorluk":"orta"},
    {"id":"BILGIEDINME-S-009","soru":"Yönetmeliğin 4. maddesindeki 'Belge' tanımına göre aşağıdakilerden hangisi doğrudur?","siklar":["Belge yalnızca yazılı ve basılı evrakı kapsar; dijital kayıtlar belge sayılmaz","Elektronik ortamda kaydedilen her türlü bilgi, haber ve veri taşıyıcıları da belge tanımına dâhildir","Yalnızca resmi mühür taşıyan evrak belge sayılır","Film, fotoğraf ve video kasetleri belge tanımı dışındadır","Belge tanımı yalnızca kurum içi yazışmaları kapsar"],"dogru":1,"aciklama":"m.4/d 'Belge' tanımı; yazılı, basılı veya çoğaltılmış dosya, evrak, kitap, dergi, film, fotoğraf, teyp ve video kaseti, harita ile 'elektronik ortamda kaydedilen her türlü bilgi, haber ve veri taşıyıcılarını' kapsayacak şekilde geniş tutulmuştur.","kaynak":"Yönetmelik m.4/d","zorluk":"orta"},
    {"id":"BILGIEDINME-S-010","soru":"Yönetmeliğin 5. maddesine (Bilgi edinme hakkı) göre aşağıdaki ifadelerden hangisi YANLIŞTIR?","siklar":["Herkes, Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir.","Türkiye'de faaliyette bulunan yabancı tüzel kişiler de belirli şartlarla Kanun ve Yönetmelik hükümlerinden yararlanır.","Yabancıların bu kapsamdaki başvuruları Türkçe olarak yapılır.","Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükler bu Yönetmelik karşısında ortadan kalkar.","Yabancıların yararlanması, istedikleri bilginin kendileri veya faaliyet alanlarıyla ilgili olması ve karşılıklılık ilkesi şartına bağlıdır."],"dogru":3,"aciklama":"m.5 son cümlesi: 'Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükleri saklıdır.' Bu hak ve yükümlülükler ortadan kalkmaz; D ifadesi madde metnine aykırıdır. A (Herkes), B (yabancı tüzel kişiler), C (Türkçe başvuru) ve E (ilgi + karşılıklılık) madde metnine uygundur.","kaynak":"Yönetmelik m.5","zorluk":"orta"},
    {"id":"BILGIEDINME-S-011","soru":"Yönetmeliğin 5. maddesine göre: '..............., Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir.' Boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?","siklar":["Herkes","Yalnızca Türk vatandaşları","Yalnızca kamu görevlileri","Onsekiz yaşını doldurmuş Türk vatandaşları","Yalnızca seçmen niteliğine sahip kişiler"],"dogru":0,"aciklama":"m.5/1: 'Herkes, Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir.' Hak sahibi herhangi bir sınırlama olmaksızın 'herkes'tir.","kaynak":"Yönetmelik m.5","zorluk":"kolay"},
    {"id":"BILGIEDINME-S-012","soru":"Yönetmeliğin 5. maddesine göre, Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükler bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Uluslararası sözleşme hükümleri bu Yönetmelik karşısında hiçbir şekilde uygulanmaz.","Bu hak ve yükümlülükler yalnızca Dışişleri Bakanlığının onayıyla geçerli olur.","Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükleri saklıdır.","Uluslararası sözleşmeler ancak karşılıklılık ülkeleri Resmi Gazetede ilan edilmişse dikkate alınır.","Bu Yönetmelik, uluslararası sözleşmelerden doğan tüm hak ve yükümlülükleri yürürlükten kaldırır."],"dogru":2,"aciklama":"m.5 son cümlesi: 'Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükleri saklıdır.' Bu haklar bu Yönetmelikten etkilenmeksizin korunur.","kaynak":"Yönetmelik m.5","zorluk":"orta"},
    {"id":"BILGIEDINME-S-013","soru":"Yönetmeliğin 5. maddesine göre, Türkiye'de ikamet eden yabancılar ile faaliyette bulunan yabancı tüzel kişilerin bu kapsamdaki başvuruları, başvuru sahibinin kendi ana dilinde yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5: 'Bu kapsamdaki başvurular Türkçe olarak yapılır.' Dolayısıyla başvuru ana dilde değil, Türkçe yapılır; ifade yanlıştır.","kaynak":"Yönetmelik m.5","zorluk":"orta"},
    {"id":"BILGIEDINME-OO-001","soru":"Vatandaş A, aynı gün üç ayrı başvuru hazırlar: (1) bağlı bulunduğu (X) köyü tüzel kişiliğine, (2) bir devlet üniversitesi rektörlüğüne, (3) bir baroya (kamu kurumu niteliğindeki meslek kuruluşu). Yönetmeliğin 2. maddesindeki KAPSAM kuralı uyarınca bu başvurulardan hangisi/hangileri bakımından bu Yönetmelik UYGULANMAZ?","siklar":["Yalnızca köye yapılan başvuru (1)","Yalnızca üniversiteye yapılan başvuru (2)","Yalnızca baroya yapılan başvuru (3)","Üniversite ve baroya yapılan başvurular (2 ve 3)","Her üç başvuru da kapsam dışıdır"],"dogru":0,"aciklama":"m.2'ye göre mahalli idareler 'köyler hariç olmak üzere' kapsamdadır; üniversiteler 'de dahil olmak üzere' açıkça sayılmış, kamu kurumu niteliğindeki meslek kuruluşları (baro/oda) da kapsama alınmıştır. Bu nedenle Yönetmelik yalnızca köye yapılan başvuruya uygulanmaz.","kaynak":"Yönetmelik m.2","zorluk":"orta"},
    {"id":"BILGIEDINME-OO-002","soru":"Başvuru sahibi B, bir kamu kurumundan belirli bir belgeyi ister. Belgenin kopyasının verilmesi niteliği bakımından mümkündür. Görevli memur, 'belge zaten arşivimizde, gelip aslını masada inceleyip not alabilirsiniz, kopya vermeyiz' der. Yönetmeliğin 4. maddesindeki 'bilgi veya belgeye erişim' tanımına göre memurun bu uygulaması hakkında ne söylenebilir?","siklar":["Doğrudur; erişim her hâlde aslı yerinde inceletmek suretiyle sağlanır","Yanlıştır; kopya verilmesi mümkün olduğundan öncelikle belgenin bir kopyası verilmelidir","Doğrudur; kopya yalnızca yabancı başvuru sahiplerine verilir","Yanlıştır; belgenin aslı kalıcı olarak başvuru sahibine teslim edilmelidir","Doğrudur; erişim biçimini seçmek tamamen başvuru sahibinin takdirindedir"],"dogru":1,"aciklama":"m.4/e: erişim öncelikle bilgi veya belgenin bir KOPYASININ verilmesini; kopya verilmesinin mümkün OLMADIĞI hâllerde aslını inceleyerek not alma/görme/işitmeye izin verilmesini ifade eder. Kopya mümkün olduğuna göre öncelik kopya vermektedir; memurun 'kopya vermeyiz, gelip inceleyin' uygulaması tanıma aykırıdır.","kaynak":"Yönetmelik m.4/e","zorluk":"orta"},
    {"id":"BILGIEDINME-OO-003","soru":"Türkiye'de ikamet eden yabancı uyruklu C, ülkesiyle Türkiye arasında karşılıklılık ilkesinin bulunduğu bir devletin vatandaşıdır. C, kendisiyle veya faaliyet alanıyla HİÇBİR ilgisi bulunmayan, tamamen genel nitelikli bir konuda bilgi edinme başvurusu yapar. Yönetmeliğin 5. maddesine göre C'nin durumu nasıl değerlendirilir?","siklar":["Karşılıklılık bulunduğundan, ilgi şartı aranmaksızın her konuda başvuru yapabilir","İstenen bilgi kendisiyle veya faaliyet alanıyla ilgili olmadığından, bu kapsamda yararlanma şartları oluşmamıştır","Yabancı olduğundan hiçbir koşulda bilgi edinme hakkından yararlanamaz","Türkçe başvurması koşuluyla, ilgi şartı tamamen ortadan kalkar","İlgi şartı yalnızca yabancı tüzel kişiler için aranır; gerçek kişilerde aranmaz"],"dogru":1,"aciklama":"m.5: Türkiye'de ikamet eden yabancılar, isteyecekleri bilgi 'kendileriyle veya faaliyet alanlarıyla ilgili olmak kaydıyla VE karşılıklılık ilkesi çerçevesinde' yararlanır. İki şart birliktedir. Karşılıklılık olsa dahi 'ilgi' şartı gerçekleşmediğinden bu kapsamda yararlanma şartları oluşmamıştır.","kaynak":"Yönetmelik m.5","zorluk":"zor"},
    {"id":"BILGIEDINME-OO-004","soru":"Türkiye'de faaliyette bulunan yabancı tüzel kişi (D) şirketi, ilgi ve karşılıklılık şartlarını taşıdığı bir konuda bir kamu kurumuna bilgi edinme başvurusunu kendi şirket dilinde, İngilizce olarak sunar. Yönetmeliğin 5. maddesi bakımından bu başvurunun dili hakkında ne söylenir?","siklar":["Başvuru İngilizce yapılabilir; dil bakımından bir zorunluluk yoktur","Bu kapsamdaki başvurular Türkçe olarak yapılır; başvurunun Türkçe sunulması gerekir","Başvuru yabancı dilde yapılır, kurum resen Türkçeye çevirir","Başvuru, başvuranın ülkesinin resmi dilinde yapılmak zorundadır","Dil serbestisi yalnızca karşılıklılık ülkeleri için geçerlidir"],"dogru":1,"aciklama":"m.5: 'Bu kapsamdaki başvurular Türkçe olarak yapılır.' Yabancı gerçek ve tüzel kişilerin bu kapsamdaki başvuruları için dil Türkçedir; İngilizce verilen başvuru bu yönüyle usule uygun değildir.","kaynak":"Yönetmelik m.5","zorluk":"orta"},
    {"id":"BILGIEDINME-OO-005","soru":"Lise öğrencisi E (17 yaşında, Türk vatandaşı), bir kamu kurumundan bir konuda bilgi edinme başvurusu yapmak ister. Görevli, 'siz reşit değilsiniz, ayrıca kamu görevlisi de değilsiniz; bu hak yalnızca onsekiz yaşını doldurmuş kişilere tanınmıştır' diyerek başvuruyu reddeder. Yönetmeliğin 5. maddesine göre bu ret işlemi yerinde midir?","siklar":["Yerindedir; bilgi edinme hakkı onsekiz yaşını doldurma şartına bağlıdır","Yerindedir; bu hak yalnızca kamu görevlilerine tanınmıştır","Yerinde değildir; bilgi edinme hakkı 'herkes'e tanınmıştır, yaş veya sıfat şartı öngörülmemiştir","Yerindedir; hak yalnızca seçmen niteliğine sahip kişiler içindir","Yerinde değildir; ancak hak yalnızca Türk vatandaşı yetişkinler için geçerlidir"],"dogru":2,"aciklama":"m.5/1: 'Herkes, Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir.' Madde yaş, kamu görevi veya seçmenlik gibi bir şart aramaz; ret işlemi madde metnine aykırıdır.","kaynak":"Yönetmelik m.5","zorluk":"kolay"},
  ],
  20: [
    {"id":"2521-S-001","soru":"2521 sayılı Yönetmelik'e göre, 2521 sayılı Kanunun 9 uncu maddesi gereğince düzenlenen yivsiz tüfek ruhsatnamesi, verildiği tarihten geçerli olmak üzere kaç yıl süreli düzenlenir?","siklar":["2 yıl","3 yıl","4 yıl","5 yıl","6 yıl"],"dogru":3,"aciklama":"Yön. m.10/b: Yivsiz tüfek ruhsatnamesi harcının ödenmiş olması kaydıyla, verildiği tarihten geçerli olmak üzere 5 yıl süreli düzenlenir; bu belge bulundurma ve meskun mahaller dışında kırsal alanda taşıma yetkisi sağlar.","kaynak":"Yön. m.10/b","zorluk":"orta"},
    {"id":"2521-S-002","soru":"2521 sayılı Yönetmelik'e göre, yivsiz tüfek ruhsatnamesi illerin merkez ilçelerinde valiler tarafından verilir. İlçelerde ise bu belge hangi makamca verilir?","siklar":["Belediye başkanlarınca","İl emniyet müdürlerince","İlçe jandarma komutanlarınca","Bölge valilerince","Kaymakamlarca"],"dogru":4,"aciklama":"Yön. m.10/b: Yivsiz tüfek ruhsatnamesi illerin merkez ilçelerinde valiler, ilçelerde kaymakamlarca verilir.","kaynak":"Yön. m.10/b","zorluk":"orta"},
    {"id":"2521-S-003","soru":"2521 sayılı Yönetmelik'e göre, yivsiz tüfek ruhsatnamesine sahip kişi, tüfeğini köy, kasaba veya şehir içinde nasıl taşıyıp nakletmek zorundadır?","siklar":["Omuzunda açıkta ve dolu olarak","Belinde dolu vaziyette hazır şekilde","Boş olarak torba veya kılıf içinde ya da aracın bagajında","Elinde kullanıma hazır şekilde","Herhangi bir koşul olmaksızın serbestçe"],"dogru":2,"aciklama":"Yön. m.10/b: Söz konusu tüfeklerin köy, kasaba veya şehir içinde boş olarak torba veya kılıf içerisinde ya da araçların bagajında taşınıp nakledilmesi zorunludur. Açık/dolu taşıma yalnızca meskun mahaller dışında kırsal alanda mümkündür.","kaynak":"Yön. m.10/b","zorluk":"orta"},
    {"id":"2521-S-004","soru":"2521 sayılı Yönetmelik'e göre, yivsiz tüfek ruhsatnamesi tüfek sahibine bulundurma ve meskun mahaller dışında kırsal alanda taşıma yetkisi sağlar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yön. m.10/b: Ruhsatname tüfek sahibine bulundurma ve meskun mahaller dışında kırsal alanda taşıma yetkisi sağlar. İfade doğrudur.","kaynak":"Yön. m.10/b","zorluk":"kolay"},
    {"id":"2521-S-005","soru":"2521 sayılı Yönetmelik'e göre, en az iki yıl süreli ikamet tezkeresi alan yabancılara, karşılıklılık ilkesi gözetilmek suretiyle yivsiz tüfek ruhsatnamesi hangi usulle verilir?","siklar":["Doğrudan valilerce, başka makamın görüşü aranmaksızın","Yalnızca İçişleri Bakanlığınca","Sanayi ve Teknoloji Bakanlığının onayıyla","Dışişleri Bakanlığının önerisi ve İçişleri Bakanlığının uygun görmesi üzerine valilerce","Emniyet Genel Müdürlüğünce"],"dogru":3,"aciklama":"Yön. m.10/b: En az iki yıl süreli ikamet tezkeresi alan yabancılara, karşılıklılık ilkesi gözetilmek suretiyle Dışişleri Bakanlığının önerisi ve İçişleri Bakanlığının uygun görmesi üzerine valilerce yivsiz tüfek ruhsatnamesi verilir.","kaynak":"Yön. m.10/b","zorluk":"zor"},
    {"id":"2521-S-006","soru":"2521 sayılı Yönetmelik'e göre, 18 yaşını bitirmemiş atıcılık lisansına sahip kimseler; veli, yönetici veya idarecilerin sorumluluğu altında silahlarını hangi izinle ve nerede taşıyıp kullanabilir?","siklar":["İçişleri Bakanlığı izniyle her yerde","Valilik izniyle meskun mahalde","Hiçbir şekilde taşıyıp kullanamaz","Türkiye Atıcılık ve Avcılık Federasyonunca düzenlenecek özel izinle, atış poligonlarında veya sportif faaliyetlerin yapıldığı alanlarda","Emniyet izniyle avlaklarda"],"dogru":3,"aciklama":"Yön. m.10/b: 18 yaşını bitirmemiş atıcılık lisanslı kimseler, veli/yönetici/idarecilerin sorumluluğu altında, Türkiye Atıcılık ve Avcılık Federasyonunca düzenlenecek özel izinle, atış poligonlarında veya sportif faaliyetlerin yapıldığı alanlarda taşıyıp kullanabilir.","kaynak":"Yön. m.10/b","zorluk":"zor"},
    {"id":"2521-S-007","soru":"2521 sayılı Yönetmelik'e göre, satıcılık (bayilik) belgesi 5 yıl, yivsiz tüfek ruhsatnamesi ise 3 yıl süreli düzenlenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"İfade terstir. Yön. m.10: Satıcılık (bayilik) belgesi 3 yıl, yivsiz tüfek ruhsatnamesi 5 yıl süreli düzenlenir.","kaynak":"Yön. m.10","zorluk":"orta"},
    {"id":"2521-S-008","soru":"2521 sayılı Yönetmelik'in belge ve ruhsat işlemlerine ilişkin aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Satıcılık (bayilik) belgesi illerde münhasıran valilerce verilir","Yivsiz tüfek ruhsatnamesi merkez ilçelerde valilerce verilir","Yivsiz tüfek ruhsatnamesi ilçelerde kaymakamlarca verilir","Satıcılık (bayilik) belgesi ilçelerde kaymakamlarca da verilebilir","Satıcılık (bayilik) belgesi almak isteyenler valiliğe müracaat eder"],"dogru":3,"aciklama":"Yön. m.10/a: Satıcılık (bayilik) belgesi illerde MÜNHASIRAN valilerce verilir; ilçelerde kaymakamlara verdirilmez. D yanlıştır. Yalnız yivsiz tüfek ruhsatnamesi ilçelerde kaymakamlarca verilir.","kaynak":"Yön. m.10","zorluk":"zor"},
    {"id":"2521-S-009","soru":"2521 sayılı Yönetmelik'e göre, satıcılık (bayilik) belgesi illerde münhasıran kaymakamlarca verilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"İfade yanlıştır. Yön. m.10/a: Satıcılık (bayilik) belgesi illerde MÜNHASIRAN valilerce verilir; kaymakamlarca değil.","kaynak":"Yön. m.10/a","zorluk":"orta"},
    {"id":"2521-S-010","soru":"2521 sayılı Yönetmelik'e göre, satın alma belgesiyle satın alınan av tüfeklerinin, en geç ne kadar süre içinde belgenin alındığı makama müracaatla cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur?","siklar":["15 gün","1 ay","3 ay","6 ay","1 yıl"],"dogru":1,"aciklama":"Yön. m.13: Satın alınan av tüfeklerinin en geç bir ay içerisinde belgenin alındığı makama müracaatla cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-S-011","soru":"2521 sayılı Yönetmelik'e göre, ruhsatname üzerine tüfeklerin kaydedilmesi işlemi esnasında tüfeklerin görülerek tespitinin yapılması esastır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yön. m.13: Ruhsatname üzerine tüfeklerin kaydedilmesi işlemi esnasında tüfeklerin görülerek tespitinin yapılması esastır. İfade doğrudur.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-S-012","soru":"2521 sayılı Yönetmelik'e göre, av tüfeği satın almak isteyenler, silah imal eden ya da satan kişi ve kuruluşlardan hangi belge ile bu silahları satın alabilir?","siklar":["Satıcılık (bayilik) belgesi","Av tezkeresi","Yivsiz tüfek satın alma belgesi","Faaliyet izni belgesi","İşletme belgesi"],"dogru":2,"aciklama":"Yön. m.13: Bu silahları satın almak isteyenler, silah imal eden ya da satan kişi ve kuruluşlardan yivsiz tüfek satın alma belgesi ile satın alabilir.","kaynak":"Yön. m.13","zorluk":"kolay"},
    {"id":"2521-S-013","soru":"2521 sayılı Yönetmelik'e göre, satın alınan av tüfeklerinin en geç bir ay içinde belgenin alındığı makama müracaatla cins, marka, çap ve ____ kaydettirilmesi zorunludur.","siklar":["üretim yılının","satış fiyatının","imalatçı adresinin","tüfeğin ağırlığının","seri numarasının"],"dogru":4,"aciklama":"Yön. m.13: Satın alınan tüfeklerin cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-S-014","soru":"2521 sayılı Yönetmelik'e göre, av tüfeği taşıma ve bulundurmalarında engel bulunmayanlara yivsiz tüfek ruhsatnamesi hangi makamca düzenlenir?","siklar":["Sanayi ve Teknoloji Bakanlığınca","Türk Standartları Enstitüsünce","Belediyelerce","Mahalli mülki amirliklerce","Jandarma Genel Komutanlığınca"],"dogru":3,"aciklama":"Yön. m.13: Av tüfeği taşıma ve bulundurmalarında engel bulunmayanlara mahalli mülki amirliklerce yivsiz tüfek ruhsatnamesi düzenlenir.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-S-015","soru":"2521 sayılı Yönetmelik m.14'e göre, 6136 sayılı Kanunun 12, 13, 14 ve 15 inci maddelerinde belirtilen suçlardan dolayı ____ hürriyeti bağlayıcı cezaya mahkum olanlara belge ve izin verilmez.","siklar":["3 aydan fazla","6 aydan fazla","1 yıldan fazla","2 yıldan fazla","6 aydan az"],"dogru":1,"aciklama":"Yön. m.14/g: 6136 sayılı Kanunun 12, 13, 14 ve 15 inci maddelerindeki suçlardan dolayı 6 aydan fazla hürriyeti bağlayıcı cezaya mahkum olanlar ile aynı Kanunun 4 üncü maddesindeki yasak aletlerden birini kullanarak suç işleyip mahkum olanlara belge verilmez.","kaynak":"Yön. m.14/g","zorluk":"zor"},
    {"id":"2521-S-016","soru":"2521 sayılı Yönetmelik m.14'e göre, ateşli silahla işlenenler ile taksirli suçlar hariç, kaç yıldan fazla hürriyeti bağlayıcı cezaya mahkum olanlara belge ve izin verilmez?","siklar":["1 yıldan fazla","2 yıldan fazla","3 yıldan fazla","5 yıldan fazla","10 yıldan fazla"],"dogru":1,"aciklama":"Yön. m.14/e: Ateşli silahla işlenenler ile taksirli suçlar hariç iki yıldan fazla hürriyeti bağlayıcı cezaya mahkum olanlara belge ve izin verilmez.","kaynak":"Yön. m.14/e","zorluk":"zor"},
    {"id":"2521-S-017","soru":"2521 sayılı Yönetmelik m.14'e göre, ateşli silahla işlenenler ile taksirli suçlar hariç, değişik zamanlarda işlediği aynı veya farklı türden ____ suçtan dolayı hapis veya ağır hapis ve/veya ağır para cezasına mahkum olanlara belge ve izin verilmez.","siklar":["bir","üçten az","ondan fazla","ikiden fazla","beşten fazla"],"dogru":3,"aciklama":"Yön. m.14/d: Değişik zamanlarda işlediği aynı veya farklı türden ikiden fazla suçtan dolayı hapis/ağır hapis ve/veya ağır para cezasına mahkum olanlara belge verilmez.","kaynak":"Yön. m.14/d","zorluk":"zor"},
    {"id":"2521-S-018","soru":"2521 sayılı Yönetmelik m.14'te belge/izin engeli bakımından belirtilen mahkumiyet, kesinleşmiş mahkumiyettir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yön. m.14: Bu maddede belirtilen mahkumiyet, kesinleşmiş mahkumiyettir. İfade doğrudur.","kaynak":"Yön. m.14","zorluk":"orta"},
    {"id":"2521-S-019","soru":"2521 sayılı Yönetmelik m.14'ün uygulanmasında, mahkemelerce verilen hürriyeti bağlayıcı cezalar paraya çevrilmiş olsa dahi, ____ esas alınır.","siklar":["para cezası","en hafif ceza","hürriyeti bağlayıcı ceza","ertelenmiş ceza","ilk verilen ceza"],"dogru":2,"aciklama":"Yön. m.14: Mahkemelerce verilen hürriyeti bağlayıcı cezalar, paraya çevrilmiş olsa dahi, hürriyeti bağlayıcı ceza esas alınır.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-S-020","soru":"2521 sayılı Yönetmelik m.14'e göre, (a)-(h) bentleri kapsamına girenler, affa uğramış olsalar veya mahkumiyetleri adli sicilden silinmiş olsa bile kendilerine bu Yönetmelik kapsamına giren belge ve izinler verilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yön. m.14: (a)-(h) bentleri kapsamına girenler, affa uğramış olsalar veya mahkumiyetleri bütün neticeleriyle birlikte ortadan kalksa ya da adli sicilden silinmiş olsa bile kendilerine hiçbir suretle belge ve izin verilmez. İfade doğrudur.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-S-021","soru":"2521 sayılı Yönetmelik m.14'e göre, (a)-(h) bentlerindeki kalıcı belge engeli (af veya sicilden silinmeye rağmen süren engel), Türk Ceza Kanununun 7 nci maddesi hükümlerine göre hangi kişilere uygulanmaz?","siklar":["Affa uğrayanlara","Mahkumiyeti adli sicilden silinenlere","Suç olmaktan çıkan bir fiil nedeniyle hüküm giymiş olanlara","Cezası ertelenmiş olanlara","18 yaşını bitirmiş olanlara"],"dogru":2,"aciklama":"Yön. m.14: a-h bentleri ve af/silinme kuralı, Türk Ceza Kanununun 7 nci maddesi hükümlerine göre suç olmaktan çıkan bir fiil nedeniyle hüküm giymiş olanlara uygulanmaz. Tek istisna budur.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-S-022","soru":"2521 sayılı Yönetmelik m.14'e göre, aşağıdakilerden hangisi kişinin hâline ilişkin (kişisel) engel hâllerinden biri DEĞİLDİR?","siklar":["Kısıtlı olmak","Kamu hizmetinden yasaklı olmak","Akıl hastası veya psikolojik ve nörolojik rahatsızlığı olmak","18 yaşını bitirmemiş olmak","Uyuşturucu ve psikotrop madde suçlarından mahkum olmak"],"dogru":4,"aciklama":"Yön. m.14: Kişisel (kişi hâli) engeller ı) kısıtlı/kamu hizmetinden yasaklı, i) akıl hastası/nörolojik rahatsızlık, j) 18 yaşını bitirmemiş olma bentleridir. Uyuşturucu suçundan mahkumiyet ise (h) bendindeki bir SUÇ hâlidir, kişisel hâl değildir.","kaynak":"Yön. m.14","zorluk":"orta"},
    {"id":"2521-S-023","soru":"2521 sayılı Yönetmelik m.14'e göre, ruhsatlı silahı ile suç işleyen veya silahın muhafazasındaki ihmal ve/veya kusuru neticesi başkaları tarafından suç işlenmesine ya da intihara teşebbüs edilmesine neden olmaktan mahkum olanlara belge ve izin verilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yön. m.14/b: Ruhsatlı silahıyla suç işleyenler veya silahın muhafazasındaki ihmal/kusur neticesi başkalarınca suç işlenmesine ya da intihar/intihara teşebbüse neden olmaktan mahkum olanlara belge verilmez. İfade doğrudur.","kaynak":"Yön. m.14/b","zorluk":"orta"},
    {"id":"2521-S-024","soru":"2521 sayılı Yönetmelik m.14'e göre, zorunlu olmadığı halde meskun mahalde veya umuma mahsus yola doğru silah atmaktan mahkum olan bir kişiye, mahkumiyetin üzerinden zaman geçtikten sonra av bıçağı bulundurma belgesi verilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"İfade yanlıştır. Yön. m.14/c bu hâli belge engeli sayar; üstelik a-h bentlerinde af, sicil silinmesi veya zaman geçmesi engeli kaldırmaz. Bu kişiye belge verilmez.","kaynak":"Yön. m.14/c","zorluk":"zor"},
    {"id":"2521-OO-001","soru":"Avcılığa meraklı (A), geçmişte ateşli silahla işlenmemiş ve taksirli de olmayan bir suçtan 2 yıl 6 ay hapis cezasına çarptırılmış ve bu mahkumiyet kesinleşmiştir. (A), av tüfeği bulundurmak için yivsiz tüfek ruhsatnamesi almak üzere mahalli mülki amirliğe başvurmuştur. 2521 sayılı Yönetmelik'e göre bu başvuruyla ilgili yapılacak işlem aşağıdakilerden hangisidir?","siklar":["Suç ateşli silahla işlenmediğinden belge verilir","Ceza iki yıldan fazla hürriyeti bağlayıcı ceza olduğundan belge ve izin verilmez","Yalnızca taşıma değil bulundurma istendiği için belge verilir","Ceza beş yılı aşmadığından belge verilir","Cezanın yarısı infaz edilmişse belge verilir"],"dogru":1,"aciklama":"Yön. m.14/e: Ateşli silahla işlenenler ile taksirli suçlar hariç iki yıldan fazla hürriyeti bağlayıcı cezaya mahkum olanlara belge ve izin verilmez. 2 yıl 6 ay, iki yıldan fazla olduğundan (A)'ya belge verilmez.","kaynak":"Yön. m.14/e","zorluk":"zor"},
    {"id":"2521-OO-002","soru":"(B), yıllar önce ateşli silahla işlediği bir cürümden hükümlü olmuş; sonradan çıkan bir afla cezası ortadan kalkmış ve mahkumiyeti adli sicilden silinmiştir. (B), şimdi av bıçağı bulundurma belgesi almak için başvurmuştur. 2521 sayılı Yönetmelik'e göre nasıl işlem yapılır?","siklar":["Affa uğradığı için belge verilir","Adli sicilden silindiği için belge verilir","Üzerinden uzun zaman geçtiği için belge verilir","Ateşli silahla işlenen cürüm bendine girdiğinden, af ve sicil silinmesine rağmen belge ve izin verilmez","Av bıçağı ateşli silah olmadığından belge verilir"],"dogru":3,"aciklama":"Yön. m.14: (a)-(h) bentleri (a bendi: ateşli silahla işlenen cürümden hükümlü) kapsamına girenler, affa uğramış olsalar veya mahkumiyetleri bütün neticeleriyle ortadan kalksa ya da adli sicilden silinmiş olsa bile kendilerine hiçbir suretle belge ve izin verilmez.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-OO-003","soru":"(C), m.14 kapsamına giren bir suçtan hürriyeti bağlayıcı cezaya mahkum olmuş, ancak mahkeme bu cezayı adli para cezasına çevirmiştir. (C), 'cezam paraya çevrildi, artık hürriyeti bağlayıcı ceza yok' diyerek yivsiz tüfek ruhsatnamesi istemektedir. 2521 sayılı Yönetmelik'e göre değerlendirme nasıl yapılır?","siklar":["Ceza paraya çevrildiğinden artık para cezası esas alınır ve belge verilir","Para cezası, belge engeli doğurmayacağından başvuru kabul edilir","Hürriyeti bağlayıcı ceza paraya çevrilmiş olsa dahi hürriyeti bağlayıcı ceza esas alınır","Cezanın peşin ödenmiş olması hâlinde belge verilir","Paraya çevirme kararı mahkumiyeti tümden ortadan kaldırır"],"dogru":2,"aciklama":"Yön. m.14: Mahkemelerce verilen hürriyeti bağlayıcı cezalar, paraya çevrilmiş olsa dahi, hürriyeti bağlayıcı ceza esas alınır. Dolayısıyla (C) açısından engel devam eder.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-OO-004","soru":"17 yaşındaki (D), babasının yanında avlanmak için kendi adına yivsiz tüfek ruhsatnamesi almak istemekte ve bu amaçla mahalli mülki amirliğe başvurmaktadır. (D)'nin herhangi bir mahkumiyeti veya sağlık sorunu yoktur. 2521 sayılı Yönetmelik'e göre bu başvuruyla ilgili doğru ifade hangisidir?","siklar":["Sağlık ve sabıka engeli olmadığından ruhsatname verilir","Velisinin izniyle 16 yaşından itibaren ruhsatname verilebilir","18 yaşını bitirmemiş olanlara belge ve izin verilmeyeceğinden başvuru kabul edilmez","15 yaşını dolduran herkese ruhsatname verilir","Yalnızca kırsal alanda taşıma şartıyla ruhsatname verilir"],"dogru":2,"aciklama":"Yön. m.14/j: 18 yaşını bitirmemiş olanlara hiçbir şekilde belge ve izin verilmez. (D) 17 yaşında olduğundan kendi adına ruhsatname alamaz. (Atıcılık lisanslı 18 yaş altına yalnızca veli/idareci sorumluluğunda, federasyonun özel izniyle poligon/sportif alanda taşıma istisnası tanınır; bu, kişisel ruhsatname değildir.)","kaynak":"Yön. m.14/j","zorluk":"orta"},
    {"id":"2521-OO-005","soru":"(E) hakkında m.14 kapsamına giren bir suçtan yerel mahkemece hapis cezası verilmiş; ancak (E) kararı istinaf/temyiz etmiş ve mahkumiyet henüz kesinleşmemiştir. (E) bu sırada yivsiz tüfek ruhsatnamesi başvurusunda bulunmuştur. 2521 sayılı Yönetmelik m.14 bakımından doğru değerlendirme hangisidir?","siklar":["Henüz kesinleşmemiş de olsa mahkumiyet bulunduğundan belge mutlaka reddedilir","m.14'teki engel kesinleşmiş mahkumiyete bağlı olduğundan, kesinleşmemiş bu mahkumiyet tek başına m.14 engelini tetiklemez","İlk derece kararı yeterli olduğundan başvuru daima reddedilir","Temyiz başvurusu mahkumiyeti ağırlaştırır, belge verilmez","Kesinleşme aranmaz; iddianame düzenlenmesi belge engeli için yeterlidir"],"dogru":1,"aciklama":"Yön. m.14: Bu maddede belirtilen mahkumiyet, kesinleşmiş mahkumiyettir. Henüz kesinleşmemiş (kanun yolunda olan) bir mahkumiyet, m.14 engelini tek başına tetiklemez.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-OO-006","soru":"(F), geçmişte bir fiilden dolayı mahkum olmuş ve mahkumiyeti kesinleşmiştir. Daha sonra yapılan bir kanun değişikliğiyle (F)'nin mahkum olduğu fiil suç olmaktan çıkarılmıştır. (F) şimdi yivsiz tüfek ruhsatnamesi başvurusu yapmaktadır. 2521 sayılı Yönetmelik m.14 bakımından doğru ifade hangisidir?","siklar":["Mahkumiyet kesinleştiği için af veya sicil silinmesine bakılmaksızın engel kalıcıdır","Türk Ceza Kanununun 7 nci maddesi gereği suç olmaktan çıkan bir fiilden hüküm giyene a-h kalıcılık kuralı uygulanmaz","Fiilin sonradan suç olmaktan çıkması belge başvurusunu hiçbir biçimde etkilemez","Belge ancak yeni bir kanunla ayrıca izin verilmesi hâlinde verilir","Suç olmaktan çıkma yalnızca taksirli suçlar için engeli kaldırır"],"dogru":1,"aciklama":"Yön. m.14: a-h bentleri ve af/silinmeye rağmen süren kalıcı engel, Türk Ceza Kanununun 7 nci maddesi hükümlerine göre suç olmaktan çıkan bir fiil nedeniyle hüküm giymiş olanlara uygulanmaz. Bu, a-h kalıcılık engelinin tek istisnasıdır.","kaynak":"Yön. m.14","zorluk":"zor"},
    {"id":"2521-OO-007","soru":"Yivsiz tüfek ruhsatnamesi bulunan (A), avdan dönerken şehir merkezinden geçerken tüfeğini omzunda açıkta ve dolu vaziyette taşırken jandarma devriyesince durdurulmuştur. 2521 sayılı Yönetmelik'e göre (A)'nın taşıma biçimine ilişkin doğru değerlendirme hangisidir?","siklar":["Ruhsatnamesi olduğundan tüfeği her yerde dolu ve açıkta taşıyabilir, işlem gerekmez","Tüfeğini köy, kasaba veya şehir içinde boş olarak torba/kılıf içinde ya da aracın bagajında taşıması gerekirdi; bu kurala aykırı davranmıştır","Şehir içinde yalnızca belinde gizleyerek taşıması yeterlidir","Tüfeği dolu fakat namlu yere bakacak şekilde taşıması yeterlidir","Avdan dönüş hâlinde şehir içinde açık taşıma serbesttir"],"dogru":1,"aciklama":"Yön. m.10/b: Ruhsatname bulundurma ve meskun mahaller dışında kırsal alanda taşıma yetkisi verir; söz konusu tüfeklerin köy, kasaba veya şehir içinde boş olarak torba veya kılıf içerisinde ya da araçların bagajında taşınıp nakledilmesi zorunludur. (A)'nın şehir içinde dolu ve açık taşıması bu hükme aykırıdır.","kaynak":"Yön. m.10/b","zorluk":"orta"},
    {"id":"2521-OO-008","soru":"Bir ilçede av tüfeği satıcılığı (bayilik) yapmak isteyen (B), satıcılık (bayilik) belgesi almak için ilçe kaymakamlığına müracaat etmiştir. 2521 sayılı Yönetmelik'e göre bu başvuruyla ilgili doğru ifade hangisidir?","siklar":["Satıcılık (bayilik) belgesi ilçelerde kaymakamlarca verildiğinden başvuru doğru makama yapılmıştır","Satıcılık (bayilik) belgesi illerde münhasıran valilerce verildiğinden başvuru valiliğe yapılmalıdır","Satıcılık (bayilik) belgesi belediye başkanlığınca verilir","Satıcılık (bayilik) belgesi il jandarma komutanlığınca verilir","Satıcılık (bayilik) belgesi doğrudan İçişleri Bakanlığınca verilir"],"dogru":1,"aciklama":"Yön. m.10/a: Satıcılık (bayilik) belgesi illerde münhasıran valilerce verilir. Yivsiz tüfek ruhsatnamesi ilçelerde kaymakamlarca verilebilirken, bayilik belgesi münhasıran valilere özgüdür.","kaynak":"Yön. m.10/a","zorluk":"orta"},
    {"id":"2521-OO-009","soru":"(A), yivsiz tüfek satın alma belgesiyle bir av tüfeği satın almış; ancak yoğunluğu nedeniyle tüfeğin cins, marka, çap ve seri numarasını kaydettirmek için belgenin alındığı makama ancak iki ay sonra başvurmuştur. 2521 sayılı Yönetmelik'e göre (A)'nın durumu hangisidir?","siklar":["Tüfeği bir yıl içinde kaydettirmesi yeterli olduğundan süresinde davranmıştır","Kayıt için süre öngörülmediğinden herhangi bir aykırılık yoktur","Satın alınan tüfeğin en geç bir ay içinde kaydettirilmesi zorunlu olduğundan (A) bu süreyi aşmıştır","Kayıt yalnızca devirde gerekli olduğundan satın almada süre işlemez","Üç ayı aşmadığı sürece kayıt yükümlülüğü ihlal edilmiş sayılmaz"],"dogru":2,"aciklama":"Yön. m.13: Satın alınan av tüfeklerinin en geç bir ay içerisinde belgenin alındığı makama müracaatla cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur. (A) iki ay sonra başvurarak bu süreyi aşmıştır.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-OO-010","soru":"(B), satın aldığı av tüfeğini fiilen yanında götürmeden, yalnızca satış faturası ve seri numarasını gösteren bir belgeyle tüfeğini ruhsatnamesine kaydettirmek istemektedir. 2521 sayılı Yönetmelik'e göre kayıt işlemi nasıl yapılmalıdır?","siklar":["Beyan ve fatura yeterli olup tüfeğin getirilmesine gerek yoktur","Kayıt işleminde tüfeklerin görülerek tespitinin yapılması esastır; tüfek ilgili makama gösterilmelidir","Yalnızca seri numarasının sözlü bildirilmesi yeterlidir","Tüfeğin fotoğrafının ibrazı her hâlde görülerek tespit yerine geçer","Tüfeğin görülmesi yalnızca devir işlemlerinde aranır"],"dogru":1,"aciklama":"Yön. m.13: Ruhsatname üzerine tüfeklerin kaydedilmesi işlemi esnasında tüfeklerin görülerek tespitinin yapılması esastır. Bu nedenle yalnızca fatura/beyan yetmez, tüfeğin fiziken gösterilmesi gerekir.","kaynak":"Yön. m.13","zorluk":"orta"},
    {"id":"2521-OO-011","soru":"(A), ruhsatlı yivsiz av tüfeğini evde kilitsiz ve ortada bırakmış; tüfeği ele geçiren bir başkası onunla suç işlemiştir. (A), silahın muhafazasındaki ihmali/kusuru nedeniyle başkasının suç işlemesine sebep olmaktan kesinleşmiş şekilde mahkum olmuştur. (A)'nın yeni belge başvurusu bakımından 2521 sayılı Yönetmelik'e göre doğru ifade hangisidir?","siklar":["Suçu bizzat (A) işlemediğinden belge engeli doğmaz","Yalnızca taksirli olduğundan engel sayılmaz ve belge verilir","Silahın muhafazasındaki ihmal/kusur sonucu başkasının suç işlemesine neden olmaktan mahkumiyet de belge engelidir; belge ve izin verilmez","Tüfek başkası tarafından kullanıldığından sorumluluk sahibe ait değildir","Mağdur şikayetçi olmazsa belge verilir"],"dogru":2,"aciklama":"Yön. m.14/b: Ruhsatlı silahıyla suç işleyenler veya silahın muhafazasındaki ihmal ve/veya kusuru neticesi başkaları tarafından suç işlenmesine ya da intihar/intihara teşebbüse neden olmaktan mahkum olanlara belge ve izin verilmez.","kaynak":"Yön. m.14/b","zorluk":"zor"},
    {"id":"2521-OO-012","soru":"(C), 6136 sayılı Kanunun 12, 13, 14 ve 15 inci maddelerinde belirtilen suçlardan biri nedeniyle 8 ay hürriyeti bağlayıcı cezaya kesinleşmiş şekilde mahkum olmuştur. (C) yivsiz tüfek ruhsatnamesi başvurusu yapmaktadır. 2521 sayılı Yönetmelik'e göre doğru değerlendirme hangisidir?","siklar":["Ceza iki yılı aşmadığından belge verilir","6136 sayılı Kanunun ilgili suçlarından 6 aydan fazla hürriyeti bağlayıcı cezaya mahkum olduğundan belge ve izin verilmez","6136 suçları için eşik iki yıl olduğundan 8 ay engel oluşturmaz","Yalnızca ateşli silahla işlenen suçlar engel doğurduğundan belge verilir","Ceza bir yılı aşmadığı için belge verilir"],"dogru":1,"aciklama":"Yön. m.14/g: 6136 sayılı Kanunun 12, 13, 14 ve 15 inci maddelerindeki suçlardan dolayı 6 aydan fazla hürriyeti bağlayıcı cezaya mahkum olanlara belge ve izin verilmez. 8 ay, 6 aydan fazla olduğundan (C)'ye belge verilmez.","kaynak":"Yön. m.14/g","zorluk":"zor"},
  ],
  21: [
    {"id":"6284UYG-S-001","soru":"6284 Sayılı Kanuna İlişkin Uygulama Yönetmeliği'ne göre, mülki amir tarafından verilecek koruyucu tedbir kararlarıyla ilgili olarak aşağıdakilerden hangisi YANLIŞTIR?","siklar":["Tedbirlere ilgilinin talebi üzerine karar verilebilir.","Tedbirlere Bakanlık veya kolluk görevlilerinin başvurusu üzerine karar verilebilir.","Mülki amir bu tedbirlere resen de karar verebilir.","Tedbirlere karar verilebilmesi için şiddetin uygulandığına dair delil veya belge bulunması şarttır.","Sayılan tedbirlerin birine, birkaçına veya uygun görülecek benzer tedbirlere karar verilebilir."],"dogru":3,"aciklama":"m.6/1: koruyucu tedbirlere 'delil veya belge aranmaksızın' mülki amir tarafından ilgilinin talebi, Bakanlık veya kolluk görevlilerinin başvurusu üzerine ya da resen karar verilir. Delil/belge bulunması ŞART DEĞİLDİR; bu nedenle D yanlıştır.","kaynak":"6284UYG m.6/1","zorluk":"orta"},
    {"id":"6284UYG-S-002","soru":"Yönetmeliğe göre, hayatî tehlikesinin bulunması hâlinde ilgilinin talebi üzerine veya resen geçici koruma altına alınmasına aşağıdakilerden hangisi karar verir?","siklar":["Aile mahkemesi hâkimi","Mülki amir","Cumhuriyet savcısı","Kolluk amiri","ŞÖNİM müdürü"],"dogru":1,"aciklama":"m.6/1-ç: geçici koruma altına alma, mülki amir tarafından verilecek koruyucu tedbirler arasındadır.","kaynak":"6284UYG m.6/1-ç","zorluk":"kolay"},
    {"id":"6284UYG-S-003","soru":"Yönetmeliğe göre, aşağıdakilerden hangisi HÂKİM tarafından şiddet uygulayanla ilgili olarak verilecek ÖNLEYİCİ tedbirlerden biri değildir?","siklar":["Tapu kütüğüne aile konutu şerhi konulması","Müşterek konuttan veya bulunduğu yerden derhâl uzaklaştırılması","Korunan kişilerin bulundukları konuta, okula ve işyerine yaklaşmaması","Bulundurulması veya taşınmasına kanunen izin verilen silahları kolluğa teslim etmesi","Korunan kişiyi iletişim araçlarıyla veya sair surette rahatsız etmemesi"],"dogru":0,"aciklama":"Önleyici tedbirler (m.17) şiddet uygulayana yöneliktir: uzaklaştırma (b), yaklaşmama (c), silah teslimi (g), iletişimle rahatsız etmeme (f). Tapu kütüğüne aile konutu şerhi konulması ise m.12/1-c uyarınca KORUYUCU bir tedbirdir; önleyici değildir.","kaynak":"6284UYG m.17/1","zorluk":"orta"},
    {"id":"6284UYG-S-004","soru":"Yönetmeliğe göre, aşağıdakilerden hangisi HÂKİM tarafından korunan kişilerle ilgili olarak verilecek KORUYUCU tedbirlerden biridir?","siklar":["Müşterek konuttan derhâl uzaklaştırılması","Bulundurulmasına izin verilen silahları kolluğa teslim etmesi","Korunan kişiyi iletişim araçlarıyla rahatsız etmemesi","Tapu kütüğüne aile konutu şerhi konulması","Korunan kişiye, konutuna, okuluna ve işyerine yaklaşmaması"],"dogru":3,"aciklama":"m.12/1-c: hâkimin koruyucu tedbirleri iş yeri değiştirme (a), evli ise ayrı yerleşim yeri (b), tapuya aile konutu şerhi (c) ve kimlik değiştirme (ç)'dir. Diğer şıklar m.17 önleyici tedbirleridir.","kaynak":"6284UYG m.12/1","zorluk":"orta"},
    {"id":"6284UYG-S-005","soru":"Yönetmeliğe göre, gecikmesinde sakınca bulunan hâllerde kolluk amirince alınan barınma yeri sağlanması ve geçici koruma altına alınması tedbirleri, mülkî amir tarafından ............ içinde onaylanmazsa kendiliğinden kalkar. Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["yirmi dört saat","bir hafta","ilk işgünü","kırk sekiz saat","yetmiş iki saat"],"dogru":3,"aciklama":"m.29/1: kolluk amiri evrakı ilk işgünü içinde mülki amirin onayına sunar; mülki amirce kırk sekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar.","kaynak":"6284UYG m.29/1","zorluk":"zor"},
    {"id":"6284UYG-S-006","soru":"Yönetmeliğe göre, gecikmesinde sakınca bulunan hâllerde kolluk amirince alınan (m.18, 19, 20 ve 22'de belirtilen) önleyici tedbirler, hâkim tarafından kaç saat içinde onaylanmazsa kendiliğinden kalkar?","siklar":["Yirmi dört saat","Kırk sekiz saat","On iki saat","Yetmiş iki saat","Bir hafta"],"dogru":0,"aciklama":"m.29/2: kolluk amiri evrakı ilk işgünü içinde hâkimin onayına sunar; hâkim tarafından yirmi dört saat içinde onaylanmayan tedbirler kendiliğinden kalkar.","kaynak":"6284UYG m.29/2","zorluk":"zor"},
    {"id":"6284UYG-S-007","soru":"Yönetmeliğe göre, hakkındaki tedbir kararına aykırı hareket eden şiddet uygulayana, fiili bir suç oluştursa bile, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim tarafından ilk kez ne kadar zorlama hapsine tâbi tutulmasına karar verilir?","siklar":["Bir günden üç güne kadar","On günden on beş güne kadar","On beş günden otuz güne kadar","Bir aydan iki aya kadar","Üç günden on güne kadar"],"dogru":4,"aciklama":"m.38/5: tedbir kararlarına aykırı hareket eden şiddet uygulayan, fiili bir suç oluştursa bile, üç günden on güne kadar zorlama hapsine tâbi tutulur.","kaynak":"6284UYG m.38/5","zorluk":"orta"},
    {"id":"6284UYG-S-008","soru":"Yönetmeliğe göre, tedbir kararının gereklerine aykırılığın her tekrarında verilecek zorlama hapsinin süresi aşağıdakilerden hangisidir?","siklar":["Üç günden on güne kadar","On beş günden otuz güne kadar","On günden yirmi güne kadar","Bir aydan iki aya kadar","Otuz günden altmış güne kadar"],"dogru":1,"aciklama":"m.38/6: aykırılığın her tekrarında zorlama hapsinin süresi on beş günden otuz güne kadardır; ancak toplam süre altı ayı geçemez.","kaynak":"6284UYG m.38/6","zorluk":"zor"},
    {"id":"6284UYG-S-009","soru":"Yönetmeliğe göre, zorlama hapsi kararları tekerrüre esas olmaz, koşullu salıverilme hükümleri uygulanmaz ve adli sicil kayıtlarına işlenmez. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.38/7: zorlama hapsi kararları tekerrüre esas olmaz, koşullu salıverilme hükümleri uygulanmaz ve adli sicil kayıtlarına işlenmez.","kaynak":"6284UYG m.38/7","zorluk":"orta"},
    {"id":"6284UYG-S-010","soru":"Yönetmeliğe göre, hâkimin tedbir kararlarının uygulanmasında teknik araç ve yöntemler kullanılmasına karar vermesi hâlinde, bu teknik araçlarla kişilerin ses ve görüntü kaydı alınabilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.37/1: hâkim teknik araç ve yöntem kullanılmasına karar verebilir; ancak teknik araçlarla kişilerin ses ve görüntü kaydı ALINAMAZ, kişiler dinlenemez ve izlenemez.","kaynak":"6284UYG m.37/1","zorluk":"orta"},
    {"id":"6284UYG-S-011","soru":"Yönetmeliğe göre, \"Sözlü yapılan şikâyet ve ihbarlar ............ tutanağa geçirilir.\" Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["bir hafta içinde","kırk sekiz saat içinde","derhâl","ilk işgünü içinde","ŞÖNİM'in onayıyla"],"dogru":2,"aciklama":"m.4/5: sözlü yapılan şikâyet ve ihbarlar DERHÂL tutanağa geçirilir; bir süre beklenmez.","kaynak":"6284UYG m.4/5","zorluk":"kolay"},
    {"id":"6284UYG-S-012","soru":"Yönetmeliğe göre, şiddet veya şiddete uğrama tehlikesinden haberdar olan kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları durumu derhâl şikâyet mercilerine bildirmek zorundadır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.4/1: şiddetten haberdar olan kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları durumu derhâl şikâyet mercilerine bildirmek ZORUNDADIR.","kaynak":"6284UYG m.4/1","zorluk":"kolay"},
    {"id":"6284UYG-S-013","soru":"Yönetmelikte geçen \"Hâkim\" ifadesi aşağıdakilerden hangisini ifade eder?","siklar":["Sulh ceza hâkimini","Aile mahkemesi hâkimini","Asliye hukuk hâkimini","Asliye ceza hâkimini","İcra hukuk hâkimini"],"dogru":1,"aciklama":"m.3/1-e: Hâkim, aile mahkemesi hâkimini ifade eder.","kaynak":"6284UYG m.3/1-e","zorluk":"kolay"},
    {"id":"6284UYG-S-014","soru":"Yönetmeliğe göre, aşağıdakilerden hangisi \"kolluk\" tanımına dâhildir?","siklar":["Cumhuriyet başsavcılığı","Şiddet Önleme ve İzleme Merkezi (ŞÖNİM)","Jandarma","Mülki amir","Aile mahkemesi"],"dogru":2,"aciklama":"m.3/1-h: Kolluk; polis, jandarma ve sahil güvenlik birimlerini ifade eder.","kaynak":"6284UYG m.3/1-h","zorluk":"orta"},
    {"id":"6284UYG-S-015","soru":"Yönetmeliğe göre, Şiddet Önleme ve İzleme Merkezindeki (ŞÖNİM) çalışmalar yalnızca haftanın beş günü, mesai saatleri içinde yürütülür. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.3/1-o: ŞÖNİM, çalışmaların yedi gün yirmi dört saat esasına göre yürütüldüğü bir merkezdir; mesai saatleriyle sınırlı değildir.","kaynak":"6284UYG m.3/1-o","zorluk":"orta"},
    {"id":"6284UYG-S-016","soru":"Yönetmeliğe göre, tedbir kararı ilk defasında en çok ne kadar süre için verilebilir?","siklar":["Üç ay","Dokuz ay","Bir yıl","Altı ay","İki yıl"],"dogru":3,"aciklama":"m.30/2: tedbir kararı ilk defasında en çok altı ay için verilebilir; şiddet veya tehlikenin devam edeceğinin anlaşılması hâlinde süresi/şekli değiştirilebilir ya da aynen devam edebilir.","kaynak":"6284UYG m.30/2","zorluk":"kolay"},
    {"id":"6284UYG-S-017","soru":"Yönetmeliğe göre, korunan kişinin nüfus kaydına işlenen gizlilik şerhi, tedbir kararının süresinin sona ermesini takip eden hangi gün MERNİS veri tabanından silinir?","siklar":["Yedinci gün","Onuncu gün","On beşinci gün","Otuzuncu gün","Altmışıncı gün"],"dogru":2,"aciklama":"m.32/6: nüfus kaydına işlenen gizlilik şerhi, tedbir kararının süresinin sona ermesini takip eden on beşinci gün MERNİS veri tabanından silinir.","kaynak":"6284UYG m.32/6","zorluk":"zor"},
    {"id":"6284UYG-S-018","soru":"Yönetmeliğe göre, mülki amir veya hâkim tarafından verilen tedbir kararlarına karşı, tefhim veya tebliğ tarihinden itibaren ne kadar süre içinde aile mahkemesine itiraz edilebilir?","siklar":["Bir hafta","On gün","İki hafta","Bir ay","Otuz gün"],"dogru":2,"aciklama":"m.33/1 ve m.34/1: tedbir kararlarına karşı tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir.","kaynak":"6284UYG m.33/1, m.34/1","zorluk":"orta"},
    {"id":"6284UYG-S-019","soru":"Yönetmeliğe göre, itiraz hakkında duruşma yapılmaksızın karar verilir; karar bir hafta içinde verilir ve itiraz üzerine verilen karar kesindir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.33/3 ve m.34/7: itiraz hakkında duruşma yapılmaksızın karar verilir, karar bir hafta içinde verilir ve itiraz üzerine verilen karar kesindir.","kaynak":"6284UYG m.34/7","zorluk":"orta"},
    {"id":"6284UYG-S-020","soru":"Yönetmeliğe göre, gecikmesinde sakınca bulunan hâllerde kolluk amirince alınabilen ve hâkimin onayına sunulan önleyici tedbirler, Yönetmeliğin hangi maddelerinde belirtilen tedbirlerdir?","siklar":["6, 12, 17 ve 29 uncu maddelerde","18, 19, 20 ve 22 nci maddelerde","7, 8, 9 ve 11 inci maddelerde","30, 32, 33 ve 34 üncü maddelerde","37, 38, 40 ve 42 nci maddelerde"],"dogru":1,"aciklama":"m.29/2: 18, 19, 20 ve 22 nci maddelerde belirtilen ve hâkim tarafından karar altına alınabilecek önleyici tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince alınabilir; evrak ilk işgünü içinde hâkimin onayına sunulur.","kaynak":"6284UYG m.29/2","zorluk":"zor"},
    {"id":"6284UYG-S-021","soru":"Yönetmeliğe göre, \"Kolluk, kendisine intikal eden her olay hakkında gecikmeksizin en seri vasıtalarla ............ bilgi verir.\" Boşluğa aşağıdakilerden hangisi gelmelidir?","siklar":["Cumhuriyet başsavcılığına","Bakanlığa","Aile mahkemesine","Valiliğe","ŞÖNİM'e"],"dogru":4,"aciklama":"m.5/1: kolluk, kendisine intikal eden her olay hakkında gecikmeksizin en seri vasıtalarla ŞÖNİM'e bilgi verir.","kaynak":"6284UYG m.5/1","zorluk":"orta"},
    {"id":"6284UYG-S-022","soru":"Yönetmeliğe göre, mülki amirin veya kolluk amirinin kararı ile kamu kurum ve kuruluşlarına ait barınma yerlerine getirilen şiddet mağduru, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhâl kabul edilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.7/5: mülki amirin veya kolluk amirinin kararı ile getirilen şiddet mağduru, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhâl kabul edilir.","kaynak":"6284UYG m.7/5","zorluk":"orta"},
    {"id":"6284UYG-S-023","soru":"Yönetmeliğe göre, geçici maddi yardımlar için yapılan ödemelerin tahsilinde, ödeme tutarının tebliğ tarihinden itibaren ne kadar süre içinde ödenmesi gerektiği şiddet uygulayana tebliğ edilir; ödeme süresinde yapılmazsa tutar 6183 sayılı Kanun hükümlerine göre tahsil edilir?","siklar":["On beş gün","İki ay","Üç ay","Bir ay","Altı ay"],"dogru":3,"aciklama":"m.42/1: ödeme tutarının tebliğ tarihinden itibaren bir ay içinde ödenmesi şiddet uygulayana tebliğ edilir; süresinde ödenmezse 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun hükümlerine göre takip ve tahsil edilir.","kaynak":"6284UYG m.42/1","zorluk":"zor"},
    {"id":"6284UYG-S-024","soru":"Yönetmeliğe göre, tek taraflı ısrarlı takip sayılabilmesi için şiddet uygulayan ile şiddet mağduru arasında aile bağı veya ilişki bulunması şarttır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.3/1-ş: tek taraflı ısrarlı takip, taraflar arasında aile bağı veya ilişki bulunup bulunmadığına BAKILMAKSIZIN tanımlanır; aile bağı şart değildir.","kaynak":"6284UYG m.3/1-ş","zorluk":"orta"},
    {"id":"6284UYG-OO-001","soru":"B, gece yarısı eşi A'nın kendisini ölümle tehdit etmesi üzerine en yakın jandarma karakoluna sığınır. B'nin hayatî tehlikesi bulunmaktadır ve o saatte mülki amir ile hâkime ulaşılarak karar alınması için yeterli vakit yoktur. Gecikmesinde sakınca bulunan bu hâlde, B'nin geçici koruma altına alınması tedbirini kim alabilir?","siklar":["Yalnızca mülki amir","Yalnızca aile mahkemesi hâkimi","İlgili kolluk amiri","Cumhuriyet savcısı","ŞÖNİM müdürü"],"dogru":2,"aciklama":"m.29/1: mülki amir tarafından alınabilecek barınma yeri sağlanmasına ve geçici koruma altına alınmasına ilişkin tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince de alınabilir; kolluk amiri evrakı ilk işgünü içinde mülki amirin onayına sunar, mülki amirce kırk sekiz saat içinde onaylanmazsa tedbir kendiliğinden kalkar.","kaynak":"6284UYG m.29/1","zorluk":"orta"},
    {"id":"6284UYG-OO-002","soru":"Aile mahkemesi hâkimi, korunan kişi B'nin talebi üzerine, eşiyle birlikte yaşadığı konutun tapu kütüğüne aile konutu şerhi konulmasına karar verir. Bu tedbirle ilgili olarak aşağıdakilerden hangisi DOĞRUDUR?","siklar":["Bir önleyici tedbirdir ve yalnızca mülki amir verebilir.","Bir koruyucu tedbirdir ve hâkim tarafından verilebilir.","Bir önleyici tedbir olup gecikmesinde sakınca hâlinde kolluk amirince de alınabilir.","Hâkimin yetkisinde olmayan, yalnızca tapu müdürlüğünce yapılan bir işlemdir.","Şiddetin delillerle ispatı koşuluna bağlı bir koruyucu tedbirdir."],"dogru":1,"aciklama":"m.12/1-c: korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması, hâkim tarafından verilebilen bir KORUYUCU tedbirdir; m.12/1'e göre koruyucu tedbirler için delil veya belge aranmaz.","kaynak":"6284UYG m.12/1-c","zorluk":"orta"},
    {"id":"6284UYG-OO-003","soru":"Hakkında 'müşterek konuttan uzaklaştırma' önleyici tedbiri verilen ve ihtarı da içeren karar kendisine tebliğ edilen A, konuta geri dönerek tedbiri ilk kez ihlal eder; bu sırada korunan kişiye hakaret de etmiştir. Hâkim, A hakkında nasıl bir karar verir?","siklar":["Fiil aynı zamanda suç oluşturduğundan zorlama hapsine karar veremez.","İlk ihlal olduğundan üç günden on güne kadar zorlama hapsine karar verir.","Doğrudan on beş günden otuz güne kadar zorlama hapsine karar verir.","Yalnızca tedbir süresini uzatır, başka bir yaptırım uygulayamaz.","Zorlama hapsi yerine adli para cezasına hükmeder."],"dogru":1,"aciklama":"m.38/5: tedbir kararına aykırı hareket eden şiddet uygulayan, fiili bir suç oluştursa bile, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre ilk kez üç günden on güne kadar zorlama hapsine tâbi tutulur. İhtarlı tebliğ koşulu (m.38/3) da gerçekleşmiştir.","kaynak":"6284UYG m.38/5","zorluk":"zor"},
    {"id":"6284UYG-OO-004","soru":"Hâkim, A hakkındaki yaklaşmama tedbirinin uygulanmasında elektronik kelepçe gibi teknik araç ve yöntemler kullanılmasına karar verir. Tedbiri uygulayan görevliler, bu teknik araçla A'nın konuşmalarının ses kaydını almak ve onu dinlemek ister. Bu talep hukuken mümkün müdür?","siklar":["Evet; teknik takip kararı ses kaydı ve dinlemeyi de kapsar.","Evet; ancak yalnızca kolluk amirinin ayrı bir onayıyla.","Hayır; teknik araçlarla kişilerin ses ve görüntü kaydı alınamaz, kişiler dinlenemez ve izlenemez.","Hayır; ancak yalnızca görüntü kaydı alınması serbesttir.","Evet; ŞÖNİM müdürünün izni alınması şartıyla mümkündür."],"dogru":2,"aciklama":"m.37/1: hâkim, tedbir kararlarının uygulanmasında teknik araç ve yöntemler kullanılmasına karar verebilir; ANCAK teknik araçlar kullanılmak suretiyle kişilerin ses ve görüntü kaydı alınamaz, kişiler dinlenemez ve izlenemez.","kaynak":"6284UYG m.37/1","zorluk":"orta"},
    {"id":"6284UYG-OO-005","soru":"Hakkında gizlilik kararı bulunan korunan kişi B'nin yeni adresi, bir kamu görevlisi tarafından resmî kayıtlardan öğrenilip B'nin kendisinden kaçtığı eşi A'ya bildirilir. Bu kamu görevlisinin fiili hukuken nasıl değerlendirilir?","siklar":["Herhangi bir yaptırımı yoktur; bilgi zaten resmî kayıtta bulunmaktadır.","Yalnızca disiplin cezasını gerektirir.","Türk Ceza Kanununun ilgili hükümleri uygulanır.","Mülki amir tarafından idari para cezası verilir.","Hâkim tarafından zorlama hapsi uygulanır."],"dogru":2,"aciklama":"m.32/1: gizli tutulması gereken kimlik ve adres bilgilerini hukuka aykırı olarak başkasına veren, ifşa eden veya açıklayan kişi hakkında Türk Ceza Kanununun ilgili hükümleri uygulanır.","kaynak":"6284UYG m.32/1","zorluk":"orta"},
    {"id":"6284UYG-OO-006","soru":"Aile mahkemesi hâkimi, A hakkında altı ay süreli bir önleyici tedbir kararı verir ve karar A'ya tebliğ edilir. Karara katılmayan A, bu karara itiraz etmek istemektedir. A, tefhim veya tebliğ tarihinden itibaren ne kadar süre içinde ve nereye itiraz edebilir?","siklar":["Bir hafta içinde sulh ceza hâkimliğine","İki hafta içinde aile mahkemesine","Altmış gün içinde ağır ceza mahkemesine","Bir ay içinde bölge adliye mahkemesine","Otuz gün içinde Cumhuriyet başsavcılığına"],"dogru":1,"aciklama":"m.34/1: hâkim tarafından verilen koruyucu veya önleyici tedbir kararlarına karşı, tefhim veya tebliğ tarihinden itibaren iki hafta içinde aile mahkemesine itiraz edilebilir; m.34/7'ye göre karar duruşma yapılmaksızın bir hafta içinde verilir ve kesindir.","kaynak":"6284UYG m.34/1","zorluk":"orta"},
    {"id":"6284UYG-OO-007","soru":"A, kendisiyle aralarında hiçbir aile bağı veya duygusal ilişki bulunmayan B'yi; sürekli mesaj atarak, telefonla arayarak ve peşinden giderek B'de korku ve güvenlik endişesi yaratacak biçimde takip etmektedir. B'nin bu düzenleme kapsamındaki durumu nasıl nitelendirilir?","siklar":["Aralarında aile bağı bulunmadığından B kapsam dışındadır.","B yalnızca genel hükümlere göre korunabilir; bu yönetmelik uygulanmaz.","Bu bir tek taraflı ısrarlı takiptir ve B korunan kişidir; aile bağı veya ilişki aranmaz.","Israrlı takip sayılabilmesi için tarafların evli veya akraba olması gerekir.","B ancak fiziksel temas gerçekleşirse korunan kişi sayılabilir."],"dogru":2,"aciklama":"m.3/1-ş: tek taraflı ısrarlı takip, taraflar arasında aile bağı veya ilişki bulunup bulunmadığına bakılmaksızın tanımlanır; m.3/1-j: tek taraflı ısrarlı takip mağduru da korunan kişi kapsamındadır.","kaynak":"6284UYG m.3/1-ş, m.3/1-j","zorluk":"orta"},
    {"id":"6284UYG-OO-008","soru":"Gecikmesinde sakınca bulunan bir hâlde, ilgili kolluk amiri, şiddet uygulayan A hakkında 'müşterek konuttan uzaklaştırma' niteliğindeki önleyici tedbiri alır. Bu tedbirin ayakta kalabilmesi için evrak kime sunulur ve ne kadar süre içinde onaylanmalıdır?","siklar":["Mülki amire; kırk sekiz saat içinde","Hâkime; yirmi dört saat içinde","Cumhuriyet savcısına; kırk sekiz saat içinde","Mülki amire; yirmi dört saat içinde","ŞÖNİM müdürüne; ilk işgünü içinde"],"dogru":1,"aciklama":"m.29/2: 18, 19, 20 ve 22 nci maddelerde belirtilen önleyici tedbirler gecikmesinde sakınca bulunan hâlde kolluk amirince alınabilir; kolluk amiri evrakı ilk işgünü içinde hâkimin onayına sunar, hâkim tarafından yirmi dört saat içinde onaylanmayan tedbir kendiliğinden kalkar.","kaynak":"6284UYG m.29/2","zorluk":"zor"},
    {"id":"6284UYG-OO-009","soru":"B, kaymakamlığa başvurarak eşinden şiddet gördüğünü beyan eder; ancak yanında darp raporu, tanık ya da herhangi bir delil-belge yoktur. B, kendisine uygun bir barınma yeri sağlanmasını talep etmektedir. Mülki amir nasıl hareket eder?","siklar":["Delil veya belge bulunmadığından talebi reddeder.","Önce şiddetin ispatına yönelik soruşturmanın tamamlanmasını bekler.","Delil veya belge aranmaksızın barınma yeri sağlanmasına karar verebilir.","Talebi yalnızca hâkime yönlendirir; kendisi karar veremez.","Yalnızca darp raporu sunulması hâlinde karar verebilir."],"dogru":2,"aciklama":"m.6/1: korunan kişilerle ilgili koruyucu tedbirlere delil veya belge aranmaksızın mülki amir tarafından ilgilinin talebi üzerine karar verilebilir; uygun barınma yeri sağlanması bu tedbirler arasındadır.","kaynak":"6284UYG m.6/1","zorluk":"kolay"},
    {"id":"6284UYG-OO-010","soru":"Aile mahkemesi hâkimi, şiddet uygulayan A hakkında ilk kez bir önleyici tedbir kararı verecektir. Hâkim, korunan kişi B'nin uzun süre korunmasını sağlamak amacıyla bu kararı bir yıl süreyle vermek istemektedir. Yönetmeliğe göre tedbir kararının ilk verilme süresi bakımından aşağıdakilerden hangisi DOĞRUDUR?","siklar":["Tedbir kararı ilk defasında en çok altı ay için verilebilir.","Tedbir kararı ilk defasında en çok bir yıl için verilebilir.","Tedbir kararı süresiz olarak verilir.","Tedbir kararı ilk defasında en çok üç ay için verilebilir.","Tedbir kararının süresini yalnızca Cumhuriyet savcısı belirleyebilir."],"dogru":0,"aciklama":"m.30/2: tedbir kararı ilk defasında en çok altı ay için verilebilir; ancak şiddet veya şiddet uygulanma tehlikesinin devam edeceğinin anlaşılması hâlinde tedbirin süresi veya şekli değiştirilebilir ya da aynen devam etmesine karar verilebilir.","kaynak":"6284UYG m.30/2","zorluk":"orta"},
    {"id":"6284UYG-OO-011","soru":"Bir olayda, şiddet uygulayan A'nın 'müşterek konuttan derhâl uzaklaştırılması' gerektiği değerlendirilmektedir. Bu tedbir bakımından aşağıdakilerden hangisi DOĞRUDUR?","siklar":["Mülki amir, koruyucu tedbir yetkisi kapsamında bu tedbiri doğrudan verebilir.","Bu bir önleyici tedbirdir; hâkim tarafından verilir, gecikmesinde sakınca bulunan hâlde kolluk amirince de alınabilir.","Yalnızca Cumhuriyet savcısı bu tedbire karar verebilir.","ŞÖNİM müdürü bu tedbiri resen uygular.","Bu bir koruyucu tedbir olup yalnızca mülki amirin yetkisindedir."],"dogru":1,"aciklama":"Müşterek konuttan uzaklaştırma bir ÖNLEYİCİ tedbirdir (m.17/1-b; m.19); önleyici tedbirleri hâkim verir, m.29/2 uyarınca m.18-19-20-22 kapsamındaki önleyici tedbirler gecikmesinde sakınca bulunan hâlde kolluk amirince alınıp hâkimin onayına sunulur. Mülki amirin yetkisi yalnızca koruyucu tedbirlerle sınırlıdır.","kaynak":"6284UYG m.29, m.6, m.12, m.17","zorluk":"zor"},
    {"id":"6284UYG-OO-012","soru":"Kolluk amirinin kararıyla, şiddet mağduru B kamu kurumuna ait bir barınma yerine (konukevine) getirilir. Konukevi görevlisi, B'yi kabul etmek için ayrıca bir hâkim kararı veya ŞÖNİM onayının beklenmesi gerektiğini düşünür. Bu durumda nasıl hareket edilmelidir?","siklar":["B, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhâl kabul edilir.","B'nin kabulü için mutlaka önce hâkim onayı beklenir.","B yalnızca ŞÖNİM müdürünün yazılı onayıyla kabul edilebilir.","B'nin kabulü için kırk sekiz saat içinde mülki amir onayı şarttır.","B ancak darp raporu ibraz ederse kabul edilebilir."],"dogru":0,"aciklama":"m.7/5: mülki amirin veya kolluk amirinin kararı ile kamu kurum ve kuruluşlarına ait barınma yerlerine getirilen şiddet mağduru, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhâl kabul edilir.","kaynak":"6284UYG m.7/5","zorluk":"kolay"},
  ],
  22: [
    {"id":"PERSONELYON-S-001","soru":"Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı Personel Yönetmeliği, aşağıdaki hükümlerin hangisine dayanılarak hazırlanmıştır?","siklar":["2803 sayılı Kanunun 23 üncü ve 2692 sayılı Kanunun 24 üncü maddesi","657 sayılı Kanunun 1 inci maddesi","2803 sayılı Kanunun 24 üncü ve 2692 sayılı Kanunun 23 üncü maddesi","2803 sayılı Kanunun 24 üncü ve 657 sayılı Kanunun 4 üncü maddesi","2692 sayılı Kanunun 23 üncü ve 657 sayılı Kanunun 1 inci maddesi"],"dogru":2,"aciklama":"m.3: Yönetmelik 2803 sayılı Kanunun 24 üncü maddesi ve 2692 sayılı Kanunun 23 üncü maddesi hükümlerine dayanılarak hazırlanmıştır.","kaynak":"Personel Yön. m.3","zorluk":"orta"},
    {"id":"PERSONELYON-S-002","soru":"Yönetmeliğin amacı; 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu, 2692 sayılı Sahil Güvenlik Komutanlığı Kanunu ile 14/7/1965 tarihli ve ____ sayılı Devlet Memurları Kanununun ilgili hükümlerinin uygulanmasına dair usul ve esasları belirlemektir. Boşluğa gelmesi gereken kanun numarası nedir?","siklar":["5237","657","5271","4483","2802"],"dogru":1,"aciklama":"m.1: Amaç, 2803 + 2692 + 657 sayılı Devlet Memurları Kanununun JGK ve SGK personeliyle ilgili hükümlerinin uygulanmasıdır.","kaynak":"Personel Yön. m.1","zorluk":"kolay"},
    {"id":"PERSONELYON-S-003","soru":"Personel Yönetmeliği'ndeki tanımlara göre, 'Makam, rütbe veya kıdem büyüklüğünü' ifade eden kavram aşağıdakilerden hangisidir?","siklar":["Amir","Makam","Branş","Üst","Kıdemli"],"dogru":3,"aciklama":"m.4/k: Üst, makam, rütbe veya kıdem büyüklüğünü ifade eder.","kaynak":"Personel Yön. m.4","zorluk":"orta"},
    {"id":"PERSONELYON-S-004","soru":"Personel Yönetmeliği'ne göre 'Kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş olan diğer kişileri' ifade eden kavram hangisidir?","siklar":["Amir","Üst","Makam","Branş","Komutan"],"dogru":0,"aciklama":"m.4/a: Amir, kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş diğer kişilerdir.","kaynak":"Personel Yön. m.4","zorluk":"kolay"},
    {"id":"PERSONELYON-S-005","soru":"Personel Yönetmeliği'ne göre JGK ve SGK'nın personel ihtiyacının miktarı neye göre belirlenir?","siklar":["Genel atama döneminin başlangıç tarihine göre","Atanılan hizmet bölgesinin özelliklerine göre","Temayüz etmiş astsubay sayısına göre","Kadro kıdem sırasına göre","Bakanlık tarafından onaylanan insan gücü planına göre"],"dogru":4,"aciklama":"m.5/4: Personel ihtiyacı, Bakanlık tarafından onaylanan insan gücü planına göre karşılanır.","kaynak":"Personel Yön. m.5","zorluk":"orta"},
    {"id":"PERSONELYON-S-006","soru":"Personel Yönetmeliği'ne göre aşağıdakilerden hangisi Jandarma Genel Komutanlığındaki astsubay branşlarından biri DEĞİLDİR?","siklar":["Jandarma","Güverte","İstihkâm","Bakım","Sağlık"],"dogru":1,"aciklama":"m.7/1-b: Jandarma astsubay branşları jandarma, istihkâm, muhabere, uçak ve helikopter teknisyeni, ikmal, bakım, personel, maliye, bando, sağlık ve İHA'dır. 'Güverte' Sahil Güvenlik astsubay branşıdır.","kaynak":"Personel Yön. m.7","zorluk":"zor"},
    {"id":"PERSONELYON-S-007","soru":"Personel Yönetmeliği'ne göre aşağıdakilerden hangisi Sahil Güvenlik Komutanlığındaki astsubay branşlarından biri DEĞİLDİR?","siklar":["Güverte","Makine","İkmal","Muhabere","Bilgi teknolojileri"],"dogru":3,"aciklama":"m.7/2-b: Sahil Güvenlik astsubay branşları güverte, makine, ikmal, uçak bakım, idari ve bilgi teknolojileridir. 'Muhabere' Jandarma astsubay branşıdır.","kaynak":"Personel Yön. m.7","zorluk":"zor"},
    {"id":"PERSONELYON-S-008","soru":"Personel Yönetmeliği'ne göre atamalarda esas alınan temel ölçüt aşağıdakilerden hangisidir?","siklar":["Hizmet bölgesinin özellikleri","Personelin kendi talebi","Kıdem sırası","Mezuniyet derecesi","İkamet adresi"],"dogru":0,"aciklama":"m.10/1: Atamalarda hizmet bölgesinin özellikleri esas alınır; personel meslek boyu farklı hizmet bölgeleri arasında zorunlu atamaya tabidir.","kaynak":"Personel Yön. m.10","zorluk":"orta"},
    {"id":"PERSONELYON-S-009","soru":"Personel Yönetmeliği'ne göre, ihtiyaç duyulması halinde subay kadrolarına liyakat esas alınarak emsalleri arasında temayüz etmiş astsubaylar atanabilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.10/7: İhtiyaç halinde subay kadrolarına liyakat esas alınarak emsalleri arasında temayüz etmiş astsubaylar atanabilir.","kaynak":"Personel Yön. m.10/7","zorluk":"orta"},
    {"id":"PERSONELYON-S-010","soru":"Personel Yönetmeliği'ne göre genel atamalar her yılın hangi ayları arasında yapılır?","siklar":["Ocak ve Haziran ayları arasında","Haziran ve Eylül ayları arasında","Mayıs ve Ekim (dâhil) ayları arasında","Mart ve Ağustos ayları arasında","Nisan ve Eylül ayları arasında"],"dogru":2,"aciklama":"m.14/2: Genel atamalar her yılın Mayıs ve Ekim (dâhil) ayları arasında yapılır; Bakanlık hizmet gereği başka zamanlarda da yapabilir.","kaynak":"Personel Yön. m.14/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-011","soru":"Personel Yönetmeliği'ne göre başka yerdeki görevlere atananlar, atama emrinin tebliğinden itibaren kaç gün içinde o yere hareket etmek zorundadır?","siklar":["7 gün","10 gün","30 gün","15 gün","20 gün"],"dogru":3,"aciklama":"m.15/1-b: Başka yerdeki görevlere atananlar tebliğden itibaren onbeş gün içinde o yere hareket eder ve yol süresini izleyen işgünü içinde işe başlar.","kaynak":"Personel Yön. m.15/1-b","zorluk":"orta"},
    {"id":"PERSONELYON-S-012","soru":"Personel Yönetmeliği'ne göre atama emri, aksi belirlenmedikçe amire ulaşmasından itibaren en geç onbeş gün içinde ilgilisine tebliğ edilir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.15/4: Atama emrinde aksi belirlenmedikçe, emir amire ulaştıktan sonra en geç ON gün içinde ilgilisine tebliğ edilir; ifadedeki 'onbeş gün' yanlıştır. Onbeş gün, başka yerdeki göreve atananın tebliğden itibaren hareket etme süresidir (m.15/1-b); bu iki süre karıştırılmamalıdır.","kaynak":"Personel Yön. m.15/4","zorluk":"orta"},
    {"id":"PERSONELYON-S-013","soru":"Personel Yönetmeliği'ne göre personel siyasi partiye üye olamaz ve herhangi bir siyasi parti, kişi veya zümrenin yararını veya zararını hedef tutan davranışta bulunamaz. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.19/1: Personel siyasi partiye üye olamaz; siyasi/ideolojik amaçlı beyan ve eylemde bulunamaz, ayrım yapamaz.","kaynak":"Personel Yön. m.19","zorluk":"kolay"},
    {"id":"PERSONELYON-S-014","soru":"Personel Yönetmeliği'ne göre kişiler, kamu hukukuna tabi görevlerle ilgili olarak uğradıkları zararlardan dolayı kime karşı dava açarlar?","siklar":["Görevi yerine getiren personel aleyhine","İlgili kurum aleyhine","Hem personel hem kurum aleyhine birlikte","Hazine aleyhine doğrudan","Amir aleyhine"],"dogru":1,"aciklama":"m.24/1: Kişiler, uğradıkları zararlardan dolayı personel aleyhine değil ilgili kurum aleyhine dava açar; kurumun sorumlu personele rücu hakkı saklıdır.","kaynak":"Personel Yön. m.24/1","zorluk":"orta"},
    {"id":"PERSONELYON-S-015","soru":"Personel Yönetmeliği'ne göre, personelin kasıt, kusur, ihmal veya tedbirsizliği sonucu idare zarara uğratılmışsa bu zararın ilgili personel tarafından maliyet bedeli üzerinden ödenmesi esastır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.23/2: Personelin kasıt/kusur/ihmal/tedbirsizliğiyle idare zarara uğratılmışsa zarar ilgili personel tarafından RAYİÇ bedel üzerinden ödenir; ifadedeki 'maliyet bedeli' yönetmeliğe aykırıdır. Yönetmelik açıkça rayiç bedeli esas alır.","kaynak":"Personel Yön. m.23/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-016","soru":"Personel Yönetmeliği'ne göre kamu görevleri hakkında basına gerekli bilgi ancak kim tarafından verilebilir?","siklar":["Yalnızca İçişleri Bakanı","Yalnızca kurum basın sözcüsü","Her amir kendi görev alanında","Genel Komutan","İllerde valiler ve Bakanın yetkili kılacağı görevli"],"dogru":4,"aciklama":"m.25/1: Personel basına bilgi/demeç veremez; gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir.","kaynak":"Personel Yön. m.25","zorluk":"orta"},
    {"id":"PERSONELYON-S-017","soru":"Personel Yönetmeliği'ne göre, görev icabı teslim edilen resmi belge, araç ve gereçleri görev sona erdiğinde iade etme zorunluluğu personelin mirasçılarına da şamildir. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.26/2: Resmi belge, araç ve gereçler görev sona erince iade edilir; bu zorunluluk personelin mirasçılarına da şamildir.","kaynak":"Personel Yön. m.26/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-018","soru":"Personel Yönetmeliği'ne göre, personel hakkındaki uydurma suç isnadı kanuni işlem sonucunda sabit olmazsa, isnatta bulunanlar hakkında kamu davası açılmasını kim ister?","siklar":["Doğrudan ilgili personelin kendisi","İçişleri Bakanı","Merkezde personelin en büyük amiri, illerde valiler","Disiplin kurulu","Cumhuriyet savcısı re'sen"],"dogru":2,"aciklama":"m.33: İsnat sabit olmazsa merkezde en büyük amir, illerde valiler, isnatta bulunanlar hakkında kamu davası açılmasını Cumhuriyet savcılığından ister.","kaynak":"Personel Yön. m.33","zorluk":"zor"},
    {"id":"PERSONELYON-S-019","soru":"Personel Yönetmeliği'ne göre personelin greve karar vermeleri, grev tertiplemeleri, ilan etmeleri ve bu yolda propaganda yapmaları yasaktır. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.36/1: Personelin greve karar vermeleri, tertiplemeleri, ilan etmeleri ve propaganda yapmaları yasaktır; greve veya teşebbüse katılamaz.","kaynak":"Personel Yön. m.36","zorluk":"kolay"},
    {"id":"PERSONELYON-S-020","soru":"Personel Yönetmeliği'ne göre eşi, reşit olmayan veya mahcur çocuğu yasaklanan faaliyetlerde bulunan personel, bu durumu kaç gün içinde bağlı olduğu kuruma bildirmek zorundadır?","siklar":["10 gün","15 gün","30 gün","7 gün","1 ay"],"dogru":1,"aciklama":"m.37/3: Eşleri, reşit olmayan veya mahcur çocukları yasak faaliyette bulunan personel bu durumu onbeş gün içinde kurumuna bildirir.","kaynak":"Personel Yön. m.37/3","zorluk":"orta"},
    {"id":"PERSONELYON-S-021","soru":"Personel Yönetmeliği'ne göre personel, kamu hizmetleriyle ilgili gizli bilgileri görevinden ayrılmış olsa bile neye dayanmadıkça açıklayamaz?","siklar":["Bakanın yazılı izni","Valinin sözlü izni","Birim amirinin onayı","Mahkeme kararı","Gizlilik süresinin dolması"],"dogru":0,"aciklama":"m.41/2: Personel, gizli bilgileri görevinden ayrılmış olsa bile Bakanın yazılı izni olmadıkça açıklayamaz.","kaynak":"Personel Yön. m.41/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-022","soru":"Personel Yönetmeliği'ne göre nöbet, amirin münasip göreceği zamanda başlar ve en çok kaç saati geçemez?","siklar":["8 saat","12 saat","16 saat","24 saat","48 saat"],"dogru":3,"aciklama":"m.42/2: Nöbet, amirin münasip göreceği zamanda başlar ve yirmidört saati geçemez.","kaynak":"Personel Yön. m.42/2","zorluk":"kolay"},
    {"id":"PERSONELYON-S-023","soru":"Personel Yönetmeliği'ne göre kadın memurlara, tabip raporunda belirtilmesi halinde hamilelik boyunca ve doğumdan sonra ne kadar süreyle gece nöbeti ve gece vardiyası görevi verilemez?","siklar":["1 yıl","6 ay","2 yıl","3 yıl","18 ay"],"dogru":2,"aciklama":"m.42/2: Kadın memurlara tabip raporuyla hamilelik boyunca ve doğumdan sonraki iki yıl süreyle gece nöbeti ve gece vardiyası verilemez.","kaynak":"Personel Yön. m.42/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-024","soru":"Personel Yönetmeliği'ne göre değerlendirme ____ yapılır. Boşluğa gelmesi gereken ifade aşağıdakilerden hangisidir?","siklar":["yılda en az bir kez","iki yılda bir","ayda bir","altı ayda bir","üç yılda bir"],"dogru":0,"aciklama":"m.45/4: Değerlendirme yılda en az bir kez yapılır.","kaynak":"Personel Yön. m.45/4","zorluk":"kolay"},
    {"id":"PERSONELYON-S-025","soru":"Personel Yönetmeliği kapsamında verilen ödüller arasında aşağıdakilerden hangisi yer almaz?","siklar":["Başarı belgesi","Üstün başarı belgesi","Aylıkla ödüllendirme","Şerit rozet","Madalya"],"dogru":2,"aciklama":"m.46/4: Ödüller başarı belgesi, üstün başarı belgesi, takdir belgesi, şerit rozet, bröve ve madalyadır. 'Aylıkla ödüllendirme' bu yönetmelikte sayılmaz.","kaynak":"Personel Yön. m.46/4","zorluk":"orta"},
    {"id":"PERSONELYON-S-026","soru":"Personel Yönetmeliği'ne göre kaç defa başarı belgesi alan personele üstün başarı belgesi verilir?","siklar":["2 defa","3 defa","4 defa","5 defa","6 defa"],"dogru":1,"aciklama":"m.47/2: Üç defa başarı belgesi alanlara üstün başarı belgesi verilir.","kaynak":"Personel Yön. m.47/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-027","soru":"Personel Yönetmeliği'ne göre, valiler ve kaymakamlar tarafından alınan görevden uzaklaştırma tedbiri ne yapılır?","siklar":["İl idare kurulunun onayına sunulur","En geç onbeş gün içinde Bakanlığa yazılı olarak iletilir","Personelin kurumuna derhal bildirilir","Yalnızca personelin özlük dosyasına işlenir","Bir sonraki genel atama döneminde değerlendirilir"],"dogru":2,"aciklama":"m.52/2: Valiler ve kaymakamlar tarafından alınan görevden uzaklaştırma tedbiri, personelin kurumuna derhal bildirilir.","kaynak":"Personel Yön. m.52/2","zorluk":"orta"},
    {"id":"PERSONELYON-S-028","soru":"Personel Yönetmeliği'ne göre görevden uzaklaştırma, görevi başında kalmasında sakınca görülen personel hakkında verilen bir disiplin cezasıdır ve bu hususta 657 sayılı Kanunda belirtilen usul ve esaslara uyulur. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.51/1: Görevden uzaklaştırma bir disiplin cezası DEĞİL, görevi başında kalmasında sakınca görülen personel hakkında alınan İHTİYATİ bir tedbirdir (usulde 657 sayılı Kanun esas alınır). İfade tedbiri 'disiplin cezası' saydığından yanlıştır.","kaynak":"Personel Yön. m.51","zorluk":"kolay"},
    {"id":"PERSONELYON-S-029","soru":"Personel Yönetmeliği'ne göre personelin mülki görevlerinden doğan suçlarında, özel kanun hükümleri saklı kalmak şartıyla hangi kanun hükümlerine göre işlem yapılır?","siklar":["5271 sayılı Kanun","5237 sayılı Kanun","353 sayılı Kanun","4483 sayılı Kanun","657 sayılı Kanun"],"dogru":3,"aciklama":"m.53/1-b: Mülki görevden doğan suçlarda, özel kanunlar saklı kalmak şartıyla 4483 sayılı Kanun hükümlerine göre işlem yapılır.","kaynak":"Personel Yön. m.53/1-b","zorluk":"zor"},
    {"id":"PERSONELYON-S-030","soru":"Personel Yönetmeliği'ne göre personelin adli görevlerinden doğan suçlarda aşağıdaki hükümlerden hangisi uygulanır?","siklar":["5271 sayılı Kanunun 161 inci maddesinin beşinci fıkrası","4483 sayılı Kanun hükümleri","353 sayılı Kanun hükümleri","Genel hükümler","5237 sayılı Kanunun 161 inci maddesi"],"dogru":0,"aciklama":"m.53/1-c: Adli görevlerden doğan suçlarda 5271 sayılı Kanunun 161 inci maddesinin beşinci fıkrası hükmü uygulanır.","kaynak":"Personel Yön. m.53/1-c","zorluk":"zor"},
    {"id":"PERSONELYON-S-031","soru":"Personel Yönetmeliği'ne göre emeklilik, çekilme veya herhangi bir nedenle JGK ya da SGK'dan ilişiği kesilen personel, ilişiğinin kesildiği tarihten itibaren resmi üniformasıyla ilgili olarak ne yapmak zorundadır?","siklar":["Üniformasını çıkarmaya mecburdur","Üniformasını yalnızca resmi tören ve anma günlerinde giyebilir","Branş ve rütbe işaretlerini söküp üniformayı sivil kıyafet olarak kullanabilir","Üniformasını bir yıl süreyle daha giymeye devam edebilir","Üniformasını kendisinden sonra göreve başlayan astına devredebilir"],"dogru":0,"aciklama":"m.55/3: Personel; emeklilik, çekilme veya herhangi bir nedenle ilişiği kesildiği tarihten itibaren resmi üniformasını çıkarmaya mecburdur.","kaynak":"Personel Yön. m.55/3","zorluk":"orta"},
    {"id":"PERSONELYON-S-032","soru":"Personel Yönetmeliği'ne göre JGK ve SGK kadrolarına atanmış personel, özlük hakları saklı kalmak üzere ayrıca herhangi bir tazminattan yararlanamaz. Bu ifade doğru mudur?","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.56/2: JGK ve SGK kadrolarına atanmış personel, özlük hakları saklı kalmak üzere AYRICA Asayiş Tazminatından yararlanır; ifade bunun tersini ('hiçbir tazminattan yararlanamaz') söylediği için yanlıştır.","kaynak":"Personel Yön. m.56/2","zorluk":"kolay"},
    {"id":"PERSONELYON-S-033","soru":"Personel Yönetmeliği'ne göre selamlamada aşağıdakilerden hangisi doğrudur?","siklar":["Üstler astlardan önce selam vermeye mecburdur.","Astlar, üstlerden evvel selam vermeye mecburdur.","Selam yalnızca törenlerde verilir.","Rütbeyi ayırt edemeyenler selamlaşmaz.","Selamlama yalnızca üstler tarafından başlatılır."],"dogru":1,"aciklama":"m.60/2: Selamlama her yerde ve her zaman yapılır; astlar üstlerden evvel selam vermeye mecburdur, aynı/ayırt edilemeyen rütbedekiler birbirini beklemeden selamlaşır.","kaynak":"Personel Yön. m.60/2","zorluk":"kolay"},
    {"id":"PERSONELYON-OO-001","soru":"Jandarma astsubayı A, hafta sonu izinli olduğu bir gün, görevle hiçbir ilgisi bulunmayan kişisel bir husumet nedeniyle apartman komşusu B ile kavga eder ve B'yi yaralar. A hakkında bu fiil sebebiyle hangi hükümlere göre işlem yapılır?","siklar":["4483 sayılı Kanun (Memurlar ve Diğer Kamu Görevlilerinin Yargılanması) hükümlerine göre","5271 sayılı Kanunun 161 inci maddesinin beşinci fıkrasına göre","353 sayılı Kanun (askeri görev suçları) hükümlerine göre","Genel hükümlere göre","Disiplin işlerine ilişkin özel kanun hükümlerine göre"],"dogru":3,"aciklama":"m.53/1-d: Personelin kişisel suçlarında genel hükümlere göre işlem yapılır. Olaydaki fiil görevle ilgisi olmayan, izinli iken işlenen kişisel bir suç olduğundan görev suçlarına özgü usuller (4483/5271/353) değil, genel hükümler uygulanır.","kaynak":"Personel Yön. m.53/1-d","zorluk":"zor"},
    {"id":"PERSONELYON-OO-002","soru":"Jandarma astsubayı A'nın, kendisine verilen bir mülki (idari) görevi yerine getirirken görevinden doğan bir suç işlediği ileri sürülür. Özel kanunların hükümleri saklı kalmak şartıyla, A hakkında bu görev suçu nedeniyle hangi kanun hükümlerine göre işlem yapılır?","siklar":["5237 sayılı Türk Ceza Kanunu, doğrudan ve başkaca usul aranmadan","4483 sayılı Kanun","5271 sayılı Kanunun 161 inci maddesinin beşinci fıkrası","353 sayılı Kanun","Genel hükümler"],"dogru":1,"aciklama":"m.53/1-b: Personelin mülki görevlerinden doğan suçlarında, özel kanunların hükümleri saklı kalmak şartıyla 4483 sayılı Kanun hükümlerine göre işlem yapılır.","kaynak":"Personel Yön. m.53/1-b","zorluk":"zor"},
    {"id":"PERSONELYON-OO-003","soru":"Astsubay A, dikkatsizlik ve tedbirsizliği sonucu kendisine teslim edilen Devlete ait hizmet aracını kaza yaptırarak hasara uğratır ve idare zarara uğrar. Bu zarar A tarafından nasıl ödenir?","siklar":["Aracın ilk alındığı tarihteki maliyet bedeli üzerinden","Zararın rayiç bedeli üzerinden","Bir maaş tutarıyla sınırlı sabit bir tarife üzerinden","Zarardan personel sorumlu tutulamaz, tamamı idarece karşılanır","Yalnızca kazadan kaynaklanan onarım giderinin yarısı üzerinden"],"dogru":1,"aciklama":"m.23/2: Personelin kasıt, kusur, ihmal veya tedbirsizliği sonucu idare zarara uğratılmışsa, bu zararın ilgili personel tarafından rayiç bedeli üzerinden ödenmesi esastır.","kaynak":"Personel Yön. m.23/2","zorluk":"orta"},
    {"id":"PERSONELYON-OO-004","soru":"Vatandaş C, bir jandarma personelinin kamu hukukuna tabi görevini yerine getirmesi sırasındaki işlemi nedeniyle zarara uğradığını ileri sürmektedir. C, bu zararın tazmini için davayı kime karşı açmalıdır?","siklar":["Görevi yerine getiren personele karşı şahsen","Personel ve onun amirine karşı birlikte","İlgili kuruma karşı","Doğrudan Hazineye karşı","Personelin bağlı olduğu ile valisine karşı şahsen"],"dogru":2,"aciklama":"m.24/1: Kişiler, kamu hukukuna tabi görevlerle ilgili olarak uğradıkları zararlardan dolayı bu görevleri yerine getiren personel aleyhine değil, ilgili kurum aleyhine dava açar. Kurumun sorumlu personele rücu hakkı saklıdır.","kaynak":"Personel Yön. m.24/1","zorluk":"orta"},
    {"id":"PERSONELYON-OO-005","soru":"Hakkında soruşturma başlatılan astsubay A, görevi başında kalmasında sakınca görüldüğü için görevden uzaklaştırılır. A, 'henüz hakkımda bir karar yokken bana disiplin cezası verildi, bu hukuka aykırı' diyerek itiraz eder. A'nın hakkında uygulanan işlemin hukuki niteliği aşağıdakilerden hangisidir?","siklar":["Kesinleşmiş bir disiplin cezasıdır","Bir adli kovuşturma tedbiridir ve hâkim kararına bağlıdır","Görevi başında kalmasında sakınca görülen personel hakkında alınan ihtiyati bir tedbirdir","Meslekten çıkarma niteliğinde idari bir karardır","Yalnızca emeklilik işlemlerinde uygulanan bir statü değişikliğidir"],"dogru":2,"aciklama":"m.51/1: Görevden uzaklaştırma, kamu hizmetlerinin gerektirdiği hallerde görevi başında kalmasında sakınca görülecek personel hakkında alınan ihtiyati bir tedbirdir; bir disiplin cezası değildir. Usulde 657 sayılı Kanun esas alınır.","kaynak":"Personel Yön. m.51/1","zorluk":"orta"},
    {"id":"PERSONELYON-OO-006","soru":"Bir ilde vali, görevi başında kalmasında sakınca gördüğü jandarma personeli A hakkında görevden uzaklaştırma tedbiri alır. Yönetmeliğe göre bu tedbir bakımından valinin yapması gereken işlem aşağıdakilerden hangisidir?","siklar":["Tedbiri il idare kurulunun onayına sunmak","Tedbiri en geç onbeş gün içinde Bakanlığa yazılı olarak bildirmek","Tedbiri yalnızca personelin özlük dosyasına işlemekle yetinmek","Tedbiri personelin kurumuna derhal bildirmek","Tedbiri bir sonraki genel atama döneminde gözden geçirmek"],"dogru":3,"aciklama":"m.52/2: Valiler ve kaymakamlar tarafından alınan görevden uzaklaştırma tedbiri, personelin kurumuna derhal bildirilir.","kaynak":"Personel Yön. m.52/2","zorluk":"orta"},
    {"id":"PERSONELYON-OO-007","soru":"Bir ildeki jandarma personeli A hakkında, B tarafından garaz ve husumet saikiyle uydurma bir suç isnadında bulunulur. Yapılan kanuni işlem sonucunda bu isnat sabit olmaz. Yönetmeliğe göre, B hakkında kamu davası açılmasını kim ister?","siklar":["Mağdur personel A'nın kendisi doğrudan","İlde vali","İçişleri Bakanı bizzat","İl disiplin kurulu","Cumhuriyet savcısı, hiçbir makamın talebi olmaksızın re'sen"],"dogru":1,"aciklama":"m.33: İsnat sabit olmadığı takdirde, merkezde bu personelin en büyük amiri, illerde valiler, isnatta bulunanlar hakkında kamu davası açılmasını Cumhuriyet savcılığından ister. Olay ilde geçtiğinden isteyen makam validir.","kaynak":"Personel Yön. m.33","zorluk":"zor"},
    {"id":"PERSONELYON-OO-008","soru":"Astsubay A, görevi nedeniyle işlemlerini yürüttüğü iş sahibi B'den, 'kısa süre sonra iade ederim' diyerek borç para ister. A'nın bu davranışı yönetmelik karşısında nasıl değerlendirilir?","siklar":["Geri ödeme vaadi bulunduğundan serbesttir","İş sahiplerinden borç para istemek ve almak yasaktır","Yalnızca amirin yazılı izni alınmışsa caizdir","Görev saatleri dışında istenmişse caizdir","Yalnızca alınan miktar belirli bir tutarı aşarsa yasaktır"],"dogru":1,"aciklama":"m.38/1: Personelin doğrudan veya aracı eliyle hediye istemeleri, menfaat sağlama amacıyla hediye kabul etmeleri ve iş sahiplerinden borç para istemeleri ve almaları yasaktır.","kaynak":"Personel Yön. m.38/1","zorluk":"orta"},
    {"id":"PERSONELYON-OO-009","soru":"Emekli olarak görevinden ayrılmış olan eski personel A, eski görevi sırasında öğrendiği ve gizli olarak nitelendirilen bir bilgiyi bir araştırmacıyla paylaşmak istemektedir. A bu bilgiyi hangi şartla açıklayabilir?","siklar":["Görevinden ayrıldığı için artık serbestçe açıklayabilir","Eski biriminin amirinin sözlü onayını alırsa açıklayabilir","Bakanın yazılı izni olmadıkça açıklayamaz","Üzerinden belirli bir süre geçtiğinde kendiliğinden açıklayabilir","Bağlı bulunduğu valinin onayıyla açıklayabilir"],"dogru":2,"aciklama":"m.41/2: Personel, kamu hizmetleri ile ilgili gizli bilgileri görevinden ayrılmış olsa bile Bakanın yazılı izni olmadıkça açıklayamaz. Yasak, görevden ayrılma (emeklilik dâhil) ile sona ermez.","kaynak":"Personel Yön. m.41/2","zorluk":"zor"},
    {"id":"PERSONELYON-OO-010","soru":"Astsubay A'nın eşi, personel için yasaklanan kapsamda bir ticari faaliyete başlar. A bu durum karşısında yönetmeliğe göre ne yapmak zorundadır?","siklar":["Herhangi bir bildirim yükümlülüğü yoktur; yasak yalnızca personelin kendisini bağlar","Durumu onbeş gün içinde bağlı olduğu kuruma bildirmek zorundadır","Durumu otuz gün içinde doğrudan İçişleri Bakanlığına bildirmek zorundadır","Eşinin faaliyeti sona erene kadar beklemek ve sonra bildirmek zorundadır","Yalnızca bir sonraki değerlendirme döneminde sözlü olarak amirine söylemek zorundadır"],"dogru":1,"aciklama":"m.37/3: Eşleri, reşit olmayan veya mahcur olan çocukları yasaklanan faaliyetlerde bulunan personel, bu durumu onbeş gün içinde bağlı oldukları kuruma bildirmekle yükümlüdür.","kaynak":"Personel Yön. m.37/3","zorluk":"orta"},
    {"id":"PERSONELYON-OO-011","soru":"Hamile olan ve durumu tabip raporuyla belgelenen kadın memur A'ya, amiri gece nöbeti ve gece vardiyası görevi vermek ister. Yönetmeliğe göre doğru uygulama aşağıdakilerden hangisidir?","siklar":["A'ya hamileliği boyunca ve doğumdan sonraki iki yıl süreyle gece nöbeti ve gece vardiyası verilemez","A'ya yalnızca son üç ay gece nöbeti verilemez, sonrasında verilebilir","A'ya rapor olsa dahi gece nöbeti verilebilir, ancak gündüz telafi izni tanınır","A'ya doğuma kadar gece nöbeti verilemez, doğumdan sonra hemen verilebilir","A'ya hamilelik boyunca ve doğumdan sonra altı ay süreyle gece nöbeti verilemez"],"dogru":0,"aciklama":"m.42/2: Kadın memurlara, tabip raporlarında belirtilmesi halinde hamilelik boyunca ve doğumdan sonraki iki yıl süreyle gece nöbeti ve gece vardiyası görevi verilemez.","kaynak":"Personel Yön. m.42/2","zorluk":"orta"},
    {"id":"PERSONELYON-OO-012","soru":"Bir gazeteci, ildeki bir asayiş olayı hakkında olay yerindeki astsubay A'dan kamuoyunu bilgilendirmek üzere demeç ister. Yönetmeliğe göre doğru olan davranış aşağıdakilerden hangisidir?","siklar":["A, görev alanıyla ilgili olduğundan basına bilgi ve demeç verebilir","A demeç veremez; gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir","A, amirinin sözlü izniyle her konuda demeç verebilir","A, yalnızca yazılı basına demeç verebilir, televizyona veremez","A, olayın aydınlatılmasını sağlamak için doğrudan demeç vermek zorundadır"],"dogru":1,"aciklama":"m.25/1: Personel, kamu görevleri hakkında basına, haber ajanslarına veya radyo ve televizyon kurumlarına bilgi veya demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir.","kaynak":"Personel Yön. m.25/1","zorluk":"orta"},
  ],
  23: [
    {"id":"23-S-001","soru":"Jandarma ve Sahil Güvenlik Personelinin Hizmet Esasları Hakkında Yönetmelik, aşağıdaki kanunların hangilerine dayanılarak hazırlanmıştır?","siklar":["2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu m.24 ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanunu m.23","2803 sayılı Kanun m.23 ve 2692 sayılı Kanun m.24","7068 sayılı Kanun ve 2803 sayılı Kanun","7179 sayılı Kanun m.24 ve 2692 sayılı Kanun m.23","657 sayılı Kanun ve 2803 sayılı Kanun m.24"],"dogru":0,"aciklama":"m.3: Yönetmelik, 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24'üncü maddesine ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 23'üncü maddesine dayanılarak hazırlanmıştır.","kaynak":"m.3","zorluk":"kolay"},
    {"id":"23-S-002","soru":"Yönetmeliğin tanımlar maddesine göre 'Rütbe veya kıdemce büyük olan kimse' aşağıdaki kavramlardan hangisini ifade eder?","siklar":["Âmir","Üst","Maiyet","Makam","Ast"],"dogru":1,"aciklama":"m.4: 'Üst: Rütbe veya kıdemce büyük olan kimseyi' ifade eder. Üst-ast ayrımı rütbe/kıdem ölçüsüyle yapılır.","kaynak":"m.4","zorluk":"orta"},
    {"id":"23-S-003","soru":"Yönetmeliğe göre 'Kadro ve kuruluş yönünden bağlı olunan kimse ile âmir olarak yetkilendirilmiş olan diğer personel' aşağıdaki kavramlardan hangisinin tanımıdır?","siklar":["Üst","Maiyet","Âmir","Ast","Görev"],"dogru":2,"aciklama":"m.4: 'Âmir: Kadro ve kuruluş yönünden bağlı olunan kimse ile âmir olarak yetkilendirilmiş olan diğer personeli' ifade eder.","kaynak":"m.4","zorluk":"orta"},
    {"id":"23-S-004","soru":"Aşağıdakilerden hangisi Yönetmeliğin tanımlar maddesinde (m.4) yer alan kavramlardan biri değildir?","siklar":["Maiyet: Âmirin emir ve komutası altındaki personel","Ast: Rütbe veya kıdemce küçük olan personel","Makam: Her âmirin temsil ettiği mevki","Refakat: Üstün her gittiği yerde yanında bulunma yükümlülüğü","Üst: Rütbe veya kıdemce büyük olan kimse"],"dogru":3,"aciklama":"m.4'te Maiyet, Ast, Makam ve Üst tanımları aynen yer alır. 'Refakat' diye bir tanım maddede bulunmaz; uydurma kavramdır.","kaynak":"m.4","zorluk":"orta"},
    {"id":"23-S-005","soru":"Yönetmeliğe göre personel, yetkili âmirlerin huzurunda mevzuatta belirtilen şekilde ant içerek göreve başlar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5/2: 'Personel, yetkili âmirlerin huzurunda mevzuatta belirtildiği şekilde ant içerek göreve başlar.' İfade doğrudur.","kaynak":"m.5","zorluk":"kolay"},
    {"id":"23-S-006","soru":"Yönetmeliğin statüler arası hiyerarşiyi düzenleyen 6'ncı maddesine göre, rütbeli personelin üstten asta doğru sıralaması aşağıdakilerden hangisidir?","siklar":["Subay > Uzman jandarma > Astsubay > Uzman erbaş > Sözleşmeli erbaş","Subay > Astsubay > Uzman jandarma > Uzman erbaş > Sözleşmeli erbaş","Astsubay > Subay > Uzman jandarma > Sözleşmeli erbaş > Uzman erbaş","Subay > Astsubay > Uzman erbaş > Uzman jandarma > Sözleşmeli erbaş","Subay > Astsubay > Uzman jandarma > Sözleşmeli erbaş > Uzman erbaş"],"dogru":1,"aciklama":"m.6: Subaylar diğer rütbeli personelin üstü; astsubaylar subayların astı diğerlerinin üstü; uzman jandarmalar subay-astsubayların astı diğerlerinin üstü; uzman erbaşlar bunların astı, emsal sözleşmeli/yükümlü erbaşların üstü; sözleşmeli erbaşlar emsal uzman erbaşların astı. Sıra: Subay > Astsubay > Uzman jandarma > Uzman erbaş > Sözleşmeli erbaş.","kaynak":"m.6","zorluk":"zor"},
    {"id":"23-S-007","soru":"Yönetmeliğe göre Devlet memurları ile rütbeli personel arasında astlık-üstlük ilişkisi bulunmamakla birlikte, görevin gerektirdiği hâllerde amir-maiyet ilişkisi vardır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.6/6: Devlet memurları ile rütbeli personel arasında astlık-üstlük ilişkisi bulunmamakla birlikte amir-maiyet ilişkisi vardır. İfade doğrudur.","kaynak":"m.6","zorluk":"orta"},
    {"id":"23-S-008","soru":"Yönetmeliğin disiplini düzenleyen 7'nci maddesine göre, aşağıdakilerden hangisi metinde 'disiplinin ayrılmaz unsurları' arasında sayılan hususlardan biri değildir?","siklar":["Görev","Nöbet","Selamlama","İzin planlaması","Kılık ve kıyafet"],"dogru":3,"aciklama":"m.7/2: Personel 'görev, nöbet, selamlama, kılık ve kıyafet gibi disiplinin ayrılmaz unsurlarına' ilişkin hükümlere uymak zorundadır. 'İzin planlaması' bu unsurlar arasında sayılmaz.","kaynak":"m.7","zorluk":"orta"},
    {"id":"23-S-009","soru":"Yönetmeliğe göre disiplin, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisinin temelidir ve __________ disiplinden taviz verilemez.","siklar":["hiçbir suretle","zorunlu hâller dışında","âmirin takdiriyle istisnaen","olağanüstü hâl ilan edilmedikçe","en zor zamanlarda kısmen"],"dogru":0,"aciklama":"m.7/1: 'Disiplin ... temelidir ve hiçbir suretle disiplinden taviz verilemez.' Ayrıca m.7/7 disiplinin en zor zamanlarda bile uygulanacağını belirtir.","kaynak":"m.7","zorluk":"kolay"},
    {"id":"23-S-010","soru":"Yönetmeliğe göre ast, âmirinin usulüne uygun emirlerini hangi şekilde yerine getirmekle yükümlü değildir?","siklar":["Tam olarak","Zamanında","Değiştirmeden","Kendi yorumunu katarak","Eksiksiz olarak"],"dogru":3,"aciklama":"m.8/1: Ast, âmirlerinin usulüne uygun emirlerini 'tam, zamanında, değiştirmeden ve eksiksiz olarak' yerine getirmekle yükümlüdür. m.8/5'e göre aldığı emirden dolayı mütalâada bulunmaz; emre kendi yorumunu katmaz.","kaynak":"m.8","zorluk":"orta"},
    {"id":"23-S-011","soru":"Yönetmeliğe göre ast, ancak âmiri resmî kıyafetli olduğunda onun usulüne uygun emirlerini yerine getirmekle yükümlüdür; âmir sivil kıyafetliyse emre uyma zorunluluğu doğmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.8/1: Ast, âmirlerinin 'resmî kıyafetli olsun veya olmasın' usulüne uygun emirlerini yerine getirmekle yükümlüdür. Resmî kıyafet şartı yoktur; ifade yanlıştır.","kaynak":"m.8","zorluk":"orta"},
    {"id":"23-S-012","soru":"Yönetmeliğe göre aşağıdakilerden hangisi âmirin görevlerinden biri değildir?","siklar":["Astlarına karşı adil ve hakkaniyetli hareket eder; hiçbir mazereti hukuk ve adaletten ayrılmaya gerekçe gösteremez.","Maiyetinin sağlık, özlük ve sosyal haklarını sürekli gözetir.","Bir zorluk çıkınca öne atılmayı şerefli bir görev kabul eder, bir kolaylıkta nefsini sona bırakır.","Aldığı her emri mütalâada bulunmadan, mutlak itaat anlayışıyla yerine getirir.","Görevine sadakati, dürüstlüğü ve hukuk kurallarına riayeti ile astlarına örnek olur."],"dogru":3,"aciklama":"A, B, C, E m.9'da sayılan âmir görevleridir. D ise m.8'de düzenlenen astın (maiyetin) görevidir; emri mütalâa etmeden mutlak itaatle yapmak asta ait bir yükümlülüktür, âmire değil.","kaynak":"m.9","zorluk":"zor"},
    {"id":"23-S-013","soru":"Yönetmeliğe göre ast, kendisine verilen emri Anayasa ve mevzuat hükümlerine aykırı görürse aşağıdakilerden hangisi doğrudur?","siklar":["Emri derhal yerine getirir, sonra durumu bir üst âmire bildirir.","Aykırılığı emri verene bildirir; âmir emrinde ısrar eder ve emrini yazı ile yinelerse emir yerine getirilir, sorumluluk emri verene aittir.","Emri hiçbir surette yerine getirmez ve sorumluluk asta aittir.","Aykırılığı emri verene bildirir; âmir sözlü olarak tekrar etse dahi emir yerine getirilir.","Emri yerine getirir; doğacak sorumluluk emri yerine getiren asta aittir."],"dogru":1,"aciklama":"m.10/3: Ast, aykırı gördüğü emri yerine getirmez ve aykırılığı emri verene bildirir. Âmir ısrar eder ve emrini yazı ile yinelerse emir yerine getirilir; sorumluluk emri verene aittir, ayrıca durum bir üst âmire bildirilir.","kaynak":"m.10/3","zorluk":"zor"},
    {"id":"23-S-014","soru":"Yönetmeliğe göre konusu suç teşkil eden bir emir, âmir tarafından yazı ile yinelendiğinde yerine getirilir ve sorumluluk emri verene ait olur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.10/4: 'Konusu suç teşkil eden emir hiçbir surette yerine getirilmez; yerine getiren kimse sorumluluktan kurtulamaz.' Suç emri için yazıyla yineleme istisnası yoktur; ifade yanlıştır.","kaynak":"m.10/4","zorluk":"orta"},
    {"id":"23-S-015","soru":"Yönetmeliğe göre emirlerin verilme silsilesiyle ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Emirler her hâlükârda silsile dışına çıkılmadan verilmek zorundadır.","Acele ve zorunlu hâllerde sıraya uyulmadan emir verilebilir; emri veren âmir atlanan kademelere en kısa zamanda bilgi verir, emri alan maiyet de âmirini haberdar eder.","Acele hâllerde sıra atlanır ve hiçbir bilgilendirme gerekmez.","Acele hâllerde sadece emri alan maiyet kendi âmirini bilgilendirir, emri veren âmirin bilgilendirme yükümlülüğü yoktur.","Silsile atlanırsa emir geçersiz sayılır ve yeniden silsileyle verilir."],"dogru":1,"aciklama":"m.10/7: Emirler kural olarak silsile ile verilir; acele ve zorunlu hâllerde sıraya riayet edilmeden de verilebilir. Bu takdirde emri veren âmir atlanan kademelere en kısa zamanda bilgi verir, böyle bir emri alan maiyet de âmirini haberdar eder.","kaynak":"m.10/7","zorluk":"orta"},
    {"id":"23-S-016","soru":"Yönetmeliğe göre personelin müracaat ve şikâyet hakkıyla ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Aynı konu ve şahısla ilgili olarak personel toplu olarak söz veya yazı ile müracaat edebilir.","Şikâyetler, en az üç personelin imzasıyla topluca yapılmak zorundadır.","Aynı konu ve şahısla ilgili toplu müracaat yasaktır; aynı olay birden fazla personeli ilgilendirse de her biri ayrı ayrı şikâyet hakkını kullanır.","Şikâyeti incelemeye yetkili âmirler, şikâyeti bir üst makama devrederek neticelendirir.","Âmirin yüzüne karşı kendisini şikâyet etmek serbesttir, ceza gerektirmez."],"dogru":2,"aciklama":"m.11/2: Aynı konu ve şahısla ilgili toplu müracaat yasaktır; aynı olay birden fazla personelin şikâyetine konu olsa bile her biri ayrı ayrı/yalnız başına hakkını kullanır. m.11/3'e göre yetkili âmir şikâyeti bizzat neticelendirir; m.11/4 yüze karşı şikâyeti cezayı mucip sayar.","kaynak":"m.11/2","zorluk":"orta"},
    {"id":"23-S-017","soru":"Yönetmeliğe göre personele disiplin cezası verilmesini gerektiren hâller ve cezanın tatbik şekli hangi mevzuatta düzenlendiği gibidir?","siklar":["6413 sayılı Türk Silahlı Kuvvetleri Disiplin Kanunu","657 sayılı Devlet Memurları Kanunu","7068 sayılı Genel Kolluk Disiplin Hükümleri Hakkında Kanun Hükmünde Kararnamenin Kabul Edilmesine Dair Kanun","2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu","5237 sayılı Türk Ceza Kanunu"],"dogru":2,"aciklama":"m.13/3: Disiplin cezası verilmesini gerektiren hâller ve tatbik şekli, 31/1/2018 tarihli ve 7068 sayılı Genel Kolluk Disiplin Hükümleri Hakkında Kanun Hükmünde Kararnamenin Kabul Edilmesine Dair Kanunda yazılı olduğu gibidir.","kaynak":"m.13/3","zorluk":"orta"},
    {"id":"23-S-018","soru":"Yönetmeliğin ödüllendirmeyi düzenleyen 12'nci maddesine göre aşağıdakilerden hangisi söylenemez?","siklar":["Ödüllendirmede personelin emsalleri ile kıyaslanması esastır.","Ödül sistemi; disiplinle ilgili yaptırım ve cezalar ile değerlendirme notundan bağımsız çalışır.","Ödüllendirme, başarılı olanları emsalleri arasında ayırt ederek diğer personele örnek olmasını sağlamak maksadıyla yapılır.","Ödüllendirme, personeli teşvik etmek ve moral vermek maksadıyla yapılır.","Ödül, ancak verilmiş bir disiplin cezasının ortadan kaldırılması karşılığında verilir."],"dogru":4,"aciklama":"m.12: Ödül teşvik/moral/örnek olma maksadıyla, emsalleriyle kıyaslama esasıyla verilir ve ödül sistemi ceza ile değerlendirme notundan bağımsız çalışır (m.12/7). Ödülün cezanın kaldırılmasına bağlanması metne aykırıdır; ödül cezadan bağımsızdır.","kaynak":"m.12","zorluk":"orta"},
    {"id":"23-S-019","soru":"Yönetmeliğin izne ilişkin hükümlerine göre aşağıdakilerden hangisi yanlıştır?","siklar":["İzin yılı, her senenin ilk ayından itibaren başlar.","İzne giden personel, ayrılmadan evvel birlik veya kurum âmirine gideceği yerin adresini ve iletişim araçlarını bildirir.","Âmir, personelin izin hakkından gönüllü olarak feragat etmesine yönelik tavır, davranış ve imada bulunmamalıdır.","İznin maksadı; personelin dinlenmesi, gücünü toplaması ve yenilenmiş güçle göreve dönmesinin sağlanmasıdır.","İzin yılı, personelin göreve başladığı ay esas alınarak her personel için ayrı ayrı belirlenir."],"dogru":4,"aciklama":"m.14/6: 'İzin yılı, her senenin ilk ayından itibaren başlar.' A doğru, E ise bunun aksini (kişiye özel başlangıç) söylediği için yanlıştır. B (m.14/5), C (m.14/3) ve D (m.14/1) doğrudur.","kaynak":"m.14","zorluk":"orta"},
    {"id":"23-S-020","soru":"Yönetmeliğe göre resmî kıyafetle ilgili olarak aşağıdakilerden hangisi söylenemez?","siklar":["Resmî kıyafet ile sakız çiğnenmez, poşet taşınmaz, ağızda sigara veya eller cepte dolaşılmaz.","Resmî kıyafet ile nişan, evlilik ve devre yüzüğü dışında yüzük, bileklik ve kolye kullanılmaz.","Kadın rütbeli personel, hamileliğini belgelediği takdirde sivil kıyafet ile görev yapabilir.","Araç içinde resmî kıyafetli olarak yolculuk yaparken şapka çıkarılabilir.","Pantolon kemerine veya palaskaya cep telefonu ve gözlük takılması, pratiklik sağladığından serbesttir."],"dogru":4,"aciklama":"m.15/9-d: Pantolon kemerine veya palaskaya cep telefonu, gözlük, çakı takımı, sigaralık vb. aksesuar/malzeme TAKILMAZ. A (b bendi), B (ç bendi), C (m bendi) ve D (f bendi) metne uygundur.","kaynak":"m.15/9","zorluk":"zor"},
    {"id":"23-S-021","soru":"Yönetmeliğin esas duruşu düzenleyen 17'nci maddesine göre aşağıdakilerden hangisi söylenemez?","siklar":["Esas duruş, rütbeli personel ve erlerin ruhen ve bedenen olgunluk ve göreve hazırlık derecesini gösterir.","Âmir veya üst, astın bulunduğu yere gelirse derhal ayağa kalkılır ve esas duruşa geçilir.","Âmir otur veya rahat komutunu vermeden esas duruş bozulmaz.","Devlet memurları da âmir karşısında derhal esas duruşa geçmek zorundadır.","Esas duruşta sessiz kalınır ve aksi emredilmedikçe kımıldanılmaz."],"dogru":3,"aciklama":"m.17/7: 'Devlet memurları esas duruşa geçmez. Ancak amirleri karşısında saygılı bir duruş sergilemek zorundadır.' D bunun aksini söylediği için yanlıştır; A, B, C, E maddeye uygundur.","kaynak":"m.17","zorluk":"orta"},
    {"id":"23-S-022","soru":"Yönetmeliğin selamlamayı düzenleyen 18'inci maddesine göre aşağıdakilerden hangisi yanlıştır?","siklar":["Astlar, üstlerden önce selam vermek zorundadır.","Selamlama gecikmiş bile olsa yapılır, görmemek mazeret teşkil etmez.","Üst veya âmir selamlamayı bitirmeden ast selamlamayı bitiremez.","Elle selamlama, başta şapka, bere veya başlık bulunduğunda sağ el ile yapılır.","Devlet memurları, üstlerini elle selamlamak ve esas duruşa geçmekle yükümlüdür."],"dogru":4,"aciklama":"m.18/16: 'Devlet memurları selamlama ile ilgili hususlardan muaftır. Ancak amirlerine karşı saygılı duruşunu muhafaza etmekle mükelleftir.' E yanlıştır. A (m.18/3), B (m.18/5), C (m.18/3) ve D (m.18/8) doğrudur.","kaynak":"m.18","zorluk":"orta"},
    {"id":"23-S-023","soru":"Yönetmeliğin ahlaki ve manevi vasıfları düzenleyen 19'uncu maddesine göre, personel için 'en büyük ve affedilmeyecek kusur' olarak nitelendirilen husus aşağıdakilerden hangisidir?","siklar":["Korkaklık","İzin sürelerine riayetsizlik","Resmî kıyafette özensizlik","Nöbet sırasını şaşırmak","Selamlamada gecikme"],"dogru":0,"aciklama":"m.19/4-ç: Cesaret ve şecaat vasfı düzenlenirken 'Korkaklık; personel için en büyük ve affedilmeyecek kusurdur.' denir. Maddede bu ağır niteleme yalnız korkaklık için kullanılır.","kaynak":"m.19/4","zorluk":"zor"},
    {"id":"23-S-024","soru":"Yönetmeliğin 19'uncu maddesine göre aşağıdakilerden hangisi her personelde bulunması lazım gelen ahlaki ve manevi vasıflardan biri olarak sayılmamıştır?","siklar":["İtaat","Sır saklamak","Tarafsız siyasi tavır geliştirmek","Sebat ve mukavemet","İntizam severlik"],"dogru":2,"aciklama":"m.19/4'te itaat, sebat ve mukavemet, sır saklamak, intizam severlik gibi vasıflar sayılır. 'Tarafsız siyasi tavır geliştirmek' bu listede yer almaz; uydurma bir vasıftır. Ayrıca m.19'a göre korkaklık en büyük ve affedilmeyecek kusurdur.","kaynak":"m.19/4","zorluk":"orta"},
    {"id":"23-S-025","soru":"Yönetmeliğin basınla münasebeti düzenleyen 22'nci maddesine göre aşağıdakilerden hangisi yanlıştır?","siklar":["Personel, gazete ve dergilere iç ve dış siyaset hakkında yazı yazabilir, Hükümet ve meslek aleyhinde tenkitte bulunabilir.","Kamu görevleri hakkında gerekli bilgi, illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir.","Personel, siyaset hariç olmak üzere bilimsel, tarihi, iktisadi, edebi bir zeminde gazete ve dergilere makale göndermekte serbesttir.","Personel, tek başına veya topluca bildiri dağıtamaz.","Personel, görevi gereği öğrendiği kişisel bilgi veya belgeleri yetkisiz kişilerle paylaşamaz."],"dogru":0,"aciklama":"m.22/4: Personel gazete ve dergilere iç ve dış siyaset hakkında yazı yazAMAZ, Hükümet ve meslek aleyhinde tenkitte bulunAMAZ. A bunun aksini söylediğinden yanlıştır. D (m.22/1), B (m.22/1), C (m.22/5) ve E (m.22/2) doğrudur.","kaynak":"m.22","zorluk":"orta"},
    {"id":"23-S-026","soru":"Yönetmeliğe göre birden fazla birliğin aynı kışla içinde bulunduğu yerlerde kışla komutanı kimdir?","siklar":["En kıdemli birlik komutanı, karargâh veya kurum âmiri","En kıdemsiz birlik komutanı","İl jandarma komutanı tarafından atanan herhangi bir subay","Kışladaki en büyük rütbeli devlet memuru","Nöbetçi amir olarak görevlendirilen astsubay"],"dogru":0,"aciklama":"m.23/1: Birden fazla birliğin aynı kışla içinde bulunduğu yerlerde en kıdemli birlik komutanı, karargâh veya kurum âmiri kışla komutanıdır.","kaynak":"m.23","zorluk":"orta"},
    {"id":"23-S-027","soru":"Yönetmeliğe göre subay, sözleşmeli subay, astsubay, sözleşmeli astsubay ve uzman jandarmaların haftalık çalışma süresi genel olarak __________ saattir.","siklar":["40","45","36","48","42"],"dogru":0,"aciklama":"m.24/1: Sayılan rütbeli personelin haftalık çalışma süresi genel olarak 40 saattir. Bu durum, görevin gerektirdiği hâllerde personelin göreve çağrılmasına veya görev yerinden ayrılmamasına engel teşkil etmez.","kaynak":"m.24","zorluk":"orta"},
    {"id":"23-S-028","soru":"Yönetmeliğe göre haftalık 40 saatlik çalışma süresi, görevin gerektirdiği durumlarda rütbeli personelin görev yerine çağrılmasına veya görev yerinden ayrılmamasına engel teşkil etmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.24/1: 40 saatlik süre, görevin gerektirdiği durumlarda personelin görev yerine çağrılmasına veya görev yerinden ayrılmamasına engel teşkil etmez. İfade doğrudur.","kaynak":"m.24","zorluk":"kolay"},
    {"id":"23-S-029","soru":"Yönetmeliğe göre hazır kıt'anın kuvveti en az kaç kişiden başlayabilir ve en çok ne kadar olabilir?","siklar":["En az iki kişiden, en çok bir takıma kadar","En az üç kişiden, birliğin tamamına kadar","En az beş kişiden, bir bölüğe kadar","En az üç kişiden, en çok on kişiye kadar","En az bir kişiden, birliğin yarısına kadar"],"dogru":1,"aciklama":"m.27/3: Hazır kıt'anın teşkil edileceği zaman ve kuvveti birlik komutanı belirler; bu kıt'anın kuvveti en az üç kişiden birliğin tamamına kadar olabilir.","kaynak":"m.27/3","zorluk":"orta"},
    {"id":"23-S-030","soru":"Yönetmeliğe göre hazır kıt'a, kendisine gösterilen yerde gece dâhil tam teçhizatlı, silahlı ve giyimli olarak harekete hazır bulunur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.27/2: Hazır kıt'a kendisine gösterilen yerde gece dahi tam teçhizatlı, silahlı ve giyimli olarak harekete hazır bulunur. İfade doğrudur.","kaynak":"m.27/2","zorluk":"orta"},
    {"id":"23-OO-001","soru":"Astsubay B, âmiri Binbaşı A'dan, gözaltına alınan bir şüpheliye bilgi alabilmek amacıyla fiziksel şiddet uygulaması yönünde sözlü bir emir alır. Emrin konusu açıkça suç teşkil etmektedir. Yönetmeliğe göre Astsubay B nasıl davranmalıdır?","siklar":["Emri yerine getirir; doğacak sorumluluk emri veren Binbaşı A'ya ait olur.","Aykırılığı Binbaşı A'ya bildirir; A emrini yazı ile yinelerse emri yerine getirir.","Emri hiçbir surette yerine getirmez; yerine getirseydi dahi sorumluluktan kurtulamazdı.","Emri yerine getirir, ardından durumu bir üst âmire ve adli mercilere bildirir.","Emri, yalnızca yazılı olarak teyit edilmesi şartıyla yerine getirir."],"dogru":2,"aciklama":"m.10/4: 'Konusu suç teşkil eden emir hiçbir surette yerine getirilmez; yerine getiren kimse sorumluluktan kurtulamaz.' Suç emrinde yazıyla yineleme veya sorumluluğun emri verene geçmesi gibi bir istisna yoktur; emri yerine getiren de sorumlu olur.","kaynak":"m.10/4","zorluk":"zor"},
    {"id":"23-OO-002","soru":"Uzman jandarma C, âmiri Yüzbaşı D'den aldığı emri mevzuata aykırı bulur ve bu aykırılığı emri veren Yüzbaşı D'ye bildirir. Yüzbaşı D emrinde ısrar eder ve emrini yazı ile yineler. Emir suç teşkil etmemektedir. Yönetmeliğe göre bundan sonra ne olur?","siklar":["Emir yerine getirilmez; aykırı emir hiçbir koşulda uygulanamaz.","Emir yerine getirilir; doğacak sorumluluk emri yerine getiren Uzman jandarma C'ye aittir.","Emir yerine getirilir; doğacak sorumluluk emri veren Yüzbaşı D'ye aittir ve durum D'nin bir üst âmirine bildirilir.","Emir, ancak Uzman jandarma C de yazılı onay verirse yerine getirilir.","Emir yerine getirilir ve sorumluluk emri veren ile yerine getiren arasında eşit paylaşılır."],"dogru":2,"aciklama":"m.10/3: Ast aykırı gördüğü emri yerine getirmez ve aykırılığı emri verene bildirir; ancak âmir ısrar edip emrini yazı ile yinelerse emir yerine getirilir. Bu hâlde sorumluluk emri verene aittir ve durum, emri veren âmirin bir üst âmirine bildirilir.","kaynak":"m.10/3","zorluk":"zor"},
    {"id":"23-OO-003","soru":"Aynı idari işlemden mağdur olduğunu düşünen üç astsubay (A, B ve C), zaman kazanmak için ortak bir metin hazırlayıp üçünün de imzasını taşıyan tek bir dilekçeyle topluca şikâyette bulunmak ister. Yönetmeliğe göre bu durumda nasıl hareket edilmelidir?","siklar":["Üç personel tek ve ortak bir dilekçe ile topluca şikâyet edebilir.","Aynı konuda toplu şikâyet yasaktır; A, B ve C'nin her biri ayrı ayrı veya yalnız başına şikâyet hakkını kullanmalıdır.","Şikâyet, ancak en kıdemli personel olan A tarafından üçü adına yapılabilir.","Aynı olay birden fazla kişiyi ilgilendirdiği için şikâyet hakkı tek bir ortak dilekçeye dönüşür.","Toplu şikâyet, en az üç personel bir araya geldiğinde serbest hâle gelir."],"dogru":1,"aciklama":"m.11/2: Personelin aynı konu ve şahısla ilgili toplu olarak söz veya yazı ile müracaatı yasaktır. Aynı olay birden fazla personelin şikâyetine sebep veya konu olsa bile, bunların her biri ayrı ayrı veya yalnız başına şikâyet hakkını kullanabilir.","kaynak":"m.11/2","zorluk":"orta"},
    {"id":"23-OO-004","soru":"Astsubay E, bir uygulamadan duyduğu rahatsızlık üzerine, âmirinin yüzüne karşı kendisini şikâyet eder ve ayrıca diğer personele 'âmirimden şikâyetçi olacağım' diyerek dedikodu yapar. Yönetmeliğe göre Astsubay E'nin bu davranışının niteliği nedir?","siklar":["Müracaat hakkının olağan bir kullanımıdır, herhangi bir sonuç doğurmaz.","Yalnızca toplu yapılması hâlinde yasaktır; tek başına yapıldığında serbesttir.","Âmirin yüzüne karşı kendisini şikâyet etmek ve şikâyetçi olacağını söyleyerek dedikodu yapmak cezayı muciptir.","Yalnızca yazılı olarak yapılması hâlinde geçerli sayılır.","Şikâyet hakkının kullanımı olduğundan ödül sistemiyle değerlendirilir."],"dogru":2,"aciklama":"m.11/4: Âmirin yüzüne karşı kendisini şikâyet etmek, âmirinden şikâyetçi olacağını söyleyerek dedikodu yapmak cezayı muciptir.","kaynak":"m.11/4","zorluk":"orta"},
    {"id":"23-OO-005","soru":"Farklı birliklerde görev yapan rütbece büyük Binbaşı A ile rütbece küçük Üsteğmen B, bir tören provasında karşılaşır. Aralarında kadro ve kuruluş yönünden bir bağlılık veya âmir olarak yetkilendirme yoktur. Yönetmeliğin tanımlarına göre Binbaşı A, Üsteğmen B'nin nesidir?","siklar":["Âmiridir; çünkü rütbece büyük olan her zaman âmir sayılır.","Üstüdür; çünkü üstlük rütbe veya kıdemce büyük olmakla belirlenir, kadro/kuruluş bağı şart değildir.","Maiyetidir; çünkü aynı törende bulunmaktadırlar.","Ne üstü ne âmiridir; aralarında hiçbir ilişki kurulamaz.","Hem üstü hem âmiridir; rütbe farkı her iki sıfatı da doğurur."],"dogru":1,"aciklama":"m.4: 'Üst: Rütbe veya kıdemce büyük olan kimseyi'; 'Âmir: Kadro ve kuruluş yönünden bağlı olunan kimse ile âmir olarak yetkilendirilmiş olan diğer personeli' ifade eder. Kadro/kuruluş bağı veya yetkilendirme bulunmadığından A, B'nin âmiri değil, rütbe itibarıyla üstüdür.","kaynak":"m.4","zorluk":"zor"},
    {"id":"23-OO-006","soru":"Aynı görev mahallinde bulunan bir uzman jandarma ile bir uzman erbaş arasındaki ilişki sorgulanmaktadır. Yönetmeliğin statüler arası hiyerarşiyi düzenleyen hükümlerine göre aşağıdakilerden hangisi doğrudur?","siklar":["Uzman erbaş, uzman jandarmanın üstüdür.","Aralarında astlık-üstlük ilişkisi bulunmaz, yalnızca amir-maiyet ilişkisi vardır.","Uzman jandarma, uzman erbaşın üstüdür.","İkisi de subay ve astsubayların astı olduğundan birbirlerine eşit konumdadır.","Rütbe eşitliği nedeniyle aralarında hiçbir hiyerarşik ilişki kurulamaz."],"dogru":2,"aciklama":"m.6: Uzman jandarmalar, subay ve astsubayların astı, diğer rütbeli personelin üstüdür; uzman erbaşlar ise subay, astsubay ve uzman jandarmaların astıdır. Dolayısıyla uzman jandarma, uzman erbaşın üstüdür.","kaynak":"m.6","zorluk":"orta"},
    {"id":"23-OO-007","soru":"Bir koridorda ast konumundaki personel ile üstü karşılaşır. Yönetmeliğin selamlama hükümlerine göre bu karşılaşmada nasıl hareket edilmesi gerekir?","siklar":["Üst, asta önce selam verir; ast selamı karşılıksız bırakabilir.","Ast, üstten önce selam verir ve üst selamlamayı bitirmeden ast selamlamayı bitiremez.","Aralarında rütbe farkı bulunduğundan selamlama gerekmez.","Ast üstü görmemişse selamlama yükümlülüğü tamamen ortadan kalkar.","Selamlamayı önce hangisinin yapacağı tarafların serbest takdirine bırakılmıştır."],"dogru":1,"aciklama":"m.18/3: Astlar üstlerden önce selam vermek zorundadır ve üst veya âmir selamlamayı bitirmeden ast selamlamayı bitiremez. Ayrıca m.18/5'e göre selamlama gecikmiş olsa bile yapılır; görmemek mazeret teşkil etmez.","kaynak":"m.18","zorluk":"orta"},
    {"id":"23-OO-008","soru":"Bir büroda görev yapan devlet memuru, âmirin içeri girdiğini fark eder. Yönetmeliğin esas duruşu düzenleyen hükümlerine göre bu devlet memuru ne yapmalıdır?","siklar":["Rütbeli personel gibi derhal ayağa kalkıp esas duruşa geçmelidir.","Esas duruşa geçmez; ancak âmiri karşısında saygılı bir duruş sergilemek zorundadır.","Hiçbir davranış sergilemesine gerek yoktur; memurların âmire karşı yükümlülüğü yoktur.","Yalnızca âmir 'esas duruşa geç' komutu verirse esas duruşa geçer.","Âmir 'otur' deyinceye kadar esas duruşta bekler."],"dogru":1,"aciklama":"m.17/7: 'Devlet memurları esas duruşa geçmez. Ancak amirleri karşısında saygılı bir duruş sergilemek zorundadır.'","kaynak":"m.17/7","zorluk":"orta"},
    {"id":"23-OO-009","soru":"Aynı kışla içinde üç ayrı birlik konuşlanmıştır. Birliklerin sınırlarının ayrılması, kışlaya yasak malzeme sokulmasının engellenmesi ve giriş-çıkışların kontrollü yapılması gibi görevlerin kim tarafından yürütüleceği tartışılmaktadır. Yönetmeliğe göre bu görevler kime aittir?","siklar":["Kışladaki en kıdemsiz birlik komutanına.","En kıdemli birlik komutanı, karargâh veya kurum âmiri olan kışla komutanına.","Birliklerin kendi komutanlarının ayrı ayrı sorumluluğuna; ortak bir komutan bulunmaz.","Kışladaki en yüksek maaşlı devlet memuruna.","İl jandarma komutanlığınca dışarıdan atanacak bir denetçiye."],"dogru":1,"aciklama":"m.23/1: Birden fazla birliğin aynı kışla içinde bulunduğu yerlerde en kıdemli birlik komutanı, karargâh veya kurum âmiri kışla komutanıdır. m.23/2'ye göre sınırların ayrılması, yasak malzemenin engellenmesi ve giriş-çıkışların kontrolü kışla komutanının görevidir.","kaynak":"m.23","zorluk":"orta"},
    {"id":"23-OO-010","soru":"Bir birlik komutanı, birlik emniyetini sağlamak için derhal kullanılmak üzere yalnızca iki kişiden oluşan bir hazır kıt'a teşkil etmek ister. Yönetmeliğe göre bu uygulama mümkün müdür?","siklar":["Mümkündür; hazır kıt'anın asgari kuvveti için bir sınır öngörülmemiştir.","Mümkün değildir; hazır kıt'anın kuvveti en az üç kişiden birliğin tamamına kadar olabilir.","Mümkündür; ancak yalnızca gündüz saatleri için geçerlidir.","Mümkün değildir; hazır kıt'a en az beş kişiden oluşmak zorundadır.","Mümkündür; hazır kıt'anın kuvvetini birlik komutanı değil il komutanı belirler."],"dogru":1,"aciklama":"m.27/3: Hazır kıt'anın teşkil edileceği zaman ve kuvveti ihtiyaca göre birlik komutanı belirler; bu kıt'anın kuvveti en az üç kişiden birliğin tamamına kadar olabilir. İki kişilik kıt'a asgari sınırın altındadır.","kaynak":"m.27/3","zorluk":"orta"},
    {"id":"23-OO-011","soru":"Bir televizyon muhabiri, yürütülen bir kamu göreviyle ilgili olarak görev mahallindeki personelden açıklama yapmasını ister. Yönetmeliğe göre personel nasıl davranmalıdır?","siklar":["Personel, görev mahallinde olduğu için bilgiyi doğrudan kendisi verebilir.","Personel kamu görevi hakkında demeç veremez; bu konuda gerekli bilgi illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir.","Personel, en yakın âmirinden sözlü izin alarak demeç verebilir.","Personel, yalnızca yazılı soru sorulması hâlinde basına bilgi verebilir.","Personel, kişisel sosyal medya hesabından açıklama yaparak muhabiri yönlendirebilir."],"dogru":1,"aciklama":"m.22/1: Personel kamu görevleri hakkında basına, haber ajanslarına, radyo ve televizyon kurumlarına bilgi, yazı ve demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir.","kaynak":"m.22/1","zorluk":"orta"},
  ],
  24: [
    {"id":"JGKIZIN-S-001","soru":"Jandarma Genel Komutanlığı İzin Yönetmeliği'ne göre personele verilecek izin türlerinden biri değildir?","siklar":["Yıllık izin","Mazeret izinleri","Hizmet içi izni","Sıhhi izinler","Yurt dışı izinleri"],"dogru":2,"aciklama":"m.5/1-a uyarınca personele verilecek izinler yalnızca dörttür: yıllık izin, mazeret izinleri, sıhhi izinler ve yurt dışı izinleri. 'Hizmet içi izni' diye bir tür yoktur.","kaynak":"m.5/1-a","zorluk":"kolay"},
    {"id":"JGKIZIN-S-002","soru":"Yönetmeliğe göre yurt dışında izinde bulunup yurda dönme kararı kendisine tebliğ edilen personel, en kısa yoldan ve en seri vasıta ile kaç saat içinde dönüşe geçer?","siklar":["24 saat","36 saat","48 saat","72 saat","96 saat"],"dogru":2,"aciklama":"m.5/1-i: Yurda dönme kararı tebliğ edilen personel 48 saat içerisinde, en kısa yoldan ve en seri vasıta ile dönüşe geçer.","kaynak":"m.5/1-i","zorluk":"orta"},
    {"id":"JGKIZIN-S-003","soru":"Yönetmeliğe göre personel, görev yaptığı ilin dışına izinsiz çıkamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5/1-j: 'Personel görev yaptığı ilin dışına izinsiz çıkamaz.' Hüküm birebir bu yöndedir.","kaynak":"m.5/1-j","zorluk":"kolay"},
    {"id":"JGKIZIN-S-004","soru":"Yönetmeliğe göre savaş ve olağanüstü hallerde izin sürelerinin kısaltılması veya kaldırılması ile personelin izinden geriye çağrılması hangi Kanunun ek 3 üncü maddesine dayanır?","siklar":["657 sayılı Devlet Memurları Kanunu","926 sayılı Türk Silâhlı Kuvvetleri Personel Kanunu","5442 sayılı İl İdaresi Kanunu","2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu","211 sayılı İç Hizmet Kanunu"],"dogru":3,"aciklama":"m.5/1-g: Savaş ve olağanüstü hallerde 2803 sayılı Kanunun ek 3 üncü maddesi uyarınca izin süreleri kısaltılabilir veya kaldırılabilir; bu hâllerde personel izinden geriye çağrılabilir.","kaynak":"m.5/1-g","zorluk":"orta"},
    {"id":"JGKIZIN-S-005","soru":"Yönetmeliğe göre adli bir makama şüpheli, sanık, tanık, mağdur veya bilirkişi sıfatıyla çağrılan personelin bu nedenle geçen süresi, kullanmakta olduğu kanuni izninden mahsup edilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.5/1-d: Adli bir makama (şüpheli, sanık, tanık, mağdur veya bilirkişi olarak) çağrılma nedeniyle geçen süre kanuni izinden MAHSUP EDİLMEZ. İfade tersini söylediğinden yanlıştır.","kaynak":"m.5/1-d","zorluk":"orta"},
    {"id":"JGKIZIN-S-006","soru":"Yönetmeliğe göre izin işlemlerine ilişkin genel esaslardan hangisi yanlıştır?","siklar":["Personel görev yaptığı ilin dışına izinsiz çıkamaz","Yurt dışında izinde bulunup yurda dönme kararı tebliğ edilen personel 48 saat içinde dönüşe geçer","Adli bir makama tanık sıfatıyla çağrılma nedeniyle geçen süre kanuni izinden mahsup edilmez","Kursiyerlere, kurs süresince her hâlükârda yıllık izinleri eksiksiz kullandırılır","Savaş ve olağanüstü hallerde personel izinden geriye çağrılabilir"],"dogru":3,"aciklama":"m.5/1-m: Kursiyerlere kurs süresince izin verilmez (planlı tatil ve geçerli özür hâlleri hariç). D bu hükmün tersi olduğundan yanlıştır.","kaynak":"m.5/1-d, m.5/1-g, m.5/1-i, m.5/1-j, m.5/1-m","zorluk":"orta"},
    {"id":"JGKIZIN-S-007","soru":"Yönetmeliğe göre iznin başlangıç ve bitiş saati kural olarak hangi andır?","siklar":["Günün başlangıç saati","Mesainin başlangıç saati","Mesainin bitiş saati","Öğle saati (12.00)","Personelin birliğinden fiilen ayrıldığı saat"],"dogru":0,"aciklama":"m.5/1-h: İznin başlangıç ve bitiş saati günün başlangıç saatidir; yetkili amir istisnai durumlarda bu saati değiştirebilir.","kaynak":"m.5/1-h","zorluk":"zor"},
    {"id":"JGKIZIN-S-008","soru":"Yönetmeliğe göre yurt dışında izinde bulunup yurda dönme kararı tebliğ edilen personel, 48 saat içerisinde, ____ ve ____ ile dönüşe geçer.","siklar":["en kısa yoldan - en seri vasıta","en ekonomik yoldan - kara yolu","bağlı olduğu birliğin belirlediği güzergâhtan - toplu taşıma","en uygun yoldan - resmî araç","izin belgesinde yazılı güzergâhtan - hava yolu"],"dogru":0,"aciklama":"m.5/1-i: Personel 48 saat içerisinde en kısa yoldan ve en seri vasıta ile dönüşe geçer.","kaynak":"m.5/1-i","zorluk":"orta"},
    {"id":"JGKIZIN-S-009","soru":"Yönetmeliğe göre personele verilecek izinler kaç türdür?","siklar":["İki","Üç","Dört","Beş","Altı"],"dogru":2,"aciklama":"m.5/1-a: Yıllık izin, mazeret izinleri, sıhhi izinler ve yurt dışı izinleri olmak üzere dört tür izin vardır.","kaynak":"m.5/1-a","zorluk":"kolay"},
    {"id":"JGKIZIN-S-010","soru":"Yönetmeliğe göre seyahat maksadıyla yurt dışına giden personelin götüremeyeceği silahlar aşağıdakilerin hangisinde eksiksiz verilmiştir?","siklar":["Yalnız miri silah","Yalnız zati silah","Şahsi ve miri silah (zati hariç)","Şahsi, zati ve miri silah","Yalnız şahsi silah"],"dogru":3,"aciklama":"m.20/1-e: Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez.","kaynak":"m.20/1-e","zorluk":"orta"},
    {"id":"JGKIZIN-S-011","soru":"Yönetmeliğe göre izinli olarak yurt dışında bulunan personel zorunlu olmadıkça üniforma giyemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.20/1-d: Zorunlu olmadıkça üniforma giyemez. İfade hükümle birebir uyumludur.","kaynak":"m.20/1-d","zorluk":"kolay"},
    {"id":"JGKIZIN-S-012","soru":"Yönetmeliğe göre izinli olarak yurt dışında bulunan personel, ____ ve ____ birer temsilcisi olarak gerek resmî gerekse özel hayatlarını Türk Jandarmasına yaraşır şekilde düzenlemek zorundadır.","siklar":["Devletin - Hükûmetin","Milletimizin - Jandarma Genel Komutanlığının","Türk Silahlı Kuvvetlerinin - İçişleri Bakanlığının","Milletimizin - Cumhurbaşkanlığının","Devletin - Sahil Güvenlik Komutanlığının"],"dogru":1,"aciklama":"m.20/1-a: Personel, milletimizin ve Jandarma Genel Komutanlığının birer temsilcisi olarak gerek resmî gerekse özel hayatlarını Türk Jandarmasına yaraşır şekilde düzenler.","kaynak":"m.20/1-a","zorluk":"orta"},
    {"id":"JGKIZIN-S-013","soru":"Yönetmeliğe göre izinli olarak yurt dışında bulunan personel, Jandarma Genel Komutanlığınca belirlenen hangi esaslara uymak zorundadır?","siklar":["Trafik ve gümrük kurallarına","İstihbarata karşı koyma ve koruyucu güvenlik esaslarına","Protokol ve nezaket kurallarına","Uluslararası seyahat ve vize esaslarına","Mali disiplin ve harcama esaslarına"],"dogru":1,"aciklama":"m.20/3: Personel, Jandarma Genel Komutanlığınca belirlenen istihbarata karşı koyma ve koruyucu güvenlik esaslarına uyar.","kaynak":"m.20/3","zorluk":"orta"},
    {"id":"JGKIZIN-S-014","soru":"Yönetmeliğe göre yurt dışına izinli gidecek personele, istihbarata karşı koyma ve koruyucu güvenlik önlemleri konusunda herhangi bir uyarıcı bilgilendirme yapılmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.20/2: Personele bağlı bulunduğu birlik, karargâh ve kurum amirlikleri tarafından istihbarata karşı koyma ve koruyucu güvenlik önlemleri konularında uyarıcı bilgiler VERİLİR. İfade tersini söylediğinden yanlıştır.","kaynak":"m.20/2","zorluk":"orta"},
    {"id":"JGKIZIN-S-015","soru":"Yönetmeliğe göre izinli yurt dışındaki personel; yabancı askeri ve kolluk personeline karşı tavır ve hareketlerinde meslekî ____ ve ____ muhafaza eder.","siklar":["disiplini - hiyerarşiyi","vakarı - ananeyi","saygıyı - mesafeyi","gizliliği - tedbiri","nezaketi - protokolü"],"dogru":1,"aciklama":"m.20/1-b: Personel, meslekî vakar ve ananeyi muhafaza eder.","kaynak":"m.20/1-b","zorluk":"orta"},
    {"id":"JGKIZIN-S-016","soru":"Yönetmeliğe göre 'yurt dışında izinde riayet edilecek hususlar'ı düzenleyen hüküm, aşağıdaki personelden hangisini kapsamına almamıştır?","siklar":["Subay","Sözleşmeli astsubay","Uzman jandarma","Uzman erbaş","Sivil memur"],"dogru":4,"aciklama":"m.20/1: Hüküm subay, sözleşmeli subay, astsubay, sözleşmeli astsubay, uzman jandarma ve uzman erbaşları sayar; 'sivil memur' bu sayımda yer almaz.","kaynak":"m.20/1","zorluk":"orta"},
    {"id":"JGKIZIN-S-017","soru":"Yönetmeliğe göre izinli yurt dışındaki personel, yabancılarla temasta serbestçe ve herhangi bir özen göstermeksizin hareket edebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.20/1-c: Personel yabancılarla temasta daha titiz ve dikkatli davranır, herhangi bir olumsuz olaya sebebiyet vermemek için özen gösterir. İfade hükmün tersidir.","kaynak":"m.20/1-c","zorluk":"orta"},
    {"id":"JGKIZIN-S-018","soru":"Yönetmeliğe göre izinli yurt dışındaki personel, mevzuat ve malî imkânlarına göre nasıl yaşamak zorundadır?","siklar":["Mutlaka resmî misafirhanede","Yalnızca Türk vatandaşlarının yaşadığı bölgelerde","Büyükelçiliğin tahsis ettiği konutta","Uygun bir meskende ve meslekî şerefe uygun bir şekilde","En düşük maliyetli her koşulda"],"dogru":3,"aciklama":"m.20/1-ç: Mevzuat ve malî imkânlarına göre uygun bir meskende ve meslekî şerefe uygun bir şekilde yaşamak zorundadır.","kaynak":"m.20/1-ç","zorluk":"orta"},
    {"id":"JGKIZIN-S-019","soru":"Yönetmeliğe göre savaş ve olağanüstü hallerde personelin izinleriyle ilgili olarak aşağıdakilerden hangisi yapılabilir?","siklar":["İzin süreleri kısaltılabilir veya kaldırılabilir ve personel izinden geriye çağrılabilir","İzinler yalnızca uzatılabilir, hiçbir şekilde kısaltılamaz","İzinler hiçbir surette etkilenmez","Yalnızca yurt dışı izinleri iptal edilir, diğerleri aynen korunur","İzinli personel ancak kendi yazılı talebiyle geri çağrılabilir"],"dogru":0,"aciklama":"m.5/1-g: Savaş ve olağanüstü hallerde 2803 sayılı Kanunun ek 3 üncü maddesi uyarınca izin süreleri kısaltılabilir veya kaldırılabilir; bu hâllerde personel izinden geriye çağrılabilir.","kaynak":"m.5/1-g","zorluk":"orta"},
    {"id":"JGKIZIN-S-020","soru":"Yönetmeliğe göre kursiyerlere kurs süresince izin verilmesi konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Kurs süresince izin verilmez; ancak planlı tatil ve geçerli özür hâlleri saklıdır","Kursiyerlere her ay üç gün izin verilir","Kursiyerlere yalnızca yıllık izin verilir","Kursiyerlere kurs süresince sınırsız izin verilir","Kursiyerlere yalnızca mazeret izni verilmez, diğer izinler verilir"],"dogru":0,"aciklama":"m.5/1-m: Kursiyerlere kurs süresince izin verilmez; planlı tatil ve geçerli özür hâlleri bunun istisnasıdır.","kaynak":"m.5/1-m","zorluk":"orta"},
    {"id":"JGKIZIN-S-021","soru":"Yönetmeliğe göre personele il dışına çıkması veya özel günler için verilen izin, personelin kanuni izninden mahsup edilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5/1-j: İl dışına çıkış/özel gün izni kanuni izinden mahsup edilmez. İfade hükümle uyumludur.","kaynak":"m.5/1-j","zorluk":"orta"},
    {"id":"JGKIZIN-S-022","soru":"Yönetmeliğe göre ____ maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez.","siklar":["öğrenim","seyahat","mesleki bilgi ve görgü","seminer ve müşahede","mazeret"],"dogru":1,"aciklama":"m.20/1-e: Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez.","kaynak":"m.20/1-e","zorluk":"orta"},
    {"id":"JGKIZIN-S-023","soru":"Yönetmeliğe göre izinli olarak yurt dışında bulunan personelin üniforma giymesiyle ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Zorunlu olmadıkça giyemez; yani ancak zorunlu hâllerde giyebilir","Hiçbir surette üniforma giyemez","İstediği her zaman üniforma giyebilir","Yalnızca resmî törenlerde üniforma giymek zorundadır","Yalnızca büyükelçiliğin izniyle üniforma giyebilir"],"dogru":0,"aciklama":"m.20/1-d: Zorunlu olmadıkça üniforma giyemez; dolayısıyla yasak mutlak değildir, zorunlu hâllerde üniforma giyilebilir.","kaynak":"m.20/1-d","zorluk":"zor"},
    {"id":"JGKIZIN-S-024","soru":"Yönetmeliğe göre izinli olarak yurt dışında bulunan personelin riayet edeceği hususlardan hangisi yanlıştır?","siklar":["Milletimizin ve Jandarma Genel Komutanlığının birer temsilcisi olarak hareket etmek zorundadır","Yabancılarla temasta daha titiz ve dikkatli davranır","Zorunlu olmadıkça üniforma giyemez","Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez","Resmî temaslarda her zaman üniforma giymek zorundadır"],"dogru":4,"aciklama":"m.20/1-d: Personel zorunlu olmadıkça üniforma giyemez. 'Her zaman üniforma giymek zorundadır' ifadesi hükmün tersidir.","kaynak":"m.20/1","zorluk":"orta"},
    {"id":"JGKIZIN-S-025","soru":"Yönetmeliğe göre kanuni izinden mahsup edilmeme hâlleriyle ilgili aşağıdakilerden hangisi yanlıştır?","siklar":["Adli bir makama tanık sıfatıyla çağrılma nedeniyle geçen süre kanuni izinden mahsup edilmez","Adli bir makama bilirkişi sıfatıyla çağrılma nedeniyle geçen süre kanuni izinden mahsup edilmez","İl dışına çıkması için verilen izin kanuni izinden mahsup edilmez","Özel günler için verilen izin kanuni izinden mahsup edilmez","Adli bir makama şüpheli sıfatıyla çağrılma nedeniyle geçen süre kanuni izinden mahsup edilir"],"dogru":4,"aciklama":"m.5/1-d: Şüpheli, sanık, tanık, mağdur veya bilirkişi sıfatıyla adli çağrı nedeniyle geçen süre mahsup edilmez; m.5/1-j: il dışı/özel gün izni de mahsup edilmez. E, şüpheli sıfatıyla çağrı süresinin mahsup edileceğini söyleyerek hükmün tersini ifade eder.","kaynak":"m.5/1-d, m.5/1-j","zorluk":"zor"},
    {"id":"JGKIZIN-OO-001","soru":"Astsubay A, kullanmakta olduğu 30 günlük yıllık iznindeyken memleketinde tanık olduğu bir trafik kazasıyla ilgili olarak Cumhuriyet savcılığınca tanık sıfatıyla ifadeye çağrılır ve bu çağrı nedeniyle iki günü adliyede geçer. Bu iki günlük süreyle ilgili Yönetmeliğe göre nasıl bir işlem yapılır?","siklar":["İki günlük süre A'nın kanuni izninden mahsup edilir","İki günlük süre A'nın kanuni izninden mahsup edilmez","İki günlük süre yıllık mazeret izninden düşülür","İki günlük süre için A'ya disiplin işlemi yapılır","A'nın yıllık izni iki gün uzatılır ancak gelecek yıldan düşülür"],"dogru":1,"aciklama":"m.5/1-d: Adli bir makama şüpheli, sanık, tanık, mağdur veya bilirkişi sıfatıyla çağrılma nedeniyle geçen süre, personelin kullanmakta olduğu kanuni izninden mahsup edilmez. A tanık olarak çağrıldığından bu süre izninden düşülmez.","kaynak":"m.5/1-d","zorluk":"orta"},
    {"id":"JGKIZIN-OO-002","soru":"Ülke genelinde olağanüstü hâl ilan edilir. Bu sırada yıllık iznini kullanmakta olan personelin durumu gündeme gelir. Yönetmeliğe göre bu personelle ilgili olarak yetkili makam ne yapabilir?","siklar":["İzin süreleri kısaltılabilir veya kaldırılabilir ve personel izinden geriye çağrılabilir","Olağanüstü hâl boyunca tüm izinler kendiliğinden ikiye katlanır","İzinler hiçbir şekilde etkilenemez; personel iznini sonuna kadar kullanır","Yalnızca yurt dışı izinleri iptal edilir, yurt içi izinler aynen sürer","Personel ancak kendi yazılı muvafakatini verirse geri çağrılabilir"],"dogru":0,"aciklama":"m.5/1-g: Savaş ve olağanüstü hallerde 2803 sayılı Kanunun ek 3 üncü maddesi uyarınca izin süreleri kısaltılabilir veya kaldırılabilir; bu hâllerde personel izinden geriye çağrılabilir.","kaynak":"m.5/1-g","zorluk":"orta"},
    {"id":"JGKIZIN-OO-003","soru":"Yurt dışında seyahat izninde bulunan personel B'ye, birliği tarafından yurda dönmesi kararı usulüne uygun olarak tebliğ edilir. Yönetmeliğe göre B nasıl hareket etmelidir?","siklar":["İznin bitiş tarihini bekleyip planladığı tarihte döner","72 saat içinde, en ekonomik ulaşım aracıyla döner","48 saat içerisinde, en kısa yoldan ve en seri vasıta ile dönüşe geçer","Bulunduğu ülkedeki Türk büyükelçiliğinin belirleyeceği güzergâhtan döner","Dönüş için ayrıca yeni bir izin talebi yapana kadar bekler"],"dogru":2,"aciklama":"m.5/1-i: Yurt dışında izinde bulunup yurda dönme kararı kendisine tebliğ edilen personel, 48 saat içerisinde, en kısa yoldan ve en seri vasıta ile dönüşe geçer.","kaynak":"m.5/1-i","zorluk":"orta"},
    {"id":"JGKIZIN-OO-004","soru":"Görev yaptığı il merkezinde bulunan personel C, hafta sonu tatilinde komşu ildeki bir akrabasının düğününe katılmak için herhangi bir izin almadan o ile gider. Yönetmeliğe göre C'nin bu davranışı için ne söylenebilir?","siklar":["Hafta sonu tatili olduğundan il dışına izinsiz çıkması serbesttir","Yalnızca yurt dışına çıkışta izin gerektiğinden il dışı çıkış serbesttir","Komşu il sınırına 100 km'den yakınsa izin gerekmez","Personel görev yaptığı ilin dışına izinsiz çıkamayacağından C'nin davranışı Yönetmeliğe aykırıdır","Düğün gibi özel günlerde il dışı çıkış kendiliğinden izinli sayılır"],"dogru":3,"aciklama":"m.5/1-j: Personel görev yaptığı ilin dışına izinsiz çıkamaz. C izin almadan il dışına çıktığından davranışı bu hükme aykırıdır.","kaynak":"m.5/1-j","zorluk":"kolay"},
    {"id":"JGKIZIN-OO-005","soru":"Bir kursa katılan personel D, kurs henüz devam ederken yıllık izninden birkaç gün kullanmak için talepte bulunur. Ortada planlı bir tatil veya geçerli bir özür hâli bulunmamaktadır. Yönetmeliğe göre bu talep nasıl değerlendirilir?","siklar":["Kursiyerlere kurs süresince izin verilmediğinden talep karşılanmaz","Kursiyere her ay üç gün izin verildiğinden talep bu kapsamda karşılanır","Kursiyerin yıllık izni öncelikli olduğundan talep mutlaka karşılanır","Kursiyere kurs süresince sınırsız izin verilebildiğinden talep karşılanır","Kursiyere yalnızca mazeret izni verilemez; yıllık izin talebi karşılanır"],"dogru":0,"aciklama":"m.5/1-m: Kursiyerlere kurs süresince izin verilmez; planlı tatil ve geçerli özür hâlleri bunun istisnasıdır. Olayda istisna hâl bulunmadığından talep karşılanmaz.","kaynak":"m.5/1-m","zorluk":"orta"},
    {"id":"JGKIZIN-OO-006","soru":"İzinli olarak yurt dışında bulunan personel E, gezdiği şehirde fotoğraf çektirmek amacıyla yanına aldığı üniformasını giymek ister; ortada herhangi bir zorunlu hâl yoktur. Yönetmeliğe göre E'nin bu davranışı için ne söylenebilir?","siklar":["Yurt dışında temsil amacıyla her zaman üniforma giyilebileceğinden E serbesttir","Zorunlu olmadıkça üniforma giyilemeyeceğinden E üniforma giyemez","Üniforma yalnızca resmî törenlerde giyilebildiğinden fotoğraf için giyebilir","Üniforma hiçbir surette giyilemeyeceğinden zorunlu hâlde bile giyemez","Büyükelçilikten izin alması hâlinde her amaçla üniforma giyebilir"],"dogru":1,"aciklama":"m.20/1-d: İzinli olarak yurt dışında bulunan personel zorunlu olmadıkça üniforma giyemez. Olayda zorunlu hâl bulunmadığından E üniforma giyemez.","kaynak":"m.20/1-d","zorluk":"orta"},
    {"id":"JGKIZIN-OO-007","soru":"Personel F, seyahat maksadıyla yurt dışına çıkacaktır ve kişisel güvenliği için yanında zati silahını da götürmek ister. Yönetmeliğe göre F'nin bu talebi yerinde midir?","siklar":["Evet; yalnızca miri silah götürülemez, zati silah serbesttir","Evet; kişisel güvenlik gerekçesiyle her tür silah götürülebilir","Hayır; seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez","Evet; zati ve şahsi silah götürülebilir, yalnız miri silah yasaktır","Hayır; ancak büyükelçiliğe bildirim yapılırsa zati silah götürülebilir"],"dogru":2,"aciklama":"m.20/1-e: Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez. Yasak üç silah türünü de kapsadığından F zati silahını götüremez.","kaynak":"m.20/1-e","zorluk":"orta"},
    {"id":"JGKIZIN-OO-008","soru":"Yurt dışına izinli gidecek personel G'ye, birlik amirliği yurt dışındaki hareket tarzı hakkında bilgilendirme yapar; G ayrıca yurt dışındayken bazı esaslara uymakla yükümlüdür. Yönetmeliğe göre bu bilgilendirme ve uyulacak esaslar hangi konuya ilişkindir?","siklar":["Gidilen ülkenin trafik ve gümrük kurallarına","İstihbarata karşı koyma ve koruyucu güvenlik esaslarına","Uluslararası protokol ve nezaket kurallarına","Yurt dışı harcamalarında mali disiplin esaslarına","Konaklama ve seyahat sigortası esaslarına"],"dogru":1,"aciklama":"m.20/2: Yurt dışına izinli gidecek personele amirliklerce istihbarata karşı koyma ve koruyucu güvenlik önlemleri konusunda uyarıcı bilgiler verilir; m.20/3: personel, Jandarma Genel Komutanlığınca belirlenen istihbarata karşı koyma ve koruyucu güvenlik esaslarına uyar.","kaynak":"m.20/2, m.20/3","zorluk":"zor"},
  ],
  25: [
    {"id":"6136-S-001","soru":"6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanun'un 4. maddesine göre, aşağıdakilerden hangisinin yapımı yasak değildir?","siklar":["Sustalı çakı","Muşta","Yalnız sporda kullanılan yivsiz av tüfeği","Boğma teli veya zinciri","Şişli baston"],"dogru":2,"aciklama":"m.4/1 kama, hançer, saldırma, şişli baston, sustalı çakı, muşta, boğma teli veya zinciri gibi salt saldırı ve savunmada kullanılan özel aletlerin yapımını yasaklar. Aynı maddeye göre yalnız sporda kullanılan yivsiz tüfekler ve mermileri Kanun hükümlerine tabi değildir; yapımı serbesttir.","kaynak":"6136 m.4/1","zorluk":"orta"},
    {"id":"6136-S-002","soru":"6136 sayılı Kanun'un 4. maddesine göre, bir sanat veya mesleğin icrası için kullanılması zorunlu bulunan bıçak ve aletlerin yapımına, çıkarılacak bir yönetmelikte belirlenen kurallara göre hangi makam izin verir?","siklar":["Adalet Bakanlığı","İçişleri Bakanlığı","Milli Savunma Bakanlığı","Emniyet Genel Müdürlüğü","Cumhurbaşkanlığı"],"dogru":1,"aciklama":"m.4/1: 'Bunlardan bir sanat veya mesleğin icrası için kullanılması zorunlu bulunanların yapımına İçişleri Bakanlığınca yapılacak bir yönetmelikte belirlenen kurallara göre izin verilir.'","kaynak":"6136 m.4/1","zorluk":"orta"},
    {"id":"6136-S-003","soru":"6136 sayılı Kanun'un 5. maddesine göre, 4. maddenin 1. fıkrası kapsamına giren yasak bıçak ve aletler bakımından aşağıdaki fiillerden hangisi maddede sayılan yasaklar arasında DEĞİLDİR?","siklar":["Kiraya verilmesi","Satılması","Satın alınması","Taşınması","Bulundurulması"],"dogru":0,"aciklama":"m.5: '...4 ncü maddenin 1 nci fıkrası kapsamına giren bıçak ve aletlerin satılması, satınalınması, taşınması ve bulundurulması yasaktır.' Maddede 'kiraya verme' fiili yer almaz.","kaynak":"6136 m.5","zorluk":"orta"},
    {"id":"6136-S-004","soru":"6136 sayılı Kanun'un 5. maddesine göre, bir sanat veya mesleğin icrası için 4. maddeye göre yapımına izin verilen bıçaklar, satış-taşıma-bulundurma yasağının dışındadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.5 son cümle: 'Bir sanat veya mesleğin icrası için kullanılmasına 4 ncü maddeye göre izin verilen bıçaklar bu yasağın dışındadırlar.'","kaynak":"6136 m.5","zorluk":"kolay"},
    {"id":"6136-S-005","soru":"6136 sayılı Kanun'un 11. maddesindeki tanıma göre, bir ateşli silah veya bıçağın 'antika silah' sayılabilmesi için maddede aranan niteliklerden biri aşağıdakilerden hangisi DEĞİLDİR?","siklar":["Eskiden kalma olması","Değerli, belli bir özelliği bulunması","Benzerlerine az rastlanması","Artık imal edilmiyor olması","Bir Devlet veya hükümet başkanı tarafından hediye edilmiş olması"],"dogru":4,"aciklama":"m.11: 'Antika silah deyimi; eskiden kalma, değerli belli bir özelliği olan, benzerlerine az rastlanan ve artık imal edilmeyen ateşli, ateşsiz silah ve bıçakları ifade eder.' A, B, C, D bu tanımın dört unsurudur. 'Devlet veya hükümet başkanınca hediye edilmiş olma' ise maddedeki 'hatıra silah' deyiminin unsurudur, antika silahın değil.","kaynak":"6136 m.11","zorluk":"zor"},
    {"id":"6136-S-006","soru":"6136 sayılı Kanun'un 11. maddesine göre, antika olan ateşli silahlar için verilen izin, bu silahların üstte taşınmasına da cevaz verir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.11: Antika silah-bıçaklar için verilen izin yalnız sahibine bırakılmasına veya nakline müsaadeyi içerir; 'üstte taşımaya cevaz vermez.' Dolayısıyla ifade yanlıştır.","kaynak":"6136 m.11","zorluk":"orta"},
    {"id":"6136-S-007","soru":"6136 sayılı Kanun'un 11. maddesine göre, antika olan ateşli silahlarla bıçakların __________ birlikte satışı serbesttir.","siklar":["bedeli peşin ödenmek şartıyla","yalnızca müzelere satılmak şartıyla","izin vesikalarıyla","noter sözleşmesiyle","İçişleri Bakanlığının ön onayıyla"],"dogru":2,"aciklama":"m.11: 'Antika olan ateşli silahlarla bıçakların izin vesikalarıyla birlikte satışı serbesttir.'","kaynak":"6136 m.11","zorluk":"orta"},
    {"id":"6136-S-008","soru":"6136 sayılı Kanun'un 12. maddesine göre, Kanun kapsamındaki ateşli silahları ülkeye sokan, ülkede yapan, satan veya bir yerden diğerine taşıyan kişi kural olarak ne kadar hapis cezası ile cezalandırılır?","siklar":["Altı aydan bir yıla kadar","Beş yıldan oniki yıla kadar","İki yıldan dört yıla kadar","Bir yıldan üç yıla kadar","Beş yıldan sekiz yıla kadar"],"dogru":1,"aciklama":"m.12/1: ateşli silahları ülkeye sokan/yapan/taşıyan/satan veya bu amaçla bulunduran kişi 'beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezası' ile cezalandırılır.","kaynak":"6136 m.12/1","zorluk":"orta"},
    {"id":"6136-S-009","soru":"6136 sayılı Kanun'un 12. maddesine göre, ateşli silah suçunun suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde verilecek cezalar nasıl belirlenir?","siklar":["Cezalar yarı oranında artırılır","Cezalar yarıya indirilir","Ceza miktarı değişmez","Cezalar iki kat artırılır","Verilecek cezalar bir kat artırılır"],"dogru":4,"aciklama":"m.12: suçun 'suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek cezalar bir kat artırılır.'","kaynak":"6136 m.12/3","zorluk":"zor"},
    {"id":"6136-S-010","soru":"6136 sayılı Kanun'un 12. maddesine göre, ateşli silah sokma/yapma/satma suçunun iki veya daha çok kişi tarafından birlikte işlenmesi halinde verilecek ceza beş yıldan oniki yıla kadar hapistir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"m.12: iki veya daha çok kişinin birlikte işlemesi halinde ceza 'sekiz yıldan onbeş yıla kadar hapis ve bin günden onbin güne kadar adlî para cezasıdır.' Beş yıldan oniki yıla kadar olan, suçun tek kişiyle işlendiği temel haldir.","kaynak":"6136 m.12/2","zorluk":"zor"},
    {"id":"6136-S-011","soru":"6136 sayılı Kanun'un 12. maddesine göre, suça konu ateşli silah, mermi veya parçaların miktar bakımından vahim olması halinde cezalar nasıl belirlenir?","siklar":["Bir kat artırılır","İki kat artırılır","Üçte bir oranında indirilir","Yarı oranında artırılır","Otuz günden beşyüz güne kadar adlî para cezasına çevrilir"],"dogru":3,"aciklama":"m.12: suça konu eşyanın 'miktar bakımından vahim olması halinde... cezalar yarı oranında artırılarak hükmolunur.'","kaynak":"6136 m.12/son","zorluk":"zor"},
    {"id":"6136-S-012","soru":"6136 sayılı Kanun'un 13. maddesine göre, Kanun hükümlerine aykırı olarak ateşli silahları satın alan, taşıyan veya bulunduran kişiler kural olarak ne kadar hapis cezası ile cezalandırılır?","siklar":["İki yıldan dört yıla kadar","Beş yıldan oniki yıla kadar","Altı aydan bir yıla kadar","Beş yıldan sekiz yıla kadar","Üç aya kadar"],"dogru":0,"aciklama":"m.13/1: ruhsatsız ateşli silahı satın alan/taşıyan/bulunduranlar hakkında 'iki yıldan dört yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasına hükmolunur.'","kaynak":"6136 m.13/1","zorluk":"orta"},
    {"id":"6136-S-013","soru":"6136 sayılı Kanun'un 13. maddesine göre, ruhsatsız ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin ev veya işyerinde bulundurulması halinde verilecek ceza nedir?","siklar":["İki yıldan dört yıla kadar hapis","Beş yıldan sekiz yıla kadar hapis","Bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezası","Altı aydan bir yıla kadar hapis","Yalnızca onbin Türk Lirası idari para cezası"],"dogru":2,"aciklama":"m.13: ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin ev veya işyerinde bulundurulması halinde ceza 'bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır.'","kaynak":"6136 m.13/3","zorluk":"zor"},
    {"id":"6136-S-014","soru":"6136 sayılı Kanun'un 12. maddesi uyarınca beş yıldan oniki yıla kadar cezayı gerektiren fiillerden biri aşağıdakilerden hangisi DEĞİLDİR?","siklar":["Ateşli silahı ülkeye sokmak","Ateşli silahı ülkede yapmak","Ateşli silahı satmak veya satmaya aracılık etmek","Ruhsatsız ateşli silahı satın almak","Ateşli silahı bir yerden diğer bir yere taşımak veya yollamak"],"dogru":3,"aciklama":"Ülkeye sokma, ülkede yapma, satma, bir yerden diğerine taşıma/yollama m.12'nin (5-12 yıl) fiilleridir. 'Ruhsatsız satın alma' ise m.13 kapsamında daha hafif (2-4 yıl) cezalandırılır.","kaynak":"6136 m.12-13","zorluk":"zor"},
    {"id":"6136-S-015","soru":"6136 sayılı Kanun'un 15. maddesine göre, 4. maddede yazılı bıçak veya aletleri satan, taşıyan veya bulunduran kişi hakkında hükmolunacak ceza nedir?","siklar":["İki yıldan dört yıla kadar hapis","Altı aydan bir yıla kadar hapis ve yirmibeş günden az olmamak üzere adlî para cezası","Beş yıldan oniki yıla kadar hapis","Bir yıldan üç yıla kadar hapis","Elli günden az olmamak üzere adlî para cezası"],"dogru":1,"aciklama":"m.15/1: m.4'teki bıçak veya aletleri satan, satmaya aracılık eden, satın alan, taşıyan veya bulunduranlar 'altı aydan bir yıla kadar hapis ve yirmibeş günden az olmamak üzere adlî para cezası' ile cezalandırılır.","kaynak":"6136 m.15/1","zorluk":"orta"},
    {"id":"6136-S-016","soru":"6136 sayılı Kanun'un 15. maddesine göre, suça konu bıçak veya aletlerin sayı veya nitelik bakımından vahim olması halinde verilecek ceza yarıdan bir katına kadar artırılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"m.15: 'bıçak veya diğer aletlerin... sayı veya nitelik bakımından vahim olması halinde yukarıdaki fıkraya göre hükmolunacak cezalar yarıdan bir katına kadar artırılır.'","kaynak":"6136 m.15/2","zorluk":"orta"},
    {"id":"6136-S-017","soru":"6136 sayılı Kanun'un Ek 1. maddesine göre, aşağıdakilerden hangisi ateşli silah taşınamayan yerlerden biri DEĞİLDİR?","siklar":["Mahkeme salonları ve duruşmalar","İbadethaneler ve cami avluları","Eğitim ve öğretim kurumları","Her türlü spor karşılaşma veya yarışmalarının yapıldığı yerler","Türkiye Büyük Millet Meclisi ana binaları"],"dogru":1,"aciklama":"Ek m.1, silah taşınamayan yerleri (A) mahkeme/tutukevi vb., (B) okul/yurt/miting/stadyum/sendika/dernek vb., (C) TBMM ana binaları olarak sayar. İbadethaneler/camiler bu listede yer almaz.","kaynak":"6136 Ek m.1","zorluk":"orta"},
    {"id":"6136-S-018","soru":"6136 sayılı Kanun'un Ek 1. maddesine göre, maddede sayılan yasak yerlerde Kanuna aykırı olarak ateşli silah taşıyan veya bulunduranlar hakkında ilgili kanunlarda belirtilen cezalar nasıl uygulanır?","siklar":["Yarı oranında artırılarak","Bir kat artırılarak","Aynen, artırımsız","İki katı olarak","Üçte bir oranında indirilerek"],"dogru":3,"aciklama":"Ek m.1: yasak yerlerde Kanuna aykırı silah taşıyan/bulunduranlar hakkında 'ilgili kanunlarda belli edilen cezaların iki katı hükmolunur.'","kaynak":"6136 Ek m.1","zorluk":"orta"},
    {"id":"6136-S-019","soru":"6136 sayılı Kanun'un Ek 1. maddesine göre, sayılan yasak yerlere silahla giren kişiler elli günden az olmamak üzere adlî para cezası ile cezalandırılır; ayrıca bu kişilerin silah ruhsatları __________ çevrilir.","siklar":["bulundurmaya","taşımaya","doğrudan iptale","geçici taşımaya","sportif amaçlıya"],"dogru":0,"aciklama":"Ek m.1: yasak yerlere silahla giren kişilerin 'silah ruhsatları bulundurmaya çevrilir.' Ayrıca beş yıllık süre geçmeden bu kişilere taşıma ruhsatı verilmez.","kaynak":"6136 Ek m.1","zorluk":"orta"},
    {"id":"6136-S-020","soru":"6136 sayılı Kanun'un Ek 4. maddesine göre, turist olarak avcılık yapmak üzere yurda gelen yabancıların yurda soktuğu silahların pasaporta kaydı, taşıma izin vesikası yerine geçer.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Ek m.4: yurda sokulmasına izin verilen silah, aksamı ve mermiler ilgili kişilerin pasaportuna kaydolunur ve 'bu kayıt silah, aksamı ve mermileri için taşıma izin vesikası yerine geçer.'","kaynak":"6136 Ek m.4","zorluk":"orta"},
    {"id":"6136-S-021","soru":"6136 sayılı Kanun'un Ek 4. maddesine göre, Kara Avcılığı Kanunu esaslarına göre izin alıp turist olarak avcılık yapmak üzere yurda gelen yabancılar, beraberlerindeki tüfek ve tabancalarını hangi koşulla geçici olarak yurda sokabilir?","siklar":["Yalnızca İçişleri Bakanlığından önceden yazılı izin alarak","Hiçbir koşul olmaksızın serbestçe","Yalnızca Türk vatandaşı bir kefil göstererek","Silahı yurda sokar sokmaz en yakın karakola teslim ederek","Gümrük makamlarına beyan etmek ve giriş kapısı emniyet makamlarından izin almak koşuluyla"],"dogru":4,"aciklama":"Ek m.4: turist avcılar/atıcılık yarışmacısı yabancılar silahlarını 'gümrük makamlarına beyan etmek ve giriş kapısı emniyet makamlarından izin almak koşuluyla geçici olarak yurda sokabilirler.'","kaynak":"6136 Ek m.4","zorluk":"orta"},
    {"id":"6136-OO-001","soru":"Bir denetimde, kasap (A) dükkânında et doğramak için kullandığı geniş kasap bıçağını taşırken; aynı sokakta yürüyen (B) ise cebinde muşta ile yakalanır. 6136 sayılı Kanun'a göre bu iki durum nasıl değerlendirilir?","siklar":["Her iki alet de salt saldırı aleti sayıldığından ikisi de yasaktır","A'nın kasap bıçağı mesleğin icrası için kullanılan bir alet olarak Kanun hükümlerine tabi değildir; B'nin muştası ise yasak alettir","Her ikisi de günlük kullanım aleti sayıldığından ikisi de serbesttir","A'nın bıçağı yasak, B'nin muştası ise küçük olduğu için serbesttir","İkisi de yalnızca İçişleri Bakanlığı izniyle taşınabilir"],"dogru":1,"aciklama":"m.4: muşta, salt saldırı ve savunmada kullanılan özel nitelikteki aletlerdendir ve yasaktır. Buna karşılık 'tababet, sanayi, tarım, spor için kullanılan aletlerle bir meslek veya sanatın icrası için gerekli bıçak' türü aletler Kanun hükümlerine tabi değildir; kasabın et doğrama bıçağı bu istisna kapsamındadır.","kaynak":"6136 m.4/1","zorluk":"orta"},
    {"id":"6136-OO-002","soru":"(A), evinde sakladığı bir sustalı çakıyı, hiçbir sanat veya meslek icrası söz konusu olmaksızın komşusu (B)'ye para karşılığı satar. 6136 sayılı Kanun bakımından bu fiil aşağıdakilerden hangisini oluşturur?","siklar":["Hiçbir suç oluşmaz; yalnızca üretim yasak olduğundan satış serbesttir","Sadece B'nin satın alması yasaktır, A'nın satması serbesttir","4. maddedeki yasak bıçağın satılması (ve satın alınması) fiilidir; m.5 uyarınca yasaktır","Antika silah satışı kapsamında izin vesikasıyla serbesttir","Yalnızca idari para cezasını gerektiren bir ruhsat ihlalidir"],"dogru":2,"aciklama":"m.5: '4 ncü maddenin 1 nci fıkrası kapsamına giren bıçak ve aletlerin satılması, satınalınması, taşınması ve bulundurulması yasaktır.' Sustalı çakı m.4 kapsamındadır; satış da satın alma da yasak fiildir (meslek/sanat istisnası burada yok).","kaynak":"6136 m.5","zorluk":"orta"},
    {"id":"6136-OO-003","soru":"(A), dedesinden kalan ve usulüne göre antika izin vesikası bulunan bir tabancayı, bir düğüne giderken belinde taşır. 6136 sayılı Kanun'un 11. maddesi bakımından bu davranış nasıl değerlendirilir?","siklar":["İzin vesikası bulunduğundan her yerde üstte taşıması serbesttir","Antika silah için verilen izin yalnızca sahibine bırakılma veya nakli kapsar; üstte taşımaya cevaz vermediğinden A'nın davranışı bu izne aykırıdır","Antika silah olduğundan Kanun kapsamı dışındadır, hiçbir kural uygulanmaz","Yalnızca düğün, asker uğurlama gibi törenlerde üstte taşıması serbesttir","İzin vesikası taşıma ruhsatı yerine geçtiğinden uygundur"],"dogru":1,"aciklama":"m.11: 'Antika olan ateşli silahlarla bıçaklar için verilen izin bunların yalnız sahibine bırakılmasına veya nakline müsaadeyi tazammun edip üstte taşımaya cevaz vermez.' Belde taşıma bu iznin dışındadır.","kaynak":"6136 m.11","zorluk":"zor"},
    {"id":"6136-OO-004","soru":"Koleksiyoncu (A), antika olduğu belgelenmiş ve izin vesikası bulunan bir tüfeği, vesikasıyla birlikte başka bir koleksiyoncu (B)'ye satmak istemektedir. 6136 sayılı Kanun'un 11. maddesine göre bu satış için aşağıdakilerden hangisi doğrudur?","siklar":["Antika silahların satışı her hâlde yasaktır","Satış yalnızca müzelere yapılabilir","Antika silahların izin vesikalarıyla birlikte satışı serbesttir","Satıştan önce silahın MSB emrine teslim edilmesi gerekir","Satış yalnızca İçişleri Bakanlığının ön onayıyla mümkündür"],"dogru":2,"aciklama":"m.11: 'Antika olan ateşli silahlarla bıçakların izin vesikalarıyla birlikte satışı serbesttir.' Vesika silahla birlikte el değiştirdiği sürece satışa engel yoktur.","kaynak":"6136 m.11","zorluk":"orta"},
    {"id":"6136-OO-005","soru":"(A), yurt dışından gizlice getirdiği bir tabancayı sınırdan kaçak yolla ülkeye sokarken yakalanır. 6136 sayılı Kanun'a göre A'nın fiili kural olarak hangi madde ve ceza kapsamındadır?","siklar":["m.13 — iki yıldan dört yıla kadar hapis","m.12 — beş yıldan oniki yıla kadar hapis ve adli para cezası","m.15 — altı aydan bir yıla kadar hapis","m.13 — bir yıldan üç yıla kadar hapis (ev/işyerinde tek adet)","Yalnızca onbin Türk Lirası idari para cezası"],"dogru":1,"aciklama":"m.12/1: ateşli silahları 'ülkeye sokar veya sokmaya kalkışır' kişi beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezası ile cezalandırılır. Ülkeye sokma, kaynak/ticaret kefesinin tipik ağır fiilidir.","kaynak":"6136 m.12/1","zorluk":"orta"},
    {"id":"6136-OO-006","soru":"Bir aramada, (A)'nın evinde ruhsatsız tek bir tabanca ile bu silaha ait mutat sayıda mermi bulunur; başka silah veya nitelikli bir durum yoktur. 6136 sayılı Kanun'un 13. maddesine göre A hakkında kural olarak hangi ceza söz konusudur?","siklar":["Beş yıldan oniki yıla kadar hapis","İki yıldan dört yıla kadar hapis","Bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezası","Beş yıldan sekiz yıla kadar hapis","Yalnızca idari para cezası"],"dogru":2,"aciklama":"m.13: ruhsatsız ateşli silahın 'bir adet olması ve mutat sayıdaki mermilerinin ev veya işyerinde bulundurulması halinde verilecek ceza bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır.' Bu, m.13'ün özel indirimli halidir.","kaynak":"6136 m.13/3","zorluk":"zor"},
    {"id":"6136-OO-007","soru":"(A) ve (B), birlikte hareket ederek atölyede ateşli silah imal edip satmaktadır. 6136 sayılı Kanun'un 12. maddesine göre, suçun iki kişi tarafından birlikte işlenmesi bu kişilerin cezasını nasıl etkiler?","siklar":["Ceza değişmez; her ikisi de beş yıldan oniki yıla kadar hapis alır","Ceza sekiz yıldan onbeş yıla kadar hapis ve bin günden onbin güne kadar adlî para cezası olur","Yalnızca ceza yarı oranında artırılır","Ceza iki yıldan dört yıla kadar hapse iner","Birlikte işlemek cezayı yarıya indirir"],"dogru":1,"aciklama":"m.12: suçun 'iki veya daha çok kişinin birlikte işlemeleri halinde... sekiz yıldan onbeş yıla kadar hapis ve bin günden onbin güne kadar adlî para cezasına hükmolunur.' Bu, tek kişiyle işlenen temel haldeki 5-12 yıldan ağırdır.","kaynak":"6136 m.12/2","zorluk":"zor"},
    {"id":"6136-OO-008","soru":"(A), kurusıkı (ses/gaz fişeği atan) bir tabancayı, teknik özelliklerinde değişiklik yaparak bu Kanun hükümlerine tabi gerçek bir ateşli silah haline dönüştürür. 6136 sayılı Kanun'un 12. maddesine göre bu eylem nasıl nitelenir?","siklar":["Tamir niteliğinde olduğundan suç oluşturmaz","Yalnızca ruhsat işlemi ihlali sayılır ve idari para cezası gerektirir","Silah üretimi (imal) olarak kabul edilir ve 12. madde hükümlerine göre cezalandırılır","Bıçak yapımına benzetilerek m.15 kapsamında cezalandırılır","Yalnızca silahı bulundurma sayılır ve m.13'e göre cezalandırılır"],"dogru":2,"aciklama":"m.12 (2024-7533 ek fıkra): 'Kurusıkı tabir edilen ses veya gaz fişeği ya da benzerlerini atabilen silahı, teknik özelliklerinde değişiklik yaparak bu Kanun hükümlerine tabi silah haline dönüştürmek eylemi... üretim olarak kabul edilir ve bu madde hükümlerine göre cezalandırılır.'","kaynak":"6136 m.12/son","zorluk":"zor"},
    {"id":"6136-OO-009","soru":"Taşıma ruhsatlı silahı bulunan (A), çocuğunun okuluna (eğitim ve öğretim kurumu) silahıyla girdiği sırada görevlilerce fark edilir; fiil daha ağır cezayı gerektiren başka bir suç oluşturmamaktadır. 6136 sayılı Kanun'un Ek 1. maddesine göre A hakkında ne uygulanır?","siklar":["Ruhsatı bulunduğundan hiçbir işlem yapılmaz","Elli günden az olmamak üzere adlî para cezası verilir ve silah ruhsatı bulundurmaya çevrilir","Yalnızca silahı geçici olarak alınır, ceza verilmez","İki yıldan dört yıla kadar hapis cezası verilir","Yalnızca uyarılır ve silahıyla girmesine izin verilir"],"dogru":1,"aciklama":"Ek m.1: yasak yerlere silahla giren kişiler, fiil daha ağır cezayı gerektiren başka suç oluşturmadığı takdirde 'elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, bu kişilerin silah ruhsatları bulundurmaya çevrilir' ve beş yıl geçmeden taşıma ruhsatı verilmez. Eğitim kurumu (B) bendindeki yasak yerlerdendir.","kaynak":"6136 Ek m.1","zorluk":"zor"},
    {"id":"6136-OO-010","soru":"Bir spor karşılaşmasının yapıldığı stadyumda, müsabakanın güvenliğiyle görevlendirilmiş jandarma personeli (A) silahını taşımakta; aynı tribünde taşıma ruhsatlı sivil (B) de silahıyla bulunmaktadır. 6136 sayılı Kanun'un Ek 1. maddesine göre durum nasıl değerlendirilir?","siklar":["Stadyum yasak yer olduğundan ikisi de silah taşıyamaz","İkisi de ruhsat/görev sahibi olduğundan ikisinin de taşıması serbesttir","O yerin güvenliğiyle görevli jandarma personeli (A) istisna kapsamında taşıyabilir; sivil (B) için ise taşıma yasaktır","Yalnızca sivil B taşıyabilir, görevli A taşıyamaz","Taşıma için her ikisinin de İçişleri Bakanlığından ayrı izin alması gerekir"],"dogru":2,"aciklama":"Ek m.1: spor karşılaşmalarının yapıldığı yerler silah taşınamayan (B bendi) yerlerdendir; ancak 'bu yerlerin güvenliği için görevli bulunan polis ve jandarma personeli' silahını taşıyabilir. Görevli jandarma istisna kapsamındadır; taşıma ruhsatlı sivil için bu istisna geçerli değildir.","kaynak":"6136 Ek m.1","zorluk":"orta"},
    {"id":"6136-OO-011","soru":"Kara Avcılığı Kanunu esaslarına göre izin alıp turist olarak avlanmak üzere yurda gelen yabancı (C), av tüfeğini gümrük makamlarına beyan edip giriş kapısı emniyet makamlarından izin alır; tüfek pasaportuna kaydedilir. 6136 sayılı Kanun'un Ek 4. maddesine göre bu pasaport kaydı ne işlev görür?","siklar":["Yalnızca gümrük çıkışında ibraz edilecek bir kayıttır, taşımaya yetki vermez","Silah, aksamı ve mermileri için taşıma izin vesikası yerine geçer","Yabancının silahını derhal en yakın emniyet birimine teslim etmesi gerektiğini gösterir","Silahın Türkiye'de süresiz bulundurulabileceği anlamına gelir","Ayrıca İçişleri Bakanlığından taşıma ruhsatı alınmasını zorunlu kılar"],"dogru":1,"aciklama":"Ek m.4: yurda sokulmasına izin verilen silah, aksamı ve mermileri ilgili kişilerin pasaportuna kaydolunur ve 'bu kayıt silah, aksamı ve mermileri için taşıma izin vesikası yerine geçer.' Ayrıca sarf edilmeyen mermilerin çıkışta yurt dışına götürülmesi zorunludur.","kaynak":"6136 Ek m.4","zorluk":"orta"},
    {"id":"6136-OO-012","soru":"(A), hal ve şartlardan sırf saldırıda kullanmak amacıyla taşıdığı anlaşılan bir bıçakla yakalanır. 6136 sayılı Kanun'un 15. maddesi bakımından, sırf saldırı amacıyla taşıma haline bağlanan ceza aşağıdakilerden hangisidir?","siklar":["Altı aydan bir yıla kadar hapis ve yirmibeş günden az olmamak üzere adlî para cezası","Üç aya kadar hapis veya adlî para cezası","İki yıldan dört yıla kadar hapis","Beş yıldan oniki yıla kadar hapis","Yalnızca idari para cezası"],"dogru":1,"aciklama":"m.15: 4 üncü maddenin ilgili fıkrasındaki bıçak ve diğer aletleri 'hal ve şartlara göre sırf saldırıda kullanmak amacıyla taşıyanlar, üç aya kadar hapis veya adlî para cezası ile cezalandırılır.' Bu, bıçağı satan/taşıyan/bulunduranın 6 ay-1 yıllık genel halinden ayrı, özel bir fıkradır.","kaynak":"6136 m.15/son","zorluk":"zor"},
  ],
  26: [
    {"id":"5271-S-001","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre 'sanık' kavramı aşağıdakilerden hangisiyle tanımlanmıştır?","siklar":["Soruşturma evresinde suç şüphesi altında bulunan kişi","İddianamenin düzenlenmesinden önce şüphe altında bulunan kişi","Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar suç şüphesi altında bulunan kişi","Yalnızca mahkûm olmuş kişi","Şikâyetçi sıfatıyla davaya katılan kişi"],"dogru":2,"aciklama":"m.2/b: 'Sanık: Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar, suç şüphesi altında bulunan kişiyi... ifade eder.' Kovuşturma evresindeki kişi sanıktır.","kaynak":"5271 m.2","zorluk":"kolay"},
    {"id":"5271-S-002","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre 'toplu suç' sayılabilmesi için en az iki kişinin aralarında iştirak iradesi bulunmaksızın bir suçu işlemesi yeterlidir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2/k: 'Toplu suç: Aralarında iştirak iradesi bulunmasa da üç veya daha fazla kişi tarafından işlenen suçu, ifade eder.' Eşik iki değil, üç veya daha fazla kişidir.","kaynak":"5271 m.2","zorluk":"kolay"},
    {"id":"5271-S-003","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre aşağıdakilerden hangisi yakalama yetkisinin kullanılabileceği hallerden biri değildir?","siklar":["Kişiye suçu işlerken rastlanması","Suçüstü bir fiilden dolayı izlenen kişinin kaçma olasılığının bulunması","Cumhuriyet savcısına veya âmirlerine derhâl başvurma olanağı bulunmayan kolluğun, gecikmesinde sakınca bulunan hâlde yakalaması","Şüphelinin ifadesinin alınması amacıyla herkesin yakalama yapabilmesi","İzlenen kişinin hemen kimliğini belirleme olanağının bulunmaması"],"dogru":3,"aciklama":"m.90/1-2: Herkes, suçu işlerken rastlanan veya suçüstünden kaçma/kimlik belirsizliği olan kişiyi yakalayabilir; kolluk da savcıya ulaşılamayan gecikmede yakalama yetkisine sahiptir. 'İfade alma amacıyla herkesin yakalaması' kanunda yer alan bir yakalama nedeni değildir; ifade alma yakalamanın amacı değil, yakalama sonrası işlemdir.","kaynak":"5271 m.90","zorluk":"orta"},
    {"id":"5271-S-004","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre kolluk görevlilerinin, tutuklama kararı veya yakalama emri düzenlenmesini gerektiren ve gecikmesinde sakınca bulunan hâllerde kendiliğinden yakalama yetkisine sahip olabilmesi için hangi şart aranır?","siklar":["Mağdurun şikâyetçi olması","Yakalanacak kişinin daha önce sabıkalı olması","Olayın gece vakti gerçekleşmesi","Şüphelinin yabancı uyruklu olması","Cumhuriyet savcısına veya âmirlerine derhâl başvurma olanağının bulunmaması"],"dogru":4,"aciklama":"m.90/2: 'Kolluk görevlileri, tutuklama kararı veya yakalama emri düzenlenmesini gerektiren ve gecikmesinde sakınca bulunan hâllerde; Cumhuriyet savcısına veya âmirlerine derhâl başvurma olanağı bulunmadığı takdirde, yakalama yetkisine sahiptirler.'","kaynak":"5271 m.90","zorluk":"orta"},
    {"id":"5271-S-005","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre gözaltı süresi, yakalama yerine en yakın hâkim veya mahkemeye gönderilmesi için zorunlu süre hariç, yakalama anından itibaren ....(1).... saati geçemez; bu gönderme için zorunlu süre ....(2).... saatten fazla olamaz. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["yirmi dört - on iki","kırk sekiz - yirmi dört","on iki - yirmi dört","yirmi dört - kırk sekiz","otuz altı - on iki"],"dogru":0,"aciklama":"m.91/1: '...yakalama anından itibaren yirmidört saati geçemez. Yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre oniki saatten fazla olamaz.' Gözaltı 24 saat, gönderme yolu ayrıca en çok 12 saattir.","kaynak":"5271 m.91","zorluk":"orta"},
    {"id":"5271-S-006","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre suçüstü hâlleriyle sınırlı olmak kaydıyla, mülki amirlerce belirlenen kolluk amirleri tarafından normal hâllerde ....(1).... saate kadar, toplumsal olaylar ile toplu olarak işlenen suçlarda ise ....(2).... saate kadar gözaltına alınma kararı verilebilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["on iki - yirmi dört","yirmi dört - kırk sekiz","kırk sekiz - yirmi dört","yirmi dört - yetmiş iki","kırk sekiz - doksan altı"],"dogru":1,"aciklama":"m.91/4: '...kolluk amirleri tarafından yirmi dört saate kadar, ...toplumsal olaylar sırasında ve toplu olarak işlenen suçlarda kırk sekiz saate kadar gözaltına alınma kararı verilebilir.' Normal 24, toplumsal/toplu 48 saattir.","kaynak":"5271 m.91/4","zorluk":"zor"},
    {"id":"5271-S-007","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre m.91/4 uyarınca kolluk amirince gözaltına alınan kişi, toplu olarak işlenen suçlarda en geç hangi süre içinde hâkim önüne çıkarılır?","siklar":["24 saat","48 saat","4 gün","3 gün","7 gün"],"dogru":2,"aciklama":"m.91/4: '...kişi en geç kırk sekiz saat, toplu olarak işlenen suçlarda dört gün içinde hâkim önüne çıkarılır.' Toplu suçta süre 4 gündür; genel hâlde bu süre 48 saattir.","kaynak":"5271 m.91/4","zorluk":"orta"},
    {"id":"5271-S-008","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre yakalanan veya nakledilen kişiye, kaçacağına ya da kendisinin veya başkalarının hayat ve beden bütünlükleri bakımından tehlike arz ettiğine ilişkin belirtilerin varlığı hâlinde kelepçe takılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.93: 'Yakalanan veya tutuklanarak bir yerden diğer bir yere nakledilen kişilere, kaçacaklarına ya da kendisi veya başkalarının hayat ve beden bütünlükleri bakımından tehlike arz ettiğine ilişkin belirtilerin varlığı hâllerinde kelepçe takılabilir.'","kaynak":"5271 m.93","zorluk":"orta"},
    {"id":"5271-S-009","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre hâkim veya mahkeme tarafından verilen yakalama emri üzerine yakalanan kişi, en geç kaç saat içinde yetkili hâkim veya mahkeme önüne çıkarılır?","siklar":["12 saat","48 saat","72 saat","24 saat","96 saat"],"dogru":3,"aciklama":"m.94/1: 'Hâkim veya mahkeme tarafından verilen yakalama emri üzerine ...yakalanan kişi, en geç yirmi dört saat içinde yetkili hâkim veya mahkeme önüne çıkarılır.'","kaynak":"5271 m.94","zorluk":"orta"},
    {"id":"5271-S-010","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre soruşturma evresinde çağrı üzerine gelmeyen veya çağrı yapılamayan şüpheli hakkında, Cumhuriyet savcısının istemi üzerine yakalama emri kim tarafından düzenlenebilir?","siklar":["Ağır ceza mahkemesi","Cumhuriyet başsavcısı","Kolluk amiri","İl valisi","Sulh ceza hâkimi"],"dogru":4,"aciklama":"m.98/1: 'Soruşturma evresinde çağrı üzerine gelmeyen veya çağrı yapılamayan şüpheli hakkında, Cumhuriyet savcısının istemi üzerine sulh ceza hâkimi tarafından yakalama emri düzenlenebilir.'","kaynak":"5271 m.98","zorluk":"zor"},
    {"id":"5271-S-011","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre aşağıdakilerden hangisi bir tutuklama nedeninin var sayıldığı hallerden biri değildir?","siklar":["Şüpheli veya sanığın kaçması ya da kaçacağı şüphesini uyandıran somut olgular","Delilleri yok etme, gizleme veya değiştirme davranışları","Tanık veya mağdur üzerinde baskı yapma girişimi","Şüphelinin ekonomik durumunun iyi olması","Kanunda sayılı katalog suçlardan birinin işlendiği hususunda somut delillere dayanan kuvvetli şüphe"],"dogru":3,"aciklama":"m.100/2-3: Kaçma/saklanma şüphesi, delil karartma veya tanık/mağdur üzerinde baskı girişimi ile katalog suçlarda kuvvetli şüphe tutuklama nedeni sayılabilir. 'Ekonomik durumun iyi olması' kanunda tutuklama nedeni olarak sayılmamıştır.","kaynak":"5271 m.100","zorluk":"orta"},
    {"id":"5271-S-012","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre sadece adlî para cezasını gerektiren suçlarda tutuklama kararı verilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.100/4: 'Sadece adlî para cezasını gerektiren suçlarda veya vücut dokunulmazlığına karşı kasten işlenenler hariç olmak üzere hapis cezasının üst sınırı iki yıldan fazla olmayan suçlarda tutuklama kararı verilemez.' Sadece adlî para cezalık suçlarda yasak istisnasızdır.","kaynak":"5271 m.100/4","zorluk":"orta"},
    {"id":"5271-S-013","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre soruşturma evresinde şüphelinin tutuklanmasına, Cumhuriyet savcısının istemi üzerine kim karar verir?","siklar":["Ağır ceza mahkemesi","Sulh ceza hâkimi","Asliye ceza mahkemesi","Cumhuriyet başsavcısı","İl valisi"],"dogru":1,"aciklama":"m.101/1: 'Soruşturma evresinde şüphelinin tutuklanmasına Cumhuriyet savcısının istemi üzerine sulh ceza hâkimi tarafından ... karar verilir.'","kaynak":"5271 m.101","zorluk":"kolay"},
    {"id":"5271-S-014","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre ağır ceza mahkemesinin görevine girmeyen işlerde tutukluluk süresi en çok ....(1).... yıl, ağır ceza mahkemesinin görevine giren işlerde ise en çok ....(2).... yıldır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["iki - üç","altı ay - bir","bir - iki","bir - üç","iki - beş"],"dogru":2,"aciklama":"m.102/1-2: 'Ağır ceza mahkemesinin görevine girmeyen işlerde tutukluluk süresi en çok bir yıldır. ... Ağır ceza mahkemesinin görevine giren işlerde, tutukluluk süresi en çok iki yıldır.'","kaynak":"5271 m.102","zorluk":"orta"},
    {"id":"5271-S-015","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre soruşturma evresinde şüpheli, Cumhuriyet savcısının istemi üzerine kimin kararıyla adlî kontrol altına alınabilir?","siklar":["Ağır ceza mahkemesi","Cumhuriyet savcısı re'sen","Kolluk amiri","Sulh ceza hâkimi","Vali"],"dogru":3,"aciklama":"m.110/1: 'Şüpheli, Cumhuriyet savcısının istemi ve sulh ceza hâkiminin kararı ile soruşturma evresinin her aşamasında adlî kontrol altına alınabilir.'","kaynak":"5271 m.109-110","zorluk":"orta"},
    {"id":"5271-S-016","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre ağır ceza mahkemesinin görevine girmeyen işlerde adlî kontrol süresi en çok ....(1).... yıl, ağır ceza işlerinde ise en çok ....(2).... yıldır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["bir - iki","altı ay - bir","üç - dört","iki - beş","iki - üç"],"dogru":4,"aciklama":"m.110/A: '(1) Ağır ceza mahkemesinin görevine girmeyen işlerde adli kontrol süresi en çok iki yıldır... (2) Ağır ceza işlerinde en çok üç yıldır...'","kaynak":"5271 m.110/A","zorluk":"zor"},
    {"id":"5271-S-017","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre adlî kontrol hükümlerini isteyerek yerine getirmeyen şüpheli veya sanık hakkında, hükmedilebilecek hapis cezasının süresi ne olursa olsun yetkili yargı mercii hemen tutuklama kararı verebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.112: 'Adlî kontrol hükümlerini isteyerek yerine getirmeyen şüpheli/sanık hakkında, hükmedilebilecek hapis cezasının süresi ne olursa olsun yetkili yargı mercii hemen tutuklama kararı verebilir.'","kaynak":"5271 m.112","zorluk":"orta"},
    {"id":"5271-S-018","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre şüphelinin veya sanığın üstünün, eşyasının, konutunun veya işyerinin aranabilmesi için hangi şart aranır?","siklar":["Makul şüphe bulunması","Kuvvetli şüphe bulunması","Kesin şüphe bulunması","Basit şüphe bulunması","Hiçbir şüphe aranmaması"],"dogru":0,"aciklama":"m.116: 'Yakalanabileceği veya suç delillerinin elde edilebileceği hususunda makul şüphe varsa; şüphelinin veya sanığın üstü, eşyası, konutu, işyeri veya ona ait diğer yerler aranabilir.'","kaynak":"5271 m.116","zorluk":"kolay"},
    {"id":"5271-S-019","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre aşağıdakilerden hangisi, konut, işyeri veya diğer kapalı yerlerde gece vaktinde arama yapılabilecek istisnai hallerden biri değildir?","siklar":["Suçüstü hali","Şikâyetçinin gece araması yapılmasını talep etmesi","Gecikmesinde sakınca bulunan haller","Gözaltına alınıp firar eden kişinin tekrar yakalanması amacı","Tutuklu veya hükümlünün tekrar yakalanması amacı"],"dogru":1,"aciklama":"m.118: '(1) Konutta, işyerinde veya diğer kapalı yerlerde gece vaktinde arama yapılamaz. (2) Suçüstü veya gecikmesinde sakınca bulunan hâller ile ...firar eden kişi veya tutuklu veya hükümlünün tekrar yakalanması amacıyla yapılan aramalarda, birinci fıkra hükmü uygulanmaz.' Şikâyetçinin talebi bir istisna değildir.","kaynak":"5271 m.118","zorluk":"orta"},
    {"id":"5271-S-020","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre konutta, işyerinde ve kamuya açık olmayan kapalı alanlarda yapılacak arama, hâkim kararı yoksa kimin yazılı emriyle yapılabilir?","siklar":["Kolluk amirinin yazılı emriyle","İl valisinin kararıyla","Cumhuriyet savcısının yazılı emriyle","Cumhuriyet başsavcısının sözlü emriyle","Adalet Bakanlığının onayıyla"],"dogru":2,"aciklama":"m.119/1: '...konutta, işyerinde ve kamuya açık olmayan kapalı alanlarda arama, hâkim kararı veya gecikmesinde sakınca bulunan hallerde Cumhuriyet savcısının yazılı emri ile yapılabilir.' Kolluk amirinin yazılı emri BU yerlerde yeterli değildir.","kaynak":"5271 m.119","zorluk":"zor"},
    {"id":"5271-S-021","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre aşağıdakilerden hangisi arama karar/emri ve uygulaması bakımından kanunda öngörülen bir kural değildir?","siklar":["Aramanın nedenini oluşturan fiilin karar/emirde gösterilmesi","Aranılacak kişi, adres veya eşyanın karar/emirde gösterilmesi","Savcı hazır olmaksızın konutta arama yapılırken ihtiyar heyetinden veya komşulardan iki kişi bulundurulması","Arama emrinin yazılı olmak yerine yalnızca sözlü olarak da verilebilmesi","Arama tutanağına işlemi yapanların açık kimliklerinin yazılması"],"dogru":3,"aciklama":"m.119/1: kolluk amiri arama emrini 'yazılı' verir; m.119/2: karar/emirde fiil, kişi/adres/eşya ve süre gösterilir; m.119/3: tutanağa kimlikler yazılır; m.119/4: savcı yokken konutta iki kişi tanık bulundurulur. Arama emrinin sözlü verilebileceği kuralı yoktur, emir kanunda hep 'yazılı'dır.","kaynak":"5271 m.119/2-5","zorluk":"orta"},
    {"id":"5271-S-022","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını inceleme yetkisi kime aittir?","siklar":["Kolluk görevlisine","Yalnızca hâkime","Yalnızca Cumhuriyet savcısına","İl emniyet müdürüne","Cumhuriyet savcısı ve hâkime"],"dogru":4,"aciklama":"m.122/1: 'Hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını inceleme yetkisi, Cumhuriyet savcısı ve hâkime aittir.' Yetki ikisine birliktedir; kolluğa ait değildir.","kaynak":"5271 m.122","zorluk":"kolay"},
    {"id":"5271-S-023","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre hâkim kararı olmaksızın yapılan elkoyma işlemi ....(1).... saat içinde görevli hâkimin onayına sunulur; hâkim kararını elkoymadan itibaren ....(2).... saat içinde açıklar, aksi hâlde elkoyma kendiliğinden kalkar. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["yirmi dört - kırk sekiz","kırk sekiz - yirmi dört","on iki - yirmi dört","yirmi dört - yetmiş iki","kırk sekiz - doksan altı"],"dogru":0,"aciklama":"m.127/3: 'Hâkim kararı olmaksızın yapılan elkoyma işlemi, yirmidört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırksekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar.'","kaynak":"5271 m.127","zorluk":"orta"},
    {"id":"5271-S-024","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre avukat büroları hangi merciin kararıyla ve kimin hazır bulunması şartıyla aranabilir?","siklar":["Cumhuriyet savcısının kararıyla, kolluk amiri hazır bulunarak","Mahkeme kararıyla, savcı denetiminde ve baro başkanı hazır bulunarak","Kolluk amirinin yazılı emriyle","Vali kararıyla, jandarma komutanı hazır bulunarak","Sulh ceza hâkiminin sözlü emriyle"],"dogru":1,"aciklama":"m.130/1: 'Avukat büroları ancak mahkeme kararıyla, savcı denetiminde, baro başkanı hazırken aranabilir.' Konut/işyeri aramasına göre çok daha ağır bir usule (mahkeme kararı + baro başkanı) tâbidir.","kaynak":"5271 m.130","zorluk":"orta"},
    {"id":"5271-S-025","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre gizli soruşturmacı görevlendirilmesine kim karar verir?","siklar":["Cumhuriyet savcısı","Kolluk amiri","Hâkim","Vali","İçişleri Bakanlığı"],"dogru":2,"aciklama":"m.139/1: '...kamu görevlileri gizli soruşturmacı olarak görevlendirilebilir; görevlendirmeye hâkim karar verir.'","kaynak":"5271 m.139","zorluk":"orta"},
    {"id":"5271-S-026","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre teknik araçlarla izleme tedbiri, şüphelinin konutunda da uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.140/5: 'Bu madde kişinin konutunda uygulanamaz.' Teknik izleme yalnız kamuya açık yerlerde ve işyerinde yapılabilir, konut istisnasız yasaktır.","kaynak":"5271 m.140","zorluk":"orta"},
    {"id":"5271-S-027","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre zorla getirilen kişi, derhâl, olanak yoksa yol süresi hariç en geç ....(1).... saat içinde çağıran hâkim, mahkeme veya Cumhuriyet savcısının önüne götürülür. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["12","48","72","24","(4 gün) olarak ifade edilir"],"dogru":3,"aciklama":"m.146/4: 'Zorla getirilen kişi derhal, olanak yoksa yol süresi hariç en geç yirmidört saat içinde çağıran hâkim, mahkeme veya Cumhuriyet savcısının önüne götürülür.'","kaynak":"5271 m.145-146","zorluk":"orta"},
    {"id":"5271-S-028","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre aşağıdakilerden hangisi ifade alma veya sorguya çekilmede şüpheliye/sanığa bildirilmesi gereken hususlardan biri değildir?","siklar":["Kimliğinin saptanması","Yüklenen suçun kendisine anlatılması","Müdafi seçme hakkının bulunduğunun bildirilmesi","Yüklenen suç hakkında açıklamada bulunmamasının kanunî hakkı olduğunun söylenmesi","İfadesinin mutlaka sesli ve görüntülü olarak kaydedileceğinin bildirilmesi"],"dogru":4,"aciklama":"m.147/1: İfade alma/sorguda kimlik saptanır, yüklenen suç anlatılır, müdafi seçme hakkı ve susma hakkı bildirilir, lehe delil toplanmasını isteyebileceği hatırlatılır. 'İfadenin mutlaka sesli-görüntülü kaydedileceğinin bildirilmesi' m.147'de öngörülen bir hak/hatırlatma değildir.","kaynak":"5271 m.147","zorluk":"orta"},
    {"id":"5271-S-029","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre yasak usullerle elde edilen bir ifade, şüpheli rıza gösterse dahi delil olarak değerlendirilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.148/3: 'Yasak usullerle elde edilen ifadeler rıza ile verilmiş olsa da delil olarak değerlendirilemez.'","kaynak":"5271 m.148","zorluk":"kolay"},
    {"id":"5271-S-030","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre suça ilişkin ihbar veya şikâyet nereye yapılabilir?","siklar":["Yalnızca Cumhuriyet Başsavcılığına","Yalnızca mahkemeye","Yalnızca valiliğe","Yalnızca Adalet Bakanlığına","Cumhuriyet Başsavcılığına veya kolluk makamlarına"],"dogru":4,"aciklama":"m.158/1: 'Suça ilişkin ihbar veya şikâyet, Cumhuriyet Başsavcılığına veya kolluk makamlarına yapılabilir.' Valilik/mahkemeye yapılan ihbar da ilgili Başsavcılığa gönderilir (m.158/2).","kaynak":"5271 m.158","zorluk":"kolay"},
    {"id":"5271-S-031","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.164'e göre, Jandarma Teşkilat, Görev ve Yetkileri Kanunu'nun hangi maddesinde belirtilen görevliler adlî kolluk sayılır?","siklar":["3201 sayılı Kanunun 8 inci maddesi","2803 sayılı Kanunun 7 nci maddesi","2692 sayılı Kanunun 4 üncü maddesi","485 sayılı KHK'nin 8 inci maddesi","2803 sayılı Kanunun 4 üncü maddesi"],"dogru":1,"aciklama":"m.164/1: '...2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 7 nci maddesi... belirtilen soruşturma işlemlerini yapan güvenlik görevlilerini ifade eder.' Jandarma için dayanak 2803/7'dir.","kaynak":"5271 m.164","zorluk":"orta"},
    {"id":"5271-S-032","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre soruşturma sonunda toplanan deliller, suçun işlendiği hususunda yeterli şüphe oluşturuyorsa Cumhuriyet savcısı ne düzenler?","siklar":["Kovuşturmaya yer olmadığı kararı","Men-i muhakeme kararı","İddianame","Beraat kararı","Tensip zaptı"],"dogru":2,"aciklama":"m.170/2: 'Soruşturma evresi sonunda toplanan deliller, suçun işlendiği hususunda yeterli şüphe oluşturuyorsa; Cumhuriyet savcısı, bir iddianame düzenler.'","kaynak":"5271 m.170-172","zorluk":"orta"},
    {"id":"5271-S-033","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre sanığın onsekiz yaşını doldurmamış olması hâlinde duruşma nasıl yapılır?","siklar":["Herkese açık yapılır","Sadece basına kapalı yapılır","Sadece mağdura kapalı yapılır","Kapalı yapılır","Duruşma yapılmaz, dosya üzerinden karar verilir"],"dogru":3,"aciklama":"m.185/1: 'Sanık, onsekiz yaşını doldurmamış ise duruşma kapalı yapılır; hüküm de kapalı duruşmada açıklanır.' Bu, genel aleniyet kuralının (m.182) zorunlu istisnasıdır.","kaynak":"5271 m.182-185","zorluk":"orta"},
    {"id":"5271-S-034","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre ortaya konulması istenen bir delil, aşağıdaki gerekçelerden hangisiyle reddedilemez?","siklar":["Delilin kanuna aykırı olarak elde edilmiş olması","Delil ile ispat edilmek istenen olayın karara etkisinin bulunmaması","İstemin sadece davayı uzatmak amacıyla yapılmış olması","Delilin toplanmasının hukuka aykırı yöntemle gerçekleştirilmiş olması","Delilin veya ispat edilmek istenen olayın geç bildirilmiş olması"],"dogru":4,"aciklama":"m.207/1: 'Delilin ortaya konulması istemi, bunun veya ispat edilmek istenen olayın geç bildirilmiş olması nedeniyle reddedilemez.' A, B, C ise m.206/2'de sayılan geçerli ret sebepleridir.","kaynak":"5271 m.206-207","zorluk":"orta"},
    {"id":"5271-S-035","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.231'e göre, hükmolunan ceza iki yıl veya daha az süreli hapis ya da adlî para cezası ise hükmün açıklanmasının geri bırakılmasına karar verilebilir; bu hâlde sanık ....(1).... yıl süreyle denetim süresine tâbi tutulur. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["5","3","1","2","10"],"dogru":0,"aciklama":"m.231/8: '...sanık, beş yıl süreyle denetim süresine tâbi tutulur.' Hükmedilen cezanın üst sınırı (2 yıl) ile denetim süresi (5 yıl) farklı sayılardır ve karıştırılmamalıdır.","kaynak":"5271 m.231","zorluk":"orta"},
    {"id":"5271-S-036","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre cinsel dokunulmazlığa karşı işlenen suçlarda, soruşturulması ve kovuşturulması şikâyete bağlı olsa bile uzlaştırma yoluna gidilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.253/3: 'Soruşturulması ve kovuşturulması şikâyete bağlı olsa bile, cinsel dokunulmazlığa karşı suçlarda, ısrarlı takip suçunda ve hakaret suçunda uzlaştırma yoluna gidilemez.' Bu suçlarda uzlaştırma kesin olarak yasaktır.","kaynak":"5271 m.253","zorluk":"orta"},
    {"id":"5271-S-037","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre hâkim veya mahkeme kararına itiraz, ilgilinin kararı öğrendiği günden itibaren kaç hafta içinde yapılır?","siklar":["1 hafta","3 hafta","1 ay","2 hafta","2 ay"],"dogru":3,"aciklama":"m.268/1: '...ilgililerin kararı öğrendiği günden itibaren iki hafta içinde kararı veren mercie verilecek bir dilekçe veya tutanağa geçirilmek koşulu ile ... yapılır.'","kaynak":"5271 m.268","zorluk":"kolay"},
    {"id":"5271-S-038","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre onbeş yıl ve daha fazla hapis cezalarına ilişkin hükümler, bölge adliye mahkemesince nasıl incelenir?","siklar":["Sadece taraflardan biri istinaf başvurusunda bulunursa incelenir","İncelenmez, kesinleşir","Re'sen incelenir","Yalnızca Yargıtay incelemesine tabidir","Sadece savcının istemiyle incelenir"],"dogru":2,"aciklama":"m.272/1: '...onbeş yıl ve daha fazla hapis cezalarına ilişkin hükümler, bölge adliye mahkemesince re'sen incelenir.' Taraflardan istinaf başvurusu beklenmeksizin inceleme kendiliğinden yapılır.","kaynak":"5271 m.272","zorluk":"zor"},
    {"id":"5271-S-039","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre bağlantılı suçlardan her biri değişik mahkemelerin görevine giriyorsa, bu suçlar hakkında dava nasıl açılabilir?","siklar":["Birleştirilmek suretiyle yüksek görevli mahkemede","Her suç için ayrı ayrı, kendi görevli mahkemesinde","Yalnızca ağır ceza mahkemesinde, birleştirme yapılmaksızın","Sulh ceza hâkimliğinde birleştirilerek","Cumhuriyet Başsavcılığının belirlediği mahkemede"],"dogru":0,"aciklama":"m.9/1: 'Bağlantılı suçlardan her biri değişik mahkemelerin görevine giriyorsa, bunlar hakkında birleştirilmek suretiyle yüksek görevli mahkemede dava açılabilir.'","kaynak":"5271 m.9","zorluk":"kolay"},
    {"id":"5271-S-040","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre suçun işlendiği yer belli değilse, davaya bakma yetkisi öncelikle hangi mahkemeye aittir?","siklar":["Mağdurun yerleşim yeri mahkemesine","Şüpheli veya sanığın yakalandığı yer mahkemesine, yakalanmamışsa yerleşim yeri mahkemesine","Cumhuriyet Başsavcılığının bulunduğu yer mahkemesine","Olayın ihbar edildiği yer mahkemesine","Ankara'daki yetkili ağır ceza mahkemesine"],"dogru":1,"aciklama":"m.13/1: 'Suçun işlendiği yer belli değilse, şüpheli veya sanığın yakalandığı yer, yakalanmamışsa yerleşim yeri mahkemesi yetkilidir.'","kaynak":"5271 m.13","zorluk":"orta"},
    {"id":"5271-S-041","soru":"Aşağıdakilerden hangisi 5271 sayılı Ceza Muhakemesi Kanunu'na göre hâkimin davaya bakamayacağı hâllerden biri değildir?","siklar":["Suçtan kendisinin zarar görmüş olması","Taraflarla evlilik veya vesayet ilişkisi bulunması","Sanığın memleketinin hâkimle aynı olması","Aynı davada daha önce tanık veya bilirkişi olarak dinlenmiş olması","Aynı davada savcılık, adlî kolluk, müdafilik veya vekillik yapmış olması"],"dogru":2,"aciklama":"m.22/1: hâkim; suçtan zarar görmüşse, taraflarla evlilik/vesayet/kayyımlık ilişkisi, akrabalık, evlât edinme bağı, aynı davada savcılık/adlî kolluk/müdafilik/vekillik veya tanık/bilirkişilik yapmışsa görevini yapamaz. Memleketin aynı olması bu sayımda yer almaz.","kaynak":"5271 m.22","zorluk":"zor"},
    {"id":"5271-S-042","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre elektronik imzalı belge ile elle atılan imzalı belgenin çelişmesi hâlinde, elle atılan imzalı belge esas alınır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.38/A(5): 'Elektronik imzalı belgenin elle atılan imzalı belgeyle çelişmesi halinde UYAP'ta kayıtlı güvenli elektronik imzalı belge geçerli kabul edilir.' Esas alınan elle imzalı değil, UYAP'taki e-imzalı belgedir.","kaynak":"5271 m.38/A","zorluk":"kolay"},
    {"id":"5271-S-043","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre gün ile belirlenen süreler ne zaman işlemeye başlar?","siklar":["Tebligatın yapıldığı gün","İşlemin tamamlandığı gün","Kararın kesinleştiği gün","Tebligatın yapıldığının ertesi günü","Tebligattan bir hafta sonra"],"dogru":3,"aciklama":"m.39/1: 'Gün ile belirlenen süreler, tebligatın yapıldığının ertesi günü işlemeye başlar.'","kaynak":"5271 m.39","zorluk":"orta"},
    {"id":"5271-S-044","soru":"Aşağıdakilerden hangisi 5271 sayılı Ceza Muhakemesi Kanunu'na göre şüpheli veya sanığın yakınlığı nedeniyle tanıklıktan çekinme hakkı tanınanlardan biri değildir?","siklar":["Nişanlısı","Eşi (evlilik sona ermiş olsa da)","Üstsoy ve altsoyu","Evlâtlık bağı bulunanlar","İş yerinde birlikte çalıştığı meslektaşı"],"dogru":4,"aciklama":"m.45/1: nişanlı, eş (evlilik bitse de), üstsoy-altsoy, belirli derece kan/kayın hısımları ve evlâtlık bağı olanlar tanıklıktan çekinebilir. Meslektaşlık/iş arkadaşlığı bu sayımda yer almaz.","kaynak":"5271 m.45","zorluk":"orta"},
    {"id":"5271-S-045","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.75'e göre üst sınırı ....(1).... yıldan az hapis cezasını gerektiren suçlarda şüpheli veya sanık üzerinde iç beden muayenesi yapılamaz ve vücuttan örnek alınamaz. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["iki","bir","üç","beş","dört"],"dogru":0,"aciklama":"m.75/5: 'Üst sınırı iki yıldan az hapis gerektiren suçlarda iç beden muayenesi/örnek alınamaz.'","kaynak":"5271 m.75","zorluk":"zor"},
    {"id":"5271-S-046","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre otopsi kural olarak kimin huzurunda ve kaç hekim tarafından yapılır?","siklar":["Hâkimin huzurunda, tek hekimle","Cumhuriyet savcısının huzurunda, biri adlî tıp diğeri patoloji uzmanı olmak üzere iki hekimle","Kolluk amirinin huzurunda, üç hekimle","Sulh ceza hâkiminin huzurunda, iki hekimle","Yalnızca adlî tıp uzmanı tarafından, savcı olmadan"],"dogru":1,"aciklama":"m.87/1: 'Otopsi, Cumhuriyet savcısının huzurunda biri adlî tıp diğeri patoloji uzmanı olmak üzere İKİ hekim tarafından yapılır; zorunlulukta bir hekim de yapabilir.'","kaynak":"5271 m.87","zorluk":"kolay"},
    {"id":"5271-S-047","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre yakalanan kişi yabancı ise, yazılı olarak karşı çıkmaması hâlinde durumu vatandaşı olduğu devletin konsolosluğuna bildirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.95/2: 'Yakalanan yabancı ise, yazılı olarak karşı çıkmaması halinde durumu vatandaşı olduğu devletin konsolosluğuna bildirilir.'","kaynak":"5271 m.95","zorluk":"orta"},
    {"id":"5271-S-048","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre postadaki gönderilere hâkim veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı kararıyla elkonulduğunda, kolluk bu gönderiler hakkında ne yapabilir?","siklar":["Zarfı açıp içeriğini inceleyebilir","Zarfı açıp fotokopisini alabilir","Zarfı açamaz, mühürleyip yetkili mercie teslim eder","Zarfı doğrudan sahibine iade eder","Zarfı imha edebilir"],"dogru":2,"aciklama":"m.129/2: kolluk zarfı açamaz, mühürleyip teslim eder.","kaynak":"5271 m.129","zorluk":"zor"},
    {"id":"5271-S-049","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.134'e göre bilgisayarlarda arama, kopyalama ve elkoymaya asıl olarak hâkim karar verir; gecikmesinde sakınca bulunan hâllerde bu yetki kime geçer?","siklar":["Kolluk amirine","İl valisine","Bilirkişiye","Cumhuriyet savcısına","Adlî kolluk görevlisine doğrudan"],"dogru":3,"aciklama":"m.134/1: bilgisayarlarda arama/kopyalama/elkoymaya hâkim, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı karar verir; savcı kararı 24 saatte hâkim onayına sunulur.","kaynak":"5271 m.134","zorluk":"zor"},
    {"id":"5271-S-050","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.137'ye göre, kovuşturmaya yer olmadığı kararı verilmesi ya da hâkim onayı alınamaması hâlinde, iletişimin denetlenmesi kayıtları savcı denetiminde en geç kaç gün içinde yok edilir?","siklar":["otuz","yirmi","beş","on beş","on"],"dogru":4,"aciklama":"m.137/3: kayıtlar savcı denetiminde en geç on gün içinde yok edilir.","kaynak":"5271 m.137","zorluk":"orta"},
    {"id":"5271-S-051","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre hâkim ve savcıların karar veya işlemleri nedeniyle açılacak tazminat davaları kime karşı açılır?","siklar":["Devlete","İlgili hâkime","İlgili Cumhuriyet savcısına","Adalet Bakanlığı personeline","Kolluk amirine"],"dogru":0,"aciklama":"m.141/3: 'Hâkim ve savcıların karar/işlemleri nedeniyle tazminat davaları ancak DEVLET aleyhine açılır.' Devlet öder, sonra kusurlu hâkim/savcıya bir yıl içinde rücu eder (m.141/4).","kaynak":"5271 m.141","zorluk":"orta"},
    {"id":"5271-S-052","soru":"5271 sayılı Ceza Muhakemesi Kanunu m.149'a göre, soruşturma evresinde ifade almada en çok kaç avukat hazır bulunabilir?","siklar":["beş","üç","bir","iki","on"],"dogru":1,"aciklama":"m.149/2: 'Soruşturma evresinde, ifade almada en çok ÜÇ avukat hazır bulunabilir.'","kaynak":"5271 m.149","zorluk":"kolay"},
    {"id":"5271-S-053","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre kanunun başka hüküm koyduğu hâller saklı kalmak ve savunma haklarına zarar vermemek koşuluyla, soruşturma evresindeki usul işlemleri alenidir (herkese açıktır).","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.157/1: '...soruşturma evresindeki usul işlemleri GİZLİDİR.' Kovuşturma evresi (duruşma) alenidir, soruşturma değil.","kaynak":"5271 m.157","zorluk":"kolay"},
    {"id":"5271-S-054","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre Cumhuriyet savcısı, bir suçun işlendiği izlenimini veren bir hâli öğrenir öğrenmez ne yapar?","siklar":["Öncelikle hâkimden izin ister","Yalnızca kolluğa bilgi verip beklemeye geçer","Hemen işin gerçeğini araştırmaya başlar","Şikâyet süresinin dolmasını bekler","Doğrudan iddianame düzenler"],"dogru":2,"aciklama":"m.160/1: savcı, suç izlenimini öğrenir öğrenmez hemen işin gerçeğini araştırmaya başlar.","kaynak":"5271 m.160","zorluk":"kolay"},
    {"id":"5271-S-055","soru":"5271 sayılı Ceza Muhakemesi Kanunu'na göre iddianamenin kabulüyle ne gerçekleşir?","siklar":["Soruşturma evresi yeniden başlar","Şüpheli sıfatı kesinleşir","Uzlaştırma süreci zorunlu hâle gelir","Kamu davası açılmış olur ve kovuşturma evresi başlar","Adlî kontrol tedbirleri kendiliğinden kalkar"],"dogru":3,"aciklama":"m.175/1: 'İddianamenin kabulüyle, kamu davası açılmış olur ve kovuşturma evresi başlar.'","kaynak":"5271 m.175-176","zorluk":"kolay"},
  ],
  27: [
    {"id":"1774-S-001","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre aşağıdaki tesislerden hangisi bu Kanunun kapsamı dışındadır?","siklar":["Askeri konaklama ve kamp tesisleri ile ordu evleri","Marinalar","Liman tesisleri","Kıyı tesisleri","Dinlenme, bakım ve tedavi tesisleri"],"dogru":0,"aciklama":"m.1: 'Askeri konaklama, dinlenme ve kamp tesisleri ile ordu evleri bu Kanunun kapsamı dışındadır.' Diğer şıklar m.1'in birinci fıkrasında kapsama açıkça dahil edilen tesislerdir.","kaynak":"1774 m.1","zorluk":"kolay"},
    {"id":"1774-S-002","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 1 inci maddesine göre aşağıdakilerden hangisi Kanun kapsamında kimlik tespiti ve bildirimine tabi kişi/faaliyetler arasında sayılmamıştır?","siklar":["Konaklama tesislerinde geçici veya sürekli kalanlar","Askeri kamp tesislerinde konaklayanlar","İşyerlerinde çalışanlar","Konutlarda oturanlar","Araç, gemi/deniz turizmi aracı kiralayan gerçek ve tüzel kişiler"],"dogru":1,"aciklama":"m.1 birinci fıkra konaklama/dinlenme/bakım-tedavi tesisleri, marina, liman, kıyı tesisleri, işyerleri, konutlarda kalanlar/oturanlar/çalışanlar/ayrılanlar ile araç-gemi kiralayanları kapsar; ikinci fıkra ise askeri konaklama ve kamp tesislerini kapsam dışı bırakır.","kaynak":"1774 m.1","zorluk":"orta"},
    {"id":"1774-S-003","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre 2 nci maddede sayılan konaklama tesislerinin sorumlu işleticilerinin yükümlülüğü aşağıdakilerden hangisidir?","siklar":["Kayıtları haftalık olarak toplayıp ay sonunda kolluğa teslim etmek","Yalnızca yabancı uyruklu misafirlerin kayıtlarını tutmak","Kimlik ve geliş-ayrılış kayıtlarını günü gününe tutmak, genel kolluğun her an incelemesine hazır bulundurmak ve Devlet İstatistik Enstitüsüne talebi halinde vermek","Kayıtları yalnızca Devlet İstatistik Enstitüsüne aylık olarak bildirmek","Kayıtları yalnızca talep halinde tutmaya başlamak"],"dogru":2,"aciklama":"m.2: '...kimlik ve geliş-ayrılış kayıtlarını...günü gününe tutmak, genel kolluk örgütlerinin her an incelemelerine hazır bulundurmak, Devlet İstatistik Enstitüsüne, talebi halinde vermek zorundadırlar.'","kaynak":"1774 m.2","zorluk":"orta"},
    {"id":"1774-S-004","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre konaklama tesisi işleticileri, tuttukları kimlik ve geliş-ayrılış kayıtlarını periyodik olarak kendiliğinden Devlet İstatistik Enstitüsüne göndermek zorundadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2 kayıtları DİE'ye 'talebi halinde' verme yükümlülüğü öngörür; kendiliğinden periyodik gönderim şartı yoktur.","kaynak":"1774 m.2","zorluk":"orta"},
    {"id":"1774-S-005","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre 2 nci maddede sayılan tesislerin sorumlu işleticisinin kimliği ne zaman en yakın kolluk örgütüne bildirilir?","siklar":["Tesis açıldıktan 24 saat sonra","Tesis açıldıktan 3 gün sonra","Yalnızca denetim sırasında istenirse","Tesis açılmadan evvel","Yıl sonunda toplu olarak"],"dogru":3,"aciklama":"m.3: '...sorumlu işleticilerinin kimlikleri, tesis açılmadan evvel müessesenin sahibi veya kanuni temsilcisi tarafından...en yakın kolluk örgütüne bildirilir.'","kaynak":"1774 m.3","zorluk":"kolay"},
    {"id":"1774-S-006","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre sorumlu işleticinin değişmesi halinde bu durum ....(1).... içinde bildirilir; işleticinin görev ve yükümlülüklerini yöneticisine devretmesi halinde işletici ve yönetici ....(2).... sorumlu olurlar. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["3 gün - ayrı ayrı","30 gün - müştereken","24 saat - ayrı ayrı","3 gün - müştereken","24 saat - müştereken"],"dogru":4,"aciklama":"m.3: 'Sorumlu işleticinin değişmesi halinde keyfiyetin 24 saat içinde...bildirilmesi zorunludur...Bu durumda işletici ve yönetici müştereken sorumlu olurlar.'","kaynak":"1774 m.3","zorluk":"zor"},
    {"id":"1774-S-007","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre 2 nci maddedeki tesislerde çalıştırılan kimseler ve bunların ayrılışları en yakın kolluk örgütüne kaç saat içinde bildirilir?","siklar":["24 saat","12 saat","48 saat","72 saat","3 gün (72 saatten fazla)"],"dogru":0,"aciklama":"m.4: '...çalıştırdıkları kimseleri ve bunların ayrılışlarını...24 saat içinde bağlı oldukları en yakın kolluk örgütüne bildirirler.'","kaynak":"1774 m.4","zorluk":"kolay"},
    {"id":"1774-S-008","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kolluk örgütüne bildirilerek çalıştırılan kişilere verilen kimlik kartı, sorumlu işletici tarafından doldurulup onaylanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4: 'Kolluk örgütüne bildirilerek çalıştırılanlara, sorumlu işletici tarafından doldurulup onaylanan, örneğine uygun bir kimlik kartı verilir.'","kaynak":"1774 m.4","zorluk":"orta"},
    {"id":"1774-S-009","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre işyerlerinde çalışanlar ile öğrenci yurtlarında kalanlar için kimlik belgesi kaç gün içinde ve hangi onaydan sonra genel kolluk örgütüne verilir?","siklar":["24 saat içinde, valilik onayından sonra","3 gün içinde, mahalle veya köy muhtarı onayından sonra","30 gün içinde, belediye onayından sonra","3 gün içinde, il özel idaresi onayından sonra","24 saat içinde, doğrudan (onay aranmaksızın)"],"dogru":1,"aciklama":"m.6: '...üç gün içinde genel kolluk örgütüne verilmesi zorunludur...Kimlik bildirimleri, mahalli kolluk örgütüne verilmeden evvel mahalle veya köy muhtarına onaylatılır.'","kaynak":"1774 m.6","zorluk":"orta"},
    {"id":"1774-S-010","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kimlik bildirimleri elektronik ortamda genel kolluk kuvvetlerine yapıldığında da mahalle veya köy muhtarının onayı aranır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6 ek fıkra: 'Bildirimlerin elektronik ortamda yapılması durumunda üçüncü fıkra hükmü uygulanmaz.' (üçüncü fıkra muhtar onayını düzenler). Elektronik bildirimler genel kolluk tarafından sonradan muhtarla paylaşılır.","kaynak":"1774 m.6","zorluk":"zor"},
    {"id":"1774-S-011","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre konutlarda 30 günden fazla kalacak misafir için bildirim kim tarafından ve kaç gün içinde yapılır?","siklar":["Misafirin kendisi tarafından, 24 saat içinde","Konut sahibi tarafından, 30 gün içinde","Aile reisi tarafından, 3 gün içinde","Aile reisi tarafından, 30 gün içinde","Muhtar tarafından, 3 gün içinde"],"dogru":2,"aciklama":"m.7/a: 'Konutlarda 30 günden fazla kalacak misafir için aile reisi...tarafından, örneğine uygun bildirim, üç gün içinde kolluk örgütüne verilir.'","kaynak":"1774 m.7","zorluk":"orta"},
    {"id":"1774-S-012","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre yaylak ve kışlak gibi yerlere mevsimlik olarak göçenler için bildirim ....(1).... tarafından, ....(2).... içinde kolluk örgütüne verilir.","siklar":["muhtar - 24 saat","işletici - 3 gün","genel kolluk - anında","aile reisi - üç gün","aile reisi - 30 gün"],"dogru":3,"aciklama":"m.7/b: 'Yaylak ve kışlak gibi yerlere mevsimlik olarak göçenler için de aile reisi tarafından, örneğine uygun bildirim, üç gün içinde kolluk örgütüne verilir.'","kaynak":"1774 m.7","zorluk":"orta"},
    {"id":"1774-S-013","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre mevsimlik tarım işçisi olarak başka bir ilde geçici olarak çalışan kişilerin kimlik bildirimi nasıl yapılır?","siklar":["Aile reisi tarafından 3 gün içinde bildirilir","İşveren tarafından 24 saat içinde bildirilir","Muhtar onayından sonra genel kolluğa verilir","Bildirim yükümlülüğü yoktur","Doğrudan kolluk kuvvetlerince alınır ve Çalışma ve Sosyal Güvenlik Bakanlığı ile elektronik ortamda paylaşılır"],"dogru":4,"aciklama":"m.7 ek fıkra: '...kimlik bildirimleri, bu kişilerin yaşadıkları geçici yerleşim alanlarında doğrudan kolluk kuvvetlerince alınır ve bu bildirimler Çalışma ve Sosyal Güvenlik Bakanlığı ile elektronik ortamda paylaşılır.'","kaynak":"1774 m.7 (ek fıkra)","zorluk":"zor"},
    {"id":"1774-S-014","soru":"1774 sayılı Kimlik Bildirme Kanunu'ndaki süreler bakımından; işletici değişikliği ve çalışan bildirimi ....(1)...., işyeri/yurt bildirimi ve mevsimlik göç ....(2)...., konutta kalacak misafir için bildirim yükümlülüğü doğuran eşik ise ....(3)....'dür. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["24 saat - 3 gün - 30 gün","3 gün - 24 saat - 30 gün","24 saat - 30 gün - 3 gün","30 gün - 3 gün - 24 saat","3 gün - 30 gün - 24 saat"],"dogru":0,"aciklama":"m.3/m.4: işletici değişikliği ve çalışan bildirimi 24 saat içindedir. m.6/m.7: işyeri-yurt bildirimi ve mevsimlik göç 3 gün içindedir. m.7/a: 30 günden fazla kalacak misafir bildirim yükümlülüğü doğurur (bu bir eşiktir, bildirim yine 3 gün içinde yapılır).","kaynak":"1774 m.3, m.4, m.6, m.7","zorluk":"zor"},
    {"id":"1774-S-015","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kimliğini nüfus hüviyet cüzdanı veya diğer resmi geçerli belgelerle ispat edemeyen kimseler hakkında ne yapılır?","siklar":["Yalnızca kolluğa bildirilerek tesiste barındırılmaya devam edilir","Tesislerinde barındırılamaz, konut ve işyerlerinde çalıştırılamaz","Yalnızca işyerinde çalıştırılamaz, konaklama tesisinde barındırılabilir","Muhtar onayıyla barındırılabilir","3 gün içinde bildirilmek şartıyla barındırılabilir"],"dogru":1,"aciklama":"m.9: '...kimliğini...ispat edemeyen kimseleri tesislerinde barındıramaz, konut ve işyerlerinde çalıştıramaz.'","kaynak":"1774 m.9","zorluk":"kolay"},
    {"id":"1774-S-016","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kahvehane, oyun salonu, kulüp, lokal ve benzeri yatısız işyerlerinde kimler yatabilir?","siklar":["Herkes, kolluğa bildirim şartıyla","Yalnızca müşteriler, muhtar onayıyla","Yalnızca sahipleri ve çalıştırdıkları kimseler","Herkes, 3 gün içinde bildirim yapılması şartıyla","Yalnızca kolluk izniyle belirlenen kişiler"],"dogru":2,"aciklama":"m.10: '...ancak sahipleri ve çalıştırdıkları kimseler yatabilir, başkaları kalamazlar.'","kaynak":"1774 m.10","zorluk":"orta"},
    {"id":"1774-S-017","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre belediye veya il özel idaresince izin verilen sabahçı kahvesi ve benzeri tesislerde kalanlar için kimlik bildirimi yapılması zorunludur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10 son cümle: 'Buralarda kalanlar için bildirim yapılmaz.'","kaynak":"1774 m.10","zorluk":"orta"},
    {"id":"1774-S-018","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kat mülkiyetine tabi taşınmazların yönetici ve kapıcıları, tespit ettikleri Kanuna aykırılıkları ve şüpheli hususları kime bildirmekle yükümlüdür?","siklar":["Mahalle veya köy muhtarına","Kat malikleri kuruluna","Belediyeye","Bağlı oldukları genel kolluk örgütüne","Mülki idare amirine"],"dogru":3,"aciklama":"m.11: 'Yönetici ve kapıcıların, bu Kanuna aykırılıkları ve diğer şüpheli gördükleri hususları, bağlı oldukları genel kolluk örgütüne bildirmeleri gereklidir.'","kaynak":"1774 m.11","zorluk":"kolay"},
    {"id":"1774-S-019","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 17 nci maddesine göre aşağıdaki maddelerden hangisine aykırı hareket edilmesi, bu maddede öngörülen idari para cezası kapsamında değildir?","siklar":["6 ncı madde","7 nci madde","9 uncu madde","11 inci madde","4 üncü madde"],"dogru":4,"aciklama":"m.17: '6, 7, 9, 10 ve 11 inci maddelerdeki hükümlere aykırı hareket edenlere...idarî para cezası verilir.' 4 üncü madde ihlali ise m.15 kapsamındadır (3 ve 4 üncü maddeler) ve ayrı bir cezaya tabidir.","kaynak":"1774 m.15, m.17","zorluk":"zor"},
    {"id":"1774-S-020","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre bu Kanunda belirtilen idari para cezaları mahalli mülki amir tarafından verilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.18: 'Bu Kanunda belirtilen idarî para cezaları, mahallî mülkî amir tarafından verilir.'","kaynak":"1774 m.18","zorluk":"kolay"},
    {"id":"1774-S-021","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 1'e göre 2 nci maddede sayılan konaklama tesislerinin bilgisayar kayıtlarına ilişkin yükümlülüğü aşağıdakilerden hangisidir?","siklar":["Kayıtları günü gününe bilgisayarda tutmak ve genel kolluk terminallerine bağlanarak bilgi/belge/kayıtları anlık bildirmek","Kayıtları yıllık olarak arşivlemek","Kayıtları yalnızca talep halinde bilgisayara aktarmak","Kayıtları yalnızca il merkezine haftalık göndermek","Kayıtları yalnızca Devlet İstatistik Enstitüsüne anlık bildirmek"],"dogru":0,"aciklama":"Ek m.1: '...konaklama tesisleri tüm kayıtlarını bilgisayarda günü gününe tutmak, genel kolluk kuvvetlerinin bilgisayar terminallerine bağlanarak mevcut bilgi, belge ve kayıtları genel kolluk kuvvetlerine anlık olarak bildirmek zorundadırlar.'","kaynak":"1774 Ek m.1","zorluk":"orta"},
    {"id":"1774-S-022","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 1'e göre, genel kolluk kuvvetlerinin terminallerine bağlanmayan konaklama tesisi ile anlık veri göndermeyen veya gerçeğe aykırı kayıt tutan konaklama tesisine öngörülen idari para cezaları arasındaki ilişki aşağıdakilerden hangisidir?","siklar":["İki ihlalin cezası birbirine eşittir","Terminale bağlanmama cezası, anlık veri göndermeme/gerçeğe aykırı kayıt cezasından daha ağırdır","Anlık veri göndermeme cezası, terminale bağlanmama cezasından daha ağırdır","Bu iki fiil için ceza öngörülmemiştir, yalnızca uyarı verilir","Ceza yalnızca dördüncü tekrarda uygulanır, ilk ihlalde uygulanmaz"],"dogru":1,"aciklama":"Ek m.1: 'İkinci fıkrada belirtilen genel kolluk kuvvetlerinin terminallerine bağlanmayanlara onbin Türk Lirası, anlık veri göndermeyen veya gerçeğe aykırı kayıt tutanlara beşbin Türk Lirası idari para cezası...verilir.' Terminale hiç bağlanmama, anlık bildirim yapmama/hatalı kayıttan daha ağır cezalandırılır.","kaynak":"1774 Ek m.1","zorluk":"zor"},
    {"id":"1774-S-023","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 3'e göre araç, gemi/deniz aracı kiralama işletmeleri, kiralanan araçlarda bulundurdukları GPS cihazına ilişkin konum bilgisi kayıtlarını ne kadar süreyle saklamak zorundadır?","siklar":["1 yıl","2 yıl","3 yıl","5 yıl","10 yıl"],"dogru":2,"aciklama":"Ek m.3: '...kiralanan araçlarda GPS cihazı (küresel uydu navigasyon sistemi) bulundurarak, araçlara ait konum bilgisine ilişkin kayıtları üç yıl saklamak zorundadırlar.'","kaynak":"1774 Ek m.3","zorluk":"orta"},
    {"id":"1774-S-024","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 3'e göre araç, gemi/deniz aracı kiralama esnasında gerçeğe aykırı kimlik kullanan kişi, bu Kanunda öngörülen idari para cezasına tabidir; 5237 sayılı Türk Ceza Kanunu hükümleri uygulanmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek m.3: 'Araç, gemi/deniz aracı kiralama esnasında gerçeğe aykırı kimlik kullananlar ile birinci fıkra kapsamında elde edilen bilgi ve kayıtları hukuka aykırı olarak kullanan, veren, yayan veya ele geçiren kişi, 5237 sayılı Türk Ceza Kanunu hükümlerine göre cezalandırılır.' Bu fiil idari değil adli bir suçtur.","kaynak":"1774 Ek m.3","zorluk":"orta"},
    {"id":"1774-S-025","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre aşağıdaki eşleştirmelerden hangisi doğrudur?","siklar":["Sorumlu işletici değişikliği - 3 gün","İşyeri/yurt bildirimi - 24 saat","Mevsimlik göç bildirimi - 24 saat","Çalışan bildirimi ve ayrılışı - 24 saat","Konutta 30 günden fazla kalacak misafir bildirimi - 30 gün"],"dogru":3,"aciklama":"m.4: çalışan bildirimi ve ayrılışı 24 saat içinde bildirilir. İşletici değişikliği de (m.3) 24 saattir (A yanlış eşleştirilmiş); işyeri/yurt bildirimi (m.6) ve mevsimlik göç (m.7/b) 3 gündür (B, C yanlış); 30 günden fazla kalacak misafir bildirimi süresi de 3 gündür, 30 gün yalnızca bildirim eşiğidir (E yanlış).","kaynak":"1774 m.3, m.4, m.6, m.7","zorluk":"zor"},
    {"id":"1774-S-026","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 2 nci maddesinde sayılan konaklama tesisi türlerinden hangisi bu madde kapsamında SAYILMAMIŞTIR?","siklar":["Öğrenci yurtları","Bekar odaları ve günübirlik kiralanan evler","Kamp, kamping ve tatil köyü","Dinlenme ve huzur evleri","Dini ve hayır kurumlarının sosyal tesisleri"],"dogru":0,"aciklama":"m.2: 'Otel, motel, han, pansiyon, bekar odaları, günübirlik kiralanan evler, kamp, kamping, tatil köyü, marinalar, liman tesisi, kıyı tesisi ve benzeri her türlü...konaklama yerleri ile özel sağlık müesseseleri, dinlenme ve huzur evleri, dini ve hayır kurumlarının sosyal tesisleri...' sayılmıştır. Öğrenci yurtları m.6/(c) bendinde ayrı düzenlenmiştir, m.2 kapsamında değildir.","kaynak":"1774 m.2","zorluk":"orta"},
    {"id":"1774-S-027","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kamu kuruluşlarına ait konaklama tesislerinde sorumluluk kimdedir?","siklar":["Yalnızca genel kolluk örgütünde","Amir ve müdürleri, işletici gibi sorumludur","Sorumluluk aranmaz, kamu tesisleri Kanun kapsamı dışındadır","Yalnızca mahalli mülki amirde","Yalnızca Devlet İstatistik Enstitüsünde"],"dogru":1,"aciklama":"m.3 son fıkra: 'Kamu kuruluşlarına ait tesislerin amir ve müdürleri işletici gibi sorumludurlar.'","kaynak":"1774 m.3","zorluk":"orta"},
    {"id":"1774-S-028","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kolluk örgütüne bildirilerek çalıştırılan kişi, kendisine verilen kimlik kartını kolluk görevlilerince her istenildiğinde göstermek zorundadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4 üçüncü fıkra: 'Kolluk görevlilerince her istenildiğinde bu kimlik kartının gösterilmesi zorunludur.'","kaynak":"1774 m.4","zorluk":"kolay"},
    {"id":"1774-S-029","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 6 ncı maddesine göre öğrenci yurtları ve benzeri yerlerde kalan öğrenciler için kimlik bildirimini yapmakla kim yükümlüdür?","siklar":["Öğrencinin kendisi","Yurdun bağlı olduğu il milli eğitim müdürlüğü","O yerin sorumlu işleticisi","Öğrencinin ailesi","Mahalle veya köy muhtarı"],"dogru":2,"aciklama":"m.6/(c): 'Öğrenci yurtları ve benzeri yerlerde çalışanlar ile bu yerlerde kalmakta olan öğrenciler için o yerin sorumlu işleticisi...tarafından...bildirilmesi zorunludur.'","kaynak":"1774 m.6","zorluk":"kolay"},
    {"id":"1774-S-030","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 6 ncı maddesindeki (a) ve (d) bentleri halen yürürlüktedir ve bağımsız bildirim yükümlülükleri düzenlemektedir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6'nın (a) ve (d) bentleri 5490 sayılı Kanunla (25/4/2006) mülga edilmiştir; yürürlükte olan bentler yalnızca (b) işyerleri ve (c) öğrenci yurtlarıdır.","kaynak":"1774 m.6","zorluk":"zor"},
    {"id":"1774-S-031","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 10 uncu maddesine göre aşağıdakilerden hangisi sabahçı kahvesi ve benzeri tesislere geçici veya sürekli izin verilebilecek 'zorunluluk olan zaman ve yerler' arasında SAYILMAMIŞTIR?","siklar":["İskele","İstasyon","Hava meydanı terminali","Kat mülkiyetine tabi apartman girişi","Fuar, panayır, sergi ve pazar kurulması"],"dogru":3,"aciklama":"m.10 ikinci fıkra: 'İskele, istasyon, hava meydanı terminal, garaj, benzin istasyonu ve benzeri kara, deniz ve hava ulaşım merkezleri ile fuar, panayır, sergi ve pazar kurulması gibi...' sayılmıştır. Apartman girişi bu sayımda yoktur, kat mülkiyeti m.11'de ayrı düzenlenmiştir.","kaynak":"1774 m.10","zorluk":"orta"},
    {"id":"1774-S-032","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre kat sahipleri, kiracılar ve binada çalışanlar, bildirim dışı kimselerin tespiti konusunda yöneticiye yardımcı olmak ve gereken bilgileri vermek zorundadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.11 ikinci fıkra: 'Bütün kat sahipleri ve kiracıları ile binada çalışanlar bu konularda yöneticiye yardımcı olmak ve gereken bilgileri vermek zorundadırlar.'","kaynak":"1774 m.11","zorluk":"kolay"},
    {"id":"1774-S-033","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun 12 nci maddesine göre bildirimlerle ilgili uygulama yönetmeliği hangi bakanlıklarca müştereken hazırlanır?","siklar":["İçişleri, Milli Eğitim, Sağlık ve Maliye Bakanlıkları","Yalnızca İçişleri Bakanlığı","Dışişleri, İçişleri ve Adalet Bakanlıkları","Hazine ve Maliye, İçişleri Bakanlıkları","Adalet, İçişleri, Turizm ve Tanıtma ile Devlet İstatistik Enstitüsü işlerine bakan Devlet Bakanlıkları"],"dogru":4,"aciklama":"m.12: '...Adalet, İçişleri, Turizm ve Tanıtma ve Devlet İstatistik Enstitüsü işlerine bakan Devlet Bakanlıklarınca müştereken hazırlanacak bir yönetmelikle gösterilir.'","kaynak":"1774 m.12","zorluk":"orta"},
    {"id":"1774-S-034","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre bu Kanuna göre verilecek belgeler ve yapılacak bildirimler hangi mali yükümlülükten muaftır?","siklar":["Her çeşit vergi, resim ve harçtan","Yalnızca damga vergisinden","Yalnızca harçtan","Yalnızca noter ücretinden","Muafiyet yoktur, tüm bildirimler harca tabidir"],"dogru":0,"aciklama":"m.14: 'Bu Kanuna göre verilecek belgeler ve yapılacak her türlü bildirimler, her çeşit vergi, resim ve harçtan muaftır.'","kaynak":"1774 m.14","zorluk":"kolay"},
    {"id":"1774-S-035","soru":"1774 sayılı Kimlik Bildirme Kanunu'na göre mahkeme kararı olmadıkça, yetkili resmi örgütler dışında hiç kimsenin bu Kanuna göre tutulan bildirim ve belgelerden yararlanmasına izin verilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.14: 'Mahkeme kararı olmadıkça, yetkili resmi örgütler dışında, hiç kimsenin bunlardan yararlanmasına müsaade edilemez.'","kaynak":"1774 m.14","zorluk":"orta"},
    {"id":"1774-S-036","soru":"1774 sayılı Kimlik Bildirme Kanunu'nun ceza hükümlerine göre, kanunda öngörülen nominal tutarlar esas alındığında aşağıdaki ihlallerden hangisine öngörülen idari para cezası en DÜŞÜK kademededir?","siklar":["3 üncü ve 4 üncü maddelerdeki yükümlülüklere aykırılık","6, 7, 9, 10 ve 11 inci maddelerdeki hükümlere aykırı hareket etme","Kimlik bildirme belgesinde gerçeğe uymayan bilgi verme","Terminale bağlanmama (Ek m.1)","Anlık veri göndermeme veya gerçeğe aykırı kayıt tutma (Ek m.1)"],"dogru":1,"aciklama":"Nominal tutarlar: m.15 (3-4 üncü madde) ikiyüzelli TL, m.17 (6,7,9,10,11 inci madde) yirmi TL ve gerçeğe aykırı bilgi yüz TL, Ek m.1 terminal onbin TL ve anlık veri beşbin TL. En düşük nominal ceza m.17'nin ilk cümlesindeki yirmi TL'dir (6,7,9,10,11 inci maddelere aykırılık).","kaynak":"1774 m.15, m.17, Ek m.1","zorluk":"zor"},
    {"id":"1774-S-037","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 1'e göre konaklama tesisleri, terminallere bağlanmak için gerekli işlemleri, maddenin yürürlüğe girdiği tarihten itibaren ....(1).... içinde tamamlar; bu maddeye göre verilen idari para cezaları ise tebliğinden itibaren ....(2).... içinde ödenir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["1 ay - 2 ay","6 ay - 1 ay","2 ay - 1 ay","3 ay - 6 ay","1 yıl - 3 ay"],"dogru":2,"aciklama":"Ek m.1: terminale bağlanma işlemleri 'iki ay içinde' tamamlanır; idari para cezaları ise 'tebliğinden itibaren bir ay içinde' ödenir.","kaynak":"1774 Ek m.1","zorluk":"zor"},
    {"id":"1774-S-038","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 1'e göre, verileri kullanan kamu personelinin denetimine ilişkin usul ve esaslar Devlet İstatistik Enstitüsü tarafından belirlenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek m.1 son fıkra: 'Bu maddenin uygulanması ile görevi gereği bu verileri kullanan kamu personelinin denetimine ilişkin usul ve esaslar İçişleri Bakanlığı tarafından belirlenir.' Devlet İstatistik Enstitüsü değil İçişleri Bakanlığı yetkilidir.","kaynak":"1774 Ek m.1","zorluk":"orta"},
    {"id":"1774-S-039","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 2'ye göre 4 üncü ve 6 ncı maddeler gereğince verilen sürekli veya geçici çalışanlara ait kimlik bilgileri kime bildirilir?","siklar":["Devlet İstatistik Enstitüsüne","Çalışma ve Sosyal Güvenlik Bakanlığına doğrudan","Mahalle veya köy muhtarına","İlgili Sosyal Güvenlik Kurumu Başkanlığı il müdürlükleri veya merkez müdürlüklerine","Mahalli mülki amire"],"dogru":3,"aciklama":"Ek m.2: 'Bu Kanunun 4 üncü ve 6 ncı maddeleri gereğince verilen sürekli veya geçici olarak çalışanlara ait kimlik bilgileri, genel kolluk kuvvetlerince ilgili Sosyal Güvenlik Kurumu Başkanlığı il müdürlükleri veya merkez müdürlüklerine bildirilir.'","kaynak":"1774 Ek m.2","zorluk":"orta"},
    {"id":"1774-S-040","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 3'e göre araç kiralayanın kamu kurum veya kuruluşu olması halinde işletmenin yükümlülüğü nasıl daralır?","siklar":["Yükümlülük tamamen kalkar","Yalnızca GPS bulundurma yükümü kalkar","Yalnızca anlık bildirim yükümü kalkar","Yükümlülük değişmez, tüm şartlar aynen uygulanır","Yalnızca kamu kurum veya kuruluşuyla yapılan sözleşme ile araç bilgileri sisteme kaydedilir"],"dogru":4,"aciklama":"Ek m.3 birinci fıkra son cümle: 'Ancak araç kiralayanın kamu kurum veya kuruluşu olması hâlinde sadece kamu kurum veya kuruluşuyla yapılan sözleşme ile araç bilgileri sisteme kaydedilir.'","kaynak":"1774 Ek m.3","zorluk":"orta"},
    {"id":"1774-S-041","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 3'e göre bu maddede öngörülen idari yaptırımların uygulanması, ilgili fiil hakkında ceza soruşturması ve kovuşturması yapılmasına engeldir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek m.3: 'Bu fıkraya göre idari yaptırımların uygulanması ceza soruşturması ve kovuşturması yapılmasına engel değildir.' İdari ve adli süreçler birlikte yürüyebilir.","kaynak":"1774 Ek m.3","zorluk":"zor"},
    {"id":"1774-S-042","soru":"1774 sayılı Kimlik Bildirme Kanunu Ek Madde 3'e göre işlenen bir suçun gizlenmesi amacıyla araç kiralama bilgilerinin yok edilmesi halinde uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["İşletme ruhsatı, tekrar veya dördüncü ihlal şartı aranmaksızın doğrudan iptal edilir","Yalnızca idari para cezasının iki katı uygulanır","Yalnızca uyarı verilir","Herhangi bir yaptırım öngörülmemiştir","Yalnızca mülki idare amirine bilgi verilir, işlem yapılmaz"],"dogru":0,"aciklama":"Ek m.3: 'İşlenen bir suçun gizlenmesi amacıyla bilgilerin yok edilmesi halinde işletme ruhsatı iptal edilir.' Bu düzenleme, aynı fıkradaki genel kuraldan (aynı takvim yılında dördüncü tekrarda ruhsat iptali) BAĞIMSIZ, doğrudan ve ilk seferde uygulanan ayrı bir yaptırımdır.","kaynak":"1774 Ek m.3","zorluk":"zor"},
    {"id":"1774-S-043","soru":"1774 sayılı Kimlik Bildirme Kanunu Geçici Madde 4'e göre araç kiralama şirketleri, maddenin yürürlüğe girdiği tarihten itibaren ....(1).... içinde bilgisayar terminallerini genel kolluğa bağlamak zorundadır; bu şartı yerine getirmeyenlere ceza verildikten sonra fiilin tekrarında ....(2).... uygulanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["2 ay - ceza iki katı","6 ay - işletme ruhsatı iptali","3 gün - uyarı","1 yıl - faaliyet durdurma","24 saat - tekrar ceza"],"dogru":1,"aciklama":"Geçici Madde 4: '...altı ay içinde araç kiralama şirketleri...bağlamak zorundadırlar...Bu fiilin tekrarı hâlinde işletme ruhsatları iptal edilir.'","kaynak":"1774 Geçici m.4","zorluk":"orta"},
  ],
  28: [
    {"id":"2911-S-001","soru":"2911 sayılı Toplantı ve Gösteri Yürüyüşleri Kanunu'nun 1 inci maddesine (amaç ve kapsam) göre, aşağıdakilerden hangisi bu Kanunun düzenleme alanına girmez?","siklar":["Toplantı ve gösteri yürüyüşü düzenleme hakkının kullanılmasında uygulanacak şekil, şart ve usuller","Düzenleme kurulunun görev ve sorumlulukları","Yetkili merciin yasaklama ve erteleme halleri","Toplantı ve gösteri yürüyüşü düzenleyenlerden alınacak katılım ücreti tarifesi","Güvenlik kuvvetlerinin görev ve yetkileri ile yasakları ve ceza hükümleri"],"dogru":3,"aciklama":"m.1: 'Bu Kanun; toplantı ve gösteri yürüyüşü düzenleme hakkının kullanılmasında uygulanacak şekil, şart ve usuller ile ... düzenleme kurulunun görev ve sorumluluklarını, yetkili merciin yasaklama ve erteleme hallerini, güvenlik kuvvetlerinin görev ve yetkileri ile yasakları ve ceza hükümlerini düzenler.' Bir 'katılım ücreti tarifesi' Kanunun hiçbir yerinde geçmez.","kaynak":"2911 m.1","zorluk":"kolay"},
    {"id":"2911-S-002","soru":"2911 sayılı Kanun'a göre 'belirli konular üzerinde halkı aydınlatmak ve bir kamuoyu yaratmak suretiyle o konuyu benimsetmek için gerçek ve tüzelkişiler tarafından bu Kanun çerçevesinde düzenlenen yürüyüşler' ifadesi hangi kavramın tanımıdır?","siklar":["Gösteri yürüyüşü","Toplantı","Düzenleme kurulu faaliyeti","Propaganda toplantısı","Açık yer toplantısı"],"dogru":0,"aciklama":"m.2/b: 'Gösteri yürüyüşü; belirli konular üzerinde halkı aydınlatmak ve bir kamuoyu yaratmak suretiyle o konuyu benimsetmek için gerçek ve tüzelkişiler tarafından bu Kanun çerçevesinde düzenlenen yürüyüşleri, ifade eder.'","kaynak":"2911 m.2","zorluk":"kolay"},
    {"id":"2911-S-003","soru":"2911 sayılı Kanun'a göre ilçelerde 'mahallin en büyük mülki amiri' kimdir?","siklar":["İlçe emniyet amiri","Kaymakam","İlçe jandarma komutanı","Belediye başkanı","Vali"],"dogru":1,"aciklama":"m.2/c: 'Mahallin en büyük mülki amiri; illerde vali, ilçelerde kaymakamı ... ifade eder.'","kaynak":"2911 m.2","zorluk":"kolay"},
    {"id":"2911-S-004","soru":"2911 sayılı Kanun'a göre bir ile bağlı ilçelerin, o ilin belediye sınırları içindeki kısımlarına ilişkin olarak Kanunun uygulanması yönünden mahallin en büyük mülki amiri, ilçenin kaymakamıdır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2 son fıkra: 'Bir il'e bağlı ilçelerin, o ilin belediye sınırları içindeki kısımlarına ilişkin olarak bu Kanunun uygulaması yönünden mahallin en büyük mülki amiri, ilin valisidir.' Kaymakam değil, vali yetkilidir.","kaynak":"2911 m.2","zorluk":"orta"},
    {"id":"2911-S-005","soru":"2911 sayılı Kanun'a göre herkes, önceden izin almaksızın, silahsız ve saldırısız olarak kanunların suç saymadığı belirli amaçlarla toplantı ve gösteri yürüyüşü düzenleme hakkına sahiptir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3/1: 'Herkes, önceden izin almaksızın, bu Kanun hükümlerine göre silahsız ve saldırısız olarak kanunların suç saymadığı belirli amaçlarla toplantı ve gösteri yürüyüşü düzenleme hakkına sahiptir.'","kaynak":"2911 m.3","zorluk":"kolay"},
    {"id":"2911-S-006","soru":"2911 sayılı Kanun'a göre yabancıların toplantı ve gösteri yürüyüşü düzenlemeleri hangi makamın iznine bağlıdır ve topluluğa hitap etmeleri/afiş taşımaları en az kaç saat önce yapılacak bildirimle mümkündür?","siklar":["Valiliğin izni – 24 saat","Emniyet Genel Müdürlüğünün izni – 72 saat","İçişleri Bakanlığının izni – 48 saat","İçişleri Bakanlığının izni – 24 saat","Valiliğin izni – 48 saat"],"dogru":2,"aciklama":"m.3/2: 'Yabancıların bu Kanun hükümlerine göre toplantı ve gösteri yürüyüşü düzenlemeleri, İçişleri Bakanlığının iznine bağlıdır. ... toplantının yapılacağı mahallin en büyük mülkî idare amirliğine toplantıdan en az kırksekiz saat önce yapılacak bildirimle mümkündür.'","kaynak":"2911 m.3","zorluk":"orta"},
    {"id":"2911-S-007","soru":"2911 sayılı Kanun'a göre aşağıdakilerden hangisi Kanunun 4 üncü maddesinde sayılan ve bu Kanun hükümlerine tabi olmayan istisnalar arasında SAYILMAMIŞTIR?","siklar":["Siyasi partilerin kendi tüzüklerine göre yapacakları kapalı yer toplantıları","Kanun, gelenek ve göreneklere göre yapılan düğün, şenlik, karşılama ve uğurlamalar","Spor faaliyetleri ile bilimsel, ticari ve ekonomik amaçlarla yapılan toplantılar","Sendikaların açık havada, meydanda düzenleyeceği kitlesel bir basın açıklaması toplantısı","Cumhurbaşkanının Devlet işleri hakkındaki toplantı ve konuşmaları"],"dogru":3,"aciklama":"m.4/a istisnayı yalnız 'kapalı yer toplantıları' ile sınırlar: '...sendikaların, ... özel kanunlarına ve kendi tüzüklerine göre yapacakları kapalı yer toplantıları.' Sendikaların AÇIK HAVADA/meydanda düzenleyeceği kitlesel toplantı bu istisna kapsamında değildir, 2911 hükümlerine tabidir. A, B, C, E metinde birebir sayılmıştır.","kaynak":"2911 m.4","zorluk":"zor"},
    {"id":"2911-S-008","soru":"2911 sayılı Kanun'a göre seçim zamanlarında yapılacak propaganda toplantıları hakkında ne öngörülmüştür?","siklar":["2911 sayılı Kanun bu toplantılara da aynen uygulanır","Bu toplantılar İçişleri Bakanlığının iznine tabidir","Bu toplantılar tamamen yasaktır","Bu toplantılarda düzenleme kurulu aranmaz","Bu toplantılara ilişkin (kendi) kanun hükümleri saklıdır"],"dogru":4,"aciklama":"m.5: 'Seçim zamanlarında yapılacak propaganda toplantıları ile ilgili kanun hükümleri saklıdır.' Yani seçim mevzuatı (kendi özel hükümleri) uygulanır.","kaynak":"2911 m.5","zorluk":"kolay"},
    {"id":"2911-S-009","soru":"2911 sayılı Kanun'a göre il ve ilçelerde toplantı ve gösteri yürüyüşü yer ve güzergâhı, ilgili kesimlerin görüşleri alınarak kim tarafından belirlenir?","siklar":["Mahallin en büyük mülki amiri","İl/ilçe belediye başkanı","Düzenleme kurulu","Mahallin güvenlik amirleri","İçişleri Bakanlığı"],"dogru":0,"aciklama":"m.6/2: '... görüşleri alınarak mahallin en büyük mülki amiri tarafından belirlenir.'","kaynak":"2911 m.6","zorluk":"orta"},
    {"id":"2911-S-010","soru":"2911 sayılı Kanun'a göre toplantı ve gösteri yürüyüşü yer ve güzergâhı hakkında sonradan yapılacak değişiklikler, duyurudan ....... sonra geçerli olur.","siklar":["yedi gün","onbeş gün","on gün","yirmi gün","otuz gün"],"dogru":1,"aciklama":"m.6/4: 'Bu değişiklikler duyurudan on beş gün sonra geçerli olur.'","kaynak":"2911 m.6","zorluk":"orta"},
    {"id":"2911-S-011","soru":"2911 sayılı Kanun'a göre belirlenen toplantı ve gösteri yürüyüşü yer ve güzergâhı, yerel gazeteler ve internet haber siteleri ile valilik ve kaymakamlık internet sitelerinden ilan edilerek halka duyurulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/3: 'Belirlenen toplantı ve gösteri yürüyüşü yer ve güzergâhı yerel gazeteler ve internet haber siteleri ile valilik ve kaymakamlık internet sitelerinden ilan edilerek halka duyurulur.' (İnternet haber siteleri ibaresi 13/10/2022-7418/28 ile eklenmiştir.)","kaynak":"2911 m.6","zorluk":"orta"},
    {"id":"2911-S-012","soru":"2911 sayılı Kanun'a göre toplantı ve yürüyüşlere ve bu amaçla toplanmalara güneş doğmadan başlanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7/1: 'Toplantı ve yürüyüşlere ve bu amaçla toplanmalara güneş doğmadan başlanamaz.' Başlangıç için güneşin doğmuş olması şarttır.","kaynak":"2911 m.7","zorluk":"kolay"},
    {"id":"2911-S-013","soru":"2911 sayılı Kanun'un 7 nci maddesindeki zaman sınırlamasıyla ilgili güncel durum aşağıdakilerden hangisidir?","siklar":["Maddenin her iki fıkrası da yürürlüktedir","Madde tamamen yürürlükten kaldırılmıştır","Maddenin ikinci fıkrası (7145 sayılı Kanunla değişik gece sınırlaması) Anayasa Mahkemesi kararıyla iptal edilmiş, yalnızca birinci fıkra ('güneş doğmadan başlanamaz') yürürlüktedir","Yalnızca ikinci fıkra yürürlüktedir, birinci fıkra iptal edilmiştir","Madde, 6529 sayılı Kanunla değiştirilerek gece toplantılarını tamamen serbest bırakmıştır"],"dogru":2,"aciklama":"m.7: '(Değişik ikinci fıkra: 25/7/2018-7145/9 md.) (İptal: Anayasa Mahkemesi'nin 30/6/2022 tarihli ve E.: 2018/137, K.: 2022/86 sayılı Kararı ile.)' Yalnızca birinci fıkra ('güneş doğmadan başlanamaz') yürürlüktedir.","kaynak":"2911 m.7","zorluk":"zor"},
    {"id":"2911-S-014","soru":"2911 sayılı Kanun'a göre toplantının yapıldığı yer, yalnızca toplantı süresince umuma açık yer sayılır; toplantı bitince bu statü sona erer.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8: 'Toplantının yapıldığı yer, toplantı süresince umuma açık yer sayılır.' Bu statü yalnızca toplantı SÜRESİNCE geçerlidir.","kaynak":"2911 m.8","zorluk":"kolay"},
    {"id":"2911-S-015","soru":"2911 sayılı Kanun'a göre düzenleme kurulu, kendi üyelerinden başkan dahil en az kaç kişiyi toplantının yapıldığı yerde bulundurmakla yükümlüdür?","siklar":["Beş","Altı","Sekiz","Yedi","Dokuz"],"dogru":3,"aciklama":"m.11/1: 'Düzenleme kurulu, kendi üyelerinden başkan dahil en az yedi kişiyi toplantının yapıldığı yerde bulundurmakla yükümlüdür.'","kaynak":"2911 m.11","zorluk":"orta"},
    {"id":"2911-S-016","soru":"2911 sayılı Kanun'a göre toplantı ve gösteri yürüyüşlerinde kolluk tarafından yapılan ses ve görüntü kaydından elde edilen kayıt ve görüntüler hangi amaçla kullanılabilir?","siklar":["Basın yayın organlarına dağıtım amacıyla","Katılımcıların kişisel arşivi amacıyla","Düzenleme kurulunun performans değerlendirmesi amacıyla","Sınırlama yoktur, her amaçla kullanılabilir","Yalnızca şüphelilerin ve suç delillerinin tespiti amacıyla"],"dogru":4,"aciklama":"m.11 ek fıkra: 'Elde edilen kayıt ve görüntüler şüphelilerin ve suç delillerinin tespiti dışında başka bir amaçla kullanılamaz.'","kaynak":"2911 m.11","zorluk":"orta"},
    {"id":"2911-S-017","soru":"2911 sayılı Kanun'a göre toplantının amacı dışına çıktığı veya düzen içinde gerçekleşmesinin imkânsız olduğu durumlarda, düzenleme kurulu toplanamadığı takdirde dağılma kararını kim alır?","siklar":["Kurul başkanı","Mahallin en büyük mülki amiri","Yetkili kolluk amiri","Mahallin güvenlik amiri","Vali"],"dogru":0,"aciklama":"m.12/2: '...kurul veya toplanamadığı takdirde kurul başkanı dağılma kararı alır ve durumu derhâl yetkili kolluk amirine bildirir.'","kaynak":"2911 m.12","zorluk":"orta"},
    {"id":"2911-S-018","soru":"2911 sayılı Kanun'a göre aşağıdakilerden hangisinde toplantı yapılması yasak DEĞİLDİR?","siklar":["Parklarda","Genel meydanlarda","Mabetlerde","Kamu hizmeti görülen bina ve tesislerde","Türkiye Büyük Millet Meclisine bir kilometre uzaklıktaki alan içinde"],"dogru":1,"aciklama":"m.22: 'parklarda, mabetlerde, kamu hizmeti görülen bina ve tesislerde ve bunların eklentilerinde ve Türkiye Büyük Millet Meclisine bir kilometre uzaklıktaki alan içinde toplantı yapılamaz.' Genel meydanlarda toplantı yasak değildir; yalnızca 'halkın ve ulaşım araçlarının gelip geçmesini sağlamak üzere valilik ve kaymakamlıklarca yapılacak düzenlemelere uyulması zorunludur.'","kaynak":"2911 m.22","zorluk":"orta"},
    {"id":"2911-S-019","soru":"2911 sayılı Kanun'a göre Türkiye Büyük Millet Meclisine ....... uzaklıktaki alan içinde toplantı yapılamaz.","siklar":["500 metre","2 kilometre","1 kilometre","3 kilometre","5 kilometre"],"dogru":2,"aciklama":"m.22: '...Türkiye Büyük Millet Meclisine bir kilometre uzaklıktaki alan içinde toplantı yapılamaz.'","kaynak":"2911 m.22","zorluk":"kolay"},
    {"id":"2911-S-020","soru":"2911 sayılı Kanun'un 23 üncü maddesine göre aşağıdakilerden hangisi bir toplantı veya gösteri yürüyüşünün Kanuna aykırı sayılması sebeplerinden biri DEĞİLDİR?","siklar":["Bildirim verilmeden veya belirtilen gün ve saatten önce ya da sonra yapılması","Ateşli silah, patlayıcı madde veya kesici-delici alet taşınarak katılım sağlanması","Belirtilen yerler dışında yapılması","Toplantıya katılan kişi sayısının önceden bildirilen sayıdan fazla olması","12 nci madde gereğince toplantının dağılmasına karar verilmesi hâlinde devam edilmesi"],"dogru":3,"aciklama":"m.23'te sayılan sebepler arasında bildirimsizlik/zaman (a bendi), yasak eşya taşıma/örtünme (b bendi), belirtilen yer dışında yapılma (d bendi) ve dağılma kararına rağmen devam (j bendi) yer alır; ancak 'katılımcı sayısının bildirilenden fazla olması' madde metninde bir aykırılık sebebi olarak SAYILMAMIŞTIR.","kaynak":"2911 m.23","zorluk":"zor"},
    {"id":"2911-S-021","soru":"2911 sayılı Kanun'a göre Kanuna uygun başlayan bir toplantı sonradan Kanuna aykırı hâle dönüşür ve düzenleme kurulu veya kurul başkanı bu görevi yerine getirmezse, durum sırasıyla nasıl işler?","siklar":["Durum doğrudan İçişleri Bakanlığına bildirilir ve Bakanlık dağıtma kararı verir","Durum güvenlik amiri tarafından doğrudan zor kullanılarak sonlandırılır","Durum vali tarafından doğrudan İçişleri Bakanlığına bildirilir","Durum düzenleme kurulu üyelerinin oylamasıyla çözülür","Durum yetkili kolluk amiri tarafından mahallin en büyük mülki amirine bildirilir; mülki amir sona erdirilip erdirilmeyeceğine karar verir"],"dogru":4,"aciklama":"m.24/b: 'Düzenleme kurulunun veya kurul başkanının bu görevi yerine getirmemesi hâlinde, durum yetkili kolluk amiri tarafından mahallin en büyük mülki amirine bildirilir. Mahallin en büyük mülki amiri tarafından toplantının sona erdirilip erdirilmeyeceğine dair karar alınır.'","kaynak":"2911 m.24","zorluk":"orta"},
    {"id":"2911-S-022","soru":"2911 sayılı Kanun'a göre güvenlik kuvvetlerine karşı fiilî saldırı veya mukavemet hâli mevcutsa, ihtara gerek olmaksızın doğrudan zor kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.24: 'Birinci fıkrada düzenlenen durumlarda güvenlik kuvvetlerine karşı fiili saldırı veya mukavemet veya korudukları yerlere ve kişilere karşı fiili saldırı hali mevcutsa, ihtara gerek olmaksızın zor kullanılır.'","kaynak":"2911 m.24","zorluk":"zor"},
    {"id":"2911-S-023","soru":"2911 sayılı Kanun'a göre topluluk içinde suç işleyenleri ve suçluları yakalamak için 24 üncü maddede belirtilen emir ve ihtarların yapılması şarttır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.25: 'Topluluk içinde suç işleyenleri ve suçluları yakalamak için 24 üncü maddede belirtilen emir ve ihtarların yapılmasına gerek yoktur.'","kaynak":"2911 m.25","zorluk":"orta"},
    {"id":"2911-S-024","soru":"2911 sayılı Kanun'a göre toplantı çağrı ilanlarında düzenleme kurulu başkanı ile en az ....(1).... üyenin imzası bulunmalı; hoparlörle çağrı ise güneşin ....(2).... arasındaki zaman içinde yapılabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["altı - doğuşundan batışına kadar","beş - doğuşundan batışına kadar","yedi - doğuşundan batışına kadar","altı - batışından doğuşuna kadar","altı - öğleden önce ve sonrası"],"dogru":0,"aciklama":"m.26/1: '...düzenleme kurulu başkanı ile en az altı üyesinin adları, soyadları ve imzalarının bulunması...' ve m.26/3: '...güneşin doğuşundan batışına kadarki zaman içinde olmak kaydıyla ses yükselten veya ileten herhangi bir alet veya araç ile çağrı yapılabilir.'","kaynak":"2911 m.26","zorluk":"orta"},
    {"id":"2911-S-025","soru":"2911 sayılı Kanun'a göre halkı Kanuna aykırı toplantı veya yürüyüşe özendiren veya kışkırtan hareketler tespit edildiğinde ne yapılır?","siklar":["Cumhuriyet savcılığınca soruşturma başlatılır, hareketlere anında müdahale edilmez","Bu hareketler güvenlik kuvvetlerince derhal menedilir","Mahallin en büyük mülki amirinin yazılı emri beklenir, hemen müdahale edilmez","Yalnızca düzenleme kurulu bu hareketleri önleyebilir","Bu hareketler yasak değildir, yalnızca izlenir"],"dogru":1,"aciklama":"m.27: 'Halka karşı, ... halkı Kanuna aykırı toplantı veya yürüyüşe özendirmek veya kışkırtmak yasaktır. Bu hareketler güvenlik kuvvetlerince derhal menedilir.' Müdahale ayrı bir bildirim/karar süreci beklenmeden anında yapılır.","kaynak":"2911 m.27","zorluk":"kolay"},
    {"id":"2911-S-026","soru":"2911 sayılı Kanun'un 2 nci maddesine göre aşağıdakilerden hangisi 'mahallin güvenlik amirleri' tanımı kapsamında SAYILMAMIŞTIR?","siklar":["İl jandarma komutanı","Sahil Güvenlik Genel Müdürü","İlçe jandarma komutanı","Sahil Güvenlik Bölge Komutanı","İl emniyet müdürü"],"dogru":1,"aciklama":"m.2/d: 'Mahallin güvenlik amirleri; illerde il emniyet müdürü ve il jandarma komutanını, ilçelerde ilçe emniyet amiri veya komiseri ve ilçe jandarma komutanını, Sahil Güvenlik Komutanlığı için Sahil Güvenlik Bölge Komutanını, Sahil Güvenlik Grup Komutanını ve Sahil Güvenlik Karakol Komutanı ile Sahil Güvenlik Gemi/Bot Komutanını, ifade eder.' Listede 'Sahil Güvenlik Genel Müdürü' hiç geçmez.","kaynak":"2911 m.2","zorluk":"zor"},
    {"id":"2911-S-027","soru":"2911 sayılı Kanun'a göre herkesin önceden izin almaksızın toplantı ve gösteri yürüyüşü düzenleme hakkı, bu eylemin hangi iki niteliği taşımasına bağlıdır?","siklar":["İzinli ve bildirimli olma","Örgütlü ve programlı olma","Silahsız ve saldırısız olma","Yazılı ve imzalı olma","Kayıtlı ve belgeli olma"],"dogru":2,"aciklama":"m.3/1: 'Herkes, önceden izin almaksızın, bu Kanun hükümlerine göre silahsız ve saldırısız olarak kanunların suç saymadığı belirli amaçlarla toplantı ve gösteri yürüyüşü düzenleme hakkına sahiptir.'","kaynak":"2911 m.3","zorluk":"kolay"},
    {"id":"2911-S-028","soru":"2911 sayılı Kanun'a göre Cumhurbaşkanı yardımcıları ve bakanların Devlet işleri hakkındaki toplantı ve konuşmaları bu Kanun hükümlerine tabidir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/d: 'Cumhurbaşkanı, Cumhurbaşkanı yardımcıları ve bakanların Devlet (…) işleri hakkındaki toplantı ve konuşmaları ile Türkiye Büyük Millet Meclisi üyelerinin halk ile yapacakları sohbet niteliğindeki görüşmeler' bu Kanun hükümlerine TABİ DEĞİLDİR; m.4'te sayılan istisnalardandır.","kaynak":"2911 m.4","zorluk":"orta"},
    {"id":"2911-S-029","soru":"2911 sayılı Kanun'a göre bir il veya ilçede birden fazla toplantı ve gösteri yürüyüşü yer ve güzergâhı belirlenmişse, bunlardan birini tercih etme yetkisi kime aittir?","siklar":["Mahallin en büyük mülki amiri","Mahallin güvenlik amirleri","İçişleri Bakanlığı","Düzenleme kurulu","Belediye başkanı"],"dogru":3,"aciklama":"m.6 son fıkra: 'Birden fazla toplantı ve gösteri yürüyüşü yer ve güzergâhının belirlendiği il ve ilçelerde düzenleme kurulu, kamu düzenini ve genel asayişi bozmayacak (…) belirlenen yer ve güzergâhlardan birisini tercih edebilir.'","kaynak":"2911 m.6","zorluk":"orta"},
    {"id":"2911-S-030","soru":"2911 sayılı Kanun'a göre düzenleme kurulunun başkan dahil en az yedi kişiyi toplantı yerinde bulundurma yükümlülüğünü yerine getirdiğine dair tutulan tutanak, kurul tarafından hazırlanarak ....... teslim edilir.","siklar":["yetkili kolluk amirine","mahallin en büyük mülki amirine","İçişleri Bakanlığına","valilik ve kaymakamlığa","mahallin güvenlik amirlerine"],"dogru":0,"aciklama":"m.11/1: 'Bu yükümlülüğün yerine getirildiğine dair tutulan tutanak, düzenleme kurulu tarafından hazırlanarak yetkili kolluk amirine teslim edilir.'","kaynak":"2911 m.11","zorluk":"orta"},
    {"id":"2911-S-031","soru":"2911 sayılı Kanun'a göre kolluk, toplantıya katılanların ve konuşmacıların ses ve görüntülerini, katılımcılar fark etmeden gizlice kaydedebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.11 ek fıkra: 'Toplantı ve gösteri yürüyüşlerinde katılımcıların ve konuşmacıların ses ve görüntüleri kolluk tarafından yapıldığı belli olacak şekilde kaydedilebilir.' Kayıt gizli değil, açıkça yapıldığı BELLİ OLACAK şekilde yapılmalıdır.","kaynak":"2911 m.11","zorluk":"zor"},
    {"id":"2911-S-032","soru":"2911 sayılı Kanun'a göre düzenleme kurulunun sorumluluğu ne zamana kadar sürer?","siklar":["Bildirimde belirtilen bitiş saatine kadar","Tutanağın kolluk amirine tesliminden itibaren 24 saat","Dağılma kararının alınmasına kadar","Güvenlik kuvvetlerinin olay yerinden ayrılmasına kadar","Topluluk toplantı yerinden tamamen dağılıncaya kadar"],"dogru":4,"aciklama":"m.12 son fıkra: 'Düzenleme kurulunun sorumluluğu, topluluk toplantı yerinden tamamen dağılıncaya kadar sürer.'","kaynak":"2911 m.12","zorluk":"orta"},
    {"id":"2911-S-033","soru":"2911 sayılı Kanun'a göre genel meydanlarda toplantı yapılabilir; ancak halkın ve ulaşım araçlarının gelip geçmesini sağlamak üzere valilik ve kaymakamlıklarca yapılacak düzenlemelere uyulması zorunludur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.22 son fıkra: 'Genel meydanlardaki toplantılarda, halkın ve ulaşım araçlarının gelip geçmesini sağlamak üzere valilik ve kaymakamlıklarca yapılacak düzenlemelere uyulması zorunludur.'","kaynak":"2911 m.22","zorluk":"kolay"},
    {"id":"2911-S-034","soru":"2911 sayılı Kanun'un 23 üncü maddesine göre aşağıdakilerden hangisi bir toplantı veya gösteri yürüyüşünün Kanuna aykırı sayılması sebeplerinden biri DEĞİLDİR?","siklar":["Toplantının basın yayın organlarınca canlı olarak yayınlanması","Toplantının, 14, 15, 16, 17 ve 19 uncu maddelere dayanılarak yasaklanması veya ertelenmesi hâlinde tespit edilen sürenin sona ermeden yapılması","Ateşli silah veya patlayıcı madde taşınarak katılım sağlanması","Bildirimde belirtilen amaç dışına çıkılması","12 nci madde gereğince toplantının dağılmasına karar verilmesi hâli"],"dogru":0,"aciklama":"m.23/i: '...14, 15, 16, 17 ve 19 uncu maddelere dayanılarak yasaklanması veya ertelenmesi halinde tespit edilen erteleme veya yasaklama süresi sona ermeden...' (B), m.23/b (C), m.23/h (D) ve m.23/j (E) madde metninde birebir sayılan sebeplerdir. 'Basın yayın organlarınca canlı yayınlanma' madde metninde hiç geçmez, bir aykırılık sebebi olarak SAYILMAMIŞTIR.","kaynak":"2911 m.23","zorluk":"zor"},
    {"id":"2911-S-035","soru":"2911 sayılı Kanun'a göre 23 üncü maddenin (b) bendinde yazılı silah, araç, alet veya maddeler ya da yasaklı sloganlarla toplantıya katılanların bulunması hâlinde, kural olarak ne yapılır?","siklar":["Toplantının tamamı derhal dağıtılır","Düzenleme kurulu bu kişileri kendi imkânlarıyla dışarı çıkarmak zorundadır","Bu kişiler güvenlik kuvvetlerince uzaklaştırılır ve toplantıya devam edilir","Mahallin en büyük mülki amiri toplantıyı derhal yasaklar","Bu kişiler yalnızca tutanakla tespit edilir, başka işlem yapılmaz"],"dogru":2,"aciklama":"m.24: 'Toplantı ve gösteri yürüyüşüne 23 üncü madde (b) bendinde yazılı silah, araç, alet veya maddeler veya sloganlarla katılanların bulunması halinde bunlar güvenlik kuvvetlerince uzaklaştırılarak toplantı ve gösteri yürüyüşüne devam edilir. Ancak, bunların sayıları ve davranışları toplantı veya gösteri yürüyüşünü Kanuna aykırı addedilerek dağıtılmasını gerektirecek derecede ise yukarıdaki fıkra hükümleri uygulanır.'","kaynak":"2911 m.24","zorluk":"orta"},
    {"id":"2911-S-036","soru":"2911 sayılı Kanun'a göre kapalı yer toplantılarında ses yükseltici alet veya araçlarla dışarıya yayın yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.26 son fıkra: 'Kapalı yer toplantılarında, ses yükseltici alet veya araçlarla dışarıya yayın yapılamaz.'","kaynak":"2911 m.26","zorluk":"kolay"},
    {"id":"2911-S-037","soru":"2911 sayılı Kanun'un 27 nci maddesine göre halkı Kanuna aykırı toplantı veya yürüyüşe kışkırtma yasağı kapsamında sayılan yöntemlerden hangisi madde metninde YER ALMAZ?","siklar":["Doğrudan doğruya söz söyleyerek","Ses yükselten veya ileten alet ile seslenerek","Basılı veya elle yazılmış kağıtları duvarlara yapıştırarak","Bu kağıtları dağıtarak","Sosyal medya hesabından paylaşım yaparak"],"dogru":4,"aciklama":"m.27: 'Halka karşı, doğrudan doğruya veya ses yükselten veya ileten herhangi bir alet veya araç ile söz söyleyerek veya seslenerek veya basılmış veya çoğaltılmış veya elle yazılmış veya çizilmiş kağıtları duvarlara veya diğer yerlere yapıştırarak veya dağıtarak veya benzeri araç ve yollarla halkı Kanuna aykırı toplantı veya yürüyüşe özendirmek veya kışkırtmak yasaktır.' Madde metni bu klasik yöntemleri sayar; 'sosyal medya hesabından paylaşım' ibaresi hiç geçmez.","kaynak":"2911 m.27","zorluk":"kolay"},
  ],
  29: [
    {"id":"4915-S-001","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre Merkez Av Komisyonu kaç üyeden teşekkül eder?","siklar":["15","20","30","35","25"],"dogru":4,"aciklama":"m.3: '...özel avlak veya örnek avlak temsilcisi bir olmak üzere toplam yirmibeş üyeden teşekkül eden Merkez Av Komisyonu kurulur.' Merkez Av Komisyonu 25 üyeden oluşur.","kaynak":"4915 m.3","zorluk":"kolay"},
    {"id":"4915-S-002","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre, Bakanlıkça belirlenen av hayvanlarından korunması gereken türleri koruma altına alma kararını hangi makam verir?","siklar":["Merkez Av Komisyonu","Bakanlık","Genel Müdürlük","İl av komisyonu","Cumhurbaşkanı"],"dogru":0,"aciklama":"m.4: 'Bakanlıkça belirlenen av hayvanlarından, korunması gerekenler Merkez Av Komisyonunca, av hayvanlarının dışında kalan yaban hayvanları ile diğer türler ... Bakanlıkça koruma altına alınır.' Av hayvanları için karar Merkez Av Komisyonuna aittir.","kaynak":"4915 m.4","zorluk":"zor"},
    {"id":"4915-S-003","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre özel avlaklar ile örnek avlaklarda avlanma sürelerini, av miktarlarını ve avlanma günlerini tespit etmeye hangi makam yetkilidir?","siklar":["Merkez Av Komisyonu","İl av komisyonu","Bakanlık","Genel Müdürlük","Vali"],"dogru":3,"aciklama":"m.5: '...il av komisyonlarının görüş ve önerileri doğrultusunda Merkez Av Komisyonu, özel avlaklar ile örnek avlaklarda ise Genel Müdürlük yetkilidir.' Özel ve örnek avlaklarda yetki Genel Müdürlüktedir.","kaynak":"4915 m.5","zorluk":"orta"},
    {"id":"4915-S-004","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre aşağıdakilerden hangisi avda kullanılması yasak olan araç ve gereçlerden biri değildir?","siklar":["Zehir","Haznesi iki fişekle sınırlandırılmış yivsiz av tüfeği","Havalı tüfek ve tabancalar","Haznesi sınırlandırılmamış otomatik, yarı otomatik, pompalı ve benzeri yivsiz av tüfekleri","Tuzak ve kapanlar"],"dogru":1,"aciklama":"m.6: 'Zehirle avlanmak yasaktır. Haznesi iki fişek alacak şekilde sınırlandırılmamış otomatik, yarı otomatik, pompalı ve benzeri yivsiz av tüfekleri ile havalı tüfek ve tabancalar avda kullanılamaz. ... tuzak, kapan ve diğer benzeri araç, gereç ve usullerle avlanılamaz.' Haznesi İKİ FİŞEKLE SINIRLANDIRILMIŞ tüfek yasak kapsamı dışındadır; kullanılabilir.","kaynak":"4915 m.6","zorluk":"orta"},
    {"id":"4915-S-005","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre Devlet avlakları, genel avlaklar ve örnek avlaklarda avlanmak hangi makamın iznine bağlıdır?","siklar":["Avlak sahibinin","Merkez Av Komisyonunun","Valinin","Bakanlığın","Genel Müdürlüğün"],"dogru":4,"aciklama":"m.12: 'Özel avlaklarda avlanmak avlak sahibinin, Devlet avlakları, genel avlaklar ve örnek avlaklarda avlanmak Genel Müdürlüğün iznine bağlıdır.'","kaynak":"4915 m.12","zorluk":"orta"},
    {"id":"4915-S-006","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre avcılık belgesi Türk vatandaşlarına ....(1).... olmak üzere verilir ve her yıl vize edilir; avcılık belgesi sahibi avcıların aldığı avlanma izni ise ....(2).... içindir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki defaya mahsus - bir av yılı","bir defaya mahsus - iki av yılı","bir defaya mahsus - bir av yılı","süresiz - bir av yılı","bir defaya mahsus - beş av yılı"],"dogru":2,"aciklama":"m.13: 'Avcılık belgesi, Türk vatandaşlarına bir defaya mahsus olmak üzere verilir ve her yıl vize edilir.' m.14: 'Avlanma izni bir av yılı içindir.'","kaynak":"4915 m.13-14","zorluk":"orta"},
    {"id":"4915-S-007","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre Türkiye'de av turu, fotoğraf ve film çekimi ile av ve yaban hayvanları gözlem turu yaptıracak seyahat acenteleri hangi belgeyi almak zorundadır?","siklar":["Avcılık belgesi","Av turizmi izin belgesi","Geçici avcılık belgesi","Yabancı avcılık belgesi","Avlanma izni"],"dogru":1,"aciklama":"m.15: 'Türkiye'de av turları, fotoğraf ve film çekimleri ile av ve yaban hayvanları gözlem turları yaptıracak seyahat acenteleri, Genel Müdürlükten av turizmi izin belgesini almaya ... mecburdurlar.'","kaynak":"4915 m.15","zorluk":"orta"},
    {"id":"4915-S-008","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre avcı turistler, beraberlerinde ok-yay ile yivli ve yivsiz av tüfeklerini ve bunlara ait mermileri Türkiye'ye getirebilirler.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16: 'Avcı turistler, beraberlerinde ok-yay ile yivli ve yivsiz av tüfeklerini ve bunlara ait mermileri getirebilirler.' (6136 ve 2521 sayılı Kanun hükümleri saklıdır.)","kaynak":"4915 m.16","zorluk":"kolay"},
    {"id":"4915-S-009","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre avcı turistler, avladıkları ve geçici avcılık belgelerine kayıtlı av hayvanlarının etlerini ve hatıra değeri taşıyan parçalarını yurt dışına nasıl çıkarabilir?","siklar":["Valilikten ayrıca izin alarak","Genel Müdürlükten ayrı bir ihraç izni alarak","Yalnızca gümrük vergisi ödeyerek","Uluslararası sözleşme taahhütleri saklı kalmak kaydıyla başka bir izne bağlı olmadan","Sadece seyahat acentesi aracılığıyla"],"dogru":3,"aciklama":"m.17: '...Türkiye'nin taraf olduğu uluslararası sözleşmelerdeki taahhütlerini dikkate almak kaydıyla başka bir izne bağlı olmadan yurt dışına beraberlerinde çıkarabilirler, adreslerine gönderebilirler veya göndertebilirler.'","kaynak":"4915 m.17","zorluk":"orta"},
    {"id":"4915-S-010","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre uluslararası sözleşmelerle ticareti yasaklanan veya 6 ncı maddeye aykırı avlanan yaban hayvanları ile bunların parçaları hakkında aşağıdakilerden hangisi söylenemez?","siklar":["Yasal olarak avlanan hayvanların ticareti Genel Müdürlükçe hiçbir şekilde sınırlandırılamaz","Satılamaz","Satın alınamaz","Nakledilemez","İthalatı ve ihracatı yapılamaz"],"dogru":0,"aciklama":"m.18: yasaklı/aykırı avlanan hayvanlar 'satılamaz, satın alınamaz, nakledilemez ve bunların ithalatı ve ihracatı yapılamaz.' Ayrıca m.18/2 uyarınca yasal olarak avlanan hayvanların ticaretini 'denetlemeye ve kısmen veya tamamen yasaklamaya ... Genel Müdürlük yetkilidir.' Yasal ticaret de Genel Müdürlükçe sınırlandırılabilir; 'hiçbir şekilde sınırlandırılamaz' ifadesi yanlıştır.","kaynak":"4915 m.18","zorluk":"orta"},
    {"id":"4915-S-011","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre elkonulan ve bulundurulması suç oluşturan silahlar nereye intikal ettirilir?","siklar":["Valiliğe","Genel Müdürlük merkez teşkilatına","Cumhuriyet başsavcılığına","İl jandarma komutanlığına","Orman Genel Müdürlüğüne"],"dogru":2,"aciklama":"m.20: 'Elkonulan ve bulundurulması suç oluşturan silâhlar soruşturma evrakı ile birlikte Cumhuriyet başsavcılığına intikal ettirilir.'","kaynak":"4915 m.20","zorluk":"orta"},
    {"id":"4915-S-012","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre fahri av müfettişleri, düzenledikleri tutanağı en geç ....(1).... içinde en yakın Genel Müdürlük taşra birimine teslim etmek zorundadır. Boşluğa gelmesi gereken süre hangisidir?","siklar":["üç gün","onbeş gün","bir ay","bir hafta","iki ay"],"dogru":3,"aciklama":"m.20: '...Genel Müdürlükçe kendilerine verilen tutanağı düzenleyerek en geç bir hafta içinde en yakın Genel Müdürlük taşra birimine teslim etmek mecburiyetindedir.'","kaynak":"4915 m.20","zorluk":"orta"},
    {"id":"4915-S-013","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre av ve yaban hayvanlarının beslendikleri ve barındıkları ortamı zehirleyenlere verilecek ceza aşağıdakilerden hangisidir?","siklar":["İki yıldan beş yıla kadar hapis","Bir yıldan üç yıla kadar hapis","Sadece onbin Türk Lirası idari para cezası","Üç aydan bir yıla kadar hapis","Beş yıldan on yıla kadar hapis"],"dogru":0,"aciklama":"m.21: '...av ve yaban hayvanlarının beslendikleri ve barındıkları ortamı zehirleyenler, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. Ayrıca, faillerin avcılık belgesi iptal edilir ve kendilerine bir daha belge verilmez.'","kaynak":"4915 m.21","zorluk":"orta"},
    {"id":"4915-S-014","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre özel avlakların kuruluş amaçları dışında işletildiğinin tespiti halinde avlak sahibine veya işletene verilecek idari para cezası tutarı aşağıdakilerden hangisidir?","siklar":["500 TL","3.000 TL","10.000 TL","1.200 TL","15.000 TL"],"dogru":3,"aciklama":"m.22: '...özel avlakların kuruluş amaçları dışında işletildiğinin tespiti halinde, avlak sahibine veya bu avlakları kiralamak sureti ile işletenlere, binikiyüz Türk Lirası idarî para cezası verilir.'","kaynak":"4915 m.22","zorluk":"kolay"},
    {"id":"4915-S-015","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre Merkez Av Komisyonunca avlanmanın yasaklandığı avlaklarda avlananlara ....(1)...., özel kanunlarla avlanmanın yasaklandığı sahalar ile 2 nci maddenin 11, 12 ve 13 üncü bentlerinde tanımlanan saha ve istasyonlarda avlananlara ise ....(2).... idarî para cezası verilir. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["15.000 TL - 10.000 TL","5.000 TL - 10.000 TL","10.000 TL - 15.000 TL","10.000 TL - 20.000 TL","20.000 TL - 15.000 TL"],"dogru":2,"aciklama":"m.23: '...avlananlara onbin Türk Lirası, ...saha ve istasyonlarda avlananlara, onbeşbin Türk Lirası idarî para cezası verilir.'","kaynak":"4915 m.23","zorluk":"orta"},
    {"id":"4915-S-016","soru":"4915 sayılı Kara Avcılığı Kanunu'nun 24 üncü maddesine göre aşağıdakilerden hangisi bu madde kapsamında idarî para cezası ile değil, hapis cezası ile cezalandırılan bir fiildir?","siklar":["Avcılık belgesi almadan avlanmak","Avlanma izni olmadan avlanmak","Avcılık belgesini yanında taşımadan avlanmak","Yabancı veya geçici avcılık belgesi almadan avlanmak","Zehirle avlanmak"],"dogru":4,"aciklama":"m.24: 'Zehirle avlananlar, bir yıldan üç yıla kadar hapis ve elli günden az olmamak üzere adlî para cezası ile cezalandırılır... alınması gereken avcılık belgesini almadan avlananlara onbin Türk Lirası; avlanma izni olmadan ... beşbin Türk Lirası; yabancı avcılık belgesi veya geçici avcılık belgesi almadan avlananlara bin Türk Lirası; belgeyi ve avlanma izin belgesini yanında taşımadan avlananlara yirmi Türk Lirası idarî para cezası verilir.' Zehirle avlanma tek başına hapis+adlî para gerektiren SUÇtur; diğerleri idari para cezası gerektiren KABAHATtir.","kaynak":"4915 m.24","zorluk":"zor"},
    {"id":"4915-S-017","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre av turizmi izin belgesi almadan av turu, fotoğraf ve film çekimi ya da av ve yaban hayvanları gözlem turu yaptıran veya yabancıların geçici avcılık belgesi olmadan avlanmasına aracılık eden kişi, kuruluş ve acentelere verilecek idari para cezası tutarı aşağıdakilerden hangisidir?","siklar":["1.200 TL","10.000 TL","3.000 TL","5.000 TL","15.000 TL"],"dogru":1,"aciklama":"m.25: 'Av turizmi izin belgesi almadan av turu, fotoğraf ve film çekimleri ile av ve yaban hayvanları gözlem turları yaptıran veya yabancıların geçici avcılık belgesi olmadan avlanmasına aracılık eden kişi, kuruluş ve acentelere onbin Türk Lirası ... idarî para cezası verilir.'","kaynak":"4915 m.25","zorluk":"orta"},
    {"id":"4915-S-018","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre 18 inci maddenin üçüncü fıkrasında belirtilen yasağa (uluslararası sözleşme çerçevesinde ithaline izin verilen yaban hayvanlarının sergi/gösteri amaçlı satışı) uymayanlara verilecek idari para cezası tutarı aşağıdakilerden hangisidir?","siklar":["500-2.500 TL","1.200 TL","10.000 TL","15.000 TL","3.000 TL"],"dogru":4,"aciklama":"m.26: '18 inci maddenin üçüncü fıkrasında belirtilen yasağa uymayanlara üçbin Türk Lirası idarî para cezası verilir.' (18/1-2 ve 19. maddeye aykırılıkta ise 500-2.500 TL aralığı uygulanır.)","kaynak":"4915 m.26","zorluk":"orta"},
    {"id":"4915-S-019","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre 20 nci madde kapsamında elkonulan av hayvanları, türevleri ve sair eşyanın mülkiyetinin kamuya geçirilmesine kim karar verir?","siklar":["Mahallî mülkî amir","Vali","Cumhuriyet başsavcısı","Genel Müdürlük bölge müdürü","Orman işletme şefi"],"dogru":0,"aciklama":"m.28: 'Bu Kanunun 20 nci maddesi kapsamında elkonulan av hayvanları ve türevleri ile sair eşyanın mülkiyetinin kamuya geçirilmesine mahallî mülkî amir tarafından karar verilir.'","kaynak":"4915 m.28","zorluk":"orta"},
    {"id":"4915-S-020","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre 23 üncü maddede yazılı cezalara konu fiillerin tekrarı hâlinde ayrıca uygulanacak sonuç aşağıdakilerden hangisidir?","siklar":["İdari para cezası üç katı olarak uygulanır","Avlak kuruluş izni iptal edilir","Ticaretten iki yıl süreyle men edilir","Faillerin avcılık belgeleri iptal edilir ve kendilerine iki yıl süre ile avcılık belgesi verilmez","Sadece tutanak düzenlenir"],"dogru":3,"aciklama":"m.29: '23 üncü maddede yazılı cezalara konu fiillerin tekrarı hâlinde, ayrıca faillerin avcılık belgeleri iptal edilir ve kendilerine iki yıl süre ile avcılık belgesi verilmez.'","kaynak":"4915 m.29","zorluk":"zor"},
    {"id":"4915-S-021","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre bu Kanuna göre verilecek idari para cezalarını kim(ler) verir?","siklar":["Vali","Mahallî mülkî amir","Cumhuriyet başsavcısı","İl av komisyonu başkanı","Genel Müdürlük bölge müdürü veya yetki verdiği personeli ile orman işletme şefi"],"dogru":4,"aciklama":"m.30: 'Bu Kanuna göre verilecek idarî para cezaları Genel Müdürlük bölge müdürü veya yetki verdiği personeli ile ... orman işletme şefi tarafından verilir.'","kaynak":"4915 m.30","zorluk":"kolay"},
    {"id":"4915-S-022","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre 3167 sayılı (eski) Kara Avcılığı Kanunu, 4915 sayılı Kanunun yürürlüğe girmesinden sonra da yürürlükte kalmaya devam etmiştir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.34: '3167 sayılı Kara Avcılığı Kanunu yürürlükten kaldırılmıştır.' 4915 sayılı Kanun, eski 3167 sayılı Kanunun yerine geçmiştir.","kaynak":"4915 m.34","zorluk":"kolay"},
    {"id":"4915-S-023","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre yaban hayatı koruma ve geliştirme sahaları ile üretme istasyonlarının tefrik edilmesi (ayrılması) konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Tamamı Cumhurbaşkanı tarafından tefrik edilir","Orman rejimine giren yerlerde Bakanlık, diğer yerlerde Cumhurbaşkanı tarafından tefrik edilir","Tamamı Bakanlık tarafından tefrik edilir","Tamamı Genel Müdürlük tarafından tefrik edilir","Tamamı Merkez Av Komisyonu tarafından tefrik edilir"],"dogru":1,"aciklama":"m.4 (son fıkra): 'Yaban hayatı koruma ve geliştirme sahaları ile üretme istasyonları, orman rejimine giren yerlerde Bakanlıkça, diğer yerlerde Cumhurbaşkanınca tefrik edilir.'","kaynak":"4915 m.4","zorluk":"zor"},
    {"id":"4915-S-024","soru":"4915 sayılı Kara Avcılığı Kanunu'nun 23 ve 24 üncü maddelerinde öngörülen idarî para cezası tutarlarına ilişkin aşağıdaki eşleştirmelerden hangisi yanlıştır?","siklar":["Avcılık belgesini yanında taşımadan avlanma – 20 TL","Avlanma izni olmadan avlanma – 5.000 TL","Merkez Av Komisyonunca yasaklanan avlakta avlanma – 20.000 TL","Avcılık belgesi almadan avlanma – 10.000 TL","Özel kanunla yasaklanan saha ve istasyonlarda avlanma – 15.000 TL"],"dogru":2,"aciklama":"m.23: yasaklı avlakta avlanma 'onbin Türk Lirası' (10.000 TL), saha/istasyonda 'onbeşbin Türk Lirası' (15.000 TL). m.24: belgesiz 'onbin', izinsiz 'beşbin', yanında taşımama 'yirmi Türk Lirası'. Merkez Av Komisyonunca yasaklanan avlakta avlanma cezası 20.000 TL DEĞİL, 10.000 TL'dir.","kaynak":"4915 m.23-24","zorluk":"zor"},
    {"id":"4915-S-025","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre il av komisyonu kaç üyeden teşekkül eder ve kararları hangi merci tarafından değerlendirilir?","siklar":["25 üye - Merkez Av Komisyonunda","11 üye - Merkez Av Komisyonunda","11 üye - Bakanlıkta","15 üye - İlçe av komisyonunda","9 üye - Genel Müdürlükte"],"dogru":1,"aciklama":"m.3: '...toplam onbir üyeden teşekkül eden il av komisyonu kurulur. İlçe av komisyonu kararları il av komisyonunda, il av komisyonu kararları da Merkez Av Komisyonunda değerlendirilir.' İl av komisyonu 11 üyelidir ve kararları Merkez Av Komisyonunda değerlendirilir.","kaynak":"4915 m.3","zorluk":"kolay"},
    {"id":"4915-S-026","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre koruma altında olmayan yaban hayvanlarının, avlanmanın yasaklandığı dönemde tarım alanlarına zarar verecek sayıda çoğalması veya bulaşıcı hastalık taşıması hâlinde, hazırlanacak ortak rapor doğrultusunda belli sayıda avlattırılmasına hangi makam izin verebilir?","siklar":["Merkez Av Komisyonu","Bakanlık","İl av komisyonu","Genel Müdürlük","Vali"],"dogru":3,"aciklama":"m.4: 'tarım alanları ile besi ve yaban hayvanlarına zarar verecek sayıda çoğalmaları veya bulaşıcı hastalık taşıdıklarının tespiti durumunda, ... hazırlanacak ortak rapor doğrultusunda belli sayıda yaban hayvanının ... avlattırılmasına Genel Müdürlükçe izin verilebilir.'","kaynak":"4915 m.4","zorluk":"orta"},
    {"id":"4915-S-027","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre radyo ve televizyonlar, av sezonunun başlamasından ....(1).... önce ve sona ermesinden itibaren de aynı süreyle eğitici ve uyarıcı yayın yapmak zorundadır; bu yayınların süresi yılda toplam ....(2).... az olamaz. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["onbeş gün - üç saatten","bir ay - üç saatten","onbeş gün - beş saatten","yedi gün - iki saatten","bir ay - bir saatten"],"dogru":0,"aciklama":"m.5 (son fıkra): '...av sezonunun başlamasından onbeş gün önce ve sona ermesinden itibaren de onbeş gün süreyle eğitici, uyarıcı ve tanıtıcı yayın yapmak zorundadırlar. ... Bu programların süresi yılda toplam üç saatten az olamaz.'","kaynak":"4915 m.5","zorluk":"orta"},
    {"id":"4915-S-028","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre avlanmanın yapılabilmesi için aşağıdakilerden hangisi aranan şartlardan biri değildir?","siklar":["Avcılık belgesi almak","Avlanma izni almak","Yasalarla izin verilen silah, araç ve eğitilmiş hayvan kullanmak","Avlanma plânlarına veya Merkez Av Komisyonu kararlarına uymak","Seyahat acentesinden av turizmi izin belgesi almak"],"dogru":4,"aciklama":"m.6: 'Avlanma, avcılık belgesi ve avlanma izni almak şartıyla, yasalarla izin verilen silâh, araç ve eğitilmiş hayvanlarla, avlanma plânlarına veya Merkez Av Komisyonu kararlarına göre yapılır.' Av turizmi izin belgesi (m.15) bireysel avcının değil, seyahat acentelerinin şartıdır.","kaynak":"4915 m.6","zorluk":"orta"},
    {"id":"4915-S-029","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre özel kanunlarla veya Merkez Av Komisyonunca avlanmanın yasaklandığı yerler ile koruma sahası ve istasyonlarında, av ve yaban hayvanlarının çoğaldığı ve zararlı olduğu hâllerde avlanmaya hangi makam izin verebilir?","siklar":["Merkez Av Komisyonu","Genel Müdürlük","İl av komisyonu","Vali","Bakanlık"],"dogru":4,"aciklama":"m.12: 'Buralarda, ancak av ve yaban hayvanlarının çoğaldığı ve zararlı olduğu hâllerde avlanmaya Bakanlıkça izin verilebilir.'","kaynak":"4915 m.12","zorluk":"orta"},
    {"id":"4915-S-030","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre avcılık belgesi alacak kişiler, herhangi bir eğitim veya sınava tabi tutulmaksızın belge alabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.13: 'Avcılık belgesi alacak olanlar, eğitime ve yeterlik sınavına tâbi tutulur.' Belge almak eğitim ve sınav şartına bağlıdır.","kaynak":"4915 m.13","zorluk":"kolay"},
    {"id":"4915-S-031","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre özel avlaklarda üretilip salınan türlerin avlanması için avlak sahibi veya işletenlerce ücreti karşılığı verilen iznin gelirine ilişkin aşağıdakilerden hangisi doğrudur?","siklar":["Ücretin tamamı Genel Müdürlük bütçesine aktarılır","Ücretin %10'u Döner Sermaye İşletmesine yatırılır, aksi hâlde özel avlak kuruluş izni iptal edilir","Ücretin %25'i Merkez Av Komisyonuna aktarılır","Bu izin ücretsiz olarak verilir","Ücretin yarısı il av komisyonuna yatırılır"],"dogru":1,"aciklama":"m.14: 'Özel avlaklarda üretilip salınan türlerin avlanması için gerekli izin, avlak sahibi veya işletenlerce ücreti karşılığı verilir. Bu ücretin %10'u Döner Sermaye İşletmesine yatırılır, aksi takdirde özel avlak kuruluş izni iptal edilir.'","kaynak":"4915 m.14","zorluk":"zor"},
    {"id":"4915-S-032","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre yurt içinde sergilenmek üzere veya gösteri amaçlı olarak uluslararası sözleşmeler çerçevesinde ithaline Bakanlıkça izin verilen yaban hayvanları hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Serbestçe satılabilir","Yalnızca yurt dışına satılabilir","Sadece Genel Müdürlüğe satılabilir","Satılamaz","Yalnızca özel avlak sahiplerine satılabilir"],"dogru":3,"aciklama":"m.18: 'Yurt içinde sergilenmek üzere veya gösteri amaçlı olarak uluslararası sözleşmeler çerçevesinde ithalatına Bakanlıkça izin verilen yaban hayvanları satılamaz.'","kaynak":"4915 m.18","zorluk":"orta"},
    {"id":"4915-S-033","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre aşağıdakilerden hangisi, av yasaklarına aykırı hareket edenleri avlanmadan men etmeye, haklarında tutanak düzenlemeye ve yasak eşyaya elkoymaya görevli ve yetkili kılınanlardan biri değildir?","siklar":["Fahri av müfettişi","Genel kolluk","Orman muhafaza memurları","Av ve doğa koruma memurları","Saha bekçileri"],"dogru":0,"aciklama":"m.20: 'Genel kolluk ile, av yasaklarının takibi ile görevli olan orman muhafaza memurları, av ve doğa koruma memurları ve saha bekçileri, ... men etmeye, haklarında tutanak düzenlemeye; ... elkoymaya ve bu amaçla yakalamaya görevli ve yetkilidir.' Fahri av müfettişinin görevi ayrı bir hükümle, Genel Müdürlükçe kendisine verilen tutanağı düzenleyip teslim etmekle sınırlıdır; kendisine men etme/elkoyma yetkisi tanınmamıştır.","kaynak":"4915 m.20","zorluk":"zor"},
    {"id":"4915-S-034","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre bir fahri av müfettişi, bu Kanunda belirtilen yasak fiillerden birini işlerse, hakkında sıradan bir avcıya uygulanacak ceza kadar (aynı miktarda) ceza uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.21: 'Bu Kanunda belirtilen yasak fiillerin fahri av müfettişleri tarafından işlenmesi halinde verilecek cezalar iki misli uygulanır.' Ayrıca yasak fiil işleyen veya gerçeğe aykırı tutanak düzenleyen fahri av müfettişinin belgesi iptal edilir ve kendisine bir daha bu görev verilmez.","kaynak":"4915 m.21","zorluk":"orta"},
    {"id":"4915-S-035","soru":"4915 sayılı Kara Avcılığı Kanunu'nun 24 üncü maddesinde yazılı cezaya konu fiillerin ....(1).... içinde tekrarı hâlinde, ceza ....(2).... olarak uygulanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üç yıl - iki katı","beş yıl - iki katı","beş yıl - üç katı","iki yıl - üç katı","on yıl - üç katı"],"dogru":2,"aciklama":"m.24: 'Bu maddede yazılı cezaya konu fiillerin beş yıl içinde tekrarı halinde ceza üç katı olarak uygulanır.'","kaynak":"4915 m.24","zorluk":"orta"},
    {"id":"4915-S-036","soru":"4915 sayılı Kara Avcılığı Kanunu'na göre 22 nci maddede yazılı cezaya konu fiilin (özel avlağın kuruluş amacı dışında işletilmesinin) tekrarı hâlinde ayrıca hangi sonuç uygulanır?","siklar":["Avcılık belgesi iptal edilir ve iki yıl süreyle belge verilmez","İdari para cezası üç katına çıkarılır","Ticaretten iki yıl süreyle men edilir","Sadece tutanak düzenlenir","Avlak kuruluş izni iptal edilir"],"dogru":4,"aciklama":"m.29: '22 nci maddede yazılı cezaya konu fiillerin tekrarı hâlinde ayrıca avlak kuruluş izni iptal edilir.'","kaynak":"4915 m.29","zorluk":"orta"},
  ],
  30: [
    {"id":"1380-S-001","soru":"1380 sayılı Su Ürünleri Kanunu'na göre \"su ürünleri\" tanımına ilişkin aşağıdakilerden hangisi bu tanımın kapsamı DIŞINDA tutulmuştur?","siklar":["Kara Avcılığı Kanunu şümulüne giren hayvanlar","Denizlerde bulunan bitkiler","İçsularda bulunan hayvanlar","Su ürünlerinin yumurtaları","İçsularda bulunan bitkiler"],"dogru":0,"aciklama":"m.2: 'Su ürünleri: Denizlerde ve içsularda bulunan bitkiler ile hayvanlar ve bunların yumurtalarıdır. (Kara Avcılığı Kanunu şümulüne giren hayvanlar hariç)'. Kara Avcılığı Kanunu kapsamına giren hayvanlar su ürünü tanımına girmez.","kaynak":"1380 m.2","zorluk":"kolay"},
    {"id":"1380-S-002","soru":"1380 sayılı Su Ürünleri Kanunu'na göre kazık, çit, çubuk, tel, taş veya beton gibi manialarla, sınırları değişmeyecek şekilde kurulan ve diple irtibatlı tesis aşağıdakilerden hangisidir?","siklar":["Muvakkat (yüzer) dalyan","Sabit dalyan","Dip trolü","Voli yeri","Kombine trol"],"dogru":1,"aciklama":"m.2: 'Sabit dalyan: ... kazık, çit, çubuk, tel, taş veya beton ve benzeri manialarla çevrilmek suretiyle, sınırları değişmeyecek şekilde kurulan ... diple irtibatlı tesislerdir.' Şamandıra, duba, tekneye bağlı ağlarla kurulan ise muvakkat (yüzer) dalyandır.","kaynak":"1380 m.2","zorluk":"orta"},
    {"id":"1380-S-003","soru":"1380 sayılı Su Ürünleri Kanunu'na göre orta su trolü, ....(1).... balıkların istihsaline mahsus, ....(2).... suyun ortasından veya yüzüne yakın kısımdan çekilen trol ağlarıdır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yerli - dibe temas ederek","göçmen - zemin üzerinde sürütülerek","münhasıran göçmen - dibe temas etmeksizin","münhasıran yerli - dibe temas etmeksizin","her türlü - dibe temas ederek"],"dogru":2,"aciklama":"m.2: 'Orta su trolu: Munhasıran göçmen balıkların istihsaline mahsus, dibe temas etmeksizin suyun ortasından veya yüzüne yakın kısımdan çekilen trol ağları ve bunlarla yapılan su ürünleri istihsalidir.'","kaynak":"1380 m.2","zorluk":"orta"},
    {"id":"1380-S-004","soru":"1380 sayılı Su Ürünleri Kanunu'na göre ticari amaçlı su ürünleri avcılık faaliyetinde bulunacak kişiler ile bu amaçla kullanılacak gemiler için ruhsat tezkeresi veya izin hangi makamdan alınır?","siklar":["İçişleri Bakanlığından","Valilikten","Ticaret Bakanlığından","Tarım ve Orman Bakanlığından","İlgili belediyeden"],"dogru":3,"aciklama":"m.3: 'Ticari amaçlı su ürünleri avcılık faaliyetinde bulunacak gerçek ve tüzel kişiler ile ... gemiler ve diğer su vasıtaları için Tarım ve Orman Bakanlığından ruhsat tezkeresi veya izin alınması zorunludur.'","kaynak":"1380 m.3","zorluk":"kolay"},
    {"id":"1380-S-005","soru":"1380 sayılı Su Ürünleri Kanunu'na göre ruhsat tezkeresi veya izin zorunluluğu yalnızca ticari amaçlı avcılık faaliyetinde kullanılacak gemileri kapsar; ticari amaçlı yetiştiricilik faaliyetinde kullanılacak gemiler bu zorunluluğun dışındadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3: '...ticari amaçlı su ürünleri avcılık ya da yetiştiricilik faaliyetinde kullanılacak gemiler ve diğer su vasıtaları için ... ruhsat tezkeresi veya izin alınması zorunludur.' Yetiştiricilik gemileri de kapsam içindedir.","kaynak":"1380 m.3","zorluk":"orta"},
    {"id":"1380-S-006","soru":"1380 sayılı Su Ürünleri Kanunu'na göre aşağıdakilerden hangisi, Bakanlık müsaadesi (izin) dahi aranmaksızın serbestçe yapılabilir?","siklar":["Elektrik cereyanı ile avlanma","Elektroşok ile avlanma (genel olarak)","Hava tazyiki ile avlanma","Sönmemiş kireç ile avlanma","Münhasıran denizlerde olta ile avlanan su ürününün çıkarılmasında elektroşok usulünün uygulanması"],"dogru":4,"aciklama":"m.19: '...münhasıran denizlerde olta ile avlanan su ürünlerinin denizden çıkarılmasında elektroşok usulünün uygulanması müsaadeye bağlı değildir.' Bu iş izin aranmaksızın serbestçe yapılabilir. Elektrik cereyanı, elektroşok (genel) ve hava tazyiki Bakanlık müsaadesiyle mümkündür (yani izne bağlıdır, izinsiz serbest değildir); sönmemiş kireç ise mutlak yasaktır (izinle dahi yapılamaz).","kaynak":"1380 m.19","zorluk":"orta"},
    {"id":"1380-S-007","soru":"1380 sayılı Su Ürünleri Kanunu'na göre aşağıdakilerden hangisi, Bakanlık müsaadesi ile dahi kullanılması mümkün olmayan mutlak yasak avlanma araç/maddelerinden biri DEĞİLDİR?","siklar":["Elektrik cereyanı","Bomba","Dinamit","Sönmemiş kireç","Kapsül"],"dogru":0,"aciklama":"m.19: Bomba, torpil, dinamit, kapsül ve benzeri patlayıcı maddeler, öldürücü/uyuşturucu maddeler ve sönmemiş kireç ile avlanmak mutlak yasaktır. Elektrik cereyanı ise 'Bakanlığın müsaadesi alınmaksızın' yasaktır; yani Bakanlık izniyle kullanılabilir, mutlak yasak değildir.","kaynak":"1380 m.19","zorluk":"orta"},
    {"id":"1380-S-008","soru":"1380 sayılı Su Ürünleri Kanunu'na göre içsulara ve denizlerdeki istihsal yerlerine dökülmesi yasak olan maddelerin hangileri olduğu nerede gösterilir?","siklar":["Bakanlar Kurulu kararında","Yönetmelikte","Tüzükte","Genelgede","Valilik kararında"],"dogru":1,"aciklama":"m.20: 'Hangi maddelerin dökülmesinin yasak olduğu yönetmelikte gösterilir.'","kaynak":"1380 m.20","zorluk":"kolay"},
    {"id":"1380-S-009","soru":"1380 sayılı Su Ürünleri Kanunu'na göre Türk vatandaşı olmayan kişilerin karasularında/içsularda su ürünleri avcılığı yasağının istisnaları kimlerdir?","siklar":["Yalnızca diplomatik pasaport sahipleri","Türkiye'de ikamet izni bulunan tüm yabancılar","Yabancı turistler ile Bakanlık müsaadesiyle etüt ve araştırma işlerinde çalışacak yabancılar","Yalnızca bilimsel araştırmacılar","Komşu ülke vatandaşları"],"dogru":2,"aciklama":"m.21: 'Ancak, 3 üncü maddenin 7 nci bendinde yazılı yabancı turistler ile ... Bakanlığın müsaadesi gereğince 14 üncü maddede gösterilen etüt ve araştırma işlerinde çalışacak yabancılar bu hükümden müstesnadır.'","kaynak":"1380 m.21","zorluk":"orta"},
    {"id":"1380-S-010","soru":"1380 sayılı Su Ürünleri Kanunu'na göre balık geçidi, balık asansörü ve diğer yapılara ilişkin projenin inşaat tekniği açısından kontrollüğü hangi kurum tarafından yapılır?","siklar":["Tarım ve Orman Bakanlığı","Çevre, Şehircilik ve İklim Değişikliği Bakanlığı","İlgili valilik","Devlet Su İşleri Genel Müdürlüğü","Enerji ve Tabii Kaynaklar Bakanlığı"],"dogru":3,"aciklama":"m.22: 'Bu madde kapsamındaki balık geçidi, balık asansörü ve diğer yapılara ilişkin projenin ... kontrollüğü ... inşaat tekniği açısından Devlet Su İşleri Genel Müdürlüğü tarafından yapılır veya yaptırılır.'","kaynak":"1380 m.22","zorluk":"orta"},
    {"id":"1380-S-011","soru":"1380 sayılı Su Ürünleri Kanunu'na göre yüksekliği ....(1).... metreden fazla olan su yapılarında, bilimsel araştırma ve inceleme sonucu balık geçitlerinin işlevsiz olacağının anlaşılması halinde balık geçidi dışında ....(2).... gibi tedbirler alınabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on - asansörle taşıma","on beş - yapay ortamda üretim","otuz - farklı göç yapıları","elli - yapay ortamda üretim","yirmi - farklı göç yapıları, asansörle taşıma"],"dogru":4,"aciklama":"m.22: 'Ancak yüksekliği yirmi metreden fazla olan su yapılarında ... balık geçitlerinin işlevsiz olacağının anlaşılması halinde balık geçidi dışında farklı göç yapıları, asansörle taşıma, yapay ortamda üretilip kaynağa bırakma gibi tedbirler alınabilir.'","kaynak":"1380 m.22","zorluk":"zor"},
    {"id":"1380-S-012","soru":"1380 sayılı Su Ürünleri Kanunu'nun 23 üncü maddesinin son fıkrası halen yürürlüktedir ve bu fıkra ayrı bir yaptırım rejimi öngörmektedir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Madde 23'ün son fıkrası '(Mülga son fıkra: 11/6/2010-5996/47 md.)' ile yürürlükten kaldırılmıştır; yürürlükte yalnız (a) ve (b) bentleri vardır.","kaynak":"1380 m.23","zorluk":"orta"},
    {"id":"1380-S-013","soru":"1380 sayılı Su Ürünleri Kanunu'na göre aşağıdakilerden hangisi doğru DEĞİLDİR?","siklar":["Münhasıran sünger avında kullanılan kankava da trol sayılır ve aynı şekilde yasaktır","İçsularda her çeşit trol ile su ürünleri istihsali yasaktır","Marmara Denizi'nde trol ile istihsal yasaktır","İstanbul ve Çanakkale boğazlarında trol ile istihsal yasaktır","İlmi maksatlarla yapılacak incelemelerde trol kullanılabilir"],"dogru":0,"aciklama":"m.24: 'a) İçsular, Marmara Denizi, İstanbul ve Çanakkale boğazlarında her çeşit trol ile su ürünleri istihsali yasaktır. İlmi maksatlarla yapılacak incelemelerde trol kullanılabilir. ... d) Munhasıran sünger avında kullanılan kankava troldan sayılmaz.' Kankava trol sayılmadığından bu yasağa tabi değildir.","kaynak":"1380 m.24","zorluk":"zor"},
    {"id":"1380-S-014","soru":"1380 sayılı Su Ürünleri Kanunu'na göre kaynakların korunması amacıyla su ürünlerinin yurt dışına çıkarılması ve canlı olarak yurt içine sokulması neye tabidir?","siklar":["Herhangi bir şarta tabi değildir","İzne","Yalnızca gümrük vergisine","Belediye onayına","Yalnızca ihracat beyannamesine"],"dogru":1,"aciklama":"m.25 (Ek fıkra: 7191/6): 'Kaynakların korunması amacıyla, su ürünlerinin yurt dışına çıkarılması ve canlı olarak yurt içine sokulması izne tabidir.'","kaynak":"1380 m.25","zorluk":"orta"},
    {"id":"1380-S-015","soru":"1380 sayılı Su Ürünleri Kanunu'na göre aşağıdakilerden hangisi, zabıt tutmaya, el koymaya ve idarî para cezası kesmeye yetkili kılınan görevliler arasında sayılmamıştır?","siklar":["Jandarma teşkilatı mensupları","Sahil güvenlik teşkilatı mensupları","Cumhuriyet savcısı","Gümrük teşkilatı mensupları","Emniyet ve jandarmanın bulunmadığı yerlerde köy muhtarı ve ihtiyar heyeti üyeleri"],"dogru":2,"aciklama":"m.33: '...emniyet, jandarma, sahil güvenlik, gümrük ve orman muhafaza teşkilatları mensupları, belediye zabıtası amir ve mensupları, kamu tüzel kişilerine bağlı muhafız, bekçi ve korucular ile emniyet ve jandarma teşkilatının bulunmadığı yerlerde köy muhtarı ve ihtiyar heyeti üyeleri ... zabıt varakası tutmak, ... el koymak ve ... idarî para cezalarını kesmekle vazifeli ve yetkilidirler.' Cumhuriyet savcısı bu sayımda yoktur; savcı adli mercidir.","kaynak":"1380 m.33","zorluk":"orta"},
    {"id":"1380-S-016","soru":"1380 sayılı Su Ürünleri Kanunu'na göre el konulan su ürünleri ve istihsal vasıtalarının mülkiyetinin kamuya geçirilmesine ilişkin kararlar kim tarafından verilir?","siklar":["Cumhuriyet savcısı","Tarım ve Orman Bakanı","Sulh ceza hâkimi","Vali","İl tarım ve orman müdürü"],"dogru":3,"aciklama":"m.34: 'Bu Kanunda düzenlenen mülkiyetin kamuya geçirilmesi kararları vali tarafından verilir.' (Ek Madde 3 uyarınca Vali bu yetkiyi ildeki mülki idare amirlerinden birine veya Bakanlık il müdürüne devredebilir.)","kaynak":"1380 m.34","zorluk":"kolay"},
    {"id":"1380-S-017","soru":"1380 sayılı Su Ürünleri Kanunu'na göre satışa sunulan su ürünlerinden asgari avlanılabilir ağırlıktan ve boy uzunluğundan küçük olanlar ile av yasağı döneminde avlanmış olanlar ....(1)...., ....(2).... olarak satılabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["perakende satılabilir - ihracat malı","hiç satılamaz - bilimsel malzeme","toptan satılamaz - sosyal yardım malzemesi","perakende satılamaz - inşaat malzemesi","perakende satılamaz - yem sanayi hammaddesi"],"dogru":4,"aciklama":"m.34/a: '...asgari avlanılabilir ağırlıktan ve boy uzunluğundan küçük olanlar ile av yasağı döneminde avlanmış olanlar perakende satılamaz, yem sanayi hammaddesi olarak satılabilir.'","kaynak":"1380 m.34","zorluk":"orta"},
    {"id":"1380-S-018","soru":"1380 sayılı Su Ürünleri Kanunu'na göre mülkiyeti kamuya geçirilmesine karar verilen ve satılan su ürünlerinin bedeli nereye kaydedilir?","siklar":["Genel bütçeye gelir olarak","İl özel idaresi bütçesine","Belediye bütçesine","Bakanlık döner sermayesine","Sosyal yardımlaşma fonuna"],"dogru":0,"aciklama":"m.35/a: 'Su ürünleri satılarak bedeli genel bütçeye gelir kaydedilmek üzere Hazine veznesine yatırılır.'","kaynak":"1380 m.35","zorluk":"orta"},
    {"id":"1380-S-019","soru":"1380 sayılı Su Ürünleri Kanunu'na göre kabahat konusu fiillerin tekrarı, kabahatin tespit edildiği tarihten itibaren iki yıl içinde ilk cezaya konu kabahatin tekrar işlenmesini ifade eder.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.36: 'Kabahat konusu fiillerin tekrarı, kabahatin tespit edildiği tarihten itibaren iki yıl içinde ilk cezaya konu kabahatin tekrar işlenmesini ifade eder.' İfade birebir doğrudur.","kaynak":"1380 m.36","zorluk":"orta"},
    {"id":"1380-S-020","soru":"1380 sayılı Su Ürünleri Kanunu'na göre m.36'daki idarî para cezaları, tam boyu oniki metre dahil ....(1).... metreye kadar olan gemiler için iki katı, ....(2).... metre ve daha uzun gemiler için üç katı olarak uygulanır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["yirmi - yirmi","yirmiiki - yirmiiki","otuz - otuz","onbeş - yirmi","yirmiiki - otuz"],"dogru":1,"aciklama":"m.36: 'Bu maddede yazılı idarî para cezaları, tam boyu oniki metre dahil yirmiiki metreye kadar olan gemiler için iki katı, yirmiiki metre ve daha uzun gemiler için üç katı olarak uygulanır.'","kaynak":"1380 m.36","zorluk":"orta"},
    {"id":"1380-S-021","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 19 uncu maddeye (patlayıcı ve zararlı madde ile avlanma yasağı) aykırı hareket edenlere verilecek idarî para cezası tutarı ne kadardır?","siklar":["5.000 Türk lirası","20.000 Türk lirası","10.000 Türk lirası","1.000-5.000 Türk lirası","50.000 Türk lirası"],"dogru":2,"aciklama":"m.36/g: '19 uncu maddeye aykırı hareket edenlere on bin Türk lirası idarî para cezası verilir. İstihsal edilen su ürünleri ile aykırılığa neden olan eşya, alet, edevat, teçhizata el konularak mülkiyetin kamuya geçirilmesine karar verilir.'","kaynak":"1380 m.36","zorluk":"orta"},
    {"id":"1380-S-022","soru":"1380 sayılı Su Ürünleri Kanunu'na göre m.36'daki genel 'kabahatin tekrarında idarî para cezası iki katı uygulanır' kuralının İSTİSNASI olan (kendi tekrar/katlama mekanizması bulunan) bentler arasında aşağıdakilerden hangisi YOKTUR?","siklar":["(b) bendi","(e) bendi","(f) bendi","(g) bendi","(j) bendinin ikinci paragrafı"],"dogru":3,"aciklama":"m.36: 'Bu maddede sayılan kabahat konusu fiillerin tekrarı halinde birinci fıkranın (b), (e) ve (f) bentleri ile (j) bendinin ikinci paragrafı hariç olmak üzere, idarî para cezaları iki katı olarak uygulanır.' (g) bendi (m.19 patlayıcı yasağı) bu istisna listesinde yoktur, dolayısıyla genel iki kat kuralına tabidir.","kaynak":"1380 m.36","zorluk":"zor"},
    {"id":"1380-S-023","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 36 ncı maddede yer alan idarî para cezaları kural olarak kim tarafından uygulanır?","siklar":["Cumhuriyet savcısı tarafından","Tarım ve Orman Bakanı tarafından","İl tarım ve orman müdürü tarafından","Belediye başkanı tarafından","Mahallin en büyük mülki amiri tarafından (Sahil Güvenlik'in yetki alanında Sahil Güvenlik Komutanlığınca görevlendirilen personel tarafından)"],"dogru":4,"aciklama":"Ek Madde 3: '36 ncı maddede yer alan idarî para cezaları mahallin en büyük mülki amiri ile Sahil Güvenlik Komutanlığının yetki ve sorumluluk alanlarında Sahil Güvenlik Komutanlığı tarafından görevlendirilen personel tarafından uygulanır.'","kaynak":"1380 Ek Madde 3","zorluk":"kolay"},
    {"id":"1380-S-024","soru":"1380 sayılı Su Ürünleri Kanunu'na göre idarî yaptırımlara karşı tebliğ tarihinden itibaren ....(1).... içerisinde yetkili idare mahkemesinde dava açılabilir; idarî para cezaları ise tebliğ tarihinden itibaren ....(2).... içinde ödenir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["onbeş gün - bir ay","otuz gün - iki ay","yedi gün - onbeş gün","onbeş gün - iki ay","bir ay - onbeş gün"],"dogru":0,"aciklama":"Ek Madde 3: 'İdarî yaptırımlara karşı tebliğ tarihinden itibaren onbeş gün içerisinde yetkili idare mahkemesinde dava açılabilir. Bu Kanuna göre verilen idarî para cezaları tebliğ tarihinden itibaren bir ay içinde ödenir.'","kaynak":"1380 Ek Madde 3","zorluk":"orta"},
    {"id":"1380-S-025","soru":"1380 sayılı Su Ürünleri Kanunu'na göre sırasıyla; (1) ruhsat tezkeresi/izin verme, (2) mülkiyetin kamuya geçirilmesine karar verme, (3) idarî para cezasını uygulama yetkileri hangi makamlara aittir?","siklar":["Vali - Tarım ve Orman Bakanlığı - mülki amir","Tarım ve Orman Bakanlığı - Vali - mahallin en büyük mülki amiri (Sahil Güvenlik alanında Sahil Güvenlik Komutanlığı)","Mülki amir - Tarım ve Orman Bakanlığı - Vali","Tarım ve Orman Bakanlığı - mülki amir - Vali","Vali - mülki amir - Tarım ve Orman Bakanlığı"],"dogru":1,"aciklama":"m.3 (ruhsat/izin: Bakanlık), m.34 ve Ek Madde 3 (mülkiyetin kamuya geçirilmesi: Vali), Ek Madde 3 (idarî para cezası: mahallin en büyük mülki amiri / Sahil Güvenlik alanında Sahil Güvenlik Komutanlığı) hükümlerinin birleşimidir.","kaynak":"1380 m.3, m.34, Ek Madde 3","zorluk":"zor"},
    {"id":"1380-S-026","soru":"1380 sayılı Su Ürünleri Kanunu'na göre aşağıdaki fiil çiftlerinden hangisinin iki yıl içinde tekrarı, idarî para cezasından çıkıp hapis + adli para cezası + müsadereye dönüşür?","siklar":["m.19 (patlayıcı madde) ve m.20 (sulara zararlı madde dökme) ihlalleri","m.21 (yabancı avcılığı) ve m.22 (akarsu engeli) ihlalleri","m.24/1-a kapsamında yasak alanda trolle avlanma ve m.25/3'e aykırı olarak su ürününü izinsiz yurt dışına çıkarma/canlı yurt içine sokma","m.33 (kolluk görevini engelleme) ve m.34 (el koymaya direnme) ihlalleri","m.23 (genel yasaklar) ve m.35 (kamuya geçen eşyayı satma) ihlalleri"],"dogru":2,"aciklama":"m.36/l: '...Fiilin iki yıl içinde tekrarı halinde kullanılan gemilerin sahip veya donatanlarına bir yıldan üç yıla kadar hapis ve beş bin günden on bin güne kadar adli para cezası verilir ve ... müsaderesine hükmolunur.' m.36/m (25/3 fıkrasına ilişkin kısım): 'Fiilin iki yıl içinde tekrarı halinde bu fiili işleyenlere bir yıldan üç yıla kadar hapis ve beş bin günden on bin güne kadar adli para cezası verilir ve ... müsaderesine hükmolunur.' Bu iki fiil dışındaki ihlallerde tekrar yalnız idari cezayı iki katına çıkarır.","kaynak":"1380 m.36","zorluk":"zor"},
    {"id":"1380-S-027","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 'istihsal vasıtaları' tanımı kapsamında aşağıdakilerden hangisi SAYILMAZ?","siklar":["Gemiler","Yemler","Alet ve edevat","İstihsal yerleri","Tesisler"],"dogru":3,"aciklama":"m.2: 'İstihsal vasıtaları: Su ürünlerinin istihsalinde kullanılan gemiler ile her türlü malzeme, teçhizat, alet, edevat, yemler, takım ve tesislerdir.' İstihsal yerleri ise ayrı bir tanımdır: 'Su ürünlerini istihsale elverişli olan ... su sahalarıdır' — yani bir saha/mekândır, araç/vasıta değildir.","kaynak":"1380 m.2","zorluk":"orta"},
    {"id":"1380-S-028","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 'gemi' tanımı bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Tonajı ve adı ne olursa olsun, su ürünleri araştırma, istihsal, nakil veya işleme amacıyla kullanılan her türlü yüzer vasıta gemi sayılır","Yalnızca motorlu yüzer vasıtalar gemi sayılır","Yalnızca belli bir tonajın üzerindeki yüzer vasıtalar gemi sayılır","Yalnızca ticari amaçlı avcılıkta kullanılan yüzer vasıtalar gemi sayılır","Yalnızca buharlı yüzer vasıtalar gemi sayılır"],"dogru":0,"aciklama":"m.2: 'Gemi: Tonajı ve adı ne olursa olsun, denizlerde ve içsularda su ürünleri araştırmasında, istihsalinde, naklinde, işlenmesinde kullanılan kayık, sandal, yelkenli, şat, salmavna gibi vasıtalarla buharlı veya motorlu bilümum yüzer vasıtalardır.'","kaynak":"1380 m.2","zorluk":"kolay"},
    {"id":"1380-S-029","soru":"1380 sayılı Su Ürünleri Kanunu'na göre deniz ve içsularda su ürünleri istihsaline elverişli, sahile bitişik ve sınırları belli su sahaları aşağıdaki tanımlardan hangisine karşılık gelir?","siklar":["Dalyan yeri","Mansap","Lagün","İstihsal yeri","Voli yeri"],"dogru":4,"aciklama":"m.2: 'Voli yeri: Deniz ve içsularda su ürünleri istihsaline elverişli, sahile bitişik ve sınırları belli su sahalarıdır.'","kaynak":"1380 m.2","zorluk":"kolay"},
    {"id":"1380-S-030","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 4922 sayılı Denizde Can ve Mal Koruma Hakkında Kanun hükümleri, ruhsat tezkeresi/izin zorunluluğunu düzenleyen 3 üncü madde karşısında uygulanmaz; 1380 sayılı Kanun bu Kanunun hükümlerinin önüne geçer.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3 son fıkra: '10/6/1946 tarihli ve 4922 sayılı Denizde Can ve Mal Koruma Hakkında Kanun hükümleri saklıdır.' Yani 4922 sayılı Kanun hükümleri saklı tutulmuş olup uygulanmaya devam eder; 1380 sayılı Kanun onun yerini almaz.","kaynak":"1380 m.3","zorluk":"orta"},
    {"id":"1380-S-031","soru":"1380 sayılı Su Ürünleri Kanunu'na göre elektrik cereyanı ile aydınlatma yapılması hangi şartla müsaadeye bağlı değildir?","siklar":["Yalnızca gündüz yapılması şartıyla","Yalnızca içsularda yapılması şartıyla","Tespit olunacak belli bir aydınlatma gücünü geçmemek şartıyla","Yalnızca ruhsatlı gemilerde yapılması şartıyla","Hiçbir şart aranmaksızın her durumda"],"dogru":2,"aciklama":"m.19/2. fıkra: 'Tespit olunacak belli bir aydınlatma gücünü geçmemek üzere elektrik cereyanı ile aydınlatma ve münhasıran denizlerde olta ile avlanan su ürünlerinin denizden çıkarılmasında elektroşok usulünün uygulanması müsaadeye bağlı değildir.'","kaynak":"1380 m.19","zorluk":"orta"},
    {"id":"1380-S-032","soru":"1380 sayılı Su Ürünleri Kanunu'na göre Tarım ve Orman Bakanlığının müsaadesi alınmadan akarsularda su ürünlerinin geçmesine veya yetişmesine engel olacak şekilde ağ kurulması, bent, çit ve benzeri engeller yapılması ile ilgili hüküm aşağıdakilerden hangisidir?","siklar":["Yasaktır","Serbesttir, herhangi bir izne gerek yoktur","Yalnızca içsularda yasaktır, denizlerde serbesttir","Yalnızca DSİ'nin iznine tabidir, Bakanlığın izni aranmaz","Valinin iznine tabidir"],"dogru":0,"aciklama":"m.22/1: 'Tarım ve Orman Bakanlığının müsaadesi alınmadan akarsularda su ürünlerinin geçmesine veya yetişmesine engel olacak şekilde ağlar kurulması, bent, çit ve benzeri engeller yapılması yasaktır.'","kaynak":"1380 m.22","zorluk":"kolay"},
    {"id":"1380-S-033","soru":"1380 sayılı Su Ürünleri Kanunu'na göre karasularımız dahilinde dip trolü ile su ürünleri istihsali şekli ....(1).... ile düzenlenir; bu düzenlemeye aykırı olarak dip trolü ile su ürünleri istihsali ....(2)..... Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["kanunla - serbesttir","Bakanlar Kurulu kararnamesiyle - serbesttir","tüzükle - yasaktır","ayrı bir yönetmelikle - yasaktır","genelgeyle - serbesttir"],"dogru":3,"aciklama":"m.24/b: 'Kara sularımız dahilinde dip trolu ile su ürünleri istihsali şekli ayrı bir yönetmelikle düzenlenir. Bu yönetmelik hükümlerine aykırı olarak dip trolu ile su ürünleri istihsali yasaktır.'","kaynak":"1380 m.24","zorluk":"orta"},
    {"id":"1380-S-034","soru":"1380 sayılı Su Ürünleri Kanunu'na göre el koyma, yediemin, bekletme, muhafaza, imha, sökme, nakliye gibi işlemlere ait masraflar kimden tahsil edilir?","siklar":["Genel bütçeden karşılanır","Tarım ve Orman Bakanlığı döner sermayesinden karşılanır","Valilik bütçesinden karşılanır","Sahil Güvenlik Komutanlığı bütçesinden karşılanır","Aykırılığı işleyenden, gemi sahibi veya donatandan tahsil edilir"],"dogru":4,"aciklama":"m.34: 'Bu Kanuna aykırı fiiller neticesinde, istihsal vasıtaları, su ürünleri ve diğer su vasıtalarına uygulanan el koyma, yediemin, bekletme, muhafaza, imha, sökme, nakliye ve diğer işlemlere ait masraflar aykırılığı işleyenden, gemi sahibi veya donatandan tahsil edilir.'","kaynak":"1380 m.34","zorluk":"orta"},
    {"id":"1380-S-035","soru":"1380 sayılı Su Ürünleri Kanunu'na göre el konulan, canlı olmayan ve muhafazası mümkün olmayan su ürünlerinin muayenesi için aşağıdaki görevlilerden hangisine başvurulacağı öngörülmemiştir?","siklar":["Veteriner hekim","Hükümet tabibi","Adli tabip","Belediye tabibi","Sağlık merkezi tabibi"],"dogru":2,"aciklama":"m.34/a: '...el koyma işlemini gerçekleştiren görevlilerin ihtiyaç duyması halinde en yakın Bakanlık laboratuvarında veya kamu kuruluşlarında görevli veteriner hekim, Hükümet, belediye veya sağlık merkezi tabiplerinden birine muayene ettirilir.' Adli tabip bu sayımda yer almaz.","kaynak":"1380 m.34","zorluk":"zor"},
    {"id":"1380-S-036","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 21 inci maddenin birinci fıkrasına (yabancıların avcılık yasağına) aykırı hareket edenlere verilecek idarî para cezası tutarı ne kadardır?","siklar":["10.000 Türk lirası","20.000 Türk lirası","50.000 Türk lirası","1.700 Türk lirası","5.000-100.000 Türk lirası"],"dogru":1,"aciklama":"m.36/i: '21 inci maddenin birinci fıkrasına aykırı hareket edenlere yirmi bin Türk lirası idarî para cezası verilir ve istihsal ettikleri su ürünleri ile bunların istihsalinde kullanılan istihsal vasıtalarına el konularak mülkiyetin kamuya geçirilmesine karar verilir.'","kaynak":"1380 m.36","zorluk":"kolay"},
    {"id":"1380-S-037","soru":"1380 sayılı Su Ürünleri Kanunu'na göre 25 inci maddenin üçüncü fıkrasına (izinsiz yurt dışına çıkarma/canlı yurt içine sokma) aykırı hareket edenlere ....(1).... Türk lirasından ....(2).... Türk lirasına kadar idarî para cezası verilir. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["bin - on bin","beş bin - elli bin","iki bin beş yüz - yirmi beş bin","beş bin - yüz bin","on bin - iki yüz elli bin"],"dogru":3,"aciklama":"m.36/m 2. paragraf: '25 inci maddenin üçüncü fıkrasına aykırı hareket edenlere beş bin Türk lirasından yüz bin Türk lirasına kadar idarî para cezası verilir.'","kaynak":"1380 m.36","zorluk":"zor"},
    {"id":"1380-S-038","soru":"1380 sayılı Su Ürünleri Kanunu'nun Ek Madde 3'üne göre aşağıdaki yetki devri eşleştirmelerinden hangisi DOĞRUDUR?","siklar":["Vali, idarî para cezası verme yetkisini mülki idare amirlerine devredebilir","Sahil Güvenlik Komutanlığı, mülkiyetin kamuya geçirilmesi yetkisini Bakanlık il müdürüne devredebilir","Mülki amirler, idarî para cezası verme yetkilerini 33 üncü maddede belirtilen görevlilere devredebilir","Vali, mülkiyetin kamuya geçirilmesi yetkisini Sahil Güvenlik Komutanlığına devredebilir","Mülki amirler, mülkiyetin kamuya geçirilmesi yetkisini 33 üncü maddede belirtilen görevlilere devredebilir"],"dogru":2,"aciklama":"Ek Madde 3: 'Mülki amirler idarî para cezası verme yetkilerini 33 üncü maddede belirtilen görevlilere devredebilir. Vali mülkiyetin kamuya geçirilmesi yetkisini ildeki mülki idare amirlerinden birine veya Tarım ve Orman Bakanlığı il müdürüne devredebilir.' İdari para cezası yetkisi mülki amirden m.33 görevlilerine devredilir; mülkiyet kararı yetkisi ise Vali'den mülki idare amiri/Bakanlık il müdürüne devredilir.","kaynak":"1380 Ek Madde 3","zorluk":"orta"},
  ],
  31: [
    {"id":"07-S-001","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre Kanunun uygulanmasında 'Bakan' ifadesi kimi belirtir?","siklar":["İçişleri Bakanını","Dışişleri Bakanını","Adalet Bakanını","Çalışma Bakanını","Aile Bakanını"],"dogru":0,"aciklama":"m.3/1-c: 'Bakan: İçişleri Bakanını ... ifade eder.' Kanunda 'Bakan' doğrudan İçişleri Bakanı anlamına gelir.","kaynak":"6458 m.3","zorluk":"kolay"},
    {"id":"07-S-002","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 'vize' tanımına göre, vize Türkiye'de en fazla kaç güne kadar kalma hakkı tanıyan ya da transit geçişi sağlayan izindir?","siklar":["Altmış gün","Doksan gün","Yüz yirmi gün","Otuz gün","Yüz seksen gün"],"dogru":1,"aciklama":"m.3/1-t: 'Vize: Türkiye'de en fazla doksan güne kadar kalma hakkı tanıyan ya da transit geçişi sağlayan izni ... ifade eder.' Azami süre 90 gündür.","kaynak":"6458 m.3","zorluk":"kolay"},
    {"id":"07-S-003","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre geri gönderme yasağı kapsamında hiç kimse hangi durumda bulunacağı bir yere gönderilemez?","siklar":["Ekonomik sıkıntı yaşayacağı bir yere","İklim koşullarının kötü olduğu bir yere","İşkenceye, insanlık dışı ya da onur kırıcı muameleye tabi tutulacağı veya hayatının/hürriyetinin tehdit altında bulunacağı bir yere","Dil bilmediği bir yere","Aile bağı bulunmadığı bir yere"],"dogru":2,"aciklama":"m.4: 'Bu Kanun kapsamındaki hiç kimse, işkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye tabi tutulacağı veya ırkı, dini, tabiiyeti, belli bir toplumsal gruba mensubiyeti veya siyasi fikirleri dolayısıyla hayatının veya hürriyetinin tehdit altında bulunacağı bir yere gönderilemez.'","kaynak":"6458 m.4","zorluk":"orta"},
    {"id":"07-S-004","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre Türkiye'ye giriş ve Türkiye'den çıkış ....(1).... yapılır ve bunun için geçerli pasaport ya da ....(2).... gerekir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["havalimanlarından - vize","kara sınırlarından - kimlik kartı","resmi geçitlerden - ikamet izni","sınır kapılarından - pasaport yerine geçen belge","gümrük kapılarından - transit belge"],"dogru":3,"aciklama":"m.5: 'Türkiye'ye giriş ve Türkiye'den çıkış, sınır kapılarından, geçerli pasaport veya pasaport yerine geçen belgelerle yapılır.' Giriş-çıkış yeri sınır kapısı, belge ise pasaport veya onun yerine geçen belgedir.","kaynak":"6458 m.5","zorluk":"orta"},
    {"id":"07-S-005","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre kapsamlı kontrole tabi tutulması gerekli görülen yabancı en fazla ....(1).... bekletilebilir; bu süre içinde yabancı istediği an ülkesine dönebileceği gibi süreyle sınırlı kalmaksızın ....(2).... da bekleyebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki saat - işlemlerin sonuçlanmasını","dört saat - avukatının gelmesini","altı saat - tercümanın gelmesini","sekiz saat - işlemlerin sonuçlanmasını","dört saat - işlemlerin sonuçlanmasını"],"dogru":4,"aciklama":"m.6/5: 'Kapsamlı kontrole tabi tutulması gerekli görülenler en fazla dört saat bekletilebilir. Yabancı, bu süre içerisinde her an ülkesine dönebileceği gibi dört saatlik süreyle sınırlı kalmaksızın ülkeye kabulle ilgili işlemlerin sonuçlanmasını da bekleyebilir.'","kaynak":"6458 m.6","zorluk":"zor"},
    {"id":"07-S-006","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre vize, vize muafiyeti veya ikamet izin süresinin bitiminden itibaren en az kaç gün süreli pasaportu ya da pasaport yerine geçen belgesi olmayan yabancı kabul edilemeyen yolcu kapsamına alınıp geri çevrilir?","siklar":["Altmış gün","Onbeş gün","Otuz gün","Kırkbeş gün","Doksan gün"],"dogru":0,"aciklama":"m.7/1-b: '... vize, vize muafiyeti veya ikamet izin süresinin bitiminden itibaren en az altmış gün süreli pasaportu veya pasaport yerine geçen belgesi olmayanlar' kabul edilemeyen yolcu kapsamındadır.","kaynak":"6458 m.7","zorluk":"orta"},
    {"id":"07-S-007","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre yabancılar, sınır dışı etme kararıyla hangi ülkeye ya da ülkelere gönderilebilir?","siklar":["Yalnızca menşe ülkesine","Yalnızca üçüncü bir ülkeye","Yalnızca Avrupa Birliği üyesi bir ülkeye","Yalnızca sınır komşusu bir ülkeye","Menşe ülkesine, transit gideceği ülkeye ya da üçüncü bir ülkeye"],"dogru":4,"aciklama":"m.52: 'Yabancılar, sınır dışı etme kararıyla, menşe ülkesine veya transit gideceği ülkeye ya da üçüncü bir ülkeye sınır dışı edilebilir.' Üç seçenek birlikte mümkündür, tek bir ülkeyle sınırlı değildir.","kaynak":"6458 m.52","zorluk":"kolay"},
    {"id":"07-S-008","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre sınır dışı etme kararı, Genel Müdürlüğün talimatı üzerine veya resen hangi makam tarafından alınır?","siklar":["İçişleri Bakanlığınca","Göç İdaresi Genel Müdürlüğünce","Valiliklerce","İdare mahkemesince","Kaymakamlıkça"],"dogru":2,"aciklama":"m.53/1: 'Sınır dışı etme kararı, Genel Müdürlüğün talimatı üzerine veya resen valiliklerce alınır.' Talimat Genel Müdürlükten gelebilir, ancak kararı bizzat veren makam valiliktir.","kaynak":"6458 m.53","zorluk":"orta"},
    {"id":"07-S-009","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre sınır dışı etme kararına karşı kararın tebliğinden itibaren ....(1).... içinde idare mahkemesine başvurulabilir; başvurular dosyanın tekemmülünden itibaren ....(2).... içinde sonuçlandırılır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["onbeş gün - otuz gün","beş gün - on gün","on gün - yirmi gün","yedi gün - onbeş gün","üç gün - yedi gün"],"dogru":3,"aciklama":"m.53/3: 'Yabancı ... sınır dışı etme kararına karşı, kararın tebliğinden itibaren yedi gün içinde idare mahkemesine başvurabilir. ... Başvurular dosyanın tekemmülünden ... itibaren on beş gün içinde sonuçlandırılır.' İtiraz süresi 7 gün, sonuçlandırma süresi 15 gündür.","kaynak":"6458 m.53","zorluk":"zor"},
    {"id":"07-S-010","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre idare mahkemesinin sınır dışı etme kararına ilişkin verdiği karara karşı bir üst mahkemeye başvurulabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.53/3: 'Mahkemenin bu konuda vermiş olduğu karar kesindir.' Karara karşı üst mahkemeye başvuru yolu kapalıdır.","kaynak":"6458 m.53","zorluk":"orta"},
    {"id":"07-S-011","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre aşağıdakilerden hangisi haklarında sınır dışı etme kararı alınacaklar arasında sayılmamıştır?","siklar":["Türk vatandaşıyla evli olup üç yıldan az süredir evli olanlar","Terör örgütü yöneticisi, üyesi veya destekleyicisi olanlar","Çalışma izni olmadan çalıştığı tespit edilenler","Vize veya vize muafiyeti süresini on günden fazla aşanlar","Kamu düzeni, kamu güvenliği veya kamu sağlığı açısından tehdit oluşturanlar"],"dogru":0,"aciklama":"m.54/1'de sayılan sebepler arasında terör örgütü üyeliği/destekleyiciliği (b), izinsiz çalışma (ğ), vize/ikamet süresini on günden fazla aşma (e, g) ve kamu düzeni-güvenlik-sağlık tehdidi (d) yer alır. 'Türk vatandaşıyla evlilik süresi' m.54'te bir sınır dışı sebebi olarak sayılmamıştır.","kaynak":"6458 m.54","zorluk":"orta"},
    {"id":"07-S-012","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 54 üncü madde kapsamında olsalar dahi haklarında sınır dışı etme kararı alınmayacaklardan biri aşağıdakilerden hangisidir?","siklar":["Türkçe bilmeyenler","Beş yıldan az süredir Türkiye'de bulunanlar","Öğrenim görmekte olanlar","Sosyal güvencesi olmayanlar","Ciddi sağlık sorunları, yaşı veya hamilelik durumu nedeniyle seyahat etmesi riskli görülenler"],"dogru":4,"aciklama":"m.55/1-b: '54 üncü madde kapsamında olsalar dahi ... ciddi sağlık sorunları, yaş ve hamilelik durumu nedeniyle seyahat etmesi riskli görülenler' hakkında sınır dışı etme kararı alınmaz.","kaynak":"6458 m.55","zorluk":"zor"},
    {"id":"07-S-013","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre sınır dışı etme kararı alınanlara, Türkiye'yi terk edebilmeleri için ....(1).... günden az olmamak üzere ....(2).... güne kadar süre tanınır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["yedi - onbeş","onbeş - otuz","on - yirmi","yirmi - kırk","otuz - altmış"],"dogru":1,"aciklama":"m.56/1: 'Türkiye'yi terk edebilmeleri için on beş günden az olmamak üzere otuz güne kadar süre tanınır.' Alt sınır 15 gün, üst sınır 30 gündür.","kaynak":"6458 m.56","zorluk":"orta"},
    {"id":"07-S-014","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre kaçma ve kaybolma riski bulunanlara veya sahte belge kullananlara Türkiye'yi terk etmeleri için süre tanınmaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.56/1: 'kaçma ve kaybolma riski bulunanlara, yasal giriş veya yasal çıkış kurallarını ihlal edenlere, sahte belge kullananlara ... bu süre tanınmaz.'","kaynak":"6458 m.56","zorluk":"kolay"},
    {"id":"07-S-015","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre kolluk tarafından yakalanan yabancı hakkında valiliğin yapacağı değerlendirme ve karar süresi en fazla kaç saati geçemez?","siklar":["Yirmi dört saat","Otuz altı saat","Yetmiş iki saat","Kırk sekiz saat","Doksan altı saat"],"dogru":3,"aciklama":"m.57/1: '... Değerlendirme ve karar süresi kırk sekiz saati geçemez.' Aynı süre, gözetim kararı alınanların geri gönderme merkezine götürülmesi için de geçerlidir.","kaynak":"6458 m.57","zorluk":"kolay"},
    {"id":"07-S-016","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre geri gönderme merkezlerindeki idari gözetim süresi ....(1).... geçemez; sınır dışı işlemlerinin yabancının iş birliği yapmaması nedeniyle tamamlanamaması hâlinde bu süre en fazla ....(2).... daha uzatılabilir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["üç ay - üç ay","bir yıl - altı ay","altı ay - altı ay","altı ay - bir yıl","dört ay - dört ay"],"dogru":2,"aciklama":"m.57/3: 'Geri gönderme merkezlerindeki idari gözetim süresi altı ayı geçemez. Ancak bu süre ... en fazla altı ay daha uzatılabilir.' Temel süre 6 ay, uzatma da 6 aydır.","kaynak":"6458 m.57","zorluk":"zor"},
    {"id":"07-S-017","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre idari gözetim kararına karşı kime başvurulabilir ve bu başvuru kaç gün içinde sonuçlandırılır?","siklar":["Sulh ceza hâkimine - beş gün","İdare mahkemesine - yedi gün","Ağır ceza mahkemesine - on gün","Bölge idare mahkemesine - otuz gün","Valiliğe - onbeş gün"],"dogru":0,"aciklama":"m.57/6: 'İdari gözetim altına alınan kişi ... idari gözetim kararına karşı sulh ceza hâkimine başvurabilir. ... Sulh ceza hâkimi incelemeyi beş gün içinde sonuçlandırır. Sulh ceza hâkiminin kararı kesindir.'","kaynak":"6458 m.57","zorluk":"orta"},
    {"id":"07-S-018","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre idari gözetim kararına karşı sulh ceza hâkimine yapılan başvuru, idari gözetimi durdurur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.57/6: 'Sulh ceza hâkimine başvurabilir. Başvuru idari gözetimi durdurmaz.' İtiraz, gözetimin devamına engel değildir.","kaynak":"6458 m.57","zorluk":"kolay"},
    {"id":"07-S-019","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre geri gönderme merkezleri esas olarak hangi kurum tarafından işletilir?","siklar":["Valilik tarafından","Göç İdaresi Genel Müdürlüğü tarafından","Türkiye Kızılay Derneği tarafından","Emniyet Genel Müdürlüğü tarafından","İçişleri Bakanlığı tarafından"],"dogru":4,"aciklama":"m.58/2: 'Geri gönderme merkezleri Bakanlık tarafından işletilir. Bakanlık, kamu kurum ve kuruluşları, Türkiye Kızılay Derneği veya kamu yararına çalışan derneklerle protokol yaparak bu merkezleri işlettirebilir.'","kaynak":"6458 m.58","zorluk":"kolay"},
    {"id":"07-S-020","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre aşağıdakilerden hangisi geri gönderme merkezlerinde sağlanan hizmetlerden biri değildir?","siklar":["Bedeli karşılanamayan acil ve temel sağlık hizmetlerinin ücretsiz verilmesi","Yakınlara, notere, yasal temsilciye ve avukata erişim imkânı sağlanması","Yargı yoluna başvuranlardan avukatlık ücretini karşılayamayanlara ücretsiz zorunlu avukat atanması","Vatandaşı olduğu ülke konsolosluk yetkilisi ve BMMYK görevlisiyle görüşebilme imkânı","Çocukların eğitim ve öğretimden yararlandırılmasının sağlanması"],"dogru":2,"aciklama":"m.59/1'de sayılan hizmetler arasında ücretsiz acil/temel sağlık (a), avukat-noter-yakın erişimi (b), konsolosluk/BMMYK görüşmesi (c) ve çocukların eğitimi (d) vardır. Ücretsiz avukat hizmeti ise m.57/7'de idari gözetim kararına karşı yargı yoluna başvuranlar için ayrıca düzenlenmiştir, m.59'un hizmet listesinde sayılmaz.","kaynak":"6458 m.59","zorluk":"orta"},
    {"id":"07-S-021","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre sınır dışı edilecek yabancının mevcut parası seyahat masraflarının tamamını karşılamaya yetmiyorsa, eksik kalan tutar kim tarafından karşılanır?","siklar":["Valilik tarafından","Kolluk birimi tarafından","Konsolosluk tarafından","Genel Müdürlük tarafından","Türkiye Kızılay Derneği tarafından"],"dogru":3,"aciklama":"m.60/3-c: Yabancının parası masrafın tamamını karşılamaya yetmiyorsa kalan kısım Genel Müdürlükçe karşılanır; parası hiç yoksa da masrafların tamamı yine Genel Müdürlükçe (b) karşılanır.","kaynak":"6458 m.60","zorluk":"orta"},
    {"id":"07-S-022","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre Avrupa ülkelerinde meydana gelen olaylar nedeniyle ırkı, dini, tabiiyeti, belli bir toplumsal gruba mensubiyeti veya siyasi düşünceleri yüzünden zulme uğrayacağından haklı sebeplerle korkan ve statü belirleme işlemleri sonrasında kendisine verilen statü aşağıdakilerden hangisidir?","siklar":["Şartlı mülteci","Mülteci","İkincil koruma","Geçici koruma","Vatansız kişi statüsü"],"dogru":1,"aciklama":"m.61: 'Avrupa ülkelerinde meydana gelen olaylar nedeniyle ... zulme uğrayacağından haklı sebeplerle korktuğu için ... yabancıya ... statü belirleme işlemleri sonrasında mülteci statüsü verilir.'","kaynak":"6458 m.61","zorluk":"kolay"},
    {"id":"07-S-023","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre şartlı mültecinin üçüncü ülkeye yerleştirilinceye kadar Türkiye'de kalmasına izin verilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.62: 'Avrupa ülkeleri dışında meydana gelen olaylar sebebiyle ... şartlı mülteci statüsü verilir. Üçüncü ülkeye yerleştirilinceye kadar, şartlı mültecinin Türkiye'de kalmasına izin verilir.'","kaynak":"6458 m.62","zorluk":"kolay"},
    {"id":"07-S-024","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre aşağıdakilerden hangisi ikincil koruma statüsünün verilme sebeplerinden biri değildir?","siklar":["Ölüm cezasına mahkûm olma veya ölüm cezasının infaz edilecek olması","İşkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye maruz kalma riski","Uluslararası veya ülke genelindeki silahlı çatışmada ayrım gözetmeyen şiddet nedeniyle ciddi tehdit","Irk, din, tabiiyet veya siyasi düşünce nedeniyle Avrupa ülkelerinde zulme uğrama korkusu","Menşe veya ikamet ülkesinin korumasından yararlanamama ya da bu tehdit nedeniyle yararlanmak istememe"],"dogru":3,"aciklama":"m.63/1'de ikincil koruma sebepleri ölüm cezası (a), işkence/insanlık dışı muamele (b) ve silahlı çatışmada ayrım gözetmeyen şiddet (c) ile bunların menşe/ikamet ülkesi korumasından yararlanamama koşuludur. 'Irk, din, tabiiyet, siyasi düşünce nedeniyle Avrupa'da zulüm korkusu' ise mülteci statüsünün (m.61) tanımıdır, ikincil korumaya ait değildir.","kaynak":"6458 m.63","zorluk":"zor"},
    {"id":"07-S-025","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre başvuru sahibinin, ikamet ettiği ülke yetkili makamlarınca o ülke vatandaşlarının sahip olduğu hak ve yükümlülüklere sahip olarak tanınması durumunda ne olur?","siklar":["Şartlı mülteci statüsü verilir","İkincil koruma statüsü verilir","Sınır dışı edilir","Geçici koruma sağlanır","Uluslararası korumadan hariçte tutulur"],"dogru":4,"aciklama":"m.64/1-b: 'İkamet ettiği ülke yetkili makamlarınca, o ülke vatandaşlarının sahip bulundukları hak ve yükümlülüklere sahip olarak tanınıyorsa ... uluslararası korumadan hariçte tutulur.'","kaynak":"6458 m.64","zorluk":"orta"},
    {"id":"07-S-026","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 5 inci maddeye aykırı şekilde Türkiye'ye yasa dışı giren veya Türkiye'yi yasa dışı terk eden yabancılar hakkında ....(1)....; girişleri yasaklanmış olmasına rağmen Türkiye'ye girebilmiş olanlar hakkında ....(2).... idari para cezası uygulanır. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["bin Türk Lirası - iki bin Türk Lirası","beşbin Türk Lirası - bin Türk Lirası","iki bin Türk Lirası - bin Türk Lirası","bin Türk Lirası - beşyüz Türk Lirası","üç bin Türk Lirası - bin beşyüz Türk Lirası"],"dogru":2,"aciklama":"m.102/1-a,b: 'Yasa dışı giren veya ... yasa dışı terk eden ... yabancılar hakkında iki bin Türk Lirası, ... girişleri yasaklanmış olmasına rağmen Türkiye'ye girebilmiş olanlar hakkında bin Türk Lirası ... idari para cezası uygulanır.'","kaynak":"6458 m.102","zorluk":"zor"},
    {"id":"07-S-027","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 'destekleyici' ifadesi kimi tanımlar?","siklar":["Yabancıya tercümanlık hizmeti veren kişiyi","Yabancının avukatlık masraflarını karşılayan kişiyi","Aile birliği amacıyla Türkiye'ye gelecek yabancıların masraflarını üstlenen ve ikamet izni talebinde bulunanlar tarafından başvuruya dayanak gösterilen Türk vatandaşını veya Türkiye'de yasal olarak bulunan yabancıyı","Yabancıyı işe alan işvereni","Yabancının ikamet izni başvurusunu yapan kamu görevlisini"],"dogru":2,"aciklama":"m.3/1-f: 'Destekleyici: Aile birliği amacıyla Türkiye'ye gelecek yabancıların masraflarını üstlenen ve ikamet izni talebinde bulunanlar tarafından başvuruya dayanak gösterilen Türk vatandaşını veya Türkiye'de yasal olarak bulunan yabancıyı ... ifade eder.'","kaynak":"6458 m.3","zorluk":"kolay"},
    {"id":"07-S-028","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 'refakatsiz çocuk', sorumlu bir kişinin ....(1).... bakımına alınmadığı sürece, kanunen ya da örf ve adet gereği kendisinden sorumlu bir yetişkinin ....(2).... bulunmaksızın Türkiye'ye gelen veya Türkiye'ye giriş yaptıktan sonra bu durumda kalan çocuğu ifade eder. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["etkin - refakati","hukuki - izni","resmi - onayı","sürekli - vekaleti","geçici - imzası"],"dogru":0,"aciklama":"m.3/1-m: 'Refakatsiz çocuk: Sorumlu bir kişinin etkin bakımına alınmadığı sürece, kanunen ya da örf ve adet gereği kendisinden sorumlu bir yetişkinin refakati bulunmaksızın Türkiye'ye gelen veya Türkiye'ye giriş yaptıktan sonra refakatsiz kalan çocuğu ... ifade eder.'","kaynak":"6458 m.3","zorluk":"orta"},
    {"id":"07-S-029","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre aşağıdakilerden hangisi 'özel ihtiyaç sahibi' tanımı kapsamında sayılan kişilerden biri değildir?","siklar":["Refakatsiz çocuk","Engelli","Hamile","Yükseköğrenim görmekte olan kişi","İşkenceye maruz kalmış kişi"],"dogru":3,"aciklama":"m.3/1-l: 'Özel ihtiyaç sahibi: Başvuru sahibi ile uluslararası koruma statüsü sahibi kişilerden; refakatsiz çocuk, engelli, yaşlı, hamile, beraberinde çocuğu olan yalnız anne ya da baba veya işkence, cinsel saldırı ya da diğer ciddi psikolojik, bedensel ya da cinsel şiddete maruz kalmış kişiyi ... ifade eder.' Yükseköğrenim görme durumu bu tanımda sayılmamıştır.","kaynak":"6458 m.3","zorluk":"orta"},
    {"id":"07-S-030","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre yabancının rızası saklı kalmak kaydıyla, dava açma süresi içinde veya yargı yoluna başvurulması hâlinde yargılama sonuçlanıncaya kadar yabancı sınır dışı edilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.53/3: 'Yabancının rızası saklı kalmak kaydıyla, dava açma süresi içinde veya yargı yoluna başvurulması hâlinde yargılama sonuçlanıncaya kadar yabancı sınır dışı edilmez.'","kaynak":"6458 m.53","zorluk":"zor"},
    {"id":"07-S-031","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre aşağıdakilerden hangisi haklarında sınır dışı etme kararı alınacaklar arasında sayılmamıştır?","siklar":["Geçimini meşru olmayan yollardan sağlayanlar","Gerçek dışı bilgi veya sahte belge kullananlar","İkamet izni uzatma başvurusu reddedilip on gün içinde Türkiye'den çıkış yapmayanlar","Türkiye'ye giriş yasağı bulunmasına rağmen geldiği tespit edilenler","Türkçe dil yeterlilik sınavında başarısız olanlar"],"dogru":4,"aciklama":"m.54/1'de sayılanlar arasında geçimini meşru olmayan yollardan sağlayanlar (ç), gerçek dışı bilgi/sahte belge kullananlar (c), ikamet izni uzatma reddi sonrası on gün içinde çıkmayanlar (j) ve giriş yasağına rağmen gelenler (ı) yer alır. 'Türkçe dil yeterlilik sınavında başarısızlık' m.54'te bir sınır dışı sebebi olarak sayılmamıştır.","kaynak":"6458 m.54","zorluk":"orta"},
    {"id":"07-S-032","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre 54 üncü madde kapsamında olsalar dahi haklarında sınır dışı etme kararı alınmayacak kişilerle ilgili değerlendirme usulü hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Değerlendirme yalnızca toplu olarak, kişi ayrımı yapılmaksızın yapılır","Değerlendirmeler herkes için ayrı yapılır; bu kişilerden belli bir adreste ikamet etmeleri ve bildirimde bulunmaları istenebilir","Bu kişiler hakkında hiçbir şekilde yükümlülük getirilemez","Değerlendirme yalnızca Genel Müdürlükçe yapılır, valilik bu konuda yetkisizdir","Bu kişilerin ikamet izni talebi kendiliğinden kabul edilmiş sayılır"],"dogru":1,"aciklama":"m.55/2: 'Birinci fıkra kapsamındaki değerlendirmeler, herkes için ayrı yapılır. Bu kişilerden, belli bir adreste ikamet etmeleri, istenilen şekil ve sürelerde bildirimde bulunmaları istenebilir.'","kaynak":"6458 m.55","zorluk":"orta"},
    {"id":"07-S-033","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre Türkiye'den çıkış için süre tanınan yabancılara verilen Çıkış İzin Belgesi harca tabidir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.56/2: 'Türkiye'den çıkış için süre tanınan kişilere, Çıkış İzin Belgesi verilir. Bu belge hiçbir harca tabi değildir.'","kaynak":"6458 m.56","zorluk":"kolay"},
    {"id":"07-S-034","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre idari gözetime alternatif olarak getirilebilecek yükümlülüklerin (belirli adreste ikamet, bildirimde bulunma, teminat, elektronik izleme vb.) toplam süresi en fazla kaç ayı geçemez?","siklar":["Altı ay","Oniki ay","Yirmi dört ay","Onsekiz ay","Otuz altı ay"],"dogru":2,"aciklama":"m.57/A-2: 'Yabancıya birinci fıkradaki yükümlülüklerden bir ya da birkaçının getirilmesi durumunda, bu süre yirmi dört ayı geçemez.'","kaynak":"6458 m.57/A","zorluk":"orta"},
    {"id":"07-S-035","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre göç alanında uzmanlığı bulunan sivil toplum kuruluşu temsilcileri, geri gönderme merkezlerini kimin izniyle ziyaret edebilir?","siklar":["Valiliğin izniyle","Bakanlar Kurulunun izniyle","İdare mahkemesinin izniyle","Genel Müdürlüğün izniyle","Herhangi bir izne gerek olmaksızın"],"dogru":3,"aciklama":"m.59/2: 'Göç alanında uzmanlığı bulunan ilgili sivil toplum kuruluşu temsilcileri, Genel Müdürlüğün izniyle geri gönderme merkezlerini ziyaret edebilirler.'","kaynak":"6458 m.59","zorluk":"kolay"},
    {"id":"07-S-036","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre yabancıların pasaportları veya diğer belgeleri, sınır dışı edilinceye kadar ....(1)....; sınır dışı işlemlerinde kullanılmak üzere ....(2).... paraya çevrilebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["tutulabilir - biletleri","iade edilir - araçları","imha edilir - eşyaları","noterde saklanır - malları","askıya alınır - kartları"],"dogru":0,"aciklama":"m.60/5: 'Yabancıların pasaportları veya diğer belgeleri, sınır dışı edilinceye kadar tutulabilir ve sınır dışı işlemlerinde kullanılmak üzere biletleri paraya çevrilebilir.'","kaynak":"6458 m.60","zorluk":"zor"},
    {"id":"07-S-037","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre başvuru sahibinin uluslararası korumadan hariçte tutulması, hariçte tutma nedenlerinden herhangi biri kendilerinde oluşmasa dahi aile üyelerinin de otomatik olarak hariçte tutulmasını gerektirir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.64/6: 'Başvuru sahibinin uluslararası korumadan hariçte tutulması, hariçte tutma nedenlerinden herhangi birinin diğer aile üyeleri için oluşmaması şartıyla, başvuru sahibinin aile üyelerinin de hariçte tutulmasını gerektirmez.'","kaynak":"6458 m.64","zorluk":"orta"},
    {"id":"07-S-038","soru":"6458 sayılı Yabancılar ve Uluslararası Koruma Kanunu'na göre geçerli seyahat belgesi veya ikamet izni olmayan yabancıların ülke içinde seyahat etmesine, barınmasına imkân sağlayan kişilere, tespit edilen her bir yabancı için ....(1).... idari para cezası uygulanır; bu cezaların bir takvim yılı içinde gerçek kişiler tarafından tekrarı hâlinde cezalar ....(2).... oranında artırılarak uygulanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["beşyüz Türk Lirası - iki katı","ikibin Türk Lirası - üçte bir","bin Türk Lirası - iki katı","beşyüz Türk Lirası - yarı","bin Türk Lirası - yarı"],"dogru":4,"aciklama":"m.102/2: '... tespit edilen her bir yabancı sayısınca bin Türk Lirası idari para cezası verilir.' m.102/3: 'İdari para cezası öngörülen kabahatlerin bir takvim yılı içinde gerçek kişiler tarafından tekrarı hâlinde, para cezaları yarı oranında artırılarak uygulanır.'","kaynak":"6458 m.102","zorluk":"zor"},
  ],
  32: [
    {"id":"6831-S-001","soru":"6831 sayılı Orman Kanunu'na göre aşağıdakilerden hangisi Devlet ormanlarında yasaklanan fiiller arasında sayılmamıştır?","siklar":["Yetişmiş fidanları kesmek veya sökmek","Ormanlardaki göl, gölet, baraj ve derelerde dinamit atarak avlanmak","Ticaret amacı olmaksızın kendi ihtiyacı için toprak, kum ve çakıl çıkarmak","Nakil vasıtalarıyla ormanlara hafriyat veya çöp dökmek","Orman idaresinin izniyle fidan sökmek veya dal kesmek"],"dogru":4,"aciklama":"m.14 (A-F bentleri) fidan kesme, dinamitle avlanma, kendi ihtiyacı için dahi toprak-kum-çakıl çıkarma ve hafriyat/çöp dökmeyi yasaklar. m.15'e göre ise orman idaresinin izni ile bu fiillerden bir kısmı (fidan sökme, dal kesme vb.) serbesttir; dolayısıyla 'izinle' yapılan fiil m.14'teki mutlak yasak kapsamında sayılmaz.","kaynak":"6831 m.14","zorluk":"orta"},
    {"id":"6831-S-002","soru":"6831 sayılı Orman Kanunu'na göre 14 üncü maddenin (A), (B) ve (C) bentlerinde yazılı bazı fiil ve hareketlerin (fidan sökme, dal kesme, orman hasılatı elde etme, muhtelif faydalar sağlama) yapılabilmesi hangi makamın izin ve müsaadesine bağlıdır?","siklar":["Tarım ve Orman Bakanlığının","Orman Genel Müdürlüğünün","Orman idaresinin","Mahalli mülki amirin","Cumhurbaşkanının"],"dogru":2,"aciklama":"m.15: '...orman idaresinin izin ve müsaadesine bağlıdır.' Kanun metninde açıkça 'orman idaresi' ifadesi kullanılmıştır.","kaynak":"6831 m.15","zorluk":"orta"},
    {"id":"6831-S-003","soru":"6831 sayılı Orman Kanunu'na göre Devlet ormanları içinde maden aranması ve işletilmesi ile madencilik faaliyeti için zorunlu tesis, yol, enerji, su, haberleşme ve altyapı tesislerine bedeli alınarak izin verme yetkisi hangi makamdadır?","siklar":["Tarım ve Orman Bakanlığı","Orman Genel Müdürlüğü","Çevre, Şehircilik ve İklim Değişikliği Bakanlığı","İçişleri Bakanlığı","Cumhurbaşkanlığı"],"dogru":0,"aciklama":"m.16: '...fon bedelleri hariç, bedeli alınarak Tarım ve Orman Bakanlığınca izin verilir.' Madencilik faaliyeti izni Tarım ve Orman Bakanlığına aittir.","kaynak":"6831 m.16","zorluk":"orta"},
    {"id":"6831-S-004","soru":"6831 sayılı Orman Kanunu'na göre Devlet ormanlarının işgal, açma veya kesme gibi yollarla elde edilen yerlerinde yapılan yapı ve tesisler hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Şahıslar adına tapuya tescil olunabilir ancak kullanım kısıtlanır","Mahkeme kararıyla belirli bir süre içinde yıkılır","Şahıslar adına tapuya tescil olunamaz ve hiçbir karar alınmasına lüzum kalmaksızın Orman Genel Müdürlüğü tarafından derhal yıkılır","Belediye tarafından yıkım kararı alınmasından sonra Orman Genel Müdürlüğünce yıkılır","Tarım ve Orman Bakanlığınca bedel karşılığında mülkiyeti devredilir"],"dogru":2,"aciklama":"m.17: '...şahıslar adına tapuya tescil olunamaz. Buralara doğrudan doğruya orman idaresince el konulur... hiçbir karar alınmasına lüzum kalmaksızın, Orman Genel Müdürlüğü tarafından derhal yıkılır...' Tescil yasağı ve kararsız-derhal yıkım birlikte düzenlenmiştir.","kaynak":"6831 m.17","zorluk":"zor"},
    {"id":"6831-S-005","soru":"6831 sayılı Orman Kanunu'na göre baraj, sokak hayvanları bakımevi, Devlete ait sağlık ve eğitim tesisleri gibi kamu yararı ve zaruret bulunan tesislerin Devlet ormanları üzerinde bulunması veya yapılması için verilebilecek iznin süresi en çok kaç yıldır?","siklar":["10 yıl","29 yıl","49 yıl","99 yıl","Süresiz"],"dogru":2,"aciklama":"m.17: 'Bu izin süresi kırkdokuz yılı geçemez.' Kamu yararı izninin ilk tavanı 49 yıldır.","kaynak":"6831 m.17","zorluk":"orta"},
    {"id":"6831-S-006","soru":"6831 sayılı Orman Kanunu'na göre izin amaç ve şartlarına uygun olarak faaliyet gösteren hak sahiplerinin izin süreleri, yer, bina ve tesislerin rayiç değeri üzerinden belirlenecek yıllık bedelle ....(1).... yıla kadar uzatılabilir; bu uzatılabilen tavana ulaşmadan önceki ilk izin süresi ise ....(2)....yılı geçemez. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["49 - 29","99 - 49","49 - 99","29 - 49","99 - 29"],"dogru":1,"aciklama":"m.17: 'Bu izin süresi kırkdokuz yılı geçemez... izin süreleri... doksandokuz yıla kadar uzatılabilir.' İlk tavan 49 yıl, uzatma tavanı 99 yıldır.","kaynak":"6831 m.17","zorluk":"zor"},
    {"id":"6831-S-007","soru":"6831 sayılı Orman Kanunu'na göre arkeolojik kazı, odun kömürü-terebentin-katran-sakız ocağı açılması veya balık üretim yeri kurulması gibi faaliyetler için Orman Genel Müdürlüğünce bedeli alınarak en çok kaç yıla kadar izin verilebilir ve saha tesliminden itibaren kaç yıl içinde tesisler işletmeye alınmazsa izin iptal edilir?","siklar":["49 yıl - 2 yıl","29 yıl - 1 yıl","49 yıl - 1 yıl","29 yıl - 2 yıl","20 yıl - 2 yıl"],"dogru":3,"aciklama":"m.18: '...yirmidokuz yıla kadar izin verilebilir... saha tesliminden itibaren iki yıl içinde tesislerin işletmeye alınmaması hâlinde izin iptal edilir.' Süre 29 yıl, iptal süresi 2 yıldır.","kaynak":"6831 m.18","zorluk":"orta"},
    {"id":"6831-S-008","soru":"6831 sayılı Orman Kanunu'na göre ormanlara her türlü hayvan sokulması yasak olmakla birlikte, orman idaresince belirlenen alanlarda, orman idaresince tespit edilen usul ve esaslar çerçevesinde hayvan otlatılmasına izin verilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.19: 'Ormanlara hertürlü hayvan sokulması yasaktır. Ancak, kamu yararı gereklerine uygun olarak, orman idaresince belirlenen orman alanlarında; orman idaresince tespit edilen usul ve esaslar çerçevesinde hayvan otlatılmasına izin verilebilir.' Kural yasak, istisna orman idaresi izniyledir.","kaynak":"6831 m.19","zorluk":"kolay"},
    {"id":"6831-S-009","soru":"6831 sayılı Orman Kanunu'na göre aşağıdaki alanlardan hangisinde orman idaresinin izniyle dahi hiçbir surette hayvan otlatılamaz?","siklar":["Kamu yararı gereğince belirlenmiş genel otlatma alanlarında","Devlet ormanı sınırına bitişik mera alanlarında","Orman idaresince usul ve esasları tespit edilmiş alanlarda","Yangın görmüş ormanlar ile gençleştirmeye ayrılmış veya ağaçlandırılmış sahalarda","Orman köylüsüne ait tarım arazilerinde"],"dogru":3,"aciklama":"m.19: 'Yangın görmüş ormanlarla, gençleştirmeye ayrılmış veya ağaçlandırılmış sahalarda hiç bir surette hayvan otlatılamaz.' Bu alanlarda izin dahi mümkün değildir.","kaynak":"6831 m.19","zorluk":"zor"},
    {"id":"6831-S-010","soru":"6831 sayılı Orman Kanunu'na göre taşıma belgesine uygun ve damgalı/işaretli orman emvalinde, taşıma belgesinde yazılı satış bedeli üzerinden bedeli ve bu bedelin yüzde on fazlası ödenerek serbest bırakılabilecek fazlalık, hacim ve ağırlık bakımından en çok yüzde kaça kadardır?","siklar":["Hacmen yüzde 15, ağırlığın yüzde 10'una kadar","Hacmen yüzde 10, ağırlığın yüzde 15'ine kadar","Hacmen yüzde 20, ağırlığın yüzde 10'una kadar","Hacmen yüzde 10, ağırlığın yüzde 20'sine kadar","Hacmen ve ağırlıkça yüzde 10'a kadar"],"dogru":1,"aciklama":"m.41: '...hepsi üzerinden hacmen yüzde on ve ağırlığının yüzde onbeşine kadar çıkacak fazlalık için... serbest bırakılır.' Hacim %10, ağırlık %15'tir.","kaynak":"6831 m.41","zorluk":"orta"},
    {"id":"6831-S-011","soru":"6831 sayılı Orman Kanunu'na göre nakliyatta serbest bırakılan hacim/ağırlık fazlalık haddini aşan miktar söz konusu olduğunda, yalnızca haddi aşan kısım kaçak sayılıp müsadere edilir; haddin altındaki fazlalık serbest bırakılmaya devam eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.41: 'Yukarıdaki hadleri aşan miktar, bütün fazlalığa şamil olmak üzere kaçak sayılarak idarece müsadere olunur.' Haddi aşınca yalnız aşan kısım değil, fazlalığın TAMAMI kaçak sayılıp müsadere edilir.","kaynak":"6831 m.41","zorluk":"orta"},
    {"id":"6831-S-012","soru":"6831 sayılı Orman Kanunu'na göre orman içinde emval taşıyanlar bakımından taşıma belgesi hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Taşıma belgesi yalnızca kontrol noktalarında ibraz edilir, sürekli üzerde bulundurulması gerekmez","Taşıma belgesi yerine sözlü beyan yeterlidir","Taşıma belgesi yalnızca şehir içi taşımalarda aranır","Taşıma belgesi emval taşıyanların daima üzerinde bulunur ve ilgili memurlarca istenildiğinde gösterilmesi zorunludur","Taşıma belgesi yalnızca orman idaresi araçlarında bulunur"],"dogru":3,"aciklama":"m.42: 'Taşıma belgesi emval taşıyanların daima üzerinde bulunur ve ilgili memurlar tarafından istenildiğinde gösterilmesi zorunludur.' Belge süreklidir, yalnız kontrolde değil daima üzerde olmalıdır.","kaynak":"6831 m.42","zorluk":"kolay"},
    {"id":"6831-S-013","soru":"6831 sayılı Orman Kanunu'na göre yangın ihbarına ilişkin telefon devreleri PTT İdaresinin santrali olmayan yerlerde hangi santrale bağlanabilir?","siklar":["Belediye santraline","Jandarma santraline","Valilik santraline","Orman idaresi santraline","Emniyet Genel Müdürlüğü santraline"],"dogru":1,"aciklama":"m.68: 'Telefon devreleri PTT İdaresi santrallerine ve PTT İdaresinin santrali olmıyan yerlerde jandarma santrallerine bağlanabilir.' Yedek bağlantı noktası jandarma santralidir.","kaynak":"6831 m.68","zorluk":"orta"},
    {"id":"6831-S-014","soru":"6831 sayılı Orman Kanunu'na göre ormanların içinde veya yakınında ateş ve yangın belirtisi görenlerin derhal haber vermekle yükümlü olduğu merciler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Orman idaresi","En yakın muhtarlık","Jandarma daireleri","Mülkiye amirleri","İtfaiye teşkilatı"],"dogru":4,"aciklama":"m.68: '...bunu derhal orman idaresine veya en yakın muhtarlığa, jandarma dairelerine veya mülkiye amirlerine haber vermeye mecburdurlar.' İtfaiye teşkilatı kanun metninde ayrıca sayılmamıştır.","kaynak":"6831 m.68","zorluk":"orta"},
    {"id":"6831-S-015","soru":"6831 sayılı Orman Kanunu'na göre ormanlara ....(1).... mesafede veya bu Kanunun 31 inci ve 32 nci maddeleri kapsamına giren köyler hudutları içinde anız veya benzeri bitki örtüsü yakmak yasaktır. Boşluğa gelmesi gereken mesafe hangisidir?","siklar":["Bir kilometre","İki kilometre","Dört kilometre","Beş kilometre","On kilometre"],"dogru":2,"aciklama":"m.76/d: 'Ormanlara dört kilometre mesafede veya bu Kanunun 31 inci ve 32 nci maddeleri kapsamına giren köyler hudutları içinde anız veya benzeri bitki örtüsü yakmak... Yasaktır.'","kaynak":"6831 m.76","zorluk":"orta"},
    {"id":"6831-S-016","soru":"6831 sayılı Orman Kanunu'na göre aşağıdakilerden hangisi m.76 kapsamında Devlet ormanlarında yasaklanan fiiller arasında sayılmamıştır?","siklar":["Orman idaresince belirlenen konak yerlerinden başka yerlerde gecelemek","İzin verilen yerde yakılan ateşi söndürmeden mahalli terk etmek","Ormanlara sönmemiş sigara atmak","Ormana dört kilometre mesafede anız yakmak","Orman idaresinin gösterdiği ocak yerinde izinli ateş yakmak"],"dogru":4,"aciklama":"m.76 (a-d bentleri) izinsiz konaklama, söndürülmeden terk edilen ateş, sönmemiş sigara atma ve 4 km'de anız yakmayı yasaklar. İzin verilen ve ocak yeri olarak belirlenen yerde ateş yakmak ise yasak kapsamı DIŞINDADIR; yasaklanan 'izin verilen ve ocak yeri olarak belirlenen yerler DIŞINDA' ateş yakmaktır.","kaynak":"6831 m.76","zorluk":"kolay"},
    {"id":"6831-S-017","soru":"6831 sayılı Orman Kanunu'na göre orman teşkilatında görevli memurlardan lüzum görülenlerin hangi makam tarafından seçilecek silahla teçhiz olunacağı belirlenir?","siklar":["Tarım ve Orman Bakanlığınca","Orman Genel Müdürlüğünce","İçişleri Bakanlığınca","Cumhurbaşkanınca","Mahalli mülki amirce"],"dogru":3,"aciklama":"m.77: '...lüzum görülecek olanlar, Cumhurbaşkanınca seçilecek silahla teçhiz olunurlar.' Silah seçimi Cumhurbaşkanına aittir; silahlar orman idaresince demirbaş olarak verilir.","kaynak":"6831 m.77","zorluk":"orta"},
    {"id":"6831-S-018","soru":"6831 sayılı Orman Kanunu'na göre orman memurları, bu Kanunda tanımlanan suçların işlenmesinin önlenmesi veya işlenen suçlarla ilgili soruşturmadaki görevleri kapsamında kolluk görevlisi sıfatını taşırlar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.77: 'Orman memurları, bu Kanunda tanımlanan suçların işlenmesinin önlenmesi veya işlenen suçlarla ilgili olarak başlatılan soruşturmadaki görevleri kapsamında kolluk görevlisi sıfatını taşırlar.'","kaynak":"6831 m.77","zorluk":"orta"},
    {"id":"6831-S-019","soru":"6831 sayılı Orman Kanunu'na göre 77 nci madde gereğince silah taşımaya yetkili olanlar görevlerini ifa sırasında hangi hallerde silahlarını kullanabilir?","siklar":["Hakkın kullanılması, meşru savunma veya zorunluluk hâllerinde ya da tecavüz/taarruzun başka şekilde önlenmesine imkân bulunmadığı hâllerde","Yalnızca amirin yazılı emri bulunduğunda","Her türlü şüpheli durumda önleyici tedbir olarak","Yalnızca gece saatlerinde devriye sırasında","Sadece kaçak yapı tespit edildiğinde"],"dogru":0,"aciklama":"m.78: hakkın kullanılması/meşru savunma/zorunluluk hâlleri (A bendi), teslim emrine uyulmayıp tecavüz/taarruzda bulunulması ve bunun başka türlü önlenememesi (B bendi) ile el konan mal/silahın geri alınması veya binaya zorla girme teşebbüsünün başka türlü önlenememesi (C bendi) sayılmıştır; ortak nokta 'başka şekilde önleme imkânı bulunmaması'dır, yani silah son çaredir.","kaynak":"6831 m.78","zorluk":"zor"},
    {"id":"6831-S-020","soru":"6831 sayılı Orman Kanunu'na göre orman malları ile suçların işlenmesinde kullanılan nakil vasıtası ve sair eşyaya Ceza Muhakemesi Kanunu hükümlerine göre el konulur. Cumhuriyet savcısına ulaşılamadığı hâllerde el koyma kimin yazılı emriyle yapılır?","siklar":["Vali yardımcısının","Orman işletme şefinin","İl jandarma komutanının","Sulh ceza hâkiminin","Orman Genel Müdürünün"],"dogru":1,"aciklama":"m.79: 'Ancak, Cumhuriyet savcısına ulaşılamadığı hallerde elkoyma, orman işletme şefinin yazılı emri ile yapılır.' Yedek makam orman işletme şefidir.","kaynak":"6831 m.79","zorluk":"orta"},
    {"id":"6831-S-021","soru":"6831 sayılı Orman Kanunu'na göre talep vukuunda orman memurlarına yardıma mecbur olanlar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Polis","Jandarma","Köy muhtarı","Köy bekçisi","Sulh ceza hâkimi"],"dogru":4,"aciklama":"m.79: 'Talep vukuunda polis, jandarma, köy muhtar ve bekçileri orman memurlarına yardıma mecburdurlar.' Sulh ceza hâkimi bu sayımda yer almaz; hâkim adli bir makamdır, yardım yükümlüsü değildir.","kaynak":"6831 m.79","zorluk":"orta"},
    {"id":"6831-S-022","soru":"6831 sayılı Orman Kanunu'na göre el konulan ağaç, tomruk, kereste gibi mahsullerin muhafaza edilmek üzere orman deposu bulunmadığı ve fiilin işlendiği yer köy hudutları içinde olduğu takdirde bu mallar öncelikle kime yediemin senedi karşılığında teslim edilir?","siklar":["O yer belediyesine","İl jandarma komutanlığına","O köy muhtarına","Cumhuriyet savcılığına","Orman işletme şefine"],"dogru":2,"aciklama":"m.84: 'orman deposu yoksa... köy hudutları içinde ise o köy muhtarına, yokluğunda vekiline, onun da yokluğunda ihtiyar heyeti üyelerinden birine yediemin senedi mukabilinde teslim olunur.' Köyde öncelik muhtardadır.","kaynak":"6831 m.84","zorluk":"kolay"},
    {"id":"6831-S-023","soru":"6831 sayılı Orman Kanunu'na göre bu Kanunda tanımlanan suçlardan dolayı arama Ceza Muhakemesi Kanunu hükümlerine göre yapılır. CMK m.119/1'e göre Cumhuriyet savcısına ulaşılamadığı hâllerde arama kimin yazılı emriyle yapılır?","siklar":["Orman şefinin","Orman Genel Müdürünün","Mahalli mülki amirin","İl jandarma komutanının","Sulh ceza hâkiminin"],"dogru":0,"aciklama":"m.88: '...Cumhuriyet savcısına ulaşılamadığı hâllerde, arama, orman şefinin yazılı emri ile yapılır.' El koymadaki (m.79) 'orman işletme şefi' ile aynı kademe orman şefidir.","kaynak":"6831 m.88","zorluk":"orta"},
    {"id":"6831-S-024","soru":"6831 sayılı Orman Kanunu'na göre Devlet ormanı içinde yapılacak madencilik faaliyetleri için gerekli tesislere izin verme yetkisi ile orman memurunun hangi silahla teçhiz edileceğini belirleme yetkisi sırasıyla hangi makamlara aittir?","siklar":["Orman Genel Müdürlüğü - Cumhuriyet savcısı","Tarım ve Orman Bakanlığı - Orman işletme şefi","Çevre ve Orman Bakanlığı - Orman Genel Müdürlüğü","Tarım ve Orman Bakanlığı - Cumhurbaşkanı","Cumhurbaşkanı - Tarım ve Orman Bakanlığı"],"dogru":3,"aciklama":"m.16: madencilik faaliyeti için gerekli tesislere 'Tarım ve Orman Bakanlığınca izin verilir.' m.77: orman memurunun silahla teçhizi 'Cumhurbaşkanınca' belirlenir. İki farklı yetki iki farklı makamdadır.","kaynak":"6831 m.16, m.17, m.77, m.79","zorluk":"zor"},
    {"id":"6831-S-025","soru":"6831 sayılı Orman Kanunu m.14/C bendine göre Devlet ormanlarında toplayıp götürülmesi yasaklanan ürünler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Mazı kozalağı","Palamut","Orman idaresince satışa çıkarılan işlenmiş kereste","Ihlamur çiçeği","Orman tohumları"],"dogru":2,"aciklama":"m.14/C: '...Palamut, ıhlamur çiçeği, her çeşit orman örtüsü, mazı kozalağı tıbbi ve sınai nebatları veya orman tohumlarını toplayıp götürmek... Yasaktır.' Bent, doğadan toplanan ham bitkisel/tohumsal ürünleri sayar; orman idaresince usulüne uygun satışa çıkarılmış işlenmiş kereste bu yasak kapsamında değildir.","kaynak":"6831 m.14","zorluk":"orta"},
    {"id":"6831-S-026","soru":"6831 sayılı Orman Kanunu m.16'ya göre madencilik ruhsatı veya imtiyazı almış olanlar ile alacak olanlar, işe başlamadan evvel ne yapmakla yükümlüdür?","siklar":["Tarım ve Orman Bakanlığından ayrıca yazılı muvafakat almak","Çalışma sahasını Cumhurbaşkanlığına bildirmek","İşe başlamadan önce bedelin tamamını peşin ödemek","Çalışma sahalarını orman idaresine haber vermek ve idarenin göstereceği tedbirleri almak","Orman Genel Müdürlüğünden ayrıca ruhsat almak"],"dogru":3,"aciklama":"m.16: 'Ruhsatname veya imtiyaz almış olanlarla, ruhsatname veya imtiyaz alacaklar, işe başlamadan evvel çalışma sahalarını orman idaresine haber vermeye ve ormana zarar gelebilecek hallerde, orman idaresinin göstereceği tedbirleri almaya ve yapmaya mecburdurlar.'","kaynak":"6831 m.16","zorluk":"orta"},
    {"id":"6831-S-027","soru":"6831 sayılı Orman Kanunu m.16'ya göre Devlet ormanları sınırları içindeki tohum meşcereleri, gen koruma alanları, muhafaza ormanları, verimli orman alanları, orman parkları ve endemik-nadir ekosistemlerin bulunduğu alanlarda maden aranması ve işletilmesi, Tarım ve Orman Bakanlığının ....(1).... bağlıdır. Boşluğa gelmesi gereken kelime hangisidir?","siklar":["iznine","onayına","muvafakatine","ruhsatına","kararına"],"dogru":2,"aciklama":"m.16: '...Devlet ormanları sınırları içindeki tohum meşcereleri, gen koruma alanları, muhafaza ormanları, verimli orman alanları, orman parkları, endemik ve korunması gereken nadir ekosistemlerin bulunduğu alanlarda maden aranması ve işletilmesi, Tarım ve Orman Bakanlığının muvafakatine bağlıdır.' Kanun bu hassas alanlar için özel olarak 'muvafakat' kelimesini kullanır.","kaynak":"6831 m.16","zorluk":"zor"},
    {"id":"6831-S-028","soru":"6831 sayılı Orman Kanunu m.17'nin birinci fıkrasına göre Devlet ormanları içinde aşağıdaki fiillerden hangisi yasaklanmamıştır?","siklar":["Bina yapılması","Ağıl yapılması","Tarla açılması ve ekilmesi","Otlatma planı kapsamında hayvanların gecelemesini emniyet altına alan geçici çevirmeler kurulması","Orman içinde yerleşilmesi"],"dogru":3,"aciklama":"m.17/1: '...otlatma planı yapılan alanlarda yıllık otlatma süresi dâhilinde hayvanların planlı otlatılmasını sağlayan, gecelemesini emniyet altına alan ve dağılmalarını engelleyen geçici çevirmeler şeklinde düzenlemeler dışında, her çeşit bina, ağıl ve hayvanların barınmasına mahsus yerler yapılması, tarla açılması, işlenmesi, ekilmesi ve orman içinde yerleşilmesi yasaktır.' Geçici çevirme düzenlemeleri açıkça yasağın dışında bırakılmıştır.","kaynak":"6831 m.17","zorluk":"orta"},
    {"id":"6831-S-029","soru":"6831 sayılı Orman Kanunu'na göre 31/12/2011 tarihinden önce toplu yerleşimin bulunduğu yaylak ve otlak alanları Orman Genel Müdürlüğünce tespit edilir; tespit edilen alanlardan uygun görülenler Cumhurbaşkanı kararı ile yayla alanı olarak ilan edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.17/1: '...kullanım bütünlüğü de dikkate alınarak Orman Genel Müdürlüğünce tespit edilir. Tespit edilen bu alanlardan uygun görülenler Cumhurbaşkanı kararı ile yayla alanı olarak ilan edilir.' Sıra: önce OGM tespit eder, sonra Cumhurbaşkanı ilan eder.","kaynak":"6831 m.17","zorluk":"kolay"},
    {"id":"6831-S-030","soru":"6831 sayılı Orman Kanunu'na göre yayla alanı olarak ilan edilen yerlerde kullanıcısı tespit edilen bina ve tesisler, tespit tarihinden itibaren bir yıl içinde talebi hâlinde hangi kanun hükümlerine göre ve neye göre belirlenecek bedelle kiraya verilebilir?","siklar":["2942 sayılı Kamulaştırma Kanunu hükümlerine göre, emsal bedel üzerinden","4706 sayılı Kanun hükümlerine göre, ihale bedeli üzerinden","2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanunu hükümlerine göre","İlgili yönetmelik hükümlerine göre, sabit bedel üzerinden","2886 sayılı Devlet İhale Kanunu hükümlerine göre, rayiç bedel üzerinden"],"dogru":4,"aciklama":"m.17/1: 'Kullanıcısı tespit edilen bina ve tesisler vaziyet planına göre kullanıcısına, tespit tarihinden itibaren bir yıl içinde talebi hâlinde rayiç bedel üzerinden 8/9/1983 tarihli ve 2886 sayılı Devlet İhale Kanunu hükümlerine göre kiraya verilebilir. Kullanıcıları tarafından kiralanmayan bina ve tesisler ise yıkılır.'","kaynak":"6831 m.17","zorluk":"zor"},
    {"id":"6831-S-031","soru":"6831 sayılı Orman Kanunu m.18'e göre yangın görmüş ormanlarla, gençleştirmeye ayrılmış veya ağaçlandırılan sahalarda birinci fıkradaki faaliyetlere (arkeolojik kazı, ocak açma, balık üretim yeri vb.) ....(1).... izin verilemez. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Ancak Bakanlar Kurulu kararıyla","Yalnızca acil durumlarda","Valilik onayıyla istisnaen","Hiçbir surette","Beş yıl sonra yeniden başvuru ile"],"dogru":3,"aciklama":"m.18 (son fıkra): 'Yangın görmüş ormanlarla, gençleştirmeye ayrılmış veya ağaçlandırılan sahalarda birinci fıkradaki faaliyetlere hiçbir surette izin verilemez.' Bu sahalarda OGM izni mutlak biçimde yasaklanmıştır, istisna yoktur.","kaynak":"6831 m.18","zorluk":"orta"},
    {"id":"6831-S-032","soru":"6831 sayılı Orman Kanunu m.18'e göre genel bütçe kapsamındaki kamu kurum ve kuruluşlarına bedelsiz verilen izne konu tesislerin izin sahibince üçüncü kişilere kiralanması hâlinde, orman sayılan alana isabet eden kira bedelinin yüzde kaçı Orman Genel Müdürlüğü bütçesine gelir kaydedilir?","siklar":["%10","%50","%25","%75","%100"],"dogru":1,"aciklama":"m.18: '...bedelsiz izne konu tesisler de dâhil olmak üzere tesislerin; izin sahibince üçüncü kişilere kiralanması halinde orman sayılan alana isabet eden kira bedelinin yüzde ellisi her yıl Orman Genel Müdürlüğü bütçesine gelir kaydedilmek üzere ilgili muhasebe birimi hesabına izin sahibi tarafından yatırılır.'","kaynak":"6831 m.18","zorluk":"zor"},
    {"id":"6831-S-033","soru":"6831 sayılı Orman Kanunu m.42'ye göre şehir ve kasabalardaki ticarethane ve fabrikalardan alınan orman emvali şehir içinde ....(1).... ile taşınabilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Taşıma belgesi","Damga belgesi","Orman idaresi yazısı","Gümrük belgesi","Fatura veya sevk irsaliyesi"],"dogru":4,"aciklama":"m.42 (ikinci fıkra): 'Şehir ve kasabalardaki ticarethane ve fabrikalardan alınan orman emvali şehir içinde fatura veya sevk irsaliyesi ile taşınabilir. Bu belgelerin taşıma araçlarında bulundurulması zorunludur.' Orman içi nakliyattaki 'taşıma belgesi' kuralından farklı olarak şehir içi ticari taşımada fatura/irsaliye yeterlidir.","kaynak":"6831 m.42","zorluk":"kolay"},
    {"id":"6831-S-034","soru":"6831 sayılı Orman Kanunu m.68'e göre yangın ihbarında Devlete ait her türlü askeri ve mülki haberleşme vasıtalarından ne şekilde faydalanılır?","siklar":["Yalnızca mesai saatleri içinde ücret karşılığı","Valilik onayı alındıktan sonra","Derhal ve parasız","Yalnızca orman idaresi personeli tarafından ücretli","Yalnızca acil durumlarda ücretsiz, diğer hallerde ücretli"],"dogru":2,"aciklama":"m.68 (ikinci fıkra): 'Yangın ihbarında Devlete ait her türlü askeri ve mülki haberleşme vasıtalarından derhal ve parasız olarak faydalanılır.' Kural hem zaman (derhal) hem bedel (parasız) bakımından koşulsuzdur.","kaynak":"6831 m.68","zorluk":"orta"},
    {"id":"6831-S-035","soru":"6831 sayılı Orman Kanunu'na göre Devlet ormanlarından gayrı ormanlarda çalışan orman bekçilerine silah taşıma izni hiçbir şekilde verilemez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.77 (son fıkra): 'Devlet ormanlarından gayrı ormanlarda çalışan orman bekçilerine de umumi hükümler dairesinde silah taşıma izni verilebilir.' Kanun bu izni açıkça mümkün kılmıştır; mutlak bir yasak yoktur.","kaynak":"6831 m.77","zorluk":"orta"},
    {"id":"6831-S-036","soru":"6831 sayılı Orman Kanunu m.78/C bendine göre silah kullanma hâli aşağıdakilerden hangisinde doğru tanımlanmıştır?","siklar":["Herhangi bir şüpheli durumda önleyici amaçla","Yalnızca amirin sözlü emri üzerine","Gece devriyesi sırasında herhangi bir tehdit algısında","(B) bendi gereğince teslim edilen alet/silahları veya el konan nakil vasıtası ile orman emvalini ya da memurun silahını almak veya orman bölge/muhafaza binalarına zorla girmek maksadıyla vaki tecavüz/taarruzun başka şekilde önlenememesi","Kaçak yapı tespitinde direniş gösterilmesi hâlinde"],"dogru":3,"aciklama":"m.78/C: '(B) bendi gereğince teslim edilen alet ve silahları veya elkonan müsadereye tabi nakil vasıtaları ile orman emvalini veya memurun silahını almak veya orman bölge ve muhafaza binalarına zorla girmek maksadiyle vakı tecavüz ve taarruzun başka şekilde def'ine imkan bulunamaması.' (C) bendi, (B) bendinde teslim alınan mallara veya orman binalarına yönelik geri alma/zorla giriş girişimlerini kapsar.","kaynak":"6831 m.78","zorluk":"zor"},
    {"id":"6831-S-037","soru":"6831 sayılı Orman Kanunu m.79'a göre orman muhafaza memurları hangi kanun hükümlerine göre şüphelileri yakalama yetkisine sahiptir?","siklar":["Polis Vazife ve Salahiyet Kanunu","Ceza Muhakemesi Kanunu","Jandarma Teşkilat Kanunu","İdari Yargılama Usulü Kanunu","Kabahatler Kanunu"],"dogru":1,"aciklama":"m.79: '...Ayrıca, orman muhafaza memurları Ceza Muhakemesi Kanunu hükümlerine göre şüphelileri yakalama yetkisine sahiptir.' Yakalama yetkisinin dayanağı genel usul kanunu olan CMK'dır; el koymadaki 'orman işletme şefi yazılı emri' istisnasından ayrı, doğrudan CMK'ya atıf yapan bağımsız bir yetkidir.","kaynak":"6831 m.79","zorluk":"orta"},
    {"id":"6831-S-038","soru":"6831 sayılı Orman Kanunu m.83'e göre 110 uncu maddenin beşinci fıkrasında gösterilen suçlara ilişkin davalar hangi mahkemede görülür?","siklar":["Sulh ceza mahkemesinde","Asliye ceza mahkemesinde","Bölge adliye mahkemesinde","İdare mahkemesinde","Ceza Muhakemesi Kanununun 250 nci maddesi uyarınca görevlendirilen ağır ceza mahkemesinde"],"dogru":4,"aciklama":"m.83: '...110 uncu maddenin üçüncü fıkrasında gösterilen suçlara ilişkin davalar asliye ceza mahkemesinde; dördüncü fıkrasında gösterilen suçlara ilişkin davalar ağır ceza mahkemesinde; beşinci fıkrasında gösterilen suçlara ilişkin davalar Ceza Muhakemesi Kanununun 250 nci maddesi uyarınca görevlendirilen ağır ceza mahkemesinde; bu suçlar dışında kalan davalar sulh ceza mahkemesinde görülür.' Dört kademeli bir görev dağılımı vardır.","kaynak":"6831 m.83","zorluk":"zor"},
    {"id":"6831-S-039","soru":"6831 sayılı Orman Kanunu'na göre orman suçlarına ait davalar mahkemelerce acele mevaddan sayılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.83 (ikinci fıkra): 'Orman suçlarına ait davalar mahkemelerce acele mevaddan sayılır.' Bu hüküm, davanın görüleceği mahkeme türünden bağımsız, tüm orman suçu davaları için geçerli genel bir usul kuralıdır.","kaynak":"6831 m.83","zorluk":"kolay"},
    {"id":"6831-S-040","soru":"6831 sayılı Orman Kanunu m.84'e göre çürüyecek veya bozulacak olan ya da muhafazası zor ve masraflı bulunan el konulan mallar, Ceza Muhakemesi Kanununun 132 nci maddesi hükümlerine uygun olarak kim tarafından satılır?","siklar":["İl özel idaresi satış komisyonunca","Cumhuriyet savcılığınca","Orman işletme müdürlüklerinin müsadereli mallar satış komisyonlarınca","Sulh ceza mahkemesince","Belediye encümenince"],"dogru":2,"aciklama":"m.84: 'Bunlardan çürüyecek veya bozulacak olanlarla muhafazası zor ve masraflı bulunanlar, Ceza Muhakemesi Kanununun 132 nci maddesinin birinci ve ikinci fıkraları hükümlerine uygun olarak orman işletme müdürlüklerinin müsadereli mallar satış komisyonlarınca, mahallinde veya pazar yerlerinde ilan edilmek suretiyle derhal satılır.' Satış yediemin (belediye/muhtar) aşamasından ayrı, özel bir komisyon eliyle yapılır.","kaynak":"6831 m.84","zorluk":"orta"},
  ],
  33: [
    {"id":"4342-S-001","soru":"4342 sayılı Mera Kanunu'na göre, 'çiftçilerin hayvanları ile birlikte yaz mevsimini geçirmeleri, hayvanlarını otlatmaları ve otundan yararlanmaları için tahsis edilen veya kadimden beri bu amaçla kullanılan yer' tanımı aşağıdaki kavramlardan hangisine aittir?","siklar":["Yaylak","Mera","Kışlak","Çayır","Otlak"],"dogru":0,"aciklama":"m.3/e: 'Yaylak: Çiftçilerin hayvanları ile birlikte yaz mevsimini geçirmeleri, hayvanlarını otlatmaları ve otundan yararlanmaları için tahsis edilen veya kadimden beri bu amaçla kullanılan yeri...' ifade eder. Tanımdaki 'yaz mevsimi' ibaresi doğrudan yaylağı işaret eder.","kaynak":"4342 m.3","zorluk":"kolay"},
    {"id":"4342-S-002","soru":"4342 sayılı Mera Kanunu'na göre 'Büyükbaş Hayvan Birimi', hayvan sayısının kaç kg canlı ağırlığa çevrilerek ifade edilmesidir?","siklar":["350 kg","500 kg","650 kg","750 kg","1000 kg"],"dogru":1,"aciklama":"m.3/n: 'Büyükbaş Hayvan Birimi: Hayvan sayısının, bir büyükbaş hayvan birimi olan 500 kg canlı ağırlığa çevrilerek ifade edilen şeklini, ifade eder.'","kaynak":"4342 m.3","zorluk":"kolay"},
    {"id":"4342-S-003","soru":"4342 sayılı Mera Kanunu'na göre, 'belli bir alanda ve eşit zaman aralıkları ile uzun yıllar bitki örtüsüne, toprak, su ve diğer tabii kaynaklara zarar vermeden otlatılabilecek büyükbaş hayvan birimi miktarı' aşağıdaki kavramlardan hangisiyle ifade edilir?","siklar":["Otlatma hakkı","Tahdit","Otlatma kapasitesi","Tahsis","Mera vasfı ve kapasitesi"],"dogru":2,"aciklama":"m.3/h: 'Otlatma Kapasitesi: Belli bir alanda ve eşit zaman aralıkları ile uzun yıllar bitki örtüsüne, toprak, su ve diğer tabii kaynaklara zarar vermeden otlatılabilecek büyükbaş hayvan birimi miktarını...' ifade eder.","kaynak":"4342 m.3","zorluk":"orta"},
    {"id":"4342-S-004","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlaklar hakkında aşağıdaki ifadelerden hangisi YANLIŞTIR?","siklar":["Bu yerler Devletin hüküm ve tasarrufu altındadır","Özel mülkiyete geçirilemez","Zaman aşımı uygulanamaz","Kullanım hakkı kiralanamaz","Sınırları daraltılamaz"],"dogru":3,"aciklama":"m.4/3: '...özel mülkiyete geçirilemez, amacı dışında kullanılamaz, zaman aşımı uygulanamaz, sınırları daraltılamaz. Ancak, kullanım hakkı kiralanabilir. Kiralama ilkeleri yönetmelikle belirlenir.' Diğer dört ifade metinde aynen yer alır; yalnız 'kiralanamaz' ifadesi kanunla çelişir.","kaynak":"4342 m.4","zorluk":"orta"},
    {"id":"4342-S-005","soru":"4342 sayılı Mera Kanunu'na göre, amaç dışı kullanılmak suretiyle vasıfları bozulan mera, yaylak ve kışlakları tekrar eski konumuna getirmek amacıyla yapılan masraflar, buna sebebiyet verenlerden tahsil edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/4 (Değişik: 27/2/2013-6443/1): '...tekrar eski konumuna getirmek amacı ile yapılan veya yapılacak olan masraflar sebebiyet verenlerden tahsil edilir.' Tahsil edilen tutarlar genel bütçeye veya ilgili ıslah hesabına gelir kaydedilir.","kaynak":"4342 m.4","zorluk":"zor"},
    {"id":"4342-S-006","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlakların tespit, tahdit ve tahsisi için kurulan komisyona kim başkanlık eder?","siklar":["İl Tarım ve Orman Müdürü","Vali","Kaymakam","Defterdar","Valinin görevlendireceği bir vali yardımcısı"],"dogru":4,"aciklama":"m.6/1: 'Bu amaçla valinin görevlendireceği bir vali yardımcısı başkanlığında; Bakanlık il müdürü, ... olmak üzere on bir kişiden oluşan bir komisyon kurulur.'","kaynak":"4342 m.6","zorluk":"kolay"},
    {"id":"4342-S-007","soru":"4342 sayılı Mera Kanunu'na göre mera komisyonu kaç kişiden oluşur?","siklar":["11 kişi","9 kişi","10 kişi","12 kişi","13 kişi"],"dogru":0,"aciklama":"m.6/1 (18/10/2018-7148/30 ile değişik): '...ilgisine göre genel kolluk biriminde görevli bir temsilci olmak üzere on bir kişiden oluşan bir komisyon kurulur.'","kaynak":"4342 m.6","zorluk":"orta"},
    {"id":"4342-S-008","soru":"4342 sayılı Mera Kanunu'na göre, vali yardımcısının bulunmadığı durumlarda mera komisyonuna kim başkanlık eder?","siklar":["Kaymakam","Bakanlık il müdürü veya görevlendireceği konu uzmanı bir ziraat mühendisi","Vali bizzat","Defterdarlıktan görevlendirilen hukukçu","Ziraat Odası Başkanı"],"dogru":1,"aciklama":"m.6/2: 'Vali yardımcısının bulunmadığı durumlarda komisyona Bakanlık il müdürü veya görevlendireceği konu uzmanı bir ziraat mühendisi başkanlık eder.'","kaynak":"4342 m.6","zorluk":"zor"},
    {"id":"4342-S-009","soru":"4342 sayılı Mera Kanunu'na göre aşağıdakilerden hangisi mera komisyonunun üyeleri arasında sayılmamıştır?","siklar":["Devlet Su İşleri Genel Müdürlüğü yetkili temsilcisi","Orman Genel Müdürlüğü yetkili temsilcisi","Cumhuriyet başsavcılığı temsilcisi","Kadastro Müdürlüğünden bir teknik eleman","Ziraat Odası Başkanlığından bir temsilci"],"dogru":2,"aciklama":"m.6/1'de sayılan 11 üye arasında Cumhuriyet başsavcılığı temsilcisi yoktur; komisyondaki hukuki temsil, defterdarlıktan veya bulunamaması halinde valinin görevlendireceği bir hukukçu ile sağlanır.","kaynak":"4342 m.6","zorluk":"orta"},
    {"id":"4342-S-010","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlaklara tecavüz olduğu takdirde muhtarlar ve belediye başkanları durumu derhal kime bildirmekle yükümlüdür?","siklar":["Cumhuriyet başsavcılığına","İl özel idaresine","Tapu müdürlüğüne","Bakanlık il veya ilçe müdürlüğüne","Ziraat Odasına"],"dogru":3,"aciklama":"m.19/3: 'Muhtarlar ve belediye başkanları, mera, yaylak ve kışlaklara tecavüz olduğu takdirde durumu derhal Bakanlık il veya ilçe müdürlüğüne, il ve ilçe müdürlükleri de valilik veya kaymakamlığa bildirmekle yükümlüdürler.'","kaynak":"4342 m.19","zorluk":"kolay"},
    {"id":"4342-S-011","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlakların korunması amacıyla ilgili köy ve belediyelerde 'Mera Yönetim Birlikleri' kurulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.19/2: 'Bu amaçla ilgili köy ve belediyelerde \"Mera Yönetim Birlikleri\" kurulur. Mera Yönetim Birliklerinin kuruluş ve çalışma esas ve usulleri yönetmelikle belirlenir.'","kaynak":"4342 m.19","zorluk":"kolay"},
    {"id":"4342-S-012","soru":"4342 sayılı Mera Kanunu'na göre, yaylak ve kışlaklardaki inşaat yasağının istisnaları arasında aşağıdakilerden hangisi YOKTUR?","siklar":["442 sayılı Köy Kanununda öngörülen inşaatlar","Valiliklerden izin alınarak yapılan mandıra, suluk, sundurma","Süreklilik göstermeyen barınak ve ağıllar","Turizm Bakanlığının talebi üzerine turizme açılan bölgelerde ahşap yapılar","Belediyeden izin alınarak yapılan kalıcı ev ve ahır"],"dogru":4,"aciklama":"m.20: '...442 sayılı Köy Kanununda öngörülen inşaatlar ile valiliklerden izin alınmak suretiyle imar mevzuatına göre yapılacak kullanma amacına uygun mandıra, suluk, sundurma ve süreklilik göstermeyen barınak ve ağıllar ile Turizm Bakanlığının talebi üzerine turizme açılması uygun görülen bölgelerde ahşap yapılar dışında, ev, ahır ve benzeri inşaatlar yapılamaz.'","kaynak":"4342 m.20","zorluk":"orta"},
    {"id":"4342-S-013","soru":"4342 sayılı Mera Kanunu'na göre, çiftçi ailelerinin bir mera, yaylak ve kışlaktan yararlanabilmeleri için, tahsisin yapıldığı tarihte ilgili köy veya belediye sınırları içinde en az ....(1).... ikamet ediyor olmaları gerekir; ancak Devletçe ....(2).... için bu şart aranmaz. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["altı aydan beri – naklen yerleştirilenler","bir yıldan beri – göçerler","üç aydan beri – naklen yerleştirilenler","altı aydan beri – göçerler","bir yıldan beri – naklen yerleştirilenler"],"dogru":0,"aciklama":"m.22/1: 'Çiftçi ailelerinin bir mera, yaylak ve kışlaktan yararlanabilmeleri için, ... tahsisin yapıldığı tarihte en az altı aydan beri ikamet ediyor olmaları gerekir. Ancak, Devletçe naklen yerleştirilenler için bu şart aranmaz.'","kaynak":"4342 m.22","zorluk":"orta"},
    {"id":"4342-S-014","soru":"4342 sayılı Mera Kanunu'na göre, köy veya belediye sınırları içinde arazisi olmakla birlikte tahsis kararı kapsamına girmeyen çiftçi aileleri, o köy veya belediyeye tahsis edilen mera, yaylak ve kışlaktan yararlanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.22/2: 'Köy ve belediye sınırları içinde arazisi olmakla birlikte tahsis kararı kapsamına girmeyen çiftçi aileleri, o köy veya belediyeye tahsis edilen mera, yaylak ve kışlaktan yararlanamazlar.'","kaynak":"4342 m.22","zorluk":"orta"},
    {"id":"4342-S-015","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlağa komisyonun tahsis kararında belirtilen miktardan fazla hayvan sokulamaz. Otlatılacak hayvan miktarının artırılabilmesi hangi hâlde mümkündür?","siklar":["Muhtarın tek başına kararıyla her zaman","Bakım, koruma ve ıslah sonucu otlatma ve barındırma kapasitesinde artış olması hâlinde","Çiftçilerin oy birliğiyle talep etmesiyle","Valinin re'sen her yıl artış kararı vermesiyle","Hiçbir şekilde artırılamaz"],"dogru":1,"aciklama":"m.23/2: 'Ancak, daha sonra bakım, koruma ve ıslah sonucu mera, yaylak ve kışlağın otlatma ve barındırma kapasitesinde bir artışın olması halinde, köy veya belediyelerin teklifi üzerine veya doğrudan doğruya komisyonca yeniden tespit yapılarak otlatılacak hayvan miktarı artırılabilir.'","kaynak":"4342 m.23","zorluk":"orta"},
    {"id":"4342-S-016","soru":"4342 sayılı Mera Kanunu'na göre, otlatma haklarından fazla hayvan otlatanlardan, fazla otlatılan her hayvan sayısı için ücret ....(1).... olarak tahsil edilir; komisyonca tespit edilen ücret ve para cezalarının takip ve tahsilinde ....(2).... sayılı Kanun hükümleri uygulanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki katı – 2886","dört katı – 6183","üç katı – 6183","üç katı – 2886","iki katı – 6183"],"dogru":2,"aciklama":"m.26/2-3: '...otlatma haklarından fazla hayvan otlatanlardan bu ücret, fazla her hayvan sayısı için üç katı olarak tahsil edilir. ... Komisyonca tespit edilen ücret ve para cezalarının takip ve tahsilinde 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun hükümleri uygulanır.'","kaynak":"4342 m.26","zorluk":"orta"},
    {"id":"4342-S-017","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlaklardan yararlanan çiftçi aileleri, bakım ve ıslah çalışmalarına ait giderlere, herhangi bir şart aranmaksızın doğrudan valiliğin belirlediği miktarda katılmakla yükümlüdür.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.26/1: 'Mera, yaylak ve kışlaklardan yararlanan çiftçi aileleri, yapılacak bakım ve ıslah çalışmalarına ait giderlere, komisyonca gerekli görülmesi halinde, valiliğin onayı ile belirlenecek süre ve miktarlarda katılmakla yükümlüdürler.' Katılım yükümlülüğü komisyonun gerekli görmesi şartına bağlıdır.","kaynak":"4342 m.26","zorluk":"zor"},
    {"id":"4342-S-018","soru":"4342 sayılı Mera Kanunu'na göre, 26 ncı maddede öngörülen yükümlülüklerini yerine getirmeyenlerin yararlanma hakları, Bakanlık taşra teşkilatının teklifi ve valilik onayı ile en az ....(1).... en çok ....(2).... süreyle geçici olarak durdurulur; aynı fiilin tekrarı hâlinde ise yararlanma hakkı ....(3).... için iptal edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["5 gün – 15 gün – bir yıl","10 gün – 60 gün – bir otlatma dönemi","15 gün – 45 gün – iki otlatma dönemi","7 gün – 30 gün – bir otlatma dönemi","3 gün – 30 gün – bir yıl"],"dogru":3,"aciklama":"m.27/1: '...yararlanma hakları, Bakanlık taşra teşkilatının teklifi ve valilik onayı ile en az 7 gün, en çok 30 gün süre ile geçici olarak, aynı fiilin tekrarı halinde ise yararlanma hakkı bir otlatma dönemi için iptal edilir.'","kaynak":"4342 m.27","zorluk":"orta"},
    {"id":"4342-S-019","soru":"4342 sayılı Mera Kanunu'na göre, 'Mera ile aynı niteliklere sahip yer' aşağıdaki kavramlardan hangisi ile tanımlanır?","siklar":["Otlak","Çayır","Kışlak","Yaylak","Tahsis"],"dogru":0,"aciklama":"m.3/m: 'Otlak: Mera ile aynı niteliklere sahip yeri, ifade eder.' Kanun, Otlak kavramını ayrı bir tanım yapmak yerine doğrudan Mera ile özdeşleştirerek tanımlamıştır.","kaynak":"4342 m.3","zorluk":"orta"},
    {"id":"4342-S-020","soru":"4342 sayılı Mera Kanunu'na göre, çayır, mera, yaylak ve kışlak arazisi olduğuna karar verilen yerlerin sınırlarının ülke nirengi sistemine dayalı olarak hangi ölçekli haritalar üzerinde belirtilmesi ve arazi üzerinde kalıcı işaretlerle işaretlenmesi işlemine ne ad verilir?","siklar":["1/2000 ölçekli haritalarla Tahsis","1/5000 ölçekli haritalarla Tahdit","1/25000 ölçekli haritalarla Tespit","1/10000 ölçekli haritalarla Tahdit","1/1000 ölçekli haritalarla Tespit"],"dogru":1,"aciklama":"m.3/i: 'Tahdit: Çayır, mera, yaylak ve kışlak arazisi olduğuna karar verilen yerlerin sınırlarının usulüne uygun olarak ülke nirengi sistemine dayalı 1/5000 ölçekli haritalar üzerinde belirtilmesini ve bu sınırların arazi üzerinde kalıcı işaretlerle işaretlenmesini... ifade eder.'","kaynak":"4342 m.3","zorluk":"zor"},
    {"id":"4342-S-021","soru":"4342 sayılı Mera Kanunu'na göre, umuma ait çayır ve otlak yerlerinin kullanılmasında ve bunlardan faydalanılmasında mera, yaylak ve kışlaklara ilişkin hükümler uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4 son fıkra: 'Umuma ait çayır ve otlak yerlerinin kullanılmasında ve bunlardan faydalanılmasında mera yaylak ve kışlaklara ilişkin hükümler uygulanır.'","kaynak":"4342 m.4","zorluk":"kolay"},
    {"id":"4342-S-022","soru":"4342 sayılı Mera Kanunu'na göre, mera komisyonunun henüz görevine başlamadığı yerlerde mera, yaylak ve kışlakların kullanımı nasıl sürdürülür?","siklar":["Kullanım tamamen durdurulur, komisyon kuruluncaya kadar hiçbir tahsis geçerli sayılmaz","Kullanım hakkı doğrudan Hazineye geçer","Evvelce çeşitli kanunlar uyarınca yapılmış olan tahsislere ve teessüs etmiş teamüllere göre köy veya belediye halkı tarafından kullanılmasına devam olunur","Valinin re'sen belirlediği geçici tahsis kararına göre kullanılır","Kullanım, en yakın belediyenin talebi üzerine askıya alınır"],"dogru":2,"aciklama":"m.4/2: 'Komisyonun henüz görevine başlamadığı yerlerde, evvelce çeşitli kanunlar uyarınca yapılmış olan tahsislere ve teessüs etmiş teamüllere göre; mera, yaylak ve kışlakların köy veya belediye halkı tarafından kullanılmasına devam olunur.'","kaynak":"4342 m.4","zorluk":"orta"},
    {"id":"4342-S-023","soru":"4342 sayılı Mera Kanunu'na göre aşağıdakilerden hangisi, komisyona bağlı olarak tespit, ölçme, harita yapma ve yer gösterme çalışmalarını yürüten 'Teknik Ekipler'in üyeleri arasında sayılmamıştır?","siklar":["Bakanlık il veya ilçe müdürlüğünden bir ziraat mühendisi","Kadastro Müdürlüğünden bir teknik eleman","Millî Emlak Müdürlüğünden bir temsilci","Devlet Su İşleri Genel Müdürlüğü yetkili temsilcisi","Komisyonun teklifi ve valinin onayı ile seçilen iki mahallî bilirkişi"],"dogru":3,"aciklama":"m.6/4 (Değişik: 27/5/2004-5178/1): Teknik ekipler; Bakanlık il veya ilçe müdürlüğünden bir ziraat mühendisi, Köy Hizmetleri İl Müdürlüğünden bir ziraat mühendisi veya teknik eleman, Kadastro Müdürlüğünden bir teknik eleman, Millî Emlak Müdürlüğünden bir temsilci, ilgili bir orman mühendisi, (3083 sayılı Kanun uygulama alanlarında) Tarım Reformu Teşkilatından bir ziraat mühendisi ile meradan yararlanan köy/belediye temsilcisi ve komisyonun teklifi ve valinin onayı ile seçilen iki mahallî bilirkişiden oluşur. Devlet Su İşleri Genel Müdürlüğü temsilcisi ise m.6/1 uyarınca asıl mera KOMİSYONUNUN 11 üyesinden biridir, Teknik Ekip üyesi değildir.","kaynak":"4342 m.6","zorluk":"zor"},
    {"id":"4342-S-024","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlaklara tecavüz bildirimini alan makamlarca ....(1).... sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun veya ....(2).... sayılı Devlet İhale Kanununun 75 inci maddesi uyarınca gerekli işlemler yapılır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["2886 – 3091","3091 – 6183","2942 – 2886","3091 – 4721","3091 – 2886"],"dogru":4,"aciklama":"m.19/3: 'Bu makamlarca 3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun veya 2886 sayılı Devlet İhale Kanununun 75 inci maddesi uyarınca gerekli işlemler yapılır.'","kaynak":"4342 m.19","zorluk":"zor"},
    {"id":"4342-S-025","soru":"4342 sayılı Mera Kanunu'na göre, başka yere yerleşme amacı ile bulunduğu yeri terk eden çiftçi ailesinin mera, yaylak ve kışlaktan yararlanma hakkı ne olur; bu hak hangi şartla yeniden tanınabilir?","siklar":["Hak kaybolmaz, otomatik olarak devam eder","Hak kaybedilir ve hiçbir şekilde geri kazanılamaz","Hak kaybedilir; yalnızca valilik onayıyla otomatik olarak iade edilir","Hak kaybedilir; sürekli ikamet amacıyla geri dönülmesi halinde komisyon kararı ile yeniden tanınabilir","Hak askıya alınır, altı ay sonra kendiliğinden geri gelir"],"dogru":3,"aciklama":"m.22/3: 'Başka yere yerleşme amacı ile bulundukları yeri terkeden çiftçi aileleri, yararlanma hakkını kaybeder. Ancak, bunların sürekli ikamet amacıyla geri dönmeleri halinde, bu hak komisyon kararı ile tanınabilir.'","kaynak":"4342 m.22","zorluk":"orta"},
    {"id":"4342-S-026","soru":"4342 sayılı Mera Kanunu'na göre, mera, yaylak ve kışlaklardan komisyonca tespit edilecek otlatma haklarına göre yararlanacak hak sahiplerinin ödeyeceği ücret, bölgenin ekonomik durumu, otlatma kapasitesi ve otlatma süresi dikkate alınarak hangi sıklıkla tespit edilir?","siklar":["Her ay","Beş yılda bir","Her yıl","Üç yılda bir","Yalnızca tahsis anında bir kez"],"dogru":2,"aciklama":"m.26/2: '...bölgenin ekonomik durumu, otlatma kapasitesi ve otlatma süresi dikkate alınarak, komisyonca her yıl tespit edilecek belli bir ücreti ödemekle yükümlüdürler.'","kaynak":"4342 m.26","zorluk":"kolay"},
    {"id":"4342-S-027","soru":"4342 sayılı Mera Kanunu'na göre, yasaklanmış yerlerde hayvanlarını otlatmaya devam edenler, mera, yaylak ve kışlak arazisini sürmek suretiyle tahrip edenler ve izinsiz inşaat yapanlar hakkında valilik tarafından hangi mevzuat hükümlerine göre gerekli kanuni işlem yapılır?","siklar":["2886 sayılı Devlet İhale Kanunu ile 6183 sayılı Kanun","Yalnızca 442 sayılı Köy Kanunu","2942 sayılı Kamulaştırma Kanunu ile Türk Medeni Kanunu","Yalnızca genel hükümlere göre disiplin işlemi","3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun ile Türk Ceza Kanununun 513 üncü ve devamı maddeleri"],"dogru":4,"aciklama":"m.27/2: 'Yasaklanmış yerlerde hayvanlarını otlatmaya devam edenlerle mera, yaylak ve kışlak arazisini sürmek sureti ile tahrip edenler ve izinsiz inşaat yapanlar hakkında, valilik tarafından 3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun ile Türk Ceza Kanununun 513 üncü ve devamı maddelerine göre gerekli kanuni işlem yapılır.'","kaynak":"4342 m.27","zorluk":"orta"},
  ],
  34: [
    {"id":"2918-S-001","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, görev sırasında can ve mal güvenliğini tehlikeye sokmamak şartıyla belirli araç sürücülerinin trafik kısıtlama veya yasaklarına bağlı olmama hali, aşağıdaki kavramlardan hangisiyle ifade edilir?","siklar":["Geçiş üstünlüğü","Geçiş hakkı","Öncelik hakkı","Trafik zabıtası yetkisi","Zorunlu geçiş hakkı"],"dogru":0,"aciklama":"m.3: 'Geçiş üstünlüğü: Görev sırasında, belirli araç sürücülerinin can ve mal güvenliğini tehlikeye sokmamak şartı ile trafik kısıtlama veya yasaklarına bağlı olmamalarıdır.' Tanımlanan kavram geçiş üstünlüğüdür.","kaynak":"2918 m.3","zorluk":"kolay"},
    {"id":"2918-S-002","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, trafik zorunlulukları nedeniyle aracın durdurulmasına ....(1)...., insan indirip bindirmek veya eşya yükleyip boşaltmak amacıyla kısa süreli durdurulmasına ....(2)...., bunların dışında kalan bırakma haline ise ....(3).... denir. Boşluklara sırasıyla gelmesi gereken kavramlar hangisidir?","siklar":["Duraklama - Durma - Park etme","Durma - Duraklama - Park etme","Park etme - Durma - Duraklama","Duraklama - Park etme - Durma","Durma - Park etme - Duraklama"],"dogru":1,"aciklama":"m.3: 'Durma: Her türlü trafik zorunlulukları nedeni ile aracın durdurulmasıdır. Duraklama: ...kısa bir süre için durdurulmasıdır. Park etme: ...durma ve duraklaması gereken haller dışında bırakılmasıdır.' Sıra: durma - duraklama - park etme.","kaynak":"2918 m.3","zorluk":"orta"},
    {"id":"2918-S-003","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre aşağıdakilerden hangisi İçişleri Bakanlığının bu Kanundan doğan görev ve yetkileri arasında sayılmamıştır?","siklar":["Araç tescili yapmak","Sürücü belgesi vermek","Karayolu yapım ve bakımını yürütmek","Trafik kaza tespit tutanağı düzenlemek","Trafik kurallarına uyumu denetlemek"],"dogru":2,"aciklama":"m.5: İçişleri Bakanlığının görevleri arasında araç tescili (f), sürücü belgesi verme (g), kaza tespit tutanağı düzenleme (c) ve kural denetimi (a) sayılmıştır. 'Karayolu yapım ve bakımını yürütmek' bu maddede İçişleri Bakanlığına verilmiş bir görev değildir; bu iş Karayolları Genel Müdürlüğü/Ulaştırma ve Altyapı Bakanlığına aittir.","kaynak":"2918 m.5","zorluk":"orta"},
    {"id":"2918-S-004","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, trafik zabıtasının bulunmadığı veya yeterli olmadığı yerlerde sorumluluk bölgesine göre trafiği düzenlemeye ve trafik suçlarına el koymaya kim görevli ve yetkilidir?","siklar":["Belediye zabıtası","İl trafik komisyonu","Karayolları Genel Müdürlüğü","Genel zabıta","Jandarma Genel Komutanlığı merkez birimi"],"dogru":3,"aciklama":"m.6: 'Genel Zabıta: Trafik zabıtasının bulunmadığı veya yeterli olmadığı yerlerde sorumluluk bölgesine göre genel zabıta ilgili mevzuatta belirtilen esas ve usullere uygun olarak trafiği düzenlemeye ve trafik suçlarına el koymaya görevli ve yetkilidir.' Yetki genel zabıtadadır.","kaynak":"2918 m.6","zorluk":"orta"},
    {"id":"2918-S-005","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre İlçe Trafik Komisyonuna kim başkanlık eder?","siklar":["Vali","Vali yardımcısı","Belediye başkanı","İl emniyet müdürü","Kaymakam"],"dogru":4,"aciklama":"m.12: '...ilçelerde kaymakamın başkanlığında, aynı kuruluşların yöneticileri veya görevlendirecekleri temsilcilerinin katıldığı İlçe Trafik Komisyonu kurulur.' İlçe komisyonuna kaymakam başkanlık eder.","kaynak":"2918 m.12","zorluk":"kolay"},
    {"id":"2918-S-006","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, tescili zorunlu araçların satın alma veya gümrükten çekme tarihinden itibaren ....(1).... içinde tescili için; hurda durumuna gelmesi halinde ise ....(2).... içinde tescilin silinmesi için ilgili tescil kuruluşuna başvurulması zorunludur. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["üç ay - bir ay","bir ay - iki ay","altı ay - bir ay","iki ay - üç ay","üç ay - iki ay"],"dogru":0,"aciklama":"m.20: 'Tescili zorunlu ve ilk tescili yapılacak olan araçların satın alma veya gümrükten çekme tarihinden itibaren üç ay içinde tescili için; bunların hurda durumuna gelmesi hâlinde ise bir ay içinde tescilin silinmesi için...başvurmak...zorundadırlar.' İlk tescil 3 ay, hurda silme 1 aydır.","kaynak":"2918 m.20","zorluk":"orta"},
    {"id":"2918-S-007","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre araçların giriş işlemlerini yapan gümrük idareleri, bu durumu araç sahiplerinin beyan ettikleri tescil kuruluşuna kaç gün içinde bildirmekle yükümlüdür?","siklar":["7 gün","15 gün","10 gün","30 gün","3 iş günü"],"dogru":1,"aciklama":"m.20/b: 'Araçların giriş işlemlerini yapan gümrük idareleri bu durumu 15 gün içinde araç sahiplerinin beyan ettikleri tescil kuruluşuna bildirmekle yükümlüdürler.' Süre 15 gündür.","kaynak":"2918 m.20","zorluk":"orta"},
    {"id":"2918-S-008","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, araç sahibinin vefatı halinde mirasçılar, gerekli bilgi ve belgeleri sağlayarak vefat tarihinden itibaren kaç gün içinde ilgili tescil kuruluşuna müracaat edip adlarına tescil belgesi almak zorundadır?","siklar":["30 gün","60 gün","90 gün","1 yıl","6 ay"],"dogru":2,"aciklama":"m.20/f: 'Araç sahiplerinin vefat etmesi halinde mirasçılar, gerekli bilgi ve belgeleri sağlayarak vefat tarihinden itibaren doksan gün içerisinde ilgili tescil kuruluşuna müracaat etmek ve adlarına tescil belgesi almak zorundadırlar.' Süre 90 gündür.","kaynak":"2918 m.20","zorluk":"orta"},
    {"id":"2918-S-009","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre Jandarma Genel Komutanlığı ile Sahil Güvenlik Komutanlığına ait bütün araçların tescili hangi kurum tarafından yapılır?","siklar":["Türk Silahlı Kuvvetleri","İçişleri Bakanlığı","İl Trafik Komisyonu","Emniyet Genel Müdürlüğü","Belediye"],"dogru":3,"aciklama":"m.22/e: 'Jandarma Genel Komutanlığı ile Sahil Güvenlik Komutanlığına ait bütün araçların tescilleri Emniyet Genel Müdürlüğünce...yapılır.' Tescil mercii Emniyet Genel Müdürlüğüdür.","kaynak":"2918 m.22","zorluk":"orta"},
    {"id":"2918-S-010","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre tescilli aracı plakasız olarak kullanan sürücü hakkında öngörülen yaptırım aşağıdakilerden hangisidir?","siklar":["Sadece idari para cezası verilir","Araç doğrudan hurdaya ayrılır","Sürücü belgesi süresiz iptal edilir","Araç men edilir ama sürücü belgesine dokunulmaz","Sürücü belgesi ve araç otuzar gün süreyle geri alınır/men edilir"],"dogru":4,"aciklama":"m.23: 'Tescilli aracı plakasız kullanan sürücülere...sürücü belgeleri otuz gün süreyle geri alınır ve araç otuz gün süre ile trafikten menedilir.' Hem belge hem araç 30 gün süreyle işlem görür.","kaynak":"2918 m.23","zorluk":"orta"},
    {"id":"2918-S-011","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, azami yüklü ağırlığı ....(1)…. kilogramdan fazla olan yük taşıma araçları ile sürücüsü dahil oturma yeri ....(2).... 'dan fazla olan yolcu taşıma araçlarında takograf bulundurulması, kullanılır durumda olması ve kullanılması zorunludur. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["3.500 - 17","750 - 9","3.500 - 9","750 - 17","7.500 - 25"],"dogru":0,"aciklama":"m.31/b: 'Yük taşımada kullanılan ve azami yüklü ağırlığı 3.500 kilogramdan fazla olan motorlu taşıtlar ile...yolcu taşımacılığı faaliyetlerinde kullanılan ve sürücüsü dahil oturma yeri on yediden fazla olan motorlu taşıtlarda takograf...bulundurulması...zorunludur.' Eşikler 3.500 kg ve 17 kişidir.","kaynak":"2918 m.31","zorluk":"orta"},
    {"id":"2918-S-012","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, muayene için tanınan süre sonunda muayenesi yapılmadan veya emniyetsiz raporu verilmiş bir araç trafiğe çıkarılırsa ne olur?","siklar":["Sadece sürücüye sözlü uyarı yapılır","Araç trafikten men edilerek en yakın muayene istasyonuna gönderilir","Araç doğrudan hurdaya ayrılır","Sürücü belgesi süresiz iptal edilir","Araç sahibine hapis cezası verilir"],"dogru":1,"aciklama":"m.34: 'İzin verilen süre sonunda, muayenesi yapılmadan veya muayene sonucunda emniyetsiz raporu verilen araçların trafiğe çıkarılması hâlinde...Bu araçlar trafikten men edilir ve en yakın muayene istasyonuna gönderilirler.' Yaptırım men + istasyona sevktir.","kaynak":"2918 m.34","zorluk":"kolay"},
    {"id":"2918-S-013","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, sürücü belgesi olmayan bir kişinin motorlu araç kullanmasına izin veren araç işletenine de idari para cezası uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.36: '...bu fıkra kapsamında motorlu araçların sürülmesine izin veren işletene de tescil plakası üzerinden...idari para cezası verilir.' Belgesiz sürme yasağı hem süren hem izin veren için ayrı ayrı yaptırıma bağlanmıştır.","kaynak":"2918 m.36","zorluk":"kolay"},
    {"id":"2918-S-014","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre sürücü belgesi almaları zorunlu olmamakla birlikte, bisiklet kullananların ....(1)…., motorsuz taşıt kullananlar ile hayvan sürücülerinin ....(2)…., elektrikli bisiklet ve elektrikli skuter kullananların ise ....(3).... yaşını bitirmiş olmaları zorunludur. Boşluklara sırasıyla gelmesi gereken yaşlar hangisidir?","siklar":["13 - 11 - 15","15 - 13 - 11","11 - 13 - 15","11 - 15 - 13","13 - 15 - 11"],"dogru":2,"aciklama":"m.37: 'Bisiklet kullananların 11, elektrikli bisiklet ve elektrikli skuter kullananların 15, motorsuz taşıtları kullananlar ile hayvan sürücülerinin 13 yaşını bitirmiş olmaları...zorunludur.' Sıra: bisiklet 11, motorsuz/hayvan 13, elektrikli bisiklet/skuter 15.","kaynak":"2918 m.37","zorluk":"orta"},
    {"id":"2918-S-015","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre sürücüler, gidişe ayrılan en soldaki şeridi sürekli olarak işgal edemezler.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.46/d: 'Gidişe ayrılan en soldaki şeridi sürekli olarak işgal etmemek...zorundadırlar.' Kural açıkça bu yasağı öngörür.","kaynak":"2918 m.46","zorluk":"kolay"},
    {"id":"2918-S-016","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, motosiklet, otomobil, kamyonet, panelvan, minibüs ve otobüs dışındaki araçları kullanan sürücüler, ikiden fazla şeridi bulunan yollarda (sola dönme hariç) hangi şerit veya şeritleri kullanamazlar?","siklar":["Yalnızca en soldaki şerit","Sağdan ikinci şerit hariç tüm şeritler","Ortadaki şeritler","En sağdaki iki şerit dışındaki şerit/şeritler","Yalnızca sağdaki şerit"],"dogru":3,"aciklama":"m.46/e-3: 'İkiden fazla şeridi bulunan yollarda sola dönme dışında en sağdaki iki şerit dışındaki şerit/şeritleri kullanmamak.' Bu araçlar sola dönme dışında yalnızca en sağdaki iki şeritte kalmak zorundadır.","kaynak":"2918 m.46","zorluk":"zor"},
    {"id":"2918-S-017","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, trafiği düzenleme ve denetimle görevli trafik zabıtası veya yetkili kişinin uyarı ve işareti ile trafik ışığı çelişirse hangisine uyulur?","siklar":["Trafik ışığına","Levhaya","Yer işaretlemesine","Yönetmelik kuralına","Trafiği düzenlemekle görevli yetkili kişinin işaretine"],"dogru":4,"aciklama":"m.47: Karayollarından faydalananlar sıralamaya göre önce (a) 'trafik zabıtası veya...yetkili kişilerin uyarı ve işaretlerine', sonra (b) trafik ışıklarına uymak zorundadır. Görevlinin işareti ışıktan önce gelir.","kaynak":"2918 m.47","zorluk":"orta"},
    {"id":"2918-S-018","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre hususi otomobil dışındaki araçları alkollü olarak kullanan sürücüler bakımından uygulanan promil alt sınırı kaçtır?","siklar":["0,21","0,50","1,00","0,20","0,10"],"dogru":0,"aciklama":"m.48: 'Hususi otomobil dışındaki araçları alkollü olarak kullanan sürücüler bakımından promil alt sınırı 0.21 olarak uygulanır.' Hususi otomobilde ise bu sınır 0,50'dir.","kaynak":"2918 m.48","zorluk":"orta"},
    {"id":"2918-S-019","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, uyuşturucu veya uyarıcı madde aldığı tespit edilen sürücü hakkında uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["Sürücü belgesi yalnızca altı ay süreyle geri alınır","Sürücü belgesi iptal edilir ve ayrıca Türk Ceza Kanunu hükümleri uygulanır","Sadece idari para cezası verilir, belgeye dokunulmaz","Sürücü belgesi iki yıl süreyle geri alınır","Araç trafikten men edilir, belgeye dokunulmaz"],"dogru":1,"aciklama":"m.48: 'Uyuşturucu veya uyarıcı madde aldığı tespit edilen sürücülere...idari para cezası uygulanır ve sürücü belgesi iptal edilir. Bu kişiler hakkında ayrıca Türk Ceza Kanunu hükümleri uygulanır.' Yaptırım iptal + ayrıca TCK'dır.","kaynak":"2918 m.48","zorluk":"orta"},
    {"id":"2918-S-020","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre şehirlerarası bölünmüş yollarda azami hız sınırı kaç km/s'dir?","siklar":["90","100","110","120","130"],"dogru":2,"aciklama":"m.50: '...şehirlerarası çift yönlü karayollarında 90 km/s, bölünmüş yollarda 110 km/s, otoyollarda 120 km/s hızı geçmemek üzere yönetmelikte belirlenir.' Bölünmüş yol sınırı 110 km/s'dir.","kaynak":"2918 m.50","zorluk":"kolay"},
    {"id":"2918-S-021","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, yerleşim yeri içinde hız sınırını en üst dilimde (66 km/s ve üzeri) aşan sürücünün belgesi her seferinde ....(1)…., bir alt dilimde (56-65 km/s) aşanın belgesi ....(2)…., ondan bir alt dilimde (46-55 km/s) aşanın belgesi ise ....(3).... süreyle geri alınır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["30 gün - 60 gün - 90 gün","60 gün - 90 gün - 30 gün","30 gün - 90 gün - 60 gün","90 gün - 60 gün - 30 gün","60 gün - 30 gün - 90 gün"],"dogru":3,"aciklama":"m.51: '(a) [66 km/s ve üzeri aşımın karşılığı olan] (9) numaralı alt bendin ihlali halinde her seferinde 90 gün, (b) [56-65 km/s aşımın karşılığı] (8) numaralı alt bendin ihlali halinde her seferinde 60 gün, (c) [46-55 km/s aşımın karşılığı] (7) numaralı alt bendin ihlali halinde ise her seferinde 30 gün süre ile sürücü belgeleri geri alınır.' En üst dilim en uzun süreyi (90 gün) doğurur.","kaynak":"2918 m.51","zorluk":"zor"},
    {"id":"2918-S-022","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre işaretsiz kavşaklarda geçiş hakkına ilişkin aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Tali yoldan anayola çıkan sürücü anayoldan gelen araca yol verir","Bölünmüş yola çıkan sürücü bu yoldan geçen araca yol verir","Motorsuz araç sürücüsü motorlu araca yol verir","Bütün sürücüler geçiş üstünlüğüne sahip araca yol verir","Sağdan gelen araç soldakine yol verir"],"dogru":4,"aciklama":"m.57/c-2: 'Motorlu araçlardan soldaki sağdan gelen araca...geçiş hakkını vermek zorundadırlar.' Kural tam tersidir: soldaki araç sağdan gelene yol verir, sağdan gelen değil. E şıkkı bu nedenle yanlıştır.","kaynak":"2918 m.57","zorluk":"zor"},
    {"id":"2918-S-023","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre elektrikli skuter kullanan sürücülerin taşıtlarını sürerken uyması gereken el kullanma kuralı nedir?","siklar":["İki elleri ile sürmeleri zorunludur","En az bir elleri ile sürmeleri yeterlidir","Herhangi bir el kuralı yoktur, serbesttir","Yalnızca sağ elleriyle sürmeleri zorunludur","Yalnızca sol elleriyle sürmeleri zorunludur"],"dogru":0,"aciklama":"m.66/b: 'Bisiklet sürenlerin en az bir elleri, elektrikli skuter ve motorlu bisiklet sürenlerin...iki elleri...ile taşıtlarını sürmeleri...zorunludur.' Elektrikli skuterde iki el zorunludur; bisiklette ise en az bir el yeterlidir.","kaynak":"2918 m.66","zorluk":"orta"},
    {"id":"2918-S-024","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, birden fazla il sınırları içindeki şehirlerarası karayolları üzerinde yapılacak millî ve milletlerarası yarış ve koşular için hangi makamdan izin alınması zorunludur?","siklar":["İlgili valilik","İçişleri Bakanlığı","Karayolları Genel Müdürlüğü","Türkiye Şoförler ve Otomobilciler Federasyonu","İl Trafik Komisyonu"],"dogru":1,"aciklama":"m.70/b: 'Birden fazla il sınırları içindeki şehirlerarası karayolları üzerinde yapılacak milli ve milletlerarası yarış ve koşular için İçişleri Bakanlığından izin alınması zorunludur.' Tek il sınırındaki yarışlarda ise izin ilgili valilikten alınır.","kaynak":"2918 m.70","zorluk":"orta"},
    {"id":"2918-S-025","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre geçiş üstünlüğüne sahip araçlar öncelik sırasıyla önce ....(1)…., sonra ....(2)…., sonra da hükümlü veya sanığı takip eden ya da olay yerine giden ....(3).... araçlarıdır. Boşluklara sırasıyla gelmesi gereken araç türleri hangisidir?","siklar":["itfaiye - cankurtaran - zabıta","zabıta - itfaiye - cankurtaran","cankurtaran - itfaiye - zabıta","cankurtaran - zabıta - itfaiye","itfaiye - zabıta - cankurtaran"],"dogru":2,"aciklama":"m.71: 'a) Cankurtaran araçları, yaralı veya acil hasta taşıyan araçlar, b) İtfaiye araçları...c) Hükümlü veya sanığı takip eden veya...acele olay yerine giden zabıta araçları.' Sıra: cankurtaran, itfaiye, zabıta.","kaynak":"2918 m.71","zorluk":"kolay"},
    {"id":"2918-S-026","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre sürücüler, ışıklı trafik işareti bulunmayan ancak levha ile belirlenmiş bir yaya geçidine yaklaşırken, geçitten geçmekte olan yayaya ilk geçiş hakkını vermek zorunda değildir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.74: 'Sürücüler, görevli bir kişi veya ışıklı trafik işareti bulunmayan ancak trafik işareti veya levhalarıyla belirlenmiş...yaya veya okul geçitlerine yaklaşırken yavaşlamak, varsa buralardan geçen...yayalara durarak ilk geçiş hakkını vermek zorundadırlar.' Yükümlülük mutlaktır.","kaynak":"2918 m.74","zorluk":"kolay"},
    {"id":"2918-S-027","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, 15 yaşını doldurmamış çocukların araçta koruyucu sistemleri (örn. çocuk bağlama sistemi) kullanmasını sağlamak kimin yükümlülüğüdür?","siklar":["Çocuğun kendisi","Trafik zabıtası","İçişleri Bakanlığı","Araç sürücüsü","Okul idaresi"],"dogru":3,"aciklama":"m.78: 'Sürücüler, 15 yaşını doldurmamış çocukların birinci fıkrada belirtilen koruyucu sistemleri kullanmalarını sağlamak zorundadırlar.' Sorumluluk aracı süren kişiye aittir.","kaynak":"2918 m.78","zorluk":"orta"},
    {"id":"2918-S-028","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre trafik kazasına karışanların yükümlülükleri arasında aşağıdakilerden hangisi YOKTUR?","siklar":["Hemen durmak ve trafik güvenliği için gerekli tedbirleri almak","Kaza yerindeki iz ve delilleri olduğu gibi bırakmak","İstendiğinde kimliğini, sürücü ve tescil belgesini göstermek","Kazayı yetkili ve görevli memurlara bildirmek","Kazaya karışan araçları derhal yoldan çekip trafiği hemen açmak"],"dogru":4,"aciklama":"m.81'de sayılan yükümlülükler hemen durma (a), delil ve izleri bozmama (b), kimlik/belge gösterme (c) ve görevliye bildirim/izinsiz ayrılmama (d) şeklindedir. 'Araçları derhal çekip trafiği açma' kazaya karışanın değil, ancak koşullu olarak yetkili mercilerin (m.83) yapabileceği bir işlemdir; kazaya karışanın kendiliğinden yapması yükümlülük değildir.","kaynak":"2918 m.81","zorluk":"orta"},
    {"id":"2918-S-029","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre şehirlerarası akaryakıt istasyonu sahip veya işletenleri, ilk yardım malzemesini her an kullanılabilir durumda bulundurmakla yükümlü değildir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.82/b: 'Şehirlerarası akaryakıt istasyonlarında, sahipleri veya işletenleri...ilk yardım malzemesini her an kullanılabilir durumda bulundurmaya...zorunludurlar.' Bu bir yükümlülüktür, muafiyet yoktur.","kaynak":"2918 m.82","zorluk":"orta"},
    {"id":"2918-S-030","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, trafik kazasının oluş nedenlerini, iz ve delillerini belirleyerek trafik kaza tespit tutanağı düzenlemekle görevli birim aşağıdakilerden hangisidir?","siklar":["Trafik zabıtası","Genel zabıta","Cumhuriyet savcılığı","Sulh ceza mahkemesi","İl trafik komisyonu"],"dogru":0,"aciklama":"m.83/b: 'Kazanın oluş nedenlerini, iz ve delillerini belirleyerek trafik kaza tespit tutanağı düzenlemek üzere...trafik zabıtasınca el konulur.' Adli yönden el koyma ise genel zabıtaya aittir (a bendi).","kaynak":"2918 m.83","zorluk":"orta"},
    {"id":"2918-S-031","soru":"2918 sayılı Karayolları Trafik Kanunu'nun 84. maddesine göre aşağıdakilerden hangisi asli kusur hallerinden biri değildir?","siklar":["Kırmızı ışıklı trafik işaretinde geçme","Duraklama işareti bulunan yerde kısa süre durmak","Arkadan çarpma","Geçme yasağı olan yerlerde geçme","Kavşaklarda geçiş önceliğine uymama"],"dogru":1,"aciklama":"m.84: Asli kusur halleri arasında kırmızı ışıkta geçme (a), arkadan çarpma (d), geçme yasağında geçme (e) ve kavşaklarda önceliğe uymama (h) sayılmıştır. 'Duraklama işaretinde kısa süre durmak' zaten duraklamanın olağan ve kurallı kullanımıdır, asli kusur değildir.","kaynak":"2918 m.84","zorluk":"zor"},
    {"id":"2918-S-032","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, motorlu araç kazalarından doğan maddi zararların tazminine ilişkin talepler, zarar görenin zararı ve tazminat yükümlüsünü öğrendiği tarihten başlayarak ....(1)…., herhalde kaza gününden başlayarak ....(2).... içinde zamanaşımına uğrar. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["1 yıl - 5 yıl","5 yıl - 10 yıl","2 yıl - 10 yıl","2 yıl - 5 yıl","1 yıl - 10 yıl"],"dogru":2,"aciklama":"m.109: 'Zarar görenin, zararı ve tazminat yükümlüsünü öğrendiği tarihten başlayarak iki yıl ve herhalde, kaza gününden başlayarak on yıl içinde zamanaşımına uğrar.' Süreler 2 yıl ve 10 yıldır.","kaynak":"2918 m.109","zorluk":"orta"},
    {"id":"2918-S-033","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, bu Kanunun 6. maddesinde sayılan görevlilerin yetkilendirildiği haller hariç olmak üzere, sürücü belgelerinin geri alınmasına ve iptaline kural olarak hangi merci karar verir?","siklar":["İl Trafik Komisyonu","Vali","Cumhuriyet savcılığı","Sulh ceza mahkemesi","İçişleri Bakanlığı"],"dogru":3,"aciklama":"m.112: '...sürücü belgelerinin geri alınmasına ve iptaline sulh ceza mahkemeleri karar verir.' m.51 hız aşımı ve m.118 '100 ceza puanı' hallerinde ise istisnaen m.6'da sayılan görevliler yetkilidir.","kaynak":"2918 m.112","zorluk":"zor"},
    {"id":"2918-S-034","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre aşağıdakilerden hangisi trafik suçlarına ilişkin tutanak düzenlemeye yetkili kılınan kurumlardan biri değildir?","siklar":["Emniyet Genel Müdürlüğü","Jandarma Genel Komutanlığı","Ulaştırma ve Altyapı Bakanlığının ilgili birimleri","Karayolları Genel Müdürlüğünün ilgili birimleri","Belediye zabıtası"],"dogru":4,"aciklama":"m.114: 'Emniyet Genel Müdürlüğü ve Jandarma Genel Komutanlığı personeli ile Ulaştırma ve Altyapı Bakanlığının ve Karayolları Genel Müdürlüğünün ilgili birimlerinin...görevli ve yetkili kılınmış personelince tutanak düzenlenir.' Belediye zabıtası bu maddede sayılmamıştır.","kaynak":"2918 m.114","zorluk":"orta"},
    {"id":"2918-S-035","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, trafik suçunun işlendiği tarihten geriye doğru bir yıl içinde ikinci defa 100 ceza puanını dolduran sürücüler hakkında aşağıdakilerden hangisi uygulanır?","siklar":["Belgeleri 4 ay süreyle geri alınarak psiko-teknik değerlendirmeye ve psikiyatri muayenesine tabi tutulurlar","Belgeleri yalnızca 2 ay süreyle geri alınır","Belgeleri süresiz olarak iptal edilir","Sadece idari para cezası uygulanır, belgeye dokunulmaz","Belgeleri 1 yıl süreyle geri alınır"],"dogru":0,"aciklama":"m.118: 'Aynı yıl içinde ikinci defa 100 puanı dolduran sürücülerin sürücü belgeleri 4 ay süre ile geri alınarak psiko-teknik değerlendirmeye ve psikiyatri uzmanının muayenesine tabi tutulurlar.' İlk dolumda 2 ay, üçüncü dolumda süresiz iptal uygulanır.","kaynak":"2918 m.118","zorluk":"orta"},
    {"id":"2918-S-036","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre 'fahri trafik müfettişliği' görevi kim tarafından verilir?","siklar":["İçişleri Bakanı","Vali","Emniyet Genel Müdürü","Karayolu Trafik Güvenliği Üst Kurulu","Kaymakam"],"dogru":1,"aciklama":"Ek m.6: '...Karayolu Trafik Güvenliği Kurulunca önerilen ve Karayolu Trafik Güvenliği Üst Kurulunca uygun görülen kişilere, valilerce fahri trafik müfettişliği görevi verilir.' Görevi bizzat veren makam validir.","kaynak":"2918 Ek m.6","zorluk":"orta"},
    {"id":"2918-S-037","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, buluntu olması nedeniyle veya Kanun hükümleri gereğince trafikten men edilerek alıkonulan araçlar, sahipleri tarafından ....(1).... içinde teslim alınmaz veya aranmazsa Hazinece satılarak bedelleri emanet hesabına alınır. Boşluğa gelmesi gereken süre hangisidir?","siklar":["3 ay","90 gün","6 ay","1 yıl","2 yıl"],"dogru":2,"aciklama":"Ek m.14: '...ancak sahipleri tarafından altı ay içinde teslim alınmayan veya aranmayan araçlar Hazinece satılarak, bedelleri emanet hesabına alınır.' Bekleme süresi altı aydır.","kaynak":"2918 Ek m.14","zorluk":"orta"},
    {"id":"2918-S-038","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre ilk defa sürücü belgesi alanlar en az bir yıl süreyle aday sürücü olarak kabul edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. Ek m.17: 'İlk defa sürücü belgesi alanlar en az bir yıl süre ile aday sürücü olarak kabul edilirler.' Aday sürücülüğün asgari süresi bir yıldır.","kaynak":"2918 Ek m.17","zorluk":"kolay"},
    {"id":"2918-S-039","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, azami yüklü ağırlığı kaç kilogramı geçmeyen römork veya yarı römork 'hafif römork' olarak tanımlanır?","siklar":["750 kg","500 kg","1.000 kg","1.500 kg","3.500 kg"],"dogru":0,"aciklama":"m.3: 'Hafif römork: Azami yüklü ağırlığı 750 Kg'ı geçmeyen römork veya yarı römorkdur.' Eşik 750 kilogramdır.","kaynak":"2918 m.3","zorluk":"orta"},
    {"id":"2918-S-040","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, İl Trafik Komisyonunda yer alan üniversite, oda, vakıf ve kamuya yararlı dernek veya kuruluş temsilcilerinin toplam sayısı ....(1).... geçemez. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["2'yi","3'ü","4'ü","5'i","sınırsızdır"],"dogru":1,"aciklama":"m.12: 'Kuruldaki üniversite, vakıf ve kamuya yararlı dernek veya kuruluşların temsilcilerinin toplam sayısı 3'ü geçemez.' Sabit üyelerin (belediye, emniyet, jandarma, milli eğitim, karayolları, şoförler odası) dışında kalan bu ek temsilciler en çok üç kişidir.","kaynak":"2918 m.12","zorluk":"zor"},
    {"id":"2918-S-041","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre araç tescili ile ilgili aşağıdaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["Askeri maksatla kullanılan TSK araçları — Türk Silahlı Kuvvetlerince","Tarım kesiminde kullanılan özel iş makineleri — ziraat odalarınca","Sanayi kesiminde kullanılan özel iş makineleri — ticaret/sanayi odalarınca","Raylı sistemle çalışan araçlar — ait olduğu kuruluşlarca","Kamu kuruluşlarına ait iş makineleri — İl Trafik Komisyonlarınca"],"dogru":4,"aciklama":"m.22/c-1: 'İş makinesi türünden araçların tescilleri; Kamu kuruluşlarına ait olanlar ilgili kuruluşlarınca...yapılır.' Kamuya ait iş makinesinin tescili kendi ilgili kuruluşuna aittir, İl Trafik Komisyonuna değil; İl Trafik Komisyonu kararı yalnızca belediyelerce tescil edilecek motorsuz taşıtlar için ön şarttır (m.22/d).","kaynak":"2918 m.22","zorluk":"orta"},
    {"id":"2918-S-042","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, başka bir araca ait tescil plakasını veya sahte plakayı takan ya da kullanan sürücüler hakkında idari para cezası ve sürücü belgesi/araç işlemlerinin yanında ayrıca Türk Ceza Kanunu hükümleri de uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.23: '...sahte plakayı takan veya kullananlara...idari para cezası uygulanarak sürücü belgeleri otuz gün süreyle geri alınır ve araç otuz gün süre ile trafikten menedilir...Ayrıca bu kişiler Türk Ceza Kanununun 204 üncü maddesi hükmüne göre cezalandırılır.' TCK atfı açıkça vardır.","kaynak":"2918 m.23","zorluk":"orta"},
    {"id":"2918-S-043","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, araç üzerinde mevzuata uygun şekilde yapılan teknik değişikliğin işleten tarafından araç tescil belgesine/kayıtlarına işletilmesi için tanınan süre kaç gündür?","siklar":["10 gün","15 gün","30 gün","60 gün","90 gün"],"dogru":2,"aciklama":"m.32: 'Araçlar üzerinde mevzuata uygun şekilde yapılan her türlü değişikliğin işleten tarafından otuz gün içinde araç tescil belgesine/kayıtlarına işletilmesi zorunludur.' Süre otuz gündür; işletilmeyen araç tescile işlenene kadar trafikten men edilir.","kaynak":"2918 m.32","zorluk":"orta"},
    {"id":"2918-S-044","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre işaretsiz kavşaklarda geçiş hakkına ilişkin aşağıdakilerden hangisi doğru DEĞİLDİR?","siklar":["Doğru geçen tramvay hattı bulunan yola çıkan sürücü bu yoldan gelen araca yol verir","Dönel kavşağa gelen sürücü, dönel kavşak içindeki araca yol verir","Bir iz veya mülkten çıkan sürücü karayolundan gelen araca yol verir","Işıklı trafik işareti izin verse bile, kavşak içinde durmayı zorunlu kılacaksa sürücünün kavşağa girmesi serbesttir","Aksine işaret olmadıkça bütün kavşaklarda araçlar ray üzerinde hareket eden taşıtlara ilk geçiş hakkını verir"],"dogru":3,"aciklama":"m.57/d: 'Işıklı trafik işaretleri izin verse bile trafik akımı; kendisini kavşak içinde durmaya zorlayacak veya diğer doğrultudaki trafiğin geçişine engel olacak ise, sürücülerin kavşağa girmeleri yasaktır.' D şıkkı bu yasağı 'serbesttir' diyerek tam tersine çevirmiştir; diğer dört şık madde metniyle birebir örtüşür.","kaynak":"2918 m.57","zorluk":"zor"},
    {"id":"2918-S-045","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, taşıt yolunun bir şeridinde bisiklet, elektrikli skuter, motorlu bisiklet ve motosikletlerden kaçından fazlasının yan yana sürülmesi yasaktır?","siklar":["Birden fazlası","Üçten fazlası","İkiden fazlası","Dörtten fazlası","Sayı sınırı yoktur"],"dogru":2,"aciklama":"m.66/a: '...Bunlardan ikiden fazlasının taşıt yolunun bir şeridinde yan yana...sürülmesi yasaktır.' Bir şeritte en fazla iki araç yan yana sürülebilir.","kaynak":"2918 m.66","zorluk":"orta"},
    {"id":"2918-S-046","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, başıboş hayvan bırakma yasağına riayet etmeyerek trafik kazasına sebebiyet veren fail hakkında ....(1).... uygulanır. Boşluğa gelmesi gereken yaptırım hangisidir?","siklar":["Yalnızca idari para cezası","Sürücü belgesinin iptali","Altı ay hafif hapis cezası","Üç ay hafif hapis cezası","Aracın süresiz men edilmesi"],"dogru":3,"aciklama":"m.69: 'Bu madde hükümlerine uymayanlar...para cezası ile cezalandırılırlar. Ancak, başıboş hayvan bırakma yasağına riayet etmeyerek trafik kazasına sebebiyet veren faile üç ay hafif hapis cezası uygulanır.' Kazaya sebebiyet halinde yaptırım idari para cezasının ötesine geçip hafif hapse dönüşür.","kaynak":"2918 m.69","zorluk":"orta"},
    {"id":"2918-S-047","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, yalnızca bir il sınırı içindeki karayolları üzerinde yapılacak yarış ve koşular için izin hangi makamdan alınır?","siklar":["O ilin valiliğinden","İçişleri Bakanlığından","Ulaştırma ve Altyapı Bakanlığından","İl Trafik Komisyonundan","Türkiye Şoförler ve Otomobilciler Federasyonundan"],"dogru":0,"aciklama":"m.70/a: 'Bir il sınırı içindeki karayolları üzerinde yapılacak yarış ve koşular için o ilin valiliğinden...izin alınması zorunludur.' Birden fazla il/milletlerarası yarışta ise izin İçişleri Bakanlığından alınır (b bendi).","kaynak":"2918 m.70","zorluk":"orta"},
    {"id":"2918-S-048","soru":"2918 sayılı Karayolları Trafik Kanunu'nun 84. maddesine göre, trafik kazasında şeride tecavüz eden sürücü hakkında hangi sonuç doğar?","siklar":["Kusur oranı doğrudan yönetmelikte belirtilen esaslara göre serbestçe belirlenir, asli kusur aranmaz","Sadece idari para cezasına tabi tutulur, kusur tayini yapılmaz","Yalnızca tali kusurlu sayılır","Kusursuz sayılır","Asli kusurlu sayılır"],"dogru":4,"aciklama":"m.84/g: '...g) Şeride tecavüz etme...Hallerinde asli kusurlu sayılırlar.' Şeride tecavüz, kırmızı ışıkta geçme ve arkadan çarpma gibi doğrudan asli kusur hallerinden biridir.","kaynak":"2918 m.84","zorluk":"zor"},
    {"id":"2918-S-049","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, bir motorlu aracı çalan veya gasbeden kimse işleten gibi sorumlu tutulur; ancak işleten, kendisinin veya eylemlerinden sorumlu olduğu kişilerden birinin aracın çalınmasında veya gasbedilmesinde kusurlu olmadığını ispat ederse sorumlu tutulamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.107: 'Bir motorlu aracı çalan veya gasbeden kimse işleten gibi sorumlu tutulur...İşleten, kendisinin veya eylemlerinden sorumlu olduğu kişilerden birinin, aracın çalınmasında veya gasbedilmesinde kusurlu olmadığını ispat ederse, sorumlu tutulamaz.' İfade maddeyle birebir örtüşür.","kaynak":"2918 m.107","zorluk":"orta"},
    {"id":"2918-S-050","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, tutanağın tebliğ tarihinden itibaren bir ay içinde ödenmeyen trafik idari para cezalarına uygulanan aylık faiz oranı ve bu suretle bulunacak tutarın tavanı aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["Aylık %5 faiz, cezanın iki katını geçemez","Aylık %10 faiz, cezanın üç katını geçemez","Aylık %2 faiz, cezanın iki katını geçemez","Aylık %5 faiz, tavan yoktur","Aylık %1 faiz, cezanın beş katını geçemez"],"dogru":0,"aciklama":"m.115: 'Bir ay içinde ödenmeyen cezalar için her ay % 5 faiz uygulanır...Bu suretle bulunacak tutar cezanın iki katını geçemez.' Süresinde ödenmeyen ceza için 6183 sayılı Kanun hükümleri uygulanır.","kaynak":"2918 m.115","zorluk":"orta"},
    {"id":"2918-S-051","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, olağanüstü hallerde ve savaşta karayolunun kullanılması, trafiğin düzenlenmesi ve yönetimi esasları hangi kurumun görüşü alınarak yönetmelikte belirtilir?","siklar":["İçişleri Bakanlığı","Milli Savunma Bakanlığı","Genelkurmay Başkanlığı","Ulaştırma ve Altyapı Bakanlığı","Karayolları Genel Müdürlüğü"],"dogru":2,"aciklama":"m.126: 'Olağanüstü hallerde ve savaşta karayolunun kullanılması, trafiğin düzenlenmesi ve yönetimi esasları Genelkurmay Başkanlığının görüşü alınarak yönetmelikte belirtilir. Barışta...manevra ve tatbikatlarda Genelkurmay Başkanlığının istemi üzerine özel uygulamalar yapılabilir.'","kaynak":"2918 m.126","zorluk":"orta"},
    {"id":"2918-S-052","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, yolcu taşımacılığı yapan otobüs ve benzeri taşıtların karıştığı ölümlü trafik kazasında, kusurlu sürücü ve araç plakası ile birlikte otobüs işleticisi teşebbüsün unvanının kusur oranından söz edilmeksizin basın yoluyla kamuoyuna duyurulması, sırrın ifşaı veya ticari itibarın ihlali sayılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek m.4: '...kusurlu araç veya araçları kullanan sürücü ve araca ait plaka numaraları ile birlikte otobüs işleticisi teşebbüsün unvanının...kusur oranlarından söz edilmeksizin ilanı, sırrın ifşaı ve ticari itibarın ihlali sayılmaz.' Kanun bu ilanı açıkça hukuka uygun kabul eder.","kaynak":"2918 Ek m.4","zorluk":"kolay"},
    {"id":"2918-S-053","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, belediyelerce kendi bütçe kaynaklarıyla kurulan ve Emniyet Genel Müdürlüğünce trafik ihlallerinin tespitinde kullanılan elektronik sistemler için, düzenlenen trafik idari yaptırım karar tutanaklarındaki idari para cezasının kaçta kaçı, kural olarak sistem kullanım hizmet bedeli olarak ilgili belediyeye ödenir?","siklar":["%10'u","%15'i","%20'si","%30'u","%50'si"],"dogru":3,"aciklama":"Ek m.16: '...trafik idari yaptırım karar tutanaklarında yer alan trafik idari para cezasının % 30'u oranındaki tutar, izleyen ayın sonuna kadar Emniyet Genel Müdürlüğü bütçesinden ilgili belediyelere sistem kullanımı hizmet bedeli olarak ödenir.' (Hasılat paylaşımı modelinde yatırım maliyeti karşılandıktan sonra bu oran %15'e düşer.)","kaynak":"2918 Ek m.16","zorluk":"zor"},
    {"id":"2918-S-054","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, noterler tarafından yapılan araç satış ve devir işlemi, siciline işlenmek üzere ....(1).... içerisinde ilgili trafik tescil kuruluşu ile vergi dairesine bildirilir ve bu bildirimle birlikte alıcı adına trafik tescil işlemi gerçekleşmiş sayılır. Boşluğa gelmesi gereken süre hangisidir?","siklar":["bir iş günü","üç iş günü","beş iş günü","on gün","bir ay"],"dogru":1,"aciklama":"m.20/d: 'Satış ve devir işlemi, siciline işlenmek üzere üç işgünü içerisinde ilgili trafik tescil kuruluşu ile vergi dairesine bildirilir. Bu bildirimle birlikte alıcı adına trafik tescil işlemi gerçekleşmiş sayılır.' Bildirim süresi üç iş günüdür.","kaynak":"2918 m.20","zorluk":"zor"},
    {"id":"2918-S-055","soru":"2918 sayılı Karayolları Trafik Kanunu'na göre, tarım kesiminde kullanılanlar hariç olmak üzere motorsuz taşıtlardan gerekli görülenlerin belediyelerce tescil edilebilmesi için hangi şart aranır?","siklar":["Ticaret ve sanayi odasının onayı","İl Trafik Komisyonundan karar alınması","Vali onayı","Emniyet Genel Müdürlüğünün izni","Ziraat odasının uygun görüşü"],"dogru":1,"aciklama":"m.22/d: 'Tarım kesiminde kullanılanlar hariç, İl Trafik Komisyonlarından karar alınmak şartı ile motorsuz taşıtlardan gerekli görülenlerin tescilleri belediyelerce...yapılır.' Belediyece tescilin ön şartı İl Trafik Komisyonu kararıdır.","kaynak":"2918 m.22","zorluk":"orta"},
  ],
  35: [
    {"id":"5188-S-001","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik komisyonu kimin başkanlığında oluşur?","siklar":["Valinin görevlendireceği bir vali yardımcısı","İl emniyet müdürü","İl jandarma komutanı","Mahalli mülki amir","Vali"],"dogru":0,"aciklama":"m.4: 'Özel güvenlik komisyonu, ... valinin görevlendireceği bir vali yardımcısının başkanlığında ... oluşur.' Komisyona bir vali yardımcısı başkanlık eder.","kaynak":"5188 m.4","zorluk":"kolay"},
    {"id":"5188-S-002","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik komisyonu üyeleri, kararların oylanmasında çekimser oy kullanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4: 'Komisyon, kararlarını oy çokluğu ile alır; oyların eşitliği halinde başkanın bulunduğu taraf çoğunluk sayılır; çekimser oy kullanılamaz.' Çekimser oy açıkça yasaktır.","kaynak":"5188 m.4","zorluk":"orta"},
    {"id":"5188-S-003","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre aşağıdakilerden hangisi özel güvenlik komisyonunun oluşumunda yer alan temsilciler arasında sayılmamıştır?","siklar":["İl emniyet müdürlüğü temsilcisi","İl jandarma komutanlığı temsilcisi","Cumhuriyet başsavcılığı temsilcisi","Ticaret odası başkanlığı temsilcisi","Sanayi odası başkanlığı temsilcisi"],"dogru":2,"aciklama":"m.4: Komisyon, vali yardımcısı başkanlığında 'il emniyet müdürlüğü, il jandarma komutanlığı, ticaret odası başkanlığı, sanayi odası başkanlığı temsilcisinden oluşur.' Cumhuriyet başsavcılığı temsilcisi bu sayımda yer almaz.","kaynak":"5188 m.4","zorluk":"orta"},
    {"id":"5188-S-004","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre şirketlerin özel güvenlik alanında faaliyette bulunması hangi makamın iznine tâbidir?","siklar":["Valiliğin","Özel güvenlik komisyonunun","Emniyet Genel Müdürlüğünün","İçişleri Bakanlığının","Mahalli mülki amirin"],"dogru":3,"aciklama":"m.5: 'Şirketlerin özel güvenlik alanında faaliyette bulunması İçişleri Bakanlığının iznine tâbidir.' Faaliyet izni merkezî olarak Bakanlıktan alınır.","kaynak":"5188 m.5","zorluk":"kolay"},
    {"id":"5188-S-005","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik şirketleri şubelerini ve hisse devirlerini ....(1).... içinde Bakanlığa bildirir; kurucu, temsilci ve yöneticilerde aranan şartların kaybedilmesi halinde ....(2).... içinde eksiklik giderilmez veya bunlar değiştirilmezse faaliyet izni iptal edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki ay - bir ay","bir ay - bir ay","onbeş gün - bir ay","iki ay - üç ay","bir ay - iki ay"],"dogru":4,"aciklama":"m.5: Şirketler 'şubelerini bir ay içinde Bakanlığa ve ilgili valiliğe ...; hisse devirlerini bir ay içinde Bakanlığa bildirirler.' Ayrıca 'şartların kaybedilmesi halinde iki ay içinde eksiklik giderilmediği veya ... değiştirilmediği takdirde faaliyet izni iptal edilir.' Bildirim 1 ay, şart giderme 2 aydır.","kaynak":"5188 m.5","zorluk":"zor"},
    {"id":"5188-S-006","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre aşağıdakilerden hangisi özel güvenlik görevlilerinin yetkileri arasında sayılmamıştır?","siklar":["Görev alanı dışında şüphelileri gözaltına alıp ifadesini alma","Ceza Muhakemesi Kanununun 90 ıncı maddesine göre yakalama","Terk edilmiş ve bulunmuş eşyayı emanete alma","Görev alanında, hakkında yakalama emri veya mahkûmiyet kararı bulunan kişileri yakalama ve arama","Genel kolluğa derhal bildirmek şartıyla, tehlike doğurabilecek eşyayı emanete alma"],"dogru":0,"aciklama":"m.7'de sayılan yetkiler arasında CMK 90'a göre yakalama (b/c), görev alanında yakalama emri/mahkûmiyet kararı olanları yakalama-arama (d), terk/bulunmuş eşyayı emanete alma (h) ve genel kolluğa derhal bildirmek şartıyla eşyayı emanete alma (g) vardır. 'Görev alanı dışında gözaltına alıp ifade alma' yetkisi yoktur; yetkiler görev alanıyla sınırlıdır ve ifade alma genel kolluğun/yargının işidir.","kaynak":"5188 m.7","zorluk":"orta"},
    {"id":"5188-S-007","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik görevlisi, aramalar sırasında suç teşkil eden veya delil olabilecek ya da tehlike doğurabilecek eşyayı hangi şartla emanete alabilir?","siklar":["Cumhuriyet savcısına 24 saat içinde bildirmek şartıyla","Genel kolluk kuvvetlerine derhal bildirmek şartıyla","Mahalli mülki amire ertesi gün bildirmek şartıyla","Şirket yöneticisine derhal bildirmek şartıyla","İlgili valiliğe bir hafta içinde bildirmek şartıyla"],"dogru":1,"aciklama":"m.7/g: 'Genel kolluk kuvvetlerine derhal bildirmek şartıyla, aramalar sırasında suç teşkil eden veya delil olabilecek ya da suç teşkil etmemekle birlikte tehlike doğurabilecek eşyayı emanete alma.' Şart: genel kolluğa DERHAL bildirim.","kaynak":"5188 m.7","zorluk":"orta"},
    {"id":"5188-S-008","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre silahlı olarak görev yapacak özel güvenlik görevlilerinde aranan asgari öğrenim şartı aşağıdakilerden hangisidir?","siklar":["En az sekiz yıllık ilköğretim veya ortaokul mezunu olmak","İlkokul mezunu olmak","En az lise veya dengi okul mezunu olmak","En az önlisans mezunu olmak","En az lisans mezunu olmak"],"dogru":2,"aciklama":"m.10/b: 'Silahsız olarak görev yapacaklar için en az sekiz yıllık ilköğretim veya ortaokul; silahlı olarak görev yapacaklar için en az lise veya dengi okul mezunu olmak.' Silahlıda asgari şart lise/dengi okuldur.","kaynak":"5188 m.10","zorluk":"orta"},
    {"id":"5188-S-009","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre aşağıdakilerden hangisi özel güvenlik görevlilerinde aranan şartlardan biri değildir?","siklar":["Türkiye Cumhuriyeti vatandaşı olmak","18 yaşını doldurmuş olmak","Güvenlik soruşturmasının olumlu olması","Erkek adaylar için askerlik hizmetini tamamlamış olmak","14 üncü maddede belirtilen özel güvenlik temel eğitimini başarıyla tamamlamış olmak"],"dogru":3,"aciklama":"m.10'da aranan şartlar arasında T.C. vatandaşlığı (a), 18 yaşını doldurmuş olma (c), temel eğitimi başarıyla tamamlama (g) ve güvenlik soruşturmasının olumlu olması (h) sayılmıştır. 'Askerlik hizmetini tamamlamış olmak' m.10'da bir şart olarak yer almaz.","kaynak":"5188 m.10","zorluk":"orta"},
    {"id":"5188-S-010","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik temel eğitimi ....(1).... ders saatinden, yenileme eğitimi ....(2).... ders saatinden az olmamak üzere düzenlenir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["altmış - yüz yirmi","yüz - elli","doksan - altmış","yüz yirmi - otuz","yüz yirmi - altmış"],"dogru":4,"aciklama":"m.14: 'Özel güvenlik temel eğitimi ... yüz yirmi ders saatinden; yenileme eğitimi altmış ders saatinden az olmamak üzere düzenlenir.' Temel 120, yenileme 60 ders saatidir.","kaynak":"5188 m.14","zorluk":"orta"},
    {"id":"5188-S-011","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik personeli greve katılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.17: 'Özel güvenlik personeli greve katılamaz.' Yasak istisnasızdır.","kaynak":"5188 m.17","zorluk":"kolay"},
    {"id":"5188-S-012","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik iznini almadan özel güvenlik görevlisi istihdam eden kişiler veya kuruluşların yöneticileri hakkında öngörülen yaptırım aşağıdakilerden hangisidir?","siklar":["Üç aydan bir yıla kadar hapis veya adlî para cezası","Bir yıldan üç yıla kadar hapis cezası","Beşbin Türk Lirası idari para cezası","Altı aya kadar hapis cezası","Üçbin Türk Lirası idari para cezası"],"dogru":0,"aciklama":"m.19/a: '... özel güvenlik iznini almadan özel güvenlik görevlisi istihdam eden kişiler veya kuruluşların yöneticileri üç aydan bir yıla kadar hapis veya adlî para cezası ile cezalandırılır.' Bu, mahkemece hükmedilen adlî bir cezadır.","kaynak":"5188 m.19","zorluk":"orta"},
    {"id":"5188-S-013","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'da öngörülen idari para cezaları ve yaptırımlar kim tarafından verilir?","siklar":["Vali","Cumhuriyet savcısı","Mahalli mülki amir","Sulh ceza hâkimi","İçişleri Bakanı"],"dogru":2,"aciklama":"m.20 son fıkra: 'Bu maddede öngörülen cezalar mahalli mülki amir tarafından verilir.' İdari para cezaları/yaptırımlar mahalli mülki amirin yetkisindedir.","kaynak":"5188 m.20","zorluk":"kolay"},
    {"id":"5188-S-014","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre aşağıdaki fiillerden hangisi, mahalli mülki amirce verilen idari para cezası/yaptırım kapsamında değil, mahkemece hükmedilen adlî bir suç ve ceza kapsamındadır?","siklar":["Özel güvenlik kimlik kartını başkasına kullandırmak","Denetim sırasında istenen bilgi, belge ve kayıtları vermemek","Grev yasağına uymamak","Özel güvenlik iznini almadan özel güvenlik görevlisi istihdam etmek","Mülki idare amirince istenen ilave tedbirleri almamak"],"dogru":3,"aciklama":"İzinsiz istihdam m.19/a'da 'adlî suçlar ve cezalar' arasında sayılır ve hapis/adlî para cezası ile mahkemece cezalandırılır. Diğer şıklar m.20'deki idari para cezası/yaptırım fiilleridir (kimlik kartı kullandırma m.20/a, denetimde belge vermeme m.20/e, grev yasağı ihlali m.20/ı, ilave tedbir almama m.20/c) ve mahalli mülki amirce verilir.","kaynak":"5188 m.19","zorluk":"zor"},
    {"id":"5188-S-015","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre genel kolluk kuvvetlerinden ve Milli İstihbarat Teşkilatından emekli olanlarda özel güvenlik temel eğitimi şartı aranmaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.14: 'Genel kolluk kuvvetlerinden ve Milli İstihbarat Teşkilatından emekli olanlar ile en az beş yıl bu görevlerde çalıştıktan sonra kendi istekleriyle görevlerinden ayrılmış olanlarda, özel güvenlik temel eğitimi şartı ve Kanunun 10 uncu maddesinin birinci fıkrasının (b) bendinde belirtilen eğitim şartı aranmaz.' Emekli olanlar için '5 yıl' koşulu aranmaz.","kaynak":"5188 m.14","zorluk":"orta"},
    {"id":"5188-S-016","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik kimlik kartını başkasına kullandıran özel güvenlik görevlisi hakkında uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["Sadece kınama cezası verilir, başka bir yaptırım uygulanmaz","Altıbin Türk Lirası idari para cezası verilir, ancak kimlik kartı iptal edilmez","Üç aydan bir yıla kadar hapis cezası verilir","Beşbin Türk Lirası idari para cezası verilir ve altı ay görev veremez","Üçbin Türk Lirası idari para cezası verilir, kimlik kartı valilikçe iptal edilir ve bir daha özel güvenlik alanında çalışamaz"],"dogru":4,"aciklama":"m.20/a: 'Özel güvenlik kimlik kartını başkasına kullandıran özel güvenlik yöneticisi ve görevlisine üçbin Türk Lirası idari para cezası verilir ve bu kişilerin özel güvenlik kimlik kartı valilikçe iptal edilir. Bu kişiler bir daha özel güvenlik alanında çalışamazlar.' Üç yaptırım birlikte: 3.000 TL + kart iptali + kalıcı yasak.","kaynak":"5188 m.20","zorluk":"zor"},
    {"id":"5188-S-017","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre yabancı kişilerin özel güvenlik şirketi kurabilmesi ve yabancı şirketlerin Türkiye'de özel güvenlik hizmeti verebilmesi hangi esasa tâbidir?","siklar":["Karşılıklılık (mütekabiliyet) esasına","İçişleri Bakanlığının özel iznine","Dışişleri Bakanlığı onayına","Cumhurbaşkanlığı kararnamesine","Uluslararası anlaşma şartına"],"dogru":0,"aciklama":"m.5: 'Yabancı kişilerin özel güvenlik şirketi kurabilmesi ve yabancı şirketlerin Türkiye'de özel güvenlik hizmeti verebilmesi mütekabiliyet esasına tâbidir.'","kaynak":"5188 m.5","zorluk":"kolay"},
    {"id":"5188-S-018","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik şirketlerinin şubelerinde veya ....(1).... kişi ve üzerinde özel güvenlik görevlisi istihdam edilen yerlerde en az bir güvenlik sorumlusu belirlenir; güvenlik sorumlularında 10 uncu maddedeki şartlara ilave olarak en az ....(2).... mezunu olma şartı aranır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on - lisans","onbeş - önlisans","yirmi - lisans","onbeş - lisans","on - önlisans"],"dogru":1,"aciklama":"m.5: '...Özel güvenlik birimleri veya özel güvenlik şirketlerinin şubelerinde veya onbeş kişi ve üzerinde özel güvenlik görevlisi istihdam edilen yerlerde en az bir güvenlik sorumlusu belirlenir. Güvenlik sorumlularında 10 uncu maddede belirtilen şartlara ilave olarak en az önlisans mezunu olma şartı aranır.'","kaynak":"5188 m.5","zorluk":"zor"},
    {"id":"5188-S-019","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik şirketi yöneticilerinde, 10 uncu maddede sayılan genel şartlara ilave olarak hangi şart aranır?","siklar":["En az önlisans mezunu olmak","Kamu görevinde en az beş yıl çalışmış olmak","En az lisans mezunu olmak ve özel güvenlik temel eğitimini başarıyla tamamlamış olmak","Yabancı dil bilgisi belgesine sahip olmak","Askerlik hizmetini yapmış olmak"],"dogru":2,"aciklama":"m.5: 'Yöneticilerin ayrıca lisans mezunu olmaları ve 14 üncü maddede belirtilen özel güvenlik temel eğitimini başarıyla tamamlamış olmaları gerekir.'","kaynak":"5188 m.5","zorluk":"orta"},
    {"id":"5188-S-020","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik görevlileri, hangi durumda görev alanındaki işyeri ve konutlara girme yetkisine sahiptir?","siklar":["Şüpheli bir ihbar alındığında","Genel kolluğun izni olmadan da her durumda","Mesai saatleri dışında rutin devriye sırasında","Yangın, deprem gibi tabiî afet durumlarında ve imdat istenmesi halinde","Şirket yöneticisinin yazılı talimatı üzerine her zaman"],"dogru":3,"aciklama":"m.7/e: 'Yangın, deprem gibi tabiî afet durumlarında ve imdat istenmesi halinde görev alanındaki işyeri ve konutlara girme.'","kaynak":"5188 m.7","zorluk":"kolay"},
    {"id":"5188-S-021","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik görevlileri, hava meydanı, liman, gar, istasyon ve terminal gibi toplu ulaşım tesislerinde hangi yetkiye sahiptir?","siklar":["Yolculardan seyahat izin belgesi isteme","Bagaj ücreti tahsil etme","Bilet kontrolü yapıp para cezası kesme","Yolcuları gözaltına alma","Kimlik sorma, duyarlı kapıdan geçirme, üstünü dedektörle arama ve eşyaları X-ray cihazından geçirme"],"dogru":4,"aciklama":"m.7/f: 'Hava meydanı, liman, gar, istasyon ve terminal gibi toplu ulaşım tesislerinde kimlik sorma, duyarlı kapıdan geçirme, bu kişilerin üstlerini dedektörle arama, eşyaları X-ray cihazından veya benzeri güvenlik sistemlerinden geçirme.'","kaynak":"5188 m.7","zorluk":"orta"},
    {"id":"5188-S-022","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre kasten işlenen bir suçtan dolayı ne kadar veya daha fazla süreyle hapis cezasına mahkûm olanlar özel güvenlik görevlisi olamaz?","siklar":["Bir yıl","Altı ay","İki yıl","Üç yıl","Beş yıl"],"dogru":0,"aciklama":"m.10/d-1: 'Kasten işlenen bir suçtan dolayı bir yıl veya daha fazla süreyle hapis cezasına mahkûm olmamak.'","kaynak":"5188 m.10","zorluk":"zor"},
    {"id":"5188-S-023","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre yükseköğretim kurumlarının güvenlikle ilgili fakülte veya meslek yüksekokullarından mezun olanlar, silah eğitimi dahil olmak üzere özel güvenlik temel eğitiminin tamamından muaftır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.14: '...mezun olanlarda silah eğitimi dışında özel güvenlik temel eğitimi şartı aranmaz.' Muafiyet yalnızca silah eğitimi HARİÇ diğer kısımlar içindir; silah eğitimi bu grup için de zorunlu kalır.","kaynak":"5188 m.14","zorluk":"orta"},
    {"id":"5188-S-024","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik eğitimi kimler tarafından verilebilir?","siklar":["Yalnızca valiliklerce","İçişleri Bakanlığınca ücreti karşılığında veya Bakanlıktan faaliyet izni alan özel eğitim kurumlarınca","Yalnızca üniversitelerin güvenlik bölümlerince","Yalnızca özel güvenlik şirketlerinin kendi bünyesinde","Yalnızca büyükşehir belediyelerince"],"dogru":1,"aciklama":"m.14: 'Özel güvenlik eğitimi, ücreti karşılığında İçişleri Bakanlığınca verilebileceği gibi, Bakanlıktan faaliyet izni alan özel eğitim kurumlarınca da verilebilir.'","kaynak":"5188 m.14","zorluk":"kolay"},
    {"id":"5188-S-025","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre faaliyet iznini almadan özel güvenlik faaliyetinde bulunan şirketlerin kurucu ve yöneticileri ....(1).... hapis ve ....(2).... adlî para cezası ile cezalandırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["altı aydan iki yıla kadar - üçbin güne kadar","üç aydan bir yıla kadar - ikibin güne kadar","üç aydan bir yıla kadar - beşbin güne kadar","bir yıldan üç yıla kadar - beşbin güne kadar","altı aya kadar - elli günden az olmamak üzere"],"dogru":2,"aciklama":"m.19/b: '...üç aydan bir yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. Bu şekilde cezalandırılan kişiler, özel güvenlik şirketlerinde ve özel güvenlik eğitimi veren kurumlarda kurucu ve yönetici olamazlar.'","kaynak":"5188 m.19","zorluk":"zor"},
    {"id":"5188-S-026","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre özel güvenlik malî sorumluluk sigortasını yaptırmadan özel güvenlik görevlisi istihdam eden kişi, kurum, kuruluş veya şirketlerin yöneticileri hakkında öngörülen yaptırım aşağıdakilerden hangisidir?","siklar":["Üç aydan bir yıla kadar hapis cezası","Altıbin Türk Lirası idari para cezası","Bir yıl süreyle görev yasağı","İstihdam ettikleri her kişi için yüzelli gün adlî para cezası","Kimlik kartının iptali"],"dogru":3,"aciklama":"m.19/d: '...özel güvenlik malî sorumluluk sigortasını yaptırmadan özel güvenlik görevlisi istihdam eden kişi; kurum, kuruluş veya şirketlerin yöneticileri istihdam ettikleri her kişi için yüzelli gün adlî para cezası ile cezalandırılır.'","kaynak":"5188 m.19","zorluk":"orta"},
    {"id":"5188-S-027","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre faaliyet iznini almadan özel güvenlik hizmeti veya özel güvenlik eğitimi verdiğini ilân eden veya reklam yapan kişi, kurum, kuruluş veya şirketlerin yöneticileri hakkında öngörülen ceza aşağıdakilerden hangisidir?","siklar":["Üç aydan bir yıla kadar hapis ve beşbin güne kadar adlî para cezası","Yüzelli gün adlî para cezası","Üçbin Türk Lirası idari para cezası","Bir yıl süreyle özel güvenlik alanında görev yasağı","Altı aya kadar hapis ve elli günden az olmamak üzere adlî para cezası"],"dogru":4,"aciklama":"m.19/e: '...faaliyet iznini almadan özel güvenlik hizmeti veya özel güvenlik eğitimi verdiğini ilân eden veya reklam yapan kişi; kurum, kuruluş veya şirketlerin yöneticileri, altı aya kadar hapis ve elli günden az olmamak üzere adlî para cezası ile cezalandırılır.'","kaynak":"5188 m.19","zorluk":"orta"},
    {"id":"5188-S-028","soru":"5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun'a göre mülki idare amirinin veya birlikte görev yapılan yetkili genel kolluk amirinin verdiği emirleri yerine getirmeyen veya öğrendiği bir suçu yetkili genel kolluğa bildirmeyen özel güvenlik yöneticisi ve görevlisi hakkında uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["Bir yıl süreyle özel güvenlik alanında görev alamama","Altı ay süreyle özel güvenlik alanında görev alamama","Üçbin Türk Lirası idari para cezası","Kimlik kartının valilikçe iptali ve kalıcı çalışma yasağı","Üç aydan bir yıla kadar hapis cezası"],"dogru":0,"aciklama":"m.20/d: '...emirleri yerine getirmeyen veya bir suçun işlendiğini göreviyle bağlantılı olarak öğrenip de bu suç ile ilgili yetkili genel kolluğa bilgi vermeyen özel güvenlik yöneticisi ve görevlileri ... bir yıl süreyle özel güvenlik alanında görev alamazlar.'","kaynak":"5188 m.20","zorluk":"orta"},
  ],
  36: [
    {"id":"5395-S-001","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre 'çocuk' kavramı nasıl tanımlanmıştır?","siklar":["Onaltı yaşını doldurmamış kişi","Oniki yaşını doldurmamış kişi","Onsekiz yaşından küçük ve evli olmayan kişi","Onsekiz yaşını doldurmamış kişi, daha erken yaşta ergin olsa bile","Yirmi bir yaşını doldurmamış kişi"],"dogru":3,"aciklama":"m.3/a: 'Çocuk: Daha erken yaşta ergin olsa bile, onsekiz yaşını doldurmamış kişiyi ... ifade eder.' Yaş sınırı 18'dir ve erken erginlik bu sınırı değiştirmez.","kaynak":"5395 m.3","zorluk":"kolay"},
    {"id":"5395-S-002","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdakilerden hangisi 'korunma ihtiyacı olan çocuk' tanımına girer?","siklar":["Kanunlarda suç olarak tanımlanan bir fiili işlediği iddiasıyla hakkında soruşturma yürütülen çocuk","Hakkında güvenlik tedbirine karar verilen çocuk","On beş yaşını doldurmamış çocuk","Bedensel, zihinsel, ahlaki, sosyal ve duygusal gelişimi ile kişisel güvenliği tehlikede olan, ihmal veya istismar edilen ya da suç mağduru çocuk","Denetim altına alınan çocuk"],"dogru":3,"aciklama":"m.3/a-1: 'Korunma ihtiyacı olan çocuk: Bedensel, zihinsel, ahlaki, sosyal ve duygusal gelişimi ile kişisel güvenliği tehlikede olan, ihmal veya istismar edilen ya da suç mağduru çocuğu' ifade eder.","kaynak":"5395 m.3","zorluk":"orta"},
    {"id":"5395-S-003","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre 'suça sürüklenen çocuk' yalnızca hakkında kesinleşmiş mahkûmiyet kararı bulunan çocuğu ifade eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/a-2: 'Suça sürüklenen çocuk: Kanunlarda suç olarak tanımlanan bir fiili işlediği iddiası ile hakkında soruşturma veya kovuşturma yapılan ya da işlediği fiilden dolayı hakkında güvenlik tedbirine karar verilen çocuğu' ifade eder. Tanım kesinleşmiş mahkûmiyetle sınırlı değildir; soruşturma/kovuşturma aşamasındaki çocuğu da kapsar.","kaynak":"5395 m.3","zorluk":"kolay"},
    {"id":"5395-S-004","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdakilerden hangisi koruyucu ve destekleyici tedbirlerden biri değildir?","siklar":["Danışmanlık","Eğitim","Bakım","Sağlık","Denetim altına alınma"],"dogru":4,"aciklama":"m.5/1: 'Koruyucu ve destekleyici tedbirler ... danışmanlık, eğitim, bakım, sağlık ve barınma konularında alınacak tedbirlerdir.' Denetim altına alınma, m.7/4 uyarınca hâkimin tedbirle BİRLİKTE ayrıca karar verebileceği farklı bir kurumdur; m.5'teki beş tedbirden biri değildir.","kaynak":"5395 m.5","zorluk":"orta"},
    {"id":"5395-S-005","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre barınma tedbiri uygulanan kimselerin, talepleri hâlinde kimlik ve adresleri gizli tutulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5/2: 'Hakkında, birinci fıkranın (e) bendinde tanımlanan barınma tedbiri uygulanan kimselerin, talepleri hâlinde kimlikleri ve adresleri gizli tutulur.'","kaynak":"5395 m.5","zorluk":"orta"},
    {"id":"5395-S-006","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdakilerden hangisi, korunma ihtiyacı olan çocuğu Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirmekle YÜKÜMLÜ olanlar arasında sayılmamıştır?","siklar":["Adlî ve idarî merciler","Kolluk görevlileri","Sağlık kuruluşları","Eğitim kuruluşları","Çocuğun bakımından sorumlu kimseler"],"dogru":4,"aciklama":"m.6/1: 'Adlî ve idarî merciler, kolluk görevlileri, sağlık ve eğitim kuruluşları, sivil toplum kuruluşları ... bildirmekle yükümlüdür. Çocuk ile çocuğun bakımından sorumlu kimseler ... Kuruma başvurabilir.' Bakımdan sorumlu kimseler için bildirim değil BAŞVURU imkânı öngörülmüştür; yükümlülük değildir.","kaynak":"5395 m.6","zorluk":"orta"},
    {"id":"5395-S-007","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuklar hakkında koruyucu ve destekleyici tedbir kararını kim verir?","siklar":["Sosyal Hizmetler ve Çocuk Esirgeme Kurumu","Cumhuriyet savcısı","Vali","Aile mahkemesi hâkimi","Çocuk hâkimi"],"dogru":4,"aciklama":"m.7/1: 'Çocuklar hakkında koruyucu ve destekleyici tedbir kararı; ... istemi üzerine veya re'sen çocuk hâkimi tarafından alınabilir.' Kararı veren tek makam çocuk hâkimidir.","kaynak":"5395 m.7","zorluk":"kolay"},
    {"id":"5395-S-008","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre tedbirin uygulanması onsekiz yaşın doldurulmasıyla kendiliğinden sona erer; hâkim hiçbir şekilde bu süreyi uzatamaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7/6: 'Tedbirin uygulanması, onsekiz yaşın doldurulmasıyla kendiliğinden sona erer. Ancak hâkim, eğitim ve öğrenimine devam edebilmesi için ve rızası alınmak suretiyle tedbirin uygulanmasına belli bir süre daha devam edilmesine karar verebilir.' Uzatma istisnası vardır.","kaynak":"5395 m.7","zorluk":"orta"},
    {"id":"5395-S-009","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre tedbir kararlarının uygulanması, kararı veren hâkim veya mahkemece en geç ....(1).... sürelerle incelettirilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["birer aylık","altışar aylık","yıllık","ikişer aylık","üçer aylık"],"dogru":4,"aciklama":"m.8/2: 'Tedbir kararlarının uygulanması, kararı veren hâkim veya mahkemece en geç üçer aylık sürelerle incelettirilir.' İnceleme periyodu üç aydır.","kaynak":"5395 m.8","zorluk":"orta"},
    {"id":"5395-S-010","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre acil korunma kararının alınması için Kurum, çocuğun geldiği tarihten itibaren en geç ....(1).... çocuk hâkimine müracaat eder; hâkim ....(2).... talep hakkında karar verir; acil korunma kararı en fazla ....(3).... süreyle sınırlı olarak verilebilir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["üç gün - beş gün - otuz gün içinde","beş gün - üç gün - on beş gün içinde","yedi gün - üç gün - otuz gün içinde","beş gün - üç gün - otuz gün içinde","beş gün - beş gün - otuz gün içinde"],"dogru":3,"aciklama":"m.9/1-2: '...en geç beş gün içinde çocuk hâkimine müracaat edilir. Hâkim tarafından, üç gün içinde talep hakkında karar verilir.' m.9/2: 'Acil korunma kararı en fazla otuz günlük süre ile sınırlı olmak üzere verilebilir.' Sıra: 5 gün - 3 gün - 30 gün.","kaynak":"5395 m.9","zorluk":"zor"},
    {"id":"5395-S-011","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre acil korunma kararını hangi makam verir?","siklar":["Sosyal Hizmetler ve Çocuk Esirgeme Kurumu","Mahalli mülki amir","Çocuk hâkimi","Cumhuriyet savcısı","Çocuk ağır ceza mahkemesi"],"dogru":2,"aciklama":"m.9/1: 'Hâkim tarafından, üç gün içinde talep hakkında karar verilir.' Kurum çocuğu bakım/gözetim altına alıp hâkime müracaat eder, ancak kararı veren makam çocuk hâkimidir.","kaynak":"5395 m.9","zorluk":"orta"},
    {"id":"5395-S-012","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre suça sürüklenen çocuk hakkındaki soruşturma kim tarafından bizzat yapılır?","siklar":["Çocuk bürosunda görevli Cumhuriyet savcısı","Çocuk hâkimi","Sosyal çalışma görevlisi","Kolluğun çocuk birimi amiri","Herhangi bir Cumhuriyet savcısı"],"dogru":0,"aciklama":"m.15/1: 'Suça sürüklenen çocuk hakkındaki soruşturma çocuk bürosunda görevli Cumhuriyet savcısı tarafından bizzat yapılır.'","kaynak":"5395 m.15","zorluk":"kolay"},
    {"id":"5395-S-013","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre kolluğun çocuk biriminin bulunmadığı yerlerde, gözaltına alınan çocuklar yetişkinlerle aynı yerde tutulabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.16/2: 'Kolluğun çocuk biriminin bulunmadığı yerlerde çocuklar, gözaltına alınan yetişkinlerden ayrı bir yerde tutulur.' Birim yoksa dahi ayrı tutma zorunludur.","kaynak":"5395 m.16","zorluk":"kolay"},
    {"id":"5395-S-014","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocukların yetişkinlerle birlikte suç işlemesi hâlinde, kural olarak nasıl bir yol izlenir?","siklar":["Soruşturma ve kovuşturma birlikte yürütülür","Dava doğrudan çocuk ağır ceza mahkemesine gider","Çocuk hakkında dava açılmaz","Soruşturma ve kovuşturma ayrı yürütülür","Yalnızca yetişkin hakkında dava açılır"],"dogru":3,"aciklama":"m.17/1: 'Çocukların yetişkinlerle birlikte suç işlemesi hâlinde, soruşturma ve kovuşturma ayrı yürütülür.' Zorunlu birleştirme ise istisnadır (m.17/3) ve yalnızca genel mahkemelerde uygun bulunursa yapılır.","kaynak":"5395 m.17","zorluk":"orta"},
    {"id":"5395-S-015","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuklara hiçbir koşulda zincir, kelepçe ve benzeri aletler takılamaz; kanunda herhangi bir istisna öngörülmemiştir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.18/1: 'Çocuklara zincir, kelepçe ve benzeri aletler takılamaz. Ancak; zorunlu hâllerde çocuğun kaçmasını, kendisinin veya başkalarının hayat veya beden bütünlükleri bakımından doğabilecek tehlikeleri önlemek için kolluk tarafından gerekli önlem alınabilir.' İstisna açıkça vardır.","kaynak":"5395 m.18","zorluk":"kolay"},
    {"id":"5395-S-016","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuğa zincir, kelepçe ve benzeri aletlerin takılmasına ilişkin yasağın istisnası hangi hâlde geçerlidir?","siklar":["Çocuğun ailesi talep ederse","Mahkeme başkanının onayı ile her zaman","Zorunlu hâllerde çocuğun kaçmasını veya kendisinin ya da başkalarının hayat/beden bütünlüğüne yönelik tehlikeleri önlemek için","Çocuk on beş yaşından büyükse","Kolluk amirinin takdirine bağlı olarak her koşulda"],"dogru":2,"aciklama":"m.18/1: 'Ancak; zorunlu hâllerde çocuğun kaçmasını, kendisinin veya başkalarının hayat veya beden bütünlükleri bakımından doğabilecek tehlikeleri önlemek için kolluk tarafından gerekli önlem alınabilir.'","kaynak":"5395 m.18","zorluk":"orta"},
    {"id":"5395-S-017","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuklar için kamu davasının açılmasının ertelenmesi kararında erteleme süresi ne kadardır?","siklar":["Bir yıl","İki yıl","Üç yıl","Beş yıl","Dört yıl"],"dogru":2,"aciklama":"m.19/1: 'Çocuğa yüklenen suçtan dolayı ... kamu davasının açılmasının ertelenmesi kararı verilebilir. Ancak, bu kişiler açısından erteleme süresi üç yıldır.'","kaynak":"5395 m.19","zorluk":"kolay"},
    {"id":"5395-S-018","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre Ceza Muhakemesi Kanununun 171 inci maddesinde belirtilen hapis cezasının üst sınırı, ....(1).... yaşını doldurmamış çocuklar bakımından ....(2).... yıl olarak uygulanır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["15 - 3","12 - 5","15 - 5","18 - 5","15 - 8"],"dogru":2,"aciklama":"m.19/2: 'Ceza Muhakemesi Kanununun 171 inci maddesinin ikinci fıkrasında belirtilen hapis cezasının üst sınırı, on beş yaşını doldurmamış çocuklar bakımından beş yıl olarak uygulanır.' Yaş 15, üst sınır 5 yıldır.","kaynak":"5395 m.19","zorluk":"zor"},
    {"id":"5395-S-019","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre m.20 uyarınca suça sürüklenen çocuklar hakkında karar verilebilecek adlî kontrol tedbirleri arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Belirlenen çevre sınırları dışına çıkmamak","Belirlenen bazı yerlere gidememek veya ancak bazı yerlere gidebilmek","Belirlenen kişi ve kuruluşlarla ilişki kurmamak","Ceza Muhakemesi Kanununun 109 uncu maddesinde sayılan tedbirlerden birine veya birkaçına karar verilmesi","Her ay düzenli olarak çocuk hâkimine yazılı rapor sunmak"],"dogru":4,"aciklama":"m.20/1: '...Ceza Muhakemesi Kanununun 109 uncu maddesinde sayılanlar ile aşağıdaki tedbirlerden bir ya da birkaçına karar verilebilir: a) Belirlenen çevre sınırları dışına çıkmamak. b) Belirlenen bazı yerlere gidememek veya ancak bazı yerlere gidebilmek. c) Belirlenen kişi ve kuruluşlarla ilişki kurmamak.' 'Her ay çocuk hâkimine yazılı rapor sunma' maddede yoktur.","kaynak":"5395 m.20","zorluk":"zor"},
    {"id":"5395-S-020","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre adli kontrol tedbirlerinden sonuç alınamaması veya tedbirlere uyulmaması durumunda, suça sürüklenen çocuk hakkında tutuklama kararı verilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.20/2: 'Ancak bu tedbirlerden sonuç alınamaması, sonuç alınamayacağının anlaşılması veya tedbirlere uyulmaması durumunda tutuklama kararı verilebilir.' Tutuklama, adli kontrolün başarısız kalmasına bağlı son çaredir.","kaynak":"5395 m.20","zorluk":"orta"},
    {"id":"5395-S-021","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre hangi yaştaki çocuklar hakkında, üst sınırı beş yılı aşmayan hapis cezasını gerektiren fiillerinden dolayı tutuklama kararı verilemez?","siklar":["On iki yaşını doldurmamış çocuklar","On dört yaşını doldurmamış çocuklar","On beş yaşını doldurmamış çocuklar","On altı yaşını doldurmamış çocuklar","On sekiz yaşını doldurmamış çocuklar"],"dogru":2,"aciklama":"m.21/1: 'Onbeş yaşını doldurmamış çocuklar hakkında üst sınırı beş yılı aşmayan hapis cezasını gerektiren fiillerinden dolayı tutuklama kararı verilemez.'","kaynak":"5395 m.21","zorluk":"kolay"},
    {"id":"5395-S-022","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuklar hakkında hükmün açıklanmasının geri bırakılması kararı verilmesi hâlinde denetim süresi ne kadardır?","siklar":["Bir yıl","İki yıl","Üç yıl","Dört yıl","Beş yıl"],"dogru":2,"aciklama":"m.23/1: 'Çocuğa yüklenen suçtan dolayı yapılan yargılama sonunda ... mahkemece hükmün açıklanmasının geri bırakılmasına karar verilebilir. Ancak, bu kişiler açısından denetim süresi üç yıldır.'","kaynak":"5395 m.23","zorluk":"orta"},
    {"id":"5395-S-023","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk mahkemesi kaç hâkimden oluşur ve duruşmada Cumhuriyet savcısı bulunur mu?","siklar":["Tek hâkimden oluşur, duruşmada Cumhuriyet savcısı bulunmaz","Bir başkan ve iki üyeden oluşur, duruşmada savcı bulunur","Tek hâkimden oluşur, duruşmada savcı da bulunur","Üç hâkimden oluşur, savcı bulunmaz","Tek hâkimden oluşur ancak kararlara karşı hiçbir kanun yoluna başvurulamaz"],"dogru":0,"aciklama":"m.25/1: 'Çocuk mahkemesi, tek hâkimden oluşur ... Çocuk mahkemelerinde yapılan duruşmalarda Cumhuriyet savcısı bulunmaz.' Ancak savcılar, çocuk mahkemesi kararlarına karşı kanun yoluna başvurabilir.","kaynak":"5395 m.25","zorluk":"kolay"},
    {"id":"5395-S-024","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk ağır ceza mahkemesi bir başkan ve iki üye ile toplanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.25/2: 'Çocuk ağır ceza mahkemelerinde bir başkan ile yeteri kadar üye bulunur ve mahkeme bir başkan ve iki üye ile toplanır.'","kaynak":"5395 m.25","zorluk":"orta"},
    {"id":"5395-S-025","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre asliye ceza mahkemesi ve sulh ceza mahkemesinin görev alanına giren suçlar bakımından, suça sürüklenen çocuklar hakkında açılacak davalara hangi mahkeme bakar?","siklar":["Çocuk ağır ceza mahkemesi","Asliye ceza mahkemesi","Çocuk mahkemesi","Sulh ceza mahkemesi","Aile mahkemesi"],"dogru":2,"aciklama":"m.26/1: 'Çocuk mahkemesi, asliye ceza mahkemesi ile sulh ceza mahkemesinin görev alanına giren suçlar bakımından, suça sürüklenen çocuklar hakkında açılacak davalara bakar.' Ağır ceza mahkemesinin görev alanındaki suçlara ise çocuk ağır ceza mahkemesi bakar (m.26/2).","kaynak":"5395 m.26","zorluk":"orta"},
    {"id":"5395-S-026","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdakilerden hangisi çocuk bürosunun görevleri arasında sayılmamıştır?","siklar":["Suça sürüklenen çocuklar hakkındaki soruşturma işlemlerini yürütmek","Çocuklar hakkında tedbir alınması gereken durumlarda gecikmeksizin tedbir alınmasını sağlamak","İlgili kamu kurum ve kuruluşları ve sivil toplum kuruluşlarıyla işbirliği içinde çalışmak","Bu Kanunla ve diğer kanunlarla verilen görevleri yerine getirmek","Çocuk hakkında doğrudan tutuklama kararı vermek"],"dogru":4,"aciklama":"m.30/1: Çocuk bürosunun görevleri arasında soruşturma yürütme (a), gecikmeksizin tedbir alınmasını sağlama (b), kurum/STK işbirliği ve bildirim (c), kanunla verilen diğer görevler (d) sayılmıştır. Tutuklama kararı vermek bir savcılık bürosunun değil, hâkim/mahkemenin yetkisindedir; m.30'da böyle bir görev yoktur.","kaynak":"5395 m.30","zorluk":"zor"},
    {"id":"5395-S-027","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre kolluğun çocuk birimi, çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına karşı nasıl davranır?","siklar":["Öncelikle bu yakınlara bilgi verir","Yalnızca baroya bilgi verilir, yakınlara da verilir","Bu yakınlar çocuğun velisi sayılır ve bilgilendirilir","Bu yakınlara bilgi verilmez","Bu yakınlara Kurum aracılığıyla bilgi ulaştırılır"],"dogru":3,"aciklama":"m.31/2: '...durumu, çocuğun veli veya vasisine ... baroya ve Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna ... bildirir. Ancak, çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına bilgi verilmez.'","kaynak":"5395 m.31","zorluk":"orta"},
    {"id":"5395-S-028","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre denetim altına alınan çocuklarla ilgili olarak kural olarak denetim görevlisini kim görevlendirir?","siklar":["Sosyal Hizmetler ve Çocuk Esirgeme Kurumu","Çocuk hâkimi","Kolluğun çocuk birimi","Denetimli serbestlik ve yardım merkezi şube müdürlüğü","Çocuk bürosu savcısı"],"dogru":3,"aciklama":"m.37/1: 'Denetim altına alınan çocukla ilgili olarak denetimli serbestlik ve yardım merkezi şube müdürlüğü tarafından bir denetim görevlisi görevlendirilir.'","kaynak":"5395 m.37","zorluk":"orta"},
    {"id":"5395-S-029","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre suç tarihinde on iki yaşını bitirmemiş suça sürüklenen çocuklar hakkında denetim görevi, gözetim esaslarına göre Sosyal Hizmetler ve Çocuk Esirgeme Kurumu tarafından yerine getirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.37/1: '...suç tarihinde oniki yaşını bitirmemiş suça sürüklenen çocuklar ile çocuğun aileye teslimi yönünde karar verilmesi hâlinde, bu çocuklar hakkında denetim görevi gözetim esaslarına göre Sosyal Hizmetler ve Çocuk Esirgeme Kurumu tarafından yerine getirilir.'","kaynak":"5395 m.37","zorluk":"orta"},
    {"id":"5395-S-030","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aile mahkemeleri tarafından verilen çocuk teslimi veya kişisel ilişki kurulmasına dair ilam veya tedbir kararları, kural olarak hangi birim tarafından yerine getirilir?","siklar":["Sosyal Hizmetler ve Çocuk Esirgeme Kurumu","Kolluğun çocuk birimi","Çocuk hâkimi","Adli destek ve mağdur hizmetleri müdürlüğü","Baro"],"dogru":3,"aciklama":"m.41/A-1: 'Çocuk teslimi veya çocukla kişisel ilişki kurulmasına dair aile mahkemeleri tarafından verilen ilam veya tedbir kararları ... Adalet Bakanlığınca kurulan adli destek ve mağdur hizmetleri müdürlüklerince bu Kısım hükümlerine göre yerine getirilir.'","kaynak":"5395 m.41/A","zorluk":"orta"},
    {"id":"5395-S-031","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk teslimine dair ilam veya tedbir kararı yükümlüsü tarafından rızasıyla yerine getirilmez ve müdürlükçe belirlenen yere de getirilmezse, müdürlük ne yapar?","siklar":["Doğrudan dava açar","Derhâl yükümlüye çocuğun teslimine dair bir teslim emri gönderir","Konuyu kapatır, hak sahibi mahkemeye yeniden başvurmalıdır","Yükümlüyü idari para cezasına çarptırır","Çocuğu doğrudan Kuruma teslim eder"],"dogru":1,"aciklama":"m.41/B-3: 'Yükümlüyle irtibat kurulamaz veya yükümlü çocuğu getirmeyeceğini beyan ederse yahut yükümlü çocuğu belirlenen yere getirmezse müdürlük, derhâl yükümlüye, çocuğun teslimine dair bir teslim emri gönderir.'","kaynak":"5395 m.41/B","zorluk":"zor"},
    {"id":"5395-S-032","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocukla kişisel ilişki kurulması hâlinde hak sahibi, çocuğu teslim almaya geleceğini teslim saatinden en az ....(1).... önce müdürlüğe bildirmek zorundadır. Boşluğa gelmesi gereken süre hangisidir?","siklar":["24 saat","48 saat","72 saat","1 hafta","12 saat"],"dogru":1,"aciklama":"m.41/C-7: 'Hak sahibi, emrin yükümlüye tebliğinden sonraki dönemde, teslim saatinden en az kırk sekiz saat önce çocuğu teslim almaya geleceğini müdürlüğe ... bildirmek zorundadır.' Süre 48 saattir.","kaynak":"5395 m.41/C","zorluk":"zor"},
    {"id":"5395-S-033","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre müdürlükçe yapılan işlem ve verilen kararlara karşı şikâyet süresi ile şikâyet üzerine verilen karara karşı itiraz süresi sırasıyla nedir?","siklar":["Bir hafta - iki hafta","İki hafta - bir hafta","On gün - yirmi gün","Bir ay - iki ay","Üç gün - bir hafta"],"dogru":0,"aciklama":"m.41/E-1: '...öğrenme veya tebliğ tarihinden itibaren bir hafta içinde ... aile mahkemesine şikâyette bulunulabilir.' m.41/E-3: 'Şikâyet üzerine verilen karara karşı, tebliğ tarihinden itibaren iki hafta içinde itiraz edilebilir.'","kaynak":"5395 m.41/E","zorluk":"zor"},
    {"id":"5395-S-034","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk teslimine dair teslim emrine aykırı hareket edenler, fiil suç teşkil etse dahi, ne kadar disiplin hapsi ile cezalandırılır?","siklar":["Üç günden on güne kadar","Bir aya kadar","Üç aya kadar","Altı aya kadar","Bir yıla kadar"],"dogru":2,"aciklama":"m.41/F-1: 'Çocuk teslimine dair ilam veya tedbir kararlarının yerine getirilmesine ilişkin teslim emrine aykırı hareket edenler ile emrin gereğinin yerine getirilmesini engelleyenler ... üç aya kadar disiplin hapsi ile cezalandırılır.'","kaynak":"5395 m.41/F","zorluk":"zor"},
    {"id":"5395-S-035","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["Bakım tedbiri - Sosyal Hizmetler ve Çocuk Esirgeme Kurumu","Sağlık tedbiri - Sağlık Bakanlığı","Eğitim tedbiri - Millî Eğitim Bakanlığı ve Çalışma ve Sosyal Güvenlik Bakanlığı","Danışmanlık ve barınma tedbirleri - Millî Eğitim Bakanlığı, Kurum ve yerel yönetimler","Tedbirlerin yerine getirilmesinde kurumların koordinasyonu - İçişleri Bakanlığı"],"dogru":4,"aciklama":"m.45/3: 'Bu tedbirlerin yerine getirilmesinde kurumların koordinasyonu Adalet Bakanlığınca sağlanır.' Koordinasyon İçişleri Bakanlığında değil, Adalet Bakanlığındadır; diğer dört eşleştirme m.45/1'in bentleriyle (a-d) birebir örtüşür.","kaynak":"5395 m.45","zorluk":"zor"},
    {"id":"5395-S-036","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdaki süre-konu eşleştirmelerinden hangisi DOĞRUDUR?","siklar":["Tedbir kararlarının incelenmesi - altı ayda bir","Kamu davasının açılmasının ertelenmesi - üç yıl","Hükmün açıklanmasının geri bırakılmasında denetim süresi - beş yıl","Acil korunma kararı için Kuruma müracaat süresi - on gün","Tutuklama yasağı yaş sınırı - on iki yaş"],"dogru":1,"aciklama":"m.19/1: 'bu kişiler açısından erteleme süresi üç yıldır.' Diğer şıklar birbirine ait sayıları karıştırır: tedbir incelemesi üçer aylıktır (A yanlış, m.8/2), HAGB denetim süresi de üç yıldır (C yanlış, m.23/1), acil korunmada Kuruma müracaat en geç beş gündür (D yanlış, m.9/1), tutuklama yasağı yaşı on beştir (E yanlış, m.21/1).","kaynak":"5395 m.9/m.19/m.21/m.23","zorluk":"zor"},
    {"id":"5395-S-037","soru":"5395 sayılı Çocuk Koruma Kanunu'nun amacı aşağıdakilerden hangisidir?","siklar":["Korunma ihtiyacı olan veya suça sürüklenen çocukların korunmasına, haklarının ve esenliklerinin güvence altına alınmasına ilişkin usûl ve esasları düzenlemek","Yalnızca suça sürüklenen çocukların cezalandırılmasına ilişkin usul ve esasları düzenlemek","Yalnızca çocuk mahkemelerinin kuruluşunu düzenlemek","Yalnızca korunma ihtiyacı olan çocuklara yönelik cezai yaptırımları düzenlemek","Çocukların eğitim hakkını düzenlemek"],"dogru":0,"aciklama":"m.1/1: 'Bu Kanunun amacı, korunma ihtiyacı olan veya suça sürüklenen çocukların korunmasına, haklarının ve esenliklerinin güvence altına alınmasına ilişkin usûl ve esasları düzenlemektir.'","kaynak":"5395 m.1","zorluk":"kolay"},
    {"id":"5395-S-038","soru":"5395 sayılı Çocuk Koruma Kanunu, yalnızca korunma ihtiyacı olan çocuklar hakkında alınacak tedbirleri düzenler; suça sürüklenen çocuklar hakkında uygulanacak güvenlik tedbirlerini ve çocuk mahkemelerinin kuruluş, görev ve yetkilerini kapsamaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2/1: 'Bu Kanun, korunma ihtiyacı olan çocuklar hakkında alınacak tedbirler ile suça sürüklenen çocuklar hakkında uygulanacak güvenlik tedbirlerinin usûl ve esaslarına, çocuk mahkemelerinin kuruluş, görev ve yetkilerine ilişkin hükümleri kapsar.' Kapsam maddesi üç unsuru BİRLİKTE kapsar; tek unsurla sınırlı değildir.","kaynak":"5395 m.2","zorluk":"orta"},
    {"id":"5395-S-039","soru":"5395 sayılı Çocuk Koruma Kanunu'nun 4 üncü maddesinde sayılan temel ilkeler arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Çocuğun yaşama, gelişme, korunma ve katılım haklarının güvence altına alınması","Çocuklar hakkında özgürlüğü kısıtlayıcı tedbirler ile hapis cezasına en son çare olarak başvurulması","Çocuk ve ailesinin herhangi bir nedenle ayrımcılığa tâbi tutulmaması","Çocuğun kimliğinin başkaları tarafından belirlenememesine yönelik önlemler alınması","Çocuğun velisinin onayı olmadan hiçbir tedbir kararı verilememesi"],"dogru":4,"aciklama":"m.4/1 bentleri (a-l) arasında A, B, C, D birebir yer alır. 'Velinin onayı olmadan tedbir kararı verilememesi' ise m.4'te sayılan ilkeler arasında yoktur; nitekim m.7/1 uyarınca tedbir kararı re'sen (istem olmaksızın) de çocuk hâkimi tarafından alınabilir.","kaynak":"5395 m.4","zorluk":"orta"},
    {"id":"5395-S-040","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre mahkeme, korunma ihtiyacı olan çocuk hakkında koruyucu ve destekleyici tedbir kararının yanında, Türk Medenî Kanunu hükümlerine göre hangi konularda da karar vermeye yetkilidir?","siklar":["Yalnızca velayet","Yalnızca nafaka ve kişisel ilişki kurulması","Velayet, vesayet, kayyım, nafaka ve kişisel ilişki kurulması","Yalnızca boşanma ve mal paylaşımı","Yalnızca vesayet ve kayyım"],"dogru":2,"aciklama":"m.7/7: 'Mahkeme, korunma ihtiyacı olan çocuk hakkında, koruyucu ve destekleyici tedbir kararının yanında ... Türk Medenî Kanunu hükümlerine göre velayet, vesayet, kayyım, nafaka ve kişisel ilişki kurulması hususlarında da karar vermeye yetkilidir.'","kaynak":"5395 m.7","zorluk":"orta"},
    {"id":"5395-S-041","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre korunma ihtiyacı olan çocuklar hakkında koruyucu ve destekleyici tedbirler hangi çocuk hâkimi tarafından alınır?","siklar":["Suçun işlendiği yerdeki çocuk hâkimi","Ankara çocuk hâkimi (merkezi yetki)","Kararı ilk talep eden kişinin bulunduğu yerdeki çocuk hâkimi","Çocuğun, ana, baba, vasisi veya birlikte yaşadığı kimselerin bulunduğu yerdeki çocuk hâkimi","Sosyal Hizmetler ve Çocuk Esirgeme Kurumunun merkezinin bulunduğu yerdeki çocuk hâkimi"],"dogru":3,"aciklama":"m.8/1: 'Korunma ihtiyacı olan çocuklar hakkında koruyucu ve destekleyici tedbirler, çocuğun menfaatleri bakımından kendisinin, ana, baba, vasisi veya birlikte yaşadığı kimselerin bulunduğu yerdeki çocuk hâkimince alınır.'","kaynak":"5395 m.8","zorluk":"orta"},
    {"id":"5395-S-042","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre, Türk Ceza Kanununun 31 inci maddesinin birinci ve ikinci fıkraları kapsamına giren ve aynı zamanda akıl hastası olan suça sürüklenen çocuklar hakkında, koruyucu ve destekleyici tedbirler DEĞİL, doğrudan ceza uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.11: 'Bu Kanunda düzenlenen koruyucu ve destekleyici tedbirler, suça sürüklenen ve ceza sorumluluğu olmayan çocuklar bakımından, çocuklara özgü güvenlik tedbiri olarak anlaşılır.' m.12: 'Suça sürüklenen çocuğun aynı zamanda akıl hastası olması hâlinde, ... Türk Ceza Kanununun 31 inci maddesinin birinci ve ikinci fıkraları kapsamına giren çocuklar hakkında, çocuklara özgü güvenlik tedbirleri uygulanır.' Ceza değil, güvenlik tedbiri uygulanır.","kaynak":"5395 m.11/m.12","zorluk":"zor"},
    {"id":"5395-S-043","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre suça sürüklenen ve ceza sorumluluğu olmayan çocuklarla korunma ihtiyacı olan çocuklar hakkında, kural olarak duruşma yapılmaksızın tedbir kararı verilir; ancak hâkim zaruret gördüğü hâllerde duruşma yapabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.13/1: 'Bu Kanunun 7 nci maddesinin yedinci fıkrasında öngörülen durumlar hariç olmak üzere, suça sürüklenen ve ceza sorumluluğu olmayan çocuklarla korunma ihtiyacı olan çocuklar hakkında duruşma yapılmaksızın tedbir kararı verilir. Ancak, hâkim zaruret gördüğü hâllerde duruşma yapabilir.'","kaynak":"5395 m.13","zorluk":"orta"},
    {"id":"5395-S-044","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk hâkimi tarafından alınan tedbir kararlarına karşı itiraz hangi mahkemeye yapılır?","siklar":["Çocuk ağır ceza mahkemesine","Aile mahkemesine","Asliye ceza mahkemesine","En yakın çocuk mahkemesine","Bölge adliye mahkemesine"],"dogru":3,"aciklama":"m.14/1: 'Bu Kanun hükümlerine göre, çocuk hâkimi tarafından alınan tedbir kararlarına karşı itiraz yolu açıktır. İtiraz, ... Ceza Muhakemesi Kanununun itiraza ilişkin hükümlerine göre en yakın çocuk mahkemesine yapılır.'","kaynak":"5395 m.14","zorluk":"kolay"},
    {"id":"5395-S-045","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre aşağıdakilerden hangisi, çocuk hakkındaki duruşmada hazır bulunabilecek kişiler arasında sayılmamıştır?","siklar":["Çocuğun kendisi","Velisi","Vasisi","Mahkemece görevlendirilmiş sosyal çalışma görevlisi","Cumhuriyet savcısı"],"dogru":4,"aciklama":"m.22/1: 'Çocuk, velisi, vasisi, mahkemece görevlendirilmiş sosyal çalışma görevlisi, çocuğun bakımını üstlenen aile ve kurumda bakılıyorsa kurumun temsilcisi duruşmada hazır bulunabilir.' Cumhuriyet savcısı bu sayımda yoktur; nitekim m.25/1 uyarınca çocuk mahkemesi duruşmalarında Cumhuriyet savcısı zaten bulunmaz.","kaynak":"5395 m.22","zorluk":"orta"},
    {"id":"5395-S-046","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre Ceza Muhakemesi Kanununun uzlaşmaya ilişkin hükümleri, suça sürüklenen çocuklar bakımından da uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.24/1: 'Ceza Muhakemesi Kanununun uzlaşmaya ilişkin hükümleri suça sürüklenen çocuklar bakımından da uygulanır.'","kaynak":"5395 m.24","zorluk":"kolay"},
    {"id":"5395-S-047","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuk bürosu nerede kurulur?","siklar":["Her il ve ilçe adliyesinde ayrı ayrı","Çocuk mahkemelerinin bünyesinde","Cumhuriyet başsavcılıklarında","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu bünyesinde","Adalet Bakanlığı merkez teşkilatında"],"dogru":2,"aciklama":"m.29/1: 'Cumhuriyet başsavcılıklarında bir çocuk bürosu kurulur. Cumhuriyet başsavcısınca 28 inci maddenin birinci fıkrasında öngörülen nitelikleri haiz olanlar arasından yeterli sayıda Cumhuriyet savcısı, bu büroda görevlendirilir.'","kaynak":"5395 m.29","zorluk":"kolay"},
    {"id":"5395-S-048","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre bu Kanun kapsamındaki tedbirleri uygulayan sosyal çalışma görevlilerine, almakta oldukları aylıklarının (ek gösterge dâhil) brüt tutarının yüzde ....(1).... oranında ödeme yapılır. Boşluğa gelmesi gereken oran hangisidir?","siklar":["Elli","Yirmi beş","Yetmiş beş","Otuz","Yüz"],"dogru":0,"aciklama":"m.33/2: 'Bu Kanun kapsamındaki tedbirleri uygulayan sosyal çalışma görevlileri ile adli destek ve mağdur hizmetleri müdürlüğü bünyesinde görev yapmakta olup da mahkemelere görevlendirilen sosyal çalışma görevlilerine almakta oldukları aylıklarının (ek gösterge dahil) brüt tutarının yüzde ellisi oranında ödeme yapılır.'","kaynak":"5395 m.33","zorluk":"zor"},
    {"id":"5395-S-049","soru":"5395 sayılı Çocuk Koruma Kanunu'nun 36 ncı maddesine göre aşağıdaki çocuklardan hangisi hakkında denetim altına alınmasına karar verilebilir?","siklar":["Yalnızca gözaltına alınan çocuk","Yalnızca adli kontrol tedbirine tabi tutulan çocuk","Yalnızca tutuklanan çocuk","Koruyucu ve destekleyici tedbir kararı verilen, kamu davasının açılmasının ertelenmesi kararı onanan veya hükmün açıklanmasının geri bırakılması kararı verilen çocuk","Yalnızca hakkında acil korunma kararı verilen çocuk"],"dogru":3,"aciklama":"m.36/1: 'Hakkında koruyucu ve destekleyici tedbir kararı verilen, kamu davasının açılmasının ertelenmesi kararı onanan, hükmün açıklanmasının geri bırakılması kararı verilen çocuğun denetim altına alınmasına karar verilebilir.'","kaynak":"5395 m.36","zorluk":"orta"},
    {"id":"5395-S-050","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre denetim görevlisi, çocuğun gelişimi hakkında Cumhuriyet savcısı veya mahkemeye ....(1).... sürelerle; denetim plânının uygulanması sırasında ise mahkeme veya çocuk hâkimine ....(2).... rapor verir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["her ay - üçer aylık","üçer aylık - her ay","altışar aylık - her ay","üçer aylık - yıllık","her hafta - her ay"],"dogru":1,"aciklama":"m.38/1-f: 'Çocuğun gelişimi hakkında, üçer aylık sürelerle Cumhuriyet savcısı veya mahkemeye rapor vermek.' m.39/3: '...her ay, ayrıca talep hâlinde mahkeme veya çocuk hâkimine rapor verir.' Sıra: üçer aylık (genel gelişim raporu) - her ay (denetim plânı uygulama raporu).","kaynak":"5395 m.38/m.39","zorluk":"zor"},
    {"id":"5395-S-051","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre çocuğa uygulanacak denetimin yöntemi, denetim görevlisince, sosyal incelemeyi yapan uzman veya sosyal çalışma görevlisi ile birlikte, görevlendirmeyi takip eden ....(1).... içinde hazırlanacak bir plânla belirlenir. Boşluğa gelmesi gereken süre hangisidir?","siklar":["Beş gün","Üç gün","On gün","On beş gün","Bir ay"],"dogru":2,"aciklama":"m.39/1: 'Çocuğa uygulanacak denetimin yöntemi, denetim görevlisince, sosyal incelemeyi yapan uzman veya sosyal çalışma görevlisi ile birlikte, görevlendirmeyi takip eden on gün içinde hazırlanacak bir plânla belirlenir.'","kaynak":"5395 m.39","zorluk":"orta"},
    {"id":"5395-S-052","soru":"5395 sayılı Çocuk Koruma Kanunu'na göre, bu Kanunda hüküm bulunmayan hâllerde uygulanacak kanunlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Ceza Muhakemesi Kanunu","İcra ve İflas Kanunu","Türk Medenî Kanunu","Hukuk Usulü Muhakemeleri Kanunu","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu Kanunu"],"dogru":1,"aciklama":"m.42/1: 'Bu Kanunda hüküm bulunmayan hâllerde Ceza Muhakemesi Kanunu, Türk Medenî Kanunu, ... Hukuk Usulü Muhakemeleri Kanunu ile ... Sosyal Hizmetler ve Çocuk Esirgeme Kurumu Kanunu hükümleri uygulanır.' İcra ve İflas Kanunu bu genel atıf listesinde yer almaz.","kaynak":"5395 m.42","zorluk":"zor"},
    {"id":"5395-S-053","soru":"5395 sayılı Çocuk Koruma Kanunu Ek Madde 1'e göre, çalıştırma yasağı kapsamındaki iş yerlerinde bu yasağa aykırı olarak işçi çalıştıran kişiye, mahallin mülki idare amiri tarafından ilk aykırılıkta çalıştırdığı her bir kişi başına brüt asgari ücretin ....(1).... katı; cezanın tebliğinden itibaren bir ay içinde aykırılık giderilmezse her bir kişi başına brüt asgari ücretin ....(2).... katı tutarında idari para cezası verilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["İki - beş","Beş - on","Üç - beş","Bir - üç","Üç - yedi"],"dogru":4,"aciklama":"Ek Madde 1/4 (Ek: 22/4/2026-7578/17 md.): '...bu fıkraya aykırı olarak çalıştırdığı her bir kişi başına brüt asgari ücretin üç katı tutarında idari para cezası verilir. Aykırılığın cezanın tebliğinden itibaren bir ay içinde giderilmediğinin tespiti hâlinde, ... her bir kişi başına brüt asgari ücretin yedi katı tutarında idari para cezası verilir.' Sıra: üç kat - yedi kat.","kaynak":"5395 Ek Madde 1","zorluk":"zor"},
  ],
  37: [
    {"id":"2860-S-001","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yetkili makamdan izin almadan girişilen yardım toplama faaliyetleri hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Faaliyet güvenlik kuvvetlerince derhal menedilir ve sorumlular hakkında kovuşturma yapılır","Faaliyet ancak mahkeme kararıyla durdurulabilir","Faaliyet, valinin izniyle geriye dönük olarak meşrulaştırılabilir","Faaliyet sadece para cezası ile sonuçlanır, durdurulmaz","Faaliyet, İçişleri Bakanlığınca uyarılıp iki ay içinde izne bağlanır"],"dogru":0,"aciklama":"m.6/2: 'İzin alınmadan girişilen yardım toplama faaliyetleri güvenlik kuvvetlerince derhal menedilir ve sorumlular hakkında kovuşturma yapılır.' Müdahale idari/kolluk eliyle ve derhal olur; ayrıca kovuşturma başlar.","kaynak":"2860 m.6","zorluk":"kolay"},
    {"id":"2860-S-002","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, izin almadan yardım toplayabilecek kamu yararına çalışan dernek, kurum ve vakıfları Bakanlar Kurulu belirler.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6/1: '...hangilerinin izin almadan yardım toplayabilecekleri, Cumhurbaşkanınca belirlenip ilan edilir.' Eski ibare (İçişleri Bakanlığının önerisi üzerine Bakanlar Kurulunca) 700 sayılı KHK m.77 ile 'Cumhurbaşkanınca' şeklinde değiştirilmiştir; güncel yetkili makam Cumhurbaşkanıdır.","kaynak":"2860 m.6","zorluk":"orta"},
    {"id":"2860-S-003","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, izinsiz yardım toplama faaliyetinin internet ortamında yapıldığının tespiti hâlinde yapılan bildirime rağmen içerik en geç ....(1).... içinde çıkarılmazsa, ilgili valilik veya İçişleri Bakanlığı erişimin engellenmesi kararı için ....(2).... başvurur. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["kırk sekiz saat - idare mahkemesine","yirmi dört saat - sulh ceza hâkimliğine","yetmiş iki saat - sulh ceza hâkimliğine","on gün - asliye ceza mahkemesine","yirmi dört saat - Cumhuriyet başsavcılığına"],"dogru":1,"aciklama":"m.6/3: 'İçeriğin en geç yirmi dört saat içinde içerik ve/veya yer sağlayıcı tarafından çıkarılmaması ... hâlinde ilgili valilik veya İçişleri Bakanlığı ... erişimin engellenmesine karar verilmesi için sulh ceza hâkimliğine başvurur.'","kaynak":"2860 m.6/3","zorluk":"orta"},
    {"id":"2860-S-004","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, izinsiz internet yardım toplama içeriğine ilişkin verilen erişimin engellenmesi kararına karşı itiraz yolu ve kararın uygulanma yöntemi hakkında aşağıdakilerden hangisi doğrudur?","siklar":["2577 sayılı İdari Yargılama Usulü Kanununa göre itiraz edilir; karar tüm siteye erişimin engellenmesi yöntemiyle verilir","İtiraz yolu yoktur; karar kesindir","5271 sayılı Ceza Muhakemesi Kanunu hükümlerine göre itiraz edilebilir; karar içeriğe erişimin engellenmesi (URL vb.) yöntemiyle verilir","5237 sayılı Türk Ceza Kanununa göre itiraz edilir; karar IP engelleme yöntemiyle verilir","5271 sayılı Ceza Muhakemesi Kanununa göre itiraz edilir; karar tüm siteye erişimin engellenmesi yöntemiyle verilir"],"dogru":2,"aciklama":"m.6/3 (AYM 2024/11 ile iptal edilmeyen kısım): 'Bu karara karşı ... 5271 sayılı Ceza Muhakemesi Kanunu hükümlerine göre itiraz edilebilir. Bu fıkra kapsamında verilen erişimin engellenmesi kararı, içeriğe erişimin engellenmesi (URL vb.) yöntemiyle verilir.' İtiraz CMK'ya göredir, karar tüm siteyi değil içeriği (URL) hedefler.","kaynak":"2860 m.6/3","zorluk":"zor"},
    {"id":"2860-S-005","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, bir ilçenin sınırları içinde kalan yardım toplama faaliyeti için izin hangi makamdan alınır?","siklar":["Vali","İçişleri Bakanlığı","Belediye başkanı","Kaymakam","Dernekler birimi müdürü"],"dogru":3,"aciklama":"m.7/1: '...bir ilçenin sınırları içinde ise o ilçenin kaymakamından izin alınır.' Tek ilçe kapsamındaki faaliyette yetkili makam kaymakamdır.","kaynak":"2860 m.7","zorluk":"kolay"},
    {"id":"2860-S-006","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, bir ilin birden fazla ilçesini kapsayan yardım toplama faaliyeti için izin hangi makamdan alınır?","siklar":["O ilçenin kaymakamından","İçişleri Bakanlığından","Yerleşim yeri kaymakamından","Dernekler birimi başkanlığından","O ilin valisinden"],"dogru":4,"aciklama":"m.7/1: 'Yardım toplama faaliyeti bir ilin birden fazla ilçesini kapsıyorsa o ilin valisinden ... izin alınır.' Kapsam tek ilçeyi aşıp il sınırında kalıyorsa yetkili makam validir.","kaynak":"2860 m.7","zorluk":"orta"},
    {"id":"2860-S-007","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, birden fazla ili kapsayan bir yardım toplama faaliyetinde izin ve bilgilendirme usulü aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["İzin, faaliyete girişecek gerçek veya tüzel kişilerin yerleşim yerinin bulunduğu ilin valisinden alınır; izni veren valilik ilgili valiliklere ve İçişleri Bakanlığına bilgi verir","İzin İçişleri Bakanlığından alınır; ilgili valiliklere bilgi verilir","İzin her ilin valisinden ayrı ayrı alınır; Bakanlığa bilgi verilmez","İzin, faaliyetin en çok yürütüldüğü ilin valisinden alınır; Bakanlık onayı gerekir","İzin ilgili ilçelerin kaymakamlarından alınır; valiliklere bilgi verilir"],"dogru":0,"aciklama":"m.7/1 son cümle: 'Yardım toplama faaliyeti birden fazla ili kapsıyorsa yardım toplama faaliyetine girişecek gerçek veya tüzel kişilerin yerleşim yerinin bulunduğu ilin valisinden izin alınır ve izni veren valilik tarafından ilgili valiliklere ve İçişleri Bakanlığına bilgi verilir.' İzin makamı yerleşim yeri valisidir; Bakanlık yalnızca bilgi alır, izin vermez.","kaynak":"2860 m.7","zorluk":"zor"},
    {"id":"2860-S-008","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama faaliyetleriyle ilgili işlemler dernekler birimlerince yürütülür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.7 son cümle: 'Yardım toplama faaliyetleriyle ilgili işlemler dernekler birimlerince yürütülür.' İzin makamı (kaymakam/vali) karar verirken, işlemleri yürüten idari birim dernekler birimidir.","kaynak":"2860 m.7","zorluk":"kolay"},
    {"id":"2860-S-009","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, gazete ve dergiler adına yapılacak yardım toplama başvurusunda dilekçe kim tarafından verilir?","siklar":["Gazetenin sahibi","Sorumlu yazı işleri müdürü","Genel yayın yönetmeni","İlan servisi şefi","Dernekler biriminin ilgili memuru"],"dogru":1,"aciklama":"m.8/2: 'Gazete ve dergiler için dilekçeler sorumlu yazı işleri müdürlerince verilir.' Genel kuralda dilekçeyi yardım toplayacak kişi/kuruluş verirken, gazete-dergi özelinde bu görev sorumlu yazı işleri müdürüne aittir.","kaynak":"2860 m.8","zorluk":"orta"},
    {"id":"2860-S-010","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama öğrenim kurumları yararına veya kurum içinde yapılacaksa, başvuru dilekçesine kurum sorumlusunun yazılı izninin eklenmesi zorunludur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8/3: 'Yardım toplama, öğrenim kurumları yararına veya kurum içinde yapılacak ise, başvuru dilekçesine kurum sorumlusunun yazılı izninin eklenmesi zorunludur.' Bu izin eklenmeden başvuru eksik sayılır.","kaynak":"2860 m.8","zorluk":"orta"},
    {"id":"2860-S-011","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, izin vermeye yetkili makamlarca başvurunun incelenmesinde aşağıdaki hususlardan hangisi dikkate alınmaz?","siklar":["İşin önemi","Yardım toplama faaliyetine girişeceklerin yeterlikleri","Başvuranın daha önce vergi borcu bulunup bulunmadığı","Yapılacak hizmetin amaca ve kamu yararına uygunluğu","Yardım toplama faaliyetinin başarıya ulaşıp ulaşamayacağı"],"dogru":2,"aciklama":"m.9: 'İzin vermeye yetkili makamlarca başvuru üzerine; işin önemi, yardım toplama faaliyetine girişeceklerin yeterlikleri, yapılacak hizmetin amaca ve kamu yararına uygunluğu, yardım toplama faaliyetinin başarıya ulaşıp ulaşamayacağı ve gerekli görülen diğer konular üzerinde inceleme yapılır.' Vergi borcu kanunda sayılan kriterler arasında yer almaz.","kaynak":"2860 m.9","zorluk":"orta"},
    {"id":"2860-S-012","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, başvurunun incelenmesi sonucu en geç ....(1).... içinde başvuranlara bildirilir. Boşluğa gelmesi gereken süre hangisidir?","siklar":["bir ay","üç ay","altı ay","iki ay","bir yıl"],"dogru":3,"aciklama":"m.9: '...inceleme yapılır ve sonucu en geç iki ay içinde başvuranlara bildirilir.' Bildirim süresi tavanı iki aydır.","kaynak":"2860 m.9","zorluk":"kolay"},
    {"id":"2860-S-013","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama süresinin takdiri kime aittir ve bu süre azami ne kadar olabilir?","siklar":["Takdir İçişleri Bakanlığına aittir; süre iki yılı geçemez","Takdir Cumhurbaşkanına aittir; süre altı ayı geçemez","Takdir dernekler birimine aittir; süre bir yılı geçemez","Takdir izin veren makama aittir; süre iki yılı geçemez","Takdir izin veren makama aittir; süre bir yılı geçemez"],"dogru":4,"aciklama":"m.10: 'Yardım toplama süresinin takdiri, izin veren makama aittir. Bu süre bir yılı geçemez.' Takdir yetkisi izin veren makamda, tavan bir yıldır.","kaynak":"2860 m.10","zorluk":"orta"},
    {"id":"2860-S-014","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, haklı sebeplerin bulunması hâlinde yardım toplama süresi, izin veren makam dışında bir üst makam tarafından da uzatılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10: 'Ancak, haklı sebeplerin bulunması halinde verilen süre, izin veren makamca ... uzatılabilir.' Uzatma yetkisi de yalnızca aynı izin veren makama aittir, başka/üst bir makama değil.","kaynak":"2860 m.10","zorluk":"zor"},
    {"id":"2860-S-015","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, gerçek kişiler yardım toplama faaliyeti için en az ....(1).... kişiden ibaret sorumlu kurul oluşturmak zorundadır; kurulda görev alanlardaki değişiklikler izin veren makama ....(2).... içinde bildirilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üç - on gün","dört - on gün","iki - beş gün","beş - on beş gün","üç - bir ay"],"dogru":0,"aciklama":"m.11: 'Gerçek kişiler ... en az üç kişiden ibaret sorumlu kurul oluşturmak zorundadırlar ... Sorumlu kurulda görev alanlar ile değişikliklerin, izin veren makama on gün içinde bildirilmesi gerekir.' Üye sayısı 3, bildirim süresi 10 gündür.","kaynak":"2860 m.11","zorluk":"orta"},
    {"id":"2860-S-016","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, tüzel kişilerin sorumlu kurulu aşağıdakilerden hangisidir?","siklar":["Denetim kurulu","Yönetim organları","Genel kurul","Disiplin kurulu","Dernekler birimi"],"dogru":1,"aciklama":"m.11/1: 'Tüzelkişilerin sorumlu kurulu, yönetim organlarıdır.' Gerçek kişilerde ayrı bir 3 kişilik kurul oluşturulurken, tüzel kişilerde bu görevi mevcut yönetim organları üstlenir.","kaynak":"2860 m.11","zorluk":"kolay"},
    {"id":"2860-S-017","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, gazete ve dergiler tarafından toplanan para yardımları nereye yatırılır?","siklar":["Doğrudan gazete/dergi kasasına","İçişleri Bakanlığı hesabına","Bankada açılacak özel bir hesaba","Valilik emanet hesabına","Sorumlu yazı işleri müdürünün şahsi hesabına"],"dogru":2,"aciklama":"m.12/1: 'Gazete ve dergiler tarafından toplanacak para yardımları, bankada açılacak özel bir hesaba yatırılır.' Para doğrudan kuruma veya kişiye değil, ayrı ve özel bir banka hesabına aktarılır.","kaynak":"2860 m.12","zorluk":"kolay"},
    {"id":"2860-S-018","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardıma katılan kişilerin adları ve yardım tutarı, yardımda bulunanın isteği ne olursa olsun gazete ve dergide yayımlanmak zorundadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/2: 'Yardıma katılan kişilerin adları ve yardım tutarı, yardımda bulunanın aksi yönde isteği olmadıkça, gazete ve dergide yayımlanır.' Yardımcının aksi yönde isteği varsa yayımlama yapılmaz; yayım koşulsuz değildir.","kaynak":"2860 m.12","zorluk":"orta"},
    {"id":"2860-S-019","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, aşağıdakilerden hangisi yardım toplama faaliyetlerinde hiçbir şekilde çalışamayacak olanlar arasında sayılmamıştır?","siklar":["Silahlı Kuvvetler mensupları","Adli ve idari yargıda görevli hâkim ve savcılar","Güvenlik kuvvetleri mensupları","Vali veya kaymakamdan izin alan kamu görevlileri","Özel kolluk görevlileri"],"dogru":3,"aciklama":"m.13/1 ve m.13/3: Kamu görevlileri, vali veya kaymakamdan izin alarak (ücretsiz) yardım toplama faaliyetinde çalışabilir; hiç çalışamayacaklar ise 'Silahlı Kuvvetler, adli ve idari yargıda görevli hakim ve savcılar ile güvenlik kuvvetleri mensupları ve özel kolluk görevlileri'dir. İzinli kamu görevlisi bu mutlak yasak grubunda değildir.","kaynak":"2860 m.13","zorluk":"orta"},
    {"id":"2860-S-020","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, Türk Hava Kurumu tarafından kurban derisi, bağırsak toplamak, fitre ve zekât zarfı dağıtmak suretiyle yardım toplama faaliyetinde görevlendirilen kamu personeli için ücret konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Hiçbir şekilde ücret verilemez","Ücret ancak İçişleri Bakanlığının onayıyla verilebilir","Sadece yol gideri ödenebilir, ücret verilemez","Ücret ancak vali onayıyla verilebilir","Kurumca ücret verilebilir"],"dogru":4,"aciklama":"m.13/2: 'Çalışması için izin verilen kamu görevlilerine, her ne ad altında olursa olsun ücret verilemez. Ancak, Türk Hava Kurumu tarafından kurban derisi, bağırsak toplamak, fitre ve zekat zarfı dağıtmak suretiyle yardım toplama faaliyetlerinde görevlendirilen kamu personeline Kurumca ücret verilebilir.' Genel kural ücretsizlik, THK için istisna Kurumca ücret ödenebilmesidir.","kaynak":"2860 m.13","zorluk":"zor"},
    {"id":"2860-S-021","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama faaliyetine girişenlerin sorumlu olduğu hususlar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Toplanan yardımın en az yarısının İçişleri Bakanlığına aktarılması","Faaliyetin düzenli ve verimli bir şekilde yürütülmesi","Faaliyetin süresi içinde sonuçlandırılması","Toplanan para ve eşyanın korunması","Toplanan para ve eşyanın amaca uygun şekilde kullanılması"],"dogru":0,"aciklama":"m.14: 'Yardım toplama faaliyetine girişenler bu faaliyetin düzenli ve verimli bir şekilde yürütülmesinden, süresi içinde sonuçlandırılmasından, toplanan para ve eşyanın korunmasından ve amaca uygun şekilde kullanılmasından sorumludur.' Toplanan yardımın bir kısmının Bakanlığa aktarılması gibi bir yükümlülük kanunda yer almaz.","kaynak":"2860 m.14","zorluk":"orta"},
    {"id":"2860-S-022","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, izinsiz internet içeriğinin kaldırılması için tanınan süre ....(1)...., sorumlu kuruldaki değişikliğin izin veren makama bildirilme süresi ....(2)...., başvuru sonucunun bildirilme süresi ....(3)...., yardım toplama süresinin azami tavanı ise ....(4).... olarak düzenlenmiştir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["48 saat - 10 gün - 1 ay - 2 yıl","24 saat - 10 gün - 2 ay - 1 yıl","24 saat - 15 gün - 1 ay - 1 yıl","10 gün - 24 saat - 2 ay - 1 yıl","24 saat - 10 gün - 1 ay - 2 yıl"],"dogru":1,"aciklama":"m.6/3: içerik kaldırma süresi '24 saat'; m.11: kurul değişikliği bildirimi 'on gün'; m.9: inceleme sonucu bildirimi 'en geç iki ay'; m.10: yardım toplama süresi 'bir yılı geçemez'. Doğru sıralama: 24 saat - 10 gün - 2 ay - 1 yıl.","kaynak":"2860 m.6/3, m.9, m.10, m.11","zorluk":"zor"},
    {"id":"2860-S-023","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, ilgili valilik veya İçişleri Bakanlığının izinsiz internet içeriğine ilişkin içerik ve/veya yer sağlayıcıya bildirimde bulunurken dayandığı bilgi kaynakları arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["İnternet sayfalarındaki iletişim araçları","Alan adı","IP adresi","Vergi kimlik numarası","Benzeri kaynaklarla elde edilen bilgiler"],"dogru":3,"aciklama":"m.6/3: '...internet sayfalarındaki iletişim araçları, alan adı, IP adresi ve benzeri kaynaklarla elde edilen bilgiler üzerinden elektronik posta veya diğer iletişim araçları ile bildirimde bulunulur.' Vergi kimlik numarası bu sayımda yer almaz.","kaynak":"2860 m.6/3","zorluk":"orta"},
    {"id":"2860-S-024","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, ilgili valilik veya İçişleri Bakanlığının erişimin engellenmesi kararı için sulh ceza hâkimliğine başvurabilmesi, içeriğin 24 saat içinde çıkarılmaması dışında hangi hâllerde de mümkündür?","siklar":["Sağlayıcının yurt dışında yerleşik olması ya da bildirim ücretinin ödenmemesi","İçerik sağlayıcısının itiraz dilekçesi vermesi ya da yabancı uyruklu olması","İçerik ve yer sağlayıcıya ilişkin bilgilerin edinilememesi ya da teknik nedenlerle bildirimde bulunulamaması","Toplanan yardım tutarının belirli bir miktarı aşması","Aynı içerikle ilgili birden fazla şikâyet bulunması"],"dogru":2,"aciklama":"m.6/3: '...içerik ve yer sağlayıcıya ilişkin bilgilerin edinilememesi ya da teknik nedenlerle bildirimde bulunulamaması hâlinde ilgili valilik veya İçişleri Bakanlığı ... erişimin engellenmesine karar verilmesi için sulh ceza hâkimliğine başvurur.'","kaynak":"2860 m.6/3","zorluk":"zor"},
    {"id":"2860-S-025","soru":"2860 sayılı Yardım Toplama Kanunu'nun izin vermeye yetkili makamları düzenleyen 7 nci maddesi, ....(1).... tarihli ve ....(2).... sayılı Kanunla değiştirilmiştir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["27/12/2020 - 7262","2/7/2018 - 700","23/6/1983 - 2860","4/11/2004 - 5072","4/11/2004 - 5253"],"dogru":4,"aciklama":"Kaynak metinde m.7 başlığı altında '(Değişik: 4/11/2004-5253/38 md.)' ibaresi yer alır; madde 5253 sayılı Kanunla değiştirilmiştir.","kaynak":"2860 m.7","zorluk":"kolay"},
    {"id":"2860-S-026","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, başvuru dilekçelerinde bulunması gereken hususlar ve eklenecek belgeler ....(1).... gösterilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["yönetmelikte","genelgede","tebliğde","valilik kararında","Resmî Gazete ilanında"],"dogru":0,"aciklama":"m.8 son cümle: 'Başvuru dilekçelerinde bulunması gereken hususlar ve eklenecek belgeler yönetmelikte gösterilir.' Ayrıntı düzenleme yetkisi yönetmeliğe bırakılmıştır.","kaynak":"2860 m.8","zorluk":"kolay"},
    {"id":"2860-S-027","soru":"2860 sayılı Yardım Toplama Kanunu'nun 9 uncu maddesine 27/12/2020 tarihli ve 7262 sayılı Kanunla eklenen ikinci fıkra hükmü hâlen yürürlüktedir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Bu ek fıkra, Anayasa Mahkemesinin 18/1/2024 tarihli ve E:2021/28, K:2024/11 sayılı kararıyla iptal edilmiştir; madde 9 metninde yalnızca ilk fıkra (inceleme kriterleri + iki aylık bildirim süresi) yürürlüktedir.","kaynak":"2860 m.9","zorluk":"orta"},
    {"id":"2860-S-028","soru":"2860 sayılı Yardım Toplama Kanunu'nun 10 uncu maddesinde Anayasa Mahkemesinin 27/6/2024 tarihli ve E:2023/181, K:2024/128 sayılı kararıyla iptal edilen ibare ve bu iptalin sonucu hakkında aşağıdakilerden hangisi doğrudur?","siklar":["İptal edilen 'bir yılı geçemez' cümlesidir; bu nedenle artık süre sınırı bulunmamaktadır","İptal kararıyla madde 10'un tamamı yürürlükten kalkmıştır","İptal edilen 'haklı sebeplerin bulunması' ibaresidir; bu nedenle süre artık hiçbir sebep aranmaksızın uzatılabilir","İptal edilen 'bir yılı geçmemek üzere' ibaresidir; ancak 'Bu süre bir yılı geçemez.' cümlesi ayrı olarak yürürlükte kalmış ve bir yıllık süre tavanı geçerliliğini korumuştur","İptal kararıyla süre tavanı bir yıldan iki yıla çıkarılmıştır"],"dogru":3,"aciklama":"Kaynak metindeki dipnota göre AYM, m.10'da yer alan 'bir yılı geçmemek üzere' ibaresini iptal etmiştir; ancak bu ibare ayrı bir cümle olan 'Bu süre bir yılı geçemez.' hükmünü ortadan kaldırmamıştır, dolayısıyla bir yıllık tavan hâlâ yürürlüktedir.","kaynak":"2860 m.10","zorluk":"zor"},
    {"id":"2860-S-029","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, tüzel kişiler de yardım toplama faaliyeti için gerçek kişiler gibi ayrıca en az üç kişiden ibaret bir sorumlu kurul oluşturmak zorundadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.11: 'Tüzelkişilerin sorumlu kurulu, yönetim organlarıdır.' Üç kişilik ayrı sorumlu kurul oluşturma zorunluluğu yalnızca gerçek kişiler için öngörülmüştür; tüzel kişilerde mevcut yönetim organı bu görevi zaten üstlenir, ayrı bir kurul kurulmasına gerek yoktur.","kaynak":"2860 m.11","zorluk":"orta"},
    {"id":"2860-S-030","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, faaliyet sonunda toplanan yardımın miktarı ....(1).... ile açıklanır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["valilik ilanı","dernekler birimi tutanağı","gazete ve dergi","İçişleri Bakanlığı genelgesi","mahkeme kararı"],"dogru":2,"aciklama":"m.12 son cümle: 'Faaliyet sonunda toplanan yardımın miktarı, gazete ve dergi ile açıklanır.' Şeffaflık, toplamayı yapan yayın organı aracılığıyla sağlanır.","kaynak":"2860 m.12","zorluk":"kolay"},
    {"id":"2860-S-031","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, kamu görevlilerinin yardım toplama faaliyetlerinde çalışabilmesi için izin alması gereken makam veya makamlar hangisidir?","siklar":["Vali veya kaymakam","Yalnızca İçişleri Bakanlığı","Yalnızca dernekler birimi","Cumhurbaşkanı","Yalnızca vali"],"dogru":0,"aciklama":"m.13/1: 'Kamu görevlileri, vali veya kaymakamdan izin almadıkça yardım toplama faaliyetlerinde çalışamazlar.' Çalışma izni vali VEYA kaymakamdan alınabilir; bu, faaliyetin bizzat hangi makamdan izinli yürütüldüğünden bağımsız ayrı bir izin şartıdır.","kaynak":"2860 m.13","zorluk":"orta"},
    {"id":"2860-S-032","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama faaliyetine girişenlerin sorumluluğu yalnızca toplanan para ve eşyanın korunmasıyla sınırlıdır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.14'e göre sorumluluk dört unsuru kapsar: faaliyetin düzenli ve verimli yürütülmesi, süresi içinde sonuçlandırılması, toplanan para ve eşyanın korunması ve amaca uygun şekilde kullanılması. Sorumluluk yalnızca korumayla sınırlı değildir.","kaynak":"2860 m.14","zorluk":"kolay"},
    {"id":"2860-S-033","soru":"2860 sayılı Yardım Toplama Kanunu'na göre, yardım toplama faaliyeti için izin veren makam ile kamu görevlisinin faaliyette çalışabilmesi için izin alması gereken makam her zaman aynı makamdır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7'ye göre faaliyet izni kapsama göre değişir (tek ilçe: kaymakam; bir ilin birden fazla ilçesi: vali; birden fazla il: yerleşim yeri valisi + Bakanlığa bilgi). m.13'e göre ise kamu görevlisinin çalışma izni her durumda yalnızca vali veya kaymakamdan alınır. Örneğin birden fazla ili kapsayan bir faaliyette izin yerleşim yeri valisinden alınırken, o faaliyette çalışacak kamu görevlisinin çalışma izni yine vali veya kaymakamdan alınır; bu iki izin kanunda ayrı fıkralarda düzenlenmiş farklı kavramlardır.","kaynak":"2860 m.7, m.13","zorluk":"zor"},
  ],
  38: [
    {"id":"5199-S-001","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre kanunda geçen 'Bakanlık' ifadesi hangi bakanlığı ifade eder?","siklar":["Tarım ve Orman Bakanlığı","İçişleri Bakanlığı","Çevre, Şehircilik ve İklim Değişikliği Bakanlığı","Sağlık Bakanlığı","Ticaret Bakanlığı"],"dogru":0,"aciklama":"m.3/o: 'Bakanlık: Tarım ve Orman Bakanlığını... ifade eder.' Kanunda geçen 'Bakanlık' ifadesi Tarım ve Orman Bakanlığı anlamına gelir.","kaynak":"5199 m.3","zorluk":"kolay"},
    {"id":"5199-S-002","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre 'sahipsiz hayvan' aşağıdakilerden hangisi olarak tanımlanmıştır?","siklar":["Doğada serbest yaşayan evcilleştirilmemiş ve kültüre alınmamış hayvanlar","Sahipli hayvanlar dışında kalan evcil hayvanlar","İnsan tarafından kültüre alınmış ve eğitilmiş hayvanlar","Bir kişi, kuruluş ya da tüzel kişilik tarafından sahiplenilip Bakanlık veri tabanına kaydedilen hayvanlar","Gıda amaçlı kesimi yapılan hayvanlar"],"dogru":1,"aciklama":"m.3/f (Değişik: 30/7/2024-7527/2 md.): 'Sahipsiz hayvan: Sahipli hayvanlar dışında kalan evcil hayvanları... ifade eder.'","kaynak":"5199 m.3","zorluk":"orta"},
    {"id":"5199-S-003","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre 'güçten düşmüş hayvan' tanımı hakkında aşağıdakilerden hangisi söylenemez?","siklar":["Yaşlanma nedeniyle güç kaybı yaşayabilir","Sakatlanma veya yaralanma nedeniyle güç kaybı yaşayabilir","Bulaşıcı ve salgın hayvan hastalıkları da bu tanım kapsamında değerlendirilir","Yalnızca binek ve yük hayvanlarını kapsar","Fiziki olarak iş yapabilme yeteneğini kaybetmiş olmalıdır"],"dogru":2,"aciklama":"m.3/g: 'Güçten düşmüş hayvan: Bulaşıcı ve salgın hayvan hastalıkları haricinde yaşlanma, sakatlanma, yaralanma ve hastalanma gibi çeşitli nedenlerle fizikî olarak iş yapabilme yeteneğini kaybetmiş binek ve yük hayvanlarını... ifade eder.' Bulaşıcı ve salgın hastalıklar tanımın HARİCİNDE tutulmuştur, kapsamda değildir.","kaynak":"5199 m.3","zorluk":"orta"},
    {"id":"5199-S-004","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre toplu yaşanan yerlerde beslenen kedi ve köpeklerin kısırlaştırılması ve kayıt altına alınması konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Kısırlaştırma yalnızca teşvik edilir, zorunlu değildir","Kısırlaştırmadan yalnızca yerel yönetimler sorumludur","Dijital kimliklendirme yükümlülüğü yalnızca köpekler için aranır","Kısırlaştırma sahiplerince esastır ve sahipler ayrıca hayvanlarını dijital kimliklendirme yöntemleriyle kayıt altına aldırmakla yükümlüdür","Kısırlaştırma yalnızca veteriner hekimin talebi üzerine yapılabilir"],"dogru":3,"aciklama":"m.4/k: 'toplu yaşanan yerlerde beslenen ve barındırılan kedi ve köpeklerin sahiplerince kısırlaştırılması esastır... Kedi ve köpek sahipleri, hayvanlarını dijital kimliklendirme yöntemleriyle kayıt altına aldırmakla yükümlüdürler.'","kaynak":"5199 m.4","zorluk":"orta"},
    {"id":"5199-S-005","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre yerel yönetimler, ilgili karar organının uygun görmesi halinde hayvan hastanesi kurabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/j: '...Ayrıca yerel yönetimler, ilgili karar organının uygun görmesi halinde hayvan hastanesi kurar.' İfade madde metniyle birebir örtüşür.","kaynak":"5199 m.4","zorluk":"kolay"},
    {"id":"5199-S-006","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ticarî amaç güdülmeden bakılan ev hayvanları hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Sahibinin her türlü borcundan dolayı haczedilebilir","Yalnızca yerel yönetim kararıyla haczedilebilir","Yalnızca veteriner hekim raporu ile haczedilebilir","Yalnızca vergi borcu dışındaki borçlar için haczedilemez","Sahibinin borcundan dolayı haczedilemez"],"dogru":4,"aciklama":"m.5: 'Ticarî amaç güdülmeden (…) bakılan ev (…) hayvanları sahiplerinin borcundan dolayı haczedilemezler.' Yasak mutlaktır, borç türü ayrımı yapılmaz.","kaynak":"5199 m.5","zorluk":"orta"},
    {"id":"5199-S-007","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ev hayvanı satan kişiler hangi yükümlülüğü yerine getirmek zorundadır?","siklar":["İl hayvanları koruma kurulundan izin almak","Yerel yönetimler tarafından düzenlenen eğitim programlarına katılarak sertifika almak","Bakanlıktan faaliyet izni almak","Veteriner hekim odasına kayıt olmak","Her satıştan önce il müdürlüğüne bildirimde bulunmak"],"dogru":1,"aciklama":"m.5: 'Ev (…) hayvanı satan kişiler, bu hayvanların bakımı ve korunması ile ilgili olarak yerel yönetimler tarafından düzenlenen eğitim programlarına katılarak sertifika almakla yükümlüdürler.'","kaynak":"5199 m.5","zorluk":"orta"},
    {"id":"5199-S-008","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre sahipsiz ya da güçten düşmüş hayvanların öldürülmesi konusunda temel kural nedir?","siklar":["Yerel yönetim izniyle her zaman öldürülebilir","Yalnızca veteriner hekim kararıyla öldürülebilir","Kanuni istisnalar hariç öldürülmeleri yasaktır","Bakanlık onayı ile serbestçe öldürülebilir","Hiçbir durumda öldürülemez, istisna yoktur"],"dogru":2,"aciklama":"m.6: 'Sahipsiz ya da güçten düşmüş hayvanların kanuni istisnalar hariç öldürülmeleri yasaktır.'","kaynak":"5199 m.6","zorluk":"kolay"},
    {"id":"5199-S-009","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre sahipsiz veya güçten düşmüş hayvanların ....(1).... şekilde hayvan bakımevlerine götürülmesi zorunludur; bu hayvanların öncelikle bu merkezlerde oluşturulacak ....(2).... yerlerinde tutulması sağlanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["en kısa sürede - tedavi","bir hafta içinde - karantina","en geç üç gün içinde - gözlem","en hızlı - müşahede","derhal - rehabilitasyon"],"dogru":3,"aciklama":"m.6: 'Sahipsiz veya güçten düşmüş hayvanların en hızlı şekilde yerel yönetimlerce kurulan veya izin verilen hayvan bakımevlerine götürülmesi zorunludur. Bu hayvanların öncelikle söz konusu merkezlerde oluşturulacak müşahede yerlerinde tutulması sağlanır.'","kaynak":"5199 m.6","zorluk":"orta"},
    {"id":"5199-S-010","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre güçten düşmüş hayvanlar ticarî ve gösteri amaçlı veya herhangi bir şekilde binicilik ve taşımacılık amacıyla çalıştırılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6: 'Güçten düşmüş hayvanlar ticarî ve gösteri amaçlı veya herhangi bir şekilde binicilik ve taşımacılık amacıyla çalıştırılamaz.' Yasak kesindir, önermenin tersi doğrudur.","kaynak":"5199 m.6","zorluk":"orta"},
    {"id":"5199-S-011","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvanlara tıbbî ve cerrahi müdahaleleri kimler yapabilir?","siklar":["Yalnızca veteriner hekimler","Veteriner sağlık teknisyenleri de yapabilir","Hayvan bakımevi personeli de yapabilir","İl hayvanları koruma kurulu üyeleri de yapabilir","Eğitim almış hayvan sahipleri de yapabilir"],"dogru":0,"aciklama":"m.7: 'Hayvanlara tıbbî ve cerrahi müdahaleler sadece veteriner hekimler tarafından yapılır.' Yetki münhasıran veteriner hekimlere aittir.","kaynak":"5199 m.7","zorluk":"kolay"},
    {"id":"5199-S-012","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ev hayvanının dış görünüşünü değiştirmek amacıyla kuyruk-kulak kesilmesi, ses tellerinin alınması gibi tedavi edici olmayan cerrahi müdahaleler kural olarak yasaktır. Bu yasağa hangi durumda istisna getirilebilir?","siklar":["Hayvan sahibinin yazılı talebi üzerine","Yerel yönetimin onayıyla","Bir veteriner hekimin tıbbî sebepler veya üremenin önlenmesi durumlarında gerekli görmesi hâlinde","İl hayvanları koruma kurulunun izniyle","Bakanlığın uygun görüşüyle"],"dogru":2,"aciklama":"m.8: 'Ancak bu yasaklamalara; bir veteriner hekimin, veteriner hekimliği uygulamaları ile ilgili tıbbî sebepler veya özel bir hayvanın yararı için gerektiğinde tedavi edici olmayan müdahaleyi gerekli görmesi veya üremenin önlenmesi durumlarında izin verilebilir.'","kaynak":"5199 m.8","zorluk":"orta"},
    {"id":"5199-S-013","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvanların bilimsel çalışmalarda deney hayvanı olarak kullanılabilmesi hangi şarta bağlıdır?","siklar":["Yalnızca Bakanlığın izniyle her zaman kullanılabilir","Hayvan sahibinin yazılı muvafakatiyle kullanılabilir","Yalnızca kamu üniversitelerinde izinsiz kullanılabilir","İl hayvanları koruma kurulunun iznine bağlıdır","Başkaca bir seçenek olmaması ve kurum bünyesindeki etik kuruldan izin alınması hâlinde kullanılabilir"],"dogru":4,"aciklama":"m.9: 'Başkaca bir seçenek olmaması halinde, hayvanlar bilimsel çalışmalarda deney hayvanı olarak kullanılabilir. Hayvan deneyi yapan kurum ve kuruluşlarda bu deneylerin yapılmasına kendi bünyelerinde kurulmuş ve kurulacak etik kurullar yoluyla izin verilir.'","kaynak":"5199 m.9","zorluk":"orta"},
    {"id":"5199-S-014","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ev hayvanı satış yerlerinde kedi ve köpek bulundurulabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10: 'Ev hayvanı satış yerlerinde kedi ve köpek bulundurulamaz, ancak buralarda Bakanlıkça izin verilen ev hayvanı üretim yerlerindeki kedi ve köpeklerin satışı yapılabilir.' Genel kural yasak olup istisna dardır.","kaynak":"5199 m.10","zorluk":"orta"},
    {"id":"5199-S-015","soru":"5199 sayılı Hayvanları Koruma Kanunu'nun hayvanların ticareti hükümleri (m.10) hakkında aşağıdakilerden hangisi söylenemez?","siklar":["Hayvanların ticarî amaçla film çekimi ve reklam için kullanılması izne tâbidir","Bir hayvan acı, ıstırap ya da zarar görecek şekilde film çekimi, gösteri veya reklamda kullanılamaz","İzne ait usul ve esaslar ilgili kuruluşların görüşü alınarak Bakanlıkça çıkarılacak yönetmelikle belirlenir","Ticarî amaçla film çekimi ve reklamda hayvan kullanımı herhangi bir izne tâbi değildir","Deney hayvanlarının ithalat ve ihracatı izne tâbidir ve bu izin Bakanlıkça verilir"],"dogru":3,"aciklama":"m.10: 'Hayvanların ticarî amaçla film çekimi ve reklam için kullanılması ile ilgili hususlar izne tâbidir.' Bu nedenle D ifadesi yanlıştır; diğer dört şık madde metniyle birebir örtüşür.","kaynak":"5199 m.10","zorluk":"zor"},
    {"id":"5199-S-016","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre folklorik amaca yönelik, şiddet içermeyen geleneksel gösterilerin düzenlenebilmesi için hangi şart aranır?","siklar":["Bakanlığın uygun görüşü alınarak il hayvanları koruma kurullarından izin alınması","Yalnızca yerel yönetimin izni yeterlidir","Yalnızca Bakanlığın izni yeterlidir","Herhangi bir izin gerekmez, serbesttir","Yalnızca il hayvanları koruma kurulunun görüşü yeterlidir, ayrıca izin gerekmez"],"dogru":0,"aciklama":"m.11: 'Folklorik amaca yönelik, şiddet içermeyen geleneksel gösteriler, Bakanlığın uygun görüşü alınarak il hayvanları koruma kurullarından izin alınmak suretiyle düzenlenebilir.' İki şart birlikte aranır.","kaynak":"5199 m.11","zorluk":"orta"},
    {"id":"5199-S-017","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvanların kesilmesiyle ilgili aşağıdakilerden hangisi bir şart olarak sayılmamıştır?","siklar":["Hayvanı korkutmadan ve ürkütmeden kesmek","En az acı verecek şekilde kesmek","Hijyenik kurallara uymak","Kesimin ehliyetli kişilerce yapılması","Kesimin mutlaka bir veteriner hekim tarafından yapılması"],"dogru":4,"aciklama":"m.12: 'Hayvanların kesilmesi; ... hayvanı korkutmadan, ürkütmeden, en az acı verecek şekilde, hijyenik kurallara uyularak ve usulüne uygun olarak bir anda yapılır. Hayvanların kesiminin ehliyetli kişilerce yapılması sağlanır.' Kanun kesim için 'ehliyetli kişi' der; veteriner hekim şartı aranmaz.","kaynak":"5199 m.12","zorluk":"orta"},
    {"id":"5199-S-018","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre yavrulama, gebelik ve süt anneliği dönemlerinde hayvanların öldürülmesi konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Bu dönemlerde hiçbir koşulda hayvan öldürülemez","Yalnızca yerel yönetim izniyle öldürülebilir","Kanunî istisnalar, tıbbî-bilimsel gerekçeler ve gıda amaçlı olmayan önlenemez acil tehditler dışında öldürülemez","Sahibinin talebi üzerine her zaman öldürülebilir","Bakımevi yönetiminin kararıyla serbestçe öldürülebilir"],"dogru":2,"aciklama":"m.13: 'Kanunî istisnalar ile tıbbî ve bilimsel gerekçeler ve gıda amaçlı olmayan, insan ve çevre sağlığına yönelen önlenemez tehditler bulunan acil durumlar dışında yavrulama, gebelik ve süt anneliği dönemlerinde hayvanlar öldürülemez.'","kaynak":"5199 m.13","zorluk":"orta"},
    {"id":"5199-S-019","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ev hayvanlarının kaç yaşından küçüklere satılması yasaktır?","siklar":["12","14","18","16","21"],"dogru":3,"aciklama":"m.14/d: 'Ev (…) hayvanlarını onaltı yaşından küçüklere satmak' yasak fiiller arasındadır.","kaynak":"5199 m.14","zorluk":"kolay"},
    {"id":"5199-S-020","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvanları hasta, gebelik süresinin ....(...)... tamamlamış gebe ve yeni ana iken çalıştırmak, uygun olmayan koşullarda barındırmak yasaktır. Boşluğa gelmesi gereken oran hangisidir?","siklar":["yarısını","1/3'ünü","3/4'ünü","tamamını","2/3'ünü"],"dogru":4,"aciklama":"m.14/ı: 'Hayvanları hasta, gebelik süresinin 2/3'ünü tamamlamış gebe ve yeni ana iken çalıştırmak, uygun olmayan koşullarda barındırmak' yasaktır.","kaynak":"5199 m.14","zorluk":"orta"},
    {"id":"5199-S-021","soru":"5199 sayılı Hayvanları Koruma Kanunu'nun 14 üncü maddesindeki yasaklar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Hayvanlara işkence yapmak veya acımasız ve zalimce muamelede bulunmak","Sahipsiz hayvanları veteriner hekim gözetiminde kısırlaştırmak","Ev hayvanını terk etmek","Hayvanlara cinsel saldırıda bulunmak veya tecavüz etmek","Yerel yönetimler adına toplanan sahipsiz hayvanları bakımevi dışında bir yere terk etmek"],"dogru":1,"aciklama":"m.14 (m), (n), (j), (o) bentlerinde işkence/acımasız muamele, ev hayvanını terk, cinsel saldırı/tecavüz ve bakımevi dışına bırakma yasak fiil olarak sayılmıştır. Veteriner hekim gözetiminde yapılan kısırlaştırma ise m.7'de düzenlenen meşru bir müdahaledir; m.14'te yasak fiil olarak sayılmaz.","kaynak":"5199 m.14","zorluk":"zor"},
    {"id":"5199-S-022","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre televizyon programlarında ayda en az ....(1).... , özel radyo kanallarının programlarında ise ayda en az ....(2).... eğitici yayın yapılması zorunludur. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["iki saat - yarım saat","bir saat - yarım saat","yarım saat - iki saat","iki saat - bir saat","üç saat - bir saat"],"dogru":0,"aciklama":"m.20: 'Türkiye Radyo ve Televizyon Kurumu ile özel televizyon kanallarına ait televizyon programlarında ayda en az iki saat, özel radyo kanallarının programlarında ise ayda en az yarım saat eğitici yayınların yapılması zorunludur.'","kaynak":"5199 m.20","zorluk":"orta"},
    {"id":"5199-S-023","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre bir hayvana çarpıp ona zarar veren sürücünün yükümlülüğü nedir?","siklar":["Olay yerini terk etmeden yalnızca trafik polisine haber vermek","Hayvanı yerel yönetime teslim etmek","Hayvanı en yakın veteriner hekime ya da tedavi ünitesine götürmek veya götürülmesini sağlamak","Hayvanı bulunduğu yerde bırakıp mülki amire bildirmek","Hiçbir yükümlülüğü yoktur"],"dogru":2,"aciklama":"m.21: 'Bir hayvana çarpan ve ona zarar veren sürücü, onu en yakın veteriner hekim ya da tedavi ünitesine götürmek veya götürülmesini sağlamak zorundadır.'","kaynak":"5199 m.21","zorluk":"kolay"},
    {"id":"5199-S-024","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre doğal yaşam parkları için aşağıdakilerden hangisi doğrudur?","siklar":["Yalnızca belediyeler kurabilir","Kuruluşu ve çalışma usul ve esasları için Bakanlık yönetmeliği aranmaz","Yalnızca Bakanlık kurabilir","Gerçek veya tüzel kişiler, hayvanların etolojisine ve habitatına uygun, serbest dolaşımlarına imkân sağlayan doğal yaşam parkları kurabilir","Hayvanat bahçesiyle aynı usul ve esaslara tabi değildir"],"dogru":3,"aciklama":"m.22: 'Gerçek veya tüzel kişiler, hayvanların etolojisine ve habitatına uygun, serbest dolaşımlarına imkan sağlayan doğal yaşam parkları kurabilir.' Kuruluş ile çalışma usul ve esasları, hayvanat bahçeleriyle birlikte Bakanlıkça çıkarılacak yönetmelikle belirlenir.","kaynak":"5199 m.22","zorluk":"orta"},
    {"id":"5199-S-025","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre 'sahipli hayvan' tanımı hakkında aşağıdakilerden hangisi söylenemez?","siklar":["Bakımı yapılan bir ev hayvanıdır","Aşıları yapılan bir ev hayvanıdır","Periyodik sağlık kontrolleri yapılan bir ev hayvanıdır","Bakanlık veri tabanına kaydedilen bir ev hayvanıdır","Kısırlaştırılmış olması tanımın zorunlu bir unsurudur"],"dogru":4,"aciklama":"m.3/j (Değişik: 30/7/2024-7527/2 md.): 'Sahipli hayvan: Bir kişi, kuruluş, kurum ya da tüzel kişilik tarafından sahiplenilen, bakımı, aşıları, periyodik sağlık kontrolleri yapılan ve Bakanlık veri tabanına kaydedilen ev hayvanlarını... ifade eder.' Kısırlaştırılmış olmak bu tanımın bir unsuru değildir.","kaynak":"5199 m.3","zorluk":"orta"},
    {"id":"5199-S-026","soru":"5199 sayılı Hayvanları Koruma Kanunu'nun tanımlar maddesine göre 'hayvan bakımevi', hangi makamdan izin alınarak kurulan bir tesis olarak tanımlanmıştır?","siklar":["İl hayvanları koruma kurulundan","Yerel yönetimden","Bakanlıktan","İçişleri Bakanlığından","Çevre, Şehircilik ve İklim Değişikliği Bakanlığından"],"dogru":2,"aciklama":"m.3/k: 'Hayvan bakımevi: Bakanlıktan izin alınmak suretiyle kurulan, hayvanların sahiplendirilinceye kadar barındırıldığı ve rehabilite edildiği bir tesisi... ifade eder.' Bakımevini fiilen kuran çoğu zaman yerel yönetim olsa da, tanımdaki izin makamı Bakanlıktır.","kaynak":"5199 m.3","zorluk":"zor"},
    {"id":"5199-S-027","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre 'rehabilitasyon' tanımı kapsamında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Tedavinin yapılması","Parazit mücadelesinin yapılması","Aşılanması","Kısırlaştırılması","Sahiplendirilmesi"],"dogru":4,"aciklama":"m.3/p: 'Rehabilitasyon: Sahipsiz hayvanların tedavi ve parazit mücadelesinin yapılmasını, aşılanmasını, kısırlaştırılmasını ve dijital kimliklendirme yöntemleriyle işaretlenmesini... ifade eder.' Sahiplendirme, m.3/k'deki 'sahiplendirilinceye kadar' ifadesiyle ilişkili ayrı bir aşamadır; rehabilitasyon tanımının unsuru değildir.","kaynak":"5199 m.3","zorluk":"zor"},
    {"id":"5199-S-028","soru":"5199 sayılı Hayvanları Koruma Kanunu'nun ilkelerine göre doğada serbestçe yaşayan bir hayvanın yakalanıp özgürlükten yoksun bırakılmaması esastır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/f: 'Yabani hayvanların yaşama ortamlarından koparılmaması, doğada serbestçe yaşayan bir hayvanın yakalanıp özgürlükten yoksun bırakılmaması esastır.' İfade madde metniyle birebir örtüşür.","kaynak":"5199 m.4","zorluk":"kolay"},
    {"id":"5199-S-029","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre bir hayvanı sahiplenen kişinin yükümlülükleri arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Hayvanı barındırmak","Hayvanın etolojik ihtiyaçlarını temin etmek","Hayvanın sağlığına dikkat etmek","İnsan, hayvan ve çevre sağlığı açısından gerekli önlemleri almak","Hayvanı yerel yönetime kayıt ettirmek"],"dogru":4,"aciklama":"m.5/1.fıkra: 'Bir hayvanı sahiplenen kişi, hayvanı barındırmak, hayvanın türüne ve üreme yöntemine uygun olan etolojik ihtiyaçlarını temin etmek, sağlığına dikkat etmek, insan, hayvan ve çevre sağlığı açısından gerekli tüm önlemleri almakla yükümlüdür.' Yerel yönetime kayıt ettirme yükümlülüğü bu fıkrada yer almaz.","kaynak":"5199 m.5","zorluk":"orta"},
    {"id":"5199-S-030","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre sahipsiz hayvanların korunması, bakılması ve gözetimine ilişkin yerel yönetimlerin yetki ve sorumluluklarını düzenleyen yönetmelik hazırlanırken Bakanlık hangi bakanlıklarla eşgüdüm sağlar?","siklar":["Sağlık Bakanlığı ve İçişleri Bakanlığı","Çevre, Şehircilik ve İklim Değişikliği Bakanlığı ve İçişleri Bakanlığı","Ticaret Bakanlığı ve Sağlık Bakanlığı","Hazine ve Maliye Bakanlığı ve İçişleri Bakanlığı","Yalnızca Çevre, Şehircilik ve İklim Değişikliği Bakanlığı"],"dogru":1,"aciklama":"m.6/3.fıkra: '...Çevre, Şehircilik ve İklim Değişikliği Bakanlığı ve İçişleri Bakanlığı ile eşgüdüm sağlanarak, diğer ilgili kuruluşların da görüşü alınmak suretiyle Bakanlıkça çıkarılacak yönetmelikle belirlenir.' İki bakanlıkla birlikte eşgüdüm şarttır.","kaynak":"5199 m.6","zorluk":"orta"},
    {"id":"5199-S-031","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvan bakımevleri ve hastanelerinin kurulması amacıyla ....(...).... ait araziler öncelikle tahsis edilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Belediyeye","Bakanlığa","Orman idaresine","Hazineye","Özelleştirme İdaresi Başkanlığına"],"dogru":3,"aciklama":"m.6: 'Hayvan bakımevleri ve hastanelerin kurulması amacıyla Hazineye ait araziler öncelikle tahsis edilir. Amacı dışında kullanıldığı tespit edilen arazilerin tahsisi iptal edilir.' Öncelikli tahsis kaynağı Hazine arazileridir.","kaynak":"5199 m.6","zorluk":"zor"},
    {"id":"5199-S-032","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre hayvanlar, bilimsel olmayan teşhis, tedavi ve deneylerde de kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.9/1.fıkra: 'Hayvanlar, bilimsel olmayan teşhis, tedavi ve deneylerde kullanılamazlar.' Yasak mutlaktır, önermenin tersi doğrudur.","kaynak":"5199 m.9","zorluk":"kolay"},
    {"id":"5199-S-033","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre ev hayvanlarının üretimini ve ticaretini yapanların yükümlülüğü nedir?","siklar":["Yalnızca il müdürlüğüne yıllık bildirimde bulunmak","Yalnızca veteriner hekim odasına üye olmak","Hayvanların sağlığını tehlikeye atmamak için gerekli anatomik, fizyolojik ve davranış karakteristikleriyle ilgili önlemleri almak","Yalnızca il hayvanları koruma kurulundan izin almak","Yalnızca Bakanlığa yıllık üretim raporu sunmak"],"dogru":2,"aciklama":"m.10/4.fıkra: 'Ev hayvanlarının üretimini ve ticaretini yapanlar, hayvanların sağlığını tehlikeye atmamak için gerekli anatomik, fizyolojik ve davranış karakteristikleri ile ilgili önlemleri almakla yükümlüdür.'","kaynak":"5199 m.10","zorluk":"kolay"},
    {"id":"5199-S-034","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre dini amaçla kurban kesimine ilişkin usul ve esasları düzenleyen yönetmelik hangi Bakanlıkça çıkarılır?","siklar":["Tarım ve Orman Bakanlığınca","Sağlık Bakanlığınca","İçişleri Bakanlığınca","Diyanet İşleri Başkanlığının bağlı olduğu Bakanlıkça","Çevre, Şehircilik ve İklim Değişikliği Bakanlığınca"],"dogru":3,"aciklama":"m.12/2.fıkra: '...kesim yerleri, ehliyetli kesim yapacak kişiler ve ilgili diğer hususlar Bakanlık, kurum ve kuruluşların görüşü alınarak, Diyanet İşleri Başkanlığının bağlı olduğu Bakanlıkça çıkarılacak yönetmelikle belirlenir.' Tarım ve Orman Bakanlığı (kanundaki 'Bakanlık') burada yalnızca görüşü alınan kurumdur, yönetmeliği çıkaran makam değildir.","kaynak":"5199 m.12","zorluk":"zor"},
    {"id":"5199-S-035","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre bakımevine alınan köpeklerden insan ve hayvanların hayatı ve sağlığı için tehlike teşkil eden ve olumsuz davranışları kontrol edilemeyenlere hangi düzenlemede belirtilen tedbir uygulanır?","siklar":["5996 sayılı Veteriner Hizmetleri, Bitki Sağlığı, Gıda ve Yem Kanununun 9 uncu maddesinin üçüncü fıkrası","6112 sayılı Radyo ve Televizyonların Kuruluş ve Yayın Hizmetleri Hakkında Kanunun 48 inci maddesi","4915 sayılı Kara Avcılığı Kanunu","2003/6168 sayılı Bakanlar Kurulu Kararı","5199 sayılı Kanunun 28 inci maddesi"],"dogru":0,"aciklama":"m.13/1.fıkra (Ek: 30/7/2024-7527/5 md.): '...11/6/2010 tarihli ve 5996 sayılı Veteriner Hizmetleri, Bitki Sağlığı, Gıda ve Yem Kanununun 9 uncu maddesinin üçüncü fıkrasında belirtilen tedbir uygulanır.' Tehlike/tehdit oluşturan bakımevi köpekleri için atıf yapılan düzenleme budur.","kaynak":"5199 m.13","zorluk":"zor"},
    {"id":"5199-S-036","soru":"5199 sayılı Hayvanları Koruma Kanunu'na göre eğitici yayınların ....(1).... 'sinin izlenme ve dinlenme oranı en yüksek saatlerde yapılması esastır ve bu maddenin takibiyle ....(2).... yükümlüdür. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["%10 - Bakanlık","%20 - Radyo ve Televizyon Üst Kurulu","%30 - İl hayvanları koruma kurulu","%20 - Bakanlık","%50 - Radyo ve Televizyon Üst Kurulu"],"dogru":1,"aciklama":"m.20: 'Bu yayınların % 20'sinin izlenme ve dinlenme oranı en yüksek saatlerde yapılması esastır. Radyo ve Televizyon Üst Kurulu görev alanına giren hususlarda bu maddenin takibi ile yükümlüdür.'","kaynak":"5199 m.20","zorluk":"orta"},
  ],
  39: [
    {"id":"2872-S-001","soru":"2872 sayılı Çevre Kanunu'na göre, bu Kanun hükümlerine uyulup uyulmadığını denetleme yetkisi, 9 uncu maddenin (a), (e) ve (f) bentleri DIŞINDAKİ diğer hükümler bakımından hangi kuruma aittir?","siklar":["Doğa Koruma ve Milli Parklar Genel Müdürlüğüne","Bakanlığa","İklim Değişikliği Başkanlığına","Jandarma Genel Komutanlığına","Türkiye Çevre Ajansına"],"dogru":1,"aciklama":"m.12: 'Bu Kanun hükümlerine uyulup uyulmadığını denetleme yetkisi 9 uncu maddenin ... (a), (e) ve (f) bentleri bakımından Doğa Koruma ve Milli Parklar Genel Müdürlüğüne, diğer hükümler bakımından Bakanlığa aittir.' Genel/asli yetki Bakanlıktadır.","kaynak":"2872 m.12","zorluk":"kolay"},
    {"id":"2872-S-002","soru":"2872 sayılı Çevre Kanunu'na göre Bakanlık, gerektiğinde denetim yetkisini aşağıdaki kurumlardan hangisine devredemez?","siklar":["İl özel idarelerine","Cumhuriyet başsavcılıklarına","Jandarma Genel Komutanlığına","Sahil Güvenlik Komutanlığına","Emniyet Genel Müdürlüğüne"],"dogru":1,"aciklama":"m.12 f.1'de devredilebilecek kurumlar tek tek sayılmıştır: İklim Değişikliği Başkanlığı, il özel idareleri, çevre denetim birimi kuran belediye başkanlıkları, Denizcilik Müsteşarlığı, Türkiye Çevre Ajansı, Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı. Cumhuriyet başsavcılığı bu sayımda yer almaz.","kaynak":"2872 m.12","zorluk":"orta"},
    {"id":"2872-S-003","soru":"2872 sayılı Çevre Kanunu'na göre askerî işyerleri, askerî bölgeler ve tatbikatların bu Kanun çerçevesindeki denetimi, hangi makamlarca müştereken hazırlanacak yönetmeliğe göre yürütülür?","siklar":["Bakanlık - Jandarma Genel Komutanlığı - Emniyet Genel Müdürlüğü","Millî Savunma Bakanlığı - Sahil Güvenlik Komutanlığı","Genelkurmay Başkanlığı - Millî Savunma Bakanlığı - İçişleri Bakanlığı - Bakanlık","Cumhurbaşkanlığı - Genelkurmay Başkanlığı","İçişleri Bakanlığı - Jandarma Genel Komutanlığı - Sahil Güvenlik Komutanlığı"],"dogru":2,"aciklama":"m.12 f.2: '...Genelkurmay Başkanlığı, Millî Savunma Bakanlığı, İçişleri Bakanlığı ve Bakanlık tarafından müştereken hazırlanacak yönetmeliğe göre yürütülür.' Bu dörtlü, genel denetim/devir düzeninden AYRI özel bir rejimdir.","kaynak":"2872 m.12","zorluk":"orta"},
    {"id":"2872-S-004","soru":"2872 sayılı Çevre Kanunu'na göre, yetkililerin denetim sırasında yaptıracakları analiz ve ölçümlerin giderlerini Bakanlık karşılar.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12: 'İlgililer, ... yetkililerin yaptıracakları analiz ve ölçümlerin giderlerini karşılamak, ... zorundadırlar.' Gider, denetlenen ilgililere (tesise) aittir, Bakanlığa değil.","kaynak":"2872 m.12","zorluk":"kolay"},
    {"id":"2872-S-005","soru":"2872 sayılı Çevre Kanunu'na göre, Kanuna aykırı davrananlara aykırı faaliyeti düzeltmesi için ....(1).... olmak üzere ve ....(2).... aşmamak üzere süre verilebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki defaya mahsus - altı ayı","bir defaya mahsus - iki yılı","süresiz - bir yılı","bir defaya mahsus - bir yılı","üç defaya mahsus - bir yılı"],"dogru":3,"aciklama":"m.15: '... bir defaya mahsus olmak üzere esasları yönetmelikle belirlenen ve bir yılı aşmamak üzere süre verilebilir.' Süre tek seferliktir ve azami bir yıldır.","kaynak":"2872 m.15","zorluk":"orta"},
    {"id":"2872-S-006","soru":"2872 sayılı Çevre Kanunu'na göre, düzeltme için süre verilmemesi halinde faaliyet derhal durdurulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.15: 'Faaliyet; süre verilmemesi halinde derhal, süre verilmesi durumunda, bu süre sonunda aykırılık düzeltilmez ise ... durdurulur.'","kaynak":"2872 m.15","zorluk":"kolay"},
    {"id":"2872-S-007","soru":"2872 sayılı Çevre Kanunu'na göre aşağıdaki faaliyetlerden hangisi süre verilmeksizin durdurulur?","siklar":["Yönetmelikteki standardı ilk kez aşan faaliyet","Düzeltme süresi içinde kısmen iyileşme gösteren faaliyet","Mahallî çevre kurulu kararına aykırı ama izinli faaliyet","Ek 9 uncu maddeye aykırı davranan faaliyet","Çevre izni veya çevre izin ve lisansı olmayan faaliyet"],"dogru":4,"aciklama":"m.15: 'Çevre ve insan sağlığı yönünden tehlike yaratan faaliyetler ile çevre izni veya çevre izin ve lisansı olmayan faaliyetler süre verilmeksizin durdurulur.'","kaynak":"2872 m.15","zorluk":"orta"},
    {"id":"2872-S-008","soru":"2872 sayılı Çevre Kanunu'na göre, proje tanıtım dosyası hazırlanmaksızın başlanan bir faaliyeti süre verilmeksizin durdurma yetkisi kime aittir?","siklar":["Mahallin en büyük mülkî amirine","Bakanlığa","Doğa Koruma ve Milli Parklar Genel Müdürlüğüne","İl özel idaresine","Cumhurbaşkanına"],"dogru":0,"aciklama":"m.15: '...proje tanıtım dosyası hazırlanmaksızın başlanan faaliyetler ise mahallin en büyük mülkî amiri tarafından süre verilmeksizin durdurulur.' (Çevresel Etki Değerlendirmesi incelemesi yapılmaksızın başlananları ise Bakanlık durdurur.)","kaynak":"2872 m.15","zorluk":"zor"},
    {"id":"2872-S-009","soru":"2872 sayılı Çevre Kanunu'na göre, faaliyetin durdurulması, bu Kanunda öngörülen cezaların uygulanmasına engel teşkil eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.15 son fıkra: 'Süre verilmesi ve faaliyetin durdurulması, bu Kanunda öngörülen cezaların uygulanmasına engel teşkil etmez.'","kaynak":"2872 m.15","zorluk":"orta"},
    {"id":"2872-S-010","soru":"2872 sayılı Çevre Kanunu'na göre, madde 20'de öngörülen idari para cezalarının uygulanmasında aşağıdakilerden hangisi geçerlidir?","siklar":["Fiil suç oluştursa dahi yalnızca idari para cezası uygulanır, TCK devreye girmez","İdari para cezası verildikten sonra TCK hükümleri artık uygulanamaz","Madde 20 yalnızca gerçek kişilere uygulanır, tüzel kişilere uygulanmaz","İdari para cezaları yalnızca Danıştay kararıyla kesinleşir","Türk Ceza Kanunu ile diğer kanunların, fiilin suç oluşturması haline ilişkin hükümleri saklıdır"],"dogru":4,"aciklama":"m.20 son fıkra: 'Bu maddenin uygulamasında Türk Ceza Kanunu ile diğer kanunların, fiilin suç oluşturması haline ilişkin hükümleri saklıdır.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-011","soru":"2872 sayılı Çevre Kanunu'na göre, denizlerde petrol ve petrol türevleri tahliyesi veya deşarjı yapan tankerlere uygulanacak idari para cezası hangi esasa göre hesaplanır?","siklar":["Aracın yaşına göre","Sabit tek bir tutar olarak","Kirlenen alanın metrekaresine göre","Groston (gros ton) esasına göre","Geminin bayrağına göre"],"dogru":3,"aciklama":"m.20/ı: cezalar 'groston başına' belirlenen tutarlarla, gemi/tankerin büyüklüğüne (grostonuna) göre hesaplanır.","kaynak":"2872 m.20","zorluk":"kolay"},
    {"id":"2872-S-012","soru":"2872 sayılı Çevre Kanunu'na göre, tehlikeli madde ve atıkların deşarjı durumunda uygulanacak idari para cezaları, petrol ve türevleri kategorisi esas alınarak ....(1).... verilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["iki katı","on katı","üç katı","beş katı","yarısı"],"dogru":1,"aciklama":"m.20/ı: 'Tehlikeli madde ve atıkların deşarjı durumunda uygulanacak idarî para cezaları, petrol ve türevleri kategorisi esas alınarak on katı verilir.'","kaynak":"2872 m.20","zorluk":"zor"},
    {"id":"2872-S-013","soru":"2872 sayılı Çevre Kanunu'na göre, kirliliğin oluşmasını müteakip gemi veya deniz aracının kendi imkânlarıyla neden olduğu kirliliği giderdiği tespit edilirse idari para cezası hangi oranda uygulanır?","siklar":["1/3 oranında","1/2 oranında","2/3 oranında","Ceza hiç uygulanmaz","Tam oranda (değişmez)"],"dogru":0,"aciklama":"m.20/ı: '...idarî para cezası 1/3 oranında uygulanır.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-014","soru":"2872 sayılı Çevre Kanunu'na göre, deniz kirliliğine ilişkin idari para cezasının derhal ve defaten ödenmemesi veya yeterli teminat gösterilmemesi halinde ne yapılır?","siklar":["Gemi kaptanı tutuklanır","Gemi müsadere edilerek mülkiyeti devlete geçer","Ceza faize bağlanarak ertelenir","Gemi ve götürülebilen diğer deniz vasıtaları en yakın liman yetkilisine teslim edilerek seyrüseferden ve faaliyetten men edilir","Yalnızca bayrak devletine bildirim yapılır, başka işlem yapılmaz"],"dogru":3,"aciklama":"m.20/ı: '...gemiler ve götürülebilen diğer deniz vasıtaları en yakın liman yetkilisine teslim edilerek seyrüseferden ve faaliyetten men edilir.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-015","soru":"2872 sayılı Çevre Kanunu'na göre, tehlikeli atıkların her ne şekilde olursa olsun ülkeye girişini sağlayanlara idari para cezası nasıl uygulanır?","siklar":["Tek seferde, toplam bir ceza olarak","Yalnızca ilk tespit edilen girişte ceza uygulanır","Ayrı ayrı, her giriş için idari para cezası olarak","Ceza uygulanmaz, yalnızca atık geri gönderilir","Ceza yarı oranda uygulanır"],"dogru":2,"aciklama":"m.20/t: 'Tehlikeli atıkların her ne şekilde olursa olsun ülkeye girişini sağlayanlara AYRI AYRI 2.000.000 Türk Lirası idarî para cezası verilir.' 'Ayrı ayrı' ibaresi her giriş için ayrı ceza uygulanacağını gösterir.","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-016","soru":"2872 sayılı Çevre Kanunu'na göre, madde 20'de öngörülen cezalar Özel Çevre Koruma Bölgelerinde ne şekilde uygulanır?","siklar":["İki kat olarak","Bir kat artırılarak","Üç kat olarak","On kat olarak","Değişiklik yapılmadan, normal oranda"],"dogru":0,"aciklama":"m.20 ek fıkra: 'Bu maddede öngörülen cezalar Özel Çevre Koruma Bölgelerinde iki kat olarak uygulanır.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-017","soru":"2872 sayılı Çevre Kanunu'na göre, madde 20'de öngörülen ceza miktarlarını on katına kadar artırmaya kim yetkilidir?","siklar":["Bakanlık","Vali","Çevre, Şehircilik ve İklim Değişikliği Bakanı","Türkiye Büyük Millet Meclisi","Cumhurbaşkanı"],"dogru":4,"aciklama":"m.20: 'Bu maddede öngörülen ceza miktarlarını on katına kadar artırmaya Cumhurbaşkanı yetkilidir.'","kaynak":"2872 m.20","zorluk":"kolay"},
    {"id":"2872-S-018","soru":"2872 sayılı Çevre Kanunu'na göre, madde 12'de öngörülen bildirim ve bilgi verme yükümlülüğüne aykırı olarak yanlış ve yanıltıcı bilgi verenler ....(1).... cezası ile cezalandırılır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["üç aydan altı aya kadar hapis","bir yıldan üç yıla kadar hapis","altı aydan bir yıla kadar hapis","yalnızca idari para","altı aydan bir yıla kadar adli para"],"dogru":2,"aciklama":"m.26 f.1: '...yanlış ve yanıltıcı bilgi verenler, altı aydan bir yıla kadar hapis cezası ile cezalandırılır.'","kaynak":"2872 m.26","zorluk":"orta"},
    {"id":"2872-S-019","soru":"2872 sayılı Çevre Kanunu'na göre, bu Kanunun uygulanmasında yanlış ve yanıltıcı belge düzenleyenler ve kullananlar hakkında hangi kanunun belgede sahtecilik suçuna ilişkin hükümleri uygulanır?","siklar":["5237 sayılı Türk Ceza Kanununun","5271 sayılı Ceza Muhakemesi Kanununun","5326 sayılı Kabahatler Kanununun","2872 sayılı Çevre Kanununun kendi hükümlerinin","6098 sayılı Türk Borçlar Kanununun"],"dogru":0,"aciklama":"m.26 f.2: '...yanlış ve yanıltıcı belge düzenleyenler ve kullananlar hakkında 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun belgede sahtecilik suçuna ilişkin hükümleri uygulanır.'","kaynak":"2872 m.26","zorluk":"orta"},
    {"id":"2872-S-020","soru":"2872 sayılı Çevre Kanunu'na göre, madde 26 uyarınca yargıya intikal eden çevresel etki değerlendirmesine ilişkin ihtilaflarda, çevresel etki değerlendirmesi süreci yargılama sonuna kadar durur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.26 f.3: 'Bu maddeye göre yargıya intikal eden çevresel etki değerlendirmesine ilişkin ihtilaflarda çevresel etki değerlendirmesi süreci yargılama sonuna kadar durur.'","kaynak":"2872 m.26","zorluk":"kolay"},
    {"id":"2872-S-021","soru":"2872 sayılı Çevre Kanunu'na göre, bu Kanunda yazılı fiiller hakkında verilecek idari nitelikteki cezalar, bu fiiller için diğer kanunlarda yazılı cezaların uygulanmasına engel olur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.27: '...verilecek idari nitelikteki cezalar, bu fiiller için diğer kanunlarda yazılı cezaların uygulanmasına engel olmaz.'","kaynak":"2872 m.27","zorluk":"kolay"},
    {"id":"2872-S-022","soru":"2872 sayılı Çevre Kanunu'na göre, çevreyi kirletenler ve çevreye zarar verenler, sebep oldukları kirlenme ve bozulmadan doğan zararlardan dolayı hangi esasa göre sorumludur?","siklar":["Yalnızca kasıt varsa sorumlu olurlar","Yalnızca ağır kusur halinde sorumlu olurlar","Sorumluluk yalnızca mahkeme kararıyla doğar","Sorumluluk yalnızca tüzel kişiler için geçerlidir","Kusur şartı aranmaksızın sorumludurlar"],"dogru":4,"aciklama":"m.28: 'Çevreyi kirletenler ve çevreye zarar verenler ... kusur şartı aranmaksızın sorumludurlar.'","kaynak":"2872 m.28","zorluk":"orta"},
    {"id":"2872-S-023","soru":"2872 sayılı Çevre Kanunu'na göre, çevreye verilen zararların tazminine ilişkin talepler, zarar görenin zararı ve tazminat yükümlüsünü öğrendiği tarihten itibaren ....(1).... sonra zamanaşımına uğrar. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["bir yıl","beş yıl","iki yıl","üç yıl","on yıl"],"dogru":1,"aciklama":"m.28 ek fıkra: '...zarar görenin zararı ve tazminat yükümlüsünü öğrendiği tarihten itibaren beş yıl sonra zamanaşımına uğrar.'","kaynak":"2872 m.28","zorluk":"orta"},
    {"id":"2872-S-024","soru":"2872 sayılı Çevre Kanunu'na göre aşağıdaki fiillerden hangisi, madde 20 kapsamında idari para cezası DEĞİL, madde 26 kapsamında adli (hapis) ceza gerektirir?","siklar":["Madde 12'de öngörülen bildirim ve bilgi verme yükümlülüğünü hiç yerine getirmemek","Umuma açık yerlerde her ne şekilde olursa olsun çevreyi kirletmek","Madde 12 uyarınca yanlış ve yanıltıcı bilgi vermek","Malî sorumluluk sigortasını yaptırmamak","Acil durum plânlarını hazırlamamak"],"dogru":2,"aciklama":"m.26 f.1: bildirim yükümlülüğüne aykırı olarak YANLIŞ VE YANILTICI bilgi vermek, altı aydan bir yıla kadar hapis cezası gerektiren adli bir suçtur. Diğer şıklar idari para cezası gerektiren fiillerdir: bilgi vermemek (A, m.20/g), umuma açık yerde kirletme (B, m.20/s), mali sorumluluk sigortası (D, m.20/p), acil durum plânı (E, m.20/o).","kaynak":"2872 m.20-26","zorluk":"zor"},
    {"id":"2872-S-025","soru":"2872 sayılı Çevre Kanunu'na göre, ilgililer çevre kirliliğine neden olabilecek faaliyetleriyle ilgili olarak talep edilmesi hâlinde Bakanlığa veya yetkili denetim birimine aşağıdakilerden hangisini vermekle yükümlü DEĞİLDİR?","siklar":["Kullandıkları hammadde ve yakıt bilgilerini","Çıkardıkları ürün ve atıkları","Üretim şemalarını ve acil durum plânlarını","İzleme sistemleri ve kirlilik raporlarını","Şirketin yıllık kâr-zarar bilançosunu"],"dogru":4,"aciklama":"m.12 f.4: 'İlgililer, çevre kirliliğine neden olabilecek faaliyetleri ile ilgili olarak, kullandıkları hammadde, yakıt, çıkardıkları ürün ve atıklar ile üretim şemalarını, acil durum plânlarını, izleme sistemleri ve kirlilik raporları ile diğer bilgi ve belgeleri talep edilmesi halinde Bakanlığa veya yetkili denetim birimine vermek zorundadırlar.' Kâr-zarar bilançosu bu sayımda yer almaz.","kaynak":"2872 m.12","zorluk":"orta"},
    {"id":"2872-S-026","soru":"2872 sayılı Çevre Kanunu'na göre, Bakanlığın gerektiğinde denetim yetkisini devredebileceği kurumlar arasına 2/7/2025 tarihli ve 7552 sayılı Kanunla eklenen kurum aşağıdakilerden hangisidir?","siklar":["Jandarma Genel Komutanlığı","Sahil Güvenlik Komutanlığı","İklim Değişikliği Başkanlığı","Türkiye Çevre Ajansı","Emniyet Genel Müdürlüğü"],"dogru":2,"aciklama":"m.12 f.1: '...Gerektiğinde bu yetki, Bakanlıkça; İklim Değişikliği Başkanlığına, il özel idarelerine, ... devredilir.' İklim Değişikliği Başkanlığı ibaresi 2/7/2025 tarihli ve 7552 sayılı Kanunun 18 inci maddesiyle eklenmiştir.","kaynak":"2872 m.12","zorluk":"zor"},
    {"id":"2872-S-027","soru":"2872 sayılı Çevre Kanunu'na göre, denetim yetkisi başka bir kuruma devredilmiş olsa bile, denetimler yine Bakanlığın belirlediği denetim usûl ve esasları çerçevesinde yapılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.12 f.1 son cümle: 'Denetimler, Bakanlığın belirlediği denetim usûl ve esasları çerçevesinde yapılır.' Yetkinin devri, usul belirleme yetkisini devretmez.","kaynak":"2872 m.12","zorluk":"orta"},
    {"id":"2872-S-028","soru":"2872 sayılı Çevre Kanunu'na göre, süre sonunda aykırılığın düzeltilmemesi hâlinde faaliyetin durdurulma biçimine ilişkin aşağıdakilerden hangisi doğrudur?","siklar":["Faaliyet yalnızca tamamen ve süresiz olarak durdurulabilir","Faaliyet yalnızca kısmen ve süreli olarak durdurulabilir","Durdurma kararı yalnızca mahkeme tarafından verilebilir","Faaliyet kısmen veya tamamen, süreli veya süresiz olarak durdurulabilir","Durdurma yalnızca bir yıl süreyle uygulanabilir"],"dogru":3,"aciklama":"m.15 f.2: '...Bakanlıkça ya da 12 nci maddenin birinci fıkrası uyarınca denetim yetkisinin devredildiği kurum ve merciler tarafından kısmen veya tamamen, süreli veya süresiz olarak durdurulur.'","kaynak":"2872 m.15","zorluk":"orta"},
    {"id":"2872-S-029","soru":"2872 sayılı Çevre Kanunu'na göre, aykırı faaliyeti düzeltmek üzere süre verme yetkisi yalnızca Bakanlığa aittir; denetim yetkisinin devredildiği diğer kurum ve merciler süre veremez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.15 f.1: süre, 'Bakanlıkça ya da 12 nci maddenin birinci fıkrası uyarınca denetim yetkisinin devredildiği kurum ve merciler tarafından' verilebilir.","kaynak":"2872 m.15","zorluk":"kolay"},
    {"id":"2872-S-030","soru":"2872 sayılı Çevre Kanunu'na göre, egzoz gazı emisyon ölçümü yaptırmayan motorlu taşıt sahibine idari para cezası verilir; ancak aynı aracın yönetmeliklerle belirlenen standartlara aykırı emisyona sebep olması durumunda bu ceza ....(1).... olarak uygulanır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["iki katı","aynı tutarda","üç katı","beş katı","yarısı"],"dogru":0,"aciklama":"m.20/a-1: '...1.250 Türk lirası, ancak aynı aracın yönetmeliklerle belirlenen standartlara aykırı emisyona sebep olması durumunda motorlu taşıt sahibine 2.500 Türk lirası ... idari para cezası verilir.' 2.500, 1.250'nin iki katıdır.","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-031","soru":"2872 sayılı Çevre Kanunu'na göre, hava kirliliği yönünden özel önem taşıyan bölgelerde veya kritik meteorolojik şartlarda yönetmeliklerle öngörülen önlemleri almayanlara, madde 20'nin (b) ve (c) bentlerinde öngörülen cezalar nasıl uygulanır?","siklar":["Yarı oranında","Bir kat artırılarak","Değişmeden aynı tutarda","Üç kat artırılarak","On kat artırılarak"],"dogru":1,"aciklama":"m.20/d: 'Hava kirliliği yönünden özel önem taşıyan bölgelerde veya kirliliğin ciddi boyutlara ulaştığı zamanlarda ve yerlerde veya kritik meteorolojik şartlarda yönetmeliklerle öngörülen önlemleri almayan, yasaklara aykırı davranan ya da mahallî çevre kurullarınca bu konuda alınan kararlara uymayanlara bu maddenin (b) ve (c) bentlerinde öngörülen cezalar bir kat artırılarak verilir.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-032","soru":"2872 sayılı Çevre Kanunu'na göre, anız yakma fiilinin orman ve sulak alanlara bitişik yerler ile meskûn mahallerde işlenmesi durumunda, her dekar için öngörülen ceza ....(1).... artırılır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["iki kat","üç kat","dört kat","beş kat","on kat"],"dogru":3,"aciklama":"m.20/l: '...anız yakanlara her dekar için ... idarî para cezası verilir. Anız yakma fiilinin orman ve sulak alanlara bitişik yerler ile meskûn mahallerde işlenmesi durumunda ceza beş kat artırılır.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-033","soru":"2872 sayılı Çevre Kanunu'na göre, çevre yönetimi hizmeti verenlere uygulanan ceza puanının dört yıl içinde 100 puana ulaşması durumunda ne olur?","siklar":["Yeterlik belgesi iptal edilir","Faaliyet süresiz olarak durdurulur","İdari para cezası üç katına çıkarılır","Yeterlik belgesi iki yıl süreyle askıya alınır","Yeterlik belgesi yüz seksen gün süreyle askıya alınır"],"dogru":4,"aciklama":"m.20/m ek fıkra (7/5/2026-7579/8): '...uygulanan ceza puanının dört yıl içerisinde 100 puana ulaşması durumunda yeterlik belgesi yüzseksen gün süre ile askıya alınır. Uygulanan ceza puanının dört yıl içinde 200 puana ulaşması durumunda yeterlik belgesi iki yıl süreyle iptal edilir.'","kaynak":"2872 m.20","zorluk":"zor"},
    {"id":"2872-S-034","soru":"2872 sayılı Çevre Kanunu'na göre, ek 11 inci maddeye aykırı olarak geri kazanım katılım payını ödemediği tespit edilenlere, katılım payı tutarının ....(1).... kadar idari para cezası verilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["%20'si","%10'u","%50'si","iki katı","üç katı"],"dogru":0,"aciklama":"m.20/z: 'Bu Kanunun ek 11 inci maddesine aykırı olarak geri kazanım katılım payını ödemediği tespit edilenlere katılım payı tutarının %20'si kadar idari para cezası olarak verilir.'","kaynak":"2872 m.20","zorluk":"orta"},
    {"id":"2872-S-035","soru":"2872 sayılı Çevre Kanunu'na göre, 11 inci madde uyarınca kurulması zorunlu olan atık alım, ön arıtma, arıtma veya bertaraf tesislerini kurmayanlara ilişkin idari para cezası, Boğazlar ve Susurluk Havzası dâhil Marmara Denizi Hidrolojik Havzası'nda yer alan İstanbul, Bursa ve Kocaeli illerinin tamamında iki kat olarak uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.20/f (ek cümle:10/6/2022-7410/5): '...Boğazlar ve Susurluk Havzası dâhil Marmara Denizi Hidrolojik Havzası'nda ve bu Havza'da yer alan illerden İstanbul, Bursa ve Kocaeli illerinin tamamında bu bentteki ceza iki kat olarak uygulanır.'","kaynak":"2872 m.20","zorluk":"zor"},
    {"id":"2872-S-036","soru":"2872 sayılı Çevre Kanunu'na göre, kirletenin kusur şartı aranmaksızın sorumlu tutulması, kirletenin genel hükümlere göre de tazminat sorumluluğu bulunmasını ortadan kaldırır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.28 f.2: 'Kirletenin, meydana gelen zararlardan ötürü genel hükümlere göre de tazminat sorumluluğu saklıdır.' Kusursuz sorumluluk, genel hükümlere göre sorumluluğu ortadan kaldırmaz, saklı tutar.","kaynak":"2872 m.28","zorluk":"orta"},
  ],
  40: [
    {"id":"2559-S-001","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre parmak izi kaydına ilişkin aşağıdakilerden hangisi doğrudur?","siklar":["Parmak izi, kime ait olduğu, ne zaman ve kim tarafından alındığı belirtilerek kaydedilir; ancak alınma sebebi kaydedilmez","Parmak izinin hangi sebeple alındığı da sisteme kaydedilir","Parmak izi, kime ait olduğu ve hangi sebeple alındığı belirtilerek kaydedilir","Parmak izi yalnızca alınma tarihiyle, kimlik belirtilmeksizin kaydedilir","Parmak izi kaydı yalnızca gözaltına alınanlar için tutulur"],"dogru":0,"aciklama":"m.5: 'Birinci fıkraya göre alınan parmak izi, ait olduğu kişinin kimlik bilgileri ile birlikte, ne zaman ve kim tarafından alındığı belirtilmek suretiyle ... kaydedilerek saklanır. Ancak, parmak izinin hangi sebeple alındığı sisteme kaydedilmez.' Kim-ne zaman kayıtlıdır, sebep hiç yazılmaz.","kaynak":"2559 m.5","zorluk":"kolay"},
    {"id":"2559-S-002","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre aşağıdakilerden hangisi, polisin parmak izini almaya yetkili olduğu kişiler arasında sayılmamıştır?","siklar":["Gönüllüler","Trafik cezası kesilen sürücüler","Sürücü belgesi almak için başvuruda bulunanlar","Türk vatandaşlığına başvuruda bulunanlar","Gözaltına alınanlar"],"dogru":1,"aciklama":"m.5 birinci fıkra altı hâl sayar: gönüllü (a), silah ruhsatı/sürücü belgesi/pasaport başvurusu (b), kolluk/özel güvenlik istihdamı (c), vatandaşlık başvurusu (ç), sığınma/yabancı (d), gözaltı (e). 'Trafik cezası kesilen sürücü' bu sayımda yer almaz.","kaynak":"2559 m.5","zorluk":"orta"},
    {"id":"2559-S-003","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre sisteme kayıtlı parmak izi ve fotoğraflar, kişinin ölümünden itibaren ....(1).... yıl ve her halde kayıt tarihinden itibaren ....(2).... yıl geçtikten sonra sistemden silinir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["5 - 60","20 - 60","10 - 80","15 - 100","10 - 60"],"dogru":2,"aciklama":"m.5 son fıkra: 'Sisteme kayıtlı olan parmak izi ve fotoğraflar, kişinin ölümünden itibaren on yıl ve her halde kayıt tarihinden itibaren seksen yıl geçtikten sonra sistemden silinir.' Ölümden 10 yıl, her halde kayıttan 80 yıl.","kaynak":"2559 m.5","zorluk":"orta"},
    {"id":"2559-S-004","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre olay yerinden elde edilen ve kime ait olduğu henüz tespit edilemeyen parmak izleri, kime ait olduğu tespit edilinceye kadar ilgili soruşturma dosya numarasıyla birlikte sisteme kaydedilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5: 'Olay yerinden elde edilen ve kime ait olduğu henüz tespit edilemeyen parmak izleri, kime ait olduğu tespit edilinceye kadar, ilgili soruşturma dosya numarası ile birlikte sisteme kaydedilir.'","kaynak":"2559 m.5","zorluk":"kolay"},
    {"id":"2559-S-005","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre kaybolan çocukların bulunması amacıyla verilen tedbir kararı en çok ne kadar süre için verilebilir ve nasıl uzatılabilir?","siklar":["En çok 15 gün; uzatılamaz","En çok 3 ay; üç defa uzatılabilir","En çok 6 ay; sınırsız uzatılabilir","En çok bir ay; bir defaya mahsus olmak üzere bir ay daha uzatılabilir","En çok iki ay; iki defa uzatılabilir"],"dogru":3,"aciklama":"m.13/A: 'Tedbir kararı, en çok bir ay için verilebilir; ancak bu süre, bir defaya mahsus olmak üzere bir ay daha uzatılabilir.' Toplamda en çok iki ay (1+1).","kaynak":"2559 m.13/A","zorluk":"kolay"},
    {"id":"2559-S-006","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre kaybolan çocuğun bulunması amacıyla, gecikmesinde sakınca bulunan hallerde emri hangi makam verebilir ve bu karar ne kadar sürede mahkemenin onayına sunulur/mahkeme ne kadar sürede karar verir?","siklar":["Cumhuriyet savcısı; 48 saat içinde","Emniyet Genel Müdürü; 24 saat içinde","İl jandarma komutanı; 48 saat içinde","Sulh ceza hâkimi; derhal","Mülki idare amiri; derhal mahkemenin onayına sunulur, mahkeme en geç 24 saat içinde karar verir"],"dogru":4,"aciklama":"m.13/A: '...gecikmesinde sakınca bulunan hallerde mülki idare amirinin ... emri ile ... Mülki idare amirinin kararı, derhal mahkemenin onayına sunulur. Mahkeme kararını en geç yirmidört saat içinde verir.'","kaynak":"2559 m.13/A","zorluk":"orta"},
    {"id":"2559-S-007","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre kaybolan çocukların bulunması amacıyla alınabilecek tedbirler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Çocuğun kaldığı konutta arama yapma","Kayıp çocuğa ait banka hesap hareketlerini talep etme","Kayıp çocuk tarafından kullanılan, başkasına ait hesap hareketlerini talep etme","Telekomünikasyon yoluyla iletişimini denetleme","Sinyal bilgilerini değerlendirme"],"dogru":0,"aciklama":"m.13/A: 'polis ... kayıp çocuğa ait veya başkasına ait olmakla birlikte kayıp çocuk tarafından kullanılan her türlü banka hesap hareketlerini talep edebilir, telekomünikasyon yoluyla iletişimini denetleyebilir ve sinyal bilgilerini değerlendirebilir.' Konutta arama bu maddede düzenlenmez.","kaynak":"2559 m.13/A","zorluk":"orta"},
    {"id":"2559-S-008","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre polisin direnen kişilere karşı kelepçe, cop, basınçlı ve/veya boyalı su, göz yaşartıcı gaz veya tozlar gibi araçları kullanması aşağıdaki kavramlardan hangisiyle ifade edilir?","siklar":["Bedenî kuvvet","Maddî güç","Silah","Meşru savunma","Zorunluluk hâli"],"dogru":1,"aciklama":"m.16: 'Maddî güç; polisin direnen kişilere karşı veya eşya üzerinde bedenî kuvvetin dışında kullandığı kelepçe, cop, basınçlı ve/veya boyalı su, göz yaşartıcı gazlar veya tozlar, fizikî engeller, polis köpekleri ve atları ile sair hizmet araçlarını ifade eder.'","kaynak":"2559 m.16","zorluk":"orta"},
    {"id":"2559-S-009","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre direnmenin mahiyeti ve derecesi göz önünde bulundurularak, ilgililere ihtar yapılmadan da zor kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16: 'Zor kullanmadan önce, ilgililere direnmeye devam etmeleri halinde doğrudan doğruya zor kullanılacağı ihtarı yapılır. Ancak, direnmenin mahiyeti ve derecesi göz önünde bulundurularak, ihtar yapılmadan da zor kullanılabilir.'","kaynak":"2559 m.16","zorluk":"kolay"},
    {"id":"2559-S-010","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre toplu kuvvet olarak müdahale edilen durumlarda, zor kullanmanın derecesi ile kullanılacak araç ve gereçleri kim tayin ve tespit eder?","siklar":["Müdahaleye katılan her polis kendisi belirler","Mülki idare amiri","Müdahale eden kuvvetin amiri","İl emniyet müdürü her zaman","Cumhuriyet savcısı"],"dogru":2,"aciklama":"m.16: 'Polis ... kullanacağı araç ve gereç ile kullanacağı zorun derecesini kendisi takdir ve tayin eder. Ancak, toplu kuvvet olarak müdahale edilen durumlarda, zor kullanmanın derecesi ile kullanılacak araç ve gereçler müdahale eden kuvvetin amiri tarafından tayin ve tespit edilir.'","kaynak":"2559 m.16","zorluk":"zor"},
    {"id":"2559-S-011","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre aşağıdakilerden hangisi, polisin silah kullanmaya yetkili olduğu hâller arasında sayılmamıştır?","siklar":["Meşru savunma hakkının kullanılması kapsamında","Bedenî kuvvet ve maddî güçle etkisiz hale getirilemeyen direniş karşısında, bu direnişi kırmak amacıyla ve kıracak ölçüde","Hakkında yakalama emri bulunan kişinin ya da suçüstü halinde şüphelinin yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde","Basit bir sözlü tartışmada karşı tarafı sindirmek amacıyla","Molotof, patlayıcı, yanıcı, yakıcı ve benzeri silahlarla saldıranlara karşı saldırıyı etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde"],"dogru":3,"aciklama":"m.16 yedinci fıkra dört hâl sayar: meşru savunma (a), direnişi kıramama (b), tutuklama/yakalama emri-suçüstü yakalaması (c), molotof/patlayıcı saldırısı (d). 'Sözlü tartışmada sindirme amacı' bu sayımda yoktur ve ölçülülük ilkesine de aykırıdır.","kaynak":"2559 m.16","zorluk":"orta"},
    {"id":"2559-S-012","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre yakalama emri/suçüstü kapsamında silah kullanmadan önce polis kişiye duyabileceği şekilde ....(1)...., kişinin kaçmaya devam etmesi halinde ise önce ....(2).... edilir; buna rağmen ısrar edilirse yakalamayı sağlamak amacıyla ve sağlayacak ölçüde ateş edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["uyarı amacıyla ateş eder - dur çağrısında bulunulur","yakalama amacıyla ateş eder - dur çağrısında bulunulur","dur çağrısında bulunur - doğrudan yakalama amacıyla ateş edilir","ihtar eder - hava atışı yapılır","'dur' çağrısında bulunur - uyarı amacıyla ateş edilir"],"dogru":4,"aciklama":"m.16: '...kişiye duyabileceği şekilde \"dur\" çağrısında bulunur. Kişinin bu çağrıya uymayarak kaçmaya devam etmesi halinde, önce uyarı amacıyla silahla ateş edilebilir. Buna rağmen kaçmakta ısrar etmesi ... halinde ise ... yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde silahla ateş edilebilir.' Sıra: dur → uyarı atışı → yakalama atışı.","kaynak":"2559 m.16","zorluk":"orta"},
    {"id":"2559-S-013","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre polis, kendisine veya başkasına yönelik bir saldırı karşısında, zor kullanmaya ilişkin koşullara bağlı kalmaksızın 5237 sayılı Türk Ceza Kanununun meşru savunmaya ilişkin hükümleri çerçevesinde savunmada bulunabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16: 'Polis, kendisine veya başkasına yönelik bir saldırı karşısında, zor kullanmaya ilişkin koşullara bağlı kalmaksızın, 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun meşru savunmaya ilişkin hükümleri çerçevesinde savunmada bulunur.'","kaynak":"2559 m.16","zorluk":"orta"},
    {"id":"2559-S-014","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre polis, Devletin ülkesi ve milletiyle bölünmez bütünlüğüne, Anayasa düzenine ve genel güvenliğine dair önleyici ve koruyucu tedbirleri almak üzere hangi faaliyeti yürütür?","siklar":["Ülke seviyesinde istihbarat faaliyetinde bulunur; bilgi toplar, değerlendirir, yetkili mercilere veya kullanma alanına ulaştırır","Adli soruşturma yürütür ve iddianame düzenler","Yalnızca il düzeyinde bilgi toplar","Sadece Millî İstihbarat Teşkilatı ile bilgi paylaşır, kendi bilgi toplamaz","Bu görevi yalnızca özel harekât birimleri yürütür"],"dogru":0,"aciklama":"Ek m.7 birinci fıkra: 'Polis ... emniyet ve asayişi sağlamak üzere, ülke seviyesinde ... istihbarat faaliyetlerinde bulunur, bu amaçla bilgi toplar, değerlendirir, yetkili mercilere veya kullanma alanına ulaştırır. Devletin diğer istihbarat kuruluşlarıyla işbirliği yapar.'","kaynak":"2559 Ek m.7","zorluk":"kolay"},
    {"id":"2559-S-015","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7 nci maddesi uyarınca iletişimin denetlenmesi konusunda yetkili ve görevli hâkim aşağıdakilerden hangisidir?","siklar":["İstanbul ağır ceza mahkemesi üyesi","Ankara ağır ceza mahkemesi üyesi","Yargıtay ilgili ceza dairesi üyesi","Olayın geçtiği yerdeki sulh ceza hâkimi","Danıştay üyesi"],"dogru":1,"aciklama":"Ek m.7: 'Yetkili ve görevli hâkim, Ankara ağır ceza mahkemesi üyesidir.' Yetki tek ve merkezîdir.","kaynak":"2559 Ek m.7","zorluk":"orta"},
    {"id":"2559-S-016","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7 nci maddesi uyarınca, iletişimin denetlenmesine (tespit, dinleme, sinyal değerlendirme, kayda alma) konu edilebilecek suçlar bakımından aşağıdakilerden hangisi kapsam dışında bırakılmıştır?","siklar":["5271 sayılı Kanunun 250 nci maddesinin birinci fıkrasının (a) bendinde yazılı suçlar","5271 sayılı Kanunun 250 nci maddesinin birinci fıkrasının (b) bendinde yazılı suçlar","Casusluk suçları","5271 sayılı Kanunun 250 nci maddesinin birinci fıkrasının (c) bendinde yazılı suçlar","Bilişim suçları"],"dogru":2,"aciklama":"Ek m.7: '5271 sayılı Ceza Muhakemesi Kanununun, casusluk suçları hariç, 250 nci maddesinin birinci fıkrasının (a), (b) ve (c) bentlerinde yazılı suçlar ile bilişim suçlarının işlenmesinin önlenmesi amacıyla ...' Casusluk suçları açıkça kapsam dışıdır.","kaynak":"2559 Ek m.7","zorluk":"zor"},
    {"id":"2559-S-017","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7 nci maddesi uyarınca, gecikmesinde sakınca bulunan hallerde verilen yazılı emir ....(1).... içinde yetkili hâkimin onayına sunulur; hâkim kararını en geç ....(2).... içinde verir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["48 saat - 24 saat","12 saat - 24 saat","24 saat - 72 saat","24 saat - 48 saat","1 gün - 1 gün"],"dogru":3,"aciklama":"Ek m.7: 'Gecikmesinde sakınca bulunan hallerde verilen yazılı emir, yirmidört saat içinde yetkili ve görevli hâkimin onayına sunulur. Hâkim, kararını en geç kırk sekiz saat içinde verir.'","kaynak":"2559 Ek m.7","zorluk":"zor"},
    {"id":"2559-S-018","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7 nci maddesi uyarınca iletişimin denetlenmesine ilişkin kararlar en fazla ne kadar süre için verilebilir ve kaç defa uzatılabilir?","siklar":["En fazla 1 ay; 1 defa uzatılabilir","En fazla 6 ay; uzatılamaz","En fazla 2 ay; 5 defa uzatılabilir","En fazla 3 ay; hiçbir istisna olmaksızın sınırsız uzatılabilir","En fazla 3 ay; aynı usulle üçer ayı geçmeyecek şekilde en fazla 3 defa uzatılabilir (terör örgütü tehlikesinde hâkim müteaddit defa uzatabilir)"],"dogru":4,"aciklama":"Ek m.7: 'Kararlar, en fazla üç ay için verilebilir; bu süre aynı usûlle üçer ayı geçmeyecek şekilde en fazla üç defa uzatılabilir. Ancak, terör örgütünün faaliyeti çerçevesinde devam eden tehlikelere ilişkin olarak ... hâkim üç aydan fazla olmamak üzere sürenin müteaddit defalar uzatılmasına karar verebilir.'","kaynak":"2559 Ek m.7","zorluk":"orta"},
    {"id":"2559-S-019","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu kapsamındaki süreler bakımından aşağıdaki eşleştirmelerden hangisi doğrudur?","siklar":["Kayıp çocuk tedbirinde mahkeme onay süresi 24 saattir; Ek m.7'de acil emrin hâkime sunulma süresi 24 saat, hâkimin karar süresi 48 saattir","Kayıp çocuk tedbirinde mahkeme onay süresi 48 saattir; Ek m.7'de hâkim karar süresi 24 saattir","Her iki düzenlemede de onay/karar süresi 48 saattir","Kayıp çocukta tedbir süresi en çok 3 ay, Ek m.7'de en çok 1 aydır","Ek m.7'de biten dinleme kaydının imha süresi 1 aydır"],"dogru":0,"aciklama":"m.13/A: mahkeme kararını en geç 24 saatte verir. Ek m.7: acil emir 24 saat içinde hâkime sunulur, hâkim en geç 48 saatte karar verir. Ayrıca kayıp çocukta tedbir en çok 1(+1) ay, Ek m.7'de en çok 3 ay (×3 uzatma); biten dinleme kaydı 10 gün içinde imha edilir.","kaynak":"2559 m.13/A; Ek m.7","zorluk":"zor"},
    {"id":"2559-S-020","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre acil hallerde emir/karar verme yetkisi bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Her iki düzenlemede de acil karar yetkisi valiye aittir","Kayıp çocuk tedbirinde acil karar mülki idare amirine, Ek m.7 istihbarat/iletişim denetiminde acil emir Emniyet Genel Müdürü, İstihbarat Dairesi Başkanı veya bilişim suçlarıyla sınırlı olarak ilgili daire başkanına aittir; her iki hâlde de asıl yetki hâkimdedir","Kayıp çocukta acil karar Emniyet Genel Müdürüne, Ek m.7'de mülki idare amirine aittir","Asıl yetki kayıp çocukta Ankara ağır ceza hâkiminde, Ek m.7'de sulh ceza hâkimindedir","Acil hallerde her iki düzenlemede de Cumhuriyet savcısı karar verir"],"dogru":1,"aciklama":"m.13/A'da acil emri mülki idare amiri verir, asıl onay sulh ceza hâkimi/mahkemesindedir. Ek m.7'de acil emri Emniyet Genel Müdürü, İstihbarat Dairesi Başkanı veya bilişim suçlarıyla sınırlı olarak ilgili daire başkanı verir; asıl yetki Ankara ağır ceza mahkemesi üyesi hâkimdedir.","kaynak":"2559 m.13/A; Ek m.7","zorluk":"zor"},
    {"id":"2559-S-021","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 5. maddesinin birinci fıkrasının (b) bendi uyarınca, aşağıdaki belgelerden hangisi için başvuranların parmak izinin alınacağı hükmü YER ALMAMIŞTIR?","siklar":["İkamet izni almak için başvuranlar","Silah ruhsatı almak için başvuranlar","Sürücü belgesi almak için başvuranlar","Pasaport almak için başvuranlar","Pasaport yerine geçen belge almak için başvuranlar"],"dogru":0,"aciklama":"m.5 (b) bendi: 'Her çeşit silah ruhsatı, sürücü belgesi, pasaport veya pasaport yerine geçen belge almak için başvuruda bulunan' kişilerin parmak izi alınır. İkamet izni bu bentte sayılmamıştır.","kaynak":"2559 m.5","zorluk":"orta"},
    {"id":"2559-S-022","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 5. maddesinde 'istihdam edilme' hâli kapsamında parmak izi alınacak görevliler arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Polis","İtfaiye görevlisi","Genel kolluk görevlisi","Özel kolluk görevlisi","Özel güvenlik görevlisi"],"dogru":1,"aciklama":"m.5 (c) bendi: 'Başta polis olmak üzere, genel veya özel kolluk görevlisi ya da özel güvenlik görevlisi olarak istihdam edilen' kişilerin parmak izi alınır. İtfaiye görevlisi bu bentte sayılmamıştır.","kaynak":"2559 m.5","zorluk":"kolay"},
    {"id":"2559-S-023","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 13/A maddesine göre, kaybolan çocukların bulunması amacıyla tedbir kararını asıl olarak ....(1).... verir; bu makamın emri yazılı ya da ....(2).... hale getirilmek üzere sözlü olabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["mülki idare amiri - sonradan yazılı","Cumhuriyet savcısı - derhal yazılı","sulh ceza hâkimi - sonradan yazılı","Ankara ağır ceza mahkemesi üyesi - derhal yazılı","il emniyet müdürü - sonradan yazılı"],"dogru":2,"aciklama":"m.13/A: '...polis, sulh ceza hâkiminin veya gecikmesinde sakınca bulunan hallerde mülki idare amirinin yazılı veya sonradan yazılı hale getirilmek üzere sözlü emri ile...' tedbirleri uygular. Asıl makam sulh ceza hâkimidir; emir yazılı veya sonradan yazılı hale getirilecek şekilde sözlü olabilir.","kaynak":"2559 m.13/A","zorluk":"zor"},
    {"id":"2559-S-024","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 16. maddesine göre, silah kullanmadan önce yapılan 'dur' çağrısı, ardından uyarı amaçlı ateş ve son olarak yakalamayı sağlamak amaçlı ateş etme sırası, meşru savunma hakkının kullanılması hâli de dâhil olmak üzere, maddede sayılan silah kullanma hâllerinin tamamında uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.16 sekizinci fıkra: 'Polis, yedinci fıkranın (c) bendi kapsamında silah kullanmadan önce...' der; yani dur çağrısı-uyarı atışı-yakalama atışı sırası YALNIZCA yedinci fıkranın (c) bendinde sayılan hâlde (tutuklama/yakalama emri veya suçüstü şüphelisinin yakalanması) uygulanır; meşru savunma, molotof/patlayıcı saldırısı gibi diğer hâllerde bu kademeli sıra aranmaz.","kaynak":"2559 m.16","zorluk":"zor"},
    {"id":"2559-S-025","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'na göre, polisin direnen kişilere karşı veya eşya üzerinde herhangi bir araç kullanmaksızın doğrudan doğruya uyguladığı bedensel güç, aşağıdaki kavramlardan hangisiyle ifade edilir?","siklar":["Maddî güç","Silah","Zor kullanma yetkisi","Bedenî kuvvet","Meşru savunma"],"dogru":3,"aciklama":"m.16 üçüncü fıkra (a) bendi: 'Bedenî kuvvet; polisin direnen kişilere karşı veya eşya üzerinde doğrudan doğruya kullandığı bedenî gücü ... ifade eder.' Araç kullanılmaksızın uygulanan güç bedenî kuvvettir.","kaynak":"2559 m.16","zorluk":"kolay"},
    {"id":"2559-S-026","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun 16. maddesinde silah kullanmaya yetki veren hâller ile bunlara karşılık gelen amaç/ölçü ifadeleri eşleştirildiğinde aşağıdakilerden hangisi doğrudur?","siklar":["Bedenî kuvvet ve maddî güçle etkisiz hale getirilemeyen direniş karşısında: 'saldırıyı etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde'","Yakalama emri/suçüstü hâlinde: 'direnişi kırmak amacıyla ve kıracak ölçüde'","Meşru savunma hakkının kullanılması: 'yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde'","Bedenî kuvvet ve maddî güçle etkisiz hale getirilemeyen direniş karşısında: 'yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde'","Molotof, patlayıcı, yanıcı vb. silahla saldırıya karşı: 'saldırıyı etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde'"],"dogru":4,"aciklama":"m.16 yedinci fıkra: (b) bendi 'bu direnişi kırmak amacıyla ve kıracak ölçüde', (c) bendi 'yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde', (d) bendi 'saldırıyı etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde' ifadelerini kullanır. Molotof/patlayıcı saldırısı (d) bendine karşılık gelen doğru eşleşme 'etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde'dir.","kaynak":"2559 m.16","zorluk":"zor"},
    {"id":"2559-S-027","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7. maddesi uyarınca iletişimin denetlenmesi tedbirine ilişkin karar veya emri vermeye yetkili merciler arasında aşağıdakilerden hangisi YOKTUR?","siklar":["İçişleri Bakanı","Hâkim kararı","Emniyet Genel Müdürü (gecikmesinde sakınca bulunan hallerde)","Emniyet Genel Müdürlüğü İstihbarat Dairesi Başkanı (gecikmesinde sakınca bulunan hallerde)","Bilişim suçlarıyla sınırlı olmak üzere bilişim suçları ile ilgili daire başkanı (gecikmesinde sakınca bulunan hallerde)"],"dogru":0,"aciklama":"Ek m.7 ikinci fıkra: '...hâkim kararı veya gecikmesinde sakınca bulunan hallerde Emniyet Genel Müdürünün, Emniyet Genel Müdürlüğü İstihbarat Dairesi Başkanının veya bilişim suçlarıyla sınırlı olmak üzere bilişim suçları ile ilgili daire başkanının yazılı emriyle...' tedbir uygulanabilir. İçişleri Bakanı bu düzenlemede yetkili merci olarak sayılmamıştır.","kaynak":"2559 Ek m.7","zorluk":"orta"},
    {"id":"2559-S-028","soru":"2559 sayılı Polis Vazife ve Salâhiyet Kanunu'nun Ek 7. maddesine göre, uygulanan iletişim denetleme tedbirinin (süre dolması veya hâkim aksi karar vermesi dışında) normal şekilde sona ermesi halinde de, dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir ve bu durum bir tutanakla tespit edilerek denetimde ibraz edilmek üzere muhafaza edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. Ek m.7 son fıkra: 'Uygulanan tedbirin sona ermesi halinde, dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir. Durum bir tutanakla tespit olunur ve bu tutanak denetimde ibraz edilmek üzere muhafaza edilir.'","kaynak":"2559 Ek m.7","zorluk":"orta"},
  ],
  41: [
    {"id":"5607-S-001","soru":"5607 sayılı Kaçakçılıkla Mücadele Kanunu'na göre gümrüklenmiş değer, ithal eşyası için hangi kıymetle gümrük vergileri toplamından oluşur?","siklar":["Fatura kıymeti","FOB kıymeti","CIF kıymeti","Sigorta kıymeti","Navlun kıymeti"],"dogru":2,"aciklama":"m.2/1-b: 'Gümrüklenmiş değer: Uluslararası kıymet sözleşmesine göre belirlenecek; ithal eşyası için eşyanın CIF kıymeti ile gümrük vergileri toplamını, ihraç eşyası için FOB kıymeti ile gümrük vergileri toplamını... ifade eder.' İthal eşyasında esas alınan kıymet CIF'tir.","kaynak":"5607 m.2","zorluk":"kolay"},
    {"id":"5607-S-002","soru":"5607 sayılı Kanun'un tanımlar maddesine göre aşağıdakilerden hangisi 'akaryakıt' tanımı kapsamında sayılmamıştır?","siklar":["Benzin","Motorin","Doğal gaz","Ham petrol","Sıvılaştırılmış petrol gazları"],"dogru":3,"aciklama":"m.2/1-c: 'Akaryakıt: Benzin, gaz yağı, jet yakıtı, motorin, fuel-oil, sıvılaştırılmış petrol gazları, doğal gaz gibi akaryakıt ürünleri ile akaryakıt yerine kullanılan petrol türevleri ve bunların karışımları ile akaryakıt yerine kullanılan diğer ürünleri, ifade eder.' Ham petrol, işlenmemiş kaynak madde olduğundan bu sayımda yer almaz.","kaynak":"5607 m.2","zorluk":"orta"},
    {"id":"5607-S-003","soru":"5607 sayılı Kanun'a göre eşyayı gümrük işlemlerine tabi tutmaksızın ülkeye sokan kişiye verilecek ceza, eşyanın gümrük kapıları dışından sokulması halinde ne kadar artırılır?","siklar":["İki kat artırılır","Yarısı kadar sabit artırılır","Dörtte birinden üçte birine kadar artırılır","Üçte biri kadar sabit artırılır","Üçte birinden yarısına kadar artırılır"],"dogru":4,"aciklama":"m.3/1: 'Eşyanın, gümrük kapıları dışından ülkeye sokulması halinde, verilecek ceza üçte birinden yarısına kadar artırılır.'","kaynak":"5607 m.3/1","zorluk":"orta"},
    {"id":"5607-S-004","soru":"5607 sayılı Kanun'a göre kaçakçılık suçunun konusu akaryakıt veya tütün mamulü olduğunda, verilecek cezalar ....(1).... artırılır; ancak bu artırım sonucu verilecek ceza ....(2).... az olamaz. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["iki kattan üç kata kadar - beş yıldan","üçte birinden yarısına kadar - iki yıldan","yarısından iki katına kadar - üç yıldan","yarısından bir katına kadar - bir yıldan","yarısından iki katına kadar - bir yıldan"],"dogru":2,"aciklama":"m.3/10: '...cezalar yarısından iki katına kadar artırılır, ancak bu fıkranın uygulanması suretiyle verilecek ceza üç yıldan az olamaz.'","kaynak":"5607 m.3/10","zorluk":"zor"},
    {"id":"5607-S-005","soru":"5607 sayılı Kanun'a göre ithali kanun gereği yasak olan eşyayı ülkeye sokan kişiye, fiil daha ağır bir suç oluşturmadığı takdirde verilecek ceza aşağıdakilerden hangisidir?","siklar":["Bir yıldan üç yıla kadar hapis","İki yıldan beş yıla kadar hapis","Altı aydan iki yıla kadar hapis","İki yıldan altı yıla kadar hapis","Üç yıldan altı yıla kadar hapis"],"dogru":3,"aciklama":"m.3/7: 'İthali kanun gereği yasak olan eşyayı ülkeye sokan kişi... iki yıldan altı yıla kadar hapis ve yirmi bin güne kadar adlî para cezası ile cezalandırılır.'","kaynak":"5607 m.3/7","zorluk":"zor"},
    {"id":"5607-S-006","soru":"5607 sayılı Kanun'a göre kaçakçılık suçlarından biri teşebbüs aşamasında kalmışsa, failine tamamlanmış suça göre indirimli ceza verilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/22: 'Yukarıdaki fıkralarda tanımlanan fiiller, teşebbüs aşamasında kalmış olsa bile, tamamlanmış gibi cezalandırılır.' İndirim uygulanmaz.","kaynak":"5607 m.3/22","zorluk":"kolay"},
    {"id":"5607-S-007","soru":"5607 sayılı Kanun'a göre kaçakçılık suçunun konusu eşyanın değerinin 'pek hafif' olması halinde verilecek ceza ne kadar indirilir?","siklar":["Üçte birine kadar","Yarısına kadar","Dörtte birine kadar","Üçte ikisine kadar","İndirim uygulanmaz"],"dogru":0,"aciklama":"m.3/23: 'Eşyanın değerinin hafif olması hâlinde verilecek cezalar yarısına kadar, pek hafif olması hâlinde ise üçte birine kadar indirilir.'","kaynak":"5607 m.3/23","zorluk":"zor"},
    {"id":"5607-S-008","soru":"5607 sayılı Kanun'a göre bu Kanunda tanımlanan suçların bir örgütün faaliyeti çerçevesinde işlenmesi halinde ceza ....(1)...., üç veya daha fazla kişi tarafından birlikte işlenmesi halinde ceza ....(2).... artırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yarı oranında - iki kat","bir kat - iki kat","yarı oranında - üçte bir oranında","iki kat - üçte bir oranında","iki kat - yarı oranında"],"dogru":4,"aciklama":"m.4/1: '...örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek ceza iki kat artırılır.' m.4/2: '...üç veya daha fazla kişi tarafından birlikte işlenmesi halinde, verilecek ceza yarı oranında artırılır.'","kaynak":"5607 m.4/1-2","zorluk":"kolay"},
    {"id":"5607-S-009","soru":"5607 sayılı Kanun'a göre kaçakçılık fiillerini önlemek, izlemek ve araştırmakla görevli olup da suçun işlenmesine kasten göz yuman kişi, işlenen suçun müşterek faili olarak sorumlu tutulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/6: '...kasten göz yuman kişi, işlenen suçun müşterek faili olarak sorumlu tutulur.'","kaynak":"5607 m.4/6","zorluk":"orta"},
    {"id":"5607-S-010","soru":"5607 sayılı Kanun'a göre kaçakçılık suçunun konusu, Devletin siyasî, iktisadî veya askerî güvenliğini bozacak nitelikte eşya ise (fiil daha ağır bir suç oluşturmadığı takdirde) verilecek hapis cezasının alt sınırı nedir?","siklar":["Beş yıldan az olamaz","Üç yıldan az olamaz","On yıldan az olamaz","Yedi yıldan az olamaz","Alt sınır yoktur, hâkim takdir eder"],"dogru":2,"aciklama":"m.4/7: '...verilecek hapis cezası on yıldan az olamaz.'","kaynak":"5607 m.4/7","zorluk":"orta"},
    {"id":"5607-S-011","soru":"5607 sayılı Kanun'a göre kaçakçılık fiillerini önlemek, izlemek, araştırmak ve soruşturmakla görevli kişiler tarafından ya da meslek ve sanatın sağladığı kolaylıklardan yararlanılarak işlenen suçlarda ceza ne oranda artırılır?","siklar":["İki kat","Üçte bir oranında","Üçte iki oranında","Yarı oranında","Değişmez, ağırlaştırıcı sebep sayılmaz"],"dogru":3,"aciklama":"m.4/4: '...verilecek ceza yarı oranında artırılır.'","kaynak":"5607 m.4/4","zorluk":"kolay"},
    {"id":"5607-S-012","soru":"5607 sayılı Kanun'a göre etkin pişmanlık göstererek indirimden yararlanmak isteyen fail, suç konusu eşyanın gümrüklenmiş değerinin kaç katı kadar parayı Devlet Hazinesine ödemek zorundadır?","siklar":["Yarısı kadar","Bir katı kadar","Üç katı kadar","Dörtte biri kadar","İki katı kadar"],"dogru":4,"aciklama":"m.5/2: '...suç konusu eşyanın gümrüklenmiş değerinin iki katı kadar parayı Devlet Hazinesine...' ödemesi gerekir.","kaynak":"5607 m.5/2","zorluk":"kolay"},
    {"id":"5607-S-013","soru":"5607 sayılı Kanun'a göre etkin pişmanlıkta, soruşturma evresi sona erinceye kadar ödeme yapılırsa ceza ....(1).... oranında, kovuşturma evresinde hüküm verilinceye kadar ödenirse ceza ....(2).... oranında indirilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yarı - üçte bir","üçte bir - yarı","yarı - üçte iki","üçte iki - yarı","dörtte bir - yarı"],"dogru":0,"aciklama":"m.5/2-a: soruşturmada 'yarı oranında', m.5/2-b: kovuşturmada 'üçte bir oranında' indirim uygulanır.","kaynak":"5607 m.5/2","zorluk":"orta"},
    {"id":"5607-S-014","soru":"5607 sayılı Kanun'a göre m.3'te tanımlanan suça iştirak etmiş bir kişi, resmî makamlarca haber alınmadan önce faili ve kaçak eşyanın yerini bildirir ve bu bilgi faillerin yakalanmasını sağlarsa, hakkında ne uygulanır?","siklar":["Ceza üçte bir oranında indirilir","Cezalandırılmaz","Ceza yarı oranında indirilir","Sadece adli para cezası verilir","Ceza üçte iki oranında indirilir"],"dogru":1,"aciklama":"m.5/1: '...haber alınmadan önce... haber verirse, verilen bilginin... sağlaması halinde cezalandırılmaz.'","kaynak":"5607 m.5/1","zorluk":"orta"},
    {"id":"5607-S-015","soru":"5607 sayılı Kanun'a göre etkin pişmanlık nedeniyle ceza indirimi hükmü, mükerrirler hakkında da suçun örgüt faaliyeti çerçevesinde işlenmesi halinde de aynen uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/3: 'İkinci fıkra hükmü, mükerrirler hakkında veya suçun bir örgütün faaliyeti çerçevesinde işlenmesi hâlinde uygulanmaz.'","kaynak":"5607 m.5/3","zorluk":"orta"},
    {"id":"5607-S-016","soru":"5607 sayılı Kanun'a göre gümrük bölgesine belirlenen kapı ve yollardan başka yerlerden girmek isteyip yakalanan kişide bulunan kaçak eşyaya ne yapılır?","siklar":["Otuz gün içinde teminat alınarak iade edilir","Mahkeme kararı beklenerek elkonulur","Derhal elkonulur","Gümrük idaresine ihbar edilir ama elkonulmaz","Yalnızca tutanak düzenlenir, eşya sahibine bırakılır"],"dogru":2,"aciklama":"m.9/3: '...Yapılan arama sonucunda tespit edilen kaçak eşyaya derhal elkonulur.'","kaynak":"5607 m.9/3","zorluk":"kolay"},
    {"id":"5607-S-017","soru":"5607 sayılı Kanun'a göre elkoyma kararı veren mercilerce alıkonulan bir taşıtın sahibinin, taşıtın iadesi için teminatı hangi süre içinde gümrük idaresine teslim etmesi gerekir?","siklar":["On beş gün","Altmış gün","Doksan gün","Otuz gün","Altı ay"],"dogru":3,"aciklama":"m.10/2: '...taşıtın değeri kadar teminatı alıkoyma tarihinden itibaren otuz gün içinde gümrük idaresine teslim etmesi halinde, taşıt sahibine iade edilir.'","kaynak":"5607 m.10/2","zorluk":"orta"},
    {"id":"5607-S-018","soru":"5607 sayılı Kanun'a göre alıkonulan taşıtta teminat süresi ....(1)...., alıkoyma kararı bulunmakla birlikte alıkonulmayan taşıtlarda gümrük idaresince yapılacak tebligattan itibaren teslim süresi ....(2).... olarak düzenlenmiştir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["60 gün - 90 gün","90 gün - 30 gün","30 gün - 60 gün","15 gün - 90 gün","30 gün - 90 gün"],"dogru":4,"aciklama":"m.10/2 (30 gün teminat süresi), m.10/3 (90 gün teslim süresi).","kaynak":"5607 m.10/2-3","zorluk":"zor"},
    {"id":"5607-S-019","soru":"5607 sayılı Kanun'a göre kaçak akaryakıt, yakalandığı ilde bulunması halinde kime teslim edilir?","siklar":["İl özel idaresine","Gümrük idaresine","Emniyet Genel Müdürlüğüne","İlgili belediyeye","Enerji Piyasası Düzenleme Kurumuna"],"dogru":0,"aciklama":"m.11/8: 'Kaçak akaryakıt, yakalandığı ildeki il özel idaresine, il özel idaresi bulunmayan yerlerde ise yatırım izleme ve koordinasyon başkanlığına... teslim edilir.'","kaynak":"5607 m.11/8","zorluk":"kolay"},
    {"id":"5607-S-020","soru":"5607 sayılı Kanun'a göre alıkonularak gümrük idaresine teslim edilen deniz taşıtları, teminatla teslim alınmaması halinde nereye teslim edilir?","siklar":["İl özel idaresine","Gümrük idaresince belirlenen liman işletme müdürlüğüne","Yatırım izleme ve koordinasyon başkanlığına","Sahil Güvenlik Komutanlığına","En yakın belediyeye"],"dogru":1,"aciklama":"m.11/3: '...gümrük idaresince belirlenen liman işletme müdürlüğüne teslim edilir.'","kaynak":"5607 m.11/3","zorluk":"orta"},
    {"id":"5607-S-021","soru":"5607 sayılı Kanun'a göre muhafazası özel tesis ve tertibat gerektiren veya gümrük idaresinin depolama kapasitesini aşan eşya bakımından aşağıdakilerden hangisi doğru değildir?","siklar":["Öncelikle özelliklerine göre doğrudan ilgili idarelere konulur","Bu mümkün olmazsa büyükşehirler dahil ilçelerde kaymakamın uygun göreceği yere konulur","Bu eşya doğrudan imha edilir, başka seçenek yoktur","İllerde valinin uygun göreceği yere konulur","Yer tayini, ilgili idarelere konulmanın mümkün olup olmamasına göre değişir"],"dogru":2,"aciklama":"m.11/4: '...özelliklerine göre doğrudan ilgili idarelere, bunun mümkün olmaması halinde büyükşehirler dahil ilçelerde kaymakam, illerde valinin uygun göreceği yerlere konulur.' Doğrudan imha bu fıkrada düzenlenmemiştir; imha yalnızca bandrolsüz mal için ayrı bir fıkrada (m.11/5) öngörülmüştür.","kaynak":"5607 m.11/4","zorluk":"zor"},
    {"id":"5607-S-022","soru":"5607 sayılı Kanun'a göre kaçak eşya taşımasında kullanılan taşıma aracının müsadere edilebilmesi için aşağıdaki koşullardan hangisi aranmaz?","siklar":["Kaçak eşyanın özel olarak hazırlanmış gizli tertibat içinde saklanmış veya taşınmış olması","Kaçak eşyanın araç yüküne göre tamamını veya ağırlıklı bölümünü oluşturması","Taşıma aracındaki kaçak eşyanın Türkiye'ye girmesi veya çıkması yasak olan maddelerden olması","Aracın sahibinin daha önce kaçakçılıktan mahkûm olmuş olması","Taşıma aracındaki kaçak eşyanın toplum veya çevre sağlığı açısından zararlı maddelerden olması"],"dogru":3,"aciklama":"m.13/1 (a,b,c): yalnız gizli tertibat, ağırlıklı/tüm yükü oluşturma veya yasak/zararlı madde koşulları sayılmıştır; 'sahibin sabıkası' bir koşul değildir. Koşullardan yalnız BİRİNİN gerçekleşmesi müsadere için yeterlidir.","kaynak":"5607 m.13/1","zorluk":"orta"},
    {"id":"5607-S-023","soru":"5607 sayılı Kanun'a göre kaçak şüphesiyle elkonulan (kaçak akaryakıt hariç) eşya hakkında, kural olarak elkoyma tarihinden itibaren ne kadar süre içinde tasfiye kararı verilmesi gerekir?","siklar":["Bir ay","Üç ay","Bir yıl","İki yıl","Altı ay"],"dogru":4,"aciklama":"m.16/1: '...el koyma tarihinden itibaren altı ay... içinde... tasfiye kararı verilir.' (Eşyanın zarara uğraması veya değer kaybı riski ya da muhafazasının ciddi külfet oluşturması halinde bu süre bir aya iner.)","kaynak":"5607 m.16/1","zorluk":"orta"},
    {"id":"5607-S-024","soru":"5607 sayılı Kanun'a göre tasfiye kararı, soruşturma aşamasında ....(1)...., kovuşturma aşamasında ise ....(2).... tarafından verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["hâkim - mahkeme","Cumhuriyet savcısı - mahkeme","mahkeme - hâkim","hâkim - Cumhuriyet savcısı","Cumhuriyet savcısı - hâkim"],"dogru":0,"aciklama":"m.16/1: '...soruşturma aşamasında hâkim, kovuşturma aşamasında mahkeme tarafından tasfiye kararı verilir.'","kaynak":"5607 m.16/1","zorluk":"orta"},
    {"id":"5607-S-025","soru":"5607 sayılı Kanun'a göre teknik düzenlemelere uygun olmadığı tespit edilen kaçak akaryakıt, il özel idaresi veya yatırım izleme ve koordinasyon başkanlığınca kime satılır?","siklar":["Kamu kurum ve kuruluşlarına bedelsiz tahsis edilir","En yakın rafineriye","Mahalli mülki amirin belirlediği bir şirkete","İlgili belediyeye","Millî Emlak Genel Müdürlüğüne"],"dogru":1,"aciklama":"m.16/A-3: '...teknik düzenlemelere uygun olmayan kaçak akaryakıt, il özel idaresi veya yatırım izleme ve koordinasyon başkanlığı tarafından en yakın rafinericiye satılır.'","kaynak":"5607 m.16/A","zorluk":"zor"},
    {"id":"5607-S-026","soru":"5607 sayılı Kanun'a göre bu Kanun kapsamına giren suçlar dolayısıyla açılan davalar kural olarak hangi mahkemede görülür?","siklar":["Ağır ceza mahkemesinde","Sulh ceza mahkemesinde","Asliye ceza mahkemesinde","İdare mahkemesinde","Bölge adliye mahkemesinde"],"dogru":2,"aciklama":"m.17/2: '...davalar... asliye ceza mahkemelerinde görülür. Ancak bu suçlarla bağlantılı olarak resmî belgede sahtecilik suçunun işlenmesi halinde, görevli mahkeme ağır ceza mahkemesidir.'","kaynak":"5607 m.17/2","zorluk":"kolay"},
    {"id":"5607-S-027","soru":"5607 sayılı Kanun'a göre gümrük idaresi, başvurusu olmasa dahi bu Kanun kapsamındaki davalara re'sen katılan sıfatıyla dahil edilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.18/1: '...Başvurusu üzerine, ilgili gümrük idaresi açılan davaya katılan olarak kabul edilir.' Katılan olma, gümrük idaresinin başvurusuna bağlıdır, re'sen olmaz.","kaynak":"5607 m.18/1","zorluk":"kolay"},
    {"id":"5607-S-028","soru":"5607 sayılı Kanun'a göre aşağıdakilerden hangisi kaçakçılık fiillerini önleme, izleme ve araştırmakla yükümlü kılınan kurumlar arasında sayılmamıştır?","siklar":["Mülkî amirler","Gümrük personeli","Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı","Türkiye Büyük Millet Meclisi Başkanlığı","Emniyet Genel Müdürlüğü"],"dogru":3,"aciklama":"m.19/1: 'Mülkî amirler, Gümrük Müsteşarlığı personeli ile Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığına bağlı personel... yükümlüdür.' TBMM Başkanlığı bu sayımda yer almaz.","kaynak":"5607 m.19/1","zorluk":"orta"},
    {"id":"5607-S-029","soru":"5607 sayılı Kanun'a göre kaçakçılık fiillerinin izlenmesine ilişkin tutanaklarda aşağıdakilerden hangisinin bulunması zorunlu unsurlar arasında sayılmamıştır?","siklar":["Tarih, yer ve düzenleyenlerin unvan ve isimleri","Hâkim kararının veya Cumhuriyet savcısının yazılı emrinin tarih ve sayısı","Olay ve kanıtlar, eşya ve taşıma araçlarının nitelikleri","İlgilinin kimlik, iş ve yerleşim yeri ile varsa ifadesi","İlgilinin daha önce kaçakçılıktan sabıkalı olup olmadığına ilişkin kayıt"],"dogru":4,"aciklama":"m.20/1 (a,b,c): tarih-yer-düzenleyen+karar/emir bilgisi, olay-kanıt-eşya, kimlik-iş-yerleşim-ifade unsurları sayılmıştır; sabıka kaydı tutanağın zorunlu unsuru olarak yer almaz.","kaynak":"5607 m.20/1","zorluk":"orta"},
    {"id":"5607-S-030","soru":"5607 sayılı Kanun'a göre yetkili memurlar, gümrük bölgesine izinsiz girmeye çalışan ve 'dur' uyarısına uymayan kişiye karşı önce hangi tedbiri uygular?","siklar":["Havaya ateş edilmek suretiyle uyarı yinelenir","Doğrudan hedefe ateş eder","Kelepçe takarak yakalar","Aracına ateş açar","Görmezden gelip devriyeye devam eder"],"dogru":0,"aciklama":"m.22/1: '...bu uyarıya uymaması halinde, havaya ateş edilmek suretiyle uyarı yinelenir. Ancak silâhla karşılığa yeltenilmesi ve sair surette meşru müdafaa durumuna düşülmesi halinde... doğrudan hedefe ateş edebilir.'","kaynak":"5607 m.22/1","zorluk":"kolay"},
    {"id":"5607-S-031","soru":"5607 sayılı Kanun'a göre dağıtılacak ikramiyenin kural olarak yüzde kaçı muhbirlere, yüzde kaçı elkoyma ikramiyesine hak kazananlara verilir?","siklar":["%25 muhbir - %75 elkoyma","%50 muhbir - %50 elkoyma","%75 muhbir - %25 elkoyma","%100 muhbir","%30 muhbir - %70 elkoyma"],"dogru":1,"aciklama":"m.23/2: 'Dağıtılacak ikramiyenin yüzde ellisi muhbirlere, yüzde ellisi elkoyma ikramiyesine hak kazananlara verilir.'","kaynak":"5607 m.23/2","zorluk":"kolay"},
    {"id":"5607-S-032","soru":"5607 sayılı Kanun'a göre kaçakçılığı önleme, izleme ve soruşturmakla görevli olanlardan yakalama işlemine bizzat ve fiilen katılanlar, elkoyma ikramiyesine hak kazanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.23/2: '...yakalama işlemine bizzat ve fiilen katılanlar... elkoyma ikramiyesine hak kazanır.' Bu kişilere muhbir ikramiyesi ödenmez, ancak elkoyma ikramiyesi ödenebilir.","kaynak":"5607 m.23/2","zorluk":"orta"},
    {"id":"5607-S-033","soru":"5607 sayılı Kanun'a göre kaçak eşya naklinde kullanılan bir taşıtın mülkiyetinin, belirli koşullardan birinin gerçekleşmesi hâlinde Devlete geçirilmesi işlemi hangisidir?","siklar":["Elkoyma","Alıkoyma","Müsadere","Tasfiye","İmha"],"dogru":2,"aciklama":"m.13/1: taşıtın mülkiyetinin Devlete geçmesi müsadere ile olur (aranan koşullardan biri gerçekleşince). Elkoyma (m.9) geçici zapttır, alıkoyma (m.10/2) taşıtı teminatla bekletir, tasfiye (m.16) ise eşyanın nihai olarak satış/imha yoluyla elden çıkarılmasıdır.","kaynak":"5607 m.9, m.10/2, m.13/1, m.16/1","zorluk":"zor"},
    {"id":"5607-S-034","soru":"5607 sayılı Kanun'a göre bir taşıta elkoyma sonrası, taşıt sahibinin taşıtı geri alabilmesi için teminatı hangi makama teslim etmesi gerekir?","siklar":["Cumhuriyet savcılığına","İl özel idaresine","Mahalli mülki amire","Gümrük idaresine","Asliye ceza mahkemesine"],"dogru":3,"aciklama":"m.10/2: '...taşıtın değeri kadar teminatı... gümrük idaresine teslim etmesi halinde, taşıt sahibine iade edilir.' Teminat teslim makamı gümrük idaresidir.","kaynak":"5607 m.10/2","zorluk":"orta"},
    {"id":"5607-S-035","soru":"5607 sayılı Kaçakçılıkla Mücadele Kanunu'na göre 'gümrük vergileri' ifadesi tanımlar maddesinde neyi kapsar?","siklar":["Yalnızca ithalat sırasında alınan vergileri","Yalnızca ihracat sırasında alınan vergileri","Gümrük idaresi veya başka idarelerce, eşyanın ithali veya ihracına bağlı olarak uygulanan vergiler ile diğer malî yükümlülükleri","Sadece gümrük idaresince alınan vergileri; diğer idarelerin yükümlülüklerini kapsamaz","Yalnızca katma değer vergisi ve özel tüketim vergisini"],"dogru":2,"aciklama":"m.2/1-a: 'Gümrük vergileri: Gümrük idaresi veya başka idarelerce, eşyanın ithali veya ihracına bağlı olarak uygulanan vergiler ile diğer malî yükümlülükleri...' ifade eder.","kaynak":"5607 m.2/1-a","zorluk":"kolay"},
    {"id":"5607-S-036","soru":"5607 sayılı Kanun'a göre eşyayı gümrük işlemlerine tabi tutmaksızın ülkeye sokan kişiye, gümrük kapıları dışından girişe ilişkin artırım uygulanmaksızın, verilecek temel hapis cezası aşağıdakilerden hangisidir?","siklar":["İki yıldan beş yıla kadar hapis","Altı aydan iki yıla kadar hapis","Üç yıldan altı yıla kadar hapis","Bir yıldan beş yıla kadar hapis","İki yıldan altı yıla kadar hapis"],"dogru":3,"aciklama":"m.3/1: 'Eşyayı, gümrük işlemlerine tabi tutmaksızın ülkeye sokan kişi, bir yıldan beş yıla kadar hapis ve on bin güne kadar adlî para cezası ile cezalandırılır.'","kaynak":"5607 m.3/1","zorluk":"kolay"},
    {"id":"5607-S-037","soru":"5607 sayılı Kanun'a göre m.3/10'da cezayı ağırlaştıran eşya türleri arasında aşağıdakilerden hangisi ayrıca isim olarak sayılmamıştır?","siklar":["Tütün mamulleri","Etil alkol","Makaron","Metanol","Sıvılaştırılmış petrol gazı"],"dogru":4,"aciklama":"m.3/10: '...eşyanın akaryakıt ile tütün, tütün mamulleri, makaron, yaprak sigara kâğıdı, etil alkol, metanol ve alkollü içkiler olması halinde...' Sıvılaştırılmış petrol gazı m.2/1-c'deki akaryakıt tanımının bir alt kalemidir; m.3/10 fıkrasında ayrıca isim olarak sayılmaz, 'akaryakıt' genel başlığı yeterli görülmüştür.","kaynak":"5607 m.3/10","zorluk":"orta"},
    {"id":"5607-S-038","soru":"5607 sayılı Kanun'a göre eşyayı aldatıcı işlem ve davranışlarla, gümrük vergilerini kısmen veya tamamen ödemeksizin ülkeye sokan kişiye verilecek ceza aşağıdakilerden hangisidir?","siklar":["Bir yıldan üç yıla kadar hapis","Bir yıldan beş yıla kadar hapis","Altı aydan iki yıla kadar hapis","İki yıldan altı yıla kadar hapis","İki yıldan beş yıla kadar hapis"],"dogru":4,"aciklama":"m.3/2: 'Eşyayı, aldatıcı işlem ve davranışlarla gümrük vergileri kısmen veya tamamen ödenmeksizin ülkeye sokan kişi, iki yıldan beş yıla kadar hapis ve on bin güne kadar adlî para cezası ile cezalandırılır.'","kaynak":"5607 m.3/2","zorluk":"orta"},
    {"id":"5607-S-039","soru":"5607 sayılı Kanun'a göre m.3'ün ilk dört fıkrasında tanımlanan fiillerin işlenmesine iştirak etmeksizin, konusu eşyayı bu özelliğini bilerek ticarî amaçla satın alan veya satan kişiye verilecek ceza nedir?","siklar":["İki yıldan beş yıla kadar hapis","Altı aydan iki yıla kadar hapis","Üç yıldan altı yıla kadar hapis","Bir yıldan üç yıla kadar hapis","İki yıldan altı yıla kadar hapis"],"dogru":3,"aciklama":"m.3/5: '...bunların konusunu oluşturan eşyayı, bu özelliğini bilerek ve ticarî amaçla satın alan, satışa arz eden, satan, taşıyan veya saklayan kişi, bir yıldan üç yıla kadar hapis ve beş bin güne kadar adlî para cezası ile cezalandırılır.'","kaynak":"5607 m.3/5","zorluk":"zor"},
    {"id":"5607-S-040","soru":"5607 sayılı Kanun'a göre ihracı kanun gereği yasak olan eşyayı ülkeden çıkaran kişiye, fiil daha ağır bir suç oluşturmadığı takdirde verilecek ceza nedir?","siklar":["İki yıldan altı yıla kadar hapis","İki yıldan beş yıla kadar hapis","Bir yıldan üç yıla kadar hapis","Altı aydan iki yıla kadar hapis","Üç yıldan altı yıla kadar hapis"],"dogru":2,"aciklama":"m.3/8: 'İhracı kanun gereği yasak olan eşyayı ülkeden çıkaran kişi, fiil daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde bir yıldan üç yıla kadar hapis ve beş bin güne kadar adlî para cezası ile cezalandırılır.'","kaynak":"5607 m.3/8","zorluk":"kolay"},
    {"id":"5607-S-041","soru":"5607 sayılı Kanun'a göre kaçakçılık suçunun konusu eşyanın değerinin fahiş olması halinde verilecek cezalar ....(1)...., hafif olması halinde ise ....(2).... Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üçte birinden yarısına kadar artırılır - üçte birine kadar indirilir","yarısına kadar artırılır - üçte birine kadar indirilir","iki kat artırılır - yarısına kadar indirilir","yarısından bir katına kadar artırılır - üçte birine kadar indirilir","yarısından bir katına kadar artırılır - yarısına kadar indirilir"],"dogru":4,"aciklama":"m.3/23: 'eşyanın değerinin fahiş olması hâlinde, verilecek cezalar yarısından bir katına kadar artırılır... Eşyanın değerinin hafif olması hâlinde verilecek cezalar yarısına kadar... indirilir.'","kaynak":"5607 m.3/23","zorluk":"zor"},
    {"id":"5607-S-042","soru":"5607 sayılı Kanun'a göre etkin pişmanlık göstererek indirimden yararlanma imkânı, soruşturma evresinde kural olarak kim tarafından şüpheliye ihtar edilir?","siklar":["Hâkim","Mahkeme başkanı","Gümrük idaresi","Cumhuriyet savcısı","Kolluk amiri"],"dogru":3,"aciklama":"m.5/2: 'Bu husus, soruşturma evresinde Cumhuriyet savcısı tarafından şüpheliye ihtar edilir. Soruşturma evresinde ihtar yapılmaması hâlinde kovuşturma evresinde hâkim tarafından sanığa ihtar yapılır.'","kaynak":"5607 m.5/2","zorluk":"orta"},
    {"id":"5607-S-043","soru":"5607 sayılı Kanun'a göre resmî makamlarca haber alındıktan sonra fiilin bütünüyle ortaya çıkmasına hizmet ve yardım eden kişiye verilecek ceza üçte iki oranında indirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5/1: 'Haber alındıktan sonra fiilin bütünüyle ortaya çıkmasına hizmet ve yardım eden kişiye verilecek ceza üçte iki oranında indirilir.'","kaynak":"5607 m.5/1","zorluk":"kolay"},
    {"id":"5607-S-044","soru":"5607 sayılı Kanun'a göre gümrük salonları ve gümrük kapılarında kaçak eşya sakladığından kuşkulanılan kişilerin üzeri, gümrük kontrolü amacıyla kimler tarafından aranabilir?","siklar":["Yalnızca Cumhuriyet savcısı kararıyla kolluk tarafından","Yalnızca hâkim kararıyla","Gümrük görevlilerince","Sahil Güvenlik personelince","Mülkî amirce"],"dogru":2,"aciklama":"m.9/2: '...kişilerin üzeri, eşyası, yükleri ve araçları gümrük kontrolü amacıyla gümrük görevlilerince aranabilir. Yapılan arama sonucunda tespit edilen kaçak eşyaya derhal elkonulur.'","kaynak":"5607 m.9/2","zorluk":"kolay"},
    {"id":"5607-S-045","soru":"5607 sayılı Kanun'a göre elkonulan bir taşıtın ayrıca alıkonulabilmesi için aşağıdaki hallerden hangisi aranmaz?","siklar":["Taşıt sahibinin daha önce adli sicil kaydının bulunması","Taşıtın, kaçak eşyanın gizli tertibatla saklanmasına ilişkin m.13/1-a kapsamına girmesi","Taşıtın Türkiye'de sicile kayıtlı olmaması","Soruşturma ve kovuşturma devam ederken taşıtın kaçakçılık suçunda tekrar kullanılması","Yukarıdaki hallerden herhangi birinin tek başına gerçekleşmesi yeterlidir"],"dogru":0,"aciklama":"m.10/2: '13 üncü maddenin birinci fıkrasının (a) bendi kapsamına girmesi, Türkiye'de sicile kayıtlı olmaması ya da soruşturma ve kovuşturma devam ederken, kaçakçılık suçunun işlenmesinde tekrar kullanılması halinde, elkonulan taşıt... alıkonulur.' Taşıt sahibinin adli sicil kaydı bu üç halden biri değildir.","kaynak":"5607 m.10/2","zorluk":"zor"},
    {"id":"5607-S-046","soru":"5607 sayılı Kanun'a göre kaçak şüphesiyle elkonulan eşya, genel kural olarak, ayırıcı özelliklerini gösterir bir tutanakla gümrük idaresine teslim edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.11/1: 'Kaçak şüphesiyle elkonulan eşya ile 10 uncu maddenin ikinci fıkrası gereğince alıkonulan her türlü taşıt ve araç; miktarı, cinsi, markası, tipi, modeli, seri numarası gibi eşyanın ayırıcı özelliklerini gösterir bir tutanakla gümrük idaresine teslim edilir.'","kaynak":"5607 m.11/1","zorluk":"kolay"},
    {"id":"5607-S-047","soru":"5607 sayılı Kanun'a göre ambalajında bandrol, etiket, hologram, pul veya damga bulunmadığı için el konulduğunda kural olarak imha edilen eşyalar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Tütün mamulleri","Kaçak akaryakıt","Etil alkol","Elektronik sigara ve elektronik nargile","İlaç ve ilaç hammaddeleri"],"dogru":1,"aciklama":"m.11/5: '...ambalajlarında kamu kurumlarınca uygulanan bandrol, etiket, hologram, pul, damga veya benzeri işaret bulunmayan tütün mamulleri, etil alkol, metanol, alkollü içkiler, makaron ve yaprak sigara kâğıdı ile ilaç, ilaç hammaddeleri... elektronik sigara ve elektronik nargile dahil her türlü mamul... imha edilir.' Kaçak akaryakıt bu fıkra kapsamında değildir.","kaynak":"5607 m.11/5","zorluk":"orta"},
    {"id":"5607-S-048","soru":"5607 sayılı Kanun'a göre kaçak akaryakıt hariç el konulan eşyanın muhafaza ve depolama masrafları Gümrük ve Ticaret Bakanlığı döner sermaye işletmesi gelirlerinden karşılanır ve bu kapsamdaki alımlarda Kamu İhale Kanunu hükümleri uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.11/6: '...masraflar, Gümrük ve Ticaret Bakanlığı döner sermaye işletmesi gelirlerinden karşılanır. Bu kapsamda yapılacak her türlü mal, araç, gereç ve hizmet alımlarında... Kamu İhale Kanunu hükümleri uygulanmaz.' Masrafların döner sermayeden karşılanması doğrudur ama Kamu İhale Kanunu uygulanmaz, uygulanır değil.","kaynak":"5607 m.11/6","zorluk":"orta"},
    {"id":"5607-S-049","soru":"5607 sayılı Kanun'a göre failin etkin pişmanlık nedeniyle cezalandırılmaması, suç konusu eşyanın müsadere edilmesine engel oluşturur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.13/2: 'Etkin pişmanlık nedeniyle fail hakkında cezaya hükmolunmaması veya kamu davasının düşmesine karar verilmesi, sadece suç konusu eşya ile ilgili olarak müsadere hükümlerinin uygulanmasına engel teşkil etmez.' Eşya yine müsadere edilebilir.","kaynak":"5607 m.13/2","zorluk":"zor"},
    {"id":"5607-S-050","soru":"5607 sayılı Kanun'a göre teknik düzenlemelere uygun olduğu tespit edilen kaçak akaryakıt nasıl tasfiye edilir?","siklar":["En yakın rafinericiye satılarak","Doğrudan bertaraf tesislerinde yakılarak","Milli Emlak Genel Müdürlüğüne devredilerek","Kamu kurum ve kuruluşları ile mahalli idarelerin kullanımına bedelsiz tahsis edilerek veya satışı yapılarak","Sahibine iade edilerek"],"dogru":3,"aciklama":"m.16/A-1: '...teknik düzenlemelere uygun olanlar, il özel idareleri, il özel idaresi bulunmayan yerde yatırım izleme ve koordinasyon başkanlıkları tarafından, numune alınmak suretiyle kamu kurum ve kuruluşları ile mahalli idarelerin kullanımına bedelsiz tahsis edilerek veya satışı yapılarak tasfiye edilir.'","kaynak":"5607 m.16/A-1","zorluk":"orta"},
    {"id":"5607-S-051","soru":"5607 sayılı Kanun'a göre yanaşma denetimine izin vermeyip kaçan bir deniz aracına önce telsiz, flama, mors gibi işaretlerle durması ihtar edilir; buna uyulmazsa ....(1)...., buna da uyulmayıp kaçmaya devam edilirse ....(2).... Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["doğrudan hedefe ateş edilir - araç batırılır","havaya ateş edilir - doğrudan hedefe ateş edilir","durmaya zorlayacak şekilde üzerine ateş edilir - uyarı mahiyetinde ateş edilir","araç takip edilir - mahkemeye bildirilir","uyarı mahiyetinde ateş edilir - durmaya zorlayacak şekilde üzerine ateş edilir"],"dogru":4,"aciklama":"m.22/2: 'Bu ihtara uymayan deniz araçlarına uyarı mahiyetinde ateş edilir. Buna da uymayıp kaçmaya devam ettiği takdirde durmaya zorlayacak şekilde üzerine ateş edilir.'","kaynak":"5607 m.22/2","zorluk":"zor"},
  ],
  42: [
    {"id":"3298-S-001","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre çizilmiş veya çizilmemiş haşhaş kapsülleri, ham afyon, tıbbi afyon ve morfin evsafını haiz afyon alkaloidleri ile koka yaprağı gibi maddelerin alımı, satımı, imali, ithali ve ihracı ile ilgili hususlar kimin tespit edeceği esaslara göre yürütülür?","siklar":["Sağlık ve Sosyal Yardım Bakanlığı","İçişleri Bakanlığı","Tarım ve Orman Bakanlığı","Cumhurbaşkanı","Türkiye Büyük Millet Meclisi"],"dogru":3,"aciklama":"m.1 f.1: '...alımı, satımı, imali, ithali ve ihracı ile ilgili hususlar Cumhurbaşkanının tespit edeceği esaslara göre yürütülür.'","kaynak":"3298 m.1","zorluk":"kolay"},
    {"id":"3298-S-002","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre madde 1 kapsamındaki maddelerin elde edildiği bitkilerin yurt içinde ekimi ve araştırması izne tabidir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.1 f.2 birebir: 'Bahis konusu maddelerin elde edildiği bitkilerin yurt içinde ekimi ve araştırması izne tabidir.'","kaynak":"3298 m.1","zorluk":"kolay"},
    {"id":"3298-S-003","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre kullanılması zararlı olduğu ve 'Toxicommanie' yaptığı tespit edilen diğer tabii ve sentetik maddelerin bu Kanun kapsamına alınması hangi usulle gerçekleşir?","siklar":["Sağlık ve Sosyal Yardım Bakanlığının doğrudan kararı ile","Cumhurbaşkanının doğrudan kararı ile, Bakanlık teklifi aranmaksızın","Sağlık ve Sosyal Yardım Bakanlığının teklifi üzerine Cumhurbaşkanı Kararı ile","Türkiye Büyük Millet Meclisi kararı ile","İlgili kuruluşun izin belgesi ile"],"dogru":2,"aciklama":"m.1 f.3: '...Sağlık ve Sosyal Yardım Bakanlığınca tespit edilen diğer tabii ve sentetik maddeler de yine bu Bakanlığın teklifi üzerine Cumhurbaşkanı Kararı ile bu Kanun kapsamına alınabilir.'","kaynak":"3298 m.1","zorluk":"orta"},
    {"id":"3298-S-004","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre haşhaş ekilecek, afyon ve kapsül üretilecek yerler her yıl ....(1).... tarafından tespit edilir ve karar en geç ....(2).... tarihine kadar yayımlanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Sağlık Bakanlığı - 1 Ocak","Cumhurbaşkanı - 1 Temmuz","İlgili kuruluş - 1 Ekim","Cumhurbaşkanı - 1 Ocak","Mahallî mülkî amir - 1 Temmuz"],"dogru":1,"aciklama":"m.2 f.1: '...her yıl Cumhurbaşkanınca tespit edilir ve karar en geç 1 Temmuza kadar yayımlanır.'","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-005","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre haşhaş ekilecek, afyon ve kapsül üretilecek yerlerin tespitinde aşağıdaki ölçütlerden hangisi kanunda sayılmamıştır?","siklar":["Memleketin tarımsal ve ekonomik durumu","Yurt içi ihtiyacı","İhraç imkanları","Mevcut stok durumu","Komşu ülkelerin talebi"],"dogru":4,"aciklama":"m.2 f.1: '...memleketin tarımsal ve ekonomik durumu, yurt içi ihtiyacı, ihraç imkanları ve mevcut stok durumuna göre...' Komşu ülkelerin talebi kanunda sayılan bir ölçüt değildir.","kaynak":"3298 m.2","zorluk":"zor"},
    {"id":"3298-S-006","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre kamu kurum ve kuruluşlarınca bilimsel araştırmalar için yapılacak haşhaş ekilişleri hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Bu ekilişler hakkında yer tespitine ilişkin birinci fıkra hükmü uygulanmaz","Bu ekilişler yasaktır","Bu ekilişler yalnızca Sağlık Bakanlığının iznine tabidir","Bu ekilişler için izin belgesi süresi iki üretim yılıdır","Bu ekilişler için de Cumhurbaşkanının yer tespiti hükmü aynen uygulanır"],"dogru":0,"aciklama":"m.2 f.2: 'Kamu kurum ve kuruluşlarınca bilimsel araştırmalar için yapılacak ekilişler hakkında birinci fıkra hükmü uygulanmaz.' Bu ekilişler yer tespiti kuralının istisnasıdır.","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-007","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre haşhaş ekimi için verilen izin belgesi ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Belge süresizdir ve başkasına devredilebilir","Belge iki üretim yılı için geçerlidir","Belge bir üretim yılı için geçerlidir ve başkasına devredilemez","Belge yalnızca Sağlık Bakanlığınca verilir","Belge devredilebilir ancak süresi altı aydır"],"dogru":2,"aciklama":"m.2 f.3: 'İzin belgeleri bir üretim yılı için geçerli olup, başkasına devir edilemez.'","kaynak":"3298 m.2","zorluk":"kolay"},
    {"id":"3298-S-008","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izin belgesi iptal edilen kişinin ekilmiş haşhaş tarlası, üreticiye bir bedel ödenerek ilgili kuruluşça toplatılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2 f.4: '...masrafı üreticiye ait olmak kaydıyla ilgili kuruluş adına herhangi bir bedel ödenmeksizin toplatılır veya imha ettirilir.' Üreticiye bedel ödenmez, üstelik masraf da üreticiye aittir.","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-009","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre madde 4 hükümlerine, kaçakçılık suçlarından veya Türk Ceza Kanununun ilgili maddelerine göre kesinleşmiş mahkûmiyeti bulunan kişi hakkında izin belgesi verilmesi konusunda aşağıdakilerden hangisi doğrudur?","siklar":["Mahkûmiyet affa uğramışsa izin belgesi verilebilir","Mahkûmiyetin kesinleşmesi izin belgesi verilmesine engel değildir","Yalnızca kaçakçılık suçundan mahkûmiyet engel oluşturur","Mahkûmiyet afla ortadan kalkmış olsa bile izin belgesi verilemez; verilmişse iptal edilir","İzin belgesi verilir ancak süresi kısaltılır"],"dogru":3,"aciklama":"m.2 f.5: '...bu mahkümiyetleri afla ortadan kalkmış olsa bile, izin belgesi verilemez; verilmiş ise iptal edilir.'","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-010","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izin belgesi verildikten sonra kişi, ilgili fıkrada sayılan suçlardan biriyle mahkûm olursa ne olur?","siklar":["Bu mahkûmiyet kesinleşmedikçe belge etkilenmez, kesinleştiğinde belge iptal edilir","Belge derhal, mahkûmiyetin kesinleşmesi beklenmeksizin iptal edilir","Belge etkilenmez, yalnızca yeni izin başvurularında dikkate alınır","Belge askıya alınır ancak iptal edilmez","Belge iptal edilir ama tarla üreticiye bedelsiz bırakılır"],"dogru":0,"aciklama":"m.2 f.6: 'İzin belgesi verilmesinden sonra yukarıdaki fıkrada yazılı suçlardan biri ile mahküm olanların bu mahkümiyetleri kesinleştiğinde izin belgeleri iptal edilir.' İptal, mahkûmiyetin kesinleşmesi şartına bağlıdır.","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-011","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre ham afyon, hazırlanmış afyon, tıbbî afyon ve bunların müstahzarları hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Türk Ceza Kanunu bakımından uyuşturucu madde sayılmaz","Yalnızca idari para cezası hükümlerine tabidir","Yalnızca 5607 sayılı Kanun kapsamında değerlendirilir","Sağlık Bakanlığının iznine bağlı olmaksızın serbestçe kullanılabilir","Türk Ceza Kanununun uygulanmasında uyuşturucu maddelerden sayılır"],"dogru":4,"aciklama":"m.4 f.1: 'Ham afyon, hazırlanmış afyon, tıbbî afyon ve bunların müstahzarları Türk Ceza Kanununun uygulanmasında uyuşturucu maddelerden sayılır.'","kaynak":"3298 m.4","zorluk":"orta"},
    {"id":"3298-S-012","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izinsiz olarak haşhaş ekimi yapan kişi ....(1).... hapis ve adlî para cezası ile; izin almış olmakla birlikte bilerek belgesinde belirtilen alandan fazla yerde veya belgede kayıtlı yerden başka yerde haşhaş ekimi yapan kişi ise ....(2).... hapis ve adlî para cezası ile cezalandırılır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["altı aydan üç yıla kadar - bir yıldan beş yıla kadar","iki yıldan beş yıla kadar - bir yıldan üç yıla kadar","bir yıldan beş yıla kadar - altı aydan üç yıla kadar","bir yıldan üç yıla kadar - altı aydan bir yıla kadar","altı aydan bir yıla kadar - iki yıldan beş yıla kadar"],"dogru":2,"aciklama":"m.4 f.2: '...bir yıldan beş yıla kadar hapis...'; f.3: '...altı aydan üç yıla kadar hapis...' İzinsiz ekim (ağır fiil) 1-5 yıl, izinli olup fazla/başka yerde ekim (hafif fiil) 6 ay-3 yıldır.","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-013","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre madde 4 kapsamında 'ekim yapma' ibaresinden ne anlaşılır?","siklar":["Yalnızca tohumun toprağa ekilmesi","Tohumun toprağa ekilmesinden ürünün hasadına kadarki süreç","Toprağın sürülmesinden tohumun ekilmesine kadarki süreç","Yalnızca ürünün hasat edilmesi","Hasat sonrası ürünün depolanması"],"dogru":1,"aciklama":"m.4 f.2: 'Bu madde kapsamında ekim yapma ibaresinden, tohumun toprağa ekilmesinden ürünün hasadına kadarki süreç anlaşılır.'","kaynak":"3298 m.4","zorluk":"orta"},
    {"id":"3298-S-014","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izin belgesinde tespit edilen miktardan az ham afyon veya kapsül teslim eden ve fiili suç oluşturmayan üreticiye uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["Cumhurbaşkanınca eksik miktarın üç misli idari para cezası","Sağlık Bakanlığınca altı aya kadar hapis cezası","İlgili kuruluşça izin belgesinin süresiz iptali","Mahallî mülkî amir tarafından eksik teslim edilen miktarların teslim anındaki baş alım fiyatının iki misli idari para cezası","Mahallî mülkî amir tarafından bir yıldan üç yıla kadar hapis cezası"],"dogru":3,"aciklama":"m.4 f.5: '...mahallî mülkî amir tarafından eksik teslim edilen miktarların teslim anındaki baş alım fiyatının iki misli kadar idarî para cezası verilir.'","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-015","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre kontrol ve denetim görevini yerine getirmeyen muhtarlar ve kolluk görevlileri hakkında hangi hüküm uygulanır?","siklar":["Türk Ceza Kanunu hükümlerine göre cezalandırılırlar","Mahallî mülkî amir tarafından idari para cezası verilir","Yalnızca disiplin cezası uygulanır, cezai sorumluluk doğmaz","Sağlık Bakanlığınca görevden uzaklaştırılırlar","İlgili kuruluşça izin belgeleri iptal edilir"],"dogru":0,"aciklama":"m.4 f.6: 'Kontrol ve denetim görevini yerine getirmeyen muhtarlar ve kolluk görevlileri, Türk Ceza Kanunu hükümlerine göre cezalandırılır.'","kaynak":"3298 m.4","zorluk":"orta"},
    {"id":"3298-S-016","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre madde 4'te tanımlanan suçların ekim bölgesi içinde işlenmesi halinde aşağıdakilerden hangisi doğrudur?","siklar":["5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanır","Yalnızca idari para cezası uygulanır, hapis cezası uygulanmaz","Türk Ceza Kanunu hükümleri hiçbir şekilde uygulanmaz","Ekim bölgesi dışında işlenen aynı suçlarla aynı şekilde cezalandırılmaz","5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanmaz"],"dogru":4,"aciklama":"m.4 f.7: 'Bu maddede tanımlanan suçların ekim bölgesi içinde işlenmesi halinde, 21/3/2007 tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanmaz.'","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-017","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre aşağıdaki görev-makam eşleştirmelerinden hangisi doğrudur?","siklar":["Ekim yerlerinin tespiti — Sağlık ve Sosyal Yardım Bakanlığı","Eksik teslimde idari para cezası verilmesi — Cumhurbaşkanı","İzin belgesinin verilmesi — ilgili kuruluş","Yeni maddelerin kanun kapsamına alınması teklifi — mahallî mülkî amir","Alım-satım-imal-ithal-ihraç esaslarının belirlenmesi — ilgili kuruluş"],"dogru":2,"aciklama":"m.2 f.3: izin belgesi 'ilgili kuruluştan' alınır. Diğer görevler farklı makamlara aittir: ekim yeri tespiti ve alım-satım esasları Cumhurbaşkanına (m.1 f.1, m.2 f.1), eksik teslim idari parası mahallî mülkî amire (m.4 f.5), yeni madde teklifi Sağlık ve Sosyal Yardım Bakanlığına (m.1 f.3) aittir.","kaynak":"3298 m.1, m.2, m.4","zorluk":"zor"},
    {"id":"3298-S-018","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre aşağıdaki fiillerden hangisi hapis cezası değil, idari para cezası ile sonuçlanır?","siklar":["İzinsiz haşhaş ekimi yapmak","İzin belgesinde belirtilen alandan fazla yerde haşhaş ekmek","İzinsiz ham afyon üretmek","İzin belgesinde tespit edilen miktardan az ürün teslim etmek (fiilin suç oluşturmaması hâlinde)","Kontrol görevini yerine getirmeyen kolluk görevlisi olmak"],"dogru":3,"aciklama":"m.4 f.5: eksik teslim, fiil suç oluşturmadığı takdirde mahallî mülkî amir tarafından idari para cezasına tabidir. A ve B fiilleri 3298'in kendi ceza hükmündeki hapis eşiklerine (m.4 f.2/f.3), C ve E fiilleri ise TCK'daki hapis yaptırımına (m.4 f.4/f.6) tabidir.","kaynak":"3298 m.4","zorluk":"orta"},
    {"id":"3298-S-019","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 1. maddesi 1. fıkrasına göre, madde 1 kapsamındaki maddelerle ilgili olarak Cumhurbaşkanının tespit edeceği esaslara tabi kılınan fiillerden aşağıdakilerden hangisi bu fıkrada SAYILMAMIŞTIR?","siklar":["Alımı","Satımı","İmali","İhracı","Depolanması"],"dogru":4,"aciklama":"m.1 f.1 birebir: '...alımı, satımı, imali, ithali ve ihracı ile ilgili hususlar Cumhurbaşkanının tespit edeceği esaslara göre yürütülür.' Depolanması bu fıkrada sayılan fiillerden biri değildir.","kaynak":"3298 m.1","zorluk":"kolay"},
    {"id":"3298-S-020","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 1. maddesinde Sağlık ve Sosyal Yardım Bakanlığına tanınan yetkiler hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Birinci fıkrada Bakanlık diğer uyuşturucu maddeleri tayin eder; üçüncü fıkrada ise Bakanlığın teklifi üzerine ayrıca Cumhurbaşkanı Kararı aranır","Birinci fıkradaki 'diğer uyuşturucu maddeleri tayin etme' yetkisi de üçüncü fıkradaki gibi mutlaka Cumhurbaşkanı Kararına bağlıdır","Üçüncü fıkradaki 'zararlı olup Toxicommanie yapan maddelerin kapsama alınması' Bakanlığın tek başına kararıyla gerçekleşir","Her iki fıkrada da yetki yalnızca Cumhurbaşkanına aittir, Bakanlığın herhangi bir rolü yoktur","Üçüncü fıkradaki yetki İçişleri Bakanlığına aittir"],"dogru":0,"aciklama":"m.1 f.1: '...Sağlık ve Sosyal Yardım Bakanlığınca tayin olunacak diğer uyuşturucu maddelerin...'; m.1 f.3: '...Sağlık ve Sosyal Yardım Bakanlığınca tespit edilen diğer tabii ve sentetik maddeler de yine bu Bakanlığın teklifi üzerine Cumhurbaşkanı Kararı ile bu Kanun kapsamına alınabilir.' İki fıkra da Bakanlığa görev verir ama yalnızca üçüncü fıkrada ayrıca Cumhurbaşkanı Kararı şarttır.","kaynak":"3298 m.1","zorluk":"zor"},
    {"id":"3298-S-021","soru":"3298 sayılı Kanun'un 1. maddesi 3. fıkrasına göre, kullanılması zararlı olduğu ve ....(1).... yaptığı Sağlık ve Sosyal Yardım Bakanlığınca tespit edilen diğer tabii ve sentetik maddeler, Bakanlığın teklifi üzerine Cumhurbaşkanı Kararı ile bu Kanun kapsamına alınabilir. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Bağımlılık","Zehirlenme","Sarhoşluk","Alışkanlık","\"Toxicommanie\""],"dogru":4,"aciklama":"m.1 f.3 birebir: '...Kullanılması zararlı olduğu ve \"Toxicommanie\" yaptığı Sağlık ve Sosyal Yardım Bakanlığınca tespit edilen diğer tabii ve sentetik maddeler...' Kanun metninde bu özgün ifade tırnak içinde kullanılır.","kaynak":"3298 m.1","zorluk":"orta"},
    {"id":"3298-S-022","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre haşhaş ekilecek yerlere ilişkin o yıl için yeni bir karar alınmaması halinde, önceki kararname hükümlerinin uygulanmasına devam olunur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.2 f.1 birebir: 'Bu konuda yeni bir karar alınmaması halinde, önceki kararname hükümlerinin uygulanmasına devam olunur.'","kaynak":"3298 m.2","zorluk":"kolay"},
    {"id":"3298-S-023","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izin belgesi verilmesine engel oluşturan (verilmişse iptaline yol açan) kesinleşmiş mahkûmiyetler hangi suç gruplarını kapsar?","siklar":["Yalnızca bu Kanunun 4 üncü maddesi hükümlerine göre mahkûmiyeti","Bu Kanunun 4 üncü maddesi hükümlerine göre, kaçakçılık suçlarının herhangi birinden veya Türk Ceza Kanununun ilgili maddelerine göre mahkûmiyetlerin herhangi birini","Yalnızca kaçakçılık suçlarından mahkûmiyeti","Yalnızca Türk Ceza Kanununun ilgili maddelerine göre mahkûmiyeti","Yalnızca trafik suçlarından mahkûmiyeti"],"dogru":1,"aciklama":"m.2 f.5 birebir: '4 üncü madde hükümlerine göre veya kaçakçılık suçlarının herhangi birisinden veya Türk Ceza Kanununun ilgili maddelerine göre kesinleşmiş mahkümiyeti bulunanlara... izin belgesi verilemez.' Üç kategori birlikte, herhangi biri yeterli olacak biçimde düzenlenmiştir.","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-024","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 4. maddesi (cezai hükümler) hangi kanunla değiştirilerek bugünkü hâlini almıştır ve bu değişiklik ne zaman yürürlüğe girmiştir?","siklar":["5237 sayılı Kanun ile, 1/6/2005","5607 sayılı Kanun ile, 21/3/2007","5728 sayılı Kanun ile, 8/2/2008","700 sayılı KHK ile, 9/7/2018","2061 sayılı Kanun ile, 3/7/1932"],"dogru":2,"aciklama":"Madde 4 başlığı altında '(Değişik: 23/1/2008-5728/457 md.)' ibaresi yer alır; kanuna ek tabloya göre 5728 sayılı Kanunun 3298'in 4. maddesindeki değişikliği 8/2/2008 tarihinde yürürlüğe girmiştir.","kaynak":"3298 m.4","zorluk":"kolay"},
    {"id":"3298-S-025","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 4. maddesine göre aşağıdaki fiillerden hangisinin tanımında kanun metninde açıkça 'bilerek' ibaresi kullanılmıştır?","siklar":["İzinsiz olarak haşhaş ekimi yapmak","İzinsiz ham afyon üretmek","İzin belgesinde tespit edilen miktardan az ürün teslim etmek","İzin almış olmakla birlikte belgesinde belirtilen alandan fazla yerde veya belgede kayıtlı yerden başka yerde haşhaş ekimi yapmak","Kontrol ve denetim görevini yerine getirmemek"],"dogru":3,"aciklama":"m.4 f.3 birebir: 'İzin almış olmakla birlikte, bilerek belgesinde belirtilen alandan fazla yerde veya izin belgesinde kayıtlı yerden başka yerde haşhaş ekimi yapan kişi...' İbare yalnızca bu fıkrada geçer; m.4 f.2 (izinsiz ekim) metninde 'bilerek' ifadesi yoktur.","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-026","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 4. maddesi 1. fıkrasına göre, Türk Ceza Kanununun uygulanmasında uyuşturucu maddelerden sayılanlar arasında aşağıdakilerden hangisi YOKTUR?","siklar":["Morfin evsafını haiz afyon alkaloidleri","Ham afyon","Hazırlanmış afyon","Tıbbî afyon","Bunların müstahzarları"],"dogru":0,"aciklama":"m.4 f.1 birebir: 'Ham afyon, hazırlanmış afyon, tıbbî afyon ve bunların müstahzarları Türk Ceza Kanununun uygulanmasında uyuşturucu maddelerden sayılır.' Morfin evsafını haiz afyon alkaloidleri m.1 f.1'de geçen ayrı bir ifadedir, m.4 f.1'de sayılmamıştır.","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-027","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izinsiz ham afyon üretenler hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Kanunun kendisinde belirtilen 1 yıldan 5 yıla kadar hapis cezası uygulanır","Yalnızca mahallî mülkî amir tarafından idari para cezası uygulanır","Fiil yalnızca disiplin sorumluluğu doğurur, cezai sorumluluk doğmaz","İzin belgeleri iptal edilir, başkaca bir yaptırım uygulanmaz","Kanun bu fiil için ayrı bir ceza miktarı öngörmez; Türk Ceza Kanunu hükümlerine göre cezalandırılır"],"dogru":4,"aciklama":"m.4 f.4 birebir: 'İzinsiz ham afyon üretenler, Türk Ceza Kanunu hükümlerine göre cezalandırılır.' 3298 bu fiil için kendi somut ceza miktarını belirlemez, doğrudan TCK'ya atıf yapar.","kaynak":"3298 m.4","zorluk":"orta"},
    {"id":"3298-S-028","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 4. maddesi son fıkrasına göre, madde 4'te tanımlanan suçların ekim bölgesi içinde işlenmesi halinde ....(1).... tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanmaz. Boşluğa gelmesi gereken tarih hangisidir?","siklar":["8/2/2008","21/3/2007","9/7/2018","3/6/1986","23/1/2008"],"dogru":1,"aciklama":"m.4 f.7 birebir: 'Bu maddede tanımlanan suçların ekim bölgesi içinde işlenmesi halinde, 21/3/2007 tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanmaz.'","kaynak":"3298 m.4","zorluk":"zor"},
    {"id":"3298-S-029","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 1. maddesi 1. fıkrasına göre, aşağıdakilerden hangisi bu fıkrada Cumhurbaşkanının tespit edeceği esaslara tabi kılınan fiillerden biri DEĞİLDİR?","siklar":["Alımı","Satımı","İmali","İhracı","Nakliyesi"],"dogru":4,"aciklama":"m.1 f.1 birebir: '...alımı, satımı, imali, ithali ve ihracı ile ilgili hususlar Cumhurbaşkanının tespit edeceği esaslara göre yürütülür.' Nakliyesi (taşınması) bu fıkrada sayılan fiillerden biri değildir.","kaynak":"3298 m.1","zorluk":"kolay"},
    {"id":"3298-S-030","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre ilgili kuruluştan izin belgesi almakla kim yükümlüdür?","siklar":["Sağlık ve Sosyal Yardım Bakanlığınca tayin edilen tüm üreticiler","Yalnızca kamu kurum ve kuruluşları","Tespit ve ilan edilen yerlerde haşhaş ekimi yapacak olanlar","Yalnızca bilimsel araştırma yapan kuruluşlar","Mahallî mülkî amirin belirlediği kişiler"],"dogru":2,"aciklama":"m.2 f.3 birebir: 'Tespit ve ilan edilen yerlerde haşhaş ekimi yapacaklar ilgili kuruluştan izin belgesi almakla yükümlüdür.'","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-031","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre izin belgesi iptal edilen kişinin ekilmiş haşhaş tarlası yalnızca toplatılabilir; imha edilmesi kanunen mümkün değildir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2 f.4: '...ilgili kuruluş adına herhangi bir bedel ödenmeksizin toplatılır veya imha ettirilir.' Kanun toplatma ile imhayı seçenek olarak birlikte öngörür, imha da kanunen mümkündür.","kaynak":"3298 m.2","zorluk":"orta"},
    {"id":"3298-S-032","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 1. ve 2. maddelerinde geçen 'Bakanlar Kurulu/Bakanlar Kurulunca/kararname' ibareleri hangi düzenlemeyle ve ne zaman 'Cumhurbaşkanı/Cumhurbaşkanınca/karar' şeklinde değiştirilmiştir?","siklar":["5728 sayılı Kanun ile, 8/2/2008","5607 sayılı Kanun ile, 21/3/2007","2061 sayılı Kanun ile, 3/7/1932","700 sayılı KHK ile, Cumhurbaşkanının andiçerek göreve başladığı tarihte (9/7/2018)","3298 sayılı Kanunun ilk kabulüyle birlikte, 3/6/1986"],"dogru":3,"aciklama":"Kanuna ek tabloya göre: 'KHK/700, 1, 2, Yürürlüğe Giriş Tarihi: 24/6/2018 tarihinde birlikte yapılan Türkiye Büyük Millet Meclisi ve Cumhurbaşkanlığı seçimleri sonucunda Cumhurbaşkanının andiçerek göreve başladığı tarihte (9/7/2018).' 700 sayılı KHK ile 1 ve 2. maddelerdeki ibareler değiştirilmiştir.","kaynak":"3298 m.1, m.2","zorluk":"zor"},
    {"id":"3298-S-033","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'un 1. maddesi, kapsamındaki maddelerin izinsiz ekimi veya üretimi hâlinde uygulanacak hapis cezalarını da doğrudan düzenler.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.1 yalnızca alım-satım-imal-ithal-ihraç esaslarını, ekim/araştırmanın izne tabi olduğunu ve yeni madde kapsama alma usulünü düzenler; cezai hükümler ayrıca ve yalnızca m.4'te ('Cezai hükümler' başlığı altında) yer alır.","kaynak":"3298 m.1, m.4","zorluk":"kolay"},
    {"id":"3298-S-034","soru":"3298 sayılı Uyuşturucu Maddelerle İlgili Kanun'a göre aşağıdaki iki durum karşılaştırıldığında hangisi doğrudur: (i) izin belgesi iptal edilen kişinin ekilmiş tarlasının akıbeti, (ii) izin belgesinde tespit edilen miktardan az ürün teslim eden ve fiili suç oluşturmayan üreticinin durumu?","siklar":["Her iki durumda da yaptırım aynıdır: idari para cezası","Her iki durumda da üreticiye bedel ödenir","(i) durumunda tarla bedelsiz toplatılır/imha edilir; (ii) durumunda ise baş alım fiyatının iki misli idari para cezası verilir — ikisi farklı yaptırım türleridir","(i) durumunda hapis cezası uygulanır; (ii) durumunda tarla toplatılır","(i) durumunda idari para cezası verilir; (ii) durumunda tarla toplatılır"],"dogru":2,"aciklama":"m.2 f.4: iptal edilen izin belgesi sahibinin tarlası 'herhangi bir bedel ödenmeksizin toplatılır veya imha ettirilir.' m.4 f.5: eksik teslimde 'mahallî mülkî amir tarafından... baş alım fiyatının iki misli kadar idarî para cezası verilir.' İki hüküm farklı fiillere farklı yaptırımlar öngörür.","kaynak":"3298 m.2, m.4","zorluk":"orta"},
  ],
  43: [
    {"id":"6222-S-001","soru":"6222 sayılı Sporda Şiddet ve Düzensizliğin Önlenmesine Dair Kanun'a göre il spor güvenlik kurulu kimin başkanlığında oluşur?","siklar":["Vali veya görevlendireceği vali yardımcısı","İl emniyet müdürü","İl jandarma komutanı","Gençlik ve spor il müdürü","Kaymakam"],"dogru":0,"aciklama":"m.4/1: 'İl spor güvenlik kurulu, vali veya görevlendireceği vali yardımcısının başkanlığında ... oluşur.' Kurula bizzat vali veya onun görevlendirdiği vali yardımcısı başkanlık eder.","kaynak":"6222 m.4/1","zorluk":"kolay"},
    {"id":"6222-S-002","soru":"6222 sayılı Kanun'a göre ilçe spor güvenlik kurulu kimin başkanlığında oluşur?","siklar":["Vali yardımcısı","İl emniyet müdürü","Belediye başkanı","Kaymakam","İlçe jandarma komutanı"],"dogru":3,"aciklama":"m.4/2: 'İlçe spor güvenlik kurulu, kaymakam başkanlığında ... oluşur.' İlçede başkanlık kaymakama aittir.","kaynak":"6222 m.4/2","zorluk":"kolay"},
    {"id":"6222-S-003","soru":"6222 sayılı Kanun'a göre aşağıdakilerden hangisi il spor güvenlik kurulunun oluşumunda sayılan temsilciler arasında yer almamaktadır?","siklar":["İl jandarma komutanlığı temsilcisi","Cumhuriyet başsavcılığı temsilcisi","İl sağlık müdürlüğü temsilcisi","Vali tarafından belirlenecek bir hukukçu","İlgili federasyon temsilcisi"],"dogru":1,"aciklama":"m.4/1: Kurul, 'belediye başkanlığı, il jandarma komutanlığı, il emniyet müdürlüğü, gençlik ve spor il müdürlüğü, il sağlık müdürlüğü, il milli eğitim müdürlüğü, ilgili federasyon ve amatör spor kulüpleri konfederasyon temsilcileri, vali tarafından belirlenecek bir hukukçu ile ... stat güvenliğinden sorumlu yönetim kurulu üyesi ... temsilcilerinden oluşur.' Cumhuriyet başsavcılığı bu sayımda geçmez.","kaynak":"6222 m.4/1","zorluk":"orta"},
    {"id":"6222-S-004","soru":"6222 sayılı Kanun'a göre müsabaka, antrenman ve seyir alanlarının güvenliğini sağlamaya yetecek sayıda özel güvenlik görevlisi bulundurmakla kimler yükümlüdür?","siklar":["Yalnızca amatör spor kulüpleri","Yalnızca futbol federasyonu","İl spor güvenlik kurulu","Genel kolluk birimleri tek başına","Profesyonel spor dallarında müsabakalara katılanlar ile basketbolun en üst ligindeki spor kulüpleri"],"dogru":4,"aciklama":"m.6/1: 'Profesyonel spor dallarında yapılan müsabakalara katılanlar ile basketbol en üst ligindeki spor kulüpleri, genel kolluk ile birlikte görev yapmak üzere güvenliği sağlamaya yetecek sayıdaki özel güvenlik görevlilerini ... bulundurmakla ... yükümlüdür.'","kaynak":"6222 m.6/1","zorluk":"kolay"},
    {"id":"6222-S-005","soru":"6222 sayılı Kanun'a göre spor kulüpleri, özel güvenlik görevlileri dışında, müsabakalarda seyirci sağlığını ve emniyetini ilgilendiren konularda çalıştırmak üzere ayrıca kulüp görevlileri bulundurmakla yükümlüdür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/2: 'Spor kulüpleri, özel güvenlik görevlileri dışında müsabakalarda seyirci sağlığını ve emniyetini ilgilendiren konularda çalıştırmak üzere ayrıca kulüp görevlileri bulundurmakla yükümlüdür.'","kaynak":"6222 m.6/2","zorluk":"orta"},
    {"id":"6222-S-006","soru":"6222 sayılı Kanun'a göre müsabaka, antrenman ve seyir alanlarında görev yapan özel güvenlik görevlileri, bu Kanundan doğan görevlerinin ifası sırasında ateşli silah taşıyabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6/4: 'Bu Kanundan doğan görevlerinin ifası sırasında, özel güvenlik görevlilerinin ateşli silah taşımaları yasaktır.'","kaynak":"6222 m.6/4","zorluk":"kolay"},
    {"id":"6222-S-007","soru":"6222 sayılı Kanun'a göre müsabakada görevlendirilecek özel güvenlik görevlilerinin kimlik bilgileri, müsabakanın başlangıç saatinden en geç ....(1).... önce ilgili kolluk birimine bildirilir. İl veya ilçe spor güvenlik kurulları tarafından belirlenen özel güvenlik görevlisi sayısının ....(2).... geçmeyecek, yüksek riskli müsabakalarda ise ....(3).... geçmeyecek sayıda ve bunların yerine genel kolluk görevlisi görevlendirilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["24 saat - yarısını - üçte ikisini","48 saat - üçte ikisini - yarısını","72 saat - yarısını - üçte ikisini","48 saat - yarısını - üçte ikisini","48 saat - yarısını - dörtte üçünü"],"dogru":3,"aciklama":"m.6/3: 'Müsabakada görevlendirilecek özel güvenlik görevlilerinin kimlik bilgileri müsabakanın başlangıç saatinden en geç kırk sekiz saat önce ilgili kolluk birimine bildirilir. ... İl veya ilçe spor güvenlik kurulları tarafından belirlenen özel güvenlik görevlisi sayısının yarısını, yüksek riskli müsabakalarda ise üçte ikisini geçmeyecek sayıda ve bunların yerine genel kolluk görevlisi bu şekilde görevlendirilir.'","kaynak":"6222 m.6/3","zorluk":"zor"},
    {"id":"6222-S-008","soru":"6222 sayılı Kanun'a göre özel güvenlik yerine görevlendirilen kolluk görevlilerine ve gözlemci kolluk görevlilerine, günlük harcırah miktarının ne kadarı ödenir?","siklar":["İki katı","Yarısı","Dört katı","Üç katı","Bir buçuk katı"],"dogru":3,"aciklama":"m.6/3: '... görevlendirildikleri müsabaka ile sınırlı olarak günlük harcırah miktarının üç katı kadar ödeme yapılır. ... Gözlemci kolluk görevlilerine ise seyahat ve konaklama giderleri ile günlük harcırah üç katı olarak ödenir.'","kaynak":"6222 m.6/3","zorluk":"orta"},
    {"id":"6222-S-009","soru":"6222 sayılı Kanun'a göre müsabaka güvenlik amiri veya yardımcısının görevi aşağıdakilerden hangisidir?","siklar":["Spor müsabakalarında alınacak güvenlik önlemlerinin yürütülmesi ve denetlenmesi konularında ilgili kişi ve kuruluşlarla koordinasyonu sağlamak","Özel güvenlik şirketlerine faaliyet izni vermek","İl spor güvenlik kurulunun başkanlığını yapmak","Spor alanına girişte yapılacak üst ve eşya aramasını bizzat mülki amir sıfatıyla yazılı olarak emretmek","Federasyonun disiplin cezalarını onaylamak"],"dogru":0,"aciklama":"m.7/1: 'Müsabaka güvenlik amiri veya yardımcısı, spor müsabakalarında alınacak güvenlik önlemlerinin yürütülmesi ve denetlenmesi konularında, müsabakanın güvenliği ile ilgili tüm kişi ve kuruluşlarla gerekli koordinasyonu sağlamakla yetkili ve görevlidir.'","kaynak":"6222 m.7/1","zorluk":"orta"},
    {"id":"6222-S-010","soru":"6222 sayılı Kanun'a göre her spor güvenlik birimi amiri, hangi liglerde faaliyet gösteren kulüplerle ilgili birer kolluk görevlisini gözlemci olarak görevlendirmekle yükümlüdür?","siklar":["Yalnızca en üst ligde","Tüm profesyonel ve amatör ligler","Yalnızca basketbolun en üst liginde","Yalnızca yüksek riskli müsabakalarda","Futbolda en üst lig ve bir altındaki lig"],"dogru":4,"aciklama":"m.7/2: 'Her spor güvenlik birimi amiri, futbolda en üst lig ve bir altındaki lig için, her bir kulüple ilgili bir kolluk görevlisini gözlemci olarak görevlendirmekle yükümlüdür.'","kaynak":"6222 m.7/2","zorluk":"orta"},
    {"id":"6222-S-011","soru":"6222 sayılı Kanun'a göre gözlemci olarak görevlendirilen kolluk görevlisi, ilgili kulübün deplasman maçları dahil bütün maçlarında görevlendirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.7/2: 'Belirlenen kolluk görevlisi, deplasman maçları dahil ilgili kulübün bütün maçlarında görevlendirilir.'","kaynak":"6222 m.7/2","zorluk":"kolay"},
    {"id":"6222-S-012","soru":"6222 sayılı Kanun'a göre tribünlerdeki genel kolluk görevlilerinin sayısının her zaman artırılmasına karar verme yetkisi kime aittir?","siklar":["İl spor güvenlik kurulu","Müsabaka güvenlik amiri","Vali","İlgili federasyon","Gözlemci kolluk görevlisi"],"dogru":1,"aciklama":"m.7/3: 'Müsabaka güvenlik amiri her zaman tribünlerdeki genel kolluk görevlilerinin sayısının artırılmasına karar verebilir.'","kaynak":"6222 m.7/3","zorluk":"orta"},
    {"id":"6222-S-013","soru":"6222 sayılı Kanun'a göre spor kulüplerinin müsabaka ve seyir alanında bulundurmakla yükümlü oldukları özel güvenlik görevlilerinin sayısını ve görev alacakları yerleri belirlemeye hangi merci yetkilidir?","siklar":["Müsabaka güvenlik amiri","İlgili federasyon","İl veya ilçe spor güvenlik kurulları","Mülki amir","Genel kolluk amiri"],"dogru":2,"aciklama":"m.7/4: 'İl veya ilçe spor güvenlik kurulları, müsabaka ve seyir alanında spor kulüplerinin bulundurmakla yükümlü oldukları özel güvenlik görevlilerinin sayısını ve görev alacakları yerleri belirlemekle yetkilidir.'","kaynak":"6222 m.7/4","zorluk":"orta"},
    {"id":"6222-S-014","soru":"6222 sayılı Kanun'a göre spor müsabakalarından önce müsabakanın güvenliğine ilişkin yapılan eş güdüm toplantısına kim başkanlık eder?","siklar":["Vali","İl spor güvenlik kurulu başkanı","Kaymakam","İlgili federasyon temsilcisi","Müsabaka güvenlik amiri"],"dogru":4,"aciklama":"m.7/5: 'Spor müsabakalarından önce müsabaka güvenlik amirinin başkanlığında müsabakanın güvenliğine ilişkin eş güdüm toplantısı yapılır.'","kaynak":"6222 m.7/5","zorluk":"zor"},
    {"id":"6222-S-015","soru":"6222 sayılı Kanun'a göre aşağıdakilerden hangisinin müsabaka, seyir, özel seyir ve antrenman alanları ile toplu seyahat araçlarına sokulması m.12/1 uyarınca mutlak biçimde yasaklanmıştır?","siklar":["Ruhsatlı dahi olsa ateşli silahlar","Kesici, ezici, bereleyici veya delici aletler","Patlayıcı, parlayıcı, yanıcı veya yakıcı maddeler","Uyuşturucu veya uyarıcı maddeler","Alkollü içecekler"],"dogru":4,"aciklama":"m.12/1: (a) ruhsatlı dahi olsa ateşli silahlar ile esasen yasak diğer silahlar, (b) kesici-ezici-bereleyici-delici aletler ile patlayıcı-parlayıcı-yanıcı-yakıcı maddeler, (c) uyuşturucu veya uyarıcı maddelerin sokulması yasaktır. Devamında ise 'Müsabaka, seyir ve antrenman alanlarında alkollü içecek sokulması, kullanılması ve satılmasına ilişkin usul ve esaslar ilgili federasyonlar tarafından belirlenir'; yani alkol mutlak yasak değil, federasyonun düzenlemesine tabidir.","kaynak":"6222 m.12/1","zorluk":"orta"},
    {"id":"6222-S-016","soru":"6222 sayılı Kanun'a göre ruhsatlı olan ateşli silahların spor müsabaka alanlarına sokulması serbesttir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/1(a): 'Ruhsatlı dahi olsa ateşli silahlar ile esasen bulundurulması yasak olan diğer silahların ... sokulması yasaktır.'","kaynak":"6222 m.12/1","zorluk":"kolay"},
    {"id":"6222-S-017","soru":"6222 sayılı Kanun'a göre müsabaka, seyir ve antrenman alanlarında alkollü içecek sokulması, kullanılması ve satılmasına ilişkin usul ve esasları kim belirler?","siklar":["İçişleri Bakanlığı","İl spor güvenlik kurulu","İlgili federasyonlar","Mülki amir","Gençlik ve Spor Bakanlığı"],"dogru":2,"aciklama":"m.12/1 son cümle: 'Müsabaka, seyir ve antrenman alanlarında alkollü içecek sokulması, kullanılması ve satılmasına ilişkin usul ve esaslar ilgili federasyonlar tarafından belirlenir.'","kaynak":"6222 m.12/1","zorluk":"orta"},
    {"id":"6222-S-018","soru":"6222 sayılı Kanun'a göre genel kolluk görevlileri ile gözetimindeki özel güvenlik görevlilerinin, spor alanına girişte izleyicilerin üstünü ve eşyasını arayabilmesi hangi merciin yazılı emrine dayanır?","siklar":["Cumhuriyet savcısı","Sulh ceza hâkimi","Mülki amir","İl spor güvenlik kurulu","Müsabaka güvenlik amiri"],"dogru":2,"aciklama":"m.12/2: '... genel kolluk görevlileri ile bunların gözetiminde olmak üzere özel güvenlik görevlileri, mülki amirin yazılı emrine istinaden, spor alanına girişte izleyicilerin üstünü ve eşyasını ... arayabilir.'","kaynak":"6222 m.12/2","zorluk":"orta"},
    {"id":"6222-S-019","soru":"6222 sayılı Kanun'a göre spor müsabakası öncesinde, esnasında ve sonrasında taraftarların üzeri ve eşyasının 2559 sayılı Polis Vazife ve Salahiyet Kanunu hükümlerine göre aranması hangi tür aramadır?","siklar":["Adli arama","Disiplin araması","Gümrük araması","Önleme araması","Adli kovuşturma araması"],"dogru":3,"aciklama":"m.12/3: 'Spor müsabakası öncesinde, esnasında ve sonrasında spor alanında taraftarların üzeri ve eşyası ... 2559 sayılı Polis Vazife ve Salahiyet Kanununun önleme aramasına ilişkin hükümlerine göre aranabilir.' m.12/4'te ise CMK'nın adli aramaya ilişkin hükümlerinin saklı olduğu ayrıca belirtilmiştir; ikisi farklı hukuki temellere dayanır.","kaynak":"6222 m.12/3-4","zorluk":"orta"},
    {"id":"6222-S-020","soru":"6222 sayılı Kanun'a göre m.12/1'in (b) ve (c) bentleri kapsamına giren alet veya maddeleri spor alanında seyyar olarak satan, satışa arz eden, dağıtan veya dağıtmak için bulunduran kişileri bu alandan uzaklaştırmakla kimler yükümlüdür?","siklar":["Yalnızca genel kolluk görevlileri","Yalnızca belediye zabıtası","Genel kolluk görevlileri ve belediye zabıtası","Müsabaka güvenlik amiri","Özel güvenlik görevlileri"],"dogru":2,"aciklama":"m.12/5: 'Genel kolluk görevlileri ve belediye zabıtası birinci fıkranın (b) ve (c) bentleri kapsamına giren alet veya maddeleri spor alanında seyyar olarak satan, satışa arz eden, dağıtan veya dağıtmak için bulunduran kişileri bu alandan uzaklaştırmakla yükümlüdür.'","kaynak":"6222 m.12/5","zorluk":"orta"},
    {"id":"6222-S-021","soru":"6222 sayılı Kanun'a göre aşağıdaki makam-yetki eşleştirmelerinden hangisi yanlıştır?","siklar":["İl spor güvenlik kurulu başkanı - Vali veya görevlendireceği vali yardımcısı","İlçe spor güvenlik kurulu başkanı - Kaymakam","Tribündeki genel kolluk sayısını artırma yetkisi - Müsabaka güvenlik amiri","Spor alanına girişte üst/eşya araması emri - İl spor güvenlik kurulu","Özel güvenlik görevlisi sayısı ve görev yerini belirleme - İl veya ilçe spor güvenlik kurulu"],"dogru":3,"aciklama":"m.12/2: Spor alanına girişte üst/eşya araması 'mülki amirin yazılı emrine istinaden' yapılır; il spor güvenlik kurulunun böyle bir arama emri verme yetkisi yoktur. Diğer eşleştirmeler doğrudur: il kurulu başkanı vali/vali yardımcısı (m.4/1), ilçe kurulu başkanı kaymakam (m.4/2), tribün kolluk artırma yetkisi müsabaka güvenlik amirine (m.7/3), özel güvenlik sayı/yer belirleme il veya ilçe spor güvenlik kuruluna (m.7/4) aittir.","kaynak":"6222 m.4, m.7, m.12","zorluk":"zor"},
    {"id":"6222-S-022","soru":"6222 sayılı Kanun'a göre, bu Kanunda yer alan yükümlülüklerini yerine getirmek amacıyla özel güvenlik hizmeti satın alabilecek olanlar kimlerdir?","siklar":["Yalnızca il spor güvenlik kurulları","Yalnızca genel kolluk birimleri","Yalnızca gençlik ve spor il müdürlükleri","Müsabaka güvenlik amirleri","Federasyonlar ve spor kulüpleri"],"dogru":4,"aciklama":"m.6/3: 'Federasyonlar ve spor kulüpleri, bu Kanunda yer alan yükümlülüklerini yerine getirmek amacıyla özel güvenlik hizmeti satın alabilir.'","kaynak":"6222 m.6/3","zorluk":"orta"},
    {"id":"6222-S-023","soru":"6222 sayılı Kanun'a göre, güvenliğin sağlanması amacıyla görevde olmayan genel kolluk görevlilerinin de görevlendirilebileceği müsabakalar hangi ligin kulüplerine aittir?","siklar":["Basketbolun en üst ligi","Futbolda en üst lig ve bir altındaki lig","Tüm amatör ligler","En üst profesyonel futbol ligi","Yalnızca yüksek riskli müsabakalar"],"dogru":3,"aciklama":"m.6/3: 'En üst profesyonel futbol ligi kulüplerinin müsabakalarında güvenliğin sağlanması amacıyla genel kolluk görevlilerinden, görevde olmayanlar da görevlendirilebilir.'","kaynak":"6222 m.6/3","zorluk":"orta"},
    {"id":"6222-S-024","soru":"6222 sayılı Kanun'a göre, görevde olmayan genel kolluk görevlilerinin en üst profesyonel futbol ligi müsabakalarında görevlendirilmesi hangi usulle yapılır?","siklar":["İlgili kulübün başvurusu ve federasyonun talebi üzerine, müsabakanın yapılacağı yerdeki yetkili kolluk birimince","Müsabaka güvenlik amirinin re'sen kararıyla","İl spor güvenlik kurulunun onayı ile mülki amirce","Yalnızca federasyonun re'sen talimatıyla","Gençlik ve Spor Bakanlığının onayı ile"],"dogru":0,"aciklama":"m.6/3: 'Bu görevlendirme, ilgili kulübün başvurusu ve federasyonun talebi üzerine, müsabakanın yapılacağı yerdeki yetkili kolluk birimince yapılır.'","kaynak":"6222 m.6/3","zorluk":"zor"},
    {"id":"6222-S-025","soru":"6222 sayılı Kanun'a göre müsabaka güvenlik amirleri ile yardımcılarına, federasyon temsilcisine ödenen miktar kadar ödeme yapılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/3: 'Müsabaka güvenlik amirleri ile yardımcılarına federasyon temsilcisine ödenen miktar kadar ödeme yapılır.'","kaynak":"6222 m.6/3","zorluk":"orta"},
    {"id":"6222-S-026","soru":"6222 sayılı Kanun'a göre federasyon, ödeyeceği para miktarı ile müsabakada görevli genel kolluğa verilen kumanya bedelini öncelikle neyden mahsup eder?","siklar":["Devlet bütçesinden ayrılan spor payından","İlgili spor kulübünün alacaklarından","Gençlik ve Spor Genel Müdürlüğü bütçesinden","İl özel idaresi gelirlerinden","Kolluk görevlilerinin maaşından"],"dogru":1,"aciklama":"m.6/3: 'Federasyon ödeyeceği para miktarı ile müsabakada görevli genel kolluğa verilen kumanya bedelini ilgili spor kulübünün alacaklarından öncelikle mahsup eder.'","kaynak":"6222 m.6/3","zorluk":"zor"},
    {"id":"6222-S-027","soru":"6222 sayılı Kanun'a göre ilçe spor güvenlik kurulunda yer alacak hukukçuyu belirleme yetkisi kime aittir?","siklar":["Vali","İl spor güvenlik kurulu","Kaymakam","Cumhuriyet başsavcısı","Adalet komisyonu başkanı"],"dogru":2,"aciklama":"m.4/2: 'İlçe spor güvenlik kurulu, kaymakam başkanlığında ... kaymakam tarafından belirlenecek bir hukukçu ile ... temsilcilerinden oluşur.' İlçe kurulundaki hukukçuyu kaymakam belirler.","kaynak":"6222 m.4/2","zorluk":"orta"},
    {"id":"6222-S-028","soru":"6222 sayılı Kanun'a göre müsabaka ve seyir alanlarında genel kolluk görevlileri ile özel güvenlik görevlileri kimin emir ve denetiminde birlikte görev yapar?","siklar":["İl spor güvenlik kurulu başkanının","Mülki amirin","İlgili federasyonun","Müsabaka güvenlik amiri ve yardımcısının","Gözlemci kolluk görevlisinin"],"dogru":3,"aciklama":"m.7/3: 'Müsabaka ve seyir alanlarında genel kolluk görevlileri ile özel güvenlik görevlileri, müsabaka güvenlik amiri ve yardımcısının emir ve denetiminde birlikte görev yapar.'","kaynak":"6222 m.7/3","zorluk":"orta"},
    {"id":"6222-S-029","soru":"6222 sayılı Kanun'a göre genel kolluk görevlileri ile gözetimindeki özel güvenlik görevlileri, spor alanına girişte izleyicilerin üstünü ve eşyasını hangi yöntemlerle arayabilir?","siklar":["Teknik cihazlarla ve gerektiğinde el ile","Yalnızca el ile","Yalnızca teknik cihazlarla","Yalnızca x-ray cihazıyla","Yalnızca köpekle arama yöntemiyle"],"dogru":0,"aciklama":"m.12/2: '... spor alanına girişte izleyicilerin üstünü ve eşyasını teknik cihazlarla ve gerektiğinde el ile kontrol edebilir ve arayabilir.'","kaynak":"6222 m.12/2","zorluk":"kolay"},
    {"id":"6222-S-030","soru":"6222 sayılı Kanun'a göre m.12/1'in (b) bendinde sayılan kesici, ezici, bereleyici veya delici aletler, esasen bulundurulması yasak olan eşyalardır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/1(b): 'Esasen bulundurulması yasak olmamakla beraber kesici, ezici, bereleyici veya delici aletler ile patlayıcı, parlayıcı, yanıcı veya yakıcı maddelerin ... sokulması yasaktır.' Bu aletler genel olarak yasak eşya değildir; yasak olan sadece spor alanına sokulmalarıdır.","kaynak":"6222 m.12/1","zorluk":"zor"},
    {"id":"6222-S-031","soru":"6222 sayılı Kanun'a göre genel kolluk görevlileri ve belediye zabıtası, m.12/1'in (a) bendi kapsamındaki ruhsatlı dahi olsa ateşli silahları spor alanında seyyar olarak satan kişileri de bu alandan uzaklaştırmakla yükümlüdür.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/5: 'Genel kolluk görevlileri ve belediye zabıtası birinci fıkranın (b) ve (c) bentleri kapsamına giren alet veya maddeleri spor alanında seyyar olarak satan ... kişileri bu alandan uzaklaştırmakla yükümlüdür.' Yükümlülük yalnız (b) ve (c) bentlerini kapsar; (a) bendindeki silahlar bu fıkranın kapsamı dışındadır.","kaynak":"6222 m.12/5","zorluk":"orta"},
    {"id":"6222-S-032","soru":"6222 sayılı Kanun'a göre il spor güvenlik kurulunun oluşumunda, 'gerekli görüldüğünde davet edilecek' temsilciler aşağıdakilerden hangisidir?","siklar":["İlgili federasyon temsilcileri","Basın kuruluşlarının ve ilgili kamu kuruluşlarının temsilcileri","Amatör spor kulüpleri konfederasyonu temsilcileri","Stat güvenliğinden sorumlu yönetim kurulu üyeleri","Vali tarafından belirlenecek hukukçu"],"dogru":1,"aciklama":"m.4/1: '... ve gerekli görüldüğünde davet edilecek basın kuruluşlarının ve ilgili kamu kuruluşlarının temsilcilerinden oluşur.' Kurulun daimi bileşenlerinden farklı olarak bu temsilciler yalnızca gerek görülmesi hâlinde davet edilir.","kaynak":"6222 m.4/1","zorluk":"orta"},
    {"id":"6222-S-033","soru":"6222 sayılı Kanun'a göre profesyonel spor dallarında müsabakalara katılanlar ile basketbolun en üst ligindeki spor kulüpleri, özel güvenlik görevlilerini hangi zaman aralığında müsabakanın yapılacağı yerde bulundurmakla yükümlüdür?","siklar":["Yalnızca müsabaka süresince","Müsabaka başlangıcından bitişine kadar","Müsabaka öncesinden, müsabakanın tamamlanıp seyirci ve sporcuların tahliyesine kadar","Sadece seyircilerin stada girişinden müsabaka başlangıcına kadar","Müsabaka bitiminden 24 saat sonrasına kadar"],"dogru":2,"aciklama":"m.6/1: '... güvenliği sağlamaya yetecek sayıdaki özel güvenlik görevlilerini müsabaka öncesinden müsabakanın tamamlanıp seyirci ve sporcuların tahliyesine kadar geçecek dönem içerisinde ... bulundurmakla ... yükümlüdür.'","kaynak":"6222 m.6/1","zorluk":"kolay"},
  ],
  44: [
    {"id":"2313-S-001","soru":"2313 sayılı Uyuşturucu Maddelerin Murakabesi Hakkında Kanun'a göre zaptedilen uyuşturucu maddeler, sahipleri belli olsun veya olmasın suç delili olarak hangi makam tarafından muhafaza altına alınır?","siklar":["Cumhuriyet Savcılığı","Mahalli mülki amirlik","Sulh ceza hâkimliği","Gümrük ve Ticaret Bakanlığı","İçişleri Bakanlığı"],"dogru":0,"aciklama":"m.20: '... sahipleri belli olsun veya olmasın suç delili olarak Cumhuriyet Savcılığınca muhafaza altına alınırlar.' Zapt ile muhafaza ayrı işlemlerdir; muhafaza eden savcılıktır.","kaynak":"2313 m.20","zorluk":"kolay"},
    {"id":"2313-S-002","soru":"2313 sayılı Kanun'a göre uyuşturucu maddeyi tutanakla zaptedebilecek görevliler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Zabıta","Sulh ceza hâkimi","Gümrük ve Ticaret Bakanlığı memurları","Hükümet tabipleri","Sağlık ocağı tabipleri"],"dogru":1,"aciklama":"m.20: '...zabıtanın, Gümrük ve Ticaret Bakanlığı memurlarının, sağlık ve sosyal yardım bakanlığı müfettiş ve müdürlerinin, hükümet tabiplerinin, sağlık ocağı tabiplerinin, hudut ve sahiller sağlık teşkilatı memurlarının herhangi birisi tarafından bir tutanak düzenlemek suretiyle zaptedilir.' Sulh ceza hâkimi bu sayımda yoktur; hâkimin görevi müsadereye karar vermektir.","kaynak":"2313 m.20","zorluk":"orta"},
    {"id":"2313-S-003","soru":"2313 sayılı Kanun'a göre uyuşturucu maddelerin müsaderesine, yalnızca soruşturmanın sona ermesinden sonra sulh ceza hâkimliğince karar verilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.20: '...müsaderesine sulh ceza hâkimliğince soruşturmanın her safhasında karar verilir.' Karar tek bir ana bağlı değildir, soruşturmanın her aşamasında verilebilir.","kaynak":"2313 m.20","zorluk":"kolay"},
    {"id":"2313-S-004","soru":"2313 sayılı Kanun'a göre uyuşturucu maddelerin müsaderesine hangi makam, soruşturmanın hangi aşamasında karar verebilir?","siklar":["Cumhuriyet Savcılığı, yalnızca soruşturma sonunda","Ağır ceza mahkemesi, iddianame düzenlendikten sonra","Sulh ceza hâkimliği, soruşturmanın her safhasında","Mahalli mülki amirlik, kesin rapor alındıktan hemen sonra","Sulh ceza hâkimliği, yalnızca kovuşturma aşamasında"],"dogru":2,"aciklama":"m.20: '...müsaderesine sulh ceza hâkimliğince soruşturmanın her safhasında karar verilir.' Karar veren makam sulh ceza hâkimliğidir, aşama sınırlaması yoktur.","kaynak":"2313 m.20","zorluk":"orta"},
    {"id":"2313-S-005","soru":"2313 sayılı Kanun'a göre zaptedilen uyuşturucu maddenin cins, vasıf ve miktarının kesin olarak saptanması amacıyla ....(1).... alınarak ilgili laboratuvarlara gönderilir; kesin raporlar alındıktan sonra müsaderesine ....(2).... karar verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["tüm madde - Cumhuriyet Savcılığınca","yarısı - ağır ceza mahkemesince","tüm madde - sulh ceza hâkimliğince","analizlere yetecek kadar örnek madde - sulh ceza hâkimliğince","analizlere yetecek kadar örnek madde - mahalli mülki amirlikçe"],"dogru":3,"aciklama":"m.20: 'Zaptedilen uyuşturucu maddenin cins, vasıf ve miktarının kesin olarak saptanması amacıyla analizlere yetecek kadar örnek madde alınarak ... ilgili laboratuvarlara gönderilir. ... müsaderesine ... sulh ceza hâkimliğince ... karar verilir.' Tüm madde değil, analiz için yeterli örnek alınır; kararı sulh ceza hâkimliği verir.","kaynak":"2313 m.20","zorluk":"zor"},
    {"id":"2313-S-006","soru":"2313 sayılı Kanun'a göre müsaderesine karar verilen uyuşturucu maddeler, gereği yapılmak üzere nasıl ve kime teslim edilir?","siklar":["Açık halde Cumhuriyet Savcılığına","Mühürsüz olarak İçişleri Bakanlığına","Açık halde sulh ceza hâkimliğine","Mühürlü olarak Gümrük ve Ticaret Bakanlığına","Mühürlü olarak mahalli mülki amirliğe"],"dogru":4,"aciklama":"m.20: 'Müsaderesine karar verilen uyuşturucu maddeler gereği yapılmak üzere mühürlü olarak mahalli mülki amirliğe teslim edilir.' Teslim şekli mühürlü, teslim makamı mahalli mülki amirliktir.","kaynak":"2313 m.20","zorluk":"kolay"},
    {"id":"2313-S-007","soru":"2313 sayılı Kanun'a göre örnek olarak alınan uyuşturucu maddeler ne zaman mahalli mülki amirliğe teslim edilir?","siklar":["Ancak hükmün kesinleşmesinden sonra","Zaptedildiği anda derhal","Kesin laboratuvar raporu alınır alınmaz","Müsadere kararı verilir verilmez","Dava açıldığı anda"],"dogru":0,"aciklama":"m.20: 'Örnek olarak alınan uyuşturucu maddeler hükümle birlikte müsadere edilir ve ancak hükmün kesinleşmesinden sonra mahalli mülki amirliğe teslim edilir.' Örnek madde, esas maddeden farklı olarak hükmün kesinleşmesini bekler.","kaynak":"2313 m.20","zorluk":"zor"},
    {"id":"2313-S-008","soru":"2313 sayılı Kanun'a göre uyuşturucu madde arama köpeği eğitiminde kullanılmak üzere ihtiyaç duyulan uyuşturucu madde, Millî Savunma Bakanının talebi üzerine hangi kuruma teslim edilir?","siklar":["İçişleri Bakanlığının ilgili bağlı kuruluşlarına","Türk Silahlı Kuvvetlerine","Gümrükler Muhafaza Genel Müdürlüğüne","Tarım ve Köyişleri Bakanlığının ilgili bağlı kuruluşlarına","Emniyet Genel Müdürlüğüne"],"dogru":1,"aciklama":"m.20: '...Millî Savunma Bakanının talebi üzerine Türk Silahlı Kuvvetlerine...' teslim edilir. Her bakanın talebi, kendi bünyesindeki farklı kuruma yöneliktir.","kaynak":"2313 m.20","zorluk":"orta"},
    {"id":"2313-S-009","soru":"2313 sayılı Kanun'a göre arama köpeği eğitimi veya tıbbî amaçlı araştırma için uyuşturucu madde teslim edilebilecek kurum/bakanlıklar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["İçişleri Bakanlığının ilgili bağlı kuruluşları (İçişleri Bakanının talebiyle)","Türk Silahlı Kuvvetleri (Millî Savunma Bakanının talebiyle)","Sağlık Bakanlığının ilgili bağlı kuruluşları (Sağlık Bakanının talebiyle)","Gümrükler Muhafaza Genel Müdürlüğü (Gümrük ve Ticaret Bakanının talebiyle)","Tarım ve Köyişleri Bakanlığının ilgili bağlı kuruluşları (Tarım ve Köyişleri Bakanının talebiyle)"],"dogru":2,"aciklama":"m.20'de sayılan dört kurum İçişleri Bakanlığının ilgili bağlı kuruluşları, Türk Silahlı Kuvvetleri, Gümrükler Muhafaza Genel Müdürlüğü ve tıbbî araştırma amaçlı olarak Tarım ve Köyişleri Bakanlığının ilgili bağlı kuruluşlarıdır. Sağlık Bakanlığı bu sayımda yer almaz.","kaynak":"2313 m.20","zorluk":"zor"},
    {"id":"2313-S-010","soru":"2313 sayılı Kanun'a göre müsaderesine karar verilen uyuşturucu maddeler, kimin başkanlığındaki heyet huzurunda imha edilir?","siklar":["İl savcısının başkanlığında","Sulh ceza hâkiminin başkanlığında","Mahalli mülki amirin bizzat başkanlığında","Valinin görevlendireceği bir yetkilinin başkanlığında","Emniyet müdürünün başkanlığında"],"dogru":3,"aciklama":"m.21: 'Müsaderesine karar verilen uyuşturucu maddeler, valinin görevlendireceği bir yetkilinin başkanlığındaki ve il savcısının veya yardımcısının nezaretçi olarak katıldığı heyet huzurunda imha edilir.' Başkan vali görevlisi, savcı yalnız nezaretçidir.","kaynak":"2313 m.21","zorluk":"kolay"},
    {"id":"2313-S-011","soru":"2313 sayılı Kanun'a göre müsadere edilen uyuşturucu maddelerin imhasını bizzat il savcısı veya yardımcısı gerçekleştirir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.21: '...il savcısının veya yardımcısının nezaretçi olarak katıldığı heyet huzurunda imha edilir.' İmhayı fiilen gerçekleştiren, valinin görevlendirdiği yetkilinin başkanlığındaki heyettir; savcı yalnızca nezaretçidir.","kaynak":"2313 m.21","zorluk":"orta"},
    {"id":"2313-S-012","soru":"2313 sayılı Kanun'a göre izinsiz yetiştirilen kenevir bitkisinin imha edilmesi hangi makamın emriyle gerçekleşir?","siklar":["Cumhuriyet Savcısının emriyle","Sulh ceza hâkiminin emriyle","Valinin görevlendirdiği yetkilinin emriyle","Tarım ve Orman Bakanlığının emriyle","Mahallin en büyük mülki amirinin emriyle"],"dogru":4,"aciklama":"m.23: 'İzinsiz yetiştirilen kenevir bitkisi, ... ziraat mühendislerinin ... vereceği rapor üzerine mahallin en büyük mülki amirinin emriyle zabıta tarafından imha edilir veya ettirilir.' Emri veren makam mahallin en büyük mülki amiridir, imhayı fiilen yapan zabıtadır.","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-013","soru":"2313 sayılı Kanun'a göre izinsiz yetiştirilen kenevir bitkisi, Tarım Orman ve Köyişleri Bakanlığı teşkilatında görevli ....(1).... vereceği rapor üzerine, ....(2).... emriyle zabıta tarafından imha edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["ziraat mühendislerinin - mahallin en büyük mülki amirinin","ziraat mühendislerinin - sulh ceza hâkiminin","veteriner hekimlerin - valinin","ziraat teknisyenlerinin - Cumhuriyet Savcısının","ziraat mühendislerinin - İçişleri Bakanının"],"dogru":0,"aciklama":"m.23: '...Tarım Orman ve Köyişleri Bakanlığı teşkilatında görevli ziraat mühendislerinin, bunların bulunmadığı yerlerde ziraat teknisyenlerinin vereceği rapor üzerine mahallin en büyük mülki amirinin emriyle zabıta tarafından imha edilir veya ettirilir.' Asıl kural ziraat mühendisi raporu + en büyük mülki amir emridir.","kaynak":"2313 m.23","zorluk":"zor"},
    {"id":"2313-S-014","soru":"2313 sayılı Kanun'a göre izinsiz kenevirin imhasında kullanılacak araç ve gereçler hangi bütçeye konulacak ödenekten sağlanır?","siklar":["İçişleri Bakanlığı bütçesi","Jandarma Genel Komutanlığı bütçesi","Tarım ve Orman Bakanlığı bütçesi","Mahalli mülki amirlik bütçesi","Emniyet Genel Müdürlüğü bütçesi"],"dogru":1,"aciklama":"m.23: 'İmhada kullanılacak araç ve gereçler, Jandarma Genel Komutanlığı bütçesine konulacak ödenekten sağlanır.' Ödenek kaynağı özel olarak Jandarma Genel Komutanlığı bütçesidir.","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-015","soru":"2313 sayılı Kanun'a göre izinsiz kenevir imhası dolayısıyla ortaya çıkan masraf, izinsiz ekim yapanlardan hangi kanuna göre tahsil edilir?","siklar":["5237 sayılı Türk Ceza Kanunu","5271 sayılı Ceza Muhakemesi Kanunu","6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun","2577 sayılı İdari Yargılama Usulü Kanunu","5326 sayılı Kabahatler Kanunu"],"dogru":2,"aciklama":"m.23: 'İmha dolayısıyla ortaya çıkan masraf, sonradan izinsiz ekim yapanlardan 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanuna göre tahsil edilir.' Önce devlet öder, sonra masraf kamu alacağı gibi tahsil edilir.","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-016","soru":"2313 sayılı Kanun'a göre lif, tohum ve sap üretimi amaçlı kenevir yetiştiriciliği hangi bakanlığın iznine tabidir?","siklar":["Sağlık Bakanlığı","İçişleri Bakanlığı","Adalet Bakanlığı","Tarım ve Orman Bakanlığı","Ticaret Bakanlığı"],"dogru":3,"aciklama":"m.23: '...amaçlı kenevir yetiştiriciliği, Tarım ve Orman Bakanlığının iznine tabidir. Lif, tohum ve sap üretimi amacıyla izinli kenevir yetiştiriciliği Tarım ve Orman Bakanlığınca çıkarılacak yönetmelikle düzenlenir.' İzin merci Tarım ve Orman Bakanlığıdır.","kaynak":"2313 m.23","zorluk":"kolay"},
    {"id":"2313-S-017","soru":"2313 sayılı Kanun'a göre izin belgesi almadan kenevir ekimi yapan kişi ....(1)...., esrar elde etmek amacıyla kenevir ekimi yapan kişi ....(2)...., münhasıran kendi kullanımı için esrar elde etmek amacıyla kenevir ekimi yapan kişi ise ....(3).... ile cezalandırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir yıldan üç yıla kadar hapis cezası - dört yıldan on iki yıla kadar hapis cezası - elli günden az olmamak üzere adlî para cezası","altı aydan bir yıla kadar hapis cezası - iki yıldan sekiz yıla kadar hapis cezası - üç aydan bir yıla kadar hapis cezası","yüz günden az olmamak üzere adlî para cezası - dört yıldan on iki yıla kadar hapis cezası - altı aydan iki yıla kadar hapis cezası","elli günden az olmamak üzere adlî para cezası - bir yıldan üç yıla kadar hapis cezası - dört yıldan on iki yıla kadar hapis cezası","elli günden az olmamak üzere adlî para cezası - dört yıldan on iki yıla kadar hapis ve beşyüz günden onbin güne kadar adlî para cezası - bir yıldan üç yıla kadar hapis cezası"],"dogru":4,"aciklama":"m.23: 'İzin belgesi almadan ... kenevir ekimi yapan kişi, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Esrar elde etmek amacıyla kenevir ekimi yapan kişi dört yıldan on iki yıla kadar hapis ve beşyüz günden onbin güne kadar adlî para cezası ile cezalandırılır. Münhasıran kendi kullanımı için ... esrarı elde etmek amacıyla kenevir ekimi yapan kişi bir yıldan üç yıla kadar hapis cezası ile cezalandırılır.' Ceza amaca göre kademeli ağırlaşır.","kaynak":"2313 m.23","zorluk":"zor"},
    {"id":"2313-S-018","soru":"2313 sayılı Kanun'a göre esrar elde etmek amacıyla kenevir ekmek suçu bakımından, Ceza Muhakemesi Kanunu'nun iletişimin tespiti, dinlenmesi ve kayda alınması ile teknik araçlarla izlemeye ilişkin hükümleri uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.23: 'Esrar elde etmek amacıyla kenevir ekmek suçu bakımından ... 5271 sayılı Ceza Muhakemesi Kanununun 135 inci maddesinde yer alan iletişimin tespiti, dinlenmesi ve kayda alınması ile 140 ıncı maddesinde yer alan teknik araçlarla izleme tedbirlerine ilişkin hükümler uygulanabilir.'","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-019","soru":"2313 sayılı Kanun'a göre aşağıdaki makam-görev eşleştirmelerinden hangisi doğru değildir?","siklar":["İmha: Cumhuriyet Savcısı bizzat","Zapteden: zabıta/gümrük/sağlık görevlilerinden herhangi biri (tutanakla)","Muhafaza eden: Cumhuriyet Savcılığı","Müsadere kararı: sulh ceza hâkimliği","Teslim: mahalli mülki amirlik (mühürlü)"],"dogru":0,"aciklama":"m.21: İmhayı 'valinin görevlendireceği bir yetkilinin başkanlığındaki' heyet yapar; 'il savcısının veya yardımcısının' rolü yalnızca NEZARETÇİdir, imhayı bizzat o yapmaz. Diğer dört eşleştirme (B: m.20 zapt, C: m.20 muhafaza, D: m.20 müsadere, E: m.20 teslim) madde metinleriyle birebir doğrudur.","kaynak":"2313 m.20, m.21, m.23","zorluk":"zor"},
    {"id":"2313-S-020","soru":"2313 sayılı Kanun'a göre uyuşturucu maddenin murakabe zincirinde işlemlerin doğru sırası aşağıdakilerden hangisidir?","siklar":["Muhafaza (savcılık) → Zapt (görevli) → İmha (vali heyeti) → Müsadere (hâkimlik) → Teslim (mülki amirlik)","Zapt (görevli) → Muhafaza (Cumhuriyet Savcılığı) → Müsadere kararı (sulh ceza hâkimliği) → Teslim (mahalli mülki amirlik) → İmha (vali görevlisi başkanlığındaki heyet)","Zapt (görevli) → Müsadere (hâkimlik) → Muhafaza (savcılık) → İmha (heyet) → Teslim (mülki amirlik)","Teslim (mülki amirlik) → Zapt (görevli) → Muhafaza (savcılık) → Müsadere (hâkimlik) → İmha (heyet)","Zapt (görevli) → Muhafaza (savcılık) → Teslim (mülki amirlik) → Müsadere (hâkimlik) → İmha (heyet)"],"dogru":1,"aciklama":"m.20-m.21'in bütünü: görevli TUTANAKLA zapteder (m.20/1) → savcılık SUÇ DELİLİ olarak muhafaza eder (m.20/1) → kesin rapordan sonra sulh ceza hâkimliği MÜSADERE kararı verir (m.20/3) → mühürlü olarak mahalli mülki amirliğe TESLİM edilir (m.20/4) → vali görevlisi başkanlığındaki heyet (savcı nezaretçi) İMHA eder (m.21/1).","kaynak":"2313 m.20, m.21","zorluk":"orta"},
    {"id":"2313-S-021","soru":"2313 sayılı Uyuşturucu Maddelerin Murakabesi Hakkında Kanun'a göre izinsiz imal edilen veya ihraç edilmek istenirken uyuşturucu madde ele geçirildiğinde, bu maddeyi hangi makam zapteder?","siklar":["Zabıta","Cumhuriyet Savcılığı","Mahalli mülki amirlik","Sağlık ve sosyal yardım bakanlığı müfettişleri","Gümrük ve Ticaret Bakanlığı"],"dogru":4,"aciklama":"m.20/1: '...gerekse izinsiz imal edilen veya ihraç edilmek istenirken Gümrük ve Ticaret Bakanlığı tarafından zaptolunanlar sahipleri belli olsun veya olmasın suç delili olarak Cumhuriyet Savcılığınca muhafaza altına alınırlar.' Bu ikinci zapt kategorisinde zaptı bizzat Gümrük ve Ticaret Bakanlığı yapar; ilk cümledeki 'zabıta/gümrük/sağlık görevlilerinden herhangi biri' listesi izinsiz sokulma/satılma/yetkisiz bulundurma haline özgü ayrı bir olaydır.","kaynak":"2313 m.20","zorluk":"zor"},
    {"id":"2313-S-022","soru":"2313 sayılı Kanun'a göre madde 20 hükümleri, 3491 sayılı Toprak Mahsulleri Ofisi Kanununun 27 nci maddesinin (F) fıkrası hükümlerini yürürlükten kaldırmıştır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.20 son fıkra: '3491 sayılı Toprak Mahsulleri Ofisi Kanununun 27 nci maddesinin (F) fıkrası hükümleri saklıdır.' Saklı tutma, o hükmün yürürlükte kalmaya ve etkilenmeden uygulanmaya devam ettiği anlamına gelir; yürürlükten kaldırma değildir.","kaynak":"2313 m.20","zorluk":"orta"},
    {"id":"2313-S-023","soru":"2313 sayılı Kanun'a göre uyuşturucu madde arama köpeği eğitiminde kullanılmak üzere teslim edilen maddenin teslimi, kullanımı, muhafazası ve imhası usulüne ilişkin yönetmelik, Adalet ve Sağlık Bakanlıkları ile Gümrük ve Ticaret Bakanlığının görüşü alınarak ....(1).... bakanlıklarınca ....(2).... içerisinde yürürlüğe konulur. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["İçişleri ve Millî Savunma - bir yıl","Adalet, Sağlık ve Gümrük ve Ticaret - altı ay","İçişleri, Millî Savunma ve Tarım ve Köyişleri - altı ay","İçişleri, Millî Savunma ve Tarım ve Köyişleri - üç ay","Sağlık ve Tarım ve Köyişleri - altı ay"],"dogru":2,"aciklama":"m.21/2: '...teslimi, kullanımı, muhafazası ve imhası usulü ile ilgili hususlar Adalet ve Sağlık Bakanlıkları ile Gümrük ve Ticaret Bakanlığının görüşü alınarak İçişleri, Millî Savunma ve Tarım ve Köyişleri bakanlıklarınca altı ay içerisinde yürürlüğe konulacak bir yönetmelikte belirlenir.'","kaynak":"2313 m.21","zorluk":"orta"},
    {"id":"2313-S-024","soru":"2313 sayılı Kanun'un 21 inci maddesine göre arama köpeği eğitimi/tıbbi araştırma amaçlı teslim edilen maddenin usulünü belirleyen yönetmelik sürecinde (görüş alınan veya yönetmeliği çıkaran taraf olarak) aşağıdaki bakanlıklardan hangisi hiç YER ALMAMIŞTIR?","siklar":["Hazine ve Maliye Bakanlığı","Adalet Bakanlığı (görüşü alınır)","İçişleri Bakanlığı (yönetmeliği çıkarır)","Millî Savunma Bakanlığı (yönetmeliği çıkarır)","Sağlık Bakanlığı (görüşü alınır)"],"dogru":0,"aciklama":"m.21/2'de geçen bakanlıklar: görüşü alınan Adalet, Sağlık, Gümrük ve Ticaret Bakanlıkları; yönetmeliği çıkaran İçişleri, Millî Savunma ve Tarım ve Köyişleri Bakanlıkları. Hazine ve Maliye Bakanlığı bu süreçte hiç anılmaz.","kaynak":"2313 m.21","zorluk":"zor"},
    {"id":"2313-S-025","soru":"2313 sayılı Kanun'a göre tıbbi ürünler, sağlık ürünleri ile kişisel bakım ürünleri ve destek ürünleri elde etmeye yönelik çiçek ve yaprak üretimi amaçlı kenevir yetiştiriciliği fiilen kim tarafından yapılır veya yaptırılır?","siklar":["Tarım ve Orman Bakanlığınca","İçişleri Bakanlığınca","Sağlık Bakanlığınca","Toprak Mahsulleri Ofisi Genel Müdürlüğünce","Mahalli mülki amirlikçe"],"dogru":3,"aciklama":"m.23/1: '...Tıbbi ürünler, sağlık ürünleri ile kişisel bakım ürünleri ve destek ürünleri üretimi amaçlı kenevir yetiştiriciliği (…) Toprak Mahsulleri Ofisi Genel Müdürlüğü tarafından yapılır veya yaptırılır.' İzin merci Tarım ve Orman Bakanlığı olsa da, bu özel ürün grubunun fiilen yetiştirilmesi TMO Genel Müdürlüğünce yapılır/yaptırılır.","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-026","soru":"2313 sayılı Kanun'a göre gerektiğinde ülke arz ve talep durumuna göre ....(1).... belirlenen kota doğrultusunda, tıbbi ürünler, sağlık ürünleri ile kişisel bakım ürünleri ve destek ürünleri üretimi amaçlı kenevir yetiştiriciliği ....(2).... kontrolünde gerçek veya tüzel kişilere yaptırılabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Tarım ve Orman Bakanlığınca - Toprak Mahsulleri Ofisi Genel Müdürlüğü","Cumhurbaşkanınca - Toprak Mahsulleri Ofisi Genel Müdürlüğü","Cumhurbaşkanınca - Tarım ve Orman Bakanlığı","Bakanlar Kurulunca - Toprak Mahsulleri Ofisi Genel Müdürlüğü","Cumhurbaşkanınca - İçişleri Bakanlığı"],"dogru":1,"aciklama":"m.23/1: 'Gerektiğinde ülke arz ve talep durumuna göre Cumhurbaşkanınca belirlenen kota doğrultusunda, Toprak Mahsulleri Ofisi Genel Müdürlüğü kontrolünde gerçek veya tüzel kişilere yaptırılabilir.'","kaynak":"2313 m.23","zorluk":"zor"},
    {"id":"2313-S-027","soru":"2313 sayılı Kanun'a göre tıbbi ürünler, sağlık ürünleri ile kişisel bakım ürünleri ve destek ürünleri üretimi amaçlı kenevir yetiştiriciliğinde münhasıran esrar elde edilmesini engelleyecek tedbirler ile yetiştirme ve hasat usul ve esasları hangi bakanlıkça, hangi bakanlıkların görüşü alınarak çıkarılacak yönetmelikle belirlenir?","siklar":["Sağlık Bakanlığınca; İçişleri ve Tarım ve Orman Bakanlığının görüşü alınarak","İçişleri Bakanlığınca; Sağlık ve Tarım ve Orman Bakanlığının görüşü alınarak","Tarım ve Orman Bakanlığınca; yalnızca Sağlık Bakanlığının görüşü alınarak","Cumhurbaşkanınca; ilgili bakanlıkların görüşü alınarak","Tarım ve Orman Bakanlığınca; İçişleri Bakanlığı ve Sağlık Bakanlığının görüşleri alınarak"],"dogru":4,"aciklama":"m.23/1: '...münhasıran esrar elde edilmesini engelleyecek her türlü tedbirin alınması, kenevirin yetiştirilmesi ve hasadına ilişkin usul ve esaslar, İçişleri Bakanlığı ve Sağlık Bakanlığının görüşleri alınmak suretiyle Tarım ve Orman Bakanlığınca çıkarılacak yönetmelikle belirlenir.'","kaynak":"2313 m.23","zorluk":"orta"},
    {"id":"2313-S-028","soru":"2313 sayılı Kanun'a göre kenevirden elde edilen tıbbi ürünler, sağlık ürünleri ile kişisel bakım ürünleri ve destek ürünlerine yönelik ruhsatlandırma ya da takip sistemlerine kayıt işlemleri Sağlık Bakanlığınca gerçekleştirilir ve bu ürünler sadece eczanelerden satılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.23/1 (Ek cümleler: 21/7/2025-7557/9): '...ruhsatlandırma ya da takip sistemlerine kayıt işlemleri Sağlık Bakanlığınca gerçekleştirilir. Bu ürünler sadece eczanelerden satılabilir.'","kaynak":"2313 m.23","zorluk":"kolay"},
    {"id":"2313-S-029","soru":"2313 sayılı Kanun'a göre kenevirden elde edilen ürünlerin izni ve satışı ile kenevirin işlenmesi, ihzarı ve ihracına ilişkin usul ve esasları düzenleyen yönetmeliği hangi bakanlık, hangi bakanlıkların görüşünü alarak çıkarır?","siklar":["Sağlık Bakanlığı; İçişleri Bakanlığı ve Tarım ve Orman Bakanlığının görüşünü alarak","Tarım ve Orman Bakanlığı; İçişleri ve Sağlık Bakanlığının görüşünü alarak","İçişleri Bakanlığı; Sağlık ve Tarım ve Orman Bakanlığının görüşünü alarak","Sağlık Bakanlığı; yalnızca Tarım ve Orman Bakanlığının görüşünü alarak","Ticaret Bakanlığı; İçişleri Bakanlığının görüşünü alarak"],"dogru":0,"aciklama":"m.23/1: 'Bu ürünlerin izin ve satışı ile kenevirin işlenmesi, ihzarı ve ihracına ilişkin usul ve esaslar, İçişleri Bakanlığı ve Tarım ve Orman Bakanlığının görüşü alınarak Sağlık Bakanlığınca çıkarılacak yönetmelikle belirlenir.'","kaynak":"2313 m.23","zorluk":"zor"},
    {"id":"2313-S-030","soru":"2313 sayılı Kanun'a göre madde 23 kapsamında 'ekim yapma' ibaresinden yalnızca tohumun toprağa ekilmesi anı anlaşılır; hasat süreci bu tanımın dışındadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.23/4: 'Bu madde kapsamında ekim yapma ibaresinden, tohumun toprağa ekilmesinden ürünün hasadına kadarki süreç anlaşılır.' Tanım, ekim anından hasada kadar uzanan tüm süreci kapsar.","kaynak":"2313 m.23","zorluk":"kolay"},
    {"id":"2313-S-031","soru":"2313 sayılı Kanun'un 23 üncü maddesindeki kenevirle ilgili yönetmelik/uygulama yetkileri bakımından aşağıdaki eşleştirmelerden hangisi yanlıştır?","siklar":["Yetiştirme/hasat + esrar engelleme tedbirleri yönetmeliği → Tarım ve Orman Bakanlığınca (İçişleri ve Sağlık görüşüyle)","Lif, tohum, sap üretimi amaçlı izinli yetiştiricilik yönetmeliği → Tarım ve Orman Bakanlığınca","İzin ve satış yönetmeliği → Tarım ve Orman Bakanlığınca (Sağlık Bakanlığı görüşüyle)","İzin ve satış + işleme/ihzar/ihraç yönetmeliği → Sağlık Bakanlığınca (İçişleri ve Tarım ve Orman görüşüyle)","Tıbbi/sağlık/kişisel bakım/destek ürünleri üretimi → Toprak Mahsulleri Ofisi Genel Müdürlüğünce yapılır/yaptırılır"],"dogru":2,"aciklama":"m.23/1'e göre izin ve satış ile işleme/ihzar/ihraç yönetmeliği, İçişleri Bakanlığı ve Tarım ve Orman Bakanlığının görüşü alınarak Sağlık Bakanlığınca çıkarılır; C şıkkındaki gibi Tarım ve Orman Bakanlığınca değildir. Diğer dört eşleştirme (A, B, D, E) madde metniyle birebir doğrudur.","kaynak":"2313 m.23","zorluk":"zor"},
  ],
  45: [
    {"id":"6415-S-001","soru":"6415 sayılı Terörizmin Finansmanının Önlenmesi Hakkında Kanun'a göre 'Başkanlık' ifadesi hangi kurumu ifade eder?","siklar":["Malvarlığının Dondurulmasını Değerlendirme Komisyonu","Hazine ve Maliye Bakanlığı","Mali Suçları Araştırma Kurulu Başkanlığı","İçişleri Bakanlığı","Adalet Bakanlığı"],"dogru":2,"aciklama":"m.2/1-a: \"Başkanlık: Mali Suçları Araştırma Kurulu Başkanlığını ... ifade eder.\" Kanun boyunca 'Başkanlık' ibaresi MASAK'ı karşılar.","kaynak":"6415 m.2","zorluk":"kolay"},
    {"id":"6415-S-002","soru":"6415 sayılı Kanun'a göre 'malvarlığının dondurulması' aşağıdakilerden hangisini ifade eder?","siklar":["Malvarlığına el konularak mülkiyetin devletçe kayyıma devredilmesini","Malvarlığının müsadere edilerek Hazineye geçirilmesini","Malvarlığının bankada bloke edilip beş yıl sonra iade edilmesini","Malvarlığı üzerindeki tasarruf yetkisinin kaldırılması veya kısıtlanmasını","Malvarlığının mülkiyetinin sona erdirilmesini"],"dogru":3,"aciklama":"m.2/1-d: \"Malvarlığının dondurulması: ... malvarlığı üzerindeki tasarruf yetkisinin kaldırılması veya kısıtlanmasını, ifade eder.\" Mal yerinde kalır, yalnız tasarruf yetkisi kilitlenir; mülkiyet devri veya müsadere değildir.","kaynak":"6415 m.2","zorluk":"orta"},
    {"id":"6415-S-003","soru":"6415 sayılı Kanun'un 3 üncü maddesine göre aşağıdaki fiillerden hangisinin gerçekleştirilmesi amacıyla fon sağlanması veya toplanması yasak fiiller arasında SAYILMAMIŞTIR?","siklar":["Bir halkı korkutmak veya sindirmek amacıyla kasten öldürme veya ağır yaralama fiilleri","3713 sayılı Terörle Mücadele Kanunu kapsamında terör suçu olarak kabul edilen fiiller","Rehine alınmasına karşı uluslararası sözleşmede yasaklanan fiiller","Terörist bombalamalarının önlenmesine ilişkin uluslararası sözleşmede yasaklanan fiiller","Kaçakçılıkla Mücadele Kanunu kapsamında düzenlenen kaçakçılık suçları"],"dogru":4,"aciklama":"m.3/1 (a), (b), (c) bentlerinde halkı korkutma/sindirme, 3713 kapsamında terör suçları ve Türkiye'nin taraf olduğu dokuz uluslararası sözleşmede (rehine, terörist bombalama vb.) yasaklanan fiiller sayılmıştır. Kaçakçılıkla Mücadele Kanunu kapsamındaki suçlar m.3'te sayılmamıştır.","kaynak":"6415 m.3","zorluk":"orta"},
    {"id":"6415-S-004","soru":"6415 sayılı Kanun'a göre 3 üncü maddede sayılan fiillerin bizzat işlenmesi (örneğin kasten öldürme fiilinin işlenmesi), bu Kanun kapsamında yasaklanmıştır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/1: \"Aşağıda sayılan fiillerin gerçekleştirilmesi amacıyla fon sağlanması veya toplanması yasaktır.\" Yasaklanan, sayılan fiillerin bizzat işlenmesi değil, bu fiiller İÇİN fon sağlamak veya toplamaktır.","kaynak":"6415 m.3","zorluk":"kolay"},
    {"id":"6415-S-005","soru":"6415 sayılı Kanun'a göre, 3 üncü madde kapsamındaki bir fiilin gerçekleştirilmesinde kullanılması amacıyla veya kullanılacağını bilerek ve isteyerek bir teröriste veya terör örgütüne fon sağlayan veya toplayan kişi, fiil daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde ne kadar hapis cezası ile cezalandırılır?","siklar":["Beş yıldan on yıla kadar","Bir yıldan üç yıla kadar","Altı aydan iki yıla kadar","İki yıldan beş yıla kadar","On yıldan on beş yıla kadar"],"dogru":0,"aciklama":"m.4/1: \"...bir teröriste veya terör örgütlerine fon sağlayan veya toplayan kişi ... beş yıldan on yıla kadar hapis cezası ile cezalandırılır.\"","kaynak":"6415 m.4/1","zorluk":"kolay"},
    {"id":"6415-S-006","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçunun örgütü kuran, yöneten veya örgüt üyesi tarafından işlenmesi hâlinde ceza ....(1).... 'e kadar artırılır; suçun kamu görevinin sağladığı nüfuz kötüye kullanılarak işlenmesi hâlinde ise ceza ....(2).... oranında artırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yarı - üçte bir","üçte bir - yarı","üçte iki - yarı","yarı - üçte iki","dörtte bir - yarı"],"dogru":1,"aciklama":"m.4/2: \"...bu kişiler hakkında örgüt kurmak, yönetmek veya örgüte üye olmak suçları uyarınca verilecek ceza üçte birine kadar artırılır.\" m.4/4: \"...kamu görevinin sağladığı nüfuz kötüye kullanılmak suretiyle işlenmesi hâlinde, verilecek ceza yarı oranında artırılır.\"","kaynak":"6415 m.4/2,4","zorluk":"zor"},
    {"id":"6415-S-007","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçundan ceza verilebilmesi için sağlanan veya toplanan fonun fiilen bir suçun işlenmesinde kullanılmış olması şartı aranır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/3: \"Birinci fıkra hükmüne göre ceza verilebilmesi için fonun bir suçun işlenmesinde kullanılmış olması şartı aranmaz.\" Fon fiilen kullanılmasa bile suç tamamlanmıştır.","kaynak":"6415 m.4/3","zorluk":"orta"},
    {"id":"6415-S-008","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçunun yabancı bir devlet veya uluslararası bir kuruluş aleyhine işlenmesi hâlinde, soruşturma ve kovuşturma yapılması hangi makamın talebine bağlıdır?","siklar":["İçişleri Bakanı","Dışişleri Bakanı","Adalet Bakanı","Hazine ve Maliye Bakanı","Cumhurbaşkanı"],"dogru":2,"aciklama":"m.4/6: \"Suçun, yabancı bir devlet veya uluslararası bir kuruluş aleyhine işlenmesi hâlinde, soruşturma ve kovuşturma yapılması Adalet Bakanının talebine bağlıdır.\"","kaynak":"6415 m.4/6","zorluk":"orta"},
    {"id":"6415-S-009","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçu bakımından Ceza Muhakemesi Kanunu hükümlerine göre uygulanabilecek tedbirler arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Şirket yönetimi için kayyım tayini","İletişimin tespiti, dinlenmesi ve kayda alınması","Gizli soruşturmacı görevlendirilmesi","Elkoyma kararına karşı istinaf yolunun kapatılması","Teknik araçlarla izleme"],"dogru":3,"aciklama":"m.4/8: CMK'nın 133 (kayyım tayini), 135 (iletişimin tespiti), 139 (gizli soruşturmacı), 140 (teknik araçlarla izleme) maddelerindeki tedbirler ile 4208 sayılı Kanuna göre kontrollü teslimat uygulanabilir. 'İstinaf yolunun kapatılması' gibi bir düzenleme madde metninde yoktur.","kaynak":"6415 m.4/8","zorluk":"zor"},
    {"id":"6415-S-010","soru":"6415 sayılı Kanun'a göre Birleşmiş Milletler Güvenlik Konseyinin 1267 (1999), 1988 (2011), 1989 (2011) ve 2253 (2015) sayılı kararlarıyla listelenen kişi, kuruluş veya organizasyonların malvarlığının dondurulması kararlarının uygulanması hangi makamın kararıyla yürürlüğe girer?","siklar":["Değerlendirme Komisyonu kararıyla","Hazine ve Maliye Bakanı kararıyla","Ankara ağır ceza mahkemesi kararıyla","Dışişleri Bakanlığı tebliğiyle","Cumhurbaşkanı kararıyla"],"dogru":4,"aciklama":"m.5/1: \"...malvarlığının dondurulması kararları ... uygulanmasına yönelik Cumhurbaşkanı kararı, Resmî Gazete'de yayımlanır ve gecikmeksizin uygulanır.\"","kaynak":"6415 m.5/1","zorluk":"kolay"},
    {"id":"6415-S-011","soru":"6415 sayılı Kanun'a göre yabancı bir devlet hükûmetinin malvarlığının dondurulması talebinin değerlendirilmesinde ....(1).... ilkesi gözetilir; bu madde uyarınca verilen dondurma kararının Resmî Gazete'de yayımlanmasından itibaren ....(2).... içinde talep eden devlet soruşturma başlatmazsa karar kaldırılabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["karşılıklılık - bir yıl","iyiniyet - altı ay","eşitlik - iki yıl","hakkaniyet - altı ay","karşılıklılık - iki yıl"],"dogru":0,"aciklama":"m.6/1: \"...Bu değerlendirmede karşılıklılık ilkesi gözetilir.\" m.6/5: \"...Resmî Gazete'de yayımlandığı tarihten itibaren bir yıl içinde, talep eden devlet tarafından soruşturma başlatılmadığı takdirde ilgili karar kaldırılabilir.\"","kaynak":"6415 m.6","zorluk":"orta"},
    {"id":"6415-S-012","soru":"6415 sayılı Kanun'a göre mahkemelerce terör örgütü olduğuna kesin karar verildikten sonra, kişi, kuruluş veya organizasyonların Türkiye'de bulunan malvarlığının dondurulmasına Değerlendirme Komisyonunun önerisi üzerine hangi makam(lar) karar verir?","siklar":["Yalnız İçişleri Bakanı","Hazine ve Maliye Bakanı ile İçişleri Bakanı birlikte","Yalnız Hazine ve Maliye Bakanı","Cumhurbaşkanı tek başına","Ankara ağır ceza mahkemesi"],"dogru":1,"aciklama":"m.7/3: \"...Değerlendirme Komisyonunun önerisi üzerine Hazine ve Maliye Bakanı ile İçişleri Bakanı tarafından birlikte karar verilebilir.\"","kaynak":"6415 m.7/3","zorluk":"kolay"},
    {"id":"6415-S-013","soru":"6415 sayılı Kanun'a göre Hazine ve Maliye Bakanı ile İçişleri Bakanının birlikte verdiği malvarlığının dondurulması kararı derhâl uygulanır ve ....(1).... içinde Ankara ağır ceza mahkemesinin onayına sunulur; mahkeme ....(2).... içinde kararın devamına veya kaldırılmasına karar verir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["yirmi dört saat - üç gün","kırk sekiz saat - on gün","kırk sekiz saat - beş gün","yetmiş iki saat - yedi gün","yirmi dört saat - beş gün"],"dogru":2,"aciklama":"m.7/4: \"...karar derhâl uygulanır ve kırk sekiz saat içinde ... Ankara ağır ceza mahkemesinin onayına sunulur. Mahkeme ... malvarlığının dondurulması kararının devamına veya kaldırılmasına beş gün içinde karar verir...\"","kaynak":"6415 m.7/4","zorluk":"orta"},
    {"id":"6415-S-014","soru":"6415 sayılı Kanun'a göre ilgililer tarafından Türkiye'de bulunan malvarlığının dondurulması kararının kaldırılmasına ilişkin talepler öncelikle nereye yapılır?","siklar":["Doğrudan Ankara ağır ceza mahkemesine","Hazine ve Maliye Bakanlığına doğrudan","Dışişleri Bakanlığına","Değerlendirme Komisyonuna","Cumhurbaşkanlığına"],"dogru":3,"aciklama":"m.7/6: \"İlgililer tarafından malvarlığının dondurulması kararının kaldırılmasına ilişkin talepler Değerlendirme Komisyonuna yapılır. Komisyon, taleplere ilişkin önerisini ilgili bakanlara sunar. Yerinde görülmeyen talepler ... ilgili mahkemeye gönderilir.\"","kaynak":"6415 m.7/6","zorluk":"zor"},
    {"id":"6415-S-015","soru":"6415 sayılı Kanun'a göre malvarlığının dondurulması kararları hakkında yapılacak mali araştırmayı kim yerine getirir ve bu araştırma hangi esasa tabidir?","siklar":["Değerlendirme Komisyonu yapar; aleniyet esasına tabidir","Ankara ağır ceza mahkemesi yapar; aleniyet esasına tabidir","İçişleri Bakanlığı yapar; kamuya açıklık esasına tabidir","Adalet Bakanlığı yapar; gizlilik esasına tabidir","Başkanlık (MASAK) yapar; gizlilik esasına tabidir"],"dogru":4,"aciklama":"m.8/1: \"Malvarlığının dondurulması kararları hakkında yapılacak mali araştırma Başkanlık tarafından yerine getirilir.\" m.8/4: \"...araştırma işlemleri gizlilik esaslarına uygun olarak yerine getirilir.\"","kaynak":"6415 m.8","zorluk":"orta"},
    {"id":"6415-S-016","soru":"6415 sayılı Kanun'a göre Değerlendirme Komisyonu kararlarını en az kaç üyenin oyuyla alır?","siklar":["En az 5","En az 4","En az 3","Salt çoğunlukla","Oybirliğiyle"],"dogru":0,"aciklama":"m.9/3: \"Değerlendirme Komisyonu ... katılanların en az beşinin oyu ile karar verir.\"","kaynak":"6415 m.9/3","zorluk":"kolay"},
    {"id":"6415-S-017","soru":"6415 sayılı Kanun'a göre malvarlığının dondurulması kararına aykırı olarak yapılan tasarruf ve işlemlerin hukuki durumu ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Bu tasarruflar geçerlidir, yalnızca idari para cezasını gerektirir","Bu tasarruflar hükümsüzdür ancak beş yıl sonra kendiliğinden geçerlilik kazanır","Bu tasarruflar hükümsüzdür; ancak Türk Medeni Kanununun iyiniyetin korunmasına ilişkin hükümleri saklıdır","Bu tasarruflar yalnız Başkanlığın onayıyla geçerli hâle gelir","Bu tasarruflar kesin hükümsüzdür, iyiniyet hiçbir şekilde korunmaz"],"dogru":2,"aciklama":"m.10: \"Malvarlığının dondurulması kararına aykırı olarak yapılan her türlü tasarruf ve işlem hükümsüzdür. Bu tasarruf ve işlemlerle ilgili olarak 4721 sayılı Türk Medeni Kanununun iyiniyetin korunmasına ilişkin hükümleri saklıdır.\"","kaynak":"6415 m.10","zorluk":"orta"},
    {"id":"6415-S-018","soru":"6415 sayılı Kanun'a göre malvarlığının dondurulması kararı, hakkında karar verilen kişi ve kuruluşa ne zaman tebliğ edilmiş sayılır?","siklar":["Kararın Başkanlıkça imzalandığı tarihte","Kararın ilgiliye posta yoluyla ulaştığı tarihte","Kararın Değerlendirme Komisyonunca onaylandığı tarihte","Kararın Resmî Gazete'de yayımlandığı tarihte","Kararın Ankara ağır ceza mahkemesince onaylandığı tarihte"],"dogru":3,"aciklama":"m.11/1: \"...Bu kararlar yayımı tarihinde, hakkında malvarlığının dondurulması kararı verilen ilgili kişi ve kuruluşa tebliğ edilmiş sayılır.\"","kaynak":"6415 m.11/1","zorluk":"kolay"},
    {"id":"6415-S-019","soru":"6415 sayılı Kanun'a göre hakkında malvarlığının dondurulması kararı verilmiş olanlar, malvarlığı değerlerine ilişkin bilgileri kararın Resmî Gazete'de yayımlandığı tarihten itibaren en geç ....(1).... içinde; kendisinden bilgi talep edilen üçüncü kişiler ise talep tarihinden itibaren ....(2).... içinde Başkanlığa bildirir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["on beş gün - üç gün","altmış gün - on beş gün","yedi gün - otuz gün","on gün - beş gün","otuz gün - yedi gün"],"dogru":4,"aciklama":"m.12/3: \"...kararının Resmî Gazete'de yayımlandığı tarihten itibaren en geç otuz gün içinde Başkanlığa bildirirler.\" m.12/5: \"...nezdinde malvarlığı kaydı bulunuyor ise ... talep tarihinden itibaren yedi gün içinde Başkanlığa bildirir.\"","kaynak":"6415 m.12/3,5","zorluk":"orta"},
    {"id":"6415-S-020","soru":"6415 sayılı Kanun'a göre dondurulmasına karar verilen malvarlığı üzerinde sair kişiler lehine ayni veya şahsi hak tesis edilmesine izin verilmesi hâlinde, sözleşme metninin bir örneği ve ödemeye ilişkin bilgiler hakkın tesis edildiği tarihten itibaren hangi süre içinde Başkanlığa verilir?","siklar":["7 gün","15 gün","30 gün","60 gün","3 ay"],"dogru":1,"aciklama":"m.13/4: \"...hakkın tesis edildiği tarihten itibaren en geç on beş gün içinde Başkanlığa verilir.\"","kaynak":"6415 m.13/4","zorluk":"orta"},
    {"id":"6415-S-021","soru":"6415 sayılı Kanun'a göre Başkanlık, dondurma kararına uygunluğu ve dondurulan malvarlığının yönetiminin Kanuna uygunluğunu denetlemek üzere hangi görevlileri görevlendirir?","siklar":["Yalnızca Cumhuriyet savcılarını","Yalnızca il jandarma komutanlığı personelini","5549 sayılı Kanunda belirtilen denetim elemanlarını veya Başkanlıkta istihdam edilen maliye uzmanlarını","Yalnızca Sayıştay denetçilerini","Yalnızca Ankara ağır ceza mahkemesi bilirkişilerini"],"dogru":2,"aciklama":"m.14/1: \"...5549 sayılı ... Kanunun 2 nci maddesinin birinci fıkrasının (e) bendinde belirtilen denetim elemanlarını veya Başkanlıkta istihdam edilen maliye uzmanlarını görevlendirir.\"","kaynak":"6415 m.14/1","zorluk":"orta"},
    {"id":"6415-S-022","soru":"6415 sayılı Kanun'un 15 inci maddesindeki ceza hükümleri bakımından aşağıdaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["Dondurma kararının gereğini yerine getirmeyen kişi: altı aydan iki yıla kadar hapis veya adli para cezası","Yasaklı kişi/kuruluşa bilerek fon sağlayan veya toplayan kişi: bir yıldan üç yıla kadar hapis veya adli para cezası","Yasaklıya finansal hizmet veren kişi: bir yıldan üç yıla kadar hapis veya adli para cezası","Dondurma kararının gereğini yerine getirmeyen kişi: iki yıldan beş yıla kadar hapis cezası","Kararın gereğini ihmal veya gecikmeyle yerine getiren kişi: altı aydan iki yıla kadar hapis veya adli para cezası"],"dogru":3,"aciklama":"m.15/1: kararın gereğini yerine getirmeyen/ihmal veya gecikme gösterenler 'altı aydan iki yıla kadar hapis veya adli para cezası' ile cezalandırılır (A, E doğru). m.15/2: yasaklıya bilerek fon sağlayan/toplayan veya finansal hizmet veren 'bir yıldan üç yıla kadar hapis veya adli para cezası' alır (B, C doğru). 'İki yıldan beş yıla kadar hapis' hükmü m.15'te yer almaz; D yanlış eşleştirmedir.","kaynak":"6415 m.15/1,2","zorluk":"orta"},
    {"id":"6415-S-023","soru":"6415 sayılı Kanun'a göre malvarlığının dondurulması kararının gereğini yerine getirmeyen kişinin bir tüzel kişinin organı veya temsilcisi olması hâlinde, bu tüzel kişiye ayrıca ne kadar idari para cezası verilir?","siklar":["Bin TL'den yüz bin TL'ye kadar","Beş bin TL'den bir milyon TL'ye kadar","Yirmi bin TL'den beş milyon TL'ye kadar","Elli bin TL sabit","On bin TL'den iki milyon TL'ye kadar"],"dogru":4,"aciklama":"m.15/3: \"...bu tüzel kişiye on bin Türk lirasından iki milyon Türk lirasına kadar idari para cezası verilir. Ancak bu fıkra uyarınca verilecek idari para cezası, tespit edilmesi hâlinde işleme konu edilen miktardan az olamaz.\"","kaynak":"6415 m.15/3","zorluk":"orta"},
    {"id":"6415-S-024","soru":"6415 sayılı Kanun'a göre, bu Kanunla yürürlükten kaldırılan 3713 sayılı Kanunun 8 inci maddesine mevzuatta yapılan yollamalar, 6415 sayılı Kanunun 4 üncü maddesine yapılmış sayılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16/2: \"Mevzuatta, bu Kanunla yürürlükten kaldırılan 3713 sayılı Kanunun 8 inci maddesine yapılan yollamalar bu Kanunun 4 üncü maddesine yapılmış sayılır.\"","kaynak":"6415 m.16/2","zorluk":"kolay"},
    {"id":"6415-S-025","soru":"6415 sayılı Kanun'a göre malvarlığının dondurulmasına ilişkin yetki-makam eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["Türkiye'deki malvarlığı dondurma kararının onayı: Değerlendirme Komisyonu","BMGK listesindeki kişi/kuruluşlar: Cumhurbaşkanı kararı","Yabancı devlet talebi: Değerlendirme Komisyonunun değerlendirmesi üzerine Cumhurbaşkanı kararı","Kesin terör örgütü kararı sonrası Türkiye'deki malvarlığı: Hazine ve Maliye Bakanı ile İçişleri Bakanı birlikte","Türkiye'deki malvarlığı dondurma kararının onayı: Ankara ağır ceza mahkemesi"],"dogru":0,"aciklama":"m.5/1 (BMGK→Cumhurbaşkanı), m.6/1 (yabancı talep→Komisyon değerlendirmesi + Cumhurbaşkanı kararı) ve m.7/3 (Türkiye'deki mal→iki bakan birlikte) doğrudur. Türkiye'deki malvarlığı dondurma kararını ONAYLAYAN merci m.7/4 uyarınca Ankara ağır ceza mahkemesidir (E doğru); Değerlendirme Komisyonu bu kararı onaylamaz, yalnızca öneride bulunur ve periyodik olarak gözden geçirir (A yanlış eşleştirme).","kaynak":"6415 m.5-7","zorluk":"zor"},
    {"id":"6415-S-026","soru":"6415 sayılı Kanun'a göre 'malvarlığı' tanımı kapsamında aşağıdakilerden hangisi de yer alır?","siklar":["Yalnızca kişinin doğrudan mülkiyetinde bulunan taşınır ve taşınmazlar","Yalnızca nakit para ve banka hesapları","Yalnızca Türkiye sınırları içindeki malvarlığı","Yalnızca tüzel kişilerin malvarlığı, gerçek kişilerinki kapsam dışıdır","Kişi adına veya hesabına hareket eden başka bir gerçek veya tüzel kişinin mülkiyetinde veya zilyetliğinde bulunan fon ve gelir"],"dogru":4,"aciklama":"m.2/1-ç (2): \"Malvarlığı: ... 2) Adına veya hesabına hareket eden gerçek veya tüzel kişinin mülkiyetinde ya da zilyetliğinde bulunan fon ve gelir ile bunlardan elde edilen veya bunların birbirine dönüştürülmesinden hasıl olan menfaat ve değeri, ifade eder.\" Tanım yalnız kişinin kendi mülkiyetiyle sınırlı değildir; onun adına/hesabına hareket eden başkasının malı da malvarlığı kapsamına girer.","kaynak":"6415 m.2/ç","zorluk":"zor"},
    {"id":"6415-S-027","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçunun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde, bu tüzel kişi hakkında herhangi bir yaptırım uygulanmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/5: \"Suçun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde, bunlara özgü güvenlik tedbirlerine hükmolunur.\" Tüzel kişi hakkında kendine özgü güvenlik tedbiri uygulanır, tamamen yaptırımsız kalınmaz.","kaynak":"6415 m.4/5","zorluk":"kolay"},
    {"id":"6415-S-028","soru":"6415 sayılı Kanun'a göre terörizmin finansmanı suçu bakımından, 3713 sayılı Terörle Mücadele Kanununun soruşturmaya, kovuşturmaya ve infaza ilişkin hükümleri de uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/7: \"3713 sayılı Kanunun soruşturmaya, kovuşturmaya ve infaza ilişkin hükümleri, bu suç bakımından da uygulanır.\"","kaynak":"6415 m.4/7","zorluk":"orta"},
    {"id":"6415-S-029","soru":"6415 sayılı Kanun'a göre, BMGK'nin 1267 (1999), 1988 (2011), 1989 (2011) ve 2253 (2015) sayılı kararlarına dayanılarak oluşturulan listelere kişi, kuruluş veya organizasyonların eklenmesi ya da makul sebeplerin ortadan kalkması hâlinde listeden çıkarılması Birleşmiş Milletler Güvenlik Konseyine kim tarafından ve nasıl teklif edilir?","siklar":["Cumhurbaşkanı, Değerlendirme Komisyonunun önerisi üzerine teklif eder; teklif Dışişleri Bakanlığı tarafından BMGK'ye bildirilir","Başkanlık (MASAK) doğrudan teklif eder; teklif Adalet Bakanlığı tarafından bildirilir","Değerlendirme Komisyonu doğrudan teklif eder; teklif Başkanlık tarafından bildirilir","İçişleri Bakanı teklif eder; teklif Hazine ve Maliye Bakanlığı tarafından bildirilir","Ankara ağır ceza mahkemesi teklif eder; teklif Adalet Bakanlığı tarafından bildirilir"],"dogru":0,"aciklama":"m.5/4: \"...Değerlendirme Komisyonunun önerisi üzerine Cumhurbaşkanı tarafından kişi, kuruluş veya organizasyonların ... listelere eklenmesi ve ... listelerden çıkarılması Birleşmiş Milletler Güvenlik Konseyine teklif edilebilir. Cumhurbaşkanının teklifi Dışişleri Bakanlığı tarafından Birleşmiş Milletler Güvenlik Konseyine bildirilir.\"","kaynak":"6415 m.5/4","zorluk":"zor"},
    {"id":"6415-S-030","soru":"6415 sayılı Kanun'a göre yabancı bir devlet hükûmetinin malvarlığının dondurulmasına ilişkin talebinin yerine getirilmesi için ilgili devletten ne talep edilebilir?","siklar":["Kefil gösterilmesi","Ek gerekçe raporu sunulması","Teminat talep edilmesi","Diplomatik dokunulmazlığın kaldırılması","Vergi mükellefiyet belgesi ibrazı"],"dogru":2,"aciklama":"m.6/3: \"Yabancı devlet hükûmetinin malvarlığının dondurulmasına ilişkin taleplerinin yerine getirilmesi için, ilgili devletten teminat talep edilebilir.\"","kaynak":"6415 m.6/3","zorluk":"kolay"},
    {"id":"6415-S-031","soru":"6415 sayılı Kanun'a göre kişi, kuruluş veya organizasyonların YABANCI ÜLKELERDE bulunan malvarlığının dondurulması talebiyle ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Türkiye'deki malvarlığında olduğu gibi Hazine ve Maliye Bakanı ile İçişleri Bakanı birlikte karar verir","Değerlendirme Komisyonu, bu yönde Cumhurbaşkanına öneride bulunulmasına karar verebilir","Ankara ağır ceza mahkemesi doğrudan karar verir","Doğrudan Dışişleri Bakanı karar verir","Yalnızca BMGK kararı varsa işlem yapılabilir"],"dogru":1,"aciklama":"m.7/1: \"...Değerlendirme Komisyonu, 3 üncü ve 4 üncü madde kapsamına giren fiilleri gerçekleştirdiği hususunda makul sebeplerin varlığına istinaden kişi, kuruluş veya organizasyonların yabancı ülkelerde bulunan malvarlığının dondurulması talebiyle Cumhurbaşkanına öneride bulunulmasına karar verebilir.\" Bu, Türkiye'deki malvarlığı için m.7/3'te öngörülen 'iki bakan birlikte karar' usulünden farklıdır.","kaynak":"6415 m.7/1","zorluk":"zor"},
    {"id":"6415-S-032","soru":"6415 sayılı Kanun'a göre Türkiye'de bulunan malvarlığının dondurulmasına karar verildiği takdirde, ilgililer hakkında Ceza Muhakemesi Kanunu uyarınca soruşturma açılması talebiyle suç duyurusunda bulunulmasına hangi makam karar verir?","siklar":["İçişleri Bakanı","Ankara ağır ceza mahkemesi","Değerlendirme Komisyonu","Adalet Bakanı","Başkanlık (MASAK)"],"dogru":4,"aciklama":"m.7/7: \"...Türkiye'de bulunan malvarlığının dondurulmasına karar verildiği takdirde ilgililer hakkında Ceza Muhakemesi Kanunu uyarınca soruşturma açılması talebiyle suç duyurusunda bulunulmasına Başkanlık tarafından karar verilir. Soruşturma ve kovuşturma sonucunda verilen kararlar Değerlendirme Komisyonuna sunulmak üzere Başkanlığa gönderilir.\"","kaynak":"6415 m.7/7","zorluk":"orta"},
    {"id":"6415-S-033","soru":"6415 sayılı Kanun'a göre Değerlendirme Komisyonu başkan ve üyelerine her toplantı için ....(1).... gösterge rakamının memur aylık katsayısıyla çarpımı sonucu bulunan tutar üzerinden toplantı ücreti ödenirken; 14 üncü madde uyarınca denetimle görevlendirilenlere ....(2).... gösterge rakamını geçmemek üzere aylık ek ücret ödenir. Boşluklara sırasıyla gelmesi gereken gösterge rakamları hangisidir?","siklar":["7.000 - 4.000","4.000 - 4.000","5.000 - 10.000","4.000 - 7.000","7.000 - 10.000"],"dogru":3,"aciklama":"m.9/5: \"Değerlendirme Komisyonunun başkan ve üyelerine her toplantı için (4.000) gösterge rakamının memur aylık katsayısıyla çarpımı sonucu bulunan tutar üzerinden toplantı ücreti ödenir.\" m.14/2: \"...görevlendirilenlere ... (7.000) gösterge rakamının memur aylık katsayısıyla çarpımı sonucunda bulunan tutarı geçmemek üzere ... aylık ek ücret ödenir.\"","kaynak":"6415 m.9/5, m.14/2","zorluk":"zor"},
    {"id":"6415-S-034","soru":"6415 sayılı Kanun'a göre, dondurulmuş bir malvarlığında sonradan meydana gelen artışlar (örneğin faiz geliri), dondurma hükümlerinin dışında kalır ve serbestçe tasarruf edilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/6: \"Malvarlığında herhangi bir artış meydana gelmesi hâlinde, bu artışlar da malvarlığının dondurulması hükümlerine tabidir.\" Artışlar dondurma kapsamının dışında bırakılmaz, aksine aynı hükümlere tabi olur.","kaynak":"6415 m.12/6","zorluk":"kolay"},
    {"id":"6415-S-035","soru":"6415 sayılı Kanun'a göre dondurulan malvarlığından vergi, resim, harç, kira, sosyal güvenlik primi gibi kamu kurumlarına yapılacak zorunlu ödemeler kural olarak nasıl gerçekleştirilir?","siklar":["Kural olarak izin alınmaksızın gerçekleştirilebilir; Başkanlık gerek görürse bu işlemleri de izne tabi tutabilir","Yalnızca Ankara ağır ceza mahkemesi kararıyla yapılabilir","Her durumda Başkanlığın önceden yazılı izni şarttır","Değerlendirme Komisyonunun onayı olmadan hiçbir ödeme yapılamaz","Bu ödemeler dondurma kararının kapsamı dışında tutulduğundan Kanunda hiç düzenlenmemiştir"],"dogru":0,"aciklama":"m.13/3: \"Dondurulan malvarlığından ödenmesi gereken vergi, resim, harç, kira, sosyal güvenlik primi gibi kamu kurumu veya kamu kurumu niteliğindeki kuruluşlara yapılacak her türlü zorunlu ödemeler, izin alınmaksızın gerçekleştirilebilir. Ancak Başkanlık gerek görmesi hâlinde bu işlemleri de izne tabi tutabilir.\"","kaynak":"6415 m.13/3","zorluk":"orta"},
    {"id":"6415-S-036","soru":"6415 sayılı Kanun'a göre, malvarlığının dondurulması kararı verilmiş olan kişiye dondurma kararının Resmî Gazete'de yayımlandığı tarihten itibaren yapılacak her türlü ödeme nasıl gerçekleştirilir?","siklar":["Elden nakit olarak ödenir","Yalnızca yurt dışındaki bir hesaba yapılabilir","Ancak bu kişiye ait bir banka hesabına yapılabilir; hesabı yoksa Başkanlık tarafından kişi adına hesap açtırılır","Ödeme yapılamaz, dondurma kararı kalkana kadar bekletilir","Üçüncü bir kişinin hesabına yapılabilir"],"dogru":2,"aciklama":"m.13/5: \"Hakkında malvarlığının dondurulması kararı verilmiş olanlara dondurma kararının Resmî Gazete'de yayımlandığı tarihten itibaren yapılacak her türlü ödeme, ancak bu kişilere ait bir banka hesabına yapılabilir. Malvarlığı dondurulan kişinin ... Türkiye'de bulunan bir bankada hesabı yoksa Başkanlık tarafından kişi adına hesap açtırılır.\"","kaynak":"6415 m.13/5","zorluk":"kolay"},
    {"id":"6415-S-037","soru":"6415 sayılı Kanun'a göre malvarlığı dondurulan kişinin asgari geçimini sağlamak veya ticari faaliyetine devam edebilmesini temin etmek üzere Başkanlığın izniyle yapılabilecek işlemler arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Taşınmazlar üzerinde sair kişiler lehine ayni veya şahsi hak tesisi","Dondurulan malvarlığının bir kısmının bağışlanması","Banka veya diğer finans kurumlarındaki hesaplar üzerindeki tasarruf yetkisinin kullanılması","Şirketlerdeki ortaklık payları üzerindeki tasarruf yetkisinin kullanılması","Ücret ve maaş gibi zorunlu ödemelerin gerçekleştirilmesi"],"dogru":1,"aciklama":"m.13/2 (a)-(f) bentlerinde taşınmaz/taşıt üzerinde hak tesisi, banka hesabı tasarrufu, alacak/hak tasarrufu, kıymetli evrak tasarrufu, ortaklık payı tasarrufu, kiralık kasa tasarrufu ve zorunlu ödemeler (ücret, maaş, kira, kredi vb.) sayılmıştır. 'Bağışlama' bu kapalı listede yer almaz; ayrıca m.10 uyarınca dondurma kararına aykırı her türlü tasarruf zaten hükümsüzdür.","kaynak":"6415 m.13/2","zorluk":"zor"},
  ],
  46: [
    {"id":"2863-S-001","soru":"2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanunu'na göre 'jeolojik devirlerle, tarih öncesi ve tarihi devirlere ait olup ender bulunmaları veya özellikleri ve güzellikleri bakımından korunması gerekli' değerler aşağıdakilerden hangisi olarak tanımlanmıştır?","siklar":["Tabiat varlıkları","Kültür varlıkları","Sit","Ören yeri","Doğal (tabii) sit"],"dogru":0,"aciklama":"m.3/a-(2): \"'Tabiat varlıkları'; jeolojik devirlerle, tarih öncesi ve tarihi devirlere ait olup ender bulunmaları veya özellikleri ve güzellikleri bakımından korunması gerekli ... değerlerdir.\" Tanım birebir tabiat varlığına aittir.","kaynak":"2863 m.3","zorluk":"kolay"},
    {"id":"2863-S-002","soru":"2863 sayılı Kanun'a göre 'topoğrafik olarak tanımlanabilecek derecede yeterince belirgin ve mütecanis özelliklere sahip, kısmen inşa edilmiş, insan emeği kültür varlıkları ile tabiat varlıklarının birleştiği alanlar' hangi kavramla tanımlanmıştır?","siklar":["Ören yeri","Sit","Yönetim alanı","Etkileşim-geçiş sahası","Korunma alanı"],"dogru":0,"aciklama":"m.3/a-(7): \"'Ören yeri'; ... topoğrafik olarak tanımlanabilecek derecede yeterince belirgin ve mütecanis özelliklere sahip ... kısmen inşa edilmiş, insan emeği kültür varlıkları ile tabiat varlıklarının birleştiği alanlardır.\"","kaynak":"2863 m.3","zorluk":"orta"},
    {"id":"2863-S-003","soru":"2863 sayılı Kanun'a göre 'Kültür Varlıklarını Koruma Bölge Kurulu' Kanun metninde hangi kısaltmayla ifade edilir?","siklar":["Koruma Bölge Kurulu","Koruma Yüksek Kurulu","Bakanlık","İl Kültür Müdürlüğü","Anıtlar Kurulu"],"dogru":0,"aciklama":"m.3/b-(3): \"'Koruma Bölge Kurulu'; Kültür Varlıklarını Koruma Bölge Kurulunu ... ifade eder.\" Kanunda tanımlı üç kısaltma Bakanlık, Koruma Yüksek Kurulu ve Koruma Bölge Kurulu'dur.","kaynak":"2863 m.3","zorluk":"orta"},
    {"id":"2863-S-004","soru":"2863 sayılı Kanun'a göre yönetim planları, yürürlüğe girdikten sonra her yıl yeniden gözden geçirilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/a-(11): \"'Yönetim plânı'; ... yıllık ve beş yıllık uygulama etaplarını ve bütçesini de gösteren, her beş yılda bir gözden geçirilen plânlardır.\" Planın uygulama etapları yıllık olsa da GÖZDEN GEÇİRME dönemi beş yıldır.","kaynak":"2863 m.3","zorluk":"orta"},
    {"id":"2863-S-005","soru":"2863 sayılı Kanun'a göre 'jeolojik devirlere ait olup, ender bulunmaları nedeniyle olağanüstü özelliklere sahip, yer üstünde, yer altında veya su altında bulunan korunması gerekli TAŞINIR tabii değerler' hangi kavramla tanımlanır?","siklar":["Doğal (tabii) sit","Taşınır tabiat varlıkları","Taşınmaz tabiat varlığı","Sit","Tabiat varlıkları (genel tanım)"],"dogru":1,"aciklama":"m.3/a-(14): \"'Taşınır tabiat varlıkları'; jeolojik devirlere ait olup, ender bulunmaları nedeniyle olağanüstü özelliklere sahip ... korunması gerekli taşınır tabii değerlerdir.\"","kaynak":"2863 m.3","zorluk":"zor"},
    {"id":"2863-S-006","soru":"2863 sayılı Kanun'a göre taşınır ve taşınmaz kültür ve tabiat varlıklarını bulanlar, bunu en geç ....(1).... gün içinde en yakın müze müdürlüğüne, muhtara veya mülki idare amirine bildirmeye mecburdur; mülki amir ve diğer makamlar ise durumu ....(2).... gün içinde yazı ile Bakanlığa ve en yakın müze müdürlüğüne bildirir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["5 - 15","3 - 10","10 - 3","7 - 15","3 - 15"],"dogru":1,"aciklama":"m.4: \"...bunu en geç üç gün içinde ... bildirmeye mecburdurlar ... mülki amir ve diğer makamlar ise on gün içinde, yazı ile Kültür ve Turizm Bakanlığına ve en yakın müze müdürlüğüne bildirir.\" Bulan için 3 gün, makam için 10 gündür.","kaynak":"2863 m.4","zorluk":"orta"},
    {"id":"2863-S-007","soru":"2863 sayılı Kanun'a göre askeri garnizonlar ve yasak bölgeler içinde bulunan kültür ve tabiat varlıkları usulüne uygun olarak nereye bildirilir?","siklar":["En yakın müze müdürlüğüne","Üst komutanlıklara","Mülki idare amirine","Kültür ve Turizm Bakanlığına","Koruma Bölge Kuruluna"],"dogru":1,"aciklama":"m.4/2.fıkra: \"Bu gibi varlıklar, askeri garnizonlar ve yasak bölgeler içinde bulunursa, usulüne uygun olarak üst komutanlıklara bildirilir.\" Bu, genel kuralın (müze/muhtar/mülki amir) özel bir istisnasıdır.","kaynak":"2863 m.4","zorluk":"kolay"},
    {"id":"2863-S-008","soru":"2863 sayılı Kanun'un 6'ncı maddesine göre aşağıdakilerden hangisi 'korunması gerekli taşınmaz kültür ve tabiat varlığı' sayılan haller arasında YER ALMAZ?","siklar":["19'uncu yüzyıl sonuna kadar yapılmış taşınmazlar","Yapım tarihine bakılmaksızın her özel mülkiyetteki bina","Sit alanı içinde bulunan taşınmaz kültür varlıkları","Mustafa Kemal Atatürk tarafından kullanılmış evler","Bakanlıkça önem ve özellikleri bakımından korunmasında gerek görülen taşınmazlar"],"dogru":1,"aciklama":"m.6 bentleri: (a) 19. yy sonuna kadar yapılmış taşınmazlar, (b) Bakanlıkça korunmasında gerek görülenler, (c) sit alanı içindeki taşınmaz kültür varlıkları, (d) Atatürk'ün kullandığı evler ve Milli Mücadele binaları. 'Yapım tarihine bakılmaksızın her özel mülkiyetteki bina' ifadesi madde metninde yoktur; kanun sınırlı ve koşullu bentler sayar.","kaynak":"2863 m.6","zorluk":"orta"},
    {"id":"2863-S-009","soru":"2863 sayılı Kanun'un 6'ncı maddesine göre aşağıdakilerden hangisi 'taşınmaz TABİAT varlığı' örneği olarak sayılmıştır?","siklar":["Kervansaray","Höyük","Tarihi mağara","Su kemeri","Külliye"],"dogru":2,"aciklama":"m.6/son fıkra: \"Tarihi mağaralar, kaya sığınakları; özellik gösteren ağaç ve ağaç toplulukları ile benzerleri; taşınmaz tabiat varlığı örneklerindendir.\" Diğerleri aynı maddede 'taşınmaz kültür varlığı' örnekleri arasında sayılmıştır.","kaynak":"2863 m.6","zorluk":"orta"},
    {"id":"2863-S-010","soru":"2863 sayılı Kanun'a göre korunması gerekli taşınmaz kültür ve tabiat varlıkları ile bunların korunma alanlarında ruhsatsız olarak inşaat yapmak yasaktır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16: \"Korunması gerekli taşınmaz kültür ve tabiat varlıkları ile bunların korunma alanlarında ruhsatsız olarak inşaat yapmak yasaktır.\" İfade madde metniyle birebir örtüşür.","kaynak":"2863 m.16","zorluk":"kolay"},
    {"id":"2863-S-011","soru":"2863 sayılı Kanun'un 23'üncü maddesine göre aşağıdakilerden hangisi korunması gerekli taşınır kültür ve tabiat varlığı örnekleri arasında SAYILMAMIŞTIR?","siklar":["Sikkeler","Heykeller","Sit alanı içindeki yol altyapı tesisleri","Yazma veya tezhipli kitaplar","Hayvan ve bitki fosilleri"],"dogru":2,"aciklama":"m.23/a: madde metninde sikkeler, heykeller, yazma/tezhipli kitaplar ve hayvan-bitki fosilleri birebir sayılıdır. 'Sit alanı içindeki yol altyapı tesisleri' m.23'ün taşınır eşya listesinde yer almaz; bu tür unsurlar taşınmaz kavramlarıyla (sit, korunma alanı) ilgilidir.","kaynak":"2863 m.23","zorluk":"zor"},
    {"id":"2863-S-012","soru":"2863 sayılı Kanun'a göre hangi Osmanlı padişahlarına ve aynı çağdaki sikkelere ait sikkeler, Kanuna göre tescile tabi olmaksızın yurt içinde alınıp satılabilir?","siklar":["Fatih Sultan Mehmet, II. Bayezid, Yavuz Sultan Selim","I. Ahmet, IV. Murat, III. Selim","Abdülmecit, Abdülaziz, V. Murat, II. Abdülhamit, V. Mehmet Reşat ve Vahidettin","Sadece Vahidettin","Sadece II. Abdülhamit ve Vahidettin"],"dogru":2,"aciklama":"m.23/a: \"Osmanlı Padişahlarından Abdülmecit, Abdülaziz, V. Murat, II. Abdülhamit, V. Mehmet Reşat ve Vahidettin ve aynı çağdaki sikkeler, bu Kanuna göre tescile tabi olmaksızın yurt içinde alınıp satılabilirler.\"","kaynak":"2863 m.23","zorluk":"orta"},
    {"id":"2863-S-013","soru":"2863 sayılı Kanun'a göre Devlet müzeleri içerisinde özel bir ihtisas ve araştırma müzesi olan askeri müzelerin kurulması, yaşatılması, malzeme ve uğraş konularının tayin ve tespiti hangi makama aittir?","siklar":["Kültür ve Turizm Bakanlığı","Milli Savunma Bakanlığı","Genelkurmay Başkanlığı","İçişleri Bakanlığı","Koruma Yüksek Kurulu"],"dogru":2,"aciklama":"m.26/4.fıkra: \"Devlet müzeleri içerisinde özel bir ihtisas ve araştırma müzeleri olan askeri müzelerin kurulması, yaşatılması, malzemenin ve uğraş konularının tayin ve tespiti Genelkurmay Başkanlığına aittir.\"","kaynak":"2863 m.26","zorluk":"orta"},
    {"id":"2863-S-014","soru":"2863 sayılı Kanun'a göre koleksiyoncular, koleksiyonlarındaki her türlü eseri ....(1).... önce Kültür ve Turizm Bakanlığına haber vermek şartıyla kendi aralarında değiştirebilir veya satabilirler; satın almada öncelik ....(2).... aittir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["10 gün - ilgili müzeye","30 gün - valiliğe","15 gün - Kültür ve Turizm Bakanlığına","15 gün - ilgili müzeye","7 gün - Kültür ve Turizm Bakanlığına"],"dogru":2,"aciklama":"m.26 son fıkra: \"Koleksiyoncular, ilgili müzeye tescil ettirerek, koleksiyonlarındaki her türlü eseri onbeş gün önce Kültür ve Turizm Bakanlığına haber vermek şartı ile kendi aralarında değiştirebilir veya satabilirler. Satın almada öncelik Kültür ve Turizm Bakanlığına aittir.\"","kaynak":"2863 m.26","zorluk":"orta"},
    {"id":"2863-S-015","soru":"2863 sayılı Kanun'a göre bulunan kültür varlığı, bulanın kendi mülkü içinde ise ayrıca ikramiye verilmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.64/a: \"Bulunan varlık, bunların mülkü içinde ise bu Kanunun 24 üncü ve 25 inci maddeleri uygulanır. Ayrıca ikramiye verilmez.\"","kaynak":"2863 m.64","zorluk":"kolay"},
    {"id":"2863-S-016","soru":"2863 sayılı Kanun'a göre bir kültür varlığı Devlete ait arazide bulunmuş ise, takdir olunacak bedelin yüzde kaçı ikramiye olarak bulana verilir?","siklar":["%20","%80","%40","%50","%100"],"dogru":2,"aciklama":"m.64/c: \"Kültür varlığı Devlete ait arazide bulunmuş ise, takdir olunacak bedelin % 40'ı bulana ikramiye olarak verilir.\"","kaynak":"2863 m.64","zorluk":"orta"},
    {"id":"2863-S-017","soru":"2863 sayılı Kanun'a göre kültür varlığını bulan, haber veren veya yakalayan kişi birden fazla ise, verilecek ikramiye bunlar arasında kıdem sırasına göre paylaştırılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.64/f: \"Yukarıdaki fıkralardan herhangi biri uyarınca kültür varlıklarını bulan, haber veren veya yakalayan kişiler birden fazla ise verilecek ikramiyeler bunlar arasında EŞİT olarak paylaştırılır.\" Kıdem esası kanunda yoktur.","kaynak":"2863 m.64","zorluk":"orta"},
    {"id":"2863-S-018","soru":"2863 sayılı Kanun'a göre tescilli sit alanları ile korunması gerekli taşınmaz kültür ve tabiat varlıklarının tahribine kasten sebebiyet verenler hakkında öngörülen temel hapis cezası aralığı aşağıdakilerden hangisidir? (Fiil, kültür varlığını yurt dışına kaçırmak amacıyla işlenmemiştir.)","siklar":["6 aydan 3 yıla kadar","1 yıldan 3 yıla kadar","3 aydan 1 yıla kadar","2 yıldan 5 yıla kadar","5 yıldan 12 yıla kadar"],"dogru":3,"aciklama":"m.65/1.fıkra: \"...yıkılmasına, bozulmasına, tahribine, yok olmasına veya her ne suretle olursa olsun zarar görmesine kasten sebebiyet verenler ... iki yıldan beş yıla kadar hapis ve beş bin güne kadar adli para cezasıyla cezalandırılır.\"","kaynak":"2863 m.65","zorluk":"kolay"},
    {"id":"2863-S-019","soru":"2863 sayılı Kanun'a göre m.65'te tanımlanan tahrip fiilleri, kültür ve tabiat varlığını yurt dışına kaçırmak amacıyla işlenmişse verilecek ceza nasıl uygulanır; ruhsata tabi olmayan tadilat ve tamiratları izinsiz yapanlar için öngörülen ceza aralığı nedir?","siklar":["Ceza yarıya iner; tadilat 3 aydan 1 yıla kadar","Ceza iki katına çıkar; tadilat 1 yıldan 3 yıla kadar","Ceza değişmez; tadilat yüz günden az olmamak üzere adli para","Ceza bir kat artırılır; tadilat 6 aydan 3 yıla kadar","Ceza üçte iki artar; tadilat 2 yıldan 5 yıla kadar"],"dogru":3,"aciklama":"m.65/3.fıkra: \"Birinci ve ikinci fıkralarda belirtilen fiiller, ... yurt dışına kaçırmak amacıyla işlenmiş ise verilecek cezalar bir kat artırılır.\" m.65/4.fıkra: ruhsata tabi olmayan tadilat ve tamiratları izinsiz yapanlar veya yaptıranlar, \"altı aydan üç yıla kadar hapis veya adli para cezası ile cezalandırılır.\"","kaynak":"2863 m.65","zorluk":"zor"},
    {"id":"2863-S-020","soru":"2863 sayılı Kanun'un 66'ncı maddesine göre, 16'ncı maddedeki yasaklara aykırı olarak belge verenler ....(1)...., 7'nci maddedeki ilan veya tebligatı bilerek süresinde usulüne uygun yapmayanlar ise ....(2).... hapis ve adli para cezası ile cezalandırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["3 aydan 1 yıla kadar - 1 yıldan 3 yıla kadar","6 aydan 3 yıla kadar - 2 yıldan 5 yıla kadar","2 yıldan 5 yıla kadar - 6 aydan 3 yıla kadar","1 yıldan 3 yıla kadar - 3 aydan 1 yıla kadar","1 yıldan 3 yıla kadar - 6 aydan 3 yıla kadar"],"dogru":3,"aciklama":"m.66: \"Bu Kanunun 16 ncı maddesinde yer alan yasaklara aykırı olarak belge verenler ... bir yıldan üç yıla kadar hapis ve adlî para cezası ile; ... 7 nci maddesinde yer alan ilan veya tebligatı bilerek, süresinde usulüne uygun yapmayanlar ise, üç aydan bir yıla kadar hapis ve adlî para cezası ile cezalandırılırlar.\"","kaynak":"2863 m.66","zorluk":"zor"},
    {"id":"2863-S-021","soru":"2863 sayılı Kanun'a göre bildirimi yapılmamış olan kültür ve tabiat varlığını satışa arzeden, satan, veren, satın alan veya kabul eden kişi hakkında öngörülen ceza aşağıdakilerden hangisidir?","siklar":["6 aydan 3 yıla kadar hapis","3 aydan 1 yıla kadar hapis","1 yıldan 3 yıla kadar hapis","2 yıldan 5 yıla kadar hapis ve beşbin güne kadar adli para cezası","5 yıldan 12 yıla kadar hapis"],"dogru":3,"aciklama":"m.67/2.fıkra: \"Bildirimi yapılmamış olan kültür ve tabiat varlığını satışa arzeden, satan, veren, satın alan, kabul eden kişi iki yıldan beş yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır.\"","kaynak":"2863 m.67","zorluk":"orta"},
    {"id":"2863-S-022","soru":"2863 sayılı Kanun'a göre kültür ve tabiat varlıklarını Kanuna aykırı olarak yurt dışına çıkaran kişi hakkında öngörülen hapis cezası aralığı aşağıdakilerden hangisidir?","siklar":["2 yıldan 5 yıla kadar","1 yıldan 3 yıla kadar","6 aydan 3 yıla kadar","5 yıldan 12 yıla kadar","3 aydan 1 yıla kadar"],"dogru":3,"aciklama":"m.68: \"Kültür ve tabiat varlıklarını bu Kanuna aykırı olarak yurt dışına çıkaran kişi, beş yıldan oniki yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır.\" Bu, Kanundaki en ağır cezadır.","kaynak":"2863 m.68","zorluk":"kolay"},
    {"id":"2863-S-023","soru":"2863 sayılı Kanun'un 69'uncu maddesine göre, 29'uncu maddede yer alan tetkik ve kontrole muhalefet edenler ile 41'inci maddedeki nakil işlerine aykırı hareket edenler hakkında öngörülen ceza aralığı aşağıdakilerden hangisidir?","siklar":["3 aydan 1 yıla kadar","1 yıldan 3 yıla kadar","2 yıldan 5 yıla kadar","100 günden az olmamak üzere adli para","6 aydan 1 yıla kadar"],"dogru":4,"aciklama":"m.69: \"Bu Kanunun 29 uncu maddesinde yer alan tetkik ve kontrole muhalefet edenler ile 41 inci maddede yer alan nakil işlerine aykırı hareket edenler altı aydan bir yıla kadar hapis ve adlî para cezası ile cezalandırılırlar.\"","kaynak":"2863 m.69","zorluk":"orta"},
    {"id":"2863-S-024","soru":"2863 sayılı Kanun'un 70'inci maddesine göre, Kanunun 24'üncü maddesine (özel mülkiyete konu taşınır kültür varlıklarına ilişkin hükümler) aykırı hareket edenler hakkında öngörülen ceza aşağıdakilerden hangisidir?","siklar":["3 aydan 1 yıla kadar hapis ve adli para cezası","6 aydan 1 yıla kadar hapis ve adli para cezası","2 yıldan 5 yıla kadar hapis","100 günden az olmamak üzere adli para cezası","1 yıldan 3 yıla kadar hapis ve üçbin güne kadar adli para cezası"],"dogru":4,"aciklama":"m.70: \"Bu Kanunun 24 üncü maddesine aykırı hareket edenler bir yıldan üç yıla kadar hapis ve üçbin güne kadar adlî para cezası ile cezalandırılırlar.\"","kaynak":"2863 m.70","zorluk":"orta"},
    {"id":"2863-S-025","soru":"2863 sayılı Kanun'un 71'inci maddesine göre, Kanunun 38, 42 ve 43'üncü maddelerine (kazı, sondaj ve araştırmaya ilişkin hükümler) aykırı hareket edenler hakkında öngörülen yaptırım aşağıdakilerden hangisidir?","siklar":["2 yıldan 5 yıla kadar hapis","6 aydan 1 yıla kadar hapis","1 yıldan 3 yıla kadar hapis","5 yıldan 12 yıla kadar hapis","Yüz günden az olmamak üzere adli para cezası"],"dogru":4,"aciklama":"m.71: \"Bu Kanunun 38, 42 ve 43 üncü maddelerine aykırı hareket edenler yüz günden az olmamak üzere adlî para cezasıyla cezalandırılırlar.\" Bu madde istisnai olarak yalnızca adli para cezası öngörür, hapis cezası yoktur.","kaynak":"2863 m.71","zorluk":"zor"},
    {"id":"2863-S-026","soru":"2863 sayılı Kanun'un 72 ve 73'üncü maddelerine göre aşağıdaki ifadelerden hangisi YANLIŞTIR?","siklar":["m.72 uyarınca görevli kamu personeli hakkında yapılacak iş ve işlemler, alınacak kararlar öncelikle incelenir ve sonuçlandırılır.","m.73 uyarınca 26 ve 30'uncu maddelere aykırı davrananlara, suç daha ağır bir cezayı gerektirmiyorsa üç aydan bir yıla kadar hapis ve adli para cezası verilir.","m.72 kapsamındaki kararlara karşı yapılacak itirazlar da öncelikle incelenip sonuçlandırılır.","m.73 cezası hem hapis hem adli para cezasını birlikte öngörür.","m.73 cezası, fiil daha ağır bir cezayı gerektirse dahi mutlaka üç aydan bir yıla kadar hapis olarak uygulanır."],"dogru":4,"aciklama":"Yanlış olan E'dir. m.73: \"Bu Kanunun 26 ve 30 uncu maddelerine aykırı davrananlara, SUÇ DAHA AĞIR BİR CEZAYI GEREKTİRMİYORSA üç aydan bir yıla kadar hapis ve adlî para cezası verilir.\" Yani fiil daha ağır bir cezayı gerektiriyorsa m.73 değil, o ağır ceza uygulanır. A, B, C, D ifadeleri m.72 ve m.73 metniyle birebir örtüşür.","kaynak":"2863 m.72, m.73","zorluk":"zor"},
    {"id":"2863-S-027","soru":"2863 sayılı Kanun'a göre kültür varlığı bulmak amacıyla izinsiz olarak kazı veya sondaj yapan kişi ....(1)...., izinsiz olarak define araştıran kişi ise ....(2).... hapis cezası ile cezalandırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["6 aydan 3 yıla kadar - 3 aydan 1 yıla kadar","1 yıldan 3 yıla kadar - 6 aydan 1 yıla kadar","5 yıldan 12 yıla kadar - 2 yıldan 5 yıla kadar","2 yıldan 5 yıla kadar - 6 aydan 3 yıla kadar","2 yıldan 5 yıla kadar - 3 aydan 2 yıla kadar"],"dogru":4,"aciklama":"m.74/1-2.fıkra: \"Kültür varlıkları bulmak amacıyla, izinsiz olarak kazı veya sondaj yapan kişi, iki yıldan beş yıla kadar hapis cezasıyla cezalandırılır. ... İzinsiz olarak define araştıranlar, üç aydan iki yıla kadar hapis cezası ile cezalandırılır.\"","kaynak":"2863 m.74","zorluk":"zor"},
    {"id":"2863-S-028","soru":"2863 sayılı Kanun'a göre m.74'te tanımlanan suçları işleyen kişinin, bulduğu kültür varlığını soruşturma başlamadan önce mahallî mülkî amire teslim etmesi hâlinde, mahkeme verilecek cezada ne kadarına kadar indirim yapabilir?","siklar":["Yarısına","Üçte birine","Dörtte üçüne","Tamamına (ceza verilmesine yer olmadığına karar verilir)","Üçte ikisine"],"dogru":4,"aciklama":"m.74/3.fıkra: \"Kişinin bu maddede tanımlanan suçları işlemek suretiyle bulduğu kültür varlığını soruşturma başlamadan önce mahallî mülkî amire teslim etmesi hâlinde, mahkeme verilecek cezada üçte ikisine kadar indirim yapabilir.\"","kaynak":"2863 m.74","zorluk":"orta"},
    {"id":"2863-S-029","soru":"2863 sayılı Kanun'a göre bu Kanun kapsamında kalan suçlar nedeniyle elkonulan taşınır kültür ve tabiat varlıkları müzeye teslim edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.75: \"Bu Kanun kapsamında kalan suçlar nedeniyle elkonulan taşınır kültür ve tabiat varlıkları müzeye teslim edilir.\" İfade madde metniyle birebir örtüşür.","kaynak":"2863 m.75","zorluk":"kolay"},
    {"id":"2863-S-030","soru":"2863 sayılı Kanun'a göre 'Koruma' ve 'Korunma' tanımı, taşınır kültür varlıklarında da taşınmazlarda olduğu gibi fonksiyon değiştirme işlemini kapsar.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/a-(4): \"'Koruma' ve 'Korunma'; taşınmaz kültür ve tabiat varlıklarında muhafaza, bakım, onarım, restorasyon, fonksiyon değiştirme işlemleri; taşınır kültür varlıklarında ise muhafaza, bakım, onarım ve restorasyon işleridir.\" Fonksiyon değiştirme yalnızca TAŞINMAZ varlıklar için sayılmıştır, taşınırda yoktur.","kaynak":"2863 m.3","zorluk":"orta"},
    {"id":"2863-S-031","soru":"2863 sayılı Kanun'a göre 'taşınmaz kültür ve tabiat varlıklarının muhafazaları veya tarihi çevre içinde korunmalarında etkinlik taşıyan korunması zorunlu olan alan' aşağıdaki kavramlardan hangisiyle tanımlanmıştır?","siklar":["Etkileşim-geçiş sahası","Yönetim alanı","Sit","Korunma alanı","Çevre düzenleme projesi"],"dogru":3,"aciklama":"m.3/a-(5): \"'Korunma alanı'; taşınmaz kültür ve tabiat varlıklarının muhafazaları veya tarihi çevre içinde korunmalarında etkinlik taşıyan korunması zorunlu olan alandır.\"","kaynak":"2863 m.3","zorluk":"kolay"},
    {"id":"2863-S-032","soru":"2863 sayılı Kanun'a göre 'çevre düzenleme projesi', her ören yerinin kendi özellikleri göz önüne alınarak ....(1)...., ....(2)...., ve ....(3).... ölçekli olarak hazırlanan düzenleme projeleridir. Boşluklara sırasıyla gelmesi gereken ölçekler hangisidir?","siklar":["1/1000 - 1/500 - 1/200","1/2000 - 1/1000 - 1/500","1/500 - 1/200 - 1/100","1/200 - 1/100 - 1/50","1/500 - 1/250 - 1/100"],"dogru":2,"aciklama":"m.3/a-(9): \"...her ören yerinin kendi özellikleri göz önüne alınarak hazırlanacak 1/500, 1/200 ve 1/100 ölçekli düzenleme projeleridir.\"","kaynak":"2863 m.3","zorluk":"zor"},
    {"id":"2863-S-033","soru":"2863 sayılı Kanun'a göre 'Etkileşim-geçiş sahası' tanımına ilişkin aşağıdaki ifadelerden hangisi Kanun metninde YER ALMAZ?","siklar":["Korunması gerekli kültür varlıklarını ve sit alanlarını doğrudan etkileyen alanlardır.","Daha önce sit sınırları içindeyken sit sınırları dışına çıkarılmış veya sit sınırları dışında tutulmuş alanları kapsayabilir.","Koruma amaçlı imar planlarının hazırlanma aşamasında gözönünde bulundurulması gerekir.","Sit bölgeleriyle bütünlük gösteren sokak, meydan, yapı grupları gibi unsurları içerebilir.","Bakanlıkça ilgili idarelerin görüşü alınarak sınırları belirlenen, sivil toplum kuruluşlarıyla eşgüdüm sağlanan alandır."],"dogru":4,"aciklama":"m.3/a-(16) etkileşim-geçiş sahasını A-D ifadeleriyle tanımlar. E şıkkındaki 'Bakanlıkça ilgili idarelerin görüşü alınarak sınırları belirlenen, sivil toplum kuruluşlarıyla eşgüdüm sağlanan alan' ifadesi ise m.3/a-(10)'daki YÖNETİM ALANI tanımına aittir.","kaynak":"2863 m.3","zorluk":"zor"},
    {"id":"2863-S-034","soru":"2863 sayılı Kanun'a göre 'yönetim alanı sınırlarında yer almamakla birlikte, arkeolojik, coğrafi, kültürel ve tarihi nedenlerle veya aynı vizyon ve tema etrafında yönetim ve gelişiminin sağlanması bakımından bu yer ile irtibatlandırılan kültürel varlıklar' hangi kavramla tanımlanmıştır?","siklar":["Bağlantı noktası","Yönetim alanı","Etkileşim-geçiş sahası","Yönetim planı","Ören yeri"],"dogru":0,"aciklama":"m.3/a-(12): \"'Bağlantı noktası'; yönetim alanı sınırlarında yer almamakla birlikte ... bu yer ile irtibatlandırılan kültürel varlıklardır.\"","kaynak":"2863 m.3","zorluk":"orta"},
    {"id":"2863-S-035","soru":"2863 sayılı Kanun'a göre ihbarı alan muhtar, aldığı tedbirlerle birlikte durumu en yakın mülki amire hangi süre içinde bildirmekle yükümlüdür?","siklar":["3 gün içinde","10 gün içinde","15 gün içinde","Aynı gün","7 gün içinde"],"dogru":3,"aciklama":"m.4/3.fıkra: \"Muhtar, aynı gün alınan tedbirlerle birlikte durumu en yakın mülki amire; mülki amir ve diğer makamlar ise on gün içinde ... bildirir.\" Muhtarın süresi AYNI GÜNdür.","kaynak":"2863 m.4","zorluk":"orta"},
    {"id":"2863-S-036","soru":"2863 sayılı Kanun'a göre 19'uncu yüzyıl sonuna kadar yapılmış bir taşınmaz, Koruma Kurullarınca mimari, tarihi, estetik, arkeolojik ve diğer önem ve özellikleri bakımından korunması gerekli bulunmadığına karar verilse dahi, salt yapım tarihi nedeniyle korunması gerekli taşınmaz kültür varlığı sayılmaya devam eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6/son fıkra: \"Ancak, Koruma Kurullarınca mimari, tarihi, estetik, arkeolojik ve diğer önem ve özellikleri bakımından korunması gerekli bulunmadığı karar altına alınan taşınmazlar, korunması gerekli taşınmaz kültür varlığı sayılmazlar.\" Koruma Kurulu kararı, tarih bendini (a) geçersiz kılabilir.","kaynak":"2863 m.6","zorluk":"orta"},
    {"id":"2863-S-037","soru":"2863 sayılı Kanun'a göre 'Mustafa Kemal Atatürk'e ait zati eşya, evrak, kitap ve yazı gibi taşınırlar' Kanunun hangi maddesi ve bendi kapsamında korunması gerekli TAŞINIR kültür varlığı sayılır?","siklar":["m.6/d","m.23/a","m.23/b","m.64/a","m.16"],"dogru":2,"aciklama":"m.23/b: \"Milli tarihimizdeki önemleri sebebiyle, Milli Mücadele ve Türkiye Cumhuriyetinin kuruluşuna ait tarihi değer taşıyan belge ve eşyalar, Mustafa Kemal ATATÜRK'e ait zati eşya, evrak, kitap, yazı ve benzeri taşınırlar.\" Bu, taşınır varlıkları düzenleyen m.23'ün b bendidir.","kaynak":"2863 m.23","zorluk":"zor"},
    {"id":"2863-S-038","soru":"2863 sayılı Kanun'a göre askeri müzelerin görev, yetki ve sorumlulukları ile çalışma düzenlerini gösteren yönetmelik hangi makam(lar)ca hazırlanır?","siklar":["Yalnızca Genelkurmay Başkanlığınca","Yalnızca Milli Savunma Bakanlığınca","Kültür ve Turizm Bakanlığının, İçişleri Bakanlığıyla birlikte","Koruma Yüksek Kurulunca","Milli Savunma Bakanlığının, Kültür ve Turizm Bakanlığıyla birlikte"],"dogru":4,"aciklama":"m.26/4.fıkra: \"Bu müzelerin görev, yetki ve sorumlulukları ile çalışma düzenleri, Milli Savunma Bakanlığının, Kültür ve Turizm Bakanlığıyla birlikte hazırlayacağı bir yönetmelikte belirtilir.\"","kaynak":"2863 m.26","zorluk":"orta"},
    {"id":"2863-S-039","soru":"2863 sayılı Kanun'a göre, Kültür ve Turizm Bakanlığının izin belgesiyle gerçek ve tüzel kişilerce kurulan müzeler, bulundurdukları taşınır kültür varlıklarının korunması hususunda Devlet müzeleri statüsündedir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.26/3.fıkra: \"Gerçek ve tüzelkişilerce kurulacak müzeler, Kültür ve Turizm Bakanlığının izin belgesinde belirlenen konu alanlarına inhisar etmek şartı ile, taşınır kültür varlığı bulundurabilir ve teşhir edebilirler. Bu müzeler de, taşınır kültür varlıklarının korunması hususunda Devlet müzeleri statüsündedirler.\"","kaynak":"2863 m.26","zorluk":"orta"},
    {"id":"2863-S-040","soru":"2863 sayılı Kanun'a göre nerede bulunursa bulunsun, haber verilen bir kültür varlığının korunması gerekli nitelikte OLMADIĞI anlaşılırsa ne uygulanır?","siklar":["Bulana yine de %40 ikramiye verilir.","Bulunan varlık doğrudan bulana iade edilip ikramiye de ödenir.","İkramiye üçte bir oranında ödenir.","Haber verenlere m.25'teki işlem uygulanır, ayrıca ikramiye verilmez.","1905 sayılı Kanun oranları uygulanır."],"dogru":3,"aciklama":"m.64/d: \"Nerede bulunursa bulunsun haber verilen kültür varlığı korunması gerekli nitelikte olmadığı takdirde haber verenlere bu Kanunun 25 inci maddesindeki işlem uygulanır. Ayrıca ikramiye verilmez.\"","kaynak":"2863 m.64","zorluk":"orta"},
    {"id":"2863-S-041","soru":"2863 sayılı Kanun'a göre 4'üncü maddede yazılı süreler içinde haber verilmediğinden dolayı gizlenmiş sayılan kültür varlıklarını haber verenler ile bunları yakalayan kamu görevlilerine, ....(1)... sayılı Kanun'da taşınır mallar için gösterilen oranlar dahilinde tespit edilen bedel ikramiye olarak verilir. Boşluğa gelmesi gereken Kanun numarası hangisidir?","siklar":["1905","2863","1319","6183","5226"],"dogru":0,"aciklama":"m.64/e: \"...1905 sayılı 'Menkul ve Gayrimenkul Emval ile Bunların İntifa Haklarının ve Daimi Vergilerin Mektumlarını Haber verenlere Verilecek İkramiyelere Dair Kanun'da taşınır mallar için gösterilen oranlar dahilinde tespit edilen bedel ikramiye olarak verilir.\"","kaynak":"2863 m.64","zorluk":"zor"},
    {"id":"2863-S-042","soru":"2863 sayılı Kanun'a göre, Kanuna aykırı olarak yıkma veya imar izni veren kişi, tahribe kasten sebebiyet verenlerle AYNI ceza aralığı olan iki yıldan beş yıla kadar hapis ve beş bin güne kadar adli para cezası ile cezalandırılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.65/2.fıkra: \"Bu Kanuna aykırı olarak yıkma veya imar izni verenler, iki yıldan beş yıla kadar hapis ve beş bin güne kadar adli para cezasıyla cezalandırılır.\" Bu ceza aralığı, aynı maddenin 1. fıkrasındaki tahrip cezasıyla birebir aynıdır.","kaynak":"2863 m.65","zorluk":"orta"},
    {"id":"2863-S-043","soru":"2863 sayılı Kanun'a göre korunması gerekli taşınmaz kültür ve tabiat varlıkları ile korunma alanlarında ruhsatsız yapılan inşaatlar ile koruma amaçlı imar planına veya sit şartlarına aykırı olarak inşa edilen yapılar hakkında ne yapılır?","siklar":["Bu Kanunun ceza hükümlerine göre doğrudan hapis cezası uygulanır, başka işlem yapılmaz.","Sadece idari para cezası kesilir, yıkım uygulanmaz.","İmar mevzuatına göre işlem yapılır.","Koruma Yüksek Kurulu doğrudan af kararı verebilir.","Yapı kendiliğinden tescilli sayılır."],"dogru":2,"aciklama":"m.16/2.cümle: \"Buralarda ruhsatsız olarak yapılacak inşaatlar ile, koruma amaçlı imar planlarında, plana; sitlerde, sit şartlarına aykırı olarak inşa edilen yapılar hakkında imar mevzuatına göre işlem yapılır.\"","kaynak":"2863 m.16","zorluk":"kolay"},
  ],
  47: [
    {"id":"3091-S-001","soru":"3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun'a göre taşınmaz mal merkez ilçe sınırları içinde ise, tecavüz veya müdahalenin önlenmesine kim karar verir?","siklar":["İlgili kaymakam","İçişleri Bakanlığı","Sulh hukuk mahkemesi","İl valisi veya görevlendireceği vali yardımcısı","İl jandarma komutanı"],"dogru":3,"aciklama":"m.2: 'taşınmaz mal merkez ilçe sınırları içinde ise, il valisi veya görevlendireceği vali yardımcısı ... tarafından bu tecavüz veya müdahalenin önlenmesine karar verilir ve taşınmaz mal yerinde zilyedine teslim edilir.'","kaynak":"3091 m.2","zorluk":"kolay"},
    {"id":"3091-S-002","soru":"3091 sayılı Kanun'a göre merkez ilçe dışındaki diğer ilçelerde taşınmaz mala tecavüz veya müdahalenin önlenmesine kim karar verir?","siklar":["Kaymakamlar","Vali yardımcısı","İlçe jandarma komutanı","İl valisi bizzat","Belediye başkanı"],"dogru":0,"aciklama":"m.2: '...diğer ilçelerde ise kaymakamlar tarafından bu tecavüz veya müdahalenin önlenmesine karar verilir...'","kaynak":"3091 m.2","zorluk":"orta"},
    {"id":"3091-S-003","soru":"3091 sayılı Kanun'a göre taşınmaz mala yapılan tecavüz veya müdahalenin önlenmesi için yetkili makamlara başvurmaya kural olarak kim yetkilidir?","siklar":["Mahalle veya köy muhtarı","İl özel idaresi","Herhangi bir vatandaş","Cumhuriyet savcısı","Taşınmaz malın zilyedi"],"dogru":4,"aciklama":"m.3: '...yetkili makamlara başvurmaya, o taşınmaz malın zilyedi, zilyed birden fazla ise içlerinden biri yetkilidir.'","kaynak":"3091 m.3","zorluk":"kolay"},
    {"id":"3091-S-004","soru":"3091 sayılı Kanun'a göre köye ait taşınmaz mallara yapılan tecavüz veya müdahalelerde, köy halkından herhangi biri de yetkili makama başvuruda bulunabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3: 'Köye ait taşınmaz mallara yapılan tecavüz veya müdahalelerde, köy halkından herhangi biri de yetkili makama başvuruda bulunabilir.'","kaynak":"3091 m.3","zorluk":"orta"},
    {"id":"3091-S-005","soru":"3091 sayılı Kanun'a göre yetkililerin, tecavüz veya müdahalenin yapıldığını öğrendikleri tarihten itibaren ....(1).... içinde idari makama başvuruda bulunmaları gerekir; ancak tecavüz veya müdahalenin oluşundan itibaren ....(2).... geçtikten sonra bu makamlara başvuruda bulunulamaz. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["otuz gün - altı ay","doksan gün - iki yıl","altmış gün - bir yıl","bir yıl - altmış gün","onbeş gün - bir yıl"],"dogru":2,"aciklama":"m.4: '...öğrendikleri tarihten altmış gün içinde, idari makama başvuruda bulunmaları gerekir. Ancak, tecavüz veya müdahalenin oluşundan itibaren bir yıl geçtikten sonra bu makamlara başvuruda bulunulamaz.'","kaynak":"3091 m.4","zorluk":"orta"},
    {"id":"3091-S-006","soru":"3091 sayılı Kanun'a göre Devletin hüküm ve tasarrufu altında bulunan veya menfaati umuma ait olan taşınmaz mallara yapılan tecavüz veya müdahalelerde de 60 günlük ve 1 yıllık başvuru süreleri aranır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4 son fıkra: 'Devletin hüküm ve tasarrufu altında bulunan yerlerle menfaati umuma ait olan taşınmaz mallara yapılan tecavüz veya müdahalelerde süre aranmaz.'","kaynak":"3091 m.4","zorluk":"kolay"},
    {"id":"3091-S-007","soru":"3091 sayılı Kanun'a göre taşınmaz mal, aynı ile bağlı ilçelerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili kaymakamlığı kim belirler?","siklar":["İçişleri Bakanlığı","Bölge idare mahkemesi","Danıştay","İlgili kaymakamların ortak kararı","Vali"],"dogru":4,"aciklama":"m.5: 'Taşınmaz mal, aynı il'e bağlı ilçelerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili kaymakamlığı vali ... belirler.'","kaynak":"3091 m.5","zorluk":"orta"},
    {"id":"3091-S-008","soru":"3091 sayılı Kanun'a göre taşınmaz mal, illerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili valiliği veya kaymakamlığı kim belirler?","siklar":["İçişleri Bakanlığı","Vali","Cumhurbaşkanlığı","Danıştay","İlgili valilerin ortak kararı"],"dogru":0,"aciklama":"m.5: '...illerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili valiliği veya kaymakamlığı İçişleri Bakanlığı belirler.'","kaynak":"3091 m.5","zorluk":"orta"},
    {"id":"3091-S-009","soru":"3091 sayılı Kanun'a göre soruşturma en geç kaç gün içinde tamamlanarak karara bağlanır?","siklar":["5 gün","15 gün","30 gün","10 gün","60 gün"],"dogru":1,"aciklama":"m.6: 'Soruşturma en geç 15 gün içinde tamamlanarak karara bağlanır.'","kaynak":"3091 m.6","zorluk":"kolay"},
    {"id":"3091-S-010","soru":"3091 sayılı Kanun'a göre bu Kanuna göre verilen kararlar hiçbir yargı denetimine tabi olmaksızın kesindir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'Bu Kanuna göre verilen kararlar idari yargı yolu açık olmak üzere kesindir.' Karar idari makamlar bakımından kesindir ama idari yargı denetimine açıktır.","kaynak":"3091 m.7","zorluk":"orta"},
    {"id":"3091-S-011","soru":"3091 sayılı Kanun'a göre mütecavize tebligat yapılamaması halinde, soruşturmanın yapılacağı veya kararın yerine getirileceği yer, tarih ve saat kaç gün önceden ilan edilir?","siklar":["3 gün","1 gün","5 gün","7 gün","15 gün"],"dogru":0,"aciklama":"m.8: 'Mütecavize tebligat yapılamaması halinde soruşturmanın yapılacağı veya kararın yerine getirileceği yer, tarih ve saat 3 gün önceden alışılmış usullerle taşınmaz malın bulunduğu köy veya beldede ilan edilir.'","kaynak":"3091 m.8","zorluk":"orta"},
    {"id":"3091-S-012","soru":"3091 sayılı Kanun'a göre karar gereğinin, kararın infaz memuruna geldiği tarihten itibaren en geç ....(1).... içinde yerine getirilmesi zorunludur. Boşluğa gelmesi gereken süre hangisidir?","siklar":["3 gün","10 gün","5 gün","15 gün","30 gün"],"dogru":2,"aciklama":"m.9: 'Karar gereğinin, kararın infaz memuruna geldiği tarihten itibaren en geç 5 gün içinde yerine getirilmesi zorunludur.'","kaynak":"3091 m.9","zorluk":"kolay"},
    {"id":"3091-S-013","soru":"3091 sayılı Kanun'a göre soruşturma ve kararın yerine getirilmesi sırasında mahallinde gerekli önlemleri alacak güvenlik kuvvetleri, kimin yazılı emriyle görevlendirilir?","siklar":["İnfaz memurunun","İl jandarma komutanının","Cumhuriyet başsavcısının","Mahallin en büyük mülki idare amirinin","Karar vermeye yetkili amirin görevlendirdiği memurun"],"dogru":3,"aciklama":"m.9: 'Mahallin en büyük mülki idare amirinin yazılı emri ile güvenlik kuvvetlerince, gerek soruşturma, gerekse kararın yerine getirilmesi sırasında mahallinde, gerekli önlemler alınır.'","kaynak":"3091 m.9","zorluk":"orta"},
    {"id":"3091-S-014","soru":"3091 sayılı Kanun'a göre tecavüz veya müdahalesi önlenen kişi, taşınmaz mal üzerinde vücuda getirdiği her türlü ekim, tesis ve değişikliklerden dolayı hangi yola başvurabilir?","siklar":["3091 sayılı Kanuna göre aynı idari makama itiraz yoluna","İdari yargıda yürütmenin durdurulması talebine","İçişleri Bakanlığına idari başvuru yoluna","Doğrudan icra takibi yoluna","Genel hükümler dairesinde yargı yoluna"],"dogru":4,"aciklama":"m.10: 'Tecavüz veya müdahalesi önlenen kişi, taşınmaz mal üzerinde vücuda getirdiği her türlü ekim, tesis ve değişikliklerden dolayı ancak genel hükümler dairesinde yargı yoluna başvurabilir.'","kaynak":"3091 m.10","zorluk":"orta"},
    {"id":"3091-S-015","soru":"3091 sayılı Kanun'a göre taşınmaz mala aynı mütecaviz tarafından ikinci defa tecavüz edilmesi halinde, tecavüz veya müdahale varsa 9 uncu madde hükümlerine göre karar uygulanır; bundan sonra her iki karara ilişkin dosyaya ne yapılır?","siklar":["Dosyalar arşivlenir, başka işlem yapılmaz","Dosyalar yalnızca il özel idaresine bildirilir","Dosyalar, 15 inci maddeye göre işlem yapılmak üzere adli mercilere gönderilir","Dosyalar İçişleri Bakanlığına gönderilerek faaliyet izni iptal edilir","Dosyalar valilikçe idari yargıya resen dava olarak açılır"],"dogru":2,"aciklama":"m.12: '...her iki kararla ilgili dosya, karar vermeye yetkili makamlarca, 15 inci maddeye göre işlem yapılmak üzere adli mercilere gönderilir.'","kaynak":"3091 m.12","zorluk":"zor"},
    {"id":"3091-S-016","soru":"3091 sayılı Kanun'a göre taşınmaz mal kamu kurum veya kuruluşlarına ait bulunuyorsa ya da Devletin hüküm ve tasarrufu altında bulunan sahipsiz veya umumun menfaatine ait yerlerdense, ikinci tecavüz veya müdahale fiilini işleyenler hakkında öngörülen temel hapis cezası hangisidir?","siklar":["Üç aydan bir yıla kadar","Altı aydan iki yıla kadar","Bir yıldan üç yıla kadar","İki yıldan dört yıla kadar","Bir aydan altı aya kadar"],"dogru":1,"aciklama":"m.15/a: 'Taşınmaz mal, kamu kurum veya kuruluşlarına ait bulunuyorsa veya Devletin hüküm ve tasarrufu altında bulunan sahipsiz veya umumun menfaatine ait yerlerden ise altı aydan iki yıla kadar ... hapis cezasına hükmolunur.'","kaynak":"3091 m.15","zorluk":"orta"},
    {"id":"3091-S-017","soru":"3091 sayılı Kanun'a göre taşınmaz mal diğer tüzelkişilere veya gerçek kişilere ait ise, ikinci tecavüz veya müdahale fiilini işleyenler hakkında öngörülen temel hapis cezası hangisidir?","siklar":["Altı aydan iki yıla kadar","Üç aydan bir yıla kadar","Bir yıldan üç yıla kadar","Bir aydan üç aya kadar","İki yıldan beş yıla kadar"],"dogru":1,"aciklama":"m.15/a: '...şayet taşınmaz mal diğer tüzelkişilere veya gerçek kişilere ait ise üç aydan bir yıla kadar hapis cezasına hükmolunur.'","kaynak":"3091 m.15","zorluk":"orta"},
    {"id":"3091-S-018","soru":"3091 sayılı Kanun'a göre tecavüz veya müdahale silahlı bir kişi veya silahsız olsalar dahi birden fazla kişi tarafından yapılırsa (a) bendindeki cezalar ....(1).... artırılır; taşınmazı paylaşmak veya ortaklaşa kullanmak amacıyla birleşenlerden en az biri silahlıysa bu artırılmış ceza ayrıca ....(2).... artırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir kat - yarı oranında","yarı oranında - bir kat","üçte bir oranında - bir kat","bir kat - üçte bir oranında","iki kat - yarı oranında"],"dogru":0,"aciklama":"m.15/b: '...cezalar bir kat artırılarak hükmolunur.' m.15/c: '...bu amaçla birleşen kişilerden en az birisinin silahlı olması halinde ise (b) bendi ile artırılan ceza ayrıca yarı oranında artırılarak hükmolunur.' Silah/çokluk artırımı bir kat; paylaşma amacıyla silahlı birleşme ayrıca yarı oranındadır.","kaynak":"3091 m.15","zorluk":"zor"},
    {"id":"3091-S-019","soru":"3091 sayılı Kanun'a göre aşağıdaki yetki eşleştirmelerinden hangisi yanlıştır?","siklar":["Merkez ilçedeki tecavüzü önleme kararı — Vali veya görevlendireceği vali yardımcısı","Diğer ilçelerdeki tecavüzü önleme kararı — Kaymakam","Aynı ile bağlı ilçelerarası sınır anlaşmazlığında yetkili kaymakamlığın belirlenmesi — Vali","İllerarası sınır anlaşmazlığında yetkili makamın belirlenmesi — İçişleri Bakanlığı","İllerarası sınır anlaşmazlığında yetkili makamın belirlenmesi — Vali"],"dogru":4,"aciklama":"m.5'e göre illerarası sınır anlaşmazlığında yetkili valiliği veya kaymakamlığı İçişleri Bakanlığı belirler, vali değil. Diğer dört eşleştirme (A, B, C, D) m.2 ve m.5'te birebir doğrudur.","kaynak":"3091 m.2, m.5","zorluk":"zor"},
    {"id":"3091-S-020","soru":"3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun'a göre, kamu idareleri, kamu kurumları, kamu kuruluşları ile tüzelkişilerin taşınmaz mallarına yapılan tecavüz veya müdahalede başvuru kim tarafından yapılır?","siklar":["İl özel idaresi genel sekreteri","Köy muhtarı","Zilyedin avukatı","Taşınmaz malın ait olduğu idare, kurum, kuruluş veya tüzelkişinin yetkilisi","Cumhuriyet savcısı"],"dogru":3,"aciklama":"m.3 fıkra 2: 'Kamu idareleri, kamu kurumları ve kamu kuruluşları ile tüzelkişilerin başvuruları, taşınmaz malın ait olduğu idare, kurum, kuruluş ve tüzelkişinin yetkilisi tarafından yapılır.'","kaynak":"3091 m.3","zorluk":"kolay"},
    {"id":"3091-S-021","soru":"3091 sayılı Kanun'a göre vali veya kaymakam, görev alanı içindeki Devletin hüküm ve tasarrufu altında bulunan sahipsiz yerlere veya menfaati umuma ait olan taşınmaz mallara tecavüz veya müdahalede bulunulduğunu öğrendiğinde, ayrıca bir başvuru şartı aranmaksızın soruşturmayı doğrudan doğruya yaptırıp sonucu karara bağlar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3 son fıkra: '...Devletin hüküm ve tasarrufu altında bulunan sahipsiz yerlere veya menfaati umuma ait olan taşınmaz mallara tecavüz veya müdahalede bulunulduğunu öğrendiklerinde, soruşturmayı doğrudan doğruya yaptırırlar ve sonucu karara bağlarlar.'","kaynak":"3091 m.3","zorluk":"orta"},
    {"id":"3091-S-022","soru":"3091 sayılı Kanun'a göre bir başvurunun bu Kanun kapsamı dışında kaldığı dilekçeden açıkça ve kesinlikle anlaşılıyorsa, yetkili makam nasıl işlem yapar?","siklar":["Başvuruyu resen mahkemeye havale eder","Soruşturmayı mutlaka yerinde yapmak zorundadır","Yerinde soruşturma yapılmadan başvuruyu yazılı olarak reddedebilir","Başvuruyu İçişleri Bakanlığına gönderir","Başvuruyu bir yıl bekletir"],"dogru":2,"aciklama":"m.5 fıkra 3: 'Bu Kanun kapsamı dışında kaldığı dilekçeden açıkça ve kesinlikle anlaşılan başvurular, yerinde soruşturma yapılmadan yazılı olarak reddedilebilir.'","kaynak":"3091 m.5","zorluk":"kolay"},
    {"id":"3091-S-023","soru":"3091 sayılı Kanun'a göre soruşturma memurunun, tarafların şahitlerini dinledikten sonra gerekli görürse dinleyebileceği kişiler arasında aşağıdakilerden hangisi YOKTUR?","siklar":["Tarafsız kişiler","Hazine temsilcisi","Belediye temsilcisi","Köy muhtarı ve ihtiyar kurulu üyeleri","Bilirkişi heyeti raportörü"],"dogru":4,"aciklama":"m.6 fıkra 1: 'Soruşturma memuru, tarafların şahitlerini dinledikten sonra gerekli gördüğü takdirde tarafsız kişileri ve ilgisine göre hazine, özel idare ve belediye temsilcilerini, köy muhtar ve ihtiyar kurulu üyelerini de dinleyebilir.' Bilirkişi heyeti raportörü madde metninde sayılmamıştır.","kaynak":"3091 m.6","zorluk":"zor"},
    {"id":"3091-S-024","soru":"3091 sayılı Kanun'a göre kararlardaki açık yazı ve hesap hataları, ancak idari yargı yoluna başvurularak düzeltilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'Ancak, açık olan yazı ve hesap hataları karar veren yetkili makamca kendiliğinden düzeltilir.' İdari yargıya başvurmaya gerek yoktur.","kaynak":"3091 m.7","zorluk":"orta"},
    {"id":"3091-S-025","soru":"3091 sayılı Kanun'a göre soruşturma yapılması ve kararın yerine getirilmesi sırasında taşınmaz malın başında bulunması zorunlu olan kişi aşağıdakilerden hangisidir?","siklar":["Şikâyetçi, varsa kanuni vekili veya dilekçesinde belirttiği temsilcisi (köy başvurusunda muhtar veya ihtiyar meclisi üyelerinden biri)","Yalnızca mütecaviz","Yalnızca infaz memuru","İl valisi bizzat","Cumhuriyet savcısı"],"dogru":0,"aciklama":"m.8 fıkra 1: 'Şikayetçinin, varsa kanuni vekilinin veya dilekçesinde ismini belirttiği temsilcisinin; başvuru, 3 üncü maddenin üçüncü fıkrasına göre yapılmış ise köy muhtarı veya ihtiyar meclisi üyelerinden birinin; soruşturma yapılması ve kararın yerine getirilmesi sırasında taşınmaz malın başında bulunması zorunludur.'","kaynak":"3091 m.8","zorluk":"kolay"},
    {"id":"3091-S-026","soru":"3091 sayılı Kanun'a göre mütecaviz, ilan edilen yer, tarih ve saatte gelmezse soruşturma ve kararın yerine getirilmesi ....(1).... yapılır; yetkili makamların, talebin esastan veya süreden reddine ilişkin karar ve işlemleri ise ....(2).... sayılı Kanun hükümlerine göre ilgililere duyurulur. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["ertelenerek - 3091","durdurularak - 6100","yokluğunda - 7201","yokluğunda - 5271","iptal edilerek - 2577"],"dogru":2,"aciklama":"m.8: 'Mütecaviz gelmezse soruşturma ve kararın yerine getirilmesi yokluğunda yapılır... karar ve işlemleri, 7201 sayılı Tebligat Kanunu hükümlerine göre ilgililere duyurulur.'","kaynak":"3091 m.8","zorluk":"zor"},
    {"id":"3091-S-027","soru":"3091 sayılı Kanun'a göre karar vermeye yetkili makam gerekli gördüğü durumlarda infaz memuruna teknik yönden yardımcı olmak üzere ne yapar?","siklar":["Davayı mahkemeye havale eder","İnfazı iptal eder","Soruşturma süresini 15 güne çıkarır","Güvenlik kuvvetlerini devre dışı bırakır","Yeteri kadar memur görevlendirir"],"dogru":4,"aciklama":"m.9 fıkra 3: 'Karar vermeye yetkili makamın gerekli göreceği durumlarda, infaz memuruna teknik yönden yardımcı olmak üzere yeteri kadar memur görevlendirilir.'","kaynak":"3091 m.9","zorluk":"orta"},
    {"id":"3091-S-028","soru":"3091 sayılı Kanun'un 12 nci maddesine göre, aynı mütecavizin taşınmaza ikinci defa tecavüz etmesi dışında, hangi durumda da birinci başvurudaki gibi yeniden soruşturma yapılıp karara bağlanır?","siklar":["Mütecavizin yakını bilmeden aynı yere tecavüz ederse","Onun (ilk mütecavizin) yararına başkaları tarafından bilerek ilk defa tecavüz veya müdahale edilirse","Taşınmaz mal üçüncü bir kişiye satılırsa","Zilyet değişirse","Tecavüz farklı bir taşınmaza yapılırsa"],"dogru":1,"aciklama":"m.12: '...aynı mütecaviz tarafından ikinci defa veya onun yararına başkaları tarafından bilerek ilk defa tecavüz veya müdahalelerle ilgili başvurularda da birinci başvuruda olduğu gibi soruşturma yapılır ve sonucu karara bağlanır.'","kaynak":"3091 m.12","zorluk":"zor"},
    {"id":"3091-S-029","soru":"3091 sayılı Kanun'un 15 inci maddesindeki cezaların uygulanabilmesi için aranan temel ön koşul aşağıdakilerden hangisidir?","siklar":["Tecavüzün ilk defa yapılmış olması","Taşınmazın mahkeme kararıyla mütecavize teslim edilmiş olması","Tecavüzün silahlı bir kişi tarafından yapılmış olması","Fiilin, mahkeme kararıyla kendisine teslim edilmeksizin aynı taşınmaz mala ikinci defa yapılmış olması","Taşınmazın kamu kurumuna ait olması"],"dogru":3,"aciklama":"m.15: 'Mahkeme kararıyla kendisine teslim edilmeksizin aynı taşınmaz mala ikinci defa yapılan tecavüz veya müdahale... bu suçu işleyenler hakkında...' cezalar uygulanır.","kaynak":"3091 m.15","zorluk":"zor"},
    {"id":"3091-S-030","soru":"3091 sayılı Kanun'a göre, ikinci tecavüz fiili daha ağır bir cezayı gerektiren ayrı bir suç teşkil ediyorsa dahi, 15 inci maddedeki cezalar mutlaka uygulanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.15: '...fiil daha ağır bir cezayı gerektiren ayrı bir suç teşkil etmediği takdirde, bu suçu işleyenler hakkında...' hükmü uygulanır. Yani fiil daha ağır cezalı ayrı bir suç oluşturuyorsa 15 inci madde değil, o suçun cezası uygulanır.","kaynak":"3091 m.15","zorluk":"orta"},
  ],
  48: [
    {"id":"4207-S-001","soru":"4207 sayılı Tütün Ürünlerinin Zararlarının Önlenmesi ve Kontrolü Hakkında Kanun'a göre, özel hukuk kişilerine ait olan ve birden çok kişinin girebileceği binaların kapalı alanlarında tütün ürünü tüketimi yasaktır. Aşağıdakilerden hangisi bu yasağın kapsamı dışında bırakılmıştır?","siklar":["Ticaret amaçlı özel binaların kapalı alanları","Spor amaçlı özel binaların kapalı alanları","Eğlence amaçlı özel binaların kapalı alanları","İkamete mahsus konutlar","Kültürel amaçlı özel binaların kapalı alanları"],"dogru":3,"aciklama":"m.2/1-b: '...birden çok kişinin girebileceği (ikamete mahsus konutlar hariç) binaların kapalı alanlarında... tüketilemez.' İkamete mahsus konutlar açıkça hariç tutulmuştur.","kaynak":"4207 m.2/1-b","zorluk":"kolay"},
    {"id":"4207-S-002","soru":"4207 sayılı Kanun'a göre aşağıdaki yerlerden hangisinde tütün ürünü tüketimi Kanunen yasaklanmamıştır?","siklar":["Kamu hizmet binalarının kapalı alanları","Taksi hizmeti veren araçlar","Bireysel kullanım amaçlı, başkasının girmediği ikamete mahsus konutlar","Okul öncesi eğitim kurumlarının açık alanları","Kahvehane, kafeterya gibi eğlence hizmeti verilen işletmeler"],"dogru":2,"aciklama":"m.2/1-b istisnası: '(ikamete mahsus konutlar hariç)'. Diğer dört şık m.2/1'de birebir sayılan yasak yerlerdir (a, c, ç, d bentleri).","kaynak":"4207 m.2/1","zorluk":"orta"},
    {"id":"4207-S-003","soru":"4207 sayılı Kanun'a göre, hususi (özel) araçlarda tütün ürünü tüketim yasağı yalnızca sürücü koltuğuyla sınırlıdır; toplu taşıma araçlarında ise bu yasak aracın tamamını kapsar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.2/1-c: 'Hususi araçların sürücü koltukları ile taksi hizmeti verenler dâhil olmak üzere karayolu, demiryolu, denizyolu ve havayolu toplu taşıma araçlarında... tüketilemez.' Yasak, hususi araçta yalnız sürücü koltuğuna, toplu taşıma araçlarında ise aracın bütününe uygulanır.","kaynak":"4207 m.2/1-c","zorluk":"zor"},
    {"id":"4207-S-004","soru":"4207 sayılı Kanun'a göre okul öncesi eğitim kurumlarının, dershanelerin, ilk ve orta öğrenim kurumlarının, kültür ve sosyal hizmet binalarının ....(1).... alanlarında tütün ürünleri tüketilemez. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["yalnızca kapalı","kapalı ve açık","yalnızca açık","bahçe hariç kapalı","giriş kapısı hariç kapalı ve açık"],"dogru":1,"aciklama":"m.2/1-ç: '...kültür ve sosyal hizmet binalarının kapalı ve açık alanlarında... tüketilemez.' Diğer yerlerden farklı olarak okul/kültür kurumlarında yasak hem kapalı hem açık alanı kapsar.","kaynak":"4207 m.2/1-ç","zorluk":"orta"},
    {"id":"4207-S-005","soru":"4207 sayılı Kanun'a göre aşağıdaki yerlerden hangisinde tütün ürünleri tüketilmesine mahsus alanlar oluşturulabilir?","siklar":["İlk ve orta öğretim kurumlarının açık alanlarında","Kamu hizmet binalarının kapalı alanlarında","Toplu taşıma araçlarında","Lokanta ve kahvehanelerde","Ruh ve sinir hastalıkları hastanelerinde"],"dogru":4,"aciklama":"m.2/2-a: 'Yaşlı bakım evlerinde, ruh ve sinir hastalıkları hastanelerinde, cezaevlerinde... tütün ürünleri tüketilmesine mahsus alanlar oluşturulabilir.'","kaynak":"4207 m.2/2","zorluk":"kolay"},
    {"id":"4207-S-006","soru":"4207 sayılı Kanun'a göre yaşlı bakım evleri, ruh ve sinir hastalıkları hastaneleri ve cezaevlerinde oluşturulan tütün tüketim alanlarına kimler giremez?","siklar":["Onsekiz yaşını doldurmamış kişiler","Sağlık raporu olmayan kişiler","Yirmi bir yaşını doldurmamış kişiler","Kurum personeli dışındaki herkes","Sadece hastalar"],"dogru":0,"aciklama":"m.2/2 son cümle: 'Bu alanlara onsekiz yaşını doldurmamış kişiler giremez.'","kaynak":"4207 m.2/2","zorluk":"orta"},
    {"id":"4207-S-007","soru":"4207 sayılı Kanun'a göre, otelcilik hizmeti verilen işletmelerde oluşturulan tütün tüketimine tahsis edilmiş odalara da onsekiz yaşını doldurmamış kişiler giremez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. 'Bu alanlara onsekiz yaşını doldurmamış kişiler giremez' cümlesi m.2/2'de sayılan alanlara (bakımevi, ruh-sinir hastanesi, cezaevi, gemi güvertesi) bağlıdır. Otel odaları ayrı bir fıkra olan m.2/3'te düzenlenmiştir ve bu fıkrada 18 yaş girişini yasaklayan ayrı bir hüküm yer almaz.","kaynak":"4207 m.2/3","zorluk":"zor"},
    {"id":"4207-S-008","soru":"4207 sayılı Kanun'a göre açık havada yapılan spor, kültür, sanat ve eğlence faaliyetlerinin yapıldığı yerler ve seyir yerleri hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Bu yerlerde tütün ürünü kullanımı hiçbir şekilde ve istisnasız yasaktır","Bu yerlerde tütün ürünü kullanımı tamamen serbesttir","Genel kural olarak kullanılamaz, ancak bu tesislerde tüketime mahsus alanlar oluşturulabilir","Yalnızca seyir yerlerinde serbesttir","Yalnızca sporcular için serbesttir"],"dogru":2,"aciklama":"m.2/4: 'Açık havada yapılan her türlü spor, kültür, sanat ve eğlence faaliyetlerinin yapıldığı yerler ile bunların seyir yerlerinde tütün ürünleri kullanılamaz. Ancak bu tesislerde, tütün ürünlerinin tüketilmesine mahsus alanlar oluşturulabilir.'","kaynak":"4207 m.2/4","zorluk":"orta"},
    {"id":"4207-S-009","soru":"4207 sayılı Kanun'a göre 'tütün ürünü' ibaresi, ....(1)...., ....(2)...., ....(3)...., ya da ....(4).... kullanılmak üzere üretilmiş, hammaddesi tamamen veya kısmen tütün yaprağından imal edilmiş maddeyi ifade eder. Boşluklara sırasıyla gelmesi gereken dört kullanım biçimi hangisidir?","siklar":["yakma - kaynatma - ezme - koklama","tüttürme - içme - yutma - koklama","yakma - emme - çiğneme - yutma","tüttürme - emme - çiğneme - buruna çekme","tüttürme - kaynatma - çiğneme - koklama"],"dogru":3,"aciklama":"m.2/6: '\"tütün ürünü\" ibaresi tüttürme, emme, çiğneme ya da buruna çekerek kullanılmak üzere üretilmiş... maddeyi ifade eder.'","kaynak":"4207 m.2/6","zorluk":"orta"},
    {"id":"4207-S-010","soru":"4207 sayılı Kanun'a göre tütün içermeyen ancak tütün mamulünü taklit eder tarzda kullanılan her türlü nargile ve sigara da tütün ürünü kabul edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.2/6: 'Tütün içermeyen ancak tütün mamulünü taklit eder tarzda kullanılan her türlü nargile ve sigara, tütün ürünü kabul edilir.'","kaynak":"4207 m.2/6","zorluk":"kolay"},
    {"id":"4207-S-011","soru":"4207 sayılı Kanun'a göre tütün ürünlerinin ve üretici firmaların isim, marka veya alametleri kullanılarak reklam ve tanıtım yapılması hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Sadece televizyon reklamı yasaktır, basılı reklam serbesttir","Her ne suretle olursa olsun reklam ve tanıtım yapılamaz","Yalnızca yurt dışına yönelik reklamlar yasaktır","Firma izniyle sınırlı reklam yapılabilir","Yalnızca 18 yaş altına yönelik reklamlar yasaktır"],"dogru":1,"aciklama":"m.3/1: 'Tütün ürünlerinin ve üretici firmaların isim, marka veya alâmetleri kullanılarak her ne suretle olursa olsun reklam ve tanıtımı yapılamaz.'","kaynak":"4207 m.3/1","zorluk":"kolay"},
    {"id":"4207-S-012","soru":"4207 sayılı Kanun'a göre aşağıdakilerden hangisi Kanun'da tütün ürünleriyle ilgili açıkça yasaklanan fiillerden biri değildir?","siklar":["Tütün firması isim/markasının kıyafet, takı ve aksesuar olarak taşınması","Tütün ürünlerinin bayilere veya tüketicilere hediye, promosyon olarak dağıtılması","Televizyon programlarında, filmlerde tütün ürünü görüntülerine yer verilmesi","Firmanın adının ve amblemlerinin bir spor etkinliğine destek olarak kullanılması","Firma çalışanlarının kendi tükettiği tütün ürününü işyeri dışında özel olarak taşıması"],"dogru":4,"aciklama":"A (m.3/2), B (m.3/4), C (m.3/6), D (m.3/1) Kanun'da açıkça sayılan yasak fiillerdir. Bir bireyin kendi tükettiği ürünü özel hayatında taşıması Kanun'un düzenlediği bir yasak fiil değildir.","kaynak":"4207 m.3/1-2-4-6","zorluk":"zor"},
    {"id":"4207-S-013","soru":"4207 sayılı Kanun'a göre onsekiz yaşını doldurmamış kişiler hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Yalnızca tütün ürünü satışında istihdam edilemezler, pazarlamada çalışabilirler","Ebeveyn izniyle tütün ürünü işletmelerinde çalıştırılabilirler","Tütün ürünü işletmelerinde, pazarlanmasında ve satışında istihdam edilemezler","Yalnızca üretim tesislerinde çalıştırılamazlar","16 yaşını dolduranlar sınırlı sürelerle çalıştırılabilir"],"dogru":2,"aciklama":"m.3/9: 'Onsekiz yaşını doldurmamış kişiler, tütün ürünü işletmelerinde, pazarlanmasında ve satışında istihdam edilemez.'","kaynak":"4207 m.3/9","zorluk":"orta"},
    {"id":"4207-S-014","soru":"4207 sayılı Kanun'a göre tütün ürünleri onsekiz yaşını doldurmamış kişilere ....(1)...., bu kişiler tütün ürünü işletmelerinde ....(2)...., ve tütün ürünleri bu kişilerin doğrudan ulaşacağı şekilde ....(3).... Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["satılamaz ve tüketimlerine sunulamaz - istihdam edilemez - satışa arz edilemez","satılabilir - istihdam edilebilir - satışa arz edilebilir","yalnızca satılamaz - çalıştırılabilir - arz edilebilir","satılamaz - istihdam edilebilir - arz edilemez","satılamaz ve sunulamaz - istihdam edilemez - serbestçe arz edilebilir"],"dogru":0,"aciklama":"m.3/8: '...onsekiz yaşını doldurmamış kişilere satılamaz ve tüketimlerine sunulamaz.' m.3/9: '...istihdam edilemez.' m.3/13: '...onsekiz yaşını doldurmamış kişilerin doğrudan ulaşacağı ve işletme dışından görülecek şekilde satışa arz edilemez.'","kaynak":"4207 m.3/8-9-13","zorluk":"orta"},
    {"id":"4207-S-015","soru":"4207 sayılı Kanun'a göre tütün ürünlerinin satışı hangi hizmetlerin verildiği yerlerde ve yerleşkelerinde yasaktır?","siklar":["Yalnızca sağlık hizmeti verilen yerlerde","Ticaret ve sanayi hizmeti verilen yerlerde","Ulaşım hizmeti verilen yerlerde","Sağlık, eğitim-öğretim, kültür ve spor hizmeti verilen yerlerde","Yalnızca kamu hizmet binalarında"],"dogru":3,"aciklama":"m.3/7: 'Sağlık, eğitim ve öğretim, kültür ve spor hizmeti verilen yerlerde ve bunların yerleşkelerinde tütün ürünlerinin satışı yapılamaz.'","kaynak":"4207 m.3/7","zorluk":"kolay"},
    {"id":"4207-S-016","soru":"4207 sayılı Kanun'a göre aşağıdakilerden hangisi tütün ürünleri için yasaklanan bir satış biçimi değildir?","siklar":["Paket açılarak adet şeklinde satış","Ruhsatlı bir işyerinde kapalı orijinal paket halinde satış","Otomatik makinelerle satış","Televizyon veya internet gibi elektronik ortamlarla satış","Satış amacıyla kargo yoluyla taşıma"],"dogru":1,"aciklama":"m.3/10: 'Tütün ürünleri, paket açılarak adet şeklinde veya daha küçük paketlere bölünerek satılamaz.' m.3/11: '...otomatik makinelerle, telefon, televizyon ve internet gibi elektronik ortamlarla satılamaz ve satış amacıyla kargo yoluyla taşınamaz.' Ruhsatlı işyerinde kapalı orijinal paket satışı Kanun'un öngördüğü olağan/yasal satış biçimidir.","kaynak":"4207 m.3/10-11","zorluk":"orta"},
    {"id":"4207-S-017","soru":"4207 sayılı Kanun'a göre tütün ürünleri hangi şartla satışa sunulamaz?","siklar":["Yalnızca kamuya açık alanlarda satışa sunulamaz","Yalnızca kırsal bölgelerde satışa sunulamaz","Yalnızca yaz aylarında satışa sunulamaz","Yalnızca büyükşehirlerde satışa sunulamaz","Satış belgesi olmaksızın ve belgede belirtilen yerin dışında satışa sunulamaz"],"dogru":4,"aciklama":"m.3/13: 'Tütün ürünleri satış belgesi olmaksızın ve satış belgesinde belirtilen yerin dışında satışa sunulamaz.' Ayrıca aynı fıkra 18 yaşını doldurmamış kişilerin doğrudan ulaşacağı ve işletme dışından görülecek şekilde arzını da yasaklar.","kaynak":"4207 m.3/13","zorluk":"orta"},
    {"id":"4207-S-018","soru":"4207 sayılı Kanun'a göre Türkiye'de üretilen veya ithal edilen tütün ürünleri paketlerinin en geniş iki yüzünün her birine, bu yüzlerin alanlarının yüzde ....(1).... 'inden az olmamak üzere uyarı konulur; markanın yazımı ise paketin sadece bir yüzeyinin yüzde ....(2)....'ini aşamaz. Boşluklara sırasıyla gelmesi gereken oranlar hangisidir?","siklar":["yetmişinden - onunu","altmışbeşinden - onbeşini","seksen beşinden - beşini","doksanından - beşini","yüzünden - beşini"],"dogru":2,"aciklama":"m.4/3: '...bu yüzlerin alanlarının yüzde seksen beşinden az olmamak üzere... uyarılar... konulur' ve 'Marka, paketin sadece bir yüzeyine ve bu yüzeyin yüzde beşini aşmayacak şekilde yazılır.' (Not: oran, 7151/2018 ile 'yüzde altmışbeşi'nden 'yüzde seksen beşi'ne yükseltilmiştir; güncel oran %85'tir.)","kaynak":"4207 m.4/3","zorluk":"kolay"},
    {"id":"4207-S-019","soru":"4207 sayılı Kanun'a göre Türkiye'de üretilen veya ithal edilen tütün ürünleri paketleri hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Marka, yazım şekli, rengi ve diğer unsurlarıyla aynı şekilde tasarlanmış düz ve standart paket biçiminde piyasaya arz edilir; paket üzerine markanın logosu konulamaz","Her firma kendi özgün paket tasarımını serbestçe kullanabilir","Yalnızca ihraç edilen ürünlerde düz paket zorunludur","Logo kullanımı serbest, yalnızca renk sınırlıdır","Düz paket zorunluluğu yalnızca sigara için geçerlidir, diğer tütün ürünleri için geçerli değildir"],"dogru":0,"aciklama":"m.4/3: '...tütün ürünleri; markanın yazım şekli, yazı karakteri ve boyutu, paket üzerindeki konumu, paketlerin rengi, diğer yazı, ibare ve şekiller dâhil olmak üzere aynı şekilde tasarlanmış düz ve standart paket biçiminde piyasaya arz edilir... Paketlerin üzerine markanın logosu, simgesi veya sair işaretleri konulamaz.'","kaynak":"4207 m.4/3","zorluk":"orta"},
    {"id":"4207-S-020","soru":"4207 sayılı Kanun'a göre tütün sektöründe faaliyet gösteren firmalar istenildiği takdirde her türlü bilgiyi ....(1).... içinde Sağlık Bakanlığına ve ilgili Kuruma vermek zorundadır; radyo-televizyon kuruluşları ise ayda en az ....(2).... tütün ürünlerinin zararları konusunda uyarıcı yayın yapmak zorundadır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["bir ay - altmış dakika","onbeş gün - altmış dakika","bir ay - doksan dakika","onbeş gün - doksan dakika","otuz gün - yüzyirmi dakika"],"dogru":3,"aciklama":"m.4/6: '...istenildiği takdirde onbeş gün içerisinde Sağlık Bakanlığına ve Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumuna vermek zorundadır.' m.4/7: '...ayda en az doksan dakika... uyarıcı, eğitici mahiyette yayınlar yapmak zorundadır.'","kaynak":"4207 m.4/6-7","zorluk":"zor"},
    {"id":"4207-S-021","soru":"4207 sayılı Kanun'a göre radyo ve televizyon kuruluşlarının yapmak zorunda olduğu ayda en az doksan dakikalık uyarıcı yayının asgari otuz dakikası hangi saatler arasında yapılmalıdır?","siklar":["06:00-08:00","17:00-22:00","22:00-24:00","12:00-17:00","08:00-12:00"],"dogru":1,"aciklama":"m.4/7: 'Bu yayınlar, asgari otuz dakikası 17:00-22:00 saatleri arasında olmak üzere 08:00-22:00 saatleri arasında yapılır.'","kaynak":"4207 m.4/7","zorluk":"orta"},
    {"id":"4207-S-022","soru":"4207 sayılı Kanun'a göre tütün sektöründe faaliyet gösteren firmalar, istenildiği takdirde ürün, üretim ve pazarlama bilgilerini onbeş gün içinde hangi makam/makamlara vermek zorundadır?","siklar":["Yalnızca Ticaret Bakanlığına","Yalnızca Radyo ve Televizyon Üst Kuruluna","Yalnızca Tarım ve Orman Bakanlığına","Yalnızca il valiliğine","Sağlık Bakanlığına ve Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumuna"],"dogru":4,"aciklama":"m.4/6: '...onbeş gün içerisinde Sağlık Bakanlığına ve Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumuna vermek zorundadır.'","kaynak":"4207 m.4/6","zorluk":"zor"},
    {"id":"4207-S-023","soru":"4207 sayılı Kanun'a göre, tütün ürünleri tüketilmesine tahsis edilen kapalı alanların fiziki şartları hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Bu alanların ayrı bir girişi bulunması zorunludur","Bu alanların en az 10 metrekare olması zorunludur","Bu alanların koku ve duman geçişini önleyecek şekilde tecrit edilmesi ve havalandırma tertibatı ile donatılması gerekir","Bu alanlarda sigara içimi yalnızca belirli saatlerde serbesttir","Bu alanların kamera ile izlenmesi zorunludur"],"dogru":2,"aciklama":"m.2/5: 'Bu Kanunun tütün ürünleri tüketilmesine tahsis edilen kapalı alanlarının koku ve duman geçişini önleyecek şekilde tecrit edilmesi ve havalandırma tertibatı ile donatılması gerekir.'","kaynak":"4207 m.2/5","zorluk":"orta"},
    {"id":"4207-S-024","soru":"4207 sayılı Kanun'a göre, tütün ürünleri sektöründe faaliyet gösteren firmalara ait araçlarda bu ürünlere ilişkin markaların tanınmasını sağlayacak bir uygulamaya gidilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3/3: 'Tütün ürünleri sektöründe faaliyet gösteren firmalara ait araçlarda bu ürünlere ilişkin markaların tanınmasını sağlayacak bir uygulamaya gidilemez.'","kaynak":"4207 m.3/3","zorluk":"orta"},
    {"id":"4207-S-025","soru":"4207 sayılı Kanun'a göre, her ne amaçla olursa olsun tütün ürünlerinin isim, logo veya amblemleri kullanılarak ....(1)...., basın-yayın organlarına ....(2).... Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bildirim yapılabilir - ilan verilebilir","yalnız bildirim yapılamaz - ilan verilebilir","bildirim yapılabilir - yalnız ilan verilemez","bildirim yapılamaz - ilan verilemez","bildirim yapılamaz - yalnız broşür dağıtılabilir"],"dogru":3,"aciklama":"m.3/5: 'Her ne amaçla olursa olsun, tütün ürünlerinin isim, logo veya amblemleri kullanılarak bildirim yapılamaz, basın-yayın organlarına ilân verilemez.'","kaynak":"4207 m.3/5","zorluk":"orta"},
    {"id":"4207-S-026","soru":"4207 sayılı Kanun'a göre tütün ürünleriyle ilgili izmarit, paket, ağızlık, kağıt ve benzeri atıklar hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Belediye çöp kutularına atılabilir","Çevreye atılamaz","Yalnızca halka açık alanlarda atılamaz, özel alanlarda serbesttir","Yakılarak imha edilmesi zorunludur","Yalnızca sigara izmariti için yasak, diğer atıklar serbesttir"],"dogru":1,"aciklama":"m.3/12: 'Tütün ürünleriyle ilgili izmarit, paket, ağızlık, kağıt ve benzeri atıklar çevreye atılamaz.'","kaynak":"4207 m.3/12","zorluk":"kolay"},
    {"id":"4207-S-027","soru":"4207 sayılı Kanun'a göre aşağıdaki ürün gruplarından hangisinin, tütün ürünlerine benzeyecek veya markasını çağrıştıracak şekilde üretilmesi, dağıtılması ve satılması Kanun'da açıkça SAYILMAMIŞTIR?","siklar":["Sakız","Şeker","Çerez","Oyuncak","Kırtasiye malzemesi"],"dogru":4,"aciklama":"m.3/14: 'Her türlü sakız, şeker, çerez, oyuncak, kıyafet, takı, aksesuar ve benzeri ürünler tütün ürünlerine benzeyecek veya markasını çağrıştıracak şekilde üretilemez, dağıtılamaz ve satılamaz.' Kırtasiye malzemesi bu sayımda yer almaz.","kaynak":"4207 m.3/14","zorluk":"orta"},
    {"id":"4207-S-028","soru":"4207 sayılı Kanun'a göre, tütün ürünleri harici mal ve hizmet sektörlerindeki firma veya ürünlerle tütün ürünlerinin ilişkilendirilmesini önleyen hükmün uygulanmasına ilişkin usul ve esasları hangi kurum belirler?","siklar":["Sağlık Bakanlığının uygun görüşü alınarak Tütün ve Alkol Piyasası Düzenleme Kurumu","Sağlık Bakanlığının uygun görüşü alınarak Tarım ve Orman Bakanlığı","Radyo ve Televizyon Üst Kurulu","Ticaret Bakanlığı","Millî Eğitim Bakanlığı"],"dogru":0,"aciklama":"m.3/15 son cümle: 'Bu fıkranın uygulanmasına ilişkin usul ve esaslar Sağlık Bakanlığının uygun görüşü alınarak Tütün ve Alkol Piyasası Düzenleme Kurumu tarafından belirlenir.'","kaynak":"4207 m.3/15","zorluk":"zor"},
    {"id":"4207-S-029","soru":"4207 sayılı Kanun'a göre tütün ürünlerinin içilmesinin yasaklandığı yerlerde asılacak uyarılar, salonlarda asgari ....(1)...., toplu taşıma araçlarında ise ....(2).... puntolarla herkes tarafından görülebilir yerlere asılır. Boşluklara sırasıyla gelmesi gereken puntolar hangisidir?","siklar":["beş santimetrelik - bir santimetrelik","yirmi santimetrelik - beş santimetrelik","on beş santimetrelik - beş santimetrelik","on santimetrelik - üç santimetrelik","üç santimetrelik - on santimetrelik"],"dogru":3,"aciklama":"m.4/1: '...salonlarda asgari on santimetrelik puntolarla, toplu taşım araçlarında üç santimetrelik puntolarla herkes tarafından görülebilir yerlere asılır.'","kaynak":"4207 m.4/1","zorluk":"orta"},
    {"id":"4207-S-030","soru":"4207 sayılı Kanun'a göre tütün ürünlerinin satışının serbest olduğu yerlere asılması gereken yasal uyarı ibaresi hakkında aşağıdakilerden hangisi doğrudur?","siklar":["\"Sigara sağlığa zararlıdır\" ibaresi, Sağlık Bakanlığınca belirlenir","İbarenin asılması işletmenin isteğine bağlıdır","\"18 yaşını doldurmayanlara sigara ve diğer tütün ürünleri satılamaz; satanlar hakkında yasal işlem yapılır\" ibaresi, Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumunca belirlenen usullere uygun olarak asılır","İbare yalnızca büyük marketlerde asılır, küçük bakkallarda zorunlu değildir","\"21 yaşını doldurmayanlara satılamaz\" ibaresi asılır"],"dogru":2,"aciklama":"m.4/2: '...Tütün ürünlerinin satışının serbest olduğu yerlere \"Yasal Uyarı: 18 yaşını doldurmayanlara sigara ve diğer tütün ürünleri satılamaz; satanlar hakkında yasal işlem yapılır.\" ibaresi Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumunca belirlenen usullere uygun olarak yazılarak... asılır.'","kaynak":"4207 m.4/2","zorluk":"kolay"},
    {"id":"4207-S-031","soru":"4207 sayılı Kanun'a göre, ithal edilen veya Türkiye'de üretilen tütün ürünlerinin paketlerinde ve etiketlerinde, uyarı yazısı bulunması koşuluyla, tüketimi özendiren, teşvik eden veya tüketiciyi yanıltan ya da ürünü cazip kılan metin, isim, marka, ibare, mecaz, resim, figür, işaret veya renkler kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/4: '...bu ürünlerin özellikleri, sağlığa etkileri, tehlikeleri veya emisyonları ile ilgili yanıltıcı ve eksik bilgi verilemez; tüketimi özendiren, teşvik eden veya tüketiciyi yanıltan ya da ürünü cazip kılan metin, isim, marka, ibare, mecaz, resim, figür, işaret veya renkler ve renk kombinasyonları kullanılamaz.' Bu yasak, uyarı yazısının varlığına bağlı bir istisna içermez; mutlaktır.","kaynak":"4207 m.4/4","zorluk":"zor"},
    {"id":"4207-S-032","soru":"4207 sayılı Kanun'a göre, tek tip olarak tasarlanmış düz ve standart paketler ile ilgili hususlar hangi kurum tarafından hazırlanan yönetmelikle düzenlenir?","siklar":["Sağlık Bakanlığının uygun görüşü alınarak Tarım ve Orman Bakanlığı","Tütün ve Alkol Piyasası Düzenleme Kurumu tek başına","Radyo ve Televizyon Üst Kurulu","Sağlık Bakanlığı tek başına","Ticaret Bakanlığının uygun görüşü alınarak Sağlık Bakanlığı"],"dogru":0,"aciklama":"m.4/5: '...düz ve standart paketler ile ilgili hususlar Sağlık Bakanlığının uygun görüşü alınarak Tarım ve Orman Bakanlığı tarafından hazırlanan yönetmelikle düzenlenir.'","kaynak":"4207 m.4/5","zorluk":"zor"},
    {"id":"4207-S-033","soru":"4207 sayılı Kanun'a göre, radyo-televizyon kuruluşlarının tütün zararları konusunda yapmakla yükümlü olduğu uyarıcı yayın sürecine ilişkin aşağıdaki ifadelerden hangisi Kanun hükümlerine uygun DEĞİLDİR?","siklar":["Bu süreler Radyo ve Televizyon Üst Kurulu tarafından denetlenir","Bu programlar Sağlık Bakanlığı, Millî Eğitim Bakanlığı, Radyo ve Televizyon Üst Kurulu, ilgili Kurum, bilimsel kuruluşlar ve sivil toplum örgütleri tarafından hazırlanır veya hazırlattırılır","Bu saatler dışında yapılan yayınlar aylık doksan dakikalık süreye dahil edilmez","Programların hazırlanmasında yalnızca özel televizyon kuruluşları yetkilidir, kamu kurumlarının programa katkısı aranmaz","Hazırlanan programlar, Sağlık Bakanlığının olumlu görüşü alındıktan sonra Radyo ve Televizyon Üst Kurulu tarafından yayınlanması sağlanır"],"dogru":3,"aciklama":"m.4/7: 'Bu süreler, Radyo ve Televizyon Üst Kurulu tarafından denetlenir. Bu programlar, Sağlık Bakanlığı, Millî Eğitim Bakanlığı, Radyo ve Televizyon Üst Kurulu, Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumu, bilimsel kuruluşlar ve sivil toplum örgütleri tarafından hazırlanır veya hazırlattırılır. Hazırlanan programlar, Sağlık Bakanlığının olumlu görüşü alındıktan sonra Radyo ve Televizyon Üst Kurulu tarafından yayınlanması sağlanır.' Programların hazırlanmasının yalnızca özel televizyon kuruluşlarına ait olduğu ve kamu kurumu katkısının aranmadığı iddiası metne aykırıdır.","kaynak":"4207 m.4/7","zorluk":"zor"},
    {"id":"4207-S-034","soru":"4207 sayılı Kanun'a göre, tütün ürünleri tüketiminin ve tütün dumanına maruz kalmanın oluşturduğu sağlık riskleri konusunda çocukları ve gençleri bilinçlendirmek üzere, ilgili kuruluşlar ve sivil toplum örgütlerinin görüşleri alınarak ....(1).... tarafından bir müfredat hazırlanır. Boşluğa gelmesi gereken kurum hangisidir?","siklar":["Sağlık Bakanlığı","Aile ve Sosyal Hizmetler Bakanlığı","Millî Eğitim Bakanlığı","Radyo ve Televizyon Üst Kurulu","Tütün ve Alkol Piyasası Düzenleme Kurumu"],"dogru":2,"aciklama":"m.4/8: '...çocukları ve gençleri bilinçlendirmek üzere ilgili kuruluşlar ve sivil toplum örgütlerinin görüşleri alınarak Millî Eğitim Bakanlığı tarafından bir müfredat hazırlanır.'","kaynak":"4207 m.4/8","zorluk":"kolay"},
    {"id":"4207-S-035","soru":"4207 sayılı Kanun'a göre, tütün ürünleri alışkanlığının bırakılmasını özendirici programlar ve tütün bağımlılığının ilaç ile tedavisinin ulaşılabilir olması için gerekli çalışmalar Millî Eğitim Bakanlığı tarafından yapılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/9: '...gerekli çalışmalar Sağlık Bakanlığı tarafından yapılır.' Millî Eğitim Bakanlığı ise m.4/8'de düzenlenen bilinçlendirme müfredatından sorumludur; iki görev farklı kurumlara aittir.","kaynak":"4207 m.4/9","zorluk":"orta"},
    {"id":"4207-S-036","soru":"4207 sayılı Kanun'a göre, 193 sayılı Gelir Vergisi Kanunu'nun ilgili maddesinde belirtilen ilan ve reklam giderleri hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Gelir ve kurumlar vergisi matrahının tespitinde gider olarak gösterilebilir","Yalnızca kurumlar vergisi matrahından indirilebilir","Yalnızca gelir vergisi matrahından indirilebilir","Sadece yurt dışı reklam giderleri için geçerlidir","Gelir ve kurumlar vergisi matrahının tespitinde gider olarak gösterilemez"],"dogru":4,"aciklama":"m.4/11: '31/12/1960 tarihli ve 193 sayılı Gelir Vergisi Kanununun 41 inci maddesinin birinci fıkrasının (7) numaralı bendinde belirtilen ilan ve reklam giderleri gelir ve kurumlar vergisi matrahının tespitinde gider olarak gösterilemez.'","kaynak":"4207 m.4/11","zorluk":"zor"},
  ],
  49: [
    {"id":"4733-S-001","soru":"4733 sayılı Tütün, Tütün Mamulleri ve Alkol Piyasasının Düzenlenmesine Dair Kanun'a göre, Bakanlıktan tesis kurma ve faaliyet izni almadan tütün mamulleri üretmek üzere fabrika, tesis veya imalathane kuran ve işleten kişi hakkında öngörülen ceza aşağıdakilerden hangisidir?","siklar":["Altı aydan iki yıla kadar hapis cezası","Üç aydan bir yıla kadar hapis veya adlî para cezası","Bir yıldan üç yıla kadar hapis ve beşbin günden onbin güne kadar adlî para cezası","Elli bin TL'den ikiyüzelli bin TL'ye kadar idari para cezası","İki yıldan beş yıla kadar hapis cezası"],"dogru":2,"aciklama":"m.8/1: '...fabrika, tesis veya imalathane kuran ve işletenler bir yıldan üç yıla kadar hapis ve beşbin günden onbin güne kadar adlî para cezası ile cezalandırılır.' Aynı ceza, m.6/2-3'e aykırı davrananlara ve izin verilen kategori dışında faaliyette bulunanlara da uygulanır.","kaynak":"4733 m.8/1","zorluk":"kolay"},
    {"id":"4733-S-002","soru":"4733 sayılı Kanun'a göre, ticari amaç olmaksızın kendi ürettiği ürünleri kullanarak şahsi tüketimi için 60 kilogram sarmalık kıyılmış tütün elde eden kişi, kanunda öngörülen izinsiz tesis kurma suçundan sorumlu tutulmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8/1 istisnası yalnızca 'elli kilogramı aşmayan sarmalık kıyılmış tütün' için geçerlidir. 60 kilogram bu 50 kg sınırını aştığından istisna kapsamı dışında kalır; fiil izinsiz üretim/tesis kapsamında değerlendirilir.","kaynak":"4733 m.8/1","zorluk":"orta"},
    {"id":"4733-S-003","soru":"4733 sayılı Kanun'a göre, tütün, tütün mamulleri, etil alkol, metanol ve alkollü içkiler piyasasında Bakanlıktan gerekli izinleri alarak veya almadan mal veya hizmet üreten, işleyen, ihraç veya ithal eden, pazarlayan, alan veya satan kişiler hakkında ne uygulanır?","siklar":["Yalnızca izinsiz faaliyette bulunanlara idari yaptırım uygulanır","Yalnızca izinli olup kurallara aykırı davrananlara idari yaptırım uygulanır","Yalnızca gerçek kişilere idari yaptırım uygulanır, tüzel kişilere uygulanmaz","İzin alsın almasın, madde 8/5'te sayılan idari yaptırımlar piyasada mal/hizmet üreten, işleyen, ihraç/ithal eden, pazarlayan, alan veya satan gerçek ve tüzel kişilere uygulanır","Yalnızca ihraç ve ithal edenlere idari yaptırım uygulanır"],"dogru":3,"aciklama":"m.8/5: '...Bakanlığından gerekli izinleri alarak veya almadan mal veya hizmet üreten, işleyen, ihraç veya ithal eden, pazarlayan, alan veya satan gerçek ve tüzel kişilere aşağıda yazılı idarî yaptırımlar uygulanır.' İzinli olmak yaptırımdan muaf kılmaz.","kaynak":"4733 m.8/5","zorluk":"kolay"},
    {"id":"4733-S-004","soru":"4733 sayılı Kanun'a göre, ticari amaçla sarmalık kıyılmış tütün üretenler ile satan veya satışa arz edenlere, tütünün miktarına göre idari para cezası uygulanır: 50 kilograma kadar (50 kg dâhil) ....(1)...., 50 kilogramdan 100 kilograma kadar (100 kg dâhil) ....(2)...., 500 kilogramdan fazla olması halinde ise ....(3).... idari para cezası verilir. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["500 TL - 1.000 TL - 3.000 TL","100 TL - 250 TL - 1.500 TL","500 TL - 1.500 TL - 5.000 TL","1.000 TL - 2.000 TL - 4.000 TL","250 TL - 500 TL - 5.000 TL"],"dogru":4,"aciklama":"m.8/5-(o): 50 kg'a kadar (dâhil) 250 TL; 50-100 kg (dâhil) 500 TL; 100-250 kg (dâhil) 1.500 TL; 250-500 kg (dâhil) 3.000 TL; 500 kg'dan fazla 5.000 TL idari para cezası verilir.","kaynak":"4733 m.8/5-(o)","zorluk":"orta"},
    {"id":"4733-S-005","soru":"4733 sayılı Kanun'a göre, idari para cezalarının fiillerin tekrarı halinde uygulanacak miktarı ile beşinci fıkranın (c) bendindeki fiilin tekrarında ayrıca uygulanabilecek tedbir aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["Bir önceki cezanın iki katı; ürünün piyasaya arzının bir yıla kadar durdurulmasına karar verilebilir","Bir önceki cezanın iki katı; ürünün piyasaya arzı üç yıla kadar durdurulabilir","Bir önceki cezanın üç katı; faaliyet izni derhal iptal edilir","Bir önceki cezanın yarısı; ürünün piyasaya arzı süresiz durdurulur","Sabit ek ceza (10.000 TL); tesis kapatılır"],"dogru":0,"aciklama":"'İdarî para cezaları, fiillerin tekrarı halinde, bir önceki cezanın iki katı olarak verilir. Beşinci fıkranın (c) bendinde sayılan fiillerin tekrarı halinde ayrıca ihlale konu ürünün piyasaya arzının bir yıla kadar durdurulmasına... karar verilir.'","kaynak":"4733 m.8 (tekrar fıkrası)","zorluk":"orta"},
    {"id":"4733-S-006","soru":"4733 sayılı Kanun'a göre, (a), (b), (d), (e), (f), (j), (k), (l), (m), (n), (o), (p), (r) ve (s) bentlerinde sayılan fiillerin, ilk fiilin işlenmesinden sonraki beş yıl içinde üçüncü defa işlenmesi halinde uygulanacak yaptırım ve bundan sonra geçerli olan yasak süresi hangisidir?","siklar":["Faaliyet izni askıya alınır; bir yıl yeni belge başvurusu yapılamaz","Belgelerin iptaline karar verilir; iptalden sonra iki yıl süreyle yeni belge başvurusunda bulunulamaz","Tesis kapatılır; üç yıl süreyle yeni belge başvurusunda bulunulamaz","Belgelerin iptaline karar verilir; iptalden sonra beş yıl süreyle yeni belge başvurusunda bulunulamaz","Sadece idari para cezası iki katına çıkarılır; başka bir yaptırım uygulanmaz"],"dogru":1,"aciklama":"'...beş yıl içinde üçüncü defa işlenmesi halinde ise belgelerin iptaline karar verilir... bu işletme üzerine kayıtlı görünen üçüncü kişiler adına iki yıl süreyle yeni belge başvurusunda bulunulamaz.'","kaynak":"4733 m.8 (tekrar fıkrası)","zorluk":"zor"},
    {"id":"4733-S-007","soru":"4733 sayılı Kanun'a göre, beşinci fıkranın (f), (g), (h), (ı), (j), (n), (o), (p), (r) ve (s) bentlerinde yazılı fiiller hakkında idarî yaptırım uygulama ve ilgili eşyanın mülkiyetinin kamuya geçirilmesi kararını verme yetkisi mahalli mülkî amirlere aittir. Aşağıdaki bentlerden hangisi bu listede SAYILMAMIŞTIR (dolayısıyla bu fiil hakkında Bakanlık yetkilidir)?","siklar":["(g) bendi","(ı) bendi","(k) bendi","(n) bendi","(o) bendi"],"dogru":2,"aciklama":"m.8/9: 'Beşinci fıkranın (f), (g), (h), (ı), (j), (n), (o), (p), (r) ve (s) bentlerinde yazılı fiiller hakkında idarî yaptırım uygulamaya... mahalli mülkî amirler... yetkilidir.' (k) bendi (elektronik ticaret/internet satışı) bu listede yer almaz; dolayısıyla Bakanlık yetkilidir.","kaynak":"4733 m.8/9","zorluk":"orta"},
    {"id":"4733-S-008","soru":"4733 sayılı Kanun'a göre, mahalli mülkî amirlerce uygulanan idari yaptırımlar otuz gün içinde Bakanlığa iletilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8/9: 'Mahalli mülkî amirlerce uygulanan idarî yaptırımlar onbeş gün içinde Gıda, Tarım ve Hayvancılık Bakanlığına iletilir.' Süre otuz gün değil onbeş gündür.","kaynak":"4733 m.8/9","zorluk":"kolay"},
    {"id":"4733-S-009","soru":"4733 sayılı Kanun'a göre verilen idari yaptırım kararlarına itiraz ve bu itirazın etkisi hakkında hangisi doğrudur?","siklar":["Sulh ceza mahkemesinde 7 gün içinde dava açılır; dava açılması yürütmeyi durdurur","İdare mahkemesinde 30 gün içinde dava açılır; dava açılması yürütmeyi durdurur","Asliye ceza mahkemesinde 15 gün içinde dava açılır; dava açılması yürütmeyi durdurmaz","İdare mahkemesinde, işlemin tebliği tarihinden itibaren 15 gün içinde dava açılır; dava açılması kararın yerine getirilmesini durdurmaz","İdare mahkemesinde 15 gün içinde dava açılır; dava açılması kararın yerine getirilmesini durdurur"],"dogru":3,"aciklama":"'...idare mahkemesinde dava, işlemin tebliği tarihinden itibaren onbeş gün içinde açılır. İdare mahkemesinde iptal davası açılmış olması, kararın yerine getirilmesini durdurmaz.'","kaynak":"4733 m.8 (itiraz fıkrası)","zorluk":"orta"},
    {"id":"4733-S-010","soru":"4733 sayılı Kanun'a göre, bu Kanuna, 4250 sayılı Kanuna, 213 sayılı Kanunun 359 uncu maddesinin (d) fıkrasına veya 5607 sayılı Kanunun 3 üncü maddesinde belirtilen fıkralara aykırı fiillerden dolayı haklarında kesinleşmiş mahkûmiyet kararı bulunanlara verilmiş belgeleri hangi makam iptal eder?","siklar":["İçişleri Bakanlığı","Mahalli mülkî amir","İdare mahkemesi","Ticaret Bakanlığı","Tarım ve Orman Bakanlığı"],"dogru":4,"aciklama":"'...bu Kanun kapsamında yürütülen faaliyetlere ilişkin hiçbir belge verilmez, verilmiş olanlar Tarım ve Orman Bakanlığınca iptal edilir.'","kaynak":"4733 m.8 (mahkûmiyet fıkrası)","zorluk":"orta"},
    {"id":"4733-S-011","soru":"4733 sayılı Kanun'a göre, soruşturma veya kovuşturma başlatılması nedeniyle askıya alınan bir belgeye ilişkin askı işlemi hangi durumda kesinleşme beklenmeksizin kaldırılır?","siklar":["Kovuşturmaya yer olmadığına dair kararın kesinleşmesi veya mahkûmiyet dışında bir hüküm ya da hükmün açıklanmasının geri bırakılmasına karar verilmesi halinde","Sanığın adli para cezası ödemesi halinde","Yalnızca altı aylık değerlendirme süresi dolduğunda otomatik olarak","Sanığın belgeyi başka bir işletmeye devretmesi halinde","Yalnızca üst mahkemede beraat kararı kesinleştiğinde"],"dogru":0,"aciklama":"'...kovuşturmaya yer olmadığına dair kararın kesinleşmesi üzerine ya da mahkûmiyet dışında bir hüküm veya hükmün açıklanmasının geri bırakılmasına karar verilmesi halinde kesinleşmesi beklenmeksizin Bakanlık tarafından askıya alma işlemi ortadan kaldırılır.'","kaynak":"4733 m.8 (mahkûmiyet fıkrası)","zorluk":"zor"},
    {"id":"4733-S-012","soru":"4733 sayılı Kanun'a göre, tütün mamulleri veya alkollü içkilerin internet, televizyon, faks, telefon gibi elektronik ticaret araçları ya da posta ile sipariş yöntemiyle satışı için sistem kuran veya faaliyette bulunanlara verilecek idari para cezası ile satışın internet ortamında yapılması halinde uygulanacak ek tedbir aşağıdakilerden hangisidir?","siklar":["5.000 TL'den 50.000 TL'ye kadar idari para cezası; işyeri kapatılır","20.000 TL'den 100.000 TL'ye kadar idari para cezası; 5651 sayılı Kanun uyarınca internet erişimi engellenir","50.000 TL'den 250.000 TL'ye kadar idari para cezası; mülkiyet kamuya geçirilir","1.000 TL'den 10.000 TL'ye kadar idari para cezası; kimlik kartı iptal edilir","200.000 TL sabit idari para cezası; faaliyet izni askıya alınır"],"dogru":1,"aciklama":"'...satış sistemi kuran veya faaliyette bulunanlara yirmibin Yeni Türk Lirasından yüzbin Yeni Türk Lirasına kadar idarî para cezası verilir... Satışın internet ortamında yapılması halinde... 5651 sayılı Kanunda öngörülen usullere göre erişimin engellenmesine karar verilir.'","kaynak":"4733 m.8/5-(k)","zorluk":"kolay"},
    {"id":"4733-S-013","soru":"4733 sayılı Kanun'a göre, Bakanlıktan satış belgesi almadan tütün mamulleri, makaron, yaprak sigara kâğıdı, etil alkol, metanol ve alkollü içkilerin toptan satışını yapanlara ....(1)...., perakende satışını yapanlara ise ....(2).... idari para cezası verilir. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["10.000 TL'den 50.000 TL'ye kadar - 1.000 TL'den 10.000 TL'ye kadar","20.000 TL'den 100.000 TL'ye kadar - 5.000 TL sabit","50.000 TL sabit - 5.000 TL sabit","5.000 TL sabit - 50.000 TL sabit","50.000 TL'den 500.000 TL'ye kadar - 50.000 TL sabit"],"dogru":2,"aciklama":"'...toptan satışını yapanlara ellibin Yeni Türk Lirası; perakende satışını yapanlara ise beşbin Yeni Türk Lirası idarî para cezası verilir.' İkisi de SABİT tutardır, aralıklı değildir.","kaynak":"4733 m.8/5-(g)","zorluk":"orta"},
    {"id":"4733-S-014","soru":"4733 sayılı Kanun'a göre, Bakanlıktan belge almamış kişilerden ürün alan veya bu kişilere ürün satan ya da belgesinde belirtilen işyeri dışında satış yapan toptan veya perakende satıcılara verilecek idari para cezası ve bu cezayı vermeye yetkili makam aşağıdakilerden hangisidir?","siklar":["50.000 TL sabit idari para cezası; Bakanlık yetkilidir","5.000 TL sabit idari para cezası; mahalli mülkî amir yetkilidir","10.000 TL'den 50.000 TL'ye kadar idari para cezası; mahalli mülkî amir yetkilidir","1.000 TL'den 10.000 TL'ye kadar idari para cezası; mahalli mülkî amir yetkilidir","20.000 TL'den 100.000 TL'ye kadar idari para cezası; Bakanlık yetkilidir"],"dogru":3,"aciklama":"m.8/5-(f): '...bin Yeni Türk Lirasından onbin Yeni Türk Lirasına kadar idarî para cezası verilir.' (f) bendi, m.8/9'daki mülki amir yetkisindeki bentler listesinde yer alır.","kaynak":"4733 m.8/5-(f)","zorluk":"orta"},
    {"id":"4733-S-015","soru":"4733 sayılı Kanun'a göre aşağıdaki idari para cezası tutarlarından hangisi ilgili bentle DOĞRU eşleştirilmemiştir?","siklar":["(e) bendi — izin/bildirim olmadan dökme alkollü içkiyi piyasaya arz etme: 200.000 TL sabit","(ı) bendi — uygunluk belgesiz enfiye/nargile tütünü/makaron üretimi veya satışı: 5.000 TL sabit","(l) ve (m) bentleri — raf-teşhir düzenlemesine aykırılık ve reklam/tanıtım ihlali: 30.000 TL sabit","(p) bendi — amacı dışında veya teknik düzenlemesine aykırı etil alkol bulundurma/satma: 20.000 TL'den 100.000 TL'ye kadar","(c) bendi — izinsiz ana girdi veya ürün ambalajında değişiklik yaparak piyasaya arz etme: 5.000 TL'den 50.000 TL'ye kadar"],"dogru":4,"aciklama":"m.8/5-(c): '...ellibin Yeni Türk Lirasından beşyüzbin Yeni Türk Lirasına kadar idarî para cezası verilir.' Doğru tutar 50.000-500.000 TL'dir; E şıkkındaki '5.000-50.000 TL' yanlış eşleştirmedir.","kaynak":"4733 m.8/5 (diğer bentler)","zorluk":"zor"},
    {"id":"4733-S-016","soru":"4733 sayılı Kanun'a göre, tütün mamullerinin/alkollü içkilerin internet üzerinden satışına ilişkin (k) bendindeki idari yaptırımı uygulamaya hangi makam yetkilidir?","siklar":["Gıda, Tarım ve Hayvancılık Bakanlığı","Mahalli mülkî amir","İçişleri Bakanlığı","Bilgi Teknolojileri ve İletişim Kurumu","İdare mahkemesi"],"dogru":0,"aciklama":"m.8/9 yetki fıkrasında sayılan mülki amir bentleri (f, g, h, ı, j, n, o, p, r, s) arasında (k) yer almaz. Bu nedenle (k) bendi 'diğer bentler' kapsamında kalır ve bu fiil hakkında idarî para cezası vermeye Bakanlık yetkilidir.","kaynak":"4733 m.8/9","zorluk":"zor"},
    {"id":"4733-S-017","soru":"4733 sayılı Kanun'a göre, izinsiz olarak tesis kurup işletmek adlî bir suç iken, piyasadaki diğer ihlaller (satış belgesi olmadan satış, uygunsuz reklam vb.) idari yaptırım kapsamındadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8/1 izinsiz tesis kurma fiilini hapis + adlî para cezasıyla SUÇ olarak düzenlerken, m.8/5 aynı piyasadaki diğer ihlalleri (satış belgesi, reklam, tescil vb.) idari yaptırım (idari para cezası vb.) olarak düzenler.","kaynak":"4733 m.8 (bütün)","zorluk":"kolay"},
    {"id":"4733-S-018","soru":"4733 sayılı Kanun'a göre, bu Kanuna göre idari para cezalarının veya idari yaptırımların uygulanmasının diğer ceza ve tedbirlere etkisi ile Kanunda hüküm bulunmayan idari yaptırım hallerinde uygulanacak genel kanun hakkında hangisi doğrudur?","siklar":["İdari yaptırım uygulanması, Kanunun diğer hükümlerinin ve diğer kanunlardaki ceza ve tedbirlerin uygulanmasını engeller; hüküm bulunmayan hallerde 5237 sayılı TCK uygulanır","İdari yaptırım uygulanması diğer ceza ve tedbirlerin uygulanmasına engel teşkil etmez; hüküm bulunmayan hallerde 5326 sayılı Kabahatler Kanunu uygulanır","İdari yaptırım uygulanması diğer ceza ve tedbirlerin uygulanmasına engel değildir; hüküm bulunmayan hallerde 2577 sayılı İdari Yargılama Usulü Kanunu uygulanır","İdari yaptırım uygulanması yalnızca adlî cezaların uygulanmasını engeller; hüküm bulunmayan hallerde 5607 sayılı Kanun uygulanır","İdari yaptırım uygulanması tüm diğer yaptırımları geçersiz kılar; hüküm bulunmayan hallerde ilgili yönetmelik uygulanır"],"dogru":1,"aciklama":"'Bu Kanuna göre idari para cezalarının veya idari yaptırımların uygulanması, bu Kanunun diğer hükümlerinin ve diğer kanunlarda yer alan ceza ve tedbirlerin uygulanmasına engel teşkil etmez.' Ayrıca: 'İdarî yaptırımlara ilişkin olarak bu Kanunda hüküm bulunmayan hallerde 30/3/2005 tarihli ve 5326 sayılı Kabahatler Kanunu hükümleri uygulanır.'","kaynak":"4733 m.8 (son fıkralar)","zorluk":"orta"},
    {"id":"4733-S-019","soru":"4733 sayılı Tütün, Tütün Mamulleri ve Alkol Piyasasının Düzenlenmesine Dair Kanun'a göre, Bakanlık tarafından istenilen ticari faaliyet raporlarını veya bilgi, belge ve numuneleri yazılı uyarıya rağmen süresinde vermeyenlere, yanlış veya yanıltıcı bilgi veya belge verenlere ya da tesis ve yerlerini incelemeye açmayanlara verilecek idari para cezası aralığı nedir?","siklar":["5.000 TL sabit idari para cezası","10.000 TL'den 50.000 TL'ye kadar idari para cezası","20.000 TL'den 100.000 TL'ye kadar idari para cezası","50.000 TL'den 500.000 TL'ye kadar idari para cezası","50.000 TL'den ikiyüzellibin TL'ye kadar idari para cezası"],"dogru":4,"aciklama":"m.8/5-(a): '...yazılı uyarıya rağmen belirlenen süre içinde vermeyenlere, yanlış veya yanıltıcı bilgi veya belge verenlere, gerekli tesis ve yerleri incelemeye açmayanlara ellibin Yeni Türk Lirasından ikiyüzellibin Yeni Türk Lirasına kadar idarî para cezası verilir.'","kaynak":"4733 m.8/5-(a)","zorluk":"orta"},
    {"id":"4733-S-020","soru":"4733 sayılı Kanun'a göre, üreticiden satın aldıkları tütünleri satış merkezlerine veya Bakanlığa tescil ettirmeyenlere, yazılı sözleşme yapma tarihine uymayanlara, işleme açılış-kapanışları ile tütün stoklarını süresi içinde bildirmeyenlere ....(1).... TL'den ....(2).... TL'ye kadar idari para cezası verilir; bu hüküm izinsiz olarak bir yere mahsus tütün çeşidinin tohum veya fidelerini başka çeşitlere ayrılmış yerlere eken, diken veya bu amaçla taşıyanlar hakkında da uygulanır. Boşluklara sırasıyla gelmesi gereken tutarlar hangisidir?","siklar":["onbin TL'den ellibin TL'ye kadar (10.000-50.000 TL)","ellibin TL'den ikiyüzellibin TL'ye kadar (50.000-250.000 TL)","bin TL'den onbin TL'ye kadar (1.000-10.000 TL)","yirmibin TL'den yüzbin TL'ye kadar (20.000-100.000 TL)","ellibin TL'den beşyüzbin TL'ye kadar (50.000-500.000 TL)"],"dogru":0,"aciklama":"m.8/5-(b): '...onbin Yeni Türk Lirasından ellibin Yeni Türk Lirasına kadar idarî para cezası verilir. Bu hüküm Gıda, Tarım ve Hayvancılık Bakanlığından izin almadan bir yere mahsus tütün çeşidinin tohum veya fidelerini başka çeşitlere ayrılmış olan yerlere ekenler, dikenler veya bu amaçlarla taşıyanlar hakkında da uygulanır.'","kaynak":"4733 m.8/5-(b)","zorluk":"zor"},
    {"id":"4733-S-021","soru":"4733 sayılı Kanun'a göre, Bakanlıktan izin almaksızın işleme veya üretim tesislerinde proje tadilatı kapsamındaki işlemleri yapan, kurulu makinelerini yurt içinde başka bir fabrikaya nakleden, başka bir firmaya devreden ya da yurt dışına çıkaran veya bildirimde bulunmaksızın faaliyetini sona erdirenlere verilecek idari para cezası aralığı nedir?","siklar":["10.000 TL'den 50.000 TL'ye kadar idari para cezası","50.000 TL'den 500.000 TL'ye kadar idari para cezası","50.000 TL'den 250.000 TL'ye kadar idari para cezası","20.000 TL'den 100.000 TL'ye kadar idari para cezası","5.000 TL'den 50.000 TL'ye kadar idari para cezası"],"dogru":1,"aciklama":"m.8/5-(d): '...ellibin Yeni Türk Lirasından beşyüzbin Yeni Türk Lirasına kadar idarî para cezası verilir.'","kaynak":"4733 m.8/5-(d)","zorluk":"orta"},
    {"id":"4733-S-022","soru":"4733 sayılı Kanun'a göre, tütün mamullerini otomatik satış makinesi ile satanlara veya bahis oynatmak ya da ödül vermek gibi yollarla verenlere (fiil suç oluşturmadığı takdirde) ellibin TL'den ikiyüzellibin TL'ye kadar idari para cezası verilir. Bu fiile konu makineler hakkında mülkiyetin kamuya geçirilmesine hangi durumda ayrıca karar verilir?","siklar":["Her durumda, ayrıca bir şart aranmaksızın otomatik olarak","Yalnızca fiilin beş yıl içinde üçüncü kez tekrarında","Yalnızca fiil (o) bendindeki sarmalık tütün ihlaliyle birlikte işlenmişse","Eyleme konu makineler hakkında müsadere kararı verilmemiş ise","Mülkiyetin kamuya geçirilmesi bu bent için hiçbir şekilde uygulanmaz"],"dogru":3,"aciklama":"m.8/5-(n) (Ek cümle: 28/10/2020-7255/13): 'Eyleme konu makineler hakkında müsadere kararı verilmemiş ise ayrıca mülkiyetin kamuya geçirilmesine karar verilir.'","kaynak":"4733 m.8/5-(n)","zorluk":"zor"},
    {"id":"4733-S-023","soru":"4733 sayılı Kanun'a göre, Kanunun 6 ncı maddesinin onikinci fıkrasına aykırı hareket edenlere, kullanılması zorunlu miktar ile fiili kullanım miktarı arasındaki farkın oranı arttıkça, kullanılmayan her kilogram için uygulanan idari para cezası da artar (oran yüzde on ve altında 8 TL, yüzde otuz ve altında 10 TL, yüzde otuzun üzerinde 12 TL).","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8/5-(ö): '...oranının; 1) Yüzde on ve altında olması halinde... sekiz Türk Lirası, 2) Yüzde otuz ve altında olması halinde... on Türk Lirası, 3) Yüzde otuzun üzerinde olması halinde... Oniki Türk Lirası idari para cezası uygulanır.' Oran dilimi büyüdükçe kilogram başına ceza da kademeli olarak artar (8→10→12 TL).","kaynak":"4733 m.8/5-(ö)","zorluk":"kolay"},
    {"id":"4733-S-024","soru":"4733 sayılı Kanun'a göre, makaron ve sigara üretim tesislerinde Bakanlığa bildirimde bulunmadan ve zorunlu özel etiket/işaretleme yapılmadan makine çalışma testi, ürün denemesi veya deneme üretimi yapanlara ya da bu şekilde üretilen makaron ve sigaraları süresi içinde imha etmeyenlere verilecek idari para cezası nasıl hesaplanır?","siklar":["Sabit onbin TL, üretim miktarından bağımsız","Üretilen her bir adet başına bir TL, ancak onbin TL'den az olmamak üzere","Üretilen her bir adet başına on TL, üst sınır yok","Kilogram başına 8, 10 veya 12 TL arasında kademeli","Ellibin TL'den ikiyüzellibin TL'ye kadar sabit aralık"],"dogru":1,"aciklama":"m.8/5-(r) ve (s): '...onbin Türk lirasından az olmamak üzere, üretilen her bir adet başına bir Türk lirası idari para cezası verilir.' Her iki bent de (test üretiminde etiketsizlik ve üretilenlerin imha edilmemesi) aynı hesaplama yöntemini kullanır.","kaynak":"4733 m.8/5-(r) ve (s)","zorluk":"orta"},
    {"id":"4733-S-025","soru":"4733 sayılı Kanun'un 8 inci maddesinde zaman içinde geçirdiği değişiklikler dikkate alındığında, aşağıdakilerden hangisi maddeden YÜRÜRLÜKTEN KALDIRILMIŞ veya ÇIKARILMIŞ bir unsur DEĞİLDİR?","siklar":["Maddenin ikinci, üçüncü ve dördüncü fıkraları (6455/2013 ile mülga)","Beşinci fıkranın (h) bendi (7061/2017 ile mülga)","(f) bendinde yer alan \"veya alkollü içkilerin\" ibaresi (6487/2013 ile çıkarılmış)","Beşinci fıkra giriş cümlesindeki \"izinsiz olarak veya Kurum düzenlemelerine aykırılık oluşturacak şekilde\" ibaresi (6111/2011 ile çıkarılmış)","Beşinci fıkranın (r) ve (s) bentleri"],"dogru":4,"aciklama":"(r) ve (s) bentleri 30/11/2022 tarihli ve 7423 sayılı Kanunla maddeye SONRADAN EKLENMİŞTİR; herhangi bir mülga veya çıkarma işlemine konu değildir. A, B, C, D ise gerçekten yürürlükten kaldırılmış veya metinden çıkarılmış unsurlardır.","kaynak":"4733 m.8 (mülga/değişiklik tarihçesi)","zorluk":"zor"},
    {"id":"4733-S-026","soru":"4733 sayılı Kanun'a göre (Ek fıkra: 28/3/2013-6455/31), Bakanlığın piyasa faaliyetlerine ilişkin olarak açılan kamu davaları karşısındaki yetkisi aşağıdakilerden hangisidir?","siklar":["Bakanlık davalara yalnızca bilirkişi sıfatıyla katılabilir","Bakanlığın kamu davalarıyla hiçbir ilgisi yoktur, yalnızca idare mahkemesinde taraf olabilir","Bakanlık kamu davalarını katılan sıfatıyla takip edebilir; ayrıca suç duyurusunda bulunabilir ve adli/mülki makamlardan yaptırım talebinde bulunabilir","Bakanlık yalnızca savcılığa yazılı bilgi verebilir, dava sürecine hiçbir şekilde katılamaz","Bakanlık yalnızca tüzel kişiler hakkında açılan davalara katılabilir, gerçek kişiler hakkında açılanlara katılamaz"],"dogru":2,"aciklama":"'Gıda, Tarım ve Hayvancılık Bakanlığı piyasa faaliyetlerine ilişkin olarak... gerçek ve tüzel kişiler ile bunların yetkilileri hakkında açılan kamu davalarını katılan sıfatıyla takip edebilir. Bu konularla ilgili olarak suç duyurusunda bulunabileceği gibi mevzuatın uygulanması açısından, adli ve mülki makamlardan yaptırım talebinde bulunabilir.'","kaynak":"4733 m.8 (ek fıkra - kamu davası takibi)","zorluk":"orta"},
  ],
  50: [
    {"id":"YON26-S-001","soru":"Kimlik Bildirme Kanununun Uygulanması ile İlgili Yönetmeliğe göre, eşlerin yerleşim yerinin ayrı olması halinde 'aile reisi' kim sayılır?","siklar":["Ayrı ayrı eşlerin her biri kendi yerleşim yerinde aile reisi sayılır","Yalnızca erkek eş aile reisi sayılır","Aile fertlerinden yaşça en büyük olan eş aile reisi sayılır","En yakın yetkili genel kolluk örgütü aile reisini belirler","Yerleşim yeri ayrı olsa da yalnızca kadın eş aile reisi sayılır"],"dogru":0,"aciklama":"m.3/a: 'Aile reisi: Eşlerden biri, eşlerin yerleşim yerinin ayrı olması halinde ayrı ayrı eşleri ya da aynı konutu paylaşan aile fertlerinden yaşça en büyük olanı ... ifade eder.' Yerleşim yeri ayrıysa her eş kendi yerinde aile reisi sayılır.","kaynak":"KBY m.3","zorluk":"orta"},
    {"id":"YON26-S-002","soru":"Yönetmeliğe göre 'en yakın yetkili genel kolluk örgütü' tanımı aşağıdakilerden hangisidir?","siklar":["İlin en büyük mülki amirinin bağlı olduğu valilik","Tesis, iş yeri veya konutun bulunduğu yerin sürekli olarak genel güvenliğini sağlayan polis veya jandarma karakolu","Türkiye genelinde kimlik bildirimlerini toplayan merkezi bir kolluk birimi","Konutun bulunduğu ildeki il emniyet müdürlüğü merkez birimi","Bölgedeki jandarma komutanlığının il merkezindeki karargâhı"],"dogru":1,"aciklama":"m.3/b: 'En yakın yetkili genel kolluk örgütü: Tesis, iş yeri veya konutun bulunduğu yerin sürekli olarak genel güvenliğini sağlayan polis veya jandarma karakollarını ... ifade eder.'","kaynak":"KBY m.3","zorluk":"kolay"},
    {"id":"YON26-S-003","soru":"Yönetmeliğin 3 üncü maddesinde (Değişik: RG-17/6/2022-31869) tanımlanan 'günübirlik kiralanan ev' kavramı için aşağıdakilerden hangisi doğrudur?","siklar":["Otel, motel veya pansiyon gibi temel konaklama işletmesi ya da sosyal tesis statüsünde bulunan, saatlik kiralanan yerlerdir","Yalnızca köy ve kasabalarda kurulan geçici konaklama çadırlarıdır","Konut olarak kullanılmak yerine fiilen iş yeri gibi işletilen, temel/yardımcı konaklama işletmesi veya sosyal tesis statüsünde bulunmayan, kısa süreli (saatlik, günlük, haftalık vb.) konaklama hizmeti sunulan ve Ulusal Adres Veri Tabanında adresi veya aboneliği bulunmayan yerlerdir","Sorumlu işleticisi bulunmayan, denetimsiz bırakılan konaklama tesisleridir","Yalnızca yabancı uyruklu kişilere kiralanabilen mülklerdir"],"dogru":2,"aciklama":"m.3/c: 'Günübirlik kiralanan ev: Konut olarak kullanılmak ya da konut olarak kullanılmak üzere kiraya verilmek yerine fiilen işyeri gibi işletilmek suretiyle, otel, motel, pansiyon, kamping, apart otel ve benzeri gibi temel veya yardımcı konaklama işletmesi ya da sosyal tesis statüsünde bulunmamakla beraber, saatlik, günlük, haftalık ve benzeri kısa süreli konaklama hizmeti sunulan, Ulusal Adres Veri Tabanında ... adresi yer almayan veya ... abonelik kaydı bulunmayan yerleri ... ifade eder.'","kaynak":"KBY m.3","zorluk":"orta"},
    {"id":"YON26-S-004","soru":"Yönetmeliğe göre '24 saat' deyimi işe başlamanın veya ....(1).... vuku bulduğu saatten itibaren geçen süreyi ifade ederken; 'üç gün' deyimi işe başlama veya ....(2).... veya ayrılmanın vuku bulduğu saatten itibaren işlemeye başlayan 72 saatlik süreyi ifade eder. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["devrin - nakil","geliş - ayrılmanın","tescilin - kaydın","ayrılmanın - geliş","tebliğin - ıttılaın"],"dogru":3,"aciklama":"m.4: '24 saat deyimi; işe başlamanın veya ayrılmanın vuku bulduğu saatten itibaren geçen 24 saatlik, ... Üç gün deyimi; işe başlama veya geliş veya ayrılmanın vuku bulduğu saatten itibaren işlemeye başlayan 72 saatlik, süreyi kapsar.' 24 saat yalnızca 'işe başlama/ayrılma' iki olayını sayar; üç gün bunlara ek olarak 'geliş' olayını da kapsar.","kaynak":"KBY m.4","zorluk":"zor"},
    {"id":"YON26-S-005","soru":"Yönetmeliğe göre 'üç gün' deyimi tam olarak 72 saatlik bir süreyi ifade eder.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/b: 'Üç gün deyimi; işe başlama veya geliş veya ayrılmanın vuku bulduğu saatten itibaren işlemeye başlayan 72 saatlik süreyi kapsar.'","kaynak":"KBY m.4","zorluk":"kolay"},
    {"id":"YON26-S-006","soru":"Yönetmeliğe göre, kimliğini nüfus hüviyet cüzdanı veya diğer resmi geçerli belgelerle ispat edemeyen bir kişi hakkında bildirimle yükümlü tutulanların yapması gereken işlem nedir?","siklar":["Kişiyi barındırıp durumu sonradan bildirmek","Kişiyi geçici olarak barındırıp kimliğini kendisi araştırmak","Kişiyi barındırmak ama çalıştırmamak","Durumu yalnızca muhtara bildirip barındırmaya devam etmek","Kişiyi tesiste barındırmamak ve konut/iş yerinde çalıştırmamak"],"dogru":4,"aciklama":"m.5: 'Bu Yönetmelik hükümlerine göre kimlik bildirme belgelerini en yakın yetkili genel kolluk örgütüne vermekle yükümlü tutulanlar, kimliğini ... ispat edemeyen kimseleri, tesislerinde barındıramaz, konut ve iş yerinde çalıştıramaz.'","kaynak":"KBY m.5","zorluk":"kolay"},
    {"id":"YON26-S-007","soru":"Yönetmeliğe göre otel, motel, han, pansiyon gibi tesislerde sorumlu işleticinin kimliği ne zaman ve nasıl bildirilir?","siklar":["Tesis açılmadan önce iki örnek İŞLETİCİ KİMLİK BİLDİRME BELGESİ düzenlenerek en yakın yetkili genel kolluk örgütüne verilir","Tesis açıldıktan sonra bir ay içinde tek örnek belge ile","Tesis açıldıktan sonra üç gün içinde muhtara bildirilerek","Yalnızca yıllık denetimlerde kolluğa bildirilir","Tesis açılmadan önce tek örnek belge ile mahalli mülki amire bildirilir"],"dogru":0,"aciklama":"m.6: 'Sorumlu işleticinin kimliği, o tesis açılmadan önce, sahip veya kanuni temsilci veya kiracısı tarafından iki örnek İŞLETİCİ KİMLİK BİLDİRME BELGESİ (form: 1)'ne yazılır ve bu belgeler en yakın yetkili genel kolluk örgütüne verilir.'","kaynak":"KBY m.6","zorluk":"orta"},
    {"id":"YON26-S-008","soru":"Yönetmeliğe göre sorumlu işleticinin değişmesi halinde, yeni işleticiye ait kimlik bildirme belgesi üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'Sorumlu işleticinin değişmesi halinde, tesisin sahip, kanuni temsilci veya kiracısı tarafından, 24 saat içinde, yeni işleticiye ait kimlik bildirme belgesi ... en yakın yetkili genel kolluk örgütüne verilir.' Süre üç gün değil 24 saattir.","kaynak":"KBY m.7","zorluk":"kolay"},
    {"id":"YON26-S-009","soru":"Yönetmeliğin 8 inci maddesine göre, 6 ncı madde kapsamı dışındaki ticaret ve sanat amacı güden iş yerlerinde çalıştırılanlara ait kimlik bildirme belgeleri hangi süre içinde en yakın yetkili genel kolluk örgütüne verilir?","siklar":["24 saat","Üç gün","48 saat","Bir hafta","Bir ay"],"dogru":1,"aciklama":"m.8: '... (a) bendi kapsamında olanların belgesi 24 saat, (b) bendi kapsamında olanların belgesi üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.' (b) bendi 6. madde kapsamı DIŞINDAKİ iş yerleridir; süre üç gündür.","kaynak":"KBY m.8","zorluk":"orta"},
    {"id":"YON26-S-010","soru":"Yönetmeliğe göre, (b) bendi kapsamındaki iş yerleri köylerde ise, bildirimler elektronik ortamda yapılsa dahi muhtar onayı aranır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8: 'Maddenin (b) bendindeki yerler köylerde ise belgeler ... verilmeden önce muhtara onaylatılır. (Ek fıkra) ... Bildirimlerin elektronik ortamda yapılması durumunda muhtar onayı aranmaz.'","kaynak":"KBY m.8","zorluk":"orta"},
    {"id":"YON26-S-011","soru":"Yönetmeliğe göre işleticilerin, kendilerine verilen görev ve yükümlülükleri yöneticilerine devretmesi halinde sorumluluk nasıl paylaşılır?","siklar":["Sorumluluk tamamen yöneticiye geçer, işletici sorumluluktan kurtulur","Sorumluluk yalnızca işleticide kalır, yönetici hiç sorumlu tutulmaz","İşletici ve yönetici müştereken sorumlu olur","Sorumluluk mahalli mülki amire geçer","Sorumluluk genel kolluk örgütüne geçer"],"dogru":2,"aciklama":"m.8 (Ek fıkra): 'İşleticiler, kendilerine bu konuda verilen görev ve yükümlülükleri, kendi sorumlulukları altında yöneticilerine devredebilirler. Bu durumda işletici ve yönetici müştereken sorumlu olurlar.'","kaynak":"KBY m.8","zorluk":"zor"},
    {"id":"YON26-S-012","soru":"Yönetmeliğe göre, çalışanlara ait kimlik bildirme belgesinin kolluk örgütüne verildiği tarihten itibaren en geç ....(...).... içinde KONAKLAMA TESİSİ PERSONELİNE AİT KİMLİK KARTI doldurulup ilgiliye verilir. Boşluğa gelmesi gereken süre hangisidir?","siklar":["24 saat","Bir hafta","On beş gün","Üç gün","Bir ay"],"dogru":3,"aciklama":"m.9: 'Yönetmeliğin 6. maddesinde yazılı tesislerde çalıştıklarından ötürü haklarında çalışanlara ait kimlik bildirme belgesi düzenlenenler adına sorumlu işletici tarafından; bu belgenin örgüte verildiği tarihten itibaren en geç üç gün içinde KONAKLAMA TESİSİ PERSONELİNE AİT KİMLİK KARTI (Form: 3) doldurulur ve kendilerine verilir.'","kaynak":"KBY m.9","zorluk":"orta"},
    {"id":"YON26-S-013","soru":"Yönetmeliğe göre, bir iş yerinde çalışmadan, her ne suretle olursa olsun barınmalarına müsaade edilen kişilerin kimlikleri hangi belgeyle ve hangi süre içinde bildirilir?","siklar":["Form 2 ÇALIŞANLARA AİT KİMLİK BİLDİRME BELGESİ, 24 saat içinde","Form 6 MİSAFİRLERE AİT KİMLİK BİLDİRME BELGESİ, üç gün içinde","Form 3 KİMLİK KARTI, üç gün içinde","Form 1 İŞLETİCİ KİMLİK BİLDİRME BELGESİ, 24 saat içinde","Form 4 BARINANLARA AİT KİMLİK BİLDİRME BELGESİ, üç gün içinde"],"dogru":4,"aciklama":"m.10: 'İş yerlerinde çalışmadan, her ne suretle olursa olsun barınmalarına müsaade edilen kişilerin kimliği o yerin sorumlu işleticisi tarafından iki örnek BARINANLARA AİT KİMLİK BİLDİRME BELGESİ (Form: 4)'ne yazılır ve bu belgeler üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.'","kaynak":"KBY m.10","zorluk":"orta"},
    {"id":"YON26-S-014","soru":"Yönetmeliğe göre, bir konuta misafir olarak gelen ve ....(1).... süre için kalacak kişilerin kimlikleri, iki nüsha olarak düzenlenen belgelerle ....(2).... içinde en yakın yetkili genel kolluk örgütüne verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["30 günden fazla bir - üç gün","30 günden az bir - 24 saat","15 günden fazla bir - bir hafta","60 günden fazla bir - üç gün","30 günden fazla bir - 24 saat"],"dogru":0,"aciklama":"m.15: 'Şehir, kasaba ve köy sınırları içindeki konutlara misafir olarak gelen ve 30 günden fazla bir süre için kalacak kişilerin kimlikleri ... form 6'daki Misafirlere Ait Kimlik Bildirme Belgesine yazılır ve iki nüsha olarak düzenlenen bu belgeler üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.'","kaynak":"KBY m.15","zorluk":"orta"},
    {"id":"YON26-S-015","soru":"Yönetmeliğin 17 nci maddesine göre öğrenci yurtları ve benzeri yerlere ilişkin aşağıdaki hükümlerden hangisi doğru DEĞİLDİR?","siklar":["Çalıştırılanların kimlikleri iki örnek ÇALIŞANLARA AİT KİMLİK BİLDİRME BELGESİ'ne yazılır","Öğrenci yurdu çalışanlarının bildirimi, 6 ncı madde kapsamındaki tesisler gibi 24 saat içinde yapılır","Kalan öğrenci veya diğer kişilerin kimlikleri iki örnek BARINANLARA AİT KİMLİK BİLDİRME BELGESİ'ne yazılır","Belgeler üç gün içinde en yakın yetkili genel kolluk örgütüne verilir","Köylerde düzenlenen belgeler, kolluğa verilmeden önce muhtara onaylatılır"],"dogru":1,"aciklama":"m.17: '... çalıştırılanların kimlikleri iki örnek ÇALIŞANLARA AİT KİMLİK BİLDİRME BELGESİ (Form.2)'ne, kalan öğrencilerin veya diğer kişilerin kimlikleri iki örnek BARINANLARA AİT KİMLİK BİLDİRME BELGESİ (Form 4)'ne yazılır ve bu belgeler üç gün içinde ... verilir. Köylerde düzenlenen belgeler, anılan örgüte verilmeden önce muhtara onaylatılır.' Öğrenci yurtları m.6 kapsamına girmez; m.17'ye tabi TÜM bildirimler (çalışan dahil) üç gün içindedir, 24 saatlik süre yoktur.","kaynak":"KBY m.17","zorluk":"zor"},
    {"id":"YON26-S-016","soru":"Yönetmeliğe göre sabahçı kahvelerinde ve benzeri tesislerde kalanlar için ayrıca bildirim yapılması gerekmez; yalnızca mülkiye amirince verilen izin belgesinin tesisin görünür bir yerine asılması yeterlidir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.19: '... mahallin en büyük mülkiye amiri tarafından ... verilen izin belgesinin, tesislerin görünür bir yerine asılması zorunludur. Buralarda kalanlar için bildirim yapılmaz.'","kaynak":"KBY m.19","zorluk":"kolay"},
    {"id":"YON26-S-017","soru":"Yönetmeliğe göre sabahçı kahvesi ve benzeri tesislerin açık tutulması için izin belgesini hangi makam verir?","siklar":["En yakın yetkili genel kolluk örgütü amiri","Belediye başkanı tek başına","Mahallin en büyük mülkiye amiri","Köy muhtarı","İçişleri Bakanlığı"],"dogru":2,"aciklama":"m.19: '... o yerin bağlı bulunduğu kolluk örgütü ile belediye veya köy idaresinin olumlu görüşü alındıktan sonra mahallin en büyük mülkiye amiri tarafından geçici veya sürekli olarak açık tutulması ve ... izin belgesinin ... asılması zorunludur.'","kaynak":"KBY m.19","zorluk":"orta"},
    {"id":"YON26-S-018","soru":"Yönetmeliğe göre, adına belge düzenlenmiş bulunan bir misafirin o konuttan ayrılışı ile ilgili olarak aşağıdakilerden hangisi doğrudur?","siklar":["Ayrılış, çalışan ve barınanlarda olduğu gibi zımbalı kısım doldurularak kolluğa bildirilir","Ayrılış 24 saat içinde muhtara bildirilir","Ayrılış üç gün içinde mahalli mülki amire bildirilir","Misafirin ayrılışı kolluk örgütüne bildirilmez","Ayrılış, işletici değişikliğiyle birlikte bildirilir"],"dogru":3,"aciklama":"m.22: 'Hakkında belge verilmiş bulunan misafirlerin ayrılışı kolluk örgütüne bildirilmez.'","kaynak":"KBY m.20-22","zorluk":"zor"},
    {"id":"YON26-S-019","soru":"Yönetmeliğe göre yükümlü, kendisinde kalan çalışan/barınan kimlik bildirme belgesi örneğini, kolluk örgütünden aldığı zımbalı kısımla birlikte ne kadar süre ile saklar?","siklar":["Bir yıl","İki yıl","Beş yıl","On yıl","Üç yıl"],"dogru":4,"aciklama":"m.22: 'Yükümlü, kendisinde kalan belge örneğini kolluk örgütünden aldığı zımbalı kısımla birlikte üç yıl süre ile saklar.'","kaynak":"KBY m.22","zorluk":"orta"},
    {"id":"YON26-S-020","soru":"Yönetmeliğe göre, konaklama tesislerinde ücretli veya ücretsiz, gündüz veya gece yatacak yer gösterilen herkesin kimliği ile geliş ve ayrılış tarihleri hangi kayıt aracına ve ne sıklıkla işlenir?","siklar":["KONAKLAMA YERİ KAYIT DEFTERİ'ne, günü gününe","KİMLİK KARTI'na, haftalık olarak","İŞLETİCİ KİMLİK BİLDİRME BELGESİ'ne, aylık olarak","MİSAFİRLERE AİT KİMLİK BİLDİRME BELGESİ'ne, yıllık olarak","BARINANLARA AİT KİMLİK BİLDİRME BELGESİ'ne, üç günde bir"],"dogru":0,"aciklama":"m.23: '... buralarda ücretli veya ücretsiz, gündüz veya gece yatacak yer gösterilen yerli veya yabancı herkesin kimliği ile geliş ve ayrılış tarihleri, KONAKLAMA YERİ KAYIT DEFTERİ (Form:7)'ne günü gününe geçirilir.'","kaynak":"KBY m.23","zorluk":"kolay"},
    {"id":"YON26-S-021","soru":"Yönetmeliğe göre konaklama belgesindeki bilgiler, kişinin kimliğini belirten geçerli resmi belge ile karşılaştırılmadan doğrudan konaklama yeri kayıt defterine aktarılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.23: 'Konaklama belgesindeki bilgiler, kişinin kimliğini belirten geçerli resmi belge ile karşılaştırıldıktan sonra, konaklama yeri kayıt defterine aktarılır.' Karşılaştırma zorunlu bir ön şarttır.","kaynak":"KBY m.23","zorluk":"orta"},
    {"id":"YON26-S-022","soru":"Yönetmeliğe göre, bir yıla ait konaklama belgeleri düzenlendiği yılı izleyen takvim yılından başlayarak ....(1)....; konaklama yeri kayıt defterleri ise dolduğu yılı izleyen takvim yılından başlayarak ....(2).... süre ile sorumlu işleticinin sorumluluğu altında saklanır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["beş yıl - bir yıl","bir yıl - beş yıl","iki yıl - on yıl","bir yıl - üç yıl","altı ay - iki yıl"],"dogru":1,"aciklama":"m.24: 'Bir yıla ait konaklama belgeleri, düzenlendiği yılı izleyen takvim yılından başlayarak bir yıl; konaklama yeri kayıt defterleri, dolduğu yılı izleyen takvim yılından başlayarak beş yıl süre ile, sorumlu işleticinin sorumluluğu altında tesiste saklanır.'","kaynak":"KBY m.24","zorluk":"orta"},
    {"id":"YON26-S-023","soru":"Yönetmeliğe göre konaklama yeri kayıt defteri en az kaç sahifeden oluşmalıdır?","siklar":["50 sahife","75 sahife","100 sahife","150 sahife","200 sahife"],"dogru":2,"aciklama":"m.24: 'Defter yüz sahifeden aşağı olamaz.'","kaynak":"KBY m.24","zorluk":"kolay"},
    {"id":"YON26-S-024","soru":"Yönetmeliğe göre, yetkili resmi örgütler dışında, mahkeme kararı olmadıkça hiç kimsenin konaklama belgelerinden ve konaklama yeri kayıt defterlerinden yararlanmasına müsaade edilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.25: 'Yetkili resmi örgütler dışında, mahkeme kararı olmadıkça, hiç kimsenin konaklama belgelerinden ve konaklama yeri kayıt defterlerinden yararlanmasına müsaade edilemez.'","kaynak":"KBY m.25","zorluk":"kolay"},
    {"id":"YON26-S-025","soru":"Yönetmeliğe göre her karakol, bölgesini normal şartlarda ne sıklıkla tarayarak yeni veya yıkılan yapıları ve değişiklikleri saptar?","siklar":["Ayda bir kez","İki ayda bir kez","Altı ayda bir kez","Üç ayda bir kez","Yılda bir kez"],"dogru":3,"aciklama":"m.28: 'Her karakol üç ayda bir kez ve gerektiğinde sürekli olarak, bölgesini tarar ve bölge krokisinde veya binalar cetvelinde yer almayan yeni veya yıkılan yapıları ve her türlü ilave ve değişiklikleri saptar ...'","kaynak":"KBY m.28","zorluk":"kolay"},
    {"id":"YON26-S-026","soru":"Yönetmeliğin Ek 1 inci maddesine göre, konaklama tesislerince genel kolluğa anlık olarak bildirilen kayıtlar, kolluk kuvvetlerine ait sistemde ne kadar süreyle muhafaza edilir?","siklar":["1 yıl","2 yıl","3 yıl","10 yıl","5 yıl"],"dogru":4,"aciklama":"Ek m.1: '... genel kolluk kuvvetlerinin bilgisayar terminallerine bağlanarak mevcut bilgi, belge ve kayıtları genel kolluk kuvvetlerine anlık olarak bildirmek zorundadırlar. Bildirilen kayıtlar genel kolluk kuvvetlerine ait sistemde beş yıl süre ile muhafaza edilir. Bu süreyi dolduran kayıtlar kaydedilen sistemden otomatik olarak silinir.'","kaynak":"KBY Ek m.1","zorluk":"orta"},
    {"id":"YON26-S-027","soru":"Yönetmeliğin Ek 2 nci maddesine göre, araç kiralayanın kamu kurum veya kuruluşu olması halinde de, kiralayan kişinin kimlik bilgileri araç kiralama şirketinin sistemine ayrıca kaydedilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Ek m.2: 'Ancak araç kiralayanın kamu kurum veya kuruluşu olması halinde sadece kamu kurum veya kuruluşuyla yapılan sözleşme ile araç bilgileri sisteme kaydedilir.' Bu durumda kiralayan KİŞİNİN kimlik bilgisi değil, yalnızca sözleşme ve araç bilgisi kaydedilir.","kaynak":"KBY Ek m.2","zorluk":"zor"},
    {"id":"YON26-S-028","soru":"Yönetmeliğe göre aşağıdakilerden hangisi ÜÇ GÜN içinde en yakın yetkili genel kolluk örgütüne bildirilmesi gerekenlerden biri DEĞİLDİR?","siklar":["6 ncı madde kapsamındaki konaklama tesislerinde çalıştırılanlar (m.8/a)","6 ncı madde kapsamı dışındaki ticaret ve sanat amacı güden iş yerinde çalıştırılanlar (m.8/b)","İş yerinde çalışmadan barınanlar (m.10)","30 günden fazla kalacak misafirler (m.15)","Öğrenci yurtlarında çalıştırılan veya barınanlar (m.17)"],"dogru":0,"aciklama":"m.8/a bendi kapsamındaki (6. madde kapsamı) konaklama tesisi çalışanlarının bildirimi 24 SAAT içindedir; (b) bendi çalışanları (üç gün), barınanlar (m.10: üç gün), misafirler (m.15: üç gün) ve öğrenci yurdu çalışan/barınanları (m.17: üç gün) ise üç gün içinde bildirilir.","kaynak":"KBY m.7, m.8","zorluk":"zor"},
    {"id":"YON26-S-029","soru":"Bir kişi, bir iş yerinde çalışmadan, sorumlu işletici tarafından barınmasına müsaade edilerek orada kalıyorsa, Yönetmeliğe göre bu kişi hangi statüde bildirilir?","siklar":["Misafir (Form 6)","Barınan (Form 4)","Çalışan (Form 2)","Konutta kalan kişi (Form 5)","Personel kimlik kartı sahibi (Form 3)"],"dogru":1,"aciklama":"m.10: 'İş yerlerinde çalışmadan, her ne suretle olursa olsun barınmalarına müsaade edilen kişilerin kimliği o yerin sorumlu işleticisi tarafından iki örnek BARINANLARA AİT KİMLİK BİLDİRME BELGESİ (Form: 4)'ne yazılır.'","kaynak":"KBY m.10","zorluk":"zor"},
    {"id":"YON26-S-030","soru":"Yönetmeliğin genel sistematiğine göre, konaklama belgesi bir yıl ve konaklama yeri kayıt defteri beş yıl saklandıktan sonra, bu belge ve defterlerden yetkili resmi örgütler dışında kalan kişilerin yararlanabilmesi hangi şarta bağlıdır?","siklar":["Valinin yazılı izni","Mahalli mülki amirin onayı","Mahkeme kararı","İlgili muhtarın izni","Sorumlu işleticinin rızası"],"dogru":2,"aciklama":"m.25: 'Yetkili resmi örgütler dışında, mahkeme kararı olmadıkça, hiç kimsenin konaklama belgelerinden ve konaklama yeri kayıt defterlerinden yararlanmasına müsaade edilemez.' Saklama süreleri (m.24) ne kadar dolarsa dolsun, erişim tek başına mahkeme kararına bağlıdır.","kaynak":"KBY m.25","zorluk":"orta"},
    {"id":"YON26-S-031","soru":"Yönetmeliğin 2 nci maddesine (Kapsam) göre, aşağıdaki gruplardan hangisi bu Yönetmelik hükümlerine tabi DEĞİLDİR?","siklar":["Özel veya resmi konaklama, dinlenme, bakım ve tedavi tesislerinin sorumlu işleticileri","Ticaret ve sanat amacı güden iş yerlerinde çalışanlar ve barınanlar","Resmi dairelerin yetkili amirleri","Konutlarını değiştiren kişiler","Yabancı devletlerin Türkiye'deki büyükelçilik ve konsoloslukları"],"dogru":4,"aciklama":"m.2: 'Özel veya resmi her türlü konaklama, dinlenme, bakım ve tedavi tesislerinin, ticaret ve sanat amacı güden bütün iş yerlerinin ve öğrenci yurtlarının sorumlu işleticileri ile bu gibi yerlerde çalışanlar ve barınanlar; resmi dairelerin yetkili amirleri; konutlarda sürekli veya geçici olarak kalanlar, çalışanlar veya konutlarını değiştirenler, bu Yönetmelik hükümlerine tabidir.' Yabancı temsilcilikler madde metninde hiç geçmez.","kaynak":"KBY m.2","zorluk":"kolay"},
    {"id":"YON26-S-032","soru":"Yönetmeliğin 3 üncü maddesine göre, resmi kuruluşlarda sorumlu işletici sıfatı kime aittir?","siklar":["Yalnızca kuruluşun en büyük amirine bizzat","En yakın yetkili genel kolluk örgütü amirine","Kuruluşun en büyük amiri tarafından bu iş için görevlendirilen veya atanan kişiye; böyle biri atanmamışsa o yerin sahip, kanuni temsilci veya kiracısına","Yalnızca özel kuruluşlarda geçerli olup resmi kuruluşlarda sorumlu işletici aranmaz","İçişleri Bakanlığınca atanan bir memura"],"dogru":2,"aciklama":"m.3/ç: 'Sorumlu işletici: ... resmi kuruluşlar için en büyük amir tarafından iş verilen veya atanan kişiyi veya bu kişi tayin edilmediği takdirde o yerin sahip, kanuni temsilci veya kiracısını ... ifade eder.'","kaynak":"KBY m.3","zorluk":"orta"},
    {"id":"YON26-S-033","soru":"Yönetmeliğin 3 üncü maddesindeki 'ticaret ve sanat amacı güden iş yeri' tanımı için aşağıdakilerden hangisi doğru DEĞİLDİR?","siklar":["Ticarethane ve tüccar yazıhaneleri bu kapsama girer","Banka ve banker daireleri bu kapsama girer","Fabrika, imalathane ve atölyeler bu kapsama girer","Yalnızca büyükşehir belediyesi sınırları içinde kurulu iş yerleri bu kapsama girer","Anonim, kooperatif, limited, komandit ve kolektif şirketler bu kapsama girer"],"dogru":3,"aciklama":"m.3/d: 'Ticaret ve sanat amacı güden iş yeri: Her türlü ticarethane, tüccar yazıhanesi, ocak veya şantiye, fabrika ve imalathane ve atölye, depo, antrepo, ardiye, mağaza ve dükkan, banka ve banker dairesi, ikraz ve istikraz müessesesi, imtiyazlı ve imtiyazsız anonim, kooperatif, limited, komandit ve kolektif şirket gibi ... özel veya kamu kuruluşlarını ifade eder.' Tanımda coğrafi bir sınırlama yoktur.","kaynak":"KBY m.3","zorluk":"orta"},
    {"id":"YON26-S-034","soru":"Yönetmeliğin 3 üncü maddesine göre 'yetkili amir' tanımı aşağıdakilerden hangisidir?","siklar":["En yakın yetkili genel kolluk örgütünün amiri","Resmi bina ve eklentilerinin korunması ile görevli ve sorumlu, kanuni yöntemine göre örgütü tarafından atanan kişi","Mahallin en büyük mülkiye amiri","Resmi dairenin en kıdemli memuru","İçişleri Bakanlığı Müsteşarı"],"dogru":1,"aciklama":"m.3/e: 'Yetkili amir: Kanuni yöntemine göre örgütü tarafından atanan ve resmi bina ve eklentilerinin korunması ile görevli ve sorumlu kişiyi ... ifade eder.'","kaynak":"KBY m.3","zorluk":"kolay"},
    {"id":"YON26-S-035","soru":"Yönetmeliğe göre, sorumlu işletici değiştiğinde düzenlenecek yeni kimlik bildirme belgesinde yalnızca yeni işleticinin bilgileri yer alır; ayrılan işleticinin adı ve ayrılış tarihi ayrıca belirtilmez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: '... 24 saat içinde, yeni işleticiye ait kimlik bildirme belgesi, ayrılan işleticinin adı ve ayrılış tarihi de yazılarak ... en yakın yetkili genel kolluk örgütüne verilir.' Ayrılan işleticinin adı ve ayrılış tarihi de mutlaka belgeye yazılır.","kaynak":"KBY m.7","zorluk":"orta"},
    {"id":"YON26-S-036","soru":"Yönetmeliğin 8 inci maddesine göre, elektronik ortamda bildirimde bulunmak isteyen iş yerlerinde sorumlu işleticinin kimliği kim tarafından ve kime bildirilir; işleticinin değişmesi halinde bu değişiklik ne kadar sürede bildirilir?","siklar":["Sorumlu işleticinin kendisi tarafından muhtara; değişiklik üç gün içinde bildirilir","İl emniyet müdürlüğüne doğrudan işletici tarafından; değişiklik bir hafta içinde bildirilir","İş yerinin sahibi, kanuni temsilcisi veya kiracısı tarafından en yakın kolluk birimine; değişiklik 24 saat içinde bildirilir","Mahalli mülki amire; değişiklik 15 gün içinde bildirilir","Genel kolluk örgütünce resen tespit edilir, ayrı bildirim gerekmez"],"dogru":2,"aciklama":"m.8 (Ek fıkra): 'Elektronik ortamda bildirimde bulunmak isteyen iş yerlerinin sahibi veya kanuni temsilcisi veya kiracısı tarafından sorumlu işleticilerinin kimlikleri örneğine uygun şekilde en yakın kolluk birimine bildirilir. Sorumlu işleticinin değişmesi halinde değişikliğin yirmi dört saat içerisinde aynı şekilde bildirilmesi zorunludur.'","kaynak":"KBY m.8","zorluk":"zor"},
    {"id":"YON26-S-037","soru":"Yönetmeliğe göre, köy ve mahalle muhtarları, sorumluluk bölgelerindeki iş yerleri tarafından elektronik ortamda yapılan kimlik bildirimlerini talepleri hâlinde genel kolluk birimlerinden temin edebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8 (Ek fıkra): 'Köy ve mahalle muhtarları sorumluluk bölgelerinde bulunan işyerleri tarafından elektronik ortamda yapılan bildirimleri talepleri halinde genel kolluk birimlerinden temin eder.'","kaynak":"KBY m.8","zorluk":"orta"},
    {"id":"YON26-S-038","soru":"Yönetmeliğe göre, konaklama tesisi personelinden ayrılmak için başvuran bir kişinin kimlik kartının geri alınması zorunlu değildir; kart kişide kalabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.9: 'Ayrılmak için başvuran kişinin kimlik kartının geri alınması zorunludur.'","kaynak":"KBY m.9","zorluk":"kolay"},
    {"id":"YON26-S-039","soru":"Yönetmeliğe göre, barınanlara ait kimlik bildirme belgelerinin köylerde muhtara onaylatılması kuralı, bildirimin elektronik ortamda yapılması halinde de aynen uygulanmaya devam eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10 (Ek fıkra): 'Bildirimlerin elektronik ortamda yapılması halinde yukarıda yer alan hükümler uygulanmaz.' Köyde muhtara onaylatma şartı, elektronik bildirimde uygulanmaz.","kaynak":"KBY m.10","zorluk":"zor"},
    {"id":"YON26-S-040","soru":"Yönetmeliğin 16 ncı maddesine göre, şehir, kasaba ve köy sınırlarındaki konutlarda otururken mevsimlik olarak yaylak ve kışlak gibi yerlere göçen veya yaylak-kışlaklar arasında yer değiştiren aile veya kişilerin kimlikleri hangi belgeyle ve hangi süre içinde bildirilir?","siklar":["Form 4 Barınanlara Ait Kimlik Bildirme Belgesi, 24 saat içinde","Form 6 Konutta Kalanlara Ait Kimlik Bildirme Belgesi, üç gün içinde, iki nüsha olarak","Form 2 Çalışanlara Ait Kimlik Bildirme Belgesi, üç gün içinde","Form 6 Misafirlere Ait Kimlik Bildirme Belgesi, 30 gün içinde","Form 5 Konutta Kalanlara Ait Kimlik Bildirme Belgesi, bir hafta içinde"],"dogru":1,"aciklama":"m.16: '... göçen veya yaylak ve kışlaklar arasında yer değiştiren aile veya kişilerin kimlikleri, aile reisleri ve kişiler tarafından form 6'daki Konutta Kalanlara Ait Kimlik Bildirme Belgesine yazılır ve iki nüsha olarak düzenlenecek bu belgeler üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.'","kaynak":"KBY m.16","zorluk":"orta"},
    {"id":"YON26-S-041","soru":"Yönetmeliğe göre, işletici kimlik bildirme belgesi örnekleri, ayrılış ve başlayış tarihleri birbirini izlemek kaydıyla, yalnızca bir yıl süreyle yükümlüler tarafından tesiste saklanır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.20: 'Belge örnekleri ayrılış ve başlayış tarihleri birbirini izlemek kaydı ile tesisin çalıştığı süre boyunca yükümlüler tarafından tesiste saklanır.' Bir yıllık süre m.24'teki konaklama belgesine (form 8) aittir; işletici belgesi için sabit bir yıl sınırı yoktur.","kaynak":"KBY m.20","zorluk":"zor"},
    {"id":"YON26-S-042","soru":"Yönetmeliğin 21 inci maddesine göre, işletici kimlik bildirme belgesi dışındaki belgeler kolluk örgütüne verilirken zımbalı kısımda hangi haneler boş bırakılır?","siklar":["Zımbalı kısmın geliş tarihi ve adres haneleri","Zımbalı kısmın yalnızca imza hanesi","Belgenin tamamındaki tüm haneler","Zımbalı kısmın ayrılış tarihi ve imza haneleri","Zımbalı kısmın kimlik numarası hanesi"],"dogru":3,"aciklama":"m.21: 'İşletici kimlik bildirme belgesi dışındaki bütün belgelerin tabloları her iki örnekte doldurup imzalandıktan sonra ve zımbalı kısmın örneklerdeki ayrılış tarihi ve imza haneleri boş bırakılarak kolluk örgütüne verilir.'","kaynak":"KBY m.21","zorluk":"orta"},
    {"id":"YON26-S-043","soru":"Yönetmeliğe göre, konaklama yeri kayıt defteri ....(1).... olarak tutulur, kapağına tesis adı ve yılı yazılır. Kullanılmaya başlanmadan önce, sonu en yakın yetkili genel kolluk örgütüne ....(2).... belirtilerek onaylatılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["aylık - tesis adı","günlük - konuk sayısı","haftalık - defter numarası","yıllık - konuk sayısı","yıllık - sahife sayısı"],"dogru":4,"aciklama":"m.24: 'Defter yıllık olarak tutulur, kapağına tesis adı ve yılı yazılır. Kullanılmağa başlanılmadan önce, sonu en yakın yetkili genel kolluk örgütüne sahife sayısı belirtilerek onaylatılır.'","kaynak":"KBY m.24","zorluk":"orta"},
    {"id":"YON26-S-044","soru":"Yönetmeliğe göre, gelen konuk sayısı az olan konaklama tesislerinde defter kullanımı bakımından hangi kolaylık tanınmıştır?","siklar":["Yılı içinde birden fazla defter yerine tek defterin kullanılmasıyla yetinilebilir; yeni yılın kayıtlarına boş bir sahife bırakıldıktan sonra başlanır","Defter tutma zorunluluğu tamamen kaldırılır","Defter üç yılda bir yenilenir","Defterin en az yüz sahifeden oluşması şartı aranmaz","Defter yalnızca elektronik ortamda tutulabilir, kağıt defter gerekmez"],"dogru":0,"aciklama":"m.24: 'Defter yüz sahifeden aşağı olamaz. Yılı içinde birden fazla defter kullanılması halinde bunların kapağına birbirini izleyen sıra numarası verilir. Şu kadar ki, gelen konuk sayısını az olduğu tesislerde tek defter kullanılması ile yetinilebilir. Bu halde, yeni yılın kayıtlarına boş bir sahife bırakıldıktan sonra başlanır.'","kaynak":"KBY m.24","zorluk":"zor"},
    {"id":"YON26-S-045","soru":"Yönetmeliğe göre, belgeler en yakın genel kolluk örgütünde, karakol bölge krokisi ve binalar cetveli esas alınarak önce ....(1).... sonra ....(2).... üzerinden sınıflandırılarak saklanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["cadde ve sokak - mahalle ve semt","bina numarası - mahalle ve semt","mahalle ve semt - cadde, sokak ve bina numarası","il ve ilçe - mahalle ve semt","kişi adı - mahalle ve semt"],"dogru":2,"aciklama":"m.26: 'Belgeler, ... önce mahalle ve semt (varsa bölge) sonra cadde ve sokak ve bina numarası üzerinden sınıflandırılmış ve üstünde bu bilgiler bulunan gözlerde kilit altında saklanır.'","kaynak":"KBY m.26","zorluk":"orta"},
    {"id":"YON26-S-046","soru":"Yönetmeliğe göre, belediyeler, mahallin en büyük mülki amirince istenilmesi halinde, düzenledikleri nümerotaj cetvelinin birer örneğini vermekle yükümlüdür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.28: 'Belediyeler, mahallin en büyük mülki amirince istenilmesi halinde düzenledikleri nümerotaj cetvelinin birer örneğini vermekle yükümlüdürler.'","kaynak":"KBY m.28","zorluk":"kolay"},
    {"id":"YON26-S-047","soru":"Yönetmeliğin Ek 3 üncü maddesine göre, bu Yönetmeliğe tabi gerçek kişiler ile özel hukuk tüzel kişilerinin defter tutma, bilgi, belge ve kayıtları arşivleme yükümlülükleri ile bunları muhafaza etme sürelerine ilişkin olarak hangi mevzuat hükümleri saklıdır?","siklar":["213 sayılı Vergi Usul Kanunu, 6102 sayılı Türk Ticaret Kanunu ve diğer mevzuatta yer alan hükümler","Yalnızca 6698 sayılı Kişisel Verilerin Korunması Kanunu","Yalnızca 1774 sayılı Kimlik Bildirme Kanunu","Yalnızca İçişleri Bakanlığı genelgeleri","Yalnızca Ticaret Bakanlığı tebliğleri"],"dogru":0,"aciklama":"Ek m.3: 'Bu Yönetmeliğe tabi gerçek kişiler ile özel hukuk tüzel kişilerinin; defter tutma, bilgi, belge ve kayıtları arşivleme yükümlülükleri ile bunları muhafaza etme sürelerine ilişkin olarak 213 sayılı Vergi Usul Kanunu, 6102 sayılı Türk Ticaret Kanunu ve diğer mevzuatta yer alan hükümler saklıdır.'","kaynak":"KBY Ek m.3","zorluk":"orta"},
    {"id":"YON26-S-048","soru":"Yönetmeliğin Ek 4 üncü maddesine göre, bu Yönetmeliğin uygulanmasında, 6698 sayılı Kişisel Verilerin Korunması Kanunu kapsamında verilerin uygun güvenlik düzeyini temin etmeye yönelik gerekli her türlü teknik ve idari tedbirlerin alınması öngörülür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. Ek m.4: 'Bu Yönetmeliğin uygulanmasında, 24/3/2016 tarihli ve 6698 sayılı Kişisel Verilerin Korunması Kanununun ilgili hükümleri kapsamında verilerin uygun güvenlik düzeyini temin etmeye yönelik gerekli her türlü teknik ve idari tedbirler alınır.'","kaynak":"KBY Ek m.4","zorluk":"kolay"},
  ],
  51: [
    {"id":"YON27-S-001","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre ses ve gaz fişeği atabilen silahların satışı hangi yerlerce yapılır?","siklar":["Mermi veya av malzemesi ya da yivsiz tüfek satışı yapmak için ruhsatlandırılmış yerlerce","Sadece silah üreticisi fabrikalarca","Emniyet Genel Müdürlüğü onaylı özel mağazalarca","Herhangi bir ruhsat aranmaksızın her işyerince","Yalnızca ithalatçı firmalarca"],"dogru":0,"aciklama":"m.13/(1): 'Ses ve gaz fişeği atabilen silahların satışı, mermi veya av malzemesi ya da yivsiz tüfek satışı yapmak için ruhsatlandırılmış yerlerce yapılır.' Satış yeri bu ruhsat türüyle sınırlıdır.","kaynak":"YON27 m.13","zorluk":"kolay"},
    {"id":"YON27-S-002","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre satış yapan yerler, sattıkları mamullere ilişkin listeleri ....(1).... içinde kolluk birimlerine bildirmek zorundadır; merkezi kayıt sisteminin devreye alınmasını müteakip bu bildirimler depo giriş ve çıkışında ....(2).... yapılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir hafta - günlük","bir ay - anlık","üç ay - haftalık","on beş gün - anlık","iki ay - günlük"],"dogru":1,"aciklama":"m.13/(2): '...bir ay içerisinde kolluk birimlerine bildirmek zorundadır. Merkezi kayıt sisteminin devreye alınmasını müteakip bildirimler depo girişinde ve çıkışında anlık olarak yapılır.'","kaynak":"YON27 m.13","zorluk":"orta"},
    {"id":"YON27-S-003","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre genel amaçlı üretimlerden yurt içine satılan ses ve gaz fişeği atabilen silahların ambalaj ve kutularına Ek-1'de yer alan yasal uyarı ile kullanım kılavuzunun konulması zorunludur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.13/(3): 'Genel amaçlı üretimlerden yurt içine satılan ses ve gaz fişeği atabilen silahların ambalaj ve kutularına Ek-1'de yer alan yasal uyarı ile ses ve gaz fişeği atabilen silahın kullanım kılavuzunun konulması zorunludur.'","kaynak":"YON27 m.13","zorluk":"kolay"},
    {"id":"YON27-S-004","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi başvurusu nasıl yapılır?","siklar":["İl özel güvenlik komisyonuna yazılı dilekçeyle","Noter onaylı başvuru formuyla","Elektronik ortamda","Kolluk biriminde şahsen imza ile","Yalnızca dağıtıcı aracılığıyla posta yoluyla"],"dogru":2,"aciklama":"m.14/(1): 'Merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi başvurusu elektronik ortamda yapılır. Gerekli şartları taşımaları kaydıyla ... merkezi kayıt sistemi aracılığıyla yetki belgesi hakları verilir.'","kaynak":"YON27 m.14","zorluk":"orta"},
    {"id":"YON27-S-005","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre yetki belgesinin geçerlilik süresi 1 yıldır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.14/(2): 'Yetki belgesinin geçerlilik süresi 6 aydır.' Süre 1 yıl değil 6 aydır.","kaynak":"YON27 m.14","zorluk":"kolay"},
    {"id":"YON27-S-006","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre alınan her yetki belgesi ile kaç adet ses ve gaz fişeği atabilen silah alınabilir?","siklar":["Sınırsız sayıda","İki adet","Dağıtıcının belirlediği sayıda","Bir adet","Üç adet"],"dogru":3,"aciklama":"m.14/(3): 'Alınan her yetki belgesi ile bir adet ses ve gaz fişeği atabilen silah alınabilir.'","kaynak":"YON27 m.14","zorluk":"kolay"},
    {"id":"YON27-S-007","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre aşağıdakilerden hangisi, kendisine ses ve gaz fişeği atabilen silah satışının yasaklandığı kişi grupları arasında sayılmamıştır?","siklar":["Ülkemizde ikamet eden yabancı","Turist","Mülteci","Şartlı mülteci veya ikincil koruma statüsü sahibi","Gerekli şartları taşıyan Türk vatandaşı"],"dogru":4,"aciklama":"m.14/(3): '...ülkemizde ikamet eden yabancılara, turistlere, mültecilere, şartlı mülteci ve ikincil koruma statüsü sahipleri ile insani ikamet izni sahipleri ve geçici koruma sağlananlara ses ve gaz fişeği atabilen silah satılamaz.' Gerekli şartları taşıyan Türk vatandaşı bu yasak kapsamında değildir; kendisine satış yapılabilir.","kaynak":"YON27 m.14","zorluk":"zor"},
    {"id":"YON27-S-008","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre dağıtıcının, gerekli şartları taşımayan veya yetki belgesi olmayan kişilere satış yapması durumunda bayilik belgesi hangi makam tarafından ve ne kadar süreyle iptal edilir?","siklar":["İçişleri Bakanlığınca - 5 yıl","Sanayi ve Teknoloji Bakanlığınca - 6 ay","Kolluk birimince - 1 yıl","Emniyet Genel Müdürlüğünce - 3 yıl","Valilikçe - 2 yıl"],"dogru":0,"aciklama":"m.14/(4): 'Dağıtıcının ... şartları sağlamayan ve ... yetki belgesi olmayan kişilere satış yapması durumunda İçişleri Bakanlığınca verilen bayilik belgesi 5 yıl süre ile iptal edilir.'","kaynak":"YON27 m.14","zorluk":"orta"},
    {"id":"YON27-S-009","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre ses ve gaz fişeği atabilen silah, dağıtıcılar dışında üçüncü kişilerden de doğrudan satın alınabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.15/(1): 'Ses ve gaz fişeği atabilen silah sadece dağıtıcılardan alınır.' Üçüncü kişilerden doğrudan satın alma metne aykırıdır.","kaynak":"YON27 m.15","zorluk":"kolay"},
    {"id":"YON27-S-010","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre satın alma işlemini gerçekleştiren kişi, fatura tarihinden itibaren ....(1).... bildirim süresi içinde fatura ve silahla birlikte kolluk birimine müracaat eder; müracaat edilen kolluk birimince her silah için Ek-3'te yer alan ....(2).... düzenlenir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir haftalık - Nakil Belgesi","bir aylık - Bildirim Kartı","üç aylık - Yetki Belgesi","on beş günlük - Nakil Belgesi","altı aylık - Bildirim Kartı"],"dogru":1,"aciklama":"m.15/(2): '...fatura tarihinden itibaren bir aylık bildirim süresi içerisinde, fatura ve ... silah ile birlikte kolluk birimine müracaat eder. Müracaat edilen kolluk birimince her ... silah için Ek-3'te yer alan Ses ve Gaz Fişeği Atabilen Silah Bildirim Kartı düzenlenir.'","kaynak":"YON27 m.15","zorluk":"orta"},
    {"id":"YON27-S-011","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre film, tiyatro, sinema, şenlik, kutlama ve tören gibi etkinlikler için kullanılacak silahların satın alma yetkilendirme ve izin işlemleri hangi kurum tarafından yapılır?","siklar":["İçişleri Bakanlığı","Sanayi ve Teknoloji Bakanlığı","Emniyet Genel Müdürlüğü","İl kolluk birimi","Vali"],"dogru":2,"aciklama":"m.15/(3): 'Film, tiyatro, sinema, şenlik, kutlama ve tören gibi etkinlikler için kullanılacak ses ve gaz fişeği atabilen silahların satışında satın alma yetkilendirme ve izin işlemleri Emniyet Genel Müdürlüğü tarafından yapılır.'","kaynak":"YON27 m.15","zorluk":"orta"},
    {"id":"YON27-S-012","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre film, tiyatro, sinema, şenlik, kutlama ve tören amaçlı satın alınan silahlara ilişkin aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Satın alma yetkilendirme ve izin işlemleri Emniyet Genel Müdürlüğünce yapılır","Genel satış amaçlı silah satın alma şartları aranmaz","İzin süreli olarak verilir","Kullanılacak silahlar için Ek-3 Bildirim Kartı düzenlenir","Süre sonunda silahlar Makine ve Kimya Endüstrisi Anonim Şirketinde imha edilmek üzere Emniyet Genel Müdürlüğüne teslim edilir veya ihraç edilir"],"dogru":3,"aciklama":"m.15/(3): '...Satın alma işlemi sonrasında Emniyet Genel Müdürlüğü tarafından süreli olarak izin verilir ve kullanılacak silahlar için bildirim kartı düzenleme işlemi yapılmaz.' D ifadesi bu cümleye aykırıdır; diğer dört ifade metinle birebir örtüşür.","kaynak":"YON27 m.15","zorluk":"zor"},
    {"id":"YON27-S-013","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre ses ve gaz fişeği atabilen silahların 'nakil' sayılabilmesi için gerekli şart aşağıdakilerden hangisidir?","siklar":["Dolu şekilde ceket içinde taşınması","Yalnızca fatura ile herhangi bir kap kullanılmadan taşınması","Kolluk eskortu eşliğinde taşınması","Sadece posta yoluyla gönderilmesi","Fişekleri boşaltılmış, kutu içinde ve Bildirim Kartı ile taşınması"],"dogru":4,"aciklama":"m.17/(1): 'Ses ve gaz fişeği atabilen silahlar; fişekleri boşaltılarak, her an kullanıma ve erişim kolaylığına imkân vermeyecek şekilde ve bir kutu içerisinde ... Bildirim Kartı ile nakledilebilirler. Bu silahların belirtilen şekil ve şartların dışında nakledilmesi taşıma olarak kabul edilir.'","kaynak":"YON27 m.17","zorluk":"orta"},
    {"id":"YON27-S-014","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre bu silahlar, bayiden veya üçüncü şahıslardan devir veya satın alınmasından itibaren bildirimde bulunulmasına kadar tanınan ....(1).... süre içinde ancak ....(2).... ile nakledilebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir aylık - fatura ya da Ek-5'te yer alan belge","üç aylık - yetki belgesi","bir haftalık - nakil belgesi","iki aylık - Bildirim Kartı","altı aylık - kolluk yazısı"],"dogru":0,"aciklama":"m.17/(2): '...devir veya satın alınmasından itibaren bildirimde bulunulmasına kadar tanınan bir aylık süre içerisinde birinci fıkrada belirtilen usule göre ve ancak fatura ya da Ek-5'te yer alan belge ile nakledilebilir.'","kaynak":"YON27 m.17","zorluk":"zor"},
    {"id":"YON27-S-015","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre ses ve gaz fişeği atabilen silahlar, belirtilen usullere uygun olmak şartıyla posta veya kargo yoluyla nakledilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.17/(4): 'Ses ve gaz fişeği atabilen silahlar birinci ve ikinci fıkralarda belirtilen usullere uygun olarak posta veya kargo yoluyla nakledilebilir.'","kaynak":"YON27 m.17","zorluk":"orta"},
    {"id":"YON27-S-016","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre nakle ilişkin birinci ve ikinci fıkralarda belirtilen usullere aykırı davranılması durumunda ne yapılır?","siklar":["Sadece yetki belgesi 6 ay süreyle askıya alınır","Kanunun 4 üncü maddesine göre işlem yapılır","Bildirim kartı iptal edilir ama başka yaptırım yoktur","Sadece idari uyarı verilir","Bayilik belgesi otomatik olarak 5 yıl iptal edilir"],"dogru":1,"aciklama":"m.17/(3): 'Birinci ve ikinci fıkralarda belirtilen işlemlere aykırı davranılması durumunda Kanunun 4 üncü maddesine göre işlem yapılır.'","kaynak":"YON27 m.17","zorluk":"orta"},
    {"id":"YON27-S-017","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre, satış yapan yerlerin bilgisayar ortamında düzenleyerek kolluk birimlerine bildireceği listede aşağıdaki bilgilerden hangisinin yer alması zorunlu değildir?","siklar":["Satılan mamulün cinsi","Satılan mamulün çapı","Satın alan kişi veya kuruluşun adı ve açık adresi","Satın alan kişinin vergi kimlik numarası","Satılan mamulün seri numarası"],"dogru":3,"aciklama":"m.13/(2): '...sattıkları mamullerin cins, çap ve seri numaralarını, satın alan kişi veya kuruluşun ad ve açık adreslerini belirleyecek tarzda bilgisayar ortamında düzenleyecekleri listeleri...' Vergi kimlik numarası metinde sayılan zorunlu bilgiler arasında yer almaz.","kaynak":"YON27 m.13","zorluk":"zor"},
    {"id":"YON27-S-018","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre, satış yapan yerler sattıkları mamullere ilişkin bildirim listesini yalnızca elle düzenlenmiş kağıt tutanak şeklinde kolluk birimine sunabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.13/(2): '...bilgisayar ortamında düzenleyecekleri listeleri bir ay içerisinde kolluk birimlerine bildirmek zorundadır.' Liste elle düzenlenmiş kağıt tutanak değil, bilgisayar ortamında düzenlenmelidir.","kaynak":"YON27 m.13","zorluk":"kolay"},
    {"id":"YON27-S-019","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre dağıtıcı, ses ve gaz fişeği atabilen silah satın almak isteyenlere hangi şartla satış yapar?","siklar":["Kanunun 3 üncü maddesinin birinci fıkrasında belirtilen şartları taşımaları şartıyla","Yalnızca yetki belgesi süresinin dolmamış olması şartıyla","Sadece nüfus cüzdanı ibraz etmeleri şartıyla","Kolluk biriminden ayrıca yazılı izin almaları şartıyla","Bildirim Kartı'na sahip olmaları şartıyla"],"dogru":0,"aciklama":"m.14/(1): 'Dağıtıcı, ses ve gaz fişeği atabilen silah satın alacaklara Kanunun 3 üncü maddesinin birinci fıkrasında belirtilen şartları taşımaları şartıyla satış yapar.'","kaynak":"YON27 m.14","zorluk":"kolay"},
    {"id":"YON27-S-020","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre dağıtıcının bayilik belgesinin İçişleri Bakanlığınca 5 yıl süreyle iptal edilebilmesi için, satış yapılan kişinin hem Kanunun 3 üncü maddesindeki şartları sağlamaması hem de (merkezi kayıt sisteminin devreye alınmasını müteakip) yetki belgesinin bulunmaması birlikte aranır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.14/(4): 'Dağıtıcının, Kanunun 3 üncü maddesinde belirtilen şartları sağlamayan ve merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi olmayan kişilere satış yapması durumunda İçişleri Bakanlığınca verilen bayilik belgesi 5 yıl süre ile iptal edilir.' Metindeki 've' bağlacı iki koşulun birlikte arandığını gösterir.","kaynak":"YON27 m.14","zorluk":"zor"},
    {"id":"YON27-S-021","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre merkezi kayıt sisteminin devreye alınmasını müteakip, yetki belgesi sahibi dağıtıcıdan silah satın alma işlemini nasıl gerçekleştirir?","siklar":["Yalnızca kimlik ibrazıyla, yetki belgesi aranmaksızın","Bu yetki belgesiyle birlikte","Kolluk biriminin refakatinde","Noter huzurunda düzenlenen sözleşmeyle","Yalnızca Bildirim Kartı'nı ibraz ederek"],"dogru":1,"aciklama":"m.15/(1): 'Merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi sahibi, bu yetki belgesi ile birlikte dağıtıcılardan ses ve gaz fişeği atabilen silahı satın alma işlemini gerçekleştirir.'","kaynak":"YON27 m.15","zorluk":"orta"},
    {"id":"YON27-S-022","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre film, tiyatro, sinema, şenlik, kutlama ve tören gibi etkinlikler için verilen izin süresi sonunda, izin verilen silahlar ....(1).... Şirketinde imha edilmek üzere ....(2).... teslim edilir veya ihraç edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Milli Savunma Bakanlığına bağlı - İçişleri Bakanlığına","Sanayi ve Teknoloji Bakanlığına bağlı - kolluk birimine","Makine ve Kimya Endüstrisi Anonim - Valiliğe","Türk Silahlı Kuvvetlerine bağlı - dağıtıcıya","Makine ve Kimya Endüstrisi Anonim - Emniyet Genel Müdürlüğüne"],"dogru":4,"aciklama":"m.15/(3): '...izin verilen silahlar Makine ve Kimya Endüstrisi Anonim Şirketinde imha edilmek üzere Emniyet Genel Müdürlüğüne teslim edilir veya ihraç edilir.'","kaynak":"YON27 m.15","zorluk":"orta"},
    {"id":"YON27-S-023","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre merkezi kayıt sisteminin devreye alınmasını müteakip, üretici ve dağıtıcılar tarafından yurt içine veya yurt dışına satılan ses ve gaz fişeği atabilen silahlar hangi belge ile nakledilir?","siklar":["Ek-3'te yer alan Bildirim Kartı","Fatura ya da Ek-5'te yer alan belge","Merkezi kayıt sistemi tarafından oluşturulan nakil belgesi","Yetki belgesi","Kolluk biriminin düzenlediği taşıma tutanağı"],"dogru":2,"aciklama":"m.17/(2): 'Merkezi kayıt sisteminin devreye alınmasını müteakip üretici ve dağıtıcılar tarafından yurt içi veya yurt dışına satılan ses ve gaz fişeği atabilen silahlar, merkezi kayıt sistemi tarafından oluşturulan nakil belgesi ile nakledilir.'","kaynak":"YON27 m.17","zorluk":"orta"},
    {"id":"YON27-S-024","soru":"Ses ve Gaz Fişeği Atabilen Silahlar Hakkında Yönetmelik'e göre aşağıdaki belge-işlev eşleştirmelerinden hangisi yanlıştır?","siklar":["Yetki Belgesi – satın alma öncesi, satın alacak kişiye merkezi kayıt sistemi aracılığıyla verilir","Bildirim Kartı – satın alma sonrası, kolluk birimince her silah için düzenlenir","Nakil Belgesi – merkezi kayıt sistemi tarafından, üretici/dağıtıcının satışlarında oluşturulur","Bayilik Belgesi – kuralsız satış hâlinde İçişleri Bakanlığınca 5 yıl süreyle iptal edilir","Ek-1 Yasal Uyarı – film, tiyatro ve tören amaçlı satın almalarda Emniyet Genel Müdürlüğünce düzenlenen bir belgedir"],"dogru":4,"aciklama":"E yanlıştır. Ek-1, m.13/(3) uyarınca genel amaçlı üretimlerden yurt içine satılan silahların ambalaj ve kutusuna konulan bir yasal uyarı ve kullanım kılavuzudur; EGM tarafından düzenlenen bir belge değildir ve film/tören istisnasıyla (m.15/3) ilgisi yoktur. A m.14/(1), B m.15/(2), C m.17/(2), D m.14/(4) ile birebir örtüşür.","kaynak":"YON27 m.13/14/15/17","zorluk":"zor"},
  ],
  52: [
    {"id":"28-S-001","soru":"Karayolları Trafik Yönetmeliği'ne göre 'geçiş üstünlüğü' kavramı ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Geçiş üstünlüğü, belirli araç sürücülerinin can ve mal güvenliğini tehlikeye sokmamak şartıyla trafik kısıtlama veya yasaklarına bağlı olmamasıdır","Geçiş üstünlüğü, yayaların araç sürücülerine göre yolu kullanmadaki öncelik hakkıdır","Geçiş üstünlüğü, kavşaklarda ana yoldan gelen aracın öncelikli olmasıdır","Geçiş üstünlüğü, sürücülerin trafik ışığına uyma zorunluluğunun adıdır","Geçiş üstünlüğü, duraklama yapan aracın öncelik hakkıdır"],"dogru":0,"aciklama":"m.3/12: 'Geçiş Üstünlüğü: Görev sırasında, belirli araç sürücülerinin can ve mal güvenliğini tehlikeye sokmamak şartı ile trafik kısıtlama veya yasaklarına bağlı olmamalarıdır.'","kaynak":"KTY m.3","zorluk":"kolay"},
    {"id":"28-S-002","soru":"Karayolları Trafik Yönetmeliği'nin tanımlar maddesine göre aşağıdakilerden hangisi yanlıştır?","siklar":["Araç, motorlu ve motorsuz taşıtlar ile iş makineleri ve lastik tekerlekli traktörlerin genel adıdır","Hizmetli, araçta sürücü dahil taşıma hizmetlerinde çalışan kişidir","Şoför, karayolunda ticari olarak tescil edilmiş bir motorlu taşıtı süren kişidir","Yolcu, aracı kullanan sürücü ile hizmetliler dışında araçta bulunan kişidir","Trafikten men, araçla ilgili belgelerin alınması ve aracın belirli bir yere çekilerek trafikten alıkonulmasıdır"],"dogru":1,"aciklama":"m.3/10: 'Hizmetli: Araçlarda, sürücü hariç, araç veya taşıma hizmetlerinde ... çalışan kişiler ...' Tanım sürücüyü açıkça DIŞLAR; B şıkkı 'sürücü dahil' diyerek metni bozar. Diğer dört şık m.3'teki tanımlarla birebir örtüşür.","kaynak":"KTY m.3/a","zorluk":"orta"},
    {"id":"28-S-003","soru":"Karayolları Trafik Yönetmeliği'ne göre 'duraklama', kırmızı ışık gibi trafik zorunlulukları nedeniyle aracın durdurulmasını ifade eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/14-15: Trafik zorunlulukları nedeniyle durdurma 'DURMA'dır ('Kırmızı ışık, yetkililerin dur işareti ... nedeni ile aracın durdurulmasıdır'); duraklama ise 'trafik zorunlulukları DIŞINDA ... kısa bir süre için durdurulmasıdır.' Soru, durma tanımını duraklamaya atfetmiştir.","kaynak":"KTY m.3","zorluk":"kolay"},
    {"id":"28-S-004","soru":"Karayolları Trafik Yönetmeliği'ne göre Karayolu Güvenliği Yüksek Kurulu ne sıklıkla olağan toplanır?","siklar":["Ayda bir","Üç ayda bir","Yılda iki defa","Yılda bir defa","İki yılda bir"],"dogru":2,"aciklama":"m.4: 'Kurul yılda iki defa olağan, ... gerek görülmesi halinde de olağanüstü olarak, gündemle toplanır.'","kaynak":"KTY m.4","zorluk":"orta"},
    {"id":"28-S-005","soru":"Karayolları Trafik Yönetmeliği'ne göre askeri mahallerde geçici trafik düzenleme yetkisinin merkez komutanlıklarına verilebilmesi için hangi iki husus birlikte gerçekleşmelidir?","siklar":["İçişleri Bakanının isteği ve Genelkurmay Başkanlığının onayı","Vali onayı ve trafik zabıtası talebi","Belediye başkanının isteği ve emniyet müdürünün onayı","Mülki idari amirinin isteği ve garnizon komutanının uygun görmesi","Jandarma Genel Komutanlığının isteği ve mülki amirin onayı"],"dogru":3,"aciklama":"m.5: '...mülki idari amirinin isteği ve garnizon komutanının uygun görmesi halinde, merkez komutanlıklarına ... geçici olarak trafiği düzenleme yetkisi verilebilir.'","kaynak":"KTY m.5","zorluk":"orta"},
    {"id":"28-S-006","soru":"Karayolları Trafik Yönetmeliği'ne göre ....(1).... sınıfı sürücü belgesi otomobil ve kamyonet kullanacaklara, ....(2).... sınıfı sürücü belgesi ise kamyon ve çekici kullanacaklara verilir. Boşluklara sırasıyla gelmesi gereken harfler hangisidir?","siklar":["A - B","C - D","D - B","A - D","B - C"],"dogru":4,"aciklama":"m.75/e: 'B sınıfı sürücü belgesi otomobil ve kamyonet kullanacaklara verilir.' m.75/h: 'C sınıfı sürücü belgesi kamyon ve çekici kullanacaklara verilir.'","kaynak":"KTY m.75","zorluk":"kolay"},
    {"id":"28-S-007","soru":"Karayolları Trafik Yönetmeliği'ne göre aşağıdaki sürücü belgesi sınıfı - araç eşleştirmelerinden hangisi yanlıştır?","siklar":["A sınıfı - dört tekerlekli motosiklet","D sınıfı - minibüs ve otobüs","F sınıfı - lastik tekerlekli traktör","G sınıfı - iş makinesi","M sınıfı - motorlu bisiklet (moped)"],"dogru":0,"aciklama":"m.75/Ç: 'A sınıfı sürücü belgesi ... iki tekerlekli motosikletler ile gücü 15 kilovatı geçen üç tekerlekli motosikletleri kullanacaklara verilir.' Dört tekerlekli motosiklet ise m.75/d uyarınca B1 sınıfına aittir, A sınıfına değil.","kaynak":"KTY m.75","zorluk":"orta"},
    {"id":"28-S-008","soru":"Karayolları Trafik Yönetmeliği'ne göre M, A1 ve B1 sınıfı sürücü belgesi alacakların ....(1).... yaşını, D ve DE sınıfı sürücü belgesi alacakların ise ....(2).... yaşını bitirmiş olmaları gerekir. Boşluklara sırasıyla gelmesi gereken yaşlar hangisidir?","siklar":["18 - 21","16 - 24","16 - 21","18 - 24","17 - 24"],"dogru":1,"aciklama":"m.76/a: 'M, A1 ve B1 sınıfı sürücü belgesi alacakların 16 ... D, DE sınıfı sürücü belgesi alacakların 24 yaşını bitirmiş olmaları' zorunludur.","kaynak":"KTY m.76","zorluk":"orta"},
    {"id":"28-S-009","soru":"Karayolları Trafik Yönetmeliği'ne göre C1, C, D1 ve D sınıfı sürücü belgesi alacaklarda deneyim bakımından hangi şart aranır?","siklar":["En az iki yıllık A2 sınıfı sürücü belgesine sahip olmak","En az bir yıllık B sınıfı sürücü belgesine sahip olmak","En az B sınıfı sürücü belgesine sahip olmak","En az iki yıllık B sınıfı sürücü belgesine sahip olmak","Herhangi bir deneyim şartı aranmaz"],"dogru":2,"aciklama":"m.76/b: 'C1, C, D1 ve D sınıfı ... en az B sınıfı ... sürücü belgesine sahip olmaları ... zorunludur.' Metinde süre şartı belirtilmemiştir.","kaynak":"KTY m.76","zorluk":"zor"},
    {"id":"28-S-010","soru":"Karayolları Trafik Yönetmeliği'ne göre araç ve hayvan sürücüleri ile yayaların yolu kullanırken uyması gereken kurallar arasındaki öncelik sıralaması nasıldır?","siklar":["Işıklı işaretler → görevlinin işaretleri → levha/tertibat/yer işaretlemesi → diğer kurallar","Levha/tertibat/yer işaretlemesi → görevlinin işaretleri → ışıklı işaretler → diğer kurallar","Diğer kurallar → görevlinin işaretleri → ışıklı işaretler → levha/tertibat/yer işaretlemesi","Görevlinin işaretleri → ışıklı-sesli işaretler → levha/tertibat/yer işaretlemesi → diğer kurallar","Görevlinin işaretleri → levha/tertibat/yer işaretlemesi → ışıklı-sesli işaretler → diğer kurallar"],"dogru":3,"aciklama":"m.95: öncelik sırası a) yetkili görevlilerin uyarı ve işaretleri, b) ışıklı ve sesli trafik işaretleri, c) levha/tertibat/yer işaretlemeleri, d) diğer kural ve yükümlülükler şeklindedir; 'bunlara uymadaki öncelik yukarıda yapılan sıralamaya göredir.'","kaynak":"KTY m.95","zorluk":"orta"},
    {"id":"28-S-011","soru":"Karayolları Trafik Yönetmeliği'ne göre trafiği yöneten görevlinin bir kolunu dik olarak yukarı kaldırması ne anlama gelir?","siklar":["Kolun gösterdiği yönden gelenler için DUR emri","Yalnız kavşağa yeni girmiş sürücüler için DUR emri","Sadece yaya trafiği için DUR emri","Kolun ters yönünden gelenler için GEÇ işareti","Yeterli güvenlikte duramayacak sürücüler ile kavşağa yeni girmiş olan ve kavşak içinde bulunan sürücüler dışında, tüm karayolunu kullananlar için DUR emri"],"dogru":4,"aciklama":"m.96/1: 'Görevli kişinin bir kolunu dik olarak yukarıya kaldırması; yeterli güvenlikte duramayacak sürücüler ile kavşağa yeni girmiş olan ve kavşak içinde bulunan sürücüler dışında, tüm karayolunu kullananlar için DUR emridir.'","kaynak":"KTY m.96","zorluk":"kolay"},
    {"id":"28-S-012","soru":"Karayolları Trafik Yönetmeliği'ne göre trafik görevlisinin kısa sesli tek veya fasılalı düdük çalması DUR emri anlamına gelir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.96: 'kısa sesli tek veya fasılalı düdük çalması uyarma, uzun sesli tek veya fasılalı düdük çalması DUR emridir.' Kısa düdük UYARI anlamındadır, DUR değildir.","kaynak":"KTY m.96","zorluk":"orta"},
    {"id":"28-S-013","soru":"Karayolları Trafik Yönetmeliği'ne göre kanlarındaki alkol miktarı hususi otomobil sürücülerinde ....(1).... promilin, diğer araç sürücülerinde ise ....(2).... promilin üzerinde olanların araç sürmesi yasaktır. Boşluklara sırasıyla gelmesi gereken değerler hangisidir?","siklar":["0.50 - 0.20","0.20 - 0.50","1,00 - 0.50","0.50 - 1,00","0.20 - 1,00"],"dogru":0,"aciklama":"m.97: '...kanlarındaki alkol miktarı 0.50 promilin üzerinde olan hususi otomobil sürücülerinin ve kanlarındaki alkol miktarı 0.20 promilin üstünde olan diğer araç sürücülerinin karayolunda araç sürmeleri yasaktır.'","kaynak":"KTY m.97","zorluk":"kolay"},
    {"id":"28-S-014","soru":"Karayolları Trafik Yönetmeliği'ne göre yasal sınırların üzerinde alkollü araç kullandığı, son ihlalden geriye doğru beş yıl içinde ikinci defa tespit edilen sürücünün belgesi ne kadar süreyle geri alınır?","siklar":["6 ay","2 yıl","1 yıl","3 yıl","5 yıl"],"dogru":1,"aciklama":"m.97/b: '...son ihlalin gerçekleştiği tarihten itibaren geriye doğru beş yıl içinde sürücü belgeleri birinci defasında altı ay, ikinci defasında iki yıl, üç veya üçten fazlasında ise her seferinde beşer yıl süreyle geri alınır.'","kaynak":"KTY m.97","zorluk":"orta"},
    {"id":"28-S-015","soru":"Karayolları Trafik Yönetmeliği'ne göre 1,00 promilin üzerinde alkollü olduğu tespit edilen ve idari işlem yapılan sürücü hakkında ayrıca ne yapılır?","siklar":["Sadece sürücü belgesi süresiz iptal edilir","Sadece idari para cezası artırılarak uygulanır","Türk Ceza Kanunu 179 uncu maddesinin üçüncü fıkrası hükümlerine göre adli işlem yapılmak üzere mahalli zabıtaya teslim edilir","Aracı süresiz olarak trafikten men edilir","Doğrudan sulh ceza hâkimliğine sevk edilmeden dosya kapatılır"],"dogru":2,"aciklama":"m.97/d: '1,00 promilin üzerinde alkollü olduğu tespit edilen ... sürücüler, haklarında ayrıca 5237 sayılı Türk Ceza Kanununun 179 uncu maddesinin üçüncü fıkrası hükümlerine göre adli işlem yapılmak üzere mahalli zabıtaya teslim edilir.'","kaynak":"KTY m.97","zorluk":"orta"},
    {"id":"28-S-016","soru":"Karayolları Trafik Yönetmeliği'ne göre ticari yük veya yolcu taşımacılığı yapan şoförler 24 saatlik süre içinde toplam ....(1).... saatten, devamlı olarak ....(2).... saatten fazla araç süremezler. Boşluklara sırasıyla gelmesi gereken değerler hangisidir?","siklar":["4,5 - 9","11 - 4,5","9 - 6","9 - 4,5","8 - 4"],"dogru":3,"aciklama":"m.98: '24 saatlik herhangi bir süre içinde; toplam olarak 9 saatten ve devamlı olarak 4,5 saatten fazla araç sürmeleri yasaktır.'","kaynak":"KTY m.98","zorluk":"orta"},
    {"id":"28-S-017","soru":"Karayolları Trafik Yönetmeliği'ne göre ticari yük veya yolcu taşımacılığı yapan şoförler, en fazla 6 günlük araç kullanma süresinden sonra en az 24 saat süren 1 günlük hafta tatili kullanmak zorundadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.98: 'Bu şoförler en fazla 6 günlük araç kullanma süresinden sonra 1 günlük hafta tatilini kullanmak zorundadırlar. Hafta tatili en az 24 saattir.'","kaynak":"KTY m.98","zorluk":"kolay"},
    {"id":"28-S-018","soru":"Karayolları Trafik Yönetmeliği'ne göre otomobillerin (M1 sınıfı) otoyollardaki azami hız sınırı kaç km/saattir?","siklar":["90","100","110","130","120"],"dogru":4,"aciklama":"m.100: Otomobil (M1) hız sınırları yerleşim yeri içinde 50, şehirlerarası çift yönlü 90, bölünmüş yollarda 110, otoyollarda 120 km/s'tir.","kaynak":"KTY m.100","zorluk":"kolay"},
    {"id":"28-S-019","soru":"Karayolları Trafik Yönetmeliği'ne göre zorunlu haller dışında şehirlerarası karayolunu kullanan motorlu araçlarda araç cinsi gözetilmeksizin asgari hız sınırı ....(1).... km/s, otoyollarda ise ....(2).... km/s'tir. Boşluklara sırasıyla gelmesi gereken değerler hangisidir?","siklar":["15 - 40","40 - 15","20 - 50","10 - 30","15 - 50"],"dogru":0,"aciklama":"m.100: 'Zorunlu haller dışında şehirlerarası karayolunu kullanan motorlu araçlarda araç cinsi gözetilmeksizin asgari hız sınırı 15 km/s, otoyollarda ise 40 km/s'tir.'","kaynak":"KTY m.100","zorluk":"orta"},
    {"id":"28-S-020","soru":"Karayolları Trafik Yönetmeliği'ne göre trafik zabıtası, işaret levhası veya ışıklı işaret cihazı bulunmayan kavşaklarda aşağıdaki yol verme kurallarından hangisi Yönetmelikte sayılmamıştır?","siklar":["Bütün sürücüler geçiş üstünlüğüne sahip araçlara geçiş hakkını verir","Hızlı giden araç, yavaş giden araca göre her zaman önceliklidir","Bütün sürücüler doğru geçmekte olan tramvaylara geçiş hakkını verir","Tali yoldan ana yola çıkan sürücüler, ana yoldan gelen araçlara geçiş hakkını verir","Dönel kavşağa gelen sürücüler, dönel kavşak içindeki araçlara geçiş hakkını verir"],"dogru":1,"aciklama":"m.109/b'de sayılan sıralamada üstünlüklü araç, doğru geçen tramvay, tali-ana yol, bölünmüş yol, dönel kavşak, iz/mülkten çıkma ve dönüş yapma hükümleri yer alır; 'hızlı giden aracın her zaman öncelikli olması' şeklinde bir kural metinde bulunmamaktadır.","kaynak":"KTY m.109","zorluk":"zor"},
    {"id":"28-S-021","soru":"Karayolları Trafik Yönetmeliği'ne göre kavşak kollarının trafik yoğunluğu bakımından farklı olduğu işaretlerle belirlenmemişse, motorsuz araç sürücüleri kime geçiş hakkı vermek zorundadır?","siklar":["Yayalara","Bisikletlilere","Motorlu araçlara","Dönüş yapan sürücülere","Soldan gelen araçlara"],"dogru":2,"aciklama":"m.109/c/1: 'Motorsuz araç sürücüleri, motorlu araçlara ... geçiş hakkını vermek zorundadırlar.'","kaynak":"KTY m.109/c","zorluk":"orta"},
    {"id":"28-S-022","soru":"Karayolları Trafik Yönetmeliği'ne göre duraklama, bekleme amacıyla yapılıyorsa süresi en çok 10 dakikadır; bu sürenin geçirilmesi parketme sayılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.112: 'Duraklama, bekleme amacı ile yapılırsa, bunun süresi en çok 5 dakikadır. Bu sürenin geçirilmesi parketme sayılır.' Doğru süre 5 dakikadır, 10 dakika değildir.","kaynak":"KTY m.112","zorluk":"kolay"},
    {"id":"28-S-023","soru":"Karayolları Trafik Yönetmeliği'ne göre belirlenmiş yangın musluklarına her iki yönden kaç metrelik mesafe içinde park etmek yasaktır?","siklar":["15 metre","10 metre","20 metre","5 metre","25 metre"],"dogru":3,"aciklama":"m.115/4: 'Belirlenmiş yangın musluklarına her iki yönden 5 metrelik mesafe içinde' parketmek yasaktır.","kaynak":"KTY m.115","zorluk":"orta"},
    {"id":"28-S-024","soru":"Karayolları Trafik Yönetmeliği'ne göre geçiş üstünlüğü bulunan bir aracın duyulur veya görülür işaretini alan sürücüler ne yapmak zorundadır?","siklar":["Aracın hızını artırıp kavşağı hemen terk etmek","Sadece korna çalarak diğer sürücüleri uyarmak","Şeridi değiştirmeden aynı hızla ilerlemeye devam etmek","En yakın park yerine çekilip motoru durdurmak","Taşıt yolu üzerinde yer açmak, gerekiyorsa durmak ve bu araç tamamen geçinceye kadar beklemek"],"dogru":4,"aciklama":"m.142: '...araç sürücüleri bu araçların kolayca ilerlemelerini sağlamak için taşıt yolu üzerinde yer açmak, gerekiyorsa durmak ve bu araçlar tarafından tamamen geçilinceye kadar beklemek mecburiyetindedirler.'","kaynak":"KTY m.142","zorluk":"kolay"},
    {"id":"28-S-025","soru":"Karayolları Trafik Yönetmeliği'ne göre koruyucu tertibat kullanma zorunluluğuna ilişkin aşağıdakilerden hangisi yanlıştır?","siklar":["Bisiklet sürücülerinin de motosiklet sürücüleriyle aynı şekilde koruyucu eldiven takması zorunludur","Motosiklet ve motorlu bisiklet sürücülerinin koruma başlığı ve koruma gözlüğü takması zorunludur","Motosiklet sürücülerinin ve taşınmaları halinde yolcularının koruyucu eldiven takması zorunludur","M1 sınıfı otomobillerin bütün koltuklarında emniyet kemerinin bulundurulması ve kullanılması zorunludur","Geri gitme veya park yerlerinde 25 km/s'i geçmeyen hızla seyreden sürücüler emniyet kemeri takmak zorunda değildir"],"dogru":0,"aciklama":"m.150/b (Ek:RG-4/11/2025-33067): eldiven zorunluluğu yalnızca 'motosiklet sürücülerinin ve taşınmaları halinde yolcuların' takması şeklinde düzenlenmiştir; bisiklet sürücüleri bu bende dahil değildir. B (m.150/a: motosiklet ve motorlu bisiklette başlık+gözlük), C (m.150/b), D (m.150/c) ve E (m.150 üçüncü fıkra 2. bent, park/geri 25 km/s) maddede yer alır. Not: m.150/a'da bisikletlilerde koruma gözlüğü aranmadığından B şıkkı bilerek yalnız motosiklet ve motorlu bisikleti kapsayacak biçimde düzenlenmiştir.","kaynak":"KTY m.150","zorluk":"orta"},
    {"id":"28-S-026","soru":"Karayolları Trafik Yönetmeliği'ne göre ambulans sürücüsü, hasta veya yaralıya müdahale nedeniyle özel pozisyonda bulunsa dahi emniyet kemeri takmak zorundadır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.150: emniyet kemeri istisnası yalnız 'ambulanslarda sürücü ve yanındaki oturma yeri DIŞINDA kalan ve hasta veya yaralıya müdahale nedeniyle özel pozisyonlarda bulunan görevliler' için geçerlidir; ambulans sürücüsü bu istisnanın kapsamı dışında bırakıldığından her koşulda emniyet kemeri takmak zorundadır.","kaynak":"KTY m.150","zorluk":"zor"},
    {"id":"28-S-027","soru":"Karayolları Trafik Yönetmeliği'ne göre trafik kazalarında 'Kaza Tespit Tutanağı' düzenlemek hangi birimin görevidir?","siklar":["Mahalli genel zabıta","Trafik zabıtası (polis veya jandarma)","Belediye trafik birimleri","Karayolları Genel Müdürlüğü","Ulaştırma Bakanlığı"],"dogru":1,"aciklama":"m.154/a/2: 'Kaza nedenlerini, iz ve delillerini belirleyecek Kaza Tespit Tutanağı düzenlemek üzere de trafik zabıtasınca (polis veya jandarma), El konulur.'","kaynak":"KTY m.154","zorluk":"orta"},
    {"id":"28-S-028","soru":"Karayolları Trafik Yönetmeliği'ne göre aşağıdakilerden hangisi trafik kazalarında sürücünün asli kusurlu sayılmasına yol açan hallerden biri değildir?","siklar":["Kırmızı ışıklı trafik işaretinde geçme","Arkadan çarpma","Kazadan hemen sonra yetkililere haber verme","Geçme yasağı olan yerlerden geçme","Kavşaklarda geçiş önceliğine uymama"],"dogru":2,"aciklama":"m.157/a'da asli kusur sayılan haller arasında kırmızı ışıkta geçme (1), arkadan çarpma (4), geçme yasağı olan yerden geçme (5) ve kavşakta geçiş önceliğine uymama (8) sayılmıştır. 'Kazadan hemen sonra yetkililere haber verme' ise m.153'te düzenlenen kazaya karışanların bir YÜKÜMLÜLÜĞÜdür, bir kusur hali değildir.","kaynak":"KTY m.157","zorluk":"zor"},
    {"id":"28-S-029","soru":"Karayolları Trafik Yönetmeliği'ne göre polisin ve trafik teşkilatının görev alanı dışında kalan yerlerde trafik zabıtası yetkisini kim kullanır?","siklar":["Sadece il jandarma komutanı","Herhangi bir jandarma personeli","Belediye zabıtası","Trafik eğitimi almış subay, astsubay ve uzman jandarmalar","Sadece uzman erbaşlar"],"dogru":3,"aciklama":"m.166: 'polisin ve trafik teşkilatının görev alanı dışında kalan yerlerde de jandarma; trafik eğitimi almış subay, astsubay ve uzman jandarmalar tarafından ...' tutanak düzenlenir.","kaynak":"KTY m.166","zorluk":"orta"},
    {"id":"28-S-030","soru":"Karayolları Trafik Yönetmeliği'ne göre trafik kuralının ihlal edildiği tarihten geriye doğru bir yıl içinde toplam 100 ceza puanını ilk defa aşan sürücünün belgesi ....(1).... süreyle, ikinci defa aşan sürücünün belgesi ise ....(2).... süreyle geri alınır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["1 ay - 2 ay","4 ay - 6 ay","3 ay - 6 ay","2 ay - 1 yıl","2 ay - 4 ay"],"dogru":4,"aciklama":"m.167/a-b: 'Toplam 100 ceza puanını aştığı tespit edilen sürücülerin, sürücü belgeleri 2 ay süre ile geri alınır ... ikinci defa aştığı tespit edilen sürücülerin sürücü belgeleri 4 ay süre ile geri alınarak ...'","kaynak":"KTY m.167","zorluk":"orta"},
    {"id":"28-S-031","soru":"Karayolları Trafik Yönetmeliği'ne göre bir yıl içinde toplam 100 ceza puanını üçüncü defa aştığı tespit edilen sürücüler hakkında ne yapılır?","siklar":["Düzenlenecek bir tutanakla sulh ceza hâkimliklerine sevk edilir","Belgesi süresiz olarak iptal edilir","Belgesi 6 ay süreyle geri alınır","Sadece idari para cezası uygulanır","Psiko-teknik değerlendirmeye tabi tutulmadan belgesi iade edilir"],"dogru":0,"aciklama":"m.167/c: 'Toplam 100 ceza puanını üçüncü defa aştığı tespit edilen sürücüler bu konuda düzenlenecek bir tutanakla sulh ceza hakimliklerine sevk edilir ve mahkeme kararına göre işlem tesis edilir.'","kaynak":"KTY m.167","zorluk":"orta"},
    {"id":"28-S-032","soru":"Karayolları Trafik Yönetmeliği'ne göre sürücü belgesi sahibinin 5237 sayılı Türk Ceza Kanunu'nun 188, 190 ve 191 inci maddelerinde belirtilen suçlardan hüküm giymesi halinde sürücü belgesi ne zamana kadar geri alınır?","siklar":["Bir yıl süreyle","Bu suçlara ilişkin kayıtlar adli sicilinden silininceye kadar","Beş yıl süreyle","Mahkeme kararı temyiz edilene kadar","İki yıl süreyle"],"dogru":1,"aciklama":"m.168/b: '...bu suçlardan hüküm giymesi halinde, bu suçlara ilişkin kayıtlar adli sicilinden silininceye kadar sürücü belgesi geri alınır.'","kaynak":"KTY m.168","zorluk":"zor"},
    {"id":"28-S-033","soru":"Karayolları Trafik Yönetmeliği'ne göre belediyeler, kendilerine görev verilen hizmetlerin denetimi dışında trafiği denetleyebilir ve trafik suç ve ceza tutanağı düzenleyebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.16 son fıkra: 'Belediyeler bu madde ile görev verilen hizmetlerin denetimi dışında, trafiği denetleyemez ve hiçbir halde trafik suç ve ceza tutanağı düzenleyemezler.'","kaynak":"KTY m.16","zorluk":"orta"},
    {"id":"28-S-034","soru":"Karayolları Trafik Yönetmeliği'ne göre ilçe trafik komisyonuna hangi makam başkanlık eder?","siklar":["Vali","İlçe emniyet müdürü","Kaymakam","Belediye başkanı","Vali yardımcısı"],"dogru":2,"aciklama":"m.17: '...ilçelerde kaymakamın başkanlığında ... ilçe trafik komisyonu kurulur.' (İllerde ise vali veya yardımcısının başkanlığında il trafik komisyonu kurulur.)","kaynak":"KTY m.17","zorluk":"orta"},
    {"id":"28-S-035","soru":"Karayolları Trafik Yönetmeliği'ne göre karayollarında her iki taraftan sınır çizgisine ....(1).... metre mesafe içinde bağlantıyı sağlayan geçiş yolları yönünden, trafik güvenliğini etkileyecek yapı ve tesisler için o karayolunun yapım/bakım/işletme kuruluşundan izin alınması zorunludur. Boşluğa gelmesi gereken değer hangisidir?","siklar":["15 metre","25 metre","100 metre","50 metre","150 metre"],"dogru":3,"aciklama":"m.26: 'Karayollarında her iki taraftan sınır çizgisine 50 metre mesafe içinde bağlantıyı sağlayacak geçiş yolları yönünden; ... trafik güvenliğini etkileyecek yapı ve tesisler için, ... izin alınması zorunludur.'","kaynak":"KTY m.26","zorluk":"orta"},
    {"id":"28-S-036","soru":"Karayolları Trafik Yönetmeliği'ne göre ilk defa sürücü belgesi alanlar, belgenin alındığı tarihten itibaren ne kadar süreyle 'aday sürücü' kabul edilir?","siklar":["1 yıl","18 ay","3 yıl","5 yıl","2 yıl"],"dogru":4,"aciklama":"Ek Madde 3: 'ilk defa sürücü belgesi alanlar ... belgenin alındığı tarihten itibaren İKİ YIL süreyle ADAY SÜRÜCÜ kabul edilir.'","kaynak":"KTY Ek m.3","zorluk":"zor"},
    {"id":"28-S-037","soru":"Karayolları Trafik Yönetmeliği'ne göre 2918 sayılı Kanunda sayılan görevlilerin ve trafik tescil kuruluşlarının yetkilendirildiği haller hariç olmak üzere, sürücü belgelerinin geri alınmasına ve iptaline hangi merci karar verir?","siklar":["Sulh ceza hâkimlikleri","İl trafik komisyonu","Vali","Trafik zabıtası amiri","Emniyet Genel Müdürlüğü"],"dogru":0,"aciklama":"m.160: '...sürücü belgelerinin geri alınmasına ve iptaline SULH CEZA HÂKİMLİKLERİ karar verir.'","kaynak":"KTY m.160","zorluk":"orta"},
    {"id":"28-S-038","soru":"Karayolları Trafik Yönetmeliği'ne göre Türk Silahlı Kuvvetlerine ait araçların karıştığı trafik kazalarında bir askeri temsilcinin bulundurulması mecburidir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.156: 'Türk Silahlı Kuvvetlerine ait araçların karıştığı kazalarda bir askeri temsilcinin bulundurulması mecburidir.'","kaynak":"KTY m.156","zorluk":"orta"},
    {"id":"28-S-039","soru":"Karayolları Trafik Yönetmeliği'ne göre motorlu araç sürücülerinin yetiştirilmesi için sürücü kursları açılmasına izin vermek ve bu kurslarda eğitilen adayların sınavlarını yaparak başarılı olanlara sertifika verilmesini sağlamak hangi bakanlığın görevidir?","siklar":["Milli Eğitim Bakanlığı","Ulaştırma Bakanlığı","İçişleri Bakanlığı","Sağlık Bakanlığı","Gençlik ve Spor Bakanlığı"],"dogru":0,"aciklama":"m.10/b-c: Milli Eğitim Bakanlığının görev ve yetkileri arasında '123 üncü madde gereğince sürücü kursları açmak, özel sürücü kursu açılmasına izin vermek, bunları her safhada denetlemek' ve 'özel motorlu taşıt sürücüleri kurslarında eğitilen sürücü adaylarının teorik ve uygulamalı sınavlarını yapmak ve başarılı olanlara sertifika verilmesini sağlamak' sayılmıştır.","kaynak":"KTY m.10","zorluk":"kolay"},
    {"id":"28-S-040","soru":"Karayolları Trafik Yönetmeliği'ne göre Karayolları Genel Müdürlüğü, yapım ve bakımından sorumlu olduğu karayollarında bu Yönetmelikte belirlenen hız sınırlarının üstünde veya altında hız sınırları belirleyip işaretleyebilmek için hangi kurumun uygun görüşünü almak zorundadır?","siklar":["Ulaştırma Bakanlığı","İçişleri Bakanlığı","İl trafik komisyonu","Emniyet Genel Müdürlüğü","Milli Eğitim Bakanlığı"],"dogru":1,"aciklama":"m.11/d: '...İçişleri Bakanlığının uygun görüşü alınmak suretiyle, bu Yönetmelikte belirlenen hız sınırlarının üstünde veya altında hız sınırları belirlemek ve işaretlemek.'","kaynak":"KTY m.11/d","zorluk":"orta"},
    {"id":"28-S-041","soru":"Karayolları Trafik Yönetmeliği'ne göre Ulaştırma Bakanlığının ilgili birimleri, Karayolları Trafik Kanununun ....(1).... inci maddesi hükümlerine aykırı hareket edenler hakkında tutanak düzenleyerek idari para cezası verir; ayrıca trafik zabıtasının görev ve yetkileri saklı kalmak üzere araçların ....(2).... kontrollerini yapar veya yaptırır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["65 - hız ve muayene","47 - ağırlık ve boyut","35 - ağırlık ve boyut","35 - alkol ve promil","18 - ağırlık ve boyut"],"dogru":2,"aciklama":"m.13/ç,e: 'Karayolları Trafik Kanununun 35 inci maddesi hükümlerine aykırı hareket edenler hakkında tutanak düzenleyerek idarî para cezası vermek ... araçların ağırlık ve boyut kontrollerini yapmak veya yaptırmak ve denetlemek, aykırı görülen hususlarla ilgili olarak sorumlular hakkında idarî para cezasına dair tutanak düzenlemek.'","kaynak":"KTY m.13","zorluk":"orta"},
    {"id":"28-S-042","soru":"Karayolları Trafik Yönetmeliği'ne göre köy yolları için sayılan görev ve hizmetlerden mecburi ve gerekli görülenler, orman yolları için de uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.14/a son fıkra: 'Köy yolları için sayılan görev ve hizmetlerden mecburi ve gerekli görülenler, orman yolları için de uygulanabilir.'","kaynak":"KTY m.14","zorluk":"kolay"},
    {"id":"28-S-043","soru":"Karayolları Trafik Yönetmeliği'ne göre belediyelerin trafik hizmetlerini yürüttüğü birimler iş kapasitesine göre çeşitli şekillerde adlandırılır. Aşağıdakilerden hangisi bu adlandırmalardan biri değildir?","siklar":["Belediye trafik şube müdürlüğü","Belediye trafik şefliği","Belediye trafik büro amirliği","Belediye trafik daire başkanlığı","Belediye trafik memurluğu"],"dogru":3,"aciklama":"m.15: 'Bu birimler, belediyelerin iş kapasitesine göre \"Belediye trafik şube müdürlüğü\", \"Belediye trafik şefliği\" veya \"Belediye trafik memurluğu\" olarak adlandırılır. Büyük illerde belediye trafik şube müdürlüklerine bağlı belediye trafik büro amirlikleri de oluşturulabilir.' 'Daire başkanlığı' adlandırması metinde yer almaz.","kaynak":"KTY m.15","zorluk":"orta"},
    {"id":"28-S-044","soru":"Karayolları Trafik Yönetmeliği'ne göre aşağıdakilerden hangisi il ve ilçe trafik komisyonunun görev ve yetkilerinden biri değildir?","siklar":["Trafik kural ve yasaklarını ihlal edenler hakkında idari para cezası karar tutanağı düzenlemek","Belediye sınırları içinde ticari amaçla çalıştırılacak yolcu ve yük taşıtlarının güzergahlarını tespit etmek","Boş alan, arazi ve arsaları geçici otopark yeri olarak ilan etmek","Karayollarının bir kısmının veya tamamının kapatılmasına karar vermek","Karayollarında en çok ve en az hız limitine göre yeniden hız sınırlarını belirlemek"],"dogru":0,"aciklama":"m.18/a-f'de sayılan görevler arasında güzergah/sayı tespiti (c), geçici otopark ilanı (d), yol kapatma kararı (e) ve hız sınırı belirleme (f) yer alır. İdari para cezası karar tutanağı düzenlemek ise m.161 uyarınca Emniyet Genel Müdürlüğünün trafik zabıtası personeli ile Jandarma Genel Komutanlığının yetkili kıldığı personelin görevidir; trafik komisyonuna ait bir görev değildir.","kaynak":"KTY m.18","zorluk":"zor"},
    {"id":"28-S-045","soru":"Karayolları Trafik Yönetmeliği'ne göre belediye sınırları içindeki karayolları kenarında yapılacak veya açılacak yapı ve tesisler için hangi izinler zorunludur?","siklar":["Yalnızca Karayolları Genel Müdürlüğünden izin alınması yeterlidir","Yalnızca il trafik komisyonundan onay alınması yeterlidir","Yalnızca Ulaştırma Bakanlığından izin alınması yeterlidir","İzin alınmasına gerek yoktur, bildirim yeterlidir","Belediyelerden izin alınması ve ilgili durumlarda Karayolları Genel Müdürlüğünün ilgili bölge müdürlüğünden uygun görüş alınması"],"dogru":4,"aciklama":"m.27/a-b: '...için, a) Belediyelerden izin alınması ... b) ... Karayolları Genel Müdürlüğünün ... ilgili bölge müdürlüğünden uygun görüş almaları zorunludur.'","kaynak":"KTY m.27","zorluk":"orta"},
    {"id":"28-S-046","soru":"Karayolları Trafik Yönetmeliği'ne göre kişi, psiko-teknik değerlendirme raporu ile birlikte ....(1).... gün içinde psikiyatri uzmanına başvurmak zorundadır; belirtilen sürede başvurmayanlar ....(2).... ay boyunca tekrar teste kabul edilmez. Boşluklara sırasıyla gelmesi gereken değerler hangisidir?","siklar":["30 - 3","60 - 6","45 - 6","45 - 3","15 - 6"],"dogru":2,"aciklama":"m.79: 'Kişi düzenlenen psiko-teknik değerlendirme raporu ile birlikte kırkbeş gün içerisinde ... psikiyatri uzmanına başvurur. Belirtilen sürede psikiyatri muayenesi için başvurmayan kişiler altı ay boyunca tekrar teste kabul edilmez.'","kaynak":"KTY m.79","zorluk":"orta"},
    {"id":"28-S-047","soru":"Karayolları Trafik Yönetmeliği'ne göre uluslararası sürücü belgesi kaç yıl süreyle geçerlidir ve kimler tarafından verilir?","siklar":["1 yıl - Türkiye Turing ve Otomobil Kurumu","5 yıl - Emniyet Genel Müdürlüğü","2 yıl - Ulaştırma Bakanlığı","3 yıl - İçişleri Bakanlığınca yetkilendirilen gerçek veya tüzel kişiler","10 yıl - trafik tescil kuruluşları"],"dogru":3,"aciklama":"m.80: 'Uluslararası sürücü belgesi ... üç yıl süre ile verilen ve verildiği ülke dışındaki ülkeler için geçerli olan sürücü belgesidir. Uluslararası sürücü belgeleri ... İçişleri Bakanlığınca yetkilendirilen gerçek veya tüzel kişilerce verilir.'","kaynak":"KTY m.80","zorluk":"kolay"},
    {"id":"28-S-048","soru":"Karayolları Trafik Yönetmeliği'ne göre G sınıfı hariç diğer sürücü belgelerinden herhangi birini almak isteyen sürücü adaylarının aldığı 'K' Sınıfı Sürücü Aday Belgesi, 1 yıl süreyle geçerlidir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.82: 'K Sınıfı Sürücü Aday Belgesi 6 ay süreyle geçerlidir.' Süre 1 yıl değil 6 aydır.","kaynak":"KTY m.82","zorluk":"kolay"},
    {"id":"28-S-049","soru":"Karayolları Trafik Yönetmeliği'ne göre B, C, C1, D ve D1 sınıfı sürücü belgesi sahipleri, araçlarını azami yüklü ağırlığı ....(1).... kilograma kadar olan (bu ağırlık dahil) hafif römork takarak da kullanabilirler. Boşluğa gelmesi gereken değer hangisidir?","siklar":["750","500","1.000","3.500","350"],"dogru":0,"aciklama":"m.86: 'B, C, C1, D ve D1 sınıfı sürücü belgesi sahipleri araçlarını, azami yüklü ağırlığı 750 kilograma kadar olan (750 kilogram dahil) hafif römork takarak da kullanabilirler.'","kaynak":"KTY m.86","zorluk":"orta"},
    {"id":"28-S-050","soru":"Karayolları Trafik Yönetmeliği'ne göre sürücü belgesi yenileme müracaatı sırasında eski belge geri alınır. Belge teslim edilinceye kadar araç kullanılabilmesi için verilebilecek 'Sürücü Belgesi Yerine Geçen Geçici Belge' kaç gün süreyle geçerlidir?","siklar":["5 gün","10 gün","30 gün","45 gün","15 gün"],"dogru":4,"aciklama":"m.87: 'Müracaatı tamamlananlara sürücü belgeleri teslim edilinceye kadar araç kullanabilmeleri için 15 gün süreyle geçerli olmak üzere \"Sürücü Belgesi Yerine Geçen Geçici Belge\" verilebilir.'","kaynak":"KTY m.87","zorluk":"zor"},
    {"id":"28-S-051","soru":"Karayolları Trafik Yönetmeliği'ne göre aşağıdaki yerlerden hangisinde önündeki aracı geçmek yasak DEĞİLDİR?","siklar":["Görüş yetersizliği olan tepe üstü ve dönemeçlerde","Bölünmüş, çok şeritli ve gidiş yönünde en az iki şeridi bulunan düz bir yolda","Yaya ve okul geçitlerine yaklaşırken","Kavşaklarda, demiryolu geçitlerinde ve buralara yaklaşırken","Gidiş ve geliş için birer şeridi bulunan iki yönlü trafiğin kullanıldığı köprü ve tünellerde"],"dogru":1,"aciklama":"m.104'te sayılan geçme yasağı yerleri: işaretle yasaklanan yerler, görüş yetersiz tepe üstü/dönemeç, yaya/okul geçidine yaklaşma, kavşak/demiryolu geçidine yaklaşma, tek şeritli iki yönlü köprü/tünel. Bölünmüş, çok şeritli düz bir yol bu sayılan yasak yerler arasında değildir; aksine m.103/d'ye göre burada şerit değiştirmeden hızlı gitmek geçme bile sayılmaz.","kaynak":"KTY m.104","zorluk":"orta"},
    {"id":"28-S-052","soru":"Karayolları Trafik Yönetmeliği'ne göre tehlikeli madde taşıyan araç sürücüleri, yerleşim birimleri dışındaki karayollarında diğer araçları en az kaç metre mesafeden takip etmek zorundadır?","siklar":["15 metre","25 metre","100 metre","50 metre","Hızın yarısı kadar metre; farklı bir asgari mesafe yoktur"],"dogru":3,"aciklama":"m.107: 'Tehlikeli madde taşıyan araç sürücüleri, yerleşim birimleri dışındaki karayollarında diğer araçları, en az 50 metre mesafeden takip etmek zorundadırlar.'","kaynak":"KTY m.107","zorluk":"orta"},
    {"id":"28-S-053","soru":"Karayolları Trafik Yönetmeliği'ne göre sadece maddi hasarla sonuçlanan bir kazada, kazaya karışan sürücülerin tamamı yetkililerin gelmesine gerek görmeyip kendi aralarında anlaşırlarsa ne yapabilirler?","siklar":["Olay yerini terk edip hiçbir belge düzenlemeyebilirler","Doğrudan sulh ceza hâkimliğine başvurmak zorundadırlar","'Maddi Hasarlı Trafik Kazası Tespit Tutanağı' düzenleyip birlikte imzalayarak olay yerinden ayrılabilirler","Kaza Tespit Tutanağını yalnızca trafik zabıtası düzenleyebilir, taraflar düzenleyemez","Zorunlu olarak en yakın trafik kuruluşuna giderek tutanak talep etmelidirler"],"dogru":2,"aciklama":"m.152: '...kazaya karışan sürücülerin tümü, yetkililerin gelmesine gerek görmez ve aralarında kazayı kendi düzenleyecekleri tutanakla tespit etmek noktasında anlaşırlarsa \"Maddi Hasarlı Trafik Kazası Tespit Tutanağı\" düzenleyip birlikte imza altına alarak olay yerinden ayrılabilirler.' Bu şekilde ayrılan taraflar sonradan yetkililerden kaza tespit tutanağı düzenlenmesini isteyemezler.","kaynak":"KTY m.152","zorluk":"orta"},
    {"id":"28-S-054","soru":"Karayolları Trafik Yönetmeliği'ne göre trafik kazası tespit tutanağını düzenleyenler, taraflar için kusur oranını yüzdesel olarak belirtmek zorundadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.156/a-3: 'Tutanak düzenleyenler, tutanakta taraflar için kusur oranı belirtmeksizin sadece kazanın oluşumunda kimin hangi trafik kuralını ihlal ettiğini belirtirler.' Kusur oranı belirtilmez, yalnızca ihlal edilen kural yazılır.","kaynak":"KTY m.156","zorluk":"orta"},
    {"id":"28-S-055","soru":"Karayolları Trafik Yönetmeliği'ne göre öğrencilerin okul geçidi görevlisi olabilmesi için kaç yaşını doldurmuş olması gerekir ve bu görev ücret karşılığı mıdır?","siklar":["15 yaşını doldurmuş olmak; ücretli bir görevdir","12 yaşını doldurmuş olmak; fahri (ücretsiz) bir görevdir","14 yaşını doldurmuş olmak; asgari ücretle görevlendirilir","10 yaşını doldurmuş olmak; ücretli bir görevdir","18 yaşını doldurmuş olmak; fahri bir görevdir"],"dogru":1,"aciklama":"m.178/a-1: 'İlk ve orta dereceli okullarda istekli öğretmenler, veliler ile 12 yaşını doldurmuş öğrenciler okul geçidi görevlisi olabilirler.' Aynı maddede: 'Okul geçidi görevi fahri bir görev olup, bu hizmetin karşılığında ücret talep edilmez.'","kaynak":"KTY m.178","zorluk":"kolay"},
  ],
  53: [
    {"id":"29-S-001","soru":"Taşınır Kültür ve Tabiat Varlıklarını Bulanlara, Haber Verenlere ve Yakalayan Kamu Görevlilerine Verilecek İkramiye ile İlgili Yönetmelik'e göre, taşınır kültür veya tabiat varlığı bulunduğunu bilenlerin bunu ilgili mercilere haber vermesi için öngörülen azami süre kaç gündür?","siklar":["7 gün","15 gün","30 gün","3 gün","60 gün"],"dogru":3,"aciklama":"m.3: '...bunu en geç üç gün içinde en yakın müzeye, köyde muhtara veya diğer yerlerde mülki idare amirlerine haber verenlere;...' Haber verme süresi üç gündür.","kaynak":"İkramiye Yön. m.3","zorluk":"kolay"},
    {"id":"29-S-002","soru":"Aynı Yönetmeliğe göre, aşağıdakilerden hangisi taşınır kültür ve tabiat varlığının bulunduğunun haber verilebileceği mercilerden biridir?","siklar":["Cumhuriyet başsavcılığı","İl jandarma komutanlığı","Mülki idare amiri","Kültür ve Turizm Bakanlığı merkez teşkilatı","İl özel idaresi"],"dogru":2,"aciklama":"m.3: haber verilecek merciler 'en yakın müze, köyde muhtar, diğer yerlerde mülki idare amirleri' olarak sınırlı biçimde sayılmıştır. Mülki idare amiri bunlardan biridir.","kaynak":"İkramiye Yön. m.3","zorluk":"orta"},
    {"id":"29-S-003","soru":"Aynı Yönetmeliğe göre, taşınır kültür veya tabiat varlığının bulanın kendi mülkü içinde bulunması halinde uygulanacak sonuç aşağıdakilerden hangisidir?","siklar":["Bedelin %80'i bulana ikramiye olarak ödenir","Bedelin %40'ı bulana ikramiye olarak ödenir","Değeri usulüne göre tespit edilip ödenir, ayrıca ikramiye verilmez","Varlık bedelsiz olarak müzeye devredilir","Varlık belge ile bulana iade edilir"],"dogru":2,"aciklama":"m.3(a): 'Varlık, bulanın mülkü içinde ise; ... tespit edilecek değeri usulüne göre ödenerek müzelerce satın alınır. Ayrıca ikramiye verilmez.'","kaynak":"İkramiye Yön. m.3/a","zorluk":"orta"},
    {"id":"29-S-004","soru":"Aynı Yönetmeliğe göre, varlık başkasının mülkü içinde bulunmuşsa takdir edilen bedelin ....(1).... bulan ile mülk sahibi arasında eşit paylaştırılır; varlık Devlete ait arazide bulunmuşsa bedelin ....(2).... bulana ikramiye olarak ödenir. Boşluklara sırasıyla gelmesi gereken oranlar hangisidir?","siklar":["%40 - %80","%80 - %40","%50 - %50","%30 - %70","%80 - %20"],"dogru":1,"aciklama":"m.3(b): '...bedelin %80'i ikramiye olarak bulan ile mülk sahibi arasında eşit olarak paylaştırılır.' m.3(c): '...bedelin %40'ı bulana ikramiye olarak ödenir.'","kaynak":"İkramiye Yön. m.3/b-c","zorluk":"orta"},
    {"id":"29-S-005","soru":"Aynı Yönetmeliğe göre, varlık başkasının mülkü içinde bulunmuşsa takdir edilen bedelin %80'i, bulan ile mülk sahibi arasında eşit olarak paylaştırılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3(b) hükmü birebir bu şekildedir: bedelin %80'i bulan ile mülk sahibi arasında eşit paylaştırılır.","kaynak":"İkramiye Yön. m.3/b","zorluk":"kolay"},
    {"id":"29-S-006","soru":"Aynı Yönetmeliğe göre, haber verilen varlığın korunması gerekli nitelikte kültür ve tabiat varlığı olmadığının anlaşılması halinde uygulanacak işlem nedir?","siklar":["Varlık, müzelerce verilecek bir belge ile sahibine iade edilir","Varlık bedeli ödenerek Devletçe satın alınır","Varlık doğrudan imha edilir","Varlık süresiz olarak müzede saklanır, sahibine iade edilmez","Varlığın bedelinin %40'ı bulana ödenir"],"dogru":0,"aciklama":"m.3(d): '...korunması gerekli nitelikte kültür ve tabiat varlığı olmadığı takdirde sahiplerine, müzelerce verilecek bir belge ile iade olunur.'","kaynak":"İkramiye Yön. m.3/d","zorluk":"zor"},
    {"id":"29-S-007","soru":"Aynı Yönetmeliğe göre, belge ile iade olunan varlık sahibince ....(1).... içinde alınmazsa, varlık müzelerde saklanabilir veya usulüne uygun olarak ....(2).... satılabilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["altı ay - Devletçe","bir yıl - müzece","üç yıl - Devletçe","bir yıl - bulana","bir yıl - Devletçe"],"dogru":4,"aciklama":"m.3(d): 'Bir yıl içinde sahiplerince alınmayan varlıklar müzelerde saklanabilir veya usulüne uygun olarak Devletçe satılabilirler.'","kaynak":"İkramiye Yön. m.3/d","zorluk":"orta"},
    {"id":"29-S-008","soru":"Aynı Yönetmeliğe göre, gizlenmiş sayılan varlığın tespit edilen değerinin 5.000 liraya kadar olan kısmı için uygulanacak ikramiye oranı yüzde kaçtır?","siklar":["%10","%15","%25","%30","%7,5"],"dogru":3,"aciklama":"m.4(a): '5.000 liraya kadar %30'. Kademeli tabloda en yüksek oran ilk dilime (5.000 liraya kadar) aittir.","kaynak":"İkramiye Yön. m.4/a","zorluk":"orta"},
    {"id":"29-S-009","soru":"Aynı Yönetmelikte, 1905 sayılı Kanunda belirlenen kademeli ikramiye oranları esas alındığında, aşağıdaki tutar-oran eşleştirmelerinden hangisi bu Yönetmelikte yer almamaktadır?","siklar":["5.000 liraya kadar - %30","25.000 liraya kadar (5.000'den yukarı kısım) - %25","50.000 liraya kadar (25.000'den yukarı kısım) - %20","100.000 liraya kadar (50.000'den yukarı kısım) - %10","100.000 liradan yukarı kısım - %7,5"],"dogru":2,"aciklama":"m.4(c): '50.000 liraya kadar (25.000 liradan yukarı olan kısmı için) %15' olarak düzenlenmiştir, %20 değildir. Diğer dört eşleştirme metinle birebir örtüşür.","kaynak":"İkramiye Yön. m.4/a-e","zorluk":"zor"},
    {"id":"29-S-010","soru":"Aynı Yönetmeliğe göre, hesaplanan ikramiye tutarı haber veren ile yakalayan kamu görevlisi arasında nasıl uygulanır?","siklar":["İkisine ayrı ayrı tam tutar üzerinden ikramiye ödenir","Toplam tutar ikisi arasında eşit bölünür","Tutarın tamamı yalnızca yakalayan kamu görevlisine ödenir","Tutarın tamamı yalnızca haber verene ödenir","Tutar, mülki idare amirinin takdirine göre dağıtılır"],"dogru":0,"aciklama":"m.4: 'Oranlarındaki miktarı, haber veren ve yakalayan şahıslara ayrı ayrı ikramiye olarak ödenir.' Her iki taraf ayrı ayrı tam tutarı alır, aralarında bölüşülmez.","kaynak":"İkramiye Yön. m.4","zorluk":"orta"},
    {"id":"29-S-011","soru":"Aynı Yönetmeliğe göre, gizlenmiş sayılan varlığı haber veren kişi birden fazla ise, hesaplanan ikramiye tutarının tamamı bu kişilerden yalnızca ilk haber verene ödenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4: '...haber verenler ve gerekse yakalayan kamu görevlilerinin birden fazla olmaları halinde hesap edilen ikramiye aralarında eşit olarak paylaştırılır.' Tamamı tek kişiye değil, eşit paylaştırılır.","kaynak":"İkramiye Yön. m.4","zorluk":"orta"},
    {"id":"29-S-012","soru":"Aynı Yönetmeliğe göre aşağıdakilerden hangisi için ihbar ikramiyesi ödenmez?","siklar":["Başkasının mülkünde bulunan ve süresi içinde haber verilen taşınır varlık","Devlete ait arazide bulunan taşınır varlık","Gizlenmiş sayılan varlığı yakalayan kamu görevlisi","Taşınmaz kültür ve tabiat varlıkları","Gizlenmiş sayılan varlığı süresinde haber veren kişi"],"dogru":3,"aciklama":"m.5: 'Taşınmaz kültür ve tabiat varlıkları ile, nerede bulunursa bulunsun varlığı Bakanlıkça daha önceden bilinen taşınır kültür ve tabiat varlıkları için ihbar ikramiyesi ödenmez.' A/B/C/E hallerinde m.3 veya m.4 uyarınca ikramiye/bedel ödenir; yalnızca taşınmaz varlıklar için ihbar ikramiyesi hiç ödenmez.","kaynak":"İkramiye Yön. m.5","zorluk":"kolay"},
    {"id":"29-S-013","soru":"Aynı Yönetmeliğe göre, varlığı Bakanlıkça önceden bilinen bir taşınır kültür varlığını haber veren kişiye ihbar ikramiyesi ödenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5: '...nerede bulunursa bulunsun varlığı Bakanlıkça daha önceden bilinen taşınır kültür ve tabiat varlıkları için ihbar ikramiyesi ödenmez.'","kaynak":"İkramiye Yön. m.5","zorluk":"orta"},
    {"id":"29-S-014","soru":"Aynı Yönetmeliğin bütünü dikkate alındığında aşağıdaki ifadelerden hangisi yanlıştır?","siklar":["Haber verme süresi en geç üç gündür","Bulanın kendi mülkünde bulunan varlık için ikramiye verilmez, yalnız değeri ödenir","Başkasının mülkünde bulunan varlıkta bedelin %80'i bulan ile mülk sahibi arasında eşit paylaştırılır","Devlete ait arazide bulunan varlıkta bedelin %40'ı bulana ödenir","Taşınmaz kültür varlıkları için de ihbar ikramiyesi bedelin %40'ı oranında ödenir"],"dogru":4,"aciklama":"m.5 gereği taşınmaz kültür ve tabiat varlıkları için ihbar ikramiyesi hiç ödenmez; '%40 oranında ödenir' ifadesi yanlıştır. Diğer dört ifade (A: m.3, B: m.3/a, C: m.3/b, D: m.3/c) metinle birebir örtüşür.","kaynak":"İkramiye Yön. m.3, m.5","zorluk":"zor"},
    {"id":"29-S-015","soru":"Aynı Yönetmeliğe göre, bir taşınır kültür varlığının Devlete ait arazide bulunması halinde uygulanacak ikramiye ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Bedelin %80'i bulan ile Hazine arasında eşit paylaştırılır","Bedelin %40'ı yalnızca bulana ödenir","Bedelin %40'ı bulan ile mülki idare amiri arasında eşit paylaştırılır","Bedelin %80'i yalnızca bulana ödenir","Bedelin %40'ı mülk sahibine ödenir"],"dogru":1,"aciklama":"m.3(c): 'Varlık Devlete ait arazide bulunmuş ise, ilgili Yönetmeliğine göre takdir olunacak bedelin %40'ı bulana ikramiye olarak ödenir.' Bu oran paylaştırılmaz, tamamı bulana aittir.","kaynak":"İkramiye Yön. m.3/c","zorluk":"zor"},
    {"id":"29-S-016","soru":"Taşınır Kültür ve Tabiat Varlıklarını Bulanlara, Haber Verenlere ve Yakalayan Kamu Görevlilerine Verilecek İkramiye ile İlgili Yönetmelik'in 3. maddesine göre, taşınır kültür veya tabiat varlığı bulunduğunu bilen veya varlıktan yeni haberdar olan ve haber verme hükmü kapsamında sayılan kişiler kimlerdir?","siklar":["Yalnızca köy muhtarları","Yalnızca mülki idare amirleri","Yalnızca müze görevlileri","Malik veya zilyetler","Yalnızca kamu görevlileri"],"dogru":3,"aciklama":"m.3: '...taşınır kültür ve tabiat varlığı bulunduğunu bilenler veya varlığından yeni haberdar olan malik veya zilyetlerden; bunu en geç üç gün içinde... haber verenlere...' Haber verme hükmü kapsamındaki kişiler malik veya zilyetlerdir.","kaynak":"İkramiye Yön. m.3 (giriş fıkrası)","zorluk":"kolay"},
    {"id":"29-S-017","soru":"Aynı Yönetmeliğe göre, süresi içinde haber verilmediği için gizlenmiş sayılan ve usulüne göre tespit edilen değeri 30.000 lira olan bir varlık için, 1905 sayılı Kanunda belirlenen kademeli oranlara göre hesaplanacak toplam ikramiye tutarı kaç liradır?","siklar":["7.250 lira","9.000 lira","6.500 lira","7.750 lira","7.500 lira"],"dogru":0,"aciklama":"m.4(a-c): İlk 5.000 lira için %30 = 1.500 lira; 5.000-25.000 lira arası (20.000 lira) için %25 = 5.000 lira; 25.000-30.000 lira arası (5.000 lira) için %15 = 750 lira. Toplam: 1.500+5.000+750 = 7.250 liradır.","kaynak":"İkramiye Yön. m.4/a-c","zorluk":"zor"},
    {"id":"29-S-018","soru":"Aynı Yönetmeliğe göre, taşınır kültür veya tabiat varlığı üç günlük süre içinde haber verilirse Madde 3'teki mülkiyet esaslı ikramiye hükümleri; süresi içinde haber verilmediği için gizlenmiş sayılırsa Madde 4'teki kademeli oran hükümleri uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3 chapeau'da öngörülen 'en geç üç gün içinde haber verme' şartı m.3(a-d)'deki mülkiyet esaslı hükümleri; m.4 chapeau'daki 'süresi içinde haber verilmediğinden gizlenmiş sayılan varlıklar' ifadesi ise m.4'teki kademeli oran hükümlerini tetikler.","kaynak":"İkramiye Yön. m.3, m.4","zorluk":"orta"},
    {"id":"29-S-019","soru":"Aynı Yönetmeliğin 4. maddesine göre, nerede olursa olsun yeni bulunup da ....(1).... içinde haber verilmediğinden ....(2).... sayılan varlıkları haber verenler ile bunları yakalayan kamu görevlilerine ikramiye ödenir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir yıl - kayıp","süresi - gizlenmiş","üç gün - saklı","otuz gün - mektum","bir yıl - gizlenmiş"],"dogru":1,"aciklama":"m.4: 'Nerede olursa olsun yeni bulunup da süresi içinde haber verilmediğinden gizlenmiş sayılan varlıkları haber verenler ile...' Boşluklar sırasıyla 'süresi' ve 'gizlenmiş' olmalıdır.","kaynak":"İkramiye Yön. m.4 (giriş fıkrası)","zorluk":"orta"},
    {"id":"29-S-020","soru":"Aynı Yönetmeliğin 3. maddesine göre, madde kapsamındaki taşınır kültür ve tabiat varlığının Türkiye Cumhuriyeti sınırları içinde bulunabileceği yerler eksiksiz olarak aşağıdakilerden hangisinde sayılmıştır?","siklar":["Yalnızca yerüstünde","Yerüstünde, yeraltında ve sualtında","Yalnızca yeraltında ve sualtında","Yalnızca kamuya ait arazilerde","Yalnızca özel mülklerde"],"dogru":1,"aciklama":"m.3: 'Türkiye Cumhuriyeti sınırları içinde yerüstünde, yeraltında ve sualtında taşınır kültür ve tabiat varlığı bulunduğunu bilenler...' Madde üç ortamı da (yerüstü, yeraltı, sualtı) kapsar.","kaynak":"İkramiye Yön. m.3 (giriş fıkrası)","zorluk":"kolay"},
    {"id":"29-S-021","soru":"Aynı Yönetmeliğe göre, tespit edilen değeri tam olarak 100.000 lira olan bir varlıkta, 50.000 liradan yukarı kalan 50.000 liralık dilime hangi ikramiye oranı uygulanır?","siklar":["%7,5","%15","%10","%25","%30"],"dogru":2,"aciklama":"m.4(d): '100.000 liraya kadar (50.000 liradan yukarı kısmı için) %10.' Değer tam 100.000 liraya kadar olduğundan, 50.000-100.000 arası dilim d bendindeki %10 oranına tabidir; %7,5 oranı yalnızca 100.000 lirayı aşan kısma uygulanır.","kaynak":"İkramiye Yön. m.4/d-e","zorluk":"zor"},
    {"id":"29-S-022","soru":"Aynı Yönetmeliğin 3. maddesinin (d) bendine göre, korunması gerekli nitelikte olmadığı için sahibine iade olunan bir varlıkla ilgili aşağıdakilerden hangisi Yönetmelik hükümlerine uygun DEĞİLDİR?","siklar":["İade belgesi, varlık ile sahibini açıkça tanımlayabilecek nitelikte düzenlenir","Sahibi, belge ile iade olunan varlık üzerinde her türlü tasarrufta bulunabilir","Bir yıl içinde alınmayan varlık müzelerde saklanabilir","Varlık, hiçbir belge düzenlenmeden doğrudan sahibine teslim edilir","Bir yıl içinde alınmayan varlık usulüne uygun olarak Devletçe satılabilir"],"dogru":3,"aciklama":"m.3(d): '...sahiplerine, müzelerce verilecek bir belge ile iade olunur.' İade işlemi mutlaka bir belgeyle yapılır; belgesiz doğrudan teslim Yönetmelikte öngörülmemiştir. A, B, C, E ifadeleri metinle birebir örtüşür.","kaynak":"İkramiye Yön. m.3/d","zorluk":"zor"},
    {"id":"29-S-023","soru":"Aynı Yönetmeliğe göre, gizlenmiş sayılan varlıklar için uygulanacak kademeli ikramiye oranlarının belirlendiği düzenleme aşağıdakilerden hangisidir?","siklar":["Korunması Gerekli Taşınır Kültür ve Tabiat Varlıklarının Tasnifi, Tescili ve Müzelere Alınmaları Hakkında Yönetmelik","1905 sayılı Kanun","Bu Yönetmeliğin 3. maddesi","2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanunu","Kültür ve Turizm Bakanlığı tebliği"],"dogru":1,"aciklama":"m.4: '...usulüne göre tespit edilen değerin, 1905 Sayılı «Menkul ve Gayrimenkul Emval ile Bunların İntifa Haklarının ve Daimi Vergilerin Mektumlarını Haber Verenlere Verilecek İkramiyelere Dair Kanun»da belirlenen şekilde...' Kademeli oranlar 1905 sayılı Kanunda belirlenmiştir.","kaynak":"İkramiye Yön. m.4","zorluk":"orta"},
  ],
  54: [
    {"id":"30-S-001","soru":"Özel Güvenlik Hizmetlerine Dair Kanunun Uygulanmasına İlişkin Yönetmeliğe göre özel güvenlik komisyonuna kim başkanlık eder?","siklar":["Valinin görevlendireceği bir vali yardımcısı","İl emniyet müdürü","İl jandarma komutanı","Vali bizzat kendisi","Ticaret odası başkanı"],"dogru":0,"aciklama":"m.5: 'Özel güvenlik komisyonu, her ilde valinin görevlendireceği bir vali yardımcısının başkanlığında, il emniyet müdürlüğü, il jandarma komutanlığı, ticaret odası başkanlığı ve sanayi odası başkanlığının temsilcilerinden oluşur.' Başkan, valinin görevlendirdiği vali yardımcısıdır.","kaynak":"YON30 m.5","zorluk":"kolay"},
    {"id":"30-S-002","soru":"Özel Güvenlik Hizmetlerine Dair Kanunun Uygulanmasına İlişkin Yönetmeliğe göre aşağıdakilerden hangisi özel güvenlik komisyonunun temsilci üyelerinden biri değildir?","siklar":["İl emniyet müdürlüğü","Cumhuriyet başsavcılığı","İl jandarma komutanlığı","Ticaret odası başkanlığı","Sanayi odası başkanlığı"],"dogru":1,"aciklama":"m.5: Komisyon, vali yardımcısı başkanlığında 'il emniyet müdürlüğü, il jandarma komutanlığı, ticaret odası başkanlığı ve sanayi odası başkanlığının temsilcilerinden oluşur.' Cumhuriyet başsavcılığı bu sayımda yer almaz.","kaynak":"YON30 m.5","zorluk":"orta"},
    {"id":"30-S-003","soru":"Özel Güvenlik Hizmetlerine Dair Kanunun Uygulanmasına İlişkin Yönetmeliğe göre özel güvenlik komisyonu üyeleri, kararların oylanmasında çekimser oy kullanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5: 'Komisyon, üye tam sayısının yarısının bir fazlasıyla toplanır ve oy çokluğuyla karar alır. Oyların eşitliği halinde başkanın bulunduğu taraf çoğunluk sayılır ve çekimser oy kullanılamaz.' Çekimser oy açıkça yasaktır.","kaynak":"YON30 m.5","zorluk":"kolay"},
    {"id":"30-S-004","soru":"Yönetmeliğe göre komisyon, üye tam sayısının ....(1).... ile toplanır ve ....(2).... ile karar alır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["tamamı - oybirliği","üçte ikisi - oy çokluğu","yarısının bir fazlası - oy çokluğu","yarısı - oybirliği","dörtte üçü - oy çokluğu"],"dogru":2,"aciklama":"m.5: 'Komisyon, üye tam sayısının yarısının bir fazlasıyla toplanır ve oy çokluğuyla karar alır.' Toplantı yeter sayısı yarı+1, karar usulü oy çokluğudur.","kaynak":"YON30 m.5","zorluk":"orta"},
    {"id":"30-S-005","soru":"Özel Güvenlik Hizmetlerine Dair Kanunun Uygulanmasına İlişkin Yönetmeliğe göre aşağıdakilerden hangisi özel güvenlik komisyonunun görevlerinden biridir?","siklar":["Özel güvenlik şirketlerine faaliyet izni vermek","Özel güvenlik görevlilerine kimlik kartı basmak","Yazılı sınav sorularını hazırlamak","Azami personel sayısını, bulundurulacak silah ve teçhizatın miktar ve niteliğini belirlemek","İdari para cezası vermek"],"dogru":3,"aciklama":"m.6/c: Komisyonun görevleri arasında 'özel güvenlik hizmetini yerine getirecek azami personel sayısını, bulundurulabilecek veya taşınabilecek silah ve teçhizatın miktar ve niteliğini ... belirlemek' sayılmıştır.","kaynak":"YON30 m.6","zorluk":"kolay"},
    {"id":"30-S-006","soru":"Yönetmeliğe göre özel güvenlik izni için yapılan müracaatlar en geç kaç iş günü içinde neticelendirilir?","siklar":["5 iş günü","7 iş günü","15 iş günü","30 iş günü","10 iş günü"],"dogru":4,"aciklama":"m.8: 'Özel güvenlik izni için yapılan müracaatlar en geç on iş günü içinde neticelendirilir.'","kaynak":"YON30 m.8","zorluk":"kolay"},
    {"id":"30-S-007","soru":"Yönetmeliğe göre izin verilen yerlerde istihdam edilen personelin listesi ve özel güvenlik mali sorumluluk sigortası poliçesinin sureti, göreve başlama tarihinden itibaren ....(1).... içinde valiliğe verilir; geçici veya acil özel güvenlik izinlerinde ise ....(2).... verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on beş gün - müracaat sırasında","on gün - bir hafta içinde","otuz gün - on gün içinde","yedi gün - müracaat sırasında","beş gün - on beş gün içinde"],"dogru":0,"aciklama":"m.8: 'Özel güvenlik izni verilen kişilerde veya yerlerde istihdam edilen özel güvenlik personelinin listesi ve özel güvenlik mali sorumluluk sigortası poliçelerinin birer sureti, personelin göreve başladığı tarihten itibaren on beş gün içinde, geçici veya acil özel güvenlik izinlerinde ise müracaat sırasında valiliğe verilir.'","kaynak":"YON30 m.8","zorluk":"orta"},
    {"id":"30-S-008","soru":"Yönetmeliğe göre Komisyonca il genelinde verilen özel güvenlik görevlisi kadrosunun en fazla yüzde kaçı kadar geçici personel istihdam izni verilebilir?","siklar":["Yüzde 5","Yüzde 10","Yüzde 15","Yüzde 20","Yüzde 25"],"dogru":1,"aciklama":"m.8: '...Komisyonca il genelinde verilen özel güvenlik görevlisi kadrosunun %10'unu aşmayacak şekilde personel istihdam etme izni verilebilir.'","kaynak":"YON30 m.8","zorluk":"kolay"},
    {"id":"30-S-009","soru":"Yönetmeliğe göre özel güvenlik birimleri ve şirketleri, koruma ve güvenlik planlarını hizmetin başladığı tarihten itibaren en geç kaç gün içinde hazırlar?","siklar":["On gün","On beş gün","Otuz gün","Altmış gün","Doksan gün"],"dogru":2,"aciklama":"m.12: '...koruma ve güvenlik planlarını hizmetin başladığı tarihten itibaren en geç otuz gün içinde hazırlayarak ... hazır halde bulundurur.'","kaynak":"YON30 m.12","zorluk":"orta"},
    {"id":"30-S-010","soru":"Yönetmeliğe göre aşağıdakilerden hangisinde özel güvenlik temel eğitim şartı aranmaz?","siklar":["Sadece lise mezunu olanlarda","Askerlik hizmetini tamamlamış olanlarda","Üç yıl özel güvenlik şirketinde çalışmış olanlarda","Genel kolluk kuvvetlerinden veya Milli İstihbarat Teşkilatından emekli olanlarda","Sadece sağlık raporu bulunanlarda"],"dogru":3,"aciklama":"m.17: 'Genel kolluk kuvvetlerinden ve Milli İstihbarat Teşkilatından emekli olanlar ile en az beş yıl fiilen bu görevlerde çalıştıktan sonra kendi istekleri ile görevlerinden ayrılmış olanlarda, özel güvenlik temel eğitim şartı ... aranmaz.'","kaynak":"YON30 m.17","zorluk":"orta"},
    {"id":"30-S-011","soru":"Yönetmeliğe göre genel kolluk kuvvetlerinden veya MİT'ten emekli olmayıp bu görevlerde en az ....(1).... yıl fiilen çalıştıktan sonra ....(2).... görevinden ayrılmış olanlarda da temel eğitim şartı aranmaz. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üç yıl - re'sen","on yıl - emeklilik nedeniyle","iki yıl - kendi isteğiyle","yedi yıl - kendi isteğiyle","beş yıl - kendi isteğiyle"],"dogru":4,"aciklama":"m.17: '...en az beş yıl fiilen bu görevlerde çalıştıktan sonra kendi istekleri ile görevlerinden ayrılmış olanlarda ... özel güvenlik temel eğitim şartı ... aranmaz.'","kaynak":"YON30 m.17","zorluk":"zor"},
    {"id":"30-S-012","soru":"Yönetmeliğe göre özel güvenlik kimlik kartları, güvenlik soruşturmasının olumlu olması ve yenileme eğitim sertifikasının ibrazı halinde kaç yılda bir yeniden düzenlenir?","siklar":["Beş yılda bir","İki yılda bir","Üç yılda bir","On yılda bir","Her yıl"],"dogru":0,"aciklama":"m.21: 'Kimlik kartları ... her beş yılda bir yenilenecek güvenlik soruşturması ve arşiv araştırması sonucunun olumlu olması ve özel güvenlik yenileme eğitim sertifikasının ibrazı halinde ... her beş yılda bir yeniden düzenlenir.'","kaynak":"YON30 m.21","zorluk":"kolay"},
    {"id":"30-S-013","soru":"Yönetmeliğe göre özel güvenlik şirketlerince kullanılacak üniforma ve üniformayı tamamlayan unsurlar ile teçhizat kim tarafından onaylanır?","siklar":["İlgili özel güvenlik komisyonu","Bakanlık","Vali","Emniyet Genel Müdürlüğü","Ticaret odası başkanlığı"],"dogru":1,"aciklama":"m.22: 'Üniforma ve üniformayı tamamlayan unsurlar ve teçhizat özel güvenlik birimlerince belirlendikten sonra, Komisyonun onayına sunulur ... Özel güvenlik şirketlerince kullanılacak üniforma ve üniformayı tamamlayan unsurlar ile teçhizat Bakanlıkça onaylanır.' Şirket üniforması ayrıca ve özel olarak Bakanlık onayına tabidir.","kaynak":"YON30 m.22","zorluk":"zor"},
    {"id":"30-S-014","soru":"Yönetmeliğe göre fiziki önlemlerin ve güvenlik cihazlarının yeterli olmayacağının anlaşılması halinde, yarı otomatik tabanca veya av silahının bulundurulmasına ve taşınmasına kim karar verir?","siklar":["Vali tek başına","İçişleri Bakanlığı","Özel güvenlik komisyonu","Emniyet Genel Müdürlüğü","Jandarma Genel Komutanlığı"],"dogru":2,"aciklama":"m.24: '...6136 sayılı Kanuna göre ruhsatlandırılması mümkün olan yarı otomatik tabancaların ve 2521 sayılı Kanun kapsamına giren av silahlarının bulundurulmasına ve taşınmasına Komisyonca karar verilir. Bu silahların sayısı ve niteliği Komisyon kararında belirtilir.'","kaynak":"YON30 m.24","zorluk":"orta"},
    {"id":"30-S-015","soru":"Yönetmeliğe göre özel güvenlik komisyonu, orantılılık ilkesine uygun olarak canlılar üzerinde kalıcı etkisi olmayan kimyasalların kullanılmasına izin verebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.24: 'Komisyon, orantılılık ilkesine uygun olarak canlılar üzerinde kalıcı etkisi olmayan kimyasalların kullanılmasına izin verebilir.' Bu, fiziki tedbir ile silah kararı arasındaki ara kademedir.","kaynak":"YON30 m.24","zorluk":"orta"},
    {"id":"30-S-016","soru":"Yönetmeliğe göre bulundurulmasına ve taşınmasına izin verilen her silah için kaç adet fişek alınmasına izin verilir?","siklar":["Beş","On beş","Yirmi","Yirmi beş","Elli"],"dogru":3,"aciklama":"m.29: 'Bulundurulmasına ve taşınmasına izin verilen her silah için yirmi beş adet fişek alınmasına izin verilir.'","kaynak":"YON30 m.29","zorluk":"kolay"},
    {"id":"30-S-017","soru":"Yönetmeliğe göre özel güvenlik izni veya silah bulundurma/taşıma izni iptal edilen kişi/kuruluşa ait silahlar kaç ay içinde devredilmezse, takip eden kaç ay içinde 6136 sayılı Kanuna göre ruhsat başvurusunda bulunulması zorunludur?","siklar":["Üç ay - bir ay","On iki ay - üç ay","Üç ay - iki ay","Altı ay - bir ay","Altı ay - iki ay"],"dogru":4,"aciklama":"m.30: 'Altı ay içinde devir gerçekleştirilmez ise, takip eden iki ay içerisinde silahın ait olduğu kişi veya kurum 6136 sayılı Kanuna göre ruhsat başvurusunda bulunmak zorundadır. Süresi içerisinde ruhsatlandırılmayan silahlar müsadere edilmek üzere adli makamlara intikal ettirilir.'","kaynak":"YON30 m.30","zorluk":"orta"},
    {"id":"30-S-018","soru":"Yönetmeliğe göre özel güvenlik eğitimine alınan adaylar asgari ....(1).... saatlik eğitime tabi tutulur; programın ....(2).... saati silah ve atış eğitimine ayrılır. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["yüz yirmi - yirmi","yüz - on","yüz elli - otuz","altmış - sekiz","doksan - on beş"],"dogru":0,"aciklama":"m.33: 'Özel güvenlik eğitimine alınan adaylar asgari yüz yirmi saatlik eğitime tabi tutulur. Programın yirmi saati silah ve atış eğitimine ayrılır.'","kaynak":"YON30 m.33","zorluk":"kolay"},
    {"id":"30-S-019","soru":"Yönetmeliğe göre atış eğitiminde kursiyerin başarılı sayılabilmesi için 25 fişeğin en az kaçının hedefe isabet etmesi gerekir?","siklar":["On","On beş","On sekiz","Yirmi","Yirmi beş"],"dogru":1,"aciklama":"m.33: 'Kursiyerlerin atış eğitiminde başarılı kabul edilmesi için 25 adet fişeğin en az 15 adedinin hedefe isabet etmesi gerekir.'","kaynak":"YON30 m.33","zorluk":"orta"},
    {"id":"30-S-020","soru":"Yönetmeliğe göre aşağıdakilerden hangisi özel güvenlik temel eğitiminin tempo kurallarından biri değildir?","siklar":["Günlük sekiz saatten fazla olamaz","Haftada kırk sekiz saatten fazla olamaz","Haftada iki gün kursiyerlerin istirahatına ayrılır","Bir ders saati kırk dakikadır","İki ders arası en az on dakika ara verilir"],"dogru":2,"aciklama":"m.33: '...günlük sekiz saat ve haftada kırksekiz saatten fazla olamaz. Bir ders saati kırk dakikadır ve iki ders arası en az on dakika ara verilir... Haftanın bir günü kursiyerlerin istirahatına ayrılır ve ders yapılmaz.' İstirahat haftada BİR gündür, iki gün değildir.","kaynak":"YON30 m.33","zorluk":"orta"},
    {"id":"30-S-021","soru":"Yönetmeliğe göre özel güvenlik yenileme eğitimi en az kaç ders saatinden oluşur ve bunun kaç saati silah bilgisi ve atış dersine ayrılır?","siklar":["120 - 20","40 - 5","80 - 10","60 - 8","100 - 15"],"dogru":3,"aciklama":"m.34: 'Yenileme eğitimi en az altmış ders saatinden oluşur. Yenileme eğitiminin sekiz ders saati silah bilgisi ve atış dersine ayrılır.'","kaynak":"YON30 m.34","zorluk":"orta"},
    {"id":"30-S-022","soru":"Yönetmeliğe göre özel güvenlik temel ve yenileme eğitimi sonu yazılı sınav soruları kim tarafından hazırlanır?","siklar":["Valilik","Özel güvenlik komisyonu","İl Milli Eğitim Müdürlüğü","Eğitim kurumu yöneticisi","Merkezi Sınav Komisyonu"],"dogru":4,"aciklama":"m.36: 'Yazılı sınav, merkezi sınav komisyonunca hazırlanan sorularla illerde yapılır.' (m.37 ile teyitli: 'Yazılı sınav soruları Merkezi Sınav Komisyonu tarafından hazırlanır.')","kaynak":"YON30 m.36","zorluk":"kolay"},
    {"id":"30-S-023","soru":"Yönetmeliğe göre temel eğitim yazılı sınavı ....(1).... sorudan oluşan birinci kısım ile silah bilgisini ölçen 20 sorudan oluşan ikinci kısımdan; yenileme eğitimi yazılı sınavı ise ....(2).... sorudan oluşan birinci kısım ile yine 20 sorudan oluşan ikinci kısımdan oluşur. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["80 - 40","40 - 80","100 - 60","60 - 30","80 - 20"],"dogru":0,"aciklama":"m.37: 'temel eğitim yazılı sınavı, 80 sorudan oluşan birinci kısım ile ... 20 sorudan oluşan ikinci kısımdan, yenileme eğitimi yazılı sınavı ise 40 sorudan oluşan birinci kısım ile ... 20 sorudan oluşan ikinci kısım olmak üzere ... yapılır.'","kaynak":"YON30 m.37","zorluk":"orta"},
    {"id":"30-S-024","soru":"Yönetmeliğe göre uygulamalı sınavda adayların atış becerisi kaç fişek üzerinden ölçülür?","siklar":["Yirmi beş","Beş","On beş","On","Yirmi"],"dogru":1,"aciklama":"m.38: 'Bakanlıkça belirlenen mesafeden ve 5 adet fişek üzerinden yaptırılacak atış ile adayların atış becerisi ölçülür.'","kaynak":"YON30 m.38","zorluk":"kolay"},
    {"id":"30-S-025","soru":"Yönetmeliğe göre Bakanlık adına denetimler, sorumluluk bölgesi esasına göre hangi kurumlara bağlı birimlerce yerine getirilir?","siklar":["Valilikler ve kaymakamlıklar","İl emniyet müdürlükleri ve belediye zabıtası","Jandarma Genel Komutanlığı ve Emniyet Genel Müdürlüğü merkez teşkilatı","Milli İstihbarat Teşkilatı","Sayıştay"],"dogru":2,"aciklama":"m.43: 'Bakanlık adına denetimler, sorumluluk bölgesi esasına göre Jandarma Genel Komutanlığı ve Emniyet Genel Müdürlüğü merkez teşkilatına bağlı ilgili birimler tarafından yerine getirilir.'","kaynak":"YON30 m.43","zorluk":"orta"},
    {"id":"30-S-026","soru":"Yönetmeliğe göre savunması yeterli görülmeyenlere ilçelerde kimin, illerde kimin onayı ile idari para cezası verilir?","siklar":["İlçelerde vali - illerde Bakan","İlçelerde Cumhuriyet savcısı - illerde sulh ceza hâkimi","İlçelerde jandarma komutanı - illerde emniyet müdürü","İlçelerde kaymakam - illerde vali","İlçelerde belediye başkanı - illerde vali"],"dogru":3,"aciklama":"m.46: 'Savunması yeterli görülmeyenlere ilçelerde kaymakamın, illerde valinin onayı ile idari para cezası verilir.'","kaynak":"YON30 m.46","zorluk":"orta"},
    {"id":"30-S-027","soru":"Yönetmeliğe göre aşağıdakilerden hangisi denetim sırasında incelenen hususlardan biri değildir?","siklar":["Faaliyet izninin ve personelin çalışma izinlerinin geçerli olup olmadığı","Mali sorumluluk sigortasının yaptırılıp yaptırılmadığı","Silah ve teçhizatın ruhsatlı olup olmadığı","Kayıt ve defterlerin usulüne uygun tutulup tutulmadığı","Şirketin yıllık kâr/zarar durumunun mali müşavirce onaylanıp onaylanmadığı"],"dogru":4,"aciklama":"m.44'te sayılan hususlar arasında faaliyet/çalışma izni geçerliliği, mali sorumluluk sigortası, sözleşmelerin usulüne uygunluğu, görev alanına uyum, silah/teçhizatın ruhsatlılığı, kayıt-defterler ve eğitim hizmetlerinin uygunluğu vardır. Şirketin kâr/zarar durumunun mali müşavirce onayı madde kapsamında sayılmamıştır.","kaynak":"YON30 m.44","zorluk":"orta"},
    {"id":"30-S-028","soru":"Yönetmeliğe göre denetim sonucu düzenlenen rapor kaç suret olarak düzenlenir?","siklar":["Bir suret","İki suret","Üç suret","Dört suret","Beş suret"],"dogru":2,"aciklama":"m.45: 'Denetim sonucu düzenlenen raporun bir sureti denetlenen birimin dosyasında muhafaza edilir, diğer sureti valiliğe, ilgisine göre bir sureti de Bakanlığa sunulur.' Toplam üç suret düzenlenir.","kaynak":"YON30 m.45","zorluk":"kolay"},
    {"id":"30-S-029","soru":"Özel Güvenlik Hizmetlerine Dair Kanunun Uygulanmasına İlişkin Yönetmeliğe göre sanayi odasının bulunmadığı illerde özel güvenlik komisyonuna hangi kurumun temsilcisi katılır?","siklar":["Ticaret ve sanayi odası başkanlığının temsilcisi","Sanayi ve Teknoloji İl Müdürlüğü temsilcisi","Esnaf ve Sanatkârlar Odası temsilcisi","İl Ticaret Müdürlüğü temsilcisi","Sanayi odası bulunmadığından komisyon o ilde kurulmaz"],"dogru":0,"aciklama":"m.5: 'Sanayi odasının bulunmadığı illerde Komisyona, ticaret ve sanayi odası başkanlığının temsilcisi katılır.' Yani ayrı bir sanayi odası temsilcisi aranmaz, ticaret ve sanayi odasının ortak temsilcisi görev yapar.","kaynak":"YON30 m.5","zorluk":"kolay"},
    {"id":"30-S-030","soru":"Yönetmeliğe göre para ve değerli eşya nakli veya cenaze töreni gibi kamuya açık ya da umumi mahallerde sağlanan özel güvenlik hizmetlerinde, kamu hürriyetlerinin korunması amacıyla gerektiğinde sınırlandırıcı kararlar almak hangi merciin görevidir?","siklar":["Vali tek başına","Özel güvenlik komisyonu","Kaymakam","Emniyet Genel Müdürlüğü","İl jandarma komutanlığı"],"dogru":1,"aciklama":"m.6/f: 'Para ve değerli eşya nakli veya cenaze töreni gibi kamuya açık ya da umumi mahallerde sağlanan özel güvenlik hizmetlerinde kamu hürriyetlerinin korunması amacıyla gerektiğinde sınırlandırıcı kararlar almak' özel güvenlik komisyonunun görevleri arasında sayılmıştır.","kaynak":"YON30 m.6","zorluk":"orta"},
    {"id":"30-S-031","soru":"Yönetmeliğe göre genel güvenlik kapsamında korunmanın mümkün olduğu ya da özel koruma ve güvenlik uygulamasının kamu hürriyetlerinin korunması açısından sakıncalı görüldüğü hallerde, özel güvenlik izni verilmemesine karar verilir ancak bu kararda gerekçe belirtilmesi zorunlu değildir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8: '...özel güvenlik izni verilmemesine karar verilir ve bu kararın gerekçesi de belirtilir.' Gerekçe belirtme açıkça zorunludur.","kaynak":"YON30 m.8","zorluk":"orta"},
    {"id":"30-S-032","soru":"Yönetmeliğe göre yükseköğretim kurumlarının güvenlikle ilgili fakülte, meslek yüksekokulu veya bölümlerinden mezun olanlarda özel güvenlik temel eğitimi bakımından durum nedir?","siklar":["Temel eğitimin tamamından muaftırlar, hiçbir ders almazlar","Hiçbir muafiyetleri yoktur, tam eğitime tabidirler","Silah eğitimi dışında özel güvenlik temel eğitimi şartı aranmaz","Yalnızca yazılı sınavdan muaftırlar","Yalnızca uygulamalı sınavdan muaftırlar"],"dogru":2,"aciklama":"m.17: '...mezun olanlarda silah eğitimi dışında özel güvenlik temel eğitimi şartı aranmaz.' Yani yalnız silah eğitimini almaları gerekir, diğer temel eğitim konularından muaftırlar.","kaynak":"YON30 m.17","zorluk":"orta"},
    {"id":"30-S-033","soru":"Yönetmeliğe göre özel güvenlik kimlik kartları kimler tarafından düzenlenebilir?","siklar":["Yalnızca İçişleri Bakanlığı merkez teşkilatınca","Yalnızca il özel idarelerince","Yalnızca ilgili özel güvenlik şirketince","Valiliklerce elektronik sistemle gönderilen bilgiler esas alınarak Emniyet Genel Müdürlüğünce ya da Bakanlıkça uygun görülecek kamu kurum/kuruluşları veya kanunla kurulan tüzel kişilerce","Yalnızca Nüfus ve Vatandaşlık İşleri Genel Müdürlüğünce"],"dogru":3,"aciklama":"m.21: 'Özel güvenlik kimlik kartları, valiliklerce elektronik sistemle gönderilen bilgiler esas alınarak Emniyet Genel Müdürlüğünce düzenlenebileceği gibi Bakanlıkça uygun görülecek kamu kurum veya kuruluşları ile kanunla kurulan tüzel kişilere de yaptırılabilir.'","kaynak":"YON30 m.21","zorluk":"zor"},
    {"id":"30-S-034","soru":"Yönetmeliğe göre özel güvenlik üniformasının renk, biçim ve motif bakımından aynı olması yasaklanan kurumlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Türk Silahlı Kuvvetleri","Emniyet Genel Müdürlüğü (genel kolluk)","Jandarma Genel Komutanlığı (genel kolluk)","Kanunla kurulan özel kolluk kuvvetleri","Belediye zabıta teşkilatı"],"dogru":4,"aciklama":"m.22: 'Özel güvenlik görevlilerinin giyeceği üniforma ve üniformayı tamamlayan diğer unsurlar, Türk Silahlı Kuvvetleri ve genel kolluk kuvvetleri ile kanunlarla kurulan özel kolluk kuvvetlerinde kullanılan renkte, biçim ve motifte olamaz.' Belediye zabıta teşkilatı bu sayımda yer almaz.","kaynak":"YON30 m.22","zorluk":"orta"},
    {"id":"30-S-035","soru":"Yönetmeliğe göre her silah için öngörülen 25 fişeklik istihkak, görev yeri ve niteliğine göre kimin kararı ve kimin onayı ile artırılabilir?","siklar":["Komisyonun kararı ve valinin onayı ile","Sadece valinin kararı ile","Sadece komisyonun kararı ile","Bakanlığın kararı ve komisyonun onayı ile","Genel kolluğun kararı ve valinin onayı ile"],"dogru":0,"aciklama":"m.29: 'Fişek miktarı Komisyonun kararı ve valinin onayı ile görev yeri ve niteliğine göre arttırılabilir.'","kaynak":"YON30 m.29","zorluk":"orta"},
    {"id":"30-S-036","soru":"Yönetmeliğe göre tüfekler ve tam otomatik tabancalar devredilebilir veya genel kolluk kuruluşlarına bağışlanabilir ya da imha edilmek üzere valilikçe ....(1).... verilir; devredilecek, hibe ya da imha edilecek veya satılacak silahlar için ise ....(2).... ekspertiz raporu aldırılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Milli Savunma Bakanlığına - Adli Tıp Kurumundan","Makine Kimya Endüstrisi Kurumuna - Bölge Kriminal Polis Laboratuvarlarından","Emniyet Genel Müdürlüğüne - Jandarma Kriminal Laboratuvarından","TÜBİTAK'a - Bölge Kriminal Polis Laboratuvarlarından","Makine Kimya Endüstrisi Kurumuna - Adli Tıp Kurumundan"],"dogru":1,"aciklama":"m.30: 'Tüfekler ve tam otomatik tabancalar devredilebilir veya genel kolluk kuruluşlarına bağışlanabilir ya da imha edilmek üzere valilikçe Makine Kimya Endüstrisi Kurumuna verilir. Devredilecek, hibe ya da imha edilecek veya satılacak silahlar için Bölge Kriminal Polis Laboratuvarlarından ekspertiz raporu aldırılır.'","kaynak":"YON30 m.30","zorluk":"zor"},
    {"id":"30-S-037","soru":"Yönetmeliğe göre havalimanı ve havaalanlarında istihdam edilecek özel güvenlik görevlileri hangi ek dersleri almak zorundadır?","siklar":["ISPS Kod çerçevesinde Deniz Limanı Güvenliği ile Uyuşturucu Madde Bilgileri","Sadece Sivil Havacılık Güvenliği dersi","Sivil Havacılık Güvenliği ile Uyuşturucu Madde Bilgileri","Silah Bilgisi ve Atış dersinin ileri düzeyi","Kalabalık Yönetimi ve İlk Yardım dersleri"],"dogru":2,"aciklama":"m.33: 'Havalimanı ve havaalanlarında istihdam edilecek özel güvenlik görevlileri Sivil Havacılık Güvenliği ile Uyuşturucu Madde Bilgileri derslerini... almak zorundadır.'","kaynak":"YON30 m.33","zorluk":"kolay"},
    {"id":"30-S-038","soru":"Yönetmeliğe göre fiilen memur statüsünde çalışan uzman eğiticiler bir haftada toplam ....(1).... saatten fazla ders veremez; emekli veya özel sektörde çalışan uzman eğiticiler ise bir haftada ....(2).... saatten fazla ders veremez. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["8 - 20","48 - 60","15 - 30","20 - 45","40 - 48"],"dogru":3,"aciklama":"m.33: 'Fiilen memur statüsünde çalışan uzman eğiticiler bir haftada toplam yirmi saatten fazla ders veremez ve mesai saatleri içerisinde ders vermek üzere bir haftada sekiz saatten fazla izin alamazlar. Emekli veya özel sektörde çalışan uzman eğiticiler ise bir haftada kırkbeş saatten fazla ders veremezler.'","kaynak":"YON30 m.33","zorluk":"zor"},
    {"id":"30-S-039","soru":"Yönetmeliğe göre Bakanlıkça belirlenen sayıda yazılı sınav gözlemcisi ile illerde yapılacak uygulamalı sınav komisyonlarında görevlendirilecek personeli kim belirler?","siklar":["Merkezi Sınav Komisyonu","Özel güvenlik komisyonu","İl Milli Eğitim Müdürlüğü","Eğitim kurumu yöneticisi","Valilik"],"dogru":4,"aciklama":"m.36: 'Bakanlıkça belirlenen sayıda yazılı sınav gözlemcisi ve illerde yapılacak uygulamalı sınav komisyonlarında görevlendirilecek personel valilik tarafından belirlenir.'","kaynak":"YON30 m.36","zorluk":"orta"},
    {"id":"30-S-040","soru":"Yönetmeliğe göre denetim sonucunda tespit edilen eksikliklerin giderilmesi için ilgili kişi, kurum, kuruluş, eğitim kurumu, alarm izleme merkezi veya şirkete eksikliğin niteliğine göre en az kaç gün süre verilir?","siklar":["7 gün","3 gün","10 gün","15 gün","30 gün"],"dogru":0,"aciklama":"m.45: '...bu eksiklikleri gidermesi için eksikliğin niteliğine göre asgari yedi gün süre verilir. Bu süre sonunda eksiklikler giderilmediği takdirde veya denetim sonucu konusu suç teşkil eden uygulamalar tespit edildiğinde Kanunun 19 uncu ve 20 nci maddesinde belirtilen cezalar uygulanır.'","kaynak":"YON30 m.45","zorluk":"kolay"},
  ],
  55: [
    {"id":"31-S-001","soru":"Adlî Kolluk Yönetmeliği'ne göre 'soruşturma' evresi hangi ifadeyle tanımlanmıştır?","siklar":["Kanuna göre yetkili mercilerce suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar geçen evre","İddianamenin kabulü ile başlayıp hükmün kesinleşmesine kadar geçen evre","Suçun işlenmesinden failin yakalanmasına kadar geçen evre","İhbarın alınmasından fezlekenin düzenlenmesine kadar geçen evre","Yakalamadan iddianamenin düzenlenmesine kadar geçen evre"],"dogru":0,"aciklama":"m.3: 'Soruşturma: Kanuna göre yetkili mercilerce suç şüphesinin öğrenilmesinden, iddianamenin kabulüne kadar geçen evreyi, ifade eder.'","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"kolay"},
    {"id":"31-S-002","soru":"Adlî Kolluk Yönetmeliği'ne göre 'kovuşturma' evresi hangi ifadeyle tanımlanmıştır?","siklar":["Suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar geçen evre","İddianamenin kabulü ile başlayıp hükmün kesinleşmesine kadar geçen evre","Yakalamadan hükmün kesinleşmesine kadar geçen evre","Fezlekenin düzenlenmesinden hükmün kesinleşmesine kadar geçen evre","İddianamenin düzenlenmesinden kabulüne kadar geçen evre"],"dogru":1,"aciklama":"m.3: 'Kovuşturma: İddianamenin kabulü ile başlayıp hükmün kesinleşmesine kadar geçen evreyi, ifade eder.'","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"kolay"},
    {"id":"31-S-003","soru":"Adlî Kolluk Yönetmeliği'ne göre 'gecikmesinde sakınca bulunan hâl', yalnızca derhâl işlem yapılmadığı takdirde şüphelinin kaçması ihtimalini ifade eder; delillerin kaybolması veya kimliğin saptanamaması ihtimalleri bu tanıma dâhil değildir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3: 'Gecikmesinde sakınca bulunan hâl: Derhâl işlem yapılmadığı takdirde suçun delillerinin kaybolması veya şüphelinin kaçması veya kimliğinin saptanamaması ihtimalini, ifade eder.' Tanım üç ihtimali BİRLİKTE kapsar, yalnız kaçmayla sınırlı değildir.","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"orta"},
    {"id":"31-S-004","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk sorumlusu kim tarafından görevlendirilir?","siklar":["İlgili Cumhuriyet başsavcısı tarafından","En üst dereceli kolluk amiri tarafından","İçişleri Bakanlığı tarafından","Mahallin en büyük mülki idare amiri tarafından","Adalet Bakanlığı tarafından"],"dogru":3,"aciklama":"m.3: 'Adlî kolluk sorumlusu: Mahallin en büyük mülki idare amiri tarafından görevlendirilen adlî kolluğun komutanını, amirini veya sorumlusunu, ... ifade eder.'","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"orta"},
    {"id":"31-S-005","soru":"Adlî Kolluk Yönetmeliği'ne göre Jandarma Genel Komutanlığında 'en üst dereceli kolluk amiri' tanımına kimler girer?","siklar":["Yalnızca Jandarma Genel Komutanı","İl jandarma komutanı, ilçe ve merkez ilçe jandarma komutanı","Mahallin en büyük mülki idare amirinin görevlendirdiği komutan","İl emniyet müdürü","Sahil güvenlik birlik komutanı"],"dogru":1,"aciklama":"m.3: '(Ek fıkra) En üst dereceli kolluk amiri: ... Jandarma Genel Komutanlığında il jandarma komutanını, ilçe ve merkez ilçe jandarma komutanını ... ifade eder.'","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"orta"},
    {"id":"31-S-006","soru":"Adlî Kolluk Yönetmeliği'ne göre 'adlî kolluk görevlileri' tanımı aşağıdaki mevzuattan hangisine dayandırılmamıştır?","siklar":["5271 sayılı Ceza Muhakemesi Kanunu","3201 sayılı Emniyet Teşkilâtı Kanununun 8, 9 ve 12 nci maddeleri","2803 sayılı Jandarma Teşkilât, Görev ve Yetkileri Kanununun 7 nci maddesi","2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 4 üncü maddesi","5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun"],"dogru":4,"aciklama":"m.3: Adlî kolluk görevlileri tanımı '5271 sayılı CMK, 3201 sayılı ETK m.8-9-12, 2803 sayılı Kanunun 7 nci maddesi, 485 sayılı KHK m.8, 2692 sayılı Kanunun 4 üncü maddesi ve Jandarma Teşkilâtı Görev ve Yetkileri Yönetmeliği'nde belirtilen soruşturma işlemlerini yapmak üzere ... görevlendirilen' kişileri ifade eder. 5188 sayılı Kanun bu sayımda yer almaz; özel güvenlik ayrı bir alandır.","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"zor"},
    {"id":"31-S-007","soru":"Adlî Kolluk Yönetmeliği m.4 hükmüne göre aşağıdaki teşkilat - asgarî görevlendirme koşulu eşleştirmelerinden hangisi bu maddede SAYILMAMIŞTIR?","siklar":["Emniyet Genel Müdürlüğü - asgarî tam teşekküllü bir polis karakolu bulunan yerler","Jandarma Genel Komutanlığı - asgarî tam teşekküllü bir jandarma karakolu bulunan yerler","Sahil Güvenlik Komutanlığı - asgarî sahil güvenlik bot komutanlıklarının bulunduğu yerler","Gümrük Muhafaza Genel Müdürlüğü - gümrük muhafaza kaçakçılık ve istihbarat müdürlüğü, gümrük müdürlüğü ile müstakil bölge ve kısım âmirlikleri bulunan yerler","Millî İstihbarat Teşkilatı - il başkanlığı bulunan yerler"],"dogru":4,"aciklama":"m.4: Soruşturma yapmak üzere adlî kolluk personeli görevlendirilecek yerler (a) EGM için asgarî tam teşekküllü polis karakolu, (b) JGK için asgarî tam teşekküllü jandarma karakolu, (c) SGK için asgarî sahil güvenlik bot komutanlıkları, (d) Gümrük Muhafaza Genel Müdürlüğü için gümrük muhafaza kaçakçılık ve istihbarat müdürlüğü/gümrük müdürlüğü/müstakil bölge ve kısım âmirlikleri olarak sayılmıştır. Millî İstihbarat Teşkilatı bu dört bentte yer almaz.","kaynak":"Adlî Kolluk Yönetmeliği m.4","zorluk":"orta"},
    {"id":"31-S-008","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî görevlere ilişkin emir ve talimatları öncelikle adlî kolluk sorumlularına veya ilgili birim âmirlerine kim verir?","siklar":["Cumhuriyet başsavcılığı","İçişleri Bakanlığı","En üst dereceli kolluk amiri","Mahallin en büyük mülki idare amiri","Adalet Bakanlığı"],"dogru":0,"aciklama":"m.5/a: 'Cumhuriyet başsavcılığı, adlî görevlere ilişkin emir ve talimatlarını öncelikle adlî kolluk sorumlularına veya adlî kolluk görevi ifa eden diğer birim âmirlerine verir.'","kaynak":"Adlî Kolluk Yönetmeliği m.5","zorluk":"kolay"},
    {"id":"31-S-009","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk görevlilerine, adlî görevi bulunmayan üstleri tarafından, yürütülen soruşturmayla ilgili emir ve talimat verilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/a: 'Adlî kolluk görevlilerine, adlî görevi bulunmayan üstleri tarafından, yürütülen soruşturma ile ilgili emir ve talimat verilemez.' Yasak açık ve istisnasızdır (m.7 saklıdır).","kaynak":"Adlî Kolluk Yönetmeliği m.5","zorluk":"orta"},
    {"id":"31-S-010","soru":"Adlî Kolluk Yönetmeliği m.5 hükümlerine göre aşağıdakilerden hangisi YANLIŞTIR?","siklar":["En üst dereceli kolluk amiri adlî olayları, mülki idare amirine derhal bildirir","Adlî kolluk, adlî görevlerin haricindeki hizmetlerde üstlerinin emrindedir","Adlî kolluk görevlilerinin özlük hakları Cumhuriyet başsavcılığı tarafından yürütülür","Adlî kolluğun öncelikli görevi, karşılaştığı suçun işlenmesini önlemektir","Adlî kolluk görevlilerinin özlük hakları bağlı oldukları teşkilât tarafından yürütülür"],"dogru":2,"aciklama":"m.5/b: 'Adlî kolluk görevlilerinin özlük hakları, bağlı oldukları teşkilât tarafından yürütülür.' (E doğru); özlük hakları Cumhuriyet başsavcılığınca değil, görevlinin bağlı olduğu kendi teşkilatınca yürütülür, bu nedenle C yanlıştır. A (m.5/c), B ve D (m.5/a) ise maddede birebir yer alan doğru ifadelerdir.","kaynak":"Adlî Kolluk Yönetmeliği m.5","zorluk":"zor"},
    {"id":"31-S-011","soru":"Adlî Kolluk Yönetmeliği'ne göre soruşturma işlemleri öncelikle kime yaptırılır ve buna ilişkin emirler adlî kolluk görevlilerince nasıl yerine getirilir?","siklar":["İçişleri Bakanlığının emriyle; en kısa sürede yerine getirilir","Mülki idare amirinin emriyle; derhal yerine getirilir","Cumhuriyet savcısının emir ve talimatları doğrultusunda öncelikle adlî kolluğa yaptırılır; emirler gecikmeksizin yerine getirilir","En üst dereceli kolluk amirinin emriyle; ivedilikle yerine getirilir","Sulh ceza hâkiminin emriyle; makul sürede yerine getirilir"],"dogru":2,"aciklama":"m.6: 'Soruşturma işlemleri, Cumhuriyet savcısının emir ve talimatları doğrultusunda öncelikle adlî kolluğa yaptırılır. Adlî kolluk görevlileri Cumhuriyet savcısının adlî görevlere ilişkin emirlerini gecikmeksizin yerine getirir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"kolay"},
    {"id":"31-S-012","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk görevlileri; kendilerine yapılan ihbar/şikâyetleri, el koydukları olayları, yakalanan kişiler ile uygulanan tedbirleri ....(1).... Cumhuriyet ....(2).... ve en üst dereceli kolluk amirine bildirir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["en kısa sürede - savcısına","yirmidört saat içinde - başsavcılığına","gecikmeksizin - savcısına","derhâl - başsavcılığına","bir hafta içinde - başsavcılığına"],"dogru":3,"aciklama":"m.6: '...derhâl Cumhuriyet başsavcılığına ve en üst dereceli kolluk amirine bildirir ve ilgili Cumhuriyet savcısının emri doğrultusunda ... soruşturma işlemlerine başlar.' Bildirim süresi 'derhâl', bildirim makamı 'başsavcılık'tır (savcı ise sonraki emir aşamasında devreye girer).","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"orta"},
    {"id":"31-S-013","soru":"Adlî Kolluk Yönetmeliği'ne göre Cumhuriyet savcısı acele hâllerde adlî kolluk görevlilerine emrini sözlü olarak verebilir ve kolluk görevlisi, emrin yazılı hâle getirilmesini beklemeden sözlü emrin gereğini yerine getirir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6: 'Cumhuriyet savcısı, adlî kolluk görevlilerine emirleri yazılı; acele hâllerde, sözlü olarak verir. ... Ancak, kolluk görevlisi emrin yazılı hâle getirilmesini beklemeden sözlü emrin gereğini yerine getirir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"kolay"},
    {"id":"31-S-014","soru":"Adlî Kolluk Yönetmeliği'ne göre sulh ceza hâkiminin de bütün soruşturma işlemlerini yapabilmesi için birlikte aranan şartlar aşağıdakilerden hangisinde doğru verilmiştir?","siklar":["Kovuşturma aşamasında olma ve Cumhuriyet savcısının izni","Gecikmesinde sakınca bulunma ve mülki idare amirinin talebi","Suçüstü hâli ve Cumhuriyet savcısının yazılı onayı","Adlî kolluk sorumlusunun talebi ve olayın basit nitelikte olması","Suçüstü hâli ile gecikmesinde sakınca bulunan hâllerde, savcıya erişilememesi veya olayın savcının iş gücünü aşması"],"dogru":4,"aciklama":"m.6: 'Suçüstü hâli ile gecikmesinde sakınca bulunan hâllerde, Cumhuriyet savcısına erişilemiyorsa veya olay genişliği itibarıyla Cumhuriyet savcısının iş gücünü aşıyorsa, sulh ceza hâkimi de bütün soruşturma işlemlerini yapabilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"zor"},
    {"id":"31-S-015","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk görevlileri, şüphelinin lehine veya aleyhine olan tüm delilleri topladıktan sonra bunları nasıl ve kime sunmakla yükümlüdür?","siklar":["Tutanakla mahalli mülki amire","Rapor hâlinde en üst dereceli kolluk amirine","Bir fezleke ile Cumhuriyet savcısına","Yazılı beyanla sulh ceza hâkimine","İhbarname ile Cumhuriyet başsavcılığına"],"dogru":2,"aciklama":"m.6: '...şüphelinin lehine veya aleyhine olan tüm delilleri, ... toplamak, muhafaza altına almak ve bunları bir fezleke ile Cumhuriyet savcısına sunmakla yükümlüdür. Hukuka aykırı delil elde edildiğinin tespiti hâlinde, fezlekede bu hususa da yer verilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"orta"},
    {"id":"31-S-016","soru":"Adlî Kolluk Yönetmeliği'ne göre bir ölümün doğal nedenlerden meydana gelmediği kuşkusu varsa veya ölünün kimliği belirlenemiyorsa, kolluk görevlisi durumu derhâl kime bildirmek zorundadır?","siklar":["Mahalli mülki idare amirine","En üst dereceli kolluk amirine","Sulh ceza hâkimine","Cumhuriyet başsavcılığına","Adalet Bakanlığına"],"dogru":3,"aciklama":"m.6: '...kolluk görevlisi, durumu derhâl Cumhuriyet başsavcılığına bildirmek ve Cumhuriyet savcısının emri doğrultusunda soruşturma işlemlerine başlamak zorundadır.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"orta"},
    {"id":"31-S-017","soru":"Adlî Kolluk Yönetmeliği'ne göre olay yerinde işlemlere engel olan veya alınan tedbirlere aykırı davranan kişiye karşı adlî kolluk görevlisinin izleyeceği doğru kademe aşağıdakilerden hangisidir?","siklar":["Doğrudan yakalama, ardından sözlü ikaz","Zor kullanarak uzaklaştırma, ardından sözlü ikaz","Yakalama, ardından zor kullanma","Sözlü ikaz, ardından doğrudan yakalama","Sözlü ikaz, uyulmazsa zor kullanarak uzaklaştırma, ısrar hâlinde yakalama"],"dogru":4,"aciklama":"m.6: '...önce sözlü olarak ikâz eder; uyulmaması hâlinde zor kullanarak olay yerinden uzaklaştırır. İlgilinin ısrarı hâlinde yakalama işlemi uygulanır.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"orta"},
    {"id":"31-S-018","soru":"Adlî Kolluk Yönetmeliği'ne göre diğer kolluk birimleri hangi hâlde adlî kolluk görevini yerine getirmekle yükümlüdür ve bu durumda haklarında hangi kanun hükümleri uygulanır?","siklar":["Yalnızca mülki idare amirinin talebiyle; 2559 sayılı PVSK hükümleri","Yalnızca olağanüstü hâl ilanında; 2803 sayılı Kanun hükümleri","Gerektiğinde veya Cumhuriyet savcısının talebi hâlinde; Ceza Muhakemesi Kanunu hükümleri","Yalnızca en üst dereceli kolluk amirinin emriyle; kendi teşkilat mevzuatı","Yalnızca suçüstü hâlinde; sulh ceza hâkiminin belirlediği usul"],"dogru":2,"aciklama":"m.7: 'Gerektiğinde veya Cumhuriyet savcısının talebi hâlinde, diğer kolluk birimleri de adlî kolluk görevini yerine getirmekle yükümlüdür. Bu durumda, kolluk görevlileri hakkında, adlî görevleri dolayısıyla Ceza Muhakemesi Kanunu hükümleri uygulanır.'","kaynak":"Adlî Kolluk Yönetmeliği m.7","zorluk":"orta"},
    {"id":"31-S-019","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk sorumluları hakkındaki değerlendirme raporu ne zaman düzenlenir ve kime gönderilir?","siklar":["Altı ayda bir; en üst dereceli kolluk amirine","Her ayın sonunda; Cumhuriyet savcısına","Göreve başlarken bir kez; Adalet Bakanlığına","Her yılın sonunda; mülki idare amirlerine","Her yılın başında; İçişleri Bakanlığına"],"dogru":3,"aciklama":"m.11: 'Cumhuriyet başsavcıları her yılın sonunda, ... belirlenmiş adlî kolluk sorumluları hakkında değerlendirme raporu düzenleyerek, mülki idare amirlerine gönderir.'","kaynak":"Adlî Kolluk Yönetmeliği m.11","zorluk":"kolay"},
    {"id":"31-S-020","soru":"Adlî Kolluk Yönetmeliği'ne göre değerlendirme raporları, adlî kolluk görevlisinin sicilinin düzenlenmesinde dikkate alınır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.11: 'Bu değerlendirme raporları ilgilinin sicilinin düzenlenmesinde dikkate alınır.'","kaynak":"Adlî Kolluk Yönetmeliği m.11","zorluk":"kolay"},
    {"id":"31-S-021","soru":"Adlî Kolluk Yönetmeliği'ne göre Cumhuriyet başsavcıları ve Cumhuriyet savcıları, adlî kolluk görevlilerince ifa edilen adlî işlemleri hangi sıklıkla denetler?","siklar":["Yılda bir kez","Ayda bir kez","Mülki idare amirinin talebi üzerine","Her zaman","Yalnızca şikâyet üzerine"],"dogru":3,"aciklama":"m.13/a: 'Adlî kolluk hizmetlerinin etkin ve verimli yürütülebilmesi amacıyla, adlî kolluk görevlilerince ifa edilen adlî işlemleri her zaman denetler.' Ayrıca gözaltına alınanların bulunduğu nezarethaneleri, gözaltı sürelerini ve ilgili kayıtları denetleyip sonucu nezarethaneye alınanların kaydına ait deftere işler.","kaynak":"Adlî Kolluk Yönetmeliği m.13","zorluk":"orta"},
    {"id":"31-S-022","soru":"Adlî Kolluk Yönetmeliği'ne göre Cumhuriyet savcısı, en üst dereceli kolluk amiri ve mülki idare amirinin yetkileri arasındaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["Cumhuriyet savcısı - adlî görevlere ilişkin emir ve talimat verme","En üst dereceli kolluk amiri - adlî kolluk sorumlusunu görevlendirme","Mahallin en büyük mülki idare amiri - adlî kolluk sorumlusunu görevlendirme","Cumhuriyet başsavcısı - yıl sonu değerlendirme raporunu mülki idare amirine gönderme","En üst dereceli kolluk amiri - adlî olayı derhal mülki idare amirine bildirme"],"dogru":1,"aciklama":"m.3: 'Adlî kolluk sorumlusu: Mahallin en büyük mülki idare amiri tarafından görevlendirilen ...' Adlî kolluk sorumlusunu görevlendiren mülki idare amiridir (C doğru), en üst dereceli kolluk amiri değildir (B yanlış). Savcı adlî emri verir (m.5/a - A doğru), başsavcı yıl sonu raporunu mülki amire gönderir (m.11 - D doğru), en üst amir adlî olayı derhal mülki amire bildirir (m.5/c - E doğru).","kaynak":"Adlî Kolluk Yönetmeliği m.3, m.5, m.11","zorluk":"zor"},
    {"id":"31-S-023","soru":"Adlî Kolluk Yönetmeliği m.1 hükmüne göre bu Yönetmeliğin düzenlediği hususlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Adlî kolluk görevlilerine verilecek disiplin cezalarının türü ve miktarı","Adlî kolluğun çalışma esasları","Adlî kolluk görevlilerinin nitelikleri","Adlî işlemlerin denetimi","Hizmet öncesi ve hizmet içi eğitimi"],"dogru":0,"aciklama":"m.1: 'Bu Yönetmelik, adlî kolluğun çalışma esaslarını, adlî kolluk görevlilerinin niteliklerini, adlî işlemlerinin denetimini, hizmet öncesi ve hizmet içi eğitimini, diğer hizmet birimleri ile ilişkilerini, değerlendirme raporlarının düzenlenmesini, uzmanlık dallarına göre hangi bölümlerde çalıştırılacaklarını ve diğer hususları düzenler.' Disiplin cezalarının türü ve miktarı bu maddede sayılmaz; disiplin, kolluk teşkilatlarının kendi mevzuatına ait ayrı bir konudur.","kaynak":"Adlî Kolluk Yönetmeliği m.1","zorluk":"kolay"},
    {"id":"31-S-024","soru":"Adlî Kolluk Yönetmeliği, hangi kanunun hangi maddesine dayanılarak hazırlanmıştır?","siklar":["2803 sayılı Kanunun 7 nci maddesi","5271 sayılı Ceza Muhakemesi Kanununun 167 nci maddesi","3201 sayılı Emniyet Teşkilâtı Kanununun 8 inci maddesi","5237 sayılı Türk Ceza Kanununun 2 nci maddesi","2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 4 üncü maddesi"],"dogru":1,"aciklama":"m.2: 'Bu Yönetmelik, 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun 167 nci maddesine dayanılarak hazırlanmıştır.'","kaynak":"Adlî Kolluk Yönetmeliği m.2","zorluk":"kolay"},
    {"id":"31-S-025","soru":"Adlî Kolluk Yönetmeliği'ne göre 'Cumhuriyet savcısı' deyimi yalnızca Cumhuriyet savcılarını ifade eder; yetkili Cumhuriyet başsavcıları bu tanımın dışında tutulmuştur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3: 'Cumhuriyet savcısı: Yetkili Cumhuriyet başsavcıları ile Cumhuriyet savcılarını, ifade eder.' Tanım her iki unvanı da (başsavcı+savcı) kapsar.","kaynak":"Adlî Kolluk Yönetmeliği m.3","zorluk":"orta"},
    {"id":"31-S-026","soru":"Adlî Kolluk Yönetmeliği m.4 hükmüne göre, aranan asgarî teşkilat şartı sağlanan yerlerde adlî kolluk personeli, mevcut imkânlardan bağımsız olarak kanunda öngörülen sabit sayıda görevlendirilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4 son fıkra: '...mevcut imkanlar ölçüsünde yeterince adlî kolluk personeli görevlendirilir.' Görevlendirilecek personel sabit bir sayıya değil, mevcut imkânlar ölçüsüne bağlıdır.","kaynak":"Adlî Kolluk Yönetmeliği m.4","zorluk":"orta"},
    {"id":"31-S-027","soru":"Adlî Kolluk Yönetmeliği m.5'e göre, adlî kolluk görevlileri ile kadrolarında yer aldıkları birimlere mevzuatla verilmiş, adlî görev kapsamı dışında kalan diğer görev ve hizmetler arasındaki ilişki aşağıdakilerden hangisidir?","siklar":["Adlî kolluk görevlileri bu tür görevlerden muaftır","Bu görevler yalnızca en üst dereceli kolluk amirinin onayıyla yerine getirilir","Adlî kolluk görevlileri bu görev ve hizmetleri de yerine getirirler","Bu görevler Cumhuriyet savcısının iznine tâbidir","Bu görevler yalnızca adlî kolluk sorumlusu tarafından yerine getirilir"],"dogru":2,"aciklama":"m.5/a: 'Adlî kolluk görevlileri, kadrolarında yer aldıkları birimlere mevzuatla verilmiş ve adlî görev kapsamı dışında kalan diğer görev ve hizmetleri de yerine getirirler.' Adlî görev yapmak, personelin kendi teşkilatındaki diğer mevzuat kaynaklı görevlerini ortadan kaldırmaz.","kaynak":"Adlî Kolluk Yönetmeliği m.5","zorluk":"zor"},
    {"id":"31-S-028","soru":"Adlî Kolluk Yönetmeliği'ne göre Ceza Muhakemesi Kanununun 135 inci maddesinin altıncı fıkrasında sayılan suçlar nedeniyle yapılan soruşturmaların aşamaları hakkında Cumhuriyet başsavcısına bilgi verilmesi nasıl gerçekleştirilir?","siklar":["Cumhuriyet savcısı tarafından doğrudan veya varsa ilgili Cumhuriyet başsavcı vekili aracılığıyla yazılı olarak","Adlî kolluk sorumlusu tarafından sözlü olarak","En üst dereceli kolluk amiri tarafından aylık rapor hâlinde","Mülki idare amiri tarafından yıl sonunda","Sulh ceza hâkimi tarafından resen"],"dogru":0,"aciklama":"m.6 (Ek fıkra): 'Ceza Muhakemesi Kanununun 135 inci maddesinin altıncı fıkrasında sayılan suçlar nedeniyle yapılan soruşturmaların aşamaları hakkında Cumhuriyet savcısı tarafından doğrudan veya varsa ilgili Cumhuriyet başsavcı vekili aracılığıyla Cumhuriyet başsavcısına yazılı olarak bilgi verilmesi zorunludur. Bu bildirim yazıları görüldü şerhinden sonra soruşturma dosyasında muhafaza edilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"zor"},
    {"id":"31-S-029","soru":"Adlî Kolluk Yönetmeliği m.6'ya göre en üst dereceli kolluk amirinin, adlî kolluk hizmetlerinin etkin ve verimli yürütülmesi amacıyla sahip olduğu yetkiler arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Gözetim","Denetim","Planlama","İş bölümü yapma","Adlî kolluk sorumlusunu görevlendirme"],"dogru":4,"aciklama":"m.6: 'En üst dereceli kolluk amiri, adlî kolluk hizmetlerinin etkin ve verimli bir şekilde yürütülmesi amacıyla adlî kolluk görevlileri üzerinde gözetim, denetim, planlama ve gerektiğinde diğer idari tedbirleri almaya ve iş bölümünü yapmaya yetkilidir.' Adlî kolluk sorumlusunu görevlendirme yetkisi ise m.3 uyarınca mahallin en büyük mülki idare amirine aittir, en üst dereceli kolluk amirine değil.","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"orta"},
    {"id":"31-S-030","soru":"Adlî Kolluk Yönetmeliği'ne göre acele hâllerde sözlü olarak verilen emir, yazılı hâle getirildikten sonra ilgili kolluğa nasıl bildirilir?","siklar":["Yalnızca posta yoluyla","Yalnızca bir sonraki adlî nöbet değişiminde","Mümkün olması hâlinde en seri iletişim vasıtasıyla; aksi hâlde ilgili kolluk görevlilerince alınmasına hazır edilerek","En üst dereceli kolluk amiri aracılığıyla yeniden sözlü olarak","Mülki idare amirinin onayından sonra"],"dogru":2,"aciklama":"m.6: 'Sözlü emir, en kısa sürede yazılı hâle dönüştürülerek mümkün olması hâlinde en seri iletişim vasıtasıyla ilgili kolluğa bildirir; aksi hâlde ilgili kolluk görevlilerince alınmasına hazır edilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"zor"},
    {"id":"31-S-031","soru":"Adlî Kolluk Yönetmeliği'ne göre hukuka aykırı delil elde edildiğinin tespiti hâlinde, bu husus ayrıca fezlekede belirtilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6: 'Hukuka aykırı delil elde edildiğinin tespiti hâlinde, fezlekede bu hususa da yer verilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.6","zorluk":"kolay"},
    {"id":"31-S-032","soru":"Adlî Kolluk Yönetmeliği m.8'e göre adlî kolluk görevlilerinin genel ve özel niteliklerinin belirlenmesinde esas alınan mevzuat arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["657 sayılı Devlet Memurları Kanunu","6136 sayılı Ateşli Silahlar ve Bıçaklar Kanunu","926 sayılı Türk Silâhlı Kuvvetleri Personel Kanunu","3269 sayılı Uzman Erbaş Kanunu","4752 sayılı Astsubay Meslek Yüksek Okulları Kanunu"],"dogru":1,"aciklama":"m.8: nitelik belirlemede '657 sayılı Devlet Memurları Kanunu, 926 sayılı Türk Silâhlı Kuvvetleri Personel Kanunu, 2803 sayılı Jandarma Teşkilât, Görev ve Yetkileri Kanunu, 3201 sayılı Emniyet Teşkilâtı Kanunu, 3466 sayılı Uzman Jandarma Kanunu, 3269 sayılı Uzman Erbaş Kanunu, 4752 sayılı Astsubay Meslek Yüksek Okulları Kanunu, 2692 sayılı Sahil Güvenlik Komutanlığı Kanunu, 485 sayılı KHK ve ilgili tüzük/yönetmelikler' sayılmıştır. 6136 sayılı Ateşli Silahlar ve Bıçaklar Kanunu bu sayımda yer almaz.","kaynak":"Adlî Kolluk Yönetmeliği m.8","zorluk":"orta"},
    {"id":"31-S-033","soru":"Adlî Kolluk Yönetmeliği m.9'a göre hizmet öncesi eğitim müfredatlarında hangi konulara yer verilir?","siklar":["Yalnızca kolluk teşkilatının kendi iç yönergeleri","Yalnızca fiziki yeterlilik ve atış eğitimi","Yalnızca trafik mevzuatı","5237 sayılı Türk Ceza Kanununun temel ilkeleri, ceza sorumluluğunun esasları, özel hükümler ile 5271 sayılı CMK ve diğer kanunlardaki soruşturma işlemlerinin hukukî çerçeveleri","Yalnızca disiplin hukuku"],"dogru":3,"aciklama":"m.9/a-2: 'Hizmet öncesi eğitim müfredatlarında; 5237 sayılı Türk Ceza Kanununun temel ilkeleri, ceza sorumluluğunun esasları, özel hükümler, 5271 sayılı Ceza Muhakemesi Kanunu ile diğer kanunlarda yer alan ve kolluk tarafından yerine getirilen suç soruşturmasına ilişkin işlemlerin hukukî çerçevelerine yönelik konulara yer verilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.9","zorluk":"orta"},
    {"id":"31-S-034","soru":"Adlî Kolluk Yönetmeliği'ne göre adlî kolluk görevlilerinin eğitimlerinin verilmesinde, kolluğun bağlı olduğu Bakanlıkça talep edilmesi hâlinde eğitici personeli Adalet Bakanlığı görevlendirir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.9: 'Adlî kolluk görevlilerinin eğitimlerinin verilmesinde kolluğun bağlı olduğu Bakanlıkça talep edilmesi hâlinde, Adalet Bakanlığı tarafından eğitici personel görevlendirilir. Hizmet içi eğitimlerin plânlanmasında Adalet Bakanlığının veya yetkili Cumhuriyet başsavcısının görüşleri de alınır.'","kaynak":"Adlî Kolluk Yönetmeliği m.9","zorluk":"kolay"},
    {"id":"31-S-035","soru":"Adlî Kolluk Yönetmeliği m.10'a göre adlî kolluk eğitimini başarıyla bitiren personele ne verilir ve adlî görevlerde kimler öncelikle görevlendirilir?","siklar":["Rütbe terfii verilir; kıdemli personel öncelikli görevlendirilir","Nişan verilir; nişan sahibi personel öncelikli görevlendirilir","Ek ödenek verilir; en yüksek ödenekli personel öncelikli görevlendirilir","Sertifika verilir; sertifikası olan kolluk personeli öncelikli görevlendirilir","Uzmanlık unvanı verilir; unvanı en yüksek personel öncelikli görevlendirilir"],"dogru":3,"aciklama":"m.10: 'Adlî kolluk eğitimini başarı ile bitiren personele, ilgili eğitim birimlerince sertifika verilir. Adli görevlerde öncelikli olarak sertifikası olan kolluk personeli görevlendirilir.'","kaynak":"Adlî Kolluk Yönetmeliği m.10","zorluk":"kolay"},
    {"id":"31-S-036","soru":"Adlî Kolluk Yönetmeliği m.11'e göre birden fazla Cumhuriyet başsavcılığının yetki çevresinde faaliyet gösteren adlî kolluk sorumluları hakkındaki değerlendirme raporu kim tarafından düzenlenir?","siklar":["İçişleri Bakanlığınca","Her yetki çevresindeki başsavcı tarafından ayrı ayrı","En üst dereceli kolluk amiri tarafından","Mülki idare amirinin belirlediği başsavcı tarafından","Adlî kolluk biriminin merkezinin bulunduğu yer Cumhuriyet başsavcısı tarafından, diğer yer başsavcılıklarının görüşü alınarak"],"dogru":4,"aciklama":"m.11 son fıkra: 'Birden fazla Cumhuriyet başsavcılığının yetki çevresinde faaliyet gösteren adlî kolluk sorumluları hakkında, değerlendirme raporları her yıl sonunda diğer yer Cumhuriyet başsavcılıklarının görüşü de alınarak adlî kolluk biriminin merkezinin bulunduğu yer Cumhuriyet başsavcısı tarafından düzenlenir.'","kaynak":"Adlî Kolluk Yönetmeliği m.11","zorluk":"orta"},
    {"id":"31-S-037","soru":"Adlî Kolluk Yönetmeliği m.12'ye göre meydana gelen olayın özelliğine göre soruşturmanın daha kapsamlı yapılabilmesi için ne yapılır?","siklar":["Kolluk âmiri, ihtiyaç duyduğu konularda ihtisaslaşmış personeli görevlendirir","Olay, doğrudan sulh ceza hâkimine devredilir","Soruşturma ertelenerek merkez teşkilata gönderilir","Mülki idare amiri bizzat soruşturmayı yürütür","En üst dereceli kolluk amiri soruşturmayı durdurur"],"dogru":0,"aciklama":"m.12: 'Meydana gelen olayın özelliğine göre, kolluk âmiri, soruşturma esnasında ihtiyaç duyduğu konularda ihtisaslaşmış personeli görevlendirerek soruşturmanın daha kapsamlı yapılmasını sağlar.' Ayrıca personelin konusunda uzmanlaşması için aynı/benzer görevlerde çalışması yönünde kendi teşkilatlarınca tedbir alınır.","kaynak":"Adlî Kolluk Yönetmeliği m.12","zorluk":"orta"},
    {"id":"31-S-038","soru":"Adlî Kolluk Yönetmeliği m.13/b hükmüne göre Cumhuriyet başsavcıları veya savcılarının yürütülen soruşturma evrakı üzerindeki yetkileri arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Gerektiğinde ilgili adlî kolluk biriminde soruşturma evrakını inceleme","Soruşturmayı resen kapatıp kovuşturmaya geçirme","Soruşturmaya ilişkin eksik görülen hususların ikmalini emretme","Soruşturma evrakı ve taraflarının bulunduğu hâl üzere Cumhuriyet başsavcılığına intikalini talimatlandırma","Adlî kolluk hizmetlerinin etkin yürütülmesi amacıyla adlî işlemleri her zaman denetleme"],"dogru":1,"aciklama":"m.13: 'b) Yürütülen soruşturma evrakını gerektiğinde ilgili adlî kolluk biriminde inceleyerek, soruşturmaya ilişkin eksik gördüğü hususların ikmalini emredebileceği gibi, soruşturma evrakı ve taraflarının bulunduğu hâl üzere Cumhuriyet başsavcılığına intikal ettirilmesi talimatını da verebilir.' ve (a) fıkrasıyla adlî işlemleri 'her zaman' denetler. Soruşturmayı resen kapatıp doğrudan kovuşturmaya geçirme yetkisi bu maddede sayılmaz; kovuşturmaya geçiş iddianamenin kabulüyle olur (m.3), bu bir inceleme/denetim yetkisi değildir.","kaynak":"Adlî Kolluk Yönetmeliği m.13","zorluk":"zor"},
    {"id":"31-S-039","soru":"Adlî Kolluk Yönetmeliği ....(1).... yürürlüğe girer ve hükümlerini ....(2).... birlikte yürütür. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yayımından altı ay sonra - İçişleri ve Millî Savunma Bakanları","yayımından üç ay sonra - Adalet ve İçişleri Bakanları","yayımı tarihinde - Adalet ve İçişleri Bakanları","yayımından bir yıl sonra - Adalet Bakanlığı tek başına","yayımı tarihinde - İçişleri Bakanlığı tek başına"],"dogru":2,"aciklama":"m.14: 'Bu Yönetmelik yayımı tarihinde yürürlüğe girer.' m.15: 'Bu Yönetmelik hükümlerini Adalet ve İçişleri Bakanları birlikte yürütür.'","kaynak":"Adlî Kolluk Yönetmeliği m.14, m.15","zorluk":"kolay"},
  ],
  56: [
    {"id":"32-S-001","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre 'gece vakti' aşağıdakilerden hangisidir?","siklar":["Güneşin doğmasından bir saat sonra başlayıp batmasından bir saat evvele kadar devam eden süre","Güneşin batmasından bir saat sonra başlayıp doğmasından bir saat evvele kadar devam eden süre","Saat 22.00'den sabah 06.00'ya kadar olan süre","Güneşin batışından doğuşuna kadar olan tüm süre","Saat 00.00'dan 05.00'e kadar olan süre"],"dogru":1,"aciklama":"m.4: 'Gece vakti: Güneşin batmasından bir saat sonra başlayan ve doğmasından bir saat evvele kadar devam eden süreyi... ifade eder.'","kaynak":"Aramalar Yön. m.4","zorluk":"kolay"},
    {"id":"32-S-002","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, bir suçun işlenmesinden birkaç gün sonra, olayla hiçbir organik bağı bulunmayan bir ihbar üzerine yakalanan kişi hakkındaki işlem 'suçüstü' kapsamında değerlendirilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4 suçüstü tanımı işlenmekte olan suçu, fiilin işlenmesinden hemen sonra takip edilerek yakalanmayı veya fiilin pek az önce işlendiğini gösteren eşya/delille yakalanmayı kapsar. Günler sonra, organik bağı olmayan bir ihbarla yakalanma bu tanıma girmez.","kaynak":"Aramalar Yön. m.4","zorluk":"orta"},
    {"id":"32-S-003","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, adli arama tanımında sayılan sınırlanabilecek özel hayat alanları arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Konut","İşyeri","Kişinin üzeri","Özel kâğıtları","Sosyal medya hesabı şifresi"],"dogru":4,"aciklama":"m.5: '...konutunda, işyerinde, kendisine ait diğer yerlerde, üzerinde, özel kâğıtlarında, eşyasında, aracında... yapılan araştırma işlemidir.' Sosyal medya hesabı şifresi bu sayımda yoktur.","kaynak":"Aramalar Yön. m.5","zorluk":"orta"},
    {"id":"32-S-004","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre makul şüpheye ilişkin aşağıdaki ifadelerden hangisi doğrudur?","siklar":["Kolluk memurunun kişisel sezgisi tek başına yeterlidir","İhbar veya şikâyet olmasa da makul şüphe her zaman var sayılır","Şüphenin somut olgulara dayanması şarttır","Makul şüphe yalnızca mahkeme kararıyla oluşur","Kişinin önceki sabıka kaydı tek başına yeterlidir"],"dogru":2,"aciklama":"m.6: 'Belirtilen konularda şüphenin somut olgulara dayanması şarttır.'","kaynak":"Aramalar Yön. m.6","zorluk":"orta"},
    {"id":"32-S-005","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre makul şüphenin belirlenmesinde göz önünde tutulacak unsurlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Aramanın yapılacağı zaman ve yer","İlgili kişinin davranış, tutum ve biçimleri","Kolluk memurunun taşındığından şüphelendiği eşyanın niteliği","İhbar veya şikâyeti destekleyen emarelerin varlığı","Kişinin daha önce hakkında açılmış idari para cezası kaydı"],"dogru":4,"aciklama":"m.6'da sayılan unsurlar zaman-yer, davranış/tutum, eşyanın niteliği ve ihbar/şikâyeti destekleyen emarelerdir. İdari para cezası kaydı metinde sayılmamıştır.","kaynak":"Aramalar Yön. m.6","zorluk":"zor"},
    {"id":"32-S-006","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısına ulaşılamazsa adli arama hangi makamın yazılı emriyle yapılabilir?","siklar":["Mülki âmirin","Baro başkanının","İl jandarma komutanının","Kolluk âmirinin","Adli kolluk sorumlusunun"],"dogru":3,"aciklama":"m.7: '...Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk âmirinin yazılı emriyle arama yapılabilir.'","kaynak":"Aramalar Yön. m.7","zorluk":"orta"},
    {"id":"32-S-007","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre kolluk âmirleri, konutta, iş yerinde ve kamuya açık olmayan kapalı alanlarda arama kararı verebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'Kolluk âmirlerince konutta, iş yerinde ve kamuya açık olmayan kapalı alanlarda arama kararı verilemez.' Bu yerlerde ancak hâkim kararı veya gecikmesinde sakınca varsa Cumhuriyet savcısının yazılı emri geçerlidir.","kaynak":"Aramalar Yön. m.7","zorluk":"kolay"},
    {"id":"32-S-008","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre Cumhuriyet başsavcılıklarınca, arama ile ilgili kararları vermek üzere ....(1).... saat süreyle nöbetçi Cumhuriyet savcısı görevlendirilir. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["8","12","24","36","48"],"dogru":2,"aciklama":"m.7: '...yirmidört saat süreyle nöbetçi Cumhuriyet savcısı görevlendirilir.'","kaynak":"Aramalar Yön. m.7","zorluk":"kolay"},
    {"id":"32-S-009","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre arama talep, karar veya emrinde açıkça gösterilmesi gereken hususlar arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Aramanın nedenini oluşturan fiil","Aranılacak kişi, konut veya diğer yerin adresi ya da eşya","Karar veya emrin geçerli olacağı zaman süresi","Aranılacak eşyanın elde edilmesi hâlinde el konulup konulmayacağı","Aramayı gerçekleştirecek kolluk görevlisinin adı, soyadı ve sicili"],"dogru":4,"aciklama":"m.7 uyarınca zorunlu içerik dört unsurdur: neden, kişi/adres/eşya, süre, el koyma durumu. Görevlinin kimlik bilgileri m.11'deki arama tutanağında yer alır, arama emrinde değil.","kaynak":"Aramalar Yön. m.7","zorluk":"zor"},
    {"id":"32-S-010","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre aşağıdaki durumlardan hangisinde, ayrıca bir arama emri ya da kararı ARANIR (yani karar gerekmeyen hâller arasında sayılmamıştır)?","siklar":["Yakalama emri bulunan kişi yakalandığında üstünde yapılacak aramada","Gözaltına alınan kişinin nezarethaneye konmadan önce yapılan üst aramasında","Bir işyerinde, önceden belirlenmiş plan dâhilinde yapılacak genel arama ve inceleme çalışmasında","Suçüstü hâlinde yapılan aramalarda","Gümrük kapılarında kaçak eşya sakladığından kuşkulanılan kişilerin gümrük görevlilerince aranmasında"],"dogru":2,"aciklama":"m.8'de sayılan karar gerekmeyen hâller arasında yakalama üzerine üst araması, nezarethane öncesi üst araması, suçüstü ve gümrük kontrolü vardır. İşyerinde önceden planlanmış genel arama bu istisnalar arasında değildir; m.7 uyarınca karar/emir gerekir.","kaynak":"Aramalar Yön. m.8","zorluk":"orta"},
    {"id":"32-S-011","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, kaçmakta olan kişilerin veya suç failinin yakalanması amacıyla takibi sırasında girilen araç, bina ve eklentilerinde yapılacak aramalar için ne gereklidir?","siklar":["Ayrıca bir arama emri ya da kararı aranmaz","Hâkim kararı şarttır","Cumhuriyet savcısının yazılı emri şarttır","Mülki âmirin yazılı emri şarttır","Kolluk âmirinin önceden yazılı onayı şarttır"],"dogru":0,"aciklama":"m.8/d: takip sırasında girilen yerlerdeki aramalarda ayrıca arama emri ya da kararı aranmaz.","kaynak":"Aramalar Yön. m.8","zorluk":"kolay"},
    {"id":"32-S-012","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, herkesin girip çıkabileceği kamuya açık alanlarda yapılan bilimsel/teknik olay yeri inceleme işlemleri için ne gerekir?","siklar":["Hâkim kararı gerekir","Mülki âmirin yazılı emri gerekir","Ayrıca bir emir veya karar gerekmez","Cumhuriyet savcısının sözlü onayı gerekir","Kolluk âmirinin önceden yazılı izni gerekir"],"dogru":2,"aciklama":"m.9: '...herkesin girip çıkabileceği kamuya açık alanlarda yapılması için bir emir veya karar gerekmez.'","kaynak":"Aramalar Yön. m.9","zorluk":"kolay"},
    {"id":"32-S-013","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, konut, işyeri ve kamuya açık olmayan kapalı alanlar DIŞINDAKİ yerlerde, Cumhuriyet savcısına ulaşılamadığı hâllerde olay yeri inceleme işlemi kimin yazılı emriyle gerçekleştirilir?","siklar":["Mülki âmirin","Baro başkanının","Adli kolluk büro amirinin","Kolluk âmirinin","İl jandarma komutanının"],"dogru":3,"aciklama":"m.9: '...Cumhuriyet savcısına ulaşılamadığı hâllerde ise konut, işyeri ve kamuya açık olmayan kapalı alanlar dışındaki yerlerde kolluk âmirinin yazılı emri üzerine gerçekleştirilir.'","kaynak":"Aramalar Yön. m.9","zorluk":"orta"},
    {"id":"32-S-014","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, hâkim kararı olmaksızın gerçekleştirilen bir el koyma işlemi ....(1).... saat içinde görevli hâkimin onayına sunulur; hâkim kararını el koymadan itibaren ....(2).... saat içinde açıklar, aksi hâlde el koyma kendiliğinden kalkar. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["48 - 24","12 - 24","24 - 48","24 - 72","36 - 48"],"dogru":2,"aciklama":"m.10: 'Hâkim kararı olmaksızın elkoyma işlemi, yirmidört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırksekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar.'","kaynak":"Aramalar Yön. m.10","zorluk":"zor"},
    {"id":"32-S-015","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, hâkim tesadüfen elde edilen delile ilişkin el koyma kararını süresinde açıklamazsa ne olur?","siklar":["El koyma kesinleşir","El koyma kendiliğinden kalkar","Dosya yeniden düzenlenip Cumhuriyet savcısına gönderilir","Süre bir kez daha uzatılabilir","Konu doğrudan mülki âmirin takdirine bırakılır"],"dogru":1,"aciklama":"m.10: '...aksi hâlde elkoyma kendiliğinden kalkar.'","kaynak":"Aramalar Yön. m.10","zorluk":"zor"},
    {"id":"32-S-016","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre adli arama tutanağında yer alması gereken hususlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Arama kararının veya yazılı emrin tarih ve sayısı","Aramanın yapıldığı yer, tarih ve saat","Arama işlemini yapanların adı, soyadı, sicili ve unvanı","Aranan kişinin banka hesap numarası ve kredi limiti","Arama sonucunda yaralanma veya maddi bir zarar meydana gelip gelmediği"],"dogru":3,"aciklama":"m.11'de sayılan hususlar arasında karar/emrin tarih-sayısı, yer-tarih-saat, arama işlemini yapanların kimlik bilgileri ve yaralanma/zarar durumu vardır; banka hesap bilgisi metinde yer almaz.","kaynak":"Aramalar Yön. m.11","zorluk":"orta"},
    {"id":"32-S-017","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre koruma altına alınan veya el konulan eşyanın tam bir listesi yapıldıktan sonra ne yapılır?","siklar":["Liste yalnızca kolluk arşivinde saklanır, ilgiliye bilgi verilmez","Liste doğrudan imha edilir","Liste resmî mühürle mühürlenir ve buna dair tutanağın bir sureti ilgiliye verilir","Liste noter onayına sunulur","Liste yalnızca Cumhuriyet savcısına gönderilir, tutanak düzenlenmez"],"dogru":2,"aciklama":"m.12: 'Koruma altına alınan veya el konulan eşyanın tam bir listesi yapılarak resmî mühürle mühürlenir. Bu eşyanın resmî mühürle mühürlendiğine dair tutanak tanzim edilerek, bir sureti ilgilisine verilir.'","kaynak":"Aramalar Yön. m.12","zorluk":"orta"},
    {"id":"32-S-018","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre avukat bürolarında arama hangi şartla yapılabilir?","siklar":["Sadece kolluk âmirinin yazılı emriyle","Mülki âmirin sözlü onayıyla","Mahkeme kararı ile ve Cumhuriyet savcısının denetiminde, baro başkanı veya temsilcisi hazır bulunarak","Baro başkanının tek başına kararıyla","Cumhuriyet savcısının sözlü talimatıyla, mahkeme kararı aranmaksızın"],"dogru":2,"aciklama":"m.13: 'Avukat büroları ancak mahkeme kararı ile ve kararda belirtilen olayla ilgili olarak Cumhuriyet savcısının denetiminde aranabilir. Baro başkanı veya onu temsil eden bir avukat aramada hazır bulundurulur.'","kaynak":"Aramalar Yön. m.13","zorluk":"orta"},
    {"id":"32-S-019","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, avukatın bürosunda ele geçen ve avukat-müvekkil arasındaki mesleki ilişkiye ait olduğu ileri sürülerek itiraz edilen eşyaya ilişkin kararın verilmesi ....(1).... saat içinde gerçekleşir. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["12","48","72","24","6"],"dogru":3,"aciklama":"m.13: 'Bu fıkrada öngörülen kararlar yirmidört saat içinde verilir.'","kaynak":"Aramalar Yön. m.13","zorluk":"zor"},
    {"id":"32-S-020","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre askerî mahallerde yapılacak arama kim tarafından yerine getirilir?","siklar":["Doğrudan Cumhuriyet savcısı tarafından","Mülki âmirin emriyle genel kolluk tarafından","Askerî savcının tek başına kararıyla","Cumhuriyet savcısının talep ve katılımıyla askerî makamlar tarafından","İl jandarma komutanının onayıyla"],"dogru":3,"aciklama":"m.14: 'Askerî mahallerde yapılacak arama Cumhuriyet savcısının talep ve katılımı ile askerî makamlar tarafından yerine getirilir.'","kaynak":"Aramalar Yön. m.14","zorluk":"kolay"},
    {"id":"32-S-021","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, arama sonucunda el koyma söz konusu olduğunda, Cumhuriyet savcısına ulaşılamadığı hâllerde el koyma işlemi kimin yazılı emriyle gerçekleştirilir?","siklar":["Kolluk âmirinin","Mülki âmirin","Baro başkanının","Mahkeme başkanının","Adli kolluk sorumlusunun"],"dogru":0,"aciklama":"m.15: '...Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk âmirinin yazılı emri ile elkoyma işlemi gerçekleştirilebilir.'","kaynak":"Aramalar Yön. m.15","zorluk":"orta"},
    {"id":"32-S-022","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, ispat aracı olarak yararlı görülen bir eşyayı yanında bulunduran kişi, bu eşyayı rızasıyla teslim etmezse eşyaya el konulabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.15: 'Yanında bulunduran kişinin rızasıyla teslim etmediği bu tür eşyaya elkonulabilir.'","kaynak":"Aramalar Yön. m.15","zorluk":"kolay"},
    {"id":"32-S-023","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre bilgisayar ve bilgisayar kütükleriyle ilgili işlemler bakımından aşağıdakilerden hangisi YANLIŞTIR?","siklar":["Şifrenin çözülememesi hâlinde bu araç ve gereçlere elkonulabilir","Şifre çözülüp gerekli kopyalar alındığında elkonulan cihazlar gecikme olmaksızın iade edilir","Elkoyma işlemi sırasında sistemdeki bütün verilerin yedeklemesi yapılır","Alınan yedekten çıkarılan elektronik kopya şüpheliye veya vekiline verilmez, yalnızca dosyada saklanır","Bilgisayar veya kütüklere elkoymaksızın da verilerin kopyası alınabilir"],"dogru":3,"aciklama":"m.17: '...alınan yedekten elektronik ortamda bir kopya çıkarılarak şüpheliye veya vekiline verilir ve bu husus tutanağa geçirilerek imza altına alınır.' D ifadesi bunun tam tersini iddia ettiği için yanlıştır.","kaynak":"Aramalar Yön. m.17","zorluk":"zor"},
    {"id":"32-S-024","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını incelemeye yetkili makam(lar) aşağıdakilerden hangisidir?","siklar":["Cumhuriyet savcısı ve hâkim","Kolluk âmiri","Mülki âmir","Baro başkanı","Adli kolluk büro amiri"],"dogru":0,"aciklama":"m.16: 'Hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını inceleme yetkisi, Cumhuriyet savcısı ve hâkime aittir.'","kaynak":"Aramalar Yön. m.16","zorluk":"kolay"},
    {"id":"32-S-025","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre umuma açık istirahat ve eğlence yerlerinin (otel, gazino, bar, internet kafe vb.) genel güvenlik ve asayiş yönünden denetimi, kolluk tarafından ayrı bir arama kararı beklenmeden kendiliğinden yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.18/a bu denetimi kolluk tarafından kendiliğinden yapılabilecek hâller arasında sayar.","kaynak":"Aramalar Yön. m.18","zorluk":"orta"},
    {"id":"32-S-026","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre önleme araması kararını vermeye kural olarak kim yetkilidir?","siklar":["Hâkim","Cumhuriyet savcısı","Kolluk âmiri","Vali yardımcısı","İl jandarma komutanı"],"dogru":0,"aciklama":"m.19: '...hâkim kararı veya gecikmesinde sakınca bulunan hâllerde mülkî âmirin yazılı emriyle... yapılan arama işlemidir.' Asıl karar mercii hâkimdir.","kaynak":"Aramalar Yön. m.19","zorluk":"orta"},
    {"id":"32-S-027","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre konutta, yerleşim yerinde ve kamuya açık olmayan özel işyerlerinde ve eklentilerinde önleme araması yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.19: 'Konutta, yerleşim yerinde ve kamuya açık olmayan özel işyerlerinde ve eklentilerinde önleme araması yapılamaz.'","kaynak":"Aramalar Yön. m.19","zorluk":"kolay"},
    {"id":"32-S-028","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre önleme araması sürecinde aşağıdaki adımlardan hangisi YER ALMAZ?","siklar":["Kolluk, makul sebeplerin oluştuğunu gösteren belirlemeleri önceden tespit eder","Belirlemeler, aramanın yapılacağı yer ve zamanla birlikte gerekçeli olarak mülkî âmire iletilir","Yetkili merci, talebi uygun bulursa hâkimden arama kararı talep eder","Gecikmesinde sakınca bulunan hâllerde yetkili merci yazılı arama emri verir","Kolluk âmiri, mülkî âmire danışmadan doğrudan hâkimden karar talep eder"],"dogru":4,"aciklama":"m.20 sürecinde kolluk önce mülkî âmire yazılı olarak iletir; hâkimden karar talebi de yetkili merci (mülkî âmir) eliyle yapılır. Kolluğun mülkî âmire danışmadan doğrudan hâkime başvurması metinde öngörülmemiştir.","kaynak":"Aramalar Yön. m.20","zorluk":"zor"},
    {"id":"32-S-029","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre özel güvenlik görevlileri, yangın, deprem gibi tabii afet durumlarında ve imdat istenmesi hâlinde ne yapabilir?","siklar":["Yalnızca dışarıdan gözlem yapabilir","Görev alanındaki işyeri ve konutlara girebilir","Konuta girmek için mutlaka hâkim kararı ister","Mülki âmirden yazılı izin almadan hiçbir şey yapamaz","Yalnızca genel kolluğu bekler, kendisi giremez"],"dogru":1,"aciklama":"m.21/c: 'Yangın, deprem gibi tabiî afet durumlarında ve imdat istenmesi hâlinde görev alanındaki işyeri ve konutlara girme.'","kaynak":"Aramalar Yön. m.21","zorluk":"orta"},
    {"id":"32-S-030","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, ayrıca bir arama emri ya da kararı gerekmeyen önleme araması hâlleri arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Devletçe kamu hizmetine özgülenmiş bina ve tesislere giriş-çıkışın belirli kurallara tâbi olduğu hâllerdeki aramada","Sivil hava meydanları, limanlar ve sınır kapılarında yapılan aramada","Olağanüstü Hal Valisinin emriyle yapılan aramada","Sıkıyönetim komutanının emriyle yapılan aramada","Bir işyerinin rutin ticari denetimi kapsamında vergi müfettişince yapılan aramada"],"dogru":4,"aciklama":"m.25'te sayılan karar gerekmeyen hâller kamu binaları, hava meydanı/liman/sınır kapısı, OHAL Valisi emri ve sıkıyönetim komutanı emridir. Vergi müfettişinin rutin ticari denetimi bu sayımda yoktur.","kaynak":"Aramalar Yön. m.25","zorluk":"orta"},
    {"id":"32-S-031","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre durdurma yetkisinin kullanılabilmesi için hangi derecede şüphe aranır?","siklar":["'Umma' derecesinde makul şüphe","Kesin şüphe","Kuvvetli şüphe","Basit bir ihbar","Somut delil şartı"],"dogru":0,"aciklama":"m.27: 'Durdurma yetkisinin kullanılabilmesi için, \"umma\" derecesinde makul şüphe bulunmalıdır.'","kaynak":"Aramalar Yön. m.27","zorluk":"kolay"},
    {"id":"32-S-032","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, arama yapılacak yerin konut veya yerleşim yeri olarak kullanılmadığının bilinmesi hâlinde kolluk nasıl davranır?","siklar":["Mutlaka önce mahkemeden yeni bir karar alır","Kapıyı çalmadan asla giremez","Yalnızca gündüz girebilir","Baro başkanının onayını bekler","İletişim kurmadan arama amacıyla içeri girer"],"dogru":4,"aciklama":"m.30: 'Aşağıdaki hâllerde iletişim kurmadan arama amacıyla kapalı yerlere ve eklentilerine girilir: a) Arama yapılacak olan yerin konut veya yerleşim yeri olarak kullanılmadığının bilinmesi...'","kaynak":"Aramalar Yön. m.30","zorluk":"orta"},
    {"id":"32-S-033","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre üst araması kim tarafından yapılır?","siklar":["Kişinin cinsiyetinde bulunan görevli tarafından","Karşı cinsiyetten bir görevli tarafından","Kıdemli olan herhangi bir görevli tarafından","Yalnızca kadın kolluk personeli tarafından, cinsiyet fark etmeksizin","Nöbetçi Cumhuriyet savcısı tarafından"],"dogru":0,"aciklama":"m.28: 'Üst araması, kişinin cinsiyetinde bulunan görevli tarafından yapılır.'","kaynak":"Aramalar Yön. m.28","zorluk":"kolay"},
    {"id":"32-S-034","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, üst ve eşya araması gerekli görüldüğü takdirde kişi başka bir yere götürülerek de yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.28: 'Üst ve eşya araması, kişinin veya aracın ilk durdurulduğu yerde veya o yerin yakınında, mümkün olduğu kadar başkalarının göremeyeceği tarzda yapılır. Başka yere götürülerek arama yapılamaz.'","kaynak":"Aramalar Yön. m.28","zorluk":"orta"},
    {"id":"32-S-035","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, kişi üst ve eşya araması sırasında dirençle karşı koyduğunda ne yapılır?","siklar":["Arama işleminden derhâl vazgeçilir","Durum mahkemeye bildirilip arama ileri bir tarihe ertelenir","Yalnızca sözlü ikna yöntemi denenir, hiçbir güç kullanılamaz","Üst ve eşya araması orantılı güç kullanılarak gerçekleştirilir","Doğrudan silah kullanılarak direnç kırılır"],"dogru":3,"aciklama":"m.28: 'Kişi direndiği takdirde üst ve eşya araması orantılı güç kullanılarak gerçekleştirilir.'","kaynak":"Aramalar Yön. m.28","zorluk":"orta"},
    {"id":"32-S-036","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, sahibi bulunmayan boş bir aracın aranması hâlinde ne yapılır?","siklar":["Araç, sahibi gelene kadar aranmadan bekletilir","Arama yapıldığını belirten ve tutanak kopyasının alınabileceği yeri gösteren bir not bırakılır","Araç doğrudan çekiciyle karakola götürülür","Herhangi bir belge bırakılmadan arama sonlandırılır","Aracın camı kırılarak içine tutanağın aslı bırakılır"],"dogru":1,"aciklama":"m.29: 'Boş araçların aranmasında, arama yapıldığını belirten bir not bırakılır. Bu notta, arama tutanağının bir kopyasının alınabileceği yer belirtilir.'","kaynak":"Aramalar Yön. m.29","zorluk":"orta"},
    {"id":"32-S-037","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre araç araması yalnızca gündüz saatlerinde yapılabilir, gece yapılamaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.29: 'Bu maddede yazılı işlemler gece de yapılabilir.'","kaynak":"Aramalar Yön. m.29","zorluk":"kolay"},
    {"id":"32-S-038","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, detaylı inceleme yapılması gereken hâllerde araç araması bakımından aşağıdakilerden hangisi doğrudur?","siklar":["Araç hiçbir şekilde başka bir yere götürülemez","Araç, detaylı inceleme yapılması gereken hâllerde başka yere götürülerek de aranabilir","Başka yere götürme yalnızca hâkim kararıyla mümkündür","Başka yere götürme yalnızca araç sahibinin onayına bağlıdır","Başka yere götürme yalnızca gündüz saatlerinde yapılabilir"],"dogru":1,"aciklama":"m.29: 'Detaylı inceleme yapılması gereken hâllerde, başka yere götürülerek arama yapılabilir.'","kaynak":"Aramalar Yön. m.29","zorluk":"zor"},
    {"id":"32-S-039","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, konut, işyeri veya diğer kapalı yerlerde gece adli arama yapılamayacağı gibi, bu yerlerde kolluk âmirinin yazılı emriyle de arama yapılamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.31: 'Konutta, işyerinde veya diğer kapalı yerlerde adlî arama gece yapılamaz. Ayrıca bu yerlerde kolluk âmirinin yazılı emriyle de arama yapılamaz.'","kaynak":"Aramalar Yön. m.31","zorluk":"orta"},
    {"id":"32-S-040","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, konut, işyeri veya diğer kapalı yerlerde gece adli aramanın yapılabileceği istisnai hâller arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["Suçüstü hâli","Gecikmesinde sakınca bulunan hâl","Firar eden kişi veya tutuklu ya da hükümlünün tekrar yakalanması hâli","Geceleyin herkesin girip çıkabileceği umuma açık eğlence yerleri","Kolluk âmirinin arama yapılmasını gerekli gördüğü her konut"],"dogru":4,"aciklama":"m.31'de sayılan istisnalar suçüstü, gecikmesinde sakınca, firarinin yakalanması ve umuma açık eğlence yerleridir. Kolluk âmirinin salt kendi takdiriyle her konutta arama yapabilmesi metinde yer almaz; aksine kolluk âmirinin yazılı emriyle bile bu yerlerde arama yapılamayacağı ayrıca belirtilmiştir.","kaynak":"Aramalar Yön. m.31","zorluk":"zor"},
    {"id":"32-S-041","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre önleme aramaları, denetimler ve kontroller ne zaman yapılabilir?","siklar":["Yalnızca gündüz","Yalnızca mülkî âmirin gece için özel izin vermesi hâlinde","Her zaman","Yalnızca suçüstü hâlinde gece yapılabilir","Yalnızca hâkim kararı varsa gece yapılabilir"],"dogru":2,"aciklama":"m.31: 'Önleme aramaları, denetimler ve kontroller her zaman yapılabilir.'","kaynak":"Aramalar Yön. m.31","zorluk":"orta"},
    {"id":"32-S-042","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, şüpheli veya sanık ile 5271 sayılı Kanuna göre tanıklıktan çekinebilecek kimseler arasındaki mektup ve belgelere, bu kimseler nezdinde bulundukça el konulamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16: 'Şüpheli veya sanık ile 5271 sayılı Ceza Muhakemesi Kanununun 45 ve 46 ncı maddelerine göre tanıklıktan çekinebilecek kimseler arasındaki mektuplara ve belgelere; bu kimselerin nezdinde bulundukça elkonulamaz.'","kaynak":"Aramalar Yön. m.16","zorluk":"orta"},
    {"id":"32-S-043","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, kolluk arama sırasında ele geçen belge veya kâğıtlara nasıl bakabilir?","siklar":["Ayrıntılı biçimde inceleyerek","Suçla ilgisi olup olmadığını tespit amacıyla, incelemeksizin","Hiçbir şekilde bakamaz","Ancak hâkim huzurunda inceleyerek","Yalnızca fotokopisini alarak inceleyebilir"],"dogru":1,"aciklama":"m.16: 'Kolluk, arama sırasında ele geçen belge veya kağıtlara, suçla ilgisi olup olmadığını tespit amacıyla, incelemeksizin bakabilir.'","kaynak":"Aramalar Yön. m.16","zorluk":"kolay"},
    {"id":"32-S-044","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, arama yapılırken kişinin avukatının aramada hazır bulunmasına engel olunabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.30: 'Kişinin avukatının aramada hazır bulunmasına engel olunamaz.'","kaynak":"Aramalar Yön. m.30","zorluk":"kolay"},
    {"id":"32-S-045","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, kasa gibi açılması özellik isteyen eşya nasıl açtırılır?","siklar":["Eşyanın sahibi zorla açmaya mecbur edilir","Doğrudan kırılarak içeriği dökülür","Kolluk tarafından veya masrafları kollukça karşılanmak üzere bu konudaki meslek erbabına açtırılır","Açılamıyorsa arama tamamen sona erdirilir","Yalnızca noter huzurunda açılabilir"],"dogru":2,"aciklama":"m.30: 'Kasa gibi, açılması özellik isteyen eşya, kolluk tarafından veya masrafları kollukça karşılanmak üzere bu konudaki meslek erbabına açtırılır.'","kaynak":"Aramalar Yön. m.30","zorluk":"orta"},
    {"id":"32-S-046","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, arama sırasında rastlanan özel kâğıt ve zarflar açılsa dahi içindeki yazılı bilgiler okunabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.30: 'Arama sırasında rastlanan özel kâğıt ve zarflar, içinde müsadereye tâbi bir eşya bulunması ihtimali dışında açılmaz; açılsa dahi yazılı bilgiler okunamaz.'","kaynak":"Aramalar Yön. m.30","zorluk":"orta"},
    {"id":"32-S-047","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, geceleyin herkesin girip çıkabileceği lokanta, bar, pavyon, gazino, meyhane gibi yerler ile kıraathanenin aranmasında tanık bulundurulması gerekmez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.30: 'Geceleyin herkesin girip çıkabileceği lokanta, bar, pavyon, gazino, meyhane gibi yerler ile kıraathane ve oyun oynatılan benzeri yerlerin aranmasında tanık bulundurulması gerekmez.'","kaynak":"Aramalar Yön. m.30","zorluk":"kolay"},
    {"id":"32-S-048","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre, avukatla ilgili postada el koyma durumunda ne yapılır?","siklar":["Postane müdürü doğrudan kararı verir","m.13'ün üçüncü fıkrasında öngörülen usul (zarfın mühürlenmesi ve hâkimden karar istenmesi) uygulanır","Baro başkanı tek başına inceleyip karar verir","Herhangi bir özel usul uygulanmaz, genel el koyma hükümleri geçerlidir","Cumhuriyet savcısı postayı doğrudan açıp inceler"],"dogru":1,"aciklama":"m.13: 'Postada el koyma durumunda (...) üçüncü fıkrada belirtilen usuller uygulanır.' Üçüncü fıkra, mesleki ilişki itirazında eşyanın mühürlü zarfa konularak hâkimden/mahkemeden karar istenmesini düzenler.","kaynak":"Aramalar Yön. m.13","zorluk":"zor"},
    {"id":"32-S-049","soru":"Adlî ve Önleme Aramaları Yönetmeliği'ne göre makul şüphenin var sayılabilmesi için aşağıdakilerden hangisinin bulunması gerekir?","siklar":["Kesinleşmiş bir mahkûmiyet kararının","İhbar veya şikâyeti destekleyen emarelerin","Kolluk memurunun yalnızca kişisel deneyiminin","Sanığın önceden ikrarda bulunmuş olmasının","Bir bilirkişi raporunun"],"dogru":1,"aciklama":"m.6: 'Makul şüphede, ihbar veya şikâyeti destekleyen emarelerin var olması gerekir.'","kaynak":"Aramalar Yön. m.6","zorluk":"orta"},
  ],
  57: [
    {"id":"YON33-S-001","soru":"Suç Eşyası Yönetmeliği'ne göre, aşağıdakilerden hangisi 'suç eşyası' tanımına girer?","siklar":["İspat aracı olarak yararlı görülen, suçta kullanılan veya suçun işlenmesine tahsis edilen ya da suçun işlenmesinde kullanılmak üzere hazırlanan, suçtan meydana gelen ya da üretimi, bulundurulması, kullanılması, taşınması, alım ve satımı suç oluşturan eşya","Yalnızca doğrudan suçun işlenmesinde kullanılan silah ve aletler","Suçun işlenmesiyle elde edilen veya suçun konusunu oluşturan maddî menfaatler ile bunların dönüştürülmesi sonucu ortaya çıkan ekonomik malvarlığı değerleri","Yalnızca mahkemece kesin olarak müsaderesine karar verilmiş taşınır mallar","Sadece kolluk tarafından el konulup emanet bürosuna fiilen teslim edilen eşya"],"dogru":0,"aciklama":"m.3/ı: 'Suç eşyası: İspat aracı olarak yararlı görülen, suçta kullanılan veya suçun işlenmesine tahsis edilen ya da suçun işlenmesinde kullanılmak üzere hazırlanan, suçtan meydana gelen ya da üretimi, bulundurulması, kullanılması, taşınması, alım ve satımı suç oluşturan eşyayı... ifade eder.'","kaynak":"YON33 m.3","zorluk":"kolay"},
    {"id":"YON33-S-002","soru":"Suç Eşyası Yönetmeliği'ne göre 'kazanç', suçun işlenmesiyle elde edilen veya suçun konusunu oluşturan ya da suçun işlenmesi için sağlanan maddî menfaatler ile bunların değerlendirilmesi veya dönüştürülmesi sonucu ortaya çıkan ekonomik malvarlığı değerlerini ifade eder.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3/ğ tanımı birebir bu şekildedir.","kaynak":"YON33 m.3","zorluk":"kolay"},
    {"id":"YON33-S-003","soru":"Suç Eşyası Yönetmeliği'ne göre, suç eşyası ile ilgili işlemler kimin sürekli gözetim ve denetimi altında emanet bürosunca yürütülür?","siklar":["Adalet Bakanlığı Ceza İşleri Genel Müdürlüğü","Cumhuriyet başsavcılığı","Adalet müfettişleri","Adalet komisyonu","İl jandarma komutanlığı"],"dogru":1,"aciklama":"m.4/1: 'Suç eşyası ile ilgili işlemler, Cumhuriyet başsavcılığının sürekli gözetim ve denetimi altında emanet bürosunca yürütülür.'","kaynak":"YON33 m.4","zorluk":"orta"},
    {"id":"YON33-S-004","soru":"Suç Eşyası Yönetmeliği'ne göre, adalet komisyonu bulunan yerlerde emanet memurluğu görevi, herhangi bir teklife gerek olmaksızın doğrudan Cumhuriyet başsavcısı tarafından belirlenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/2: 'Emanet memurunun atanmasına lüzum görülmeyen hâllerde bu görev, ilgili yer Cumhuriyet başsavcısının teklifi üzerine adalet komisyonunca, adalet komisyonu bulunmayan yerlerde bu yer Cumhuriyet başsavcısınca belirlenecek yazı işleri müdürü veya zabıt kâtiplerinden birine geçici olarak verilir.' Komisyon bulunan yerde karar komisyona aittir; başsavcı sadece teklif eder. Yalnız komisyon yoksa başsavcı doğrudan belirler.","kaynak":"YON33 m.4","zorluk":"orta"},
    {"id":"YON33-S-005","soru":"Suç Eşyası Yönetmeliği'ne göre, adalet dairelerinde suç eşyasının muhafazası için tahsis edilen muhkem yerin özellikleri arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Mümkünse penceresiz olması","Çift kilitli çelik ya da demir kapılı olması","Yılda en az bir kez adalet müfettişlerince mühürlenmesi","Kamera sistemi ile kontrol edilmesi","Rutubet almaması ve sürekli havalandırılması"],"dogru":2,"aciklama":"m.4/4: 'mümkün ise penceresiz, değil ise dışarıdan sökülemeyecek biçimde demir parmaklıklı pencereli, çift kilitli çelik ya da demir kapılı, rutubet almayan, havalandırması süreklilik arz eden ve yangına karşı her türlü tedbirin alındığı muhkem bir yer tahsis edilir. Bu yerler kamera sistemi ile kontrol edilir.' 'Yılda bir kez mühürleme' metinde yoktur.","kaynak":"YON33 m.4","zorluk":"orta"},
    {"id":"YON33-S-006","soru":"Suç Eşyası Yönetmeliği'ne göre, devlet sırrı niteliğindeki bilgileri içeren belge, CD, DVD, harici bellek ve benzeri aygıtlar yüksek güvenlikli kasada saklanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4/5 birebir bu şekildedir.","kaynak":"YON33 m.4","zorluk":"kolay"},
    {"id":"YON33-S-007","soru":"Suç Eşyası Yönetmeliği'ne göre, hâkim kararı olmaksızın elkoyma işlemi hangi sıraya göre yapılabilir?","siklar":["Önce kolluk amiri, ulaşılamazsa Cumhuriyet savcısının yazılı emriyle","Önce Cumhuriyet savcısının, gecikmesinde sakınca varsa kolluk amirinin yazılı emriyle","Yalnızca hâkim kararıyla, başka hiçbir merci elkoyma emri veremez","Hâkim kararı üzerine veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, savcıya ulaşılamadığı hâllerde kolluk amirinin yazılı emriyle","Önce mahallî mülki amirin, ardından Cumhuriyet savcısının yazılı emriyle"],"dogru":3,"aciklama":"m.5/2: 'Hâkim kararı üzerine veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk amirinin yazılı emri ile elkoyma işlemini yapan kolluk görevlilerince, suç eşyasına elkonulduğuna dair bir tutanak düzenlenir.'","kaynak":"YON33 m.5","zorluk":"orta"},
    {"id":"YON33-S-008","soru":"Suç Eşyası Yönetmeliği'ne göre, ispat aracı olarak yararlı görülen eşyayı yanında bulunduran kişi bu eşyayı rızasıyla teslim ederse, eşyaya 'elkonulmuş' sayılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/1: 'İspat aracı olarak yararlı görülen ya da eşya veya kazanç müsaderesinin konusunu oluşturan malvarlığı değerleri, muhafaza altına alınır. Yanında bulunduran kişinin rızasıyla teslim etmediği bu tür eşyaya elkonulabilir.' Rızayla teslimde eşya muhafaza altına alınır; elkoyma yalnızca rıza YOKSA söz konusudur.","kaynak":"YON33 m.5","zorluk":"orta"},
    {"id":"YON33-S-009","soru":"Suç Eşyası Yönetmeliği'ne göre, hâkim kararı olmaksızın yapılan elkoyma işlemi ....(1).... saat içinde görevli hâkimin onayına sunulur; hâkim kararını elkoymadan itibaren ....(2).... saat içinde açıklamazsa elkoyma kendiliğinden kalkar. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["48 - 24","12 - 24","24 - 72","48 - 72","24 - 48"],"dogru":4,"aciklama":"m.5/5: 'Hâkim kararı olmaksızın yapılan elkoyma işlemi yirmi dört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırk sekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar.'","kaynak":"YON33 m.5","zorluk":"zor"},
    {"id":"YON33-S-010","soru":"Suç Eşyası Yönetmeliği'ne göre, hâkim kararı olmaksızın yapılan elkoyma işlemi kırk sekiz saat içinde görevli hâkimin onayına sunulur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/5: onaya sunma süresi yirmi dört saattir; kırk sekiz saat ise hâkimin kararını açıklaması gereken süredir. İfadede iki süre yer değiştirmiştir.","kaynak":"YON33 m.5","zorluk":"orta"},
    {"id":"YON33-S-011","soru":"Suç Eşyası Yönetmeliği'ne göre, elkoyma işlemi suçtan zarar gören mağdura ne şekilde bildirilir?","siklar":["Cumhuriyet başsavcılığınca gecikmeksizin","Kolluk tarafından bir hafta içinde","Mahkemece kesinleşmeden önce","Emanet memurunca üç ay içinde","Bildirim zorunlu değildir, mağdurun talebi beklenir"],"dogru":0,"aciklama":"m.5/6: 'Elkoyma işlemi, suçtan zarar gören mağdura Cumhuriyet başsavcılığınca gecikmeksizin bildirilir.'","kaynak":"YON33 m.5","zorluk":"kolay"},
    {"id":"YON33-S-012","soru":"Suç Eşyası Yönetmeliği'ne göre, 5 inci maddedeki usule göre ambalajlanmamış veya mühürlenmemiş olan suç eşyası hakkında emanet memuru ne yapar?","siklar":["Eşyayı savcı onayıyla geçici olarak teslim alır","Eşyayı teslim alamaz","Eşyayı tutanakla teslim alıp sonradan mühürler","Eşyayı doğrudan mahkemeye gönderir","Eşyayı jandarma birlik deposuna nakleder"],"dogru":1,"aciklama":"m.7: 'Emanet memuru, 5 inci maddedeki usule göre ambalajlanmamış veya mühürlenmemiş olan suç eşyasını teslim alamaz.'","kaynak":"YON33 m.7","zorluk":"kolay"},
    {"id":"YON33-S-013","soru":"Suç Eşyası Yönetmeliği'ne göre, emanet bürosunda muhafaza altına alınan suç eşyası hangi ölçüte göre tasnif edilir ve nasıl kayıt altına alınır?","siklar":["Yalnızca soruşturma numarasına göre tasnif edilir, kayıt tutulmaz","Yalnızca değerine göre tasnif edilir, UYAP'a hiç işlenmez","Nitelik ve yıllarına göre tasnif edilir; depo/sıra/raf ile giriş-çıkış tarihleri barkod sistemiyle kaydedilir","Alfabetik olarak sahip adına göre tasnif edilir","Yalnızca ceza türüne göre tasnif edilir"],"dogru":2,"aciklama":"m.8/1-2: eşya 'nitelik ve yıllarına göre' tasnif edilir; emanet memuru 'suç eşyasının depoda muhafaza edildiği yeri, sırayı, rafı, depoya giriş ve çıkış tarihleri de dâhil olmak üzere yapılan tüm işlemleri gösterir şekilde barkod sistemiyle kaydeder.'","kaynak":"YON33 m.8","zorluk":"orta"},
    {"id":"YON33-S-014","soru":"Suç Eşyası Yönetmeliği'ne göre, elektronik eşyanın (bilgisayar, ses/görüntü kayıt aygıtları vb.) muhafazasında aşağıdakilerden hangisi aranmaz?","siklar":["Bozulmalarını engelleyecek uygun alanda saklanması","Nemden korunması","Isıdan korunması","Kimyasal ve biyolojik eşya ile aynı bölmede saklanması","Manyetik alandan korunması"],"dogru":3,"aciklama":"m.8/3: elektronik eşya 'nem, ısı, manyetik alan ve darbelerden korunmalarını sağlayacak müstakil uygun alanlarda muhafaza edilir.' m.8/4'e göre kimyasal/biyolojik eşya için de AYRI müstakil alanlar oluşturulur; ikisi aynı bölmede saklanmaz.","kaynak":"YON33 m.8","zorluk":"orta"},
    {"id":"YON33-S-015","soru":"Suç Eşyası Yönetmeliği'ne göre, mahkeme ve diğer resmî daireler tarafından incelenmek üzere istenilen suç eşyası emanet memurunca ne şekilde teslim edilir?","siklar":["Herhangi bir onaya gerek olmadan doğrudan teslim edilir","Yalnızca mahkeme başkanının yazılı emriyle teslim edilir","Adalet Bakanlığının onayıyla teslim edilir","İl jandarma komutanının onayıyla teslim edilir","Cumhuriyet savcısının onayıyla zimmet kaydına görevlinin imzası alınarak teslim edilir"],"dogru":4,"aciklama":"m.9/1: emanet memuru istenilen suç eşyasını 'isteyen makama, Cumhuriyet savcısının onayıyla zimmet kaydına görevlinin imzasını almak suretiyle teslim eder... Mahkemelerin ve Cumhuriyet başsavcılıklarının istekleri UYAP üzerinden güvenli elektronik imzalı olarak yapılması zorunludur.'","kaynak":"YON33 m.9","zorluk":"orta"},
    {"id":"YON33-S-016","soru":"Suç Eşyası Yönetmeliği'ne göre, iade edilmeyen suç eşyasının iade edilmeme sebebi, ilgili merciden ......... fasılalarla sorulur. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["Üçer aylık","Aylık","Altışar aylık","Yıllık","On beşer günlük"],"dogru":0,"aciklama":"m.9/4: 'İade edilmeyen suç eşyasının iade edilmeme sebebi, ilgili merciden üçer aylık fasılalarla sorulur.'","kaynak":"YON33 m.9","zorluk":"orta"},
    {"id":"YON33-S-017","soru":"Suç Eşyası Yönetmeliği'ne göre, kıymetli maden/taş, antika gibi fazla değerli eşyanın emanet bürosundaki kasaya konulup çıkarılması ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Kasa yalnızca emanet memuru tarafından tek başına açılıp kapatılır","Kasa en az iki kişi tarafından açılır ve kapanır; bu defter kasa içerisinde durur","Kasanın açılıp kapanmasına yalnızca Cumhuriyet başsavcısı bizzat karar verir ve bunu bizzat yapar","Kasa yılda yalnızca bir kez açılabilir","Kasa yalnızca banka görevlisi eşliğinde açılabilir"],"dogru":1,"aciklama":"m.10/1: 'Bu defter kasa içerisinde durur, kasa en az iki kişi tarafından açılır, kapanır. Bu göreve emanet memurundan başka kimin katılacağı Cumhuriyet başsavcılığınca tayin edilir.'","kaynak":"YON33 m.10","zorluk":"zor"},
    {"id":"YON33-S-018","soru":"Suç Eşyası Yönetmeliği'ne göre, elkonulan ve emanet bürolarında muhafazası Cumhuriyet başsavcılığınca sakıncalı görülen ateşli silahlar ile bunlara ait mermiler ve her türlü patlayıcı madde, mahkemece karar verilinceye kadar nerede muhafaza altına alınır?","siklar":["Mahallin en büyük mal memurluğu deposunda","İl emniyet müdürlüğü silah deposunda","Mahallî jandarma birlik komutanlıklarına ait mahfuz bina ve depolarda","Adalet Bakanlığı merkez deposunda","Cumhuriyet başsavcılığı emanet bürosu kasasında"],"dogru":2,"aciklama":"m.11/2: bu eşya 'mahkemece haklarında bir karar verilinceye kadar Cumhuriyet başsavcılığının yazılı emri ile mahallî jandarma birlik komutanlıklarına ait mahfuz bina ve depolarda muhafaza altına alınırlar.' Üç nüsha tutanakla teslim edilir.","kaynak":"YON33 m.11","zorluk":"orta"},
    {"id":"YON33-S-019","soru":"Suç Eşyası Yönetmeliği'ne göre, elkonulan kara, deniz ve hava araçları emanet bürosuna giriş kaydı yapıldıktan sonra kime teslim edilir?","siklar":["Mahallî jandarma birlik komutanlığına","İl emniyet müdürlüğü otopark birimine","Adalet Bakanlığı taşınır kayıt biriminde","Mahallin en büyük mal memurluğuna","Cumhuriyet başsavcılığı emanet bürosunda kalır"],"dogru":3,"aciklama":"m.12/2: 'Elkonulan kara, deniz ve hava araçlarının, emanet bürosuna girişi ve bu konu ile ilgili kayıt işlemleri ... yapıldıktan sonra, mahallin en büyük mal memurluğuna ... tüm bilgileri içeren bir tutanakla derhâl teslim edilir.' Tutanak üç nüsha düzenlenir.","kaynak":"YON33 m.12","zorluk":"kolay"},
    {"id":"YON33-S-020","soru":"Suç Eşyası Yönetmeliği'ne göre, aşağıdaki eşya-merci eşleşmelerinden hangisi yanlıştır?","siklar":["Ateşli silah ve patlayıcı madde → mahallî jandarma birlik komutanlığı","Kara, deniz ve hava aracı → mahallin en büyük mal memurluğu","Fikri/sınai mülkiyet suçlarında sayı/ebadı nedeniyle sığmayan CD/DVD/kitap (numune sonrası) → mahallin en büyük mal memurluğu","Değeri olmayıp süresinde alınmayan eşya → imha komisyonu","Ateşli silah ve patlayıcı madde → mahallin en büyük mal memurluğu"],"dogru":4,"aciklama":"m.11/2 ateşli silah ve patlayıcıyı mahallî jandarma birlik komutanlığına, m.12/2 aracı mahallin en büyük mal memurluğuna, m.10/2 fazla CD/DVD/kitabı mahallin en büyük mal memurluğuna, m.24/1 değersiz eşyayı imha komisyonuna bağlar. E, ateşli silah/patlayıcı için jandarma yerine mal memurluğunu göstererek m.11 ile m.12'yi karıştırır.","kaynak":"YON33 m.11, m.12, m.10, m.24","zorluk":"orta"},
    {"id":"YON33-S-021","soru":"Suç Eşyası Yönetmeliği'ne göre, Cumhuriyet savcısı, hâkim veya mahkemece verilen iade/elden çıkarma kararları en geç ....(1).... içinde başsavcılığa tevdi edilir; müsadere/iade kararı kesinleştiğinde ise karar örneği ....(2).... içinde UYAP'tan başsavcılığa gönderilir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["İki gün - bir hafta","Bir hafta - iki gün","Üç gün - on beş gün","Bir gün - bir ay","İki gün - bir ay"],"dogru":0,"aciklama":"m.16/1: 'kararlar, dosyadaki emanet makbuzu ile birlikte en geç iki gün içerisinde Cumhuriyet başsavcılığına tevdi edilir.' m.17/1: kesinleşen karar örneği 'bir hafta içerisinde UYAP'tan Cumhuriyet başsavcılığına gönderilir.'","kaynak":"YON33 m.16, m.17","zorluk":"zor"},
    {"id":"YON33-S-022","soru":"Suç Eşyası Yönetmeliği'ne göre, sahibine iadesine karar verilen eşyanın teslim ve tesellüm işlemleri kimin huzurunda yerine getirilir?","siklar":["İl jandarma komutanının","Cumhuriyet savcısının","Adalet komisyonu başkanının","Sulh ceza hâkiminin","Adalet müfettişinin"],"dogru":1,"aciklama":"m.18/1-b: 'Bu işlemler, Cumhuriyet savcısının huzurunda yerine getirilir ve düzenlenen teslim ve tesellüm tutanağına Cumhuriyet savcısı ve emanet memurunun imzaları ile şerh verilir.'","kaynak":"YON33 m.18","zorluk":"orta"},
    {"id":"YON33-S-023","soru":"Suç Eşyası Yönetmeliği'ne göre, müsadere konusu eşya veya maddî menfaatlere elkonulamadığı veya merciine teslim edilemediği hâllerde, bunların karşılığını oluşturan değerlerin müsaderesine ilişkin kesinleşmiş karar örneğinin infazı hangi kanun hükümlerine göre yapılır?","siklar":["5271 sayılı Ceza Muhakemesi Kanunu","5237 sayılı Türk Ceza Kanunu","6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun","2004 sayılı İcra ve İflas Kanunu","4721 sayılı Türk Medeni Kanunu"],"dogru":2,"aciklama":"m.18/1-e: karşılık değerlerin müsaderesine ilişkin kesinleşmiş karar örneği mal memurluğuna gönderilir; 'Bu kararların infazı, 21/7/1953 tarihli ve 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun hükümlerine göre yapılır.'","kaynak":"YON33 m.18","zorluk":"zor"},
    {"id":"YON33-S-024","soru":"Suç Eşyası Yönetmeliği'ne göre, emanet bürosuna teslim tarihinden itibaren ....(1).... içinde hakkında karar verilmemiş eşya, ilgili mahkemeden sorulmak üzere başsavcılığa bildirilir; mahkeme veya daire yazı işleri müdürü en geç ....(2).... içinde durumu bildirir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["Altı ay - bir ay","İki yıl - bir hafta","On beş gün - bir yıl","Bir yıl - on beş gün","Bir yıl - bir ay"],"dogru":3,"aciklama":"m.20/1-a: emanet memuru 'emanet bürosuna teslimi tarihinden itibaren bir yıl içerisinde, hakkında herhangi bir karar verilmemiş olan eşya' için başsavcılığa bildirir; ilgili yazı işleri müdürleri 'en geç on beş gün içinde' durumu bildirir.","kaynak":"YON33 m.20","zorluk":"orta"},
    {"id":"YON33-S-025","soru":"Suç Eşyası Yönetmeliği'ne göre, iadesine karar verilmiş olup usulüne uygun tebligata rağmen bir ay içinde sahipleri tarafından alınmayan eşya en geç kaç ay içinde satılır ve satışa karar verecek merci hangisidir?","siklar":["En geç bir ay içinde, sulh hukuk hâkimi","En geç üç ay içinde, asliye ceza mahkemesi","En geç iki ay içinde, Cumhuriyet başsavcısı","En geç altı ay içinde, sulh ceza hâkimi","En geç iki ay içinde, sulh ceza hâkimi"],"dogru":4,"aciklama":"m.21/1: eşya 'en geç iki ay içerisinde satılarak bedeli millî bankalardan birinde ... vadeli hesaba yatırılır. Satışa karar verecek merci suç eşyasının bulunduğu yer sulh ceza hâkimidir.'","kaynak":"YON33 m.21","zorluk":"orta"},
    {"id":"YON33-S-026","soru":"Suç Eşyası Yönetmeliği'ne göre, iadesine karar verilmiş olup da sahibi ölmüş veya hakkında gaiplik kararı alınmış bulunanlara ait eşya kime tevdi olunur?","siklar":["Yetkili sulh hukuk hâkimine","Sulh ceza hâkimine","Asliye hukuk mahkemesine","Cumhuriyet başsavcılığına","Mahallin en büyük mal memurluğuna"],"dogru":0,"aciklama":"m.23: 'İadesine karar verilmiş olup da sahibi ölmüş veya hakkında gaiplik kararı alınmış bulunanlara ait eşya, yetkili sulh hukuk hâkimine tevdi olunur.'","kaynak":"YON33 m.23","zorluk":"zor"},
    {"id":"YON33-S-027","soru":"Suç Eşyası Yönetmeliği'ne göre, değeri olmayan eşyanın imhasına ilişkin komisyon ve imha usulü hakkında aşağıdakilerden hangisi yanlıştır?","siklar":["Komisyona Cumhuriyet savcısı başkanlık eder","Komisyona hangi zabıt kâtibinin katılacağını doğrudan Cumhuriyet savcısı belirler","Komisyonda emanet memuru yer alır","Komisyonda bir zabıt kâtibi yer alır","İmha, komisyon huzurunda yapılır ve buna dair bir tutanak tanzim olunur"],"dogru":1,"aciklama":"m.24/1: imhaya 'Cumhuriyet savcısı başkanlığında, emanet memuru ve bir zabıt kâtibinden oluşan komisyonca' karar verilir; imha komisyon huzurunda yapılıp tutanak düzenlenir. m.24/2: 'imha komisyonuna hangi zabıt kâtibinin katılacağı, adalet komisyonlarınca, bulunmayan yerlerde kıdemli hâkim tarafından belirlenir' — Cumhuriyet savcısı tarafından değil.","kaynak":"YON33 m.24","zorluk":"orta"},
    {"id":"YON33-S-028","soru":"Suç Eşyası Yönetmeliği'ne göre, emanet bürosunda UYAP'ta tutulması zorunlu olan kayıtlar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Suç eşyası esas kaydı","Kasa kaydı","Personel özlük kaydı","Muhabere kaydı","Zimmet kaydı"],"dogru":2,"aciklama":"m.25/1: 'a) Suç eşyası esas kaydı, b) Kasa kaydı, c) Muhabere kaydı, ç) Zimmet kaydı, d) Kıymetli eşya kaydı.' Bu kayıtlar UYAP'a emanet memuru tarafından güvenli elektronik imza ile onaylanarak işlenir. 'Personel özlük kaydı' sayılan beş kayıt arasında yoktur.","kaynak":"YON33 m.25","zorluk":"kolay"},
    {"id":"YON33-S-029","soru":"Suç Eşyası Yönetmeliği'ne göre, satılacak suç eşyasının değerinin satış masraflarını karşılamayacağının belli olması hâlinde, satışa karar veren hâkimin kararı üzerine 24 üncü madde uyarınca (imha) işlem yapılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.21/3 birebir bu şekildedir.","kaynak":"YON33 m.21","zorluk":"orta"},
    {"id":"YON33-S-030","soru":"Suç Eşyası Yönetmeliği'nde öngörülen sürelerden hangisi doğru eşleştirilmiştir?","siklar":["Hâkimsiz elkoymanın onaya sunulması: kırk sekiz saat","Karar verilmemiş eşyanın mahkemeden sorulması: on beş gün","Bir ay içinde alınmayan eşyanın satılması: üç ay","İade edilmeyen eşyanın sebebinin sorulması: üçer aylık fasılalarla","Kesinleşen müsadere/iade kararının UYAP'tan gönderilmesi: iki gün"],"dogru":3,"aciklama":"m.9/4: iade edilmeyen eşyanın sebebi üçer aylık fasılalarla sorulur — doğru eşleştirme budur. A yanlış (onaya sunma 24 saattir, 48 saat hâkimin karar süresidir); B yanlış (mahkemeden sorma 1 yıl içinde, 15 gün mahkemenin cevap süresidir); C yanlış (satış süresi 2 aydır); E yanlış (UYAP'tan gönderme 1 hafta içindedir, 2 gün ise kesinleşmeden önceki karar tevdi süresidir - m.16/1).","kaynak":"YON33 m.5, m.9, m.20, m.21","zorluk":"zor"},
    {"id":"YON33-S-031","soru":"Suç Eşyası Yönetmeliği'ne göre, 'dış birim' tanımı aşağıdakilerden hangisidir?","siklar":["Adlî yargı ilk derece mahkemesi adalet komisyonu ile bölge adliye mahkemesi adalet komisyonu","Bölge adliye mahkemesi ceza daireleri","Adalet hizmetlerinin elektronik ortamda yürütülmesi amacıyla oluşturulan sistem","UYAP'a dâhil olmayan kamu kurumları ile özel kuruluşlar","Elektronik cihaz kullanılarak üzerinde işlem yapılabilen her türlü değer"],"dogru":3,"aciklama":"m.3/d: 'Dış birim: UYAP'a dâhil olmayan kamu kurumları ile özel kuruluşları,' ifade eder.","kaynak":"YON33 m.3","zorluk":"kolay"},
    {"id":"YON33-S-032","soru":"Suç Eşyası Yönetmeliği'ndeki 'güvenli elektronik imza' tanımına göre, aşağıdakilerden hangisi bu tanımın bir unsuru değildir?","siklar":["Münhasıran imza sahibinin tasarrufunda olan bir araçla oluşturulması","Nitelikli elektronik sertifikaya dayanması","İmza sahibinin kimliğinin tespitini sağlaması","İmzalanmış veride sonradan değişiklik yapılıp yapılmadığının tespitini sağlaması","Yalnızca mahkeme kararlarında geçerli olup diğer belgelerde geçerli olmaması"],"dogru":4,"aciklama":"m.3/f: 'Güvenli elektronik imza: Münhasıran imza sahibinin tasarrufunda olan güvenli elektronik imza oluşturma aracı ile oluşturulan, nitelikli elektronik sertifikaya dayanarak imza sahibinin kimliğinin ve imzalanmış elektronik veride sonradan herhangi bir değişiklik yapılıp yapılmadığının tespitini sağlayan, elle atılan imza ile aynı hukukî sonucu doğuran imzayı... ifade eder.' Tanım 'elle atılan imza ile aynı hukukî sonucu' der; belge türüne göre bir sınırlama yoktur.","kaynak":"YON33 m.3","zorluk":"orta"},
    {"id":"YON33-S-033","soru":"Suç Eşyası Yönetmeliği'ne göre, ağır ceza mahkemesi Cumhuriyet başsavcılıklarında emanet bürosu işlerine bakmak üzere ayrıca ....(1).... görevlendirilir; bu kişi kefalet altında değilse ....(2).... sayılı Kefalet Kanununa göre kefalete bağlanır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Zabıt kâtibi - 5271","Emanet memuru - 6183","Adalet komisyonu üyesi - 2802","Müdür - 4483","Müdür - 2489"],"dogru":4,"aciklama":"m.4/2: '...Ağır ceza mahkemesi Cumhuriyet başsavcılıklarında emanet bürosu işlerine bakmak üzere ayrıca müdür görevlendirilir. Görevlendirilen müdür ya da zabıt kâtibi kefalet altında değil ise, 2/6/1934 tarihli ve 2489 sayılı Kefalet Kanununa göre kefalete bağlanır.'","kaynak":"YON33 m.4","zorluk":"zor"},
    {"id":"YON33-S-034","soru":"Suç Eşyası Yönetmeliği'ne göre, elkoyma tutanağında yer alması gereken bilgiler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Elkonulan eşyanın takdir edilen değeri","Eşyanın hangi suçtan, kimden, nereden ve ne suretle alındığı","Eşya sahibinin daha önce aldığı adli sicil kaydı","İşlemin yapıldığı yer, tarih ve saat","Elkoyma işlemini yapan kolluk görevlilerinin açık kimlikleri"],"dogru":2,"aciklama":"m.5/3 tutanak içeriğini ayrıntılı sayar: eşyanın cinsi/miktarı/değeri, hangi suçtan-kimden-nereden-ne suretle alındığı, soruşturma evrakı numarası, hazır bulunanların kimlikleri, işlemin yeri-tarihi-saati, imza/parmak izi. 'Adli sicil kaydı' bu sayımda yer almaz.","kaynak":"YON33 m.5","zorluk":"orta"},
    {"id":"YON33-S-035","soru":"Suç Eşyası Yönetmeliği'ne göre, elkonulan eşya ambalajlandıktan sonra, açıldığında yeniden kullanılabilecek ve açılıp açılmadığı dışarıdan belli olmayacak şekilde bir mühür bandı, kurşun veya mum ile mühürlenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/4: mühür 'açıldığında yeniden kullanılamayacak derecede bozulan ve açıldığı belli olan' türden olmalıdır — ifadedeki iki nitelik de gerçeğin tam tersine çevrilmiştir.","kaynak":"YON33 m.5","zorluk":"orta"},
    {"id":"YON33-S-036","soru":"Suç Eşyası Yönetmeliği'ne göre, elkonulan eşyanın teslim alınması işlemleri kim tarafından, ne şekilde yerine getirilir?","siklar":["Yalnızca hâkim kararıyla ve doğrudan mahkeme yazı işleri müdürünce","Kolluk amirinin talimatıyla ve doğrudan jandarma birlik komutanlığınca","Cumhuriyet savcısının talimatı doğrultusunda emanet memurunca; emanet memuru bulunmadığında başsavcılıkça görevlendirilecek personelce tutanakla teslim alınıp en kısa zamanda emanet bürosuna teslim edilir","Adalet komisyonunun onayı olmadan hiçbir personel teslim alamaz","Emanet memuru bulunmasa dahi işlemler ertelenip yalnızca emanet memuru göreve döndüğünde yapılır"],"dogru":2,"aciklama":"m.5/7: 'Elkonulan eşyanın teslim alınmasına dair işlemler Cumhuriyet savcısının talimatı doğrultusunda emanet memurunca yerine getirilir. Bulunmadığı takdirde Cumhuriyet başsavcılığınca görevlendirilecek personel tarafından tutanakla teslim alınarak en kısa zamanda emanet bürosuna teslim edilir.'","kaynak":"YON33 m.5","zorluk":"kolay"},
    {"id":"YON33-S-037","soru":"Suç Eşyası Yönetmeliği'ne göre, elkoyma tutanağındaki bilgilerin doğruluğundan tereddüt edilmesi hâlinde, teslim alan görevli veya emanet memuru, eşyayı getiren kişiyle birlikte suç eşyasına ve delil özelliğine zarar vermeyecek şekilde mührü sökerek eşyayı inceleyebilir; bu husus tutanakla tespit edilip mutabakat sağlandıktan sonra eşya yeniden mühürlenir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5/8 birebir bu şekildedir.","kaynak":"YON33 m.5","zorluk":"zor"},
    {"id":"YON33-S-038","soru":"Suç Eşyası Yönetmeliği'ne göre, mahkeme veya resmî dairece incelenmek üzere gönderilen suç eşyasının mührünün inceleme sırasında bozulması veya sökülmesi hâlinde ne yapılır?","siklar":["Eşya artık emanet bürosuna kabul edilmez, doğrudan imha edilir","Yalnızca sözlü olarak durum bildirilir, tutanak tutulmasına gerek yoktur","Eşya, mühürsüz hâliyle olduğu gibi emanet bürosuna iade edilir","Eşya yeniden usulüne uygun olarak ambalajlanıp mühürlenir; en az iki nüsha tutanak tutulur, eşya değişikliğe uğramışsa iade tutanağında bu husus belirtilir","Tek nüsha tutanakla yetinilir ve eşyadaki değişiklik esas kaydına işlenmez"],"dogru":3,"aciklama":"m.9/2: 'Zorunluluk bulunmadıkça eşyanın mührü sökülmez. Ancak inceleme sırasında mühür bozulur veya sökülür ise eşya yeniden usulüne uygun olarak ambalajlanıp mühürlenir, bu durumda en az iki nüsha tutanak tutulması zorunlu olup incelenen eşya değişikliğe uğrar ise iade tutanağında bu husus belirtilir.'","kaynak":"YON33 m.9","zorluk":"orta"},
    {"id":"YON33-S-039","soru":"Suç Eşyası Yönetmeliği'ne göre, mahkeme veya resmî daireden iade edilen suç eşyasında emanet makbuzu veya açma-kapama-iade tutanağı gibi bir eksiklik tespit edilirse ne yapılır?","siklar":["Eşya kabul edilmez; gönderen makam eksikliği giderdikten sonra eşyayı tekrar emanet bürosuna iade etmek zorundadır","Eşya yine de kabul edilip eksiklik daha sonra tamamlanır","Eşya doğrudan mahallin en büyük mal memurluğuna gönderilir","Eksiklik varsa dahi emanet memuru eşyayı kabul edip esas kayda hiç işlemez","Eksiklik tespit edilirse eşya imha komisyonuna sevk edilir"],"dogru":0,"aciklama":"m.9/3: '...Mühürlü, etiketli, emanet makbuzu olmayan veya açma-kapama-iade tutanağı bulunmayan suç eşyası kabul edilmez. Gönderen makamın tespit edilen eksikliği gidermesinden sonra tekrar emanet bürosuna iade etmesi zorunludur.'","kaynak":"YON33 m.9","zorluk":"kolay"},
    {"id":"YON33-S-040","soru":"Suç Eşyası Yönetmeliği'ne göre, yetkisizlik veya görevsizlik kararı üzerine görevli mahkemenin emanetteki eşyayı istemesi hâlinde, eşyanın sayı veya ebat olarak fazla olması ya da naklinin büyük maliyet gerektirmesi durumunda dahi eşya mutlaka evrakın bulunduğu yere gönderilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.9/5: bu durumlarda ('suç eşyasının sayı veya ebat olarak fazlalığı veyahut da niteliği gereği nakli büyük maliyetler gerektirdiği ya da taşınması sırasında da suç eşyasının zarar görmesi muhakkak ise') eşya gönderilmeyip ilk bulunduğu yerde muhafaza edilir; 'mutlaka gönderilir' kuralı istisnasız değildir.","kaynak":"YON33 m.9","zorluk":"zor"},
    {"id":"YON33-S-041","soru":"Suç Eşyası Yönetmeliği'ne göre, m.10 kapsamında bozulacak veya değerini kaybedecek eşyanın erken satışı ya da tevdisi için yapılan masraflar nasıl karşılanır?","siklar":["Devlet bütçesinden doğrudan karşılanır","Cezaya veya güvenlik tedbirine mahkûm edilen sanıktan alınmak üzere kovuşturma giderlerinden karşılanır","Mağdurdan tahsil edilir","Adalet Bakanlığı döner sermayesinden karşılanır","Satış bedelinden düşülmeksizin emanet bürosu bütçesinden karşılanır"],"dogru":1,"aciklama":"m.10/4: '...Satış ve tevdi için yapılan masraflar cezaya veya güvenlik tedbirine mahkûm edilen sanıktan alınmak üzere kovuşturma giderlerinden karşılanır. Eşyanın satılması hâlinde satış bedeli, 14 üncü madde hükümleri doğrultusunda emanet bürosunca saklanır.'","kaynak":"YON33 m.10","zorluk":"orta"},
    {"id":"YON33-S-042","soru":"Suç Eşyası Yönetmeliği'ne göre, jandarma birlik komutanlığına teslim edilmiş ateşli silah veya patlayıcının, Cumhuriyet başsavcılığı ya da mahkemece istenmesi hâlinde depodan alınması hangi usulle yapılır?","siklar":["Jandarma birlik komutanlığına hitaben yazılan, emanet memuru ile Cumhuriyet savcısının imzalarını taşıyan bir yazıyla","Yalnızca emanet memurunun sözlü talebiyle","Yalnızca Cumhuriyet savcısının imzasını taşıyan bir yazıyla, emanet memurunun imzasına gerek yoktur","Adalet Bakanlığının onayı alınarak","Jandarma birlik komutanının kendi takdiriyle, herhangi bir yazıya gerek olmaksızın"],"dogru":0,"aciklama":"m.11/3: '...depodan alınma ve depoya iade işlemi; jandarma birlik komutanlığına hitaben yazılıp, emanet memuru ile birlikte Cumhuriyet savcısının imzalarını taşıyan ve eşyanın emanet memuruna teslimini öngören bir yazıya müsteniden yapılır.'","kaynak":"YON33 m.11","zorluk":"orta"},
    {"id":"YON33-S-043","soru":"Suç Eşyası Yönetmeliği'ne göre, jandarma birlik depolarında muhafazası miktar itibarıyla mümkün görülmeyen ateşli silah/patlayıcı maddeler hakkında, ....(1).... 'nın başvurusu üzerine ilgili hâkim veya mahkemeden alınacak kararla numune jandarma birlik deposunda alıkonularak, geri kalanı ....(2).... tarafından görevlendirilen birlik, bakım merkezi ile mühimmat ana depo ve bölüklerine teslim edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Cumhuriyet savcısı - Jandarma Genel Komutanlığı","Adalet müfettişi - İçişleri Bakanlığı","Birlik komutanı - Kara Kuvvetleri Komutanlığı","Emanet memuru - Millî Savunma Bakanlığı","Birlik komutanı - Jandarma Genel Komutanlığı"],"dogru":2,"aciklama":"m.11/5: '...birlik komutanının başvurusu üzerine; Cumhuriyet başsavcılıklarınca, ilgili hâkim veya mahkemeden alınacak kararla, gerektiği kadar numune jandarma birlik deposunda alıkonularak, jandarma birlik komutanlığınca Kara Kuvvetleri Komutanlığı tarafından görevlendirilen ilgili birlik, bakım merkezi ile mühimmat ana depo ve bölüklerine teslim olunur.'","kaynak":"YON33 m.11","zorluk":"zor"},
    {"id":"YON33-S-044","soru":"Suç Eşyası Yönetmeliği'ne göre, özel düzenleme bulunmayan hâllerde fiilen elkonulması gereken kara, deniz ve hava araçlarının teslim alınması işlemleri, Cumhuriyet savcısının talimatı doğrultusunda emanet bürosunca yerine getirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.12/1 birebir bu şekildedir.","kaynak":"YON33 m.12","zorluk":"kolay"},
    {"id":"YON33-S-045","soru":"Suç Eşyası Yönetmeliği'ne göre, suç eşyasının iadesine veya elden çıkarılmasına teminat ya da rayiç değerinin ödenmesi karşılığında karar verilmişse, bu ödemeye ait makbuz veya belge nereye yatırıldığını göstermelidir?","siklar":["Cumhuriyet başsavcılığı emanet bürosu kasasına","Adalet Bakanlığı merkez muhasebe birimine","İlgili bankanın vadesiz hesabına doğrudan sahibi adına","Adalet komisyonu veznesine","Mahallin en büyük mal memurluğuna"],"dogru":4,"aciklama":"m.16/3: 'Suç eşyasının iadesine veya elden çıkarılmasına, teminat ya da rayiç değerinin ödenmesi karşılığında karar verilmiş ise, bunun mahallin en büyük mal memurluğuna yatırıldığına dair makbuz ya da belge evraka eklenir.'","kaynak":"YON33 m.16","zorluk":"orta"},
    {"id":"YON33-S-046","soru":"Suç Eşyası Yönetmeliği'ne göre, iadesine karar verilen suç eşyası yabancı uyruklu bir kimseye aitse, bu kişinin müracaatı hâlinde eşya kime gönderilebilir?","siklar":["Yalnızca Türkiye'deki bir avukata","Yalnızca Dışişleri Bakanlığına","Doğrudan Interpol'e","Kendisine veya yabancının uyruğu bulunduğu devletin sefaret ya da konsolosluklarına","Adalet Bakanlığı Uluslararası Hukuk Genel Müdürlüğüne"],"dogru":3,"aciklama":"m.18/ç: 'İadesine karar verilen suç eşyası yabancı uyruklu bir kimseye ait ise müracaatı hâlinde kendisine veya yabancının uyruğu bulunduğu devletin sefaret veya konsolosluklarına gönderilir. Belgesi kartonunda saklanır.'","kaynak":"YON33 m.18","zorluk":"kolay"},
    {"id":"YON33-S-047","soru":"Suç Eşyası Yönetmeliği'ne göre, mahiyeti itibarıyla müsadereye konu edilemeyen ve emanete alınmış eşya, yargılama sonunda verilecek karar doğrultusunda ilgili dosyasında delil olarak muhafaza edilmek üzere mahkemesine gönderilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.18/d: 'Emanete alınmakla birlikte mahiyetleri itibarıyla müsadereye konu edilemeyen eşya, yargılama sonunda verilen bu yöndeki karar doğrultusunda, ilgili dosyasında delil olarak muhafaza edilmek üzere mahkemesine gönderilir. Mahkemeden alınacak alındı yazısının gün ve sayısı suç eşyası kaydına işlenir.'","kaynak":"YON33 m.18","zorluk":"orta"},
    {"id":"YON33-S-048","soru":"Suç Eşyası Yönetmeliği'ne göre, bir dava karara bağlandığı hâlde eşya hakkında müsadere veya iadeye ilişkin herhangi bir karar verilmediğinin anlaşılması durumunda ne yapılır?","siklar":["Eşya kendiliğinden sahibine iade edilmiş sayılır","İlgilisi veya Cumhuriyet savcısı, davayı gören ya da görmeye yetkili mahkemeden eşya hakkında karar verilmesini ister","Eşya doğrudan imha komisyonuna sevk edilir","Emanet memuru resen eşyayı müsadere edilmiş kabul ederek mal memurluğuna gönderir","Konu, adalet müfettişlerinin bir sonraki teftişine bırakılır"],"dogru":1,"aciklama":"m.20/1-b: 'İlgili oldukları iş veya davalar karara bağlanmış olup da eşya, mal varlığı değerleri veya paralar hakkında müsadere yahut iadeye ilişkin bir karar verilmemiş olduğunun anlaşılması hâlinde, ilgilisi veya Cumhuriyet savcısı, davayı gören ya da görmeye yetkili mahkemeden eşya, malvarlığı değerleri ve paralar hakkında bir karar verilmesini ister.'","kaynak":"YON33 m.20","zorluk":"orta"},
  ],
  58: [
    {"id":"YON34-S-001","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalanan kişinin hakkındaki işlemlerin tamamlanması amacıyla yetkili hâkim önüne çıkarılmasına veya serbest bırakılmasına kadar kanunî süre içinde özgürlüğünün geçici olarak kısıtlanıp alıkonulmasına ne ad verilir?","siklar":["Gözaltına alma","Yakalama","Muhafaza altına alma","Tutuklama","Sorgu"],"dogru":0,"aciklama":"m.4: \"Gözaltına alma: ...yakalanan kişinin hakkındaki işlemlerin tamamlanması amacıyla, yetkili hâkim önüne çıkarılmasına veya serbest bırakılmasına kadar kanunî süre içinde ... özgürlüğünün geçici olarak kısıtlanıp alıkonulmasını\" ifade eder.","kaynak":"Yakalama Yön. m.4","zorluk":"kolay"},
    {"id":"YON34-S-002","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre muhafaza altına alma; yetkili merci önüne çıkarılması gereken kişilerin ilgili kurum veya kişilerce teslim alınana kadar, sağlıklarına zarar vermeyecek şekilde ve zorunlu olduğu ölçüde özgürlüklerinin kısıtlanıp alıkonulmasıdır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.4 tanımıyla birebir örtüşür: \"Muhafaza altına alma: ... teslim alınana kadar sağlıklarına zarar vermeyecek şekilde ve zorunlu olduğu ölçüde özgürlüklerinin kısıtlanıp alıkonulmasını\" ifade eder.","kaynak":"Yakalama Yön. m.4","zorluk":"orta"},
    {"id":"YON34-S-003","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre 'toplu suç' tanımında, aralarında iştirak iradesi bulunmasa dahi en az kaç kişi tarafından işlenmesi aranır?","siklar":["İki","Üç","Dört","Beş","Sayı aranmaz, yalnız birlikte hareket yeterlidir"],"dogru":1,"aciklama":"m.4: \"Toplu suç: Aralarında iştirak iradesi bulunmasa da üç veya daha fazla kişi tarafından işlenen suçu\" ifade eder. Asgari sayı üçtür.","kaynak":"Yakalama Yön. m.4","zorluk":"kolay"},
    {"id":"YON34-S-004","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, hangi evrenin başlamasından itibaren hükmün kesinleşmesine kadar suç şüphesi altında bulunan kişi 'sanık' olarak tanımlanır?","siklar":["Soruşturma","Yakalama","Kovuşturma","Gözaltı","İfade alma"],"dogru":2,"aciklama":"m.4: \"Sanık: Kovuşturmanın başlamasından itibaren, hükmün kesinleşmesine kadar, suç şüphesi altında bulunan kişiyi\" ifade eder. Soruşturma evresindeki kişi ise 'şüpheli'dir.","kaynak":"Yakalama Yön. m.4","zorluk":"orta"},
    {"id":"YON34-S-005","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, gecikmesinde sakınca bulunan ve Cumhuriyet savcısına veya derhâl âmirlerine müracaat imkânı olmayan hâllerde, hakkında yakalama emri düzenlenmesi gereken bir kişiyle karşılaşan kolluk görevlisi ne yapar?","siklar":["Savcıdan yazılı emir gelmeden hiçbir işlem yapamaz","Yalnızca sulh ceza hâkiminin onayıyla yakalayabilir","Durumu il jandarma komutanına bildirip beklemek zorundadır","Kişiyi doğrudan yakalayabilir","Ancak suçüstü hâli sona erdikten sonra yakalayabilir"],"dogru":3,"aciklama":"m.5/a: kolluk görevlileri \"gecikmesinde sakınca bulunan ve Cumhuriyet savcısına veya derhâl âmirlerine müracaat imkânı olmayan hâllerde... yakalayabilir.\" Savcıya ulaşılamadığında kolluk beklemeden doğrudan yakalar.","kaynak":"Yakalama Yön. m.5","zorluk":"orta"},
    {"id":"YON34-S-006","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, kimliğini bir belgeyle veya güvenilir kişilerin tanıklığıyla ispat edemeyen ve gösterdiği belgenin doğruluğundan şüphe edilen kişi, aranan kişilerden olup olmadığı anlaşılıncaya kadar en çok kaç saat yakalama ve muhafaza altına alınabilir?","siklar":["12","48","72","Süre sınırı yoktur","24"],"dogru":4,"aciklama":"m.5: \"...yirmidört saati geçmemek üzere, yakalama ve muhafaza altına almaya yetkilidir.\" Süre en çok 24 saattir.","kaynak":"Yakalama Yön. m.5","zorluk":"kolay"},
    {"id":"YON34-S-007","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, kimliğini ispat edemeyen bir kişi, kimliği belirleninceye kadar en çok 48 saat yakalama ve muhafaza altına alınabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5'te kimliği belirsiz kişi için süre açıkça \"yirmidört saat\"tir; 48 saat, m.13'te CMK 250/1 kapsamındaki suçlar için öngörülüp Danıştay 10. D. 9/10/2024 E.:2024/1960 kararıyla yürütmesi durdurulan ayrı ve güncel olmayan bir fıkraya aittir, kimliği belirsiz kişiyle ilgisi yoktur.","kaynak":"Yakalama Yön. m.5","zorluk":"zor"},
    {"id":"YON34-S-008","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre aşağıdaki hâllerden hangisinde herkes tarafından geçici yakalama yapılabilir?","siklar":["Kişiye suçu işlerken rastlanması","Şüphelinin ifade vermeyi reddetmesi","Şüphelinin yurt dışına çıkma ihtimalinin bulunması","Kolluğun bu yönde talimat vermesi","Cumhuriyet savcısının yazılı emri bulunması"],"dogru":0,"aciklama":"m.5: \"Aşağıda belirtilen hâllerde, herkes tarafından geçici olarak yakalama yapılabilir: a) Kişiye suçu işlerken rastlanması, b) Suçüstü bir fiilden dolayı izlenen kişinin kaçması ihtimalinin bulunması veya hemen kimliğini belirleme imkânının bulunmaması.\"","kaynak":"Yakalama Yön. m.5","zorluk":"orta"},
    {"id":"YON34-S-009","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre aşağıdakilerden hangisi kolluk görevlilerinin yakalama yetkisi kapsamında sayılan hâllerden biri değildir?","siklar":["Kolluğun verdiği emre itaatsizlik edenler","Ruhsatsız işyeri açan esnaf","Usulüne aykırı şekilde ülkeye girmek isteyenler","Görev yaparken kolluğa mukavemette bulunanlar","Uyuşturucu ve uyarıcı maddeleri alan, satan veya bulunduran kişiler"],"dogru":1,"aciklama":"m.5/b,c,e,i bentlerinde sırasıyla emre itaatsizlik (b), mukavemet (c), uyuşturucu (e) ve usulsüz giriş/sınır dışı (i) hâlleri sayılmıştır. \"Ruhsatsız işyeri açan esnaf\" m.5'in hiçbir bendinde yer almaz; bu, idari/başka mevzuatın konusudur.","kaynak":"Yakalama Yön. m.5","zorluk":"orta"},
    {"id":"YON34-S-010","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, toplum için tehlike teşkil eden akıl hastası, uyuşturucu/uyarıcı madde veya alkol tutkunu, serseri veya hastalık bulaştırabilecek kişiler hangi amaçla yakalanabilir?","siklar":["Cezalandırılmaları için","Yalnızca kimlik tespiti için","Bir kurumda tedavi, eğitim ve ıslahı için alınan tedbirlerin yerine getirilmesi amacıyla","Seçim güvenliğini sağlamak için","Sadece istatistiksel kayıt tutmak için"],"dogru":2,"aciklama":"m.5/h: \"Bir kurumda tedavi, eğitim ve ıslahı için kanunlarla belirtilen esaslara uygun olarak, alınan tedbirlerin yerine getirilmesi amacıyla toplum için tehlike teşkil eden... kişileri... yakalayabilir.\"","kaynak":"Yakalama Yön. m.5","zorluk":"orta"},
    {"id":"YON34-S-011","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre yakalanan kişiye, yakalama sebebi ve hakkındaki iddialar ile susma, müdafiden yararlanma ve itiraz hakları kural olarak nasıl bildirilir?","siklar":["Yalnızca sözlü olarak","Yalnızca avukatı geldikten sonra","Sadece nezarethaneye girişte sözlü olarak","Herhâlde yazılı olarak, bunun hemen mümkün olmaması hâlinde sözlü olarak","Yakalamadan 24 saat sonra yazılı olarak"],"dogru":3,"aciklama":"m.6: \"...yazılı, bunun hemen mümkün olmaması hâlinde sözlü olarak derhâl bildirilir.\" Kural yazılı bildirimdir; sözlü bildirim istisnadır.","kaynak":"Yakalama Yön. m.6","zorluk":"orta"},
    {"id":"YON34-S-012","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalanan veya nakledilen her kişiye, kaçma veya tehlike belirtisi aranmaksızın kural olarak kelepçe takılır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: \"...kaçacaklarına ya da kendisi veya başkalarının hayat ve beden bütünlükleri bakımından tehlike arz ettiğine ilişkin belirtilerin varlığı hâllerinde kelepçe takılabilir.\" Kelepçe kural değil, belirtilerin varlığına bağlı istisnadır.","kaynak":"Yakalama Yön. m.7","zorluk":"kolay"},
    {"id":"YON34-S-013","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalanan veya gözaltına alınan kişi yabancı ise ve durumun bildirilmesine yazılı olarak karşı çıkmamışsa, durum kime haber verilir?","siklar":["Yalnızca Dışişleri Bakanlığına","Uluslararası Kızılhaç'a","Göç İdaresi Genel Müdürlüğüne","Türkiye'deki herhangi bir yabancı derneğe","Vatandaşı olduğu ülkenin büyükelçiliği veya konsolosluğuna"],"dogru":4,"aciklama":"m.8: \"Yakalanan veya gözaltına alınan kişi yabancı ise, yazılı olarak karşı çıkmaması hâlinde, durumu vatandaşı olduğu ülkenin büyükelçiliği veya konsolosluğuna haber verilir.\"","kaynak":"Yakalama Yön. m.8","zorluk":"orta"},
    {"id":"YON34-S-014","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre hekim raporu üç nüsha hâlinde düzenlenir; birinci nüsha raporu tanzim eden sağlık kuruluşunda saklanır, ikinci nüshası ....(1)...., üçüncü nüshası ise soruşturma dosyasına eklenmek üzere ....(2).... verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["gözaltına alınana - ilgili kolluk görevlisine","müdafiine - Cumhuriyet savcısına","mahalli mülki amire - sulh ceza hâkimine","ailesine - baro başkanlığına","valiliğe - adli tıp kurumuna"],"dogru":0,"aciklama":"m.9: \"...ikinci nüshası gözaltına alınana, üçüncü nüsha ise soruşturma dosyasına eklenmek üzere ilgili kolluk görevlisine verilir.\"","kaynak":"Yakalama Yön. m.9","zorluk":"orta"},
    {"id":"YON34-S-015","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, gözaltına alınan kişinin ifadesini alan veya soruşturmayı yürüten kolluk görevlisi ile bu kişiyi tıbbî muayeneye götüren kolluk görevlisinin aynı kişi olması gerekir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.9: \"...ifadesini alan veya soruşturmayı yürüten kolluk görevlisi ile bu kişiyi tıbbî muayeneye götüren kolluk görevlisinin farklı olması zorunludur. Ancak personel yetersizliği nedeniyle farklı kolluk görevlisinin bulunmaması hâlinde bu durum belgelendirilir.\"","kaynak":"Yakalama Yön. m.9","zorluk":"orta"},
    {"id":"YON34-S-016","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, gözaltı birimine getirilen bir kadının üst veya vücudunun aranması kim tarafından yapılır?","siklar":["Herhangi bir kolluk görevlisi tarafından","Bir kadın görevli veya bu amaçla görevlendirilecek diğer bir kadın tarafından","Yalnızca nöbetçi amiri tarafından","Gözaltı ve nezarethane sorumlusu tarafından, cinsiyet gözetmeksizin","Adlî tabip tarafından"],"dogru":1,"aciklama":"m.10/a: \"Kadının üst veya vücudunun aranması, bir kadın görevli veya bu amaçla görevlendirilecek diğer bir kadın tarafından yapılır.\"","kaynak":"Yakalama Yön. m.10","zorluk":"kolay"},
    {"id":"YON34-S-017","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, zarurî hâller dışında nezarethanede en fazla kaç kişi bir arada bulundurulabilir?","siklar":["3","4","5","7","10"],"dogru":2,"aciklama":"m.11/b: \"Nezarethanede zarurî hâller dışında beşten fazla kişi bir arada bulundurulmaz.\" Azami sayı 5'tir.","kaynak":"Yakalama Yön. m.11","zorluk":"kolay"},
    {"id":"YON34-S-018","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre gözaltı süresi, yakalama anından itibaren en çok ....(1)... saati geçemez; yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre ise en çok ....(2)... saat olabilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["12 - 24","24 - 48","48 - 24","24 - 12","24 - 24"],"dogru":3,"aciklama":"m.13: \"Gözaltı süresi... yirmidört saati geçemez. Yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre oniki saatten fazla olamaz.\" Gözaltı 24 saat, sevk yolu ayrıca en çok 12 saattir.","kaynak":"Yakalama Yön. m.13","zorluk":"orta"},
    {"id":"YON34-S-019","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalama yerine en yakın hâkim veya mahkemeye gönderilmesi için zorunlu süre, yirmidört saatlik gözaltı süresi hesabına dâhil edilmez; bu süre ayrıca ve en çok oniki saat olarak uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.13: \"Gözaltı süresi, yakalama yerine en yakın hâkim veya mahkemeye gönderilmesi için zorunlu süre hariç, yakalama anından itibaren yirmidört saati geçemez. Yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre oniki saatten fazla olamaz.\" Sevk yolu süresi 24 saatin dışında, ayrıca sayılır.","kaynak":"Yakalama Yön. m.13","zorluk":"zor"},
    {"id":"YON34-S-020","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, toplu olarak işlenen suçlarda Cumhuriyet savcısı gözaltı süresini her defasında ....(1).... günü geçmemek üzere, en çok ....(2).... gün süreyle yazılı olarak uzatabilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["iki - altı","iki - dört","bir - beş","üç - yedi","bir - üç"],"dogru":4,"aciklama":"m.14: \"...Cumhuriyet savcısı gözaltı süresini her defasında bir günü geçmemek üzere, üç gün süreyle uzatılmasına yazılı olarak emir verebilir.\" Her defasında 1 gün, toplamda 3 güne kadar.","kaynak":"Yakalama Yön. m.14","zorluk":"orta"},
    {"id":"YON34-S-021","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, Anayasanın 120 nci maddesi gereğince olağanüstü hâl ilân edilen bölgelerde, CMK m.250/1 kapsamına giren suçlardan yakalanan kişiler hakkında dört gün olarak belirlenen süre, kimin talebi ve kimin kararıyla en çok kaç güne kadar uzatılabilir?","siklar":["Cumhuriyet savcısının talebi ve hâkim kararıyla 7 güne","Kolluk âmirinin talebi ve valinin kararıyla 5 güne","Sulh ceza hâkiminin talebi ve savcı kararıyla 10 güne","İçişleri Bakanının onayıyla süresiz","Cumhuriyet başsavcısının tek başına kararıyla 7 güne"],"dogru":0,"aciklama":"m.14: \"...dört gün olarak belirlenen süre, Cumhuriyet savcısının talebi ve hâkim kararı ile yedi güne kadar uzatılabilir.\" Uzatma iki şarta bağlıdır: savcı talebi + hâkim kararı, üst sınır 7 gündür.","kaynak":"Yakalama Yön. m.14","zorluk":"zor"},
    {"id":"YON34-S-022","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalama veya gözaltına alma işlemine ya da gözaltı süresinin uzatılmasına karşı serbest bırakılmayı sağlamak için sulh ceza hâkimine aşağıdakilerden hangisi başvuramaz?","siklar":["Yakalanan kişinin kendisi","Yakalanan kişinin işvereni","Müdafi","Yakalanan kişinin eşi","Yakalanan kişinin birinci veya ikinci derece kan hısımı"],"dogru":1,"aciklama":"m.15: \"...yakalanan kişi, müdafi veya kanunî temsilcisi, eşi ya da birinci veya ikinci derecede kan hısımı hemen serbest bırakılmasını sağlamak için sulh ceza hâkimine başvurabilir.\" İşveren bu sayımda yer almaz.","kaynak":"Yakalama Yön. m.15","zorluk":"orta"},
    {"id":"YON34-S-023","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, gözaltı süresinin dolması veya sulh ceza hâkiminin kararı üzerine serbest bırakılan kişi hakkında, aynı nedenle yeniden yakalama işlemi hangi şart(lar) gerçekleşmedikçe uygulanamaz?","siklar":["Yalnızca yeni bir tanık ifadesi yeterlidir","Yalnızca sulh ceza hâkiminin re'sen kararı","Yeni ve yeterli delil elde edilmesi ile birlikte Cumhuriyet savcısının kararı","Kişinin yeniden şüpheli sıfatını kazanması yeterlidir","Herhangi bir şart aranmaz, kolluk her zaman yeniden yakalayabilir"],"dogru":2,"aciklama":"m.18: \"...yakalamaya neden olan fiille ilgili yeni ve yeterli delil elde edilmedikçe ve Cumhuriyet savcısının kararı olmadıkça bir daha aynı nedenle yakalama işlemi uygulanamaz.\" İki şart birlikte aranır: yeni-yeterli delil + savcı kararı.","kaynak":"Yakalama Yön. m.18","zorluk":"orta"},
    {"id":"YON34-S-024","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, fiili işlediği zaman oniki yaşını doldurmamış olanlar suç nedeniyle yakalanamaz; sağır ve dilsizlerde bu yaş sınırı ....(1)....'dir. Oniki-onsekiz yaş arasındaki çocuklar suç nedeniyle yakalanabilir, ancak yakınları ve müdafiye haber verilerek derhâl ....(2)....'na sevk edilirler. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on dört - valiliğe","on altı - il emniyet müdürlüğüne","on üç - jandarma komutanlığına","on beş - Cumhuriyet başsavcılığına","on beş - sulh ceza mahkemesine"],"dogru":3,"aciklama":"m.19/a: \"...onbeş yaşını doldurmamış sağır ve dilsizler; suç nedeni ile yakalanamaz...\" ve m.19/b: \"...bu çocuklar, yakınları ile müdafiye haber verilerek derhâl Cumhuriyet başsavcılığına sevk edilirler.\"","kaynak":"Yakalama Yön. m.19","zorluk":"orta"},
    {"id":"YON34-S-025","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, oniki yaşını doldurmamış çocuklar suç nedeniyle yakalanamaz; ancak kimlik ve suç tespiti amacıyla yakalanabilir ve kimlik tespitinden hemen sonra serbest bırakılırlar.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.19/a: \"Suç nedeni ile yakalanamaz ve hiçbir suretle suç tespitinde kullanılamaz. Kimlik ve suç tespiti amacı ile yakalama yapılabilir. Kimlik tespitinden hemen sonra serbest bırakılır.\"","kaynak":"Yakalama Yön. m.19","zorluk":"kolay"},
    {"id":"YON34-S-026","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, soruşturma evresinde ifade almada en çok kaç müdafi hazır bulunabilir?","siklar":["1","2","4","5","3"],"dogru":4,"aciklama":"m.20: \"Soruşturma evresinde, ifade almada en çok üç müdafi hazır bulunabilir.\"","kaynak":"Yakalama Yön. m.20","zorluk":"kolay"},
    {"id":"YON34-S-027","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre aşağıdakilerden hangisi, şüpheli veya sanığın talebi aranmaksızın kendisine bir müdafi görevlendirilmesini gerektiren hâllerden biri değildir?","siklar":["Şüpheli veya sanığın yabancı uyruklu olması","Şüpheli veya sanığın onsekiz yaşını doldurmamış olması","Şüpheli veya sanığın sağır veya dilsiz olması","Üst sınırı en az beş yıl hapis cezasını gerektiren bir suçtan soruşturma yapılması","Şüpheli veya sanığın kendisini savunamayacak derecede malûl olması"],"dogru":0,"aciklama":"m.20: \"Şüpheli veya sanık onsekiz yaşını doldurmamış ya da sağır veya dilsiz veya kendisini savunamayacak derecede malûl olur... talebi aranmaksızın bir müdafi görevlendirilir. Üst sınırı en az beş yıl hapis cezasını gerektiren suçlardan dolayı yapılan soruşturma ve kovuşturmada şüpheli veya sanığın talebi aranmaksızın bir müdafi görevlendirilir.\" Yabancı uyrukluluk bu sayımda bağımsız bir şart olarak yer almaz.","kaynak":"Yakalama Yön. m.20","zorluk":"zor"},
    {"id":"YON34-S-028","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, iddianamenin Cumhuriyet başsavcılığınca mahkemeye verilmesinden itibaren müdafi hangi hakka sahiptir?","siklar":["Yalnızca duruşmada söz alma hakkına","Dosya içeriğini ve muhafaza altına alınmış delilleri inceleme, tutanak ve belgelerin örneklerini harçsız alma hakkına","Sadece iddianameyi okuma, başka belgeye erişememe hakkına","Yalnızca sulh ceza hâkiminin izniyle dosyayı inceleme hakkına","Bu aşamada hiçbir inceleme hakkı yoktur, hak yalnızca soruşturmada geçerlidir"],"dogru":1,"aciklama":"m.22: \"Müdafi, Cumhuriyet başsavcılığınca iddianamenin mahkemeye verildiği tarihten itibaren dosya içeriğini ve muhafaza altına alınmış delilleri inceleyebilir; bütün tutanak ve belgelerin örneklerini harçsız olarak alabilir.\"","kaynak":"Yakalama Yön. m.22","zorluk":"orta"},
    {"id":"YON34-S-029","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, ifade alma sırasında hazır bulunan müdafi hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Şüpheliye sorulan soruya onun yerine doğrudan cevap verebilir","İfadeyi tamamen kendisi yönetebilir","Yalnızca hukukî yardımda bulunabilir, şüpheliye sorulan soruya doğrudan cevap veremez","Şüphelinin yerine yeminle beyanda bulunabilir","İfade sürecine hiçbir şekilde müdahale edemez, yalnızca izler"],"dogru":2,"aciklama":"m.23/d: \"Müdafi sadece hukukî yardımda bulunabilir, şüphelinin ifadesi alınırken şüpheliye sorulan soruya doğrudan cevap veremez, onun yerini aldığı izlenimi veren herhangi bir müdahalede bulunamaz.\"","kaynak":"Yakalama Yön. m.23","zorluk":"orta"},
    {"id":"YON34-S-030","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, ifadesi alınan şüpheli, kimliğine ilişkin sorulara doğru cevap vermekle yükümlü değildir; dilerse yanlış bilgi verebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.23/a: \"Şüphelinin kimliği saptanır. Şüpheli, kimliğine ilişkin soruları doğru olarak cevaplandırmakla yükümlüdür.\" Susma hakkı yalnızca yüklenen suç hakkındaki açıklamayla ilgilidir, kimlik sorularıyla ilgili değildir.","kaynak":"Yakalama Yön. m.23","zorluk":"kolay"},
    {"id":"YON34-S-031","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, ifade veren şüphelinin özgür iradesini engelleyici nitelikte olduğu için yasaklanan yöntemler arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Kötü davranma ve işkence","İlâç verme ve yorma","Aldatma, cebir veya tehditte bulunma","Şüpheliye susma hakkının hatırlatılması","Bazı araçları kullanma gibi bedensel veya ruhsal müdahaleler"],"dogru":3,"aciklama":"m.24: \"Bunu engelleyici nitelikte kötü davranma, işkence, ilâç verme, yorma, aldatma, cebir veya tehditte bulunma, bazı araçları kullanma gibi bedensel veya ruhsal müdahaleler yapılamaz.\" Susma hakkının hatırlatılması ise m.23/f'de öngörülen bir yükümlülük olup yasak bir yöntem değil, tam tersine şüphelinin lehine bir haktır.","kaynak":"Yakalama Yön. m.24","zorluk":"orta"},
    {"id":"YON34-S-032","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yasak usullerle elde edilen bir ifade hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Şüpheli sonradan rıza gösterirse delil olarak kullanılabilir","Yalnızca mahkeme onaylarsa delil sayılır","Savcı uygun görürse geçerli delildir","Sadece ağır suçlarda delil olarak kabul edilir","Rıza ile verilmiş olsa dahi delil olarak değerlendirilemez"],"dogru":4,"aciklama":"m.24: \"Yasak usullerle elde edilen ifadeler rıza ile verilmiş olsa da delil olarak değerlendirilemez.\" Sonradan rıza gösterilmesi dahi bu ifadeleri geçerli hâle getirmez.","kaynak":"Yakalama Yön. m.24","zorluk":"orta"},
    {"id":"YON34-S-033","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre nezarethaneler en az kaç metrekare genişliğinde, en az kaç metre yükseklikte ve duvarlar arasında en az kaç metre mesafe olacak şekilde düzenlenir?","siklar":["7 m² - 2,5 m - 2 m","5 m² - 2 m - 1,5 m","10 m² - 3 m - 2,5 m","7 m² - 3 m - 1 m","6 m² - 2,5 m - 2 m"],"dogru":0,"aciklama":"m.25: \"Nezarethaneler en az 7 metrekare genişliğinde, 2,5 metre yüksekliğinde ve duvarlar arasında en az 2 metre mesafe olacak şekilde düzenlenir.\"","kaynak":"Yakalama Yön. m.25","zorluk":"orta"},
    {"id":"YON34-S-034","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, Cumhuriyet başsavcıları veya görevlendirecekleri Cumhuriyet savcıları, gözaltına alınan kişilerin durumlarını ve gözaltına alınma neden/sürelerini denetleyip sonucunu nereye kaydeder?","siklar":["Yakalama ve Gözaltına Alma Tutanağı Şüpheli ve Sanık Hakları Formuna (EK-A)","Nezarethaneye Alınanların Kaydına Ait Deftere","Sevk/Serbest Bırakma Tutanağına (EK-C)","İfade Tutanağına (EK-D)","Herhangi bir yere kaydedilmesi zorunlu değildir"],"dogru":1,"aciklama":"m.26: \"...gözaltına alınma ile ilgili tüm kayıt ve işlemleri denetler; sonucunu Nezarethaneye Alınanların Kaydına Ait Deftere kaydederler.\"","kaynak":"Yakalama Yön. m.26","zorluk":"orta"},
    {"id":"YON34-S-035","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, soruşturma evresinde gözaltındaki bir kişiyle ilgili aşağıdakilerden hangisine sebebiyet verilmesi yasaklanmamıştır?","siklar":["Kişinin müdafi ile görüştürülmesi","Kişinin 'suçlu' olarak kamuoyuna duyurulması","Kişinin basın önüne çıkartılması","Kişinin görüntülerinin alınıp teşhir edilmesi","Soruşturma evrakının yayımlanması"],"dogru":0,"aciklama":"m.27: \"...gözaltındaki bir kişinin 'suçlu' olarak kamuoyuna duyurulmasına, basın önüne çıkartılmasına, kişilerin basınla sorulu cevaplı görüştürülmelerine, görüntülerinin alınmasına, teşhir edilmelerine sebebiyet verilmez ve soruşturma evrakı hiçbir şekilde yayımlanamaz.\" Müdafi ile görüşme ise m.21 uyarınca şüphelinin güvenceye alınmış temel bir hakkıdır, yasaklanan bir durum değildir.","kaynak":"Yakalama Yön. m.27","zorluk":"orta"},
    {"id":"YON34-S-036","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yer gösterme işlemini kural olarak Cumhuriyet savcısı yaptırır. Hangi hâlde adlî kolluk âmiri de yer gösterme işlemi yaptırmaya yetkilidir?","siklar":["Şüphelinin talep etmesi hâlinde","Gece vakti işlem yapılması gerektiğinde","CMK m.250/1 kapsamına giren suçlar söz konusu olduğunda","Savcıya ulaşılamayan her durumda","Müdafi hazır bulunmadığında"],"dogru":2,"aciklama":"m.28: \"5271 sayılı Ceza Muhakemesi Kanununun 250 nci maddesinin birinci fıkrası kapsamına giren suçlar söz konusu olduğunda, adlî kolluk âmiri de yer gösterme işlemi yaptırmaya yetkilidir. Bu suçlar dışında yer gösterme işlemi kolluk âmirleri tarafından yaptırılamaz.\"","kaynak":"Yakalama Yön. m.28","zorluk":"orta"},
    {"id":"YON34-S-037","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin tanımlarına göre, kişinin özgürlüğünün 'gözaltına veya muhafaza altına alma işlemlerinden önce', geçici olarak ve fiilen kısıtlanarak denetim altına alınmasına ne ad verilir?","siklar":["Gözaltına alma","Muhafaza altına alma","Tutuklama","Yakalama","Sorgu"],"dogru":3,"aciklama":"m.4: \"Yakalama: ...gözaltına veya muhafaza altına alma işlemlerinden önce özgürlüğünün geçici olarak ve fiilen kısıtlanarak denetim altına alınmasını\" ifade eder. Yakalama, gözaltı ve muhafazadan önceki ilk ve en kısa süreli aşamadır.","kaynak":"Yakalama Yön. m.4","zorluk":"orta"},
    {"id":"YON34-S-038","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, şüpheli veya sanığın, hâkim veya mahkeme tarafından soruşturma veya kovuşturma konusu suçla ilgili olarak dinlenmesine ne ad verilir?","siklar":["Bilgi alma","İfade alma","Yer gösterme","Güvenlik araması","Sorgu"],"dogru":4,"aciklama":"m.4: \"Sorgu: Şüpheli veya sanığın, hâkim veya mahkeme tarafından soruşturma veya kovuşturma konusu suçla ilgili olarak dinlenmesini\" ifade eder. Bilgi alma (A) şüphe altında olmayan kişiden, ifade alma (B) kolluk/savcı tarafından şüpheliden alınan beyandır.","kaynak":"Yakalama Yön. m.4","zorluk":"orta"},
    {"id":"YON34-S-039","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin amacı, adlî kolluk görevlilerinin Cumhuriyet savcılarının bilgi ve emirleri doğrultusunda yürütecekleri adlî soruşturma sırasında hangi işlemlerin yürütülmesinde uyulacak usul ve esasları düzenlemektir?","siklar":["Yakalama, gözaltına alma, muhafaza altına alma ve ifade alma işlemleri","Yalnızca gözaltı süresinin uzatılmasına ilişkin hâkim kararları","Yalnızca adlî kolluk personelinin özlük hakları","Yalnızca nezarethanelerin fizikî standartları","Yalnızca müdafi ücret tarifesi"],"dogru":0,"aciklama":"m.1: \"Bu Yönetmeliğin amacı, ... kolluk tarafından gerçekleştirilen yakalama, gözaltına alma, muhafaza altına alma ve ifade alma işlemlerinin yürütülmesinde uyulacak usul ve esasları düzenlemektir.\"","kaynak":"Yakalama Yön. m.1","zorluk":"kolay"},
    {"id":"YON34-S-040","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, bu Yönetmelik yalnızca adlî kolluk görevlilerini kapsar; gerektiğinde veya Cumhuriyet savcısının talebi üzerine adlî kolluk görevini ifa eden diğer kolluk birimlerini kapsamaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2: \"Bu Yönetmelik yakalama, gözaltına alma, muhafaza altına alma ve ifade alma işlemleri ile adlî kolluk görevlileri ile gerektiğinde veya Cumhuriyet savcısının talebi üzerine adlî kolluk görevini ifa eden bütün kolluk birimlerini kapsar.\" Kapsam, adlî kolluk dışındaki görevlendirilen birimleri de içerir.","kaynak":"Yakalama Yön. m.2","zorluk":"kolay"},
    {"id":"YON34-S-041","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin dayanak maddesinde (m.3) aşağıdaki mevzuattan hangisi sayılmamıştır?","siklar":["5271 sayılı Ceza Muhakemesi Kanunu","2559 sayılı Polis Vazife ve Salahiyet Kanunu","5395 sayılı Çocuk Koruma Kanunu","2803 sayılı Jandarma Teşkilât, Görev ve Yetkileri Kanunu","2692 sayılı Sahil Güvenlik Komutanlığı Kanunu"],"dogru":2,"aciklama":"m.3: Yönetmelik 5271 sayılı CMK, 2253 sayılı Çocuk Mahkemelerinin Kuruluşu, Görev ve Yargılama Usulleri Hakkında Kanun, 2559 sayılı PVSK, 2803 sayılı Jandarma Kanunu, 2692 sayılı Sahil Güvenlik Kanunu ve 485 sayılı Gümrük KHK'sine dayanır. 5395 sayılı Çocuk Koruma Kanunu bu sayımda yer almaz; çocuklarla ilgili dayanak kanun 2253 sayılıdır.","kaynak":"Yakalama Yön. m.3","zorluk":"orta"},
    {"id":"YON34-S-042","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin tanımlarına göre, bir suçun tespiti veya aydınlatılmasına yönelik olarak müşteki ve suçtan zarar gören ile suç işleme şüphesi altında bulunmayan diğer kişilerin dinlenmesi ve tutanağa geçirilmesine ne ad verilir?","siklar":["İfade alma","Sorgu","Bilgi alma","Yer gösterme","Güvenlik araması"],"dogru":2,"aciklama":"m.4: \"Bilgi alma: Bir suçun tespiti veya aydınlatılmasına yönelik olarak, müşteki ve suçtan zarar gören ile suç işleme şüphesi altında bulunmayan diğer kişilerin dinlenmesini ve tutanağa geçirilmesini\" ifade eder.","kaynak":"Yakalama Yön. m.4","zorluk":"orta"},
    {"id":"YON34-S-043","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin tanımlarına göre, derhâl işlem yapılmadığı takdirde suçun iz, eser, emare ve delillerinin ....(1)...., veya şüphelinin ....(2).... ihtimalinin ortaya çıkması hâline 'gecikmesinde sakınca bulunan hâl' denir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["çoğalması - ifade vermeyi reddetmesi","tespit edilmesi - yakalanması","kaybolması veya şüphelinin kaçması - kimliğinin saptanamaması","mahkemeye sunulması - serbest kalması","yeniden incelenmesi - itiraf etmesi"],"dogru":2,"aciklama":"m.4: \"Gecikmesinde sakınca bulunan hâl: Derhâl işlem yapılmadığı takdirde suçun iz, eser, emare ve delillerinin kaybolması veya şüphelinin kaçması veya kimliğinin saptanamaması ihtimalinin ortaya çıkması hâlini\" ifade eder.","kaynak":"Yakalama Yön. m.4","zorluk":"zor"},
    {"id":"YON34-S-044","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'nin tanımlarına göre, şüpheli veya sanıkların haklarındaki işlemlerin tamamlanıp adlî mercilere sevk edilinceye kadar bekletilmesi amacıyla yapılmış yerlere ne ad verilir?","siklar":["Nezarethane","Gözaltı birimi","Muhafaza altına alma yeri","İfade alma odası","Gözaltı ve nezarethane sorumlusu bürosu"],"dogru":0,"aciklama":"m.4: \"Nezarethane: Şüpheli veya sanıkların haklarındaki işlemlerin tamamlanıp adlî mercilere sevk edilinceye kadar bekletilmesi amacıyla yapılmış yerleri\" ifade eder.","kaynak":"Yakalama Yön. m.4","zorluk":"kolay"},
    {"id":"YON34-S-045","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalama tutanağında aşağıdakilerden hangisinin yer alması gerektiği madde metninde belirtilmemiştir?","siklar":["Yakalananın hangi suç nedeniyle yakalandığı","Yakalamanın hangi yer ve zamanda yapıldığı","Yakalamayı kimlerin yaptığı","Yakalanan kişinin daha önceki adlî sicil kaydı","Haklarının tam olarak anlatıldığı"],"dogru":3,"aciklama":"m.6: \"Bu tutanağa yakalananın, hangi suç nedeniyle, hangi koşullarda, hangi yer ve zamanda yakalandığı, yakalamayı kimlerin yaptığı, hangi kolluk mensubunca tespit edildiği, haklarının tam olarak anlatıldığı açıkça yazılır.\" Kişinin önceki adlî sicil kaydı bu sayımda yer almaz.","kaynak":"Yakalama Yön. m.6","zorluk":"zor"},
    {"id":"YON34-S-046","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, yakalanan kişi hangi hâl veya hâllerde hekim kontrolünden geçirilerek yakalanma anındaki sağlık durumu belirlenir?","siklar":["Yalnızca kronik hastalığı bulunması hâlinde","Gözaltına alınacak olması veya zor kullanılarak yakalanması hâllerinde","Yalnızca kendi talebi bulunması hâlinde","Yalnızca yabancı uyruklu olması hâlinde","Yalnızca nezarethanede beşinci saatini doldurması hâlinde"],"dogru":1,"aciklama":"m.9: \"Yakalanan kişinin gözaltına alınacak olması veya zor kullanılarak yakalanması hâllerinde hekim kontrolünden geçirilerek yakalanma anındaki sağlık durumu belirlenir.\"","kaynak":"Yakalama Yön. m.9","zorluk":"orta"},
    {"id":"YON34-S-047","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, kadının muayenesi talebi hâlinde ve olanaklar elverdiğinde bir kadın hekim tarafından yapılır; kadın hekim bulunmaması hâlinde, muayene sırasında hekimle birlikte sağlık mesleği mensubu bir kadın personelin bulundurulmasına özen gösterilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.9: \"Kadının muayenesi, talebi hâlinde ve olanaklar elverdiğinde bir kadın hekim tarafından yapılır. Muayene edilecek kadının talebine rağmen kadın hekimin bulunmaması halinde, muayene sırasında hekim ile birlikte sağlık mesleği mensubu bir kadın personelin bulundurulmasına özen gösterilir.\"","kaynak":"Yakalama Yön. m.9","zorluk":"orta"},
    {"id":"YON34-S-048","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, Nezarethaneye Alınanların Kaydına Ait Deftere (EK-B) işlenmesi gereken bilgilerden hangisi madde metninde sayılmamıştır?","siklar":["Adı ve soyadı","Şüphelinin daha önceki mahkûmiyet sayısı","İsnat edilen suç ve gözaltına alınma nedeni","Sevk edildiği makam","Türkiye Cumhuriyeti kimlik numarası"],"dogru":1,"aciklama":"m.12: Deftere kimlik bilgileri (ad-soyad, T.C. kimlik numarası vb.), gözaltına alınmaya esas bilgiler (isnat edilen suç, gözaltına alınma nedeni), giriş/çıkış işlemleri (sevk edildiği makam vb.) işlenir. Şüphelinin daha önceki mahkûmiyet sayısı bu sayımda yer almaz.","kaynak":"Yakalama Yön. m.12","zorluk":"zor"},
    {"id":"YON34-S-049","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, hâkim veya mahkeme tarafından verilen yakalama emri üzerine yakalanan kişi, en geç ....(1).... saat içinde yetkili hâkim veya mahkeme önüne çıkarılamıyorsa, aynı süre içinde en yakın ....(2).... önüne çıkarılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["12 - Cumhuriyet savcısı","24 - sulh ceza hâkimi","48 - il jandarma komutanı","24 - Cumhuriyet başsavcısı","12 - sulh ceza mahkemesi başkanı"],"dogru":1,"aciklama":"m.16: \"Hâkim veya mahkeme tarafından verilen yakalama emri üzerine soruşturma veya kovuşturma evresinde yakalanan kişi, en geç yirmidört saat içinde yetkili hâkim veya mahkeme önüne çıkarılamıyorsa, aynı süre içinde en yakın sulh ceza hâkimi önüne çıkarılır; serbest bırakılmadığı takdirde, yetkili hâkim veya mahkemeye en kısa zamanda gönderilmek üzere tutuklanır.\"","kaynak":"Yakalama Yön. m.16","zorluk":"orta"},
    {"id":"YON34-S-050","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, gözaltı süreleri azamî süreler olup gözaltına alınan kişilerin işlemlerinin en kısa sürede bitirilmesi esastır; işlemleri bitirilenler, gözaltı süresinin dolması beklenmeksizin kolluk kuvvetince ilgili Cumhuriyet başsavcılığına derhâl sevk edilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.17: \"Gözaltı süreleri azamî süreler olup, gözaltına alınan kişilerin işlemlerinin en kısa sürede bitirilmesi esastır. Gözaltına alınanlar, işlemleri bitirildikten sonra gözaltı süresinin dolması beklenmeksizin kolluk kuvvetince ilgili Cumhuriyet başsavcılığına derhâl sevk edilir.\"","kaynak":"Yakalama Yön. m.17","zorluk":"kolay"},
    {"id":"YON34-S-051","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, suçun mağduru çocuk ise, buna karşı işlenen suçüstü hâllerinde, kovuşturulması suçtan zarar gören kimsenin şikâyetine bağlı fiillerde şüphelinin yakalanması ve soruşturma yapılması için ne aranır?","siklar":["Anne-babanın yazılı izni aranır","Sulh ceza hâkiminin ön izni aranır","Şikâyet şartı aranmaz","Yalnızca vasinin şikâyeti yeterli sayılır","Cumhuriyet başsavcısının onayı aranır"],"dogru":2,"aciklama":"m.19/b-8: \"Suçun mağduru çocuksa, bunlara karşı işlenen suçüstü hâllerinde, kovuşturulması suçtan zarar gören kimsenin şikâyetine bağlı olan fiillerde şüphelinin yakalanması ve soruşturma yapılması için şikâyet şartı aranmaz.\"","kaynak":"Yakalama Yön. m.19","zorluk":"orta"},
    {"id":"YON34-S-052","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, şüpheli veya sanık müdafi seçebilecek durumda olmadığını beyan eder ve müdafi yardımından yararlanmak isterse, talebi hâlinde kim tarafından bir müdafi görevlendirilir?","siklar":["Cumhuriyet savcısı tarafından","Sulh ceza hâkimi tarafından","Kolluk âmiri tarafından","Baro tarafından","Adalet Bakanlığı tarafından"],"dogru":3,"aciklama":"m.20: \"Şüpheli veya sanık, müdafi seçebilecek durumda olmadığını beyan ederse, talebi hâlinde baro tarafından bir müdafi görevlendirilir.\"","kaynak":"Yakalama Yön. m.20","zorluk":"kolay"},
    {"id":"YON34-S-053","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, şüpheli veya sanık vekâletname aranmaksızın müdafi ile her zaman ve konuşulanları başkalarının duyamayacağı bir ortamda görüşebilir; bu kişilerin müdafi ile yazışmaları denetime tâbi tutulabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.21: \"Şüpheli veya sanık vekâletname aranmaksızın müdafi ile her zaman ve konuşulanları başkalarının duyamayacağı bir ortamda görüşebilir. Bu kişilerin müdafiî ile yazışmaları denetime tâbi tutulamaz.\" Yazışmalar denetime tâbi tutulamaz, tutulabilir değil.","kaynak":"Yakalama Yön. m.21","zorluk":"orta"},
    {"id":"YON34-S-054","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, ifade alma sırasında şüpheliye hangi imkân hatırlatılır ve tanınır?","siklar":["Yalnızca susma hakkını kullanabileceği hatırlatılır","Yalnızca müdafi seçebileceği hatırlatılır","Yalnızca kimliğine ilişkin soruları cevaplamayabileceği hatırlatılır","Yalnızca ifadesinin ses kaydına alınmasını isteyebileceği hatırlatılır","Şüpheden kurtulması için somut delillerin toplanmasını isteyebileceği hatırlatılır; aleyhindeki şüphe nedenlerini ortadan kaldırmak ve lehine olan hususları ileri sürmek imkânı tanınır"],"dogru":4,"aciklama":"m.23/g: \"Şüpheden kurtulması için somut delillerin toplanmasını isteyebileceği hatırlatılır ve kendisi aleyhine var olan şüphe nedenlerini ortadan kaldırmak ve lehine olan hususları ileri sürmek imkânı tanınır.\"","kaynak":"Yakalama Yön. m.23","zorluk":"zor"},
    {"id":"YON34-S-055","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, personelin eğitim süresi ve müfredatı Adalet Bakanlığının görüşü alınarak ilgisine göre aşağıdaki makamlardan hangisinin onayı ile belirlenmez?","siklar":["Jandarma Genel Komutanı","Emniyet Genel Müdürü","Sahil Güvenlik Komutanı","Gümrük Müsteşarı","İçişleri Bakanı"],"dogru":4,"aciklama":"m.31: \"Eğitim süresi ve müfredatı Adalet Bakanlığının görüşü alınarak ilgisine göre Jandarma Genel Komutanı veya Emniyet Genel Müdürü veya Gümrük Müsteşarı ya da Sahil Güvenlik Komutanının onayı ile belirlenir.\" İçişleri Bakanı bu onay makamları arasında sayılmamıştır.","kaynak":"Yakalama Yön. m.31","zorluk":"zor"},
    {"id":"YON34-S-056","soru":"Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği'ne göre, bu Yönetmelik hükümlerini kim yürütür?","siklar":["Adalet Bakanı","İçişleri Bakanı","Cumhuriyet Başsavcısı","Jandarma Genel Komutanı","Emniyet Genel Müdürü"],"dogru":0,"aciklama":"m.34: \"Bu Yönetmelik hükümlerini Adalet Bakanı yürütür.\"","kaynak":"Yakalama Yön. m.34","zorluk":"kolay"},
  ],
  59: [
    {"id":"YON35-S-001","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre 'soruşturma' evresi hangi anda sona erer?","siklar":["İddianamenin kabulüyle","Hükmün kesinleşmesiyle","Şüphelinin ifadesinin alınmasıyla","Delillerin toplanmasının tamamlanmasıyla","Mahkemenin ilk duruşmasıyla"],"dogru":0,"aciklama":"m.3: 'Soruşturma: ... suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar geçen evreyi ... ifade eder.' Soruşturma iddianamenin kabulüyle sona erer, kovuşturma bu anda başlar.","kaynak":"YON35 m.3","zorluk":"kolay"},
    {"id":"YON35-S-002","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre kovuşturmanın başlamasından hükmün kesinleşmesine kadar suç şüphesi altında bulunan kişi Yönetmelikte nasıl tanımlanır?","siklar":["Mağdur","Şüpheli","Sanık","Hükümlü","Muhbir"],"dogru":2,"aciklama":"m.3: 'Sanık: Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar suç şüphesi altında bulunan kişiyi ... ifade eder.' Bu evredeki kişi sanıktır.","kaynak":"YON35 m.3","zorluk":"kolay"},
    {"id":"YON35-S-003","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre 'iç beden muayenesi' tanımı aşağıdakilerden hangisini kapsar?","siklar":["Kulak, burun ve ağız bölgelerinin gözle incelenmesini","Kafa, göğüs ve karın boşlukları ile cilt altı dokularının incelenmesini","Vücudun dış yüzeyinin elle yapılan yüzeysel incelemesini","Yalnızca kan örneği alınmasını","Girişimsel olmayan tıbbî görüntülemeyi"],"dogru":1,"aciklama":"m.3: 'İç beden muayenesi: Kafa, göğüs ve karın boşlukları ile cilt altı dokularının incelenmesini ... ifade eder.' Boşluklar ve cilt altı iç muayenenin konusudur.","kaynak":"YON35 m.3","zorluk":"orta"},
    {"id":"YON35-S-004","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre aşağıdakilerden hangisi 'beden parçası' tanımı kapsamında sayılan unsurlardan biri değildir?","siklar":["Baş","Kol","Bacak","Moleküler genetik veri","İç organlar"],"dogru":3,"aciklama":"m.3: 'Beden parçası: Bir bedenin tamamlayıcı unsuru olan baş, gövde, kol, el, bacak, ayak gibi uzuv ve iç organları ... ifade eder.' Moleküler genetik veri ayrı bir tanım olan 'moleküler genetik inceleme' kavramına aittir, beden parçası sayımında yer almaz.","kaynak":"YON35 m.3","zorluk":"orta"},
    {"id":"YON35-S-005","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre şüpheli veya sanık üzerinde iç beden muayenesi yapılabilmesine kural olarak kim karar verir?","siklar":["Cumhuriyet savcısı tek başına her zaman","Genel kolluk amiri","Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme","Adli tabip","Mahalli mülki amir"],"dogru":2,"aciklama":"m.4: 'Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından karar verilebilir.' Kural olarak karar hâkim veya mahkemeye aittir.","kaynak":"YON35 m.4","zorluk":"orta"},
    {"id":"YON35-S-006","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre Cumhuriyet savcısının iç beden muayenesi kararı ....(1).... içinde hâkim veya mahkeme onayına sunulur; hâkim veya mahkeme de ....(2).... içinde kararını verir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["yirmidört saat - kırksekiz saat","yirmidört saat - yirmidört saat","kırksekiz saat - yirmidört saat","oniki saat - yirmidört saat","yirmidört saat - üç gün"],"dogru":1,"aciklama":"m.4: 'Cumhuriyet savcısının kararı, yirmidört saat içinde hâkim veya mahkeme onayına sunulur. Hâkim veya mahkeme, yirmidört saat içinde kararını verir.' Her iki süre de yirmidört saattir.","kaynak":"YON35 m.4","zorluk":"orta"},
    {"id":"YON35-S-007","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre hâkim veya mahkeme tarafından onaylanmayan Cumhuriyet savcısı kararına dayanılarak elde edilen deliller kullanılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4: 'Onaylanmayan kararlar hükümsüz kalır ve elde edilen deliller kullanılamaz.' Onay yoksa hem karar hükümsüzdür hem de delil kullanılamaz.","kaynak":"YON35 m.4","zorluk":"kolay"},
    {"id":"YON35-S-008","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre şüpheli veya sanığın iç beden muayenesi ancak kim tarafından yapılabilir?","siklar":["Tabip gözetiminde herhangi bir sağlık personeli tarafından","Hemşire tarafından tek başına","Adli kolluk görevlisi tarafından","Cumhuriyet savcısı tarafından","Ancak tabip tarafından"],"dogru":4,"aciklama":"m.4: 'Şüpheli veya sanığın iç beden muayenesi ancak tabip tarafından yapılır.' Dış muayene ve girişimsel olmayan görüntülemenin aksine, iç muayenede tabip dışında başka sağlık personeli yetkili değildir.","kaynak":"YON35 m.4","zorluk":"orta"},
    {"id":"YON35-S-009","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre iç beden muayenesi hangi durumda yapılamaz?","siklar":["Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda","Alt sınırı iki yıldan az hapis cezasını gerektiren suçlarda","Üst sınırı beş yıldan az hapis cezasını gerektiren suçlarda","Yalnızca adli para cezasını gerektiren suçlarda","Şüphelinin reşit olmaması hâlinde"],"dogru":0,"aciklama":"m.4: 'Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda kişi üzerinde iç beden muayenesi yapılamaz.' Eşik cezanın üst sınırına göre belirlenir, alt sınıra göre değil.","kaynak":"YON35 m.4","zorluk":"zor"},
    {"id":"YON35-S-010","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre cinsel organlar veya anüs bölgesinde yapılan muayene, dış beden muayenesi olarak kabul edilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4: 'Cinsel organlar veya anüs bölgesinde yapılan muayene de iç beden muayenesi sayılır.' Bu bölge muayenesi dış değil, iç beden muayenesi kapsamındadır.","kaynak":"YON35 m.4","zorluk":"orta"},
    {"id":"YON35-S-011","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre dış beden muayenesi kimin talebiyle yapılabilir?","siklar":["Yalnızca hâkim veya mahkemenin kararıyla","Mahalli mülki amirin onayıyla","Yalnızca mağdurun istemiyle","Cumhuriyet savcısı ile emrindeki adlî kolluk görevlileri veya kovuşturma makamlarının talebiyle","Sanığın kendi rızasıyla, başkaca hiçbir işleme gerek olmaksızın"],"dogru":3,"aciklama":"m.5: 'Bir suça ilişkin delil elde etmek için, şüpheli veya sanık üzerinde dış beden muayenesi Cumhuriyet savcısı ile, emrindeki adlî kolluk görevlileri veya kovuşturma makamlarının talebiyle yapılabilir.' Dış muayenede hâkim kararı aranmaz.","kaynak":"YON35 m.5","zorluk":"orta"},
    {"id":"YON35-S-012","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre girişimsel olmayan tıbbî görüntüleme yöntemleri, bedenin dış muayenesi sayılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5: 'Girişimsel olmayan tıbbî görüntüleme yöntemleri de bedenin dış muayenesi sayılır. Bu tür incelemeler tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir.'","kaynak":"YON35 m.5","zorluk":"orta"},
    {"id":"YON35-S-013","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre şüpheli veya sanığın vücudundan kan, saç, tükürük veya tırnak gibi örnekler alınabilmesine kural olarak kim karar verir?","siklar":["Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme","Yalnızca adli tabip","Genel kolluk amiri, kendiliğinden","Mahalli mülki amir","Şüphelinin avukatı"],"dogru":0,"aciklama":"m.6: 'Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından karar verilebilir.' Karar mekanizması iç beden muayenesiyle aynıdır.","kaynak":"YON35 m.6","zorluk":"orta"},
    {"id":"YON35-S-014","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre vücuttan örnek alınmasına ilişkin aşağıdaki ifadelerden hangisi doğru değildir?","siklar":["Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda kişiden kan, saç, tükürük, tırnak gibi örnekler alınamaz","Özel kanunlardaki alkol muayenesine ilişkin hükümler saklıdır","Onaylanmayan kararlara dayanılarak alınan örnekler Cumhuriyet savcısının huzurunda derhâl yok edilir","Bu müdahaleler ancak tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir","Örnek alınmasına, hiçbir sağlık riski değerlendirmesi yapılmaksızın her hâlde karar verilebilir"],"dogru":4,"aciklama":"m.6: 'Vücuttan örnekler alınabilmesi için; müdahalenin, kişinin sağlığına açıkça ve öngörülebilir zarar verme tehlikesinin bulunmaması gerekir.' Sağlık riski değerlendirmesi şarttır; A, B, C, D ifadeleri ise maddede birebir yer alır.","kaynak":"YON35 m.6","zorluk":"orta"},
    {"id":"YON35-S-015","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre beraat kararının kesinleşmesi hâlinde, elde edilen fizik kimlik verileri nasıl imha edilir?","siklar":["Cumhuriyet savcısının huzurunda ve uygun göreceği usullerle derhâl yok edilerek tutanağa geçirilir","Hâkim kararıyla altı ay içinde imha edilir","Mahalli mülki amirin onayı ile bir yıl saklandıktan sonra imha edilir","Şüphelinin talebi olmaksızın süresiz saklanır","Genel kolluk tarafından herhangi bir tutanak tutulmaksızın imha edilir"],"dogru":0,"aciklama":"m.16: '... beraat ... kararı verilip kesinleşmesi hâllerinde ... elde edilen veriler, Cumhuriyet savcısının huzurunda ve uygun göreceği usullerle derhâl yok edilir ve bu husus tutanağa geçirilir.' İmha savcı huzurunda, derhâl ve tutanaklı yapılır.","kaynak":"YON35 m.16","zorluk":"kolay"},
    {"id":"YON35-S-016","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre şüpheli veya sanık üzerinde iç beden muayenesi yapılabilmesi için aranan şart aşağıdakilerden hangisidir?","siklar":["Müdahalenin, kişinin sağlığına açıkça ve öngörülebilir zarar verme tehlikesinin bulunmaması","Şüpheli veya sanığın önceden yazılı rızasının alınmış olması","Muayenenin yalnızca gündüz saatlerinde yapılması","Şüphelinin avukatının muayene sırasında hazır bulunması","Muayenenin ancak bir adli tıp kurumunda yapılması"],"dogru":0,"aciklama":"m.4: 'Muayenenin yapılabilmesi için; müdahalenin, kişinin sağlığına açıkça ve öngörülebilir zarar verme tehlikesinin bulunmaması gerekir.' Yönetmelikte aranan tek şart budur; rıza, saat kısıtı, avukat huzuru veya kurum şartı metinde yer almaz.","kaynak":"YON35 m.4","zorluk":"orta"},
    {"id":"YON35-S-017","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre dış beden muayenesine ilişkin aşağıdaki ifadelerden hangisi doğru değildir?","siklar":["Dış beden muayenesi ancak tabip tarafından yapılır","Dış beden muayenesi yapılabilmesi için hâkim veya mahkeme kararı şarttır","Muayenenin yapılabilmesi için kişinin sağlığına açıkça ve öngörülebilir zarar verme tehlikesinin bulunmaması gerekir","Girişimsel olmayan tıbbî görüntüleme, tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir","Dış beden muayenesi bir suça ilişkin delil elde etmek amacıyla yapılabilir"],"dogru":1,"aciklama":"B ifadesi yanlıştır. m.5: dış beden muayenesi 'Cumhuriyet savcısı ile, emrindeki adlî kolluk görevlileri veya kovuşturma makamlarının talebiyle yapılabilir'; hâkim veya mahkeme kararı aranmaz. A, C, D, E maddede birebir yer alan doğru ifadelerdir.","kaynak":"YON35 m.5","zorluk":"orta"},
    {"id":"YON35-S-018","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre şüpheli veya sanığın vücudundan kan, saç, tükürük veya tırnak gibi örnekler ancak tabip tarafından alınabilir; tabip gözetiminde başka bir sağlık mesleği mensubu bu işlemi yapamaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6: 'Bu müdahaleler ancak tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir.' Tabip dışında, tabip gözetiminde diğer bir sağlık mesleği mensubu da bu işlemi yapabilir.","kaynak":"YON35 m.6","zorluk":"orta"},
    {"id":"YON35-S-019","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre vücuttan örnek alınmasına ilişkin tıbbî müdahaleler, ....(boşluk).... kabul ettiği yöntem ve araçlarla yapılır. Boşluğa gelmesi gereken ifade hangisidir?","siklar":["mahalli mülki amirin uygun gördüğü","Sağlık Bakanlığının onayladığı","hekimlik sanatının ve tıp biliminin","Cumhuriyet savcısının belirlediği","hastane baştabipliğinin"],"dogru":2,"aciklama":"m.6: 'Tıbbî müdahaleler, hekimlik sanatının ve tıp biliminin kabul ettiği yöntem ve araçlarla yapılır.' Ölçüt idari bir onay değil, tıbbî/bilimsel kabuldür.","kaynak":"YON35 m.6","zorluk":"kolay"},
    {"id":"YON35-S-020","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre aşağıdakilerden hangisi elde edilen fizik kimlik verilerinin imha edilmesini gerektiren hâllerden biri değildir?","siklar":["Kovuşturmaya yer olmadığı kararına itiraz süresinin dolması","İtirazın reddi","Beraat kararının kesinleşmesi","Mahkûmiyet kararının kesinleşmesi","Ceza verilmesine yer olmadığı kararının kesinleşmesi"],"dogru":3,"aciklama":"m.16 imhayı gerektiren hâller: 'Kovuşturmaya yer olmadığı kararına itiraz süresinin dolması, itirazın reddi, beraat veya ceza verilmesine yer olmadığı kararı verilip kesinleşmesi hâlleri'dir. Mahkûmiyet kararının kesinleşmesi bu hâller arasında sayılmamıştır.","kaynak":"YON35 m.16","zorluk":"zor"},
    {"id":"YON35-S-021","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre 'sağlık mesleği mensubu' tanımı kapsamında sayılmayan kişi aşağıdakilerden hangisidir?","siklar":["Tabip","Diş tabibi","Ebe","Hemşire","Adli kolluk görevlisi"],"dogru":4,"aciklama":"m.3: 'Sağlık mesleği mensubu: Tabip, diş tabibi, eczacı, ebe, hemşire ve sağlık hizmeti veren diğer kişileri ... ifade eder.' Adli kolluk görevlisi bu tanımda sayılmaz.","kaynak":"YON35 m.3","zorluk":"orta"},
    {"id":"YON35-S-022","soru":"Ceza Muhakemesinde Beden Muayenesi, Genetik İncelemeler ve Fizik Kimliğin Tespiti Hakkında Yönetmelik'e göre 'gecikmesinde sakınca bulunan hâl', yalnızca şüphelinin kaçma ihtimalinin ortaya çıkması durumunu ifade eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3: 'Gecikmesinde sakınca bulunan hâl: Derhâl işlem yapılmadığı takdirde suçun iz, eser, emare ve delillerinin kaybolması veya şüphelinin kaçması veya kimliğinin saptanamaması ihtimalinin ortaya çıkması hâlini ... ifade eder.' Tanım yalnızca kaçma ihtimaliyle sınırlı değildir.","kaynak":"YON35 m.3","zorluk":"kolay"},
  ],
  60: [
    {"id":"36-S-001","soru":"Çocuk Koruma Kanununa Göre Verilen Koruyucu ve Destekleyici Tedbir Kararlarının Uygulanması Hakkında Yönetmeliğe göre, 'çocuk' kimdir?","siklar":["Onaltı yaşını doldurmamış, evlenmemiş kişi","Onbeş yaşını doldurmamış kişi","Daha erken yaşta ergin olsa bile, onsekiz yaşını doldurmamış kişi","Yalnızca suça sürüklenen onsekiz yaşından küçük kişi","Yalnızca korunma ihtiyacı olan onsekiz yaşından küçük kişi"],"dogru":2,"aciklama":"m.4/a: 'Çocuk: Daha erken yaşta ergin olsa bile, onsekiz yaşını doldurmamış kişiyi... ifade eder.' Erken erginlik (ör. evlenme) çocukluk sıfatını ortadan kaldırmaz.","kaynak":"YON36 m.4","zorluk":"kolay"},
    {"id":"36-S-002","soru":"...Yönetmeliğe göre, hakkında kovuşturma başlatılmış olan bir çocuk hakkındaki tedbir kararı da 'çocuk hâkimi' tanımı kapsamında değerlendirilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.4/b: 'Çocuk hâkimi: Hakkında kovuşturma başlatılmış olanlar hariç, suça sürüklenen çocuklarla korunma ihtiyacı olan çocuklar hakkında uygulanacak tedbir kararlarını veren çocuk mahkemesi hâkimini... ifade eder.' Kovuşturma başlamışsa tedbir kararını çocuk hâkimi değil, kovuşturmanın yapıldığı mahkeme verir (m.8/3).","kaynak":"YON36 m.4","zorluk":"orta"},
    {"id":"36-S-003","soru":"...Yönetmeliğin 5. maddesine göre aşağıdakilerden hangisi koruyucu ve destekleyici tedbir türlerinden biri DEĞİLDİR?","siklar":["Danışmanlık","Eğitim","Bakım","Gözetim","Barınma"],"dogru":3,"aciklama":"m.5/1: tedbirler 'a) Danışmanlık, b) Eğitim, c) Bakım, d) Sağlık, e) Barınma' olarak sayılmıştır. 'Gözetim' adıyla ayrı bir tedbir türü yoktur; beşinci tür Sağlık'tır.","kaynak":"YON36 m.5","zorluk":"kolay"},
    {"id":"36-S-004","soru":"...Yönetmeliğe göre koruyucu ve destekleyici tedbirler düzenlenirken öncelik, çocuğun ailesinden alınıp bir kuruma yerleştirilmesidir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/1: tedbirler 'öncelikle kendi aile ortamında korunmasının sağlanması ile yaşına ve gelişimine uygun eğitim ve öğreniminin desteklenmesini... sağlamaya yönelik'tir. Öncelik aile ortamında korumadır, kuruma yerleştirme değildir.","kaynak":"YON36 m.5","zorluk":"orta"},
    {"id":"36-S-005","soru":"...Yönetmeliğe göre, bir çocuğun korunma ihtiyacı olduğundan haberdar olan kolluk görevlileri, köy/mahalle muhtarları, sağlık ve eğitim kuruluşu görevlileri gibi kişiler durumu hangi mercie bildirmekle yükümlüdür?","siklar":["Cumhuriyet başsavcılığına","İl veya ilçe Aile ve Sosyal Politikalar müdürlüklerine","Doğrudan çocuk hâkimine","İl valiliğine","Millî Eğitim Bakanlığına"],"dogru":1,"aciklama":"m.6/1: '...bir çocuğun korunma ihtiyacı olduğundan haberdar olanlar, durumu il ve ilçelerdeki Aile ve Sosyal Politikalar müdürlüklerine bildirmekle yükümlüdür.'","kaynak":"YON36 m.6","zorluk":"kolay"},
    {"id":"36-S-006","soru":"...Yönetmeliğe göre, il ve ilçe Aile ve Sosyal Politikalar müdürlükleri, basın-yayın organlarında çıkan haberleri ve her türlü duyumu ihbar kabul ederek, ayrıca resmî bir duyuru gelmesini beklemeden harekete geçip araştırma yapmakla yükümlüdür.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/3: '...basın ve yayın organları ile benzeri iletişim araçlarında çıkan haberleri ve her türlü duyumu ihbar kabul ederek ayrıca bir resmî duyuru gelmesini beklemeden harekete geçerek bunları araştırmakla yükümlüdür.'","kaynak":"YON36 m.6","zorluk":"orta"},
    {"id":"36-S-007","soru":"...Yönetmeliğe göre Kurum, çocuğun Kuruma geldiği tarihten itibaren en geç ....(1).... içinde çocuk hâkimine müracaat eder; hâkim ....(2).... içinde talep hakkında karar verir; acil korunma kararı en fazla ....(3).... süreyle sınırlı olmak üzere verilebilir. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["üç gün - beş gün - otuz gün","beş gün - üç gün - otuz gün","beş gün - on gün - otuz gün","yedi gün - üç gün - altmış gün","beş gün - üç gün - altmış gün"],"dogru":1,"aciklama":"m.7/2: '...en geç beş gün içinde çocuk hâkimine müracaat edilir. Hâkim tarafından, üç gün içinde talep hakkında karar verilir.' m.7/4: 'Acil korunma kararı en fazla otuz günlük süre ile sınırlı olmak üzere verilebilir.' Sıra: 5-3-30.","kaynak":"YON36 m.7","zorluk":"orta"},
    {"id":"36-S-008","soru":"...Yönetmeliğe göre, acil korunma kararı sürecinde hâkim ek olarak hangi konuda karar verebilir?","siklar":["Çocuğun bulunduğu yerin gizli tutulması ve gerektiğinde kişisel ilişkinin tesisi","Çocuğun velayetinin tamamen kaldırılması","Çocuğun yurt dışına çıkış yasağı konulması","Ailenin sosyal yardımdan mahrum bırakılması","Çocuğun okul kaydının silinmesi"],"dogru":0,"aciklama":"m.7/2: 'Hâkim, çocuğun bulunduğu yerin gizli tutulmasına ve gerektiğinde kişisel ilişkinin tesisine karar verebilir.'","kaynak":"YON36 m.7","zorluk":"zor"},
    {"id":"36-S-009","soru":"...Yönetmeliğin 8. maddesine göre, aşağıdakilerden hangisi koruyucu ve destekleyici tedbir kararının alınmasını isteme yetkisi bulunanlar arasında sayılmamıştır?","siklar":["Çocuğun anası, babası veya vasisi","Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü","Cumhuriyet savcısı","Çocuğun okulundaki sınıf öğretmeni","Çocuk hâkiminin re'sen harekete geçmesi"],"dogru":3,"aciklama":"m.8/1: tedbir kararı 'çocuğun anası, babası, vasisi, bakım ve gözetiminden sorumlu kimse... Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü ve Cumhuriyet savcısının istemi üzerine veya re'sen... çocuk hâkimince alınır.' Sınıf öğretmeni bu istem sahipleri arasında sayılmamıştır.","kaynak":"YON36 m.8","zorluk":"orta"},
    {"id":"36-S-010","soru":"...Yönetmeliğe göre, fiili işlediği sırada oniki yaşından küçük çocuklar hakkında mahkemece ne uygulanabilir?","siklar":["Doğrudan hapis cezası","Adlî para cezası","Türk Ceza Kanununun 31 inci maddesinin birinci fıkrası ile 33 üncü maddesi uyarınca çocuklara özgü güvenlik tedbirleri","Kamu davasının açılmasının ertelenmesi kararı","Uzlaştırma prosedürünün uygulanması"],"dogru":2,"aciklama":"m.8/5: 'Fiili işlediği sırada oniki yaşından küçük çocuklar ile onbeş yaşını doldurmamış sağır ve dilsizler hakkında mahkemece... Türk Ceza Kanununun 31 inci maddesinin birinci fıkrası ile 33 üncü maddesi uyarınca çocuklara özgü güvenlik tedbirleri uygulanabilir.'","kaynak":"YON36 m.8","zorluk":"orta"},
    {"id":"36-S-011","soru":"...Yönetmeliğe göre, çocuk hâkimi veya mahkemece koruyucu ve destekleyici tedbir kararı verilmeden önce, yeterli idrak gücü bulunan çocuğun yazılı veya sözlü olarak görüşü alınır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8/8: 'Çocuk hâkimi veya mahkemece, koruyucu ve destekleyici tedbir kararı verilmeden önce yeterli idrak gücü bulunan çocuğun yazılı veya sözlü olarak görüşü alınır.'","kaynak":"YON36 m.8","zorluk":"kolay"},
    {"id":"36-S-012","soru":"...Yönetmeliğe göre, suça sürüklenen bir çocuk hakkında soruşturma aşamasında tedbir kararı çocuk hâkimince alınmışken, çocuk hakkında kovuşturma başlatılırsa, bundan böyle tedbir kararını hangi makam verir?","siklar":["Yine aynı çocuk hâkimi verir, makam değişmez","İl valisi","Cumhuriyet savcısı","Kovuşturmanın yapıldığı mahkeme","Aile ve Sosyal Politikalar Bakanlığı"],"dogru":3,"aciklama":"m.8/3: 'Hakkında kovuşturma başlatılmış olan çocuklar için koruyucu ve destekleyici tedbir kararı kovuşturmanın yapıldığı mahkemece alınır.' Ayrıca m.4/b'deki çocuk hâkimi tanımı da kovuşturma başlatılmış olanları kapsam dışı bırakır.","kaynak":"YON36 m.4, m.8","zorluk":"zor"},
    {"id":"36-S-013","soru":"...Yönetmeliğin 9. maddesine göre, aşağıdaki tedbir-merci eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["Sağlık tedbiri kararı → il sağlık müdürlükleri","Bakım tedbiri kararı → Aile ve Sosyal Politikalar Bakanlığı il/ilçe müdürlükleri","Eğitim tedbiri kararı → il millî eğitim müdürlükleri veya Çalışma ve Sosyal Güvenlik Bakanlığı bölge müdürlükleri","Danışmanlık ve barınma tedbir kararları → il millî eğitim müdürlükleri, ASP il/ilçe müdürlükleri veya yerel yönetimler","Bakım tedbiri kararı → il jandarma komutanlığı"],"dogru":4,"aciklama":"m.9/1: kararlar sırasıyla (a) danışmanlık/barınma → MEB il müdürlükleri/ASP il-ilçe müdürlükleri/yerel yönetimler, (b) eğitim → MEB il müdürlükleri veya ÇSGB bölge müdürlükleri, (c) bakım → ASP il/ilçe müdürlükleri, (ç) sağlık → il sağlık müdürlükleri gönderilir. Bakım tedbiri kararı il jandarma komutanlığına gönderilmez.","kaynak":"YON36 m.9","zorluk":"orta"},
    {"id":"36-S-014","soru":"...Yönetmeliğe göre, koruyucu ve destekleyici tedbir kararı, kesinleşmesi beklenmeksizin derhâl uygulanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.9/2: 'Koruyucu ve destekleyici tedbir kararı, kesinleştirilmesi beklenmeksizin derhâl uygulanır.'","kaynak":"YON36 m.9","zorluk":"orta"},
    {"id":"36-S-015","soru":"...Yönetmeliğe göre, koruyucu ve destekleyici tedbirin uygulanması onsekiz yaşın doldurulmasıyla nasıl sona erer?","siklar":["Ancak hâkimin ayrıca vereceği bir kararla sona erer","Sona ermez, tedbir süresiz devam eder","Cumhuriyet savcısının talebiyle sona erer","Sosyal inceleme raporunun tamamlanmasıyla sona erer","Ayrıca bir karara gerek kalmaksızın kendiliğinden sona erer"],"dogru":4,"aciklama":"m.11/3: 'Tedbirin uygulanması, onsekiz yaşın doldurulmasıyla ayrıca bir karara gerek kalmaksızın kendiliğinden sona erer. Ancak hâkim, eğitim ve öğrenimine devam edebilmesi için ve çocuğun rızası alınmak suretiyle tedbirin uygulanmasına belli bir süre daha devam edilmesine karar verebilir.'","kaynak":"YON36 m.11","zorluk":"orta"},
    {"id":"36-S-016","soru":"...Yönetmeliğe göre danışmanlık tedbiri, temelde neye yöneliktir?","siklar":["Çocuğun bir eğitim kurumuna yatılı olarak devamına","Çocuğun tıbbî tedavi altına alınmasına","Çocuğun resmî veya özel bir bakım yurduna yerleştirilmesine","Çocuğun bakımından sorumlu kimselere ve çocuğa, sorunların çözümünde yol gösterici rehberlik sağlanmasına","Çocuğa uygun bir barınma yeri sağlanmasına"],"dogru":3,"aciklama":"m.12/1: 'Danışmanlık tedbiri, çocuğun bakımından sorumlu olan kimselere çocuk yetiştirme konusunda; çocuklara da eğitim ve gelişimleri ile ilgili sorunlarının çözümünde yol göstermeye yönelik rehberlik tedbirleridir.'","kaynak":"YON36 m.12","zorluk":"kolay"},
    {"id":"36-S-017","soru":"...Yönetmeliğe göre, danışmanlık tedbiri çocuk hakkında en fazla altı ay süreyle uygulanabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.12/7'de geçen 'altı ay' ibaresi, danışmanlık tedbirini yerine getirmekle sorumlu kurumların (MEB, ASP-ÇHGM, yerel yönetimler) bu Yönetmeliğin yayımından itibaren uygulama usûl ve esaslarını OLUŞTURMA süresidir; tedbirin uygulama süresiyle ilgisi yoktur. Yönetmelikte danışmanlık tedbirinin azami süresine ilişkin böyle bir sınırlama bulunmamaktadır.","kaynak":"YON36 m.12","zorluk":"zor"},
    {"id":"36-S-018","soru":"...Yönetmeliğe göre, eğitim tedbiri kararı verilirken onbeş yaşını doldurmamış çocuklar hakkında öncelikle ....(1)...., onbeş yaşını doldurmuş çocuk hakkında ise iş ve meslek edinmesi amacıyla ....(2).... yönelik tedbir kararı verilebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["meslek veya sanat edinme kursuna gitmesine - eğitimlerinin devamına","evde eğitim almasına - yurt dışında eğitim görmesine","resmî bir bakım yurduna yerleştirilmesine - barınma sağlanmasına","sağlık tedbirine hükmedilmesine - danışmanlık tedbirine hükmedilmesine","eğitimlerinin devamına - meslek veya sanat edinme kursuna gitmesine, usta yanına veya işyerine yerleştirilmesine"],"dogru":4,"aciklama":"m.13/5-6: onbeş yaşını doldurmamış çocuklar hakkında 'eğitimlerinin devamına ilişkin tedbir kararı verilebilir'; onbeş yaşını doldurmuş çocuk hakkında ise 'iş ve meslek edinmesi amacıyla bir meslek veya sanat edinme kursuna gitmesine, meslek sahibi bir ustanın yanına yahut... işyerlerine yerleştirilmesine yönelik' tedbir kararı verilir.","kaynak":"YON36 m.13","zorluk":"orta"},
    {"id":"36-S-019","soru":"...Yönetmeliğe göre eğitim tedbiri hangi bakanlık/bakanlıkların ilgili birimleri tarafından yerine getirilir?","siklar":["Yalnızca Millî Eğitim Bakanlığı","Sağlık Bakanlığı ile Millî Eğitim Bakanlığı","Millî Eğitim Bakanlığı ile Çalışma ve Sosyal Güvenlik Bakanlığı","Aile ve Sosyal Politikalar Bakanlığı","İçişleri Bakanlığı"],"dogru":2,"aciklama":"m.13/8: 'Eğitim tedbiri, Millî Eğitim Bakanlığı ile Çalışma ve Sosyal Güvenlik Bakanlığının ilgili birimleri tarafından yerine getirilir.'","kaynak":"YON36 m.13","zorluk":"kolay"},
    {"id":"36-S-020","soru":"...Yönetmeliğe göre, bakım tedbiri kararı verilen çocukların kolluk kuvvetlerince Aile ve Sosyal Politikalar Bakanlığı il/ilçe müdürlüklerine teslim edileceği hâllerde, teslimden önce ne yapılması gerekir?","siklar":["Çocuğun mahkemeye ifade vermesi","Ailenin yazılı izninin alınması","Çocuğa avukat atanması","Çocuğun ilk sağlık kontrolünün yapılması","Sosyal inceleme raporunun tamamlanması"],"dogru":3,"aciklama":"m.14/4: 'Bakım tedbiri kararı verilen çocukların kolluk kuvvetlerince Aile ve Sosyal Politikalar Bakanlığı il ve ilçe müdürlüklerine teslim edileceği hâllerde, çocuğun ilk sağlık kontrolü yapıldıktan sonra teslimi sağlanır.'","kaynak":"YON36 m.14","zorluk":"orta"},
    {"id":"36-S-021","soru":"...Yönetmeliğe göre, barınma tedbiri uygulanan kimselerin kimlikleri ve adresleri, talepleri hâlinde gizli tutulur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.15/2: 'Barınma tedbiri uygulanan kimselerin, talepleri hâlinde kimlikleri ve adresleri gizli tutulur.'","kaynak":"YON36 m.15","zorluk":"orta"},
    {"id":"36-S-022","soru":"...Yönetmeliğe göre, alkol ya da uyuşturucu veya uyarıcı madde bağımlısı olan çocukların tedavi altına alınmasına yönelik sağlık tedbiri kararlarının yerine getirilmesinde neye ihtiyaç yoktur?","siklar":["Sağlık Bakanlığının bu tedbiri yerine getirmesine","İlgili kurum uzmanınca çocuğa bilgi verilmesine","Çocuğun tedaviye rızasına","Mahkeme veya çocuk hâkimi kararına","Tedbirin uygulama süresince öğüt ve yol gösterilmesine"],"dogru":2,"aciklama":"m.16/13: '...alkol ya da uyuşturucu veya uyarıcı madde bağımlılarının tedavi altına alınmasına yönelik olarak verilen kararların yerine getirilmesinde tedavi için çocuğun rızası aranmaz.'","kaynak":"YON36 m.16","zorluk":"orta"},
    {"id":"36-S-023","soru":"...Yönetmeliğe göre, bakım ve barınma tedbirlerinin yerine getirilmesi sırasında ihtiyaç duyulan kolluk hizmetleri talep edildiğinde, kolluk birimleri bu talepleri nasıl yerine getirir?","siklar":["Mahalli mülki amirin onayından sonra","Ancak mahkeme kararı üzerine","Geciktirmeksizin","Talebin yazılı olarak tekrarlanmasından sonra","Yalnızca acil hâllerde"],"dogru":2,"aciklama":"m.17/1: 'Bakım ve barınma tedbirlerinin yerine getirilmesi sırasında ihtiyaç duyulan kolluk hizmetleri ilgili birimlerden talep edilir. Kolluk birimleri, bu talepleri geciktirmeksizin yerine getirir.'","kaynak":"YON36 m.17","zorluk":"kolay"},
    {"id":"36-S-024","soru":"...Yönetmeliğe göre, tedbir kararının nasıl yerine getirileceğine dair uygulama plânı, çocuğun teslim edildiği/teslim alındığı tarihten itibaren en geç ....(1).... içinde mahkeme veya çocuk hâkiminin onayına sunulur; tedbirin uygulanması en geç ....(2).... sürelerle incelettirilir; ayrıca bu tedbirlerin yerine getirilmesinde ....(3).... herhangi bir görev yüklenemez. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on gün - üçer aylık - ceza infaz kurumlarına","otuz gün - altışar aylık - kolluk birimlerine","beş gün - üçer aylık - ceza infaz kurumlarına","on gün - birer yıllık - denetimli serbestlik birimlerine","yirmi gün - üçer aylık - ceza infaz kurumlarına"],"dogru":0,"aciklama":"m.18/1: plân 'en geç on gün içerisinde mahkeme veya çocuk hâkiminin onayına sunulur.' m.18/4: tedbir 'en geç üçer aylık sürelerle incelettirir.' m.18/13: '...bu tedbirlerin yerine getirilmesinde ceza infaz kurumlarına herhangi bir görev yüklenemez.'","kaynak":"YON36 m.18","zorluk":"orta"},
    {"id":"36-S-025","soru":"...Yönetmeliğe göre, illerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumlar arası bağlantı, uyum, düzen ve eşgüdüm kimin başkanlığında sağlanır ve aşağıdakilerden hangisi bu eşgüdümde yer alan üyelerden biridir?","siklar":["Aile ve Sosyal Politikalar il müdürünün başkanlığında; il sağlık müdürü","Kaymakamın başkanlığında; belediye başkanı","Cumhuriyet başsavcısının başkanlığında; il emniyet müdürü","İl millî eğitim müdürünün başkanlığında; baro temsilcisi","Vali veya vali yardımcısının başkanlığında; il jandarma komutanı"],"dogru":4,"aciklama":"m.20/1: 'İllerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumlar arasında bağlantı, uyum, düzen ve eşgüdüm; vali veya vali yardımcısının başkanlığında, Cumhuriyet başsavcısı... ile il emniyet müdürü, il jandarma komutanı, il millî eğitim müdürü, il sağlık müdürü... marifetiyle yerine getirilir.'","kaynak":"YON36 m.20","zorluk":"orta"},
    {"id":"36-S-026","soru":"...Yönetmeliğe göre, illerde koordinasyonun sekretarya hizmetlerini hangi kurum yürütür ve toplantı gündemi ile günü katılımcılara kaç gün önceden bildirilir?","siklar":["İl emniyet müdürlüğü - beş gün önceden","Baro başkanlığı - üç gün önceden","Vali yardımcılığı - otuz gün önceden","İl millî eğitim müdürlüğü - on gün önceden","Aile ve Sosyal Politikalar Bakanlığı il müdürlüğü - on beş gün önceden"],"dogru":4,"aciklama":"m.20/4: 'İllerde koordinasyonun sekretarya hizmetleri Aile ve Sosyal Politikalar Bakanlığı il müdürlüğü tarafından yürütülür.' m.20/2: 'Toplântı gündemi ve günü sekretarya görevini yürüten koordinatör birim tarafından bu kişilere on beş gün önceden bildirilir.'","kaynak":"YON36 m.20","zorluk":"zor"},
    {"id":"36-S-027","soru":"...Yönetmeliğe göre, tedbir kararının yerine getirilmesi amacıyla teslim alınacak çocuğun bulunamaması hâlinde mahkeme veya çocuk hâkimi, çocuğun bulunup ilgili kuruma tesliminin sağlanmasına ilişkin kararı hangi birime verebilir?","siklar":["Denetimli serbestlik bürolarına","Cumhuriyet başsavcılığına","Aile ve Sosyal Politikalar il müdürlüğüne","Kolluğun çocuk birimine","Baro çocuk hakları merkezine"],"dogru":3,"aciklama":"m.22/3: 'Çocuğun bulunamaması hâlinde durum ilgili kolluk birimlerine bildirilir. Mahkeme veya çocuk hâkimi tedbir kararının yerine getirilmesi için çocuğun bulunması ve ilgili kuruma tesliminin kolluğun çocuk birimi tarafından sağlanmasına karar verebilir.'","kaynak":"YON36 m.22","zorluk":"orta"},
    {"id":"36-S-028","soru":"...Yönetmeliğe göre, çocuğa ilişkin koruyucu ve destekleyici tedbir süreçlerinde çocuğun kimliği, adresi, fotoğrafları ve yaşadığı travmalar gibi bilgiler, çocuğun avukatı da dâhil olmak üzere herkese karşı gizli tutulur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.26/1: '...çocuğun avukatı hariç olmak üzere çocuğun kimliği, adresi, fotoğrafları, yaşadığı travmalar gibi çocuğa ve yakınlarına ait her türlü bilgi ve bu bilgilerin yer aldığı rapor ve belgeler ile kayıtlar gizli tutulur.' Gizlilik kuralının tek istisnası çocuğun avukatıdır.","kaynak":"YON36 m.26","zorluk":"kolay"},
    {"id":"36-S-029","soru":"...Yönetmeliğe göre; acil korunmada hâkime başvuru süresi ....(1)...., hâkimin karar süresi ....(2)...., uygulama plânının onaya sunulma süresi ....(3)...., tedbirin uygulanmasının denetlenme sıklığı ....(4)....'dır. Boşluklara sırasıyla gelmesi gereken süreler hangisidir?","siklar":["üç gün - beş gün - on gün - üç ayda bir","beş gün - üç gün - otuz gün - altı ayda bir","beş gün - üç gün - on gün - üç ayda bir","on gün - üç gün - beş gün - bir yılda bir","beş gün - on gün - üç gün - üç ayda bir"],"dogru":2,"aciklama":"m.7/2: başvuru 'beş gün', karar 'üç gün'. m.18/1: plân onayı 'en geç on gün içerisinde'. m.18/4: denetim/inceleme 'en geç üçer aylık sürelerle'. Doğru sıra: 5-3-10-3ay. (Not: m.12/7'deki 'altı ay', danışmanlık tedbirini yerine getiren kurumların usûl/esas hazırlama süresidir; bu bir tedbir veya denetim süresi olmadığından bu sayımın dışındadır.)","kaynak":"YON36 m.7, m.12, m.18","zorluk":"zor"},
    {"id":"36-S-030","soru":"Çocuk Koruma Kanununa Göre Verilen Koruyucu ve Destekleyici Tedbir Kararlarının Uygulanması Hakkında Yönetmeliğin 1. maddesine göre, Yönetmeliğin amacı nedir?","siklar":["Yalnızca suça sürüklenen çocukların cezalandırılmasına ilişkin usul ve esasları düzenlemek","Yalnızca korunma ihtiyacı olan çocuklara yönelik sosyal yardım tutarlarını belirlemek","Korunma ihtiyacı olan veya suça sürüklenen çocukların korunmasına, haklarının ve esenliklerinin güvence altına alınmasına ilişkin usûl ve esasları düzenlemek","Çocuk mahkemelerinin kuruluş ve görevlerini düzenlemek","Yalnızca kolluk birimlerinin çocuk birimlerinin görev alanını belirlemek"],"dogru":2,"aciklama":"m.1: 'Bu Yönetmeliğin amacı, korunma ihtiyacı olan veya suça sürüklenen çocukların korunmasına, haklarının ve esenliklerinin güvence altına alınmasına ilişkin usûl ve esasları düzenlemektir.'","kaynak":"YON36 m.1","zorluk":"kolay"},
    {"id":"36-S-031","soru":"...Yönetmeliğe göre, bu Yönetmelik yalnızca korunma ihtiyacı olan çocuklar hakkında alınacak tedbirleri kapsar; suça sürüklenen çocuklar hakkında uygulanacak güvenlik tedbirlerinin usûl ve esasları bu Yönetmeliğin kapsamı dışındadır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.2: 'Bu Yönetmelik, korunma ihtiyacı olan çocuklar hakkında alınacak tedbirler ile suça sürüklenen çocuklar hakkında uygulanacak güvenlik tedbirlerinin usûl ve esaslarına, bu kararların yerine getirilmesinde kurumların görev ve sorumluluklarına ilişkin hükümleri kapsar.' Kapsam her iki grubu da içerir.","kaynak":"YON36 m.2","zorluk":"orta"},
    {"id":"36-S-032","soru":"...Yönetmeliğe göre, çocuğun kendisi veya çocuğun bakımından sorumlu kimseler, çocuğun korunma altına alınması amacıyla doğrudan nereye başvurabilir?","siklar":["Cumhuriyet başsavcılığına","Çocuk hâkimine","İl veya ilçelerdeki Aile ve Sosyal Politikalar müdürlüklerine","İl valiliğine","Kolluk çocuk birimine"],"dogru":2,"aciklama":"m.6/2: 'Çocuk veya çocuğun bakımından sorumlu kimseler, çocuğun korunma altına alınması amacıyla il ve ilçelerdeki Aile ve Sosyal Politikalar müdürlüklerine başvurabilir.'","kaynak":"YON36 m.6/2","zorluk":"kolay"},
    {"id":"36-S-033","soru":"...Yönetmeliğe göre, koruyucu ve destekleyici tedbir kararı alınması gereken hâllerde, il veya ilçe Aile ve Sosyal Politikalar müdürlüğünce çocuk hakkında hazırlanacak ....(1)...., talep yazısı ekinde ....(2)...., sunulur. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["sosyal inceleme raporu - mahkemeye veya çocuk hâkimine","tehlikelilik raporu - Cumhuriyet başsavcılığına","sağlık kurulu raporu - il valiliğine","uygulama plânı - kolluk birimine","bilirkişi raporu - baro başkanlığına"],"dogru":0,"aciklama":"m.6/7: '...il veya ilçe Aile ve Sosyal Politikalar müdürlüğünce çocuk hakkında ... hazırlanacak sosyal inceleme raporu, talep yazısı ekinde mahkemeye veya çocuk hâkimine sunulur.'","kaynak":"YON36 m.6/7","zorluk":"orta"},
    {"id":"36-S-034","soru":"...Yönetmeliğe göre, derhâl korunma altına alınmasını gerektiren bir durumun varlığı hâlinde çocuk, herhangi bir sağlık kontrolüne gerek olmaksızın doğrudan Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü tarafından bakım ve gözetim altına alınır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7/1: '...çocuk, sağlık kontrolü yaptırıldıktan sonra Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü tarafından bakım ve gözetim altına alınır.' Sağlık kontrolü ön şarttır.","kaynak":"YON36 m.7/1","zorluk":"orta"},
    {"id":"36-S-035","soru":"...Yönetmeliğe göre, acil korunma kararı alınıncaya kadar geçen sürede çocuk, kimin oluruna istinaden Aile ve Sosyal Politikalar Bakanlığının hizmet modellerinden yararlandırılır?","siklar":["Cumhuriyet başsavcısının","Çocuk hâkiminin","Aile ve Sosyal Politikalar il müdürünün","Valinin","Kaymakamın"],"dogru":2,"aciklama":"m.7/3: 'Acil korunma kararı alınıncaya kadar geçen sürede çocuk; Aile ve Sosyal Politikalar il müdürünün oluruna istinaden Aile ve Sosyal Politikalar Bakanlığının hizmet modellerinden yararlandırılır.'","kaynak":"YON36 m.7/3","zorluk":"orta"},
    {"id":"36-S-036","soru":"...Yönetmeliğe göre, çocuk mahkemesi bulunmayan yerlerde bu mahkeme kurulup göreve başlayıncaya kadar, hakkında kovuşturma başlatılmış olanlar hariç korunma ihtiyacı olan çocuklar hakkında tedbir kararları, aile mahkemesi kurulan yerlerde hangi mahkemece alınır?","siklar":["Ceza mahkemesince","Sulh hukuk mahkemesince","Aile mahkemesince","Ağır ceza mahkemesince","İdare mahkemesince"],"dogru":2,"aciklama":"m.8/2: '...aile mahkemeleri kurulan yerler bakımından bu mahkemeler, kurulu bulunmayan yerler bakımından asliye hukuk mahkemelerince alınır.'","kaynak":"YON36 m.8/2","zorluk":"zor"},
    {"id":"36-S-037","soru":"...Yönetmeliğe göre, Kanunun 7 nci maddesinin yedinci fıkrası uyarınca görevli mahkeme, korunma ihtiyacı olan çocuk hakkında koruyucu ve destekleyici tedbir kararının yanında hangi konularda da duruşma yaparak karar vermeye yetkilidir?","siklar":["Yalnızca velayet konusunda","Yalnızca ceza belirleme konusunda","Yalnızca miras paylaşımı konusunda","Türk Medenî Kanunu hükümlerine göre velayet, vesayet, kayyım, nafaka ve kişisel ilişki kurulması konularında","Yalnızca boşanma konusunda"],"dogru":3,"aciklama":"m.8/9: '...korunma ihtiyacı olan çocuk hakkında koruyucu ve destekleyici tedbir kararının yanında 4721 sayılı Türk Medenî Kanunu hükümlerine göre velayet, vesayet, kayyım, nafaka ve kişisel ilişki kurulması gereken hâllerde de duruşma yaparak karar vermeye yetkilidir.'","kaynak":"YON36 m.8/9","zorluk":"zor"},
    {"id":"36-S-038","soru":"...Yönetmeliğe göre, fiili işlediği sırada oniki yaşını bitirmiş onbeş yaşını doldurmamış çocuklar ile onbeş yaşını doldurmuş ancak onsekiz yaşını doldurmamış sağır ve dilsizlerin, işledikleri fiili algılama ve davranışlarını yönlendirme yeteneklerinin bulunup bulunmadığının takdiri bakımından sosyal inceleme yaptırılması zorunludur.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.8/11: '...bu fiille ilgili olarak davranışlarını yönlendirme yeteneğinin olup olmadığının takdiri bakımından sosyal inceleme yaptırılması zorunludur.' (Maddenin ilk cümlesi genel kural olarak tedbir kararı öncesi sosyal incelemenin ihtiyari olduğunu belirtir: 'yaptırılabilir'; ancak 'Ancak' bağlacıyla getirilen bu özel yaş/durum grubu için inceleme yaptırılması zorunlu kılınmıştır.)","kaynak":"YON36 m.8/11","zorluk":"orta"},
    {"id":"36-S-039","soru":"...Yönetmeliğe göre, tedbir kararlarının, kararı veren mahkemenin veya çocuk hâkimliğinin bulunduğu yerde uygulanması esastır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.9/3: 'Tedbir kararlarının, kararı veren mahkemenin veya çocuk hâkimliğinin bulunduğu yerde uygulanması esastır. Ancak, tedbir kararının uygulanmasının, kararın gönderildiği ildeki kurum veya kuruluşlar tarafından yerine getirilmesi mümkün olmadığı takdirde çocuğun yararı gözetilerek tedbir kararını yerine getirmekle sorumlu kurum tarafından tedbirin nerede yerine getirileceğine karar verilir.'","kaynak":"YON36 m.9/3","zorluk":"orta"},
    {"id":"36-S-040","soru":"...Yönetmeliğin 10. maddesine göre, aşağıdakilerden hangisi hâkim veya mahkemeden tedbir kararının süresinin uzatılmasını veya değiştirilmesini talep edebilecekler arasında sayılmamıştır?","siklar":["Denetim görevlileri","Çocuğun velisi veya vasisi","Tedbir kararını yerine getiren kuruluşun temsilcisi","Cumhuriyet savcısı","Çocuğun sınıf arkadaşları"],"dogru":4,"aciklama":"m.10/1: 'Hâkim veya mahkeme; denetim görevlileri, çocuğun velisi, vasisi, bakım ve gözetimini üstlenen kimselerin, tedbir kararını yerine getiren kişi ve kuruluşun temsilcisi ile Cumhuriyet savcısının talebi üzerine veya re'sen ... süresini uzatabilir veya değiştirebilir.' Çocuğun sınıf arkadaşları bu talep sahipleri arasında sayılmamıştır.","kaynak":"YON36 m.10","zorluk":"orta"},
    {"id":"36-S-041","soru":"...Yönetmeliğe göre, danışmanlık hizmeti verecek kişiler arasından tercih yapılırken kimlere öncelik tanınır?","siklar":["Yalnızca kamu personeli olanlara","Yalnızca en kıdemli olanlara","Yalnızca yüksek lisans derecesine sahip olanlara","Meslekî eğitim almış olmalarının yanı sıra yeterliliklerini sertifikayla belirten ve hizmet belgesiyle ispat edenlere","Yalnızca gönüllü çalışanlara"],"dogru":3,"aciklama":"m.12/6: 'Danışmanlık hizmeti verecek olan kişilerin konularında meslekî eğitim almış olmalarının yanı sıra yeterliliklerini sertifikaları ile belirten ve alanlarında çalıştıklarını hizmet belgesi ile ispat edenler öncelikli olarak tercih edilir.'","kaynak":"YON36 m.12/6","zorluk":"kolay"},
    {"id":"36-S-042","soru":"...Yönetmeliğe göre, bakım veya barınma tedbir kararı alınan ve ihmal veya istismara uğrayan çocuklar, rehabilitasyonları sağlanıncaya kadar korunma ihtiyacı olan diğer çocuklarla aynı ortamda bakılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.14/2: '...ihmal veya istismara uğrayan ... çocukların, rehabilitasyonu sağlanıncaya kadar korunma ihtiyacı olan diğer çocuklarla aynı ortamda bakılmamaları esastır.' Bu çocuklar öncelikle Aile ve Sosyal Politikalar il/ilçe müdürlüklerince bu amaçla kurulmuş merkezlerde rehabilite edilir.","kaynak":"YON36 m.14/2","zorluk":"orta"},
    {"id":"36-S-043","soru":"...Yönetmeliğe göre, sağlık kurulunca düzenlenen rapora göre toplum açısından tehlikeli olan suça sürüklenen veya korunma ihtiyacı olan akıl hastası çocuklar, ....(1).... sağlık kurumlarında korunma ve tedavi altına alınır; bu çocuğun tehlikeliliğinin devam edip etmediği hususunda en geç ....(2).... mahkeme veya çocuk hâkimine bilgi verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["genel - altışar aylık dönemler hâlinde","yüksek güvenlikli - üçer aylık dönemler hâlinde","yüksek güvenlikli - yıllık dönemler hâlinde","özel eğitim veren - üçer aylık dönemler hâlinde","genel - üçer aylık dönemler hâlinde"],"dogru":1,"aciklama":"m.16/5: '...toplum açısından tehlikeli olan suça sürüklenen veya korunma ihtiyacı olan akıl hastası çocuklar hakkında sağlık tedbiri, yüksek güvenlikli sağlık kurumlarında korunma ve tedavi altına alınmak suretiyle yerine getirilir.' m.16/6: '...en geç üçer aylık dönemler hâlinde mahkeme veya çocuk hâkimine bilgi verilir.'","kaynak":"YON36 m.16/5-6","zorluk":"zor"},
    {"id":"36-S-044","soru":"...Yönetmeliğe göre, incelemeyi yapan sosyal çalışma görevlisi ya da uzman, inceleme sonucunda düzenlediği raporu kaç gün içinde mahkemeye veya hâkime vermelidir?","siklar":["Üç gün","Beş gün","Üç ay","On gün","Otuz gün"],"dogru":3,"aciklama":"m.18/12: 'İncelemeyi yapan sosyal çalışma görevlisi ya da uzman, inceleme sonucunda bir rapor düzenleyerek on gün içinde mahkemeye veya hâkime verir.'","kaynak":"YON36 m.18/12","zorluk":"zor"},
    {"id":"36-S-045","soru":"...Yönetmeliğe göre, koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumların merkezî koordinasyonu hangi bakanlıkça sağlanır ve bu koordinasyonun sekretarya hizmetlerini hangi birim yürütür?","siklar":["İçişleri Bakanlığı - İl Emniyet Müdürlüğü","Adalet Bakanlığı - Ceza İşleri Genel Müdürlüğü","Millî Eğitim Bakanlığı - Özel Eğitim Genel Müdürlüğü","Sağlık Bakanlığı - Ruh Sağlığı Genel Müdürlüğü","Aile ve Sosyal Politikalar Bakanlığı - Çocuk Hizmetleri Genel Müdürlüğü"],"dogru":4,"aciklama":"m.19/1-2: 'Koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumların koordinasyonu Aile ve Sosyal Politikalar Bakanlığınca sağlanır. Koordinasyonun sekretarya hizmetleri Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü tarafından yürütülür.'","kaynak":"YON36 m.19","zorluk":"orta"},
    {"id":"36-S-046","soru":"...Yönetmeliğe göre, ilçelerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumların koordinasyonu, 20 nci madde hükümlerine göre kaymakamlıkça yerine getirilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.21/1: 'İlçelerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumların koordinasyonu, 20 nci madde hükümlerine göre kaymakamlıkça yerine getirilir.'","kaynak":"YON36 m.21","zorluk":"kolay"},
    {"id":"36-S-047","soru":"...Yönetmeliğe göre, çocuk birimlerinde görevli kolluk personeline hangi konularda eğitim verilir?","siklar":["Yalnızca trafik mevzuatı","Yalnızca silah kullanımı","Yalnızca arşiv ve evrak yönetimi","Yalnızca yabancı dil","Çocuk hukuku, çocuk suçluluğunun önlenmesi, çocuk gelişimi ve psikolojisi, sosyal hizmet gibi konularda"],"dogru":4,"aciklama":"m.25/2: 'Çocuk birimlerinde görevli kolluk personeline, kendi kurumları tarafından çocuk hukuku, çocuk suçluluğunun önlenmesi, çocuk gelişimi ve psikolojisi, sosyal hizmet gibi konularda eğitim verilir.'","kaynak":"YON36 m.25/2","zorluk":"kolay"},
  ],
  61: [
    {"id":"YON37-S-001","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre bu Yönetmelik hangi Kanunun hangi maddelerine dayanılarak hazırlanmıştır?","siklar":["5395 sayılı Çocuk Koruma Kanununun 32 ve 47 nci maddelerine","5271 sayılı Ceza Muhakemesi Kanununun 172 ve 174 üncü maddelerine","2828 sayılı Sosyal Hizmetler Kanununun 9 uncu maddesine","5237 sayılı Türk Ceza Kanununun 31 inci maddesine","5395 sayılı Çocuk Koruma Kanununun 3 ve 5 inci maddelerine"],"dogru":0,"aciklama":"m.3/1: 'Bu Yönetmelik, 3/7/2005 tarihli ve 5395 sayılı Çocuk Koruma Kanununun 32 ve 47 nci maddelerine dayanılarak hazırlanmıştır.' Dayanak, 5395'in 32 ve 47'nci maddeleridir.","kaynak":"YON37 m.3","zorluk":"kolay"},
    {"id":"YON37-S-002","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre suça sürüklenen çocuk hakkındaki soruşturmayı kural olarak kim yürütür?","siklar":["İl emniyet müdürlüğü çocuk şube müdürlüğü","Çocuk bürosunda görevli Cumhuriyet savcısı bizzat","Çocuk mahkemesi hâkimi","Kolluğun çocuk birimi amiri","Cumhuriyet başsavcısı bizzat"],"dogru":1,"aciklama":"m.5/1: 'Suça sürüklenen çocuk hakkındaki soruşturma, çocuk bürosunda görevli Cumhuriyet savcısı tarafından bizzat yapılır.' Kural, çocuk bürosu savcısının bizzat soruşturmasıdır.","kaynak":"YON37 m.5/1","zorluk":"orta"},
    {"id":"YON37-S-003","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre gecikmesinde sakınca bulunan hâllerde, suça sürüklenen çocuk hakkındaki soruşturma çocuk bürosunda görevli olmayan Cumhuriyet savcıları tarafından da yerine getirilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5/1: 'Gecikmesinde sakınca bulunan hâllerde, soruşturma çocuk bürosunda görevli olmayan Cumhuriyet savcıları tarafından da yerine getirilebilir.' Bu, bizzat yapma kuralının istisnasıdır.","kaynak":"YON37 m.5/1","zorluk":"orta"},
    {"id":"YON37-S-004","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre suça sürüklenen çocuğun ifadesinin alınması sırasında çocuğun yanında sosyal çalışma görevlisinin bulundurulması zorunludur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/4: 'Suça sürüklenen çocuğun ifadesinin alınması veya çocuk hakkındaki diğer işlemler sırasında, çocuğun yanında sosyal çalışma görevlisi bulundurulabilir.' 'Bulundurulabilir' takdirî bir imkândır, zorunluluk değildir.","kaynak":"YON37 m.5/4","zorluk":"kolay"},
    {"id":"YON37-S-005","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre mağdur çocuğun tanık olarak dinlenmesi hâlinde Ceza Muhakemesi Kanununun tanıklığa ilişkin hükümleri hangi istisna ile uygulanır?","siklar":["Sadece kollukta değil, yalnızca mahkemede","Sadece sosyal çalışma görevlisi eşliğinde","Yemin hariç","Sadece onbeş yaşından büyükse","İstisnasız tüm hükümler uygulanır"],"dogru":2,"aciklama":"m.5/5: 'Mağdur çocuğun tanık olarak dinlenmesi hâlinde, yemin hariç, ... 5271 sayılı Ceza Muhakemesi Kanununun tanıklığa ilişkin hükümleri uygulanır.' Tek istisna yemin hükmüdür.","kaynak":"YON37 m.5/5","zorluk":"orta"},
    {"id":"YON37-S-006","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre işlenen suçun etkisiyle psikolojisi bozulmuş mağdur çocuk, ilgili soruşturmada tanık olarak kaç defa dinlenebilir?","siklar":["İki defa","Üç defa","Sınırsız sayıda","Bir defa; maddî gerçeğin ortaya çıkarılması açısından zorunluluk arz eden hâller saklıdır","Hiç dinlenmez, yalnızca yazılı rapor alınır"],"dogru":3,"aciklama":"m.5/6: '...psikolojisi bozulmuş mağdur çocuk, bu suça ilişkin soruşturmada tanık olarak bir defa dinlenebilir. Maddî gerçeğin ortaya çıkarılması açısından zorunluluk arz eden haller saklıdır.' Kural bir defa, istisna zorunluluk hâlidir.","kaynak":"YON37 m.5/6","zorluk":"orta"},
    {"id":"YON37-S-007","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre mağdur çocuğun tanık olarak dinlenmesi sırasında bulundurulacak uzman kişi aşağıdaki alanlardan hangisinden olmak zorunda DEĞİLDİR?","siklar":["Psikoloji","Psikiyatri","Tıp","Eğitim","Hukuk"],"dogru":4,"aciklama":"m.5/7: 'Mağdur çocuğun tanık olarak dinlenmesi sırasında psikoloji, psikiyatri, tıp veya eğitim alanında uzman bir kişi bulundurulur. Bunlar hakkında bilirkişilere ilişkin hükümler uygulanır.' Hukuk alanı bu sayımda yer almaz.","kaynak":"YON37 m.5/7","zorluk":"orta"},
    {"id":"YON37-S-008","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre Cumhuriyet savcısı, soruşturmayı yürütürken tedbir kararı alınabilmesi için korunma ihtiyacı olan çocuğu hangi kuruma bildirmekle yükümlüdür?","siklar":["Aile Mahkemesine","Kolluğun çocuk birimine","Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna","Baroya","Valiliğe"],"dogru":2,"aciklama":"m.5/8: 'Cumhuriyet savcısı ... korunma ihtiyacı olan çocuğu, Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirmekle yükümlüdür. Sosyal Hizmetler ve Çocuk Esirgeme Kurumu gerekli incelemeyi derhâl yapar.'","kaynak":"YON37 m.5/8","zorluk":"orta"},
    {"id":"YON37-S-009","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre Cumhuriyet savcısının isteği üzerine çocuk hakkında koruyucu ve destekleyici tedbir kararını kim verir?","siklar":["Cumhuriyet savcısı bizzat","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu müdürü","İl sosyal hizmetler müdürü","Çocuk hâkimi","Kolluğun çocuk birimi amiri"],"dogru":3,"aciklama":"m.5/8: 'Cumhuriyet savcısı da soruşturma sırasında gerekli gördüğünde çocuk hâkiminden koruyucu ve destekleyici tedbir kararı verilmesini isteyebilir.' Tedbir kararını veren makam çocuk hâkimidir; savcı yalnızca ister.","kaynak":"YON37 m.5/8","zorluk":"zor"},
    {"id":"YON37-S-010","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre fiili işlediği sırada ....(1).... yaşından küçük çocuklar ile ....(2).... yaşını doldurmamış sağır ve dilsizlerin işledikleri iddia olunan suçlara dair delillerin toplanması veya başka fail bulunup bulunmadığının belirlenmesine ilişkin soruşturma yapılabilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["on - oniki","oniki - onbeş","onbeş - oniki","oniki - onaltı","on - onbeş"],"dogru":1,"aciklama":"m.5/10: 'Fiili işlediği sırada oniki yaşından küçük çocuklar ile onbeş yaşını doldurmamış sağır ve dilsizlerin işledikleri iddia olunan suçlara dair delillerin toplanması veya başka fail ya da faillerin bulunup bulunmadığının belirlenmesine ilişkin olarak ... soruşturma yapılabilir.' Sayılar oniki ve onbeştir.","kaynak":"YON37 m.5/10","zorluk":"zor"},
    {"id":"YON37-S-011","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre görünüş itibarıyla oniki yaşından büyük olup nüfus kaydına göre oniki yaşından küçük olan çocuklar hakkında, yaşı hukuk mahkemesi nezdinde düzeltilmeden hangi işlem yapılamaz?","siklar":["Kolluk ifadesi alınamaz","Koruyucu tedbir kararı verilemez","Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirim yapılamaz","Sosyal inceleme raporu düzenlenemez","Kamu davası açılamaz"],"dogru":4,"aciklama":"m.5/11: '...çocuğun yaşı hukuk mahkemesi nezdinde dava açılıp düzeltilmeden kamu davası açılamaz.' Yaş çelişkisinin doğrudan bağlandığı işlem kamu davası açılmasıdır.","kaynak":"YON37 m.5/11","zorluk":"orta"},
    {"id":"YON37-S-012","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuklarla ilgili kolluk görevi öncelikle kim tarafından yerine getirilir?","siklar":["Kolluğun çocuk birimleri","Cumhuriyet savcısı","Çocuk hâkimi","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu personeli","Sosyal çalışma görevlisi"],"dogru":0,"aciklama":"m.16/1: 'Çocuklarla ilgili kolluk görevi, öncelikle kolluğun çocuk birimleri tarafından yerine getirilir.' Öncelik çocuk birimlerindedir.","kaynak":"YON37 m.16/1","zorluk":"kolay"},
    {"id":"YON37-S-013","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre kolluk bünyesinde çocuklarla ilgili işlemler yürütülürken, çocukların soruşturma nedeniyle kolluk biriminde bulunan yetişkinlerle karşılaşmasına engel olunmasına gerek yoktur; bu konuda herhangi bir tedbir alınmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.16/2: 'Kolluk bünyesinde çocuklarla ilgili işlemlerin yürütülmesi sırasında, bunların soruşturma nedeniyle kolluk biriminde bulunan yetişkinlerle karşılaşmalarının engellenmesi için gerekli tedbirler alınır.' Tedbir alınması açıkça öngörülmüştür.","kaynak":"YON37 m.16/2","zorluk":"kolay"},
    {"id":"YON37-S-014","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre kolluğun çocuk birimi, korunma ihtiyacı olan veya suça sürüklenen çocuklar hakkında işleme başlandığında durumu aşağıdakilerden hangisine bildirmekle yükümlü DEĞİLDİR?","siklar":["Çocuğun veli veya vasisine","Baroya","Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna","Çocuğu suça azmettirdiğinden şüphelenilen yakınına","Çocuğun bakımını üstlenen kimseye"],"dogru":3,"aciklama":"m.16/3: '...durumu, derhal çocuğun veli veya vasisine ya da çocuğun bakımını üstlenen kimseye, baroya ve Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna ... bildirir. Ancak, çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına bilgi verilmez.'","kaynak":"YON37 m.16/3","zorluk":"orta"},
    {"id":"YON37-S-015","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına bilgi verilmemesi hususu ne şekilde işleme bağlanır?","siklar":["Yalnızca sözlü olarak amire rapor edilir","Baro tarafından tutanağa geçirilir","Tutanak altına alınıp derhal Cumhuriyet savcısına bildirilir","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu tarafından mahkemeye bildirilir","İşlem kayda geçirilmeden doğrudan uygulanır"],"dogru":2,"aciklama":"m.16/3: 'Keyfiyet, soruşturma dosyası içine konulmak üzere tutanak altına alınarak derhâl Cumhuriyet savcısına bildirilir.' İşlem yazılı tutanakla ve savcıya derhal bildirimle belgelenir.","kaynak":"YON37 m.16/3","zorluk":"zor"},
    {"id":"YON37-S-016","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuğun kollukta bulunduğu süre içinde yanında bir yakınının bulunmasına ilişkin kural aşağıdakilerden hangisidir?","siklar":["Her koşulda yanında bir yakını bulunması zorunludur, istisna yoktur","Yanında yalnızca sosyal çalışma görevlisi bulunabilir, yakını bulunamaz","Yakınının bulunması yalnızca mahkeme kararıyla mümkündür","Yanında yakını bulunması yalnızca onbeş yaşından küçüklere tanınır","Çocuğun yararı aksini gerektirmedikçe yanında yakınlarından biri devamlı bulunur; azmettiren veya istismar şüphesi olan yakın hariç tutulur"],"dogru":4,"aciklama":"m.16/4: 'Çocuğun yararı aksini gerektirmediği takdirde kollukta bulunduğu süre içerisinde yanında yakınlarından birinin devamlı olarak bulunmasına imkân sağlanır. Çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınları yanında bulundurulmaz.'","kaynak":"YON37 m.16/4","zorluk":"orta"},
    {"id":"YON37-S-017","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre kolluğun çocuk birimi, teslim edeceği veli, vasi veya kanunî temsilciyi bulamadığı ya da bunların çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelendiği hâllerde çocuğu kime teslim eder?","siklar":["Doğrudan çocuk hâkimine teslim eder","En yakın akrabaya, savcı onayı olmadan teslim eder","Belediye sosyal yardım birimine teslim eder","Cumhuriyet savcısının talimatını alarak Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder","Baroya teslim eder"],"dogru":3,"aciklama":"m.16/5: '...bu kişilere teslim edemez. Cumhuriyet savcısının talimatını alarak Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder.' Teslim, savcı talimatına bağlı olarak Kuruma yapılır.","kaynak":"YON37 m.16/5","zorluk":"orta"},
    {"id":"YON37-S-018","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre kolluk görevlisi, teslim ettiği çocuğun veli, vasi veya kanunî temsilcisinin çocuğa yeterli rehberlik sunamadığı veya çocuğu yeterince gözetemediği hususunda bilgi edinirse durumu Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna derhal bildirir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16/6: 'Kolluk görevlisi, teslim ettiği çocuğun veli, vasi, kanunî temsilcisi veya bakımını üstlenen kimselerin çocuğa yeterli rehberliği sunamadığı veya çocuğu yeterince gözetemediği hususlarında bilgi edinmesi hâlinde durumu Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna derhâl bildirir.'","kaynak":"YON37 m.16/6","zorluk":"kolay"},
    {"id":"YON37-S-019","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre hakkında acil korunma kararı almak için beklemenin çocuğun yararına aykırı olduğu tespit edilen hâllerde, kolluğun çocuk birimi durumun gerektirdiği önlemleri alarak çocuğun güvenliğini sağlar ve ....(1).... Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder; çocuk suç mağduruysa bu teslim işlemi ....(2).... doğrultusunda yapılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["bir hafta içinde - kolluk amirinin talimatı","mümkün olan en kısa sürede - Cumhuriyet savcısının talimatı","derhal - çocuk hâkiminin kararı","yirmidört saat içinde - Sosyal Hizmetler ve Çocuk Esirgeme Kurumu müdürünün onayı","en geç üç gün içinde - baro görüşü"],"dogru":1,"aciklama":"m.16/7: '...kolluğun çocuk birimi, durumun gerektirdiği önlemleri almak suretiyle çocuğun güvenliğini sağlar ve mümkün olan en kısa sürede Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder. ... Kolluğun çocuk birimi, suç mağduru olan korunma ihtiyacı içinde olan çocuklar hakkında ... teslim işlemini, Cumhuriyet savcısının talimatı doğrultusunda yapar.'","kaynak":"YON37 m.16/7","zorluk":"zor"},
    {"id":"YON37-S-020","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre aşağıdaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["Cumhuriyet savcısı - soruşturmayı bizzat yürütür ve gerektiğinde çocuk hâkiminden tedbir kararı ister","Kolluğun çocuk birimi - korunma ihtiyacı olan çocuğu ilgili makamlara bildirir ve gerektiğinde Kuruma teslim eder","Çocuk hâkimi - koruyucu ve destekleyici tedbir kararını verir","Kolluğun çocuk birimi - koruyucu ve destekleyici tedbir kararını doğrudan kendisi verir","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu - kendisine yapılan bildirim üzerine gerekli incelemeyi derhâl yapar"],"dogru":3,"aciklama":"m.5/8'e göre koruyucu ve destekleyici tedbir kararını yalnızca çocuk hâkimi verir; savcı bu kararı 'ister', kolluk ise m.16 uyarınca bildirim ve teslim işlemlerini yürütür ama tedbir kararı verme yetkisi yoktur. D eşleştirmesi bu nedenle yanlıştır.","kaynak":"YON37 m.5/8, m.16","zorluk":"zor"},
    {"id":"YON37-S-021","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuk mahkemeleri ile çocuk ağır ceza mahkemeleri bulunmayan yerlerde, bu mahkemeler kurulup göreve başlayıncaya kadar çocuklar tarafından işlenen suçlara ait soruşturmaları kim yürütür?","siklar":["Cumhuriyet başsavcılığının iş bölümünde gösterilen Cumhuriyet savcısı","Çocuk bürosunda görevli Cumhuriyet savcısı","İl valisi","Kolluğun çocuk birimi amiri","Çocuk hâkimi bizzat"],"dogru":0,"aciklama":"m.5/2: 'Çocuk mahkemeleri ile çocuk ağır ceza mahkemeleri bulunmayan yerlerde, bu mahkemeler kurulup göreve başlayıncaya kadar çocuklar tarafından işlenen suçlara ait soruşturmalar Cumhuriyet başsavcılığının iş bölümünde gösterilen Cumhuriyet savcısı tarafından yapılır.' Bu, mahkemesi kurulmamış yerler için geçici bir görevlendirme kuralıdır.","kaynak":"YON37 m.5/2","zorluk":"kolay"},
    {"id":"YON37-S-022","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre, suçun işlendiği yerin bağlı olduğu ağır ceza mahkemesi ile bağlı bulunduğu çocuk mahkemesi veya çocuk ağır ceza mahkemesi farklı yerlerde bulunduğunda, Cumhuriyet savcısı soruşturma evrakını ilgili yer Cumhuriyet başsavcılığına ne düzenleyerek gönderir?","siklar":["İddianame düzenleyerek","Kovuşturmaya yer olmadığına dair karar düzenleyerek","Fezleke düzenleyerek","Tensip zaptı düzenleyerek","Bilirkişi raporu düzenleyerek"],"dogru":2,"aciklama":"m.5/3: 'Cumhuriyet savcısı çocuk hakkında düzenlediği soruşturma evrakını, çocuk mahkemesine veya çocuk ağır ceza mahkemesine dava açılmak üzere bu yer Cumhuriyet başsavcılığına fezleke düzenleyerek gönderir.' Yargı çevresi farklılığında evrakın gönderilme aracı fezlekedir.","kaynak":"YON37 m.5/3","zorluk":"orta"},
    {"id":"YON37-S-023","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre, koruyucu ve destekleyici tedbir kararı alınması gereken hâllerde çocuk hakkında hazırlanacak sosyal inceleme raporu, bu Yönetmeliğin kaçıncı maddesine uygun olarak hazırlanır?","siklar":["16 ncı maddesine","21 inci maddesine","3 üncü maddesine","32 nci maddesine","47 nci maddesine"],"dogru":1,"aciklama":"m.5/8: '...il veya ilçe sosyal hizmetler müdürlüğünce çocuk hakkında bu Yönetmeliğin 21 inci maddesine uygun olarak hazırlanacak sosyal inceleme raporu, talep yazısı ekinde mahkemeye veya çocuk hâkimine sunulur.' Dayanak madde numarası 21'dir.","kaynak":"YON37 m.5/8","zorluk":"zor"},
    {"id":"YON37-S-024","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre, koruyucu ve destekleyici tedbir kararı alınması gereken hâllerde çocuk hakkındaki sosyal inceleme raporunu kim hazırlar?","siklar":["İl veya ilçe sosyal hizmetler müdürlüğü","Sosyal Hizmetler ve Çocuk Esirgeme Kurumu merkez teşkilatı","Çocuk hâkimi","Cumhuriyet savcısı","Kolluğun çocuk birimi"],"dogru":0,"aciklama":"m.5/8: '...il veya ilçe sosyal hizmetler müdürlüğünce çocuk hakkında ... sosyal inceleme raporu ... hazırlanacak...' Raporu hazırlayan makam il veya ilçe sosyal hizmetler müdürlüğüdür.","kaynak":"YON37 m.5/8","zorluk":"orta"},
    {"id":"YON37-S-025","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre Sosyal Hizmetler ve Çocuk Esirgeme Kurumu, yaptığı inceleme sonucunda hazırladığı sosyal inceleme raporunun bir örneğini soruşturmayı yapan Cumhuriyet savcılığına gönderir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5/8: 'Kurum, aynı zamanda yaptığı inceleme sonucunda hazırladığı sosyal inceleme raporunun bir örneğini soruşturmayı yapan Cumhuriyet savcılığına gönderir.' Rapor hem mahkemeye/çocuk hâkimine hem de soruşturmayı yürüten savcılığa ulaştırılır.","kaynak":"YON37 m.5/8","zorluk":"kolay"},
    {"id":"YON37-S-026","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuklar hakkında yakalama, gözaltına alma ve ifade almaya ilişkin hususlarda hangi düzenlemenin çocuklara ilişkin hükümleri uygulanır?","siklar":["Ceza Muhakemesi Kanununun 91 inci maddesi","Çocuk Koruma Kanununun 15 inci maddesi","Adli ve Önleme Aramaları Yönetmeliği","Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliği","Polis Vazife ve Salahiyet Kanunu"],"dogru":3,"aciklama":"m.5/9: 'Çocuklar hakkında, yakalama, gözaltına alma ve ifade almaya ilişkin hususlarda 1/6/2005 tarihli ve 25832 sayılı Resmî Gazete'de yayımlanan Yakalama, Gözaltına Alma ve İfade Alma Yönetmeliğinin çocuklara ilişkin hükümleri uygulanır.' Atıf yapılan düzenleme budur.","kaynak":"YON37 m.5/9","zorluk":"orta"},
    {"id":"YON37-S-027","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre, çocuk resmî veya özel bir kurumda kalıyorsa, kolluğun çocuk birimi durumu veli/vasi, baro ve Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirmenin yanı sıra ayrıca kime bildirir?","siklar":["Kurum müdürüne","Kurum temsilcisine","Çocuk hâkimine","İl sosyal hizmetler müdürüne","Cumhuriyet başsavcısına"],"dogru":1,"aciklama":"m.16/3: '...çocuk resmî veya özel bir kurumda kalıyorsa ayrıca kurum temsilcisine bildirir.' Ek bildirimin muhatabı kurum temsilcisidir.","kaynak":"YON37 m.16/3","zorluk":"orta"},
    {"id":"YON37-S-028","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuğun kollukta bulunduğu süre içinde yanında bir yakınının bulunmasına ilişkin keyfiyet nasıl işleme bağlanır?","siklar":["Sözlü olarak amire bildirilir, herhangi bir kayıt tutulmaz","Ayrı bir dosyada saklanır, soruşturma evrakına eklenmez","Hazırlanan tutanağa yazılarak adlî veya idarî makamlara sevk edilen evraka eklenir","Yalnızca Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna gönderilir","Yalnızca baroya bildirilir"],"dogru":2,"aciklama":"m.16/4: 'Keyfiyet hazırlanan tutanağa yazılarak adlî veya idarî makamlara sevk edilen evraka eklenir.' Kayıt yazılı tutanakla yapılır ve sevk edilen evrakın bir parçası olur.","kaynak":"YON37 m.16/4","zorluk":"zor"},
    {"id":"YON37-S-029","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre Sosyal Hizmetler ve Çocuk Esirgeme Kurumu, kolluğun çocuk birimi tarafından getirilen çocuklarla ilgili olarak ne yapmakla yükümlüdür?","siklar":["Çocukları en az bir hafta gözlem altında tutmakla","Teslim işlemini mahkeme kararı şartına bağlamakla","Teslim almayı gerekçe göstererek reddedebilmekle","Çocukların derhâl teslim alınabilmesi için gerekli önlemleri almakla","Teslim süresini kendi takdirine bırakmakla"],"dogru":3,"aciklama":"m.16/7: 'Sosyal Hizmetler ve Çocuk Esirgeme Kurumu, kolluk tarafından getirilen çocukların derhâl teslim alınabilmesi için gerekli önlemleri alır.' Kurumun yükümlülüğü derhal teslim alımını mümkün kılacak önlemleri almaktır.","kaynak":"YON37 m.16/7","zorluk":"orta"},
    {"id":"YON37-S-030","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre sosyal inceleme raporu sürecine ilişkin aşağıdaki ifadelerden hangisi YANLIŞTIR?","siklar":["Rapor, il veya ilçe sosyal hizmetler müdürlüğünce hazırlanır","Rapor, bu Yönetmeliğin 21 inci maddesine uygun olarak hazırlanır","Rapor, talep yazısı ekinde mahkemeye veya çocuk hâkimine sunulur","Kurum, raporun bir örneğini soruşturmayı yapan Cumhuriyet savcılığına gönderir","Rapor, doğrudan çocuk bürosunda görevli Cumhuriyet savcısı tarafından hazırlanır"],"dogru":4,"aciklama":"m.5/8'e göre sosyal inceleme raporunu hazırlayan makam il veya ilçe sosyal hizmetler müdürlüğüdür; çocuk bürosu savcısının raporu bizzat hazırlaması metinde yer almaz, savcının rolü soruşturmayı yürütmek ve gerektiğinde tedbir istemektir. A, B, C, D ise m.5/8 metniyle birebir uyumludur.","kaynak":"YON37 m.5/8","zorluk":"zor"},
    {"id":"YON37-S-031","soru":"Çocuk Koruma Kanununun Uygulanmasına İlişkin Usûl ve Esaslar Hakkında Yönetmelik'e göre çocuk mahkemeleri ile çocuk ağır ceza mahkemeleri bulunmayan yerlerde soruşturmalar ....(1).... tarafından yürütülür; yargı çevresinin farklı olduğu hâllerde ise Cumhuriyet savcısı soruşturma evrakını ilgili yer başsavcılığına ....(2).... düzenleyerek gönderir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["çocuk bürosunda görevli Cumhuriyet savcısı - iddianame","Cumhuriyet başsavcılığının iş bölümünde gösterilen Cumhuriyet savcısı - fezleke","il veya ilçe sosyal hizmetler müdürlüğü - sosyal inceleme raporu","kolluğun çocuk birimi amiri - tutanak","çocuk hâkimi - takipsizlik kararı"],"dogru":1,"aciklama":"m.5/2: '...soruşturmalar Cumhuriyet başsavcılığının iş bölümünde gösterilen Cumhuriyet savcısı tarafından yapılır.' m.5/3: '...Cumhuriyet savcısı ... soruşturma evrakını ... bu yer Cumhuriyet başsavcılığına fezleke düzenleyerek gönderir.' Doğru ifadeler sırasıyla iş bölümü savcısı ve fezlekedir.","kaynak":"YON37 m.5/2, m.5/3","zorluk":"zor"},
  ],
  62: [
    {"id":"YON38-S-001","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre bu Yönetmeliğin dayandığı kanunlardan biri aşağıdakilerden hangisidir?","siklar":["5237 sayılı Türk Ceza Kanunu","14/6/1989 tarihli ve 3572 sayılı İşyeri Açma ve Çalışma Ruhsatlarına Dair Kanun Hükmünde Kararnamenin Değiştirilerek Kabulüne Dair Kanun","5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanun","2911 sayılı Toplantı ve Gösteri Yürüyüşleri Kanunu","6136 sayılı Ateşli Silahlar ve Bıçaklar Kanunu"],"dogru":1,"aciklama":"m.3: 'Bu Yönetmelik, ... 14/6/1989 tarihli ve 3572 sayılı İşyeri Açma ve Çalışma Ruhsatlarına Dair Kanun Hükmünde Kararnamenin Değiştirilerek Kabulüne Dair Kanun ... hükümleri ... dayanılarak hazırlanmıştır.' 3572 sayılı Kanun, Yönetmeliğin temel dayanaklarından biridir.","kaynak":"İşyeri Açma Yön. m.3","zorluk":"kolay"},
    {"id":"YON38-S-002","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre 634 sayılı Kat Mülkiyeti Kanunu kapsamındaki bir gayrimenkulde, tapu kütüğünde MESKEN olarak gösterilen bağımsız bölümde eğlence ve toplantı yeri açılabilmesi için kat maliklerinden hangi karar aranır?","siklar":["Kat malikleri kurulunun üçte iki çoğunluğu","Oy çokluğu ile alınmış karar","Oy birliği ile alınmış karar","Yalnızca bina yöneticisinin yazılı onayı","Yönetim planında aksine hüküm yoksa hiçbir karar aranmaz"],"dogru":2,"aciklama":"m.5/b: '...tapu kütüğünde mesken olarak gösterilen bağımsız bölümlerinde sinema, tiyatro, ... eğlence ve toplantı yerleri ... açılması hususunda kat maliklerinin oy birliği ile karar alması...' Meskende şart oy birliğidir.","kaynak":"İşyeri Açma Yön. m.5","zorluk":"orta"},
    {"id":"YON38-S-003","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre işyeri açma ve çalışma ruhsatı verilen işyerlerinde aranan genel şartlar arasında aşağıdakilerden hangisi SAYILMAMIŞTIR?","siklar":["İş sağlığı ve güvenliği ile ilgili mevzuatta öngörülen tedbirlerin alınmış olması","Karayolu kenarındaki işyerleri için karayolu trafik güvenliğinin sağlanmış ve geçiş yolu izin belgesinin alınmış olması","İşyerinin en az beş yıl süreyle aynı adreste kesintisiz faaliyet göstermiş olması","Madencilik faaliyetleri sırasında patlayıcı madde kullanılan yerlerde ilgili tüzük hükümlerine uygun tedbirlerin alınması","Sınai, tıbbi ve radyoaktif atık üreten işyerlerinde bu atıklara ilişkin gerekli tedbir ve izinlerin alınmış olması"],"dogru":2,"aciklama":"m.5(a) iş sağlığı-güvenliği, (g) karayolu geçiş izni, (f) maden/patlayıcı tüzüğü ve (j) atık tedbir/izni açıkça sayılmıştır. 'En az beş yıl aynı adreste faaliyet' şeklinde bir süre şartı m.5'te yer almaz.","kaynak":"İşyeri Açma Yön. m.5","zorluk":"orta"},
    {"id":"YON38-S-004","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre sıvılaştırılmış petrol gazı (LPG) tüp dağıtım merkezleri ve perakende satış yerlerinde işyerine giren ve çıkanların tespiti amacıyla kurulan kamera kayıt sistemi kayıtları ....(1).... gün süreyle saklanır ve bu kayıtlar ....(2).... haricindeki kişi ve kuruluşlara verilemez. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["on beş - kolluk kuvvetleri","altmış - mülki idare amiri","doksan - yetkili idare","otuz - yetkili makamlar","yedi - genel kolluk"],"dogru":3,"aciklama":"m.5(o): '...kayıtlar otuz gün süre ile saklanır ve kayıtlar yetkili makamlar haricindeki kişi ve kuruluşlara verilemez.' Süre 30 gün, erişim yalnızca yetkili makamlara açıktır.","kaynak":"İşyeri Açma Yön. m.5(o)","zorluk":"orta"},
    {"id":"YON38-S-005","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre işyeri açma ve çalışma ruhsatlarını kim imzalar?","siklar":["Belediye meclisi","İl encümeni","Mülki idare amiri her zaman bizzat","Özel güvenlik komisyonu","Yetkili idarenin en üst amiri veya görevlendireceği yetkili"],"dogru":4,"aciklama":"m.6: 'İşyeri ruhsatları yetkili idarelerin en üst amiri veya görevlendireceği yetkili tarafından bu Yönetmelikte öngörülen sürede imzalanır; ruhsat için ayrıca, meclis veya encümen tarafından bir karar alınmaz.' İmza yetkisi en üst amir veya görevlendirdiği kişidedir.","kaynak":"İşyeri Açma Yön. m.6","zorluk":"kolay"},
    {"id":"YON38-S-006","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre diğer kamu kurum ve kuruluşları veya ilgili meslek kuruluşları tarafından özel mevzuatına göre verilen izinler ile tescil ve benzeri işlemler, bu Yönetmelik hükümlerine göre ruhsat alma yükümlülüğünü ortadan kaldırır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.6: '...diğer kamu kurum ve kuruluşları ile ilgili meslek kuruluşları tarafından özel mevzuatına göre verilen izinler ile tescil ve benzeri işlemler bu Yönetmelik hükümlerine göre ruhsat alma mükellefiyetini ortadan kaldırmaz.'","kaynak":"İşyeri Açma Yön. m.6","zorluk":"orta"},
    {"id":"YON38-S-007","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre yetkili idareler tarafından verilen işyeri açma ve çalışma ruhsatlarının örnekleri sigorta il müdürlüğüne ve ilgili sicile ....(1).... gönderilir; umuma açık istirahat ve eğlence yerleri için düzenlenen ruhsatların bir örneği ise en geç ....(2).... içinde yetkili idare tarafından kolluğa gönderilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["haftalık olarak - üç gün","yıllık olarak - onbeş gün","aylık olarak - yedi gün","üç aylık olarak - bir ay","aylık olarak - bir ay"],"dogru":2,"aciklama":"m.7: 'Yetkili idareler tarafından verilen işyeri açma ve çalışma ruhsatlarının örnekleri aylık olarak sigorta il müdürlüğüne ve ilgili ise ticaret siciline veya esnaf siciline gönderilir. Umuma açık istirahat ve eğlence yerleri için düzenlenen ... ruhsatların bir örneği en geç yedi gün içinde yetkili idare tarafından kolluğa gönderilir.'","kaynak":"İşyeri Açma Yön. m.7","zorluk":"orta"},
    {"id":"YON38-S-008","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre ruhsatın yenilenmesi veya intibakı gereken hallerde yetkili idareye en geç ....(1).... içinde müracaat edilmesi zorunludur; bu süre mirasçılar için ....(2).... olarak uygulanır. Süresi içinde müracaat yapılmadığının tespiti durumunda ise tespit tarihinden itibaren ....(3).... süre verilir; bu sürenin sonunda ruhsat yenilenmez veya intibak yaptırılmazsa ruhsat iptal edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["altı ay - üç ay - onbeş gün","üç ay - bir yıl - onbeş gün","bir ay - üç ay - yedi gün","üç ay - altı ay - onbeş gün","üç ay - altı ay - bir ay"],"dogru":3,"aciklama":"m.8: '...yetkili idareye en geç üç ay içinde müracaat edilmesi zorunludur. Bu süre mirasçılar için altı ay olarak uygulanır. Süresi içinde müracaat yapılmadığının ... tespiti durumunda tespit tarihinden itibaren onbeş günlük süre verilir. Bu süre sonunda ruhsat yenilenmediği veya intibak yaptırılmadığı hallerde ruhsat iptal edilir.'","kaynak":"İşyeri Açma Yön. m.8","zorluk":"zor"},
    {"id":"YON38-S-009","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre içkili yer bölgesi, mülki idare amirinin genel güvenlik ve asayiş durumu hakkındaki görüşü doğrultusunda belediye sınırları ve mücavir alanlar içinde hangi organ tarafından tespit edilir?","siklar":["Belediye encümeni","İl özel idaresi","İl encümeni","İl genel meclisi","Belediye meclisi"],"dogru":4,"aciklama":"m.29: 'İçkili yer bölgesi, mülkî idare amirinin genel güvenlik ve asayiş durumu hakkındaki görüşü doğrultusunda belediye sınırları ve mücavir alanlar içinde belediye meclisi, bu sınırlar dışında il genel meclisi tarafından tespit edilir.' Sınır içinde yetkili organ belediye meclisidir.","kaynak":"İşyeri Açma Yön. m.29","zorluk":"orta"},
    {"id":"YON38-S-010","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre aşağıdakilerden hangisi, içkili yer bölgesi olarak tespit edilmesine m.30'da açıkça engel getirilen yerlerden/mesafelerden biri DEĞİLDİR?","siklar":["Hükümet binaları, her türlü mabet ve dini kurum ve kuruluşların yakını","Otogar ve otobüs terminalleri","Otoyol ve karayollarının her iki tarafında sınır çizgisine ikiyüz metreden yakın mesafe (konaklama yerleri hariç)","Resmî ve özel okul binaları ile anaokullarına yüz metreden yakın mesafe","Alışveriş merkezlerinin beş yüz metre yakını"],"dogru":4,"aciklama":"m.30(a-d): hükümet binaları/mabet yakını, otoyol-karayolu 200 m, otogar-terminaller, okul-yurt-anaokulu 100 m açıkça sayılmıştır. 'Alışveriş merkezlerinin beş yüz metre yakını' şeklinde bir engel m.30'da yer almaz.","kaynak":"İşyeri Açma Yön. m.30","zorluk":"orta"},
    {"id":"YON38-S-011","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre konaklama yerleri hariç olmak üzere, otoyolları ve karayollarının her iki tarafında sınır çizgisine ikiyüz metreden yakın mesafe içinde içkili yer bölgesi tespit edilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.30/b: 'Konaklama yerleri hariç olmak üzere, otoyolları ve karayollarının her iki tarafında sınır çizgisine ikiyüz metreden yakın mesafe içinde' içkili yer bölgesi tespit edilemez.","kaynak":"İşyeri Açma Yön. m.30","zorluk":"kolay"},
    {"id":"YON38-S-012","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre umuma açık istirahat ve eğlence yerinin açılmasına ve faaliyette bulunmasına, belediye sınırları ve mücavir alan sınırları dışında hangi idare tarafından izin verilir?","siklar":["Belediye","Büyükşehir belediyesi","İl genel meclisi","İl özel idaresi","Vali"],"dogru":3,"aciklama":"m.32: 'Umuma açık istirahat ve eğlence yerinin açılması ve faaliyette bulunmasına belediye sınırları ve mücavir alan sınırları içinde belediye, bu alanlar dışında il özel idaresi tarafından izin verilir.' İzni sınır dışında il özel idaresi verir.","kaynak":"İşyeri Açma Yön. m.32","zorluk":"orta"},
    {"id":"YON38-S-013","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre kolluk tarafından izin almadan açıldığı tespit edilen bir umuma açık istirahat ve eğlence yeri, düzenlenen tutanakla yetkili idareye bildirilir. Yetkili idare, izin almadan açılan bu yeri kapattıktan sonra kolluğa en geç ne kadar süre içinde bilgi verir?","siklar":["Üç gün","Yirmi dört saat","Yedi gün","Onbeş gün","Bir ay"],"dogru":0,"aciklama":"m.32: 'Yetkili idare yapılan bildirim üzerine izin almadan açılan yeri kapatarak en geç üç gün içinde kolluğa bilgi verir.' Süre üç gündür.","kaynak":"İşyeri Açma Yön. m.32","zorluk":"zor"},
    {"id":"YON38-S-014","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre turizmin yoğun olduğu yörelerdeki okulların tatil olduğu dönemlerde, umuma açık yerler (meyhane, bar, internet salonu vb.) ile okullar arasında yüz metre mesafe şartı aranmaya devam eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.32: 'Turizmin yoğun olduğu yörelerdeki okulların tatil olduğu dönemlerde yukarıda belirtilen işyerleri ile okullar arasında yüz metre şartı aranmaz.' Tatil döneminde bu şart aranmaz.","kaynak":"İşyeri Açma Yön. m.32","zorluk":"zor"},
    {"id":"YON38-S-015","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre umuma açık istirahat ve eğlence yerlerinin açılış ve kapanış saatleri, belediye sınırları içinde hangi organ tarafından tespit edilir?","siklar":["Belediye meclisi","İl genel meclisi","Belediye encümeni","Mülki idare amiri","İl özel idaresi"],"dogru":2,"aciklama":"m.33: 'Umuma açık istirahat ve eğlence yerlerinin açılış ve kapanış saatleri belediye sınırları içinde belediye encümeni, bu yerler dışında il encümeni tarafından tespit edilir.' Sınır içinde yetkili organ belediye ENCÜMENİdir, meclis değildir.","kaynak":"İşyeri Açma Yön. m.33","zorluk":"kolay"},
    {"id":"YON38-S-016","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre yüz metre uzaklığın ölçümünde, bina ve tesislerin varsa bahçe kapıları, yoksa bina kapıları esas alınır; kapıların birden fazla olması durumunda en yakını esas alınır ve ölçüm mevcut cadde ve sokaklar üzerinden yaya yolu kullanılarak yapılır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.34: '...bina ve tesislerin varsa bahçe kapıları, yoksa bina kapıları; kapıların birden fazla olması durumunda en yakını esas alınır. Yüz metre uzaklığın ölçümünde, mevcut cadde ve sokaklar üzerinden yaya yolu kullanılarak, yaya kurallarına göre gidilebilecek en kısa mesafe dikkate alınır.'","kaynak":"İşyeri Açma Yön. m.34","zorluk":"orta"},
    {"id":"YON38-S-017","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre umuma açık istirahat ve eğlence yerlerinde çalıştırılacak kişilerin bulaşıcı hastalığı bulunmadığına dair sağlık raporu hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Yılda bir yenilenir ve ruhsat verilirken yetkili idareye ibraz edilmesi zorunludur","Üç ayda bir yenilenir ve yalnızca kolluk denetiminde istenir","Bir defa işe başlamadan önce alınır, sonradan yenilenmesi gerekmez","İşe başlamadan önce temin edilir, çalışıldığı sürece altı ayda bir yenilenir; ruhsat verme aşamasında istenmez ama denetimlerde gösterilir","İki yılda bir yenilenir ve yalnızca mülki idare amirine ibraz edilir"],"dogru":3,"aciklama":"m.36: '...sağlık raporu, bu kişiler işe başlamadan önce temin edilir ve bu kişiler çalıştığı sürece altı ayda bir yenilenerek işyerinde hazır bulundurulur. Bu raporlar ruhsat verme aşamasında yetkili idare tarafından istenmez; ancak, yapılacak denetimlerde bu raporların görevlilere gösterilmesi gerekir.'","kaynak":"İşyeri Açma Yön. m.36","zorluk":"orta"},
    {"id":"YON38-S-018","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre işyerlerindeki müzik yayınları ve müzik yayın izni hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Müzik yayın izni işyeri açma ve çalışma ruhsatına işlenir ve ruhsattan ayrı değerlendirilmez","Müzik yayını, işyeri açma ve çalışma ruhsatı kapsamında yetkili idarece verilir","Müzik yayın izni iptal edilen işyerinde tüm faaliyetler durdurulur","Müzik yayın izni yalnızca kolluk kuvvetlerince denetlenebilir","Müzik yayın izni Çevresel Gürültü Kontrol Yönetmeliği hükümlerine göre verilir, ruhsata işlenmez; ancak görevlilerce sorulduğunda gösterilecek şekilde işyerinde bulundurulur"],"dogru":4,"aciklama":"m.38: 'İş yerlerindeki müzik yayınları, ... Çevresel Gürültü Kontrol Yönetmeliği hükümleri kapsamında verilmiş müzik yayın izni ile yapılır. Müzik yayın izni ruhsata işlenmez. Ancak görevlilerce sorulduğu zaman gösterilebilecek şekilde iş yerinde bulundurulur.'","kaynak":"İşyeri Açma Yön. m.38","zorluk":"kolay"},
    {"id":"YON38-S-019","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre bu Yönetmelik kapsamına giren işletmelerin işletmecisi veya mesul müdürü, işyerinde çalıştırılan bir kişinin ayrılışını, kimlik bildirme belgesi doldurmak suretiyle ....(1).... içinde bağlı bulunduğu ....(2).... bildirir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["yirmi dört saat - kolluğa","kırk sekiz saat - mülki idare amirine","yedi gün - valiliğe","üç gün - il özel idaresine","onbeş gün - belediyeye"],"dogru":0,"aciklama":"m.43: '...iş yerinde sürekli veya geçici olarak çalıştırılan kişinin ayrılışını, ... kimlik bildirme belgesi doldurmak suretiyle yirmi dört saat içerisinde bağlı bulunduğu kolluğa bildirir.' Süre 24 saat, muhatap kolluktur.","kaynak":"İşyeri Açma Yön. m.43","zorluk":"orta"},
    {"id":"YON38-S-020","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre aşağıdaki eşleştirmelerden hangisi YANLIŞTIR?","siklar":["İçkili yer bölgesinin tespiti — belediye sınırları içinde belediye meclisi, dışında il genel meclisi","İşyeri ruhsatının imzalanması — en üst amirce imzalanır, ayrıca belediye meclisi kararı da alınması zorunludur","Umuma açık eğlence yerine izin verilmesi — belediye sınırları içinde belediye, dışında il özel idaresi","Açılış ve kapanış saatlerinin tespiti — belediye sınırları içinde belediye encümeni, dışında il encümeni","Kolluğun işyeri hakkındaki görüşünün iletilmesi — mülki idare amiri vasıtasıyla"],"dogru":1,"aciklama":"m.6: 'İşyeri ruhsatları yetkili idarelerin en üst amiri veya görevlendireceği yetkili tarafından ... imzalanır; ruhsat için ayrıca, meclis veya encümen tarafından bir karar alınmaz.' Ruhsat imzası için meclis kararı ARANMAZ; B şıkkındaki 'ayrıca meclis kararı da alınması zorunludur' ifadesi yanlıştır.","kaynak":"İşyeri Açma Yön. m.6, m.29, m.32, m.33","zorluk":"zor"},
    {"id":"YON38-S-021","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre özel yapı şeklini gerektirdiği için açılabilmesi yapı kullanma izin belgesinin alınmış olması şartına bağlanan yerler arasında aşağıdakilerden hangisi YER ALMAZ?","siklar":["Otel","Hamam ve sauna","Akaryakıt istasyonu","Sıvılaştırılmış petrol gazı (LPG) istasyonu","Kahvehane"],"dogru":4,"aciklama":"m.5(c): 'Özel yapı şeklini gerektiren sinema, tiyatro, düğün salonu, otel, hamam, sauna; ekmek fırını ile akaryakıt, sıvılaştırılmış petrol gazı, sıvılaştırılmış doğal gaz ve sıkıştırılmış doğal gaz istasyonu için yapı kullanma izin belgesinin alınmış olması...' Kahvehane bu bentte sayılmaz; kahvehane m.5(b)'de kat maliklerinin oy birliği/oy çokluğu kararı gerektiren yerler arasında geçer.","kaynak":"İşyeri Açma Yön. m.5(c)","zorluk":"orta"},
    {"id":"YON38-S-022","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre patlayıcı-parlayıcı-yanıcı madde üretilen/satılan/depolanan işyerleri ile iş hanı, çarşı ve benzeri yerler dışında, ....(1).... kişiden fazla çalışanın bulunduğu her türlü işyerinde de yangına karşı gerekli önlemlerin alındığını gösteren itfaiye raporunun alınması zorunludur. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["on","yirmi","yirmi beş","otuz","elli"],"dogru":3,"aciklama":"m.5(h): '...otuz kişiden fazla çalışanın bulunduğu her türlü işyerleri... yangına karşı gerekli önlemlerinin alındığını gösteren itfaiye raporunun alınması...' Eşik otuz kişidir.","kaynak":"İşyeri Açma Yön. m.5(h)","zorluk":"orta"},
    {"id":"YON38-S-023","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre birden fazla işyerinin bir arada bulunduğu iş hanı, çarşı ve benzeri yerlerde itfaiye raporu binanın yönetimi tarafından alınır; yapıda değişiklik olmadığı sürece bu yerlerdeki işyerleri için ayrıca münferit itfaiye raporu aranmaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.5 ek fıkra (12/3/2012-2012/2958 K.): '...itfaiye raporu bu binaların yönetimi tarafından alınır ve yapıda değişiklik olmadığı sürece buralardaki işyerleri için ayrıca münferit itfaiye raporu aranmaz. Yangın tedbirlerini etkileyecek şekilde yapıda değişiklik yapılması durumunda yalnızca yapısında değişiklik yapılan işyerinin sahibinden münferit itfaiye raporu istenir.'","kaynak":"İşyeri Açma Yön. m.5 (ek fıkra)","zorluk":"zor"},
    {"id":"YON38-S-024","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre ekmek fırınlarının bu amaca tahsisli ayrık nizamda müstakil binalarda açılmış olması şartı hangi durumda aranmaz?","siklar":["Fırın, konut bölgesi içinde faaliyet gösteriyorsa","Fırın, ilk kez ruhsat başvurusunda bulunuyorsa","Fırın, alışveriş merkezi içinde bulunan 1000 m² ve üstü alana sahip hipermarket, süpermarket, grossmarket ve megamarket gibi işyerleri bünyesinde yer alıyorsa","Fırın sahibi esnaf sicil kaydına sahipse","Fırın belediye mücavir alanı dışında ise"],"dogru":2,"aciklama":"m.5(m): 'Ekmek fırınlarının bu amaca tahsisli ayrık nizamda müstakil binalarda açılmış olması (Ancak, alışveriş merkezleri içinde bulunan 1000 m² ve üstü alana sahip hipermarket, süpermarket, grossmarket ve megamarket gibi adlarla açılan işyerleri bünyesinde yer alan fırınlarda ayrık nizamda müstakil bina şartı aranmaz.).' İstisna yalnızca bu büyük market türlerine bağlıdır.","kaynak":"İşyeri Açma Yön. m.5(m)","zorluk":"kolay"},
    {"id":"YON38-S-025","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre yanıcı ve parlayıcı madde kategorisindeki sıvıların depolanması amacıyla kullanılan tesis ve düzeneklerde gerçekleştirilecek tadilatlar, ruhsata işlenmeden de faaliyete geçirilebilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5(n): '...bu tesis ve düzeneklerde gerçekleştirilecek tadilatların ruhsata işlenmeden faaliyete geçirilmemesi.' Tadilatın ruhsata işlenmeden faaliyete geçirilmesi yasaktır.","kaynak":"İşyeri Açma Yön. m.5(n)","zorluk":"orta"},
    {"id":"YON38-S-026","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre yapılacak her türlü ruhsat başvurusunda müracaat sahibine, başvuruyu kabul eden görevlinin ....(1).... ile başvurunun yapıldığı ....(2).... gösteren Örnek 6'da yer alan alındı belgesi verilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["adı, soyadı ve unvanı - tarih ve saati","sicil numarası - yalnızca tarihi","T.C. kimlik numarası - haftanın gününü","imza örneği - yalnızca saatini","görev yeri - ay ve yılını"],"dogru":0,"aciklama":"m.6: '...müracaat sahibine başvuruyu kabul eden görevlinin adı, soyadı ve unvanı ile başvurunun yapıldığı tarih ve saati gösteren Örnek 6'da yer alan alındı belgesi verilir.' Belge hem görevlinin kimliğini hem tam zaman bilgisini içerir.","kaynak":"İşyeri Açma Yön. m.6","zorluk":"orta"},
    {"id":"YON38-S-027","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre bu Yönetmelikte belirtilen ruhsatlandırmaya ilişkin süreler ne zaman başlar?","siklar":["Başvuru formunun doldurulduğu an","Eksik belgelerin yetkili idareye verilmesi ile","Kolluk görüşünün alınması ile","Alındı belgesinin düzenlenmesinden bir hafta sonra","İlk denetimin yapıldığı tarihten itibaren"],"dogru":1,"aciklama":"m.6: 'Bu Yönetmelikte belirtilen ruhsatlandırmaya ilişkin süreler eksik belgelerin yetkili idareye verilmesi ile başlar.' Süre, ön incelemede tespit edilen eksikliklerin tamamlanmasıyla işlemeye başlar.","kaynak":"İşyeri Açma Yön. m.6","zorluk":"kolay"},
    {"id":"YON38-S-028","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre işyeri sahibinin ölümü halinde, kanuni mirasçıları adına yeni bir ruhsat düzenlenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8: 'İşyeri sahibinin ölümü halinde, yeni ruhsat düzenlenmeksizin kanunî mirasçıları adına eski ruhsatın intibakı yapılır.' Yeni ruhsat değil, mevcut ruhsatın intibakı söz konusudur.","kaynak":"İşyeri Açma Yön. m.8","zorluk":"orta"},
    {"id":"YON38-S-029","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre aşağıdaki durumlardan hangisinde yeni ruhsat düzenlenmesi GEREKMEZ?","siklar":["İşyerinin başka bir adrese nakledilmesi","İşletmecinin tamamen değişmesi (devir)","İşyerine yeni ortak alınması veya ortaklardan birinin ayrılması","Umuma açık istirahat ve eğlence yeri ile gayrisıhhi müessesenin faaliyet konusunun değişmesi","İşyeri sahibinin ölümü hariç yeni bir işletmeci belirlenmesi"],"dogru":2,"aciklama":"m.8: 'İşyerine yeni ortak alınması veya ortaklardan birinin ayrılması durumunda yeni ruhsat düzenlenmez.' Diğer seçeneklerdeki nakil, devir ve faaliyet konusu değişikliği hallerinde ise yeniden ruhsatlandırma esastır.","kaynak":"İşyeri Açma Yön. m.8","zorluk":"orta"},
    {"id":"YON38-S-030","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre açıkta alkollü içki satışı ve sunumu yapılan işyerleri ile nargilelik tütün mamulünün sunumu yapılan işyerlerine ....(1).... ruhsat düzenlenir; bu işyerleri ....(2).... içinde gerekli belgeleri yetkili idareye ibraz ederek ruhsatlarını kesinleştirir; aksi halde ruhsatları iptal edilerek kapatılır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["kesinleşmemiş - bir aylık süre","geçici - üç aylık süre","ön izinli - onbeş günlük süre","deneme amaçlı - altı aylık süre","taslak - bir haftalık süre"],"dogru":0,"aciklama":"m.32 (Ek onbirinci fıkra:RG-17/4/2021-31457-C.K.-3835/5 md.): '...içkili yerler ile nargilelik tütün mamulünün sunumu yapılan iş yerlerine kesinleşmemiş ruhsat düzenlenir. Kesinleşmemiş ruhsat düzenlenen bu yerler bir aylık süre içinde... gerekli olan belgeleri yetkili idareye ibraz ederek ruhsatlarını kesinleştirir. Bu maddedeki belgeleri süresi içinde ibraz edilmeyen iş yerleri, işyeri açma ve çalışma ruhsatları iptal edilerek yetkili idareler tarafından kapatılır.'","kaynak":"İşyeri Açma Yön. m.32 (ek fıkra)","zorluk":"zor"},
    {"id":"YON38-S-031","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre özel eğitime muhtaç bireylerin devam ettikleri öğretim kurumları ile okullar dışındaki diğer özel öğretim kurumları için meyhane, bar ve benzeri işyerlerine karşı yüz metre mesafe şartı aranmamakla birlikte, hangi kısıtlama bu istisnaya rağmen geçerliliğini korur?","siklar":["İstisna yalnızca gündüz saatlerinde geçerlidir","İstisna yalnızca resmî tatil günlerinde geçerlidir","Bu kurumlarla söz konusu işyerleri aynı sokakta bulunamaz","Bu kurumlarla söz konusu işyerleri aynı ilçede bulunamaz","Bu özel öğretim kurumlarıyla söz konusu işyerlerinin aynı binada bulunması yasaktır"],"dogru":4,"aciklama":"m.32: 'Özel eğitime muhtaç bireylerin devam ettikleri öğretim kurumları ile okullar dışındaki diğer özel öğretim kurumları için bu zorunluluk aranmaz. Ancak söz konusu özel öğretim kurumlarıyla yukarıda belirtilen türdeki işyerleri aynı binada bulunamaz.' Yüz metre şartı kalkar ama aynı bina yasağı kalır.","kaynak":"İşyeri Açma Yön. m.32","zorluk":"zor"},
    {"id":"YON38-S-032","soru":"İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmelik'e göre iskele, istasyon, hava meydanı, terminal, garaj, benzin istasyonu ve benzeri yerler ile fuar, panayır, sergi ve pazar kurulması gibi zorunluluk arz eden yer ve zamanlarda sabahçı kahvesi ve benzeri tesislere geçici veya sürekli izin verilmesi hangi şarta bağlıdır?","siklar":["Yalnızca il genel meclisinin onayına","Sadece mülki idare amirinin re'sen kararına","Ticaret odasının uygun görüşüne","Bağlı olduğu kolluk kuvvetinin görüşü alınmak suretiyle yetkili idare tarafından izin verilmesine","Herhangi bir izin veya görüş aranmaksızın otomatik olarak faaliyete başlanmasına"],"dogru":3,"aciklama":"m.33: '...sabahçı kahvesi ve benzeri diğer tesislere, bağlı olduğu kolluk kuvvetinin görüşü alınmak suretiyle yetkili idare tarafından geçici veya sürekli izin verilebilir.' İzin, kolluk görüşü alınarak yetkili idarece verilir.","kaynak":"İşyeri Açma Yön. m.33","zorluk":"orta"},
  ],
  63: [
    {"id":"YON39-S-001","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre bu Yönetmelik hangi kanunun hangi hükmüne dayanılarak hazırlanmıştır?","siklar":["2872 sayılı Çevre Kanunu'nun Ek-1 inci maddesinin birinci fıkrasının (d) bendi","2872 sayılı Çevre Kanunu'nun 12 nci maddesi","2872 sayılı Çevre Kanunu'nun 20 nci maddesi","5403 sayılı Toprak Koruma ve Arazi Kullanımı Kanunu","6831 sayılı Orman Kanunu"],"dogru":0,"aciklama":"m.3: 'Bu Yönetmelik 9/8/1983 tarihli ve 2872 sayılı Çevre Kanunu'nun Ek-1 inci maddesinin birinci fıkrasının (d) bendine dayanılarak hazırlanmıştır.' Dayanak Ek-1/(d) bendidir.","kaynak":"YON39 m.3","zorluk":"kolay"},
    {"id":"YON39-S-002","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre aşağıdakilerden hangisi, kum ve çakıl ocağı açılması ve işletilmesine izin verilmeyen yerlerden biri DEĞİLDİR?","siklar":["İçme ve kullanma suyu temin edilen kıta içi yüzeysel su kaynakları ve bunları besleyen akarsu ve kuru dereler","Tarım arazileri içinde bulunan sulama kanalları","Termal su kaynaklarının birinci ve ikinci derece koruma alanları","Denizlerde kıyı çizgisi ile kıyı kenar çizgisi arasındaki bölge ve deniz sahil şeritleri","Kıyı çizgisinden deniz istikametine doğru 20 metreden daha az derin denizler"],"dogru":1,"aciklama":"m.5/1: yasak yerler arasında (a) içme-kullanma suyu kaynakları, (b) termal koruma alanları, (ç) kıyı çizgisi-kıyı kenar çizgisi arası bölge, (d) 20 metreden az derin denizler sayılmıştır. 'Tarım arazileri içindeki sulama kanalları' m.5'in bu sayımında yer almaz.","kaynak":"YON39 m.5","zorluk":"orta"},
    {"id":"YON39-S-003","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve dere yatakları üzerinde inşa edilmiş köprü, menfez ve benzeri sanat yapılarına menba yönünde ....(1).... metre ve mansap yönünde ....(2).... metreden daha yakın mesafe bırakarak yaklaşılacak hallerde kum ve çakıl ocağı açılması ve işletilmesine izin verilmez. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["1000 - 750","500 - 1000","750 - 1000","1000 - 1500","500 - 750"],"dogru":2,"aciklama":"m.5/(i): 'anılan sanat yapılarından herhangi birine menba yönünde 750 metre ve mansap yönünde 1000 metreden daha yakın mesafe bırakarak yaklaşılacak hallerde ... izin verilmez.' Menba 750 m, mansap 1000 m.","kaynak":"YON39 m.5","zorluk":"zor"},
    {"id":"YON39-S-004","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, kıyı çizgisinden deniz istikametine doğru 20 metreden daha fazla derin denizlerde kum ve çakıl ocağı açılması ve işletilmesi yasaktır.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/(d): yasak, 'kıyı çizgisinden deniz istikametine doğru 20 metreden daha AZ derin denizlerde' geçerlidir; 'daha fazla derin' denizler bu bent kapsamında değildir.","kaynak":"YON39 m.5","zorluk":"orta"},
    {"id":"YON39-S-005","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve kuru dere yataklarında ocak sahasının akarsu yatağı içindeki başlangıç ve bitim noktaları, kıyıda çakılacak en az kaç metre yüksekliğindeki beton kazıklarla belirlenir?","siklar":["1 metre","2 metre","2,5 metre","1,5 metre","3 metre"],"dogru":3,"aciklama":"m.6/1-(a): 'Ocak sahasının akarsu yatağı içindeki başlangıç ve bitim noktaları kıyıda çakılacak en az 1,5 metre yüksekliğindeki beton kazıklar ile belirlenir.' Asgari yükseklik 1,5 metredir.","kaynak":"YON39 m.6","zorluk":"kolay"},
    {"id":"YON39-S-006","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve kuru dere yataklarında işletme esnasında belirlenecek hangi kottan daha fazla derine inilmez?","siklar":["Şev kotu","Taban kotu","Menba kotu","Mansap kotu","Talveg kotu"],"dogru":4,"aciklama":"m.6/1-(e): 'Belirlenecek talveg kotundan daha fazla derine inilmez.' Derinlik sınırı talveg kotudur.","kaynak":"YON39 m.6","zorluk":"orta"},
    {"id":"YON39-S-007","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, kum, çakıl ve benzeri malzeme alınan yerlere hiçbir şekilde atık bırakılamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/1-(ı): 'Kum, çakıl ve benzeri malzeme alınan yerlere hiçbir şekilde atık bırakılmaz.' Yasak istisnasızdır.","kaynak":"YON39 m.6","zorluk":"kolay"},
    {"id":"YON39-S-008","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve kuru dere yataklarından kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetlerine ilişkin olarak hangi bakanlıktan su ürünleri açısından görüş alınması gerekir?","siklar":["Tarım ve Köyişleri Bakanlığı","Çevre ve Orman Bakanlığı","İçişleri Bakanlığı","Enerji ve Tabii Kaynaklar Bakanlığı","Orman ve Su İşleri Bakanlığı"],"dogru":0,"aciklama":"m.6/1-(k): 'Tarım ve Köyişleri Bakanlığı'ndan söz konusu faaliyet sahası ile ilgili su ürünleri açısından alınacak görüş doğrultusunda faaliyetler yürütülür.' Görüş mercii Tarım ve Köyişleri Bakanlığıdır.","kaynak":"YON39 m.6","zorluk":"orta"},
    {"id":"YON39-S-009","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, deniz ve göl yataklarından kum, çakıl ve benzeri maddelerin alınması ve işletilmesinde esas olan ilke aşağıdakilerden hangisidir?","siklar":["Faaliyetin en kısa sürede tamamlanması","Ekosistem bütünlüğünün korunması ve doğal hayata zarar verilmemesi","Malzemenin en düşük maliyetle çıkarılması","Kıyı çizgisinin genişletilmesi","Faaliyet sahibinin istediği derinliğe inilmesi"],"dogru":1,"aciklama":"m.7/1-(a): 'Ekosistem bütünlüğünün korunması ve doğal hayata zarar verilmemesi esastır.' Deniz-göl işletmesinde temel ilke budur.","kaynak":"YON39 m.7","zorluk":"kolay"},
    {"id":"YON39-S-010","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, deniz ve göl yataklarında faaliyet sahibinin ocak sahası içerisinde derinlik ölçümü yapılabilmesine olanak sağlayacak ekipman bulundurma zorunluluğu yoktur.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7/1-(f): 'Faaliyet sahibince ocak sahası içerisinde derinlik ölçümü yapılabilmesine olanak sağlayacak gerekli ekipman bulundurulur.' Böyle bir zorunluluk vardır.","kaynak":"YON39 m.7","zorluk":"orta"},
    {"id":"YON39-S-011","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, sulak alanlardan kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetleri ile ilgili olarak, bu Yönetmelikle getirilen hükümlere ilaveten hangi düzenleme uygulanır?","siklar":["Çevresel Etki Değerlendirmesi Yönetmeliği","Su Kirliliğinin Kontrolü Yönetmeliği","Sulak Alanların Korunması Yönetmeliği","Toprak Koruma ve Arazi Kullanımı Kanunu","Milli Parklar Kanunu"],"dogru":2,"aciklama":"m.8/1: 'Sulak alanlardan kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetleri ile ilgili olarak bu Yönetmelikle getirilen hükümlere ilaveten ... Sulak Alanların Korunması Yönetmeliği hükümleri uygulanır.' Ek düzenleme budur.","kaynak":"YON39 m.8","zorluk":"orta"},
    {"id":"YON39-S-012","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, Çevresel Etki Değerlendirmesi raporu hazırlaması zorunlu ya da gerekli faaliyet sahipleri, ÇED raporunun eki olarak hangi belge(ler)i ilgili makamlara sunmakla yükümlüdür?","siklar":["Yalnızca noter tasdikli taahhüt","Ek-1'de formatı verilen Çevre Yönetim Planı","Faaliyet ruhsatı örneği","Doğaya Yeniden Kazandırma Planı, çevre yönetim uygulama takvimi ve noter tasdikli taahhüt","İl Çevre ve Orman Müdürlüğü onay yazısı"],"dogru":3,"aciklama":"m.10/1: 'ÇED raporu hazırlaması zorunlu ya da gerekli faaliyet sahipleri, çevresel etki değerlendirmesi raporunun eki olarak Doğaya Yeniden Kazandırma Planını, çevre yönetim uygulama takvimini ve bu plan ve takvimi aynen uygulayacağını gösterir noter tasdikli taahhüdü ilgili makamlara sunmakla ... yükümlüdürler.'","kaynak":"YON39 m.10","zorluk":"zor"},
    {"id":"YON39-S-013","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, çevresel etki değerlendirmesinin gerekli olmadığına karar verilen veya ÇED Yönetmeliği dışındaki faaliyet sahipleri, Ek-1'de formatı verilen Çevre Yönetim Planını ve noter tasdikli taahhüdü ilgili İl Çevre ve Orman Müdürlüğüne kaç nüsha halinde verirler?","siklar":["Bir","İki","Dört","Beş","Üç"],"dogru":4,"aciklama":"m.10/2: '... ilgili İl Çevre ve Orman Müdürlüğüne üç nüsha halinde vermekle ... yükümlüdürler.' Nüsha sayısı üçtür.","kaynak":"YON39 m.10","zorluk":"orta"},
    {"id":"YON39-S-014","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği çerçevesindeki denetimlerde, Çevre Kanununun 12 nci maddesi uyarınca kimler yetkilidir?","siklar":["Bakanlık, İl Çevre ve Orman Müdürlüğü ve Bakanlıkça yetki devri yapılmış kurum veya kuruluşlar","Yalnızca Bakanlık","Yalnızca İl Çevre ve Orman Müdürlüğü","Cumhuriyet savcılığı ve kolluk kuvvetleri","Tarım ve Köyişleri Bakanlığı"],"dogru":0,"aciklama":"m.14/1: 'Bu Yönetmelik çerçevesindeki denetimlerde, Çevre Kanununun 12 nci maddesi uyarınca Bakanlık, İl Çevre ve Orman Müdürlüğü ve Bakanlıkça yetki devri yapılmış kurum veya kuruluşlar yetkilidir.' Yetkili üç merci birlikte sayılmıştır.","kaynak":"YON39 m.14","zorluk":"kolay"},
    {"id":"YON39-S-015","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği hükümlerine aykırı faaliyette bulunanlara uygulanacak yaptırım aşağıdakilerden hangisidir?","siklar":["Yalnızca faaliyeti durdurma","İdari para cezası ve faaliyeti durdurma","Yalnızca idari para cezası","Yalnızca hapis cezası","Ruhsatın süresiz iptali"],"dogru":1,"aciklama":"m.15/1: '... Çevre Kanunu'nun 20 nci maddesi birinci fıkrası (l) bendinin ikinci paragrafına göre idari para cezası ve 15 inci maddesi uyarınca faaliyeti durdurma yaptırımı uygulanır.' Yaptırım çifttir: idari para cezası + faaliyeti durdurma.","kaynak":"YON39 m.15","zorluk":"orta"},
    {"id":"YON39-S-016","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu-kuru dere (m.6) ve deniz-göl (m.7) yataklarında su ürünleri açısından görüş veren makam ile Yönetmelik çerçevesinde denetim yapan makamlar hakkında aşağıdakilerden hangisi doğrudur?","siklar":["Görüşü İl Çevre ve Orman Müdürlüğü verir, denetimi Tarım ve Köyişleri Bakanlığı yapar","Görüş ve denetim aynı makam tarafından yürütülür, ayrım yoktur","Görüşü Tarım ve Köyişleri Bakanlığı verir, denetimi Bakanlık/İl Çevre ve Orman Müdürlüğü/yetki devri yapılan kurum yapar","Görüşü de denetimi de yalnızca Bakanlık yapar","Görüşü valilik verir, denetimi Cumhuriyet savcılığı yapar"],"dogru":2,"aciklama":"m.6/1-(k) ve m.7/1-(d): su ürünleri görüşü 'Tarım ve Köyişleri Bakanlığı'ndan' alınır. m.14/1: denetim 'Bakanlık, İl Çevre ve Orman Müdürlüğü ve Bakanlıkça yetki devri yapılmış kurum veya kuruluşlar' tarafından yapılır. İki makam ve iki işlev birbirinden ayrıdır.","kaynak":"YON39 m.6, m.7, m.14","zorluk":"zor"},
    {"id":"YON39-S-017","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, yeraltısuyu rezervlerini haiz akifer karakterindeki her türlü formasyonlarda kum ve çakıl ocağı açılması ve işletilmesi konusunda durum nedir?","siklar":["İzin verilmez","Yalnızca İl Çevre ve Orman Müdürlüğü onayıyla izin verilir","Tarım ve Köyişleri Bakanlığı iznine tabidir","Yalnızca yaz aylarında izin verilir","Sınırlama yoktur, serbesttir"],"dogru":0,"aciklama":"m.5/(c): 'Yeraltısuyu rezervlerini haiz akifer karakterindeki her türlü formasyonlarda ... kum, çakıl ve benzeri maddelerin alımına yönelik kum ve çakıl ocağı açılması ve işletilmesine izin verilmez.'","kaynak":"YON39 m.5","zorluk":"kolay"},
    {"id":"YON39-S-018","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, yatak şev diplerine şev yüksekliğinin ....(1).... katından daha az bir mesafe bırakarak yaklaşmak suretiyle şev stabilitesini tehdit edecek durumlarda kum ve çakıl ocağı açılması ve işletilmesine izin verilmez. Boşluğa gelmesi gereken sayı hangisidir?","siklar":["Üç","İki","Bir","Dört","Yarım"],"dogru":1,"aciklama":"m.5/(g): '...yatak şev diplerine şev yüksekliğinin iki katından daha az bir mesafe bırakarak yaklaşmak suretiyle şev stabilitesini tehdit edecek durumlarda ... izin verilmez.' Katsayı ikidir.","kaynak":"YON39 m.5","zorluk":"orta"},
    {"id":"YON39-S-019","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, talep edilen ocak yerinin bir akarsu ya da derenin boğaz çıkışından sonraki hangi jeomorfolojik oluşum üzerinde olması durumunda kum ve çakıl ocağı açılmasına izin verilmez?","siklar":["Menderes dış kurbu","Talveg hattı","Rüsup konisi","Taşkın yatağı","Delta ovası"],"dogru":2,"aciklama":"m.5/(h): 'Talep edilen ocak yerinin bir akarsu ya da derenin boğaz çıkışından sonraki rüsup konisi üzerinde olması durumunda' izin verilmez.","kaynak":"YON39 m.5","zorluk":"orta"},
    {"id":"YON39-S-020","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, mevcut durumda taşkın yönünden emniyetli olan yerleşim birimleri ve tarım arazilerinin, talep edilen kum-çakıl ocağının açılmasından sonra taşkına maruz kalacağının anlaşıldığı hallerde, faaliyet sahibinin ek tedbir alması şartıyla ocak açılmasına izin verilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.5/(ı): böyle bir durumda ocak açılması ve işletilmesine izin verilmez; metinde 'tedbir alınması şartıyla istisnai izin' gibi bir esneklik yoktur, yasak mutlaktır.","kaynak":"YON39 m.5","zorluk":"kolay"},
    {"id":"YON39-S-021","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, Su Kirliliğinin Kontrolü Yönetmeliği ekindeki tablolar esas alınarak su kalite sınıfının belirlenmesinde, akarsu ve kuru dere yatakları ile deniz ve göl yatakları için sırasıyla hangi tablolar kullanılır?","siklar":["Akarsu-kuru derede Tablo-2, Tablo-3 ve Tablo-4; deniz-gölde Tablo-1","Her iki durumda da yalnızca Tablo-1 kullanılır","Akarsu-kuru derede Tablo-1; deniz-gölde de yalnızca Tablo-1","Akarsu-kuru derede Tablo-1; deniz-gölde Tablo-2, Tablo-3 ve Tablo-4","Her iki durumda da Tablo-2, Tablo-3 ve Tablo-4 kullanılır"],"dogru":3,"aciklama":"m.6/(j): akarsu ve kuru dere yataklarında su kalite sınıfı Su Kirliliğinin Kontrolü Yönetmeliği ekindeki Tablo-1'e göre belirlenir. m.7/(c): deniz ve göl yataklarında ise aynı Yönetmeliğin ekindeki Tablo-2, Tablo-3 ve Tablo-4'e göre belirlenir.","kaynak":"YON39 m.6, m.7","zorluk":"zor"},
    {"id":"YON39-S-022","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve kuru dere yataklarında işletme ruhsatı süresinin bitiminde faaliyet sahibinin yükümlülüğü nedir?","siklar":["Sahayı olduğu gibi bırakmak, herhangi bir işlem yapmamak","Sahayı yeniden ruhsatlandırmak zorunda olmak","Sahayı İl Çevre ve Orman Müdürlüğüne bedelsiz devretmek","Sahada yeni bir ÇED raporu hazırlatmak","Gerekli arazi ıslahı ve rehabilitasyon çalışmalarını yaparak doğal akış rejimi koşullarını sağlayıp sahayı terk etmek"],"dogru":4,"aciklama":"m.6/(d): 'İşletme ruhsatı süresinin bitiminde, faaliyet sahibi tarafından akarsu veya kuru dere yatağında gerekli arazi ıslahı ve rehabilitasyon çalışmaları yapılarak doğal akış rejimi koşulları sağlanarak saha terk edilir.'","kaynak":"YON39 m.6","zorluk":"orta"},
    {"id":"YON39-S-023","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, akarsu ve kuru dere yataklarından alınan malzemenin yıkanması ve elenmesi sonucunda oluşan pasa, ruhsat alanı içerisinde çevreye ve insan sağlığına zarar vermeyecek şekilde doğaya yeniden kazanım çalışmalarında kullanılmak üzere depolanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/(g): '...alınan malzemenin yıkanması ve elenmesi sonucunda oluşan pasa, ruhsat alanı içerisinde çevreye ve insan sağlığına zarar vermeyecek can ve mal emniyetini sağlayacak şekilde doğaya yeniden kazanım çalışmalarında kullanılmak üzere depolanır.'","kaynak":"YON39 m.6","zorluk":"orta"},
    {"id":"YON39-S-024","soru":"Kum, Çakıl ve Benzeri Maddelerin Alınması, İşletilmesi ve Kontrolü Yönetmeliği'ne göre, deniz ve göl yataklarından kum, çakıl ve benzeri madde alınması faaliyetinde kıyının hangi özelliğinin doğal durumunun korunması esastır?","siklar":["Ekonomik değeri","Turistik kullanımı","Jeomorfolojik yapısı","Tapu sınırları","Nüfus yoğunluğu"],"dogru":2,"aciklama":"m.7/(b): 'Kıyının jeomorfolojik yapısının doğal durumu korunur.'","kaynak":"YON39 m.7","zorluk":"kolay"},
  ],
  64: [
    {"id":"YON40-S-001","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aşağıdakilerden hangisi bu Yönetmeliğin dayanağı arasında sayılmamıştır?","siklar":["5607 sayılı Kaçakçılıkla Mücadele Kanunu","4250 sayılı İspirto ve İspirtolu İçkiler İnhisarı Kanunu","4207 sayılı Tütün Ürünlerinin Zararlarının Önlenmesi ve Kontrolü Hakkında Kanun","4733 sayılı Tütün, Tütün Mamulleri ve Alkol Piyasasının Düzenlenmesine Dair Kanun","Dünya Sağlık Örgütü Tütün Kontrolü Çerçeve Sözleşmesi"],"dogru":0,"aciklama":"m.3: 'Bu Yönetmelik, ... 4250 sayılı ... Kanun, ... 4207 sayılı ... Kanun, ... 4733 sayılı ... Kanun ile ... yürürlüğe konulan Dünya Sağlık Örgütü Tütün Kontrolü Çerçeve Sözleşmesine dayanılarak hazırlanmıştır.' 5607 sayılı Kaçakçılıkla Mücadele Kanunu bu dört dayanak arasında yer almaz.","kaynak":"YON40 m.3","zorluk":"kolay"},
    {"id":"YON40-S-002","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre işyerinde tütün mamulü veya alkollü içki talep eden tüketicinin yaşı konusunda tereddüde düşülmesi halinde satıcı ne yapmak zorundadır?","siklar":["Kolluğa haber verir","Satışı reddetmek zorunda değildir","Talepte bulunan tüketiciden kimlik belgesi talep eder","Mülki amirden onay ister","Satışı yapar ancak kayıt tutar"],"dogru":2,"aciklama":"m.6/1-f: 'Yaş konusunda tereddüde düşülmesi halinde satıcı, talepte bulunan tüketiciden kimlik belgesi talep eder.'","kaynak":"YON40 m.6","zorluk":"orta"},
    {"id":"YON40-S-003","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre onsekiz yaşını doldurmamış kişiler, alkollü içkilerin üretiminde, pazarlanmasında, satışında ve açık sunumunda istihdam edilemez.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/2: '... bu kişiler, alkollü içkilerin üretiminde, pazarlanmasında, satışında ve açık sunumunda istihdam edilemez.'","kaynak":"YON40 m.6","zorluk":"kolay"},
    {"id":"YON40-S-004","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aynı gerçek veya tüzel kişinin birden fazla işyerinin bulunması halinde satış belgesi nasıl alınır?","siklar":["Her biri için ayrı satış belgesi alınması zorunludur","Tek bir merkezi belge tüm şubeler için yeterlidir","Sadece ilk açılan şube için belge alınır","Belge yalnızca merkez şubeye verilir, diğerleri bildirimle çalışır","İki şubeye kadar tek belge yeterlidir"],"dogru":0,"aciklama":"m.6/1-a: 'Aynı gerçek veya tüzel kişinin birden fazla işyerinin bulunması halinde her biri için ayrı satış belgesi alınması zorunludur.'","kaynak":"YON40 m.6","zorluk":"kolay"},
    {"id":"YON40-S-005","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre farklı ürünlerin de satıldığı işyerlerinde, Yönetmelik kapsamındaki ürünler diğer ürünlerden ....(1).... edilmiş olarak depolanır; bu ürünlerin kapsam dışı ürünlerle birlikte nakliyesi gerektiğinde, ticari araçlarda bu ürünler ....(2).... taşınır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["ayrıştırılmış - aynı bölümde","izole - kilitli dolapta","mühürlenmiş - ayrı araçta","tefrik - ayrı bölümde","kayıt altına alınmış - etiketli kutuda"],"dogru":3,"aciklama":"m.6/1-d: '... bu Yönetmelik kapsamındaki ürünler, diğer ürünlerden tefrik edilmiş olarak ... depolanır ve/veya satışa arz edilir. ... nakliyenin yapıldığı ticari araçlarda, bu ürünler ayrı bölümde taşınır.'","kaynak":"YON40 m.6","zorluk":"zor"},
    {"id":"YON40-S-006","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre tütün mamulü ve alkollü içki üreticileri ile ithalatçıları hangi durumda ayrıca toptan satış belgesi almak zorundadır?","siklar":["Sadece toptan satıcılara satış yaptıklarında","Hiçbir durumda belge almaları gerekmez","Yalnızca ihracat yaptıklarında","Sadece yıllık cirosu belli bir tutarı aşınca","Doğrudan perakende satıcılara, açık alkollü içki satıcılarına veya nargilelik tütün mamulü sunumu yapan kişilere satış yapmak istediklerinde"],"dogru":4,"aciklama":"m.7/1-a: 'Bu kişilerin, doğrudan açık alkollü içki satıcılarına, nargilelik tütün mamulü sunumu yapan kişilere ve/veya perakende satıcılara satış yapmak istemeleri halinde toptan satış belgesi almaları zorunludur.'","kaynak":"YON40 m.7","zorluk":"orta"},
    {"id":"YON40-S-007","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre faaliyetine kendi isteğiyle son veren, belgesi iptal edilen veya belgesi geçerliliğini kaybeden toptan satıcılara ilişkin bilgiler nerede yayımlanır?","siklar":["Resmî Gazete'de","Kurumun internet sitesinde","Valilik internet sitesinde","Ticaret sicili gazetesinde","Yerel gazetede ilan yoluyla"],"dogru":1,"aciklama":"m.7/1-c: '... bu durumlarına ilişkin bilgileri Kurumun internet sitesinde yayımlanır.'","kaynak":"YON40 m.7","zorluk":"kolay"},
    {"id":"YON40-S-008","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre perakende satıcılar, tütün mamullerinin ve alkollü içkilerin nihai tüketicilere yönelik arz ambalajlarını bozarak veya bölerek satış ya da sunumunu yapabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.8/1-ç: 'Perakende satıcılar; tütün mamullerinin ve alkollü içkilerin, nihai tüketicilere yönelik arz ambalajlarını bozmak ya da bölmek suretiyle satış veya sunumunu yapamazlar.'","kaynak":"YON40 m.8","zorluk":"kolay"},
    {"id":"YON40-S-009","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre alkollü içkiler ....(1).... saatleri arasında perakende olarak satılamaz; perakende satıcının faaliyet konusu tütün mamulü ve alkollü içkinin her ikisini kapsıyorsa ....(2).... satış belgesi düzenlenir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["22:00-06:00 - her bir faaliyet konusu için ayrı","23:00-07:00 - tek bir","22:00-06:00 - tek bir","24:00-06:00 - ortak bir","22:00-05:00 - her bir faaliyet konusu için ayrı"],"dogru":0,"aciklama":"m.8/1-d: 'Alkollü içkiler, 22:00 ila 06:00 saatleri arasında perakende olarak satılamaz.' m.8/1-c: '... Ancak her bir faaliyet konusu için ayrı satış belgesi düzenlenir.'","kaynak":"YON40 m.8","zorluk":"orta"},
    {"id":"YON40-S-010","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aşağıdakilerden hangisi tütün mamulü satışının yasak olduğu yer veya yöntemlerden biri değildir?","siklar":["Sağlık hizmeti verilen yerlerin yerleşkesinde","Bilgi toplumu hizmetleri (internet) vasıtasıyla","Otomatik satış makinelerinde","Kültür ve spor hizmeti verilen yerlerin yerleşkesinde","Kahvehane ve kıraathanelerde"],"dogru":4,"aciklama":"m.9: Tütün mamulü satışı sağlık, eğitim ve öğretim, kültür ve spor hizmeti verilen yerlerin yerleşkesinde (f.1), bilgi toplumu hizmetleri/posta yoluyla (f.2) ve otomatik satış makinelerinde/oyun-bahis yoluyla (f.3) yasaklanmıştır. Kahvehane ve kıraathane m.9'da sayılmaz; bu yerler m.10/3-d'de ALKOL satışının yasak olduğu yerler arasındadır.","kaynak":"YON40 m.9","zorluk":"orta"},
    {"id":"YON40-S-011","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre 4207 sayılı Kanun kapsamında tütün mamullerinin tüketilmesinin yasaklandığı alanlarda ne yapılamaz?","siklar":["Sigara içmek amacıyla mola verilemez","Elektronik sigara kullanılabilir","Nargilelik tütün mamulü sunumu yapılamaz","Puro satışı serbesttir","Tütün reklamı yapılabilir"],"dogru":2,"aciklama":"m.6/1-h: '4207 sayılı Kanun kapsamında, tütün mamullerinin tüketilmesinin yasaklandığı alanlarda nargilelik tütün mamulü sunumu yapılamaz.'","kaynak":"YON40 m.6","zorluk":"kolay"},
    {"id":"YON40-S-012","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aşağıdakilerden hangisinde faaliyet gösteren işyerlerinde alkollü içki satışı veya sunumu yasak DEĞİLDİR?","siklar":["Öğrenci yurtlarında","Kültür hizmeti verilen yerlerde","Sağlık hizmeti verilen yerlerde","Kahvehane ve kıraathanelerde","Akaryakıt istasyonlarında"],"dogru":1,"aciklama":"m.10/3 (a-d): öğrenci yurtları, sağlık hizmeti verilen yerler, spor müsabakası yapılan stadyum/kapalı spor salonu, her türlü eğitim ve öğretim kurumu, kahvehane/kıraathane/pastane/bezik ve briç salonları ile akaryakıt istasyonları sayılmıştır. 'Kültür hizmeti verilen yerler' bu sayımda yoktur; kültür yalnızca m.9/1'de TÜTÜN yasak yeri olarak geçer.","kaynak":"YON40 m.10","zorluk":"zor"},
    {"id":"YON40-S-013","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre açık alkollü içki satış belgesi bulunmayan perakende satış yapılan işyerlerinde ne yapılamaz?","siklar":["Kapalı ambalajlı alkol satışı yapılamaz","Hiçbir ürün satılamaz","Sadece akşam saatlerinde satış yapılamaz","Açık alkollü içki tüketilemez ve sunumu yapılamaz","Sadece 18 yaş altına satış yapılamaz"],"dogru":3,"aciklama":"m.10/1: 'Açık alkollü içki satış belgesi bulunmayan perakende satış yapılan işyerlerinde, açık alkollü içki tüketilemez ve sunumu yapılamaz.'","kaynak":"YON40 m.10","zorluk":"orta"},
    {"id":"YON40-S-014","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre otoyollardaki ve devlet karayollarındaki yapı ve tesislerde alkollü içki satışı ve tüketimi hangi durumda yasaktır?","siklar":["Meskûn mahaller ve konaklama yerleri hariç olmak üzere yasaktır","Her koşulda, istisnasız yasaktır","Sadece gece saatlerinde yasaktır","Yalnızca satış yasaktır, tüketim serbesttir","Yalnızca tüketim yasaktır, satış serbesttir"],"dogru":0,"aciklama":"m.10/2: 'Meskûn mahaller ve konaklama yerleri hariç olmak üzere, otoyollardaki ve devlet karayollarındaki yapı ve tesislerde alkollü içki satışına ve tüketimine izin verilmez.'","kaynak":"YON40 m.10","zorluk":"orta"},
    {"id":"YON40-S-015","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre alkollü içkilerin perakende veya açık olarak satışının yapıldığı yerler ile örgün eğitim kurumları, dershaneler, öğrenci yurtları ve ibadethaneler arasında kapıdan kapıya en az ....(1).... mesafe bulunması zorunludur; ancak ....(2).... tarihinden önce işyeri açma ve çalışma ruhsatı ile satış belgesi almış işletmeler için bu şart aranmaz. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["elli metre - 18/9/2013","yüz metre - 20/9/2023","yüz metre - 11/6/2013","iki yüz metre - 11/6/2013","yüz elli metre - 27/1/2013"],"dogru":2,"aciklama":"m.10/5: '... kapıdan kapıya en az yüz metre mesafenin bulunması zorunludur. ... Ancak 11/6/2013 tarihinden önce işyeri açma ve çalışma ruhsatı ve satış belgesi almış işletmeler için bu şart aranmaz.'","kaynak":"YON40 m.10","zorluk":"zor"},
    {"id":"YON40-S-016","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre 100 metre mesafe şartından muaf olan işletmenin sahibi, işletmesini kimlere devredebilir?","siklar":["Herhangi bir üçüncü kişiye","Yalnızca eşine","Sadece aynı sektördeki bir şirkete","Devir mümkün değildir","Birinci ve ikinci derece kan hısımlarına"],"dogru":4,"aciklama":"m.10/5: 'Bu işletme sahipleri işletmelerini birinci ve ikinci derece kan hısımlarına devredebilir.'","kaynak":"YON40 m.10","zorluk":"orta"},
    {"id":"YON40-S-017","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aşağıdakilerden hangisi yalnızca ALKOLLÜ içki satışının/sunumunun yasak olduğu yerler arasında sayılmış olup tütün mamulü satışının yasak olduğu yerler arasında sayılmamıştır?","siklar":["Sağlık hizmeti verilen yerler","Eğitim ve öğretim kurumları","İnternet ortamı","Kahvehane ve akaryakıt istasyonları","Kültür hizmeti verilen yerler"],"dogru":3,"aciklama":"Kahvehane, kıraathane, pastane, bezik-briç salonları ve akaryakıt istasyonları yalnızca m.10/3-d'de ALKOL yasak yeri olarak sayılmıştır; m.9'da tütün için bu yerler geçmez. Sağlık ve eğitim-öğretim her iki listede de ortaktır; kültür ve internet ise yalnızca m.9'da (tütün) yasaktır.","kaynak":"YON40 m.9-10","zorluk":"zor"},
    {"id":"YON40-S-018","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre nargilelik tütün mamulü sunumu faaliyetine ve işyerlerine ilişkin usul ve esasları belirleyen tebliği hangi makam çıkarır?","siklar":["İçişleri Bakanlığı","Kurum (Tarım ve Orman Bakanlığı)","Ruhsat vermeye yetkili merci","Valilik","Belediye"],"dogru":1,"aciklama":"m.10/4: 'Nargilelik tütün mamulü sunumu faaliyetine ve işyerlerine ilişkin usul ve esaslar, Kurum tarafından çıkarılacak tebliğ ile belirlenir.' (Kurum = Tarım ve Orman Bakanlığı; ruhsat/izin verme yetkisi ise m.10/7'de ayrıca 'yetkili merci'ye aittir.)","kaynak":"YON40 m.10","zorluk":"orta"},
    {"id":"YON40-S-019","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre yetkili satıcılar, satış belgesinde belirtilen işyeri adresi dışında satış ve/veya sunum yapamaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.6/1-b: 'Yetkili satıcılar tarafından satış belgesinde belirtilen işyeri adresi dışında satış ve/veya sunum yapılamaz.'","kaynak":"YON40 m.6","zorluk":"kolay"},
    {"id":"YON40-S-020","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre satış belgeleri işyeri içinde nasıl bulundurulmalıdır?","siklar":["Tüketicilerce rahatlıkla görülebilecek ve okunabilecek uygun yerlere asılır","Sadece denetim sırasında ibraz edilecek şekilde saklanır","Yalnızca işletme sahibinin bürosunda muhafaza edilir","Kapalı bir dosyada arşivlenir, talep halinde gösterilir","İşyeri dışına asılarak dışarıdan görünür kılınır"],"dogru":0,"aciklama":"m.6/1-e: 'Satış belgeleri, işyerlerinin içerisinde tüketicilerce rahatlıkla görülebilecek ve okunabilecek uygun yerlere asılır.'","kaynak":"YON40 m.6","zorluk":"kolay"},
    {"id":"YON40-S-021","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre satıcılar, ambalajlarında mevzuat uyarınca kullanılması zorunlu olan bandrol, etiket, hologram, pul, damga veya benzeri işaretleri ....(1).... ürünleri ya da taklit veya niteliğine uygun olmayan işaretleri taşıyan ürünleri ticari amaçla işyerlerinde bulunduramaz, nakledemez, satışa arz edemez. Birada uygulanacak kod ....(2).... hükmündedir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["eksik olan - etiket","hasarlı olan - pul","süresi geçmiş - damga","taşımayan - bandrol","yanlış yapıştırılmış - hologram"],"dogru":3,"aciklama":"m.6/1-ğ: 'Satıcılar, ambalajlarında ... bandrol, etiket, hologram, pul, damga veya benzeri işaretleri taşımayan ürünleri ya da taklit veya niteliğine uygun olmayan işaretleri taşıyan ürünleri ... bulunduramazlar, nakledemezler, satışa arz edemezler. Birada uygulanacak kod bandrol hükmündedir.'","kaynak":"YON40 m.6","zorluk":"orta"},
    {"id":"YON40-S-022","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre toptan satış belgesi, tüzel kişilerde kimin başvurusu üzerine ve kimin adına düzenlenir?","siklar":["İşletme müdürünün başvurusu üzerine müdür adına","Herhangi bir çalışanın başvurusu üzerine şirket adına","Tüzel kişiliği temsil ve ilzama yetkili kişinin başvurusu üzerine tüzel kişilik adına","Ortaklardan birinin başvurusu üzerine o ortak adına","Muhasebecinin başvurusu üzerine vergi numarası adına"],"dogru":2,"aciklama":"m.7/1-b: 'Toptan satış belgeleri, gerçek kişilerde; işletme sahibinin veya vekilinin başvurusu üzerine şahıs adına, tüzel kişilerde ise; tüzel kişiliği temsil ve ilzama yetkili kişi tarafından yapılacak başvuru üzerine, tüzel kişilik adına düzenlenir.'","kaynak":"YON40 m.7","zorluk":"orta"},
    {"id":"YON40-S-023","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre toptan satıcının satış faturaları ve sevk/taşıma irsaliyeleri üzerinde yer alması zorunlu bilgiler arasında aşağıdakilerden hangisi YOKTUR?","siklar":["Toptan satıcının Kurum sicil numarası","Ürün sattığı satıcının Kurum sicil numarası","Ürünün markası","Ürünün ambalaj hacmi veya birimi","Ürünün perakende satış fiyatı"],"dogru":4,"aciklama":"m.7/1-c: '... Ürünlerin ticaretine ilişkin satış faturaları ve sevk/taşıma irsaliyeleri üzerinde, toptan satıcının ve ürün sattığı satıcının Kurum sicil numarası ile ürünlerin niteliğini tanımlayan marka ve ambalaj hacmi veya birimi bilgilerine yer verilmesi zorunludur.' Perakende satış fiyatı bu zorunlu bilgiler arasında sayılmamıştır.","kaynak":"YON40 m.7","zorluk":"zor"},
    {"id":"YON40-S-024","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre aşağıdaki işyeri açma ve çalışma ruhsatı faaliyet konularından hangisinin sahibi perakende satış belgesi talebinde bulunabilecek türlerden biri DEĞİLDİR?","siklar":["Bakkal","Süpermarket","Kuruyemişçi","Eczane","Büfe"],"dogru":3,"aciklama":"m.8/1-b: '... işyeri açma ve çalışma ruhsatında belirtilen faaliyet konusu; bakkal, market, süpermarket, hipermarket, kuruyemişçi, büfe olanlar ile münhasıran tütün mamulü ve/veya alkollü içki satışı yapan kişiler, perakende satış belgesi talebinde bulunabilirler.' Eczane bu sayımda yer almaz.","kaynak":"YON40 m.8","zorluk":"orta"},
    {"id":"YON40-S-025","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre açık alkollü içki satış belgesi bulunan bir işyerinde, tesis sınırları dışında tüketilmek üzere de alkollü içki satışı veya sunumu yapılabilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10/7: 'Alkollü içkiler, Kurum tarafından açık alkollü içki satış belgesi düzenlenmek suretiyle alkollü içki sunum izni verilen yerlerde açık olarak tüketime sunulabilir. Ancak bu yerlerde tesis sınırları dışında tüketilmek üzere alkollü içki satışı veya sunumu yapılamaz.'","kaynak":"YON40 m.10","zorluk":"orta"},
    {"id":"YON40-S-026","soru":"Tütün Mamulleri ve Alkollü İçkilerin Satışına ve Sunumuna İlişkin Usul ve Esaslar Hakkında Yönetmelik'e göre açık alkollü içki satışı yapılan bir yerin tamamen bağımsız olmayan bir bölümünde faaliyet göstermek üzere perakende satış belgesi başvurusunda bulunulması halinde kural nedir?","siklar":["Bakiye faaliyet için farklı bir işyeri açma ve çalışma ruhsatı varsa perakende satış belgesi düzenlenir","Konaklama tesisi, mesire yeri ve kamp alanları hariç olmak üzere, perakende satış belgesi düzenlenmez","Her durumda perakende satış belgesi verilir","Sadece belediyenin ayrıca onay vermesi şartıyla belge düzenlenir","Yalnızca gündüz saatleriyle sınırlı kısıtlı bir belge düzenlenir"],"dogru":1,"aciklama":"m.10/8: 'Açık alkollü içki satışı yapılan yerlerin içinde veya bu yerlerin tamamen bağımsız olmayan bölümlerinde faaliyette bulunmak üzere perakende satış belgesi başvurusunda bulunanlara, ... farklı bir işyeri açma ve çalışma ruhsatı bulunsa dahi, ... perakende satış belgesi düzenlenmez. Açık alkollü içki satış belgesini haiz konaklama tesislerinde, mesire yerlerinde ve kamp alanlarında faaliyet gösteren perakende satış yerlerinde bu hüküm uygulanmaz.'","kaynak":"YON40 m.10","zorluk":"zor"},
  ],
  65: [
    {"id":"YON41-S-001","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre, Yönetmelikte geçen 'Bakanlık' ifadesi hangi kurumu ifade eder?","siklar":["İçişleri Bakanlığı","Dışişleri Bakanlığı","Adalet Bakanlığı","Aile ve Sosyal Hizmetler Bakanlığı","Çalışma ve Sosyal Güvenlik Bakanlığı"],"dogru":0,"aciklama":"m.3/b: 'Bakanlık: İçişleri Bakanlığını, ... ifade eder.' Yönetmelikte 'Bakanlık' tek başına yalnız İçişleri Bakanlığını karşılar.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"kolay"},
    {"id":"YON41-S-002","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmelik m.3'teki aşağıdaki tanım eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["Bakanlık – İçişleri Bakanlığı","Kurum – Nüfus ve Vatandaşlık İşleri Genel Müdürlüğü","Genel Müdürlük – Nüfus ve Vatandaşlık İşleri Genel Müdürlüğü","Komisyon – Vatandaşlık başvuru inceleme komisyonu","Kanun – 5901 sayılı Türk Vatandaşlığı Kanunu"],"dogru":1,"aciklama":"m.3/k: 'Kurum: Genel Müdürlük dışındaki diğer kamu kurum ve kuruluşlarını ... ifade eder.' Kurum, Genel Müdürlüğün kendisi değil, ONUN DIŞINDAKİ kamu kurum ve kuruluşlarıdır; B şıkkı bu nedenle yanlıştır. A, C, D, E eşleştirmeleri m.3'te birebir doğrudur.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"orta"},
    {"id":"YON41-S-003","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'çocuk' tanımı aşağıdakilerden hangisidir?","siklar":["Onaltı yaşını tamamlamamış olan kişi","Onsekiz yaşını doldurmuş olan kişi","Onsekiz yaşını tamamlamamış olan kişi","Onbeş yaşını tamamlamamış olan kişi","Ergin olmayan ve evli bulunmayan kişi"],"dogru":2,"aciklama":"m.3/c: 'Çocuk: Onsekiz yaşını tamamlamamış olan kişiyi, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"kolay"},
    {"id":"YON41-S-004","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'ergin', 4721 sayılı Türk Medenî Kanununa göre ergin olan kişi olarak tanımlanır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3/e: 'Ergin: 4721 sayılı Türk Medenî Kanununa göre ergin olan kişiyi, ... ifade eder.' Yönetmelik erginliği ayrı bir yaş belirtmeden doğrudan 4721 sayılı Kanuna atıfla tanımlar.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"kolay"},
    {"id":"YON41-S-005","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'yabancı' kimdir?","siklar":["Türk soyundan olup yerleşmek amacıyla Türkiye'ye gelen kişi","Kanunun 28 inci maddesi kapsamına giren kişi","Türkiye'de en az altı ay ikamet eden Türk vatandaşı","Türkiye Cumhuriyeti Devleti ile vatandaşlık bağı bulunmayan kişi","5543 sayılı İskân Kanunu uyarınca göçmen olarak kabul edilen kişi"],"dogru":3,"aciklama":"m.3/u: 'Yabancı: Türkiye Cumhuriyeti Devleti ile vatandaşlık bağı bulunmayan kişiyi, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"orta"},
    {"id":"YON41-S-006","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'göçmen', ....(1).... soyundan ve ....(2).... kültürüne bağlı olup yerleşmek amacıyla Türkiye'ye gelip ....(3).... sayılı İskân Kanunu uyarınca göçmen olarak kabul edilen kişidir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Türk - Türk - 6458","Kürt - Türk - 5543","Türk - Batı - 5543","Türk - Türk - 5901","Türk - Türk - 5543"],"dogru":4,"aciklama":"m.3/g: 'Göçmen: Türk soyundan ve Türk kültürüne bağlı olup yerleşmek amacıyla tek başına veya toplu halde Türkiye'ye gelip 5543 sayılı İskân Kanunu uyarınca göçmen olarak kabul edilen kişiyi, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
    {"id":"YON41-S-007","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre Türkiye Cumhuriyeti kimlik numarası ile yabancı kimlik numarası hakkında aşağıdakilerden hangisi doğrudur?","siklar":["İkisi de onbir rakamdan oluşur; yabancı kimlik numarası Türkiye'de en az altı ay süreli ikamet eden yabancılar için verilir","TC kimlik numarası dokuz, yabancı kimlik numarası onbir rakamdan oluşur","Yabancı kimlik numarası yalnız üç ay süreli ikamet edenlere verilir","İkisi de on rakamdan oluşur","Yabancı kimlik numarası yalnız Mavi Kart sahiplerine verilir"],"dogru":0,"aciklama":"m.3/s: TC kimlik numarası 'onbir rakamdan oluşan numara'dır. m.3/ü: yabancı kimlik numarası 'Türkiye'de herhangi bir amaçla en az altı ay süreli ikamet eden yabancıların' kayıtlarına ulaşmak için verilen, 'onbir rakamdan oluşan' bir numaradır.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"orta"},
    {"id":"YON41-S-008","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmelik m.3'teki aşağıdaki tanım eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["İl müdürlüğü – İl nüfus ve vatandaşlık müdürlüğü","Nüfus müdürlüğü – İl nüfus müdürlüğü","Mutad mesken – Kişinin yerleşim yeri","Çok vatandaşlık – Türk vatandaşının aynı anda birden çok vatandaşlığa sahip olması","İkamet – Yabancının yasal ikamet izniyle Türkiye'de bulunması"],"dogru":1,"aciklama":"m.3/ö: 'Nüfus müdürlüğü: İLÇE nüfus müdürlüğünü, ... ifade eder.' B şıkkı 'il nüfus müdürlüğü' diyerek bunu İl müdürlüğü tanımıyla (m.3/ı) karıştırmıştır; doğrusu İLÇE nüfus müdürlüğüdür. A, C, D, E eşleştirmeleri m.3'te birebir doğrudur.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
    {"id":"YON41-S-009","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre Türk vatandaşlığı hangi yol veya yollarla kazanılır?","siklar":["Yalnızca doğumla","Yalnızca sonradan başvuru ile","Doğumla veya sonradan olmak üzere iki yolla","Doğumla, sonradan ve evlat edinilme olmak üzere üç yolla","Yalnızca evlenme yoluyla"],"dogru":2,"aciklama":"m.5: 'Türk vatandaşlığı, doğumla veya sonradan olmak üzere iki yolla kazanılır.'","kaynak":"TVK Uyg. Yön. m.5","zorluk":"kolay"},
    {"id":"YON41-S-010","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre, onsekiz yaşını tamamladıktan sonra doğuma ilişkin yurt dışından yapılan bildirimde, kişinin Türk vatandaşı anadan veya babadan olduğunu ispata yarayacak yeterli bilgi ve belge bulunmaması halinde ne olur?","siklar":["İlgilinin talebi Genel Müdürlükçe reddedilir","Konu doğrudan mahkemeye intikal ettirilir","Kişi geçici olarak Türk vatandaşı sayılır","İlgilinin talebi Bakanlıkça reddedilir","Talep Komisyonca incelemeye alınır"],"dogru":3,"aciklama":"m.10(2): '... yeterli bilgi ve belge bulunmaması halinde, ilgili kişinin bu yöndeki talebi Bakanlıkça reddedilir.'","kaynak":"TVK Uyg. Yön. m.10","zorluk":"orta"},
    {"id":"YON41-S-011","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre onsekiz yaşını tamamladıktan sonra doğuma ilişkin yurt dışından yapılan bildirimde, Türk vatandaşı anadan veya babadan doğduğu tespit edilen kişi, bildirim tarihinden itibaren Türk vatandaşı olarak aile kütüğüne tescil edilir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.10(1): 'Bakanlıkça yapılacak inceleme ve araştırma sonucunda Türk vatandaşı anadan doğduğu veya babadan olduğu tespit edilen kişinin, doğumundan itibaren Türk vatandaşı olduğu aile kütüğüne tescil edilir.' Tescil bildirim tarihinden değil, doğumdan itibaren geçerlidir.","kaynak":"TVK Uyg. Yön. m.10","zorluk":"orta"},
    {"id":"YON41-S-012","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre doğum yeri esasına göre Türk vatandaşlığını kazanan çocuk, aile kütüğüne nasıl tescil edilir?","siklar":["Doğum yerinin bulunduğu ilin ilk hanesine","Ankara merkez nüfus kütüğüne","Anne veya babasının kayıtlı olduğu haneye","Dış temsilciliğin bildireceği herhangi bir haneye","Yerleşim yerinin bulunduğu idari birimin son hanesinden bir sonraki haneye"],"dogru":4,"aciklama":"m.12(1): '... doğumundan itibaren Türk vatandaşlığını kazanır ve yerleşim yerinin bulunduğu idari birimin son hanesinden bir sonraki haneye tescil edilir.'","kaynak":"TVK Uyg. Yön. m.12","zorluk":"orta"},
    {"id":"YON41-S-013","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre Türkiye'de bulunmuş çocuk, 29/9/2006 tarihli ve 2006/11081 sayılı Bakanlar Kurulu Kararıyla yürürlüğe konulan Nüfus Hizmetleri Kanununun Uygulanmasına İlişkin Yönetmeliğin ....(1).... maddesine göre aile kütüğüne tescil edilir. Boşluğa gelmesi gereken madde numarası hangisidir?","siklar":["32 nci","11 inci","22 nci","43 üncü","12 nci"],"dogru":0,"aciklama":"m.12(3): 'Türkiye'de bulunmuş çocuk, ... Nüfus Hizmetleri Kanununun Uygulanmasına İlişkin Yönetmeliğin 32 nci maddesine göre aile kütüğüne tescil edilir.'","kaynak":"TVK Uyg. Yön. m.12","zorluk":"zor"},
    {"id":"YON41-S-014","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre, Kanunun 13 üncü ve 43 üncü maddelerinde belirtilen kişiler, millî güvenlik bakımından engel teşkil edecek bir hali bulunmamak şartıyla, Türkiye'de ikamet şartı aranmaksızın Türk vatandaşlığını yeniden kazanabilirler.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.22(1): 'Kanunun 13 üncü ve 43 üncü maddelerinde belirtilen kişiler, millî güvenlik bakımından engel teşkil edecek bir hali bulunmamak şartıyla Türkiye'de ikamet şartı aranmaksızın, Türk vatandaşlığını yeniden kazanabilirler.'","kaynak":"TVK Uyg. Yön. m.22","zorluk":"orta"},
    {"id":"YON41-S-015","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre Kanunun 14 üncü maddesinde belirtilen kişilerin Türk vatandaşlığını yeniden kazanabilmesi için aranan ikamet süresi nedir?","siklar":["Aranmaz","Üç yıl","İki yıl","Bir yıl","Beş yıl"],"dogru":1,"aciklama":"m.22(2): 'Kanunun 14 üncü maddesinde belirtilen kişiler ise millî güvenlik bakımından engel teşkil edecek bir hali bulunmamak ve Türkiye'de üç yıl ikamet etmek şartıyla Türk vatandaşlığını yeniden kazanabilirler.'","kaynak":"TVK Uyg. Yön. m.22","zorluk":"zor"},
    {"id":"YON41-S-016","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre, Kanunun 14 üncü maddesinde belirtilen kişilerin Türkiye'de yeniden vatandaşlık kazanabilmesi için millî güvenlik bakımından engel teşkil edecek bir halinin bulunmaması yeterlidir, ayrıca ikamet şartı aranmaz.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.22(2): 14 üncü madde kapsamındakiler için millî güvenlik şartına EK olarak 'Türkiye'de üç yıl ikamet etmek' şartı da aranır. İkametin aranmadığı grup 13 ve 43 üncü madde kapsamındakilerdir (m.22/1), 14 üncü madde kapsamındakiler değil.","kaynak":"TVK Uyg. Yön. m.22","zorluk":"orta"},
    {"id":"YON41-S-017","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'aile kütüğü' tanımı aşağıdakilerden hangisidir?","siklar":["Nüfus olaylarına ilişkin kayıtların kâğıt veya elektronik ortamda tutulduğu kütüğü","Aile kütüğüne işlenmiş kişisel durum siciline ilişkin bilgilerin tümü","Aile kütüğüne işlenmiş kişisel bilgilerin özetlerini gösteren belge","Türkiye'de en az altı ay süreli Yabancılara Ait İkamet Tezkeresi verilen yabancıların kayıtlarının tutulduğu kütük","Doğum, ölüm, evlenme, boşanma gibi kişisel durum sicilinde değişiklik meydana getiren olay"],"dogru":0,"aciklama":"m.3/a: 'Aile kütüğü: Nüfus olaylarına ilişkin kayıtların kâğıt veya elektronik ortamda tutulduğu kütüğü, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"orta"},
    {"id":"YON41-S-018","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmelik m.3'e göre, aşağıdakilerden hangisi 'nüfus olayı' tanımı kapsamında SAYILAN olaylardan biri DEĞİLDİR?","siklar":["Doğum","Evlat edinme","Gaiplik","Askerlik durumu değişikliği","Soy bağının düzeltilmesi"],"dogru":3,"aciklama":"m.3/p: 'Nüfus olayı: Doğum, ölüm, evlenme, boşanma, evlat edinme, tanıma, kayıt düzeltme, soy bağının düzeltilmesi ve gaiplik gibi kişisel durum sicilinde değişiklik meydana getiren olayı, ... ifade eder.' Tanımda 'askerlik durumu değişikliği' sayılmamıştır.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
    {"id":"YON41-S-019","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'Yabancılar kütüğü', Türkiye'de herhangi bir amaçla en az altı ay süreli ikamet eden yabancıların kayıtlarına ulaşmak amacıyla elektronik ortamda verilen, onbir rakamdan oluşan numarayı ifade eder.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3/v: 'Yabancılar kütüğü: Türkiye'de herhangi bir amaçla en az altı ay süreli Yabancılara Ait İkamet Tezkeresi verilen yabancıların kayıtlarının tutulduğu kütüğü, ... ifade eder.' Sorudaki ifade aslında m.3/ü'deki 'Yabancı kimlik numarası' tanımıdır; 'Yabancılar kütüğü' bir NUMARA değil, ikamet tezkeresi verilenlerin kayıtlı olduğu bir KÜTÜKTÜR.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
    {"id":"YON41-S-020","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre Yönetmelikte geçen 'Sistem' ifadesi neyi kapsar?","siklar":["Yalnızca Merkezi Nüfus İdaresi Sistemini","Yalnızca Kimlik Paylaşımı Sistemini","Merkezi Nüfus İdaresi Sistemini veya sadece Kimlik Paylaşımı Sistemini","Ulusal Yargı Ağı Bilişim Sistemini","Elektronik Kamu Bilgi Yönetim Sistemini"],"dogru":2,"aciklama":"m.3/r: 'Sistem: Merkezi Nüfus İdaresi Sistemini veya sadece Kimlik Paylaşımı Sistemini, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"kolay"},
    {"id":"YON41-S-021","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre, hem onsekiz yaşını tamamladıktan sonra doğuma ilişkin yurt dışından yapılan bildirimde yeterli bilgi ve belge bulunmaması halinde hem de doğum yeri esasına göre aranan şartları taşımayanların taleplerinin reddedilmesinde yetkili makam Bakanlıktır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.10(2): '... ilgili kişinin bu yöndeki talebi Bakanlıkça reddedilir.' m.12(2): 'Aranan şartları taşımayanların talepleri Bakanlıkça reddedilir.' Her iki maddede de ret yetkisi doğrudan Bakanlığa aittir.","kaynak":"TVK Uyg. Yön. m.10, m.12","zorluk":"orta"},
    {"id":"YON41-S-022","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'ikamet' tanımı aşağıdakilerden hangisidir?","siklar":["Türk vatandaşının yurt dışında yasal olarak bulunması","Yabancının yasal ikamet izniyle Türkiye'de bulunması","Kişinin nüfusa kayıtlı olduğu yerde sürekli oturması","Yabancının Türkiye'de en az altı ay çalışması","Göçmenin İskân Kanunu uyarınca yerleştirilmesi"],"dogru":1,"aciklama":"m.3/h: 'İkamet: Yabancının yasal ikamet izniyle Türkiye'de bulunmasını, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"orta"},
    {"id":"YON41-S-023","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmelik m.3'teki aşağıdaki tanım eşleştirmelerinden hangisi YANLIŞTIR?","siklar":["Çok vatandaşlık – Türk vatandaşının aynı anda birden çok vatandaşlığa sahip olması","Dış temsilcilik – Türkiye Cumhuriyetinin yabancı ülkelerde bulunan büyükelçiliği, başkonsolosluğu veya konsolosluğu","İdari birim – Kişilerin kayıtlı bulundukları aile kütüklerinin ait olduğu il veya ilçe","Mutad mesken – Kişinin yerleşim yeri","Veri giriş formu – Nüfus olaylarına ilişkin bilgilerin elektronik ortamda tutulması amacıyla Merkezi Nüfus İdaresi Sistemine göre hazırlanan form"],"dogru":2,"aciklama":"m.3/ğ: 'İdari birim: Kişilerin kayıtlı bulundukları aile kütüklerinin ait olduğu MAHALLE VEYA KÖYÜ, ... ifade eder.' C şıkkı bunu 'il veya ilçe' olarak değiştirmiştir; doğrusu mahalle veya köydür. A, B, D, E eşleştirmeleri m.3'te birebir doğrudur.","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
    {"id":"YON41-S-024","soru":"Türk Vatandaşlığı Kanununun Uygulanmasına İlişkin Yönetmeliğe göre 'Yabancılar kütüğü', Türkiye'de herhangi bir amaçla en az ....(1).... ay süreli ....(2).... verilen yabancıların kayıtlarının tutulduğu kütüğü ifade eder. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üç - Yabancılara Ait İkamet Tezkeresi","altı - yabancı kimlik numarası","oniki - Yabancılara Ait İkamet Tezkeresi","altı - ikamet izni belgesi","altı - Yabancılara Ait İkamet Tezkeresi"],"dogru":4,"aciklama":"m.3/v: 'Yabancılar kütüğü: Türkiye'de herhangi bir amaçla en az altı ay süreli Yabancılara Ait İkamet Tezkeresi verilen yabancıların kayıtlarının tutulduğu kütüğü, ... ifade eder.'","kaynak":"TVK Uyg. Yön. m.3","zorluk":"zor"},
  ],
  66: [
    {"id":"42-S-001","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre taşıma ve bulundurma ruhsatları onay tarihinden itibaren kaç yıl için geçerlidir?","siklar":["Üç yıl","Dört yıl","Beş yıl","Yedi yıl","On yıl"],"dogru":2,"aciklama":"m.3: 'Taşıma ve bulundurma ruhsatları onay tarihinden itibaren beş yıl için geçerli olup, gerekli şartların varlığı halinde her beş yılda bir yenilenir.' Geçerlilik süresi sabit olarak beş yıldır.","kaynak":"42 YÖN m.3","zorluk":"kolay"},
    {"id":"42-S-002","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre ruhsatlar verilirken, süre bitiminden itibaren en geç ....(1).... içinde ruhsatın yenilenmesi gerektiği kişiye tebliğ edilir; bu süre içinde yenilenmezse ruhsat ....(2).... iptal edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["üç ay - talep üzerine","bir yıl - mahkeme kararıyla","altı ay - valinin onayıyla","altı ay - başka bir işleme gerek kalmaksızın","üç ay - başka bir işleme gerek kalmaksızın"],"dogru":3,"aciklama":"m.3: '...süre bitiminden itibaren en geç altı ay içinde ruhsatın yenilenmesi gerektiği kişiye tebliğ edilir. Beş yıllık geçerlilik süresini müteakip altı ay içinde ruhsatın yenilenmemesi halinde o silaha ait ruhsat başka bir işleme gerek kalmaksızın iptal edilerek...'","kaynak":"42 YÖN m.3","zorluk":"orta"},
    {"id":"42-S-003","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre Cumhurbaşkanı, Başbakan, Genelkurmay Başkanı, Jandarma Genel Komutanı gibi makamlarda asaleten bulunmuş olanların silah ruhsatlarında süre kaydı aranmaz.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.3: '...Jandarma Genel Komutanı ile Sahil Güvenlik Komutanı ve bu görevlerde asaleten bulunmuş olanların ruhsatlarında süre kaydı aranmaz.'","kaynak":"42 YÖN m.3","zorluk":"kolay"},
    {"id":"42-S-004","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre bulundurmak amacıyla silah satın alabilmek için Türk vatandaşının doldurmuş olması gereken asgari yaş kaçtır?","siklar":["On sekiz","Yirmi","Yirmibir","Yirmibeş","Otuz"],"dogru":2,"aciklama":"m.4: 'Silah ruhsatı alınmasına engel hali bulunmayan, yirmibir yaşını doldurmuş her Türk vatandaşı bulundurmak amacıyla silah satın alabilir.'","kaynak":"42 YÖN m.4","zorluk":"kolay"},
    {"id":"42-S-005","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre bulundurma ruhsatlı bir silahın zorunlu hallerde başka bir yere nakli hangi makamın vereceği belge ile mümkündür?","siklar":["İl emniyet müdürünün","Özel güvenlik komisyonunun","İçişleri Bakanlığının","Mahallin en büyük mülki amirinin","Kriminal Polis Laboratuvarının"],"dogru":3,"aciklama":"m.4: 'Bulundurma ruhsatlı silahların atış poligonu da dahil, zorunlu hallerde bir yerden başka bir yere nakli, mahallin en büyük mülki amirinin vereceği (EK-2)'deki Silah Nakil Belgesi ile mümkündür.' Ayrıca 'Taşıt araçları işyeri veya mesken sayılmaz.'","kaynak":"42 YÖN m.4","zorluk":"orta"},
    {"id":"42-S-006","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre can güvenliği ciddi ve harici tehdit altında bulunan Türk vatandaşlarına silah taşıma ruhsatını hangi makam verebilir?","siklar":["İçişleri Bakanı","Vali","Emniyet Genel Müdürü","Cumhuriyet savcısı","Özel güvenlik komisyonu"],"dogru":0,"aciklama":"m.7: 'İçişleri Bakanı; a) ...can güvenliklerinin ciddi ve harici tehdit ve tehlikelere maruz kalacağı kuvvetle muhtemel olduğu anlaşılan Türk vatandaşları ... talepleri halinde silah taşıma ruhsatı verebilir.'","kaynak":"42 YÖN m.7","zorluk":"kolay"},
    {"id":"42-S-007","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre can güvenliği nedeniyle silah taşıma ruhsatı verme yetkisi yalnızca İçişleri Bakanına aittir ve hiçbir şekilde devredilemez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.7: 'İçişleri Bakanı gerekli gördüğü takdirde, birinci fıkrada belirtilen yetkisini yazılı olarak Bakan Yardımcıları veya il valilerine tamamen veya kısmen devredebilir.'","kaynak":"42 YÖN m.7","zorluk":"orta"},
    {"id":"42-S-008","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre Kanunun 7 nci maddesinin (1), (2), (3) ve (6) numaralı bentleri kapsamında taşıma ruhsatı verilecek kamu görevlilerinde aranan ortak şart aşağıdakilerden hangisidir?","siklar":["En az beş yıl kıdemli olmak","Silahlı kuvvetlerden emekli olmak","Görevde asaleten bulunmuş olmak","Güvenlik soruşturmasının olumlu olması","İl genel meclisi üyesi olmak"],"dogru":2,"aciklama":"m.8 son fıkra: 'Bu madde ve 9 uncu madde uyarınca taşıma ruhsatlarının verilmesinde kişinin görevinde asaleten bulunmuş olması şartı aranır.'","kaynak":"42 YÖN m.8","zorluk":"orta"},
    {"id":"42-S-009","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre aşağıdakilerden hangisine, bu Yönetmeliğin 8 inci maddesi uyarınca demirbaş silah taşıma imkânı tanınmamıştır?","siklar":["Köy ve mahalle muhtarları","Açık denizlerde sefer yapan gemi kaptanları","Adalet Bakanlığına bağlı taşradaki cezaevi bekçileri","Enterkonnekte hat bakım-onarım personeli","Belediye başkan yardımcıları"],"dogru":4,"aciklama":"m.8/(b) ve (c) bentlerinde köy/mahalle muhtarları (b/1), gemi kaptanları (b/2), cezaevi bekçileri (c/8) ve enterkonnekte hat personeli (c/2) sayılmıştır. 'Belediye başkan yardımcıları' m.8'de hiçbir bentte geçmez.","kaynak":"42 YÖN m.8","zorluk":"orta"},
    {"id":"42-S-010","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre basın mensupları, kuyumcular, banka müdürleri gibi diğer meslek mensuplarına silah taşıma ruhsatını hangi makam verebilir?","siklar":["İçişleri Bakanı","Özel güvenlik komisyonu","Bakanlık","Vali","Kaymakam"],"dogru":3,"aciklama":"m.9: '...valiler, aşağıda belirtilen kişilere, durumlarının bu Yönetmelik hükümlerinde aranan şartlara uygunluğunun tesbit edilmesi halinde silah taşıma ruhsatı verebilir.'","kaynak":"42 YÖN m.9","zorluk":"kolay"},
    {"id":"42-S-011","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre gezginci olarak arıcılık yapan yetiştiricilere en az ....(1).... adet fenni arılı kovan şartıyla; iş sahiplerine ise en az ....(2).... sigortalı işçi çalıştırma şartıyla taşıma ruhsatı verilebilir; şirket ortağı olunması halinde ruhsat en fazla ....(3).... sorumlu ortağa verilir. Boşluklara sırasıyla gelmesi gereken sayılar hangisidir?","siklar":["100 - 50 - 2","50 - 100 - 3","100 - 100 - 2","150 - 50 - 1","50 - 150 - 2"],"dogru":0,"aciklama":"m.9/(ö): 'en az 100 adet fenni arılı kovan ile gezginci olarak bilfiil arıcılık yapan yetiştiricilere.' m.9/(m): 'En az elli sigortalı işçi çalıştıran ve fiilen ve bizzat bu işle iştigal eden iş sahiplerine, şirket ise sorumlu ortaklardan en fazla iki kişiye...'","kaynak":"42 YÖN m.9","zorluk":"zor"},
    {"id":"42-S-012","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre vali, hakim-savcı, emniyet hizmetleri sınıfı personeli gibi emekli kamu görevlilerine zati silahları için taşıma ruhsatı, hangi makama müracaatları halinde verilir?","siklar":["İkamet ettikleri yer valiliği","İçişleri Bakanlığı","Emekli oldukları kurumun genel müdürlüğü","Bulundukları yer kaymakamlığı","Özel güvenlik komisyonu"],"dogru":0,"aciklama":"m.10: '...ikamet ettikleri yer valiliğine müracaatları halinde, mevcut veya alacakları zati silahları için taşıma ruhsatı verilir.'","kaynak":"42 YÖN m.10","zorluk":"orta"},
    {"id":"42-S-013","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre en az bir dönem köy veya mahalle muhtarlığı, belediye başkanlığı ya da il genel meclis üyeliği yapmış olanlara taşıma ruhsatı verilebilmesi için, bu görevlere 2972 sayılı Kanun hükümlerine göre seçilmiş olma şartı aranır.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.10 ek ikinci fıkra: 'Birinci fıkranın (o) bendinde belirtilenler için 2972 sayılı Mahalli İdareler ile Mahalle Muhtarlıkları ve İhtiyar Heyetleri Seçimi Hakkında Kanun Hükümlerine göre seçilmiş ve bu görevlerde bulunmuş olma şartı aranır.'","kaynak":"42 YÖN m.10","zorluk":"orta"},
    {"id":"42-S-014","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre aşağıdakilerden hangisi silah taşıma ya da bulundurma ruhsatı verilmesini engelleyen hallerden biri değildir?","siklar":["Taksirli suçlar hariç bir yıldan fazla hapis cezasına mahkum olmak","Yirmibir yaşını bitirmemiş olmak","Kısıtlı olmak veya kamu hizmetinden yasaklı olmak","Psikolojik, nörolojik ve fiziki rahatsızlığı bulunmak","Bekar olmak"],"dogru":4,"aciklama":"m.16/(c) taksirli hariç bir yıldan fazla hapis, (k) kısıtlılık/kamu hizmetinden yasaklılık, (l) psikolojik-nörolojik-fiziki rahatsızlık, (m) 21 yaşını bitirmemiş olma engel hali olarak sayılmıştır. 'Bekar olmak' maddede bir engel hali olarak yer almaz.","kaynak":"42 YÖN m.16","zorluk":"orta"},
    {"id":"42-S-015","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre taksirli suçlar hariç olmak üzere kaç yıldan fazla hapis cezasına mahkumiyet, silah ruhsatı verilmesine engel oluşturur?","siklar":["Altı ay","Üç yıl","İki yıl","Bir yıl","Beş yıl"],"dogru":3,"aciklama":"m.16/(c): 'Taksirli suçlar hariç bir yıldan fazla hapis cezasına mahkum olanlara.'","kaynak":"42 YÖN m.16","zorluk":"kolay"},
    {"id":"42-S-016","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre Türk Ceza Kanununun Devletin güvenliğine, Anayasal düzene, milli savunmaya karşı suçlar ile casusluk ve 3713 sayılı Kanun kapsamındaki terör suçlarından mahkum olanlar hakkında, affa uğramış olsalar dahi silah ruhsatı verilmesi konusunda uygulama nasıldır?","siklar":["İnfazın tamamlanmasından 5 yıl sonra ruhsat verilebilir","Yasaklanmış hakların geri verilmesi kararıyla hemen ruhsat verilebilir","İdari para cezası ödenmesi kaydıyla ruhsat verilebilir","Vali onayıyla istisnai olarak ruhsat verilebilir","Affa uğramış olsalar bile ruhsat verilmez"],"dogru":4,"aciklama":"m.16 ikinci fıkra: 'Birinci fıkranın (e) bendi kapsamına girenlere affa uğramış olsalar bile ateşli silahlar ile mermilerini taşıma ya da bulundurma izni verilmez.'","kaynak":"42 YÖN m.16","zorluk":"zor"},
    {"id":"42-S-017","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre m.16/1'in (a), (b), (d), (e) ve (h) bentlerindeki suçlardan kovuşturulan kişinin ruhsat işlemleri ve silahı hakkında uygulanan tedbir aşağıdakilerden hangisidir?","siklar":["Silah derhal imha edilir","Ruhsat işlemleri kovuşturma sonuçlanana kadar bekletilir ve silah emanete alınır","Silah geçici olarak sahibine bırakılır, yalnız ruhsat iptal edilir","Kovuşturma süresi ne olursa olsun silah altı ay sonra iade edilir","Silah ilgili derneğe teslim edilir"],"dogru":1,"aciklama":"m.16 dördüncü fıkra: '...kovuşturma yapılan kişiye kovuşturma sonuçlanıncaya kadar... silah ruhsatı verilmesine ve yenilenmesine ilişkin işlemler bekletilir ve silah ilgili birimce emanete alınır.' Ayrıca 'Bu maddede belirtilen mahkumiyet, kesinleşmiş mahkumiyettir... adli para cezasına çevrilmiş olsa dahi hapis cezası esas alınır.'","kaynak":"42 YÖN m.16","zorluk":"orta"},
    {"id":"42-S-018","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre yivli spor tüfek ve tabancası olarak kayıtlı silahlara hangi tür ruhsat verilir ve bunların atış poligonunda kullanılabilmesi için ruhsatla birlikte ne bulunması gerekir?","siklar":["Taşıma ruhsatı - avcılık belgesi","Bulundurma ruhsatı - geçerli amatör sporcu lisansı","Taşıma ruhsatı - av tezkeresi","Bulundurma ruhsatı - polis emniyet belgesi","Geçici kullanım izni - kulüp üyelik kartı"],"dogru":1,"aciklama":"m.47: 'Yivli spor tüfek ve tabancası olarak kayıtlı bulunan bütün silahlara bulundurma ruhsatı verilir. Bu silahlar,... ancak ruhsatı ile birlikte geçerli amatör sporcu lisansı beraberinde olmak şartıyla kullanılabilir.'","kaynak":"42 YÖN m.47","zorluk":"kolay"},
    {"id":"42-S-019","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre bıçak, diğer aletler ve benzerlerinin nakli sırasında aşağıdaki şekillerden hangisi Yönetmelikte sayılan usullerden biri değildir?","siklar":["Ceket cebinde açıkta, görünür şekilde taşınması","Bavul, valiz, takım veya el çantalarında taşınması","Çuval, bez torba veya ambalajlarında taşınması","Araçların bagaj ve torpido gözlerinde taşınması","Ani olaylarda kullanılmayı engelleyecek şekilde kağıt veya bezle sarılıp paketlenmiş halde üstte taşınması"],"dogru":0,"aciklama":"m.54: 'Bıçak, diğer aletler ve benzerleri, her ne sebeple olursa olsun üstte taşınamaz.' Sayılan usuller: bavul/valiz/çanta (a), çuval/torba/ambalaj (b), araç bagaj/torpido (c), paketlenmiş halde üstte (d). 'Ceket cebinde açıkta taşıma' hiçbir bentte yoktur ve doğrudan yasaktır.","kaynak":"42 YÖN m.54","zorluk":"orta"},
    {"id":"42-S-020","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre kapalı tabanca, açık/yarı açık atış poligonu veya trap-skeet atış alanı kurmak isteyenler ön izin belgesini hangi makamdan almak zorundadır?","siklar":["Valilikten","Bakanlıktan","İl özel idaresinden","Belediyeden","Gençlik ve Spor Genel Müdürlüğünden"],"dogru":1,"aciklama":"m.60: '...Bakanlıktan ön izin belgesi almak zorundadırlar.' Ayrıca başvuranın 16. maddedeki engel hallerinden birine girmediği ve yerin genel güvenlik bakımından uygunluğu yine Bakanlıkça belirlenir.","kaynak":"42 YÖN m.60","zorluk":"kolay"},
    {"id":"42-S-021","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre bir tabancanın namlu, sürgü, çerçeve gibi ana ve balistik önemi haiz parçaları üzerinde tamir veya tadilat yapılabilmesi için izlenecek usul aşağıdakilerden hangisidir?","siklar":["Doğrudan valilikten izin alınır, laboratuvar raporuna gerek yoktur","Tamirci, silahı doğrudan Bakanlığa göndererek izin alır","Tamircinin raporuyla valiliğe müracaat edilir; valilik silahı Kriminal Polis/Jandarma Laboratuvarına gönderir, gelen rapora göre valilik izin verir","İşlem basit tamirat sayıldığından izinsiz yapılabilir","İşlem il jandarma komutanlığının doğrudan iznine tabidir"],"dogru":2,"aciklama":"m.70/(a): '...silah tamir yeri açma ruhsatı bulunan tamirci tarafından bu hususla ilgili düzenlenmiş raporla birlikte valiliğe müracaat edilir. Valilik bu müracaatı silahla birlikte ilgili Kriminal Polis/Jandarma Laboratuvarına gönderir. Buradan alınacak rapora istinaden valilikçe tamir veya tadilat izni verilebilir.'","kaynak":"42 YÖN m.70","zorluk":"zor"},
    {"id":"42-S-022","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre silah tamir yeri açma izni, mahalli kolluk tahkikatından sonra ....(1).... tarafından verilir; bu ruhsatlar ....(2).... geçerli olup, geçerlilik süresi bitiminden itibaren ....(3).... içinde mazeretsiz müracaat edilmezse ruhsat yenileninceye kadar faaliyetten men edilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["Bakanlık - üç yıl - altı ay","Valilik - beş yıl - üç ay","Emniyet Genel Müdürlüğü - on yıl - bir ay","Valilik - üç yıl - bir yıl","Kaymakamlık - beş yıl - altı ay"],"dogru":1,"aciklama":"m.71: '...tamir yerinin açılacağı yer valiliğince verilebilir... Silah Tamir Yeri Açma Ruhsatları beş yıl geçerli olup... en geç üç ay içinde müracaat etmeyenler, ruhsatları yenileninceye kadar valilikçe faaliyetten menedilirler.'","kaynak":"42 YÖN m.71","zorluk":"orta"},
    {"id":"42-S-023","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre ruhsatların veriliş nedenleri ortadan kalktığı halde bu durumu ruhsatı veren makama bir yıl içinde bildirmeyen ruhsat sahiplerine ruhsat verilmesi engellenir.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.16/(ı): 'Ruhsatların veriliş nedenleri ortadan kalktığı halde durumu ruhsatı veren makama altı ay içinde bildirmeyen ruhsat sahiplerine' ruhsat verilmez - süre bir yıl değil altı aydır.","kaynak":"42 YÖN m.16","zorluk":"orta"},
    {"id":"42-S-024","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre ruhsata bağlanmış silahlara ait yerli ve yabancı menşeli mermiler için ayrıca ruhsat aranmaz; ancak yabancı menşeli mermilerin kanuna uygun yollardan temin edildiğinin ispatı hiçbir şekilde istenemez.","siklar":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. m.3: 'Ruhsata bağlanmış silahlara ait yerli ve yabancı menşeli mermiler için ayrıca ruhsat aranmaz. Ancak, yabancı menşeli mermilerin Kanuna uygun yollardan temin edildiğinin ispatı yetkililerce istenebilir.' Cümlenin ilk kısmı doğru, ikinci kısmı (ispat hiçbir şekilde istenemez) yanlıştır.","kaynak":"42 YÖN m.3","zorluk":"kolay"},
    {"id":"42-S-025","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre, Kanunun 7 nci maddesinin (4) numaralı bendi kapsamına giren emekli kamu görevlilerine verilen silah taşıma ve bulundurma ruhsatları süre kaydına tabi tutulmaz; ancak bu kişilerin silah taşıma ve bulundurma şartlarını koruyup korumadıkları hususu ne sıklıkla araştırılır?","siklar":["Beş yılda bir","Her yıl","İki yılda bir","Üç yılda bir","Hiç araştırılmaz"],"dogru":0,"aciklama":"m.3: '...süre kaydına tabi tutulmaz. Ancak, bu şahısların silah taşıma ve bulundurma şartlarını koruyup korumadıkları hususu her beş yılda bir araştırılır.'","kaynak":"42 YÖN m.3","zorluk":"orta"},
    {"id":"42-S-026","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre bulundurma ruhsatlı silaha sahip bir kişi mesken veya işyerini daimi olarak değiştirdiğinde ve yeni adres başka bir mülki sınır içinde kaldığında izlenecek usul ile ilgili aşağıdakilerden hangisi doğrudur?","siklar":["Dosya eski mülki amirlikte kalır, yalnız adres güncellenir","Silah nakil belgesi alınır, dosya yeni adresin mülki amirliğine nakledilir ve orada harç alınmaksızın yeniden bulundurma ruhsatı düzenlenir","Ruhsat iptal edilir, yeniden baştan müracaat gerekir","Yeni adreste harç ödenerek ruhsat yenilenir","Değişiklik yalnızca altı ay içinde bildirilirse geçerli sayılır"],"dogru":1,"aciklama":"m.4: '...yeni adreslerini ruhsatı veren mülki amirliğe bildirerek silah nakil belgesi almak ve yeni adreslerinin kayıtlara geçirilmesini ve ruhsatına işlenmesini sağlamak zorundadırlar. Ruhsatlı silahın bulundurulacağı yeni adresin başka bir mülki sınır içinde olması halinde, silaha ait bulundurma dosyası yeni adresin bulunduğu mülki amirliğe nakledilir. Dosyanın nakledildiği mülki amirlikçe harç alınmaksızın yeniden bulundurma ruhsatı düzenlenir.'","kaynak":"42 YÖN m.4","zorluk":"orta"},
    {"id":"42-S-027","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğin 8 inci maddesinin (d) bendinde 'paraya vazıülyed olanlardan' sayılan ve demirbaş/zati silah taşıyabilen görevliler arasında aşağıdakilerden hangisi yer almaz?","siklar":["İcra müdürleri ve icra müdür yardımcıları","Veznedarlar","Muhasebe müdürleri","Tahsildarlar","2004 sayılı Kanunun 1 inci maddesine göre icra görevini ifa eden kişiler"],"dogru":2,"aciklama":"m.8/(d): '1 – ...icra müdürleri ile icra müdür yardımcıları ve bunların bulunmadığı yerlerde aynı Kanunun 1 inci maddesine istinaden bu görevi ifa eden kişilere..., 2 – Veznedarlara..., 3 – Tahsildarlara...' 'Muhasebe müdürleri' bu bentte sayılmamıştır.","kaynak":"42 YÖN m.8","zorluk":"orta"},
    {"id":"42-S-028","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre 2972 sayılı Mahalli İdareler ile Mahalle Muhtarlıkları ve İhtiyar Heyetleri Seçimi Hakkında Kanun hükümlerine göre seçimle göreve gelmiş olma şartı, madde 8'in birinci fıkrasının ....(1).... bendinin (1) numaralı alt bendinde sayılan ....(2).... için ve (e) bendinin (9) numaralı alt bendinde sayılan belediye başkanları, il genel meclisi ve büyükşehir belediye meclisi üyeleri için aranır. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["(a) - valiler - (c)","(c) - bekçiler - (e)","(e) - belediye başkanları - (b)","(b) - köy ve mahalle muhtarları - (e)","(b) - gemi kaptanları - (d)"],"dogru":3,"aciklama":"m.8 son fıkra: 'Birinci fıkranın (b) bendinin (1) numaralı alt bendi ile (e) bendinin (9) numaralı alt bendinde belirtilen görevliler için, 2972 sayılı...Kanun hükümlerine göre seçimle bu görevlere gelmiş olma şartı aranır.' (b)/1 = köy ve mahalle muhtarları, (e)/9 = belediye başkanları vd.","kaynak":"42 YÖN m.8","zorluk":"zor"},
    {"id":"42-S-029","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre yapı, tesis, inşaat ve büyük onarım işleriyle uğraşan müteahhitlerin ortaklık veya şirket olması halinde, taşıma ruhsatı sorumlu ortaklardan en fazla kaç kişiye verilebilir?","siklar":["Bir","Üç","Dört","Sınırlama yoktur, tüm ortaklara verilir","İki"],"dogru":4,"aciklama":"m.9/(j): '...yapı, tesis, inşaat ve büyük onarım işleriyle fiilen ve bizzat uğraşan müteahhitlere (ortaklık veya şirket ise sorumlu ortaklardan en fazla iki kişiye)...'","kaynak":"42 YÖN m.9","zorluk":"orta"},
    {"id":"42-S-030","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğin 16 ncı maddesinin (d) bendinde ruhsat verilmesini engelleyen suçlar arasında aşağıdakilerden hangisi sayılmamıştır?","siklar":["Trafik güvenliğini tehlikeye sokma","Zimmet, irtikap, rüşvet","Hırsızlık, dolandırıcılık, sahtecilik","İhaleye fesat karıştırma, yağma, uyuşturucu","Kasten öldürme, silahla kasten yaralama, çocukların cinsel istismarı"],"dogru":0,"aciklama":"m.16/(d) bendi zimmet, irtikap, rüşvet, hırsızlık, dolandırıcılık, sahtecilik, güveni kötüye kullanma, hileli iflas, bilişim suçları, ihaleye fesat karıştırma, yağma, uyuşturucu, aklama, örgüt kurma, insan/organ ticareti, silahla ateş etme, fuhuş, sistemi engelleme, kasten öldürme, silahla kasten yaralama, çocukların cinsel istismarı gibi suçları sayar. 'Trafik güvenliğini tehlikeye sokma' bu bentte yer almaz.","kaynak":"42 YÖN m.16","zorluk":"zor"},
    {"id":"42-S-031","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre ruhsatın veriliş nedeninin ortadan kalktığını altı ay içinde bildirmediği için ruhsatı iptal edilen kişiye (m.16/1-ı), Kanunun 6 ncı maddesinde belirlenen idari para cezasını ödemesi kaydıyla tekrar ruhsat verilebilir.","siklar":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. m.16 ikinci fıkra: 'Aynı fıkranın (ı) bendi kapsamına girenlere Kanunun 6 ncı maddesinin birinci fıkrasında belirlenen idari para cezasını ödemeleri kaydıyla tekrar ruhsat verilebilir.'","kaynak":"42 YÖN m.16","zorluk":"orta"},
    {"id":"42-S-032","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre Kanunun ek 1 inci maddesinde silahla girilmesi yasaklanan yerlere silahla giren veya buralarda silah taşıyan kişilerin silah ruhsatına ve sonraki taşıma ruhsatı hakkına ne olur?","siklar":["Ruhsat doğrudan iptal edilir, bir daha hiç ruhsat verilmez","Ruhsat bulundurmaya çevrilir; ön ödeme veya mahkumiyetteki adli para cezası infaz edildiği ya da düştüğü tarihten itibaren beş yıl geçmedikçe taşıma ruhsatı verilmez","Ruhsat aynen geçerli kalır, yalnızca uyarı yazısı yazılır","Ruhsat altı ay süreyle askıya alınır, sonra otomatik iade edilir","Ruhsat iptal edilir ama üç ay sonra harçsız yenilenir"],"dogru":1,"aciklama":"m.16: 'Kanunun ek 1 inci maddesinde silahla girilmesi yasaklanan yerlere silahla giren veya buralarda silah taşıyan kişilerin silah ruhsatları bulundurmaya çevrilir. Ön ödeme veya mahkumiyet kararındaki adli para cezasının infaz edildiği veya düştüğü tarihten itibaren beş yıllık süre geçmediği takdirde, bu kişilere taşıma ruhsatı verilmez.'","kaynak":"42 YÖN m.16","zorluk":"zor"},
    {"id":"42-S-033","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre valilikçe yapılacak tahkikat sonucu ruhsat almaya hak kazandığı tespit edilen kişilerden avlanma ruhsatı (avcılık belgesi) bulunanlara yivli av tüfeği için hangi ruhsat, avcılık belgesi bulunmayanlara ise hangi ruhsat tanzim edilir?","siklar":["Bulundurma ruhsatı - taşıma ruhsatı","Taşıma ruhsatı - taşıma ruhsatı","Geçici izin belgesi - bulundurma ruhsatı","Bulundurma ruhsatı - geçici izin belgesi","Taşıma ruhsatı - bulundurma ruhsatı"],"dogru":4,"aciklama":"m.47: '...avlanma ruhsatı (avcılık belgesi) bulunanlara yivli av tüfeği taşıma ruhsatı, diğerlerine de bulundurma ruhsatı tanzim edilir.'","kaynak":"42 YÖN m.47","zorluk":"orta"},
    {"id":"42-S-034","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre silahların parça değişikliği gerektiren tamiratlarında ana parçaların yurt dışından temini hangi makamın iznine tabidir?","siklar":["Valiliğin","Kriminal Polis Laboratuvarının","Bakanlığın","İl Jandarma Komutanlığının","Gümrük idaresinin"],"dogru":2,"aciklama":"m.70/(b): 'Silahların parça değişikliği gerektiren tamiratlarında yukarıdaki bentte belirtildiği şekilde sözkonusu silahlara ait ana parçaların yurt dışından temini Bakanlığın iznine tabidir.'","kaynak":"42 YÖN m.70","zorluk":"orta"},
    {"id":"42-S-035","soru":"Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Yönetmeliğe göre silah tamirhanesi açmak isteyenlerin, 16 ncı maddedeki hallerden birine girmemiş olmasının yanı sıra Bakanlıkça oluşturulan yetkili uzman komisyon tarafından yapılacak ....(1).... kazanmış olması gerekir; irtibat bürosu ile tamir yeri arasında silah nakil işinde çalışanlara valilikçe, bu işte çalıştığı sürece ve en fazla ....(2).... geçerli Silah Nakil Belgesi verilebilir. Boşluklara sırasıyla gelmesi gereken ifadeler hangisidir?","siklar":["ehliyet sınavını - üç yıl","güvenlik soruşturmasını - bir yıl","mesleki yeterlilik sınavını - iki yıl","mesleki yeterlilik sınavını - beş yıl","mesleki yeterlilik sınavını - on yıl"],"dogru":3,"aciklama":"m.71: '...Bakanlıkça oluşturulan yetkili uzman komisyon tarafından yapılacak mesleki yeterlilik sınavını kazanmış olması...' ve '...silah nakil işinde çalışanlara valilikçe, bu işte çalıştığı sürece ve en fazla beş yıl geçerli (Ek-6)'daki Silah Nakil Belgesi verilebilir.'","kaynak":"42 YÖN m.71","zorluk":"zor"},
  ],
};
